-- PATTERN 1: User Authentication
-- Before:
SELECT * FROM users WHERE email = ? AND is_active = true;

-- After (with covering index):
SELECT user_id, password_hash, account_locked
FROM users
WHERE email = ? AND is_active = true;

-- PATTERN 2: Connection Graph
-- Before:
SELECT * FROM user_connections
WHERE user_id = ? OR connected_user_id = ?;

-- After (with bidirectional index):
-- Use UNION for better index utilization
SELECT * FROM user_connections WHERE user_id = ? AND connection_status = 'accepted'
UNION
SELECT * FROM user_connections WHERE connected_user_id = ? AND connection_status = 'accepted';

