-- Index: (is_active, location_country, salary_min, posted_at DESC)
SELECT job_listing_id, title, company_id, location_city, salary_min, posted_at
FROM job_listings
WHERE is_active = true
AND location_country = ?
AND salary_min >= ?
ORDER BY posted_at DESC
