-- Company Analytics Dashboard
CREATE MATERIALIZED VIEW mv_company_analytics AS
SELECT
    c.company_id,
    c.name,
    COUNT(DISTINCT cr.review_id) as review_count,
    AVG(cr.overall_rating) as avg_rating,
    COUNT(DISTINCT jl.job_listing_id) as active_jobs,
    COUNT(DISTINCT e.employee_id) as employee_count
FROM companies c
LEFT JOIN company_reviews cr ON c.company_id = cr.company_id
    AND cr.approval_status = 'approved'
LEFT JOIN job_listings jl ON c.company_id = jl.company_id
    AND jl.is_active = true
LEFT JOIN employees e ON c.company_id = e.company_id
    AND e.employment_status = 'active'
GROUP BY c.company_id, c.name;

CREATE UNIQUE INDEX ON mv_company_analytics(company_id);

-- Refresh strategy: Every 4 hours
SELECT cron.schedule('refresh-company-analytics', '0 */4 * * *',
    'REFRESH MATERIALIZED VIEW CONCURRENTLY mv_company_analytics');


