-- Your partition creation functions don't check for existing partitions
-- Add existence checks and better error handling

CREATE OR REPLACE FUNCTION public.create_connection_partition(year int)
RETURNS void AS $$
DECLARE
    partition_name text;
    start_date text;
    end_date text;
BEGIN
    partition_name := 'user_connections_y' || year;
    start_date := year || '-01-01';
    end_date := (year + 1) || '-01-01';

    -- Check if partition already exists
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE format('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.user_connections
            FOR VALUES FROM (%L) TO (%L)
        ', partition_name, start_date, end_date);

        -- Create indexes only if partition was created
        -- ... index creation logic
    END IF;
END;
$$ LANGUAGE plpgsql;


