-- Your RLS policies use current_user_id() but some tables might be accessed by service accounts
-- Add fallback for service users

CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS uuid AS $$
DECLARE
    user_id uuid;
    service_accounts text[] := ARRAY['reports_service', 'analytics_service', 'backup_service'];
BEGIN
    -- Check if this is a service account
    IF current_user = ANY(service_accounts) THEN
        RETURN '00000000-0000-0000-0000-000000000000'::uuid;  -- Service account ID
    END IF;

    BEGIN
        user_id := current_setting('app.current_user_id')::uuid;
    EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
    END;
    RETURN user_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Then update policies
CREATE POLICY user_own_data_policy ON core.users
    USING (user_id = current_user_id() OR current_user = ANY(service_accounts));



