    -- Create a maintenance procedure for regular cleanup
CREATE OR REPLACE PROCEDURE public.run_maintenance()
LANGUAGE plpgsql
AS $$
BEGIN
    -- Refresh materialized views
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_company_analytics;
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_daily_business_dashboard;

    -- Archive old data
    PERFORM public.archive_dead_letter_queue();
    PERFORM public.archive_audit_logs(interval '90 days');

    -- Update statistics
    ANALYZE;

    -- Log maintenance completion
    INSERT INTO maintenance_logs (task, completed_at, status)
    VALUES ('scheduled_maintenance', CURRENT_TIMESTAMP, 'SUCCESS');
END;
$$;

-- Schedule with pg_cron
SELECT cron.schedule('maintenance-job', '0 2 * * *', 'CALL public.run_maintenance()');


