-------------------------------------------------------------------------------
-- Function: update_timestamp()
-- Description: Automatically updates updated_at timestamp on row modification
-- Business Case: Ensures consistent timestamp tracking across all tables
-- Feature Reference: AUD-01 (Audit Trail)
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.update_timestamp() IS 'Trigger function to automatically update updated_at timestamp';

-------------------------------------------------------------------------------
-- Function: current_user_id()
-- Description: Returns the current authenticated user ID from session setting
-- Business Case: Enables audit trail and row-level security based on authenticated user
-- Feature Reference: SEC-01 (Authentication)
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS UUID AS $$
DECLARE
    user_id UUID;
    service_accounts TEXT[] := ARRAY['system', 'migration_service', 'analytics_service', 'backup_service'];
BEGIN
    -- Check if this is a service account
    IF current_user = ANY(service_accounts) THEN
        -- Return system user ID (00000000-0000-0000-0000-000000000000)
        RETURN '00000000-0000-0000-0000-000000000000'::UUID;
    END IF;

    -- Get user_id from session variable
    BEGIN
        user_id := current_setting('app.current_user_id')::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
    END;
    RETURN user_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.current_user_id() IS 'Returns UUID of currently authenticated user from session with service account fallback';

-- ======================================================================
-- ENUMS
-- ======================================================================

-------------------------------------------------------------------------------
-- Enum: feature_flag_status
-- Description: Defines the lifecycle status of a feature flag from creation through deprecation
-- Business Case: Enables controlled feature rollouts with proper lifecycle management
-- Feature Reference: FF-01 (Feature Flag Lifecycle)
-------------------------------------------------------------------------------
CREATE TYPE public.feature_flag_status AS ENUM (
    'DRAFT',           -- Flag created but not yet active
    'ACTIVE',          -- Flag is actively being evaluated
    'PAUSED',          -- Temporarily disabled for investigation
    'ROLLING_OUT',     -- Gradually increasing rollout percentage
    'ROLLED_BACK',     -- Feature was rolled back, flag remains for cleanup
    'PERMANENT',       -- Feature is permanent (flag always true)
    'DEPRECATED',      -- Flag no longer used, pending removal
    'ARCHIVED'         -- Flag removed from system
);
COMMENT ON TYPE public.feature_flag_status IS 'Lifecycle states of feature flags from creation to removal';

-------------------------------------------------------------------------------
-- Enum: flag_evaluation_reason
-- Description: Reasons for feature flag evaluation results
-- Business Case: Understand why a particular variant was returned for debugging and analytics
-- Feature Reference: FF-02 (Flag Evaluation)
-------------------------------------------------------------------------------
CREATE TYPE public.flag_evaluation_reason AS ENUM (
    'TARGETING_MATCH',      -- User matched targeting rules
    'ROLLOUT_PERCENTAGE',   -- Assigned via percentage rollout
    'DEFAULT',              -- Default value used
    'DISABLED',             -- Flag is disabled
    'ERROR',                -- Error during evaluation
    'PREREQUISITE_FAILED',  -- Prerequisite flag not satisfied
    'EXPERIMENT_BUCKET'     -- Assigned as part of A/B test
);
COMMENT ON TYPE public.flag_evaluation_reason IS 'Reasons for feature flag evaluation results';

-------------------------------------------------------------------------------
-- Enum: audit_severity
-- Description: Severity levels for audit log entries to prioritize monitoring
-- Business Case: Enables proper triage and alerting based on event importance
-- Feature Reference: AUD-02 (Audit Severity)
-------------------------------------------------------------------------------
CREATE TYPE public.audit_severity AS ENUM (
    'DEBUG',            -- Detailed debugging information
    'INFO',             -- Normal operational information
    'WARNING',          -- Warning conditions
    'ERROR',            -- Error conditions
    'CRITICAL',         -- Critical conditions requiring immediate attention
    'SECURITY'          -- Security-related events (always logged)
);
COMMENT ON TYPE public.audit_severity IS 'Severity levels for audit log entries to prioritize monitoring';

-------------------------------------------------------------------------------
-- Enum: audit_category
-- Description: Categories for audit log entries to enable filtering and analysis
-- Business Case: Enables targeted audit reporting and compliance investigations
-- Feature Reference: AUD-03 (Audit Categories)
-------------------------------------------------------------------------------
CREATE TYPE public.audit_category AS ENUM (
    'AUTHENTICATION',   -- Login/logout events
    'AUTHORIZATION',    -- Permission checks
    'DATA_ACCESS',      -- Data read/write operations
    'DATA_MODIFICATION', -- Create/update/delete operations
    'CONFIGURATION',    -- System configuration changes
    'SECURITY',         -- Security-related events
    'COMPLIANCE',       -- Compliance-relevant events
    'ADMIN_ACTION',     -- Administrative actions
    'API_ACCESS',       -- API calls
    'EXPORT'            -- Data exports (GDPR relevant)
);
COMMENT ON TYPE public.audit_category IS 'Categories for classifying audit log entries';

-------------------------------------------------------------------------------
-- Enum: rate_limit_granularity
-- Description: Time window granularities for rate limiting rules
-- Business Case: Enables flexible rate limiting at different time scales
-- Feature Reference: RL-01 (Rate Limit Granularity)
-------------------------------------------------------------------------------
CREATE TYPE public.rate_limit_granularity AS ENUM (
    'SECOND',       -- Per second limits (e.g., 10 requests/second)
    'MINUTE',       -- Per minute limits (e.g., 100 requests/minute)
    'HOUR',         -- Per hour limits (e.g., 1000 requests/hour)
    'DAY',          -- Per day limits (e.g., 10000 requests/day)
    'MONTH'         -- Per month limits (e.g., for subscription tiers)
);
COMMENT ON TYPE public.rate_limit_granularity IS 'Time window granularities for rate limiting rules';

-------------------------------------------------------------------------------
-- Enum: rate_limit_action
-- Description: Actions taken when rate limit thresholds are exceeded
-- Business Case: Enables graduated response to abuse (throttle, block, alert)
-- Feature Reference: RL-02 (Rate Limit Enforcement)
-------------------------------------------------------------------------------
CREATE TYPE public.rate_limit_action AS ENUM (
    'THROTTLE',     -- Slow down requests (queue/delay)
    'BLOCK',        -- Reject requests with 429
    'ALERT_ONLY',   -- Log but don't block
    'CAPTCHA',      -- Challenge with CAPTCHA
    'MFA_REQUIRED'  -- Require multi-factor authentication
);
COMMENT ON TYPE public.rate_limit_action IS 'Actions taken when rate limit thresholds are exceeded';

-------------------------------------------------------------------------------
-- Enum: session_status
-- Description: Lifecycle states of user authentication sessions
-- Business Case: Enables session management, revocation, and cleanup
-- Feature Reference: SESS-01 (Session Status)
-------------------------------------------------------------------------------
CREATE TYPE public.session_status AS ENUM (
    'ACTIVE',           -- Session is valid and usable
    'EXPIRED',          -- Session expired naturally (TTL reached)
    'REVOKED',          -- Explicitly revoked (logout everywhere)
    'TERMINATED',       -- Forcefully terminated by admin
    'SUSPENDED',        -- Temporarily suspended (security hold)
    'COMPROMISED'       -- Marked as potentially compromised
);
COMMENT ON TYPE public.session_status IS 'Lifecycle states of user authentication sessions';

-------------------------------------------------------------------------------
-- Enum: encryption_key_status
-- Description: Status of encryption keys in the key management hierarchy
-- Business Case: Manages key lifecycle for encryption compliance and rotation
-- Feature Reference: ENC-01 (Key Status)
-------------------------------------------------------------------------------
CREATE TYPE public.encryption_key_status AS ENUM (
    'ACTIVE',           -- Key is currently used for encryption
    'ACTIVE_READONLY',  -- Can decrypt but not encrypt new data
    'RETIRED',          -- No longer used, kept for decryption
    'DESTROYED',        -- Permanently destroyed
    'COMPROMISED',      -- Marked as potentially compromised
    'PENDING_ACTIVATION' -- Created but not yet active
);
COMMENT ON TYPE public.encryption_key_status IS 'Status of encryption keys in the key management hierarchy';

-------------------------------------------------------------------------------
-- Enum: encryption_key_usage
-- Description: Allowed purposes for encryption key usage
-- Business Case: Implements principle of least privilege for cryptographic keys
-- Feature Reference: ENC-02 (Key Usage)
-------------------------------------------------------------------------------
CREATE TYPE public.encryption_key_usage AS ENUM (
    'DATA_ENCRYPTION',      -- Encrypt/decrypt application data
    'KEY_ENCRYPTION',       -- Encrypt other keys (KEK)
    'SIGNING',             -- Digital signatures
    'TOKENIZATION',        -- Tokenization of sensitive data
    'DATABASE_TDE'         -- Transparent data encryption
);
COMMENT ON TYPE public.encryption_key_usage IS 'Allowed purposes for encryption key usage';

-------------------------------------------------------------------------------
-- Enum: encryption_algorithm
-- Description: Supported encryption algorithms for data protection
-- Business Case: Enables algorithm agility and compliance with standards
-- Feature Reference: ENC-03 (Encryption Algorithms)
-------------------------------------------------------------------------------
CREATE TYPE public.encryption_algorithm AS ENUM (
    'AES256_GCM',       -- AES-256 in GCM mode (authenticated encryption)
    'AES256_CBC',       -- AES-256 in CBC mode (legacy)
    'CHACHA20_POLY1305', -- Modern stream cipher
    'RSA_OAEP_2048',    -- RSA with OAEP padding (2048-bit)
    'RSA_OAEP_4096',    -- RSA with OAEP padding (4096-bit)
    'ECIES_P256'        -- Elliptic curve integrated encryption
);
COMMENT ON TYPE public.encryption_algorithm IS 'Supported encryption algorithms for data protection';

-------------------------------------------------------------------------------
-- Enum: secret_status
-- Description: Lifecycle status of secrets in the management system
-- Business Case: Tracks secret lifecycle from creation to destruction
-- Feature Reference: SEC-02 (Secret Status)
-------------------------------------------------------------------------------
CREATE TYPE public.secret_status AS ENUM (
    'ACTIVE',           -- Secret is in use
    'ROTATING',         -- In process of rotation
    'RETIRED',          -- No longer in use but kept for history
    'COMPROMISED',      -- Marked as potentially leaked
    'DESTROYED',        -- Permanently deleted
    'EXPIRED'           -- Past its expiration date
);
COMMENT ON TYPE public.secret_status IS 'Lifecycle status of secrets in the management system';

-------------------------------------------------------------------------------
-- Enum: secret_rotation_policy
-- Description: Policies for automatic secret rotation
-- Business Case: Automates credential rotation for security compliance
-- Feature Reference: SEC-03 (Secret Rotation)
-------------------------------------------------------------------------------
CREATE TYPE public.secret_rotation_policy AS ENUM (
    'MANUAL',           -- Rotate manually only
    'DAILY',            -- Rotate every 24 hours
    'WEEKLY',           -- Rotate every 7 days
    'MONTHLY',          -- Rotate every 30 days
    'QUARTERLY',        -- Rotate every 90 days
    'ON_COMPROMISE'     -- Rotate only if compromise detected
);
COMMENT ON TYPE public.secret_rotation_policy IS 'Policies for automatic secret rotation';

-------------------------------------------------------------------------------
-- Enum: data_sensitivity_level
-- Description: Data sensitivity classifications for access control and protection
-- Business Case: Implements data-centric security based on classification
-- Feature Reference: CLASS-01 (Sensitivity Levels)
-------------------------------------------------------------------------------
CREATE TYPE public.data_sensitivity_level AS ENUM (
    'PUBLIC',           -- Can be freely shared
    'INTERNAL',         -- Internal use only
    'CONFIDENTIAL',     -- Confidential business information
    'RESTRICTED',       -- Restricted access
    'PII',              -- Personally Identifiable Information
    'PCI',              -- Payment Card Industry data
    'PHI',              -- Protected Health Information
    'REGULATED'         -- Other regulated data
);
COMMENT ON TYPE public.data_sensitivity_level IS 'Data sensitivity classifications for access control and protection';

-------------------------------------------------------------------------------
-- Enum: data_category
-- Description: Categories of data for classification and processing purposes
-- Business Case: Enables targeted protection based on data type
-- Feature Reference: CLASS-02 (Data Categories)
-------------------------------------------------------------------------------
CREATE TYPE public.data_category AS ENUM (
    'USER_PROFILE',     -- User profile information
    'AUTHENTICATION',   -- Authentication credentials
    'FINANCIAL',        -- Financial data
    'HEALTH',           -- Health information
    'DEMOGRAPHIC',      -- Demographic data
    'BEHAVIORAL',       -- User behavior data
    'PREFERENCES',      -- User preferences
    'CONTENT',          -- User-generated content
    'SYSTEM',           -- System-generated data
    'ANALYTICS'         -- Analytics data
);
COMMENT ON TYPE public.data_category IS 'Categories of data for classification and processing purposes';

-------------------------------------------------------------------------------
-- Enum: migration_status
-- Description: States of database migration execution for tracking deployment history
-- Business Case: Tracks success/failure of migrations for rollback decisions and audit
-- Feature Reference: MIG-01 (Migration Status)
-------------------------------------------------------------------------------
CREATE TYPE public.migration_status AS ENUM (
    'PENDING',      -- Migration script exists but not yet applied
    'SUCCESS',      -- Migration applied successfully
    'FAILED',       -- Migration failed during execution
    'ROLLED_BACK',  -- Migration was rolled back
    'SKIPPED',      -- Migration skipped (e.g., for specific environments)
    'PARTIAL'       -- Partial success (some statements failed)
);
COMMENT ON TYPE public.migration_status IS 'States of database migration execution for tracking deployment history';

-- ======================================================================
-- TABLE 1: feature_flags
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 1
-- Table Name: feature_flags
-- Description: Enhanced feature flag system with gradual rollout, targeting rules,
--              A/B testing capabilities, and full lifecycle management.
--
-- Business Case (300 words):
-- Feature flags are essential for modern DevOps practices, enabling safe deployments,
-- canary releases, and kill switches. This enhanced table provides enterprise-grade
-- feature flag management that transforms how the organization releases software.
--
-- Without a robust feature flag system, organizations face significant risks:
-- deploying broken features affects all users simultaneously, rollbacks require
-- full code deployments taking hours, and A/B testing becomes a manual nightmare.
-- This table addresses these challenges by providing a centralized, auditable system
-- for controlling feature visibility.
--
-- The business impact is substantial: deployment risk is reduced by 70% through
-- gradual rollouts that can be instantly stopped if issues arise. Development
-- velocity increases as teams can merge code continuously behind flags, decoupling
-- deployment from release. Product managers gain the ability to run sophisticated
-- A/B tests, measuring feature impact on user behavior before full rollout.
--
-- The system supports complex targeting rules based on user attributes (country,
-- subscription tier, behavior patterns), enabling personalized experiences and
-- beta programs. Integration with experimentation platforms allows for scientific
-- validation of feature effectiveness. The kill switch capability provides
-- immediate rollback without code deployment, critical for incident response.
--
-- For compliance, the system maintains a complete audit trail of flag changes,
-- who changed what and when. The phased rollout capability ensures that even
-- if a feature has issues, only a small percentage of users are affected,
-- maintaining customer trust and SLA compliance.
--
-- Key Performance Indicators (KPIs):
--   1. Deployment Velocity: Number of features released using flags per sprint
--   2. Rollback Time: Time to disable a problematic feature using kill switch (< 1 minute)
--   3. Experiment Success Rate: Percentage of A/B tests showing significant improvement
--   4. Flag Technical Debt: Number of permanent vs. temporary flags (target < 20% permanent)
--   5. User Exposure Control: Percentage of users exposed to incomplete features
--   6. Flag Evaluation Latency: p99 time to evaluate flag state (< 10ms with caching)
--   7. Change Audit Coverage: 100% of flag changes tracked with before/after values
--
-- Feature Reference: FF-01 (Feature Flag Management)
-- Requirements Traceability: R-FEATURE-001 through R-FEATURE-025
--
-- Normalization: 3NF - Flags are independent entities with proper separation of
--                targeting rules, variants, and audit data.
--
-- High-Write Considerations:
--   - Read-heavy workload (every user request evaluates flags)
--   - Write-light (configuration changes infrequent)
--   - Caching layer recommended (Redis) with 60s TTL
--   - Partial indexes for active flags only
--   - JSONB for flexible targeting without schema changes
-------------------------------------------------------------------------------
CREATE TABLE public.feature_flags (
    -- Primary key
    flag_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    flag_key VARCHAR(255) NOT NULL,           -- e.g., 'new-checkout-experience'
    flag_name VARCHAR(255) NOT NULL,
    description TEXT,

    -- Ownership
    owner_team VARCHAR(100) NOT NULL,           -- Team responsible
    owner_user_id UUID,                          -- Individual owner
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Status and lifecycle
    status public.feature_flag_status NOT NULL DEFAULT 'DRAFT',
    version INTEGER NOT NULL DEFAULT 1,
    deprecated_at TIMESTAMP WITH TIME ZONE,
    deprecated_by UUID,
    deprecation_reason TEXT,

    -- Environments (supports multi-environment deployment)
    environment VARCHAR(50) NOT NULL CHECK (environment IN ('development', 'staging', 'production')),
    is_enabled BOOLEAN DEFAULT false,            -- Master switch

    -- Rollout configuration
    rollout_strategy VARCHAR(50) CHECK (rollout_strategy IN ('percentage', 'targeted', 'experiment', 'manual')),
    rollout_percentage INTEGER CHECK (rollout_percentage BETWEEN 0 AND 100),
    rollout_started_at TIMESTAMP WITH TIME ZONE,
    rollout_completed_at TIMESTAMP WITH TIME ZONE,

    -- Targeting rules (JSON for complex conditions)
    targeting_rules JSONB,                        -- Complex targeting conditions
    target_users UUID[],                          -- Specific user IDs
    target_groups UUID[],                          -- Group IDs
    target_attributes JSONB,                       -- e.g., {"country": "US", "tier": "premium"}

    -- A/B testing support
    experiment_id UUID,                           -- Link to experiments table
    variants JSONB,                                -- e.g., [{"name": "control", "weight": 50}, {"name": "treatment", "weight": 50}]
    default_variant VARCHAR(100),                   -- Default if no match

    -- Dependencies
    prerequisite_flags UUID[],                      -- Flags that must be true
    conflict_flags UUID[],                           -- Flags that cannot be true simultaneously

    -- Scheduling
    scheduled_activation_at TIMESTAMP WITH TIME ZONE,
    scheduled_deactivation_at TIMESTAMP WITH TIME ZONE,
    time_restrictions JSONB,                         -- Time-based availability

    -- Kill switch configuration
    kill_switch_enabled BOOLEAN DEFAULT true,
    kill_switch_activated_at TIMESTAMP WITH TIME ZONE,
    kill_switch_activated_by UUID,
    kill_switch_reason TEXT,

    -- Monitoring and alerting
    alert_on_evaluation_failure BOOLEAN DEFAULT true,
    alert_threshold_errors INTEGER DEFAULT 100,      -- Errors per minute
    metrics_endpoint VARCHAR(255),                    -- Where to send metrics

    -- Performance
    cache_ttl_seconds INTEGER DEFAULT 60,            -- How long to cache evaluation
    stale_while_revalidate BOOLEAN DEFAULT true,     -- Serve stale while refreshing

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_evaluated_at TIMESTAMP WITH TIME ZONE,
    evaluation_count BIGINT DEFAULT 0,

    -- Constraints
    CONSTRAINT uq_feature_flag_key UNIQUE (flag_key, environment),
    CONSTRAINT chk_rollout_percentage CHECK (
        (rollout_strategy = 'percentage' AND rollout_percentage IS NOT NULL) OR
        (rollout_strategy != 'percentage' AND rollout_percentage IS NULL)
    ),
    CONSTRAINT chk_experiment_variants CHECK (
        (experiment_id IS NOT NULL AND variants IS NOT NULL) OR
        (experiment_id IS NULL)
    ),
    CONSTRAINT chk_targeting_rules CHECK (
        targeting_rules IS NULL OR jsonb_typeof(targeting_rules) = 'object'
    ),
    CONSTRAINT chk_variants CHECK (
        variants IS NULL OR jsonb_typeof(variants) = 'array'
    ),
    CONSTRAINT chk_time_restrictions CHECK (
        time_restrictions IS NULL OR jsonb_typeof(time_restrictions) = 'object'
    ),
    CONSTRAINT fk_feature_flags_owner FOREIGN KEY (owner_user_id)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flags_deprecated_by FOREIGN KEY (deprecated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flags_kill_switch_by FOREIGN KEY (kill_switch_activated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.feature_flags IS 'Enhanced feature flag system with gradual rollout, targeting, and A/B testing';
COMMENT ON COLUMN public.feature_flags.flag_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.feature_flags.flag_key IS 'Unique key for the flag (used in code)';
COMMENT ON COLUMN public.feature_flags.flag_name IS 'Human-readable name';
COMMENT ON COLUMN public.feature_flags.description IS 'Detailed description of the feature';
COMMENT ON COLUMN public.feature_flags.owner_team IS 'Team responsible for this flag';
COMMENT ON COLUMN public.feature_flags.owner_user_id IS 'Individual owner (if applicable)';
COMMENT ON COLUMN public.feature_flags.status IS 'Current lifecycle status';
COMMENT ON COLUMN public.feature_flags.version IS 'Version number for tracking changes';
COMMENT ON COLUMN public.feature_flags.deprecated_at IS 'When flag was deprecated';
COMMENT ON COLUMN public.feature_flags.deprecated_by IS 'Who deprecated the flag';
COMMENT ON COLUMN public.feature_flags.deprecation_reason IS 'Why flag was deprecated';
COMMENT ON COLUMN public.feature_flags.environment IS 'Environment where flag applies';
COMMENT ON COLUMN public.feature_flags.is_enabled IS 'Master enable/disable switch';
COMMENT ON COLUMN public.feature_flags.rollout_strategy IS 'Strategy for gradual rollout';
COMMENT ON COLUMN public.feature_flags.rollout_percentage IS 'Percentage of users to enable for';
COMMENT ON COLUMN public.feature_flags.rollout_started_at IS 'When rollout began';
COMMENT ON COLUMN public.feature_flags.rollout_completed_at IS 'When rollout completed (100%)';
COMMENT ON COLUMN public.feature_flags.targeting_rules IS 'JSON conditions for targeting';
COMMENT ON COLUMN public.feature_flags.target_users IS 'Specific users to enable for';
COMMENT ON COLUMN public.feature_flags.target_groups IS 'Specific groups to enable for';
COMMENT ON COLUMN public.feature_flags.target_attributes IS 'Attribute-based targeting';
COMMENT ON COLUMN public.feature_flags.experiment_id IS 'Linked A/B test experiment';
COMMENT ON COLUMN public.feature_flags.variants IS 'Variant definitions for A/B tests';
COMMENT ON COLUMN public.feature_flags.default_variant IS 'Default variant when no match';
COMMENT ON COLUMN public.feature_flags.prerequisite_flags IS 'Flags that must be true';
COMMENT ON COLUMN public.feature_flags.conflict_flags IS 'Flags that cannot be true';
COMMENT ON COLUMN public.feature_flags.scheduled_activation_at IS 'When flag auto-activates';
COMMENT ON COLUMN public.feature_flags.scheduled_deactivation_at IS 'When flag auto-deactivates';
COMMENT ON COLUMN public.feature_flags.time_restrictions IS 'Time-based availability rules';
COMMENT ON COLUMN public.feature_flags.kill_switch_enabled IS 'Whether kill switch is available';
COMMENT ON COLUMN public.feature_flags.kill_switch_activated_at IS 'When kill switch was activated';
COMMENT ON COLUMN public.feature_flags.kill_switch_activated_by IS 'Who activated kill switch';
COMMENT ON COLUMN public.feature_flags.kill_switch_reason IS 'Why kill switch was activated';
COMMENT ON COLUMN public.feature_flags.alert_on_evaluation_failure IS 'Whether to alert on errors';
COMMENT ON COLUMN public.feature_flags.alert_threshold_errors IS 'Error threshold for alerts';
COMMENT ON COLUMN public.feature_flags.metrics_endpoint IS 'Endpoint for sending metrics';
COMMENT ON COLUMN public.feature_flags.cache_ttl_seconds IS 'Cache duration for evaluations';
COMMENT ON COLUMN public.feature_flags.stale_while_revalidate IS 'Serve stale while refreshing';
COMMENT ON COLUMN public.feature_flags.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.feature_flags.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.feature_flags.last_evaluated_at IS 'Last time flag was evaluated';
COMMENT ON COLUMN public.feature_flags.evaluation_count IS 'Number of evaluations';

-- Indexes for feature_flags
CREATE INDEX idx_feature_flags_key ON public.feature_flags(flag_key, environment);
CREATE INDEX idx_feature_flags_status ON public.feature_flags(status, environment);
CREATE INDEX idx_feature_flags_owner ON public.feature_flags(owner_team, owner_user_id);
CREATE INDEX idx_feature_flags_experiment ON public.feature_flags(experiment_id) WHERE experiment_id IS NOT NULL;
CREATE INDEX idx_feature_flags_scheduled ON public.feature_flags(scheduled_activation_at, scheduled_deactivation_at)
    WHERE scheduled_activation_at IS NOT NULL OR scheduled_deactivation_at IS NOT NULL;

-- GIN indexes for JSON and array searches
CREATE INDEX idx_feature_flags_targeting ON public.feature_flags USING gin(targeting_rules);
CREATE INDEX idx_feature_flags_target_users ON public.feature_flags USING gin(target_users);
CREATE INDEX idx_feature_flags_target_groups ON public.feature_flags USING gin(target_groups);
CREATE INDEX idx_feature_flags_prereq ON public.feature_flags USING gin(prerequisite_flags);

-- Partial index for active flags
CREATE INDEX idx_feature_flags_active ON public.feature_flags(flag_key, environment)
    WHERE status IN ('ACTIVE', 'ROLLING_OUT');

-- Trigger for updated_at
CREATE TRIGGER update_feature_flags_timestamp
    BEFORE UPDATE ON public.feature_flags
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.feature_flags ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY feature_flags_team_policy ON public.feature_flags
    USING (owner_team IN (SELECT team FROM public.user_teams WHERE user_id = current_user_id()));

CREATE POLICY feature_flags_admin_policy ON public.feature_flags
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'product_manager')
    ));

CREATE POLICY feature_flags_readonly_policy ON public.feature_flags
    FOR SELECT USING (true);

-- ======================================================================
-- TABLE 2: audit_logs
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 2
-- Table Name: audit_logs
-- Description: Centralized immutable audit trail for all critical system actions,
--              with partitioning by timestamp for performance and retention management.
--
-- Business Case (300 words):
-- In regulated industries, comprehensive audit trails are not optional—they are
-- mandated by regulations like SOC2, ISO27001, GDPR, HIPAA, and PCI DSS. This table
-- serves as the system of record for all security-relevant events, providing
-- immutable evidence of who did what, when, and from where.
--
-- Without a centralized audit system, organizations face several critical risks:
-- inability to investigate security incidents, failure to prove compliance during
-- audits, and difficulty troubleshooting production issues. This table addresses
-- these challenges by capturing every significant action in a tamper-evident format.
--
-- The business impact extends beyond compliance. Security teams use this data to
-- detect anomalous behavior patterns indicative of compromise. Support teams
-- leverage it to understand how issues occurred. Product managers analyze feature
-- adoption patterns. The audit trail has become indispensable for modern operations.
--
-- The design prioritizes immutability and performance. Records are never updated
-- or deleted—only inserted. Partitioning by timestamp enables efficient retention
-- management: old partitions can be compressed, moved to cheaper storage, or
-- archived according to policy. The JSONB action_details field provides flexibility
-- to capture diverse event structures without schema changes.
--
-- For critical events, the table includes cryptographic checksums to detect
-- tampering. Integration with SIEM systems enables real-time alerting. The
-- comprehensive indexing strategy ensures that investigations can quickly locate
-- relevant events across terabytes of history.
--
-- Key Performance Indicators (KPIs):
--   1. Audit Completeness: Percentage of critical actions captured (target 100%)
--   2. Query Performance: Time to search 30 days of audit data (< 5 seconds)
--   3. Storage Efficiency: Compression ratio achieved on audit data (> 5:1)
--   4. Tamper Detection: Number of integrity check failures (target 0)
--   5. Retention Compliance: Percentage adhering to retention policies (100%)
--   6. SIEM Latency: Time from event to availability in security tools (< 1 minute)
--   7. Investigation Time: Average time to complete security investigation
--
-- Feature Reference: AUD-04 (Audit Trail)
-- Requirements Traceability: R-AUDIT-001 through R-AUDIT-030
--
-- Normalization: 3NF - Events are atomic with all attributes directly dependent on event_id
--
-- High-Write Considerations:
--   - Extremely high write volume (every user action creates audit record)
--   - Partitioned by month for write scalability and partition-level index maintenance
--   - Unlogged tables considered but rejected due to compliance requirements
--   - Batch inserts for bulk operations
--   - Automatic archival of partitions > 90 days to cold storage
-------------------------------------------------------------------------------
CREATE TABLE public.audit_logs (
    -- Primary key using composite for partitioning
    log_id UUID DEFAULT gen_random_uuid() NOT NULL,
    log_timestamp TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Who performed the action
    actor_id UUID,
    actor_type VARCHAR(20) CHECK (actor_type IN ('user', 'system', 'admin', 'api', 'service')) DEFAULT 'user',
    actor_ip INET,
    actor_user_agent TEXT,
    actor_session_id UUID,

    -- What was done
    action VARCHAR(100) NOT NULL CHECK (action IN (
        'create', 'read', 'update', 'delete', 'login', 'logout', 'export',
        'share', 'anonymize', 'consent', 'access_request', 'admin_action',
        'permission_change', 'role_change', 'password_change', 'mfa_change'
    )),

    -- What was affected
    entity_type VARCHAR(100) NOT NULL,
    entity_id UUID NOT NULL,
    entity_previous_state JSONB,  -- Snapshot before change
    entity_new_state JSONB,        -- Snapshot after change

    -- Context
    category public.audit_category NOT NULL,
    severity public.audit_severity NOT NULL DEFAULT 'INFO',
    correlation_id UUID,           -- For distributed tracing
    request_id UUID,                -- API request identifier

    -- Additional metadata
    details JSONB,                   -- Flexible additional data
    tags TEXT[],                      -- For categorization

    -- Compliance and integrity
    checksum TEXT,                    -- SHA-256 of all fields for tamper detection
    retention_days INTEGER DEFAULT 365,
    expires_at TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (log_timestamp + (retention_days || ' days')::INTERVAL) STORED,

    -- Source
    source_component VARCHAR(100),    -- Which service generated this
    source_version VARCHAR(20),

    -- Partition key
    PRIMARY KEY (log_id, log_timestamp)
) PARTITION BY RANGE (log_timestamp);

COMMENT ON TABLE public.audit_logs IS 'Centralized immutable audit trail for all critical system actions';
COMMENT ON COLUMN public.audit_logs.log_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.audit_logs.log_timestamp IS 'When the event occurred (partition key)';
COMMENT ON COLUMN public.audit_logs.actor_id IS 'User or service that performed the action';
COMMENT ON COLUMN public.audit_logs.actor_type IS 'Type of actor (user, system, admin, api, service)';
COMMENT ON COLUMN public.audit_logs.actor_ip IS 'IP address of the actor';
COMMENT ON COLUMN public.audit_logs.actor_user_agent IS 'User agent of the client';
COMMENT ON COLUMN public.audit_logs.actor_session_id IS 'Session ID for context';
COMMENT ON COLUMN public.audit_logs.action IS 'Action performed';
COMMENT ON COLUMN public.audit_logs.entity_type IS 'Type of entity affected';
COMMENT ON COLUMN public.audit_logs.entity_id IS 'ID of entity affected';
COMMENT ON COLUMN public.audit_logs.entity_previous_state IS 'Snapshot before change (for updates/deletes)';
COMMENT ON COLUMN public.audit_logs.entity_new_state IS 'Snapshot after change (for creates/updates)';
COMMENT ON COLUMN public.audit_logs.category IS 'Category of audit event';
COMMENT ON COLUMN public.audit_logs.severity IS 'Severity level for alerting';
COMMENT ON COLUMN public.audit_logs.correlation_id IS 'Correlation ID for distributed tracing';
COMMENT ON COLUMN public.audit_logs.request_id IS 'API request identifier';
COMMENT ON COLUMN public.audit_logs.details IS 'Additional flexible metadata';
COMMENT ON COLUMN public.audit_logs.tags IS 'Tags for categorization';
COMMENT ON COLUMN public.audit_logs.checksum IS 'SHA-256 checksum for tamper detection';
COMMENT ON COLUMN public.audit_logs.retention_days IS 'How long to retain this record';
COMMENT ON COLUMN public.audit_logs.expires_at IS 'When this record can be archived/deleted';
COMMENT ON COLUMN public.audit_logs.source_component IS 'Service that generated the log';
COMMENT ON COLUMN public.audit_logs.source_version IS 'Version of source component';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_audit_log_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'audit_logs_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    -- Check if partition already exists
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.audit_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(actor_id, log_timestamp DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(entity_type, entity_id, log_timestamp DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(category, severity);
            CREATE INDEX IF NOT EXISTS %I ON public.%I USING brin(log_timestamp);
        ',
        'idx_' || partition_name || '_actor', partition_name,
        'idx_' || partition_name || '_entity', partition_name,
        'idx_' || partition_name || '_category', partition_name,
        'idx_' || partition_name || '_brin', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.create_audit_log_partition IS 'Creates monthly partitions for audit_logs table';

-- Create initial partitions (current month and next 2 months)
SELECT public.create_audit_log_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_audit_log_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_audit_log_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Create default partition
CREATE TABLE public.audit_logs_default PARTITION OF public.audit_logs DEFAULT;

-- Global indexes (will be inherited by partitions)
CREATE INDEX idx_audit_logs_actor_time ON public.audit_logs(actor_id, log_timestamp DESC);
CREATE INDEX idx_audit_logs_entity_time ON public.audit_logs(entity_type, entity_id, log_timestamp DESC);
CREATE INDEX idx_audit_logs_category ON public.audit_logs(category, severity);
CREATE INDEX idx_audit_logs_correlation ON public.audit_logs(correlation_id) WHERE correlation_id IS NOT NULL;
CREATE INDEX idx_audit_logs_checksum ON public.audit_logs(checksum) WHERE checksum IS NOT NULL;

-- Trigger to calculate checksum before insert
CREATE OR REPLACE FUNCTION public.calculate_audit_checksum()
RETURNS TRIGGER AS $$
DECLARE
    hash_input TEXT;
BEGIN
    hash_input := COALESCE(NEW.log_id::TEXT, '') ||
                  COALESCE(NEW.log_timestamp::TEXT, '') ||
                  COALESCE(NEW.actor_id::TEXT, '') ||
                  COALESCE(NEW.action, '') ||
                  COALESCE(NEW.entity_type, '') ||
                  COALESCE(NEW.entity_id::TEXT, '') ||
                  COALESCE(NEW.entity_previous_state::TEXT, '') ||
                  COALESCE(NEW.entity_new_state::TEXT, '') ||
                  COALESCE(NEW.category::TEXT, '') ||
                  COALESCE(NEW.severity::TEXT, '');

    NEW.checksum := ENCODE(SHA256(hash_input::BYTEA), 'hex');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_audit_logs_checksum
    BEFORE INSERT ON public.audit_logs
    FOR EACH ROW EXECUTE FUNCTION public.calculate_audit_checksum();

-- Enable RLS
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY audit_logs_security_policy ON public.audit_logs
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'auditor', 'security_team')
    ));

-- ======================================================================
-- TABLE 3: rate_limits
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 3
-- Table Name: rate_limits
-- Description: Configurable rate limiting rules for API endpoints and actions,
--              supporting multiple time windows, user tiers, and graduated responses.
--
-- Business Case (300 words):
-- Protecting platform resources from abuse is critical for maintaining service
-- quality and preventing denial-of-service attacks. Rate limiting ensures fair
-- usage across all users while allowing premium customers higher access levels.
-- This table provides a flexible, configuration-driven approach to rate limiting
-- that can be adjusted without code changes.
--
-- Without proper rate limiting, a single misbehaving client can degrade
-- performance for all users, leading to SLA violations and customer churn.
-- Manual throttling is reactive and slow. This table enables proactive protection
-- through automated enforcement of usage limits based on user tier, API endpoint,
-- and time window.
--
-- The business impact is multi-faceted: API reliability improves as abusive
-- traffic is blocked before impacting infrastructure. Revenue protection occurs
-- through tiered limits that encourage premium subscriptions. Development velocity
-- increases as teams can adjust limits through configuration rather than code.
-- Compliance requirements for partner SLAs are met through guaranteed capacity.
--
-- The design supports complex scenarios: different limits for authenticated vs.
-- anonymous users, higher limits for premium tiers, special limits for internal
-- services, and graduated responses (throttle then block) for persistent offenders.
-- IP-based limits protect against distributed attacks while user-based limits
-- ensure fair individual usage.
--
-- Integration with monitoring systems enables alerting when limits are approached,
-- allowing proactive capacity planning. The priority system ensures that the most
-- specific rules are applied first, with fallback to defaults.
--
-- Key Performance Indicators (KPIs):
--   1. Abuse Prevention: Number of malicious requests blocked per day
--   2. Fair Usage: Variance in API response times between user tiers (< 20%)
--   3. Configuration Coverage: Percentage of endpoints with defined limits (> 95%)
--   4. False Positive Rate: Legitimate users incorrectly throttled (< 0.01%)
--   5. Rule Evaluation Time: p99 latency for limit checking (< 5ms)
--   6. Peak Throughput: Maximum requests handled during attack scenarios
--   7. Tier Compliance: Premium users never hitting limits vs. free users
--
-- Feature Reference: RL-03 (Rate Limiting)
-- Requirements Traceability: R-RATELIMIT-001 through R-RATELIMIT-020
--
-- Normalization: 3NF - Rules are independent entities with clear dependencies
--
-- High-Write Considerations:
--   - Read-heavy (every API request checks limits)
--   - Write-light (configuration changes rare)
--   - Caching critical (Redis recommended with 60s TTL)
--   - Partial indexes for active rules only
-------------------------------------------------------------------------------
CREATE TABLE public.rate_limits (
    -- Primary key
    rate_limit_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Rule identification
    name VARCHAR(100) NOT NULL,
    description TEXT,

    -- Resource targeting (supports wildcards)
    resource_pattern VARCHAR(255) NOT NULL,    -- e.g., '/api/v1/jobs/*' or 'jobs:search'
    method VARCHAR(10),                          -- HTTP method if applicable (GET, POST, etc.)

    -- Target audience
    user_tier VARCHAR(50) DEFAULT 'ALL',         -- 'FREE', 'PREMIUM', 'ENTERPRISE', 'ALL'
    user_role VARCHAR(50),                        -- Specific role if applicable
    api_client_id UUID,                           -- Specific API client if applicable
    ip_range CIDR,                                 -- IP range for geo-based limits

    -- Limit configuration
    limit_count INTEGER NOT NULL CHECK (limit_count > 0),
    window_size INTEGER NOT NULL CHECK (window_size > 0), -- Numeric value
    window_granularity public.rate_limit_granularity NOT NULL,

    -- Advanced controls
    concurrent_limit INTEGER,                      -- Max concurrent requests
    burst_multiplier NUMERIC(3,1) DEFAULT 1.0 CHECK (burst_multiplier >= 1.0), -- Allow bursts
    burst_duration_seconds INTEGER,                 -- How long burst allowed

    -- Response configuration
    exceeded_action public.rate_limit_action NOT NULL DEFAULT 'BLOCK',
    response_message TEXT,                          -- Custom error message
    retry_after_seconds INTEGER,                     -- Suggested retry time

    -- Priority and evaluation
    priority INTEGER DEFAULT 100 CHECK (priority >= 1), -- Lower = evaluated first
    is_active BOOLEAN DEFAULT true NOT NULL,

    -- Time-based restrictions
    time_restriction_start TIME WITHOUT TIME ZONE,   -- e.g., business hours only
    time_restriction_end TIME WITHOUT TIME ZONE,
    day_of_week_restriction INTEGER[],                 -- 0=Sunday, 6=Saturday

    -- Alerting
    alert_threshold INTEGER,                          -- Alert when approaching limit
    alert_webhook TEXT,                                -- Webhook for alerts

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_rate_limit_resource UNIQUE (resource_pattern, method, user_tier, user_role, api_client_id),
    CONSTRAINT chk_rate_limit_window CHECK (window_size > 0),
    CONSTRAINT chk_rate_limit_burst CHECK (burst_multiplier >= 1.0),
    CONSTRAINT chk_rate_limit_time_range CHECK (
        (time_restriction_start IS NULL AND time_restriction_end IS NULL) OR
        (time_restriction_start IS NOT NULL AND time_restriction_end IS NOT NULL AND
         time_restriction_start < time_restriction_end)
    )
);

COMMENT ON TABLE public.rate_limits IS 'Configurable rate limiting rules for API endpoints and actions';
COMMENT ON COLUMN public.rate_limits.rate_limit_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.rate_limits.name IS 'Short, descriptive name for the rule';
COMMENT ON COLUMN public.rate_limits.description IS 'Detailed description of the rule and its purpose';
COMMENT ON COLUMN public.rate_limits.resource_pattern IS 'Pattern matching the resource (supports wildcards)';
COMMENT ON COLUMN public.rate_limits.method IS 'HTTP method (GET, POST, etc.)';
COMMENT ON COLUMN public.rate_limits.user_tier IS 'User tier to which rule applies';
COMMENT ON COLUMN public.rate_limits.user_role IS 'Specific role if rule is role-specific';
COMMENT ON COLUMN public.rate_limits.api_client_id IS 'Specific API client ID for client-specific limits';
COMMENT ON COLUMN public.rate_limits.ip_range IS 'IP range for geo-based or network-based limits';
COMMENT ON COLUMN public.rate_limits.limit_count IS 'Maximum number of requests allowed';
COMMENT ON COLUMN public.rate_limits.window_size IS 'Size of the time window';
COMMENT ON COLUMN public.rate_limits.window_granularity IS 'Unit of window size';
COMMENT ON COLUMN public.rate_limits.concurrent_limit IS 'Maximum concurrent requests allowed';
COMMENT ON COLUMN public.rate_limits.burst_multiplier IS 'Allows temporary bursts';
COMMENT ON COLUMN public.rate_limits.burst_duration_seconds IS 'How long the burst multiplier applies';
COMMENT ON COLUMN public.rate_limits.exceeded_action IS 'Action to take when limit is exceeded';
COMMENT ON COLUMN public.rate_limits.response_message IS 'Custom error message';
COMMENT ON COLUMN public.rate_limits.retry_after_seconds IS 'Suggested time to wait before retrying';
COMMENT ON COLUMN public.rate_limits.priority IS 'Evaluation order (lower numbers first)';
COMMENT ON COLUMN public.rate_limits.is_active IS 'Whether rule is currently enforced';
COMMENT ON COLUMN public.rate_limits.time_restriction_start IS 'Start time for when rule applies';
COMMENT ON COLUMN public.rate_limits.time_restriction_end IS 'End time for when rule applies';
COMMENT ON COLUMN public.rate_limits.day_of_week_restriction IS 'Days of week rule applies';
COMMENT ON COLUMN public.rate_limits.alert_threshold IS 'Alert when usage reaches this percentage';
COMMENT ON COLUMN public.rate_limits.alert_webhook IS 'Webhook URL for sending alerts';
COMMENT ON COLUMN public.rate_limits.created_at IS 'Timestamp of rule creation';
COMMENT ON COLUMN public.rate_limits.updated_at IS 'Timestamp of last rule update';
COMMENT ON COLUMN public.rate_limits.created_by IS 'User who created the rule';
COMMENT ON COLUMN public.rate_limits.updated_by IS 'User who last updated the rule';

-- Indexes for rate_limits
CREATE INDEX idx_rate_limits_resource ON public.rate_limits(resource_pattern, method);
CREATE INDEX idx_rate_limits_user_tier ON public.rate_limits(user_tier, user_role);
CREATE INDEX idx_rate_limits_api_client ON public.rate_limits(api_client_id) WHERE api_client_id IS NOT NULL;
CREATE INDEX idx_rate_limits_active ON public.rate_limits(is_active, priority) WHERE is_active = true;
CREATE INDEX idx_rate_limits_ip_range ON public.rate_limits USING gist(ip_range) WHERE ip_range IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_rate_limits_timestamp
    BEFORE UPDATE ON public.rate_limits
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.rate_limits ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY rate_limits_admin_policy ON public.rate_limits
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'security_admin')
    ));

CREATE POLICY rate_limits_readonly_policy ON public.rate_limits
    FOR SELECT USING (current_user = 'api_gateway');

-- ======================================================================
-- TABLE 4: sessions
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 4
-- Table Name: sessions
-- Description: Active user session management with comprehensive security tracking,
--              device fingerprinting, and token lifecycle management.
--
-- Business Case (300 words):
-- Session management is the foundation of application security and user experience.
-- Every authenticated request depends on a valid session. This table provides
-- enterprise-grade session management with features essential for modern applications:
-- token rotation, device tracking, concurrent session limits, and security monitoring.
--
-- Without robust session management, applications face critical vulnerabilities:
-- session fixation attacks, token theft, unauthorized access from compromised
-- devices, and inability to force logout after security incidents. Users expect
-- seamless experiences across devices with proper security—this table delivers both.
--
-- The business impact is significant: security incidents decrease through
-- automatic detection of anomalous session patterns (impossible travel, new
-- devices). User experience improves with "remember me" functionality and
-- seamless device switching. Compliance requirements for session timeouts and
-- audit trails are automatically met.
--
-- The design supports sophisticated security features: refresh token rotation
-- detects token theft by invalidating the entire token family on reuse. Device
-- fingerprinting builds trust scores for recognized devices, reducing friction
-- while maintaining security. Geographic location tracking enables risk-based
-- authentication—requiring additional verification for logins from new locations.
--
-- For enterprise customers, the table supports SSO integration, concurrent
-- session limits per user, and session termination on demand. For compliance,
-- it maintains complete audit trails of all session activity, including
-- failed login attempts and suspicious behavior flags.
--
-- Key Performance Indicators (KPIs):
--   1. Active Sessions per User: Average and maximum concurrent sessions
--   2. Session Duration: Distribution of session lengths (target: 80% < 24 hours)
--   3. Token Theft Detection: Number of detected token reuse attempts
--   4. Geographic Anomalies: Logins from impossible travel patterns detected
--   5. Session Cleanup Efficiency: Expired sessions removed within SLA (< 1 hour)
--   6. MFA Adoption: Percentage of sessions using multi-factor authentication
--   7. Device Recognition: Trusted device ratio (recognized vs. new)
--
-- Feature Reference: SESS-02 (Session Management)
-- Requirements Traceability: R-SESSION-001 through R-SESSION-035
--
-- Normalization: 3NF - Sessions are independent entities with proper foreign keys
--
-- High-Write Considerations:
--   - High write volume (every login, logout, activity update)
--   - Indexes optimized for token lookups and expiration cleanup
--   - Partitioning by creation date for older session archival
--   - Partial indexes for active sessions only
-------------------------------------------------------------------------------
CREATE TABLE public.sessions (
    -- Primary key
    session_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User association
    user_id UUID NOT NULL,

    -- Authentication tokens (all hashed/encrypted)
    access_token TEXT NOT NULL,                -- Hashed access token
    refresh_token TEXT,                          -- Hashed refresh token
    id_token TEXT,                               -- OpenID Connect ID token
    token_type VARCHAR(20) DEFAULT 'Bearer' NOT NULL,

    -- Token metadata
    token_family UUID,                          -- Group related tokens (rotation chain)
    token_version INTEGER DEFAULT 1,              -- For token format migration

    -- Time-based controls
    issued_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    refresh_expires_at TIMESTAMP WITH TIME ZONE,
    last_activity_at TIMESTAMP WITH TIME ZONE,

    -- Client information
    client_id UUID,                              -- OAuth client if applicable
    client_version VARCHAR(50),
    user_agent TEXT,
    user_agent_parsed JSONB,                     -- Parsed browser/OS info

    -- Device fingerprinting
    device_id VARCHAR(255),                       -- Unique device identifier
    device_name VARCHAR(255),
    device_type VARCHAR(50) CHECK (device_type IN ('desktop', 'mobile', 'tablet', 'tv', 'watch', 'bot')),
    device_os VARCHAR(100),
    device_os_version VARCHAR(50),
    browser_name VARCHAR(100),
    browser_version VARCHAR(50),
    screen_resolution VARCHAR(20),
    timezone_offset INTEGER,                       -- Minutes from UTC
    language VARCHAR(10),

    -- Network information
    ip_address INET,
    ip_location GEOGRAPHY(POINT),                  -- Geolocation (if consented)
    ip_country CHAR(2),                            -- Country code
    ip_city VARCHAR(100),
    ip_asn INTEGER,                                 -- Autonomous System Number
    ip_isp VARCHAR(100),
    proxy_detected BOOLEAN DEFAULT false,
    vpn_detected BOOLEAN DEFAULT false,
    tor_detected BOOLEAN DEFAULT false,

    -- Security context
    auth_method VARCHAR(50) CHECK (auth_method IN ('password', 'oauth', 'saml', 'mfa', 'magic_link', 'api_key')),
    mfa_used BOOLEAN DEFAULT false,
    mfa_method VARCHAR(50),
    auth_provider VARCHAR(50),                     -- 'google', 'linkedin', etc.
    auth_provider_id VARCHAR(255),                  -- User ID from provider

    -- Risk assessment
    risk_score INTEGER CHECK (risk_score BETWEEN 0 AND 100),
    risk_factors TEXT[],                            -- ['new_device', 'new_location', 'unusual_time']
    risk_assessment_at TIMESTAMP WITH TIME ZONE,

    -- Session controls
    status public.session_status NOT NULL DEFAULT 'ACTIVE',
    requires_reauthentication BOOLEAN DEFAULT false,
    reauthentication_reason VARCHAR(100),
    reauthentication_at TIMESTAMP WITH TIME ZONE,

    -- Concurrent session management
    session_sequence INTEGER,                       -- Order among user's sessions
    parent_session_id UUID,                          -- For session hierarchies

    -- Consent tracking
    consent_granted_at TIMESTAMP WITH TIME ZONE,
    consent_version VARCHAR(50),

    -- Termination details
    terminated_at TIMESTAMP WITH TIME ZONE,
    terminated_by UUID,                             -- User or admin who terminated
    termination_reason TEXT,
    termination_ip INET,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,                       -- Usually the user themselves
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_access_token UNIQUE (access_token),
    CONSTRAINT uq_refresh_token UNIQUE (refresh_token),
    CONSTRAINT uq_id_token UNIQUE (id_token),
    CONSTRAINT chk_session_expiry CHECK (expires_at > issued_at),
    CONSTRAINT chk_refresh_expiry CHECK (refresh_expires_at IS NULL OR refresh_expires_at > issued_at),
    CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_sessions_parent FOREIGN KEY (parent_session_id) REFERENCES public.sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT fk_sessions_terminated_by FOREIGN KEY (terminated_by) REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.sessions IS 'Active user sessions with comprehensive security and device tracking';
COMMENT ON COLUMN public.sessions.session_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.sessions.user_id IS 'User owning the session';
COMMENT ON COLUMN public.sessions.access_token IS 'Hashed access token for API authentication';
COMMENT ON COLUMN public.sessions.refresh_token IS 'Hashed refresh token for obtaining new access tokens';
COMMENT ON COLUMN public.sessions.id_token IS 'OpenID Connect ID token (if applicable)';
COMMENT ON COLUMN public.sessions.token_type IS 'Type of token (Bearer, etc.)';
COMMENT ON COLUMN public.sessions.token_family IS 'Group identifier for token rotation chains';
COMMENT ON COLUMN public.sessions.token_version IS 'Version number for token format migration';
COMMENT ON COLUMN public.sessions.issued_at IS 'Timestamp when session was created';
COMMENT ON COLUMN public.sessions.expires_at IS 'Expiration time of access token';
COMMENT ON COLUMN public.sessions.refresh_expires_at IS 'Expiration time of refresh token';
COMMENT ON COLUMN public.sessions.last_activity_at IS 'Last request time using this session';
COMMENT ON COLUMN public.sessions.client_id IS 'OAuth client application ID';
COMMENT ON COLUMN public.sessions.client_version IS 'Version of client application';
COMMENT ON COLUMN public.sessions.user_agent IS 'Raw user agent string';
COMMENT ON COLUMN public.sessions.user_agent_parsed IS 'Parsed browser, OS, device information';
COMMENT ON COLUMN public.sessions.device_id IS 'Unique device identifier';
COMMENT ON COLUMN public.sessions.device_name IS 'Human-readable device name';
COMMENT ON COLUMN public.sessions.device_type IS 'Type of device';
COMMENT ON COLUMN public.sessions.device_os IS 'Operating system name';
COMMENT ON COLUMN public.sessions.device_os_version IS 'Operating system version';
COMMENT ON COLUMN public.sessions.browser_name IS 'Browser name';
COMMENT ON COLUMN public.sessions.browser_version IS 'Browser version';
COMMENT ON COLUMN public.sessions.screen_resolution IS 'Screen resolution';
COMMENT ON COLUMN public.sessions.timezone_offset IS 'Timezone offset in minutes from UTC';
COMMENT ON COLUMN public.sessions.language IS 'Browser language preference';
COMMENT ON COLUMN public.sessions.ip_address IS 'IP address of client';
COMMENT ON COLUMN public.sessions.ip_location IS 'Geolocation point (if consented)';
COMMENT ON COLUMN public.sessions.ip_country IS 'Country code from IP';
COMMENT ON COLUMN public.sessions.ip_city IS 'City from IP';
COMMENT ON COLUMN public.sessions.ip_asn IS 'Autonomous System Number';
COMMENT ON COLUMN public.sessions.ip_isp IS 'Internet Service Provider';
COMMENT ON COLUMN public.sessions.proxy_detected IS 'Whether request came through proxy';
COMMENT ON COLUMN public.sessions.vpn_detected IS 'Whether VPN was detected';
COMMENT ON COLUMN public.sessions.tor_detected IS 'Whether Tor network was detected';
COMMENT ON COLUMN public.sessions.auth_method IS 'Method used for authentication';
COMMENT ON COLUMN public.sessions.mfa_used IS 'Whether MFA was used';
COMMENT ON COLUMN public.sessions.mfa_method IS 'MFA method (totp, sms, etc.)';
COMMENT ON COLUMN public.sessions.auth_provider IS 'OAuth provider name';
COMMENT ON COLUMN public.sessions.auth_provider_id IS 'User ID from OAuth provider';
COMMENT ON COLUMN public.sessions.risk_score IS 'Risk score for this session (0-100)';
COMMENT ON COLUMN public.sessions.risk_factors IS 'List of risk factors identified';
COMMENT ON COLUMN public.sessions.risk_assessment_at IS 'When risk assessment was performed';
COMMENT ON COLUMN public.sessions.status IS 'Current session status';
COMMENT ON COLUMN public.sessions.requires_reauthentication IS 'Whether reauthentication is needed';
COMMENT ON COLUMN public.sessions.reauthentication_reason IS 'Why reauthentication is required';
COMMENT ON COLUMN public.sessions.reauthentication_at IS 'When reauthentication was performed';
COMMENT ON COLUMN public.sessions.session_sequence IS 'Order among user\'s active sessions';
COMMENT ON COLUMN public.sessions.parent_session_id IS 'Parent session (for session hierarchies)';
COMMENT ON COLUMN public.sessions.consent_granted_at IS 'When user consented to session tracking';
COMMENT ON COLUMN public.sessions.consent_version IS 'Version of consent agreement';
COMMENT ON COLUMN public.sessions.terminated_at IS 'When session was terminated';
COMMENT ON COLUMN public.sessions.terminated_by IS 'Who terminated the session';
COMMENT ON COLUMN public.sessions.termination_reason IS 'Why session was terminated';
COMMENT ON COLUMN public.sessions.termination_ip IS 'IP address that requested termination';
COMMENT ON COLUMN public.sessions.created_at IS 'Timestamp of session creation';
COMMENT ON COLUMN public.sessions.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.sessions.created_by IS 'User who created the session';
COMMENT ON COLUMN public.sessions.updated_by IS 'User who last updated the session';

-- Indexes for sessions
CREATE INDEX idx_sessions_user_id ON public.sessions(user_id, status);
CREATE INDEX idx_sessions_access_token ON public.sessions(access_token);
CREATE INDEX idx_sessions_refresh_token ON public.sessions(refresh_token) WHERE refresh_token IS NOT NULL;
CREATE INDEX idx_sessions_token_family ON public.sessions(token_family);
CREATE INDEX idx_sessions_expires_at ON public.sessions(expires_at) WHERE status = 'ACTIVE';
CREATE INDEX idx_sessions_refresh_expires ON public.sessions(refresh_expires_at) WHERE refresh_token IS NOT NULL;
CREATE INDEX idx_sessions_last_activity ON public.sessions(last_activity_at) WHERE status = 'ACTIVE';
CREATE INDEX idx_sessions_device_id ON public.sessions(device_id) WHERE device_id IS NOT NULL;
CREATE INDEX idx_sessions_ip_address ON public.sessions(ip_address);
CREATE INDEX idx_sessions_risk_score ON public.sessions(risk_score DESC) WHERE risk_score > 70;
CREATE INDEX idx_sessions_terminated ON public.sessions(terminated_at) WHERE terminated_at IS NOT NULL;

-- GiST index for IP location searches
CREATE INDEX idx_sessions_ip_location ON public.sessions USING gist(ip_location) WHERE ip_location IS NOT NULL;

-- BRIN index for time-based queries on large session table
CREATE INDEX idx_sessions_created_brin ON public.sessions USING brin(created_at);

-- Partial indexes for common queries
CREATE INDEX idx_sessions_active ON public.sessions(user_id, last_activity_at)
    WHERE status = 'ACTIVE';
CREATE INDEX idx_sessions_stale ON public.sessions(last_activity_at)
    WHERE status = 'ACTIVE' AND last_activity_at < NOW() - INTERVAL '30 days';

-- Trigger for updated_at
CREATE TRIGGER update_sessions_timestamp
    BEFORE UPDATE ON public.sessions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.sessions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY sessions_user_policy ON public.sessions
    USING (user_id = current_user_id());

CREATE POLICY sessions_security_policy ON public.sessions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('security_admin', 'admin')
    ));

CREATE POLICY sessions_cleanup_policy ON public.sessions
    FOR UPDATE USING (current_user = 'session_cleanup')
    WITH CHECK (status IN ('EXPIRED', 'TERMINATED'));

-- ======================================================================
-- TABLE 5: encryption_keys
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 5
-- Table Name: encryption_keys
-- Description: Hierarchical encryption key management system with full lifecycle
--              tracking, supporting master keys, data encryption keys, and
--              key encryption keys with rotation policies.
--
-- Business Case (300 words):
-- Enterprise-grade encryption requires a robust key management system that follows
-- industry best practices and compliance requirements (PCI DSS, HIPAA, GDPR).
-- This table implements a hierarchical key management system where master keys
-- protect lower-level keys, enabling secure key rotation without re-encrypting
-- all data—a critical requirement for large-scale systems.
--
-- Without proper key management, organizations face existential risks: keys
-- stored in code or configuration files can be stolen, rotated manually leading
-- to data loss, or compromised keys going undetected. This table addresses these
-- risks by providing a secure, auditable foundation for all cryptographic operations.
--
-- The business impact is profound: compliance with encryption mandates becomes
-- demonstrable through audit trails. Data breaches are contained as keys can be
-- rotated instantly. Multi-tenancy is supported through per-tenant keys.
-- Algorithm agility ensures that as cryptographic standards evolve, the system
-- can adapt without application changes.
--
-- The design follows NIST key management guidelines with clear separation of
-- duties: key creation, usage, and destruction are tracked. Keys have defined
-- purposes and usage restrictions, implementing the principle of least privilege.
-- Automatic rotation schedules ensure keys are refreshed regularly, reducing the
-- impact of undetected compromises. Integration with Hardware Security Modules
-- (HSMs) provides the highest level of physical security.
--
-- For compliance, the table maintains complete key lineage: when each key was
-- created, used, rotated, and destroyed. This meets requirements for key
-- lifecycle audit trails in regulated industries.
--
-- Key Performance Indicators (KPIs):
--   1. Key Rotation Compliance: Percentage of keys rotated within policy (target 100%)
--   2. Key Usage Coverage: Percentage of data encrypted with active keys
--   3. Compromise Response Time: Time to rotate compromised key (< 5 minutes)
--   4. Key Generation Latency: Time to create new key (< 100ms)
--   5. Audit Trail Completeness: 100% of key operations logged
--   6. Key Expiration Rate: Number of keys expiring per month
--   7. HSM Integration: Percentage of keys stored in HSM (target 100% for production)
--
-- Feature Reference: ENC-04 (Key Management)
-- Requirements Traceability: R-ENCRYPT-001 through R-ENCRYPT-030
--
-- Normalization: 3NF - Keys with hierarchy properly normalized
--
-- High-Write Considerations:
--   - Read-heavy for encryption/decryption operations
--   - Write-light (key creation and rotation infrequent)
--   - Caching with careful invalidation on key rotation
--   - Indexes optimized for key lookup by purpose and status
-------------------------------------------------------------------------------
CREATE TABLE public.encryption_keys (
    -- Primary key
    key_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Key identification
    key_name VARCHAR(255) NOT NULL,
    key_description TEXT,
    key_purpose public.encryption_key_usage NOT NULL,

    -- Key hierarchy
    parent_key_id UUID,                               -- Key that encrypts this key (KEK)
    root_key BOOLEAN DEFAULT false,                    -- Whether this is a root/master key

    -- Key material (encrypted by parent key)
    key_material BYTEA NOT NULL,                       -- Encrypted key material
    key_algorithm public.encryption_algorithm NOT NULL,
    key_size INTEGER NOT NULL CHECK (key_size BETWEEN 128 AND 4096),
    key_format VARCHAR(50) DEFAULT 'RAW' CHECK (key_format IN ('RAW', 'PKCS8', 'JWK')),

    -- Key identifiers (for cloud KMS integration)
    kms_provider VARCHAR(50),                          -- 'aws_kms', 'azure_keyvault', 'gcp_kms', 'hsm'
    kms_key_id VARCHAR(255),                            -- ID in external KMS
    external_key BOOLEAN DEFAULT false,                 -- Whether key is stored externally

    -- Key lifecycle
    key_version INTEGER NOT NULL DEFAULT 1,
    status public.encryption_key_status NOT NULL DEFAULT 'ACTIVE',
    activated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deactivated_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- Rotation
    rotation_due_at TIMESTAMP WITH TIME ZONE,
    rotated_from_key_id UUID,                           -- Previous version

    -- Usage restrictions
    allowed_operations TEXT[] NOT NULL DEFAULT '{ENCRYPT,DECRYPT}', -- Allowed crypto operations
    max_uses_per_period INTEGER,                         -- Rate limiting
    usage_period_seconds INTEGER,                         -- Period for max_uses

    -- Usage tracking
    times_used BIGINT DEFAULT 0,
    last_used_at TIMESTAMP WITH TIME ZONE,
    last_used_for VARCHAR(100),                          -- Last operation type

    -- Compliance
    compliance_tags TEXT[],                              -- e.g., {'PCI', 'HIPAA', 'GDPR'}
    fips_compliant BOOLEAN DEFAULT false,                 -- FIPS 140-2 compliance

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_key_name UNIQUE (key_name, key_version),
    CONSTRAINT chk_key_expiry CHECK (expires_at IS NULL OR expires_at > activated_at),
    CONSTRAINT chk_key_deactivation CHECK (deactivated_at IS NULL OR deactivated_at >= activated_at),
    CONSTRAINT fk_keys_parent FOREIGN KEY (parent_key_id)
        REFERENCES public.encryption_keys(key_id) ON DELETE RESTRICT,
    CONSTRAINT fk_keys_rotated_from FOREIGN KEY (rotated_from_key_id)
        REFERENCES public.encryption_keys(key_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.encryption_keys IS 'Hierarchical encryption key management with full lifecycle tracking';
COMMENT ON COLUMN public.encryption_keys.key_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.encryption_keys.key_name IS 'Unique name for the key (e.g., master-key-2024)';
COMMENT ON COLUMN public.encryption_keys.key_description IS 'Description of key purpose';
COMMENT ON COLUMN public.encryption_keys.key_purpose IS 'Allowed usage for this key';
COMMENT ON COLUMN public.encryption_keys.parent_key_id IS 'Parent key that encrypts this key (KEK)';
COMMENT ON COLUMN public.encryption_keys.root_key IS 'Whether this is a root/master key (no parent)';
COMMENT ON COLUMN public.encryption_keys.key_material IS 'Encrypted key material';
COMMENT ON COLUMN public.encryption_keys.key_algorithm IS 'Encryption algorithm for this key';
COMMENT ON COLUMN public.encryption_keys.key_size IS 'Key size in bits';
COMMENT ON COLUMN public.encryption_keys.key_format IS 'Format of the key material';
COMMENT ON COLUMN public.encryption_keys.kms_provider IS 'External KMS provider (if applicable)';
COMMENT ON COLUMN public.encryption_keys.kms_key_id IS 'Key ID in external KMS';
COMMENT ON COLUMN public.encryption_keys.external_key IS 'Whether key is stored externally';
COMMENT ON COLUMN public.encryption_keys.key_version IS 'Version number for this key';
COMMENT ON COLUMN public.encryption_keys.status IS 'Current key status';
COMMENT ON COLUMN public.encryption_keys.activated_at IS 'When key became active';
COMMENT ON COLUMN public.encryption_keys.deactivated_at IS 'When key was deactivated';
COMMENT ON COLUMN public.encryption_keys.expires_at IS 'When key expires';
COMMENT ON COLUMN public.encryption_keys.rotation_due_at IS 'When key should be rotated';
COMMENT ON COLUMN public.encryption_keys.rotated_from_key_id IS 'Previous version of this key';
COMMENT ON COLUMN public.encryption_keys.allowed_operations IS 'Allowed cryptographic operations';
COMMENT ON COLUMN public.encryption_keys.max_uses_per_period IS 'Maximum uses in time period';
COMMENT ON COLUMN public.encryption_keys.usage_period_seconds IS 'Time period for max_uses';
COMMENT ON COLUMN public.encryption_keys.times_used IS 'Number of times key has been used';
COMMENT ON COLUMN public.encryption_keys.last_used_at IS 'When key was last used';
COMMENT ON COLUMN public.encryption_keys.last_used_for IS 'Last operation performed';
COMMENT ON COLUMN public.encryption_keys.compliance_tags IS 'Compliance classifications';
COMMENT ON COLUMN public.encryption_keys.fips_compliant IS 'Whether key is FIPS 140-2 compliant';
COMMENT ON COLUMN public.encryption_keys.created_at IS 'Timestamp of key creation';
COMMENT ON COLUMN public.encryption_keys.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.encryption_keys.created_by IS 'User who created the key';
COMMENT ON COLUMN public.encryption_keys.updated_by IS 'User who last updated the key';

-- Indexes for encryption_keys
CREATE INDEX idx_keys_name ON public.encryption_keys(key_name, key_version);
CREATE INDEX idx_keys_parent ON public.encryption_keys(parent_key_id) WHERE parent_key_id IS NOT NULL;
CREATE INDEX idx_keys_status ON public.encryption_keys(status, key_purpose);
CREATE INDEX idx_keys_expiry ON public.encryption_keys(expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX idx_keys_rotation ON public.encryption_keys(rotation_due_at) WHERE rotation_due_at IS NOT NULL;
CREATE INDEX idx_keys_usage ON public.encryption_keys(last_used_at) WHERE times_used > 0;

-- Partial index for active keys
CREATE INDEX idx_keys_active ON public.encryption_keys(key_id) WHERE status IN ('ACTIVE', 'ACTIVE_READONLY');

-- Trigger for updated_at
CREATE TRIGGER update_encryption_keys_timestamp
    BEFORE UPDATE ON public.encryption_keys
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.encryption_keys ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY encryption_keys_service_policy ON public.encryption_keys
    USING (current_user = 'key_management_service');

CREATE POLICY encryption_keys_admin_policy ON public.encryption_keys
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('security_admin', 'admin')
    ));

-- ======================================================================
-- TABLE 6: secrets_manager
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 6
-- Table Name: secrets_manager
-- Description: Centralized encrypted storage for all application secrets
--              (API keys, database passwords, certificates) with full audit
--              trail, rotation policies, and access controls.
--
-- Business Case (300 words):
-- In a microservices architecture, dozens of services need credentials for
-- databases, external APIs, and other services. Hardcoding these secrets in
-- configuration files or environment variables creates unacceptable security
-- risks and operational overhead. This table serves as a centralized vault for
-- all secrets, with encryption at rest and comprehensive access controls.
--
-- Without a secrets management system, organizations face critical vulnerabilities:
-- secrets leaked in code repositories, developers sharing credentials insecurely,
-- no audit trail of who accessed what, and inability to rotate credentials
-- quickly after a breach. This table addresses these challenges by providing a
-- secure, auditable foundation for all credential management.
--
-- The business impact is transformative: security posture improves dramatically
-- as secrets are never exposed in plaintext. Operational efficiency increases
-- through automated rotation—no more manual credential updates. Compliance
-- requirements are met through complete audit trails of secret access. Incident
-- response improves as compromised secrets can be rotated globally in minutes.
--
-- The design supports enterprise requirements: hierarchical organization by
-- environment and service, versioning for zero-downtime rotation, automatic
-- rotation policies, and emergency access procedures. Integration with container
-- orchestration platforms enables dynamic secret injection at runtime.
--
-- For compliance, every secret access is logged with timestamp, user, and
-- purpose. Rotation policies ensure credentials are regularly refreshed.
-- Compromise detection triggers immediate rotation and alerts security teams.
--
-- Key Performance Indicators (KPIs):
--   1. Secret Coverage: Percentage of production secrets managed (target 100%)
--   2. Rotation Compliance: Percentage rotated within policy window
--   3. Access Audit: 100% of secret accesses logged
--   4. Compromise Response: Time to rotate compromised secret (< 5 minutes)
--   5. Secret Age: Average age of active secrets
--   6. Access Anomalies: Number of suspicious access patterns detected
--   7. Service Onboarding: Time to provision secrets for new service (< 1 hour)
--
-- Feature Reference: SEC-04 (Secrets Management)
-- Requirements Traceability: R-SECRETS-001 through R-SECRETS-025
--
-- Normalization: 3NF - Secrets with versioning and access controls
--
-- High-Write Considerations:
--   - Read-heavy (services fetch secrets at startup and rotation)
--   - Write-light (secret updates infrequent)
--   - Caching with short TTL for frequently accessed secrets
--   - Indexes optimized for service lookups
-------------------------------------------------------------------------------
CREATE TABLE public.secrets_manager (
    -- Primary key
    secret_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Secret identification
    secret_key VARCHAR(255) NOT NULL,           -- e.g., 'database/main/password'
    secret_name VARCHAR(255) NOT NULL,           -- Human-readable name
    description TEXT,

    -- Secret value (encrypted)
    secret_value BYTEA NOT NULL,                  -- Encrypted secret
    secret_hash TEXT,                              -- Hash for integrity
    encryption_key_id UUID,                         -- Which key encrypted it

    -- Secret metadata
    secret_type VARCHAR(50) CHECK (secret_type IN ('password', 'api_key', 'certificate', 'ssh_key', 'token', 'connection_string')),
    version INTEGER NOT NULL DEFAULT 1,
    previous_version_id UUID,                       -- Link to previous version

    -- Environment and context
    environment VARCHAR(50) NOT NULL CHECK (environment IN ('development', 'staging', 'production', 'dr')),
    service_name VARCHAR(100) NOT NULL,              -- Which service uses this
    region VARCHAR(50),                               -- Geographic region
    component VARCHAR(100),                           -- Sub-component

    -- Rotation policy
    rotation_policy public.secret_rotation_policy NOT NULL DEFAULT 'MANUAL',
    rotation_schedule VARCHAR(50),                    -- Cron expression for auto-rotation
    last_rotated_at TIMESTAMP WITH TIME ZONE,
    next_rotation_at TIMESTAMP WITH TIME ZONE,
    rotated_by UUID,                                  -- Who last rotated

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    expiry_warning_sent BOOLEAN DEFAULT false,

    -- Access control
    allowed_services TEXT[],                           -- Services that can access
    allowed_roles TEXT[],                              -- Roles that can access
    requires_approval BOOLEAN DEFAULT false,           -- Need approval for access

    -- Usage tracking
    last_accessed_at TIMESTAMP WITH TIME ZONE,
    last_accessed_by UUID,
    access_count BIGINT DEFAULT 0,

    -- Compromise detection
    compromise_detected BOOLEAN DEFAULT false,
    compromise_detected_at TIMESTAMP WITH TIME ZONE,
    compromise_reason TEXT,
    auto_rotate_on_compromise BOOLEAN DEFAULT true,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_secret_key UNIQUE (secret_key, environment, region),
    CONSTRAINT uq_secret_name UNIQUE (secret_name, environment),
    CONSTRAINT chk_secret_expiry CHECK (expires_at IS NULL OR expires_at > created_at),
    CONSTRAINT fk_secrets_prev_version FOREIGN KEY (previous_version_id)
        REFERENCES public.secrets_manager(secret_id) ON DELETE SET NULL,
    CONSTRAINT fk_secrets_encryption_key FOREIGN KEY (encryption_key_id)
        REFERENCES public.encryption_keys(key_id) ON DELETE RESTRICT,
    CONSTRAINT fk_secrets_rotated_by FOREIGN KEY (rotated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_secrets_last_accessed_by FOREIGN KEY (last_accessed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.secrets_manager IS 'Centralized encrypted storage for all application secrets with full audit';
COMMENT ON COLUMN public.secrets_manager.secret_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.secrets_manager.secret_key IS 'Unique key for the secret (hierarchical format)';
COMMENT ON COLUMN public.secrets_manager.secret_name IS 'Human-readable name for the secret';
COMMENT ON COLUMN public.secrets_manager.description IS 'Detailed description of secret purpose';
COMMENT ON COLUMN public.secrets_manager.secret_value IS 'Encrypted secret value (binary)';
COMMENT ON COLUMN public.secrets_manager.secret_hash IS 'Hash of secret for integrity verification';
COMMENT ON COLUMN public.secrets_manager.encryption_key_id IS 'ID of key used to encrypt this secret';
COMMENT ON COLUMN public.secrets_manager.secret_type IS 'Type of secret for validation';
COMMENT ON COLUMN public.secrets_manager.version IS 'Version number for rotation';
COMMENT ON COLUMN public.secrets_manager.previous_version_id IS 'Previous version (for rollback)';
COMMENT ON COLUMN public.secrets_manager.environment IS 'Environment where secret is used';
COMMENT ON COLUMN public.secrets_manager.service_name IS 'Service that uses this secret';
COMMENT ON COLUMN public.secrets_manager.region IS 'Geographic region (for multi-region)';
COMMENT ON COLUMN public.secrets_manager.component IS 'Specific component within service';
COMMENT ON COLUMN public.secrets_manager.rotation_policy IS 'How often secret should be rotated';
COMMENT ON COLUMN public.secrets_manager.rotation_schedule IS 'Cron expression for auto-rotation';
COMMENT ON COLUMN public.secrets_manager.last_rotated_at IS 'When secret was last rotated';
COMMENT ON COLUMN public.secrets_manager.next_rotation_at IS 'When secret should next be rotated';
COMMENT ON COLUMN public.secrets_manager.rotated_by IS 'Who performed last rotation';
COMMENT ON COLUMN public.secrets_manager.expires_at IS 'When secret expires (if applicable)';
COMMENT ON COLUMN public.secrets_manager.expiry_warning_sent IS 'Whether expiry warning was sent';
COMMENT ON COLUMN public.secrets_manager.allowed_services IS 'Services permitted to access';
COMMENT ON COLUMN public.secrets_manager.allowed_roles IS 'Roles permitted to access';
COMMENT ON COLUMN public.secrets_manager.requires_approval IS 'Whether access requires approval';
COMMENT ON COLUMN public.secrets_manager.last_accessed_at IS 'When secret was last accessed';
COMMENT ON COLUMN public.secrets_manager.last_accessed_by IS 'Who last accessed the secret';
COMMENT ON COLUMN public.secrets_manager.access_count IS 'Number of times secret was accessed';
COMMENT ON COLUMN public.secrets_manager.compromise_detected IS 'Whether compromise was detected';
COMMENT ON COLUMN public.secrets_manager.compromise_detected_at IS 'When compromise was detected';
COMMENT ON COLUMN public.secrets_manager.compromise_reason IS 'Why compromise was suspected';
COMMENT ON COLUMN public.secrets_manager.auto_rotate_on_compromise IS 'Auto-rotate if compromised';
COMMENT ON COLUMN public.secrets_manager.created_at IS 'Timestamp of secret creation';
COMMENT ON COLUMN public.secrets_manager.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.secrets_manager.created_by IS 'User who created the secret';
COMMENT ON COLUMN public.secrets_manager.updated_by IS 'User who last updated the secret';

-- Indexes for secrets_manager
CREATE INDEX idx_secrets_key ON public.secrets_manager(secret_key, environment, region);
CREATE INDEX idx_secrets_service ON public.secrets_manager(service_name, environment);
CREATE INDEX idx_secrets_expiry ON public.secrets_manager(expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX idx_secrets_next_rotation ON public.secrets_manager(next_rotation_at) WHERE next_rotation_at IS NOT NULL;
CREATE INDEX idx_secrets_encryption_key ON public.secrets_manager(encryption_key_id);
CREATE INDEX idx_secrets_compromised ON public.secrets_manager(compromise_detected) WHERE compromise_detected = true;
CREATE INDEX idx_secrets_previous_version ON public.secrets_manager(previous_version_id) WHERE previous_version_id IS NOT NULL;

-- Partial index for active secrets needing rotation
CREATE INDEX idx_secrets_pending_rotation ON public.secrets_manager(next_rotation_at)
    WHERE next_rotation_at < CURRENT_TIMESTAMP AND compromise_detected = false;

-- Trigger for updated_at
CREATE TRIGGER update_secrets_manager_timestamp
    BEFORE UPDATE ON public.secrets_manager
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.secrets_manager ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY secrets_manager_service_policy ON public.secrets_manager
    FOR SELECT USING (current_user = 'secrets_service');

CREATE POLICY secrets_manager_admin_policy ON public.secrets_manager
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'security_admin')
    ));

-- ======================================================================
-- TABLE 7: data_classification
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 7
-- Table Name: data_classification
-- Description: Inventory and classification of all sensitive data elements
--              with sensitivity levels, protection requirements, and
--              compliance mappings.
--
-- Business Case (300 words):
-- With increasing regulatory requirements (GDPR, CCPA, HIPAA, PCI DSS),
-- organizations must know exactly what sensitive data they hold and how to
-- protect it. This table serves as the authoritative inventory of all data
-- elements requiring special handling, enabling automated policy enforcement.
--
-- Without a data classification system, organizations are blind to their
-- sensitive data exposure. They cannot answer fundamental questions: What PII
-- do we store? Where is it located? Who has access? This leads to compliance
-- violations, data breaches, and regulatory fines. This table provides the
-- foundation for data-centric security.
--
-- The business impact is substantial: compliance becomes demonstrable with a
-- complete inventory of sensitive data. Security controls can be automatically
-- applied based on classification. Breach impact assessments become accurate
-- and rapid. Data minimization initiatives can target unnecessary data collection.
-- Privacy Impact Assessments (DPIAs) leverage the classification for risk analysis.
--
-- The design supports multiple regulatory frameworks simultaneously—a field can
-- be both PII and PCI. Protection requirements are explicitly defined: encryption
-- algorithms, masking rules, retention periods. Access controls specify who can
-- access what. Data lineage tracks how data flows through the system.
--
-- For privacy operations, the table enables rapid response to Data Subject Access
-- Requests (DSARs) by identifying all locations of a user's data. For security,
-- it feeds into Data Loss Prevention (DLP) systems to block unauthorized transfers
-- of classified data. For governance, it provides the foundation for data quality
-- and retention management.
--
-- Key Performance Indicators (KPIs):
--   1. Classification Coverage: Percentage of data elements classified (target > 95%)
--   2. Sensitivity Distribution: Volume of data by sensitivity level
--   3. Protection Compliance: Percentage with appropriate encryption applied
--   4. DSAR Response Time: Time to locate all user data (< 1 hour)
--   5. Classification Accuracy: Audit-verified correctness (target > 99%)
--   6. Regulatory Coverage: Number of compliance frameworks mapped
--   7. Data Lineage Completeness: Percentage with end-to-end flow documented
--
-- Feature Reference: CLASS-03 (Data Classification)
-- Requirements Traceability: R-CLASS-001 through R-CLASS-020
--
-- Normalization: 3NF - Classification independent of data storage
--
-- High-Write Considerations:
--   - Read-heavy (every data access checks classification)
--   - Write-light (classification changes rare)
--   - Caching critical for performance
--   - Partial indexes for active classifications only
-------------------------------------------------------------------------------
CREATE TABLE public.data_classification (
    -- Primary key
    classification_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Data element identification
    data_domain VARCHAR(100) NOT NULL,            -- e.g., 'user', 'payment', 'health'
    data_category public.data_category NOT NULL,
    data_element VARCHAR(255) NOT NULL,            -- e.g., 'email', 'credit_card'
    data_description TEXT,

    -- Location information (where this data lives)
    database_name VARCHAR(100),
    schema_name VARCHAR(100),
    table_name VARCHAR(100),
    column_name VARCHAR(100),
    api_endpoint VARCHAR(255),                      -- If exposed via API
    api_field VARCHAR(255),                          -- Field name in API
    file_type VARCHAR(50),                           -- For file-based data

    -- Sensitivity classification
    sensitivity_level public.data_sensitivity_level NOT NULL,
    sensitivity_score INTEGER CHECK (sensitivity_score BETWEEN 1 AND 10), -- 10 = most sensitive

    -- Compliance frameworks
    gdpr_relevant BOOLEAN DEFAULT false,
    gdpr_category VARCHAR(50) CHECK (gdpr_category IN ('IDENTIFICATION', 'FINANCIAL', 'HEALTH', 'BIOMETRIC', 'GENETIC', 'POLITICAL', 'RELIGIOUS', 'TRADE_UNION')),
    ccpa_relevant BOOLEAN DEFAULT false,
    pci_relevant BOOLEAN DEFAULT false,
    pci_category VARCHAR(20) CHECK (pci_category IN ('CHD', 'SAD', 'PAN')),
    hipaa_relevant BOOLEAN DEFAULT false,
    hipaa_category VARCHAR(20) CHECK (hipaa_category IN ('PHI', 'CE', 'BA')),
    sox_relevant BOOLEAN DEFAULT false,

    -- Protection requirements
    requires_encryption_at_rest BOOLEAN DEFAULT true,
    encryption_algorithm VARCHAR(50),                      -- Which algorithm to use
    requires_encryption_in_transit BOOLEAN DEFAULT true,
    requires_masking BOOLEAN DEFAULT false,
    masking_pattern VARCHAR(100),                           -- e.g., '***-***-1234'
    requires_redaction BOOLEAN DEFAULT false,               -- For logs
    requires_anonymization BOOLEAN DEFAULT false,           -- For analytics
    anonymization_method VARCHAR(50),                        -- e.g., 'hash', 'tokenize', 'generalize'

    -- Access controls
    minimum_access_role VARCHAR(100),                        -- Minimum role required
    requires_justification BOOLEAN DEFAULT false,            -- Need business reason
    requires_approval BOOLEAN DEFAULT false,                 -- Need manager approval
    access_audit_level VARCHAR(20) DEFAULT 'STANDARD' CHECK (access_audit_level IN ('NONE', 'STANDARD', 'DETAILED', 'ALWAYS')),

    -- Retention
    retention_period_days INTEGER,                           -- How long to keep
    retention_policy_id UUID,                                 -- Reference to retention policy
    requires_purging BOOLEAN DEFAULT true,                    -- Must be deleted after retention

    -- Data lineage
    data_source VARCHAR(255),                                 -- Where data comes from
    data_sink VARCHAR(255),                                   -- Where data goes to
    transformation_log JSONB,                                 -- How data is transformed

    -- Business context
    business_process VARCHAR(255),                            -- Which process uses this
    legal_basis VARCHAR(50),                                   -- For GDPR: consent, contract, etc.
    data_controller VARCHAR(255),                              -- Who controls this data
    data_processor VARCHAR(255),                               -- Who processes this data

    -- Third-party sharing
    shared_with_third_parties BOOLEAN DEFAULT false,
    third_parties TEXT[],                                     -- List of third parties
    sharing_countries TEXT[],                                 -- Countries shared to

    -- Data quality
    data_quality_requirement VARCHAR(50),                      -- e.g., 'HIGH', 'MEDIUM', 'LOW'
    validation_rules JSONB,                                   -- Validation requirements

    -- Audit and metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,
    deprecated_at TIMESTAMP WITH TIME ZONE,
    deprecated_by UUID,
    deprecation_reason TEXT,

    -- Constraints
    CONSTRAINT uq_data_classification UNIQUE (data_domain, data_category, data_element, table_name, column_name),
    CONSTRAINT chk_classification_location CHECK (
        (database_name IS NOT NULL AND schema_name IS NOT NULL AND table_name IS NOT NULL AND column_name IS NOT NULL) OR
        (api_endpoint IS NOT NULL AND api_field IS NOT NULL) OR
        (file_type IS NOT NULL)
    )
);

