-- ======================================================================
-- MATERIALIZED VIEW: mv_encryption_key_status
-- ======================================================================
-------------------------------------------------------------------------------
-- Materialized View: mv_encryption_key_status
-- Description: Pre-aggregated view of encryption key health and compliance status
-- Business Case: Provides rapid dashboard for key management monitoring
-- Refresh Strategy: Hourly (configurable based on rotation frequency)
-- Feature Reference: ENC-05 (Key Monitoring)
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW public.mv_encryption_key_status AS
WITH key_metrics AS (
    SELECT
        key_purpose,
        status,
        COUNT(*) as key_count,
        AVG(EXTRACT(EPOCH FROM (NOW() - last_used_at)) / 86400) as avg_days_since_use,
        COUNT(*) FILTER (WHERE expires_at < NOW() + INTERVAL '30 days') as keys_expiring_soon,
        COUNT(*) FILTER (WHERE rotation_due_at < NOW()) as keys_needing_rotation
    FROM public.encryption_keys
    GROUP BY key_purpose, status
)
SELECT
    key_purpose,
    status,
    key_count,
    ROUND(avg_days_since_use::NUMERIC, 2) as avg_days_since_use,
    keys_expiring_soon,
    keys_needing_rotation,
    ROUND((keys_expiring_soon::NUMERIC / NULLIF(key_count, 0) * 100), 2) as pct_expiring_soon,
    ROUND((keys_needing_rotation::NUMERIC / NULLIF(key_count, 0) * 100), 2) as pct_needing_rotation,
    NOW() as refreshed_at
FROM key_metrics;

COMMENT ON MATERIALIZED VIEW public.mv_encryption_key_status IS 'Aggregated encryption key health metrics for monitoring dashboards';

CREATE UNIQUE INDEX idx_mv_encryption_key_status ON public.mv_encryption_key_status(key_purpose, status);

-- ======================================================================
-- STORED PROCEDURE: rotate_encryption_key
-- ======================================================================
-------------------------------------------------------------------------------
-- Stored Procedure: rotate_encryption_key
-- Description: Safely rotates an encryption key, creating a new version and
--              updating dependent secrets with comprehensive error handling.
-- Business Case: Automates key rotation to comply with security policies
-- Feature Reference: ENC-06 (Key Rotation)
-------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE public.rotate_encryption_key(
    p_key_id UUID,
    p_rotated_by UUID,
    p_reason TEXT DEFAULT 'scheduled rotation'
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_old_key RECORD;
    v_new_key_id UUID;
    v_new_key_material BYTEA;
    v_affected_secrets INTEGER;
BEGIN
    -- Input validation
    IF p_key_id IS NULL THEN
        RAISE EXCEPTION 'key_id cannot be null';
    END IF;

    IF p_rotated_by IS NULL THEN
        RAISE EXCEPTION 'rotated_by cannot be null';
    END IF;

    -- Get old key details with row lock
    SELECT * INTO v_old_key
    FROM public.encryption_keys
    WHERE key_id = p_key_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Key with ID % not found', p_key_id;
    END IF;

    -- Check if key can be rotated
    IF v_old_key.status NOT IN ('ACTIVE', 'ACTIVE_READONLY') THEN
        RAISE EXCEPTION 'Cannot rotate key with status %', v_old_key.status;
    END IF;

    -- Start transaction
    BEGIN
        -- Generate new key material (simplified - in production, use proper key generation)
        v_new_key_material := pgp_sym_encrypt(
            encode(gen_random_bytes(32), 'hex'),
            current_setting('app.encryption_master_key')
        );

        -- Create new key version
        INSERT INTO public.encryption_keys (
            key_name,
            key_description,
            key_purpose,
            parent_key_id,
            root_key,
            key_material,
            key_algorithm,
            key_size,
            key_version,
            status,
            rotated_from_key_id,
            created_by,
            updated_by
        ) VALUES (
            v_old_key.key_name || '_v' || (v_old_key.key_version + 1),
            'Rotated from ' || v_old_key.key_name || ' - ' || p_reason,
            v_old_key.key_purpose,
            v_old_key.parent_key_id,
            v_old_key.root_key,
            v_new_key_material,
            v_old_key.key_algorithm,
            v_old_key.key_size,
            v_old_key.key_version + 1,
            'ACTIVE',
            v_old_key.key_id,
            p_rotated_by,
            p_rotated_by
        ) RETURNING key_id INTO v_new_key_id;

        -- Mark old key as read-only
        UPDATE public.encryption_keys
        SET
            status = 'ACTIVE_READONLY',
            rotation_due_at = NULL,
            updated_at = CURRENT_TIMESTAMP,
            updated_by = p_rotated_by
        WHERE key_id = p_key_id;

        -- Update dependent secrets to use new key
        UPDATE public.secrets_manager
        SET
            encryption_key_id = v_new_key_id,
            updated_at = CURRENT_TIMESTAMP,
            updated_by = p_rotated_by
        WHERE encryption_key_id = p_key_id;

        GET DIAGNOSTICS v_affected_secrets = ROW_COUNT;

        -- Log rotation in audit logs
        INSERT INTO public.audit_logs (
            actor_id,
            action,
            entity_type,
            entity_id,
            details,
            category,
            severity,
            log_timestamp
        ) VALUES (
            p_rotated_by,
            'rotate_key',
            'encryption_keys',
            p_key_id,
            jsonb_build_object(
                'new_key_id', v_new_key_id,
                'affected_secrets', v_affected_secrets,
                'reason', p_reason
            ),
            'SECURITY',
            'INFO',
            CURRENT_TIMESTAMP
        );

        -- Commit transaction
        COMMIT;

        RAISE NOTICE 'Successfully rotated key % to new version %. Affected secrets: %',
            v_old_key.key_name, v_old_key.key_version + 1, v_affected_secrets;

    EXCEPTION
        WHEN OTHERS THEN
            -- Rollback transaction
            ROLLBACK;
            RAISE EXCEPTION 'Key rotation failed: %', SQLERRM;
    END;
END;
$$;

COMMENT ON PROCEDURE public.rotate_encryption_key IS 'Safely rotates encryption keys with comprehensive error handling and audit logging';

