    'password_hash',
    'RESTRICTED',
    10,
    true,
    true,
    false,
    'admin',
    '00000000-0000-0000-0000-000000000000',
    '00000000-0000-0000-0000-000000000000'
) ON CONFLICT (data_domain, data_category, data_element, table_name, column_name) DO NOTHING;

-- Insert initial encryption master key
INSERT INTO public.encryption_keys (
    key_name,
    key_description,
    key_purpose,
    root_key,
    key_material,
    key_algorithm,
    key_size,
    status,
    created_by,
    updated_by
) VALUES (
    'master-key-2025',
    'Master encryption key for all data encryption keys',
    'KEY_ENCRYPTION',
    true,
    pgp_sym_encrypt(gen_random_bytes(32)::TEXT, 'temporary-master-password-change-me'),
    'AES256_GCM',
    256,
    'ACTIVE',
    '00000000-0000-0000-0000-000000000000',
    '00000000-0000-0000-0000-000000000000'
) ON CONFLICT (key_name, key_version) DO NOTHING;

-- ======================================================================
-- SCHEDULED JOBS (pg_cron integration)
-- ======================================================================

-- Create scheduled jobs if pg_cron is available
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
        -- Clean up expired sessions daily at 2 AM
        PERFORM cron.schedule(
            'cleanup-expired-sessions',
            '0 2 * * *',
            $$
            DELETE FROM public.sessions
            WHERE status IN ('EXPIRED', 'TERMINATED')
            AND updated_at < NOW() - INTERVAL '7 days'
            $$
        );

        -- Refresh encryption key status view hourly
        PERFORM cron.schedule(
            'refresh-key-status',
            '0 * * * *',
            'REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_encryption_key_status'
        );

        -- Check for keys needing rotation daily at 3 AM
        PERFORM cron.schedule(
            'check-key-rotation',
            '0 3 * * *',
            $$
            SELECT key_id, key_name
            FROM public.encryption_keys
            WHERE rotation_due_at < NOW() + INTERVAL '7 days'
            AND status = 'ACTIVE'
            $$
        );

        -- Archive audit logs older than 90 days monthly
        PERFORM cron.schedule(
            'archive-audit-logs',
            '0 4 1 * *',
            $$
            CALL public.archive_audit_logs(INTERVAL '90 days')
            $$
        );
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'pg_cron extension not available. Scheduled jobs will not be created.';
END $$;

