-- Indexes for subscriptions
CREATE INDEX idx_subscriptions_user_id ON public.subscriptions(user_id, status);
CREATE INDEX idx_subscriptions_company_id ON public.subscriptions(company_id) WHERE company_id IS NOT NULL;
CREATE INDEX idx_subscriptions_plan_id ON public.subscriptions(plan_id, status);
