CREATE INDEX idx_subscriptions_active ON public.subscriptions(subscription_id)
    WHERE status IN ('ACTIVE', 'TRIALING', 'PAST_DUE');

-- GiST index for JSONB metadata
CREATE INDEX idx_subscriptions_metadata ON public.subscriptions USING gin(metadata);

-- Trigger for updated_at
CREATE TRIGGER update_subscriptions_timestamp
    BEFORE UPDATE ON public.subscriptions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update status_changed_at
CREATE OR REPLACE FUNCTION public.update_subscription_status_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.status != OLD.status THEN
        NEW.status_changed_at := CURRENT_TIMESTAMP;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER set_subscription_status_changed
    BEFORE UPDATE OF status ON public.subscriptions
    FOR EACH ROW EXECUTE FUNCTION public.update_subscription_status_timestamp();

-- Enable RLS
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY subscriptions_user_policy ON public.subscriptions
    USING (user_id = current_user_id());

CREATE POLICY subscriptions_company_policy ON public.subscriptions
    FOR SELECT USING (
        company_id IS NOT NULL AND
        EXISTS (
            SELECT 1 FROM public.company_admins ca
            WHERE ca.company_id = subscriptions.company_id
            AND ca.user_id = current_user_id()
        )
    );

CREATE POLICY subscriptions_finance_policy ON public.subscriptions
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- ======================================================================
-- TABLE 15: subscription_events
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 15
-- Table Name: subscription_events
-- Description: Audit trail of all subscription state changes for analysis
--              and debugging. Records every status change, plan change,
--              and significant event in the subscription lifecycle.
--
-- Business Case: Subscriptions change state frequently (trial → active →
--                canceled). This table records every state change with
--                reasons, enabling churn analysis, subscription lifecycle
--                tracking, debugging billing issues, and compliance audit.
--
-- The business impact is understanding why users churn—by analyzing
-- cancellation reasons and patterns, the business can implement retention
-- strategies. For financial reporting, the event history supports accurate
-- revenue recognition and audit trails.
--
-- Key Performance Indicators (KPIs):
--   1. Event Frequency: Distribution of event types
--   2. Time Between Events: Average time in each state
--   3. Churn Pattern Analysis: Most common paths to cancellation
--   4. Upgrade/Downgrade Patterns: When users change plans
--   5. Payment Failure Rate: By subscription cohort
--
-- Feature Reference: SUB-04 (Subscription Audit)
-- Requirements Traceability: R-SUB-036 through R-SUB-045
--
-- Normalization: 3NF - Events dependent on subscriptions
--
-- High-Write Considerations:
--   - High write volume (each status change creates event)
--   - Read-heavy for analytics and debugging
--   - Partitioning by created_at recommended
--   - Indexed by subscription_id for fast history retrieval
-------------------------------------------------------------------------------
CREATE TABLE public.subscription_events (
    -- Primary key
    event_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    subscription_id UUID NOT NULL,

    -- Event details
    event_type VARCHAR(50) NOT NULL CHECK (event_type IN (
        'CREATED', 'TRIAL_STARTED', 'TRIAL_ENDED', 'ACTIVATED', 'RENEWED',
        'UPGRADED', 'DOWNGRADED', 'PAYMENT_SUCCEEDED', 'PAYMENT_FAILED',
        'PAST_DUE', 'SUSPENDED', 'CANCELED', 'EXPIRED', 'REACTIVATED',
        'PLAN_CHANGED', 'QUANTITY_CHANGED', 'PAYMENT_METHOD_CHANGED'
    )),

    -- State transition
    previous_status public.subscription_status,
    new_status public.subscription_status NOT NULL,

    -- Plan changes (if applicable)
    previous_plan_id UUID,
    new_plan_id UUID,

    -- Metadata
    event_reason TEXT,
    event_data JSONB,                                   -- Additional event data

    -- Who triggered
    triggered_by UUID,                                  -- User or system
    triggered_by_type VARCHAR(20) CHECK (triggered_by_type IN ('user', 'system', 'admin')),

    -- Timing
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT fk_subscription_events_subscription FOREIGN KEY (subscription_id)
        REFERENCES public.subscriptions(subscription_id) ON DELETE CASCADE,
    CONSTRAINT fk_previous_plan FOREIGN KEY (previous_plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE SET NULL,
    CONSTRAINT fk_new_plan FOREIGN KEY (new_plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE SET NULL,
    CONSTRAINT fk_triggered_by FOREIGN KEY (triggered_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.subscription_events IS 'Audit trail of subscription state changes';
COMMENT ON COLUMN public.subscription_events.event_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.subscription_events.subscription_id IS 'Subscription reference';
COMMENT ON COLUMN public.subscription_events.event_type IS 'Type of event';
COMMENT ON COLUMN public.subscription_events.previous_status IS 'Previous status';
COMMENT ON COLUMN public.subscription_events.new_status IS 'New status';
COMMENT ON COLUMN public.subscription_events.previous_plan_id IS 'Previous plan (if changed)';
COMMENT ON COLUMN public.subscription_events.new_plan_id IS 'New plan (if changed)';
COMMENT ON COLUMN public.subscription_events.event_reason IS 'Reason for event';
COMMENT ON COLUMN public.subscription_events.event_data IS 'Additional event data';
COMMENT ON COLUMN public.subscription_events.triggered_by IS 'User who triggered (if any)';
COMMENT ON COLUMN public.subscription_events.triggered_by_type IS 'Type of trigger';
COMMENT ON COLUMN public.subscription_events.occurred_at IS 'When event occurred';

-- Indexes
CREATE INDEX idx_subscription_events_subscription_id ON public.subscription_events(subscription_id, occurred_at DESC);
CREATE INDEX idx_subscription_events_type ON public.subscription_events(event_type, occurred_at DESC);
CREATE INDEX idx_subscription_events_occurred_at ON public.subscription_events(occurred_at DESC);

-- Enable RLS
ALTER TABLE public.subscription_events ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY subscription_events_user_policy ON public.subscription_events
    USING (EXISTS (
        SELECT 1 FROM public.subscriptions s
        WHERE s.subscription_id = subscription_events.subscription_id
        AND s.user_id = current_user_id()
    ));

CREATE POLICY subscription_events_finance_policy ON public.subscription_events
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin', 'analyst')
    ));

-- ======================================================================
-- TABLE 16: usage_meters
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 16
-- Table Name: usage_meters
-- Description: Tracks consumption of metered resources for usage-based billing,
--              with real-time aggregation and alerting.
--
-- Business Case (300 words):
-- Modern SaaS products increasingly use usage-based pricing (API calls,
-- storage, active users). This table records usage events in near real-time
-- and aggregates them for billing. It supports multiple meter types
-- (incremental, absolute, gauge), real-time aggregation, usage alerts,
-- and integration with subscription billing.
--
-- The business impact is revenue optimization—usage-based pricing captures
-- value from heavy users while keeping entry prices low. Real-time tracking
-- enables usage alerts that prevent bill shock and allow users to manage
-- consumption. Historical trending supports capacity planning and product
-- decisions.
--
-- The design supports complex usage patterns: cumulative (total API calls),
-- peak (max concurrent users), rate (requests per second), and duration
-- (total minutes streamed). For enterprise, it enables custom usage metrics,
-- multi-dimensional tracking, usage-based discounts, and commitment tracking.
--
-- Integration with the billing system ensures accurate overage charges.
-- Alert thresholds notify users before they exceed plan limits, reducing
-- support inquiries and improving satisfaction. The meter can also drive
-- automated actions like throttling when limits are exceeded.
--
-- Key Performance Indicators (KPIs):
--   1. Usage per User: Average and distribution
--   2. Peak Usage Times: When systems are busiest
--   3. Overage Revenue: Percentage of revenue from overages
--   4. Forecast Accuracy: Predicted vs. actual usage
--   5. Metering Latency: Time from event to meter update (< 1 second)
--   6. Alert Effectiveness: Percentage of users who reduce usage after alert
--   7. Billing Accuracy: 100% match between usage and invoices
--
-- Feature Reference: USG-02 (Usage Metering)
-- Requirements Traceability: R-USAGE-001 through R-USAGE-025
--
-- Normalization: 3NF - Meters independent with usage events separate
--
-- High-Write Considerations:
--   - Very high write volume (every usage event updates meter)
--   - Read-heavy for usage dashboards and billing
--   - Updated frequently (every event increments counter)
--   - Indexes optimized for user_id and period lookups
-------------------------------------------------------------------------------
CREATE TABLE public.usage_meters (
    -- Primary key
    meter_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Customer
    user_id UUID NOT NULL,
    subscription_id UUID,                               -- Linked subscription
    company_id UUID,                                    -- For team/organization

    -- Meter configuration
    meter_name VARCHAR(100) NOT NULL,
    meter_type public.usage_meter_type NOT NULL,
    meter_unit VARCHAR(50),                             -- e.g., 'calls', 'GB', 'hours'

    -- Meter mode
    aggregation_method VARCHAR(20) NOT NULL CHECK (aggregation_method IN (
        'SUM', 'MAX', 'AVG', 'COUNT', 'LAST', 'RATE'
    )),
    reset_frequency VARCHAR(20) CHECK (reset_frequency IN (
        'NEVER', 'DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY', 'BILLING_CYCLE'
    )),

    -- Current billing period
    current_period_start TIMESTAMP WITH TIME ZONE NOT NULL,
    current_period_end TIMESTAMP WITH TIME ZONE NOT NULL,
    current_usage NUMERIC(15,3) DEFAULT 0 NOT NULL,

    -- Plan limits
    included_quantity NUMERIC(15,3),                    -- Included in plan
    overage_rate NUMERIC(12,4),                          -- Price per unit over limit
    overage_currency CHAR(3),

    -- Alert thresholds
    alert_thresholds INTEGER[],                           -- Percentages [50,80,90,100]
    alert_sent_at TIMESTAMP WITH TIME ZONE[],             -- When alerts were sent
    last_alert_level INTEGER,

    -- Usage tracking
    last_usage_at TIMESTAMP WITH TIME ZONE,
    peak_usage NUMERIC(15,3),                             -- Peak recorded
    peak_usage_at TIMESTAMP WITH TIME ZONE,
    average_usage_rate NUMERIC(15,3),                     -- Rolling average

    -- Metadata
    metadata JSONB,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_usage_meter UNIQUE (user_id, meter_name, current_period_start),
    CONSTRAINT chk_usage_period CHECK (current_period_end > current_period_start),
    CONSTRAINT fk_usage_meters_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_usage_meters_subscription FOREIGN KEY (subscription_id)
        REFERENCES public.subscriptions(subscription_id) ON DELETE SET NULL,
    CONSTRAINT fk_usage_meters_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.usage_meters IS 'Tracks consumption of metered resources for usage-based billing';
COMMENT ON COLUMN public.usage_meters.meter_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.usage_meters.user_id IS 'User whose usage is tracked';
COMMENT ON COLUMN public.usage_meters.subscription_id IS 'Linked subscription';
COMMENT ON COLUMN public.usage_meters.company_id IS 'Company (if team/organization)';
COMMENT ON COLUMN public.usage_meters.meter_name IS 'Name of the meter';
COMMENT ON COLUMN public.usage_meters.meter_type IS 'Type of usage being metered';
COMMENT ON COLUMN public.usage_meters.meter_unit IS 'Unit of measurement';
COMMENT ON COLUMN public.usage_meters.aggregation_method IS 'How usage is aggregated';
COMMENT ON COLUMN public.usage_meters.reset_frequency IS 'How often usage resets';
COMMENT ON COLUMN public.usage_meters.current_period_start IS 'Current period start';
COMMENT ON COLUMN public.usage_meters.current_period_end IS 'Current period end';
COMMENT ON COLUMN public.usage_meters.current_usage IS 'Usage in current period';
COMMENT ON COLUMN public.usage_meters.included_quantity IS 'Quantity included in plan';
COMMENT ON COLUMN public.usage_meters.overage_rate IS 'Price per unit over limit';
COMMENT ON COLUMN public.usage_meters.overage_currency IS 'Currency for overage';
COMMENT ON COLUMN public.usage_meters.alert_thresholds IS 'Alert at percentages';
COMMENT ON COLUMN public.usage_meters.alert_sent_at IS 'When alerts were sent';
COMMENT ON COLUMN public.usage_meters.last_alert_level IS 'Last alert level sent';
COMMENT ON COLUMN public.usage_meters.last_usage_at IS 'Last usage recorded';
COMMENT ON COLUMN public.usage_meters.peak_usage IS 'Peak usage recorded';
COMMENT ON COLUMN public.usage_meters.peak_usage_at IS 'When peak occurred';
COMMENT ON COLUMN public.usage_meters.average_usage_rate IS 'Rolling average usage';
COMMENT ON COLUMN public.usage_meters.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.usage_meters.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.usage_meters.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.usage_meters.created_by IS 'User who created the record';
COMMENT ON COLUMN public.usage_meters.updated_by IS 'User who last updated the record';

-- Indexes for usage_meters
CREATE INDEX idx_usage_meters_user_id ON public.usage_meters(user_id, meter_name);
CREATE INDEX idx_usage_meters_subscription_id ON public.usage_meters(subscription_id) WHERE subscription_id IS NOT NULL;
CREATE INDEX idx_usage_meters_period ON public.usage_meters(current_period_end) WHERE current_usage > 0;
CREATE INDEX idx_usage_meters_alert ON public.usage_meters(user_id) WHERE alert_thresholds IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_usage_meters_timestamp
    BEFORE UPDATE ON public.usage_meters
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.usage_meters ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY usage_meters_user_policy ON public.usage_meters
    USING (user_id = current_user_id());

CREATE POLICY usage_meters_finance_policy ON public.usage_meters
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- ======================================================================
-- TABLE 17: usage_events
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 17
-- Table Name: usage_events
-- Description: Raw usage events recorded in real-time for metering and analytics.
--              Stores every usage event with full context for audit, debugging,
--              and replay capabilities.
--
-- Business Case: For accurate usage-based billing, every usage event must be
--                recorded. This table stores raw events as they occur, which
--                are then aggregated into usage_meters. It supports high-volume
--                event ingestion, event deduplication, timestamp accuracy,
--                replay capabilities, and debugging.
--
-- The business impact is billing accuracy—every billable event is recorded,
-- eliminating revenue leakage. For compliance, the raw events provide audit
-- trail for disputed charges. For analytics, the data reveals usage patterns
-- that inform product decisions.
--
-- Key Performance Indicators (KPIs):
--   1. Event Volume: Events per second/minute/hour
--   2. Ingestion Latency: Time from event to database (< 100ms)
--   3. Duplicate Rate: Percentage of duplicate events (< 0.1%)
--   4. Data Retention: Storage growth rate
--   5. Query Performance: Time to analyze historical usage
--
-- Feature Reference: USG-03 (Usage Events)
-- Requirements Traceability: R-USAGE-026 through R-USAGE-035
--
-- Normalization: 3NF - Events independent with meter reference
--
-- High-Write Considerations:
--   - Extremely high write volume (millions of events daily)
--   - Partitioned by date for write scalability
--   - Unlogged table considered but rejected for billing data
--   - Batch inserts for efficiency
--   - Automatic archival of old partitions
-------------------------------------------------------------------------------
CREATE TABLE public.usage_events (
    -- Primary key (composite for partitioning)
    event_id UUID DEFAULT gen_random_uuid() NOT NULL,
    event_date DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Event identification
    user_id UUID NOT NULL,
    subscription_id UUID,
    meter_id UUID,

    -- Event details
    event_type public.usage_meter_type NOT NULL,
    event_value NUMERIC(15,3) NOT NULL,
    event_unit VARCHAR(50),

    -- Timing
    event_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    recorded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Source
    source_ip INET,
    source_endpoint VARCHAR(255),
    user_agent TEXT,

    -- Context
    session_id UUID,
    request_id UUID,
    metadata JSONB,

    -- Deduplication
    idempotency_key VARCHAR(255) UNIQUE,

    -- Partition key
    PRIMARY KEY (event_id, event_date)
) PARTITION BY RANGE (event_date);

COMMENT ON TABLE public.usage_events IS 'Raw usage events for metering and analytics';
COMMENT ON COLUMN public.usage_events.event_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.usage_events.event_date IS 'Date of event (partition key)';
COMMENT ON COLUMN public.usage_events.user_id IS 'User generating usage';
COMMENT ON COLUMN public.usage_events.subscription_id IS 'Linked subscription';
COMMENT ON COLUMN public.usage_events.meter_id IS 'Linked meter (after aggregation)';
COMMENT ON COLUMN public.usage_events.event_type IS 'Type of usage event';
COMMENT ON COLUMN public.usage_events.event_value IS 'Usage value';
COMMENT ON COLUMN public.usage_events.event_unit IS 'Unit of measurement';
COMMENT ON COLUMN public.usage_events.event_timestamp IS 'When usage occurred';
COMMENT ON COLUMN public.usage_events.recorded_at IS 'When event was recorded';
COMMENT ON COLUMN public.usage_events.source_ip IS 'Source IP address';
COMMENT ON COLUMN public.usage_events.source_endpoint IS 'API endpoint that generated usage';
COMMENT ON COLUMN public.usage_events.user_agent IS 'Client user agent';
COMMENT ON COLUMN public.usage_events.session_id IS 'Session identifier';
COMMENT ON COLUMN public.usage_events.request_id IS 'Request identifier';
COMMENT ON COLUMN public.usage_events.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.usage_events.idempotency_key IS 'Key for deduplication';

-- Create partition function for usage_events
CREATE OR REPLACE FUNCTION public.create_usage_events_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'usage_events_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    EXECUTE FORMAT('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.usage_events
        FOR VALUES FROM (%L) TO (%L)
    ', partition_name, start_date, end_date);

    -- Create indexes on partition
    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, event_timestamp DESC);
        CREATE INDEX IF NOT EXISTS %I ON public.%I(meter_id, event_timestamp DESC);
    ',
    'idx_' || partition_name || '_user', partition_name,
    'idx_' || partition_name || '_meter', partition_name
    );
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for next 7 days
SELECT public.create_usage_events_partition(CURRENT_DATE);
SELECT public.create_usage_events_partition(CURRENT_DATE + INTERVAL '1 day');
SELECT public.create_usage_events_partition(CURRENT_DATE + INTERVAL '2 days');
SELECT public.create_usage_events_partition(CURRENT_DATE + INTERVAL '3 days');
SELECT public.create_usage_events_partition(CURRENT_DATE + INTERVAL '4 days');
SELECT public.create_usage_events_partition(CURRENT_DATE + INTERVAL '5 days');
SELECT public.create_usage_events_partition(CURRENT_DATE + INTERVAL '6 days');

-- Global indexes
CREATE INDEX idx_usage_events_user_id ON public.usage_events(user_id, event_timestamp DESC);
CREATE INDEX idx_usage_events_subscription_id ON public.usage_events(subscription_id, event_timestamp DESC);
CREATE INDEX idx_usage_events_meter_id ON public.usage_events(meter_id, event_timestamp DESC);
CREATE INDEX idx_usage_events_idempotency ON public.usage_events(idempotency_key) WHERE idempotency_key IS NOT NULL;

-- Enable RLS
ALTER TABLE public.usage_events ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY usage_events_user_policy ON public.usage_events
    USING (user_id = current_user_id());

CREATE POLICY usage_events_finance_policy ON public.usage_events
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin', 'analyst')
    ));

-- ======================================================================
-- TABLE 18: credits_wallet
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 18
-- Table Name: credits_wallet
-- Description: Manages user credit/points balance with full transaction history,
--              supporting virtual currency, refunds, and promotional credits.
--
-- Business Case (300 words):
-- Modern platforms use virtual credits for multiple purposes: referral program
-- rewards, refunds (to avoid payment reversals), promotional giveaways,
-- loyalty points, cashback programs, gift cards, and microtransactions.
-- This table maintains the current balance with complete audit trail of every
-- credit movement.
--
-- The business impact is customer engagement—credits incentivize desired
-- behaviors (referrals, content creation) and increase retention through
-- loyalty programs. For finance, credits reduce payment processing costs
-- (refunds become credits rather than payment reversals). For marketing,
-- promotional credits drive acquisition at lower cost than discounts.
--
-- The design supports multiple credit types (promotional, purchased, loyalty)
-- with different behaviors—promotional credits can expire, purchased credits
-- cannot. Expiration tracking ensures liability is properly managed on the
-- balance sheet. Spending rules control what credits can be used for,
-- preventing abuse.
--
-- For compliance, the table maintains complete transaction history for audit
-- and regulatory reporting. The double-entry style ensures balance integrity
-- and simplifies reconciliation. Integration with the billing system enables
-- seamless credit purchases and application to invoices.
--
-- Key Performance Indicators (KPIs):
--   1. Average Credits per User: Balance distribution
--   2. Redemption Rate: Percentage of credits used
--   3. Expiration Rate: Percentage of credits expiring unused
--   4. Credit Source Distribution: Promotional vs. purchased
--   5. Fraud Rate: Unauthorized credit usage (< 0.01%)
--   6. Customer Satisfaction: Feedback on credit programs
--   7. Revenue Impact: Credits driving incremental purchases
--
-- Feature Reference: WAL-02 (Credit Wallet)
-- Requirements Traceability: R-CREDIT-001 through R-CREDIT-020
--
-- Normalization: 3NF - Wallet per user with separate transactions
--
-- High-Write Considerations:
--   - Moderate write volume (credits earned and spent daily)
--   - Read-heavy for balance checks (every transaction)
--   - Indexed by user_id for fast balance lookups
--   - Optimistic locking for concurrent updates
-------------------------------------------------------------------------------
CREATE TABLE public.credits_wallet (
    -- Primary key
    wallet_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Owner
    user_id UUID NOT NULL UNIQUE,                    -- One wallet per user
    company_id UUID,                                 -- For business accounts

    -- Current balance
    current_balance NUMERIC(15,4) DEFAULT 0 NOT NULL CHECK (current_balance >= 0),
    pending_balance NUMERIC(15,4) DEFAULT 0 CHECK (pending_balance >= 0),
    lifetime_credits NUMERIC(15,4) DEFAULT 0,        -- Total credits ever received
    lifetime_usage NUMERIC(15,4) DEFAULT 0,          -- Total credits ever used

    -- Balance breakdown by type
    promotional_balance NUMERIC(15,4) DEFAULT 0 CHECK (promotional_balance >= 0),
    purchased_balance NUMERIC(15,4) DEFAULT 0 CHECK (purchased_balance >= 0),
    loyalty_balance NUMERIC(15,4) DEFAULT 0 CHECK (loyalty_balance >= 0),
    refund_balance NUMERIC(15,4) DEFAULT 0 CHECK (refund_balance >= 0),

    -- Currency
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    credit_value NUMERIC(10,4) DEFAULT 1.0,          -- Value per credit in currency

    -- Controls
    is_active BOOLEAN DEFAULT true,
    locked_until TIMESTAMP WITH TIME ZONE,            -- For fraud holds
    lock_reason TEXT,

    -- Spending rules
    allowed_products TEXT[],                           -- Products credits can buy
    excluded_products TEXT[],                          -- Products credits cannot buy
    minimum_spend NUMERIC(15,4),                       -- Minimum spend to use credits
    maximum_per_transaction NUMERIC(15,4),             -- Max credits per transaction

    -- Auto-recharge (for negative balances prevention)
    auto_recharge_threshold NUMERIC(15,4),             -- Auto-recharge when below
    auto_recharge_amount NUMERIC(15,4),
    auto_recharge_payment_method_id UUID,

    -- Audit
    last_transaction_at TIMESTAMP WITH TIME ZONE,
    last_activity_at TIMESTAMP WITH TIME ZONE,

    -- Metadata
    metadata JSONB,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_wallet_balances CHECK (
        current_balance = promotional_balance + purchased_balance + loyalty_balance + refund_balance
    ),
    CONSTRAINT fk_credits_wallet_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_credits_wallet_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT fk_credits_wallet_payment_method FOREIGN KEY (auto_recharge_payment_method_id)
        REFERENCES public.payment_methods(payment_method_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.credits_wallet IS 'User credit/points wallet with balance tracking';
COMMENT ON COLUMN public.credits_wallet.wallet_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.credits_wallet.user_id IS 'Wallet owner';
COMMENT ON COLUMN public.credits_wallet.company_id IS 'Company (if business account)';
COMMENT ON COLUMN public.credits_wallet.current_balance IS 'Current available balance';
COMMENT ON COLUMN public.credits_wallet.pending_balance IS 'Pending (unconfirmed) balance';
COMMENT ON COLUMN public.credits_wallet.lifetime_credits IS 'Total credits ever received';
COMMENT ON COLUMN public.credits_wallet.lifetime_usage IS 'Total credits ever used';
COMMENT ON COLUMN public.credits_wallet.promotional_balance IS 'Promotional credits balance';
COMMENT ON COLUMN public.credits_wallet.purchased_balance IS 'Purchased credits balance';
COMMENT ON COLUMN public.credits_wallet.loyalty_balance IS 'Loyalty credits balance';
COMMENT ON COLUMN public.credits_wallet.refund_balance IS 'Refund credits balance';
COMMENT ON COLUMN public.credits_wallet.currency IS 'Currency of credits';
COMMENT ON COLUMN public.credits_wallet.credit_value IS 'Value per credit in currency';
COMMENT ON COLUMN public.credits_wallet.is_active IS 'Whether wallet is active';
COMMENT ON COLUMN public.credits_wallet.locked_until IS 'Lock for fraud holds';
COMMENT ON COLUMN public.credits_wallet.lock_reason IS 'Reason for lock';
COMMENT ON COLUMN public.credits_wallet.allowed_products IS 'Products credits can buy';
COMMENT ON COLUMN public.credits_wallet.excluded_products IS 'Products credits cannot buy';
COMMENT ON COLUMN public.credits_wallet.minimum_spend IS 'Minimum spend to use credits';
COMMENT ON COLUMN public.credits_wallet.maximum_per_transaction IS 'Max credits per transaction';
COMMENT ON COLUMN public.credits_wallet.auto_recharge_threshold IS 'Auto-recharge when below';
COMMENT ON COLUMN public.credits_wallet.auto_recharge_amount IS 'Amount to auto-recharge';
COMMENT ON COLUMN public.credits_wallet.auto_recharge_payment_method_id IS 'Payment method for auto-recharge';
COMMENT ON COLUMN public.credits_wallet.last_transaction_at IS 'Last transaction timestamp';
COMMENT ON COLUMN public.credits_wallet.last_activity_at IS 'Last activity timestamp';
COMMENT ON COLUMN public.credits_wallet.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.credits_wallet.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.credits_wallet.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.credits_wallet.created_by IS 'User who created the record';
COMMENT ON COLUMN public.credits_wallet.updated_by IS 'User who last updated the record';

-- Indexes for credits_wallet
CREATE INDEX idx_credits_wallet_user_id ON public.credits_wallet(user_id);
CREATE INDEX idx_credits_wallet_company_id ON public.credits_wallet(company_id) WHERE company_id IS NOT NULL;
CREATE INDEX idx_credits_wallet_balance ON public.credits_wallet(current_balance) WHERE current_balance > 0;
CREATE INDEX idx_credits_wallet_locked ON public.credits_wallet(locked_until) WHERE locked_until IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_credits_wallet_timestamp
    BEFORE UPDATE ON public.credits_wallet
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.credits_wallet ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY credits_wallet_user_policy ON public.credits_wallet
    USING (user_id = current_user_id());

CREATE POLICY credits_wallet_finance_policy ON public.credits_wallet
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- ======================================================================
-- TABLE 19: credit_transactions
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 19
-- Table Name: credit_transactions
-- Description: Complete audit trail of all credit movements in the wallet,
--              supporting balance verification and dispute resolution.
--
-- Business Case: Every credit movement must be tracked for audit and
--                reconciliation. This table records each transaction with
--                before/after balances for verification, transaction type
--                and reason, reference to related entities (orders, invoices),
--                expiration tracking, and reversal links.
--
-- The business impact is financial integrity—the complete audit trail ensures
-- balances can be verified and disputes resolved. For accounting, the data
-- supports revenue recognition and liability tracking. For fraud detection,
-- patterns in transactions can identify suspicious activity.
--
-- Key Performance Indicators (KPIs):
--   1. Transaction Volume: Average per user per day
--   2. Balance Verification: Percentage of wallets that balance
--   3. Dispute Rate: Percentage of transactions disputed (< 0.1%)
--   4. Reversal Rate: Percentage of transactions reversed
--   5. Expiration Impact: Credits expiring vs. used
--
-- Feature Reference: WAL-03 (Credit Transactions)
-- Requirements Traceability: R-CREDIT-021 through R-CREDIT-030
--
-- Normalization: 3NF - Transactions dependent on wallet
--
-- High-Write Considerations:
--   - High write volume (every credit movement)
--   - Indexed by wallet_id and transaction_date
--   - Partitioning by date recommended
-------------------------------------------------------------------------------
CREATE TABLE public.credit_transactions (
    -- Primary key
    transaction_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    wallet_id UUID NOT NULL,
    user_id UUID NOT NULL,                            -- Denormalized for performance

    -- Transaction identification
    transaction_type public.credit_transaction_type NOT NULL,
    transaction_reason TEXT,
    transaction_ref VARCHAR(255),                      -- External reference

    -- Amounts
    amount NUMERIC(15,4) NOT NULL,
    credit_type VARCHAR(20) NOT NULL CHECK (credit_type IN ('PROMOTIONAL', 'PURCHASED', 'LOYALTY', 'REFUND')),

    -- Balance tracking
    balance_before NUMERIC(15,4) NOT NULL,
    balance_after NUMERIC(15,4) NOT NULL,

    -- Related entities
    order_id UUID,                                     -- Related order
    invoice_id UUID,                                   -- Related invoice
    subscription_id UUID,                              -- Related subscription
    referral_id UUID,                                  -- Related referral
    reversal_of UUID,                                  -- If this is a reversal

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,               -- When credits expire
    expired_at TIMESTAMP WITH TIME ZONE,                -- When actually expired

    -- Status
    status VARCHAR(20) DEFAULT 'COMPLETED' CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')),

    -- Metadata
    metadata JSONB,

    -- Timestamps
    transaction_date TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,                                   -- System or user who initiated

    -- Constraints
    CONSTRAINT chk_credit_balance CHECK (balance_after = balance_before +
        CASE WHEN transaction_type IN ('PURCHASE', 'REFERRAL_BONUS', 'SIGNUP_BONUS', 'LOYALTY_BONUS', 'PROMOTION', 'CASHBACK', 'TRANSFER_IN', 'REFUND')
            THEN amount
            ELSE -amount
        END),
    CONSTRAINT fk_credit_transactions_wallet FOREIGN KEY (wallet_id)
        REFERENCES public.credits_wallet(wallet_id) ON DELETE CASCADE,
    CONSTRAINT fk_credit_transactions_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_credit_transactions_reversal FOREIGN KEY (reversal_of)
        REFERENCES public.credit_transactions(transaction_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.credit_transactions IS 'Audit trail of all credit wallet transactions';
COMMENT ON COLUMN public.credit_transactions.transaction_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.credit_transactions.wallet_id IS 'Wallet reference';
COMMENT ON COLUMN public.credit_transactions.user_id IS 'User (denormalized)';
COMMENT ON COLUMN public.credit_transactions.transaction_type IS 'Type of transaction';
COMMENT ON COLUMN public.credit_transactions.transaction_reason IS 'Reason for transaction';
COMMENT ON COLUMN public.credit_transactions.transaction_ref IS 'External reference';
COMMENT ON COLUMN public.credit_transactions.amount IS 'Transaction amount';
COMMENT ON COLUMN public.credit_transactions.credit_type IS 'Type of credits';
COMMENT ON COLUMN public.credit_transactions.balance_before IS 'Balance before transaction';
COMMENT ON COLUMN public.credit_transactions.balance_after IS 'Balance after transaction';
COMMENT ON COLUMN public.credit_transactions.order_id IS 'Related order';
COMMENT ON COLUMN public.credit_transactions.invoice_id IS 'Related invoice';
COMMENT ON COLUMN public.credit_transactions.subscription_id IS 'Related subscription';
COMMENT ON COLUMN public.credit_transactions.referral_id IS 'Related referral';
COMMENT ON COLUMN public.credit_transactions.reversal_of IS 'Reversed transaction';
COMMENT ON COLUMN public.credit_transactions.expires_at IS 'When credits expire';
COMMENT ON COLUMN public.credit_transactions.expired_at IS 'When credits expired';
COMMENT ON COLUMN public.credit_transactions.status IS 'Transaction status';
COMMENT ON COLUMN public.credit_transactions.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.credit_transactions.transaction_date IS 'When transaction occurred';
COMMENT ON COLUMN public.credit_transactions.created_at IS 'Record creation time';
COMMENT ON COLUMN public.credit_transactions.created_by IS 'Who initiated';

-- Indexes for credit_transactions
CREATE INDEX idx_credit_transactions_wallet_id ON public.credit_transactions(wallet_id, transaction_date DESC);
CREATE INDEX idx_credit_transactions_user_id ON public.credit_transactions(user_id, transaction_date DESC);
CREATE INDEX idx_credit_transactions_type ON public.credit_transactions(transaction_type, transaction_date);
CREATE INDEX idx_credit_transactions_reference ON public.credit_transactions(order_id) WHERE order_id IS NOT NULL;
CREATE INDEX idx_credit_transactions_invoice ON public.credit_transactions(invoice_id) WHERE invoice_id IS NOT NULL;
CREATE INDEX idx_credit_transactions_expiry ON public.credit_transactions(expires_at) WHERE expires_at IS NOT NULL;

-- Trigger to update wallet last_transaction_at
CREATE OR REPLACE FUNCTION public.update_wallet_activity()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE public.credits_wallet
    SET last_transaction_at = NEW.transaction_date,
        last_activity_at = CURRENT_TIMESTAMP
    WHERE wallet_id = NEW.wallet_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_wallet_on_transaction
    AFTER INSERT ON public.credit_transactions
    FOR EACH ROW EXECUTE FUNCTION public.update_wallet_activity();

-- Enable RLS
ALTER TABLE public.credit_transactions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY credit_transactions_user_policy ON public.credit_transactions
    USING (user_id = current_user_id());

CREATE POLICY credit_transactions_finance_policy ON public.credit_transactions
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- ======================================================================
-- TABLE 20: coupons
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 20
-- Table Name: coupons
-- Description: Manages discount coupons and promotional codes with flexible
--              rules for marketing campaigns. Supports multiple discount types,
--              usage limits, customer eligibility, and time-based restrictions.
--
-- Business Case (300 words):
-- Marketing campaigns require flexible discount mechanisms to acquire and
-- retain customers. This table stores coupon configurations with support for
-- multiple discount types (percentage, fixed amount), single-use or multi-use
-- codes, first-time customer restrictions, minimum purchase requirements,
-- product/category restrictions, and time-limited campaigns.
--
-- The business impact is customer acquisition—coupons drive new signups and
-- conversions. For retention, targeted coupons reduce churn. For analytics,
-- tracking redemption rates by campaign enables ROI calculation and budget
-- optimization. Stacking rules prevent abuse while allowing legitimate
-- combinations.
--
-- The design supports sophisticated marketing: first-time customer coupons
-- for acquisition, reactivation coupons for dormant users, referral coupons
-- for word-of-mouth growth, and seasonal promotions. Usage limits prevent
-- excessive discounting and fraud. Geographic restrictions ensure compliance
-- with local regulations.
--
-- For enterprise, the table supports custom coupons for specific accounts,
-- negotiated volume discounts, and contract-based promotions. Integration
-- with the subscription system enables free trial extensions and upgrade
-- discounts.
--
-- Key Performance Indicators (KPIs):
--   1. Redemption Rate: Percentage of coupons used by campaign
--   2. Average Order Value: With vs. without coupon
--   3. Customer Retention: Long-term value of coupon users
--   4. Fraud Rate: Unauthorized coupon usage (< 0.1%)
--   5. Campaign ROI: Revenue generated vs. discount cost
--   6. First-time Customer Rate: Acquisition via coupons
--   7. Time to Redemption: How quickly coupons are used
--
-- Feature Reference: CUP-03 (Coupon Management)
-- Requirements Traceability: R-COUPON-001 through R-COUPON-025
--
-- Normalization: 3NF - Coupons independent with usage tracking separate
--
-- High-Write Considerations:
--   - Read-heavy (every checkout checks coupons)
--   - Write-light (coupons created in batches)
--   - Partial indexes for active coupons
--   - Caching of frequently used coupons
-------------------------------------------------------------------------------
CREATE TABLE public.coupons (
    -- Primary key
    coupon_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Coupon identification
    coupon_code VARCHAR(100) NOT NULL UNIQUE,
    coupon_name VARCHAR(255) NOT NULL,
    coupon_description TEXT,

    -- Campaign
    campaign_id UUID,                                   -- Marketing campaign
    campaign_name VARCHAR(255),

    -- Discount configuration
    coupon_type public.coupon_type NOT NULL,
    discount_value NUMERIC(12,4) NOT NULL,              -- Percentage or fixed amount
    discount_currency CHAR(3),                          -- For fixed amount
    minimum_order_amount NUMERIC(12,2),                  -- Minimum purchase
    maximum_discount NUMERIC(12,2),                      -- Max discount amount

    -- Duration and usage
    duration public.coupon_duration NOT NULL DEFAULT 'ONCE',
    duration_in_months INTEGER,                          -- For REPEATING duration
    max_uses INTEGER,                                    -- Total uses across all customers
    max_uses_per_customer INTEGER,                       -- Uses per customer
    max_uses_per_order INTEGER DEFAULT 1,

    -- Eligibility
    first_time_customers_only BOOLEAN DEFAULT false,
    existing_customers_only BOOLEAN DEFAULT false,
    minimum_account_age_days INTEGER,                    -- Min days since signup
    maximum_account_age_days INTEGER,                    -- Max days since signup

    -- Product restrictions
    applicable_products TEXT[],                           -- Product IDs or categories
    applicable_categories TEXT[],
    excluded_products TEXT[],
    excluded_categories TEXT[],

    -- Customer restrictions
    applicable_customer_segments TEXT[],                 -- Customer segments
    applicable_customer_tags TEXT[],                     -- Customer tags
    excluded_customers UUID[],                           -- Specific customers excluded

    -- Geographic restrictions
    applicable_countries CHAR(3)[],                      -- Countries where valid
    excluded_countries CHAR(3)[],                        -- Countries where invalid
    applicable_postal_codes TEXT[],                      -- Specific postal codes

    -- Time restrictions
    valid_from TIMESTAMP WITH TIME ZONE NOT NULL,
    valid_until TIMESTAMP WITH TIME ZONE,
    active_days_of_week INTEGER[],                       -- 0=Sunday, 6=Saturday
    active_hours_start TIME WITHOUT TIME ZONE,           -- Start time each day
    active_hours_end TIME WITHOUT TIME ZONE,             -- End time each day

    -- Stacking rules
    stackable_with_other_coupons BOOLEAN DEFAULT false,
    stackable_with_sales BOOLEAN DEFAULT true,
    stackable_with_referrals BOOLEAN DEFAULT true,
    stack_priority INTEGER DEFAULT 0,                    -- Higher = applied first

    -- Referral tracking
    is_referral_coupon BOOLEAN DEFAULT false,
    referring_user_id UUID,                              -- User who generated (for referral)

    -- Status
    is_active BOOLEAN DEFAULT true NOT NULL,
    is_public BOOLEAN DEFAULT true,                      -- Visible to all users
    status_reason TEXT,                                   -- Why deactivated if not active

    -- Usage tracking
    times_used INTEGER DEFAULT 0 NOT NULL,
    first_used_at TIMESTAMP WITH TIME ZONE,
    last_used_at TIMESTAMP WITH TIME ZONE,
    total_discount_given NUMERIC(15,2) DEFAULT 0,

    -- Metadata
    metadata JSONB,
    tags TEXT[],

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_coupon_dates CHECK (valid_until IS NULL OR valid_until > valid_from),
    CONSTRAINT chk_coupon_duration CHECK (
        (duration = 'REPEATING' AND duration_in_months IS NOT NULL) OR
        (duration != 'REPEATING' OR duration_in_months IS NULL)
    ),
    CONSTRAINT chk_coupon_hours CHECK (
        (active_hours_start IS NULL AND active_hours_end IS NULL) OR
        (active_hours_start IS NOT NULL AND active_hours_end IS NOT NULL AND active_hours_start < active_hours_end)
    ),
    CONSTRAINT fk_coupons_campaign FOREIGN KEY (campaign_id)
        REFERENCES public.campaigns(campaign_id) ON DELETE SET NULL,
    CONSTRAINT fk_coupons_referring_user FOREIGN KEY (referring_user_id)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.coupons IS 'Discount coupons and promotional codes with flexible eligibility rules';
COMMENT ON COLUMN public.coupons.coupon_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.coupons.coupon_code IS 'Unique coupon code for redemption';
COMMENT ON COLUMN public.coupons.coupon_name IS 'Display name for the coupon';
COMMENT ON COLUMN public.coupons.coupon_description IS 'Detailed description of coupon terms';
COMMENT ON COLUMN public.coupons.campaign_id IS 'Associated marketing campaign';
COMMENT ON COLUMN public.coupons.campaign_name IS 'Campaign name (denormalized)';
COMMENT ON COLUMN public.coupons.coupon_type IS 'Type of discount';
COMMENT ON COLUMN public.coupons.discount_value IS 'Discount amount or percentage';
COMMENT ON COLUMN public.coupons.discount_currency IS 'Currency for fixed amount discounts';
COMMENT ON COLUMN public.coupons.minimum_order_amount IS 'Minimum purchase required';
COMMENT ON COLUMN public.coupons.maximum_discount IS 'Maximum discount amount';
COMMENT ON COLUMN public.coupons.duration IS 'How long coupon applies after first use';
COMMENT ON COLUMN public.coupons.duration_in_months IS 'Months for REPEATING duration';
COMMENT ON COLUMN public.coupons.max_uses IS 'Total uses allowed';
COMMENT ON COLUMN public.coupons.max_uses_per_customer IS 'Uses per customer';
COMMENT ON COLUMN public.coupons.max_uses_per_order IS 'Uses per order';
COMMENT ON COLUMN public.coupons.first_time_customers_only IS 'Only for new customers';
COMMENT ON COLUMN public.coupons.existing_customers_only IS 'Only for existing customers';
COMMENT ON COLUMN public.coupons.minimum_account_age_days IS 'Minimum days since signup';
COMMENT ON COLUMN public.coupons.maximum_account_age_days IS 'Maximum days since signup';
COMMENT ON COLUMN public.coupons.applicable_products IS 'Products coupon applies to';
COMMENT ON COLUMN public.coupons.applicable_categories IS 'Categories coupon applies to';
COMMENT ON COLUMN public.coupons.excluded_products IS 'Products excluded';
COMMENT ON COLUMN public.coupons.excluded_categories IS 'Categories excluded';
COMMENT ON COLUMN public.coupons.applicable_customer_segments IS 'Customer segments eligible';
COMMENT ON COLUMN public.coupons.applicable_customer_tags IS 'Customer tags eligible';
COMMENT ON COLUMN public.coupons.excluded_customers IS 'Specific customers excluded';
COMMENT ON COLUMN public.coupons.applicable_countries IS 'Countries where valid';
COMMENT ON COLUMN public.coupons.excluded_countries IS 'Countries where invalid';
COMMENT ON COLUMN public.coupons.applicable_postal_codes IS 'Specific postal codes';
COMMENT ON COLUMN public.coupons.valid_from IS 'When coupon becomes valid';
COMMENT ON COLUMN public.coupons.valid_until IS 'When coupon expires';
COMMENT ON COLUMN public.coupons.active_days_of_week IS 'Days of week active';
COMMENT ON COLUMN public.coupons.active_hours_start IS 'Start time each day';
COMMENT ON COLUMN public.coupons.active_hours_end IS 'End time each day';
COMMENT ON COLUMN public.coupons.stackable_with_other_coupons IS 'Can combine with other coupons';
COMMENT ON COLUMN public.coupons.stackable_with_sales IS 'Can combine with sales';
COMMENT ON COLUMN public.coupons.stackable_with_referrals IS 'Can combine with referrals';
COMMENT ON COLUMN public.coupons.stack_priority IS 'Priority when stacking';
COMMENT ON COLUMN public.coupons.is_referral_coupon IS 'Whether this is a referral coupon';
COMMENT ON COLUMN public.coupons.referring_user_id IS 'User who generated (for referral)';
COMMENT ON COLUMN public.coupons.is_active IS 'Whether coupon is active';
COMMENT ON COLUMN public.coupons.is_public IS 'Whether publicly visible';
COMMENT ON COLUMN public.coupons.status_reason IS 'Reason if inactive';
COMMENT ON COLUMN public.coupons.times_used IS 'Number of times used';
COMMENT ON COLUMN public.coupons.first_used_at IS 'First use timestamp';
COMMENT ON COLUMN public.coupons.last_used_at IS 'Most recent use';
COMMENT ON COLUMN public.coupons.total_discount_given IS 'Total discount amount provided';
COMMENT ON COLUMN public.coupons.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.coupons.tags IS 'Tags for categorization';
COMMENT ON COLUMN public.coupons.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.coupons.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.coupons.created_by IS 'User who created the record';
COMMENT ON COLUMN public.coupons.updated_by IS 'User who last updated the record';

-- Indexes for coupons
CREATE INDEX idx_coupons_code ON public.coupons(coupon_code) WHERE is_active = true;
CREATE INDEX idx_coupons_campaign_id ON public.coupons(campaign_id) WHERE campaign_id IS NOT NULL;
CREATE INDEX idx_coupons_valid_period ON public.coupons(valid_from, valid_until) WHERE is_active = true;
CREATE INDEX idx_coupons_type ON public.coupons(coupon_type);
CREATE INDEX idx_coupons_referring_user ON public.coupons(referring_user_id) WHERE is_referral_coupon = true;
CREATE INDEX idx_coupons_usage ON public.coupons(times_used) WHERE times_used > 0;

-- Partial index for active coupons
CREATE INDEX idx_coupons_active ON public.coupons(coupon_id)
    WHERE is_active = true AND valid_from <= CURRENT_TIMESTAMP AND (valid_until IS NULL OR valid_until >= CURRENT_TIMESTAMP);

-- GiST index for array columns
CREATE INDEX idx_coupons_applicable_products ON public.coupons USING gin(applicable_products);
CREATE INDEX idx_coupons_excluded_products ON public.coupons USING gin(excluded_products);
CREATE INDEX idx_coupons_applicable_countries ON public.coupons USING gin(applicable_countries);

-- Trigger for updated_at
CREATE TRIGGER update_coupons_timestamp
    BEFORE UPDATE ON public.coupons
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY coupons_marketing_policy ON public.coupons
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('marketing_admin', 'admin')
    ));

CREATE POLICY coupons_read_policy ON public.coupons
    FOR SELECT USING (is_active = true AND is_public = true);

-- ======================================================================
-- TABLE 21: coupon_redemptions
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 21
-- Table Name: coupon_redemptions
-- Description: Tracks each instance of coupon usage by customers for audit
--              and analytics. Records who used which coupon when, and on what order.
--
-- Business Case: Understanding coupon effectiveness requires tracking every
--                redemption. This table records each usage with order context,
--                enabling campaign ROI analysis, fraud detection, and customer
--                behavior analysis.
--
-- The business impact is marketing optimization—knowing which coupons drive
-- the most revenue enables budget allocation to high-performing campaigns.
-- Fraud detection identifies suspicious patterns like multiple redemptions
-- from the same IP. Customer behavior analysis reveals which segments
-- respond best to which offers.
--
-- Key Performance Indicators (KPIs):
--   1. Redemption Rate: By coupon and campaign
--   2. Average Order Value: With coupon applied
--   3. Fraud Detection: Suspicious patterns identified
--   4. Time to Redemption: How quickly coupons are used
--   5. Repeat Usage: Customers using multiple coupons
--
-- Feature Reference: CUP-04 (Redemption Tracking)
-- Requirements Traceability: R-COUPON-026 through R-COUPON-030
--
-- Normalization: 3NF - Redemptions dependent on coupons and users
--
-- High-Write Considerations:
--   - High write volume during promotions
--   - Indexed by coupon_id and user_id for analytics
--   - Partitioning by redemption_date recommended
-------------------------------------------------------------------------------
CREATE TABLE public.coupon_redemptions (
    -- Primary key
    redemption_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    coupon_id UUID NOT NULL,
    user_id UUID NOT NULL,
    order_id UUID,                                       -- Order where applied
    invoice_id UUID,                                     -- Generated invoice

    -- Discount details
    discount_amount NUMERIC(12,2) NOT NULL,
    currency CHAR(3) NOT NULL,

    -- Order context
    order_amount NUMERIC(12,2) NOT NULL,                 -- Original order amount
    final_amount NUMERIC(12,2) NOT NULL,                 -- Amount after discount

    -- Metadata
    redemption_date TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    ip_address INET,
    user_agent TEXT,
    metadata JSONB,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT fk_coupon_redemptions_coupon FOREIGN KEY (coupon_id)
        REFERENCES public.coupons(coupon_id) ON DELETE CASCADE,
    CONSTRAINT fk_coupon_redemptions_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_coupon_redemptions_order FOREIGN KEY (order_id)
        REFERENCES public.orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_coupon_redemptions_invoice FOREIGN KEY (invoice_id)
        REFERENCES public.invoices(invoice_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.coupon_redemptions IS 'Tracks each coupon usage by customers';

-- Indexes
CREATE INDEX idx_coupon_redemptions_coupon_id ON public.coupon_redemptions(coupon_id, redemption_date DESC);
CREATE INDEX idx_coupon_redemptions_user_id ON public.coupon_redemptions(user_id, redemption_date DESC);
CREATE INDEX idx_coupon_redemptions_order_id ON public.coupon_redemptions(order_id) WHERE order_id IS NOT NULL;
CREATE INDEX idx_coupon_redemptions_date ON public.coupon_redemptions(redemption_date DESC);

-- Trigger to update coupon usage stats
CREATE OR REPLACE FUNCTION public.update_coupon_usage_stats()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE public.coupons
    SET times_used = times_used + 1,
        last_used_at = NEW.redemption_date,
        total_discount_given = total_discount_given + NEW.discount_amount,
        first_used_at = COALESCE(first_used_at, NEW.redemption_date)
    WHERE coupon_id = NEW.coupon_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_coupon_on_redemption
    AFTER INSERT ON public.coupon_redemptions
    FOR EACH ROW EXECUTE FUNCTION public.update_coupon_usage_stats();

-- Enable RLS
ALTER TABLE public.coupon_redemptions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY coupon_redemptions_user_policy ON public.coupon_redemptions
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY coupon_redemptions_marketing_policy ON public.coupon_redemptions
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('marketing_admin', 'admin', 'analyst')
    ));

-- ======================================================================
-- TABLE 22: affiliate_partners
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 22
-- Table Name: affiliate_partners
-- Description: Manages affiliate marketing partners who promote the platform
--              in exchange for commissions on referred sales. Includes partner
--              registration, commission structures, and payout tracking.
--
-- Business Case (300 words):
-- Affiliate marketing is a powerful customer acquisition channel. This table
-- manages the partner program with partner registration and approval workflow,
-- commission structures (percentage, fixed, tiered), cookie tracking for
-- attribution, payout schedules and thresholds, marketing materials access,
-- performance tracking, and fraud detection.
--
-- The business impact is scalable customer acquisition—affiliates drive
-- growth with performance-based costs. Partners are only paid when they
-- deliver results, making it a low-risk channel. Top-performing affiliates
-- can be incentivized with higher commissions, increasing their promotional
-- efforts.
--
-- The design supports complex commission models: percentage of sale for
-- standard affiliates, fixed amounts for specific products, tiered rates
-- based on volume, and recurring commissions for subscription referrals.
-- Cookie tracking ensures proper attribution even if the customer doesn't
-- convert immediately.
--
-- For compliance, the table tracks tax information (W-9, W-8BEN) and partner
-- agreements. Fraud detection flags suspicious activity like self-referrals
-- or bot traffic. Payment thresholds ensure cost-effective payouts.
--
-- Key Performance Indicators (KPIs):
--   1. Active Partners: Number promoting the platform
--   2. Revenue from Affiliates: Total and percentage of revenue
--   3. Average Commission Rate: By partner tier
--   4. Partner Acquisition Cost: Cost to recruit new partners
--   5. Partner Retention Rate: Percentage staying active
--   6. Top Partner Concentration: 80/20 rule analysis
--   7. Fraud Rate: Invalid referrals detected (< 1%)
--
-- Feature Reference: AFF-03 (Affiliate Program)
-- Requirements Traceability: R-AFF-001 through R-AFF-025
--
-- Normalization: 3NF - Partners independent with separate referrals
--
-- High-Write Considerations:
--   - Moderate write volume (partner updates, performance tracking)
--   - Read-heavy for commission calculations
--   - Indexed by status and performance metrics
-------------------------------------------------------------------------------
CREATE TABLE public.affiliate_partners (
    -- Primary key
    partner_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Partner identification
    partner_user_id UUID NOT NULL UNIQUE,               -- User account of partner
    company_id UUID,                                    -- If partner is a company
    partner_type VARCHAR(50) NOT NULL CHECK (partner_type IN (
        'INDIVIDUAL', 'BLOG', 'INFLUENCER', 'REVIEW_SITE', 'STRATEGIC_PARTNER', 'RESELLER', 'AGENCY'
    )),

    -- Contact information
    business_name VARCHAR(255),
    contact_name VARCHAR(255) NOT NULL,
    contact_email VARCHAR(255) NOT NULL,
    contact_phone VARCHAR(50),
    website_url VARCHAR(255),
    social_media_handles JSONB,                          -- Social media accounts

    -- Tax information
    tax_id VARCHAR(50),                                  -- EIN or SSN
    tax_id_type VARCHAR(20) CHECK (tax_id_type IN ('EIN', 'SSN', 'VAT', 'OTHER')),
    tax_country CHAR(2),
    w9_received BOOLEAN DEFAULT false,
    w9_verified_at TIMESTAMP WITH TIME ZONE,
    w9_url TEXT,                                         -- Stored W-9 document

    -- Payment information
    payment_method public.payment_method_type,
    payment_details JSONB,                               -- Bank account/PayPal details (encrypted)
    payment_currency CHAR(3) DEFAULT 'USD',
    payment_threshold NUMERIC(12,2) DEFAULT 50.00,      -- Minimum for payout
    payment_frequency VARCHAR(20) DEFAULT 'MONTHLY' CHECK (payment_frequency IN ('WEEKLY', 'BIWEEKLY', 'MONTHLY', 'QUARTERLY')),

    -- Commission structure
    commission_type public.commission_type NOT NULL,
    commission_rate NUMERIC(5,2) NOT NULL,               -- Percentage or fixed amount
    commission_tiers JSONB,                              -- Tiered commission structure

    -- Cookie tracking
    cookie_days INTEGER DEFAULT 30,                       -- Attribution window
    default_tracking_code TEXT,                           -- Default tracking code

    -- Marketing materials
    marketing_materials_access BOOLEAN DEFAULT false,
    custom_landing_page VARCHAR(255),                    -- Custom landing page URL

    -- Performance metrics
    referral_count INTEGER DEFAULT 0,
    conversion_count INTEGER DEFAULT 0,
    conversion_rate NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN referral_count > 0
        THEN (conversion_count::NUMERIC / referral_count::NUMERIC) * 100
        ELSE 0 END
    ) STORED,
    total_sales NUMERIC(15,2) DEFAULT 0,
    total_commission NUMERIC(15,2) DEFAULT 0,
    paid_commission NUMERIC(15,2) DEFAULT 0,
    pending_commission NUMERIC(15,2) DEFAULT 0,

    -- Status
    status public.affiliate_status NOT NULL DEFAULT 'PENDING_APPROVAL',
    status_reason TEXT,
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,

    -- Dates
    joined_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_activity_at TIMESTAMP WITH TIME ZONE,

    -- Agreement
    agreement_accepted_at TIMESTAMP WITH TIME ZONE,
    agreement_version VARCHAR(50),
    agreement_ip INET,

    -- Fraud detection
    fraud_score INTEGER CHECK (fraud_score BETWEEN 0 AND 100),
    fraud_flags TEXT[],                                  -- Suspicious activities
    last_fraud_check TIMESTAMP WITH TIME ZONE,

    -- Metadata
    metadata JSONB,
    tags TEXT[],

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_affiliate_commission CHECK (commission_rate >= 0),
    CONSTRAINT fk_affiliate_partners_user FOREIGN KEY (partner_user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_affiliate_partners_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT fk_affiliate_partners_approved_by FOREIGN KEY (approved_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.affiliate_partners IS 'Manages affiliate marketing partners and their commission structures';
COMMENT ON COLUMN public.affiliate_partners.partner_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.affiliate_partners.partner_user_id IS 'User account of partner';
COMMENT ON COLUMN public.affiliate_partners.company_id IS 'Company (if partner is a business)';
COMMENT ON COLUMN public.affiliate_partners.partner_type IS 'Type of partner';
COMMENT ON COLUMN public.affiliate_partners.business_name IS 'Business name if applicable';
COMMENT ON COLUMN public.affiliate_partners.contact_name IS 'Primary contact name';
COMMENT ON COLUMN public.affiliate_partners.contact_email IS 'Contact email';
COMMENT ON COLUMN public.affiliate_partners.contact_phone IS 'Contact phone';
COMMENT ON COLUMN public.affiliate_partners.website_url IS 'Partner website';
COMMENT ON COLUMN public.affiliate_partners.social_media_handles IS 'Social media accounts';
COMMENT ON COLUMN public.affiliate_partners.tax_id IS 'Tax ID for reporting';
COMMENT ON COLUMN public.affiliate_partners.tax_id_type IS 'Type of tax ID';
COMMENT ON COLUMN public.affiliate_partners.tax_country IS 'Country for tax purposes';
COMMENT ON COLUMN public.affiliate_partners.w9_received IS 'Whether W-9/W-8BEN received';
COMMENT ON COLUMN public.affiliate_partners.w9_verified_at IS 'When tax form was verified';
COMMENT ON COLUMN public.affiliate_partners.w9_url IS 'URL to stored tax document';
COMMENT ON COLUMN public.affiliate_partners.payment_method IS 'Payment method for commissions';
COMMENT ON COLUMN public.affiliate_partners.payment_details IS 'Payment details (encrypted)';
COMMENT ON COLUMN public.affiliate_partners.payment_currency IS 'Currency for payments';
COMMENT ON COLUMN public.affiliate_partners.payment_threshold IS 'Minimum for payout';
COMMENT ON COLUMN public.affiliate_partners.payment_frequency IS 'How often to pay';
COMMENT ON COLUMN public.affiliate_partners.commission_type IS 'Type of commission';
COMMENT ON COLUMN public.affiliate_partners.commission_rate IS 'Base commission rate';
COMMENT ON COLUMN public.affiliate_partners.commission_tiers IS 'Tiered commission structure';
COMMENT ON COLUMN public.affiliate_partners.cookie_days IS 'Attribution window in days';
COMMENT ON COLUMN public.affiliate_partners.default_tracking_code IS 'Default tracking code';
COMMENT ON COLUMN public.affiliate_partners.marketing_materials_access IS 'Access to marketing materials';
COMMENT ON COLUMN public.affiliate_partners.custom_landing_page IS 'Custom landing page URL';
COMMENT ON COLUMN public.affiliate_partners.referral_count IS 'Total referrals';
COMMENT ON COLUMN public.affiliate_partners.conversion_count IS 'Converted referrals';
COMMENT ON COLUMN public.affiliate_partners.conversion_rate IS 'Conversion rate percentage';
COMMENT ON COLUMN public.affiliate_partners.total_sales IS 'Total sales generated';
COMMENT ON COLUMN public.affiliate_partners.total_commission IS 'Total commission earned';
COMMENT ON COLUMN public.affiliate_partners.paid_commission IS 'Commission already paid';
COMMENT ON COLUMN public.affiliate_partners.pending_commission IS 'Commission pending payment';
COMMENT ON COLUMN public.affiliate_partners.status IS 'Partner status';
COMMENT ON COLUMN public.affiliate_partners.status_reason IS 'Reason for status';
COMMENT ON COLUMN public.affiliate_partners.approved_at IS 'When partner was approved';
COMMENT ON COLUMN public.affiliate_partners.approved_by IS 'Who approved partner';
COMMENT ON COLUMN public.affiliate_partners.joined_at IS 'When partner joined';
COMMENT ON COLUMN public.affiliate_partners.last_activity_at IS 'Last activity timestamp';
COMMENT ON COLUMN public.affiliate_partners.agreement_accepted_at IS 'When agreement accepted';
COMMENT ON COLUMN public.affiliate_partners.agreement_version IS 'Agreement version';
COMMENT ON COLUMN public.affiliate_partners.agreement_ip IS 'IP address of acceptance';
COMMENT ON COLUMN public.affiliate_partners.fraud_score IS 'Fraud risk score (0-100)';
COMMENT ON COLUMN public.affiliate_partners.fraud_flags IS 'Fraud flags raised';
COMMENT ON COLUMN public.affiliate_partners.last_fraud_check IS 'Last fraud assessment';
COMMENT ON COLUMN public.affiliate_partners.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.affiliate_partners.tags IS 'Tags for categorization';
COMMENT ON COLUMN public.affiliate_partners.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.affiliate_partners.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.affiliate_partners.created_by IS 'User who created the record';
COMMENT ON COLUMN public.affiliate_partners.updated_by IS 'User who last updated the record';

-- Indexes for affiliate_partners
CREATE INDEX idx_affiliate_partners_user_id ON public.affiliate_partners(partner_user_id);
CREATE INDEX idx_affiliate_partners_status ON public.affiliate_partners(status, joined_at);
CREATE INDEX idx_affiliate_partners_type ON public.affiliate_partners(partner_type);
CREATE INDEX idx_affiliate_partners_fraud ON public.affiliate_partners(fraud_score) WHERE fraud_score > 70;
CREATE INDEX idx_affiliate_partners_payment ON public.affiliate_partners(pending_commission) WHERE pending_commission >= payment_threshold;

-- Partial index for active partners
CREATE INDEX idx_affiliate_partners_active ON public.affiliate_partners(partner_id)
    WHERE status = 'ACTIVE';

-- Trigger for updated_at
CREATE TRIGGER update_affiliate_partners_timestamp
    BEFORE UPDATE ON public.affiliate_partners
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.affiliate_partners ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY affiliate_partners_self_policy ON public.affiliate_partners
    USING (partner_user_id = current_user_id());

CREATE POLICY affiliate_partners_marketing_policy ON public.affiliate_partners
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('affiliate_manager', 'admin')
    ));

-- ======================================================================
-- TABLE 23: affiliate_referrals
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 23
-- Table Name: affiliate_referrals
-- Description: Tracks individual referrals from affiliate partners, including
--              attribution, conversion status, and commission calculations.
--
-- Business Case: Accurate tracking of each referral is essential for paying
--                commissions correctly and analyzing program performance.
--                This table records referral source (link, cookie, promo code),
--                referred customer and their actions, conversion status,
--                commission amounts, and fraud detection data.
--
-- The business impact is trust—partners need confidence that they'll be paid
-- correctly for their referrals. Accurate tracking ensures partners remain
-- engaged and continue promoting the platform. Fraud detection protects the
-- business from invalid commissions.
--
-- Key Performance Indicators (KPIs):
--   1. Referral Volume: By partner and time period
--   2. Conversion Rate: Percentage becoming customers
--   3. Commission Cost: Percentage of revenue
--   4. Fraud Rate: Invalid referrals detected
--   5. Time to Conversion: How long to convert
--
-- Feature Reference: AFF-04 (Referral Tracking)
-- Requirements Traceability: R-AFF-026 through R-AFF-035
--
-- Normalization: 3NF - Referrals dependent on partners
--
-- High-Write Considerations:
--   - High write volume (every click tracked)
--   - Partitioning by clicked_at recommended
--   - Indexed for partner lookups and conversion tracking
-------------------------------------------------------------------------------
CREATE TABLE public.affiliate_referrals (
    -- Primary key
    referral_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Partner
    partner_id UUID NOT NULL,
    tracking_code VARCHAR(100),                          -- Specific tracking code used

    -- Referred user
    referred_user_id UUID,                               -- User who was referred
    referred_email VARCHAR(255),                         -- Email before signup
    referred_ip INET,                                    -- IP at time of referral

    -- Referral source
    referrer_url TEXT,                                   -- URL where click occurred
    landing_url TEXT,                                    -- Landing page URL
    utm_source VARCHAR(255),                             -- UTM parameters
    utm_medium VARCHAR(255),
    utm_campaign VARCHAR(255),
    utm_term VARCHAR(255),
    utm_content VARCHAR(255),

    -- Attribution
    cookie_id VARCHAR(255),                              -- Browser cookie ID
    click_id VARCHAR(255),                               -- Click ID from network
    clicked_at TIMESTAMP WITH TIME ZONE NOT NULL,
    attributed_at TIMESTAMP WITH TIME ZONE,              -- When attributed to partner

    -- Conversion tracking
    conversion_type VARCHAR(50) CHECK (conversion_type IN ('CLICK', 'SIGNUP', 'PURCHASE', 'SUBSCRIBE')),
    converted_at TIMESTAMP WITH TIME ZONE,
    order_id UUID,                                       -- Order if purchase
    subscription_id UUID,                                -- Subscription if applicable
    conversion_value NUMERIC(12,2),                      -- Value of conversion

    -- Commission
    commission_rate NUMERIC(5,2),                        -- Rate at time of conversion
    commission_amount NUMERIC(12,2),                     -- Calculated commission
    commission_currency CHAR(3),
    commission_paid BOOLEAN DEFAULT false,
    commission_paid_at TIMESTAMP WITH TIME ZONE,
    commission_payout_id UUID,                           -- Link to payout

    -- Fraud detection
    fraud_score INTEGER CHECK (fraud_score BETWEEN 0 AND 100),
    fraud_reason TEXT,
    is_valid BOOLEAN DEFAULT true,                       -- Whether referral is valid
    validation_notes TEXT,

    -- Metadata
    metadata JSONB,

    -- Timestamps
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT fk_affiliate_referrals_partner FOREIGN KEY (partner_id)
        REFERENCES public.affiliate_partners(partner_id) ON DELETE CASCADE,
    CONSTRAINT fk_affiliate_referrals_user FOREIGN KEY (referred_user_id)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_affiliate_referrals_order FOREIGN KEY (order_id)
        REFERENCES public.orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_affiliate_referrals_subscription FOREIGN KEY (subscription_id)
        REFERENCES public.subscriptions(subscription_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.affiliate_referrals IS 'Tracks individual referrals from affiliate partners';

-- Indexes
CREATE INDEX idx_affiliate_referrals_partner_id ON public.affiliate_referrals(partner_id, clicked_at DESC);
CREATE INDEX idx_affiliate_referrals_user_id ON public.affiliate_referrals(referred_user_id) WHERE referred_user_id IS NOT NULL;
CREATE INDEX idx_affiliate_referrals_tracking ON public.affiliate_referrals(tracking_code) WHERE tracking_code IS NOT NULL;
CREATE INDEX idx_affiliate_referrals_converted ON public.affiliate_referrals(converted_at) WHERE converted_at IS NOT NULL;
CREATE INDEX idx_affiliate_referrals_fraud ON public.affiliate_referrals(fraud_score) WHERE fraud_score > 70;
CREATE INDEX idx_affiliate_referrals_paid ON public.affiliate_referrals(commission_paid) WHERE commission_paid = false;

-- Trigger for updated_at
CREATE TRIGGER update_affiliate_referrals_timestamp
    BEFORE UPDATE ON public.affiliate_referrals
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update partner metrics
CREATE OR REPLACE FUNCTION public.update_partner_metrics()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.affiliate_partners
        SET referral_count = referral_count + 1,
            last_activity_at = CURRENT_TIMESTAMP
        WHERE partner_id = NEW.partner_id;
    ELSIF TG_OP = 'UPDATE' AND NEW.converted_at IS NOT NULL AND OLD.converted_at IS NULL THEN
        UPDATE public.affiliate_partners
        SET conversion_count = conversion_count + 1,
            total_sales = total_sales + COALESCE(NEW.conversion_value, 0),
            total_commission = total_commission + COALESCE(NEW.commission_amount, 0),
            pending_commission = pending_commission + COALESCE(NEW.commission_amount, 0)
        WHERE partner_id = NEW.partner_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_partner_on_referral
    AFTER INSERT OR UPDATE ON public.affiliate_referrals
    FOR EACH ROW EXECUTE FUNCTION public.update_partner_metrics();

-- Enable RLS
ALTER TABLE public.affiliate_referrals ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY affiliate_referrals_partner_policy ON public.affiliate_referrals
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.affiliate_partners ap
        WHERE ap.partner_id = affiliate_referrals.partner_id
        AND ap.partner_user_id = current_user_id()
    ));

CREATE POLICY affiliate_referrals_marketing_policy ON public.affiliate_referrals
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('affiliate_manager', 'admin', 'analyst')
    ));

-- ======================================================================
-- TABLE 24: affiliate_payouts
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 24
-- Table Name: affiliate_payouts
-- Description: Tracks commission payouts to affiliate partners with payment
--              processing and reconciliation.
--
-- Business Case: Managing affiliate payments requires careful tracking to
--                ensure partners are paid correctly and on time. This table
--                records each payout with payout period and amount, linked
--                referrals included, payment method and transaction ID,
--                tax withholding information, and reconciliation status.
--
-- The business impact is partner trust—timely, accurate payments keep
-- partners engaged and promoting. For finance, proper tracking ensures
-- accurate 1099 reporting and cash flow forecasting.
--
-- Key Performance Indicators (KPIs):
--   1. Payout Volume: Total paid to partners
--   2. Average Payout Size: By partner tier
--   3. Payment Timeliness: Days from period end to payment
--   4. Tax Withholding: Total tax collected
--   5. Reconciliation Rate: Percentage matched to bank records
--
-- Feature Reference: AFF-05 (Commission Payouts)
-- Requirements Traceability: R-AFF-036 through R-AFF-040
--
-- Normalization: 3NF - Payouts dependent on partners
--
-- High-Write Considerations:
--   - Low write volume (payouts periodic)
--   - Indexed by partner_id and payout_date
-------------------------------------------------------------------------------
CREATE TABLE public.affiliate_payouts (
    -- Primary key
    payout_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Partner
    partner_id UUID NOT NULL,

    -- Payout period
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    payout_date DATE NOT NULL,

    -- Amounts
    gross_amount NUMERIC(12,2) NOT NULL,
    tax_withheld NUMERIC(12,2) DEFAULT 0,
    fee_amount NUMERIC(12,2) DEFAULT 0,
    net_amount NUMERIC(12,2) GENERATED ALWAYS AS (gross_amount - tax_withheld - fee_amount) STORED,
    currency CHAR(3) NOT NULL,

    -- Payment details
    payment_method public.payment_method_type NOT NULL,
    payment_reference VARCHAR(255),                      -- Transaction ID
    payment_status VARCHAR(20) DEFAULT 'PENDING' CHECK (payment_status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED')),
    processed_at TIMESTAMP WITH TIME ZONE,

    -- Tax reporting
    tax_year INTEGER,
    tax_form_required BOOLEAN DEFAULT false,
    tax_form_sent BOOLEAN DEFAULT false,

    -- Reconciliation
    reconciliation_status public.reconciliation_status DEFAULT 'UNRECONCILED',
    reconciled_at TIMESTAMP WITH TIME ZONE,

    -- Notes
    notes TEXT,

    -- Metadata
    metadata JSONB,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_payout_period CHECK (period_end >= period_start),
    CONSTRAINT fk_affiliate_payouts_partner FOREIGN KEY (partner_id)
        REFERENCES public.affiliate_partners(partner_id) ON DELETE CASCADE
);

COMMENT ON TABLE public.affiliate_payouts IS 'Tracks commission payouts to affiliate partners';

-- Indexes
CREATE INDEX idx_affiliate_payouts_partner_id ON public.affiliate_payouts(partner_id, payout_date DESC);
CREATE INDEX idx_affiliate_payouts_date ON public.affiliate_payouts(payout_date);
CREATE INDEX idx_affiliate_payouts_status ON public.affiliate_payouts(payment_status);
CREATE INDEX idx_affiliate_payouts_tax_year ON public.affiliate_payouts(tax_year) WHERE tax_year IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_affiliate_payouts_timestamp
    BEFORE UPDATE ON public.affiliate_payouts
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update partner paid commission
CREATE OR REPLACE FUNCTION public.update_partner_paid_commission()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.payment_status = 'COMPLETED' AND (OLD.payment_status != 'COMPLETED' OR OLD IS NULL) THEN
        UPDATE public.affiliate_partners
        SET paid_commission = paid_commission + NEW.net_amount,
            pending_commission = pending_commission - NEW.gross_amount
        WHERE partner_id = NEW.partner_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_partner_on_payout
    AFTER INSERT OR UPDATE OF payment_status ON public.affiliate_payouts
    FOR EACH ROW EXECUTE FUNCTION public.update_partner_paid_commission();

-- Enable RLS
ALTER TABLE public.affiliate_payouts ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY affiliate_payouts_partner_policy ON public.affiliate_payouts
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.affiliate_partners ap
        WHERE ap.partner_id = affiliate_payouts.partner_id
        AND ap.partner_user_id = current_user_id()
    ));

CREATE POLICY affiliate_payouts_finance_policy ON public.affiliate_payouts
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- ======================================================================
-- TABLE 25: payout_referrals
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 25
-- Table Name: payout_referrals
-- Description: Links affiliate payouts to the specific referrals included,
--              enabling detailed reconciliation.
--
-- Business Case: When processing payouts, it's important to know exactly which
--                referrals were included. This junction table creates the
--                many-to-many relationship between payouts and referrals,
--                allowing detailed payout breakdowns, dispute resolution,
--                audit trails, and partial payments if needed.
--
-- The business impact is transparency—partners can see exactly which referrals
-- generated each payout. For finance, the link ensures accurate reconciliation
-- and audit trails.
--
-- Key Performance Indicators (KPIs):
--   1. Referrals per Payout: Average count
--   2. Payout Accuracy: Disputes per payout
--   3. Audit Trail Completeness: 100% linkage
--
-- Feature Reference: AFF-06 (Payout Mapping)
-- Requirements Traceability: R-AFF-041 through R-AFF-042
--
-- Normalization: 3NF - Junction table resolving many-to-many
--
-- High-Write Considerations:
--   - Low write volume
--   - Indexed by both IDs for fast joins
-------------------------------------------------------------------------------
CREATE TABLE public.payout_referrals (
    -- Composite primary key
    payout_id UUID NOT NULL,
    referral_id UUID NOT NULL,

    -- Amount for this referral
    commission_amount NUMERIC(12,2) NOT NULL,

    -- Timestamp
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    PRIMARY KEY (payout_id, referral_id),

    CONSTRAINT fk_payout_referrals_payout FOREIGN KEY (payout_id)
        REFERENCES public.affiliate_payouts(payout_id) ON DELETE CASCADE,
    CONSTRAINT fk_payout_referrals_referral FOREIGN KEY (referral_id)
        REFERENCES public.affiliate_referrals(referral_id) ON DELETE CASCADE
);

COMMENT ON TABLE public.payout_referrals IS 'Links affiliate payouts to specific referrals';

-- Indexes
CREATE INDEX idx_payout_referrals_payout_id ON public.payout_referrals(payout_id);
CREATE INDEX idx_payout_referrals_referral_id ON public.payout_referrals(referral_id);

-- Enable RLS (inherits from parent tables)
ALTER TABLE public.payout_referrals ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY payout_referrals_partner_policy ON public.payout_referrals
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.affiliate_referrals ar
        JOIN public.affiliate_partners ap ON ar.partner_id = ap.partner_id
        WHERE ar.referral_id = payout_referrals.referral_id
        AND ap.partner_user_id = current_user_id()
    ));

CREATE POLICY payout_referrals_finance_policy ON public.payout_referrals
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- ======================================================================
-- TABLE 26: ledger_accounts
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 26
-- Table Name: ledger_accounts
-- Description: Chart of accounts for double-entry bookkeeping, defining all
--              accounts used in the financial system. Follows GAAP/IFRS standards.
--
-- Business Case (300 words):
-- Proper accounting requires a structured chart of accounts that follows
-- GAAP/IFRS standards. This table defines asset accounts (cash, receivables),
-- liability accounts (deferred revenue, payables), equity accounts (retained
-- earnings), revenue accounts (subscription revenue), and expense accounts
-- (COGS, marketing). The hierarchical structure allows for financial statement
-- generation, audit trails, tax reporting, departmental accounting, and
-- project-based accounting.
--
-- The business impact is financial integrity—without a proper chart of
-- accounts, the business cannot produce accurate financial statements,
-- comply with tax requirements, or provide investors with reliable data.
-- This table is the foundation of all financial reporting.
--
-- The design supports complex organizational structures: multiple subsidiaries,
-- departmental P&L, project-based accounting, and cost center allocation.
-- The hierarchical account structure enables roll-ups at any level—from
-- individual accounts to balance sheet categories.
--
-- For compliance, the table tracks which accounts are relevant for tax
-- reporting and maintains an audit trail of all changes. Integration with
-- the general ledger ensures every transaction is properly classified.
--
-- Key Performance Indicators (KPIs):
--   1. Account Coverage: Percentage of transactions properly classified
--   2. Hierarchy Completeness: All accounts have proper parent
--   3. Tax Reporting Accuracy: 100% match with tax filings
--   4. Audit Trail: 100% of account changes tracked
--   5. Financial Statement Generation: Time to close books (< 5 days)
--
-- Feature Reference: LED-04 (Chart of Accounts)
-- Requirements Traceability: R-LEDGER-001 through R-LEDGER-020
--
-- Normalization: 3NF - Accounts with parent-child hierarchy
--
-- High-Write Considerations:
--   - Very low write volume (accounts rarely change)
--   - Read-heavy for every transaction
--   - Materialized path for hierarchy queries
--   - Caching recommended
-------------------------------------------------------------------------------
-- Enable ltree extension for hierarchical queries
CREATE EXTENSION IF NOT EXISTS ltree;

CREATE TABLE public.ledger_accounts (
    -- Primary key
    account_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Account identification
    account_code VARCHAR(20) NOT NULL UNIQUE,           -- Account number (e.g., 1000-001)
    account_name VARCHAR(255) NOT NULL,
    account_type public.account_type NOT NULL,
    account_category VARCHAR(100),                      -- e.g., 'Current Assets', 'Long-term Liabilities'

    -- Hierarchy
    parent_account_id UUID,                             -- Parent account for rollups
    level INTEGER,                                      -- Depth in hierarchy
    path LTREE,                                         -- Materialized path for hierarchy

    -- Normal balance
    normal_balance public.ledger_entry_type NOT NULL,  -- Debit or Credit normal balance

    -- Currency
    currency CHAR(3) DEFAULT 'USD',
    multi_currency BOOLEAN DEFAULT false,               -- Whether holds multiple currencies

    -- Control account
    is_control_account BOOLEAN DEFAULT false,           -- Whether it's a control account
    control_account_for TEXT[],                          -- What it controls

    -- Status
    is_active BOOLEAN DEFAULT true NOT NULL,
    is_cash_account BOOLEAN DEFAULT false,              -- For cash flow statements
    is_bank_account BOOLEAN DEFAULT false,              -- Linked to bank account

    -- Reporting
    financial_statement VARCHAR(20) CHECK (financial_statement IN ('BALANCE_SHEET', 'INCOME_STATEMENT', 'CASH_FLOW', 'NONE')),
    report_order INTEGER,                                -- Order in financial statements

    -- Tax
    tax_relevant BOOLEAN DEFAULT false,
    tax_code VARCHAR(50),                                -- Tax reporting code

    -- Description
    description TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT fk_ledger_accounts_parent FOREIGN KEY (parent_account_id)
        REFERENCES public.ledger_accounts(account_id) ON DELETE RESTRICT
);

COMMENT ON TABLE public.ledger_accounts IS 'Chart of accounts for double-entry bookkeeping';
COMMENT ON COLUMN public.ledger_accounts.account_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.ledger_accounts.account_code IS 'Account number for identification';
COMMENT ON COLUMN public.ledger_accounts.account_name IS 'Name of the account';
COMMENT ON COLUMN public.ledger_accounts.account_type IS 'Type of account (Asset, Liability, etc.)';
COMMENT ON COLUMN public.ledger_accounts.account_category IS 'Category within type';
COMMENT ON COLUMN public.ledger_accounts.parent_account_id IS 'Parent account for rollups';
COMMENT ON COLUMN public.ledger_accounts.level IS 'Depth in account hierarchy';
COMMENT ON COLUMN public.ledger_accounts.path IS 'Materialized path for hierarchy queries';
COMMENT ON COLUMN public.ledger_accounts.normal_balance IS 'Normal balance side (debit or credit)';
COMMENT ON COLUMN public.ledger_accounts.currency IS 'Default currency';
COMMENT ON COLUMN public.ledger_accounts.multi_currency IS 'Whether holds multiple currencies';
COMMENT ON COLUMN public.ledger_accounts.is_control_account IS 'Whether this is a control account';
COMMENT ON COLUMN public.ledger_accounts.control_account_for IS 'What this account controls';
COMMENT ON COLUMN public.ledger_accounts.is_active IS 'Whether account is active';
COMMENT ON COLUMN public.ledger_accounts.is_cash_account IS 'For cash flow classification';
COMMENT ON COLUMN public.ledger_accounts.is_bank_account IS 'Linked to bank account';
COMMENT ON COLUMN public.ledger_accounts.financial_statement IS 'Which statement this appears on';
COMMENT ON COLUMN public.ledger_accounts.report_order IS 'Order in financial statements';
COMMENT ON COLUMN public.ledger_accounts.tax_relevant IS 'Whether relevant for tax';
COMMENT ON COLUMN public.ledger_accounts.tax_code IS 'Tax reporting code';
COMMENT ON COLUMN public.ledger_accounts.description IS 'Description of account purpose';
COMMENT ON COLUMN public.ledger_accounts.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.ledger_accounts.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.ledger_accounts.created_by IS 'User who created the record';
COMMENT ON COLUMN public.ledger_accounts.updated_by IS 'User who last updated the record';

-- Indexes for ledger_accounts
CREATE INDEX idx_ledger_accounts_code ON public.ledger_accounts(account_code);
CREATE INDEX idx_ledger_accounts_type ON public.ledger_accounts(account_type);
CREATE INDEX idx_ledger_accounts_parent ON public.ledger_accounts(parent_account_id);
CREATE INDEX idx_ledger_accounts_path ON public.ledger_accounts USING gist(path);
CREATE INDEX idx_ledger_accounts_active ON public.ledger_accounts(is_active) WHERE is_active = true;

-- Trigger for updated_at
CREATE TRIGGER update_ledger_accounts_timestamp
    BEFORE UPDATE ON public.ledger_accounts
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update path and level
CREATE OR REPLACE FUNCTION public.update_account_path()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.parent_account_id IS NULL THEN
        NEW.level := 1;
        NEW.path := text2ltree(NEW.account_code);
    ELSE
        SELECT level + 1, path || text2ltree(NEW.account_code)
        INTO NEW.level, NEW.path
        FROM public.ledger_accounts
        WHERE account_id = NEW.parent_account_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER set_account_path
    BEFORE INSERT OR UPDATE OF parent_account_id ON public.ledger_accounts
    FOR EACH ROW EXECUTE FUNCTION public.update_account_path();

-- Enable RLS
ALTER TABLE public.ledger_accounts ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY ledger_accounts_finance_policy ON public.ledger_accounts
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'accountant', 'admin')
    ));

-- ======================================================================
-- TABLE 27: ledger_entries
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 27
-- Table Name: ledger_entries
-- Description: Core double-entry accounting table recording all financial
--              transactions with debits and credits ensuring balance.
--
-- Business Case (300 words):
-- For financial integrity and audit compliance, every monetary transaction
-- must be recorded using double-entry bookkeeping. This table is the heart
-- of the accounting system, ensuring every transaction balances (debits = credits),
-- complete audit trail of all financial activity, integration with sub-ledgers
-- (invoices, payments), support for multiple currencies, period closing and
-- reversals, financial statement generation, tax reporting, and reconciliation
-- with bank statements.
--
-- The business impact is financial accuracy—every dollar is tracked from
-- customer payment to bank deposit. For audit, the complete trail satisfies
-- external auditors and regulatory requirements. For management, the data
-- enables accurate financial reporting and business intelligence.
--
-- The design supports complex transactions: multiple lines per journal entry,
-- recurring journal entries for amortization, adjusting entries for accruals,
-- reversing entries for corrections, and intercompany transactions for
-- multi-entity structures. Each entry is immutable once posted, with references
-- to source documents for full traceability.
--
-- For compliance, the table maintains fiscal year and period tracking,
-- enabling period closing and reopening controls. The reconciliation status
-- tracks which entries have been matched to bank statements.
--
-- Key Performance Indicators (KPIs):
--   1. Transaction Volume: Entries per day/month
--   2. Automation Rate: Percentage automatically generated (> 90%)
--   3. Reconciliation Rate: Percentage matched to bank (> 95%)
--   4. Time to Close Books: Days after month end (< 5)
--   5. Audit Adjustments: Number of correcting entries (< 1% of total)
--
-- Feature Reference: LED-05 (General Ledger)
-- Requirements Traceability: R-LEDGER-021 through R-LEDGER-040
--
-- Normalization: 3NF - Entries dependent on accounts with journal grouping
--
-- High-Write Considerations:
--   - High write volume (every financial transaction)
--   - Partitioning by entry_date recommended
--   - Indexes for account lookups and period queries
--   - Immutable after posting (no updates)
-------------------------------------------------------------------------------
CREATE TABLE public.ledger_entries (
    -- Primary key
    entry_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Journal identification
    journal_id UUID NOT NULL,                           -- Group entries for same transaction
    entry_number VARCHAR(50),                            -- Human-readable entry number
    entry_type VARCHAR(50) NOT NULL CHECK (entry_type IN (
        'SALE', 'PURCHASE', 'PAYMENT', 'RECEIPT', 'REFUND', 'ADJUSTMENT',
        'DEPRECIATION', 'ACCRUAL', 'DEFERRAL', 'REVERSAL', 'CLOSING'
    )),

    -- Account
    account_id UUID NOT NULL,
    account_code VARCHAR(20) NOT NULL,                  -- Denormalized for performance

    -- Entry details
    entry_date DATE NOT NULL,
    entry_description TEXT NOT NULL,

    -- Amounts (debit/credit - only one will be non-zero)
    debit_amount NUMERIC(15,2) DEFAULT 0 CHECK (debit_amount >= 0),
    credit_amount NUMERIC(15,2) DEFAULT 0 CHECK (credit_amount >= 0),
    currency CHAR(3) NOT NULL,
    exchange_rate NUMERIC(12,6) DEFAULT 1.0,
    base_currency_amount NUMERIC(15,2) GENERATED ALWAYS AS (
        CASE
            WHEN debit_amount > 0 THEN debit_amount * exchange_rate
            ELSE credit_amount * exchange_rate
        END
    ) STORED,

    -- Reference to source
    source_type VARCHAR(50) NOT NULL CHECK (source_type IN (
        'INVOICE', 'PAYMENT', 'REFUND', 'CREDIT_NOTE', 'JOURNAL', 'SYSTEM'
    )),
    source_id UUID NOT NULL,
    source_reference VARCHAR(255),                      -- Human-readable reference

    -- Period
    fiscal_year INTEGER NOT NULL,
    fiscal_period INTEGER NOT NULL CHECK (fiscal_period BETWEEN 1 AND 12),
    is_period_closing BOOLEAN DEFAULT false,

    -- Reconciliation
    reconciliation_status public.reconciliation_status DEFAULT 'UNRECONCILED',
    reconciled_at TIMESTAMP WITH TIME ZONE,
    reconciled_by UUID,

    -- Reversal
    reverses_entry_id UUID,                             -- If this entry reverses another
    reversed_by_entry_id UUID,                          -- If this entry was reversed

    -- Approval
    requires_approval BOOLEAN DEFAULT false,
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,

    -- Metadata
    metadata JSONB,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_ledger_entry_amount CHECK (
        (debit_amount > 0 AND credit_amount = 0) OR
        (debit_amount = 0 AND credit_amount > 0)
    ),
    CONSTRAINT fk_ledger_entries_account FOREIGN KEY (account_id)
        REFERENCES public.ledger_accounts(account_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ledger_entries_reverses FOREIGN KEY (reverses_entry_id)
        REFERENCES public.ledger_entries(entry_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_entries_reversed_by FOREIGN KEY (reversed_by_entry_id)
        REFERENCES public.ledger_entries(entry_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_entries_approved_by FOREIGN KEY (approved_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_entries_reconciled_by FOREIGN KEY (reconciled_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.ledger_entries IS 'Double-entry accounting records for all financial transactions';
COMMENT ON COLUMN public.ledger_entries.entry_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.ledger_entries.journal_id IS 'Group ID for related entries in same transaction';
COMMENT ON COLUMN public.ledger_entries.entry_number IS 'Human-readable entry number';
COMMENT ON COLUMN public.ledger_entries.entry_type IS 'Type of journal entry';
COMMENT ON COLUMN public.ledger_entries.account_id IS 'Account being debited/credited';
COMMENT ON COLUMN public.ledger_entries.account_code IS 'Account code (denormalized)';
COMMENT ON COLUMN public.ledger_entries.entry_date IS 'Date of the entry';
COMMENT ON COLUMN public.ledger_entries.entry_description IS 'Description of the transaction';
COMMENT ON COLUMN public.ledger_entries.debit_amount IS 'Debit amount (if applicable)';
COMMENT ON COLUMN public.ledger_entries.credit_amount IS 'Credit amount (if applicable)';
COMMENT ON COLUMN public.ledger_entries.currency IS 'Transaction currency';
COMMENT ON COLUMN public.ledger_entries.exchange_rate IS 'Exchange rate to base currency';
COMMENT ON COLUMN public.ledger_entries.base_currency_amount IS 'Amount in base currency';
COMMENT ON COLUMN public.ledger_entries.source_type IS 'Source document type';
COMMENT ON COLUMN public.ledger_entries.source_id IS 'Source document ID';
COMMENT ON COLUMN public.ledger_entries.source_reference IS 'Human-readable source reference';
COMMENT ON COLUMN public.ledger_entries.fiscal_year IS 'Fiscal year';
COMMENT ON COLUMN public.ledger_entries.fiscal_period IS 'Fiscal period (1-12)';
COMMENT ON COLUMN public.ledger_entries.is_period_closing IS 'Whether this is a closing entry';
COMMENT ON COLUMN public.ledger_entries.reconciliation_status IS 'Reconciliation status';
COMMENT ON COLUMN public.ledger_entries.reconciled_at IS 'When entry was reconciled';
COMMENT ON COLUMN public.ledger_entries.reconciled_by IS 'Who reconciled the entry';
COMMENT ON COLUMN public.ledger_entries.reverses_entry_id IS 'Entry that this reverses';
COMMENT ON COLUMN public.ledger_entries.reversed_by_entry_id IS 'Entry that reversed this';
COMMENT ON COLUMN public.ledger_entries.requires_approval IS 'Whether entry needs approval';
COMMENT ON COLUMN public.ledger_entries.approved_at IS 'When entry was approved';
COMMENT ON COLUMN public.ledger_entries.approved_by IS 'Who approved the entry';
COMMENT ON COLUMN public.ledger_entries.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.ledger_entries.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.ledger_entries.created_by IS 'User who created the entry';

-- Indexes for ledger_entries
CREATE INDEX idx_ledger_entries_journal_id ON public.ledger_entries(journal_id);
CREATE INDEX idx_ledger_entries_account_id ON public.ledger_entries(account_id, entry_date DESC);
CREATE INDEX idx_ledger_entries_date ON public.ledger_entries(entry_date DESC);
CREATE INDEX idx_ledger_entries_period ON public.ledger_entries(fiscal_year, fiscal_period);
CREATE INDEX idx_ledger_entries_source ON public.ledger_entries(source_type, source_id);
CREATE INDEX idx_ledger_entries_reconciliation ON public.ledger_entries(reconciliation_status)
    WHERE reconciliation_status != 'RECONCILED';

-- Partial index for entries needing approval
CREATE INDEX idx_ledger_entries_pending_approval ON public.ledger_entries(entry_date)
    WHERE requires_approval = true AND approved_at IS NULL;

-- Trigger to validate that journal balances
CREATE OR REPLACE FUNCTION public.validate_journal_balance()
RETURNS TRIGGER AS $$
DECLARE
    v_sum_debit NUMERIC;
    v_sum_credit NUMERIC;
BEGIN
    -- For new entries, check that the journal balances
    SELECT COALESCE(SUM(debit_amount), 0), COALESCE(SUM(credit_amount), 0)
    INTO v_sum_debit, v_sum_credit
    FROM public.ledger_entries
    WHERE journal_id = NEW.journal_id;

    -- Include the new entry if this is an insert
    IF TG_OP = 'INSERT' THEN
        IF NEW.debit_amount > 0 THEN
            v_sum_debit := v_sum_debit + NEW.debit_amount;
        ELSE
            v_sum_credit := v_sum_credit + NEW.credit_amount;
        END IF;
    END IF;

    -- Debits must equal credits (within rounding tolerance)
    IF ROUND(v_sum_debit, 2) != ROUND(v_sum_credit, 2) THEN
        RAISE EXCEPTION 'Journal % does not balance: Debits = %, Credits = %',
            NEW.journal_id, v_sum_debit, v_sum_credit;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER validate_journal_balance
    AFTER INSERT OR UPDATE ON public.ledger_entries
    FOR EACH ROW EXECUTE FUNCTION public.validate_journal_balance();

-- Enable RLS
ALTER TABLE public.ledger_entries ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY ledger_entries_finance_policy ON public.ledger_entries
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'accountant', 'auditor', 'admin')
    ));

-- ======================================================================
-- TABLE 28: ledger_periods
-- ======================================================================
-------------------------------------------------------------------------------
-- Serial No: 28
-- Table Name: ledger_periods
-- Description: Defines accounting periods (months, quarters, years) and their
--              open/closed status for financial reporting and controls.
--
-- Business Case: Accounting follows fiscal periods. Once a period is closed,
--                no new entries should be added to ensure financial statement
--                integrity. This table manages fiscal year definitions, period
--                open/close status, period adjustment windows, and audit trail
--                of period changes. It enforces that entries cannot be posted
--                to closed periods and tracks who closed each period for audit.
--
-- The business impact is financial integrity—closed periods guarantee that
-- reported results are final and won't change. For audit, the closure trail
-- provides evidence of proper controls. For operations, automatic enforcement
-- prevents accidental posting to closed periods.
--
-- Key Performance Indicators (KPIs):
--   1. Period Closure Timeliness: Days after period end (< 5)
--   2. Reopening Rate: Number of periods reopened (< 1% per year)
--   3. Audit Trail: 100% of closures logged
--
-- Feature Reference: LED-06 (Period Management)
-- Requirements Traceability: R-LEDGER-041 through R-LEDGER-045
--
-- Normalization: 3NF - Periods independent
--
-- High-Write Considerations:
--   - Very low write volume (periods defined annually)
--   - Read-heavy for every transaction
--   - Indexed by fiscal year/period
-------------------------------------------------------------------------------
CREATE TABLE public.ledger_periods (
    -- Primary key
    period_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Period identification
    fiscal_year INTEGER NOT NULL,
    fiscal_period INTEGER NOT NULL CHECK (fiscal_period BETWEEN 1 AND 12),
    period_name VARCHAR(50) NOT NULL,                   -- e.g., 'January 2025'

    -- Dates
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    closing_date DATE,                                  -- Actual closing date

    -- Status
    is_open BOOLEAN DEFAULT true NOT NULL,
    is_adjustment_period BOOLEAN DEFAULT false,         -- For post-close adjustments
    closed_at TIMESTAMP WITH TIME ZONE,
    closed_by UUID,
    reopened_at TIMESTAMP WITH TIME ZONE,
    reopened_by UUID,
    reopen_reason TEXT,

    -- Next period
    next_period_id UUID,                                -- For chaining

    -- Notes
    closing_notes TEXT,

    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_ledger_period UNIQUE (fiscal_year, fiscal_period),
    CONSTRAINT chk_period_dates CHECK (end_date >= start_date),
    CONSTRAINT fk_ledger_periods_closed_by FOREIGN KEY (closed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_periods_reopened_by FOREIGN KEY (reopened_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_periods_next FOREIGN KEY (next_period_id)
        REFERENCES public.ledger_periods(period_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.ledger_periods IS 'Accounting periods with open/close status';

-- Indexes
CREATE INDEX idx_ledger_periods_year ON public.ledger_periods(fiscal_year, fiscal_period);
CREATE INDEX idx_ledger_periods_open ON public.ledger_periods(is_open) WHERE is_open = true;

-- Trigger for updated_at
CREATE TRIGGER update_ledger_periods_timestamp
    BEFORE UPDATE ON public.ledger_periods
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.ledger_periods ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY ledger_periods_finance_policy ON public.ledger_periods
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'accountant', 'admin')
    ));

-- ======================================================================
-- MATERIALIZED VIEW: mv_monthly_revenue
-- ======================================================================
-------------------------------------------------------------------------------
-- Materialized View: mv_monthly_revenue
-- Description: Pre-aggregated monthly revenue by plan, subscription, and customer
-- Business Case: Provides fast revenue reporting for finance and management
-- Refresh Strategy: Daily
-- Feature Reference: LED-07 (Revenue Reporting)
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW public.mv_monthly_revenue AS
WITH invoice_data AS (
    SELECT
        DATE_TRUNC('month', i.issue_date) AS revenue_month,
        s.plan_id,
        s.user_id,
        COUNT(DISTINCT i.invoice_id) AS invoice_count,
        SUM(i.grand_total) AS total_revenue,
        SUM(i.tax_total) AS total_tax,
        SUM(i.subtotal) AS total_subtotal,
        AVG(i.grand_total) AS avg_invoice_value
    FROM public.invoices i
    JOIN public.subscriptions s ON i.subscription_id = s.subscription_id
    WHERE i.invoice_status IN ('PAID', 'SENT')
    GROUP BY DATE_TRUNC('month', i.issue_date), s.plan_id, s.user_id
)
SELECT
    revenue_month,
    plan_id,
    COUNT(DISTINCT user_id) AS paying_customers,
    SUM(invoice_count) AS total_invoices,
    SUM(total_revenue) AS total_revenue,
    SUM(total_tax) AS total_tax,
    SUM(total_subtotal) AS total_subtotal,
    AVG(avg_invoice_value) AS avg_invoice_value,
    SUM(total_revenue) / NULLIF(COUNT(DISTINCT user_id), 0) AS arpu,
    NOW() AS refreshed_at
FROM invoice_data
GROUP BY revenue_month, plan_id;

COMMENT ON MATERIALIZED VIEW public.mv_monthly_revenue IS 'Pre-aggregated monthly revenue metrics';

CREATE UNIQUE INDEX idx_mv_monthly_revenue ON public.mv_monthly_revenue(revenue_month, plan_id);

