-- ======================================================================
-- SCHEDULED JOBS
-- ======================================================================

-- Create scheduled jobs if pg_cron is available
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
        -- Refresh monthly revenue view daily at 1 AM
        PERFORM cron.schedule(
            'refresh-monthly-revenue',
            '0 1 * * *',
            'REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_monthly_revenue'
        );

        -- Process expired subscriptions daily at 2 AM
        PERFORM cron.schedule(
            'process-expired-subscriptions',
            '0 2 * * *',
            $$
            UPDATE public.subscriptions
            SET status = 'EXPIRED',
                status_changed_at = CURRENT_TIMESTAMP
            WHERE status = 'ACTIVE'
            AND current_period_end < CURRENT_TIMESTAMP
            AND cancel_at_period_end = false
            RETURNING subscription_id;
            $$
        );

        -- Generate invoices for upcoming subscriptions daily at 3 AM
        PERFORM cron.schedule(
            'generate-recurring-invoices',
            '0 3 * * *',
            $$
            -- Invoice generation logic would go here
            -- This is a placeholder for the actual procedure
            SELECT 'Invoices generated' AS message;
            $$
        );
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'pg_cron extension not available. Scheduled jobs will not be created.';
END $$;

