-- =============================================================================
-- ENUMS FOR COMPLIANCE & DATA GOVERNANCE
-- =============================================================================

-------------------------------------------------------------------------------
-- Enum: CDG01 - retention_policy_action
-- Description: Defines actions to take when data reaches end of retention period
-- Business Case: GDPR requires specific actions based on data category
-- Feature Reference: GDPR-01, DP-01
-------------------------------------------------------------------------------
CREATE TYPE public.retention_policy_action AS ENUM (
    'DELETE',                    -- Permanent deletion
    'ANONYMIZE',                 -- Pseudonymization/anonymization
    'AGGREGATE',                 -- Aggregate for statistics only
    'ARCHIVE',                   -- Move to long-term cold storage
    'REVIEW_REQUIRED',           -- Manual review required
    'NO_ACTION'                  -- Retain indefinitely (legal hold override)
);
COMMENT ON TYPE public.retention_policy_action IS 'Actions to execute when data retention period expires';

-------------------------------------------------------------------------------
-- Enum: CDG02 - data_category_gdpr
-- Description: Categories of personal data under GDPR classification
-- Business Case: Different categories have different protection requirements
-- Feature Reference: GDPR-02, DP-02
-------------------------------------------------------------------------------
CREATE TYPE public.data_category_gdpr AS ENUM (
    'BASIC_IDENTITY',            -- Name, email, phone (Article 4(1))
    'SENSITIVE_PERSONAL',        -- Race, religion, health (Article 9)
    'BIOMETRIC',                 -- Fingerprints, facial recognition (Article 9)
    'GENETIC',                   -- Genetic data (Article 9)
    'CRIMINAL',                  -- Criminal convictions (Article 10)
    'FINANCIAL',                 -- Payment data, credit info
    'PROFESSIONAL',              -- Work history, qualifications
    'BEHAVIORAL',                -- Usage patterns, preferences
    'LOCATION',                  -- Geolocation data
    'TECHNICAL',                 -- IP addresses, device IDs
    'COMMUNICATION',             -- Messages, emails
    'DERIVED'                    -- Inferred data/profiling results
);
COMMENT ON TYPE public.data_category_gdpr IS 'GDPR classification categories for personal data';

-------------------------------------------------------------------------------
-- Enum: CDG03 - processing_legal_basis
-- Description: Legal bases for processing under GDPR Article 6
-- Business Case: Must document legal basis for each processing activity
-- Feature Reference: GDPR-03, DP-03
-------------------------------------------------------------------------------
CREATE TYPE public.processing_legal_basis AS ENUM (
    'CONSENT',                   -- Article 6(1)(a) - Consent
    'CONTRACT',                  -- Article 6(1)(b) - Contract performance
    'LEGAL_OBLIGATION',          -- Article 6(1)(c) - Legal compliance
    'VITAL_INTERESTS',           -- Article 6(1)(d) - Protect vital interests
    'PUBLIC_INTEREST',           -- Article 6(1)(e) - Public task
    'LEGITIMATE_INTERESTS',      -- Article 6(1)(f) - Legitimate interests
    'SPECIAL_CATEGORY_CONSENT',  -- Article 9(2)(a) - Explicit consent
    'EMPLOYMENT_LAW',            -- Article 9(2)(b) - Employment/social security
    'VITAL_INTERESTS_SPECIAL',   -- Article 9(2)(c) - Vital interests (special)
    'NON_PROFIT_BODY',           -- Article 9(2)(d) - Legitimate activities of foundation
    'MANIFESTLY_MADE_PUBLIC',    -- Article 9(2)(e) - Data manifestly made public
    'LEGAL_CLAIMS',              -- Article 9(2)(f) - Legal claims
    'SUBSTANTIAL_PUBLIC_INTEREST' -- Article 9(2)(g) - Substantial public interest
);
COMMENT ON TYPE public.processing_legal_basis IS 'GDPR Article 6 legal bases for data processing';

-------------------------------------------------------------------------------
-- Enum: CDG04 - consent_status
-- Description: Status of user consent for specific processing purposes
-- Business Case: Track consent lifecycle for audit trail
-- Feature Reference: GDPR-04, DP-04
-------------------------------------------------------------------------------
CREATE TYPE public.consent_status AS ENUM (
    'GRANTED',                   -- Active consent given
    'WITHDRAWN',                 -- Consent withdrawn by user
    'EXPIRED',                   -- Consent period expired
    'RENEWED',                   -- Consent renewed after expiry
    'REJECTED',                  -- Explicitly rejected
    'IMPLIED',                   -- Implied by action (legitimate interest)
    'NOT_PROVIDED'               -- No decision made
);
COMMENT ON TYPE public.consent_status IS 'Lifecycle states of user consent';

-------------------------------------------------------------------------------
-- Enum: CDG05 - dpia_status
-- Description: Status of Data Protection Impact Assessment
-- Business Case: Track DPIA progress for high-risk processing
-- Feature Reference: GDPR-05, DP-05
-------------------------------------------------------------------------------
CREATE TYPE public.dpia_status AS ENUM (
    'NOT_REQUIRED',              -- DPIA not required
    'SCREENING',                 -- Initial screening phase
    'IN_PROGRESS',               -- Assessment underway
    'REVIEW',                    -- Under review by DPO
    'APPROVED',                  -- Approved with mitigations
    'CONDITIONALLY_APPROVED',    -- Approved with conditions
    'REJECTED',                  -- Cannot proceed as planned
    'MONITORING',                -- Ongoing monitoring of risks
    'OUTDATED',                  -- Needs review due to changes
    'ARCHIVED'                   -- Archived after project completion
);
COMMENT ON TYPE public.dpia_status IS 'Progress states for Data Protection Impact Assessments';

-------------------------------------------------------------------------------
-- Enum: CDG06 - breach_severity
-- Description: Severity levels for personal data breaches
-- Business Case: Determines notification requirements and response priority
-- Feature Reference: GDPR-06, DP-06
-------------------------------------------------------------------------------
CREATE TYPE public.breach_severity AS ENUM (
    'CRITICAL',                  -- High risk to rights, immediate notification required
    'HIGH',                      -- Significant risk, notification within 72h
    'MEDIUM',                    -- Moderate risk, documented but not notified
    'LOW',                       -- Minimal risk, internal log only
    'UNDER_ASSESSMENT'           -- Severity being determined
);
COMMENT ON TYPE public.breach_severity IS 'Severity classification for data breaches under GDPR Article 33-34';

-------------------------------------------------------------------------------
-- Enum: CDG07 - breach_status
-- Description: Status of breach investigation and remediation
-- Business Case: Track breach response lifecycle
-- Feature Reference: GDPR-07, DP-07
-------------------------------------------------------------------------------
CREATE TYPE public.breach_status AS ENUM (
    'DETECTED',                  -- Initial detection
    'INVESTIGATING',             -- Investigation in progress
    'CONTAINED',                 -- Breach contained
    'NOTIFIED_AUTHORITIES',      -- Supervisory authority notified
    'NOTIFIED_DATA_SUBJECTS',    -- Affected individuals notified
    'REMEDIATION',               -- Remediation in progress
    'RESOLVED',                  -- Fully resolved
    'CLOSED',                    -- Case closed
    'FALSE_POSITIVE'             -- Determined to be false alarm
);
COMMENT ON TYPE public.breach_status IS 'Response lifecycle states for data breach incidents';

-------------------------------------------------------------------------------
-- Enum: CDG08 - dsar_request_type
-- Description: Types of data subject requests under GDPR
-- Business Case: Track and manage different rights requests
-- Feature Reference: GDPR-08, DP-08
-------------------------------------------------------------------------------
CREATE TYPE public.dsar_request_type AS ENUM (
    'ACCESS',                    -- Right to access (Article 15)
    'RECTIFICATION',             -- Right to rectification (Article 16)
    'ERASURE',                   -- Right to erasure/right to be forgotten (Article 17)
    'RESTRICTION',               -- Right to restriction (Article 18)
    'PORTABILITY',               -- Right to data portability (Article 20)
    'OBJECTION',                 -- Right to object (Article 21)
    'AUTOMATED_DECISION',        -- Automated decision-making (Article 22)
    'CONSENT_WITHDRAWAL',        -- Withdraw consent
    'INFORMATION'                -- Request for information (Article 13-14)
);
COMMENT ON TYPE public.dsar_request_type IS 'GDPR data subject rights request types';

-------------------------------------------------------------------------------
-- Enum: CDG09 - dsar_request_status
-- Description: Status of data subject request processing
-- Business Case: Track SLA compliance for request handling
-- Feature Reference: GDPR-09, DP-09
-------------------------------------------------------------------------------
CREATE TYPE public.dsar_request_status AS ENUM (
    'RECEIVED',                  -- Request received
    'VERIFYING_IDENTITY',        -- Verifying requester identity
    'PROCESSING',                -- Processing in progress
    'EXTENSION_APPLIED',         -- Extension applied (complex requests)
    'AWAITING_INFORMATION',      -- Need more information
    'COMPLETED',                 -- Request fulfilled
    'PARTIALLY_COMPLETED',       -- Partial fulfillment
    'REJECTED',                  -- Request rejected (legal grounds)
    'EXPIRED',                   -- Request expired (no response)
    'APPEALED',                  -- Decision appealed
    'ESCALATED_TO_DPO'           -- Escalated to Data Protection Officer
);
COMMENT ON TYPE public.dsar_request_status IS 'Processing states for data subject requests';

-------------------------------------------------------------------------------
-- Enum: CDG10 - legal_hold_status
-- Description: Status of legal holds for litigation/eDiscovery
-- Business Case: Override retention policies when data needed for legal proceedings
-- Feature Reference: LEGAL-01, DP-11
-------------------------------------------------------------------------------
CREATE TYPE public.legal_hold_status AS ENUM (
    'ACTIVE',                    -- Hold actively in place
    'PENDING',                   -- Hold requested, not yet applied
    'RELEASED',                  -- Hold released
    'EXPIRED',                   -- Hold expired by date
    'OVERRIDDEN'                 -- Overridden by higher legal authority
);
COMMENT ON TYPE public.legal_hold_status IS 'Status of legal holds that override retention policies';

-- =============================================================================
-- TABLE 41: data_retention_policies
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 41
-- Table Name: data_retention_policies
-- Description: Defines retention periods and actions for each data category,
--              with audit trail, legal basis documentation, and compliance
--              mapping to regulations (GDPR, CCPA, HIPAA, etc.).
--
-- Business Case (300 words):
-- GDPR Article 5(1)(e) requires that personal data be kept for no longer than
-- necessary for the purposes for which it is processed. Organizations must
-- establish and document retention periods for different categories of data.
-- This table serves as the central repository for all retention policy definitions,
-- enabling automated enforcement of data lifecycle management.
--
-- Without a formal retention policy framework, organizations face several risks:
-- keeping data longer than necessary increases breach impact and liability,
-- deleting data too early may violate legal obligations, inconsistent application
-- leads to compliance gaps, and manual processes are error-prone. This table
-- addresses these challenges by providing a systematic, auditable framework.
--
-- The business impact is substantial: compliance with privacy regulations becomes
-- demonstrable through documented policies. Storage costs are optimized by
-- automatically deleting data when no longer needed. Legal holds can override
-- standard policies when litigation requires preservation. Data minimization
-- principles are enforced consistently across all systems.
--
-- The design supports multi-jurisdiction requirements (GDPR, CCPA, LGPD) with
-- different retention periods for the same data based on location. It includes
-- approval workflows to ensure policies are reviewed by legal and compliance
-- teams before activation. The versioning system tracks policy changes over
-- time, essential for audit trails.
--
-- Key Performance Indicators (KPIs):
--   1. Policy Coverage: Percentage of data categories with defined retention (>95%)
--   2. Policy Currency: Number of policies reviewed/updated in last 12 months
--   3. Compliance Rate: Percentage of automated deletions executed successfully (>99%)
--   4. Legal Hold Overrides: Number of holds overriding policies (monitor)
--   5. Audit Trail Completeness: 100% of policy changes traceable
--   6. Time to Policy Update: Days from regulation change to policy update (<30)
--   7. Data Volume Impact: TB of data deleted/anonymized per quarter
--   8. Storage Cost Savings: Reduction in storage costs from enforcement (>20%)
--
-- Feature Reference: GDPR-01, RET-01, COMP-01
-- Requirements Traceability: GDPR Article 5(1)(e), Article 17, Article 30
--
-- Normalization: 3NF - Policies independent with versioning and approvals
--
-- High-Write Considerations:
--   - Write-light (policy changes infrequent)
--   - Read-heavy for retention job execution
--   - Partial indexes for active policies only
--   - JSONB for flexible compliance mapping
-------------------------------------------------------------------------------
CREATE TABLE public.data_retention_policies (
    -- Primary key
    policy_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core policy identification
    policy_name VARCHAR(200) NOT NULL,
    policy_version VARCHAR(20) NOT NULL,
    policy_number VARCHAR(50) GENERATED ALWAYS AS (
        'RET-' || TO_CHAR(created_at, 'YYYY') || '-' ||
        LPAD(CAST(EXTRACT(DOY FROM created_at) AS TEXT), 3, '0') || '-' ||
        LPAD(ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('year', created_at) ORDER BY created_at)::TEXT, 4, '0')
    ) STORED,

    -- Data classification
    data_category public.data_category_gdpr NOT NULL,
    sub_category VARCHAR(100),
    sensitivity_level public.data_sensitivity_level NOT NULL DEFAULT 'CONFIDENTIAL',
    data_scope_description TEXT NOT NULL,
    includes_personal_data BOOLEAN DEFAULT true,
    includes_special_category BOOLEAN DEFAULT false,

    -- Applicable tables/columns
    affected_tables TEXT[] NOT NULL,           -- Array of table names
    affected_columns TEXT[],                    -- NULL means entire table
    filter_condition TEXT,                       -- SQL condition for selective retention

    -- Retention period definition
    retention_period_unit VARCHAR(20) CHECK (retention_period_unit IN ('DAYS', 'MONTHS', 'YEARS', 'INDEFINITE', 'EVENT_BASED')),
    retention_period_value INTEGER CHECK (retention_period_value > 0 OR retention_period_unit = 'INDEFINITE'),
    retention_period_days INTEGER GENERATED ALWAYS AS (
        CASE
            WHEN retention_period_unit = 'DAYS' THEN retention_period_value
            WHEN retention_period_unit = 'MONTHS' THEN retention_period_value * 30
            WHEN retention_period_unit = 'YEARS' THEN retention_period_value * 365
            ELSE NULL
        END
    ) STORED,

    -- Action on expiry
    expiry_action public.retention_policy_action NOT NULL,
    anonymization_method VARCHAR(50) CHECK (anonymization_method IS NULL OR
        anonymization_method IN ('NULLIFY', 'MASK', 'PERTURB', 'GENERALIZE', 'PSEUDONYMIZE', 'SWAP', 'AGGREGATE')),
    archive_location TEXT,                       -- Where to archive if action = 'ARCHIVE'

    -- Jurisdictional applicability
    applicable_jurisdictions TEXT[] NOT NULL DEFAULT '{GLOBAL}', -- e.g., {'EU', 'USA', 'CALIFORNIA'}
    primary_regulation VARCHAR(50) CHECK (primary_regulation IN ('GDPR', 'CCPA', 'LGPD', 'PIPEDA', 'APPI', 'HIPAA', 'GLBA', 'OTHER')),
    secondary_regulations TEXT[],                -- Other applicable regulations

    -- Legal basis and justification
    legal_basis public.processing_legal_basis NOT NULL,
    legal_basis_justification TEXT NOT NULL,
    business_justification TEXT NOT NULL,
    risk_assessment TEXT,
    data_protection_impact TEXT,

    -- Policy ownership
    policy_owner_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    data_steward_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    legal_reviewer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    technical_contact_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Validity period
    effective_from DATE NOT NULL DEFAULT CURRENT_DATE,
    effective_to DATE,                            -- NULL means current
    review_date DATE NOT NULL DEFAULT (CURRENT_DATE + INTERVAL '1 year'),
    last_reviewed_date DATE,
    next_review_date DATE GENERATED ALWAYS AS (
        CASE
            WHEN review_date IS NOT NULL THEN review_date
            ELSE last_reviewed_date + INTERVAL '1 year'
        END
    ) STORED,

    -- Approval workflow
    approval_status VARCHAR(20) DEFAULT 'DRAFT' CHECK (approval_status IN ('DRAFT', 'PENDING_REVIEW', 'APPROVED', 'REJECTED', 'SUPERSEDED')),
    approved_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    approved_at TIMESTAMP WITH TIME ZONE,
    rejection_reason TEXT,

    -- Exception handling
    allows_legal_hold_override BOOLEAN DEFAULT true,
    requires_individual_consent BOOLEAN DEFAULT false,
    has_opt_out_provision BOOLEAN DEFAULT false,

    -- Statistics
    estimated_record_count BIGINT,
    estimated_data_size_gb NUMERIC(10,2),
    actual_deleted_count BIGINT DEFAULT 0,
    actual_archived_count BIGINT DEFAULT 0,
    last_execution_date DATE,
    last_execution_status VARCHAR(20),

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    tags TEXT[],
    notes TEXT,
    documentation_link TEXT,

    -- Constraints
    CONSTRAINT valid_retention_period CHECK (
        (retention_period_unit = 'INDEFINITE' AND retention_period_value IS NULL) OR
        (retention_period_unit != 'INDEFINITE' AND retention_period_value IS NOT NULL AND retention_period_value > 0)
    ),
    CONSTRAINT valid_effective_dates CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT valid_review_date CHECK (review_date >= effective_from),
    CONSTRAINT unique_policy_name_version UNIQUE (policy_name, policy_version, effective_from)
);

COMMENT ON TABLE public.data_retention_policies IS 'GDPR-compliant data retention policies with audit trail and legal basis documentation';
COMMENT ON COLUMN public.data_retention_policies.policy_id IS 'Primary key - unique policy identifier';
COMMENT ON COLUMN public.data_retention_policies.policy_name IS 'Human-readable policy name';
COMMENT ON COLUMN public.data_retention_policies.policy_version IS 'Semantic version of the policy';
COMMENT ON COLUMN public.data_retention_policies.data_category IS 'GDPR data category classification';
COMMENT ON COLUMN public.data_retention_policies.affected_tables IS 'Database tables subject to this policy';
COMMENT ON COLUMN public.data_retention_policies.retention_period_days IS 'Calculated retention period in days';
COMMENT ON COLUMN public.data_retention_policies.expiry_action IS 'Action to take when data reaches end of retention';
COMMENT ON COLUMN public.data_retention_policies.legal_basis IS 'Legal justification for retention period';
COMMENT ON COLUMN public.data_retention_policies.policy_owner_id IS 'Business owner accountable for this policy';

-- Indexes
CREATE INDEX idx_retention_policies_data_category ON public.data_retention_policies(data_category);
CREATE INDEX idx_retention_policies_effective_dates ON public.data_retention_policies(effective_from, effective_to);
CREATE INDEX idx_retention_policies_review_date ON public.data_retention_policies(next_review_date) WHERE approval_status = 'APPROVED';
CREATE INDEX idx_retention_policies_owner ON public.data_retention_policies(policy_owner_id);
CREATE INDEX idx_retention_policies_tables ON public.data_retention_policies USING gin(affected_tables);
CREATE INDEX idx_retention_policies_approval_status ON public.data_retention_policies(approval_status);
CREATE INDEX idx_retention_policies_expiry_action ON public.data_retention_policies(expiry_action) WHERE expiry_action != 'NO_ACTION';

-- Trigger for updated_at
CREATE TRIGGER update_data_retention_policies_timestamp
    BEFORE UPDATE ON public.data_retention_policies
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.data_retention_policies ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY data_retention_policies_dpo_policy ON public.data_retention_policies
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'admin', 'compliance_manager', 'legal_counsel')
    ));

-- =============================================================================
-- TABLE 42: data_retention_queue
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 42
-- Table Name: data_retention_queue
-- Description: Execution queue for automated data retention enforcement with
--              retry logic, dead letter handling, and comprehensive audit trail.
--
-- Business Case (300 words):
-- Automated enforcement of data retention policies requires a reliable queuing
-- mechanism to handle large volumes of records without impacting production
-- database performance. This table serves as the execution engine for the
-- retention policy framework, ensuring that data is deleted, anonymized, or
-- archived according to schedule.
--
-- Without an automated queue, retention enforcement would require manual
-- scripts or ad-hoc jobs, leading to inconsistent application, missed deadlines,
-- and audit failures. The queue ensures that every record scheduled for action
-- is processed reliably, with retries for transient failures and dead letter
-- handling for permanent errors.
--
-- The business impact is direct: regulatory compliance is maintained through
-- consistent enforcement. Data minimization reduces storage costs and breach
-- risk. The audit trail provides evidence of compliance to regulators. Failed
-- executions are captured for manual intervention, ensuring no record is
-- inadvertently retained beyond its policy.
--
-- The design supports multiple execution strategies: batch processing during
-- off-peak hours for efficiency, real-time processing for urgent deletions
-- (right to be forgotten), and phased processing to avoid lock contention.
-- The SKIP LOCKED pattern enables multiple workers to process the queue
-- concurrently without conflicts.
--
-- Key Performance Indicators (KPIs):
--   1. Queue Depth: Number of pending records to process (<10,000)
--   2. Processing Latency: Average time from scheduled_date to completion (<24h)
--   3. Success Rate: Percentage of records processed successfully (>99%)
--   4. Throughput: Records processed per hour (monitor for capacity)
--   5. Error Rate: Percentage of records that failed permanently (<1%)
--   6. Age of Oldest Pending: Days since scheduling of oldest unprocessed record
--   7. SLA Compliance: Percentage processed within retention period + grace window
--   8. Storage Impact: GB of data deleted/anonymized per day
--
-- Feature Reference: GDPR-02, RET-02, AUTO-01
-- Requirements Traceability: GDPR Article 17 (Right to erasure), Article 5(1)(e)
--
-- Normalization: 3NF - Queue entries dependent on policies with execution tracking
--
-- High-Write Considerations:
--   - High write volume (daily batch inserts)
--   - Partitioned by scheduled_date for efficient management
--   - SKIP LOCKED pattern for concurrent worker processing
--   - Partial indexes for pending items only
-------------------------------------------------------------------------------
CREATE TABLE public.data_retention_queue (
    -- Primary key (composite for partitioning)
    queue_id UUID DEFAULT gen_random_uuid() NOT NULL,
    scheduled_date DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Policy reference
    policy_id UUID NOT NULL REFERENCES public.data_retention_policies(policy_id) ON DELETE CASCADE,
    policy_name VARCHAR(200) NOT NULL,

    -- Target record identification
    schema_name VARCHAR(100) NOT NULL,
    table_name VARCHAR(100) NOT NULL,
    record_id UUID NOT NULL,                         -- Primary key of the record
    partition_name VARCHAR(100),                      -- If table is partitioned

    -- Record metadata (for audit)
    record_created_at TIMESTAMP WITH TIME ZONE,
    record_updated_at TIMESTAMP WITH TIME ZONE,
    record_owner_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    record_size_bytes BIGINT,                         -- For storage tracking

    -- Scheduling
    scheduled_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    scheduled_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Action to perform
    action_required public.retention_policy_action NOT NULL,
    action_parameters JSONB,                          -- Additional parameters (anonymization rules, archive location)

    -- Processing status
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN (
        'PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'RETRYING',
        'SKIPPED', 'CANCELLED', 'ON_HOLD', 'DEAD_LETTER'
    )),

    -- Retry logic
    retry_count INTEGER DEFAULT 0 NOT NULL,
    max_retries INTEGER DEFAULT 3 NOT NULL,
    retry_interval_minutes INTEGER DEFAULT 60,        -- Exponential backoff base
    next_retry_at TIMESTAMP WITH TIME ZONE,
    last_error_message TEXT,
    last_error_stack TEXT,
    last_error_timestamp TIMESTAMP WITH TIME ZONE,

    -- Locking for concurrent workers
    locked_by VARCHAR(100),                           -- Worker identifier
    locked_at TIMESTAMP WITH TIME ZONE,
    locked_until TIMESTAMP WITH TIME ZONE,

    -- Execution timing
    processing_started_at TIMESTAMP WITH TIME ZONE,
    processing_completed_at TIMESTAMP WITH TIME ZONE,
    processing_duration_ms INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (processing_completed_at - processing_started_at)) * 1000
    ) STORED,

    -- Execution results
    records_affected INTEGER,                         -- For batch operations
    bytes_processed BIGINT,
    archive_location TEXT,                            -- If archived
    archive_checksum TEXT,                            -- For verification
    execution_details JSONB,                          -- Detailed results

    -- Quality metrics
    execution_quality_score NUMERIC(5,2) CHECK (execution_quality_score IS NULL OR (execution_quality_score BETWEEN 0 AND 100)),
    verification_status BOOLEAN,                      -- Post-execution verification
    verified_at TIMESTAMP WITH TIME ZONE,
    verified_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Metadata
    batch_id UUID,                                    -- Group records processed together
    priority INTEGER DEFAULT 100 CHECK (priority BETWEEN 1 AND 1000), -- Lower = higher priority
    tags TEXT[],
    notes TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Constraints
    CONSTRAINT unique_record_policy UNIQUE (schema_name, table_name, record_id, policy_id, scheduled_date),
    CONSTRAINT chk_retry_count CHECK (retry_count <= max_retries),

    PRIMARY KEY (queue_id, scheduled_date)
) PARTITION BY RANGE (scheduled_date);

COMMENT ON TABLE public.data_retention_queue IS 'Execution queue for automated data retention enforcement with retry logic and audit';
COMMENT ON COLUMN public.data_retention_queue.queue_id IS 'Primary key';
COMMENT ON COLUMN public.data_retention_queue.scheduled_date IS 'Date when action should be executed (partition key)';
COMMENT ON COLUMN public.data_retention_queue.policy_id IS 'Reference to the retention policy being enforced';
COMMENT ON COLUMN public.data_retention_queue.schema_name IS 'Database schema containing the record';
COMMENT ON COLUMN public.data_retention_queue.table_name IS 'Table containing the record';
COMMENT ON COLUMN public.data_retention_queue.record_id IS 'Primary key of the record to process';
COMMENT ON COLUMN public.data_retention_queue.action_required IS 'Type of action to perform';
COMMENT ON COLUMN public.data_retention_queue.status IS 'Current processing status with retry states';
COMMENT ON COLUMN public.data_retention_queue.locked_until IS 'Lock expiration for distributed workers';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_retention_queue_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'data_retention_queue_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    -- Check if partition already exists
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.data_retention_queue
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(status, next_retry_at) WHERE status IN (''PENDING'', ''RETRYING'');
            CREATE INDEX IF NOT EXISTS %I ON public.%I(locked_until) WHERE locked_until IS NOT NULL;
        ',
        'idx_' || partition_name || '_status', partition_name,
        'idx_' || partition_name || '_locked', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create initial partitions (current and next 2 months)
SELECT public.create_retention_queue_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_retention_queue_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_retention_queue_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes
CREATE INDEX idx_retention_queue_status_scheduled ON public.data_retention_queue(status, next_retry_at)
    WHERE status IN ('PENDING', 'RETRYING');
CREATE INDEX idx_retention_queue_next_retry ON public.data_retention_queue(next_retry_at)
    WHERE status = 'RETRYING' AND next_retry_at IS NOT NULL;
CREATE INDEX idx_retention_queue_locked ON public.data_retention_queue(locked_until)
    WHERE locked_until IS NOT NULL;
CREATE INDEX idx_retention_queue_record ON public.data_retention_queue(schema_name, table_name, record_id);
CREATE INDEX idx_retention_queue_batch ON public.data_retention_queue(batch_id);
CREATE INDEX idx_retention_queue_policy ON public.data_retention_queue(policy_id, status);

-- Trigger for updated_at
CREATE TRIGGER update_data_retention_queue_timestamp
    BEFORE UPDATE ON public.data_retention_queue
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to claim next batch of records for processing (using SKIP LOCKED pattern)
CREATE OR REPLACE FUNCTION public.claim_retention_queue_batch(
    p_worker_id VARCHAR(100),
    p_batch_size INTEGER DEFAULT 100,
    p_lock_minutes INTEGER DEFAULT 30
)
RETURNS TABLE (
    queue_id UUID,
    scheduled_date DATE,
    schema_name VARCHAR(100),
    table_name VARCHAR(100),
    record_id UUID,
    action_required public.retention_policy_action,
    action_parameters JSONB
) AS $$
BEGIN
    RETURN QUERY
    UPDATE public.data_retention_queue
    SET
        status = 'PROCESSING',
        locked_by = p_worker_id,
        locked_at = CURRENT_TIMESTAMP,
        locked_until = CURRENT_TIMESTAMP + (p_lock_minutes || ' minutes')::INTERVAL,
        processing_started_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = current_user_id()
    WHERE queue_id IN (
        SELECT queue_id
        FROM public.data_retention_queue
        WHERE status IN ('PENDING', 'RETRYING')
            AND (next_retry_at IS NULL OR next_retry_at <= CURRENT_TIMESTAMP)
            AND (locked_until IS NULL OR locked_until < CURRENT_TIMESTAMP)
        ORDER BY
            priority ASC,
            CASE status
                WHEN 'RETRYING' THEN 1
                WHEN 'PENDING' THEN 2
            END,
            scheduled_date ASC
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    )
    RETURNING
        data_retention_queue.queue_id,
        data_retention_queue.scheduled_date,
        data_retention_queue.schema_name,
        data_retention_queue.table_name,
        data_retention_queue.record_id,
        data_retention_queue.action_required,
        data_retention_queue.action_parameters;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.claim_retention_queue_batch IS 'Claims next batch of retention queue items for processing using SKIP LOCKED pattern';

-- Enable RLS
ALTER TABLE public.data_retention_queue ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY data_retention_queue_platform_policy ON public.data_retention_queue
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'compliance_officer', 'data_steward')
    ));

-- =============================================================================
-- TABLE 43: data_processing_register
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 43
-- Table Name: data_processing_register
-- Description: GDPR Article 30 register of processing activities, documenting
--              all data processing operations with legal basis, purpose, data
--              categories, recipients, and safeguards.
--
-- Business Case (300 words):
-- Article 30 of the GDPR requires organizations to maintain a record of all
-- processing activities. This register is a fundamental compliance document
-- that must be made available to supervisory authorities upon request. It serves
-- as the central inventory of how personal data flows through the organization.
--
-- Without this register, organizations cannot demonstrate compliance with GDPR
-- Article 30, risking significant fines (up to 4% of global revenue). They
-- cannot respond to supervisory authority inquiries, conduct proper Data
-- Protection Impact Assessments, or understand their data processing landscape.
--
-- The business impact is direct: compliance with Article 30 protects against
-- regulatory penalties. The register enables privacy by design by documenting
-- processing purposes and legal bases. It supports data subject rights requests
-- by revealing where data is processed. For data protection officers, it
-- provides the visibility needed to oversee compliance.
--
-- The design captures everything required by Article 30: controller information,
-- processing purposes, data subject categories, personal data types, recipient
-- categories, international transfers, retention periods, and security measures.
-- Each activity is versioned to track changes over time, with scheduled reviews
-- to ensure accuracy.
--
-- Key Performance Indicators (KPIs):
--   1. Register Completeness: Percentage of processing activities documented (100%)
--   2. Currency: Number of activities reviewed/updated in last 12 months
--   3. DPIA Coverage: Percentage of high-risk activities with DPIA (100%)
--   4. Third-Country Transfer Documentation: All transfers with safeguards documented
--   5. Review Compliance: Percentage of activities reviewed within required timeframe
--   6. Authority Response Time: Hours to provide register upon request (<24h)
--   7. Processing Volume Growth: Year-over-year change in activities
--
-- Feature Reference: GDPR-03, ART30-01, COMP-02
-- Requirements Traceability: GDPR Article 30, Article 35, Article 46
--
-- Normalization: 3NF - Processing activities independent with versioning
--
-- High-Write Considerations:
--   - Write-light (activities added as new processing occurs)
--   - Read-heavy for audits and assessments
--   - JSONB for flexible recipient and safeguard documentation
--   - Partial indexes for active activities only
-------------------------------------------------------------------------------
CREATE TABLE public.data_processing_register (
    -- Primary key
    register_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    activity_id VARCHAR(50) NOT NULL UNIQUE,
    activity_name VARCHAR(500) NOT NULL,
    activity_version VARCHAR(20) NOT NULL,
    activity_status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (activity_status IN ('ACTIVE', 'INACTIVE', 'PLANNED', 'RETIRED', 'ARCHIVED')),

    -- Controller information
    controller_name VARCHAR(500) NOT NULL,
    controller_representative VARCHAR(500),
    controller_email VARCHAR(255),
    controller_phone VARCHAR(50),
    controller_address TEXT,

    -- Data Protection Officer
    dpo_name VARCHAR(500),
    dpo_email VARCHAR(255),
    dpo_phone VARCHAR(50),
    dpo_contact_method TEXT,

    -- Joint controllers (if any)
    joint_controllers JSONB,

    -- Processing purpose
    processing_purpose TEXT NOT NULL,
    processing_description TEXT NOT NULL,
    legal_basis public.processing_legal_basis NOT NULL,
    legal_basis_justification TEXT NOT NULL,
    legitimate_interest_assessment TEXT,  -- Required for legitimate interests basis
    consent_required BOOLEAN DEFAULT false,
    consent_withdrawal_process TEXT,

    -- Data subjects
    data_subject_categories TEXT[] NOT NULL,
    data_subject_count_estimate INTEGER,
    data_subject_count_actual INTEGER,
    data_subject_min_age INTEGER,
    vulnerable_subjects_included BOOLEAN DEFAULT false,
    vulnerable_subject_safeguards TEXT,

    -- Personal data categories
    personal_data_categories public.data_category_gdpr[] NOT NULL,
    special_category_data BOOLEAN DEFAULT false,
    special_category_condition TEXT,
    sensitive_data_safeguards TEXT,
    data_sources TEXT[],
    data_retention_policy_id UUID REFERENCES public.data_retention_policies(policy_id) ON DELETE SET NULL,

    -- Processing operations
    processing_operations TEXT[] NOT NULL,
    processing_frequency VARCHAR(50) CHECK (processing_frequency IN ('CONTINUOUS', 'DAILY', 'WEEKLY', 'MONTHLY', 'QUARTERLY', 'YEARLY', 'ONE_OFF')),
    processing_volume_estimate VARCHAR(50),
    processing_start_date DATE,
    processing_end_date DATE,

    -- Recipients
    recipient_categories TEXT[],
    recipient_names TEXT[],
    recipient_countries VARCHAR(3)[],
    data_sharing_agreements JSONB,

    -- Third country transfers
    third_country_transfers BOOLEAN DEFAULT false,
    third_country_list VARCHAR(3)[],
    transfer_safeguards TEXT,
    adequacy_decision_reference TEXT,
    binding_corporate_rules_ref TEXT,
    standard_contractual_clauses_ref TEXT,
    transfer_impact_assessment TEXT,

    -- Security measures
    technical_measures TEXT[],
    organizational_measures TEXT[],
    security_certifications TEXT[],
    last_security_audit_date DATE,
    security_incident_count INTEGER DEFAULT 0,

    -- Risk assessment
    risk_level public.processing_risk_level NOT NULL,
    risk_assessment_date DATE,
    risk_assessment_summary TEXT,
    dpia_required BOOLEAN GENERATED ALWAYS AS (
        risk_level IN ('HIGH', 'VERY_HIGH') OR special_category_data = true
    ) STORED,
    dpia_reference UUID,  -- Reference to data_protection_impact_assessments

    -- Prior consultation
    prior_consultation_required BOOLEAN DEFAULT false,
    prior_consultation_date DATE,
    supervisory_authority VARCHAR(500),
    consultation_outcome TEXT,

    -- Compliance monitoring
    last_review_date DATE NOT NULL DEFAULT CURRENT_DATE,
    next_review_date DATE GENERATED ALWAYS AS (
        CASE
            WHEN risk_level IN ('HIGH', 'VERY_HIGH') THEN last_review_date + INTERVAL '6 months'
            ELSE last_review_date + INTERVAL '1 year'
        END
    ) STORED,
    review_required BOOLEAN DEFAULT true,
    review_notes TEXT,

    -- Documentation
    documentation_urls TEXT[],
    supporting_documents JSONB,

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    business_unit VARCHAR(200),
    department VARCHAR(200),
    process_owner_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_dates CHECK (processing_end_date IS NULL OR processing_end_date > processing_start_date)
);

COMMENT ON TABLE public.data_processing_register IS 'GDPR Article 30 register of processing activities with full compliance documentation';
COMMENT ON COLUMN public.data_processing_register.register_id IS 'Primary key';
COMMENT ON COLUMN public.data_processing_register.activity_id IS 'Unique identifier for the processing activity';
COMMENT ON COLUMN public.data_processing_register.legal_basis IS 'Legal basis under GDPR Article 6 for this processing';
COMMENT ON COLUMN public.data_processing_register.dpia_required IS 'Generated flag indicating if DPIA is required';
COMMENT ON COLUMN public.data_processing_register.next_review_date IS 'Calculated next review date based on risk level';

-- Indexes
CREATE INDEX idx_processing_register_legal_basis ON public.data_processing_register(legal_basis);
CREATE INDEX idx_processing_register_risk_level ON public.data_processing_register(risk_level);
CREATE INDEX idx_processing_register_next_review ON public.data_processing_register(next_review_date) WHERE activity_status = 'ACTIVE';
CREATE INDEX idx_processing_register_dpia_reference ON public.data_processing_register(dpia_reference) WHERE dpia_reference IS NOT NULL;
CREATE INDEX idx_processing_register_data_categories ON public.data_processing_register USING gin(personal_data_categories);
CREATE INDEX idx_processing_register_data_subjects ON public.data_processing_register USING gin(data_subject_categories);
CREATE INDEX idx_processing_register_activity_id ON public.data_processing_register(activity_id);

-- Trigger for updated_at
CREATE TRIGGER update_data_processing_register_timestamp
    BEFORE UPDATE ON public.data_processing_register
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.data_processing_register ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY data_processing_register_compliance_policy ON public.data_processing_register
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'compliance_officer', 'admin', 'auditor')
    ));

-- =============================================================================
-- TABLE 44: data_protection_impact_assessments
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 44
-- Table Name: data_protection_impact_assessments
-- Description: GDPR Article 35 Data Protection Impact Assessments (DPIAs) for
--              high-risk processing activities, with risk identification,
--              mitigation measures, and approval tracking.
--
-- Business Case (300 words):
-- Article 35 of the GDPR requires controllers to conduct a Data Protection
-- Impact Assessment (DPIA) where processing is likely to result in a high risk
-- to the rights and freedoms of individuals. The DPIA must include systematic
-- description of processing operations, assessment of necessity and proportionality,
-- assessment of risks, and measures to address risks.
--
-- Without proper DPIAs, organizations risk processing high-risk data without
-- adequate safeguards, leading to breaches, regulatory fines, and reputational
-- damage. The DPIA is not just a compliance checkbox—it's a risk management tool
-- that identifies and mitigates privacy risks before they materialize.
--
-- The business impact is substantial: DPIAs demonstrate proactive compliance
-- to regulators, potentially reducing fines if breaches occur. They build user
-- trust by ensuring privacy risks are identified and addressed. For product
-- teams, they provide a framework for privacy by design, embedding privacy
-- considerations into new features from the start.
--
-- The design captures everything required for a compliant DPIA: systematic
-- description of processing, necessity and proportionality assessment, risk
-- identification with severity ratings, proposed mitigation measures, residual
-- risk assessment, and stakeholder consultations (including DPO and data subjects).
-- It supports the full lifecycle from screening through approval to ongoing
-- monitoring.
--
-- Key Performance Indicators (KPIs):
--   1. DPIA Coverage: Percentage of high-risk activities with current DPIA (100%)
--   2. Completion Time: Average days from identification to DPIA approval (<30)
--   3. Risk Mitigation Effectiveness: Percentage of identified risks mitigated
--   4. Review Compliance: Percentage of DPIAs reviewed within required timeframe
--   5. Consultation Rate: Percentage of DPIAs requiring authority consultation
--   6. Quality Score: Internal/external audit rating of DPIA quality
--   7. Action Closure Rate: Percentage of mitigation actions completed on time
--
-- Feature Reference: GDPR-04, ART35-01, RISK-01
-- Requirements Traceability: GDPR Article 35, Article 36, WP29 Guidelines on DPIA
--
-- Normalization: 3NF - DPIAs independent with versioning and approvals
--
-- High-Write Considerations:
--   - Write-light (DPIAs created for new high-risk processing)
--   - Read-heavy for audits and reviews
--   - JSONB for flexible risk and mitigation documentation
--   - Partial indexes for active DPIAs only
-------------------------------------------------------------------------------
CREATE TABLE public.data_protection_impact_assessments (
    -- Primary key
    dpia_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    dpia_reference VARCHAR(50) NOT NULL UNIQUE,
    dpia_title VARCHAR(500) NOT NULL,
    dpia_version VARCHAR(20) NOT NULL,
    dpia_status public.dpia_status NOT NULL DEFAULT 'SCREENING',

    -- Relationship to processing
    processing_register_id UUID REFERENCES public.data_processing_register(register_id) ON DELETE SET NULL,
    processing_activity_id VARCHAR(50),
    processing_description TEXT NOT NULL,

    -- Scope definition
    scope_description TEXT NOT NULL,
    data_subjects_affected TEXT[] NOT NULL,
    data_categories_affected public.data_category_gdpr[] NOT NULL,
    data_volume_estimate VARCHAR(100),
    data_subject_count_estimate INTEGER,

    -- Necessity and proportionality
    necessity_assessment TEXT NOT NULL,
    proportionality_assessment TEXT NOT NULL,
    public_interest_justification TEXT,
    less_intrusive_means_considered TEXT,
    less_intrusive_means_rejection_reason TEXT,

    -- Risk assessment
    risk_identification_date DATE NOT NULL DEFAULT CURRENT_DATE,
    risk_assessment_methodology VARCHAR(200),
    inherent_risk_score NUMERIC(5,2) CHECK (inherent_risk_score >= 0 AND inherent_risk_score <= 100),
    inherent_risk_level VARCHAR(20) CHECK (inherent_risk_level IN ('VERY_LOW', 'LOW', 'MEDIUM', 'HIGH', 'VERY_HIGH')),

    -- Identified risks (JSON structure for flexibility)
    identified_risks JSONB NOT NULL DEFAULT '[]'::JSONB,

    -- Mitigation measures
    proposed_mitigations JSONB NOT NULL DEFAULT '[]'::JSONB,
    residual_risk_score NUMERIC(5,2) CHECK (residual_risk_score >= 0 AND residual_risk_score <= 100),
    residual_risk_level VARCHAR(20) CHECK (residual_risk_level IN ('VERY_LOW', 'LOW', 'MEDIUM', 'HIGH', 'VERY_HIGH')),
    risk_acceptance_justification TEXT,

    -- Stakeholder consultation
    data_subject_views_sought BOOLEAN DEFAULT false,
    data_subject_consultation_method TEXT,
    data_subject_consultation_summary TEXT,
    dpo_consulted BOOLEAN DEFAULT true,
    dpo_opinion TEXT,
    dpo_consultation_date DATE,

    -- Supervisory authority consultation (Article 36)
    authority_consultation_required BOOLEAN DEFAULT false,
    authority_consultation_date DATE,
    authority_consulted VARCHAR(500),
    authority_reference VARCHAR(200),
    authority_opinion TEXT,
    authority_opinion_date DATE,

    -- Approvals
    dpia_author_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    dpia_author_name VARCHAR(500) NOT NULL,
    dpia_reviewer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    dpia_review_date DATE,
    dpia_review_comments TEXT,
    dpia_approver_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    dpia_approval_date DATE,
    dpia_approval_conditions TEXT,

    -- Lifecycle management
    effective_from DATE NOT NULL DEFAULT CURRENT_DATE,
    effective_to DATE,
    review_date DATE NOT NULL DEFAULT (CURRENT_DATE + INTERVAL '1 year'),
    last_review_date DATE,
    next_review_date DATE GENERATED ALWAYS AS (
        CASE
            WHEN residual_risk_level IN ('HIGH', 'VERY_HIGH') THEN last_review_date + INTERVAL '6 months'
            ELSE last_review_date + INTERVAL '1 year'
        END
    ) STORED,

    -- Change history
    previous_version_id UUID REFERENCES public.data_protection_impact_assessments(dpia_id) ON DELETE SET NULL,
    change_description TEXT,
    change_reason TEXT,

    -- Documentation
    supporting_documents JSONB,
    dpia_document_url TEXT,
    attachments TEXT[],

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    business_unit VARCHAR(200),
    project_name VARCHAR(500),
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_dpia_dates CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT valid_risk_scores CHECK (
        (inherent_risk_score IS NULL AND inherent_risk_level IS NULL) OR
        (inherent_risk_score IS NOT NULL AND inherent_risk_level IS NOT NULL)
    ),
    CONSTRAINT valid_review_date CHECK (review_date >= effective_from)
);

COMMENT ON TABLE public.data_protection_impact_assessments IS 'GDPR Article 35 Data Protection Impact Assessments with risk mitigation tracking';
COMMENT ON COLUMN public.data_protection_impact_assessments.dpia_id IS 'Primary key';
COMMENT ON COLUMN public.data_protection_impact_assessments.dpia_status IS 'Current status in review/approval workflow';
COMMENT ON COLUMN public.data_protection_impact_assessments.processing_register_id IS 'Reference to the processing activity this DPIA covers';
COMMENT ON COLUMN public.data_protection_impact_assessments.identified_risks IS 'JSON array of identified risks with assessments';
COMMENT ON COLUMN public.data_protection_impact_assessments.proposed_mitigations IS 'JSON array of mitigation measures and status';
COMMENT ON COLUMN public.data_protection_impact_assessments.residual_risk_level IS 'Risk level after mitigation measures applied';

-- Indexes
CREATE INDEX idx_dpia_processing_register ON public.data_protection_impact_assessments(processing_register_id);
CREATE INDEX idx_dpia_status ON public.data_protection_impact_assessments(dpia_status);
CREATE INDEX idx_dpia_residual_risk ON public.data_protection_impact_assessments(residual_risk_level) WHERE dpia_status = 'APPROVED';
CREATE INDEX idx_dpia_next_review ON public.data_protection_impact_assessments(next_review_date) WHERE dpia_status IN ('APPROVED', 'CONDITIONALLY_APPROVED');
CREATE INDEX idx_dpia_effective_dates ON public.data_protection_impact_assessments(effective_from, effective_to);
CREATE INDEX idx_dpia_previous_version ON public.data_protection_impact_assessments(previous_version_id);

-- Trigger for updated_at
CREATE TRIGGER update_data_protection_impact_assessments_timestamp
    BEFORE UPDATE ON public.data_protection_impact_assessments
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.data_protection_impact_assessments ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY data_protection_impact_assessments_access_policy ON public.data_protection_impact_assessments
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'compliance_officer', 'admin', 'process_owner')
    ));

-- =============================================================================
-- TABLE 45: data_breach_log
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 45
-- Table Name: data_breach_log
-- Description: Comprehensive log of personal data breaches with investigation
--              details, notification tracking, remediation measures, and
--              compliance with Articles 33-34 notification requirements.
--
-- Business Case (300 words):
-- Articles 33 and 34 of the GDPR establish mandatory breach notification
-- requirements: notification to supervisory authority within 72 hours, and
-- communication to affected data subjects without undue delay when the breach
-- poses a high risk. This table serves as the official record of all breach
-- incidents, ensuring timely detection, complete documentation, and compliance
-- with notification deadlines.
--
-- Without a structured breach log, organizations cannot demonstrate compliance
-- with notification requirements, risking fines up to 2% of global revenue.
-- They cannot conduct proper root cause analysis, identify patterns, or
-- implement preventive measures. During audits or investigations, the lack of
-- documentation creates significant compliance risk.
--
-- The business impact is critical: the breach log provides evidence of compliance
-- to regulators, potentially reducing fines. It enables rapid incident response
-- by documenting containment and remediation actions. Post-incident analysis
-- identifies root causes and prevents recurrence. For customers, transparent
-- breach handling maintains trust even when incidents occur.
--
-- The design captures the entire breach lifecycle: detection, investigation,
-- containment, notification, remediation, and closure. It tracks notification
-- deadlines automatically, flagging when the 72-hour window is at risk. All
-- communication with authorities and data subjects is documented, including
-- content and timing. Lessons learned feed into security improvements.
--
-- Key Performance Indicators (KPIs):
--   1. Detection Time: Average hours from occurrence to detection (<24h)
--   2. Response Time: Average hours from detection to containment (<4h)
--   3. Notification Compliance: Percentage notified within 72-hour deadline (100%)
--   4. Breach Severity Distribution: Count by severity level
--   5. Root Cause Categories: Most common breach causes
--   6. Repeat Incident Rate: Percentage of recurring breach types (<5%)
--   7. Remediation Effectiveness: Percentage with successful prevention measures
--
-- Feature Reference: GDPR-05, BREACH-01, SEC-01
-- Requirements Traceability: GDPR Article 33, Article 34, Article 5(1)(f)
--
-- Normalization: 3NF - Breaches independent with comprehensive tracking
--
-- High-Write Considerations:
--   - Low write volume (breaches are rare)
--   - Read-heavy during incident response and audits
--   - JSONB for flexible investigation data
--   - Partial indexes for open breaches only
-------------------------------------------------------------------------------
CREATE TABLE public.data_breach_log (
    -- Primary key
    breach_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    breach_reference VARCHAR(50) NOT NULL UNIQUE,
    breach_name VARCHAR(500),
    breach_status public.breach_status NOT NULL DEFAULT 'DETECTED',

    -- Timeline
    occurrence_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    detection_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    detection_lag_minutes INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (detection_timestamp - occurrence_timestamp)) / 60
    ) STORED,
    investigation_started_at TIMESTAMP WITH TIME ZONE,
    containment_timestamp TIMESTAMP WITH TIME ZONE,
    resolution_timestamp TIMESTAMP WITH TIME ZONE,
    closure_timestamp TIMESTAMP WITH TIME ZONE,

    -- Detection source
    detection_method VARCHAR(100) CHECK (detection_method IN (
        'INTERNAL_DETECTION', 'EXTERNAL_REPORT', 'AUDIT_FINDING',
        'SECURITY_TOOL', 'USER_REPORT', 'LAW_ENFORCEMENT', 'REGULATOR', 'OTHER'
    )),
    detected_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    detection_details TEXT,

    -- Breach classification
    breach_type VARCHAR(100) NOT NULL CHECK (breach_type IN (
        'UNAUTHORIZED_ACCESS', 'DATA_LOSS', 'DATA_DESTRUCTION',
        'DATA_ALTERATION', 'DATA_DISCLOSURE', 'PHISHING_ATTACK',
        'MALWARE_INFECTION', 'INSIDER_THREAT', 'LOST_DEVICE',
        'STOLEN_DEVICE', 'MISCONFIGURATION', 'THIRD_PARTY_BREACH',
        'PHYSICAL_BREACH', 'SOCIAL_ENGINEERING', 'UNKNOWN'
    )),
    breach_cause TEXT NOT NULL,
    breach_cause_category VARCHAR(100),
    breach_severity public.breach_severity NOT NULL,

    -- Affected data
    data_categories_affected public.data_category_gdpr[] NOT NULL,
    special_category_data_affected BOOLEAN DEFAULT false,
    data_volume_estimate INTEGER,  -- Estimated records affected
    data_volume_actual INTEGER,     -- Actual count after investigation
    data_sensitivity_rating VARCHAR(20) CHECK (data_sensitivity_rating IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),

    -- Affected individuals
    data_subjects_affected_estimate INTEGER,
    data_subjects_affected_actual INTEGER,
    data_subjects_minors_affected BOOLEAN DEFAULT false,
    vulnerable_subjects_affected BOOLEAN DEFAULT false,
    data_subjects_list TEXT,        -- Description of affected groups
    affected_geographies TEXT[],     -- Countries/regions affected

    -- Affected systems
    affected_systems TEXT[],
    affected_applications TEXT[],
    affected_databases TEXT[],
    affected_third_parties TEXT[],

    -- Investigation details
    investigation_lead_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    investigation_team TEXT[],
    investigation_summary TEXT,
    root_cause_analysis TEXT,
    forensic_analysis_reference TEXT,
    evidence_preserved BOOLEAN DEFAULT false,
    evidence_location TEXT,

    -- Risk assessment
    risk_to_rights_assessment TEXT,
    risk_level_assessed VARCHAR(20) CHECK (risk_level_assessed IN ('NO_RISK', 'LOW', 'MEDIUM', 'HIGH', 'VERY_HIGH')),
    risk_assessment_date DATE,
    risk_assessment_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Containment measures
    containment_actions TEXT[],
    containment_effectiveness VARCHAR(20),
    data_recovered BOOLEAN DEFAULT false,
    recovery_percentage INTEGER CHECK (recovery_percentage BETWEEN 0 AND 100),

    -- Notification to supervisory authority (Article 33)
    authority_notification_required BOOLEAN GENERATED ALWAYS AS (
        breach_severity IN ('HIGH', 'CRITICAL', 'MEDIUM')
    ) STORED,
    authority_notification_sent BOOLEAN DEFAULT false,
    authority_notification_date TIMESTAMP WITH TIME ZONE,
    authority_notification_within_72h BOOLEAN GENERATED ALWAYS AS (
        authority_notification_date IS NOT NULL AND
        EXTRACT(EPOCH FROM (authority_notification_date - detection_timestamp)) <= 72 * 3600
    ) STORED,
    authority_notified VARCHAR(500),
    authority_reference VARCHAR(200),
    authority_response TEXT,
    authority_fines NUMERIC(15,2),
    authority_fines_currency CHAR(3),

    -- Notification to data subjects (Article 34)
    data_subject_notification_required BOOLEAN GENERATED ALWAYS AS (
        risk_level_assessed IN ('HIGH', 'VERY_HIGH')
    ) STORED,
    data_subject_notification_sent BOOLEAN DEFAULT false,
    data_subject_notification_date TIMESTAMP WITH TIME ZONE,
    data_subject_notification_method VARCHAR(100),
    data_subject_notification_content TEXT,
    data_subject_notification_count INTEGER,
    public_communication_made BOOLEAN DEFAULT false,
    public_communication_url TEXT,

    -- Media and public relations
    media_attention BOOLEAN DEFAULT false,
    media_coverage TEXT[],
    pr_statement_issued BOOLEAN DEFAULT false,
    pr_statement_url TEXT,

    -- Remediation and prevention
    corrective_actions TEXT[],
    corrective_actions_deadline DATE,
    corrective_actions_completed DATE,
    preventive_measures TEXT[],
    security_improvements TEXT[],
    policy_updates TEXT[],
    training_conducted BOOLEAN DEFAULT false,

    -- Legal and compliance
    legal_notification_sent BOOLEAN DEFAULT false,
    legal_counsel_involved BOOLEAN DEFAULT false,
    legal_counsel_name VARCHAR(500),
    insurance_claim_filed BOOLEAN DEFAULT false,
    insurance_claim_reference VARCHAR(200),
    insurance_payout NUMERIC(15,2),

    -- Lessons learned
    post_incident_review_date DATE,
    post_incident_review_summary TEXT,
    lessons_learned TEXT[],
    recommendations TEXT[],
    action_items JSONB,

    -- Documentation
    incident_report_url TEXT,
    investigation_report_url TEXT,
    notification_proof_url TEXT,
    attachments TEXT[],

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    reported_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    business_unit VARCHAR(200),
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_breach_timeline CHECK (
        detection_timestamp >= occurrence_timestamp AND
        (containment_timestamp IS NULL OR containment_timestamp >= detection_timestamp) AND
        (resolution_timestamp IS NULL OR resolution_timestamp >= containment_timestamp) AND
        (closure_timestamp IS NULL OR closure_timestamp >= resolution_timestamp)
    )
);

COMMENT ON TABLE public.data_breach_log IS 'GDPR Article 33-34 personal data breach register with full incident lifecycle';
COMMENT ON COLUMN public.data_breach_log.breach_id IS 'Primary key';
COMMENT ON COLUMN public.data_breach_log.breach_reference IS 'Human-readable reference number';
COMMENT ON COLUMN public.data_breach_log.detection_lag_minutes IS 'Time from occurrence to detection (calculated)';
COMMENT ON COLUMN public.data_breach_log.authority_notification_within_72h IS 'Flag indicating if 72-hour deadline was met';
COMMENT ON COLUMN public.data_breach_log.data_subject_notification_required IS 'Generated flag if notification to data subjects is required';

-- Indexes
CREATE INDEX idx_breach_log_status ON public.data_breach_log(breach_status);
CREATE INDEX idx_breach_log_severity ON public.data_breach_log(breach_severity);
CREATE INDEX idx_breach_log_occurrence ON public.data_breach_log(occurrence_timestamp DESC);
CREATE INDEX idx_breach_log_detection ON public.data_breach_log(detection_timestamp DESC);
CREATE INDEX idx_breach_log_authority_notification ON public.data_breach_log(authority_notification_sent, authority_notification_date);
CREATE INDEX idx_breach_log_data_categories ON public.data_breach_log USING gin(data_categories_affected);
CREATE INDEX idx_breach_log_breach_type ON public.data_breach_log(breach_type);
CREATE INDEX idx_breach_log_reported_by ON public.data_breach_log(reported_by);

-- Trigger for updated_at
CREATE TRIGGER update_data_breach_log_timestamp
    BEFORE UPDATE ON public.data_breach_log
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.data_breach_log ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY data_breach_log_security_policy ON public.data_breach_log
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'security_officer', 'compliance_officer', 'admin', 'legal_counsel')
    ));

-- =============================================================================
-- TABLE 46: consent_records
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 46
-- Table Name: consent_records
-- Description: Comprehensive consent management with proof of consent,
--              withdrawal tracking, consent versioning, and audit trail for
--              GDPR Article 7 compliance.
--
-- Business Case (300 words):
-- Under GDPR Article 7, organizations must be able to demonstrate that consent
-- was obtained. This requires record of when and how consent was obtained,
-- clear affirmative action evidence, separate consent for different purposes,
-- right to withdraw consent as easily as it was given, and proof that consent
-- was informed and specific.
--
-- Without proper consent records, organizations cannot prove compliance with
-- Article 7, risking significant fines. They cannot honor withdrawal requests
-- consistently, leading to continued processing after consent is revoked.
-- During audits, the lack of evidence creates significant compliance risk.
--
-- The business impact is direct: consent records provide the evidence needed
-- to demonstrate compliance to regulators. They enable automated enforcement
-- of consent preferences across all systems. Withdrawal tracking ensures that
-- user choices are respected, building trust. Consent versioning protects
-- against claims that users weren't properly informed.
--
-- The design captures everything required: the exact consent language the user
-- agreed to (versioned), technical proof (IP address, user agent, timestamp),
-- withdrawal tracking with confirmation, and consent expiry for time-limited
-- consent. It supports special category consent under Article 9 and parental
-- consent for minors under Article 8.
--
-- Key Performance Indicators (KPIs):
--   1. Consent Rate: Percentage of users providing consent by purpose
--   2. Withdrawal Rate: Percentage of users withdrawing consent
--   3. Consent Freshness: Percentage of consents renewed within expiry period
--   4. Audit Completeness: Percentage of consents with complete proof data (100%)
--   5. Channel Distribution: Consent rates by acquisition channel
--   6. Time to Withdrawal: Average days from grant to withdrawal
--   7. Re-consent Success Rate: Percentage successfully re-consented after expiry
--
-- Feature Reference: GDPR-06, CONSENT-01
-- Requirements Traceability: GDPR Article 4(11), Article 6(1)(a), Article 7, Article 8, Article 9(2)(a)
--
-- Normalization: 3NF - Consents per user and purpose with versioning
--
-- High-Write Considerations:
--   - Moderate write volume (consent changes when users update preferences)
--   - Read-heavy for every processing decision
--   - Partitioned by created_at for historical queries
--   - Partial indexes for active consents only
-------------------------------------------------------------------------------
CREATE TABLE public.consent_records (
    -- Primary key
    consent_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User identification
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    user_email VARCHAR(255) NOT NULL,  -- Denormalized for audit
    user_type VARCHAR(50) DEFAULT 'REGISTERED' CHECK (user_type IN ('REGISTERED', 'ANONYMOUS', 'GUEST')),

    -- Consent purpose
    purpose_id UUID NOT NULL,  -- References purposes table (can be extended)
    purpose_name VARCHAR(200) NOT NULL,
    purpose_category VARCHAR(100) CHECK (purpose_category IN (
        'ACCOUNT', 'MARKETING', 'ANALYTICS', 'THIRD_PARTY',
        'PROFILING', 'LOCATION', 'COMMUNICATIONS', 'RESEARCH', 'SPECIAL_CATEGORY'
    )),
    purpose_description TEXT,

    -- Consent version (tracking changes in consent language)
    consent_version VARCHAR(50) NOT NULL,
    consent_language TEXT,  -- The exact text the user agreed to
    consent_language_hash TEXT,  -- For integrity verification

    -- Consent status
    status public.consent_status NOT NULL DEFAULT 'NOT_PROVIDED',
    status_reason TEXT,  -- e.g., 'withdrawn_via_portal', 'expired'

    -- Grant details
    granted_at TIMESTAMP WITH TIME ZONE,
    granted_method VARCHAR(100) CHECK (granted_method IN (
        'WEB_FORM', 'MOBILE_APP', 'EMAIL', 'API', 'CUSTOMER_SERVICE',
        'SIGNUP_FLOW', 'SETTINGS_PAGE', 'MARKETING_PREFERENCE_CENTER', 'OTHER'
    )),
    granted_url TEXT,  -- URL where consent was obtained
    granted_page TEXT,  -- Page/screen identifier

    -- Technical proof of consent
    ip_address INET,
    user_agent TEXT,
    device_id VARCHAR(255),
    session_id UUID,
    proof_payload JSONB,  -- Full technical details
    consent_fingerprint TEXT UNIQUE,  -- Cryptographic hash of consent event

    -- Withdrawal details
    withdrawn_at TIMESTAMP WITH TIME ZONE,
    withdrawn_method VARCHAR(100),
    withdrawn_reason TEXT,
    withdrawn_confirmation_sent BOOLEAN DEFAULT false,
    withdrawn_confirmation_at TIMESTAMP WITH TIME ZONE,

    -- Expiry and renewal
    consent_expires_at TIMESTAMP WITH TIME ZONE,
    renewal_notification_sent BOOLEAN DEFAULT false,
    renewal_notification_at TIMESTAMP WITH TIME ZONE,
    renewed_consent_id UUID REFERENCES public.consent_records(consent_id) ON DELETE SET NULL,  -- Chain for renewals

    -- Special category consent (Article 9)
    is_special_category BOOLEAN DEFAULT false,
    special_category_type VARCHAR(100),
    explicit_consent_obtained BOOLEAN DEFAULT false,
    explicit_consent_proof TEXT,

    -- Parental consent for minors (Article 8)
    is_minor BOOLEAN DEFAULT false,
    parental_consent_obtained BOOLEAN DEFAULT false,
    parent_user_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    parent_email VARCHAR(255),
    parental_consent_proof TEXT,
    parental_consent_at TIMESTAMP WITH TIME ZONE,

    -- Channel-specific consent
    channels JSONB,  -- e.g., {"email": true, "sms": false, "push": true}

    -- Data processing restrictions
    processing_restrictions JSONB,  -- Purpose-specific limitations

    -- Compliance documentation
    dpia_reference UUID REFERENCES public.data_protection_impact_assessments(dpia_id) ON DELETE SET NULL,
    legal_basis_documentation TEXT,

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    source_system VARCHAR(100),
    campaign_id VARCHAR(100),  -- For marketing campaign tracking
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_consent_timeline CHECK (
        (granted_at IS NOT NULL AND status IN ('GRANTED', 'RENEWED')) OR
        (granted_at IS NULL AND status IN ('NOT_PROVIDED', 'REJECTED'))
    ),
    CONSTRAINT valid_withdrawal_timeline CHECK (
        withdrawn_at IS NULL OR
        (withdrawn_at IS NOT NULL AND granted_at IS NOT NULL AND withdrawn_at > granted_at)
    ),
    CONSTRAINT valid_expiry CHECK (
        consent_expires_at IS NULL OR
        (consent_expires_at IS NOT NULL AND (granted_at IS NULL OR consent_expires_at > granted_at))
    ),
    CONSTRAINT parental_consent_consistency CHECK (
        (is_minor = true AND parental_consent_obtained = true AND parent_user_id IS NOT NULL) OR
        (is_minor = false)
    ),
    CONSTRAINT special_category_consistency CHECK (
        (is_special_category = true AND explicit_consent_obtained = true) OR
        (is_special_category = false)
    )
);

COMMENT ON TABLE public.consent_records IS 'GDPR Article 7 consent management with complete proof and audit trail';
COMMENT ON COLUMN public.consent_records.consent_id IS 'Primary key';
COMMENT ON COLUMN public.consent_records.user_id IS 'User who provided consent';
COMMENT ON COLUMN public.consent_records.consent_fingerprint IS 'Cryptographic hash of consent event for integrity';
COMMENT ON COLUMN public.consent_records.ip_address IS 'IP address at time of consent (technical proof)';
COMMENT ON COLUMN public.consent_records.user_agent IS 'User agent at time of consent (technical proof)';
COMMENT ON COLUMN public.consent_records.parental_consent_obtained IS 'Flag indicating parental consent for minors under Article 8';

-- Indexes
CREATE INDEX idx_consent_records_user_id ON public.consent_records(user_id);
CREATE INDEX idx_consent_records_purpose ON public.consent_records(purpose_id, status);
CREATE INDEX idx_consent_records_status ON public.consent_records(status, consent_expires_at);
CREATE INDEX idx_consent_records_granted_at ON public.consent_records(granted_at DESC);
CREATE INDEX idx_consent_records_fingerprint ON public.consent_records(consent_fingerprint);
CREATE INDEX idx_consent_records_ip ON public.consent_records(ip_address);
CREATE INDEX idx_consent_records_special_category ON public.consent_records(is_special_category) WHERE is_special_category = true;
CREATE INDEX idx_consent_records_minor ON public.consent_records(is_minor) WHERE is_minor = true;

-- Trigger for updated_at
CREATE TRIGGER update_consent_records_timestamp
    BEFORE UPDATE ON public.consent_records
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to record consent withdrawal
CREATE OR REPLACE FUNCTION public.withdraw_consent(
    p_user_id UUID,
    p_purpose_id UUID,
    p_withdrawn_method VARCHAR(100),
    p_withdrawn_reason TEXT DEFAULT NULL
)
RETURNS UUID AS $$
DECLARE
    v_consent_id UUID;
BEGIN
    UPDATE public.consent_records
    SET
        status = 'WITHDRAWN',
        withdrawn_at = CURRENT_TIMESTAMP,
        withdrawn_method = p_withdrawn_method,
        withdrawn_reason = p_withdrawn_reason,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = current_user_id()
    WHERE user_id = p_user_id
        AND purpose_id = p_purpose_id
        AND status = 'GRANTED'
    RETURNING consent_id INTO v_consent_id;

    -- Log the withdrawal for audit
    INSERT INTO public.audit_logs (
        actor_id,
        action,
        entity_type,
        entity_id,
        details,
        category,
        severity
    ) VALUES (
        current_user_id(),
        'WITHDRAW_CONSENT',
        'consent_records',
        v_consent_id,
        jsonb_build_object(
            'user_id', p_user_id,
            'purpose_id', p_purpose_id,
            'method', p_withdrawn_method,
            'reason', p_withdrawn_reason
        ),
        'COMPLIANCE',
        'INFO'
    );

    RETURN v_consent_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.withdraw_consent IS 'Records consent withdrawal with audit trail';

-- Enable RLS
ALTER TABLE public.consent_records ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY consent_records_user_policy ON public.consent_records
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY consent_records_compliance_policy ON public.consent_records
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'compliance_officer', 'admin', 'auditor')
    ));

-- =============================================================================
-- TABLE 47: data_subject_requests
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 47
-- Table Name: data_subject_requests
-- Description: Manages GDPR data subject rights requests (Articles 12-23) with
--              SLA tracking, identity verification workflow, and fulfillment
--              monitoring.
--
-- Business Case (300 words):
-- GDPR grants individuals eight fundamental rights regarding their personal data.
-- Organizations must have a systematic process for receiving, verifying, and
-- responding to these requests within strict deadlines (generally one month).
-- This table manages the entire request lifecycle: receipt and acknowledgment,
-- identity verification, request tracking against SLA deadlines, fulfillment
-- workflow, response delivery, and appeals handling.
--
-- Without a structured request management system, organizations cannot meet
-- the strict 30-day deadline, risking fines and regulatory action. Requests
-- can be lost, identity verification can be inconsistent, and there's no audit
-- trail of how requests were handled. This table provides the infrastructure
-- needed to manage DSARs at scale.
--
-- The business impact is direct: compliance with rights requests demonstrates
-- respect for individual privacy, building trust. Systematic tracking ensures
-- no request falls through cracks, reducing regulatory risk. The audit trail
-- provides evidence of compliance during investigations. For complex requests,
-- extension tracking ensures deadlines are met or properly extended.
--
-- The design supports all eight rights: access, rectification, erasure,
-- restriction, portability, objection, automated decision-making, and information.
-- It tracks the entire workflow from receipt through completion, with detailed
-- logging of actions taken. Identity verification steps are documented to
-- prevent unauthorized access to personal data.
--
-- Key Performance Indicators (KPIs):
--   1. SLA Compliance: Percentage of requests completed within legal deadline (100%)
--   2. Request Volume: Number of requests by type per month
--   3. Average Fulfillment Time: Days to complete by request type
--   4. Verification Success Rate: Percentage of identities successfully verified
--   5. Appeal Rate: Percentage of decisions appealed (<5%)
--   6. Extension Rate: Percentage of requests requiring deadline extension (<10%)
--   7. Rejection Rate: Percentage of requests rejected with legal basis (<5%)
--
-- Feature Reference: GDPR-07, DSR-01, SLA-01
-- Requirements Traceability: GDPR Articles 12-23 (Data Subject Rights)
--
-- Normalization: 3NF - Requests independent with status tracking
--
-- High-Write Considerations:
--   - Moderate write volume (updates as requests progress)
--   - Read-heavy for SLA monitoring and audits
--   - Partitioning by created_at recommended for large volumes
--   - Partial indexes for open requests only
-------------------------------------------------------------------------------
CREATE TABLE public.data_subject_requests (
    -- Primary key
    request_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    request_number VARCHAR(50) NOT NULL UNIQUE,
    request_type public.dsar_request_type NOT NULL,
    request_subtype VARCHAR(100),  -- For complex requests

    -- Requester information
    requester_user_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    requester_email VARCHAR(255) NOT NULL,
    requester_name VARCHAR(500),
    requester_phone VARCHAR(50),
    requester_address TEXT,
    requester_country VARCHAR(3),
    is_requester_verified BOOLEAN DEFAULT false,

    -- Representative (if request made by representative)
    representative_name VARCHAR(500),
    representative_email VARCHAR(255),
    representative_relationship TEXT,
    proof_of_authority TEXT,

    -- Request details
    request_received_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    request_details TEXT NOT NULL,
    request_language VARCHAR(10) DEFAULT 'en',
    request_source VARCHAR(50) CHECK (request_source IN (
        'WEB_FORM', 'EMAIL', 'PORTAL', 'API', 'PHONE', 'MAIL', 'IN_PERSON', 'THIRD_PARTY'
    )),
    request_reference VARCHAR(200),  -- External reference

    -- Identity verification
    identity_verification_required BOOLEAN DEFAULT true,
    identity_verified_at TIMESTAMP WITH TIME ZONE,
    identity_verified_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    identity_verification_method VARCHAR(100),
    identity_verification_proof TEXT,
    identity_verification_notes TEXT,

    -- Timeline management
    acknowledgment_sent_at TIMESTAMP WITH TIME ZONE,
    acknowledgment_deadline TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (
        request_received_at + INTERVAL '3 days'
    ) STORED,

    response_deadline TIMESTAMP WITH TIME ZONE NOT NULL,
    extension_applied BOOLEAN DEFAULT false,
    extension_reason TEXT,
    extension_granted_at TIMESTAMP WITH TIME ZONE,
    extension_approved_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    new_response_deadline TIMESTAMP WITH TIME ZONE,

    -- Processing status
    status public.dsar_request_status NOT NULL DEFAULT 'RECEIVED',
    status_history JSONB DEFAULT '[]'::JSONB,

    -- Assignment
    assigned_to UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    assigned_at TIMESTAMP WITH TIME ZONE,
    assigned_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Processing team
    primary_processor_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    secondary_processors UUID[],
    legal_reviewer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    dpo_review_required BOOLEAN DEFAULT false,
    dpo_reviewed_at TIMESTAMP WITH TIME ZONE,
    dpo_review_notes TEXT,

    -- Data discovery
    data_discovery_completed BOOLEAN DEFAULT false,
    data_discovery_summary TEXT,
    systems_searched TEXT[],
    data_categories_found public.data_category_gdpr[],
    data_volume_found BIGINT,
    data_locations_found TEXT[],
    third_parties_involved TEXT[],

    -- For access requests (Article 15)
    access_response_provided BOOLEAN DEFAULT false,
    access_response_format VARCHAR(50),
    access_response_url TEXT,
    access_response_provided_at TIMESTAMP WITH TIME ZONE,

    -- For rectification requests (Article 16)
    rectification_made BOOLEAN DEFAULT false,
    rectification_details TEXT,
    rectification_made_at TIMESTAMP WITH TIME ZONE,

    -- For erasure requests (Article 17)
    erasure_completed BOOLEAN DEFAULT false,
    erasure_details TEXT,
    erasure_completed_at TIMESTAMP WITH TIME ZONE,
    erasure_verification_method TEXT,

    -- For restriction requests (Article 18)
    restriction_applied BOOLEAN DEFAULT false,
    restriction_details TEXT,
    restriction_lifted_at TIMESTAMP WITH TIME ZONE,

    -- For portability requests (Article 20)
    portability_format VARCHAR(20) CHECK (portability_format IN ('JSON', 'XML', 'CSV', 'PDF')),
    portability_data_provided BOOLEAN DEFAULT false,
    portability_provided_at TIMESTAMP WITH TIME ZONE,
    portability_download_url TEXT,
    portability_download_expires_at TIMESTAMP WITH TIME ZONE,
    portability_size_bytes BIGINT,

    -- For objection requests (Article 21)
    objection_assessment TEXT,
    objection_upheld BOOLEAN,
    objection_response TEXT,

    -- For automated decision requests (Article 22)
    automated_decision_details TEXT,
    human_review_provided BOOLEAN DEFAULT false,
    human_review_results TEXT,
    human_reviewer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Fees and charges (GDPR allows fees for manifestly unfounded/excessive)
    fee_charged NUMERIC(10,2),
    fee_currency CHAR(3),
    fee_justification TEXT,
    fee_paid BOOLEAN DEFAULT false,

    -- Response delivery
    response_sent_at TIMESTAMP WITH TIME ZONE,
    response_method VARCHAR(50) CHECK (response_method IN ('EMAIL', 'PORTAL', 'MAIL', 'API', 'IN_PERSON')),
    response_recipient VARCHAR(255),
    response_confirmation_received BOOLEAN DEFAULT false,
    response_confirmation_at TIMESTAMP WITH TIME ZONE,

    -- Rejection (if applicable)
    rejection_reason TEXT,
    rejection_legal_basis TEXT,
    rejection_advice_given TEXT,
    rejection_appeal_rights_explained BOOLEAN DEFAULT true,

    -- Appeal (if requester appeals)
    appeal_received BOOLEAN DEFAULT false,
    appeal_received_at TIMESTAMP WITH TIME ZONE,
    appeal_details TEXT,
    appeal_outcome TEXT,
    appeal_outcome_at TIMESTAMP WITH TIME ZONE,

    -- Documentation
    supporting_documents JSONB,
    correspondence_log JSONB DEFAULT '[]'::JSONB,

    -- Quality assurance
    quality_review_required BOOLEAN DEFAULT false,
    quality_reviewed_at TIMESTAMP WITH TIME ZONE,
    quality_reviewer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    quality_score INTEGER CHECK (quality_score IS NULL OR (quality_score BETWEEN 1 AND 5)),
    quality_notes TEXT,

    -- Metrics
    processing_days INTEGER GENERATED ALWAYS AS (
        EXTRACT(DAY FROM (COALESCE(response_sent_at, CURRENT_TIMESTAMP) - request_received_at))
    ) STORED,
    sla_met BOOLEAN GENERATED ALWAYS AS (
        response_sent_at IS NOT NULL AND response_sent_at <=
        COALESCE(new_response_deadline, response_deadline)
    ) STORED,

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    department VARCHAR(200),
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_response_deadline CHECK (response_deadline > request_received_at),
    CONSTRAINT valid_extension CHECK (
        (extension_applied = true AND extension_reason IS NOT NULL AND new_response_deadline IS NOT NULL) OR
        (extension_applied = false)
    ),
    CONSTRAINT valid_fee CHECK (
        (fee_charged IS NULL AND fee_paid = false) OR
        (fee_charged IS NOT NULL)
    )
);

COMMENT ON TABLE public.data_subject_requests IS 'GDPR Articles 12-23 data subject rights request management with SLA tracking';
COMMENT ON COLUMN public.data_subject_requests.request_id IS 'Primary key';
COMMENT ON COLUMN public.data_subject_requests.request_number IS 'Human-readable request reference number';
COMMENT ON COLUMN public.data_subject_requests.acknowledgment_deadline IS '3-day deadline for acknowledgment (GDPR best practice)';
COMMENT ON COLUMN public.data_subject_requests.response_deadline IS 'Legal deadline for response (generally 30 days)';
COMMENT ON COLUMN public.data_subject_requests.sla_met IS 'Generated flag indicating if response met legal deadline';

-- Indexes
CREATE INDEX idx_dsr_user_id ON public.data_subject_requests(requester_user_id);
CREATE INDEX idx_dsr_email ON public.data_subject_requests(requester_email);
CREATE INDEX idx_dsr_type ON public.data_subject_requests(request_type);
CREATE INDEX idx_dsr_status ON public.data_subject_requests(status);
CREATE INDEX idx_dsr_response_deadline ON public.data_subject_requests(response_deadline) WHERE status NOT IN ('COMPLETED', 'REJECTED');
CREATE INDEX idx_dsr_assigned_to ON public.data_subject_requests(assigned_to) WHERE assigned_to IS NOT NULL;
CREATE INDEX idx_dsr_created_at ON public.data_subject_requests(created_at DESC);
CREATE INDEX idx_dsr_request_number ON public.data_subject_requests(request_number);

-- Trigger for updated_at
CREATE TRIGGER update_data_subject_requests_timestamp
    BEFORE UPDATE ON public.data_subject_requests
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.data_subject_requests ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY dsr_user_policy ON public.data_subject_requests
    FOR SELECT USING (requester_user_id = current_user_id());

CREATE POLICY dsr_privacy_team_policy ON public.data_subject_requests
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'privacy_analyst', 'compliance_officer', 'admin')
    ));

-- =============================================================================
-- TABLE 48: data_export_requests
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 48
-- Table Name: data_export_requests
-- Description: Manages GDPR Article 20 data portability requests, generating
--              structured, machine-readable exports of user data with secure
--              delivery and automatic expiration.
--
-- Business Case (300 words):
-- Article 20 of the GDPR introduces the right to data portability—the right
-- to receive personal data in a structured, commonly used, machine-readable
-- format and to transmit it to another controller. This right empowers
-- individuals and promotes competition, but it's technically challenging.
--
-- Data must be extracted from multiple systems, comprehensive but exclude others'
-- data, in truly machine-readable format (JSON, XML, CSV), structured to maintain
-- relationships between data, delivered securely to the right individual, and
-- automatically deleted after a reasonable period. This table manages the
-- entire export workflow to meet these challenges.
--
-- The business impact is trust—users who can easily export their data feel more
-- in control and are more likely to trust the platform. For compliance, the
-- export capability demonstrates adherence to Article 20. For product teams,
-- understanding what users export reveals what data they value most.
--
-- The design supports all required features: flexible data filters (select which
-- data to export), multiple format options with compression, secure delivery via
-- signed URLs or encrypted email, and expiration policies for security. Large
-- exports are chunked and can be resumed if interrupted. Every export is logged
-- with complete audit trail.
--
-- Key Performance Indicators (KPIs):
--   1. Export Success Rate: Percentage of exports successfully generated (>99%)
--   2. Average Generation Time: Minutes to generate complete export
--   3. Export Size Distribution: Average/median export size by user
--   4. Format Preference: Most requested export formats
--   5. Download Rate: Percentage of generated exports actually downloaded
--   6. Expiry Compliance: Percentage deleted within retention period (100%)
--   7. System Coverage: Number of systems included in exports
--
-- Feature Reference: GDPR-08, PORT-01
-- Requirements Traceability: GDPR Article 20 (Right to data portability)
--
-- Normalization: 3NF - Export requests independent with status tracking
--
-- High-Write Considerations:
--   - Low write volume (exports are relatively rare)
--   - Read-heavy during generation and download
--   - Partitioning by requested_at for historical queries
--   - Partial indexes for pending exports only
-------------------------------------------------------------------------------
CREATE TABLE public.data_export_requests (
    -- Primary key
    export_id UUID DEFAULT gen_random_uuid() NOT NULL,
    requested_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Core identification
    export_reference VARCHAR(50) NOT NULL UNIQUE,
    dsr_request_id UUID REFERENCES public.data_subject_requests(request_id) ON DELETE CASCADE,

    -- Requester information
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    user_email VARCHAR(255) NOT NULL,
    user_name VARCHAR(500),

    -- Request details
    requested_format VARCHAR(20) NOT NULL DEFAULT 'JSON' CHECK (requested_format IN ('JSON', 'XML', 'CSV', 'PDF', 'HTML')),
    requested_data_scope VARCHAR(50) DEFAULT 'ALL' CHECK (requested_data_scope IN (
        'ALL', 'PROFILE_ONLY', 'ACTIVITY_ONLY', 'MESSAGES_ONLY', 'CUSTOM'
    )),
    custom_scope JSONB,  -- For custom selections

    -- Processing
    status VARCHAR(50) NOT NULL DEFAULT 'PENDING' CHECK (status IN (
        'PENDING', 'VALIDATING', 'EXTRACTING', 'TRANSFORMING', 'COMPRESSING',
        'ENCRYPTING', 'COMPLETED', 'FAILED', 'EXPIRED', 'CANCELLED'
    )),
    status_history JSONB DEFAULT '[]'::JSONB,

    -- Validation
    identity_verified BOOLEAN DEFAULT false,
    identity_verification_method VARCHAR(100),
    identity_verified_at TIMESTAMP WITH TIME ZONE,
    identity_verified_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Data discovery
    systems_queried TEXT[],
    tables_queried TEXT[],
    records_found INTEGER,
    data_categories_found public.data_category_gdpr[],

    -- Export generation
    generation_started_at TIMESTAMP WITH TIME ZONE,
    generation_completed_at TIMESTAMP WITH TIME ZONE,
    generation_duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (generation_completed_at - generation_started_at))
    ) STORED,

    -- Export metadata
    export_file_name VARCHAR(500),
    export_file_size_bytes BIGINT,
    export_file_hash VARCHAR(256),  -- SHA-256 for integrity
    export_mime_type VARCHAR(100),
    record_count INTEGER,

    -- Structure (for JSON/XML)
    export_schema JSONB,  -- Schema definition
    export_structure_description TEXT,

    -- Encryption
    encryption_method VARCHAR(50) CHECK (encryption_method IN ('AES-256', 'PGP', 'NONE')),
    encryption_key_id VARCHAR(200),  -- Reference to key management system
    encryption_details JSONB,

    -- Storage
    storage_location VARCHAR(500),  -- S3 path, file system path
    storage_provider VARCHAR(100),
    storage_region VARCHAR(100),
    storage_bucket VARCHAR(200),
    storage_key VARCHAR(500),

    -- Download access
    download_url TEXT,
    download_url_expires_at TIMESTAMP WITH TIME ZONE,
    download_count INTEGER DEFAULT 0,
    last_download_at TIMESTAMP WITH TIME ZONE,
    last_download_ip INET,

    -- Secure delivery
    delivery_method VARCHAR(50) CHECK (delivery_method IN (
        'SECURE_DOWNLOAD', 'ENCRYPTED_EMAIL', 'SECURE_PORTAL', 'API', 'PHYSICAL_MEDIA'
    )),
    delivery_address TEXT,
    delivery_tracking_id VARCHAR(200),
    delivery_confirmed_at TIMESTAMP WITH TIME ZONE,

    -- Expiry and deletion
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT (CURRENT_TIMESTAMP + INTERVAL '30 days'),
    deletion_notification_sent BOOLEAN DEFAULT false,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deletion_verified_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    deletion_certificate TEXT,

    -- Error handling
    error_message TEXT,
    error_details JSONB,
    failed_step VARCHAR(50),
    retry_count INTEGER DEFAULT 0,

    -- Quality metrics
    completeness_score NUMERIC(5,2) CHECK (completeness_score IS NULL OR (completeness_score BETWEEN 0 AND 100)),
    accuracy_score NUMERIC(5,2) CHECK (accuracy_score IS NULL OR (accuracy_score BETWEEN 0 AND 100)),
    quality_checked_at TIMESTAMP WITH TIME ZONE,
    quality_checked_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    processed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    processing_notes TEXT,
    tags TEXT[],

    -- Constraints
    CONSTRAINT valid_generation_timeline CHECK (
        generation_completed_at IS NULL OR
        (generation_started_at IS NOT NULL AND generation_completed_at > generation_started_at)
    ),
    CONSTRAINT valid_expiry CHECK (expires_at > requested_at),
    CONSTRAINT valid_download_url CHECK (
        (download_url IS NULL AND delivery_method != 'SECURE_DOWNLOAD') OR
        (download_url IS NOT NULL AND delivery_method = 'SECURE_DOWNLOAD')
    ),

    PRIMARY KEY (export_id, requested_at)
) PARTITION BY RANGE (requested_at);

COMMENT ON TABLE public.data_export_requests IS 'GDPR Article 20 data portability request management with secure export generation';
COMMENT ON COLUMN public.data_export_requests.export_id IS 'Primary key';
COMMENT ON COLUMN public.data_export_requests.requested_at IS 'When export was requested (partition key)';
COMMENT ON COLUMN public.data_export_requests.export_reference IS 'Human-readable export reference';
COMMENT ON COLUMN public.data_export_requests.dsr_request_id IS 'Link to parent data subject request if applicable';
COMMENT ON COLUMN public.data_export_requests.export_file_hash IS 'SHA-256 hash for integrity verification';
COMMENT ON COLUMN public.data_export_requests.expires_at IS 'When the export will be automatically deleted';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_export_requests_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'data_export_requests_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    -- Check if partition already exists
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.data_export_requests
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, requested_at DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(status) WHERE status IN (''PENDING'', ''PROCESSING'');
        ',
        'idx_' || partition_name || '_user', partition_name,
        'idx_' || partition_name || '_status', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create initial partitions (current and next 2 months)
SELECT public.create_export_requests_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_export_requests_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_export_requests_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes
CREATE INDEX idx_export_requests_user_id ON public.data_export_requests(user_id, requested_at DESC);
CREATE INDEX idx_export_requests_dsr_id ON public.data_export_requests(dsr_request_id);
CREATE INDEX idx_export_requests_status ON public.data_export_requests(status);
CREATE INDEX idx_export_requests_expires_at ON public.data_export_requests(expires_at) WHERE status = 'COMPLETED';
CREATE INDEX idx_export_requests_format ON public.data_export_requests(requested_format);

-- Trigger for updated_at
CREATE TRIGGER update_data_export_requests_timestamp
    BEFORE UPDATE ON public.data_export_requests
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.data_export_requests ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY export_requests_user_policy ON public.data_export_requests
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY export_requests_privacy_team_policy ON public.data_export_requests
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'privacy_analyst', 'compliance_officer', 'admin')
    ));

-- =============================================================================
-- TABLE 49: third_party_sharing_log
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 49
-- Table Name: third_party_sharing_log
-- Description: Comprehensive log of all personal data shared with third parties,
--              including legal basis, safeguards, recipient details, and
--              international transfer mechanisms.
--
-- Business Case (300 words):
-- GDPR transparency requirements (Articles 13-14) mandate that individuals be
-- informed about recipients of their personal data. Additionally, Article 30
-- requires documentation of data recipients in the processing register. This
-- table serves as the definitive record of all data sharing activities,
-- enabling transparency, accountability, and third-party risk management.
--
-- Without a sharing log, organizations cannot respond to data subject inquiries
-- about who their data has been shared with. They cannot demonstrate to auditors
-- that sharing complies with legal bases. During a breach, they cannot quickly
-- identify affected third parties. This table addresses all these gaps.
--
-- The business impact is direct: transparency builds user trust. The ability
-- to quickly identify all third parties with access to data improves incident
-- response. Third-party risk management becomes systematic, with all sharing
-- documented and reviewed. For international transfers, the documented safeguards
-- demonstrate compliance with Chapter V requirements.
--
-- The design captures every sharing event with complete context: third party
-- identification, legal basis (consent, contract, legitimate interests), data
-- categories shared, purpose, and international transfer mechanisms. Data
-- processing agreements are referenced, and risk assessments are documented.
--
-- Key Performance Indicators (KPIs):
--   1. Sharing Volume: Number of sharing events by time period
--   2. Recipient Diversity: Number of distinct third parties
--   3. Data Category Distribution: Types of data most frequently shared
--   4. Legal Basis Distribution: Most common legal bases for sharing
--   5. Third-Party Geography: Countries where data is transferred
--   6. Agreement Coverage: Percentage with signed data processing agreements (100%)
--   7. Breach Incidents: Number of incidents involving third parties
--
-- Feature Reference: GDPR-09, SHARE-01, THIRDPARTY-01
-- Requirements Traceability: GDPR Articles 13-14, Article 30, Article 44-50
--
-- Normalization: 3NF - Sharing events independent with recipient references
--
-- High-Write Considerations:
--   - Moderate write volume (each sharing event logged)
--   - Read-heavy for transparency responses and audits
--   - JSONB for flexible recipient and agreement data
--   - Partial indexes for active sharing arrangements
-------------------------------------------------------------------------------
CREATE TABLE public.third_party_sharing_log (
    -- Primary key
    sharing_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    sharing_reference VARCHAR(50) NOT NULL UNIQUE,
    sharing_timestamp TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Third party information
    third_party_name VARCHAR(500) NOT NULL,
    third_party_id UUID,  -- If registered in vendor/partner system
    third_party_type VARCHAR(100) CHECK (third_party_type IN (
        'SERVICE_PROVIDER', 'PROCESSOR', 'SUB_PROCESSOR', 'CONTROLLER',
        'JOINT_CONTROLLER', 'PARTNER', 'LAW_ENFORCEMENT', 'REGULATOR',
        'ACQUIRER', 'INVESTOR', 'OTHER'
    )),
    third_party_country VARCHAR(3),
    third_party_contact VARCHAR(500),
    third_party_email VARCHAR(255),

    -- Data sharing agreement
    agreement_reference VARCHAR(200),
    agreement_date DATE,
    agreement_type VARCHAR(100) CHECK (agreement_type IN (
        'DATA_PROCESSING_AGREEMENT', 'STANDARD_CONTRACTUAL_CLAUSES',
        'BINDING_CORPORATE_RULES', 'ADEQUACY_DECISION', 'CODE_OF_CONDUCT',
        'CERTIFICATION', 'IMPLIED_CONSENT', 'EXPLICIT_CONSENT', 'LEGAL_OBLIGATION'
    )),
    agreement_expiry DATE,
    agreement_document_url TEXT,

    -- Legal basis for sharing
    legal_basis public.processing_legal_basis NOT NULL,
    legal_basis_justification TEXT NOT NULL,
    specific_consent_obtained BOOLEAN DEFAULT false,
    consent_reference UUID REFERENCES public.consent_records(consent_id) ON DELETE SET NULL,

    -- Data shared
    data_categories_shared public.data_category_gdpr[] NOT NULL,
    data_elements_shared TEXT[],  -- Specific fields/attributes
    data_volume_estimate INTEGER,
    data_sensitivity_level VARCHAR(20) CHECK (data_sensitivity_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    data_retention_on_recipient_side TEXT,  -- How long they keep it

    -- Data subjects affected
    data_subject_categories TEXT[],
    data_subject_count INTEGER,
    data_subject_segments TEXT[],  -- e.g., 'EU_CUSTOMERS', 'ALL_USERS'

    -- Purpose of sharing
    sharing_purpose TEXT NOT NULL,
    processing_instructions TEXT,  -- Specific processing restrictions
    permitted_uses TEXT[],
    prohibited_uses TEXT[],

    -- Transfer mechanism (for international transfers)
    international_transfer BOOLEAN DEFAULT false,
    transfer_mechanism VARCHAR(100) CHECK (transfer_mechanism IN (
        'ADEQUACY_DECISION', 'STANDARD_CONTRACTUAL_CLAUSES', 'BINDING_CORPORATE_RULES',
        'DEROGATION', 'EXPLICIT_CONSENT', 'PUBLIC_INTEREST', 'LEGAL_CLAIMS'
    )),
    transfer_safeguards TEXT,
    adequacy_decision_reference VARCHAR(200),
    scc_reference VARCHAR(200),
    bcr_reference VARCHAR(200),

    -- Technical sharing method
    sharing_method VARCHAR(100) CHECK (sharing_method IN (
        'API', 'SFTP', 'EMAIL', 'MANUAL_UPLOAD', 'DATABASE_REPLICATION',
        'FILE_TRANSFER', 'CLOUD_SYNC', 'PHYSICAL_MEDIA', 'USER_ACTION', 'OTHER'
    )),
    sharing_frequency VARCHAR(50) CHECK (sharing_frequency IN (
        'REAL_TIME', 'BATCH_DAILY', 'BATCH_WEEKLY', 'BATCH_MONTHLY', 'ONE_TIME', 'ON_DEMAND'
    )),
    sharing_channel VARCHAR(100),

    -- Security measures
    encryption_in_transit BOOLEAN DEFAULT true,
    encryption_at_rest BOOLEAN DEFAULT true,
    encryption_method VARCHAR(100),
    security_certifications TEXT[],
    audit_rights BOOLEAN DEFAULT false,
    last_audit_date DATE,

    -- Compliance documentation
    dpia_reference UUID REFERENCES public.data_protection_impact_assessments(dpia_id) ON DELETE SET NULL,
    risk_assessment_completed BOOLEAN DEFAULT false,
    risk_assessment_date DATE,
    risk_assessment_summary TEXT,
    risk_level_assessed VARCHAR(20),

    -- Authorizations
    authorized_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    authorized_at TIMESTAMP WITH TIME ZONE,
    authorization_evidence TEXT,
    legal_reviewed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    legal_review_date DATE,

    -- Data subject notification
    data_subjects_notified BOOLEAN DEFAULT false,
    notification_method VARCHAR(100),
    notification_date DATE,
    privacy_policy_updated BOOLEAN DEFAULT false,
    privacy_policy_section VARCHAR(200),

    -- Data sharing log (for individual requests)
    individual_share_log JSONB,  -- Log of actual sharing events

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    department VARCHAR(200),
    project_name VARCHAR(500),
    contract_value NUMERIC(15,2),
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_transfer CHECK (
        (international_transfer = true AND transfer_mechanism IS NOT NULL) OR
        (international_transfer = false)
    ),
    CONSTRAINT valid_consent CHECK (
        (legal_basis = 'CONSENT' AND specific_consent_obtained = true AND consent_reference IS NOT NULL) OR
        (legal_basis != 'CONSENT')
    )
);

COMMENT ON TABLE public.third_party_sharing_log IS 'Comprehensive log of all personal data sharing with third parties for GDPR transparency';
COMMENT ON COLUMN public.third_party_sharing_log.sharing_id IS 'Primary key';
COMMENT ON COLUMN public.third_party_sharing_log.third_party_name IS 'Name of the third party recipient';
COMMENT ON COLUMN public.third_party_sharing_log.agreement_reference IS 'Reference to data processing agreement';
COMMENT ON COLUMN public.third_party_sharing_log.international_transfer IS 'Flag indicating if this is an international data transfer';
COMMENT ON COLUMN public.third_party_sharing_log.transfer_mechanism IS 'Legal mechanism for international transfer under GDPR Chapter V';

-- Indexes
CREATE INDEX idx_third_party_sharing_timestamp ON public.third_party_sharing_log(sharing_timestamp DESC);
CREATE INDEX idx_third_party_sharing_third_party ON public.third_party_sharing_log(third_party_name);
CREATE INDEX idx_third_party_sharing_legal_basis ON public.third_party_sharing_log(legal_basis);
CREATE INDEX idx_third_party_sharing_country ON public.third_party_sharing_log(third_party_country);
CREATE INDEX idx_third_party_sharing_data_categories ON public.third_party_sharing_log USING gin(data_categories_shared);
CREATE INDEX idx_third_party_sharing_international ON public.third_party_sharing_log(international_transfer) WHERE international_transfer = true;

-- Trigger for updated_at
CREATE TRIGGER update_third_party_sharing_log_timestamp
    BEFORE UPDATE ON public.third_party_sharing_log
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.third_party_sharing_log ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY third_party_sharing_compliance_policy ON public.third_party_sharing_log
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('data_protection_officer', 'compliance_officer', 'legal_counsel', 'admin')
    ));

-- =============================================================================
-- TABLE 50: legal_holds
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 50
-- Table Name: legal_holds
-- Description: Manages legal holds that override standard data retention policies
--              for litigation, investigations, or regulatory inquiries, with
--              custodian tracking and hold release workflows.
--
-- Business Case (300 words):
-- When litigation is reasonably anticipated, or an investigation is underway,
-- organizations have a legal obligation to preserve relevant data. This duty
-- to preserve overrides standard data retention policies and deletion schedules.
-- Failure to implement a legal hold can result in severe penalties, including
-- sanctions for spoliation of evidence, adverse inference instructions, and
-- monetary fines.
--
-- Without a legal hold system, organizations cannot ensure that relevant data
-- is preserved during litigation. Critical evidence may be deleted automatically
-- by retention policies, causing irreparable harm to legal defense. This table
-- provides the mechanism to override standard policies when legal obligations
-- require preservation.
--
-- The business impact is direct: proper legal holds protect the organization
-- in litigation, avoiding sanctions that can reach millions of dollars. They
-- ensure that discovery obligations are met, preserving the ability to defend
-- claims. For regulated industries, they demonstrate good faith efforts to
-- comply with investigations.
--
-- The design supports the entire hold lifecycle: hold receipt and logging,
-- scope definition (data categories, systems, date ranges), hold implementation
-- across systems, custodian identification and notification, periodic reminders,
-- hold release, and comprehensive audit trail. Integration with retention
-- policies ensures automatic override of deletion schedules.
--
-- Key Performance Indicators (KPIs):
--   1. Hold Implementation Time: Hours from notice to technical implementation (<24h)
--   2. Hold Coverage: Percentage of identified data successfully preserved (100%)
--   3. Custodian Compliance: Percentage of custodians acknowledging hold (>95%)
--   4. Hold Duration: Average/median length of legal holds
--   5. Release Compliance: Percentage of holds released according to schedule
--   6. Preservation Cost: Storage costs associated with legal holds
--   7. Audit Findings: Number of deficiencies identified in audits (0)
--
-- Feature Reference: LEGAL-01, HOLD-01, LIT-01
-- Requirements Traceability: FRCP Rule 37(e), eDiscovery Rules, SEC Rule 17a-4
--
-- Normalization: 3NF - Holds independent with custodian tracking
--
-- High-Write Considerations:
--   - Low write volume (holds are relatively rare)
--   - Read-heavy during discovery and audits
--   - JSONB for flexible custodian and scope data
--   - Partial indexes for active holds only
-------------------------------------------------------------------------------
CREATE TABLE public.legal_holds (
    -- Primary key
    hold_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    hold_number VARCHAR(50) NOT NULL UNIQUE,
    hold_name VARCHAR(500) NOT NULL,
    hold_type VARCHAR(50) CHECK (hold_type IN (
        'LITIGATION', 'REGULATORY_INVESTIGATION', 'AUDIT', 'INTERNAL_INVESTIGATION',
        'GOVERNMENT_INQUIRY', 'CONTRACT_DISPUTE', 'EMPLOYMENT_MATTER', 'PATENT_MATTER',
        'ANTICIPATED_LITIGATION', 'OTHER'
    )),

    -- Legal matter reference
    matter_id VARCHAR(100),
    matter_name VARCHAR(500),
    matter_type VARCHAR(100),

    -- Parties involved
    plaintiff_parties TEXT[],
    defendant_parties TEXT[],
    regulatory_body VARCHAR(500),
    case_number VARCHAR(200),
    court_jurisdiction VARCHAR(200),

    -- Hold timeline
    hold_notice_received_at TIMESTAMP WITH TIME ZONE NOT NULL,
    hold_implemented_at TIMESTAMP WITH TIME ZONE,
    hold_review_date TIMESTAMP WITH TIME ZONE,
    hold_release_date TIMESTAMP WITH TIME ZONE,
    hold_expiration_date TIMESTAMP WITH TIME ZONE,  -- Automatic release if not extended

    -- Hold status
    status public.legal_hold_status NOT NULL DEFAULT 'PENDING',
    status_reason TEXT,

    -- Scope definition
    scope_description TEXT NOT NULL,
    date_range_start DATE,  -- Beginning of relevant time period
    date_range_end DATE,     -- End of relevant time period

    -- Data categories under hold
    data_categories_held public.data_category_gdpr[] NOT NULL,
    data_elements_held TEXT[],  -- Specific fields/attributes

    -- Systems under hold
    systems_affected TEXT[] NOT NULL,
    databases_affected TEXT[],
    applications_affected TEXT[],
    file_shares_affected TEXT[],
    email_systems_affected TEXT[],

    -- Custodians
    custodians JSONB NOT NULL DEFAULT '[]'::JSONB,  -- Array of custodian objects with details
    custodian_count INTEGER GENERATED ALWAYS AS (
        jsonb_array_length(custodians)
    ) STORED,

    -- Data volumes
    estimated_data_volume_gb NUMERIC(10,2),
    actual_data_volume_gb NUMERIC(10,2),
    record_count_estimate INTEGER,
    record_count_actual INTEGER,

    -- Hold implementation details
    implementation_method VARCHAR(100) CHECK (implementation_method IN (
        'PRESERVATION_NOTICE', 'TECHNICAL_LOCKDOWN', 'BACKUP_PRESERVATION',
        'LEGAL_HOLD_SOFTWARE', 'MANUAL_PRESERVATION', 'HYBRID'
    )),
    technical_implementation_details TEXT,
    preservation_notice_sent BOOLEAN DEFAULT false,
    preservation_notice_date DATE,

    -- Custodian notifications
    custodians_notified BOOLEAN DEFAULT false,
    notification_method VARCHAR(100),
    notification_date DATE,
    acknowledgment_deadline DATE,
    acknowledgments_received INTEGER DEFAULT 0,
    reminders_sent INTEGER DEFAULT 0,

    -- Hold certifications
    certification_required BOOLEAN DEFAULT false,
    certification_frequency VARCHAR(50),
    last_certification_date DATE,
    next_certification_date DATE,

    -- Hold modifications
    modification_history JSONB DEFAULT '[]'::JSONB,

    -- Hold release
    release_authorized_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    release_authorized_at TIMESTAMP WITH TIME ZONE,
    release_reason TEXT,
    release_instructions TEXT,
    release_verified_at TIMESTAMP WITH TIME ZONE,
    release_verified_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Data disposition after release
    disposition_instructions TEXT,
    disposition_completed BOOLEAN DEFAULT false,
    disposition_completed_at TIMESTAMP WITH TIME ZONE,
    disposition_certificate TEXT,

    -- Legal team
    primary_attorney_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    outside_counsel_firm VARCHAR(500),
    outside_counsel_attorney VARCHAR(500),
    outside_counsel_email VARCHAR(255),

    -- Compliance and audit
    compliance_officer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    last_audit_date DATE,
    audit_findings TEXT,
    audit_resolved_date DATE,

    -- Documentation
    hold_notice_document_url TEXT,
    legal_hold_policy_document_url TEXT,
    custodian_acknowledgments_url TEXT,
    correspondence_log_url TEXT,
    attachments TEXT[],

    -- Cost tracking
    estimated_preservation_cost NUMERIC(15,2),
    actual_preservation_cost NUMERIC(15,2),
    cost_currency CHAR(3) DEFAULT 'USD',
    cost_tracking_notes TEXT,

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    business_unit VARCHAR(200),
    department VARCHAR(200),
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_hold_dates CHECK (
        hold_implemented_at IS NULL OR hold_implemented_at >= hold_notice_received_at
    ),
    CONSTRAINT valid_release CHECK (
        hold_release_date IS NULL OR hold_release_date > hold_implemented_at
    ),
    CONSTRAINT valid_date_range CHECK (
        date_range_end IS NULL OR date_range_end >= date_range_start
    )
);

COMMENT ON TABLE public.legal_holds IS 'Legal hold management for litigation and investigations, overriding standard retention policies';
COMMENT ON COLUMN public.legal_holds.hold_id IS 'Primary key';
COMMENT ON COLUMN public.legal_holds.hold_number IS 'Human-readable hold reference number';
COMMENT ON COLUMN public.legal_holds.custodians IS 'JSON array of custodians under hold with contact and acknowledgment status';
COMMENT ON COLUMN public.legal_holds.data_categories_held IS 'Categories of data subject to the hold';
COMMENT ON COLUMN public.legal_holds.systems_affected IS 'Systems and applications where data must be preserved';

-- Indexes
CREATE INDEX idx_legal_holds_status ON public.legal_holds(status);
CREATE INDEX idx_legal_holds_type ON public.legal_holds(hold_type);
CREATE INDEX idx_legal_holds_notice_date ON public.legal_holds(hold_notice_received_at DESC);
CREATE INDEX idx_legal_holds_release_date ON public.legal_holds(hold_release_date) WHERE hold_release_date IS NOT NULL;
CREATE INDEX idx_legal_holds_attorney ON public.legal_holds(primary_attorney_id);
CREATE INDEX idx_legal_holds_data_categories ON public.legal_holds USING gin(data_categories_held);
CREATE INDEX idx_legal_holds_systems ON public.legal_holds USING gin(systems_affected);

-- Trigger for updated_at
CREATE TRIGGER update_legal_holds_timestamp
    BEFORE UPDATE ON public.legal_holds
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.legal_holds ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY legal_holds_legal_team_policy ON public.legal_holds
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('legal_counsel', 'compliance_officer', 'admin', 'data_protection_officer')
    ));

-- =============================================================================
-- MATERIALIZED VIEW: mv_compliance_dashboard
-- =============================================================================
-------------------------------------------------------------------------------
-- Materialized View: mv_compliance_dashboard
-- Description: Pre-aggregated compliance metrics for executive dashboard
-- Refresh Strategy: Daily
-- Feature Reference: COMP-03 (Compliance Reporting)
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW public.mv_compliance_dashboard AS
WITH retention_stats AS (
    SELECT
        COUNT(*) as total_policies,
        COUNT(*) FILTER (WHERE approval_status = 'APPROVED' AND is_current = true) as active_policies,
        COUNT(*) FILTER (WHERE next_review_date < CURRENT_DATE + INTERVAL '30 days') as policies_needing_review
    FROM public.data_retention_policies
    WHERE effective_to IS NULL
),
breach_stats AS (
    SELECT
        COUNT(*) as total_breaches_30d,
        COUNT(*) FILTER (WHERE breach_severity IN ('CRITICAL', 'HIGH')) as critical_breaches_30d,
        COUNT(*) FILTER (WHERE authority_notification_within_72h = false AND authority_notification_required = true) as late_notifications_30d
    FROM public.data_breach_log
    WHERE occurrence_timestamp > CURRENT_DATE - INTERVAL '30 days'
),
dsar_stats AS (
    SELECT
        COUNT(*) as total_requests_30d,
        AVG(EXTRACT(DAY FROM (response_sent_at - request_received_at))) as avg_response_days,
        COUNT(*) FILTER (WHERE sla_met = false) as sla_breaches_30d
    FROM public.data_subject_requests
    WHERE request_received_at > CURRENT_DATE - INTERVAL '30 days'
)
SELECT
    CURRENT_DATE as as_of_date,
    jsonb_build_object(
        'retention_policies', jsonb_build_object(
            'total', total_policies,
            'active', active_policies,
            'needing_review', policies_needing_review
        ),
        'breaches', jsonb_build_object(
            'total_30d', total_breaches_30d,
            'critical_30d', critical_breaches_30d,
            'late_notifications_30d', late_notifications_30d
        ),
        'dsar', jsonb_build_object(
            'total_30d', total_requests_30d,
            'avg_response_days', ROUND(avg_response_days::NUMERIC, 1),
            'sla_breaches_30d', sla_breaches_30d
        )
    ) as metrics
FROM retention_stats, breach_stats, dsar_stats;

COMMENT ON MATERIALIZED VIEW public.mv_compliance_dashboard IS 'Pre-aggregated compliance metrics for executive dashboard';

CREATE UNIQUE INDEX idx_mv_compliance_dashboard_date ON public.mv_compliance_dashboard(as_of_date);

