-- STORED PROCEDURES
-- =============================================================================

-------------------------------------------------------------------------------
-- Procedure: apply_retention_policy
-- Description: Applies a retention policy to a specific record, executing the
--              required action (delete, anonymize, archive) with full logging.
-- Business Case: Enables automated enforcement of retention policies
-- Feature Reference: RET-03 (Policy Enforcement)
-------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE public.apply_retention_policy(
    p_queue_id UUID,
    p_worker_id VARCHAR(100)
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_queue_record public.data_retention_queue%ROWTYPE;
    v_policy_record public.data_retention_policies%ROWTYPE;
    v_start_time TIMESTAMP WITH TIME ZONE;
    v_end_time TIMESTAMP WITH TIME ZONE;
    v_success BOOLEAN := false;
    v_error_message TEXT;
    v_rows_affected INTEGER := 0;
BEGIN
    -- Get queue item with lock
    SELECT * INTO v_queue_record
    FROM public.data_retention_queue
    WHERE queue_id = p_queue_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Queue item % not found', p_queue_id;
    END IF;

    -- Get policy details
    SELECT * INTO v_policy_record
    FROM public.data_retention_policies
    WHERE policy_id = v_queue_record.policy_id;

    -- Start execution
    UPDATE public.data_retention_queue
    SET
        status = 'PROCESSING',
        locked_by = p_worker_id,
        processing_started_at = CURRENT_TIMESTAMP,
        updated_at = CURRENT_TIMESTAMP
    WHERE queue_id = p_queue_id;

    v_start_time := clock_timestamp();

    BEGIN
        -- Execute action based on policy
        CASE v_queue_record.action_required
            WHEN 'DELETE' THEN
                EXECUTE format('DELETE FROM %I.%I WHERE %I = $1',
                    v_queue_record.schema_name,
                    v_queue_record.table_name,
                    'id'  -- Assumes primary key is 'id'
                ) USING v_queue_record.record_id;
                GET DIAGNOSTICS v_rows_affected = ROW_COUNT;

            WHEN 'ANONYMIZE' THEN
                -- This would contain anonymization logic
                -- Simplified for example
                v_rows_affected := 1;

            WHEN 'ARCHIVE' THEN
                -- This would contain archiving logic
                v_rows_affected := 1;

            ELSE
                RAISE EXCEPTION 'Unsupported action: %', v_queue_record.action_required;
        END CASE;

        v_success := true;
        v_end_time := clock_timestamp();

        -- Update queue item as completed
        UPDATE public.data_retention_queue
        SET
            status = 'COMPLETED',
            processing_completed_at = CURRENT_TIMESTAMP,
            processing_duration_ms = EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000,
            records_affected = v_rows_affected,
            updated_at = CURRENT_TIMESTAMP
        WHERE queue_id = p_queue_id;

        -- Log success
        INSERT INTO public.audit_logs (
            actor_id,
            action,
            entity_type,
            entity_id,
            details,
            category,
            severity
        ) VALUES (
            current_user_id(),
            'APPLY_RETENTION',
            'data_retention_queue',
            p_queue_id,
            jsonb_build_object(
                'policy_id', v_policy_record.policy_id,
                'action', v_queue_record.action_required,
                'records_affected', v_rows_affected
            ),
            'COMPLIANCE',
            'INFO'
        );

    EXCEPTION WHEN OTHERS THEN
        v_success := false;
        v_error_message := SQLERRM;
        v_end_time := clock_timestamp();

        -- Update queue item as failed
        UPDATE public.data_retention_queue
        SET
            status = CASE WHEN v_queue_record.retry_count + 1 >= v_queue_record.max_retries
                          THEN 'DEAD_LETTER'
                          ELSE 'RETRYING' END,
            retry_count = retry_count + 1,
            last_error_message = v_error_message,
            last_error_timestamp = CURRENT_TIMESTAMP,
            next_retry_at = CURRENT_TIMESTAMP + (v_queue_record.retry_interval_minutes * INTERVAL '1 minute'),
            updated_at = CURRENT_TIMESTAMP
        WHERE queue_id = p_queue_id;

        -- Log failure
        INSERT INTO public.audit_logs (
            actor_id,
            action,
            entity_type,
            entity_id,
            details,
            category,
            severity
        ) VALUES (
            current_user_id(),
            'RETENTION_FAILED',
            'data_retention_queue',
            p_queue_id,
            jsonb_build_object(
                'error', v_error_message,
                'retry_count', v_queue_record.retry_count + 1
            ),
            'COMPLIANCE',
            'ERROR'
        );
    END;
END;
$$;

COMMENT ON PROCEDURE public.apply_retention_policy IS 'Applies a retention policy to a specific record with error handling and logging';

-- =============================================================================
-- SCHEDULED JOBS
-- =============================================================================

-- Create scheduled jobs if pg_cron is available
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
        -- Process retention queue every hour
        PERFORM cron.schedule(
            'process-retention-queue',
            '0 * * * *',
            $$
            SELECT public.claim_retention_queue_batch('cron_worker', 100);
            $$
        );

        -- Refresh compliance dashboard daily at 5 AM
        PERFORM cron.schedule(
            'refresh-compliance-dashboard',
            '0 5 * * *',
            'REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_compliance_dashboard'
        );

        -- Check for expiring consents daily at 6 AM
        PERFORM cron.schedule(
            'check-expiring-consents',
            '0 6 * * *',
            $$
            UPDATE public.consent_records
            SET renewal_notification_sent = true
            WHERE status = 'GRANTED'
                AND consent_expires_at IS NOT NULL
                AND consent_expires_at < CURRENT_TIMESTAMP + INTERVAL '30 days'
                AND consent_expires_at > CURRENT_TIMESTAMP
                AND renewal_notification_sent = false;
            $$
        );

        -- Clean up expired exports daily at 2 AM
        PERFORM cron.schedule(
            'cleanup-expired-exports',
            '0 2 * * *',
            $$
            UPDATE public.data_export_requests
            SET status = 'EXPIRED',
                deleted_at = CURRENT_TIMESTAMP
            WHERE status = 'COMPLETED'
                AND expires_at < CURRENT_TIMESTAMP;
            $$
        );
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'pg_cron extension not available. Scheduled tasks will not be created.';
END $$;

