    FOR VALUES WITH (MODULUS 16, REMAINDER 4);
CREATE TABLE public.feed_ranking_scores_p5 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 5);
CREATE TABLE public.feed_ranking_scores_p6 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 6);
CREATE TABLE public.feed_ranking_scores_p7 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 7);
CREATE TABLE public.feed_ranking_scores_p8 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 8);
CREATE TABLE public.feed_ranking_scores_p9 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 9);
