    FOR VALUES WITH (MODULUS 16, REMAINDER 10);
CREATE TABLE public.feed_ranking_scores_p11 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 11);
CREATE TABLE public.feed_ranking_scores_p12 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 12);
CREATE TABLE public.feed_ranking_scores_p13 PARTITION OF public.feed_ranking_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 13);
CREATE TABLE public.feed_ranking_scores_p14 PARTITION OF public.feed_ranking_scores
