-- Global indexes
CREATE INDEX idx_feed_ranking_scores_user_active ON public.feed_ranking_scores(user_id, final_score DESC)
    WHERE is_active = true;
CREATE INDEX idx_feed_ranking_scores_content ON public.feed_ranking_scores(content_id);
