    WHERE valid_until IS NOT NULL;

-- GIN index for component scores
CREATE INDEX idx_feed_ranking_scores_components ON public.feed_ranking_scores USING gin(component_scores);

-- Trigger for updated_at
CREATE TRIGGER update_feed_ranking_scores_timestamp
    BEFORE UPDATE ON public.feed_ranking_scores
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.feed_ranking_scores ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY feed_ranking_scores_self_policy ON public.feed_ranking_scores
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY feed_ranking_scores_system_policy ON public.feed_ranking_scores
    USING (current_user = 'feed_generation_service');

-- =============================================================================
-- TABLE 89: feed_interactions
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 89
-- Table Name: feed_interactions
-- Description: Real-time tracking of user interactions with feed items for
--              model training, engagement analytics, and feedback loops.
--
-- Business Case (300 words):
-- Machine learning models for feed ranking require continuous training data
-- to improve. Every user interaction with the feed—views, clicks, likes,
-- comments, hides—provides a signal about what content is relevant and engaging.
-- This table captures these signals in real-time, creating the training dataset
-- that powers the next generation of ranking models.
--
-- Without comprehensive interaction tracking, models cannot learn from user
-- behavior. They become static and outdated, failing to adapt to changing user
-- preferences. Feed quality degrades over time, engagement drops, and users
-- become frustrated. This table closes the loop, enabling continuous model
-- improvement through online learning.
--
-- The business impact is transformative: models trained on real user behavior
-- achieve 30-50% higher engagement than static models. The ability to detect
-- negative signals (hides, reports) allows rapid removal of low-quality content
-- from feeds. Real-time feedback enables quick responses to emerging trends
-- and viral content.
--
-- The design captures both explicit interactions (likes, comments, shares) and
-- implicit signals (views, dwell time, scroll depth). Session context links
-- interactions within a user session, revealing patterns like bounces after
-- certain content. The position tracking accounts for position bias in click
-- modeling.
--
-- Key Performance Indicators (KPIs):
--   1. Interaction Coverage: Percentage of feed items with some interaction (>40%)
--   2. Data Freshness: Time from interaction to model training (<1 hour)
--   3. Signal Quality: Correlation between interactions and user satisfaction
--   4. Negative Signal Rate: Percentage of hides/reports per user
--   5. Model Improvement: Lift in engagement from new training data (>5%)
--   6. Session Completeness: Percentage of sessions with complete interaction tracking
--   7. Data Volume: Interactions per user per day (monitor for trends)
--
-- Feature Reference: FEED-08 (Interaction Tracking)
-- Requirements Traceability: R-FEED-036 through R-FEED-050
--
-- Normalization: 3NF - Interactions independent with session context
--
-- High-Write Considerations:
--   - Extremely high write volume (every user interaction)
--   - Partitioned by interaction_time for write scalability
--   - UNLOGGED table considered but rejected for critical data
--   - Batch inserts for bulk events
--   - Automatic archival of old partitions (>90 days)
-------------------------------------------------------------------------------
CREATE TABLE public.feed_interactions (
    -- Primary key (composite for partitioning)
    interaction_id UUID DEFAULT gen_random_uuid() NOT NULL,
    interaction_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- User context
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    session_id UUID, -- For session tracking

    -- Feed item context
    feed_item_id UUID NOT NULL, -- ID of the feed item (references external systems)
    content_id UUID REFERENCES public.contents(content_id) ON DELETE SET NULL,
    item_type public.feed_item_type NOT NULL,
    item_source_id UUID, -- ID of source (user, company, group, etc.)

    -- Interaction details
    interaction_type public.interaction_type NOT NULL,
    interaction_value NUMERIC, -- e.g., time spent in seconds, rating value
    interaction_data JSONB, -- Additional data (comment text, reaction type, etc.)

    -- Feed context
    feed_position INTEGER CHECK (feed_position >= 0), -- Position in feed (0-based)
    feed_page INTEGER DEFAULT 1, -- Page number in paginated feed
    feed_type VARCHAR(50) CHECK (feed_type IN ('main', 'job', 'network', 'trending', 'sponsored')),
    algorithm_version VARCHAR(50), -- Version of ranking algorithm at time

    -- Item context at interaction time
    item_publisher_id UUID, -- Who created the content
    item_age_seconds INTEGER, -- Age of item when interacted with
    item_quality_score NUMERIC(5,4), -- Quality score at interaction time

    -- Device and platform
    user_agent TEXT,
    ip_address INET,
    device_type VARCHAR(50),
    platform VARCHAR(50),

    -- Performance
    response_time_ms INTEGER, -- Time to load/respond
    interaction_duration_ms INTEGER, -- Duration of interaction

    -- Feedback signals
    is_positive BOOLEAN GENERATED ALWAYS AS (
        interaction_type IN ('LIKE', 'COMMENT', 'SHARE', 'SAVE', 'FOLLOW', 'CLICK_THROUGH')
    ) STORED,
    is_negative BOOLEAN GENERATED ALWAYS AS (
        interaction_type IN ('HIDE', 'REPORT', 'UNFOLLOW')
    ) STORED,
    feedback_weight NUMERIC(3,2) DEFAULT 1.0, -- Weight for model training

    -- Attribution
    recommendation_id UUID, -- If from recommendation system
    experiment_id UUID, -- A/B test experiment if applicable
    experiment_variant VARCHAR(50),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_interaction CHECK (
        (interaction_value IS NULL) OR
        (interaction_value >= 0)
    ),

    PRIMARY KEY (interaction_id, interaction_time)
) PARTITION BY RANGE (interaction_time);

COMMENT ON TABLE public.feed_interactions IS 'Real-time tracking of user interactions with feed items for model training';
COMMENT ON COLUMN public.feed_interactions.interaction_id IS 'Primary key';
COMMENT ON COLUMN public.feed_interactions.interaction_time IS 'When interaction occurred (partition key)';
COMMENT ON COLUMN public.feed_interactions.user_id IS 'User who interacted';
COMMENT ON COLUMN public.feed_interactions.session_id IS 'Session for context';
COMMENT ON COLUMN public.feed_interactions.feed_item_id IS 'ID of the feed item';
COMMENT ON COLUMN public.feed_interactions.content_id IS 'Related content (if applicable)';
COMMENT ON COLUMN public.feed_interactions.item_type IS 'Type of feed item';
COMMENT ON COLUMN public.feed_interactions.interaction_type IS 'Type of interaction';
COMMENT ON COLUMN public.feed_interactions.interaction_value IS 'Quantitative value (time spent, etc.)';
COMMENT ON COLUMN public.feed_interactions.interaction_data IS 'Additional interaction data';
COMMENT ON COLUMN public.feed_interactions.feed_position IS 'Position in feed (0-based)';
COMMENT ON COLUMN public.feed_interactions.feed_type IS 'Type of feed';
COMMENT ON COLUMN public.feed_interactions.is_positive IS 'Generated flag for positive interactions';
COMMENT ON COLUMN public.feed_interactions.is_negative IS 'Generated flag for negative interactions';
COMMENT ON COLUMN public.feed_interactions.feedback_weight IS 'Weight for model training';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_feed_interactions_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'feed_interactions_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    -- Check if partition already exists
    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.feed_interactions
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, interaction_time DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(content_id, interaction_type);
            CREATE INDEX IF NOT EXISTS %I ON public.%I USING gin(interaction_data);
        ',
        'idx_' || partition_name || '_user', partition_name,
        'idx_' || partition_name || '_content', partition_name,
        'idx_' || partition_name || '_data', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for next 7 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..7 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_feed_interactions_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_feed_interactions_user_time ON public.feed_interactions(user_id, interaction_time DESC);
CREATE INDEX idx_feed_interactions_content ON public.feed_interactions(content_id, interaction_type);
CREATE INDEX idx_feed_interactions_session ON public.feed_interactions(session_id) WHERE session_id IS NOT NULL;
CREATE INDEX idx_feed_interactions_experiment ON public.feed_interactions(experiment_id) WHERE experiment_id IS NOT NULL;
CREATE INDEX idx_feed_interactions_type ON public.feed_interactions(interaction_type, interaction_time DESC);
CREATE INDEX idx_feed_interactions_positive ON public.feed_interactions(is_positive) WHERE is_positive = true;
CREATE INDEX idx_feed_interactions_negative ON public.feed_interactions(is_negative) WHERE is_negative = true;

-- GIN index for JSONB data
CREATE INDEX idx_feed_interactions_data ON public.feed_interactions USING gin(interaction_data);

-- Enable RLS
ALTER TABLE public.feed_interactions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY feed_interactions_self_policy ON public.feed_interactions
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY feed_interactions_analyst_policy ON public.feed_interactions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'analyst', 'data_scientist')
    ));

-- =============================================================================
-- TABLE 90: trending_topics
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 90
-- Table Name: trending_topics
-- Description: Detected trending topics, hashtags, and discussions with
--              momentum scores, decay algorithms, and geographic segmentation.
--
-- Business Case (300 words):
-- Trending topics create a sense of community and real-time relevance in
-- professional networks. They surface important conversations, emerging
-- industry trends, and viral content that users might otherwise miss. This
-- table powers the "Trending" section of the platform, driving discovery
-- and engagement.
--
-- Without trending detection, the platform feels static and disconnected from
-- real-world events. Users miss important conversations in their industry,
-- engagement drops, and the platform loses its value as a real-time information
-- source. This table provides the algorithmic foundation for surfacing what's
-- relevant right now.
--
-- The business impact is significant: trending features increase time spent
-- by 25% and content discovery by 40%. They create network effects as users
-- join conversations that are already happening. For advertisers, trending
-- topics provide context for sponsored content placement. For content creators,
-- trending visibility provides motivation to create timely, relevant content.
--
-- The design uses momentum-based algorithms that account for both volume and
-- velocity of mentions. Decay factors ensure that old trends naturally fall
-- off, while surge detection captures sudden spikes. Geographic segmentation
-- enables local trending (trending in San Francisco vs. global). Topic
-- clustering groups related discussions to avoid fragmentation.
--
-- Key Performance Indicators (KPIs):
--   1. Trend Accuracy: Percentage of trending topics users find relevant (>80%)
--   2. Trend Freshness: Average age of trending topics (<24 hours)
--   3. Geographic Granularity: Number of regions with trending detection
--   4. Topic Diversity: Distribution of topics across industries
--   5. User Engagement: Click-through rate on trending topics (>15%)
--   6. Surge Detection: Time to detect emerging trends (<1 hour)
--   7. Spam Filtering: Percentage of spam topics filtered (>99%)
--
-- Feature Reference: FEED-09 (Trending Detection)
-- Requirements Traceability: R-TREND-001 through R-TREND-020
--
-- Normalization: 3NF - Topics independent with versioning
--
-- High-Write Considerations:
--   - Write-heavy during trend recalculation
--   - Read-heavy for feed generation
--   - Partitioned by detection_date for historical analysis
--   - Partial indexes for active trends only
-------------------------------------------------------------------------------
CREATE TABLE public.trending_topics (
    -- Primary key
    topic_id UUID DEFAULT gen_random_uuid() NOT NULL,
    detection_date DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Topic identification
    topic_name VARCHAR(255) NOT NULL,
    topic_normalized VARCHAR(255) NOT NULL, -- Lowercase, normalized version
    topic_type VARCHAR(50) CHECK (topic_type IN ('hashtag', 'keyword', 'phrase', 'discussion', 'event')),

    -- Topic metadata
    topic_description TEXT,
    topic_category VARCHAR(100), -- e.g., 'technology', 'career', 'industry'
    topic_language VARCHAR(10) REFERENCES public.languages(language_code) ON DELETE SET NULL,

    -- Geographic context
    geographic_scope VARCHAR(50) CHECK (geographic_scope IN ('global', 'country', 'region', 'city')),
    country_code CHAR(2),
    region VARCHAR(100),
    city VARCHAR(100),

    -- Trending metrics
    mention_count INTEGER NOT NULL DEFAULT 0,
    unique_contributors INTEGER DEFAULT 0,
    momentum_score NUMERIC(10,6) NOT NULL, -- Combined volume + velocity
    velocity_score NUMERIC(10,6), -- Rate of increase
    acceleration_score NUMERIC(10,6), -- Change in velocity
    peak_momentum NUMERIC(10,6), -- Highest momentum achieved
    peak_time TIMESTAMP WITH TIME ZONE, -- When peak occurred

    -- Time context
    first_detected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_mentioned_at TIMESTAMP WITH TIME ZONE,
    trending_start_time TIMESTAMP WITH TIME ZONE,
    trending_end_time TIMESTAMP WITH TIME ZONE,
    is_trending BOOLEAN GENERATED ALWAYS AS (
        trending_end_time IS NULL OR trending_end_time > CURRENT_TIMESTAMP
    ) STORED,

    -- Decay parameters
    decay_factor NUMERIC(5,4) DEFAULT 0.95, -- How fast momentum decays
    half_life_hours INTEGER, -- Time for momentum to halve

    -- Engagement metrics
    total_views INTEGER DEFAULT 0,
    total_clicks INTEGER DEFAULT 0,
    click_through_rate NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN total_views > 0
        THEN (total_clicks::NUMERIC / total_views) * 100
        ELSE 0 END
    ) STORED,

    -- Content association
    representative_content_id UUID REFERENCES public.contents(content_id) ON DELETE SET NULL,
    top_contributors UUID[], -- Top users driving the trend

    -- Trend clustering
    cluster_id UUID, -- Related topics group
    related_topics UUID[], -- Other related topics

    -- Algorithm metadata
    detection_algorithm_version VARCHAR(50),
    parameters_used JSONB,

    -- Quality signals
    quality_score NUMERIC(5,4) CHECK (quality_score >= 0 AND quality_score <= 1),
    spam_score NUMERIC(5,4) CHECK (spam_score >= 0 AND spam_score <= 1),
    is_verified_topic BOOLEAN DEFAULT false, -- Manually verified

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Constraints
    CONSTRAINT unique_topic_date_geo UNIQUE (topic_normalized, detection_date, geographic_scope, country_code, region, city),

    PRIMARY KEY (topic_id, detection_date)
) PARTITION BY RANGE (detection_date);

COMMENT ON TABLE public.trending_topics IS 'Detected trending topics, hashtags, and discussions with momentum scores';
COMMENT ON COLUMN public.trending_topics.topic_id IS 'Primary key';
COMMENT ON COLUMN public.trending_topics.detection_date IS 'Date of trend detection (partition key)';
COMMENT ON COLUMN public.trending_topics.topic_name IS 'Display name of the trending topic';
COMMENT ON COLUMN public.trending_topics.topic_normalized IS 'Normalized version for matching';
COMMENT ON COLUMN public.trending_topics.geographic_scope IS 'Scope of trending (global, country, region, city)';
COMMENT ON COLUMN public.trending_topics.mention_count IS 'Number of mentions in detection period';
COMMENT ON COLUMN public.trending_topics.momentum_score IS 'Combined volume and velocity score';
COMMENT ON COLUMN public.trending_topics.velocity_score IS 'Rate of increase in mentions';
COMMENT ON COLUMN public.trending_topics.first_detected_at IS 'When topic first appeared';
COMMENT ON COLUMN public.trending_topics.last_mentioned_at IS 'Most recent mention';
COMMENT ON COLUMN public.trending_topics.trending_start_time IS 'When topic started trending';
COMMENT ON COLUMN public.trending_topics.trending_end_time IS 'When topic stopped trending';
COMMENT ON COLUMN public.trending_topics.is_trending IS 'Whether currently trending';
COMMENT ON COLUMN public.trending_topics.half_life_hours IS 'Time for momentum to halve';
COMMENT ON COLUMN public.trending_topics.quality_score IS 'Quality assessment of the trend';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_trending_topics_partition(start_year INTEGER, end_year INTEGER)
RETURNS VOID AS $$
DECLARE
    year INTEGER;
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    FOR year IN start_year..end_year LOOP
        partition_name := 'trending_topics_' || year;
        start_date := year || '-01-01';
        end_date := (year + 1) || '-01-01';

        IF NOT EXISTS (
            SELECT 1 FROM pg_class c
            JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE n.nspname = 'public' AND c.relname = partition_name
        ) THEN
            EXECUTE FORMAT('
                CREATE TABLE IF NOT EXISTS public.%I
                PARTITION OF public.trending_topics
                FOR VALUES FROM (%L) TO (%L)',
                partition_name, start_date, end_date
            );

            -- Create indexes on the partition
            EXECUTE FORMAT('
                CREATE INDEX IF NOT EXISTS %I ON public.%I(topic_normalized, detection_date DESC);
                CREATE INDEX IF NOT EXISTS %I ON public.%I(momentum_score DESC) WHERE is_trending = true;
                CREATE INDEX IF NOT EXISTS %I ON public.%I(geographic_scope, country_code, region, city);
            ',
            'idx_' || partition_name || '_topic', partition_name,
            'idx_' || partition_name || '_momentum', partition_name,
            'idx_' || partition_name || '_geo', partition_name
            );
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-- Create partitions for current and next 2 years
SELECT public.create_trending_topics_partition(
    EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER,
    EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER + 2
);

-- Global indexes
CREATE INDEX idx_trending_topics_topic_date ON public.trending_topics(topic_normalized, detection_date DESC);
CREATE INDEX idx_trending_topics_momentum ON public.trending_topics(momentum_score DESC) WHERE is_trending = true;
CREATE INDEX idx_trending_topics_geo ON public.trending_topics(geographic_scope, country_code, region, city);
CREATE INDEX idx_trending_topics_cluster ON public.trending_topics(cluster_id) WHERE cluster_id IS NOT NULL;

-- GIN indexes for array columns
CREATE INDEX idx_trending_topics_contributors ON public.trending_topics USING gin(top_contributors);
CREATE INDEX idx_trending_topics_related ON public.trending_topics USING gin(related_topics);

-- Trigger for updated_at
CREATE TRIGGER update_trending_topics_timestamp
    BEFORE UPDATE ON public.trending_topics
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.trending_topics ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY trending_topics_read_policy ON public.trending_topics
    FOR SELECT USING (true);

CREATE POLICY trending_topics_write_policy ON public.trending_topics
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'data_scientist')
    ));

-- =============================================================================
-- TABLE 91: trending_content
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 91
-- Table Name: trending_content
-- Description: Temporarily stores trending content with decay algorithms,
--              engagement velocity, and geographic relevance for feed boosting.
--
-- Business Case (300 words):
-- While trending topics identify conversations, trending content identifies
-- specific pieces of content that are gaining traction. This table powers the
-- "Trending Now" sections of feeds, boosting visibility of content that is
-- currently popular. The temporal nature means that content naturally falls
-- off as it ages, ensuring feeds stay fresh.
--
-- Without trending content detection, viral content spreads through organic
-- sharing alone, missing opportunities to amplify what's already popular.
-- Users miss content that their network is already engaging with, reducing
-- the network effect. This table provides the algorithmic boost that makes
-- viral content truly viral.
--
-- The business impact is measurable: trending content receives 3-5x more
-- engagement than non-trending content. The amplification effect creates
-- positive feedback loops—popular content becomes more popular, driving
-- engagement and retention. For creators, trending visibility provides
-- motivation to create high-quality content.
--
-- The design uses velocity-based scoring that prioritizes content with
-- rapid recent engagement over older content with high total engagement.
-- Decay algorithms ensure that yesterday's viral content doesn't crowd out
-- today's emerging content. Geographic segmentation enables local trending
-- (content popular in specific regions). Content-type segregation ensures
-- diversity in trending feeds.
--
-- Key Performance Indicators (KPIs):
--   1. Trend Freshness: Average age of trending content (<12 hours)
--   2. Engagement Lift: Increase in engagement for trending content (3-5x)
--   3. Diversity Score: Distribution across content types and topics
--   4. Geographic Relevance: Local content appearing in local feeds
--   5. Spam Rate: Percentage of trending content later flagged as spam (<1%)
--   6. User Satisfaction: Positive feedback on trending content (>80%)
--   7. Churn Prevention: Users engaging with trending content vs. leaving
--
-- Feature Reference: FEED-10 (Trending Content)
-- Requirements Traceability: R-TREND-021 through R-TREND-035
--
-- Normalization: 3NF - Content independent with temporal scoring
--
-- High-Write Considerations:
--   - Write-heavy during trend recalculation
--   - Read-heavy for feed generation
--   - Partitioned by detection_date for TTL-based cleanup
--   - Partial indexes for active trending content only
-------------------------------------------------------------------------------
CREATE TABLE public.trending_content (
    -- Primary key
    trending_content_id UUID DEFAULT gen_random_uuid() NOT NULL,
    detection_date DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Content reference
    content_id UUID NOT NULL REFERENCES public.contents(content_id) ON DELETE CASCADE,
    content_type VARCHAR(50) NOT NULL, -- Denormalized from contents

    -- Trending metrics
    velocity_score NUMERIC(10,6) NOT NULL, -- Engagement rate over time
    acceleration_score NUMERIC(10,6), -- Change in velocity
    total_engagement INTEGER NOT NULL DEFAULT 0,
    engagement_rate NUMERIC(10,6), -- Engagement per unit time

    -- Time decay
    base_score NUMERIC(10,6) NOT NULL,
    decay_factor NUMERIC(5,4) DEFAULT 0.95,
    final_score NUMERIC(10,6) GENERATED ALWAYS AS (base_score * decay_factor ^ (EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - first_detected_at))/3600)) STORED,

    -- Trending status
    first_detected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    trending_start_time TIMESTAMP WITH TIME ZONE,
    trending_end_time TIMESTAMP WITH TIME ZONE,
    is_trending BOOLEAN GENERATED ALWAYS AS (
        trending_end_time IS NULL OR trending_end_time > CURRENT_TIMESTAMP
    ) STORED,

    -- Geographic context
    geographic_scope VARCHAR(50) CHECK (geographic_scope IN ('global', 'country', 'region', 'city')),
    country_code CHAR(2),
    region VARCHAR(100),
    city VARCHAR(100),

    -- Content metadata (denormalized for performance)
    content_author_id UUID,
    content_age_hours INTEGER,
    content_quality_score NUMERIC(5,4),

    -- Trending category
    trending_category VARCHAR(50) CHECK (trending_category IN (
        'viral', 'rising', 'sustained', 'local', 'niche', 'seasonal'
    )),

    -- Boosting factors
    boost_multiplier NUMERIC(3,2) DEFAULT 1.0, -- Additional boost for feed
    promoted BOOLEAN DEFAULT false, -- Manually promoted content

    -- Related trending topics
    related_topic_ids UUID[], -- Which trending topics this content relates to

    -- Algorithm metadata
    detection_algorithm_version VARCHAR(50),
    parameters_used JSONB,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT unique_content_detection UNIQUE (content_id, detection_date),

    PRIMARY KEY (trending_content_id, detection_date)
) PARTITION BY RANGE (detection_date);

COMMENT ON TABLE public.trending_content IS 'Temporarily stores trending content with decay algorithms for feed boosting';
COMMENT ON COLUMN public.trending_content.trending_content_id IS 'Primary key';
COMMENT ON COLUMN public.trending_content.detection_date IS 'Date of trend detection (partition key)';
COMMENT ON COLUMN public.trending_content.content_id IS 'Content that is trending';
COMMENT ON COLUMN public.trending_content.velocity_score IS 'Engagement rate over time';
COMMENT ON COLUMN public.trending_content.acceleration_score IS 'Change in velocity';
COMMENT ON COLUMN public.trending_content.total_engagement IS 'Total engagement count';
COMMENT ON COLUMN public.trending_content.final_score IS 'Score after time decay (generated)';
COMMENT ON COLUMN public.trending_content.first_detected_at IS 'When content started trending';
COMMENT ON COLUMN public.trending_content.trending_start_time IS 'When trending period began';
COMMENT ON COLUMN public.trending_content.trending_end_time IS 'When trending period ended';
COMMENT ON COLUMN public.trending_content.is_trending IS 'Whether currently trending';
COMMENT ON COLUMN public.trending_content.geographic_scope IS 'Geographic scope of trending';
COMMENT ON COLUMN public.trending_content.trending_category IS 'Category of trending pattern';
COMMENT ON COLUMN public.trending_content.boost_multiplier IS 'Additional boost for feed';

-- Create partitions (same pattern as trending_topics)
SELECT public.create_trending_topics_partition(  -- Reuse partition function
    EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER,
    EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER + 2
);

-- Global indexes
CREATE INDEX idx_trending_content_content ON public.trending_content(content_id, detection_date DESC);
CREATE INDEX idx_trending_content_score ON public.trending_content(final_score DESC) WHERE is_trending = true;
CREATE INDEX idx_trending_content_geo ON public.trending_content(geographic_scope, country_code, region, city)
    WHERE is_trending = true;
CREATE INDEX idx_trending_content_category ON public.trending_content(trending_category) WHERE trending_category IS NOT NULL;
CREATE INDEX idx_trending_content_first_detected ON public.trending_content(first_detected_at DESC);

-- GIN index for related topics
CREATE INDEX idx_trending_content_related_topics ON public.trending_content USING gin(related_topic_ids);

-- Trigger for updated_at
CREATE TRIGGER update_trending_content_timestamp
    BEFORE UPDATE ON public.trending_content
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.trending_content ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY trending_content_read_policy ON public.trending_content
    FOR SELECT USING (true);

CREATE POLICY trending_content_write_policy ON public.trending_content
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'data_scientist')
    ));

-- =============================================================================
-- TABLE 92: content_quality_scores
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 92
-- Table Name: content_quality_scores
-- Description: ML-based content quality and spam scores with explainability,
--              used for feed ranking, moderation, and spam filtering.
--
-- Business Case (300 words):
-- Content quality varies widely in user-generated platforms. Without quality
-- scoring, low-quality content, spam, and misinformation can overwhelm feeds,
-- driving away valuable users and damaging platform reputation. This table
-- provides the quality signals needed to promote high-quality content and
-- demote or filter problematic content.
--
-- The business impact is profound: platforms with effective quality filtering
-- see 40% higher user satisfaction and 25% lower churn. Spam reduction protects
-- user experience and reduces moderation costs. Promoting high-quality content
-- incentivizes creators to produce better content, creating a virtuous cycle.
--
-- The design uses multiple ML models to score different quality dimensions:
-- textual quality (grammar, readability), engagement potential, spam likelihood,
-- misinformation risk, and appropriateness. Each score includes confidence
-- intervals and explainability data, enabling human moderators to understand
-- why content was flagged.
--
-- Versioning tracks model improvements over time, allowing A/B testing of new
-- quality algorithms. The combination of automated scoring with human review
-- flags provides a scalable moderation pipeline. Scores are updated as new
-- interactions provide additional signals.
--
-- Key Performance Indicators (KPIs):
--   1. Classification Accuracy: Precision/recall on test sets (>90%)
--   2. Spam Detection Rate: Percentage of spam caught before user report (>95%)
--   3. False Positive Rate: Good content incorrectly flagged (<1%)
--   4. Moderation Efficiency: Reduction in human review time (>50%)
--   5. Quality Distribution: Percentage of content in each quality bucket
--   6. Model Freshness: Time since last model update (<7 days)
--   7. User Satisfaction: Correlation with reported content quality
--
-- Feature Reference: FEED-11 (Content Quality)
-- Requirements Traceability: R-QUALITY-001 through R-QUALITY-025
--
-- Normalization: 3NF - Scores dependent on content with model references
--
-- High-Write Considerations:
--   - Write-heavy during content creation
--   - Read-heavy for feed ranking
--   - Partitioned by content_id hash for distribution
--   - Partial indexes for active content only
-------------------------------------------------------------------------------
CREATE TABLE public.content_quality_scores (
    -- Primary key
    quality_id UUID DEFAULT gen_random_uuid() NOT NULL,
    content_id UUID NOT NULL REFERENCES public.contents(content_id) ON DELETE CASCADE,

    -- Model context
    model_id UUID NOT NULL REFERENCES public.feed_ranking_models(model_id) ON DELETE CASCADE,
    model_version VARCHAR(50) NOT NULL,

    -- Quality dimensions
    overall_quality_score NUMERIC(5,4) CHECK (overall_quality_score >= 0 AND overall_quality_score <= 1),
    spam_score NUMERIC(5,4) CHECK (spam_score >= 0 AND spam_score <= 1),
    misinformation_score NUMERIC(5,4) CHECK (misinformation_score >= 0 AND misinformation_score <= 1),
    inappropriate_score NUMERIC(5,4) CHECK (inappropriate_score >= 0 AND inappropriate_score <= 1),
    clickbait_score NUMERIC(5,4) CHECK (clickbait_score >= 0 AND clickbait_score <= 1),
    duplicate_score NUMERIC(5,4) CHECK (duplicate_score >= 0 AND duplicate_score <= 1),
    low_quality_score NUMERIC(5,4) CHECK (low_quality_score >= 0 AND low_quality_score <= 1),

    -- Quality label (derived from scores)
    quality_label public.content_quality_label NOT NULL,
    confidence_score NUMERIC(5,4) CHECK (confidence_score >= 0 AND confidence_score <= 1),

    -- Score components (for explainability)
    component_scores JSONB, -- Detailed breakdown
    feature_importance JSONB, -- Which features influenced score
    explanation_text TEXT, -- Human-readable explanation

    -- Text analysis metrics
    readability_score NUMERIC(5,4), -- Flesch-Kincaid, etc.
    grammar_score NUMERIC(5,4),
    sentiment_score NUMERIC(5,4) CHECK (sentiment_score >= -1 AND sentiment_score <= 1),
    toxicity_score NUMERIC(5,4) CHECK (toxicity_score >= 0 AND toxicity_score <= 1),

    -- Image/video analysis (if applicable)
    image_quality_score NUMERIC(5,4),
    inappropriate_image_score NUMERIC(5,4),
    video_transcript_quality NUMERIC(5,4),

    -- Source credibility
    author_reputation_score NUMERIC(5,4), -- Based on author history
    source_credibility_score NUMERIC(5,4), -- Based on domain/source

    -- Historical performance
    predicted_engagement_score NUMERIC(5,4), -- Expected engagement
    actual_engagement_correlation NUMERIC(5,4), -- How well predictions matched

    -- Moderation flags
    requires_moderation BOOLEAN GENERATED ALWAYS AS (
        spam_score > 0.7 OR inappropriate_score > 0.7 OR misinformation_score > 0.7
    ) STORED,
    moderation_priority VARCHAR(20) CHECK (moderation_priority IN ('low', 'medium', 'high', 'critical')),
    auto_moderated BOOLEAN DEFAULT false, -- Automatically filtered
    moderated_at TIMESTAMP WITH TIME ZONE,
    moderated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Score validity
    scored_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    valid_until TIMESTAMP WITH TIME ZONE,
    is_current BOOLEAN GENERATED ALWAYS AS (valid_until IS NULL OR valid_until > CURRENT_TIMESTAMP) STORED,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Constraints
    CONSTRAINT unique_content_model_version UNIQUE (content_id, model_id, scored_at),

    PRIMARY KEY (quality_id, content_id)
) PARTITION BY HASH (content_id);

COMMENT ON TABLE public.content_quality_scores IS 'ML-based content quality and spam scores for feed ranking and moderation';
COMMENT ON COLUMN public.content_quality_scores.quality_id IS 'Primary key';
COMMENT ON COLUMN public.content_quality_scores.content_id IS 'Content being scored (partition key)';
COMMENT ON COLUMN public.content_quality_scores.model_id IS 'Model used for scoring';
COMMENT ON COLUMN public.content_quality_scores.overall_quality_score IS 'Overall quality score (0-1)';
COMMENT ON COLUMN public.content_quality_scores.spam_score IS 'Likelihood of being spam';
COMMENT ON COLUMN public.content_quality_scores.misinformation_score IS 'Likelihood of misinformation';
COMMENT ON COLUMN public.content_quality_scores.quality_label IS 'Derived quality classification';
COMMENT ON COLUMN public.content_quality_scores.confidence_score IS 'Confidence in classification';
COMMENT ON COLUMN public.content_quality_scores.component_scores IS 'Detailed score breakdown';
COMMENT ON COLUMN public.content_quality_scores.explanation_text IS 'Human-readable explanation';
COMMENT ON COLUMN public.content_quality_scores.readability_score IS 'Text readability metric';
COMMENT ON COLUMN public.content_quality_scores.toxicity_score IS 'Content toxicity level';
COMMENT ON COLUMN public.content_quality_scores.requires_moderation IS 'Flag for human review needed';
COMMENT ON COLUMN public.content_quality_scores.is_current IS 'Whether score is current';

-- Create hash partitions (16 partitions)
CREATE TABLE public.content_quality_scores_p0 PARTITION OF public.content_quality_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 0);
CREATE TABLE public.content_quality_scores_p1 PARTITION OF public.content_quality_scores
    FOR VALUES WITH (MODULUS 16, REMAINDER 1);
-- ... continue through remainder 15

-- Global indexes
CREATE INDEX idx_content_quality_content ON public.content_quality_scores(content_id) WHERE is_current = true;
CREATE INDEX idx_content_quality_label ON public.content_quality_scores(quality_label, overall_quality_score DESC)
    WHERE is_current = true;
CREATE INDEX idx_content_quality_spam ON public.content_quality_scores(spam_score DESC)
    WHERE is_current = true AND spam_score > 0.5;
CREATE INDEX idx_content_quality_moderation ON public.content_quality_scores(requires_moderation, moderation_priority)
    WHERE requires_moderation = true;
CREATE INDEX idx_content_quality_model ON public.content_quality_scores(model_id);

-- GIN indexes for JSONB
CREATE INDEX idx_content_quality_components ON public.content_quality_scores USING gin(component_scores);
CREATE INDEX idx_content_quality_feature_importance ON public.content_quality_scores USING gin(feature_importance);

-- Trigger for updated_at
CREATE TRIGGER update_content_quality_scores_timestamp
    BEFORE UPDATE ON public.content_quality_scores
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.content_quality_scores ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY content_quality_scores_read_policy ON public.content_quality_scores
    FOR SELECT USING (true);

CREATE POLICY content_quality_scores_write_policy ON public.content_quality_scores
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'data_scientist', 'moderator')
    ));

-- =============================================================================
-- TABLE 93: content_spam_reports
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 93
-- Table Name: content_spam_reports
-- Description: User-reported spam and inappropriate content for training
--              moderation models and manual review workflows.
--
-- Business Case (300 words):
-- Automated quality scoring is never perfect. User reports provide the ground
-- truth needed to train better models and catch content that automated systems
-- miss. This table captures every user report of problematic content, creating
-- a training dataset for improving spam detection and a workflow for human
-- moderation.
--
-- Without user reports, problematic content can persist indefinitely, damaging
-- user trust and platform reputation. Users who see spam and can't report it
-- become frustrated and may leave. This table provides the feedback loop that
-- ensures quality issues are addressed promptly.
--
-- The business impact is direct: platforms with effective reporting systems
-- resolve issues 10x faster, leading to higher user satisfaction. The report
-- data trains better detection models, reducing future spam. For legal
-- compliance, the report log provides evidence of proactive moderation efforts.
--
-- The design captures rich context: why the user reported (spam, inappropriate,
-- misinformation), their confidence level, and any additional comments. Each
-- report can be linked to a moderation action, creating a complete audit trail.
-- Duplicate detection prevents report spam while still capturing signal volume.
--
-- Key Performance Indicators (KPIs):
--   1. Report Accuracy: Percentage of reports resulting in action (>80%)
--   2. Response Time: Average time from report to action (<4 hours)
--   3. Reporter Satisfaction: Users whose reports led to action (>90%)
--   4. False Report Rate: Malicious/incorrect reports (<5%)
--   5. Model Improvement: Lift in detection from training on reports (>10%)
--   6. Coverage: Percentage of problematic content caught by reports
--   7. Moderator Efficiency: Reports handled per hour
--
-- Feature Reference: FEED-12 (Content Reporting)
-- Requirements Traceability: R-REPORT-001 through R-REPORT-020
--
-- Normalization: 3NF - Reports independent with action tracking
--
-- High-Write Considerations:
--   - Moderate write volume (reports less frequent than interactions)
--   - Read-heavy during moderation workflows
--   - Partitioned by reported_at for historical queries
--   - Partial indexes for pending reports only
-------------------------------------------------------------------------------
CREATE TABLE public.content_spam_reports (
    -- Primary key
    report_id UUID DEFAULT gen_random_uuid() NOT NULL,
    reported_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Reporting user
    reporter_user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    reporter_ip INET,
    reporter_user_agent TEXT,

    -- Reported content
    content_id UUID NOT NULL REFERENCES public.contents(content_id) ON DELETE CASCADE,
    content_author_id UUID, -- Denormalized for efficiency

    -- Report details
    report_reason VARCHAR(50) NOT NULL CHECK (report_reason IN (
        'spam', 'inappropriate', 'harassment', 'misinformation',
        'hate_speech', 'violence', 'illegal', 'copyright', 'other'
    )),
    report_confidence VARCHAR(20) CHECK (report_confidence IN ('low', 'medium', 'high', 'certain')),
    report_description TEXT,
    additional_context JSONB,

    -- Duplicate tracking
    duplicate_group_id UUID, -- Group similar reports on same content
    report_count_for_content INTEGER DEFAULT 1,

    -- Content snapshot (in case content is deleted)
    content_snapshot JSONB, -- Snapshot at time of report

    -- Moderation action
    moderation_status VARCHAR(50) DEFAULT 'pending' CHECK (moderation_status IN (
        'pending', 'in_review', 'approved', 'rejected', 'action_taken', 'escalated'
    )),
    moderation_action VARCHAR(50) CHECK (moderation_action IN (
        'none', 'warning_issued', 'content_hidden', 'content_removed',
        'user_suspended', 'user_banned', 'escalated_to_legal'
    )),
    moderation_notes TEXT,
    moderated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    moderated_at TIMESTAMP WITH TIME ZONE,

    -- Feedback to reporter
    reporter_notified BOOLEAN DEFAULT false,
    notification_sent_at TIMESTAMP WITH TIME ZONE,
    feedback_provided TEXT,

    -- Training data linkage
    used_for_training BOOLEAN DEFAULT false,
    training_batch_id UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Constraints
    CONSTRAINT unique_reporter_content UNIQUE (reporter_user_id, content_id),

    PRIMARY KEY (report_id, reported_at)
) PARTITION BY RANGE (reported_at);

COMMENT ON TABLE public.content_spam_reports IS 'User-reported spam and inappropriate content for moderation and model training';
COMMENT ON COLUMN public.content_spam_reports.report_id IS 'Primary key';
COMMENT ON COLUMN public.content_spam_reports.reported_at IS 'When report was submitted (partition key)';
COMMENT ON COLUMN public.content_spam_reports.reporter_user_id IS 'User who submitted report';
COMMENT ON COLUMN public.content_spam_reports.content_id IS 'Content being reported';
COMMENT ON COLUMN public.content_spam_reports.report_reason IS 'Reason for reporting';
COMMENT ON COLUMN public.content_spam_reports.report_confidence IS 'Reporter confidence level';
COMMENT ON COLUMN public.content_spam_reports.duplicate_group_id IS 'Group ID for duplicate reports';
COMMENT ON COLUMN public.content_spam_reports.content_snapshot IS 'Snapshot of content at report time';
COMMENT ON COLUMN public.content_spam_reports.moderation_status IS 'Status of moderation review';
COMMENT ON COLUMN public.content_spam_reports.moderation_action IS 'Action taken on report';
COMMENT ON COLUMN public.content_spam_reports.moderated_by IS 'Moderator who handled report';
COMMENT ON COLUMN public.content_spam_reports.moderated_at IS 'When moderation was completed';

-- Create partition management function (reuse from feed_interactions)
SELECT public.create_feed_interactions_partition(CURRENT_DATE);
-- Create additional partitions as needed

-- Global indexes
CREATE INDEX idx_spam_reports_status ON public.content_spam_reports(moderation_status, reported_at DESC)
    WHERE moderation_status = 'pending';
CREATE INDEX idx_spam_reports_content ON public.content_spam_reports(content_id, reported_at DESC);
CREATE INDEX idx_spam_reports_reporter ON public.content_spam_reports(reporter_user_id, reported_at DESC);
CREATE INDEX idx_spam_reports_reason ON public.content_spam_reports(report_reason);
CREATE INDEX idx_spam_reports_duplicate ON public.content_spam_reports(duplicate_group_id) WHERE duplicate_group_id IS NOT NULL;

-- GIN index for content snapshot
CREATE INDEX idx_spam_reports_snapshot ON public.content_spam_reports USING gin(content_snapshot);

-- Trigger for updated_at
CREATE TRIGGER update_content_spam_reports_timestamp
    BEFORE UPDATE ON public.content_spam_reports
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.content_spam_reports ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY spam_reports_self_policy ON public.content_spam_reports
    FOR SELECT USING (reporter_user_id = current_user_id());

CREATE POLICY spam_reports_moderator_policy ON public.content_spam_reports
    FOR ALL USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'moderator')
    ));

-- =============================================================================
-- TABLE 94: feed_impressions
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 94
-- Table Name: feed_impressions
-- Description: Raw feed impression logs tracking which items were shown to
--              users, their positions, and context for analytics and ad billing.
--
-- Business Case (300 words):
-- Understanding what content users see is as important as understanding what
-- they interact with. Feed impressions capture the denominator for all
-- engagement metrics—without knowing what was shown, you cannot calculate
-- click-through rates, measure ranking effectiveness, or bill for sponsored
-- content impressions.
--
-- The business impact is foundational: impression data enables accurate
-- measurement of feed performance. Advertisers pay for impressions, so accurate
-- counting is essential for revenue. Product teams use impression data to
-- measure ranking algorithm effectiveness—are users seeing relevant content?
-- For personalization, impression data reveals what content was available
-- but not chosen.
--
-- The design captures every feed item shown to every user, with position,
-- context, and timing. This creates an immense dataset that powers analytics,
-- billing, and model training. The sheer volume requires careful partitioning
-- and efficient storage strategies. Sampling may be used for non-critical
-- analytics to control costs.
--
-- For sponsored content, impression data must be immutable for billing
-- integrity. Each impression includes the auction winner, bid price, and
-- delivery context. This creates an auditable trail for advertiser billing
-- and dispute resolution.
--
-- Key Performance Indicators (KPIs):
--   1. Impression Volume: Items shown per user per session
--   2. Viewable Impressions: Percentage in viewport (>50%)
--   3. Data Completeness: Percentage of feeds with full impression logging (100%)
--   4. Billing Accuracy: 100% match between impressions and invoices
--   5. Storage Efficiency: Compression ratio of impression logs (>10:1)
--   6. Query Performance: Time to retrieve impressions for analysis (<1 second)
--   7. Sampling Accuracy: Statistical validity of sampled data
--
-- Feature Reference: FEED-13 (Impression Tracking)
-- Requirements Traceability: R-IMPRESSION-001 through R-IMPRESSION-025
--
-- Normalization: 3NF - Impressions independent with full context
--
-- High-Write Considerations:
--   - Extremely high write volume (every feed item shown)
--   - Partitioned by impression_time for write scalability
--   - UNLOGGED table considered for non-critical analytics
--   - Automatic archival to cold storage after 30 days
--   - Sampling for non-billing analytics
-------------------------------------------------------------------------------
CREATE TABLE public.feed_impressions (
    -- Primary key (composite for partitioning)
    impression_id UUID DEFAULT gen_random_uuid() NOT NULL,
    impression_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- User context
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    session_id UUID,

    -- Feed item shown
    feed_item_id UUID NOT NULL,
    content_id UUID REFERENCES public.contents(content_id) ON DELETE SET NULL,
    item_type public.feed_item_type NOT NULL,
    item_source_id UUID,

    -- Impression context
    feed_position INTEGER NOT NULL CHECK (feed_position >= 0),
    feed_page INTEGER DEFAULT 1,
    feed_type VARCHAR(50) CHECK (feed_type IN ('main', 'job', 'network', 'trending', 'sponsored')),
    feed_session_id UUID, -- Unique feed load session

    -- Visibility
    viewport_position INTEGER, -- Scroll position
    viewport_height INTEGER,
    time_in_viewport_ms INTEGER, -- How long visible
    was_visible BOOLEAN DEFAULT true,
    visible_percentage INTEGER CHECK (visible_percentage BETWEEN 0 AND 100),

    -- Ranking context
    ranking_model_id UUID,
    ranking_score NUMERIC(10,6),
    predicted_engagement_score NUMERIC(5,4),

    -- Sponsored content (if applicable)
    is_sponsored BOOLEAN DEFAULT false,
    campaign_id UUID,
    advertiser_id UUID,
    bid_amount NUMERIC(10,4),
    auction_winner BOOLEAN DEFAULT true,
    delivery_platform VARCHAR(50),

    -- User engagement (post-impression)
    was_clicked BOOLEAN DEFAULT false,
    click_time TIMESTAMP WITH TIME ZONE,
    click_position INTEGER,
    interaction_count INTEGER DEFAULT 0,

    -- Device context
    user_agent TEXT,
    ip_address INET,
    device_type VARCHAR(50),
    platform VARCHAR(50),

    -- A/B testing
    experiment_id UUID,
    experiment_variant VARCHAR(50),

    -- Sampling
    is_sampled BOOLEAN DEFAULT false,
    sample_rate NUMERIC(3,2), -- 1.0 = 100%, 0.01 = 1%

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_impression CHECK (
        (is_sponsored = false) OR
        (is_sponsored = true AND campaign_id IS NOT NULL AND advertiser_id IS NOT NULL)
    ),

    PRIMARY KEY (impression_id, impression_time)
) PARTITION BY RANGE (impression_time);

COMMENT ON TABLE public.feed_impressions IS 'Raw feed impression logs for analytics, model training, and ad billing';
COMMENT ON COLUMN public.feed_impressions.impression_id IS 'Primary key';
COMMENT ON COLUMN public.feed_impressions.impression_time IS 'When impression occurred (partition key)';
COMMENT ON COLUMN public.feed_impressions.user_id IS 'User who saw the impression';
COMMENT ON COLUMN public.feed_impressions.feed_item_id IS 'ID of the feed item shown';
COMMENT ON COLUMN public.feed_impressions.content_id IS 'Related content (if applicable)';
COMMENT ON COLUMN public.feed_impressions.item_type IS 'Type of feed item';
COMMENT ON COLUMN public.feed_impressions.feed_position IS 'Position in feed (0-based)';
COMMENT ON COLUMN public.feed_impressions.feed_type IS 'Type of feed';
COMMENT ON COLUMN public.feed_impressions.time_in_viewport_ms IS 'How long item was visible';
COMMENT ON COLUMN public.feed_impressions.ranking_model_id IS 'Model used for ranking';
COMMENT ON COLUMN public.feed_impressions.is_sponsored IS 'Whether this is sponsored content';
COMMENT ON COLUMN public.feed_impressions.campaign_id IS 'Ad campaign ID (if sponsored)';
COMMENT ON COLUMN public.feed_impressions.bid_amount IS 'Bid amount for auction';
COMMENT ON COLUMN public.feed_impressions.was_clicked IS 'Whether user clicked';
COMMENT ON COLUMN public.feed_impressions.is_sampled IS 'Whether this is a sampled impression';

-- Create partition management function (reuse from feed_interactions)
-- Create daily partitions for next 30 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..30 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_feed_interactions_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_feed_impressions_user_time ON public.feed_impressions(user_id, impression_time DESC);
CREATE INDEX idx_feed_impressions_content ON public.feed_impressions(content_id) WHERE content_id IS NOT NULL;
CREATE INDEX idx_feed_impressions_session ON public.feed_impressions(session_id) WHERE session_id IS NOT NULL;
CREATE INDEX idx_feed_impressions_feed_session ON public.feed_impressions(feed_session_id);
CREATE INDEX idx_feed_impressions_sponsored ON public.feed_impressions(campaign_id, impression_time DESC) WHERE is_sponsored = true;
CREATE INDEX idx_feed_impressions_clicked ON public.feed_impressions(was_clicked, impression_time DESC) WHERE was_clicked = true;
CREATE INDEX idx_feed_impressions_experiment ON public.feed_impressions(experiment_id) WHERE experiment_id IS NOT NULL;

-- Enable RLS
ALTER TABLE public.feed_impressions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY feed_impressions_self_policy ON public.feed_impressions
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY feed_impressions_analyst_policy ON public.feed_impressions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'analyst', 'data_scientist')
    ));

-- =============================================================================
-- TABLE 95: feed_control_settings
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 95
-- Table Name: feed_control_settings
-- Description: User feed preference controls including content filtering,
--              source muting, topic preferences, and algorithmic adjustments.
--
-- Business Case (300 words):
-- Giving users control over their feed experience is essential for satisfaction
-- and retention. Some users want to see more from specific sources, others
-- want to hide certain topics, and everyone wants the ability to tune their
-- experience. This table stores all user-level feed controls, enabling
-- personalization while respecting user preferences.
--
-- Without feed controls, users are powerless when they see content they don't
-- like. They may become frustrated and leave rather than continuing to see
-- unwanted content. Providing controls reduces churn and increases satisfaction.
-- For the platform, user preferences provide valuable signals about what
-- content is valued.
--
-- The business impact is direct: platforms with granular user controls see
-- 30% higher user satisfaction and 20% lower churn. The preference data
-- trains better recommendation models—users who mute certain sources are
-- telling us what they don't want. For compliance, controls demonstrate
-- respect for user autonomy.
--
-- The design supports multiple control types: source following/unfollowing,
-- topic preferences, content type filtering, keyword blocking, and algorithmic
-- tuning (more/less of certain content). Controls can be temporary (vacation
-- mode) or permanent. The system respects user choices while still providing
-- a coherent feed experience.
--
-- Key Performance Indicators (KPIs):
--   1. Control Usage: Percentage of users using at least one control (>40%)
--   2. Control Diversity: Average number of controls per user
--   3. Mute Effectiveness: Reduction in unwanted content after muting (>80%)
--   4. Control Satisfaction: Users satisfied with controls (>90%)
--   5. Churn Reduction: Lower churn among users who use controls
--   6. Control Freshness: Time since last control update
--   7. Preference Accuracy: Match between controls and actual preferences
--
-- Feature Reference: FEED-14 (Feed Controls)
-- Requirements Traceability: R-CONTROL-001 through R-CONTROL-020
--
-- Normalization: 3NF - Controls dependent on users with flexible types
--
-- High-Write Considerations:
--   - Low write volume (user changes infrequent)
--   - Read-heavy for every feed generation
--   - Caching critical (Redis recommended)
--   - JSONB for flexible control parameters
-------------------------------------------------------------------------------
CREATE TABLE public.feed_control_settings (
    -- Primary key
    control_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Control identification
    control_type VARCHAR(50) NOT NULL CHECK (control_type IN (
        'follow', 'unfollow', 'mute', 'block', 'prefer_more', 'prefer_less',
        'topic_interest', 'keyword_block', 'content_type_filter', 'algorithm_tuning',
        'temporary_pause', 'sensitive_content_filter'
    )),
    control_target_type VARCHAR(50) CHECK (control_target_type IN (
        'user', 'company', 'topic', 'hashtag', 'keyword', 'content_type',
        'source', 'group', 'event'
    )),
    control_target_id UUID, -- ID of target (user_id, company_id, etc.)
    control_target_text TEXT, -- For text-based targets (keywords, hashtags)

    -- Control parameters
    parameters JSONB, -- Additional parameters (strength, duration, etc.)
    priority INTEGER DEFAULT 100 CHECK (priority BETWEEN 1 AND 1000), -- Lower = higher priority

    -- Temporal scope
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE, -- For temporary controls
    is_active BOOLEAN GENERATED ALWAYS AS (
        expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP
    ) STORED,

    -- Source of control
    source VARCHAR(50) CHECK (source IN ('user_action', 'algorithm_suggestion', 'system_default')),

    -- Impact metrics
    times_applied INTEGER DEFAULT 0, -- How many times this control affected feed
    last_applied_at TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Metadata
    notes TEXT,
    tags TEXT[],

    -- Constraints
    CONSTRAINT valid_target CHECK (
        (control_target_type IS NOT NULL AND control_target_id IS NOT NULL) OR
        (control_target_type = 'keyword' AND control_target_text IS NOT NULL) OR
        (control_target_type IS NULL)
    ),
    CONSTRAINT unique_user_control_target UNIQUE (user_id, control_type, control_target_type, control_target_id, control_target_text)
);

COMMENT ON TABLE public.feed_control_settings IS 'User feed preference controls for personalization and filtering';
COMMENT ON COLUMN public.feed_control_settings.control_id IS 'Primary key';
COMMENT ON COLUMN public.feed_control_settings.user_id IS 'User who set the control';
COMMENT ON COLUMN public.feed_control_settings.control_type IS 'Type of control';
COMMENT ON COLUMN public.feed_control_settings.control_target_type IS 'Type of target being controlled';
COMMENT ON COLUMN public.feed_control_settings.control_target_id IS 'ID of target (if applicable)';
COMMENT ON COLUMN public.feed_control_settings.control_target_text IS 'Text target (keywords, hashtags)';
COMMENT ON COLUMN public.feed_control_settings.parameters IS 'Additional control parameters';
COMMENT ON COLUMN public.feed_control_settings.priority IS 'Priority (lower = applied first)';
COMMENT ON COLUMN public.feed_control_settings.expires_at IS 'When control expires';
COMMENT ON COLUMN public.feed_control_settings.is_active IS 'Whether control is currently active';
COMMENT ON COLUMN public.feed_control_settings.source IS 'How control was created';

-- Indexes
CREATE INDEX idx_feed_controls_user ON public.feed_control_settings(user_id, is_active);
CREATE INDEX idx_feed_controls_type ON public.feed_control_settings(control_type);
CREATE INDEX idx_feed_controls_target ON public.feed_control_settings(control_target_type, control_target_id)
    WHERE control_target_id IS NOT NULL;
CREATE INDEX idx_feed_controls_expires ON public.feed_control_settings(expires_at) WHERE expires_at IS NOT NULL;

-- Partial index for active controls only
CREATE INDEX idx_feed_controls_active ON public.feed_control_settings(user_id) WHERE is_active = true;

-- GIN index for parameters
CREATE INDEX idx_feed_controls_parameters ON public.feed_control_settings USING gin(parameters);
CREATE INDEX idx_feed_controls_tags ON public.feed_control_settings USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_feed_control_settings_timestamp
    BEFORE UPDATE ON public.feed_control_settings
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.feed_control_settings ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY feed_controls_self_policy ON public.feed_control_settings
    FOR ALL USING (user_id = current_user_id());

CREATE POLICY feed_controls_system_policy ON public.feed_control_settings
    FOR SELECT USING (current_user = 'feed_generation_service');

-- =============================================================================
-- TABLE 96: content_diversity_buckets
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 96
-- Table Name: content_diversity_buckets
-- Description: Content categorization for feed diversity optimization, ensuring
--              users see a balanced mix of content types, topics, and sources.
--
-- Business Case (300 words):
-- Personalized feeds can create filter bubbles where users only see content
-- similar to what they've already engaged with. While this increases short-term
-- engagement, it reduces long-term satisfaction and discovery. Diversity
-- optimization ensures users see a balanced mix of content, breaking filter
-- bubbles while maintaining relevance.
--
-- Without diversity controls, feeds become homogeneous and predictable. Users
-- miss serendipitous discoveries, get bored, and eventually disengage. This
-- table provides the categorization needed to enforce diversity constraints—
-- ensuring that feeds contain a mix of content types, topics, and sources.
--
-- The business impact is significant: platforms with diversity optimization
-- see 25% higher long-term retention and 40% more content discovery. Users
-- report higher satisfaction when they discover unexpected content. For
-- creators, diversity ensures that niche content still gets visibility.
--
-- The design categorizes content along multiple dimensions: content type
-- (post, article, video), topic category (industry, technology, career),
-- source type (individual, company, group), content age (fresh vs. evergreen),
-- and engagement level (viral vs. niche). Each piece of content is assigned
-- to buckets in each dimension, enabling multi-dimensional diversity constraints.
--
-- Key Performance Indicators (KPIs):
--   1. Diversity Score: Distribution across content categories
--   2. Filter Bubble Reduction: New topics discovered per user
--   3. Niche Content Visibility: Percentage of niche content in feeds
--   4. User Satisfaction: Correlation with diversity metrics
--   5. Bucket Coverage: Percentage of content categorized (>95%)
--   6. Categorization Accuracy: Manual review accuracy (>90%)
--   7. Freshness: New content appearing in under-represented buckets
--
-- Feature Reference: FEED-15 (Diversity Management)
-- Requirements Traceability: R-DIVERSITY-001 through R-DIVERSITY-015
--
-- Normalization: 3NF - Buckets assigned to content with multiple dimensions
--
-- High-Write Considerations:
--   - Write-heavy during content creation
--   - Read-heavy for every feed generation
--   - Partitioned by content_id hash for distribution
--   - JSONB for flexible bucket definitions
-------------------------------------------------------------------------------
CREATE TABLE public.content_diversity_buckets (
    -- Primary key
    bucket_id UUID DEFAULT gen_random_uuid() NOT NULL,
    content_id UUID NOT NULL REFERENCES public.contents(content_id) ON DELETE CASCADE,

    -- Bucket dimensions
    bucket_type public.diversity_bucket_type NOT NULL,
    bucket_value VARCHAR(255) NOT NULL, -- e.g., 'technology' for topic, 'post' for type
    bucket_normalized VARCHAR(255), -- Normalized for matching

    -- Bucket hierarchy
    parent_bucket VARCHAR(255), -- Parent category (e.g., 'technology' parent of 'ai')
    bucket_level INTEGER DEFAULT 1, -- Depth in hierarchy

    -- Confidence in assignment
    assignment_confidence NUMERIC(5,4) CHECK (assignment_confidence >= 0 AND assignment_confidence <= 1),
    assignment_method VARCHAR(50) CHECK (assignment_method IN ('ml_classification', 'rule_based', 'manual', 'derived')),

    -- Temporal validity
    valid_from TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    valid_until TIMESTAMP WITH TIME ZONE,
    is_current BOOLEAN GENERATED ALWAYS AS (valid_until IS NULL OR valid_until > CURRENT_TIMESTAMP) STORED,

    -- Scoring
    bucket_weight NUMERIC(5,4) DEFAULT 1.0, -- Importance of this bucket

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Metadata
    source_system VARCHAR(100),
    tags TEXT[],

    -- Constraints
    CONSTRAINT unique_content_bucket UNIQUE (content_id, bucket_type, bucket_value),

    PRIMARY KEY (bucket_id, content_id)
) PARTITION BY HASH (content_id);

COMMENT ON TABLE public.content_diversity_buckets IS 'Content categorization for feed diversity optimization';
COMMENT ON COLUMN public.content_diversity_buckets.bucket_id IS 'Primary key';
COMMENT ON COLUMN public.content_diversity_buckets.content_id IS 'Content being categorized (partition key)';
COMMENT ON COLUMN public.content_diversity_buckets.bucket_type IS 'Dimension of diversity';
COMMENT ON COLUMN public.content_diversity_buckets.bucket_value IS 'Value in this dimension';
COMMENT ON COLUMN public.content_diversity_buckets.bucket_normalized IS 'Normalized value for matching';
COMMENT ON COLUMN public.content_diversity_buckets.parent_bucket IS 'Parent in hierarchy';
COMMENT ON COLUMN public.content_diversity_buckets.bucket_level IS 'Depth in hierarchy';
COMMENT ON COLUMN public.content_diversity_buckets.assignment_confidence IS 'Confidence in classification';
COMMENT ON COLUMN public.content_diversity_buckets.assignment_method IS 'How bucket was assigned';
COMMENT ON COLUMN public.content_diversity_buckets.valid_from IS 'When bucket assignment starts';
COMMENT ON COLUMN public.content_diversity_buckets.valid_until IS 'When bucket assignment ends';
COMMENT ON COLUMN public.content_diversity_buckets.is_current IS 'Whether bucket is current';
COMMENT ON COLUMN public.content_diversity_buckets.bucket_weight IS 'Importance weight';

-- Create hash partitions (16 partitions) - reuse pattern from content_quality_scores

-- Global indexes
CREATE INDEX idx_diversity_buckets_content ON public.content_diversity_buckets(content_id) WHERE is_current = true;
CREATE INDEX idx_diversity_buckets_type_value ON public.content_diversity_buckets(bucket_type, bucket_value, is_current);
CREATE INDEX idx_diversity_buckets_parent ON public.content_diversity_buckets(parent_bucket) WHERE parent_bucket IS NOT NULL;

-- GIN index for tags
CREATE INDEX idx_diversity_buckets_tags ON public.content_diversity_buckets USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_content_diversity_buckets_timestamp
    BEFORE UPDATE ON public.content_diversity_buckets
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.content_diversity_buckets ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY diversity_buckets_read_policy ON public.content_diversity_buckets
    FOR SELECT USING (true);

CREATE POLICY diversity_buckets_write_policy ON public.content_diversity_buckets
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'data_scientist')
    ));

-- =============================================================================
-- MATERIALIZED VIEW: mv_feed_performance_dashboard
-- =============================================================================
-------------------------------------------------------------------------------
-- Materialized View: mv_feed_performance_dashboard
-- Description: Pre-aggregated feed performance metrics for product teams
-- Refresh Strategy: Hourly
-- Feature Reference: FEED-16 (Feed Analytics)
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW public.mv_feed_performance_dashboard AS
WITH hourly_stats AS (
    SELECT
        DATE_TRUNC('hour', fi.impression_time) as hour,
        fi.feed_type,
        COUNT(DISTINCT fi.user_id) as unique_users,
        COUNT(*) as total_impressions,
        COUNT(*) FILTER (WHERE fi.was_clicked) as total_clicks,
        ROUND((COUNT(*) FILTER (WHERE fi.was_clicked)::NUMERIC / NULLIF(COUNT(*), 0) * 100), 2) as ctr_percentage,
        AVG(fi.time_in_viewport_ms) FILTER (WHERE fi.time_in_viewport_ms IS NOT NULL) as avg_viewport_time_ms
    FROM public.feed_impressions fi
    WHERE fi.impression_time > CURRENT_TIMESTAMP - INTERVAL '7 days'
    GROUP BY DATE_TRUNC('hour', fi.impression_time), fi.feed_type
)
SELECT
    hour,
    feed_type,
    unique_users,
    total_impressions,
    total_clicks,
    ctr_percentage,
    ROUND(avg_viewport_time_ms::NUMERIC, 2) as avg_viewport_time_ms,
    SUM(total_impressions) OVER (PARTITION BY feed_type ORDER BY hour ROWS 23 PRECEDING) as rolling_24h_impressions,
    NOW() as refreshed_at
FROM hourly_stats
ORDER BY hour DESC, feed_type;

COMMENT ON MATERIALIZED VIEW public.mv_feed_performance_dashboard IS 'Pre-aggregated feed performance metrics for product teams';

CREATE UNIQUE INDEX idx_mv_feed_performance_hour ON public.mv_feed_performance_dashboard(hour, feed_type);

-- =============================================================================
-- STORED PROCEDURES
-- =============================================================================

-------------------------------------------------------------------------------
-- Procedure: calculate_trending_scores
-- Description: Recalculates trending scores for content based on recent engagement
-- Business Case: Ensures trending content reflects current popularity
-- Feature Reference: FEED-17 (Trending Recalculation)
-------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE public.calculate_trending_scores(
    p_lookback_hours INTEGER DEFAULT 24,
    p_min_engagement INTEGER DEFAULT 10
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_start_time TIMESTAMP WITH TIME ZONE := CURRENT_TIMESTAMP;
    v_content_count INTEGER := 0;
BEGIN
    -- Clear old trending content
    DELETE FROM public.trending_content
    WHERE is_trending = false OR detection_date < CURRENT_DATE - INTERVAL '7 days';

    -- Insert new trending content
    WITH engagement_data AS (
        SELECT
            fi.content_id,
            c.content_type,
            c.user_id as content_author_id,
            COUNT(*) as engagement_count,
            COUNT(*) FILTER (WHERE fi.interaction_time > CURRENT_TIMESTAMP - INTERVAL '1 hour') as hourly_engagement,
            COUNT(*) FILTER (WHERE fi.interaction_time > CURRENT_TIMESTAMP - INTERVAL '6 hours') as six_hour_engagement,
            EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - MIN(fi.interaction_time)))/3600 as hours_since_first
        FROM public.feed_interactions fi
        JOIN public.contents c ON fi.content_id = c.content_id
        WHERE fi.interaction_time > CURRENT_TIMESTAMP - (p_lookback_hours || ' hours')::INTERVAL
            AND fi.is_positive = true
        GROUP BY fi.content_id, c.content_type, c.user_id
        HAVING COUNT(*) >= p_min_engagement
    )
    INSERT INTO public.trending_content (
        content_id,
        content_type,
        velocity_score,
        acceleration_score,
        total_engagement,
        base_score,
        first_detected_at,
        trending_start_time,
        content_author_id,
        content_age_hours,
        detection_algorithm_version
    )
    SELECT
        ed.content_id,
        ed.content_type,
        ed.hourly_engagement::NUMERIC / 3600 as velocity_score,
        (ed.hourly_engagement - ed.six_hour_engagement/6)::NUMERIC as acceleration_score,
        ed.engagement_count,
        ed.hourly_engagement * LOG(ed.engagement_count + 1) as base_score,
        v_start_time,
        v_start_time,
        ed.content_author_id,
        ed.hours_since_first,
        'v1.0'
    FROM engagement_data ed
    WHERE ed.hourly_engagement > 0
    ORDER BY base_score DESC
    LIMIT 1000;

    GET DIAGNOSTICS v_content_count = ROW_COUNT;

    -- Update trending topics based on new content
    -- (Simplified - would include topic extraction logic)

    -- Log the recalculation
    INSERT INTO public.audit_logs (
        actor_id,
        action,
        entity_type,
        details,
        category,
        severity
    ) VALUES (
        current_user_id(),
        'RECALCULATE_TRENDING',
        'trending_content',
        jsonb_build_object(
            'content_count', v_content_count,
            'lookback_hours', p_lookback_hours,
            'duration_ms', EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - v_start_time)) * 1000
        ),
        'SYSTEM',
        'INFO'
    );

    RAISE NOTICE 'Trending recalculation completed. Processed % content items in % ms',
        v_content_count,
        EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - v_start_time)) * 1000;
END;
$$;

COMMENT ON PROCEDURE public.calculate_trending_scores IS 'Recalculates trending scores for content based on recent engagement';

-- =============================================================================
-- SCHEDULED JOBS
-- =============================================================================

-- Create scheduled jobs if pg_cron is available
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
        -- Recalculate trending scores every 15 minutes
        PERFORM cron.schedule(
            'recalculate-trending',
            '*/15 * * * *',
            'CALL public.calculate_trending_scores(24, 10);'
        );

        -- Refresh feed performance dashboard hourly
        PERFORM cron.schedule(
            'refresh-feed-dashboard',
            '0 * * * *',
            'REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_feed_performance_dashboard;'
        );

        -- Clean up old feed impressions daily (keep 30 days)
        PERFORM cron.schedule(
            'cleanup-old-impressions',
            '0 3 * * *',
            $$
            DELETE FROM public.feed_impressions
            WHERE impression_time < CURRENT_TIMESTAMP - INTERVAL '30 days';
            $$
        );

        -- Archive old feed interactions monthly
        PERFORM cron.schedule(
            'archive-feed-interactions',
            '0 4 1 * *',
            $$
            CREATE TABLE IF NOT EXISTS public.feed_interactions_archive
            AS SELECT * FROM public.feed_interactions
            WHERE interaction_time < CURRENT_TIMESTAMP - INTERVAL '90 days';

            DELETE FROM public.feed_interactions
            WHERE interaction_time < CURRENT_TIMESTAMP - INTERVAL '90 days';
            $$
        );
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'pg_cron extension not available. Scheduled tasks will not be created.';
END $$;

