-- =============================================================================
-- ENUMS FOR NOTIFICATION & COMMUNICATION SYSTEM
-- =============================================================================

-------------------------------------------------------------------------------
-- Enum: NCS01 - notification_channel
-- Description: Available channels for delivering notifications to users
-- Business Case: Supports omnichannel communication strategy
-- Feature Reference: NOT-01 (Notification Channels)
-------------------------------------------------------------------------------
CREATE TYPE public.notification_channel AS ENUM (
    'IN_APP',           -- Within platform notifications
    'EMAIL',            -- Email delivery
    'PUSH',             -- Mobile push notifications
    'SMS',              -- Text messages
    'WEB_PUSH',         -- Browser push notifications
    'SLACK',            -- Slack integration (for enterprise)
    'DIGEST',           -- Daily/weekly digest emails
    'WHATSAPP',         -- WhatsApp business API
    'TELEGRAM',         -- Telegram bot
    'DISCORD'           -- Discord webhook
);
COMMENT ON TYPE public.notification_channel IS 'Supported notification delivery channels';

-------------------------------------------------------------------------------
-- Enum: NCS02 - notification_priority
-- Description: Priority levels for notifications affecting delivery timing
-- Business Case: Ensures critical notifications are delivered promptly
-- Feature Reference: NOT-02 (Notification Prioritization)
-------------------------------------------------------------------------------
CREATE TYPE public.notification_priority AS ENUM (
    'CRITICAL',         -- Immediate delivery required (security alerts, password reset)
    'HIGH',             -- Deliver within minutes (connection requests, messages)
    'MEDIUM',           -- Deliver within hours (job recommendations, content updates)
    'LOW',              -- Batch with digest (marketing, newsletters)
    'BACKGROUND'        -- No user action required (analytics, internal)
);
COMMENT ON TYPE public.notification_priority IS 'Priority levels affecting notification delivery timing';

-------------------------------------------------------------------------------
-- Enum: NCS03 - notification_delivery_status
-- Description: Status of individual notification delivery attempts
-- Business Case: Enables detailed monitoring and retry logic
-- Feature Reference: NOT-03 (Delivery Tracking)
-------------------------------------------------------------------------------
CREATE TYPE public.notification_delivery_status AS ENUM (
    'PENDING',          -- Queued for delivery
    'IN_FLIGHT',        -- Currently being sent
    'DELIVERED',        -- Successfully delivered (confirmed)
    'FAILED',           -- Permanent failure (invalid address)
    'RETRYING',         -- Will retry after backoff
    'EXPIRED',          -- Max retries exceeded
    'CANCELLED',        -- Manually cancelled
    'BOUNCED',          -- Email bounced (permanent)
    'SPAM',             -- Marked as spam
    'UNSUBSCRIBED',     -- User unsubscribed
    'OPENED',           -- User opened (email/push)
    'CLICKED'           -- User clicked link
);
COMMENT ON TYPE public.notification_delivery_status IS 'Status tracking for notification delivery attempts';

-------------------------------------------------------------------------------
-- Enum: NCS04 - notification_category
-- Description: Categories of notifications for user preference management
-- Business Case: Enables granular user control over notification types
-- Feature Reference: NOT-04 (Notification Categories)
-------------------------------------------------------------------------------
CREATE TYPE public.notification_category AS ENUM (
    'ACCOUNT',          -- Account-related (security, login, password)
    'SOCIAL',           -- Social interactions (connections, messages, comments)
    'JOBS',             -- Job-related (recommendations, applications, offers)
    'CONTENT',          -- Content updates (posts, articles, likes)
    'EVENTS',           -- Event reminders and invitations
    'COURSES',          -- Learning platform notifications
    'PAYMENTS',         -- Billing and subscription notifications
    'PROMOTIONS',       -- Marketing and promotional messages
    'SYSTEM',           -- System announcements and maintenance
    'MODERATION'        -- Content moderation updates
);
COMMENT ON TYPE public.notification_category IS 'Categories for user notification preferences';

-------------------------------------------------------------------------------
-- Enum: NCS05 - subscription_preference
-- Description: User preference levels for notification subscriptions
-- Business Case: Enables fine-grained user control over notification frequency
-- Feature Reference: NOT-05 (User Preferences)
-------------------------------------------------------------------------------
CREATE TYPE public.subscription_preference AS ENUM (
    'ALL',              -- Receive all notifications immediately
    'DIGEST',           -- Receive daily/weekly digest
    'PUSH_ONLY',        -- Receive push notifications only (no email)
    'EMAIL_ONLY',       -- Receive email only (no push)
    'SILENT',           -- Receive but don't alert (in-app only)
    'NONE'              -- Receive none
);
COMMENT ON TYPE public.subscription_preference IS 'User preference levels for notification subscriptions';

-------------------------------------------------------------------------------
-- Enum: NCS06 - message_type
-- Description: Types of messages in the messaging system
-- Business Case: Enables different handling for different message types
-- Feature Reference: MSG-01 (Message Types)
-------------------------------------------------------------------------------
CREATE TYPE public.message_type AS ENUM (
    'DIRECT',           -- One-to-one direct message
    'GROUP',            -- Group conversation message
    'SYSTEM',           -- System-generated message
    'BROADCAST',        -- Broadcast to multiple recipients
    'AUTO_REPLY',       -- Automated reply
    'FORWARDED'         -- Forwarded message
);
COMMENT ON TYPE public.message_type IS 'Types of messages in the messaging system';

-------------------------------------------------------------------------------
-- Enum: NCS07 - message_status
-- Description: Status of individual messages
-- Business Case: Tracks message delivery and read status
-- Feature Reference: MSG-02 (Message Status)
-------------------------------------------------------------------------------
CREATE TYPE public.message_status AS ENUM (
    'SENT',             -- Message sent successfully
    'DELIVERED',        -- Delivered to recipient's device
    'READ',             -- Read by recipient
    'FAILED',           -- Failed to send
    'PENDING',          -- Queued for sending
    'RECALLED',         -- Recalled by sender
    'DELETED'           -- Deleted (soft delete)
);
COMMENT ON TYPE public.message_status IS 'Status of individual messages';

-------------------------------------------------------------------------------
-- Enum: NCS08 - conversation_type
-- Description: Types of conversations in the messaging system
-- Business Case: Enables different features for different conversation types
-- Feature Reference: MSG-03 (Conversation Types)
-------------------------------------------------------------------------------
CREATE TYPE public.conversation_type AS ENUM (
    'ONE_TO_ONE',       -- Private conversation between two users
    'GROUP',            -- Group conversation with multiple participants
    'CHANNEL',          -- Broadcast channel (one-to-many)
    'SUPPORT',          -- Customer support conversation
    'SYSTEM'            -- System notifications conversation
);
COMMENT ON TYPE public.conversation_type IS 'Types of conversations in the messaging system';

-------------------------------------------------------------------------------
-- Enum: NCS09 - participant_role
-- Description: Roles of participants in conversations
-- Business Case: Enables permission management within conversations
-- Feature Reference: MSG-04 (Participant Roles)
-------------------------------------------------------------------------------
CREATE TYPE public.participant_role AS ENUM (
    'OWNER',            -- Conversation creator/owner
    'ADMIN',            -- Administrator (can manage participants)
    'MEMBER',           -- Regular participant
    'MODERATOR',        -- Can moderate content
    'OBSERVER'          -- Read-only participant
);
COMMENT ON TYPE public.participant_role IS 'Roles of participants in conversations';

-- =============================================================================
-- TABLE 97: notification_templates
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 97
-- Table Name: notification_templates
-- Description: Central repository for notification message templates with
--              versioning, localization, multi-channel support, and A/B testing.
--
-- Business Case (300 words):
-- Consistent, well-crafted notification messages are essential for user engagement
-- and brand perception. However, managing message copy across multiple channels
-- (email, push, SMS) and languages quickly becomes chaotic without a centralized
-- system. This table provides a single source of truth for all notification
-- content, enabling marketing teams, product managers, and localization vendors
-- to manage copy without engineering involvement.
--
-- The business value is substantial: consistent messaging improves brand
-- recognition, A/B testing of subject lines can increase open rates by 30%,
-- and centralized management reduces the risk of sending broken or outdated
-- messages. For international growth, the localization support allows the
-- platform to scale to new markets efficiently—adding a new language becomes
-- a data entry task rather than a development project.
--
-- The design supports multiple channels with channel-specific content variants
-- (e.g., shorter push notifications vs. longer emails). Placeholder variables
-- ({{user_name}}, {{link}}) enable personalization while maintaining template
-- structure. Versioning tracks changes over time, enabling rollback if new
-- versions underperform. A/B testing variants can be configured with traffic
-- allocation for systematic optimization.
--
-- For compliance, the table tracks legal approval status and maintains an
-- audit trail of all template changes. This is essential for regulated
-- industries where notification content may require legal review.
--
-- Key Performance Indicators (KPIs):
--   1. Template Usage Frequency: Most commonly used notification types
--   2. A/B Test Performance: Lift in open/click rates from optimized templates
--   3. Localization Coverage: Number of languages per template
--   4. Template Freshness: Time since last update (<6 months)
--   5. Placeholder Error Rate: Missing data causing rendering failures (<0.1%)
--   6. Approval Time: Average time from draft to approved (<48 hours)
--   7. Channel Coverage: Templates available for all major channels
--
-- Feature Reference: NOT-06 (Template Management)
-- Requirements Traceability: R-NOTIFY-001 through R-NOTIFY-025
--
-- Normalization: 3NF - Templates independent with language variants
--
-- High-Write Considerations:
--   - Read-heavy (every notification uses templates)
--   - Write-light (templates change infrequently)
--   - Caching essential (Redis with 1-hour TTL)
--   - Partial indexes for active templates only
-------------------------------------------------------------------------------
CREATE TABLE public.notification_templates (
    -- Primary key
    template_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Template identification
    template_name VARCHAR(255) NOT NULL UNIQUE,
    template_description TEXT,
    notification_type VARCHAR(100) NOT NULL,
    category public.notification_category NOT NULL,

    -- Versioning
    version INTEGER NOT NULL DEFAULT 1,
    is_active BOOLEAN DEFAULT true,
    superseded_by UUID REFERENCES public.notification_templates(template_id) ON DELETE SET NULL,
    deprecated_at TIMESTAMP WITH TIME ZONE,
    deprecation_reason TEXT,

    -- Multi-channel content
    subject TEXT,                                      -- Email subject, push title
    preheader TEXT,                                    -- Email preheader text
    body_template TEXT NOT NULL,                       -- With placeholders like {{variable}}
    html_template TEXT,                                -- HTML version for email
    plain_text_template TEXT,                          -- Plain text fallback
    sms_template TEXT,                                 -- SMS version (short)
    push_title TEXT,                                   -- Push notification title
    push_body TEXT,                                    -- Push notification body
    push_icon TEXT,                                    -- Push notification icon
    push_sound VARCHAR(100),                           -- Push notification sound

    -- Placeholders
    required_placeholders TEXT[],                      -- Variables that must be provided
    optional_placeholders TEXT[],                      -- Variables that can be omitted
    example_payload JSONB,                             -- Example data for testing

    -- Localization
    language_code VARCHAR(10) NOT NULL DEFAULT 'en' REFERENCES public.languages(language_code),
    is_default_language BOOLEAN DEFAULT false,
    fallback_template_id UUID REFERENCES public.notification_templates(template_id) ON DELETE SET NULL,

    -- A/B testing
    experiment_id UUID,                                -- A/B test experiment reference
    variant_name VARCHAR(50),                          -- Variant identifier
    traffic_allocation SMALLINT CHECK (traffic_allocation BETWEEN 0 AND 100),

    -- Performance metrics (aggregated)
    sent_count BIGINT DEFAULT 0,
    delivered_count BIGINT DEFAULT 0,
    opened_count BIGINT DEFAULT 0,
    clicked_count BIGINT DEFAULT 0,
    converted_count BIGINT DEFAULT 0,
    open_rate NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN sent_count > 0
        THEN (opened_count::NUMERIC / sent_count) * 100
        ELSE 0 END
    ) STORED,
    click_rate NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN opened_count > 0
        THEN (clicked_count::NUMERIC / opened_count) * 100
        ELSE 0 END
    ) STORED,
    last_used_at TIMESTAMP WITH TIME ZONE,

    -- Approval workflow
    approval_status VARCHAR(20) DEFAULT 'DRAFT' CHECK (approval_status IN (
        'DRAFT', 'PENDING_REVIEW', 'APPROVED', 'REJECTED', 'ARCHIVED'
    )),
    approved_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    approved_at TIMESTAMP WITH TIME ZONE,
    approval_notes TEXT,

    -- Legal review
    legal_reviewed BOOLEAN DEFAULT false,
    legal_reviewer UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    legal_review_date DATE,
    legal_notes TEXT,

    -- Ownership
    owner_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    owner_team VARCHAR(100),

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    tags TEXT[],
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_approval CHECK (
        (approval_status = 'APPROVED' AND approved_by IS NOT NULL AND approved_at IS NOT NULL) OR
        (approval_status != 'APPROVED')
    )
);

COMMENT ON TABLE public.notification_templates IS 'Central repository for notification message templates';
COMMENT ON COLUMN public.notification_templates.template_id IS 'Primary key';
COMMENT ON COLUMN public.notification_templates.template_name IS 'Unique template identifier';
COMMENT ON COLUMN public.notification_templates.notification_type IS 'Type of notification event';
COMMENT ON COLUMN public.notification_templates.category IS 'Category for user preferences';
COMMENT ON COLUMN public.notification_templates.version IS 'Template version number';
COMMENT ON COLUMN public.notification_templates.is_active IS 'Whether template is currently in use';
COMMENT ON COLUMN public.notification_templates.superseded_by IS 'Newer version of this template';
COMMENT ON COLUMN public.notification_templates.subject IS 'Subject line (email/push)';
COMMENT ON COLUMN public.notification_templates.body_template IS 'Message body with placeholders';
COMMENT ON COLUMN public.notification_templates.html_template IS 'HTML version for email';
COMMENT ON COLUMN public.notification_templates.required_placeholders IS 'Variables that must be provided';
COMMENT ON COLUMN public.notification_templates.example_payload IS 'Example data for testing';
COMMENT ON COLUMN public.notification_templates.language_code IS 'Language of this template';
COMMENT ON COLUMN public.notification_templates.is_default_language IS 'Whether this is the default language';
COMMENT ON COLUMN public.notification_templates.experiment_id IS 'A/B experiment reference';
COMMENT ON COLUMN public.notification_templates.traffic_allocation IS 'Percentage of traffic for this variant';
COMMENT ON COLUMN public.notification_templates.sent_count IS 'Total sends using this template';
COMMENT ON COLUMN public.notification_templates.open_rate IS 'Calculated open rate';
COMMENT ON COLUMN public.notification_templates.click_rate IS 'Calculated click rate';
COMMENT ON COLUMN public.notification_templates.approval_status IS 'Workflow status';
COMMENT ON COLUMN public.notification_templates.legal_reviewed IS 'Whether legally reviewed';

-- Indexes
CREATE INDEX idx_notification_templates_type ON public.notification_templates(notification_type, is_active);
CREATE INDEX idx_notification_templates_category ON public.notification_templates(category);
CREATE INDEX idx_notification_templates_language ON public.notification_templates(language_code);
CREATE INDEX idx_notification_templates_experiment ON public.notification_templates(experiment_id) WHERE experiment_id IS NOT NULL;
CREATE INDEX idx_notification_templates_owner ON public.notification_templates(owner_id);
CREATE INDEX idx_notification_templates_approval ON public.notification_templates(approval_status) WHERE approval_status = 'PENDING_REVIEW';

-- Partial index for active templates
CREATE INDEX idx_notification_templates_active ON public.notification_templates(template_name) WHERE is_active = true;

-- GIN index for tags
CREATE INDEX idx_notification_templates_tags ON public.notification_templates USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_notification_templates_timestamp
    BEFORE UPDATE ON public.notification_templates
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.notification_templates ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY notification_templates_admin_policy ON public.notification_templates
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'content_manager', 'marketing_manager')
    ));

CREATE POLICY notification_templates_read_policy ON public.notification_templates
    FOR SELECT USING (true);

-- =============================================================================
-- TABLE 98: notification_preferences
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 98
-- Table Name: notification_preferences
-- Description: Granular user preferences for notification delivery across
--              channels and categories, including quiet hours, frequency caps,
--              and opt-in/out settings.
--
-- Business Case (300 words):
-- Notification overload is a primary driver of user churn and app uninstalls.
-- Conversely, missing important notifications reduces engagement. This table
-- empowers users with control over their communication experience while providing
-- the business with a systematic way to respect user choices and comply with
-- regulations (CAN-SPAM, GDPR).
--
-- The business impact is significant: proper preference management reduces
-- unsubscribe rates by 40%, increases email engagement by 25%, and ensures
-- compliance with anti-spam laws. For enterprise customers, this table supports
-- team-level notification policies (e.g., all team members must receive security
-- alerts). The data also feeds into notification system optimization—analyzing
-- which notification types users disable helps product teams refine their
-- communication strategy.
--
-- The design implements a preference hierarchy: channel-level (email on/off),
-- category-level (job alerts vs. social notifications), and time-based controls
-- (quiet hours, frequency caps). This balances user autonomy with business
-- needs—marketing emails can be separate from transactional notifications, and
-- critical security alerts can override preferences.
--
-- For compliance, the table tracks consent timestamps and IP addresses,
-- providing evidence of opt-in where required. The audit trail of preference
-- changes supports dispute resolution and regulatory inquiries.
--
-- Key Performance Indicators (KPIs):
--   1. Opt-out Rate: By notification category (<20% for transactional)
--   2. Channel Preference Distribution: Email vs. push vs. in-app
--   3. Quiet Hour Usage: Percentage of users setting quiet hours (>30%)
--   4. Preference Change Frequency: Average changes per user per month
--   5. Notification Fatigue: Correlation between volume and opt-outs
--   6. Re-engagement Rate: Users who re-enable after disabling
--   7. Compliance Rate: Users with valid consent records (100%)
--
-- Feature Reference: NOT-07 (User Preferences)
-- Requirements Traceability: R-NOTIFY-026 through R-NOTIFY-045
--
-- Normalization: 3NF - Preferences per user per category
--
-- High-Write Considerations:
--   - Read-heavy (every notification checks preferences)
--   - Write-light (users change preferences infrequently)
--   - Caching critical (Redis recommended)
--   - Partial indexes for users with non-default preferences
-------------------------------------------------------------------------------
CREATE TABLE public.notification_preferences (
    -- Primary key
    preference_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Targeting
    category public.notification_category NOT NULL,
    channel public.notification_channel NOT NULL,

    -- Core preference
    preference_level public.subscription_preference NOT NULL DEFAULT 'ALL',
    is_enabled BOOLEAN GENERATED ALWAYS AS (
        preference_level NOT IN ('NONE')
    ) STORED,

    -- Delivery controls
    priority_override public.notification_priority, -- Override default priority
    frequency_cap INTEGER,                           -- Max per day/week
    frequency_period VARCHAR(10) CHECK (frequency_period IN ('day', 'week', 'month')),

    -- Quiet hours (suppress during specified times)
    quiet_hours_enabled BOOLEAN DEFAULT false,
    quiet_hours_start TIME WITH TIME ZONE,
    quiet_hours_end TIME WITH TIME ZONE,
    quiet_hours_timezone VARCHAR(50) DEFAULT 'UTC',

    -- Digest settings
    digest_frequency VARCHAR(20) CHECK (digest_frequency IN ('none', 'daily', 'weekly', 'monthly')),
    last_digest_sent_at TIMESTAMP WITH TIME ZONE,

    -- Channel-specific settings
    email_format VARCHAR(10) CHECK (email_format IN ('html', 'text', 'both')),
    push_sound VARCHAR(100),
    push_badge_count BOOLEAN DEFAULT true,
    sms_opt_out BOOLEAN DEFAULT false,

    -- Advanced rules (JSON for complex scenarios)
    delivery_rules JSONB, -- e.g., only weekdays, after threshold

    -- Consent tracking (GDPR)
    consent_granted_at TIMESTAMP WITH TIME ZONE,
    consent_ip_address INET,
    consent_user_agent TEXT,
    consent_version VARCHAR(20),

    -- Override flags
    is_critical BOOLEAN DEFAULT false,               -- Cannot be disabled (security)
    is_deprecated BOOLEAN DEFAULT false,             -- Category no longer used

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Metadata
    source VARCHAR(50) CHECK (source IN ('user_action', 'default', 'imported')),
    notes TEXT,

    -- Constraints
    CONSTRAINT unique_user_category_channel UNIQUE (user_id, category, channel),
    CONSTRAINT valid_quiet_hours CHECK (
        (quiet_hours_enabled = false) OR
        (quiet_hours_start IS NOT NULL AND quiet_hours_end IS NOT NULL)
    ),
    CONSTRAINT valid_frequency CHECK (
        (frequency_cap IS NULL) OR
        (frequency_period IS NOT NULL AND frequency_cap > 0)
    )
);

COMMENT ON TABLE public.notification_preferences IS 'Granular user preferences for notification delivery';
COMMENT ON COLUMN public.notification_preferences.preference_id IS 'Primary key';
COMMENT ON COLUMN public.notification_preferences.user_id IS 'User reference';
COMMENT ON COLUMN public.notification_preferences.category IS 'Notification category';
COMMENT ON COLUMN public.notification_preferences.channel IS 'Delivery channel';
COMMENT ON COLUMN public.notification_preferences.preference_level IS 'Subscription preference level';
COMMENT ON COLUMN public.notification_preferences.is_enabled IS 'Generated flag for easy filtering';
COMMENT ON COLUMN public.notification_preferences.priority_override IS 'Override default priority';
COMMENT ON COLUMN public.notification_preferences.frequency_cap IS 'Maximum notifications per period';
COMMENT ON COLUMN public.notification_preferences.quiet_hours_enabled IS 'Whether to suppress during quiet hours';
COMMENT ON COLUMN public.notification_preferences.quiet_hours_start IS 'Start of quiet period';
COMMENT ON COLUMN public.notification_preferences.quiet_hours_end IS 'End of quiet period';
COMMENT ON COLUMN public.notification_preferences.digest_frequency IS 'How often to batch notifications';
COMMENT ON COLUMN public.notification_preferences.consent_granted_at IS 'When consent was given (GDPR)';
COMMENT ON COLUMN public.notification_preferences.is_critical IS 'Cannot be disabled (security)';

-- Indexes
CREATE INDEX idx_notification_preferences_user ON public.notification_preferences(user_id, is_enabled);
CREATE INDEX idx_notification_preferences_category ON public.notification_preferences(category);
CREATE INDEX idx_notification_preferences_channel ON public.notification_preferences(channel);
CREATE INDEX idx_notification_preferences_digest ON public.notification_preferences(digest_frequency)
    WHERE digest_frequency != 'none';

-- Partial index for active preferences (most queries)
CREATE INDEX idx_notification_preferences_active ON public.notification_preferences(user_id, category)
    WHERE is_enabled = true;

-- GIN index for delivery_rules
CREATE INDEX idx_notification_preferences_rules ON public.notification_preferences USING gin(delivery_rules);

-- Trigger for updated_at
CREATE TRIGGER update_notification_preferences_timestamp
    BEFORE UPDATE ON public.notification_preferences
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY notification_preferences_user_policy ON public.notification_preferences
    FOR ALL USING (user_id = current_user_id());

CREATE POLICY notification_preferences_admin_policy ON public.notification_preferences
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name = 'admin'
    ));

-- =============================================================================
-- TABLE 99: user_notifications
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 99
-- Table Name: user_notifications
-- Description: Individual notifications sent to users with delivery tracking,
--              read status, and action links. Supports both in-app and external
--              notifications with full audit trail.
--
-- Business Case (300 words):
-- The user notification inbox is a critical touchpoint for user engagement.
-- This table stores every notification sent to users, whether delivered in-app,
-- via email, or through other channels. It powers the notification center
-- where users can view their history, take actions, and manage their attention.
--
-- Without a centralized notification store, users would miss important updates,
-- have no way to review past notifications, and lose context for actions they
-- need to take. The platform would lack visibility into notification effectiveness
-- and user engagement patterns. This table provides the foundation for all
-- user communication.
--
-- The business impact is direct: notifications drive user re-engagement, with
-- well-timed notifications increasing return rates by 30%. The action links
-- enable users to take immediate action (apply to job, accept connection),
-- reducing friction and increasing conversion. Read/unread tracking helps
-- users manage their attention and provides analytics on notification effectiveness.
--
-- The design supports rich notifications with titles, bodies, images, and
-- action buttons. Each notification can be linked to a specific entity (job,
-- connection request, message) for deep linking. Expiration dates ensure that
-- outdated notifications are automatically cleaned up. Read receipts provide
-- feedback on user engagement.
--
-- Key Performance Indicators (KPIs):
--   1. Notification Volume: Average per user per day (monitor for fatigue)
--   2. Read Rate: Percentage of notifications opened (>40%)
--   3. Action Rate: Percentage with action taken (>15%)
--   4. Time to Read: Average delay between send and open
--   5. Click-through Rate: By notification type
--   6. Opt-out Impact: Correlation between notifications and unsubscribes
--   7. Re-engagement: Users returning after notification
--
-- Feature Reference: NOT-08 (Notification Inbox)
-- Requirements Traceability: R-NOTIFY-046 through R-NOTIFY-065
--
-- Normalization: 3NF - Notifications per user with template reference
--
-- High-Write Considerations:
--   - Very high write volume (every notification sent)
--   - Partitioned by created_at for write scalability
--   - Partial indexes for unread notifications only
--   - Automatic cleanup of old notifications (>90 days)
-------------------------------------------------------------------------------
CREATE TABLE public.user_notifications (
    -- Primary key (composite for partitioning)
    notification_id UUID DEFAULT gen_random_uuid() NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Notification content (denormalized from template)
    title VARCHAR(255),
    body TEXT NOT NULL,
    image_url TEXT,
    icon VARCHAR(255),
    category public.notification_category NOT NULL,
    priority public.notification_priority NOT NULL DEFAULT 'MEDIUM',

    -- Template reference
    template_id UUID REFERENCES public.notification_templates(template_id) ON DELETE SET NULL,
    template_version INTEGER,

    -- Deep linking
    target_url TEXT,                                   -- Where to go when clicked
    target_entity_type VARCHAR(50),                     -- e.g., 'job', 'message', 'connection'
    target_entity_id UUID,                              -- ID of target entity
    action_buttons JSONB,                               -- Array of {label, url, action_type}

    -- Tracking
    is_read BOOLEAN DEFAULT false,
    read_at TIMESTAMP WITH TIME ZONE,
    is_clicked BOOLEAN DEFAULT false,
    clicked_at TIMESTAMP WITH TIME ZONE,
    is_dismissed BOOLEAN DEFAULT false,
    dismissed_at TIMESTAMP WITH TIME ZONE,

    -- Delivery status (aggregated from delivery logs)
    delivery_status public.notification_delivery_status DEFAULT 'PENDING',
    sent_via_channels public.notification_channel[],    -- Which channels attempted
    successful_channels public.notification_channel[],  -- Which channels succeeded

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    is_expired BOOLEAN GENERATED ALWAYS AS (expires_at < CURRENT_TIMESTAMP) STORED,

    -- Grouping (for notification stacking)
    group_key VARCHAR(255),                             -- Key for grouping similar notifications
    group_count INTEGER DEFAULT 1,                      -- Count when grouped

    -- Metadata
    metadata JSONB,                                      -- Additional data
    tags TEXT[],

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_dates CHECK (expires_at IS NULL OR expires_at > created_at),

    PRIMARY KEY (notification_id, created_at)
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.user_notifications IS 'Individual notifications sent to users with delivery tracking';
COMMENT ON COLUMN public.user_notifications.notification_id IS 'Primary key';
COMMENT ON COLUMN public.user_notifications.created_at IS 'When notification was created (partition key)';
COMMENT ON COLUMN public.user_notifications.user_id IS 'Recipient user';
COMMENT ON COLUMN public.user_notifications.title IS 'Notification title';
COMMENT ON COLUMN public.user_notifications.body IS 'Notification body';
COMMENT ON COLUMN public.user_notifications.category IS 'Notification category';
COMMENT ON COLUMN public.user_notifications.priority IS 'Delivery priority';
COMMENT ON COLUMN public.user_notifications.template_id IS 'Template used (if any)';
COMMENT ON COLUMN public.user_notifications.target_url IS 'Deep link URL';
COMMENT ON COLUMN public.user_notifications.target_entity_type IS 'Type of target entity';
COMMENT ON COLUMN public.user_notifications.target_entity_id IS 'ID of target entity';
COMMENT ON COLUMN public.user_notifications.action_buttons IS 'Interactive buttons';
COMMENT ON COLUMN public.user_notifications.is_read IS 'Whether user opened';
COMMENT ON COLUMN public.user_notifications.is_clicked IS 'Whether user clicked';
COMMENT ON COLUMN public.user_notifications.is_dismissed IS 'Whether user dismissed';
COMMENT ON COLUMN public.user_notifications.expires_at IS 'When notification expires';
COMMENT ON COLUMN public.user_notifications.is_expired IS 'Whether notification is expired';
COMMENT ON COLUMN public.user_notifications.group_key IS 'Key for grouping similar notifications';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_user_notifications_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'user_notifications_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.user_notifications
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, created_at DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(is_read) WHERE is_read = false;
            CREATE INDEX IF NOT EXISTS %I ON public.%I(target_entity_type, target_entity_id);
        ',
        'idx_' || partition_name || '_user', partition_name,
        'idx_' || partition_name || '_unread', partition_name,
        'idx_' || partition_name || '_target', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create monthly partitions for current and next 2 months
SELECT public.create_user_notifications_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_user_notifications_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_user_notifications_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes
CREATE INDEX idx_user_notifications_user_time ON public.user_notifications(user_id, created_at DESC);
CREATE INDEX idx_user_notifications_unread ON public.user_notifications(user_id) WHERE is_read = false;
CREATE INDEX idx_user_notifications_category ON public.user_notifications(category, created_at DESC);
CREATE INDEX idx_user_notifications_target ON public.user_notifications(target_entity_type, target_entity_id)
    WHERE target_entity_id IS NOT NULL;
CREATE INDEX idx_user_notifications_expires ON public.user_notifications(expires_at) WHERE is_expired = false;

-- GIN index for tags
CREATE INDEX idx_user_notifications_tags ON public.user_notifications USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_user_notifications_timestamp
    BEFORE UPDATE ON public.user_notifications
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY user_notifications_self_policy ON public.user_notifications
    FOR ALL USING (user_id = current_user_id());

CREATE POLICY user_notifications_admin_policy ON public.user_notifications
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'support_agent')
    ));

-- =============================================================================
-- TABLE 100: notification_delivery_logs
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 100
-- Table Name: notification_delivery_logs
-- Description: Comprehensive audit trail of all notification delivery attempts,
--              including status, timing, errors, and engagement metrics (opens/clicks)
--              for each channel.
--
-- Business Case (300 words):
-- In a platform sending millions of notifications daily, visibility into delivery
-- success, timing, and user engagement is critical. This table provides the
-- operational and analytical backbone for the notification system, enabling
-- real-time monitoring, debugging, and optimization of all outbound communications.
--
-- From an operational perspective, the logs enable immediate detection of delivery
-- failures (e.g., email provider down, push certificate expired) and automated
-- retry logic. Support teams can investigate user-reported "I didn't receive the
-- email" issues by checking exact delivery status and error messages. The table
-- also supports SLA monitoring for critical notifications (e.g., password reset
-- emails must deliver within 5 minutes).
--
-- For analytics, the data feeds into engagement reporting—open rates by notification
-- type, click-through rates by template, and optimal send times by user timezone.
-- Product managers use this data to refine notification strategies, reducing
-- fatigue while maximizing impact. Marketing teams measure campaign performance
-- with precise delivery and conversion tracking.
--
-- The design captures every attempt per channel, enabling detailed analysis of
-- channel effectiveness. Provider responses are stored for debugging, and
-- engagement events (opens, clicks) are linked back to the original attempt.
-- The table is partitioned by date to manage the massive data volume while
-- maintaining query performance.
--
-- Key Performance Indicators (KPIs):
--   1. Delivery Success Rate: By channel (>99% for transactional)
--   2. Average Delivery Latency: Time from creation to sent (<30 seconds)
--   3. Open Rate: By notification type and template
--   4. Click-through Rate: By notification type
--   5. Bounce Rate: Permanent failures by provider (<1%)
--   6. Retry Success Rate: Recoveries after initial failure (>70%)
--   7. Provider Performance: Comparative metrics across providers
--
-- Feature Reference: NOT-09 (Delivery Analytics)
-- Requirements Traceability: R-NOTIFY-066 through R-NOTIFY-085
--
-- Normalization: 3NF - Logs independent with notification reference
--
-- High-Write Considerations:
--   - Extremely high write volume (every delivery attempt)
--   - Partitioned by attempt_time for write scalability
--   - BRIN indexes for time-series queries
--   - Automatic archival to cold storage after 90 days
-------------------------------------------------------------------------------
CREATE TABLE public.notification_delivery_logs (
    -- Primary key (composite for partitioning)
    log_id BIGSERIAL NOT NULL,
    attempt_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Notification reference
    notification_id UUID NOT NULL REFERENCES public.user_notifications(notification_id) ON DELETE CASCADE,
    user_id UUID NOT NULL, -- Denormalized for performance

    -- Delivery context
    channel public.notification_channel NOT NULL,
    template_id UUID REFERENCES public.notification_templates(template_id) ON DELETE SET NULL,
    template_version INTEGER,

    -- Recipient
    recipient_address VARCHAR(500),                     -- email, phone, device token
    recipient_device_id VARCHAR(255),                    -- For push notifications

    -- Attempt tracking
    attempt_number INTEGER NOT NULL DEFAULT 1,
    status public.notification_delivery_status NOT NULL DEFAULT 'PENDING',
    status_reason TEXT,

    -- Timing
    queued_at TIMESTAMP WITH TIME ZONE,
    sent_at TIMESTAMP WITH TIME ZONE,
    delivered_at TIMESTAMP WITH TIME ZONE,
    opened_at TIMESTAMP WITH TIME ZONE,
    clicked_at TIMESTAMP WITH TIME ZONE,
    failed_at TIMESTAMP WITH TIME ZONE,
    duration_ms INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (COALESCE(delivered_at, failed_at, sent_at) - queued_at)) * 1000
    ) STORED,

    -- Provider details
    provider VARCHAR(100),                              -- e.g., 'aws_ses', 'twilio', 'firebase'
    provider_message_id VARCHAR(255),                    -- External ID for tracking
    provider_response JSONB,                             -- Raw provider response
    provider_error_code VARCHAR(100),
    provider_error_message TEXT,

    -- Request details
    request_payload TEXT,                                -- What was sent (truncated)
    request_size_bytes INTEGER,

    -- Response details
    response_status_code INTEGER,
    response_headers JSONB,
    response_body TEXT,                                  -- Truncated

    -- Engagement (for this channel)
    open_count INTEGER DEFAULT 0,
    click_count INTEGER DEFAULT 0,
    last_open_at TIMESTAMP WITH TIME ZONE,
    last_click_at TIMESTAMP WITH TIME ZONE,
    clicked_links TEXT[],                                -- URLs that were clicked

    -- Device/client info (for opens/clicks)
    user_agent TEXT,
    ip_address INET,
    device_type VARCHAR(50),
    platform VARCHAR(50),

    -- Retry information
    retry_count INTEGER DEFAULT 0,
    max_retries INTEGER DEFAULT 3,
    next_retry_at TIMESTAMP WITH TIME ZONE,
    retry_decision_reason TEXT,

    -- Cost tracking
    cost_amount NUMERIC(10,6),                           -- Cost per delivery
    cost_currency CHAR(3) DEFAULT 'USD',

    -- Metadata
    batch_id UUID,                                       -- For grouped sends
    tags TEXT[],

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_timing CHECK (
        (queued_at IS NOT NULL) AND
        (sent_at IS NULL OR sent_at >= queued_at) AND
        (delivered_at IS NULL OR delivered_at >= sent_at) AND
        (opened_at IS NULL OR opened_at >= delivered_at) AND
        (clicked_at IS NULL OR clicked_at >= opened_at)
    ),

    PRIMARY KEY (log_id, attempt_time)
) PARTITION BY RANGE (attempt_time);

COMMENT ON TABLE public.notification_delivery_logs IS 'Comprehensive audit trail of notification delivery attempts';
COMMENT ON COLUMN public.notification_delivery_logs.log_id IS 'Primary key (bigserial for high volume)';
COMMENT ON COLUMN public.notification_delivery_logs.attempt_time IS 'When attempt was made (partition key)';
COMMENT ON COLUMN public.notification_delivery_logs.notification_id IS 'Reference to user notification';
COMMENT ON COLUMN public.notification_delivery_logs.user_id IS 'User (denormalized)';
COMMENT ON COLUMN public.notification_delivery_logs.channel IS 'Delivery channel';
COMMENT ON COLUMN public.notification_delivery_logs.template_id IS 'Template used';
COMMENT ON COLUMN public.notification_delivery_logs.recipient_address IS 'Actual delivery address';
COMMENT ON COLUMN public.notification_delivery_logs.attempt_number IS 'Attempt number';
COMMENT ON COLUMN public.notification_delivery_logs.status IS 'Current delivery status';
COMMENT ON COLUMN public.notification_delivery_logs.queued_at IS 'When queued for delivery';
COMMENT ON COLUMN public.notification_delivery_logs.sent_at IS 'When handed to provider';
COMMENT ON COLUMN public.notification_delivery_logs.delivered_at IS 'When confirmed delivered';
COMMENT ON COLUMN public.notification_delivery_logs.opened_at IS 'When user opened';
COMMENT ON COLUMN public.notification_delivery_logs.clicked_at IS 'When user clicked';
COMMENT ON COLUMN public.notification_delivery_logs.provider IS 'Delivery service provider';
COMMENT ON COLUMN public.notification_delivery_logs.provider_message_id IS 'Provider’s message ID';
COMMENT ON COLUMN public.notification_delivery_logs.open_count IS 'Number of opens';
COMMENT ON COLUMN public.notification_delivery_logs.click_count IS 'Number of clicks';
COMMENT ON COLUMN public.notification_delivery_logs.retry_count IS 'Number of retries so far';
COMMENT ON COLUMN public.notification_delivery_logs.cost_amount IS 'Cost of this delivery';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_delivery_logs_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'notification_delivery_logs_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.notification_delivery_logs
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(notification_id);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(status, next_retry_at);
        ',
        'idx_' || partition_name || '_notif', partition_name,
        'idx_' || partition_name || '_user', partition_name,
        'idx_' || partition_name || '_status', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for next 7 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..7 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_delivery_logs_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_delivery_logs_notification ON public.notification_delivery_logs(notification_id);
CREATE INDEX idx_delivery_logs_user ON public.notification_delivery_logs(user_id, attempt_time DESC);
CREATE INDEX idx_delivery_logs_status ON public.notification_delivery_logs(status, next_retry_at)
    WHERE status IN ('PENDING', 'RETRYING');
CREATE INDEX idx_delivery_logs_provider ON public.notification_delivery_logs(provider, provider_message_id)
    WHERE provider_message_id IS NOT NULL;
CREATE INDEX idx_delivery_logs_opened ON public.notification_delivery_logs(opened_at) WHERE opened_at IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_delivery_logs_timestamp
    BEFORE UPDATE ON public.notification_delivery_logs
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.notification_delivery_logs ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY delivery_logs_user_policy ON public.notification_delivery_logs
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY delivery_logs_admin_policy ON public.notification_delivery_logs
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'support_agent', 'analyst')
    ));

-- =============================================================================
-- TABLE 101: conversations
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 101
-- Table Name: conversations
-- Description: Messaging conversations between users, supporting one-to-one,
--              group chats, and broadcast channels with full metadata.
--
-- Business Case (300 words):
-- Messaging is the core of professional networking—it's how users build
-- relationships, discuss opportunities, and collaborate. This table manages
-- the conversation containers that hold all messages, participants, and metadata.
-- It supports multiple conversation types to serve different use cases.
--
-- Without a proper conversation model, messaging becomes chaotic—messages get
-- lost, context disappears, and users cannot manage their communications
-- effectively. This table provides the organizational structure that makes
-- messaging scalable and user-friendly.
--
-- The business impact is direct: messaging drives engagement, with users who
-- message being 3x more likely to retain. Group conversations enable team
-- collaboration and community building. Broadcast channels allow companies
-- and influencers to communicate with followers at scale. Support conversations
-- provide customer service channels within the platform.
--
-- The design supports rich conversation features: titles for group chats,
-- avatars for visual identification, pinned messages for important content,
-- and encryption flags for security-sensitive conversations. Last message
-- denormalization enables efficient inbox loading without joining to messages.
-- Participant counts help with UI rendering and permissions.
--
-- Key Performance Indicators (KPIs):
--   1. Conversation Volume: New conversations per day
--   2. Active Conversations: With messages in last 30 days
--   3. Conversation Size: Average participants per conversation
--   4. Conversation Longevity: Average duration of active conversations
--   5. Group vs. One-to-One Ratio: Distribution of conversation types
--   6. Message Density: Messages per conversation
--   7. Response Time: Time between messages in conversation
--
-- Feature Reference: MSG-05 (Conversation Management)
-- Requirements Traceability: R-MSG-001 through R-MSG-020
--
-- Normalization: 3NF - Conversations independent with participant references
--
-- High-Write Considerations:
--   - Moderate write volume (new conversations created daily)
--   - Read-heavy for inbox loading
--   - Partitioning optional (conversations are long-lived)
--   - Partial indexes for active conversations only
-------------------------------------------------------------------------------
CREATE TABLE public.conversations (
    -- Primary key
    conversation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Conversation metadata
    title VARCHAR(255),                                  -- For group conversations
    avatar_url TEXT,                                     -- Group avatar
    description TEXT,                                    -- Conversation purpose
    conversation_type public.conversation_type NOT NULL DEFAULT 'ONE_TO_ONE',

    -- Settings
    is_encrypted BOOLEAN DEFAULT false,                  -- End-to-end encrypted
    is_read_only BOOLEAN DEFAULT false,                   -- Only admins can message
    is_archived BOOLEAN DEFAULT false,                    -- Soft delete
    expires_at TIMESTAMP WITH TIME ZONE,                   -- Auto-expire after date
    max_participants INTEGER,                             -- Limit for groups

    -- Pinned items
    pinned_message_id UUID,                               -- Important message
    pinned_at TIMESTAMP WITH TIME ZONE,

    -- Last message (denormalized for performance)
    last_message_id UUID,
    last_message_text TEXT,
    last_message_sender_id UUID,
    last_message_at TIMESTAMP WITH TIME ZONE,

    -- Statistics
    participant_count INTEGER DEFAULT 0,
    message_count INTEGER DEFAULT 0,
    attachment_count INTEGER DEFAULT 0,

    -- Ownership (for channels)
    owner_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    owner_company_id UUID REFERENCES public.companies(company_id) ON DELETE SET NULL,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Metadata
    tags TEXT[],
    metadata JSONB
);

COMMENT ON TABLE public.conversations IS 'Messaging conversations between users';
COMMENT ON COLUMN public.conversations.conversation_id IS 'Primary key';
COMMENT ON COLUMN public.conversations.title IS 'Conversation title (for groups)';
COMMENT ON COLUMN public.conversations.conversation_type IS 'Type of conversation';
COMMENT ON COLUMN public.conversations.is_encrypted IS 'Whether end-to-end encrypted';
COMMENT ON COLUMN public.conversations.is_read_only IS 'Whether read-only';
COMMENT ON COLUMN public.conversations.is_archived IS 'Soft delete flag';
COMMENT ON COLUMN public.conversations.expires_at IS 'When conversation auto-expires';
COMMENT ON COLUMN public.conversations.max_participants IS 'Maximum participants allowed';
COMMENT ON COLUMN public.conversations.pinned_message_id IS 'Pinned message reference';
COMMENT ON COLUMN public.conversations.last_message_at IS 'Time of most recent message';
COMMENT ON COLUMN public.conversations.participant_count IS 'Number of participants';
COMMENT ON COLUMN public.conversations.message_count IS 'Total messages count';
COMMENT ON COLUMN public.conversations.owner_id IS 'Owner user (for channels)';
COMMENT ON COLUMN public.conversations.owner_company_id IS 'Owner company (for channels)';

-- Indexes
CREATE INDEX idx_conversations_type ON public.conversations(conversation_type);
CREATE INDEX idx_conversations_last_message ON public.conversations(last_message_at DESC);
CREATE INDEX idx_conversations_owner ON public.conversations(owner_id) WHERE owner_id IS NOT NULL;
CREATE INDEX idx_conversations_owner_company ON public.conversations(owner_company_id) WHERE owner_company_id IS NOT NULL;
CREATE INDEX idx_conversations_expires ON public.conversations(expires_at) WHERE expires_at IS NOT NULL;

-- Partial index for active conversations
CREATE INDEX idx_conversations_active ON public.conversations(conversation_id)
    WHERE is_archived = false AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP);

-- GIN index for tags
CREATE INDEX idx_conversations_tags ON public.conversations USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_conversations_timestamp
    BEFORE UPDATE ON public.conversations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;

-- RLS Policies (enforced through conversation_participants)
CREATE POLICY conversations_participant_policy ON public.conversations
    USING (EXISTS (
        SELECT 1 FROM public.conversation_participants cp
        WHERE cp.conversation_id = conversations.conversation_id
        AND cp.user_id = current_user_id()
    ));

CREATE POLICY conversations_owner_policy ON public.conversations
    USING (owner_id = current_user_id() OR
           EXISTS (SELECT 1 FROM public.company_admins ca
                   WHERE ca.company_id = conversations.owner_company_id
                   AND ca.user_id = current_user_id()));

-- =============================================================================
-- TABLE 102: conversation_participants
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 102
-- Table Name: conversation_participants
-- Description: Maps users to conversations with role, membership status, and
--              per-user settings like mute, archive, and last read timestamp.
--
-- Business Case (300 words):
-- In any messaging system, managing who has access to which conversations is
-- fundamental. This junction table connects users to conversations, storing
-- role-based permissions, membership status, and per-user preferences. It
-- enables features like leaving conversations, muting notifications, and
-- tracking unread counts.
--
-- Without proper participant management, conversations would lack access
-- control—anyone could join or see messages not intended for them. Users
-- couldn't manage their notification preferences per conversation, leading
-- to notification fatigue. Read receipts and unread counts would be impossible.
--
-- The business impact is user experience—granular controls over conversation
-- participation give users confidence that their messages are private and that
-- they can manage their notification load. For group conversations, role-based
-- permissions enable admins to moderate and manage the group effectively.
--
-- The design supports the full lifecycle of participation: joining, leaving,
-- being removed, muting, archiving, and marking as read. Last read timestamps
-- enable unread counts and read receipts. Notification overrides allow users
-- to customize alert settings per conversation. Mute until dates support
-- temporary muting (e.g., vacation mode).
--
-- Key Performance Indicators (KPIs):
--   1. Participation Rate: Average conversations per user
--   2. Group Size Distribution: Participants per conversation
--   3. Mute Rate: Percentage of conversations muted (>20%)
--   4. Archive Rate: Percentage of conversations archived
--   5. Read Receipt Coverage: Messages with read tracking
--   6. Churn Impact: Conversations after user leaves
--   7. Admin Ratio: Percentage of participants with admin roles
--
-- Feature Reference: MSG-06 (Participant Management)
-- Requirements Traceability: R-MSG-021 through R-MSG-035
--
-- Normalization: 3NF - Junction table with participant attributes
--
-- High-Write Considerations:
--   - Moderate write volume (participants join/leave)
--   - Read-heavy for every message access check
--   - Indexed by user_id for inbox loading
--   - Partial indexes for active participants only
-------------------------------------------------------------------------------
CREATE TABLE public.conversation_participants (
    -- Primary key
    participant_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- References
    conversation_id UUID NOT NULL REFERENCES public.conversations(conversation_id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Role and permissions
    role public.participant_role NOT NULL DEFAULT 'MEMBER',
    permissions JSONB,                                    -- Additional granular permissions

    -- Membership status
    joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    left_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN GENERATED ALWAYS AS (left_at IS NULL) STORED,
    removed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    removal_reason TEXT,

    -- Read tracking
    last_read_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_read_message_id UUID,
    unread_count INTEGER DEFAULT 0,

    -- Notification preferences (per conversation)
    muted BOOLEAN DEFAULT false,
    muted_until TIMESTAMP WITH TIME ZONE,
    archived BOOLEAN DEFAULT false,
    archived_at TIMESTAMP WITH TIME ZONE,

    -- Favorites
    is_favorite BOOLEAN DEFAULT false,

    -- Custom nickname (for this conversation)
    nickname VARCHAR(255),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Constraints
    CONSTRAINT unique_conversation_user UNIQUE (conversation_id, user_id),
    CONSTRAINT valid_mute CHECK (
        (muted = false) OR
        (muted_until IS NULL OR muted_until > CURRENT_TIMESTAMP)
    )
);

COMMENT ON TABLE public.conversation_participants IS 'Maps users to conversations with role and settings';
COMMENT ON COLUMN public.conversation_participants.participant_id IS 'Primary key';
COMMENT ON COLUMN public.conversation_participants.conversation_id IS 'Conversation reference';
COMMENT ON COLUMN public.conversation_participants.user_id IS 'User reference';
COMMENT ON COLUMN public.conversation_participants.role IS 'Role in conversation';
COMMENT ON COLUMN public.conversation_participants.joined_at IS 'When user joined';
COMMENT ON COLUMN public.conversation_participants.left_at IS 'When user left (if applicable)';
COMMENT ON COLUMN public.conversation_participants.is_active IS 'Whether currently active';
COMMENT ON COLUMN public.conversation_participants.removed_by IS 'Who removed user';
COMMENT ON COLUMN public.conversation_participants.last_read_at IS 'Last time user read messages';
COMMENT ON COLUMN public.conversation_participants.last_read_message_id IS 'Last message read';
COMMENT ON COLUMN public.conversation_participants.unread_count IS 'Number of unread messages';
COMMENT ON COLUMN public.conversation_participants.muted IS 'Whether notifications muted';
COMMENT ON COLUMN public.conversation_participants.muted_until IS 'When mute expires';
COMMENT ON COLUMN public.conversation_participants.archived IS 'Whether conversation archived';
COMMENT ON COLUMN public.conversation_participants.is_favorite IS 'Whether favorite';
COMMENT ON COLUMN public.conversation_participants.nickname IS 'Custom nickname for this conversation';

-- Indexes
CREATE INDEX idx_conv_participants_user ON public.conversation_participants(user_id, is_active, archived)
    WHERE is_active = true;
CREATE INDEX idx_conv_participants_conversation ON public.conversation_participants(conversation_id, role);
CREATE INDEX idx_conv_participants_unread ON public.conversation_participants(user_id, unread_count)
    WHERE unread_count > 0;
CREATE INDEX idx_conv_participants_muted ON public.conversation_participants(user_id, muted_until)
    WHERE muted = true;

-- Trigger for updated_at
CREATE TRIGGER update_conv_participants_timestamp
    BEFORE UPDATE ON public.conversation_participants
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to update participant count on conversation
CREATE OR REPLACE FUNCTION public.update_conversation_participant_count()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.conversations
        SET participant_count = participant_count + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE conversation_id = NEW.conversation_id;
    ELSIF TG_OP = 'UPDATE' AND NEW.left_at IS NOT NULL AND OLD.left_at IS NULL THEN
        UPDATE public.conversations
        SET participant_count = participant_count - 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE conversation_id = NEW.conversation_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE public.conversations
        SET participant_count = participant_count - 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE conversation_id = OLD.conversation_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_conversation_participant_count
    AFTER INSERT OR UPDATE OR DELETE ON public.conversation_participants
    FOR EACH ROW EXECUTE FUNCTION public.update_conversation_participant_count();

-- Enable RLS
ALTER TABLE public.conversation_participants ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY conv_participants_self_policy ON public.conversation_participants
    FOR ALL USING (user_id = current_user_id());

CREATE POLICY conv_participants_admin_policy ON public.conversation_participants
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name = 'admin'
    ));

-- =============================================================================
-- TABLE 103: messages
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 103
-- Table Name: messages
-- Description: Individual messages within conversations with content, metadata,
--              attachments, and reply/forward tracking.
--
-- Business Case (300 words):
-- Messages are the atomic unit of communication in the platform. This table
-- stores every message sent, with rich content support including text, rich
-- formatting, media attachments, and reply/forward relationships. It powers
-- the real-time messaging experience and provides the historical record of
-- all communications.
--
-- Without proper message storage, conversations would be ephemeral—users
-- couldn't scroll back to see past messages, couldn't reference previous
-- discussions, and the platform would lose valuable data about user interactions.
-- This table provides the durable storage that makes messaging a reliable
-- communication tool.
--
-- The business impact is engagement—users who exchange messages are building
-- relationships that keep them on the platform. The message content provides
-- rich signals for understanding user interests and connection strength. For
-- compliance, message retention may be required for legal or regulatory reasons.
--
-- The design supports modern messaging features: rich text with formatting,
-- mentions of other users, emoji reactions, replies that create threaded
-- discussions, and message editing with edit history. Soft deletes allow
-- messages to be removed from view while preserving audit trail. Attachments
-- enable file sharing within conversations.
--
-- Key Performance Indicators (KPIs):
--   1. Message Volume: Messages per day by conversation type
--   2. Response Time: Time between messages in conversation
--   3. Attachment Rate: Percentage of messages with attachments
--   4. Mention Rate: Frequency of @mentions
--   5. Reaction Rate: Messages with emoji reactions
--   6. Edit Rate: Percentage of messages edited
--   7. Delete Rate: Percentage of messages deleted
--
-- Feature Reference: MSG-07 (Message Management)
-- Requirements Traceability: R-MSG-036 through R-MSG-055
--
-- Normalization: 3NF - Messages dependent on conversations
--
-- High-Write Considerations:
--   - Extremely high write volume (all messages)
--   - Partitioned by created_at for write scalability
--   - BRIN indexes for time-series queries
--   - Automatic archival of old messages (>1 year)
-------------------------------------------------------------------------------
CREATE TABLE public.messages (
    -- Primary key (composite for partitioning)
    message_id UUID DEFAULT gen_random_uuid() NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Conversation
    conversation_id UUID NOT NULL REFERENCES public.conversations(conversation_id) ON DELETE CASCADE,

    -- Author
    sender_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    sender_name VARCHAR(255), -- Denormalized for display

    -- Message content
    message_type public.message_type NOT NULL DEFAULT 'DIRECT',
    body TEXT NOT NULL,
    formatted_body TEXT,                                  -- HTML/Markdown version
    language_code VARCHAR(10) REFERENCES public.languages(language_code) ON DELETE SET NULL,

    -- Rich features
    mentions UUID[],                                      -- Users mentioned (@mentions)
    emoji_reactions JSONB,                                -- { "👍": [user_ids], "❤️": [user_ids] }
    reply_to_message_id UUID,                             -- Parent message (for threads)
    forward_from_message_id UUID,                         -- Original message if forwarded
    forward_from_conversation_id UUID,                    -- Original conversation

    -- Attachments
    attachments JSONB,                                    -- Array of attachment metadata
    has_attachments BOOLEAN GENERATED ALWAYS AS (
        attachments IS NOT NULL AND jsonb_array_length(attachments) > 0
    ) STORED,

    -- Status
    status public.message_status NOT NULL DEFAULT 'SENT',
    is_edited BOOLEAN DEFAULT false,
    edit_history JSONB,                                   -- Previous versions
    is_deleted BOOLEAN DEFAULT false,
    deleted_at TIMESTAMP WITH TIME ZONE,
    deleted_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Delivery (aggregated)
    delivered_count INTEGER DEFAULT 0,
    read_count INTEGER DEFAULT 0,

    -- Client info
    client_ip INET,
    user_agent TEXT,
    client_message_id VARCHAR(255),                        -- For idempotency

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Metadata
    metadata JSONB,
    tags TEXT[],

    -- Constraints
    CONSTRAINT valid_reply CHECK (
        (reply_to_message_id IS NULL) OR
        (reply_to_message_id != message_id)
    ),

    PRIMARY KEY (message_id, created_at)
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.messages IS 'Individual messages within conversations';
COMMENT ON COLUMN public.messages.message_id IS 'Primary key';
COMMENT ON COLUMN public.messages.created_at IS 'When message was sent (partition key)';
COMMENT ON COLUMN public.messages.conversation_id IS 'Parent conversation';
COMMENT ON COLUMN public.messages.sender_id IS 'User who sent the message';
COMMENT ON COLUMN public.messages.message_type IS 'Type of message';
COMMENT ON COLUMN public.messages.body IS 'Message content';
COMMENT ON COLUMN public.messages.formatted_body IS 'Formatted version (HTML/Markdown)';
COMMENT ON COLUMN public.messages.mentions IS 'Users mentioned in message';
COMMENT ON COLUMN public.messages.emoji_reactions IS 'Emoji reactions with user lists';
COMMENT ON COLUMN public.messages.reply_to_message_id IS 'Parent message for replies';
COMMENT ON COLUMN public.messages.forward_from_message_id IS 'Original message if forwarded';
COMMENT ON COLUMN public.messages.attachments IS 'File attachments metadata';
COMMENT ON COLUMN public.messages.status IS 'Delivery status';
COMMENT ON COLUMN public.messages.is_edited IS 'Whether message was edited';
COMMENT ON COLUMN public.messages.edit_history IS 'Previous versions';
COMMENT ON COLUMN public.messages.is_deleted IS 'Soft delete flag';
COMMENT ON COLUMN public.messages.client_message_id IS 'Client-generated ID for idempotency';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_messages_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'messages_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.messages
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(conversation_id, created_at DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(sender_id, created_at DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I USING gin(mentions);
        ',
        'idx_' || partition_name || '_conv', partition_name,
        'idx_' || partition_name || '_sender', partition_name,
        'idx_' || partition_name || '_mentions', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create monthly partitions for current and next 2 months
SELECT public.create_messages_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_messages_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_messages_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes
CREATE INDEX idx_messages_conversation ON public.messages(conversation_id, created_at DESC);
CREATE INDEX idx_messages_sender ON public.messages(sender_id, created_at DESC);
CREATE INDEX idx_messages_reply_to ON public.messages(reply_to_message_id) WHERE reply_to_message_id IS NOT NULL;
CREATE INDEX idx_messages_forward_from ON public.messages(forward_from_message_id) WHERE forward_from_message_id IS NOT NULL;

-- GIN indexes
CREATE INDEX idx_messages_mentions ON public.messages USING gin(mentions);
CREATE INDEX idx_messages_attachments ON public.messages USING gin(attachments);
CREATE INDEX idx_messages_emoji ON public.messages USING gin(emoji_reactions);

-- Trigger for updated_at
CREATE TRIGGER update_messages_timestamp
    BEFORE UPDATE ON public.messages
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to update conversation last message
CREATE OR REPLACE FUNCTION public.update_conversation_last_message()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'SENT' THEN
        UPDATE public.conversations
        SET last_message_id = NEW.message_id,
            last_message_text = NEW.body,
            last_message_sender_id = NEW.sender_id,
            last_message_at = NEW.created_at,
            message_count = message_count + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE conversation_id = NEW.conversation_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_conversation_last_message
    AFTER INSERT ON public.messages
    FOR EACH ROW EXECUTE FUNCTION public.update_conversation_last_message();

-- Enable RLS
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY messages_participant_policy ON public.messages
    USING (EXISTS (
        SELECT 1 FROM public.conversation_participants cp
        WHERE cp.conversation_id = messages.conversation_id
        AND cp.user_id = current_user_id()
        AND cp.is_active = true
    ));

-- =============================================================================
-- TABLE 104: message_attachments
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 104
-- Table Name: message_attachments
-- Description: File attachments for messages with metadata, storage locations,
--              and virus scanning status.
--
-- Business Case (300 words):
-- File sharing is an essential feature of modern messaging—users need to share
-- documents, images, and other files within conversations. This table manages
-- the metadata for all attachments, linking them to messages and providing
-- storage locations, file types, sizes, and security scanning status.
--
-- Without proper attachment management, file sharing would be unreliable—files
-- could be lost, virus-infected files could spread, and storage would be
-- unmanaged. This table provides the infrastructure for secure, reliable file
-- sharing that users expect from professional communication platforms.
--
-- The business impact is productivity—users can share resumes, proposals,
-- contracts, and other professional documents directly within conversations,
-- eliminating the need for external file-sharing services. For compliance,
-- virus scanning and file type restrictions protect the platform and its users.
-- Storage tracking enables cost management and quota enforcement.
--
-- The design supports multiple storage providers (S3, Azure Blob, local) with
-- redundancy options. Virus scanning status ensures that infected files are
-- never delivered to users. Thumbnails for images improve the user experience.
-- Expiration dates enable temporary file sharing with automatic cleanup.
--
-- Key Performance Indicators (KPIs):
--   1. Attachment Volume: Files uploaded per day
--   2. Storage Growth: Total storage used over time
--   3. File Type Distribution: Most common file types
--   4. Average File Size: By file type
--   5. Virus Detection Rate: Infected files caught (>99.9%)
--   6. Thumbnail Generation: Success rate for images
--   7. Upload Failure Rate: Percentage of failed uploads (<1%)
--
-- Feature Reference: MSG-08 (Attachment Management)
-- Requirements Traceability: R-MSG-056 through R-MSG-070
--
-- Normalization: 3NF - Attachments dependent on messages
--
-- High-Write Considerations:
--   - Moderate write volume (attachments less frequent than messages)
--   - Read-heavy when loading messages with attachments
--   - Indexed by message_id for fast retrieval
--   - JSONB for flexible storage provider metadata
-------------------------------------------------------------------------------
CREATE TABLE public.message_attachments (
    -- Primary key
    attachment_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Message reference
    message_id UUID NOT NULL,
    conversation_id UUID NOT NULL, -- Denormalized for performance

    -- File metadata
    file_name VARCHAR(500) NOT NULL,
    file_size_bytes BIGINT NOT NULL CHECK (file_size_bytes > 0),
    mime_type VARCHAR(200) NOT NULL,
    file_hash VARCHAR(64), -- SHA-256 for integrity

    -- Storage
    storage_provider VARCHAR(50) NOT NULL CHECK (storage_provider IN ('aws_s3', 'azure_blob', 'gcp_storage', 'local', 'cdn')),
    storage_path TEXT NOT NULL,
    storage_region VARCHAR(100),
    storage_bucket VARCHAR(200),
    public_url TEXT, -- Generated URL with expiration
    public_url_expires_at TIMESTAMP WITH TIME ZONE,

    -- Content processing
    thumbnail_path TEXT, -- For images/videos
    thumbnail_url TEXT,
    thumbnail_generated_at TIMESTAMP WITH TIME ZONE,
    processing_status VARCHAR(50) DEFAULT 'PENDING' CHECK (processing_status IN (
        'PENDING', 'PROCESSING', 'COMPLETED', 'FAILED'
    )),

    -- Security
    virus_scan_status VARCHAR(50) DEFAULT 'PENDING' CHECK (virus_scan_status IN (
        'PENDING', 'SCANNING', 'CLEAN', 'INFECTED', 'ERROR'
    )),
    virus_scan_result TEXT,
    scanned_at TIMESTAMP WITH TIME ZONE,

    -- Image/Video metadata
    width INTEGER,
    height INTEGER,
    duration_seconds INTEGER, -- For videos/audio
    has_thumbnail BOOLEAN DEFAULT false,

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    is_expired BOOLEAN GENERATED ALWAYS AS (expires_at < CURRENT_TIMESTAMP) STORED,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Metadata
    metadata JSONB,
    tags TEXT[],

    -- Constraints
    CONSTRAINT valid_file_hash CHECK (file_hash ~ '^[a-f0-9]{64}$'),
    CONSTRAINT valid_dimensions CHECK (
        (width IS NULL AND height IS NULL) OR
        (width > 0 AND height > 0)
    )
);

COMMENT ON TABLE public.message_attachments IS 'File attachments for messages with metadata and security scanning';
COMMENT ON COLUMN public.message_attachments.attachment_id IS 'Primary key';
COMMENT ON COLUMN public.message_attachments.message_id IS 'Message this belongs to';
COMMENT ON COLUMN public.message_attachments.conversation_id IS 'Conversation (denormalized)';
COMMENT ON COLUMN public.message_attachments.file_name IS 'Original file name';
COMMENT ON COLUMN public.message_attachments.file_size_bytes IS 'File size in bytes';
COMMENT ON COLUMN public.message_attachments.mime_type IS 'MIME type';
COMMENT ON COLUMN public.message_attachments.file_hash IS 'SHA-256 hash for integrity';
COMMENT ON COLUMN public.message_attachments.storage_provider IS 'Where file is stored';
COMMENT ON COLUMN public.message_attachments.storage_path IS 'Path in storage provider';
COMMENT ON COLUMN public.message_attachments.public_url IS 'Temporary access URL';
COMMENT ON COLUMN public.message_attachments.thumbnail_path IS 'Path to thumbnail';
COMMENT ON COLUMN public.message_attachments.virus_scan_status IS 'Security scan status';
COMMENT ON COLUMN public.message_attachments.virus_scan_result IS 'Scan result details';
COMMENT ON COLUMN public.message_attachments.width IS 'Image width (pixels)';
COMMENT ON COLUMN public.message_attachments.height IS 'Image height (pixels)';
COMMENT ON COLUMN public.message_attachments.duration_seconds IS 'Duration for media';
COMMENT ON COLUMN public.message_attachments.expires_at IS 'When attachment expires';

-- Indexes
CREATE INDEX idx_message_attachments_message ON public.message_attachments(message_id);
CREATE INDEX idx_message_attachments_conversation ON public.message_attachments(conversation_id, created_at DESC);
CREATE INDEX idx_message_attachments_virus ON public.message_attachments(virus_scan_status)
    WHERE virus_scan_status IN ('PENDING', 'SCANNING');
CREATE INDEX idx_message_attachments_expires ON public.message_attachments(expires_at)
    WHERE expires_at IS NOT NULL AND is_expired = false;

-- GIN index for tags
CREATE INDEX idx_message_attachments_tags ON public.message_attachments USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_message_attachments_timestamp
    BEFORE UPDATE ON public.message_attachments
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.message_attachments ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY message_attachments_participant_policy ON public.message_attachments
    USING (EXISTS (
        SELECT 1 FROM public.conversation_participants cp
        WHERE cp.conversation_id = message_attachments.conversation_id
        AND cp.user_id = current_user_id()
        AND cp.is_active = true
    ));

-- =============================================================================
-- TABLE 105: message_read_receipts
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 105
-- Table Name: message_read_receipts
-- Description: Tracks which users have read which messages, enabling read
--              receipts and unread counts.
--
-- Business Case (300 words):
-- Read receipts are a fundamental feature of modern messaging—they tell users
-- when their messages have been seen. This table tracks every read event,
-- enabling accurate unread counts, read receipts, and analytics on message
-- engagement.
--
-- Without read tracking, users would have no idea if their messages were seen,
-- leading to uncertainty and follow-up messages asking "did you see this?".
-- Group conversations would lack visibility into who has read important messages.
-- This table provides the data that makes messaging feel responsive and reliable.
--
-- The business impact is user confidence—users trust the platform more when
-- they can see that their communications are being received. For time-sensitive
-- professional communications (job offers, contract negotiations), read receipts
-- provide critical confirmation. For analytics, read rates indicate which
-- messages are actually being seen by recipients.
--
-- The design stores each read event with the user, message, and timestamp.
-- This enables both point-in-time queries (has user read this message?) and
-- historical analysis (when did users typically read messages?). The table is
-- write-heavy (every read creates a record) but queries are highly selective
-- (specific message/user combinations).
--
-- Key Performance Indicators (KPIs):
--   1. Read Rate: Percentage of messages read within 24 hours
--   2. Time to Read: Average delay between send and first read
--   3. Group Read Coverage: Percentage of group members who read key messages
--   4. Read Receipt Overhead: Storage per message
--   5. User Reading Patterns: Time of day when messages are read
--
-- Feature Reference: MSG-09 (Read Receipts)
-- Requirements Traceability: R-MSG-071 through R-MSG-080
--
-- Normalization: 3NF - Read receipts as independent events
--
-- High-Write Considerations:
--   - Extremely high write volume (every message read)
--   - Partitioned by read_at for write scalability
--   - Composite primary key for efficient lookups
--   - Automatic cleanup of old receipts (>90 days)
-------------------------------------------------------------------------------
CREATE TABLE public.message_read_receipts (
    -- Primary key (composite for partitioning)
    read_id UUID DEFAULT gen_random_uuid() NOT NULL,
    read_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Message
    message_id UUID NOT NULL,
    conversation_id UUID NOT NULL, -- Denormalized for performance

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Read context
    read_count INTEGER DEFAULT 1, -- For counting multiple reads
    read_duration_ms INTEGER, -- How long message was visible
    scroll_position INTEGER, -- Where in conversation they were

    -- Client info
    ip_address INET,
    user_agent TEXT,
    device_type VARCHAR(50),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT unique_message_user UNIQUE (message_id, user_id),

    PRIMARY KEY (read_id, read_at)
) PARTITION BY RANGE (read_at);

COMMENT ON TABLE public.message_read_receipts IS 'Tracks which users have read which messages';
COMMENT ON COLUMN public.message_read_receipts.read_id IS 'Primary key';
COMMENT ON COLUMN public.message_read_receipts.read_at IS 'When message was read (partition key)';
COMMENT ON COLUMN public.message_read_receipts.message_id IS 'Message that was read';
COMMENT ON COLUMN public.message_read_receipts.conversation_id IS 'Conversation (denormalized)';
COMMENT ON COLUMN public.message_read_receipts.user_id IS 'User who read the message';
COMMENT ON COLUMN public.message_read_receipts.read_count IS 'Number of times read';
COMMENT ON COLUMN public.message_read_receipts.read_duration_ms IS 'How long message was visible';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_read_receipts_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'message_read_receipts_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.message_read_receipts
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(message_id);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, read_at DESC);
        ',
        'idx_' || partition_name || '_msg', partition_name,
        'idx_' || partition_name || '_user', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for next 7 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..7 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_read_receipts_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_read_receipts_message ON public.message_read_receipts(message_id);
CREATE INDEX idx_read_receipts_user ON public.message_read_receipts(user_id, read_at DESC);
CREATE INDEX idx_read_receipts_conversation ON public.message_read_receipts(conversation_id, read_at DESC);

-- Function to update message read counts
CREATE OR REPLACE FUNCTION public.update_message_read_counts()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE public.messages
    SET read_count = read_count + 1,
        updated_at = CURRENT_TIMESTAMP
    WHERE message_id = NEW.message_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_message_read_counts
    AFTER INSERT ON public.message_read_receipts
    FOR EACH ROW EXECUTE FUNCTION public.update_message_read_counts();

-- Enable RLS
ALTER TABLE public.message_read_receipts ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY read_receipts_participant_policy ON public.message_read_receipts
    USING (EXISTS (
        SELECT 1 FROM public.conversation_participants cp
        WHERE cp.conversation_id = message_read_receipts.conversation_id
        AND cp.user_id = current_user_id()
        AND cp.is_active = true
    ));

-- =============================================================================
-- TABLE 106: message_reactions
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 106
-- Table Name: message_reactions
-- Description: Emoji reactions to messages, enabling lightweight engagement
--              without cluttering conversations with additional messages.
--
-- Business Case (300 words):
-- Emoji reactions provide a lightweight way for users to acknowledge messages,
-- express emotions, or vote without creating additional message clutter. This
-- feature has become standard in modern messaging and significantly enhances
-- conversation dynamics.
--
-- Without reactions, users must type "👍" or "agree" as separate messages,
-- creating noise in conversations and making it harder to scan for substantive
-- content. Reactions keep conversations clean while still allowing users to
-- acknowledge messages. For group decision-making, reactions can serve as
-- lightweight voting mechanisms.
--
-- The business impact is conversation quality—reactions reduce noise while
-- increasing engagement. Users are more likely to react than to type a response,
-- so reactions increase the sense of community and responsiveness. For analytics,
-- reaction patterns reveal sentiment and engagement with specific messages.
--
-- The design stores each reaction with the user, message, and emoji. This
-- enables both aggregated counts (how many 👍 on this message) and detailed
-- views (who reacted with what). Reactions can be added, removed, and changed,
-- with timestamps tracking the latest state.
--
-- Key Performance Indicators (KPIs):
--   1. Reaction Rate: Percentage of messages with reactions
--   2. Reactions per Message: Average count on reacted messages
--   3. Unique Reactors: Percentage of users who use reactions
--   4. Popular Emojis: Most frequently used reactions
--   5. Reaction Time: Time from message to first reaction
--   6. Reaction Removal Rate: How often reactions are removed
--
-- Feature Reference: MSG-10 (Message Reactions)
-- Requirements Traceability: R-MSG-081 through R-MSG-090
--
-- Normalization: 3NF - Reactions as independent events
--
-- High-Write Considerations:
--   - High write volume (reactions added/removed frequently)
--   - Partitioned by created_at for write scalability
--   - Unique constraint prevents duplicate reactions
--   - Partial indexes for active reactions only
-------------------------------------------------------------------------------
CREATE TABLE public.message_reactions (
    -- Primary key (composite for partitioning)
    reaction_id UUID DEFAULT gen_random_uuid() NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Message
    message_id UUID NOT NULL,
    conversation_id UUID NOT NULL, -- Denormalized for performance

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Reaction
    emoji VARCHAR(50) NOT NULL, -- Unicode emoji or custom emoji ID
    emoji_type VARCHAR(20) CHECK (emoji_type IN ('unicode', 'custom', 'skin_tone')),

    -- State
    is_active BOOLEAN DEFAULT true,
    removed_at TIMESTAMP WITH TIME ZONE,
    removed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT unique_message_user_emoji UNIQUE (message_id, user_id, emoji),

    PRIMARY KEY (reaction_id, created_at)
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.message_reactions IS 'Emoji reactions to messages';
COMMENT ON COLUMN public.message_reactions.reaction_id IS 'Primary key';
COMMENT ON COLUMN public.message_reactions.created_at IS 'When reaction was added (partition key)';
COMMENT ON COLUMN public.message_reactions.message_id IS 'Message being reacted to';
COMMENT ON COLUMN public.message_reactions.conversation_id IS 'Conversation (denormalized)';
COMMENT ON COLUMN public.message_reactions.user_id IS 'User who reacted';
COMMENT ON COLUMN public.message_reactions.emoji IS 'Emoji character or ID';
COMMENT ON COLUMN public.message_reactions.emoji_type IS 'Type of emoji';
COMMENT ON COLUMN public.message_reactions.is_active IS 'Whether reaction is still present';
COMMENT ON COLUMN public.message_reactions.removed_at IS 'When reaction was removed';
COMMENT ON COLUMN public.message_reactions.removed_by IS 'Who removed it';

-- Create partition management function (reuse from messages)
SELECT public.create_messages_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);

-- Global indexes
CREATE INDEX idx_message_reactions_message ON public.message_reactions(message_id, emoji) WHERE is_active = true;
CREATE INDEX idx_message_reactions_user ON public.message_reactions(user_id, created_at DESC);
CREATE INDEX idx_message_reactions_conversation ON public.message_reactions(conversation_id, created_at DESC);

-- Trigger for updated_at
CREATE TRIGGER update_message_reactions_timestamp
    BEFORE UPDATE ON public.message_reactions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to update message reaction counts
CREATE OR REPLACE FUNCTION public.update_message_reaction_counts()
RETURNS TRIGGER AS $$
DECLARE
    v_reactions JSONB;
BEGIN
    -- Aggregate reactions for the message
    SELECT jsonb_object_agg(emoji, reaction_count)
    INTO v_reactions
    FROM (
        SELECT emoji, COUNT(*) as reaction_count
        FROM public.message_reactions
        WHERE message_id = COALESCE(NEW.message_id, OLD.message_id)
            AND is_active = true
        GROUP BY emoji
    ) t;

    UPDATE public.messages
    SET emoji_reactions = v_reactions,
        updated_at = CURRENT_TIMESTAMP
    WHERE message_id = COALESCE(NEW.message_id, OLD.message_id);

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_message_reaction_counts
    AFTER INSERT OR UPDATE OR DELETE ON public.message_reactions
    FOR EACH ROW EXECUTE FUNCTION public.update_message_reaction_counts();

-- Enable RLS
ALTER TABLE public.message_reactions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY message_reactions_participant_policy ON public.message_reactions
    USING (EXISTS (
        SELECT 1 FROM public.conversation_participants cp
        WHERE cp.conversation_id = message_reactions.conversation_id
        AND cp.user_id = current_user_id()
        AND cp.is_active = true
    ));

-- =============================================================================
-- MATERIALIZED VIEW: mv_messaging_analytics
-- =============================================================================
-------------------------------------------------------------------------------
-- Materialized View: mv_messaging_analytics
-- Description: Pre-aggregated messaging metrics for product teams
-- Refresh Strategy: Hourly
-- Feature Reference: MSG-11 (Messaging Analytics)
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW public.mv_messaging_analytics AS
WITH daily_stats AS (
    SELECT
        DATE_TRUNC('day', m.created_at) as day,
        c.conversation_type,
        COUNT(DISTINCT m.conversation_id) as active_conversations,
        COUNT(*) as total_messages,
        COUNT(DISTINCT m.sender_id) as active_senders,
        AVG(LENGTH(m.body)) as avg_message_length,
        COUNT(*) FILTER (WHERE m.has_attachments) as messages_with_attachments,
        COUNT(*) FILTER (WHERE m.is_edited) as edited_messages,
        COUNT(*) FILTER (WHERE m.is_deleted) as deleted_messages,
        AVG(m.read_count) FILTER (WHERE m.read_count > 0) as avg_read_count
    FROM public.messages m
    JOIN public.conversations c ON m.conversation_id = c.conversation_id
    WHERE m.created_at > CURRENT_TIMESTAMP - INTERVAL '30 days'
    GROUP BY DATE_TRUNC('day', m.created_at), c.conversation_type
)
SELECT
    day,
    conversation_type,
    active_conversations,
    total_messages,
    active_senders,
    ROUND(avg_message_length::NUMERIC, 2) as avg_message_length,
    messages_with_attachments,
    ROUND((messages_with_attachments::NUMERIC / NULLIF(total_messages, 0) * 100), 2) as attachment_rate,
    edited_messages,
    deleted_messages,
    ROUND(avg_read_count::NUMERIC, 2) as avg_read_count,
    SUM(total_messages) OVER (PARTITION BY conversation_type ORDER BY day ROWS 6 PRECEDING) as rolling_7d_messages,
    NOW() as refreshed_at
FROM daily_stats
ORDER BY day DESC, conversation_type;

COMMENT ON MATERIALIZED VIEW public.mv_messaging_analytics IS 'Pre-aggregated messaging metrics for product teams';

CREATE UNIQUE INDEX idx_mv_messaging_analytics_day ON public.mv_messaging_analytics(day, conversation_type);

-- =============================================================================
-- STORED PROCEDURES
-- =============================================================================

-------------------------------------------------------------------------------
-- Procedure: send_notification
-- Description: Creates and sends a notification to a user with template rendering
-- Business Case: Centralized notification sending with consistent handling
-- Feature Reference: NOT-10 (Notification Sending)
-------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE public.send_notification(
    p_user_id UUID,
    p_template_name VARCHAR(255),
    p_template_data JSONB,
    p_target_entity_type VARCHAR(50) DEFAULT NULL,
    p_target_entity_id UUID DEFAULT NULL,
    p_priority public.notification_priority DEFAULT 'MEDIUM'
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_template RECORD;
    v_notification_id UUID;
    v_rendered_title TEXT;
    v_rendered_body TEXT;
    v_user_email VARCHAR(255);
    v_user_preferences RECORD;
BEGIN
    -- Get template
    SELECT * INTO v_template
    FROM public.notification_templates
    WHERE template_name = p_template_name
        AND is_active = true
    ORDER BY version DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Template % not found or inactive', p_template_name;
    END IF;

    -- Get user email for denormalization
    SELECT email INTO v_user_email
    FROM public.users
    WHERE user_id = p_user_id;

    -- Render template (simplified - would use proper template engine)
    v_rendered_title := COALESCE(v_template.subject, '');
    v_rendered_body := v_template.body_template;

    -- Create notification
    INSERT INTO public.user_notifications (
        user_id,
        title,
        body,
        category,
        priority,
        template_id,
        template_version,
        target_entity_type,
        target_entity_id,
        metadata
    ) VALUES (
        p_user_id,
        v_rendered_title,
        v_rendered_body,
        v_template.category,
        p_priority,
        v_template.template_id,
        v_template.version,
        p_target_entity_type,
        p_target_entity_id,
        p_template_data
    ) RETURNING notification_id INTO v_notification_id;

    -- Log the notification creation
    INSERT INTO public.audit_logs (
        actor_id,
        action,
        entity_type,
        entity_id,
        details,
        category,
        severity
    ) VALUES (
        current_user_id(),
        'SEND_NOTIFICATION',
        'user_notifications',
        v_notification_id,
        jsonb_build_object(
            'user_id', p_user_id,
            'template', p_template_name,
            'priority', p_priority
        ),
        'NOTIFICATION',
        'INFO'
    );

    -- Queue for delivery (actual delivery handled by background workers)
    -- This would typically insert into a queue table or notify a worker

    RAISE NOTICE 'Notification % created for user %', v_notification_id, p_user_id;
END;
$$;

COMMENT ON PROCEDURE public.send_notification IS 'Creates and sends a notification to a user with template rendering';

-- =============================================================================
-- SCHEDULED JOBS
-- =============================================================================

-- Create scheduled jobs if pg_cron is available
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
        -- Clean up expired notifications daily
        PERFORM cron.schedule(
            'cleanup-expired-notifications',
            '0 2 * * *',
            $$
            UPDATE public.user_notifications
            SET is_expired = true
            WHERE expires_at < CURRENT_TIMESTAMP;
            $$
        );

        -- Process digest notifications hourly
        PERFORM cron.schedule(
            'process-digest-notifications',
            '0 * * * *',
            $$
            -- Logic for aggregating digest notifications
            -- Would query notification_preferences and send digests
            $$
        );

        -- Refresh messaging analytics hourly
        PERFORM cron.schedule(
            'refresh-messaging-analytics',
            '0 * * * *',
            'REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_messaging_analytics;'
        );

        -- Clean up old read receipts monthly (keep 90 days)
        PERFORM cron.schedule(
            'cleanup-old-read-receipts',
            '0 3 1 * *',
            $$
            DELETE FROM public.message_read_receipts
            WHERE read_at < CURRENT_TIMESTAMP - INTERVAL '90 days';
            $$
        );
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'pg_cron extension not available. Scheduled tasks will not be created.';
END $$;

