-- =============================================================================
-- ENUMS FOR REAL-TIME FEATURES
-- =============================================================================

-------------------------------------------------------------------------------
-- Enum: RTF01 - live_stream_status
-- Description: Status of a live video stream throughout its lifecycle
-- Business Case: Tracks stream state from creation to completion
-- Feature Reference: LIVE-01 (Stream Lifecycle)
-------------------------------------------------------------------------------
CREATE TYPE public.live_stream_status AS ENUM (
    'SCHEDULED',        -- Stream scheduled for future
    'PREPARING',        -- Streamer preparing, not yet live
    'LIVE',             -- Currently broadcasting
    'PAUSED',           -- Temporarily paused
    'INTERRUPTED',      -- Technical interruption
    'ENDED',            -- Successfully completed
    'FAILED',           -- Failed to start/had errors
    'ARCHIVED'          -- Recording archived for replay
);
COMMENT ON TYPE public.live_stream_status IS 'Lifecycle states for live video streams';

-------------------------------------------------------------------------------
-- Enum: RTF02 - live_stream_type
-- Description: Types of live video content
-- Business Case: Differentiates content types for discovery and monetization
-- Feature Reference: LIVE-02 (Stream Types)
-------------------------------------------------------------------------------
CREATE TYPE public.live_stream_type AS ENUM (
    'WEBINAR',          -- One-to-many presentation
    'WORKSHOP',         -- Interactive teaching session
    'Q_AND_A',          -- Question and answer session
    'INTERVIEW',        -- Interview between hosts
    'PANEL',            -- Multiple speakers discussion
    'EVENT_COVERAGE',   -- Live event broadcasting
    'PERSONAL_STREAM',  -- Casual personal streaming
    'PRODUCT_LAUNCH',   -- Product announcement
    'TUTORIAL'          -- Step-by-step tutorial
);
COMMENT ON TYPE public.live_stream_type IS 'Types of live video content available on the platform';

-------------------------------------------------------------------------------
-- Enum: RTF03 - participant_role_live
-- Description: Roles of participants in live streams
-- Business Case: Enables permission management for different participant types
-- Feature Reference: LIVE-03 (Participant Roles)
-------------------------------------------------------------------------------
CREATE TYPE public.participant_role_live AS ENUM (
    'HOST',             -- Primary streamer/host
    'CO_HOST',          -- Co-host with moderation privileges
    'SPEAKER',          -- Guest speaker (can speak)
    'MODERATOR',        -- Can moderate chat and manage participants
    'VIEWER',           -- Regular viewer (can watch and chat)
    'LISTENER'          -- Listen-only mode (no chat)
);
COMMENT ON TYPE public.participant_role_live IS 'Roles for participants in live video streams';

-------------------------------------------------------------------------------
-- Enum: RTF04 - presence_status
-- Description: User presence states for real-time features
-- Business Case: Enables accurate online/offline/away detection
-- Feature Reference: PRES-01 (Presence Tracking)
-------------------------------------------------------------------------------
CREATE TYPE public.presence_status AS ENUM (
    'ONLINE',           -- Actively connected
    'AWAY',             -- Connected but inactive
    'BUSY',             -- Connected but in Do Not Disturb
    'OFFLINE',          -- Disconnected
    'INVISIBLE'         -- Connected but appears offline
);
COMMENT ON TYPE public.presence_status IS 'User presence states for real-time features';

-------------------------------------------------------------------------------
-- Enum: RTF05 - connection_type
-- Description: Types of real-time connections
-- Business Case: Differentiates connection types for monitoring and scaling
-- Feature Reference: REAL-01 (Connection Types)
-------------------------------------------------------------------------------
CREATE TYPE public.connection_type AS ENUM (
    'WEBSOCKET',        -- WebSocket connection
    'SSE',              -- Server-Sent Events
    'LONG_POLLING',     -- Long-polling fallback
    'WEBRTC',           -- WebRTC data channel
    'MOBILE_PUSH'       -- Mobile push notification channel
);
COMMENT ON TYPE public.connection_type IS 'Types of real-time connections supported';

-------------------------------------------------------------------------------
-- Enum: RTF06 - webrtc_session_status
-- Description: Status of WebRTC peer connections
-- Business Case: Tracks WebRTC session lifecycle for media calls
-- Feature Reference: WEBRTC-01 (WebRTC Session Lifecycle)
-------------------------------------------------------------------------------
CREATE TYPE public.webrtc_session_status AS ENUM (
    'INITIATING',       -- Session being set up
    'CONNECTING',       -- ICE gathering/connectivity checks
    'CONNECTED',        -- Successfully connected
    'RECONNECTING',     -- Attempting to reconnect
    'DISCONNECTED',     -- Gracefully disconnected
    'FAILED',           -- Connection failed
    'CLOSED'            -- Session ended
);
COMMENT ON TYPE public.webrtc_session_status IS 'Lifecycle states for WebRTC peer connections';

-- =============================================================================
-- TABLE 107: live_video_streams
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 107
-- Table Name: live_video_streams
-- Description: Manages live video streaming sessions including metadata,
--              stream keys, recording settings, and viewer analytics.
--
-- Business Case (300 words):
-- Live video has become an essential feature for professional networking,
-- enabling virtual events, webinars, workshops, and real-time engagement
-- between users. This table manages the complete lifecycle of live streams,
-- from scheduling through broadcasting to archived playback. It provides the
-- foundation for a scalable live streaming infrastructure.
--
-- Without a robust live stream management system, the platform cannot support
-- real-time video engagement at scale. Streams would lack proper authentication,
-- recording capabilities would be inconsistent, and viewer analytics would be
-- impossible to track. This table addresses these challenges by providing a
-- centralized system for stream configuration, security, and monitoring.
--
-- The business impact is substantial: live video increases user engagement by
-- 300% compared to pre-recorded content, with viewers spending 8x more time
-- on live content. For creators, live streaming provides monetization
-- opportunities through ticketed events and sponsorships. For the platform,
-- live events drive retention and create network effects as users invite
-- colleagues to join.
--
-- The design supports enterprise-grade features: RTMP/SRT ingest for
-- professional broadcasting tools, adaptive bitrate streaming for optimal
-- viewer experience, DVR functionality for time-shifted viewing, and detailed
-- analytics on viewer engagement. Stream keys ensure secure access for
-- broadcasters, while chat integration enables real-time interaction.
--
-- Key Performance Indicators (KPIs):
--   1. Concurrent Streams: Peak live streams at any time
--   2. Viewer Concurrency: Average viewers per stream
--   3. Stream Completion Rate: Percentage of scheduled streams completed
--   4. Viewer Retention: Drop-off rates during streams
--   5. Stream Quality: Average bitrate and resolution
--   6. Latency: End-to-end streaming delay (<5 seconds)
--   7. Recording Success: Percentage of streams successfully recorded
--   8. Monetization: Revenue from ticketed streams
--
-- Feature Reference: LIVE-04 (Stream Management)
-- Requirements Traceability: R-LIVE-001 through R-LIVE-030
--
-- Normalization: 3NF - Streams independent with host references
--
-- High-Write Considerations:
--   - Moderate write volume (stream creation/updates)
--   - Read-heavy for stream discovery and viewing
--   - Partitioning by scheduled_time for historical queries
--   - Partial indexes for live streams only
-------------------------------------------------------------------------------
CREATE TABLE public.live_video_streams (
    -- Primary key
    stream_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Stream identification
    stream_title VARCHAR(500) NOT NULL,
    stream_description TEXT,
    stream_type public.live_stream_type NOT NULL,

    -- Host information
    host_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    co_hosts UUID[], -- Array of co-host user IDs
    organization_id UUID REFERENCES public.companies(company_id) ON DELETE SET NULL,

    -- Scheduling
    scheduled_start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    scheduled_end_time TIMESTAMP WITH TIME ZONE,
    actual_start_time TIMESTAMP WITH TIME ZONE,
    actual_end_time TIMESTAMP WITH TIME ZONE,
    duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (actual_end_time - actual_start_time))
    ) STORED,

    -- Stream status
    status public.live_stream_status NOT NULL DEFAULT 'SCHEDULED',
    status_reason TEXT,
    quality_issues TEXT[],

    -- Stream keys and URLs (for broadcaster)
    stream_key VARCHAR(255) UNIQUE, -- RTMP/SRT stream key
    ingest_url TEXT, -- RTMP/SRT ingest endpoint
    playback_url TEXT, -- HLS/DASH playback URL
    playback_url_hls TEXT, -- HLS specific
    playback_url_dash TEXT, -- DASH specific

    -- Recording
    record_stream BOOLEAN DEFAULT true,
    recording_url TEXT, -- URL to recorded video
    recording_start_time TIMESTAMP WITH TIME ZONE,
    recording_end_time TIMESTAMP WITH TIME ZONE,
    recording_size_bytes BIGINT,
    recording_format VARCHAR(50),

    -- Thumbnails
    thumbnail_url TEXT,
    thumbnail_timestamps INTEGER[], -- Timestamps for thumbnails

    -- Stream settings
    max_viewers INTEGER, -- Limit concurrent viewers
    is_private BOOLEAN DEFAULT false,
    allowed_viewers UUID[], -- Specific users allowed (if private)
    requires_ticket BOOLEAN DEFAULT false,
    ticket_price NUMERIC(10,2),
    ticket_currency CHAR(3) DEFAULT 'USD',

    -- Chat settings
    chat_enabled BOOLEAN DEFAULT true,
    chat_rate_limit INTEGER DEFAULT 10, -- Messages per minute
    slow_mode BOOLEAN DEFAULT false,
    slow_mode_interval INTEGER DEFAULT 30, -- Seconds between messages
    moderation_enabled BOOLEAN DEFAULT true,
    allowed_chatters UUID[], -- Users allowed to chat (if restricted)

    -- Monetization
    is_monetized BOOLEAN DEFAULT false,
    tips_enabled BOOLEAN DEFAULT false,
    super_chat_enabled BOOLEAN DEFAULT false,
    merchandise_url TEXT,

    -- Viewer metrics
    peak_viewers INTEGER DEFAULT 0,
    total_viewers INTEGER DEFAULT 0,
    unique_viewers INTEGER DEFAULT 0,
    avg_view_duration_seconds INTEGER,
    chat_messages_count INTEGER DEFAULT 0,
    likes_count INTEGER DEFAULT 0,
    shares_count INTEGER DEFAULT 0,

    -- Geographic distribution (aggregated)
    viewer_countries JSONB, -- Country-level viewer counts
    viewer_cities JSONB, -- City-level viewer counts (anonymized)

    -- Stream health
    health_score NUMERIC(3,2) CHECK (health_score >= 0 AND health_score <= 1),
    buffering_ratio NUMERIC(5,4), -- Ratio of buffering time
    bitrate_avg INTEGER, -- Average bitrate (kbps)
    bitrate_min INTEGER,
    bitrate_max INTEGER,
    resolution VARCHAR(20), -- e.g., '1080p', '720p'
    frame_rate INTEGER,

    -- CDN information
    cdn_provider VARCHAR(100),
    cdn_region VARCHAR(100),
    edge_locations TEXT[],

    -- Tags and categories
    tags TEXT[],
    categories TEXT[],

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Metadata
    metadata JSONB,
    notes TEXT,

    -- Constraints
    CONSTRAINT valid_stream_times CHECK (
        (actual_start_time IS NULL OR actual_start_time >= scheduled_start_time) AND
        (actual_end_time IS NULL OR actual_end_time >= actual_start_time) AND
        (scheduled_end_time IS NULL OR scheduled_end_time >= scheduled_start_time)
    ),
    CONSTRAINT valid_ticket CHECK (
        (requires_ticket = false) OR
        (requires_ticket = true AND ticket_price IS NOT NULL)
    )
);

COMMENT ON TABLE public.live_video_streams IS 'Manages live video streaming sessions with full metadata and analytics';
COMMENT ON COLUMN public.live_video_streams.stream_id IS 'Primary key';
COMMENT ON COLUMN public.live_video_streams.stream_title IS 'Title of the live stream';
COMMENT ON COLUMN public.live_video_streams.stream_type IS 'Type of live content';
COMMENT ON COLUMN public.live_video_streams.host_id IS 'Primary host/streamer';
COMMENT ON COLUMN public.live_video_streams.co_hosts IS 'Additional hosts/co-hosts';
COMMENT ON COLUMN public.live_video_streams.scheduled_start_time IS 'When stream is scheduled to start';
COMMENT ON COLUMN public.live_video_streams.actual_start_time IS 'When stream actually started';
COMMENT ON COLUMN public.live_video_streams.status IS 'Current stream status';
COMMENT ON COLUMN public.live_video_streams.stream_key IS 'Secret key for broadcasting (RTMP)';
COMMENT ON COLUMN public.live_video_streams.ingest_url IS 'URL for broadcaster to push stream';
COMMENT ON COLUMN public.live_video_streams.playback_url IS 'URL for viewers to watch';
COMMENT ON COLUMN public.live_video_streams.recording_url IS 'URL to recorded video after stream';
COMMENT ON COLUMN public.live_video_streams.max_viewers IS 'Maximum concurrent viewers allowed';
COMMENT ON COLUMN public.live_video_streams.is_private IS 'Whether stream is private/invite-only';
COMMENT ON COLUMN public.live_video_streams.requires_ticket IS 'Whether ticket purchase required';
COMMENT ON COLUMN public.live_video_streams.peak_viewers IS 'Maximum concurrent viewers reached';
COMMENT ON COLUMN public.live_video_streams.total_viewers IS 'Total viewers over stream lifetime';
COMMENT ON COLUMN public.live_video_streams.health_score IS 'Stream quality score (0-1)';
COMMENT ON COLUMN public.live_video_streams.buffering_ratio IS 'Ratio of time spent buffering';

-- Indexes
CREATE INDEX idx_live_streams_host ON public.live_video_streams(host_id, scheduled_start_time DESC);
CREATE INDEX idx_live_streams_status ON public.live_video_streams(status, scheduled_start_time);
CREATE INDEX idx_live_streams_scheduled ON public.live_video_streams(scheduled_start_time)
    WHERE status = 'SCHEDULED';
CREATE INDEX idx_live_streams_live ON public.live_video_streams(actual_start_time DESC)
    WHERE status = 'LIVE';
CREATE INDEX idx_live_streams_type ON public.live_video_streams(stream_type);
CREATE INDEX idx_live_streams_organization ON public.live_video_streams(organization_id)
    WHERE organization_id IS NOT NULL;

-- GIN indexes
CREATE INDEX idx_live_streams_co_hosts ON public.live_video_streams USING gin(co_hosts);
CREATE INDEX idx_live_streams_allowed_viewers ON public.live_video_streams USING gin(allowed_viewers);
CREATE INDEX idx_live_streams_tags ON public.live_video_streams USING gin(tags);
CREATE INDEX idx_live_streams_categories ON public.live_video_streams USING gin(categories);

-- Trigger for updated_at
CREATE TRIGGER update_live_video_streams_timestamp
    BEFORE UPDATE ON public.live_video_streams
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.live_video_streams ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY live_streams_host_policy ON public.live_video_streams
    FOR ALL USING (host_id = current_user_id() OR
                   current_user_id() = ANY(co_hosts) OR
                   EXISTS (SELECT 1 FROM public.user_roles ur
                          JOIN public.roles r ON ur.role_id = r.role_id
                          WHERE ur.user_id = current_user_id() AND r.name = 'admin'));

CREATE POLICY live_streams_viewer_policy ON public.live_video_streams
    FOR SELECT USING (
        is_private = false OR
        (is_private = true AND current_user_id() = ANY(allowed_viewers)) OR
        host_id = current_user_id() OR
        current_user_id() = ANY(co_hosts)
    );

-- =============================================================================
-- TABLE 108: live_video_participants
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 108
-- Table Name: live_video_participants
-- Description: Tracks viewers and participants in live streams with role,
--              join/leave times, and engagement metrics.
--
-- Business Case (300 words):
-- Understanding viewer behavior during live streams is critical for measuring
-- success and improving content. This table tracks every participant in a live
-- stream, capturing when they joined, when they left, their role, and their
-- engagement actions (chat messages, reactions, etc.). This data powers
-- analytics dashboards for creators and informs recommendations for viewers.
--
-- Without participant tracking, creators have no visibility into their audience—
-- they don't know how many people watched, how long they stayed, or when they
-- dropped off. Viewers would have no persistent connection to streams they've
-- attended. This table provides the foundation for understanding live stream
-- performance and building community around live content.
--
-- The business impact is direct: creators use engagement metrics to improve
-- their content, leading to higher retention and more streams. The platform
-- uses participant data to recommend relevant live content to users based on
-- their viewing history. For monetized streams, accurate participant counts
-- are essential for revenue calculations and fraud detection.
--
-- The design captures the full participant journey: join time, leave time,
-- watch duration, engagement actions (likes, shares, chat messages), and
-- quality of experience (buffering events, resolution switches). This enables
-- granular analysis of viewer behavior and stream quality impact on retention.
--
-- Key Performance Indicators (KPIs):
--   1. Average Watch Time: Mean duration viewers stayed
--   2. Viewer Drop-off: Percentage leaving at each time interval
--   3. Return Rate: Viewers who attend multiple streams from same creator
--   4. Engagement Rate: Actions per viewer per minute
--   5. Peak Concurrency: Maximum simultaneous viewers
--   6. Geographic Distribution: Viewer locations
--   7. Device Distribution: Mobile vs. desktop viewership
--   8. Quality Impact: Correlation between buffering and drop-off
--
-- Feature Reference: LIVE-05 (Participant Tracking)
-- Requirements Traceability: R-LIVE-031 through R-LIVE-045
--
-- Normalization: 3NF - Participants dependent on streams and users
--
-- High-Write Considerations:
--   - Very high write volume (every join/leave event)
--   - Partitioned by joined_at for write scalability
--   - BRIN indexes for time-series queries
--   - Partial indexes for active participants only
-------------------------------------------------------------------------------
CREATE TABLE public.live_video_participants (
    -- Primary key (composite for partitioning)
    participant_id UUID DEFAULT gen_random_uuid() NOT NULL,
    joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Stream
    stream_id UUID NOT NULL REFERENCES public.live_video_streams(stream_id) ON DELETE CASCADE,

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Participant role
    role public.participant_role_live NOT NULL DEFAULT 'VIEWER',

    -- Session timing
    left_at TIMESTAMP WITH TIME ZONE,
    watch_duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (COALESCE(left_at, CURRENT_TIMESTAMP) - joined_at))
    ) STORED,
    is_active BOOLEAN GENERATED ALWAYS AS (left_at IS NULL) STORED,

    -- Engagement metrics
    chat_messages_sent INTEGER DEFAULT 0,
    reactions_sent INTEGER DEFAULT 0,
    likes_given INTEGER DEFAULT 0,
    shares_count INTEGER DEFAULT 0,
    tips_amount NUMERIC(10,2),
    tips_currency CHAR(3) DEFAULT 'USD',

    -- Quality of experience
    buffering_events INTEGER DEFAULT 0,
    buffering_duration_seconds INTEGER DEFAULT 0,
    resolution_switches INTEGER DEFAULT 0,
    avg_bitrate INTEGER,
    connection_drops INTEGER DEFAULT 0,

    -- Device info
    device_type VARCHAR(50),
    platform VARCHAR(50),
    browser VARCHAR(100),
    os VARCHAR(100),
    app_version VARCHAR(50),
    ip_address INET,
    user_agent TEXT,

    -- Geographic
    country_code CHAR(2),
    region VARCHAR(100),
    city VARCHAR(100),

    -- Referral
    referred_by VARCHAR(50), -- How they found the stream
    referrer_url TEXT,

    -- Monetization
    ticket_purchased BOOLEAN DEFAULT false,
    ticket_price NUMERIC(10,2),
    payment_id UUID,

    -- Feedback
    rating INTEGER CHECK (rating >= 1 AND rating <= 5),
    feedback_text TEXT,
    would_recommend BOOLEAN,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT unique_stream_user UNIQUE (stream_id, user_id),

    PRIMARY KEY (participant_id, joined_at)
) PARTITION BY RANGE (joined_at);

COMMENT ON TABLE public.live_video_participants IS 'Tracks viewers and participants in live streams';
COMMENT ON COLUMN public.live_video_participants.participant_id IS 'Primary key';
COMMENT ON COLUMN public.live_video_participants.joined_at IS 'When user joined (partition key)';
COMMENT ON COLUMN public.live_video_participants.stream_id IS 'Stream being viewed';
COMMENT ON COLUMN public.live_video_participants.user_id IS 'Viewer user';
COMMENT ON COLUMN public.live_video_participants.role IS 'Role in stream';
COMMENT ON COLUMN public.live_video_participants.left_at IS 'When user left';
COMMENT ON COLUMN public.live_video_participants.watch_duration_seconds IS 'Total watch time';
COMMENT ON COLUMN public.live_video_participants.is_active IS 'Whether currently watching';
COMMENT ON COLUMN public.live_video_participants.chat_messages_sent IS 'Number of chat messages';
COMMENT ON COLUMN public.live_video_participants.buffering_events IS 'Number of buffering occurrences';
COMMENT ON COLUMN public.live_video_participants.buffering_duration_seconds IS 'Total buffering time';
COMMENT ON COLUMN public.live_video_participants.ticket_purchased IS 'Whether ticket was purchased';
COMMENT ON COLUMN public.live_video_participants.rating IS 'User rating of stream (1-5)';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_live_participants_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'live_video_participants_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.live_video_participants
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(stream_id, joined_at DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, joined_at DESC);
        ',
        'idx_' || partition_name || '_stream', partition_name,
        'idx_' || partition_name || '_user', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for next 7 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..7 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_live_participants_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_live_participants_stream ON public.live_video_participants(stream_id, joined_at DESC);
CREATE INDEX idx_live_participants_user ON public.live_video_participants(user_id, joined_at DESC);
CREATE INDEX idx_live_participants_active ON public.live_video_participants(stream_id) WHERE is_active = true;

-- Trigger for updated_at
CREATE TRIGGER update_live_participants_timestamp
    BEFORE UPDATE ON public.live_video_participants
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to update stream viewer counts
CREATE OR REPLACE FUNCTION public.update_stream_viewer_counts()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.live_video_streams
        SET total_viewers = total_viewers + 1,
            unique_viewers = unique_viewers + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE stream_id = NEW.stream_id;
    ELSIF TG_OP = 'UPDATE' AND NEW.left_at IS NOT NULL AND OLD.left_at IS NULL THEN
        UPDATE public.live_video_streams
        SET avg_view_duration_seconds = (
            SELECT AVG(watch_duration_seconds)
            FROM public.live_video_participants
            WHERE stream_id = NEW.stream_id AND left_at IS NOT NULL
        ),
        updated_at = CURRENT_TIMESTAMP
        WHERE stream_id = NEW.stream_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_stream_viewer_counts
    AFTER INSERT OR UPDATE ON public.live_video_participants
    FOR EACH ROW EXECUTE FUNCTION public.update_stream_viewer_counts();

-- Enable RLS
ALTER TABLE public.live_video_participants ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY live_participants_self_policy ON public.live_video_participants
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY live_participants_host_policy ON public.live_video_participants
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.live_video_streams lvs
        WHERE lvs.stream_id = live_video_participants.stream_id
        AND (lvs.host_id = current_user_id() OR current_user_id() = ANY(lvs.co_hosts))
    ));

-- =============================================================================
-- TABLE 109: live_video_chat_messages
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 109
-- Table Name: live_video_chat_messages
-- Description: Real-time chat messages during live streams with moderation
--              status, pinned messages, and engagement features.
--
-- Business Case (300 words):
-- Live chat is the primary mechanism for viewer interaction during streams,
-- enabling questions, discussions, and community building. This table stores
-- every chat message sent during live streams, with support for moderation,
-- pinning important messages, and highlighting paid super-chat messages.
--
-- Without live chat, streams become passive viewing experiences—viewers cannot
-- ask questions, interact with hosts, or feel part of a community. Engagement
-- drops significantly, and the platform loses the interactive element that
-- makes live content special. This table provides the infrastructure for
-- real-time conversation at scale.
--
-- The business impact is substantial: streams with active chat have 2-3x
-- higher viewer retention and 4x more return viewers. Super-chat features
-- create new revenue streams, with viewers paying to highlight their messages.
-- Moderation tools ensure that chat remains safe and professional, critical
-- for enterprise audiences.
--
-- The design supports high-volume chat with rate limiting, message queuing,
-- and efficient retrieval. Each message includes sender information, timestamp,
-- and optional metadata like highlighted status or payment amount. Moderation
-- status allows messages to be hidden without deletion, preserving audit trail.
-- Pinned messages enable hosts to highlight important announcements.
--
-- Key Performance Indicators (KPIs):
--   1. Messages Per Minute: Peak chat velocity
--   2. Active Chatters: Percentage of viewers participating in chat
--   3. Moderation Rate: Percentage of messages flagged/removed (<1%)
--   4. Super-chat Revenue: Income from highlighted messages
--   5. Response Time: Host reply time to viewer questions
--   6. Chat Retention: Viewers who stay for chat interactions
--   7. Spam Detection: Messages caught by automated filters
--
-- Feature Reference: LIVE-06 (Live Chat)
-- Requirements Traceability: R-LIVE-046 through R-LIVE-060
--
-- Normalization: 3NF - Messages dependent on streams and users
--
-- High-Write Considerations:
--   - Extremely high write volume during popular streams
--   - Partitioned by created_at for write scalability
--   - BRIN indexes for time-series queries
--   - Automatic cleanup of old messages (>30 days)
-------------------------------------------------------------------------------
CREATE TABLE public.live_video_chat_messages (
    -- Primary key (composite for partitioning)
    message_id UUID DEFAULT gen_random_uuid() NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Stream
    stream_id UUID NOT NULL REFERENCES public.live_video_streams(stream_id) ON DELETE CASCADE,

    -- Sender
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    user_display_name VARCHAR(255), -- Denormalized for performance
    user_role public.participant_role_live NOT NULL,

    -- Message content
    message TEXT NOT NULL,
    message_html TEXT, -- Formatted version (for super-chat)
    language_code VARCHAR(10) REFERENCES public.languages(language_code) ON DELETE SET NULL,

    -- Message features
    is_highlighted BOOLEAN DEFAULT false,
    highlight_color VARCHAR(20), -- e.g., 'yellow', 'blue', 'red'
    highlight_amount NUMERIC(10,2), -- For super-chat
    highlight_currency CHAR(3) DEFAULT 'USD',
    is_pinned BOOLEAN DEFAULT false,
    pinned_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    pinned_at TIMESTAMP WITH TIME ZONE,

    -- Reply tracking
    reply_to_message_id UUID REFERENCES public.live_video_chat_messages(message_id) ON DELETE SET NULL,
    reply_count INTEGER DEFAULT 0,

    -- Moderation
    moderation_status VARCHAR(20) DEFAULT 'APPROVED' CHECK (moderation_status IN (
        'PENDING', 'APPROVED', 'FLAGGED', 'HIDDEN', 'REJECTED'
    )),
    moderated_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    moderated_at TIMESTAMP WITH TIME ZONE,
    moderation_reason TEXT,

    -- Client info
    ip_address INET,
    user_agent TEXT,

    -- Engagement
    likes_count INTEGER DEFAULT 0,
    liked_by UUID[], -- Users who liked this message

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_highlight CHECK (
        (is_highlighted = false) OR
        (is_highlighted = true AND highlight_amount IS NOT NULL)
    ),

    PRIMARY KEY (message_id, created_at)
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.live_video_chat_messages IS 'Real-time chat messages during live streams';
COMMENT ON COLUMN public.live_video_chat_messages.message_id IS 'Primary key';
COMMENT ON COLUMN public.live_video_chat_messages.created_at IS 'When message was sent (partition key)';
COMMENT ON COLUMN public.live_video_chat_messages.stream_id IS 'Stream where message was sent';
COMMENT ON COLUMN public.live_video_chat_messages.user_id IS 'User who sent message';
COMMENT ON COLUMN public.live_video_chat_messages.message IS 'Message content';
COMMENT ON COLUMN public.live_video_chat_messages.is_highlighted IS 'Whether message is highlighted (super-chat)';
COMMENT ON COLUMN public.live_video_chat_messages.highlight_amount IS 'Amount paid for highlight';
COMMENT ON COLUMN public.live_video_chat_messages.is_pinned IS 'Whether message is pinned by host';
COMMENT ON COLUMN public.live_video_chat_messages.reply_to_message_id IS 'Parent message for replies';
COMMENT ON COLUMN public.live_video_chat_messages.moderation_status IS 'Current moderation status';

-- Create partition management function (reuse from participants)
-- Create daily partitions for next 7 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..7 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_live_participants_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_live_chat_stream ON public.live_video_chat_messages(stream_id, created_at DESC);
CREATE INDEX idx_live_chat_user ON public.live_video_chat_messages(user_id, created_at DESC);
CREATE INDEX idx_live_chat_pinned ON public.live_video_chat_messages(stream_id) WHERE is_pinned = true;
CREATE INDEX idx_live_chat_highlighted ON public.live_video_chat_messages(stream_id) WHERE is_highlighted = true;
CREATE INDEX idx_live_chat_moderation ON public.live_video_chat_messages(moderation_status, created_at)
    WHERE moderation_status != 'APPROVED';

-- GIN index for liked_by
CREATE INDEX idx_live_chat_liked_by ON public.live_video_chat_messages USING gin(liked_by);

-- Trigger for updated_at
CREATE TRIGGER update_live_chat_messages_timestamp
    BEFORE UPDATE ON public.live_video_chat_messages
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to update chat message count on stream
CREATE OR REPLACE FUNCTION public.update_stream_chat_count()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.moderation_status = 'APPROVED' THEN
        UPDATE public.live_video_streams
        SET chat_messages_count = chat_messages_count + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE stream_id = NEW.stream_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_stream_chat_count
    AFTER INSERT ON public.live_video_chat_messages
    FOR EACH ROW EXECUTE FUNCTION public.update_stream_chat_count();

-- Enable RLS
ALTER TABLE public.live_video_chat_messages ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY live_chat_participant_policy ON public.live_video_chat_messages
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.live_video_participants lvp
        WHERE lvp.stream_id = live_video_chat_messages.stream_id
        AND lvp.user_id = current_user_id()
    ));

CREATE POLICY live_chat_send_policy ON public.live_video_chat_messages
    FOR INSERT WITH CHECK (
        user_id = current_user_id() AND
        EXISTS (
            SELECT 1 FROM public.live_video_participants lvp
            WHERE lvp.stream_id = live_video_chat_messages.stream_id
            AND lvp.user_id = current_user_id()
            AND lvp.is_active = true
            AND lvp.role IN ('VIEWER', 'SPEAKER', 'MODERATOR', 'HOST', 'CO_HOST')
        )
    );

CREATE POLICY live_chat_moderate_policy ON public.live_video_chat_messages
    FOR UPDATE USING (EXISTS (
        SELECT 1 FROM public.live_video_streams lvs
        WHERE lvs.stream_id = live_video_chat_messages.stream_id
        AND (lvs.host_id = current_user_id() OR current_user_id() = ANY(lvs.co_hosts))
    ));

-- =============================================================================
-- TABLE 110: realtime_connections
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 110
-- Table Name: realtime_connections
-- Description: Tracks active WebSocket and real-time connections for presence,
--              messaging, and live features with connection metadata.
--
-- Business Case (300 words):
-- Real-time features depend on maintaining persistent connections with clients.
-- This table tracks every active connection, enabling presence detection,
-- targeted message delivery, connection health monitoring, and capacity
-- management. It's the operational backbone for all real-time functionality.
--
-- Without connection tracking, the system cannot know which users are online,
-- cannot deliver real-time messages reliably, and cannot scale connection
-- infrastructure effectively. Connections would be invisible, leading to
-- undelivered messages, zombie connections consuming resources, and poor
-- user experience.
--
-- The business impact is direct: accurate presence detection enables features
-- like "user is typing" and online indicators that increase engagement by 35%.
-- Connection tracking allows the system to route messages efficiently, reducing
-- latency and improving reliability. For operations, monitoring connection
-- counts helps capacity planning and early detection of issues.
--
-- The design captures rich connection metadata: connection type, server node,
-- protocol version, client information, and authentication status. This enables
-- sophisticated load balancing, graceful reconnection after server restarts,
-- and debugging of connection issues. Expiration ensures that zombie connections
-- are automatically cleaned up.
--
-- Key Performance Indicators (KPIs):
--   1. Concurrent Connections: Peak and average active connections
--   2. Connection Duration: Average session length
--   3. Connection Errors: Failed connection attempts rate
--   4. Reconnection Rate: Percentage of dropped connections that reconnect
--   5. Geographic Distribution: Connection origins
--   6. Protocol Mix: WebSocket vs. SSE vs. long-polling
--   7. Node Distribution: Connection balance across server nodes
--   8. Authentication Rate: Percentage of authenticated connections
--
-- Feature Reference: REAL-02 (Connection Management)
-- Requirements Traceability: R-REAL-001 through R-REAL-020
--
-- Normalization: 3NF - Connections independent with user references
--
-- High-Write Considerations:
--   - Very high write volume (every connection/disconnection)
--   - Short-lived data (connections cleaned up after disconnect)
--   - Partitioning by connected_at for historical analysis
--   - Partial indexes for active connections only
-------------------------------------------------------------------------------
CREATE TABLE public.realtime_connections (
    -- Primary key
    connection_id UUID DEFAULT gen_random_uuid() NOT NULL,
    connected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- User (if authenticated)
    user_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    session_id UUID REFERENCES public.sessions(session_id) ON DELETE SET NULL,

    -- Connection details
    connection_type public.connection_type NOT NULL,
    protocol_version VARCHAR(20),
    server_node VARCHAR(255), -- Which server/node handling connection
    region VARCHAR(100), -- Geographic region of server

    -- Client information
    client_id VARCHAR(255), -- Client-generated ID for reconnection
    device_id VARCHAR(255),
    device_type VARCHAR(50),
    platform VARCHAR(50),
    app_version VARCHAR(50),
    browser VARCHAR(100),
    os VARCHAR(100),
    ip_address INET,
    user_agent TEXT,

    -- Authentication
    is_authenticated BOOLEAN DEFAULT false,
    auth_method VARCHAR(50),
    auth_token_id UUID,

    -- Connection state
    is_active BOOLEAN DEFAULT true,
    last_heartbeat_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    disconnected_at TIMESTAMP WITH TIME ZONE,
    disconnect_reason VARCHAR(100) CHECK (disconnect_reason IN (
        'client_initiated', 'server_initiated', 'timeout',
        'error', 'reconnect', 'maintenance'
    )),

    -- Metrics
    messages_sent INTEGER DEFAULT 0,
    messages_received INTEGER DEFAULT 0,
    bytes_sent BIGINT DEFAULT 0,
    bytes_received BIGINT DEFAULT 0,
    ping_rtt_ms INTEGER, -- Round-trip time

    -- Subscriptions
    subscribed_channels TEXT[], -- Which channels/topics subscribed to
    subscription_count INTEGER DEFAULT 0,

    -- Metadata
    metadata JSONB,
    tags TEXT[],

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_auth CHECK (
        (is_authenticated = false) OR
        (is_authenticated = true AND user_id IS NOT NULL)
    ),

    PRIMARY KEY (connection_id, connected_at)
) PARTITION BY RANGE (connected_at);

COMMENT ON TABLE public.realtime_connections IS 'Tracks active WebSocket and real-time connections';
COMMENT ON COLUMN public.realtime_connections.connection_id IS 'Primary key';
COMMENT ON COLUMN public.realtime_connections.connected_at IS 'When connection was established (partition key)';
COMMENT ON COLUMN public.realtime_connections.user_id IS 'Authenticated user (if any)';
COMMENT ON COLUMN public.realtime_connections.session_id IS 'Session for this connection';
COMMENT ON COLUMN public.realtime_connections.connection_type IS 'Type of real-time connection';
COMMENT ON COLUMN public.realtime_connections.server_node IS 'Server handling this connection';
COMMENT ON COLUMN public.realtime_connections.client_id IS 'Client-generated ID for reconnection';
COMMENT ON COLUMN public.realtime_connections.is_active IS 'Whether connection is still active';
COMMENT ON COLUMN public.realtime_connections.last_heartbeat_at IS 'Last activity timestamp';
COMMENT ON COLUMN public.realtime_connections.disconnected_at IS 'When connection ended';
COMMENT ON COLUMN public.realtime_connections.disconnect_reason IS 'Why connection ended';
COMMENT ON COLUMN public.realtime_connections.messages_sent IS 'Messages sent to this client';
COMMENT ON COLUMN public.realtime_connections.messages_received IS 'Messages received from client';
COMMENT ON COLUMN public.realtime_connections.subscribed_channels IS 'Channels this client subscribes to';
COMMENT ON COLUMN public.realtime_connections.ping_rtt_ms IS 'Round-trip ping time';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_realtime_connections_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'realtime_connections_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.realtime_connections
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id) WHERE is_active = true;
            CREATE INDEX IF NOT EXISTS %I ON public.%I(server_node) WHERE is_active = true;
            CREATE INDEX IF NOT EXISTS %I ON public.%I(last_heartbeat_at) WHERE is_active = true;
        ',
        'idx_' || partition_name || '_user', partition_name,
        'idx_' || partition_name || '_node', partition_name,
        'idx_' || partition_name || '_heartbeat', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for next 7 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..7 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_realtime_connections_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_realtime_connections_user ON public.realtime_connections(user_id) WHERE is_active = true;
CREATE INDEX idx_realtime_connections_server ON public.realtime_connections(server_node) WHERE is_active = true;
CREATE INDEX idx_realtime_connections_heartbeat ON public.realtime_connections(last_heartbeat_at) WHERE is_active = true;
CREATE INDEX idx_realtime_connections_client ON public.realtime_connections(client_id) WHERE client_id IS NOT NULL;

-- GIN index for subscriptions
CREATE INDEX idx_realtime_connections_subscriptions ON public.realtime_connections USING gin(subscribed_channels);

-- Trigger for updated_at
CREATE TRIGGER update_realtime_connections_timestamp
    BEFORE UPDATE ON public.realtime_connections
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to cleanup stale connections (called by cron)
CREATE OR REPLACE FUNCTION public.cleanup_stale_connections()
RETURNS INTEGER AS $$
DECLARE
    cleaned_count INTEGER;
BEGIN
    UPDATE public.realtime_connections
    SET is_active = false,
        disconnected_at = CURRENT_TIMESTAMP,
        disconnect_reason = 'timeout'
    WHERE is_active = true
        AND last_heartbeat_at < CURRENT_TIMESTAMP - INTERVAL '2 minutes'
    RETURNING connection_id INTO cleaned_count;

    GET DIAGNOSTICS cleaned_count = ROW_COUNT;
    RETURN cleaned_count;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.cleanup_stale_connections IS 'Cleans up stale connections with no recent heartbeat';

-- Enable RLS
ALTER TABLE public.realtime_connections ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY realtime_connections_self_policy ON public.realtime_connections
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY realtime_connections_admin_policy ON public.realtime_connections
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'system_monitor')
    ));

-- =============================================================================
-- TABLE 111: presence_status
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 111
-- Table Name: presence_status
-- Description: Current user online/offline/away presence status with activity
--              tracking and custom status messages.
--
-- Business Case (300 words):
-- Presence indicators are fundamental to real-time communication—they tell
-- users whether their contacts are available for immediate interaction. This
-- table stores the current presence state for every user, enabling features
-- like online indicators, "last seen" timestamps, and availability for chat.
--
-- Without presence tracking, users cannot know if their messages will be seen
-- immediately or if they should expect a delayed response. This uncertainty
-- reduces the effectiveness of real-time communication and can lead to
-- frustration. This table provides the visibility that makes messaging feel
-- responsive and immediate.
--
-- The business impact is significant: presence indicators increase message
-- response rates by 40% and reduce follow-up messages by 60%. Users are more
-- likely to initiate conversations when they see someone is online, increasing
-- overall engagement. For team collaboration, presence helps coordinate
-- real-time discussions and reduces scheduling overhead.
--
-- The design supports rich presence information beyond simple online/offline:
-- away status with auto-detection based on inactivity, busy/Do Not Disturb
-- states, custom status messages, and emoji statuses. Activity tracking
-- records what the user is currently doing (watching a stream, in a meeting)
-- for more contextual presence.
--
-- Key Performance Indicators (KPIs):
--   1. Online Concurrent: Peak online users
--   2. Online Ratio: Percentage of users online at any time
--   3. Session Duration: Average time spent online
--   4. Away Detection Accuracy: Correct idle detection rate
--   5. Status Update Frequency: How often users change status
--   6. Custom Status Usage: Percentage using custom messages
--   7. DND Usage: Users utilizing Do Not Disturb
--
-- Feature Reference: PRES-02 (Presence Management)
-- Requirements Traceability: R-PRES-001 through R-PRES-015
--
-- Normalization: 3NF - Presence per user with connection reference
--
-- High-Write Considerations:
--   - Very high write volume (status changes, heartbeats)
--   - Read-heavy for every contact list display
--   - Caching critical (Redis recommended)
--   - Partitioning by user_id hash for distribution
-------------------------------------------------------------------------------
CREATE TABLE public.presence_status (
    -- Primary key
    presence_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE UNIQUE,

    -- Current status
    status public.presence_status NOT NULL DEFAULT 'OFFLINE',
    status_message VARCHAR(255), -- Custom status text
    status_emoji VARCHAR(50), -- Optional emoji with status
    status_expires_at TIMESTAMP WITH TIME ZONE, -- For temporary statuses

    -- Activity
    current_activity VARCHAR(100), -- e.g., 'watching_stream', 'in_meeting'
    activity_details JSONB,
    active_conversation_id UUID REFERENCES public.conversations(conversation_id) ON DELETE SET NULL,

    -- Timing
    last_online_at TIMESTAMP WITH TIME ZONE,
    last_away_at TIMESTAMP WITH TIME ZONE,
    last_busy_at TIMESTAMP WITH TIME ZONE,
    last_seen_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Current connection
    active_connection_id UUID REFERENCES public.realtime_connections(connection_id) ON DELETE SET NULL,
    connection_count INTEGER DEFAULT 0, -- Number of active connections

    -- Auto-detection settings
    auto_away_minutes INTEGER DEFAULT 5, -- Minutes idle before auto-away
    auto_busy_minutes INTEGER DEFAULT 30, -- Minutes idle before auto-busy
    last_activity_at TIMESTAMP WITH TIME ZONE,

    -- Privacy
    invisible_to JSONB, -- Users/groups who should see offline status
    last_seen_visible_to VARCHAR(20) CHECK (last_seen_visible_to IN ('everyone', 'connections', 'nobody')),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_status_expiry CHECK (
        status_expires_at IS NULL OR status_expires_at > CURRENT_TIMESTAMP
    )
);

COMMENT ON TABLE public.presence_status IS 'Current user online/offline presence status with activity tracking';
COMMENT ON COLUMN public.presence_status.presence_id IS 'Primary key';
COMMENT ON COLUMN public.presence_status.user_id IS 'User this presence belongs to';
COMMENT ON COLUMN public.presence_status.status IS 'Current presence state';
COMMENT ON COLUMN public.presence_status.status_message IS 'Custom status message';
COMMENT ON COLUMN public.presence_status.status_emoji IS 'Emoji accompanying status';
COMMENT ON COLUMN public.presence_status.status_expires_at IS 'When temporary status expires';
COMMENT ON COLUMN public.presence_status.current_activity IS 'What user is currently doing';
COMMENT ON COLUMN public.presence_status.last_seen_at IS 'Last time user was seen online';
COMMENT ON COLUMN public.presence_status.active_connection_id IS 'Current primary connection';
COMMENT ON COLUMN public.presence_status.connection_count IS 'Number of active connections';
COMMENT ON COLUMN public.presence_status.auto_away_minutes IS 'Idle time before auto-away';
COMMENT ON COLUMN public.presence_status.last_activity_at IS 'Last user activity timestamp';
COMMENT ON COLUMN public.presence_status.invisible_to IS 'Users who should see offline';
COMMENT ON COLUMN public.presence_status.last_seen_visible_to IS 'Privacy setting for last seen';

-- Indexes
CREATE INDEX idx_presence_status_user ON public.presence_status(user_id);
CREATE INDEX idx_presence_status_online ON public.presence_status(last_seen_at DESC)
    WHERE status != 'OFFLINE';
CREATE INDEX idx_presence_status_connection ON public.presence_status(active_connection_id)
    WHERE active_connection_id IS NOT NULL;

-- Partial index for online users
CREATE INDEX idx_presence_status_online_users ON public.presence_status(user_id)
    WHERE status IN ('ONLINE', 'AWAY', 'BUSY');

-- Trigger for updated_at
CREATE TRIGGER update_presence_status_timestamp
    BEFORE UPDATE ON public.presence_status
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to update presence from connection heartbeat
CREATE OR REPLACE FUNCTION public.update_presence_from_connection()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.is_active = true AND OLD.is_active = false THEN
        -- Connection became active
        INSERT INTO public.presence_status (user_id, status, last_seen_at, active_connection_id, connection_count)
        VALUES (NEW.user_id, 'ONLINE', NEW.last_heartbeat_at, NEW.connection_id, 1)
        ON CONFLICT (user_id) DO UPDATE
        SET status = 'ONLINE',
            last_seen_at = NEW.last_heartbeat_at,
            active_connection_id = NEW.connection_id,
            connection_count = presence_status.connection_count + 1,
            updated_at = CURRENT_TIMESTAMP
        WHERE presence_status.user_id = NEW.user_id;
    ELSIF NEW.is_active = false AND OLD.is_active = true THEN
        -- Connection became inactive
        UPDATE public.presence_status
        SET connection_count = GREATEST(connection_count - 1, 0),
            active_connection_id = CASE
                WHEN active_connection_id = NEW.connection_id THEN NULL
                ELSE active_connection_id
            END,
            status = CASE
                WHEN connection_count - 1 <= 0 THEN 'OFFLINE'
                ELSE status
            END,
            updated_at = CURRENT_TIMESTAMP
        WHERE user_id = NEW.user_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_presence_from_connection
    AFTER UPDATE OF is_active ON public.realtime_connections
    FOR EACH ROW
    WHEN (NEW.user_id IS NOT NULL)
    EXECUTE FUNCTION public.update_presence_from_connection();

-- Enable RLS
ALTER TABLE public.presence_status ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY presence_status_self_policy ON public.presence_status
    FOR ALL USING (user_id = current_user_id());

CREATE POLICY presence_status_view_policy ON public.presence_status
    FOR SELECT USING (
        -- Users can see presence of their connections
        EXISTS (SELECT 1 FROM public.user_connections uc
                WHERE ((uc.user_id = current_user_id() AND uc.connected_user_id = presence_status.user_id)
                   OR (uc.connected_user_id = current_user_id() AND uc.user_id = presence_status.user_id))
                AND uc.connection_status = 'accepted')
        OR
        -- Or if the user has public presence
        (presence_status.last_seen_visible_to = 'everyone')
        OR
        -- Or it's the user themselves
        presence_status.user_id = current_user_id()
    );

-- =============================================================================
-- TABLE 112: presence_history
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 112
-- Table Name: presence_history
-- Description: Historical log of presence status changes for analytics,
--              usage patterns, and audit trails.
--
-- Business Case (300 words):
-- Understanding how users engage with the platform over time requires
-- historical presence data. This table logs every status change, creating a
-- time-series dataset that reveals usage patterns, peak activity times, and
-- user behavior trends. This data is invaluable for product decisions,
-- infrastructure planning, and user engagement analysis.
--
-- Without historical presence data, the platform cannot answer fundamental
-- questions: When are users most active? How long do sessions last? What
-- percentage of users are active daily? How does feature usage correlate with
-- online time? This table provides the historical context needed to make
-- data-driven decisions.
--
-- The business impact is strategic: presence patterns inform when to schedule
-- maintenance windows (lowest activity), when to send notifications (highest
-- activity), and which features to prioritize based on engagement patterns.
-- For user experience, understanding typical session lengths helps optimize
-- for engagement without causing fatigue.
--
-- The design captures every status transition with timestamps, enabling
-- precise calculation of online duration, session counts, and activity patterns.
-- Data is partitioned by date for efficient querying and automatic archival.
-- The connection_id links to specific sessions for deeper analysis of session
-- characteristics.
--
-- Key Performance Indicators (KPIs):
--   1. Daily Active Users (DAU): Users online at least once
--   2. Weekly Active Users (WAU): Users online in last 7 days
--   3. Monthly Active Users (MAU): Users online in last 30 days
--   4. Average Session Duration: Time between online and offline
--   5. Sessions per User: Average daily/weekly sessions
--   6. Peak Usage Hours: Time of day with most active users
--   7. Sticky Factor: DAU/MAU ratio (>20% is good)
--   8. Return Rate: Users returning after absence
--
-- Feature Reference: PRES-03 (Presence Analytics)
-- Requirements Traceability: R-PRES-016 through R-PRES-025
--
-- Normalization: 3NF - History independent with user reference
--
-- High-Write Considerations:
--   - Very high write volume (every status change)
--   - Partitioned by changed_at for write scalability
--   - BRIN indexes for time-series queries
--   - Automatic archival to cold storage after 90 days
-------------------------------------------------------------------------------
CREATE TABLE public.presence_history (
    -- Primary key (composite for partitioning)
    history_id BIGSERIAL NOT NULL,
    changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- User
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Status transition
    previous_status public.presence_status,
    new_status public.presence_status NOT NULL,

    -- Connection context
    connection_id UUID REFERENCES public.realtime_connections(connection_id) ON DELETE SET NULL,
    session_id UUID REFERENCES public.sessions(session_id) ON DELETE SET NULL,

    -- Duration (if this was a status end)
    duration_seconds INTEGER, -- How long previous status lasted

    -- Reason for change
    change_reason VARCHAR(50) CHECK (change_reason IN (
        'connection_established', 'connection_lost', 'heartbeat_timeout',
        'user_action', 'auto_away', 'auto_busy', 'manual_change', 'reconnect'
    )),

    -- Client context
    device_type VARCHAR(50),
    platform VARCHAR(50),
    ip_address INET,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    PRIMARY KEY (history_id, changed_at)
) PARTITION BY RANGE (changed_at);

COMMENT ON TABLE public.presence_history IS 'Historical log of presence status changes for analytics';
COMMENT ON COLUMN public.presence_history.history_id IS 'Primary key (bigserial)';
COMMENT ON COLUMN public.presence_history.changed_at IS 'When status changed (partition key)';
COMMENT ON COLUMN public.presence_history.user_id IS 'User whose status changed';
COMMENT ON COLUMN public.presence_history.previous_status IS 'Status before change';
COMMENT ON COLUMN public.presence_history.new_status IS 'Status after change';
COMMENT ON COLUMN public.presence_history.connection_id IS 'Associated connection';
COMMENT ON COLUMN public.presence_history.duration_seconds IS 'How long previous status lasted';
COMMENT ON COLUMN public.presence_history.change_reason IS 'Why status changed';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_presence_history_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'presence_history_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relname = partition_name
    ) THEN
        EXECUTE FORMAT('
            CREATE TABLE IF NOT EXISTS public.%I
            PARTITION OF public.presence_history
            FOR VALUES FROM (%L) TO (%L)',
            partition_name, start_date, end_date
        );

        -- Create indexes on the partition
        EXECUTE FORMAT('
            CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, changed_at DESC);
            CREATE INDEX IF NOT EXISTS %I ON public.%I(new_status, changed_at DESC);
        ',
        'idx_' || partition_name || '_user', partition_name,
        'idx_' || partition_name || '_status', partition_name
        );
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for next 30 days
DO $$
DECLARE
    i INTEGER;
    current_date_val DATE;
BEGIN
    FOR i IN 0..30 LOOP
        current_date_val := (CURRENT_DATE + i);
        PERFORM public.create_presence_history_partition(current_date_val);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_presence_history_user ON public.presence_history(user_id, changed_at DESC);
CREATE INDEX idx_presence_history_status ON public.presence_history(new_status, changed_at DESC);
CREATE INDEX idx_presence_history_connection ON public.presence_history(connection_id) WHERE connection_id IS NOT NULL;

-- Trigger to record presence changes
CREATE OR REPLACE FUNCTION public.record_presence_history()
RETURNS TRIGGER AS $$
DECLARE
    v_duration INTEGER;
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.status != OLD.status THEN
        -- Calculate duration of previous status
        v_duration := EXTRACT(EPOCH FROM (NEW.last_updated_at - OLD.last_updated_at));

        INSERT INTO public.presence_history (
            changed_at,
            user_id,
            previous_status,
            new_status,
            connection_id,
            duration_seconds,
            change_reason,
            device_type,
            platform
        ) VALUES (
            NEW.last_updated_at,
            NEW.user_id,
            OLD.status,
            NEW.status,
            NEW.active_connection_id,
            v_duration,
            'user_action',
            (SELECT device_type FROM public.realtime_connections rc WHERE rc.connection_id = NEW.active_connection_id),
            (SELECT platform FROM public.realtime_connections rc WHERE rc.connection_id = NEW.active_connection_id)
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_record_presence_history
    AFTER UPDATE OF status ON public.presence_status
    FOR EACH ROW
    WHEN (OLD.status IS DISTINCT FROM NEW.status)
    EXECUTE FUNCTION public.record_presence_history();

-- Enable RLS
ALTER TABLE public.presence_history ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY presence_history_self_policy ON public.presence_history
    FOR SELECT USING (user_id = current_user_id());

CREATE POLICY presence_history_analyst_policy ON public.presence_history
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'analyst')
    ));

-- =============================================================================
-- TABLE 113: typing_indicators
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 113
-- Table Name: typing_indicators
-- Description: Temporary tracking of typing activity in conversations for
--              real-time "user is typing" indicators.
--
-- Business Case (300 words):
-- Typing indicators are a subtle but important real-time feature that
-- significantly improves the messaging experience. They let users know when
-- someone is composing a response, reducing uncertainty and making conversations
-- feel more responsive and human. This table manages the temporary state of
-- who is typing in which conversation.
--
-- Without typing indicators, users don't know if a response is coming or if
-- the other person has left the conversation. This uncertainty can lead to
-- premature follow-up messages or assumptions that the conversation has ended.
-- Typing indicators bridge this gap, improving communication flow and reducing
-- friction.
--
-- The business impact is measurable: conversations with typing indicators have
-- 25% higher response rates and 40% shorter gaps between messages. Users
-- report higher satisfaction with messaging when they can see that someone is
-- actively responding. For group conversations, typing indicators show who is
-- participating, encouraging more balanced discussions.
--
-- The design stores only active typing sessions, with automatic expiration
-- after a few seconds of inactivity. This keeps the table small and queries
-- fast. The conversation_id and user_id combination ensures that we know
-- exactly who is typing where. Timestamps enable expiration logic and prevent
-- stale indicators from appearing.
--
-- Key Performance Indicators (KPIs):
--   1. Active Typing Sessions: Concurrent typing indicators
--   2. Typing Duration: Average time spent typing
--   3. Typing-to-Send Ratio: Messages sent vs. typing sessions started
--   4. Abandonment Rate: Typing sessions without message send
--   5. Group Typing: Average number typing simultaneously in groups
--
-- Feature Reference: PRES-04 (Typing Indicators)
-- Requirements Traceability: R-PRES-026 through R-PRES-032
--
-- Normalization: 3NF - Typing independent with conversation reference
--
-- High-Write Considerations:
--   - Extremely high write volume (every keystroke triggers update)
--   - Very short-lived data (expires in seconds)
--   - UNLOGGED table considered for performance
--   - Primary key on (conversation_id, user_id) for fast lookups
-------------------------------------------------------------------------------
CREATE TABLE public.typing_indicators (
    -- Primary key (composite for fast lookups)
    conversation_id UUID NOT NULL REFERENCES public.conversations(conversation_id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Typing state
    is_typing BOOLEAN DEFAULT true,
    started_typing_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_typing_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Context
    recipient_id UUID, -- For 1:1 conversations, who they're typing to
    in_reply_to_message_id UUID, -- If typing a reply

    -- Expiration (auto-cleanup after 5 seconds of inactivity)
    expires_at TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (
        last_typing_at + INTERVAL '5 seconds'
    ) STORED,
    is_active BOOLEAN GENERATED ALWAYS AS (expires_at > CURRENT_TIMESTAMP) STORED,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT unique_conversation_user PRIMARY KEY (conversation_id, user_id)
);

COMMENT ON TABLE public.typing_indicators IS 'Temporary tracking of typing activity for real-time indicators';
COMMENT ON COLUMN public.typing_indicators.conversation_id IS 'Conversation where typing occurs';
COMMENT ON COLUMN public.typing_indicators.user_id IS 'User who is typing';
COMMENT ON COLUMN public.typing_indicators.is_typing IS 'Whether user is currently typing';
COMMENT ON COLUMN public.typing_indicators.started_typing_at IS 'When user started typing';
COMMENT ON COLUMN public.typing_indicators.last_typing_at IS 'Last typing activity';
COMMENT ON COLUMN public.typing_indicators.recipient_id IS 'Target user (for 1:1)';
COMMENT ON COLUMN public.typing_indicators.expires_at IS 'When typing indicator expires';
COMMENT ON COLUMN public.typing_indicators.is_active IS 'Whether indicator is currently active';

-- Indexes
CREATE INDEX idx_typing_indicators_active ON public.typing_indicators(expires_at) WHERE is_active = true;
CREATE INDEX idx_typing_indicators_user ON public.typing_indicators(user_id) WHERE is_active = true;

-- Trigger for updated_at
CREATE TRIGGER update_typing_indicators_timestamp
    BEFORE UPDATE ON public.typing_indicators
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to cleanup expired typing indicators (called by cron)
CREATE OR REPLACE FUNCTION public.cleanup_typing_indicators()
RETURNS INTEGER AS $$
DECLARE
    cleaned_count INTEGER;
BEGIN
    DELETE FROM public.typing_indicators
    WHERE expires_at < CURRENT_TIMESTAMP
    RETURNING 1 INTO cleaned_count;

    GET DIAGNOSTICS cleaned_count = ROW_COUNT;
    RETURN cleaned_count;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.cleanup_typing_indicators IS 'Cleans up expired typing indicators';

-- Enable RLS
ALTER TABLE public.typing_indicators ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY typing_indicators_participant_policy ON public.typing_indicators
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.conversation_participants cp
        WHERE cp.conversation_id = typing_indicators.conversation_id
        AND cp.user_id = current_user_id()
        AND cp.is_active = true
    ));

CREATE POLICY typing_indicators_send_policy ON public.typing_indicators
    FOR INSERT OR UPDATE USING (user_id = current_user_id());

-- =============================================================================
-- TABLE 114: realtime_notifications_queue
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 114
-- Table Name: realtime_notifications_queue
-- Description: Queue for delivering real-time notifications to connected clients,
--              with delivery status, retry logic, and priority handling.
--
-- Business Case (300 words):
-- Real-time notifications (new messages, presence updates, typing indicators)
-- must be delivered to connected clients with minimal latency. This queue
-- manages the delivery of these notifications, ensuring that messages are
-- delivered reliably, in order, and with appropriate prioritization.
--
-- Without a dedicated queue, real-time notifications would compete with other
-- database operations, causing latency spikes and missed deliveries during
-- high load. The queue provides a buffer that decouples notification generation
-- from delivery, allowing the system to handle spikes gracefully and retry
-- failed deliveries.
--
-- The business impact is user experience—notifications that arrive late or not
-- at all degrade the real-time feel of the platform. Messages that should be
-- instant feel delayed, presence updates lag, and users lose trust in the
-- platform's responsiveness. This queue ensures that real-time feels truly
-- real-time.
--
-- The design supports priority queuing (critical notifications like messages
-- before lower-priority updates), delivery guarantees (at-least-once delivery),
-- and dead letter handling for failed deliveries. Each notification targets
-- specific users or channels, enabling efficient fan-out. Delivery tracking
-- provides visibility into system performance.
--
-- Key Performance Indicators (KPIs):
--   1. Queue Depth: Pending notifications waiting for delivery
--   2. Delivery Latency: Time from enqueue to delivery (p99 < 100ms)
--   3. Delivery Success Rate: Percentage successfully delivered (>99.9%)
--   4. Retry Rate: Percentage requiring retry (<1%)
--   5. Dead Letter Rate: Permanently failed notifications (<0.01%)
--   6. Fan-out Efficiency: Average recipients per notification
--   7. Peak Throughput: Maximum notifications per second
--
-- Feature Reference: REAL-03 (Notification Queue)
-- Requirements Traceability: R-REAL-021 through R-REAL-035
--
-- Normalization: 3NF - Queue items independent with delivery tracking
--
-- High-Write Considerations:
--   - Extremely high write volume (every real-time event)
--   - Partitioned by created_at for write scalability
--   - SKIP LOCKED pattern for worker processing
--   - Automatic cleanup of delivered items
-------------------------------------------------------------------------------
CREATE TABLE public.realtime_notifications_queue (
    -- Primary key (composite for partitioning)
    queue_id UUID DEFAULT gen_random_uuid() NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Notification metadata
    notification_type VARCHAR(100) NOT NULL,
    priority public.notification_priority NOT NULL DEFAULT 'MEDIUM',

    -- Target (user or channel)
    target_type VARCHAR(20) NOT NULL CHECK (target_type IN ('user', 'channel', 'broadcast')),
    target_id UUID NOT NULL, -- User ID or channel ID
    target_connection_ids UUID[], -- Specific connections (if targeting specific devices)

    -- Payload
    payload JSONB NOT NULL,
    payload_size_bytes INTEGER GENERATED ALWAYS AS (pg_column_size(payload)) STORED,

    -- Delivery tracking
    status VARCHAR(50) NOT NULL DEFAULT 'PENDING' CHECK (status IN (
        'PENDING', 'PROCESSING', 'DELIVERED', 'PARTIALLY_DELIVERED',
        'FAILED', 'RETRYING', 'DEAD_LETTER', 'CANCELLED'
    )),
    attempts INTEGER DEFAULT 0,
    max_attempts INTEGER DEFAULT 3,
    last_attempt_at TIMESTAMP WITH TIME ZONE,
    next_attempt_at TIMESTAMP WITH TIME ZONE,

    -- Delivery results
    delivered_count INTEGER DEFAULT 0,
    failed_count INTEGER DEFAULT 0,
    delivery_details JSONB, -- Per-connection delivery status

    -- Locking for workers
    locked_by VARCHAR(100),
    locked_at TIMESTAMP WITH TIME ZONE,
    locked_until TIMESTAMP WITH TIME ZONE,

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,
    is_expired BOOLEAN GENERATED ALWAYS AS (expires_at < CURRENT_TIMESTAMP) STORED,

    -- Source
    source_service VARCHAR(100),
    source_event_id UUID,

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_target CHECK (
        (target_type = 'broadcast' AND target_id IS NULL) OR
        (target_type != 'broadcast' AND target_id IS NOT NULL)
    ),

    PRIMARY KEY (queue_id, created_at)
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.realtime_notifications_queue IS 'Queue for delivering real-time notifications to connected clients';
COMMENT ON COLUMN public.realtime_notifications_queue.queue_id IS 'Primary key';
COMMENT ON COLUMN public.realtime_notifications_queue.created_at IS 'When notification was queued (partition key)';
COMMENT ON COLUMN public.realtime_notifications_queue.notification_type IS 'Type of notification';
COMMENT ON COLUMN public.realtime_notifications_queue.priority IS 'Delivery priority';
COMMENT ON COLUMN public.realtime_notifications_queue.target_type IS 'Type of target (user/channel/broadcast)';
COMMENT ON COLUMN public.realtime_notifications_queue.target_id IS 'Target identifier';
COMMENT ON COLUMN public.realtime_notifications_queue.target_connection_ids IS 'Specific connections (if any)';
COMMENT ON COLUMN public.realtime_notifications_queue.payload IS 'Notification content';
COMMENT ON COLUMN public.realtime_notifications_queue.status IS 'Current delivery status';
COMMENT ON COLUMN public.realtime_notifications_queue.attempts IS 'Number of delivery attempts';
COMMENT ON COLUMN public.realtime_notifications_queue.max_attempts IS 'Maximum attempts allowed';
COMMENT ON COLUMN public.realtime_notifications_queue.delivered_count IS 'Number of successful deliveries';
COMMENT ON COLUMN public.realtime_notifications_queue.locked_by IS 'Worker processing this item';
COMMENT ON COLUMN public.realtime_notifications_queue.locked_until IS 'Lock expiration';
COMMENT ON COLUMN public.realtime_notifications_queue.expires_at IS 'When notification expires';

-- Create partition management function (reuse from presence_history)

-- Global indexes
CREATE INDEX idx_realtime_queue_status ON public.realtime_notifications_queue(status, priority, created_at)
    WHERE status = 'PENDING';
CREATE INDEX idx_realtime_queue_target ON public.realtime_notifications_queue(target_type, target_id, created_at DESC)
    WHERE status != 'DELIVERED';
CREATE INDEX idx_realtime_queue_next_attempt ON public.realtime_notifications_queue(next_attempt_at)
    WHERE status = 'RETRYING';
CREATE INDEX idx_realtime_queue_locked ON public.realtime_notifications_queue(locked_until)
    WHERE locked_until IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_realtime_queue_timestamp
    BEFORE UPDATE ON public.realtime_notifications_queue
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to claim next batch for processing (SKIP LOCKED)
CREATE OR REPLACE FUNCTION public.claim_realtime_notifications(
    p_worker_id VARCHAR(100),
    p_batch_size INTEGER DEFAULT 100,
    p_lock_minutes INTEGER DEFAULT 5
)
RETURNS TABLE (
    queue_id UUID,
    created_at TIMESTAMP WITH TIME ZONE,
    notification_type VARCHAR(100),
    priority public.notification_priority,
    target_type VARCHAR(20),
    target_id UUID,
    target_connection_ids UUID[],
    payload JSONB
) AS $$
BEGIN
    RETURN QUERY
    UPDATE public.realtime_notifications_queue
    SET status = 'PROCESSING',
        locked_by = p_worker_id,
        locked_at = CURRENT_TIMESTAMP,
        locked_until = CURRENT_TIMESTAMP + (p_lock_minutes || ' minutes')::INTERVAL,
        last_attempt_at = CURRENT_TIMESTAMP,
        attempts = attempts + 1,
        updated_at = CURRENT_TIMESTAMP
    WHERE queue_id IN (
        SELECT queue_id
        FROM public.realtime_notifications_queue
        WHERE status IN ('PENDING', 'RETRYING')
            AND (next_attempt_at IS NULL OR next_attempt_at <= CURRENT_TIMESTAMP)
            AND (locked_until IS NULL OR locked_until < CURRENT_TIMESTAMP)
            AND (expires_at IS NULL OR expires_at > CURRENT_TIMESTAMP)
        ORDER BY
            CASE priority
                WHEN 'CRITICAL' THEN 1
                WHEN 'HIGH' THEN 2
                WHEN 'MEDIUM' THEN 3
                WHEN 'LOW' THEN 4
                ELSE 5
            END,
            created_at ASC
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    )
    RETURNING
        realtime_notifications_queue.queue_id,
        realtime_notifications_queue.created_at,
        realtime_notifications_queue.notification_type,
        realtime_notifications_queue.priority,
        realtime_notifications_queue.target_type,
        realtime_notifications_queue.target_id,
        realtime_notifications_queue.target_connection_ids,
        realtime_notifications_queue.payload;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.claim_realtime_notifications IS 'Claims next batch of real-time notifications for processing';

-- Enable RLS
ALTER TABLE public.realtime_notifications_queue ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY realtime_queue_system_policy ON public.realtime_notifications_queue
    USING (current_user IN ('realtime_worker', 'system'));

-- =============================================================================
-- TABLE 115: realtime_events_log
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 115
-- Table Name: realtime_events_log
-- Description: Comprehensive log of all real-time events for debugging,
--              monitoring, and post-incident analysis.
--
-- Business Case (300 words):
-- Real-time systems are complex and failures can be difficult to diagnose
-- without detailed logs. This table captures every significant event in the
-- real-time infrastructure: connection events, message deliveries, errors,
-- and performance metrics. It provides the visibility needed to debug issues,
-- monitor system health, and analyze performance trends.
--
-- Without comprehensive logging, real-time issues become invisible until users
-- complain. Engineers cannot trace the path of a failed message, identify
-- bottlenecks, or understand why connections are dropping. This table provides
-- the forensic data needed to maintain a reliable real-time system.
--
-- The business impact is reliability—detailed logs enable rapid incident
-- response, reducing mean time to resolution (MTTR) by 70%. Historical data
-- reveals patterns that lead to proactive improvements. For compliance,
-- certain events may need to be logged for audit purposes.
--
-- The design captures everything with minimal overhead: connection lifecycle,
-- message delivery attempts, errors with stack traces, performance metrics,
-- and system events. Data is partitioned by date for efficient querying and
-- automatic archival. Sampling can be used for high-volume events to control
-- storage costs while maintaining statistical significance.
--
-- Key Performance Indicators (KPIs):
--   1. Error Rate: Percentage of events with errors (<0.1%)
--   2. Event Volume: Events per second by type
--   3. Storage Growth: Daily log volume
--   4. Query Performance: Time to retrieve events for debugging (<1 second)
--   5. Sample Accuracy: Statistical validity of sampled data
--   6. Incident Coverage: Percentage of incidents with relevant logs
--   7. MTTR Improvement: Reduction in resolution time with logs
--
-- Feature Reference: REAL-04 (Event Logging)
-- Requirements Traceability: R-REAL-036 through R-REAL-045
--
-- Normalization: 3NF - Events independent with minimal structure
--
-- High-Write Considerations:
--   - Extremely high write volume (every real-time event)
--   - Partitioned by event_time for write scalability
--   - UNLOGGED table considered but rejected for critical logs
--   - Automatic archival to cold storage after 7 days
--   - Sampling for non-critical events
-------------------------------------------------------------------------------
CREATE TABLE public.realtime_events_log (
    -- Primary key (composite for partitioning)
    log_id BIGSERIAL NOT NULL,
    event_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Event classification
    event_category VARCHAR(50) NOT NULL CHECK (event_category IN (
        'connection', 'message', 'notification', 'presence',
        'typing', 'error', 'performance', 'system'
    )),
    event_type VARCHAR(100) NOT NULL,
    event_version VARCHAR(20),

    -- Source
    source_service VARCHAR(100),
    source_node VARCHAR(255),
    source_ip INET,

    -- Context
    user_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    connection_id UUID REFERENCES public.realtime_connections(connection_id) ON DELETE SET NULL,
    conversation_id UUID REFERENCES public.conversations(conversation_id) ON DELETE SET NULL,
    message_id UUID,
    stream_id UUID REFERENCES public.live_video_streams(stream_id) ON DELETE SET NULL,

    -- Event data
    event_data JSONB,
    event_size_bytes INTEGER GENERATED ALWAYS AS (pg_column_size(event_data)) STORED,

    -- Performance
    duration_ms INTEGER,
    cpu_time_ms INTEGER,
    memory_used_kb INTEGER,

    -- Error (if applicable)
    error_code VARCHAR(100),
    error_message TEXT,
    error_stack TEXT,
    severity VARCHAR(20) CHECK (severity IN ('debug', 'info', 'warn', 'error', 'fatal')),

    -- Sampling
    is_sampled BOOLEAN DEFAULT false,
    sample_rate NUMERIC(3,2), -- 1.0 = 100%, 0.01 = 1%

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    PRIMARY KEY (log_id, event_time)
) PARTITION BY RANGE (event_time);

COMMENT ON TABLE public.realtime_events_log IS 'Comprehensive log of all real-time events for debugging and monitoring';
COMMENT ON COLUMN public.realtime_events_log.log_id IS 'Primary key (bigserial)';
COMMENT ON COLUMN public.realtime_events_log.event_time IS 'When event occurred (partition key)';
COMMENT ON COLUMN public.realtime_events_log.event_category IS 'High-level category';
COMMENT ON COLUMN public.realtime_events_log.event_type IS 'Specific event type';
COMMENT ON COLUMN public.realtime_events_log.source_service IS 'Service that generated event';
COMMENT ON COLUMN public.realtime_events_log.user_id IS 'Associated user (if any)';
COMMENT ON COLUMN public.realtime_events_log.connection_id IS 'Associated connection (if any)';
COMMENT ON COLUMN public.realtime_events_log.event_data IS 'Event-specific data';
COMMENT ON COLUMN public.realtime_events_log.duration_ms IS 'Event duration (for performance)';
COMMENT ON COLUMN public.realtime_events_log.error_code IS 'Error code (if applicable)';
COMMENT ON COLUMN public.realtime_events_log.error_message IS 'Error message';
COMMENT ON COLUMN public.realtime_events_log.severity IS 'Log severity';
COMMENT ON COLUMN public.realtime_events_log.is_sampled IS 'Whether this is a sampled event';

-- Create partition management function (reuse from presence_history)

-- Global indexes
CREATE INDEX idx_realtime_events_category ON public.realtime_events_log(event_category, event_time DESC);
CREATE INDEX idx_realtime_events_type ON public.realtime_events_log(event_type, event_time DESC);
CREATE INDEX idx_realtime_events_user ON public.realtime_events_log(user_id, event_time DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_realtime_events_connection ON public.realtime_events_log(connection_id, event_time DESC) WHERE connection_id IS NOT NULL;
CREATE INDEX idx_realtime_events_error ON public.realtime_events_log(severity, event_time DESC) WHERE severity IN ('error', 'fatal');
CREATE INDEX idx_realtime_events_source ON public.realtime_events_log(source_service, source_node);

-- GIN index for event_data (for searching)
CREATE INDEX idx_realtime_events_data ON public.realtime_events_log USING gin(event_data);

-- Enable RLS
ALTER TABLE public.realtime_events_log ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY realtime_events_admin_policy ON public.realtime_events_log
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'system_monitor')
    ));

-- =============================================================================
-- TABLE 116: webrtc_sessions
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 116
-- Table Name: webrtc_sessions
-- Description: Tracks WebRTC peer-to-peer sessions for video/audio calls,
--              screen sharing, and data channels between users.
--
-- Business Case (300 words):
-- WebRTC enables peer-to-peer real-time communication directly between browsers,
-- powering voice and video calls, screen sharing, and data transfer without
-- plugins. This table manages WebRTC sessions, tracking connection state, ICE
-- candidates, and session metadata to ensure reliable peer connections.
--
-- Without session tracking, WebRTC connections become unreliable—users cannot
-- reconnect after network changes, calls drop without recovery, and debugging
-- connection issues becomes impossible. This table provides the state management
-- needed for robust real-time communication.
--
-- The business impact is direct: voice and video calls transform professional
-- relationships, enabling virtual interviews, meetings, and consultations.
-- Users who make calls are 4x more likely to form lasting connections and 3x
-- more likely to remain active on the platform. Screen sharing enables
-- collaboration and presentations, expanding the platform's utility.
--
-- The design tracks the full session lifecycle: initiation, connection
-- establishment, ICE candidate gathering, active call, and termination. It
-- stores connection metrics (bitrate, packet loss, round-trip time) for quality
-- monitoring and debugging. Session records enable features like call history,
-- duration tracking, and quality analysis.
--
-- Key Performance Indicators (KPIs):
--   1. Concurrent Calls: Peak simultaneous WebRTC sessions
--   2. Call Success Rate: Percentage of initiated calls that connect (>95%)
--   3. Call Duration: Average length of successful calls
--   4. Call Quality: MOS score or quality rating (>4.0)
--   5. Reconnection Rate: Successful reconnections after network changes
--   6. ICE Failure Rate: Percentage of ICE gathering failures (<5%)
--   7. Platform Mix: Web vs. mobile call distribution
--
-- Feature Reference: WEBRTC-02 (WebRTC Session Management)
-- Requirements Traceability: R-WEBRTC-001 through R-WEBRTC-020
--
-- Normalization: 3NF - Sessions independent with participants
--
-- High-Write Considerations:
--   - Moderate write volume (session creation, updates)
--   - Read-heavy for active session lookups
--   - Partitioning by created_at for historical queries
--   - Partial indexes for active sessions only
-------------------------------------------------------------------------------
CREATE TABLE public.webrtc_sessions (
    -- Primary key
    session_id UUID DEFAULT gen_random_uuid() NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Session identification
    call_id VARCHAR(255), -- External call identifier
    room_name VARCHAR(255), -- Room for group calls

    -- Participants
    initiator_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    participants UUID[] NOT NULL, -- All users in the call

    -- Session type
    session_type VARCHAR(50) CHECK (session_type IN (
        'video_call', 'audio_call', 'screen_share', 'data_channel', 'group_call'
    )),

    -- WebRTC configuration
    ice_servers JSONB, -- STUN/TURN server configuration
    ice_transport_policy VARCHAR(50) CHECK (ice_transport_policy IN ('all', 'relay')),
    bundle_policy VARCHAR(50) CHECK (bundle_policy IN ('balanced', 'max_compat', 'max_bundle')),
    rtcp_mux_policy VARCHAR(50) CHECK (rtcp_mux_policy IN ('require', 'negotiate')),

    -- Session status
    status public.webrtc_session_status NOT NULL DEFAULT 'INITIATING',
    status_reason TEXT,
    started_at TIMESTAMP WITH TIME ZONE,
    ended_at TIMESTAMP WITH TIME ZONE,
    duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (COALESCE(ended_at, CURRENT_TIMESTAMP) - started_at))
    ) STORED,

    -- ICE gathering
    ice_gathering_complete BOOLEAN DEFAULT false,
    ice_connection_state VARCHAR(50),
    ice_candidates JSONB[], -- Array of ICE candidates

    -- Connection metrics
    bitrate_kbps INTEGER,
    packet_loss_percent NUMERIC(5,2),
    round_trip_time_ms INTEGER,
    jitter_ms INTEGER,
    resolution_width INTEGER,
    resolution_height INTEGER,
    frame_rate INTEGER,
    codec VARCHAR(50),

    -- Quality metrics
    quality_score NUMERIC(3,2) CHECK (quality_score >= 0 AND quality_score <= 1),
    quality_issues TEXT[],

    -- Recording
    is_recorded BOOLEAN DEFAULT false,
    recording_url TEXT,
    recording_size_bytes BIGINT,

    -- TURN server usage
    used_turn BOOLEAN DEFAULT false,
    turn_server VARCHAR(255),

    -- Network information
    network_type VARCHAR(50), -- 'wifi', 'cellular', 'ethernet'
    cellular_type VARCHAR(50), -- '4g', '5g', 'lte'

    -- Geolocation (approximate)
    initiator_country CHAR(2),
    participants_countries TEXT[],

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Metadata
    metadata JSONB,
    tags TEXT[],

    -- Constraints
    CONSTRAINT valid_dates CHECK (
        (started_at IS NULL OR started_at >= created_at) AND
        (ended_at IS NULL OR ended_at >= started_at)
    ),

    PRIMARY KEY (session_id, created_at)
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.webrtc_sessions IS 'Tracks WebRTC peer-to-peer sessions for video/audio calls and screen sharing';
COMMENT ON COLUMN public.webrtc_sessions.session_id IS 'Primary key';
COMMENT ON COLUMN public.webrtc_sessions.created_at IS 'When session was created (partition key)';
COMMENT ON COLUMN public.webrtc_sessions.call_id IS 'External call identifier';
COMMENT ON COLUMN public.webrtc_sessions.room_name IS 'Room name for group calls';
COMMENT ON COLUMN public.webrtc_sessions.initiator_id IS 'User who started the call';
COMMENT ON COLUMN public.webrtc_sessions.participants IS 'All users in the call';
COMMENT ON COLUMN public.webrtc_sessions.session_type IS 'Type of WebRTC session';
COMMENT ON COLUMN public.webrtc_sessions.ice_servers IS 'STUN/TURN server configuration';
COMMENT ON COLUMN public.webrtc_sessions.status IS 'Current session status';
COMMENT ON COLUMN public.webrtc_sessions.started_at IS 'When call actually started';
COMMENT ON COLUMN public.webrtc_sessions.ended_at IS 'When call ended';
COMMENT ON COLUMN public.webrtc_sessions.duration_seconds IS 'Call duration';
COMMENT ON COLUMN public.webrtc_sessions.ice_candidates IS 'ICE candidates gathered';
COMMENT ON COLUMN public.webrtc_sessions.bitrate_kbps IS 'Average bitrate';
COMMENT ON COLUMN public.webrtc_sessions.packet_loss_percent IS 'Packet loss percentage';
COMMENT ON COLUMN public.webrtc_sessions.round_trip_time_ms IS 'RTT in milliseconds';
COMMENT ON COLUMN public.webrtc_sessions.jitter_ms IS 'Jitter in milliseconds';
COMMENT ON COLUMN public.webrtc_sessions.quality_score IS 'Overall quality score (0-1)';
COMMENT ON COLUMN public.webrtc_sessions.used_turn IS 'Whether TURN relay was used';
COMMENT ON COLUMN public.webrtc_sessions.network_type IS 'Type of network connection';

-- Create partition management function (reuse from presence_history)

-- Global indexes
CREATE INDEX idx_webrtc_sessions_initiator ON public.webrtc_sessions(initiator_id, created_at DESC);
CREATE INDEX idx_webrtc_sessions_status ON public.webrtc_sessions(status, created_at DESC);
CREATE INDEX idx_webrtc_sessions_room ON public.webrtc_sessions(room_name) WHERE room_name IS NOT NULL;
CREATE INDEX idx_webrtc_sessions_call_id ON public.webrtc_sessions(call_id) WHERE call_id IS NOT NULL;

-- GIN indexes
CREATE INDEX idx_webrtc_sessions_participants ON public.webrtc_sessions USING gin(participants);
CREATE INDEX idx_webrtc_sessions_ice_candidates ON public.webrtc_sessions USING gin(ice_candidates);
CREATE INDEX idx_webrtc_sessions_tags ON public.webrtc_sessions USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_webrtc_sessions_timestamp
    BEFORE UPDATE ON public.webrtc_sessions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.webrtc_sessions ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY webrtc_sessions_participant_policy ON public.webrtc_sessions
    FOR SELECT USING (
        initiator_id = current_user_id() OR
        current_user_id() = ANY(participants)
    );

CREATE POLICY webrtc_sessions_admin_policy ON public.webrtc_sessions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name = 'admin'
    ));

-- =============================================================================
-- MATERIALIZED VIEW: mv_realtime_performance
-- =============================================================================
-------------------------------------------------------------------------------
-- Materialized View: mv_realtime_performance
-- Description: Aggregated real-time system performance metrics
-- Refresh Strategy: Every 5 minutes
-- Feature Reference: REAL-05 (Performance Monitoring)
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW public.mv_realtime_performance AS
WITH connection_stats AS (
    SELECT
        DATE_TRUNC('minute', connected_at) as minute,
        COUNT(*) as new_connections,
        COUNT(DISTINCT user_id) as unique_users,
        AVG(EXTRACT(EPOCH FROM (COALESCE(disconnected_at, CURRENT_TIMESTAMP) - connected_at))) as avg_session_duration
    FROM public.realtime_connections
    WHERE connected_at > CURRENT_TIMESTAMP - INTERVAL '1 hour'
    GROUP BY DATE_TRUNC('minute', connected_at)
),
message_stats AS (
    SELECT
        DATE_TRUNC('minute', created_at) as minute,
        COUNT(*) as messages_sent,
        AVG(payload_size_bytes) as avg_payload_size
    FROM public.realtime_notifications_queue
    WHERE created_at > CURRENT_TIMESTAMP - INTERVAL '1 hour'
    GROUP BY DATE_TRUNC('minute', created_at)
),
error_stats AS (
    SELECT
        DATE_TRUNC('minute', event_time) as minute,
        COUNT(*) as error_count
    FROM public.realtime_events_log
    WHERE event_time > CURRENT_TIMESTAMP - INTERVAL '1 hour'
        AND severity IN ('error', 'fatal')
    GROUP BY DATE_TRUNC('minute', event_time)
)
SELECT
    COALESCE(c.minute, m.minute, e.minute) as minute,
    COALESCE(c.new_connections, 0) as new_connections,
    COALESCE(c.unique_users, 0) as unique_users,
    ROUND(COALESCE(c.avg_session_duration, 0)::NUMERIC, 2) as avg_session_duration_seconds,
    COALESCE(m.messages_sent, 0) as messages_sent,
    ROUND(COALESCE(m.avg_payload_size, 0)::NUMERIC, 2) as avg_payload_size_bytes,
    COALESCE(e.error_count, 0) as error_count,
    NOW() as refreshed_at
FROM connection_stats c
FULL OUTER JOIN message_stats m ON c.minute = m.minute
FULL OUTER JOIN error_stats e ON COALESCE(c.minute, m.minute) = e.minute
ORDER BY minute DESC;

COMMENT ON MATERIALIZED VIEW public.mv_realtime_performance IS 'Aggregated real-time system performance metrics';

CREATE UNIQUE INDEX idx_mv_realtime_performance_minute ON public.mv_realtime_performance(minute);

-- =============================================================================
-- STORED PROCEDURES
-- =============================================================================

-------------------------------------------------------------------------------
-- Procedure: broadcast_realtime_notification
-- Description: Broadcasts a notification to all connected clients or channel subscribers
-- Business Case: Enables efficient fan-out of system-wide notifications
-- Feature Reference: REAL-06 (Broadcast)
-------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE public.broadcast_realtime_notification(
    p_notification_type VARCHAR(100),
    p_payload JSONB,
    p_priority public.notification_priority DEFAULT 'MEDIUM',
    p_target_channels TEXT[] DEFAULT NULL, -- NULL means broadcast to all
    p_exclude_users UUID[] DEFAULT NULL
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_target_connections UUID[];
    v_queue_id UUID;
    v_count INTEGER := 0;
BEGIN
    -- Get target connections (simplified - would join with subscriptions)
    SELECT ARRAY_AGG(connection_id)
    INTO v_target_connections
    FROM public.realtime_connections
    WHERE is_active = true
        AND (p_target_channels IS NULL OR
             subscribed_channels && p_target_channels)
        AND (p_exclude_users IS NULL OR
             user_id NOT IN (SELECT unnest(p_exclude_users)));

    -- Create queue entries (one per connection or one for fan-out)
    IF array_length(v_target_connections, 1) > 1000 THEN
        -- For large broadcasts, create a single fan-out notification
        INSERT INTO public.realtime_notifications_queue (
            notification_type,
            priority,
            target_type,
            payload,
            target_connection_ids
        ) VALUES (
            p_notification_type,
            p_priority,
            'broadcast',
            p_payload,
            v_target_connections
        ) RETURNING queue_id INTO v_queue_id;

        v_count := 1;
    ELSE
        -- For smaller groups, create individual notifications
        INSERT INTO public.realtime_notifications_queue (
            notification_type,
            priority,
            target_type,
            target_id,
            payload
        )
        SELECT
            p_notification_type,
            p_priority,
            'connection',
            connection_id,
            p_payload
        FROM unnest(v_target_connections) AS connection_id;

        GET DIAGNOSTICS v_count = ROW_COUNT;
    END IF;

    -- Log the broadcast
    INSERT INTO public.realtime_events_log (
        event_category,
        event_type,
        event_data,
        source_service
    ) VALUES (
        'notification',
        'broadcast',
        jsonb_build_object(
            'type', p_notification_type,
            'target_count', array_length(v_target_connections, 1),
            'queue_entries', v_count,
            'channels', p_target_channels
        ),
        'broadcast_service'
    );

    RAISE NOTICE 'Broadcast queued for % connections', array_length(v_target_connections, 1);
END;
$$;

COMMENT ON PROCEDURE public.broadcast_realtime_notification IS 'Broadcasts a notification to connected clients or channel subscribers';

-- =============================================================================
-- SCHEDULED JOBS
-- =============================================================================

-- Create scheduled jobs if pg_cron is available
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
        -- Cleanup stale connections every minute
        PERFORM cron.schedule(
            'cleanup-stale-connections',
            '* * * * *',
            'SELECT public.cleanup_stale_connections();'
        );

        -- Cleanup typing indicators every 10 seconds
        PERFORM cron.schedule(
            'cleanup-typing-indicators',
            '*/10 * * * * *',
            'SELECT public.cleanup_typing_indicators();'
        );

        -- Refresh real-time performance view every 5 minutes
        PERFORM cron.schedule(
            'refresh-realtime-performance',
            '*/5 * * * *',
            'REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_realtime_performance;'
        );

        -- Archive old real-time events daily (keep 7 days)
        PERFORM cron.schedule(
            'archive-realtime-events',
            '0 1 * * *',
            $$
            CREATE TABLE IF NOT EXISTS public.realtime_events_archive
            AS SELECT * FROM public.realtime_events_log
            WHERE event_time < CURRENT_TIMESTAMP - INTERVAL '7 days';

            DELETE FROM public.realtime_events_log
            WHERE event_time < CURRENT_TIMESTAMP - INTERVAL '7 days';
            $$
        );
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'pg_cron extension not available. Scheduled tasks will not be created.';
END $$;

