-- =============================================================================
-- EXTENSIONS
-- =============================================================================

-- Extension 1: pgcrypto
-- Purpose: Provides cryptographic functions for generating secure random values,
--          hashing, and encryption. Used for certificate verification codes,
--          secure tokens, and data protection.
-- Functionality: gen_random_uuid(), digest(), encrypt(), decrypt(), pgp_sym_encrypt()
CREATE EXTENSION IF NOT EXISTS pgcrypto;
COMMENT ON EXTENSION pgcrypto IS 'Cryptographic functions for secure token generation and encryption';

-- Extension 2: pg_trgm
-- Purpose: Provides trigram-based text similarity and fuzzy string matching.
--          Essential for search functionality, template name matching, and
--          user-friendly search experiences.
-- Functionality: similarity(), word_similarity(), GIN/GIST indexes for text search
CREATE EXTENSION IF NOT EXISTS pg_trgm;
COMMENT ON EXTENSION pg_trgm IS 'Trigram-based text similarity for fuzzy search and matching';

-- Extension 3: btree_gin
-- Purpose: Enables GIN indexes on scalar data types (integers, timestamps, etc.)
--          allowing combined GIN indexes for mixed data type queries, crucial
--          for complex search filters.
-- Functionality: GIN operator classes for scalar types
CREATE EXTENSION IF NOT EXISTS btree_gin;
COMMENT ON EXTENSION btree_gin IS 'GIN operator classes for scalar data types';

-- Extension 4: tablefunc
-- Purpose: Provides crosstab functions for generating pivot tables and summary
--          reports from normalized data. Used for analytics and reporting.
-- Functionality: crosstab(), connectby()
CREATE EXTENSION IF NOT EXISTS tablefunc;
COMMENT ON EXTENSION tablefunc IS 'Crosstab functions for pivot table generation';

-- Extension 5: pg_stat_statements
-- Purpose: Tracks execution statistics of all SQL statements executed.
--          Essential for performance monitoring and query optimization.
-- Functionality: Query performance metrics, execution counts, timing statistics
CREATE EXTENSION IF NOT EXISTS pg_stat_statements;
COMMENT ON EXTENSION pg_stat_statements IS 'SQL statement execution statistics for performance monitoring';

