-------------------------------------------------------------------------------
-- Function: update_timestamp
-- Description: Automatically updates updated_at column to CURRENT_TIMESTAMP
-- Business Case: Ensures audit trail accuracy by maintaining last modification
--                timestamps without application-level intervention.
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.update_timestamp() IS 'Universal trigger function for updating updated_at timestamp';

-------------------------------------------------------------------------------
-- Function: current_user_id
-- Description: Retrieves the current authenticated user's ID from session context
-- Business Case: Centralizes user context retrieval for RLS policies and audit
--                columns, ensuring consistent user identification across the
--                entire database layer.
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS UUID AS $$
DECLARE
    user_uuid UUID;
BEGIN
    -- Try to get from session variable first (application-set)
    user_uuid := NULLIF(current_setting('app.current_user_id', TRUE), '')::UUID;

    -- Fallback to role-based mapping (for service accounts)
    IF user_uuid IS NULL THEN
        SELECT user_id INTO user_uuid
        FROM public.users
        WHERE username = current_user
        LIMIT 1;
    END IF;

    RETURN user_uuid;
EXCEPTION
    WHEN OTHERS THEN
        RETURN NULL;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;
COMMENT ON FUNCTION public.current_user_id() IS 'Retrieves current authenticated user ID from session context';

