CREATE TYPE public.alert_frequency AS ENUM (
    'DAILY',
    'WEEKLY',
    'MONTHLY',
    'REAL_TIME',
    'NEVER'
);
COMMENT ON TYPE public.alert_frequency IS 'Frequency for saved search alerts';

