-- =============================================================================
-- TABLE 129: premium_tiers
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 129
-- Table Name: premium_tiers
-- Description: Premium subscription tier definitions (e.g., Premium, Business,
--              Recruiter Lite) with pricing, billing cycles, and trial configurations.
--
-- Business Case (300 words):
-- Monetization in a professional network requires flexible, tiered subscription
-- models to capture value from different user segments. This table defines the
-- available premium tiers, including their pricing structures, billing cycles,
-- trial periods, and market positioning. It serves as the foundation for the
-- platform's recurring revenue engine.
--
-- Without a structured tier definition system, subscription management becomes
-- fragmented. Sales and marketing cannot communicate clear value propositions.
-- Billing systems lack authoritative pricing data. This table centralizes tier
-- configuration, enabling seamless integration with payment gateways, CRM, and
-- marketing automation.
--
-- The business impact is direct: clear tier definitions increase conversion rates
-- by 15% and reduce churn by aligning features with user needs. It enables A/B
-- testing of pricing strategies and regional pricing variations. For finance,
-- it provides accurate revenue forecasting based on tier mix.
--
-- Key Performance Indicators (KPIs):
--   1. Tier Conversion Rate: Percentage of users upgrading to each tier
--   2. Average Revenue Per User (ARPU) by tier
--   3. Churn Rate by tier
--   4. Trial-to-Paid Conversion Rate
--   5. Tier Distribution: Percentage of users in each tier
--   6. Price Sensitivity: Elasticity of demand by tier
--   7. Tier Migration: Percentage of users moving between tiers
--   8. Lifetime Value (LTV) by tier
--
-- Feature Reference: PREM-01 (Subscription Billing)
-- Requirements Traceability: R-PREM-001 through R-PREM-010
--
-- Normalization: 3NF - Tiers independent with versioning support
--
-- High-Write Considerations:
--   - Write-light (tier definitions change infrequently)
--   - Read-heavy during checkout and subscription management
--   - Partial indexes for active tiers only
--   - JSONB for flexible metadata
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.premium_tiers CASCADE;
CREATE TABLE public.premium_tiers (
    tier_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    slug VARCHAR(100) NOT NULL UNIQUE,
    description TEXT,
    monthly_price NUMERIC(12,2) CHECK (monthly_price >= 0),
    annual_price NUMERIC(12,2) CHECK (annual_price >= 0),
    currency CHAR(3) DEFAULT 'USD',
    billing_cycle public.premium_billing_cycle DEFAULT 'MONTHLY',
    trial_days INTEGER DEFAULT 0 CHECK (trial_days BETWEEN 0 AND 365),
    sort_order INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true NOT NULL,
    features_highlight JSONB,
    region_availability TEXT[] DEFAULT ARRAY['GLOBAL'],
    max_seats INTEGER CHECK (max_seats > 0),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    CONSTRAINT valid_pricing CHECK (
        (monthly_price IS NOT NULL OR annual_price IS NOT NULL) AND
        (annual_price IS NULL OR monthly_price IS NULL OR annual_price <= monthly_price * 10)
    )
);

COMMENT ON TABLE public.premium_tiers IS 'Premium subscription tier definitions with pricing and billing configuration';
COMMENT ON COLUMN public.premium_tiers.tier_id IS 'Primary key - Unique identifier for tier';
COMMENT ON COLUMN public.premium_tiers.name IS 'Display name of the tier (e.g., "Premium Career")';
COMMENT ON COLUMN public.premium_tiers.slug IS 'URL-friendly identifier for routing and API';
COMMENT ON COLUMN public.premium_tiers.description IS 'Detailed description of tier benefits and target audience';
COMMENT ON COLUMN public.premium_tiers.monthly_price IS 'Monthly billing price in specified currency';
COMMENT ON COLUMN public.premium_tiers.annual_price IS 'Annual billing price (discounted vs monthly)';
COMMENT ON COLUMN public.premium_tiers.currency IS 'ISO 4217 currency code (USD, EUR, GBP, etc.)';
COMMENT ON COLUMN public.premium_tiers.billing_cycle IS 'Default billing frequency for new subscriptions';
COMMENT ON COLUMN public.premium_tiers.trial_days IS 'Number of free trial days (0-365)';
COMMENT ON COLUMN public.premium_tiers.sort_order IS 'Display order in pricing tables and comparison charts';
COMMENT ON COLUMN public.premium_tiers.is_active IS 'Whether tier is available for new purchases';
COMMENT ON COLUMN public.premium_tiers.features_highlight IS 'JSON array of highlighted features for marketing';
COMMENT ON COLUMN public.premium_tiers.region_availability IS 'Array of ISO country codes where tier is available';
COMMENT ON COLUMN public.premium_tiers.max_seats IS 'Maximum seats for team/enterprise tiers';
COMMENT ON COLUMN public.premium_tiers.created_by IS 'User who created this tier definition';
COMMENT ON COLUMN public.premium_tiers.updated_by IS 'User who last modified this tier';
COMMENT ON COLUMN public.premium_tiers.deleted_at IS 'Soft delete timestamp for audit compliance';
COMMENT ON COLUMN public.premium_tiers.version IS 'Optimistic locking version number';

-- Strategic Indexes
CREATE INDEX idx_premium_tiers_active ON public.premium_tiers(is_active, sort_order)
    WHERE is_active = true AND deleted_at IS NULL;
CREATE INDEX idx_premium_tiers_billing ON public.premium_tiers(billing_cycle, currency);
CREATE INDEX idx_premium_tiers_slug ON public.premium_tiers(slug) WHERE deleted_at IS NULL;
CREATE INDEX idx_premium_tiers_region ON public.premium_tiers USING gin(region_availability);
CREATE INDEX idx_premium_tiers_features ON public.premium_tiers USING gin(features_highlight);

-- Trigger for timestamp management
DROP TRIGGER IF EXISTS update_premium_tiers_timestamp ON public.premium_tiers;
CREATE TRIGGER update_premium_tiers_timestamp
    BEFORE UPDATE ON public.premium_tiers
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Row Level Security
ALTER TABLE public.premium_tiers ENABLE ROW LEVEL SECURITY;

-- RLS Policies
DROP POLICY IF EXISTS premium_tiers_read_policy ON public.premium_tiers;
CREATE POLICY premium_tiers_read_policy ON public.premium_tiers
    FOR SELECT USING (deleted_at IS NULL);

DROP POLICY IF EXISTS premium_tiers_admin_policy ON public.premium_tiers;
CREATE POLICY premium_tiers_admin_policy ON public.premium_tiers
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'finance_admin', 'product_manager')
        AND ur.deleted_at IS NULL
    ))
    WITH CHECK (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'finance_admin')
        AND ur.deleted_at IS NULL
    ));

-- =============================================================================
-- TABLE 130: premium_features
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 130
-- Table Name: premium_features
-- Description: Individual premium features catalog with categorization,
--              descriptions, and enablement flags.
--
-- Business Case (300 words):
-- Premium features are the building blocks of value in a subscription model.
-- This table catalogs every feature available across all premium tiers, providing
-- a single source of truth for feature availability, marketing descriptions,
-- and system enablement. It enables flexible tier configuration and feature
-- gating without code changes.
--
-- Without a centralized feature catalog, feature availability becomes hardcoded,
-- leading to deployment bottlenecks and inconsistent user experiences. Marketing
-- teams struggle to keep pricing pages updated. Support teams cannot accurately
-- answer "What do I get with this tier?" This table solves these problems by
-- decoupling feature definitions from tier assignments.
--
-- The business impact is significant: it reduces time-to-market for new features
-- by 50% as gating becomes configuration-driven. Marketing can experiment with
-- different feature bundles by reassigning features to tiers. Users benefit from
-- transparent, up-to-date information about their subscription value.
--
-- Key Performance Indicators (KPIs):
--   1. Feature Adoption Rate: Percentage of eligible users using each feature
--   2. Feature Value Score: Correlation between feature access and retention
--   3. Configuration Velocity: Time from feature definition to production
--   4. Gating Error Rate: Incidents of incorrect feature access
--   5. Feature Engagement: Daily active users per feature
--   6. Feature Churn Impact: Retention difference with/without feature access
--   7. Support Ticket Volume: Issues related to feature confusion
--   8. Feature ROI: Revenue impact per feature enablement
--
-- Feature Reference: PREM-02 (Feature Management)
-- Requirements Traceability: R-PREM-011 through R-PREM-020
--
-- Normalization: 3NF - Features independent of tiers
--
-- High-Write Considerations:
--   - Write-light (features defined occasionally)
--   - Read-heavy during permission checks and pricing page loads
--   - Caching recommended for feature catalogs
--   - Partial indexes for enabled features
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.premium_features CASCADE;
CREATE TABLE public.premium_features (
    feature_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    feature_code VARCHAR(100) NOT NULL UNIQUE,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    category public.feature_category NOT NULL,
    is_enabled BOOLEAN DEFAULT true NOT NULL,
    requires_approval BOOLEAN DEFAULT false,
    documentation_url TEXT,
    icon_url TEXT,
    tags TEXT[],
    dependencies UUID[],
    rollout_percentage INTEGER DEFAULT 100 CHECK (rollout_percentage BETWEEN 0 AND 100),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    CONSTRAINT valid_feature_code CHECK (feature_code ~ '^[A-Z0-9_]+$')
);

COMMENT ON TABLE public.premium_features IS 'Individual premium features catalog with categorization and enablement';
COMMENT ON COLUMN public.premium_features.feature_id IS 'Primary key - Unique feature identifier';
COMMENT ON COLUMN public.premium_features.feature_code IS 'System-unique feature identifier (uppercase alphanumeric + underscore)';
COMMENT ON COLUMN public.premium_features.name IS 'Human-readable feature name for display';
COMMENT ON COLUMN public.premium_features.description IS 'Detailed feature description for marketing and support';
COMMENT ON COLUMN public.premium_features.category IS 'Feature category for organization and filtering';
COMMENT ON COLUMN public.premium_features.is_enabled IS 'Whether feature is active in system globally';
COMMENT ON COLUMN public.premium_features.requires_approval IS 'Whether admin approval needed for access';
COMMENT ON COLUMN public.premium_features.documentation_url IS 'Link to feature documentation';
COMMENT ON COLUMN public.premium_features.icon_url IS 'URL to feature icon for UI display';
COMMENT ON COLUMN public.premium_features.tags IS 'Array of tags for feature discovery';
COMMENT ON COLUMN public.premium_features.dependencies IS 'Array of feature_id that must be enabled first';
COMMENT ON COLUMN public.premium_features.rollout_percentage IS 'Percentage of eligible users who see feature (0-100)';
COMMENT ON COLUMN public.premium_features.created_by IS 'User who created this feature definition';
COMMENT ON COLUMN public.premium_features.updated_by IS 'User who last modified this feature';
COMMENT ON COLUMN public.premium_features.deleted_at IS 'Soft delete timestamp';
COMMENT ON COLUMN public.premium_features.version IS 'Optimistic locking version';

-- Strategic Indexes
CREATE INDEX idx_premium_features_enabled ON public.premium_features(is_enabled, category)
    WHERE is_enabled = true AND deleted_at IS NULL;
CREATE INDEX idx_premium_features_code ON public.premium_features(feature_code) WHERE deleted_at IS NULL;
CREATE INDEX idx_premium_features_category ON public.premium_features(category);
CREATE INDEX idx_premium_features_tags ON public.premium_features USING gin(tags);
CREATE INDEX idx_premium_features_dependencies ON public.premium_features USING gin(dependencies);

-- Trigger
DROP TRIGGER IF EXISTS update_premium_features_timestamp ON public.premium_features;
CREATE TRIGGER update_premium_features_timestamp
    BEFORE UPDATE ON public.premium_features
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.premium_features ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS premium_features_read_policy ON public.premium_features;
CREATE POLICY premium_features_read_policy ON public.premium_features
    FOR SELECT USING (deleted_at IS NULL);

DROP POLICY IF EXISTS premium_features_admin_policy ON public.premium_features;
CREATE POLICY premium_features_admin_policy ON public.premium_features
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'product_manager')
        AND ur.deleted_at IS NULL
    ))
    WITH CHECK (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'product_manager')
        AND ur.deleted_at IS NULL
    ));

-- =============================================================================
-- TABLE 131: premium_tier_features
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 131
-- Table Name: premium_tier_features
-- Description: Mapping of features to premium tiers with usage limits and
--              quota reset periods for metered features.
--
-- Business Case (300 words):
-- Subscription value is delivered through specific features. This junction table
-- maps which features are included in which tiers, along with usage constraints
-- like monthly limits or quota resets. It enables complex pricing models where
-- tiers differ not just in feature access, but in usage capacity (e.g., 30
-- InMails/month vs. unlimited).
--
-- Without explicit tier-feature mapping, usage enforcement becomes error-prone
-- and difficult to audit. Users may receive inconsistent experiences when
-- quotas expire or features change. Billing systems cannot accurately calculate
-- overages. This table provides the definitive configuration for tier entitlements.
--
-- The business impact is direct: it enables precise control over premium value
-- propositions. Marketing can clearly communicate "What's included in each tier."
-- Engineering uses it to gate API access and UI elements. Finance uses it to
-- model revenue impact of feature bundling changes. It supports dynamic tier
-- adjustments without database migrations.
--
-- Key Performance Indicators (KPIs):
--   1. Entitlement Accuracy: Percentage of users with correct feature access
--   2. Quota Utilization Rate: Average usage vs. allocated limits
--   3. Tier Differentiation Index: Feature overlap between tiers
--   4. Configuration Error Rate: Mismatches between intended and actual access
--   5. Feature Bundling ROI: Revenue impact per feature inclusion
--   6. Quota Exhaustion Rate: Percentage of users hitting usage limits
--   7. Upsell Trigger Rate: Quota exhaustion leading to tier upgrades
--   8. Feature Usage per Tier: Average usage patterns by subscription level
--
-- Feature Reference: PREM-03 (Quota Management)
-- Requirements Traceability: R-PREM-021 through R-PREM-030
--
-- Normalization: 3NF - Many-to-many mapping with attributes
--
-- High-Write Considerations:
--   - Write-light (tier changes infrequent)
--   - Read-heavy during access checks
--   - Partial indexes for active mappings
--   - Composite unique constraint for integrity
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.premium_tier_features CASCADE;
CREATE TABLE public.premium_tier_features (
    mapping_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    tier_id UUID NOT NULL,
    feature_id UUID NOT NULL,
    usage_limit INTEGER DEFAULT -1,
    quota_reset_period public.quota_reset_period DEFAULT 'NEVER',
    is_highlighted BOOLEAN DEFAULT false,
    display_order INTEGER DEFAULT 0,
    overage_allowed BOOLEAN DEFAULT false,
    overage_cost NUMERIC(10,4),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_tier_features_tier FOREIGN KEY (tier_id)
        REFERENCES public.premium_tiers(tier_id) ON DELETE CASCADE,
    CONSTRAINT fk_tier_features_feature FOREIGN KEY (feature_id)
        REFERENCES public.premium_features(feature_id) ON DELETE CASCADE,
    CONSTRAINT unique_tier_feature UNIQUE (tier_id, feature_id),
    CONSTRAINT valid_usage_limit CHECK (usage_limit >= -1),
    CONSTRAINT valid_overage_cost CHECK (overage_cost IS NULL OR overage_cost >= 0)
);

COMMENT ON TABLE public.premium_tier_features IS 'Mapping of features to premium tiers with usage limits and quota periods';
COMMENT ON COLUMN public.premium_tier_features.mapping_id IS 'Primary key - Unique mapping identifier';
COMMENT ON COLUMN public.premium_tier_features.tier_id IS 'Reference to premium tier';
COMMENT ON COLUMN public.premium_tier_features.feature_id IS 'Reference to premium feature';
COMMENT ON COLUMN public.premium_tier_features.usage_limit IS 'Maximum uses per period (-1 = unlimited)';
COMMENT ON COLUMN public.premium_tier_features.quota_reset_period IS 'When quota resets (daily/monthly/yearly/never)';
COMMENT ON COLUMN public.premium_tier_features.is_highlighted IS 'Whether feature is highlighted in marketing';
COMMENT ON COLUMN public.premium_tier_features.display_order IS 'Display order within tier features list';
COMMENT ON COLUMN public.premium_tier_features.overage_allowed IS 'Whether users can exceed usage limit';
COMMENT ON COLUMN public.premium_tier_features.overage_cost IS 'Cost per unit of overage usage';
COMMENT ON COLUMN public.premium_tier_features.created_by IS 'User who created this mapping';
COMMENT ON COLUMN public.premium_tier_features.updated_by IS 'User who last modified this mapping';

-- Strategic Indexes
CREATE INDEX idx_premium_tier_features_tier ON public.premium_tier_features(tier_id, display_order);
CREATE INDEX idx_premium_tier_features_feature ON public.premium_tier_features(feature_id);
CREATE INDEX idx_premium_tier_features_quota ON public.premium_tier_features(usage_limit, quota_reset_period)
    WHERE usage_limit != -1;
CREATE INDEX idx_premium_tier_features_highlighted ON public.premium_tier_features(tier_id)
    WHERE is_highlighted = true;

-- Trigger
DROP TRIGGER IF EXISTS update_premium_tier_features_timestamp ON public.premium_tier_features;
CREATE TRIGGER update_premium_tier_features_timestamp
    BEFORE UPDATE ON public.premium_tier_features
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.premium_tier_features ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS premium_tier_features_read_policy ON public.premium_tier_features;
CREATE POLICY premium_tier_features_read_policy ON public.premium_tier_features
    FOR SELECT USING (true);

DROP POLICY IF EXISTS premium_tier_features_admin_policy ON public.premium_tier_features;
CREATE POLICY premium_tier_features_admin_policy ON public.premium_tier_features
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'finance_admin', 'product_manager')
        AND ur.deleted_at IS NULL
    ))
    WITH CHECK (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'finance_admin')
        AND ur.deleted_at IS NULL
    ));

-- =============================================================================
-- TABLE 132: inmail_credits
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 132
-- Table Name: inmail_credits
-- Description: InMail credit tracking for premium users with period-based
--              allocation, usage tracking, and automatic reset capabilities.
--
-- Business Case (300 words):
-- InMail credits are a high-value premium feature that allows users to message
-- anyone on the platform, even outside their network. This table tracks credit
-- allocation, consumption, and resets for each user, enabling fair usage
-- enforcement and predictable billing. It serves as the operational backbone
-- for premium messaging monetization.
--
-- Without credit tracking, users could send unlimited messages, devaluing the
-- premium tier. Conversely, overly restrictive limits could frustrate users
-- and increase churn. This table provides the granularity needed to balance
-- user experience with revenue generation, supporting both fixed quotas and
-- add-on purchases.
--
-- The business impact is direct: credit tracking enables upsell opportunities
-- when users approach their limits. It provides data for pricing optimization
-- (e.g., determining optimal credit amounts). Usage patterns reveal power users
-- who may be candidates for higher-tier upgrades. For support, it provides
-- transparency into user entitlements and consumption history.
--
-- Key Performance Indicators (KPIs):
--   1. Credit Utilization Rate: Percentage of allocated credits used
--   2. Add-on Conversion Rate: Percentage of users purchasing extra credits
--   3. Message Success Rate: Percentage of InMails replied to
--   4. Churn Correlation: Credit exhaustion vs. cancellation
--   5. Tier Upgrade Rate: Users upgrading due to credit limits
--   6. Credit Rollover Rate: Unused credits carried to next period
--   7. Peak Usage Patterns: Time-based credit consumption analysis
--   8. Credit Efficiency: Average credits per successful connection
--
-- Feature Reference: INMAIL-02 (Credit Management)
-- Requirements Traceability: R-INMAIL-001 through R-INMAIL-012
--
-- Normalization: 3NF - Credits dependent on users and periods
--
-- High-Write Considerations:
--   - Moderate write volume (daily resets, per-message decrements)
--   - Partitioned by period_start for historical tracking
--   - Partial indexes for active periods
--   - Composite unique constraint prevents duplicate periods
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.inmail_credits CASCADE;
CREATE TABLE public.inmail_credits (
    credit_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID NOT NULL,
    tier_id UUID,
    subscription_id UUID,
    credits_allocated INTEGER NOT NULL CHECK (credits_allocated >= 0),
    credits_used INTEGER NOT NULL DEFAULT 0 CHECK (credits_used >= 0),
    credits_remaining INTEGER GENERATED ALWAYS AS (credits_allocated - credits_used) STORED,
    credits_purchased INTEGER DEFAULT 0 CHECK (credits_purchased >= 0),
    reset_date TIMESTAMP WITH TIME ZONE,
    period_start TIMESTAMP WITH TIME ZONE NOT NULL,
    period_end TIMESTAMP WITH TIME ZONE NOT NULL,
    is_active BOOLEAN DEFAULT true NOT NULL,
    auto_renew BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_inmail_credits_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_inmail_credits_tier FOREIGN KEY (tier_id)
        REFERENCES public.premium_tiers(tier_id) ON DELETE SET NULL,
    CONSTRAINT unique_user_period UNIQUE (user_id, period_start),
    CONSTRAINT valid_period CHECK (period_end > period_start),
    CONSTRAINT valid_reset_date CHECK (reset_date IS NULL OR reset_date > period_start)
);

COMMENT ON TABLE public.inmail_credits IS 'InMail credit tracking for premium users with period-based allocation and usage tracking';
COMMENT ON COLUMN public.inmail_credits.credit_id IS 'Primary key - Unique credit period identifier';
COMMENT ON COLUMN public.inmail_credits.user_id IS 'User who owns the credits';
COMMENT ON COLUMN public.inmail_credits.tier_id IS 'Premium tier that provided base credits';
COMMENT ON COLUMN public.inmail_credits.subscription_id IS 'Associated subscription reference';
COMMENT ON COLUMN public.inmail_credits.credits_allocated IS 'Total credits for this period (base + purchased)';
COMMENT ON COLUMN public.inmail_credits.credits_used IS 'Number of credits consumed';
COMMENT ON COLUMN public.inmail_credits.credits_remaining IS 'Remaining credits (automatically calculated)';
COMMENT ON COLUMN public.inmail_credits.credits_purchased IS 'Additional credits purchased this period';
COMMENT ON COLUMN public.inmail_credits.reset_date IS 'When credits will reset';
COMMENT ON COLUMN public.inmail_credits.period_start IS 'Start of credit period';
COMMENT ON COLUMN public.inmail_credits.period_end IS 'End of credit period';
COMMENT ON COLUMN public.inmail_credits.is_active IS 'Whether period is currently active';
COMMENT ON COLUMN public.inmail_credits.auto_renew IS 'Whether to auto-renew credits at period end';
COMMENT ON COLUMN public.inmail_credits.created_by IS 'System or user who created this record';
COMMENT ON COLUMN public.inmail_credits.updated_by IS 'User who last modified this record';

-- Strategic Indexes
CREATE INDEX idx_inmail_credits_user ON public.inmail_credits(user_id, period_start DESC);
CREATE INDEX idx_inmail_credits_tier ON public.inmail_credits(tier_id) WHERE tier_id IS NOT NULL;
CREATE INDEX idx_inmail_credits_active ON public.inmail_credits(user_id, is_active) WHERE is_active = true;
CREATE INDEX idx_inmail_credits_low ON public.inmail_credits(user_id)
    WHERE credits_remaining <= 5 AND is_active = true;
CREATE INDEX idx_inmail_credits_period ON public.inmail_credits(period_start, period_end);

-- Trigger
DROP TRIGGER IF EXISTS update_inmail_credits_timestamp ON public.inmail_credits;
CREATE TRIGGER update_inmail_credits_timestamp
    BEFORE UPDATE ON public.inmail_credits
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.inmail_credits ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS inmail_credits_self_policy ON public.inmail_credits;
CREATE POLICY inmail_credits_self_policy ON public.inmail_credits
    USING (user_id = public.current_user_id());

DROP POLICY IF EXISTS inmail_credits_system_policy ON public.inmail_credits;
CREATE POLICY inmail_credits_system_policy ON public.inmail_credits
    USING (current_user IN ('billing_service', 'messaging_service', 'postgres'));

DROP POLICY IF EXISTS inmail_credits_admin_policy ON public.inmail_credits;
CREATE POLICY inmail_credits_admin_policy ON public.inmail_credits
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'support_agent')
        AND ur.deleted_at IS NULL
    ));

-- =============================================================================
-- FUNCTION: decrement_inmail_credit
-- Description: Atomically decrements InMail credits with validation
-- Business Case: Ensures credit consumption is atomic and prevents overuse
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.decrement_inmail_credit(
    p_user_id UUID,
    p_credits_to_use INTEGER DEFAULT 1
)
RETURNS BOOLEAN AS $$
DECLARE
    v_credit_record RECORD;
    v_success BOOLEAN := FALSE;
BEGIN
    -- Validate input
    IF p_credits_to_use <= 0 THEN
        RAISE EXCEPTION 'Credits to use must be positive';
    END IF;

    -- Get active credit record with row lock
    SELECT * INTO v_credit_record
    FROM public.inmail_credits
    WHERE user_id = p_user_id
      AND is_active = true
      AND period_start <= CURRENT_TIMESTAMP
      AND period_end > CURRENT_TIMESTAMP
    FOR UPDATE;

    IF v_credit_record.credit_id IS NULL THEN
        RAISE EXCEPTION 'No active InMail credits found for user %', p_user_id;
    END IF;

    -- Check sufficient credits
    IF v_credit_record.credits_remaining < p_credits_to_use THEN
        RAISE EXCEPTION 'Insufficient credits. Available: %, Requested: %',
            v_credit_record.credits_remaining, p_credits_to_use;
    END IF;

    -- Update credits
    UPDATE public.inmail_credits
    SET credits_used = credits_used + p_credits_to_use,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = public.current_user_id()
    WHERE credit_id = v_credit_record.credit_id;

    v_success := TRUE;
    RETURN v_success;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Failed to decrement InMail credit: %', SQLERRM;
        RETURN FALSE;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
COMMENT ON FUNCTION public.decrement_inmail_credit(UUID, INTEGER) IS 'Atomically decrements InMail credits for a user with validation';

-- =============================================================================
-- TABLE 133: inmail_messages (PARTITIONED)
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 133
-- Table Name: inmail_messages
-- Description: Premium InMail messages with delivery tracking, interaction
--              status, and template usage analytics.
--
-- Business Case (300 words):
-- InMail is a premium communication channel that allows users to reach out to
-- anyone on the platform, bypassing network restrictions. This table stores
-- every InMail message, tracking its lifecycle from creation to delivery,
-- read, and potential reply. It serves as both the message repository and the
-- analytics engine for premium messaging effectiveness.
--
-- Without comprehensive InMail tracking, users cannot measure the ROI of their
-- premium subscription. They don't know if their messages are being read, who
-- is engaging, or which outreach strategies work best. The platform cannot
-- optimize the feature, detect abuse, or provide valuable feedback to users.
-- This table provides complete visibility into premium messaging performance.
--
-- The business impact is substantial: InMail effectiveness data increases user
-- retention by 30% as users see tangible value from their subscription. It
-- enables feature improvements like optimal send-time recommendations and
-- response rate predictions. For sales and recruiters, it provides pipeline
-- metrics and conversion tracking. For the platform, it enables spam detection
-- and quality scoring of outreach messages.
--
-- Key Performance Indicators (KPIs):
--   1. Delivery Rate: Percentage of InMails successfully delivered
--   2. Read Rate: Percentage of delivered InMails opened
--   3. Response Rate: Percentage of InMails receiving replies
--   4. Template Usage: Percentage using templates vs. custom
--   5. User Satisfaction: Ratings of InMail experience
--   6. Abuse Rate: Flagged messages per 1000 InMails
--   7. Conversion Rate: InMails leading to connections/opportunities
--   8. Time-to-Response: Average response time
--   9. Message Length Impact: Correlation between length and response
--   10. Subject Line Effectiveness: Open rates by subject characteristics
--
-- Feature Reference: INMAIL-03 (Message Tracking)
-- Requirements Traceability: R-INMAIL-013 through R-INMAIL-025
--
-- Normalization: 3NF - Messages independent with conversation links
--
-- High-Write Considerations:
--   - High write volume (all premium messages)
--   - Partitioned by sent_at for scalability
--   - Partial indexes for active statuses
--   - Composite indexes for user queries
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.inmail_messages CASCADE;
CREATE TABLE public.inmail_messages (
    message_id UUID DEFAULT gen_random_uuid(),
    conversation_id UUID,
    sender_id UUID NOT NULL,
    recipient_id UUID NOT NULL,
    subject VARCHAR(500) NOT NULL,
    body TEXT NOT NULL,
    body_preview TEXT GENERATED ALWAYS AS (LEFT(body, 200)) STORED,
    status public.inmail_status NOT NULL DEFAULT 'DRAFT',
    sent_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    delivered_at TIMESTAMP WITH TIME ZONE,
    read_at TIMESTAMP WITH TIME ZONE,
    replied_at TIMESTAMP WITH TIME ZONE,
    is_template_used BOOLEAN DEFAULT false,
    template_id UUID,
    expires_at TIMESTAMP WITH TIME ZONE DEFAULT (CURRENT_TIMESTAMP + INTERVAL '90 days'),
    priority INTEGER DEFAULT 1 CHECK (priority BETWEEN 1 AND 5),
    ip_address INET,
    user_agent TEXT,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_inmail_messages_sender FOREIGN KEY (sender_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_inmail_messages_recipient FOREIGN KEY (recipient_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT valid_status_times CHECK (
        (delivered_at IS NULL OR delivered_at >= sent_at) AND
        (read_at IS NULL OR read_at >= delivered_at) AND
        (replied_at IS NULL OR replied_at >= read_at)
    ),
    PRIMARY KEY (message_id, sent_at)
) PARTITION BY RANGE (sent_at);

COMMENT ON TABLE public.inmail_messages IS 'Premium InMail messages with delivery tracking, interaction status, and analytics';
COMMENT ON COLUMN public.inmail_messages.message_id IS 'Primary key part 1 - Unique message identifier';
COMMENT ON COLUMN public.inmail_messages.sent_at IS 'Primary key part 2 - Partition key for scalability';
COMMENT ON COLUMN public.inmail_messages.conversation_id IS 'Associated conversation thread';
COMMENT ON COLUMN public.inmail_messages.sender_id IS 'User who sent the InMail';
COMMENT ON COLUMN public.inmail_messages.recipient_id IS 'Target recipient';
COMMENT ON COLUMN public.inmail_messages.subject IS 'Message subject line';
COMMENT ON COLUMN public.inmail_messages.body IS 'Full message content';
COMMENT ON COLUMN public.inmail_messages.body_preview IS 'First 200 characters for preview';
COMMENT ON COLUMN public.inmail_messages.status IS 'Current delivery/interaction status';
COMMENT ON COLUMN public.inmail_messages.delivered_at IS 'When message was delivered to recipient';
COMMENT ON COLUMN public.inmail_messages.read_at IS 'When recipient read the message';
COMMENT ON COLUMN public.inmail_messages.replied_at IS 'When recipient replied';
COMMENT ON COLUMN public.inmail_messages.is_template_used IS 'Whether a template was used';
COMMENT ON COLUMN public.inmail_messages.expires_at IS 'When message expires if unread';
COMMENT ON COLUMN public.inmail_messages.priority IS 'Message priority (1-5, 5 highest)';
COMMENT ON COLUMN public.inmail_messages.ip_address IS 'Sender IP address for abuse prevention';
COMMENT ON COLUMN public.inmail_messages.user_agent IS 'Sender client for analytics';
COMMENT ON COLUMN public.inmail_messages.metadata IS 'Additional message metadata';
COMMENT ON COLUMN public.inmail_messages.created_by IS 'User who created this message';
COMMENT ON COLUMN public.inmail_messages.updated_by IS 'User who last updated this message';
COMMENT ON COLUMN public.inmail_messages.deleted_at IS 'Soft delete timestamp';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_inmail_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'inmail_messages_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    EXECUTE FORMAT('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.inmail_messages
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create indexes on partition
    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(sender_id, sent_at DESC)',
        'idx_' || partition_name || '_sender', partition_name);

    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(recipient_id, sent_at DESC)',
        'idx_' || partition_name || '_recipient', partition_name);

    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(status, sent_at) WHERE status IN (''SENT'', ''DELIVERED'')',
        'idx_' || partition_name || '_status', partition_name);

    RAISE NOTICE 'Created partition: %', partition_name;
END;
$$ LANGUAGE plpgsql;

-- Create initial partitions
SELECT public.create_inmail_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_inmail_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_inmail_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes (these will be created on parent table but apply to all partitions)
CREATE INDEX idx_inmail_messages_sender ON public.inmail_messages(sender_id, sent_at DESC);
CREATE INDEX idx_inmail_messages_recipient ON public.inmail_messages(recipient_id, sent_at DESC);
CREATE INDEX idx_inmail_messages_status ON public.inmail_messages(status, sent_at)
    WHERE status IN ('SENT', 'DELIVERED', 'READ');
CREATE INDEX idx_inmail_messages_conversation ON public.inmail_messages(conversation_id)
    WHERE conversation_id IS NOT NULL;
CREATE INDEX idx_inmail_messages_expires ON public.inmail_messages(expires_at)
    WHERE expires_at IS NOT NULL AND status NOT IN ('REPLIED', 'EXPIRED');
CREATE INDEX idx_inmail_messages_metadata ON public.inmail_messages USING gin(metadata);

-- Trigger
DROP TRIGGER IF EXISTS update_inmail_messages_timestamp ON public.inmail_messages;
CREATE TRIGGER update_inmail_messages_timestamp
    BEFORE UPDATE ON public.inmail_messages
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.inmail_messages ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS inmail_messages_self_policy ON public.inmail_messages;
CREATE POLICY inmail_messages_self_policy ON public.inmail_messages
    USING (sender_id = public.current_user_id() OR recipient_id = public.current_user_id());

DROP POLICY IF EXISTS inmail_messages_admin_policy ON public.inmail_messages;
CREATE POLICY inmail_messages_admin_policy ON public.inmail_messages
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'moderator', 'support_agent')
        AND ur.deleted_at IS NULL
    ));

