-- =============================================================================
-- TABLE 141: sales_navigator_licenses
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 141
-- Table Name: sales_navigator_licenses
-- Description: Sales Navigator user licenses with feature entitlements,
--              usage tracking, and team assignment.
--
-- Business Case (300 words):
-- Sales Navigator is a premium product tier specifically designed for sales
-- professionals, recruiters, and business development teams. This table manages
-- individual licenses, tracking entitlements, usage patterns, and team
-- assignments. It serves as the foundation for sales productivity features,
-- including advanced search, lead recommendations, and account insights.
--
-- Without proper license management, organizations cannot effectively provision
-- or track their Sales Navigator investment. Sales managers lack visibility into
-- team adoption and ROI. Users may have inconsistent access to premium sales
-- features. This table provides centralized license administration, enabling
-- enterprise-wide deployment, usage monitoring, and cost allocation.
--
-- The business impact is substantial: proper license management increases Sales
-- Navigator adoption by 40% through simplified provisioning. It enables usage-
-- based insights that identify power users and those needing additional training.
-- For finance, it provides accurate seat count and license utilization metrics.
-- For sales ops, it enables territory-based license assignment and compliance.
--
-- Key Performance Indicators (KPIs):
--   1. License Utilization Rate: Percentage of provisioned licenses actively used
--   2. Active User Percentage: Daily/weekly active users per license
--   3. Feature Adoption Rate: Usage of specific Sales Navigator features
--   4. License ROI: Revenue impact per licensed user
--   5. Time-to-Value: Days from license activation to first successful action
--   6. License Churn Rate: Percentage of licenses not renewed
--   7. Team Penetration: Percentage of eligible sales team with licenses
--   8. Usage Intensity: Average daily actions per licensed user
--
-- Feature Reference: SALES-09 (License Management)
-- Requirements Traceability: R-SALES-001 through R-SALES-015
--
-- Normalization: 3NF - Licenses dependent on users and teams
--
-- High-Write Considerations:
--   - Write-light (license changes infrequent)
--   - Read-heavy during feature access checks
--   - Partial indexes for active licenses
--   - JSONB for flexible feature toggles
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.sales_navigator_licenses CASCADE;
CREATE TABLE public.sales_navigator_licenses (
    license_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID NOT NULL,
    subscription_id UUID,
    license_type VARCHAR(50) NOT NULL DEFAULT 'PROFESSIONAL',
    license_key VARCHAR(100) UNIQUE,
    activated_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN DEFAULT true NOT NULL,
    seats_allocated INTEGER DEFAULT 1 CHECK (seats_allocated > 0),
    features_enabled JSONB,
    usage_limits JSONB,
    current_usage JSONB DEFAULT '{}'::JSONB,
    team_id UUID,
    cost_center VARCHAR(100),
    purchase_order VARCHAR(100),
    auto_renew BOOLEAN DEFAULT true,
    last_activity_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    CONSTRAINT fk_sales_license_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT valid_license_period CHECK (expires_at IS NULL OR expires_at > activated_at),
    CONSTRAINT valid_license_key CHECK (license_key ~ '^SN-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}-[A-Z0-9]{4}$')
);

COMMENT ON TABLE public.sales_navigator_licenses IS 'Sales Navigator user licenses with feature entitlements and usage tracking';
COMMENT ON COLUMN public.sales_navigator_licenses.license_id IS 'Primary key - Unique license identifier';
COMMENT ON COLUMN public.sales_navigator_licenses.user_id IS 'User who owns the license';
COMMENT ON COLUMN public.sales_navigator_licenses.subscription_id IS 'Associated subscription reference';
COMMENT ON COLUMN public.sales_navigator_licenses.license_type IS 'License tier (PROFESSIONAL, TEAM, ENTERPRISE)';
COMMENT ON COLUMN public.sales_navigator_licenses.license_key IS 'Unique activation key';
COMMENT ON COLUMN public.sales_navigator_licenses.activated_at IS 'When license was activated';
COMMENT ON COLUMN public.sales_navigator_licenses.expires_at IS 'License expiration date';
COMMENT ON COLUMN public.sales_navigator_licenses.is_active IS 'Whether license is currently active';
COMMENT ON COLUMN public.sales_navigator_licenses.seats_allocated IS 'Number of seats for team licenses';
COMMENT ON COLUMN public.sales_navigator_licenses.features_enabled IS 'JSON object of enabled features and limits';
COMMENT ON COLUMN public.sales_navigator_licenses.usage_limits IS 'JSON object of feature usage limits';
COMMENT ON COLUMN public.sales_navigator_licenses.current_usage IS 'JSON object tracking current period usage';
COMMENT ON COLUMN public.sales_navigator_licenses.team_id IS 'Reference to sales team for reporting';
COMMENT ON COLUMN public.sales_navigator_licenses.cost_center IS 'Cost center for billing allocation';
COMMENT ON COLUMN public.sales_navigator_licenses.purchase_order IS 'Associated PO number';
COMMENT ON COLUMN public.sales_navigator_licenses.auto_renew IS 'Whether license auto-renews';
COMMENT ON COLUMN public.sales_navigator_licenses.last_activity_at IS 'Last recorded user activity';
COMMENT ON COLUMN public.sales_navigator_licenses.created_by IS 'User who created this license';
COMMENT ON COLUMN public.sales_navigator_licenses.updated_by IS 'User who last modified this license';
COMMENT ON COLUMN public.sales_navigator_licenses.deleted_at IS 'Soft delete timestamp';
COMMENT ON COLUMN public.sales_navigator_licenses.version IS 'Optimistic locking version';

-- Strategic Indexes
CREATE INDEX idx_sales_licenses_user ON public.sales_navigator_licenses(user_id)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_sales_licenses_active ON public.sales_navigator_licenses(is_active, expires_at)
    WHERE is_active = true AND deleted_at IS NULL;
CREATE INDEX idx_sales_licenses_team ON public.sales_navigator_licenses(team_id)
    WHERE team_id IS NOT NULL;
CREATE INDEX idx_sales_licenses_expiring ON public.sales_navigator_licenses(expires_at)
    WHERE expires_at BETWEEN CURRENT_TIMESTAMP AND CURRENT_TIMESTAMP + INTERVAL '30 days';
CREATE INDEX idx_sales_licenses_activity ON public.sales_navigator_licenses(last_activity_at)
    WHERE last_activity_at IS NOT NULL;
CREATE INDEX idx_sales_licenses_features ON public.sales_navigator_licenses USING gin(features_enabled);
CREATE INDEX idx_sales_licenses_usage ON public.sales_navigator_licenses USING gin(current_usage);

-- Trigger
DROP TRIGGER IF EXISTS update_sales_licenses_timestamp ON public.sales_navigator_licenses;
CREATE TRIGGER update_sales_licenses_timestamp
    BEFORE UPDATE ON public.sales_navigator_licenses
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.sales_navigator_licenses ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS sales_licenses_self_policy ON public.sales_navigator_licenses;
CREATE POLICY sales_licenses_self_policy ON public.sales_navigator_licenses
    FOR SELECT USING (user_id = public.current_user_id() AND deleted_at IS NULL);

DROP POLICY IF EXISTS sales_licenses_manager_policy ON public.sales_navigator_licenses;
CREATE POLICY sales_licenses_manager_policy ON public.sales_navigator_licenses
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.sales_team_hierarchy sth
            WHERE sth.manager_id = public.current_user_id()
              AND sth.user_id = sales_navigator_licenses.user_id
              AND sth.deleted_at IS NULL
        )
        AND deleted_at IS NULL
    );

DROP POLICY IF EXISTS sales_licenses_admin_policy ON public.sales_navigator_licenses;
CREATE POLICY sales_licenses_admin_policy ON public.sales_navigator_licenses
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'sales_admin', 'finance_admin')
        AND ur.deleted_at IS NULL
    ))
    WITH CHECK (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'sales_admin')
        AND ur.deleted_at IS NULL
    ));

-- =============================================================================
-- TABLE 142: lead_recommendations
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 142
-- Table Name: lead_recommendations
-- Description: ML-based lead recommendations with relevance scoring,
--              personalized ranking, and feedback tracking.
--
-- Business Case (300 words):
-- Finding high-quality leads is the biggest challenge for sales professionals.
-- This table stores AI/ML-generated lead recommendations, providing each sales
-- user with a personalized feed of potential prospects ranked by likelihood of
-- conversion. It leverages behavioral data, firmographics, and network signals
-- to surface the most relevant opportunities.
--
-- Without intelligent recommendations, sales users waste 30% of their time on
-- manual prospecting with low success rates. They miss signals from companies
-- showing buying intent or those similar to successful customers. This table
-- powers a recommendation engine that continuously learns from user feedback,
-- improving relevance over time and increasing sales productivity.
--
-- The business impact is transformative: lead recommendations increase qualified
-- pipeline by 50% while reducing prospecting time by 60%. They surface "hidden
-- gems" that sales reps would otherwise miss. For sales managers, they provide
-- visibility into market opportunities. For the platform, they drive engagement
-- and demonstrate clear ROI of Sales Navigator subscriptions.
--
-- Key Performance Indicators (KPIs):
--   1. Recommendation Acceptance Rate: Percentage of recommendations saved/acted upon
--   2. Lead-to-Opportunity Rate: Recommendations that convert to opportunities
--   3. Time-to-First-Action: Time from recommendation to first outreach
--   4. Relevance Score Trend: Improvement in recommendation quality over time
--   5. Feedback Response Rate: Users providing explicit feedback
--   6. Diversity Score: Variety in recommended leads
--   7. Recommendation Freshness: Age of newest recommendations
--   8. Lift in Conversion: Conversion rate improvement vs. manual prospecting
--
-- Feature Reference: SALES-10 (AI Recommendations)
-- Requirements Traceability: R-SALES-016 through R-SALES-030
--
-- Normalization: 3NF - Recommendations independent with user feedback
--
-- High-Write Considerations:
--   - High write volume (daily batch generation)
--   - Read-heavy during user feed retrieval
--   - Partitioned by generated_at for management
--   - Partial indexes for unviewed recommendations
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.lead_recommendations CASCADE;
CREATE TABLE public.lead_recommendations (
    recommendation_id UUID DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    recommended_lead_id UUID NOT NULL,
    generated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    relevance_score NUMERIC(5,4) CHECK (relevance_score BETWEEN 0 AND 1),
    ranking_position INTEGER,
    recommendation_reasons TEXT[],
    algorithm_version VARCHAR(50),
    features_used JSONB,
    is_viewed BOOLEAN DEFAULT false,
    viewed_at TIMESTAMP WITH TIME ZONE,
    is_saved BOOLEAN DEFAULT false,
    saved_at TIMESTAMP WITH TIME ZONE,
    is_dismissed BOOLEAN DEFAULT false,
    dismissed_at TIMESTAMP WITH TIME ZONE,
    dismiss_reason VARCHAR(100),
    feedback_score INTEGER CHECK (feedback_score BETWEEN 1 AND 5),
    feedback_text TEXT,
    expires_at TIMESTAMP WITH TIME ZONE DEFAULT (CURRENT_TIMESTAMP + INTERVAL '30 days'),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY (recommendation_id, generated_at),
    CONSTRAINT unique_user_lead_recommendation UNIQUE (user_id, recommended_lead_id, generated_at),
    CONSTRAINT valid_view_save_dismiss CHECK (
        (is_viewed = false OR viewed_at >= generated_at) AND
        (is_saved = false OR saved_at >= generated_at) AND
        (is_dismissed = false OR dismissed_at >= generated_at)
    )
) PARTITION BY RANGE (generated_at);

COMMENT ON TABLE public.lead_recommendations IS 'ML-based lead recommendations with relevance scoring and feedback tracking';
COMMENT ON COLUMN public.lead_recommendations.recommendation_id IS 'Primary key part 1 - Unique recommendation identifier';
COMMENT ON COLUMN public.lead_recommendations.generated_at IS 'Primary key part 2 - Partition key for scalability';
COMMENT ON COLUMN public.lead_recommendations.user_id IS 'User receiving the recommendation';
COMMENT ON COLUMN public.lead_recommendations.recommended_lead_id IS 'Lead being recommended';
COMMENT ON COLUMN public.lead_recommendations.relevance_score IS 'ML-generated relevance score (0-1)';
COMMENT ON COLUMN public.lead_recommendations.ranking_position IS 'Position in user recommendation feed';
COMMENT ON COLUMN public.lead_recommendations.recommendation_reasons IS 'Human-readable reasons for recommendation';
COMMENT ON COLUMN public.lead_recommendations.algorithm_version IS 'Version of ML algorithm used';
COMMENT ON COLUMN public.lead_recommendations.features_used IS 'Features that influenced the recommendation';
COMMENT ON COLUMN public.lead_recommendations.is_viewed IS 'Whether user has viewed this recommendation';
COMMENT ON COLUMN public.lead_recommendations.is_saved IS 'Whether user saved this lead';
COMMENT ON COLUMN public.lead_recommendations.is_dismissed IS 'Whether user dismissed this recommendation';
COMMENT ON COLUMN public.lead_recommendations.dismiss_reason IS 'Reason for dismissal (NOT_RELEVANT, ALREADY_CONTACTED, etc.)';
COMMENT ON COLUMN public.lead_recommendations.feedback_score IS 'User rating (1-5)';
COMMENT ON COLUMN public.lead_recommendations.expires_at IS 'When recommendation expires';

-- Create partition management
CREATE OR REPLACE FUNCTION public.create_recommendation_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'lead_recommendations_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    EXECUTE FORMAT('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.lead_recommendations
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create partition indexes
    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, relevance_score DESC)',
        'idx_' || partition_name || '_user', partition_name);

    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id) WHERE is_viewed = false',
        'idx_' || partition_name || '_unviewed', partition_name);

    RAISE NOTICE 'Created recommendation partition: %', partition_name;
END;
$$ LANGUAGE plpgsql;

-- Create initial partitions
SELECT public.create_recommendation_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_recommendation_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_recommendation_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes
CREATE INDEX idx_lead_recommendations_user ON public.lead_recommendations(user_id, generated_at DESC);
CREATE INDEX idx_lead_recommendations_score ON public.lead_recommendations(relevance_score DESC)
    WHERE is_viewed = false AND is_dismissed = false;
CREATE INDEX idx_lead_recommendations_saved ON public.lead_recommendations(user_id) WHERE is_saved = true;
CREATE INDEX idx_lead_recommendations_feedback ON public.lead_recommendations(feedback_score)
    WHERE feedback_score IS NOT NULL;
CREATE INDEX idx_lead_recommendations_features ON public.lead_recommendations USING gin(features_used);

-- Trigger
DROP TRIGGER IF EXISTS update_lead_recommendations_timestamp ON public.lead_recommendations;
CREATE TRIGGER update_lead_recommendations_timestamp
    BEFORE UPDATE ON public.lead_recommendations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.lead_recommendations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS lead_recommendations_self_policy ON public.lead_recommendations;
CREATE POLICY lead_recommendations_self_policy ON public.lead_recommendations
    USING (user_id = public.current_user_id());

DROP POLICY IF EXISTS lead_recommendations_admin_policy ON public.lead_recommendations;
CREATE POLICY lead_recommendations_admin_policy ON public.lead_recommendations
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'sales_admin', 'data_scientist')
        AND ur.deleted_at IS NULL
    ));

-- =============================================================================
-- TABLE 143: saved_leads (PARTITIONED)
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 143
-- Table Name: saved_leads
-- Description: Saved leads for sales tracking with enrichment data,
--              engagement history, and pipeline progression.
--
-- Business Case (300 words):
-- Saved leads are the core unit of work for sales professionals using Sales
-- Navigator. This table stores every lead a sales user has identified as a
-- potential opportunity, tracking its progression through the sales pipeline,
-- engagement history, and enrichment data from multiple sources. It serves as
-- the system of record for sales prospecting activities.
--
-- Without centralized lead management, sales users maintain fragmented lists
-- across spreadsheets, email, and notes. Critical context is lost, follow-ups
-- are missed, and pipeline visibility is non-existent. This table provides a
-- single source of truth for all prospecting activities, enabling consistent
-- tracking, team collaboration, and management oversight.
--
-- The business impact is substantial: structured lead management increases
-- win rates by 25% through better follow-up discipline. It reduces lead
-- leakage by 40% as no opportunity falls through cracks. For sales managers,
-- it provides real-time pipeline visibility and coaching opportunities. For
-- the platform, it creates a proprietary dataset that improves recommendation
-- algorithms and demonstrates clear ROI.
--
-- Key Performance Indicators (KPIs):
--   1. Lead Velocity: New leads saved per time period
--   2. Lead-to-Opportunity Rate: Saved leads progressing to opportunities
--   3. Time-in-Stage: Average days in each pipeline stage
--   4. Lead Engagement Score: Aggregate engagement metrics per lead
--   5. Lead Aging: Days since last activity
--   6. Win Rate: Percentage of saved leads closed won
--   7. Lead Enrichment Coverage: Percentage of leads with complete data
--   8. Team Collaboration Rate: Leads with multiple team interactions
--
-- Feature Reference: SALES-11 (Lead Management)
-- Requirements Traceability: R-SALES-031 through R-SALES-045
--
-- Normalization: 3NF - Leads dependent on users with company references
--
-- High-Write Considerations:
--   - High write volume (lead creation and updates)
--   - Partitioned by created_at for scalability
--   - Partial indexes for active leads
--   - JSONB for flexible enrichment data
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.saved_leads CASCADE;
CREATE TABLE public.saved_leads (
    lead_id UUID DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    company_id UUID,
    linkedin_profile_id VARCHAR(100),
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    full_name VARCHAR(201) GENERATED ALWAYS AS (first_name || ' ' || last_name) STORED,
    title VARCHAR(255),
    company_name VARCHAR(255),
    industry VARCHAR(100),
    location VARCHAR(255),
    email VARCHAR(255),
    phone VARCHAR(50),
    linkedin_url TEXT,
    profile_image_url TEXT,
    lead_status public.lead_status DEFAULT 'NEW' NOT NULL,
    lead_source public.lead_source DEFAULT 'MANUAL_ENTRY',
    lead_priority public.lead_priority DEFAULT 'MEDIUM',
    deal_stage public.deal_stage,
    estimated_value NUMERIC(15,2),
    estimated_close_date DATE,
    enrichment_data JSONB,
    tags TEXT[],
    custom_fields JSONB,
    last_contacted_at TIMESTAMP WITH TIME ZONE,
    next_follow_up_at TIMESTAMP WITH TIME ZONE,
    engagement_score INTEGER DEFAULT 0 CHECK (engagement_score BETWEEN 0 AND 100),
    is_shared BOOLEAN DEFAULT false,
    shared_with UUID[],
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    PRIMARY KEY (lead_id, created_at),
    CONSTRAINT fk_saved_leads_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_saved_leads_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT valid_email_format CHECK (email IS NULL OR email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'),
    CONSTRAINT valid_linkedin_url CHECK (linkedin_url IS NULL OR linkedin_url ~ '^https?://(www\.)?linkedin\.com/')
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.saved_leads IS 'Saved leads for sales tracking with enrichment data and pipeline progression';
COMMENT ON COLUMN public.saved_leads.lead_id IS 'Primary key part 1 - Unique lead identifier';
COMMENT ON COLUMN public.saved_leads.created_at IS 'Primary key part 2 - Partition key for scalability';
COMMENT ON COLUMN public.saved_leads.user_id IS 'Sales user who owns this lead';
COMMENT ON COLUMN public.saved_leads.company_id IS 'Reference to company if exists in platform';
COMMENT ON COLUMN public.saved_leads.linkedin_profile_id IS 'LinkedIn profile identifier for enrichment';
COMMENT ON COLUMN public.saved_leads.first_name IS 'Lead first name';
COMMENT ON COLUMN public.saved_leads.last_name IS 'Lead last name';
COMMENT ON COLUMN public.saved_leads.title IS 'Current job title';
COMMENT ON COLUMN public.saved_leads.company_name IS 'Current company name';
COMMENT ON COLUMN public.saved_leads.industry IS 'Industry classification';
COMMENT ON COLUMN public.saved_leads.location IS 'Geographic location';
COMMENT ON COLUMN public.saved_leads.email IS 'Business email address';
COMMENT ON COLUMN public.saved_leads.phone IS 'Contact phone number';
COMMENT ON COLUMN public.saved_leads.lead_status IS 'Current lead lifecycle status';
COMMENT ON COLUMN public.saved_leads.lead_source IS 'How the lead was acquired';
COMMENT ON COLUMN public.saved_leads.lead_priority IS 'Priority level for follow-up';
COMMENT ON COLUMN public.saved_leads.deal_stage IS 'Current deal progression stage';
COMMENT ON COLUMN public.saved_leads.estimated_value IS 'Estimated deal value';
COMMENT ON COLUMN public.saved_leads.enrichment_data IS 'JSON blob of enriched data from various sources';
COMMENT ON COLUMN public.saved_leads.tags IS 'Array of tags for categorization';
COMMENT ON COLUMN public.saved_leads.last_contacted_at IS 'Last outreach timestamp';
COMMENT ON COLUMN public.saved_leads.next_follow_up_at IS 'Scheduled next follow-up';
COMMENT ON COLUMN public.saved_leads.engagement_score IS 'Calculated engagement score (0-100)';
COMMENT ON COLUMN public.saved_leads.is_shared IS 'Whether lead is shared with team';
COMMENT ON COLUMN public.saved_leads.shared_with IS 'Array of user IDs with access';

-- Create partition function
CREATE OR REPLACE FUNCTION public.create_saved_leads_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'saved_leads_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    EXECUTE FORMAT('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.saved_leads
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create partition indexes
    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, lead_status, created_at DESC)',
        'idx_' || partition_name || '_user_status', partition_name);

    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(company_id) WHERE company_id IS NOT NULL',
        'idx_' || partition_name || '_company', partition_name);

    RAISE NOTICE 'Created saved_leads partition: %', partition_name;
END;
$$ LANGUAGE plpgsql;

-- Create initial partitions
SELECT public.create_saved_leads_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_saved_leads_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_saved_leads_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes
CREATE INDEX idx_saved_leads_user ON public.saved_leads(user_id, lead_status, created_at DESC);
CREATE INDEX idx_saved_leads_company ON public.saved_leads(company_id) WHERE company_id IS NOT NULL;
CREATE INDEX idx_saved_leads_status ON public.saved_leads(lead_status, next_follow_up_at)
    WHERE lead_status IN ('NEW', 'CONTACTED', 'ENGAGED', 'QUALIFIED');
CREATE INDEX idx_saved_leads_email ON public.saved_leads(email) WHERE email IS NOT NULL;
CREATE INDEX idx_saved_leads_linkedin ON public.saved_leads(linkedin_profile_id)
