CREATE INDEX idx_saved_leads_follow_up ON public.saved_leads(user_id, next_follow_up_at)
    WHERE next_follow_up_at IS NOT NULL;
CREATE INDEX idx_saved_leads_tags ON public.saved_leads USING gin(tags);
CREATE INDEX idx_saved_leads_enrichment ON public.saved_leads USING gin(enrichment_data);
CREATE INDEX idx_saved_leads_fulltext ON public.saved_leads USING gin(
    to_tsvector('english', COALESCE(first_name,'') || ' ' || COALESCE(last_name,'') || ' ' || COALESCE(company_name,''))
);

-- Trigger
DROP TRIGGER IF EXISTS update_saved_leads_timestamp ON public.saved_leads;
