    BEFORE UPDATE ON public.saved_leads
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.saved_leads ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS saved_leads_owner_policy ON public.saved_leads;
CREATE POLICY saved_leads_owner_policy ON public.saved_leads
    USING (user_id = public.current_user_id() AND deleted_at IS NULL)
    WITH CHECK (user_id = public.current_user_id());

DROP POLICY IF EXISTS saved_leads_shared_policy ON public.saved_leads;
CREATE POLICY saved_leads_shared_policy ON public.saved_leads
    FOR SELECT USING (
        is_shared = true
        AND public.current_user_id() = ANY(shared_with)
        AND deleted_at IS NULL
    );

DROP POLICY IF EXISTS saved_leads_manager_policy ON public.saved_leads;
CREATE POLICY saved_leads_manager_policy ON public.saved_leads
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.sales_team_hierarchy sth
            WHERE sth.manager_id = public.current_user_id()
              AND sth.user_id = saved_leads.user_id
              AND sth.deleted_at IS NULL
        )
        AND deleted_at IS NULL
    );

