COMMENT ON COLUMN public.saved_accounts.team_members IS 'Array of team members collaborating';
COMMENT ON COLUMN public.saved_accounts.total_contacts IS 'Number of contacts identified';
COMMENT ON COLUMN public.saved_accounts.active_opportunities IS 'Count of active deals';
COMMENT ON COLUMN public.saved_accounts.total_pipeline_value IS 'Sum of all opportunity values';
COMMENT ON COLUMN public.saved_accounts.last_activity_at IS 'Last engagement timestamp';
COMMENT ON COLUMN public.saved_accounts.next_review_at IS 'Scheduled account review';
COMMENT ON COLUMN public.saved_accounts.account_insights IS 'JSON with account intelligence';
COMMENT ON COLUMN public.saved_accounts.enrichment_data IS 'External data enrichment';
COMMENT ON COLUMN public.saved_accounts.tags IS 'Categorization tags';
COMMENT ON COLUMN public.saved_accounts.is_favorite IS 'Marked as priority account';

-- Strategic Indexes
CREATE INDEX idx_saved_accounts_user ON public.saved_accounts(user_id, account_status)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_saved_accounts_owner ON public.saved_accounts(account_owner_id)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_saved_accounts_company ON public.saved_accounts(company_id)
    WHERE company_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX idx_saved_accounts_relationship ON public.saved_accounts(relationship_type, account_status)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_saved_accounts_review ON public.saved_accounts(next_review_at)
    WHERE next_review_at IS NOT NULL AND account_status NOT IN ('WON', 'LOST');
CREATE INDEX idx_saved_accounts_strategic ON public.saved_accounts(strategic_value DESC)
    WHERE strategic_value >= 7 AND deleted_at IS NULL;
CREATE INDEX idx_saved_accounts_favorite ON public.saved_accounts(user_id)
    WHERE is_favorite = true AND deleted_at IS NULL;
CREATE INDEX idx_saved_accounts_team ON public.saved_accounts USING gin(team_members);
CREATE INDEX idx_saved_accounts_tags ON public.saved_accounts USING gin(tags);
CREATE INDEX idx_saved_accounts_insights ON public.saved_accounts USING gin(account_insights);
CREATE INDEX idx_saved_accounts_fulltext ON public.saved_accounts USING gin(
    to_tsvector('english', company_name || ' ' || COALESCE(industry,''))
);

-- Trigger
DROP TRIGGER IF EXISTS update_saved_accounts_timestamp ON public.saved_accounts;
CREATE TRIGGER update_saved_accounts_timestamp
    BEFORE UPDATE ON public.saved_accounts
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.saved_accounts ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS saved_accounts_owner_policy ON public.saved_accounts;
CREATE POLICY saved_accounts_owner_policy ON public.saved_accounts
    USING (user_id = public.current_user_id() AND deleted_at IS NULL)
    WITH CHECK (user_id = public.current_user_id());

DROP POLICY IF EXISTS saved_accounts_team_policy ON public.saved_accounts;
CREATE POLICY saved_accounts_team_policy ON public.saved_accounts
    FOR SELECT USING (
        public.current_user_id() = account_owner_id
        OR public.current_user_id() = ANY(team_members)
        AND deleted_at IS NULL
    );

DROP POLICY IF EXISTS saved_accounts_manager_policy ON public.saved_accounts;
CREATE POLICY saved_accounts_manager_policy ON public.saved_accounts
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.sales_team_hierarchy sth
            WHERE sth.manager_id = public.current_user_id()
