-- TABLE 145: lead_lists
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 145
-- Table Name: lead_lists
-- Description: Custom lead lists for organizing prospects into targeted
--              campaigns, territories, or priority groupings.
--
-- Business Case (300 words):
-- Effective sales prospecting requires organization. Sales professionals create
-- multiple lists to segment leads by industry, campaign, territory, or priority.
-- This table stores list definitions, enabling users to organize thousands of
-- leads into manageable, actionable groupings that can be worked systematically.
--
-- Without list management, sales users struggle to prioritize their outreach
-- across large prospect pools. Important leads get buried. Campaign tracking
-- becomes impossible. Territory management is chaotic. This table provides the
-- organizational layer that transforms a flat list of leads into strategic
-- portfolios that can be worked methodically.
--
-- The business impact is direct: list-based selling increases productivity by
-- 45% through focused, batch-oriented workflows. It enables territory planning
-- and load balancing. For marketing, it supports targeted nurture campaigns.
-- For sales ops, it provides visibility into prospect segmentation and coverage.
-- Lists can be shared, cloned, and analyzed for best practices.
--
-- Key Performance Indicators (KPIs):
--   1. List Creation Rate: New lists created per user
--   2. List Utilization: Percentage of leads organized into lists
--   3. List Workthrough Rate: Percentage of list leads contacted
--   4. List Conversion Rate: Conversion by list
--   5. List Sharing Rate: Lists shared with team members
--   6. Dynamic List Usage: Adoption of smart/dynamic lists
--   7. List Freshness: Average age of leads in active lists
--   8. List ROI: Revenue impact per list campaign
--
-- Feature Reference: SALES-13 (List Management)
-- Requirements Traceability: R-SALES-061 through R-SALES-075
--
-- Normalization: 3NF - Lists dependent on users
--
-- High-Write Considerations:
--   - Moderate write volume (list creation/updates)
--   - Read-heavy during lead browsing and filtering
--   - JSONB for dynamic list criteria
--   - Partial indexes for shared lists
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.lead_lists CASCADE;
CREATE TABLE public.lead_lists (
    list_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID NOT NULL,
    name VARCHAR(255) NOT NULL,
    description TEXT,
    list_type VARCHAR(50) DEFAULT 'STATIC',
    dynamic_criteria JSONB,
    color VARCHAR(7),
    icon VARCHAR(50),
    is_shared BOOLEAN DEFAULT false,
    shared_with UUID[],
    is_default BOOLEAN DEFAULT false,
    lead_count INTEGER DEFAULT 0,
    last_updated_at TIMESTAMP WITH TIME ZONE,
    sort_order INTEGER DEFAULT 0,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_lead_lists_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT unique_user_list_name UNIQUE (user_id, name, deleted_at),
    CONSTRAINT valid_color CHECK (color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$')
);

COMMENT ON TABLE public.lead_lists IS 'Custom lead lists for organizing prospects into targeted groupings';
COMMENT ON COLUMN public.lead_lists.list_id IS 'Primary key - Unique list identifier';
COMMENT ON COLUMN public.lead_lists.user_id IS 'Owner of the list';
COMMENT ON COLUMN public.lead_lists.name IS 'List display name';
COMMENT ON COLUMN public.lead_lists.description IS 'Optional list description';
COMMENT ON COLUMN public.lead_lists.list_type IS 'STATIC or DYNAMIC (smart list)';
COMMENT ON COLUMN public.lead_lists.dynamic_criteria IS 'JSON criteria for dynamic list population';
COMMENT ON COLUMN public.lead_lists.color IS 'Hex color code for UI display';
COMMENT ON COLUMN public.lead_lists.icon IS 'Icon identifier for UI';
COMMENT ON COLUMN public.lead_lists.is_shared IS 'Whether list is shared with team';
COMMENT ON COLUMN public.lead_lists.shared_with IS 'Array of user IDs with access';
COMMENT ON COLUMN public.lead_lists.is_default IS 'Whether this is a system default list';
COMMENT ON COLUMN public.lead_lists.lead_count IS 'Cached count of leads in list';
COMMENT ON COLUMN public.lead_lists.last_updated_at IS 'When list contents last changed';
COMMENT ON COLUMN public.lead_lists.sort_order IS 'Display order among user lists';
COMMENT ON COLUMN public.lead_lists.metadata IS 'Additional list metadata';

-- Strategic Indexes
CREATE INDEX idx_lead_lists_user ON public.lead_lists(user_id, sort_order)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_lead_lists_shared ON public.lead_lists(is_shared)
    WHERE is_shared = true AND deleted_at IS NULL;
CREATE INDEX idx_lead_lists_type ON public.lead_lists(list_type)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_lead_lists_dynamic ON public.lead_lists USING gin(dynamic_criteria)
    WHERE list_type = 'DYNAMIC';
CREATE INDEX idx_lead_lists_shared_with ON public.lead_lists USING gin(shared_with);

-- Trigger
DROP TRIGGER IF EXISTS update_lead_lists_timestamp ON public.lead_lists;
CREATE TRIGGER update_lead_lists_timestamp
    BEFORE UPDATE ON public.lead_lists
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.lead_lists ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS lead_lists_owner_policy ON public.lead_lists;
CREATE POLICY lead_lists_owner_policy ON public.lead_lists
    USING (user_id = public.current_user_id() AND deleted_at IS NULL)
    WITH CHECK (user_id = public.current_user_id());

DROP POLICY IF EXISTS lead_lists_shared_policy ON public.lead_lists;
CREATE POLICY lead_lists_shared_policy ON public.lead_lists
    FOR SELECT USING (
        is_shared = true
        AND public.current_user_id() = ANY(shared_with)
        AND deleted_at IS NULL
    );

