-- TABLE 146: lead_list_members
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 146
-- Table Name: lead_list_members
-- Description: Junction table linking leads to lists with membership metadata,
--              addition tracking, and engagement context.
--
-- Business Case (300 words):
-- Lists are only valuable when populated with relevant leads. This junction
-- table manages the many-to-many relationship between leads and lists, tracking
-- when leads were added, by whom, and any list-specific context. It enables
-- flexible list management while maintaining full audit trails of membership
-- changes.
--
-- Without proper membership tracking, list management becomes unreliable.
-- Duplicate additions cause confusion. Removal auditing is impossible. Campaign
-- attribution breaks down. This table provides the foundation for trustworthy
-- list operations, enabling users to confidently manage their prospect
-- portfolios and track list effectiveness over time.
--
-- The business impact is foundational: accurate list membership enables reliable
-- campaign execution and measurement. It supports list-based workflows where
-- users systematically work through prioritized lead sets. For analytics, it
-- enables list performance comparison. For compliance, it maintains audit trails
-- of prospect data handling.
--
-- Key Performance Indicators (KPIs):
--   1. Membership Churn: Leads added vs. removed from lists
--   2. List Growth Rate: New members added per time period
--   3. Cross-list Membership: Leads appearing in multiple lists
--   4. List Workthrough: Members marked as contacted/completed
--   5. Time-in-List: Average duration before action/removal
--   6. Manual vs. Auto-Add: Percentage added via dynamic criteria
--   7. List Purity: Percentage of valid/active leads in lists
--   8. Membership Source: How leads entered lists
--
-- Feature Reference: SALES-14 (List Membership)
-- Requirements Traceability: R-SALES-076 through R-SALES-085
--
-- Normalization: 3NF - Junction table with membership attributes
--
-- High-Write Considerations:
--   - High write volume (bulk additions/removals)
--   - Read-heavy during list viewing and filtering
--   - Composite indexes for list queries
--   - Partial indexes for active members
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.lead_list_members CASCADE;
CREATE TABLE public.lead_list_members (
    membership_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    list_id UUID NOT NULL,
    lead_id UUID NOT NULL,
    added_by UUID,
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    added_source VARCHAR(100),
    sort_position INTEGER,
    notes TEXT,
    custom_fields JSONB,
    is_active BOOLEAN DEFAULT true,
    removed_at TIMESTAMP WITH TIME ZONE,
    removed_by UUID,
    removal_reason VARCHAR(100),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_list_members_list FOREIGN KEY (list_id)
        REFERENCES public.lead_lists(list_id) ON DELETE CASCADE,
    CONSTRAINT fk_list_members_lead FOREIGN KEY (lead_id)
        REFERENCES public.saved_leads(lead_id) ON DELETE CASCADE,
    CONSTRAINT fk_list_members_added_by FOREIGN KEY (added_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_list_members_removed_by FOREIGN KEY (removed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT unique_list_lead UNIQUE (list_id, lead_id)
);

COMMENT ON TABLE public.lead_list_members IS 'Junction table linking leads to lists with membership metadata';
COMMENT ON COLUMN public.lead_list_members.membership_id IS 'Primary key - Unique membership identifier';
COMMENT ON COLUMN public.lead_list_members.list_id IS 'Reference to lead list';
COMMENT ON COLUMN public.lead_list_members.lead_id IS 'Reference to lead';
COMMENT ON COLUMN public.lead_list_members.added_by IS 'User who added the lead';
COMMENT ON COLUMN public.lead_list_members.added_at IS 'When lead was added to list';
COMMENT ON COLUMN public.lead_list_members.added_source IS 'How lead was added (manual, import, dynamic)';
COMMENT ON COLUMN public.lead_list_members.sort_position IS 'Custom ordering within list';
COMMENT ON COLUMN public.lead_list_members.notes IS 'List-specific notes about this lead';
COMMENT ON COLUMN public.lead_list_members.custom_fields IS 'List-specific custom field values';
COMMENT ON COLUMN public.lead_list_members.is_active IS 'Whether membership is active';
COMMENT ON COLUMN public.lead_list_members.removed_at IS 'When lead was removed from list';
COMMENT ON COLUMN public.lead_list_members.removed_by IS 'User who removed the lead';
COMMENT ON COLUMN public.lead_list_members.removal_reason IS 'Reason for removal';

-- Strategic Indexes
CREATE INDEX idx_list_members_list ON public.lead_list_members(list_id, added_at DESC)
    WHERE is_active = true;
CREATE INDEX idx_list_members_lead ON public.lead_list_members(lead_id)
    WHERE is_active = true;
CREATE INDEX idx_list_members_added_by ON public.lead_list_members(added_by, added_at DESC);
CREATE INDEX idx_list_members_active ON public.lead_list_members(list_id)
    WHERE is_active = true;
CREATE INDEX idx_list_members_custom ON public.lead_list_members USING gin(custom_fields);

-- Trigger
DROP TRIGGER IF EXISTS update_lead_list_members_timestamp ON public.lead_list_members;
CREATE TRIGGER update_lead_list_members_timestamp
    BEFORE UPDATE ON public.lead_list_members
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update list lead count
CREATE OR REPLACE FUNCTION public.update_list_lead_count()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.is_active THEN
        UPDATE public.lead_lists
        SET lead_count = lead_count + 1,
            last_updated_at = CURRENT_TIMESTAMP
        WHERE list_id = NEW.list_id;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.is_active = true AND NEW.is_active = false THEN
            UPDATE public.lead_lists
            SET lead_count = lead_count - 1,
                last_updated_at = CURRENT_TIMESTAMP
            WHERE list_id = NEW.list_id;
        ELSIF OLD.is_active = false AND NEW.is_active = true THEN
            UPDATE public.lead_lists
            SET lead_count = lead_count + 1,
                last_updated_at = CURRENT_TIMESTAMP
            WHERE list_id = NEW.list_id;
        END IF;
    ELSIF TG_OP = 'DELETE' AND OLD.is_active THEN
        UPDATE public.lead_lists
        SET lead_count = lead_count - 1,
            last_updated_at = CURRENT_TIMESTAMP
        WHERE list_id = OLD.list_id;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_list_count ON public.lead_list_members;
CREATE TRIGGER trigger_update_list_count
    AFTER INSERT OR UPDATE OR DELETE ON public.lead_list_members
    FOR EACH ROW EXECUTE FUNCTION public.update_list_lead_count();

-- RLS
ALTER TABLE public.lead_list_members ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS lead_list_members_owner_policy ON public.lead_list_members;
CREATE POLICY lead_list_members_owner_policy ON public.lead_list_members
    USING (
        EXISTS (
            SELECT 1 FROM public.lead_lists ll
            WHERE ll.list_id = lead_list_members.list_id
              AND ll.user_id = public.current_user_id()
              AND ll.deleted_at IS NULL
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.lead_lists ll
            WHERE ll.list_id = lead_list_members.list_id
              AND ll.user_id = public.current_user_id()
              AND ll.deleted_at IS NULL
        )
    );

DROP POLICY IF EXISTS lead_list_members_shared_policy ON public.lead_list_members;
CREATE POLICY lead_list_members_shared_policy ON public.lead_list_members
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.lead_lists ll
            WHERE ll.list_id = lead_list_members.list_id
              AND ll.is_shared = true
              AND public.current_user_id() = ANY(ll.shared_with)
              AND ll.deleted_at IS NULL
        )
    );

