-- FUNCTIONS FOR SALES NAVIGATOR
-- =============================================================================

-------------------------------------------------------------------------------
-- Function: calculate_lead_score
-- Description: ML-based lead scoring using multiple signals
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.calculate_lead_score(
    p_lead_id UUID
)
RETURNS INTEGER AS $$
DECLARE
    v_score INTEGER := 0;
    v_lead_record RECORD;
BEGIN
    -- Get lead details
    SELECT * INTO v_lead_record
    FROM public.saved_leads
    WHERE lead_id = p_lead_id;

    IF v_lead_record.lead_id IS NULL THEN
        RETURN 0;
    END IF;

    -- Title scoring (C-level = +30, VP = +20, Director = +15, Manager = +10)
    IF v_lead_record.title ~* 'CEO|CFO|CTO|CIO|COO|President|Founder' THEN
        v_score := v_score + 30;
    ELSIF v_lead_record.title ~* 'VP|Vice President' THEN
        v_score := v_score + 20;
    ELSIF v_lead_record.title ~* 'Director|Head of' THEN
        v_score := v_score + 15;
    ELSIF v_lead_record.title ~* 'Manager|Lead' THEN
        v_score := v_score + 10;
    END IF;

    -- Company size scoring
    IF v_lead_record.enrichment_data->>'employee_count' IS NOT NULL THEN
        IF (v_lead_record.enrichment_data->>'employee_count')::INTEGER > 1000 THEN
            v_score := v_score + 25;
        ELSIF (v_lead_record.enrichment_data->>'employee_count')::INTEGER > 100 THEN
            v_score := v_score + 15;
        END IF;
    END IF;

    -- Industry fit (configurable)
    IF v_lead_record.industry = ANY(ARRAY['Technology', 'Software', 'SaaS', 'Financial Services']) THEN
        v_score := v_score + 20;
    END IF;

    -- Recent activity signals
    IF v_lead_record.last_contacted_at > NOW() - INTERVAL '7 days' THEN
        v_score := v_score + 15;
    END IF;

    -- Engagement score from activities
    SELECT COALESCE(COUNT(*) * 5, 0) INTO v_score
    FROM public.sales_activities
    WHERE lead_id = p_lead_id
      AND activity_date > NOW() - INTERVAL '30 days';

    v_score := LEAST(v_score, 100);

    -- Update the lead's engagement score
    UPDATE public.saved_leads
    SET engagement_score = v_score,
        updated_at = NOW()
    WHERE lead_id = p_lead_id;

    RETURN v_score;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.calculate_lead_score(UUID) IS 'ML-based lead scoring using multiple signals and enrichment data';

-------------------------------------------------------------------------------
-- Function: track_sales_activity
-- Description: Track sales activities with validation and lead updates
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.track_sales_activity(
    p_user_id UUID,
    p_lead_id UUID DEFAULT NULL,
    p_account_id UUID DEFAULT NULL,
    p_activity_type public.sales_activity_type,
    p_activity_date TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    p_subject VARCHAR(500) DEFAULT NULL,
    p_description TEXT DEFAULT NULL,
    p_outcome VARCHAR(100) DEFAULT NULL,
    p_duration_minutes INTEGER DEFAULT NULL,
    p_metadata JSONB DEFAULT '{}'::JSONB
)
RETURNS UUID AS $$
DECLARE
    v_activity_id UUID;
BEGIN
    -- Validate inputs
    IF p_lead_id IS NULL AND p_account_id IS NULL THEN
        RAISE EXCEPTION 'Either lead_id or account_id must be provided';
    END IF;

    IF p_duration_minutes IS NOT NULL AND p_duration_minutes <= 0 THEN
        RAISE EXCEPTION 'Duration must be positive';
    END IF;

    -- Insert activity
    INSERT INTO public.sales_activities (
        user_id, lead_id, account_id, activity_type, activity_date,
        subject, description, outcome, duration_minutes, metadata,
        created_by, updated_by
    ) VALUES (
        p_user_id, p_lead_id, p_account_id, p_activity_type, p_activity_date,
        p_subject, p_description, p_outcome, p_duration_minutes, p_metadata,
        p_user_id, p_user_id
    ) RETURNING activity_id INTO v_activity_id;

    -- Update lead last contacted timestamp
    IF p_lead_id IS NOT NULL THEN
        UPDATE public.saved_leads
        SET last_contacted_at = p_activity_date,
            updated_at = NOW(),
            updated_by = p_user_id
        WHERE lead_id = p_lead_id;

        -- Recalculate lead score
        PERFORM public.calculate_lead_score(p_lead_id);
    END IF;

    -- Update account last activity
    IF p_account_id IS NOT NULL THEN
        UPDATE public.saved_accounts
        SET last_activity_at = p_activity_date,
            updated_at = NOW(),
            updated_by = p_user_id
        WHERE account_id = p_account_id;
    END IF;

    -- Update license last activity
    UPDATE public.sales_navigator_licenses
    SET last_activity_at = p_activity_date,
        updated_at = NOW()
    WHERE user_id = p_user_id
      AND is_active = true
      AND deleted_at IS NULL;

    RETURN v_activity_id;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Failed to track sales activity: %', SQLERRM;
        RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.track_sales_activity(UUID, UUID, UUID, public.sales_activity_type, TIMESTAMP WITH TIME ZONE, VARCHAR, TEXT, VARCHAR, INTEGER, JSONB) IS 'Track sales activities with validation and automatic lead/account updates';

