-- TABLE 157: candidate_pipeline_stages
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 157
-- Table Name: candidate_pipeline_stages
-- Description: Custom pipeline stage definitions for recruiting workflows,
--              with configurable transitions, SLAs, and automation rules.
--
-- Business Case (300 words):
-- Every organization has unique recruiting processes. This table enables
-- recruiters and HR leaders to define custom pipeline stages that reflect
-- their specific hiring workflows. It supports stage ordering, transition
-- rules, service level agreements (SLAs) for time-in-stage, and automation
-- triggers that streamline candidate progression.
--
-- Without customizable pipelines, recruiters must adapt their processes to
-- rigid, one-size-fits-all stages. Important steps are missed, handoffs are
-- unclear, and compliance requirements are difficult to enforce. This table
-- empowers organizations to model their exact hiring processes, ensuring
-- consistency, compliance, and efficiency across all recruiting activities.
--
-- The business impact is significant: customized pipelines reduce process
-- variance by 70% and improve compliance by 60%. They enable accurate time-to-
-- hire measurement at each stage. Automation rules reduce manual work by 40%
-- through triggered actions (notifications, task creation, candidate
-- communications). SLAs create accountability and highlight bottlenecks
-- requiring attention.
--
-- Key Performance Indicators (KPIs):
--   1. Pipeline Adoption: Projects using custom vs. default pipelines
--   2. Stage Compliance: Candidates progressing through required stages
--   3. SLA Adherence: Stages completed within defined time limits
--   4. Automation Effectiveness: Actions triggered vs. manual
--   5. Pipeline Efficiency: Time saved through automation
--   6. Stage Customization: Unique stages created per organization
--   7. Bottleneck Identification: Stages exceeding SLA thresholds
--   8. Transition Accuracy: Proper stage progression tracking
--   9. Audit Trail Completeness: Stage change documentation
--   10. Process Standardization: Consistency across similar roles
--
-- Feature Reference: RECRUIT-12 (Pipeline Configuration)
-- Requirements Traceability: R-RECRUIT-056 through R-RECRUIT-070
--
-- Normalization: 3NF - Stages dependent on projects or templates
--
-- High-Write Considerations:
--   - Write-light (pipeline definitions change infrequently)
--   - Read-heavy during candidate progression
--   - JSONB for flexible automation rules
--   - Partial indexes for active stages
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.candidate_pipeline_stages CASCADE;
CREATE TABLE public.candidate_pipeline_stages (
    stage_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    project_id UUID,
    template_id UUID,
    stage_name VARCHAR(100) NOT NULL,
    stage_type public.pipeline_stage_type NOT NULL,
    stage_order INTEGER NOT NULL,
    description TEXT,
    is_required BOOLEAN DEFAULT true,
    sla_hours INTEGER,
    auto_advance BOOLEAN DEFAULT false,
    advance_condition JSONB,
    automation_rules JSONB,
    notification_config JSONB,
    color VARCHAR(7),
    icon VARCHAR(50),
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_pipeline_stages_project FOREIGN KEY (project_id)
        REFERENCES public.recruiter_projects(project_id) ON DELETE CASCADE,
    CONSTRAINT unique_project_stage_order UNIQUE (project_id, stage_order, deleted_at),
    CONSTRAINT valid_color CHECK (color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$'),
    CONSTRAINT valid_stage_order CHECK (stage_order >= 0)
);

COMMENT ON TABLE public.candidate_pipeline_stages IS 'Custom pipeline stage definitions for recruiting workflows';
COMMENT ON COLUMN public.candidate_pipeline_stages.stage_id IS 'Primary key - Unique stage identifier';
COMMENT ON COLUMN public.candidate_pipeline_stages.project_id IS 'Project this stage belongs to (NULL for template)';
COMMENT ON COLUMN public.candidate_pipeline_stages.template_id IS 'Template this stage belongs to';
COMMENT ON COLUMN public.candidate_pipeline_stages.stage_name IS 'Display name of stage';
COMMENT ON COLUMN public.candidate_pipeline_stages.stage_type IS 'Standardized stage type for reporting';
COMMENT ON COLUMN public.candidate_pipeline_stages.stage_order IS 'Sequential order in pipeline';
COMMENT ON COLUMN public.candidate_pipeline_stages.description IS 'Stage description and expectations';
COMMENT ON COLUMN public.candidate_pipeline_stages.is_required IS 'Whether stage cannot be skipped';
COMMENT ON COLUMN public.candidate_pipeline_stages.sla_hours IS 'Target hours to complete stage';
COMMENT ON COLUMN public.candidate_pipeline_stages.auto_advance IS 'Whether candidates auto-advance';
COMMENT ON COLUMN public.candidate_pipeline_stages.advance_condition IS 'JSON condition for auto-advance';
COMMENT ON COLUMN public.candidate_pipeline_stages.automation_rules IS 'JSON automation triggers';
COMMENT ON COLUMN public.candidate_pipeline_stages.notification_config IS 'JSON notification settings';
COMMENT ON COLUMN public.candidate_pipeline_stages.color IS 'UI color for stage';
COMMENT ON COLUMN public.candidate_pipeline_stages.icon IS 'UI icon identifier';
COMMENT ON COLUMN public.candidate_pipeline_stages.is_active IS 'Whether stage is active';

-- Strategic Indexes
CREATE INDEX idx_pipeline_stages_project ON public.candidate_pipeline_stages(project_id, stage_order)
    WHERE deleted_at IS NULL AND is_active = true;
CREATE INDEX idx_pipeline_stages_template ON public.candidate_pipeline_stages(template_id, stage_order)
    WHERE template_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX idx_pipeline_stages_type ON public.candidate_pipeline_stages(stage_type);
CREATE INDEX idx_pipeline_stages_automation ON public.candidate_pipeline_stages USING gin(automation_rules);

-- Trigger
DROP TRIGGER IF EXISTS update_pipeline_stages_timestamp ON public.candidate_pipeline_stages;
CREATE TRIGGER update_pipeline_stages_timestamp
    BEFORE UPDATE ON public.candidate_pipeline_stages
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.candidate_pipeline_stages ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS pipeline_stages_access_policy ON public.candidate_pipeline_stages;
CREATE POLICY pipeline_stages_access_policy ON public.candidate_pipeline_stages
    USING (
        deleted_at IS NULL AND (
            EXISTS (
                SELECT 1 FROM public.recruiter_projects rp
                WHERE rp.project_id = candidate_pipeline_stages.project_id
                  AND (rp.owner_id = public.current_user_id()
                       OR public.current_user_id() = ANY(rp.team_members)
                       OR rp.hiring_manager_id = public.current_user_id())
            )
            OR template_id IS NOT NULL
        )
    );

