COMMENT ON COLUMN public.candidate_pipeline_entries.assigned_to IS 'Recruiter assigned to this candidate';
COMMENT ON COLUMN public.candidate_pipeline_entries.priority IS 'Priority level (1-5)';
COMMENT ON COLUMN public.candidate_pipeline_entries.expected_salary IS 'Candidate salary expectation';
COMMENT ON COLUMN public.candidate_pipeline_entries.current_salary IS 'Current salary if known';
COMMENT ON COLUMN public.candidate_pipeline_entries.availability_date IS 'When candidate can start';
