COMMENT ON COLUMN public.candidate_pipeline_entries.visa_required IS 'Visa sponsorship needed';
COMMENT ON COLUMN public.candidate_pipeline_entries.notes_summary IS 'Brief summary of latest notes';
COMMENT ON COLUMN public.candidate_pipeline_entries.custom_fields IS 'Custom field values';
COMMENT ON COLUMN public.candidate_pipeline_entries.tags IS 'Categorization tags';

-- Strategic Indexes
CREATE INDEX idx_pipeline_entries_project ON public.candidate_pipeline_entries(project_id, current_stage_id)
    WHERE deleted_at IS NULL AND current_status NOT IN ('HIRED', 'REJECTED', 'ARCHIVED');
CREATE INDEX idx_pipeline_entries_candidate ON public.candidate_pipeline_entries(candidate_id);
CREATE INDEX idx_pipeline_entries_assigned ON public.candidate_pipeline_entries(assigned_to, current_status)
    WHERE assigned_to IS NOT NULL;
CREATE INDEX idx_pipeline_entries_status ON public.candidate_pipeline_entries(current_status, next_action_due)
    WHERE current_status IN ('NEW', 'CONTACTED', 'RESPONDED', 'SCHEDULED', 'INTERVIEWED');
CREATE INDEX idx_pipeline_entries_source ON public.candidate_pipeline_entries(source);
CREATE INDEX idx_pipeline_entries_priority ON public.candidate_pipeline_entries(priority DESC)
    WHERE current_status NOT IN ('HIRED', 'REJECTED');
CREATE INDEX idx_pipeline_entries_history ON public.candidate_pipeline_entries USING gin(stage_history);
CREATE INDEX idx_pipeline_entries_custom ON public.candidate_pipeline_entries USING gin(custom_fields);
CREATE INDEX idx_pipeline_entries_tags ON public.candidate_pipeline_entries USING gin(tags);

-- Trigger for stage history tracking
CREATE OR REPLACE FUNCTION public.track_stage_history()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.current_stage_id IS DISTINCT FROM NEW.current_stage_id THEN
        NEW.stage_history = NEW.stage_history || jsonb_build_object(
            'stage_id', NEW.current_stage_id,
            'changed_at', NOW(),
            'changed_by', public.current_user_id(),
            'previous_stage_id', OLD.current_stage_id
        );
        NEW.last_activity_at = NOW();

        -- Update project metrics
        UPDATE public.recruiter_projects
        SET updated_at = NOW()
        WHERE project_id = NEW.project_id;
    END IF;

    IF OLD.current_status IS DISTINCT FROM NEW.current_status THEN
        NEW.status_history = NEW.status_history || jsonb_build_object(
            'status', NEW.current_status,
            'changed_at', NOW(),
            'changed_by', public.current_user_id(),
            'previous_status', OLD.current_status
        );
        NEW.last_activity_at = NOW();
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_track_stage_history ON public.candidate_pipeline_entries;
CREATE TRIGGER trigger_track_stage_history
    BEFORE UPDATE ON public.candidate_pipeline_entries
    FOR EACH ROW EXECUTE FUNCTION public.track_stage_history();

-- Trigger
DROP TRIGGER IF EXISTS update_pipeline_entries_timestamp ON public.candidate_pipeline_entries;
CREATE TRIGGER update_pipeline_entries_timestamp
    BEFORE UPDATE ON public.candidate_pipeline_entries
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

