CREATE POLICY pipeline_entries_access_policy ON public.candidate_pipeline_entries
    USING (
        deleted_at IS NULL AND (
            EXISTS (
                SELECT 1 FROM public.recruiter_projects rp
                WHERE rp.project_id = candidate_pipeline_entries.project_id
                  AND (rp.owner_id = public.current_user_id()
                       OR public.current_user_id() = ANY(rp.team_members)
                       OR rp.hiring_manager_id = public.current_user_id()
                       OR candidate_pipeline_entries.assigned_to = public.current_user_id())
            )
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.recruiter_projects rp
            WHERE rp.project_id = candidate_pipeline_entries.project_id
              AND (rp.owner_id = public.current_user_id()
                   OR public.current_user_id() = ANY(rp.team_members)
                   OR candidate_pipeline_entries.assigned_to = public.current_user_id())
        )
    );

-- =============================================================================
-- TABLE 159: candidate_notes
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 159
-- Table Name: candidate_notes
-- Description: Recruiter notes on candidates with @mentions, attachments,
--              and privacy controls for collaborative evaluation.
--
-- Business Case (300 words):
-- Effective candidate evaluation requires capturing observations, insights,
-- and context throughout the hiring process. This table stores all notes from
-- recruiters, hiring managers, and interviewers, creating a comprehensive
-- narrative of candidate interactions and assessments. It supports collaboration
-- through @mentions, file attachments, and configurable privacy levels.
--
-- Without centralized note-taking, critical candidate information is siloed in
-- individual email inboxes, chat messages, or paper notes. Hiring decisions are
-- made with incomplete information. Handoffs between recruiters and hiring
-- managers lose context. This table ensures that all candidate-related
-- information is captured, searchable, and accessible to authorized team members.
--
-- The business impact is substantial: comprehensive notes improve hiring quality
-- by 30% through better-informed decisions. They reduce miscommunication by 50%
-- and enable seamless transitions when recruiters change roles. For compliance,
-- they provide audit trails of candidate interactions. AI-powered analysis of
-- notes can identify patterns in successful hires and common concerns.
--
-- Key Performance Indicators (KPIs):
--   1. Note Frequency: Average notes per candidate
--   2. Collaboration Rate: Notes with @mentions or replies
--   3. Note Completeness: Notes per stage of pipeline
--   4. Time-to-Note: Time from interaction to note creation
--   5. Note Sentiment: Sentiment analysis of notes over time
--   6. Attachment Usage: Frequency of supporting documents
--   7. Note Accessibility: Notes viewed by team members
--   8. Decision Influence: Notes correlated with outcomes
--   9. Privacy Compliance: Private vs. shared note ratio
--   10. Search Effectiveness: Note retrieval success rate
--
-- Feature Reference: RECRUIT-14 (Collaboration & Notes)
-- Requirements Traceability: R-RECRUIT-086 through R-RECRUIT-100
--
-- Normalization: 3NF - Notes dependent on candidates and authors
--
-- High-Write Considerations:
--   - Moderate write volume (note creation)
--   - Read-heavy during candidate reviews
--   - Full-text search for note content
--   - JSONB for rich content and mentions
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.candidate_notes CASCADE;
CREATE TABLE public.candidate_notes (
    note_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    candidate_id UUID NOT NULL,
    project_id UUID,
    pipeline_entry_id UUID,
    author_id UUID NOT NULL,
    note_type VARCHAR(50) DEFAULT 'GENERAL',
    title VARCHAR(255),
    content TEXT NOT NULL,
    content_formatted TEXT,
    mentions UUID[],
    privacy_level VARCHAR(20) DEFAULT 'TEAM',
    attachments JSONB,
    tags TEXT[],
    is_pinned BOOLEAN DEFAULT false,
    is_ai_generated BOOLEAN DEFAULT false,
    sentiment_score NUMERIC(3,2) CHECK (sentiment_score BETWEEN -1 AND 1),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_candidate_notes_candidate FOREIGN KEY (candidate_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_candidate_notes_project FOREIGN KEY (project_id)
        REFERENCES public.recruiter_projects(project_id) ON DELETE SET NULL,
    CONSTRAINT fk_candidate_notes_entry FOREIGN KEY (pipeline_entry_id)
        REFERENCES public.candidate_pipeline_entries(entry_id) ON DELETE SET NULL,
    CONSTRAINT fk_candidate_notes_author FOREIGN KEY (author_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT valid_privacy_level CHECK (privacy_level IN ('PRIVATE', 'TEAM', 'HIRING_TEAM', 'PUBLIC'))
);

COMMENT ON TABLE public.candidate_notes IS 'Recruiter notes on candidates with @mentions, attachments, and privacy controls';
COMMENT ON COLUMN public.candidate_notes.note_id IS 'Primary key - Unique note identifier';
COMMENT ON COLUMN public.candidate_notes.candidate_id IS 'Candidate the note is about';
COMMENT ON COLUMN public.candidate_notes.project_id IS 'Associated project if applicable';
COMMENT ON COLUMN public.candidate_notes.pipeline_entry_id IS 'Associated pipeline entry';
COMMENT ON COLUMN public.candidate_notes.author_id IS 'User who wrote the note';
COMMENT ON COLUMN public.candidate_notes.note_type IS 'Type of note (SCREENING, INTERVIEW, FEEDBACK, GENERAL)';
COMMENT ON COLUMN public.candidate_notes.title IS 'Optional note title';
COMMENT ON COLUMN public.candidate_notes.content IS 'Plain text content';
COMMENT ON COLUMN public.candidate_notes.content_formatted IS 'Rich text/formatted content';
COMMENT ON COLUMN public.candidate_notes.mentions IS 'Array of user IDs mentioned with @';
COMMENT ON COLUMN public.candidate_notes.privacy_level IS 'Who can view this note';
COMMENT ON COLUMN public.candidate_notes.attachments IS 'JSON array of file attachments';
COMMENT ON COLUMN public.candidate_notes.tags IS 'Categorization tags';
COMMENT ON COLUMN public.candidate_notes.is_pinned IS 'Whether note is pinned to top';
COMMENT ON COLUMN public.candidate_notes.is_ai_generated IS 'Whether AI generated this note';
COMMENT ON COLUMN public.candidate_notes.sentiment_score IS 'AI-analyzed sentiment (-1 to 1)';
COMMENT ON COLUMN public.candidate_notes.created_by IS 'User who created this note';
COMMENT ON COLUMN public.candidate_notes.updated_by IS 'User who last modified this note';
COMMENT ON COLUMN public.candidate_notes.deleted_at IS 'Soft delete timestamp';

-- Strategic Indexes
CREATE INDEX idx_candidate_notes_candidate ON public.candidate_notes(candidate_id, created_at DESC)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_candidate_notes_project ON public.candidate_notes(project_id, created_at DESC)
    WHERE project_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX idx_candidate_notes_author ON public.candidate_notes(author_id, created_at DESC);
CREATE INDEX idx_candidate_notes_pinned ON public.candidate_notes(candidate_id)
    WHERE is_pinned = true AND deleted_at IS NULL;
CREATE INDEX idx_candidate_notes_type ON public.candidate_notes(note_type);
CREATE INDEX idx_candidate_notes_mentions ON public.candidate_notes USING gin(mentions);
CREATE INDEX idx_candidate_notes_tags ON public.candidate_notes USING gin(tags);
CREATE INDEX idx_candidate_notes_fulltext ON public.candidate_notes USING gin(
    to_tsvector('english', COALESCE(title,'') || ' ' || content)
);
CREATE INDEX idx_candidate_notes_sentiment ON public.candidate_notes(sentiment_score)
    WHERE sentiment_score IS NOT NULL;

-- Trigger
DROP TRIGGER IF EXISTS update_candidate_notes_timestamp ON public.candidate_notes;
CREATE TRIGGER update_candidate_notes_timestamp
    BEFORE UPDATE ON public.candidate_notes
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.candidate_notes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS candidate_notes_author_policy ON public.candidate_notes;
CREATE POLICY candidate_notes_author_policy ON public.candidate_notes
    USING (author_id = public.current_user_id() AND deleted_at IS NULL)
    WITH CHECK (author_id = public.current_user_id());

DROP POLICY IF EXISTS candidate_notes_team_policy ON public.candidate_notes;
CREATE POLICY candidate_notes_team_policy ON public.candidate_notes
    FOR SELECT USING (
        deleted_at IS NULL AND (
            privacy_level IN ('TEAM', 'HIRING_TEAM', 'PUBLIC') AND
            EXISTS (
                SELECT 1 FROM public.recruiter_projects rp
                WHERE rp.project_id = candidate_notes.project_id
                  AND (rp.owner_id = public.current_user_id()
                       OR public.current_user_id() = ANY(rp.team_members)
                       OR rp.hiring_manager_id = public.current_user_id())
            )
        )
    );

DROP POLICY IF EXISTS candidate_notes_mentioned_policy ON public.candidate_notes;
CREATE POLICY candidate_notes_mentioned_policy ON public.candidate_notes
    FOR SELECT USING (
        public.current_user_id() = ANY(mentions)
        AND deleted_at IS NULL
    );

