-------------------------------------------------------------------------------
-- Function: calculate_candidate_score
-- Description: AI-powered candidate scoring based on job requirements match
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.calculate_candidate_score(
    p_candidate_id UUID,
    p_project_id UUID
)
RETURNS NUMERIC AS $$
DECLARE
    v_score NUMERIC := 0;
    v_project RECORD;
    v_candidate RECORD;
    v_skill_match INTEGER := 0;
    v_total_skills INTEGER := 0;
BEGIN
    -- Get project requirements
    SELECT * INTO v_project
    FROM public.recruiter_projects
    WHERE project_id = p_project_id AND deleted_at IS NULL;

    IF v_project.project_id IS NULL THEN
        RETURN 0;
    END IF;

    -- Get candidate profile (simplified - would join with profile tables)
    SELECT * INTO v_candidate
    FROM public.users
    WHERE user_id = p_candidate_id;

    IF v_candidate.user_id IS NULL THEN
        RETURN 0;
    END IF;

    -- Skill matching (simplified logic)
    IF v_project.skills_required IS NOT NULL THEN
        v_total_skills := array_length(v_project.skills_required, 1);
        -- In production, this would match against candidate skills
        v_skill_match := (v_total_skills * 0.7)::INTEGER; -- Placeholder
        v_score := v_score + (v_skill_match::NUMERIC / NULLIF(v_total_skills, 0)) * 40;
    END IF;

    -- Experience scoring
    -- In production, would parse years of experience from profile

    -- Location match
    IF v_project.location IS NOT NULL THEN
        -- Simplified location scoring
        v_score := v_score + 10;
    END IF;

    -- Seniority match
    IF v_project.seniority_level IS NOT NULL THEN
        v_score := v_score + 10;
    END IF;

    -- Engagement signals from past interactions
    SELECT COUNT(*) * 2 INTO v_score
    FROM public.candidate_notes
    WHERE candidate_id = p_candidate_id
      AND created_at > NOW() - INTERVAL '30 days';

    v_score := LEAST(v_score, 100);

    RETURN ROUND(v_score, 2);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.calculate_candidate_score(UUID, UUID) IS 'AI-powered candidate scoring based on job requirements match';

-------------------------------------------------------------------------------
-- Function: match_candidates_to_project
-- Description: Find best matching candidates for a project
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.match_candidates_to_project(
    p_project_id UUID,
    p_limit INTEGER DEFAULT 50
)
RETURNS TABLE (
    candidate_id UUID,
    match_score NUMERIC,
    match_reasons TEXT[]
) AS $$
BEGIN
    -- Validate project exists
    IF NOT EXISTS (SELECT 1 FROM public.recruiter_projects WHERE project_id = p_project_id) THEN
        RAISE EXCEPTION 'Project not found';
    END IF;

    RETURN QUERY
    WITH scored_candidates AS (
        SELECT
            u.user_id,
            public.calculate_candidate_score(u.user_id, p_project_id) AS score,
            ARRAY['Skill match', 'Location match'] AS reasons -- Placeholder
        FROM public.users u
        WHERE u.user_type = 'CANDIDATE'
          AND u.is_active = true
        LIMIT p_limit * 2
    )
    SELECT
        sc.user_id,
        sc.score,
        sc.reasons
    FROM scored_candidates sc
    WHERE sc.score > 0
    ORDER BY sc.score DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.match_candidates_to_project(UUID, INTEGER) IS 'Find best matching candidates for a project with scoring';

