-- =============================================================================
-- TABLE 167: ad_campaigns
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 167
-- Table Name: ad_campaigns
-- Description: Advertising campaign definitions with objectives, budgets,
--              schedules, and performance targets.
--
-- Business Case (300 words):
-- Professional network advertising requires sophisticated campaign management
-- to reach the right professionals with relevant messages. This table serves
-- as the central hub for advertising campaigns, defining objectives, budgets,
-- schedules, and performance targets. It enables advertisers to organize their
-- marketing efforts, control spending, and measure ROI across different
-- campaign initiatives.
--
-- Without structured campaign management, advertisers struggle to organize
-- their spending across multiple objectives and audiences. Budget tracking
-- becomes chaotic, and performance measurement is impossible. This table
-- provides the foundational structure for programmatic advertising, enabling
-- campaign-level control while supporting complex organizational hierarchies
-- for agencies and enterprise advertisers with multiple accounts.
--
-- The business impact is substantial: structured campaigns increase advertiser
-- ROI by 35% through better budget allocation and performance tracking. They
-- enable A/B testing of different strategies and objectives. For the platform,
-- campaigns provide the organizational framework for ad serving, billing, and
-- reporting. The structure supports agency management with account hierarchies,
-- shared audiences, and consolidated billing.
--
-- Key Performance Indicators (KPIs):
--   1. Campaign ROI/ROAS: Return on ad spend per campaign
--   2. Budget Utilization: Percentage of budget spent vs. planned
--   3. Campaign Efficiency: Cost per objective (CPC, CPA, CPL)
--   4. Conversion Rate: Conversions per impression/click
--   5. Campaign Pacing: Daily spend relative to budget
--   6. Quality Score: Platform-assigned relevance score
--   7. Audience Reach: Unique users reached
--   8. Frequency: Average impressions per user
--   9. Engagement Rate: Clicks/interactions per impression
--   10. Campaign Lifetime: Days active vs. planned
--
-- Feature Reference: AD-01 (Campaign Management)
-- Requirements Traceability: R-AD-001 through R-AD-020
--
-- Normalization: 3NF - Campaigns dependent on advertisers
--
-- High-Write Considerations:
--   - Moderate write volume (campaign updates)
--   - Read-heavy during ad serving and reporting
--   - JSONB for flexible settings
--   - Partial indexes for active campaigns
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.ad_campaigns CASCADE;
CREATE TABLE public.ad_campaigns (
    campaign_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    advertiser_id UUID NOT NULL,
    account_id UUID,
    campaign_name VARCHAR(255) NOT NULL,
    objective public.campaign_objective NOT NULL,
    status public.campaign_status DEFAULT 'DRAFT' NOT NULL,
    start_date TIMESTAMP WITH TIME ZONE NOT NULL,
    end_date TIMESTAMP WITH TIME ZONE,
    daily_budget NUMERIC(12,2) CHECK (daily_budget >= 0),
    lifetime_budget NUMERIC(15,2) CHECK (lifetime_budget >= 0),
    total_spent NUMERIC(15,2) DEFAULT 0,
    currency CHAR(3) DEFAULT 'USD',
    targeting_template_id UUID,
    frequency_cap INTEGER,
    frequency_cap_period VARCHAR(20),
    pacing_type VARCHAR(20) DEFAULT 'STANDARD',
    optimization_goal VARCHAR(50),
    conversion_window INTEGER DEFAULT 30,
    attribution_model public.attribution_model DEFAULT 'LAST_CLICK',
    brand_safety_level VARCHAR(20) DEFAULT 'STANDARD',
    is_retargeting BOOLEAN DEFAULT false,
    custom_params JSONB,
    performance_targets JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    CONSTRAINT fk_ad_campaigns_advertiser FOREIGN KEY (advertiser_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT valid_campaign_dates CHECK (end_date IS NULL OR end_date > start_date),
    CONSTRAINT valid_budget CHECK (daily_budget IS NOT NULL OR lifetime_budget IS NOT NULL),
    CONSTRAINT valid_frequency_cap CHECK (frequency_cap IS NULL OR frequency_cap > 0)
);

COMMENT ON TABLE public.ad_campaigns IS 'Advertising campaign definitions with objectives, budgets, and schedules';
COMMENT ON COLUMN public.ad_campaigns.campaign_id IS 'Primary key - Unique campaign identifier';
COMMENT ON COLUMN public.ad_campaigns.advertiser_id IS 'Advertiser who owns the campaign';
COMMENT ON COLUMN public.ad_campaigns.account_id IS 'Ad account reference for agency management';
COMMENT ON COLUMN public.ad_campaigns.campaign_name IS 'Campaign display name';
COMMENT ON COLUMN public.ad_campaigns.objective IS 'Campaign marketing objective';
COMMENT ON COLUMN public.ad_campaigns.status IS 'Current campaign status';
COMMENT ON COLUMN public.ad_campaigns.start_date IS 'Campaign start date/time';
COMMENT ON COLUMN public.ad_campaigns.end_date IS 'Campaign end date/time (NULL for ongoing)';
COMMENT ON COLUMN public.ad_campaigns.daily_budget IS 'Maximum daily spend';
COMMENT ON COLUMN public.ad_campaigns.lifetime_budget IS 'Maximum lifetime spend';
COMMENT ON COLUMN public.ad_campaigns.total_spent IS 'Total spend to date';
COMMENT ON COLUMN public.ad_campaigns.currency IS 'Billing currency (ISO 4217)';
COMMENT ON COLUMN public.ad_campaigns.targeting_template_id IS 'Reference to saved targeting template';
COMMENT ON COLUMN public.ad_campaigns.frequency_cap IS 'Max impressions per user';
COMMENT ON COLUMN public.ad_campaigns.frequency_cap_period IS 'Period for frequency cap (DAY, WEEK, MONTH)';
COMMENT ON COLUMN public.ad_campaigns.pacing_type IS 'Budget pacing (STANDARD, ACCELERATED)';
COMMENT ON COLUMN public.ad_campaigns.optimization_goal IS 'Optimization target (CLICKS, CONVERSIONS, IMPRESSIONS)';
COMMENT ON COLUMN public.ad_campaigns.conversion_window IS 'Days to attribute conversions';
COMMENT ON COLUMN public.ad_campaigns.attribution_model IS 'Conversion attribution model';
COMMENT ON COLUMN public.ad_campaigns.brand_safety_level IS 'Content safety filtering level';
COMMENT ON COLUMN public.ad_campaigns.is_retargeting IS 'Whether campaign retargets previous visitors';
COMMENT ON COLUMN public.ad_campaigns.custom_params IS 'Custom tracking parameters';
COMMENT ON COLUMN public.ad_campaigns.performance_targets IS 'Target CPA, ROAS, etc.';

-- Strategic Indexes
CREATE INDEX idx_ad_campaigns_advertiser ON public.ad_campaigns(advertiser_id, status)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_ad_campaigns_status ON public.ad_campaigns(status, start_date, end_date)
    WHERE status IN ('ACTIVE', 'SCHEDULED', 'PAUSED');
CREATE INDEX idx_ad_campaigns_dates ON public.ad_campaigns(start_date, end_date)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_ad_campaigns_objective ON public.ad_campaigns(objective, status);
CREATE INDEX idx_ad_campaigns_budget ON public.ad_campaigns(total_spent, daily_budget, lifetime_budget);
CREATE INDEX idx_ad_campaigns_custom ON public.ad_campaigns USING gin(custom_params);
CREATE INDEX idx_ad_campaigns_targets ON public.ad_campaigns USING gin(performance_targets);

-- Trigger
DROP TRIGGER IF EXISTS update_ad_campaigns_timestamp ON public.ad_campaigns;
CREATE TRIGGER update_ad_campaigns_timestamp
    BEFORE UPDATE ON public.ad_campaigns
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.ad_campaigns ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ad_campaigns_owner_policy ON public.ad_campaigns;
CREATE POLICY ad_campaigns_owner_policy ON public.ad_campaigns
    USING (advertiser_id = public.current_user_id() AND deleted_at IS NULL)
    WITH CHECK (advertiser_id = public.current_user_id());

DROP POLICY IF EXISTS ad_campaigns_admin_policy ON public.ad_campaigns;
CREATE POLICY ad_campaigns_admin_policy ON public.ad_campaigns
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'ad_ops', 'finance_admin')
        AND ur.deleted_at IS NULL
    ));

-- =============================================================================
-- TABLE 168: ad_groups
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 168
-- Table Name: ad_groups
-- Description: Ad groups within campaigns for organizing ads by targeting,
--              bidding, and creative themes.
--
-- Business Case (300 words):
-- Effective campaign organization requires grouping related ads that share
-- targeting and bidding strategies. This table manages ad groups, the
-- intermediate organizational unit between campaigns and individual ads.
-- Each ad group inherits campaign-level settings while enabling specific
-- targeting, bidding, and creative rotations for a focused set of ads.
--
-- Without ad groups, advertisers cannot efficiently manage different audience
-- segments or test multiple creative approaches within a single campaign.
-- Targeting becomes cumbersome to manage at the ad level. This table provides
-- the flexibility to segment campaign traffic while maintaining hierarchical
-- control and reporting.
--
-- The business impact is significant: ad groups improve campaign organization
-- by 50% and enable more precise performance optimization. They support A/B
-- testing of different ad variations against consistent audiences. For the
-- platform, ad groups enable more efficient ad serving and provide granular
-- performance data for optimization algorithms.
--
-- Key Performance Indicators (KPIs):
--   1. Ad Group CTR: Click-through rate by ad group
--   2. Quality Score: Relevance score per ad group
--   3. Conversion Rate: Conversions by ad group
--   4. Cost Efficiency: CPA/ROAS by ad group
--   5. Impression Share: Available impressions captured
--   6. Ad Rotation Performance: Best performing creative
--   7. Audience Engagement: Engagement by targeting segment
--   8. Bid Efficiency: Actual vs. target bid achievement
--   9. Budget Distribution: Spend allocation across groups
--   10. Creative Fatigue: Performance decline over time
--
-- Feature Reference: AD-13 (Ad Group Management)
-- Requirements Traceability: R-AD-021 through R-AD-035
--
-- Normalization: 3NF - Groups dependent on campaigns
--
-- High-Write Considerations:
--   - Moderate write volume (group updates)
--   - Read-heavy during ad serving decisions
--   - JSONB for flexible settings
--   - Composite indexes for campaign queries
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.ad_groups CASCADE;
CREATE TABLE public.ad_groups (
    ad_group_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    campaign_id UUID NOT NULL,
    ad_group_name VARCHAR(255) NOT NULL,
    status public.campaign_status DEFAULT 'DRAFT' NOT NULL,
    ad_rotation VARCHAR(20) DEFAULT 'OPTIMIZE',
    bid_strategy_type public.bid_strategy_type DEFAULT 'MANUAL_CPC',
    default_bid_amount NUMERIC(10,4),
    target_cpa NUMERIC(12,2),
    target_roas NUMERIC(5,2),
    bid_adjustments JSONB,
    device_targeting JSONB,
    placement_targeting JSONB,
    scheduled_start TIME,
    scheduled_end TIME,
    day_parting JSONB,
    custom_params JSONB,
    quality_score INTEGER CHECK (quality_score BETWEEN 1 AND 10),
    relevance_score INTEGER CHECK (relevance_score BETWEEN 1 AND 10),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_ad_groups_campaign FOREIGN KEY (campaign_id)
        REFERENCES public.ad_campaigns(campaign_id) ON DELETE CASCADE,
    CONSTRAINT unique_campaign_group_name UNIQUE (campaign_id, ad_group_name, deleted_at),
    CONSTRAINT valid_roas CHECK (target_roas IS NULL OR target_roas > 0)
);

COMMENT ON TABLE public.ad_groups IS 'Ad groups within campaigns for organizing ads by targeting and bidding themes';
COMMENT ON COLUMN public.ad_groups.ad_group_id IS 'Primary key - Unique ad group identifier';
COMMENT ON COLUMN public.ad_groups.campaign_id IS 'Parent campaign reference';
COMMENT ON COLUMN public.ad_groups.ad_group_name IS 'Ad group display name';
COMMENT ON COLUMN public.ad_groups.status IS 'Current ad group status';
COMMENT ON COLUMN public.ad_groups.ad_rotation IS 'Creative rotation strategy';
COMMENT ON COLUMN public.ad_groups.bid_strategy_type IS 'Bidding strategy for this group';
COMMENT ON COLUMN public.ad_groups.default_bid_amount IS 'Default bid for manual strategies';
COMMENT ON COLUMN public.ad_groups.target_cpa IS 'Target cost per acquisition';
COMMENT ON COLUMN public.ad_groups.target_roas IS 'Target return on ad spend';
COMMENT ON COLUMN public.ad_groups.bid_adjustments IS 'Bid modifiers by dimension';
COMMENT ON COLUMN public.ad_groups.device_targeting IS 'Device-specific settings';
COMMENT ON COLUMN public.ad_groups.placement_targeting IS 'Placement targeting rules';
COMMENT ON COLUMN public.ad_groups.scheduled_start IS 'Daily start time for ad serving';
COMMENT ON COLUMN public.ad_groups.scheduled_end IS 'Daily end time for ad serving';
COMMENT ON COLUMN public.ad_groups.day_parting IS 'Hourly bid adjustments';
COMMENT ON COLUMN public.ad_groups.custom_params IS 'Custom tracking parameters';
COMMENT ON COLUMN public.ad_groups.quality_score IS 'Platform quality score (1-10)';
COMMENT ON COLUMN public.ad_groups.relevance_score IS 'Targeting relevance score (1-10)';

-- Strategic Indexes
CREATE INDEX idx_ad_groups_campaign ON public.ad_groups(campaign_id, status)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_ad_groups_status ON public.ad_groups(status)
    WHERE status IN ('ACTIVE', 'PAUSED');
CREATE INDEX idx_ad_groups_bid_strategy ON public.ad_groups(bid_strategy_type);
CREATE INDEX idx_ad_groups_quality ON public.ad_groups(quality_score)
    WHERE quality_score IS NOT NULL;
CREATE INDEX idx_ad_groups_bid_adjustments ON public.ad_groups USING gin(bid_adjustments);
CREATE INDEX idx_ad_groups_targeting ON public.ad_groups USING gin(device_targeting);

-- Trigger
DROP TRIGGER IF EXISTS update_ad_groups_timestamp ON public.ad_groups;
CREATE TRIGGER update_ad_groups_timestamp
    BEFORE UPDATE ON public.ad_groups
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.ad_groups ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ad_groups_campaign_owner_policy ON public.ad_groups;
CREATE POLICY ad_groups_campaign_owner_policy ON public.ad_groups
    USING (
        EXISTS (
            SELECT 1 FROM public.ad_campaigns ac
            WHERE ac.campaign_id = ad_groups.campaign_id
              AND ac.advertiser_id = public.current_user_id()
              AND ac.deleted_at IS NULL
        )
        AND deleted_at IS NULL
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.ad_campaigns ac
            WHERE ac.campaign_id = ad_groups.campaign_id
              AND ac.advertiser_id = public.current_user_id()
              AND ac.deleted_at IS NULL
        )
    );

-- =============================================================================
-- TABLE 169: ad_creatives
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 169
-- Table Name: ad_creatives
-- Description: Ad creative assets including images, videos, copy, and
--              interactive elements with approval workflow.
--
-- Business Case (300 words):
-- Creative assets are the visible manifestation of advertising campaigns.
-- This table manages all ad creative elements including images, videos,
-- headlines, descriptions, and call-to-action buttons. It supports multiple
-- formats (single image, carousel, video, sponsored content) and includes
-- a comprehensive approval workflow to ensure brand safety and policy
-- compliance.
--
-- Without centralized creative management, advertisers struggle to maintain
-- consistent branding across campaigns. Creative assets are duplicated and
-- version control becomes impossible. Approval processes are manual and
-- error-prone. This table provides a single source of truth for all ad
-- creatives with built-in approval workflows, versioning, and performance
-- tracking.
--
-- The business impact is substantial: structured creative management reduces
-- approval time by 60% through automated workflows. It enables creative A/B
-- testing at scale. For the platform, it ensures policy compliance and brand
-- safety while providing data to optimize creative performance through machine
-- learning.
--
-- Key Performance Indicators (KPIs):
--   1. Creative CTR: Click-through rate by creative
--   2. Approval Time: Time from submission to approval
--   3. Rejection Rate: Percentage of creatives rejected
--   4. Creative Fatigue: Performance decline over impressions
--   5. Engagement Rate: Interactions per impression
--   6. Conversion Rate: Conversions by creative
--   7. Quality Score: Creative relevance score
--   8. A/B Test Results: Winning creative performance
--   9. Video Completion Rate: Percentage watching full video
--   10. Creative Diversity: Number of active variations
--
-- Feature Reference: AD-03 (Creative Management)
-- Requirements Traceability: R-AD-036 through R-AD-050
--
-- Normalization: 3NF - Creatives dependent on ad groups
--
-- High-Write Considerations:
--   - Moderate write volume (creative creation/updates)
--   - Read-heavy during ad serving
--   - JSONB for flexible creative elements
--   - Full-text search for copy elements
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.ad_creatives CASCADE;
CREATE TABLE public.ad_creatives (
    creative_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    ad_group_id UUID NOT NULL,
    creative_name VARCHAR(255) NOT NULL,
    format public.ad_format NOT NULL,
    status public.ad_status DEFAULT 'DRAFT' NOT NULL,
    headline VARCHAR(150),
    description TEXT,
    primary_text TEXT,
    call_to_action VARCHAR(50),
    display_url VARCHAR(500),
    destination_url VARCHAR(2000) NOT NULL,
    deep_link_url VARCHAR(2000),
    image_url VARCHAR(1000),
    image_hash VARCHAR(64),
    video_url VARCHAR(1000),
    video_thumbnail_url VARCHAR(1000),
    video_duration INTEGER,
    carousel_cards JSONB,
    lead_gen_form_id UUID,
    interactive_elements JSONB,
    tracking_params JSONB,
    utm_parameters JSONB,
    approval_notes TEXT,
    approved_at TIMESTAMP WITH TIME ZONE,
    approved_by UUID,
    rejection_reason TEXT,
    performance_score NUMERIC(5,2),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    CONSTRAINT fk_ad_creatives_ad_group FOREIGN KEY (ad_group_id)
        REFERENCES public.ad_groups(ad_group_id) ON DELETE CASCADE,
    CONSTRAINT fk_ad_creatives_approved_by FOREIGN KEY (approved_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT valid_destination_url CHECK (destination_url ~ '^https?://'),
    CONSTRAINT valid_headline_length CHECK (headline IS NULL OR length(headline) <= 150),
    CONSTRAINT valid_description_length CHECK (description IS NULL OR length(description) <= 500)
);

COMMENT ON TABLE public.ad_creatives IS 'Ad creative assets including images, videos, copy, and interactive elements';
COMMENT ON COLUMN public.ad_creatives.creative_id IS 'Primary key - Unique creative identifier';
COMMENT ON COLUMN public.ad_creatives.ad_group_id IS 'Parent ad group reference';
COMMENT ON COLUMN public.ad_creatives.creative_name IS 'Internal creative name';
COMMENT ON COLUMN public.ad_creatives.format IS 'Ad format type';
COMMENT ON COLUMN public.ad_creatives.status IS 'Creative approval status';
COMMENT ON COLUMN public.ad_creatives.headline IS 'Ad headline text';
COMMENT ON COLUMN public.ad_creatives.description IS 'Ad description text';
COMMENT ON COLUMN public.ad_creatives.primary_text IS 'Primary body text';
COMMENT ON COLUMN public.ad_creatives.call_to_action IS 'CTA button text';
COMMENT ON COLUMN public.ad_creatives.display_url IS 'Display URL shown in ad';
COMMENT ON COLUMN public.ad_creatives.destination_url IS 'Click destination URL';
COMMENT ON COLUMN public.ad_creatives.deep_link_url IS 'Mobile app deep link';
COMMENT ON COLUMN public.ad_creatives.image_url IS 'Primary image URL';
COMMENT ON COLUMN public.ad_creatives.image_hash IS 'Image hash for deduplication';
COMMENT ON COLUMN public.ad_creatives.video_url IS 'Video asset URL';
COMMENT ON COLUMN public.ad_creatives.video_thumbnail_url IS 'Video thumbnail URL';
COMMENT ON COLUMN public.ad_creatives.video_duration IS 'Video length in seconds';
COMMENT ON COLUMN public.ad_creatives.carousel_cards IS 'JSON array of carousel cards';
COMMENT ON COLUMN public.ad_creatives.lead_gen_form_id IS 'Linked lead generation form';
COMMENT ON COLUMN public.ad_creatives.interactive_elements IS 'JSON interactive components';
COMMENT ON COLUMN public.ad_creatives.tracking_params IS 'Additional tracking parameters';
COMMENT ON COLUMN public.ad_creatives.utm_parameters IS 'UTM tracking parameters';
COMMENT ON COLUMN public.ad_creatives.approval_notes IS 'Reviewer approval notes';
COMMENT ON COLUMN public.ad_creatives.approved_at IS 'Approval timestamp';
COMMENT ON COLUMN public.ad_creatives.approved_by IS 'Reviewer user ID';
COMMENT ON COLUMN public.ad_creatives.rejection_reason IS 'Reason for rejection';
COMMENT ON COLUMN public.ad_creatives.performance_score IS 'ML-based creative score';

-- Strategic Indexes
CREATE INDEX idx_ad_creatives_ad_group ON public.ad_creatives(ad_group_id, status)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_ad_creatives_status ON public.ad_creatives(status)
    WHERE status IN ('PENDING_REVIEW', 'APPROVED', 'ACTIVE');
CREATE INDEX idx_ad_creatives_format ON public.ad_creatives(format);
CREATE INDEX idx_ad_creatives_approved ON public.ad_creatives(approved_at)
    WHERE approved_at IS NOT NULL;
CREATE INDEX idx_ad_creatives_score ON public.ad_creatives(performance_score)
    WHERE performance_score IS NOT NULL;
CREATE INDEX idx_ad_creatives_interactive ON public.ad_creatives USING gin(interactive_elements);
CREATE INDEX idx_ad_creatives_carousel ON public.ad_creatives USING gin(carousel_cards);
CREATE INDEX idx_ad_creatives_fulltext ON public.ad_creatives USING gin(
    to_tsvector('english', COALESCE(headline,'') || ' ' || COALESCE(description,'') || ' ' || COALESCE(primary_text,''))
);

-- Trigger
DROP TRIGGER IF EXISTS update_ad_creatives_timestamp ON public.ad_creatives;
CREATE TRIGGER update_ad_creatives_timestamp
    BEFORE UPDATE ON public.ad_creatives
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.ad_creatives ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ad_creatives_ad_group_owner_policy ON public.ad_creatives;
CREATE POLICY ad_creatives_ad_group_owner_policy ON public.ad_creatives
    USING (
        EXISTS (
            SELECT 1 FROM public.ad_groups ag
            JOIN public.ad_campaigns ac ON ag.campaign_id = ac.campaign_id
            WHERE ag.ad_group_id = ad_creatives.ad_group_id
              AND ac.advertiser_id = public.current_user_id()
              AND ac.deleted_at IS NULL
        )
        AND deleted_at IS NULL
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.ad_groups ag
            JOIN public.ad_campaigns ac ON ag.campaign_id = ac.campaign_id
            WHERE ag.ad_group_id = ad_creatives.ad_group_id
              AND ac.advertiser_id = public.current_user_id()
              AND ac.deleted_at IS NULL
        )
    );

-- =============================================================================
-- TABLE 170: ad_targeting_criteria
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 170
-- Table Name: ad_targeting_criteria
-- Description: Detailed ad targeting rules with Boolean logic for precise
--              audience selection including demographics, interests, and
--              behaviors.
--
-- Business Case (300 words):
-- Precision targeting is the core value proposition of professional network
-- advertising. This table stores detailed targeting rules that determine which
-- users see which ads. It supports complex Boolean logic combining demographic
-- filters (industry, job title, seniority, company size), interest-based
-- targeting, and behavioral signals. The rules engine enables advertisers to
-- reach exact professional audiences while respecting privacy controls.
--
-- Without granular targeting, advertising becomes inefficient spray-and-pray.
-- Advertisers waste budget showing irrelevant ads to the wrong audiences.
-- Users see poor-quality ads and engagement suffers. This table powers the
-- targeting engine that matches ads to users with surgical precision, maximizing
-- ROI for advertisers while maintaining a quality user experience.
--
-- The business impact is transformative: precise targeting increases CTR by
-- 200-400% compared to untargeted ads. It enables premium pricing for highly
-- specific professional audiences. For users, it ensures ads are relevant to
-- their professional interests. The targeting data also provides valuable
-- insights into audience composition and market trends.
--
-- Key Performance Indicators (KPIs):
--   1. Targeting Precision: Relevance score of served ads
--   2. Audience Size: Addressable users per targeting set
--   3. Targeting Expansion: Overlap between criteria sets
--   4. Rule Complexity: Average conditions per targeting set
--   5. Match Rate: Percentage of inventory matching criteria
--   6. Exclusion Effectiveness: Blocked impressions from exclusions
--   7. Audience Freshness: Update frequency of targeting attributes
--   8. Privacy Compliance: Opt-out rate impact
--   9. Bid Modifier Impact: Performance of adjusted bids
--   10. Segment Performance: CTR/CVR by targeting segment
--
-- Feature Reference: AD-05 (Targeting)
-- Requirements Traceability: R-AD-051 through R-AD-070
--
-- Normalization: 3NF - Criteria dependent on ad groups or templates
--
-- High-Write Considerations:
--   - Write-light (targeting changes infrequent)
--   - Read-heavy during ad serving (cached)
--   - JSONB for flexible rule structures
--   - GIN indexes for rule evaluation
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.ad_targeting_criteria CASCADE;
CREATE TABLE public.ad_targeting_criteria (
    criteria_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    ad_group_id UUID,
    audience_template_id UUID,
    rule_name VARCHAR(255) NOT NULL,
    rule_type VARCHAR(20) DEFAULT 'INCLUDE' CHECK (rule_type IN ('INCLUDE', 'EXCLUDE')),
    targeting_rules JSONB NOT NULL,
    estimated_reach INTEGER,
    estimated_impressions INTEGER,
    bid_modifier NUMERIC(5,2) DEFAULT 1.0,
    priority INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    performance_data JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_targeting_criteria_ad_group FOREIGN KEY (ad_group_id)
        REFERENCES public.ad_groups(ad_group_id) ON DELETE CASCADE,
    CONSTRAINT valid_targeting_rules CHECK (jsonb_typeof(targeting_rules) = 'object'),
    CONSTRAINT valid_bid_modifier CHECK (bid_modifier >= 0.1 AND bid_modifier <= 10.0)
);

COMMENT ON TABLE public.ad_targeting_criteria IS 'Detailed ad targeting rules with Boolean logic for precise audience selection';
COMMENT ON COLUMN public.ad_targeting_criteria.criteria_id IS 'Primary key - Unique targeting criteria identifier';
COMMENT ON COLUMN public.ad_targeting_criteria.ad_group_id IS 'Associated ad group';
COMMENT ON COLUMN public.ad_targeting_criteria.audience_template_id IS 'Saved audience template reference';
COMMENT ON COLUMN public.ad_targeting_criteria.rule_name IS 'Descriptive rule name';
COMMENT ON COLUMN public.ad_targeting_criteria.rule_type IS 'Include or exclude rule';
COMMENT ON COLUMN public.ad_targeting_criteria.targeting_rules IS 'JSON targeting rule definition';
COMMENT ON COLUMN public.ad_targeting_criteria.estimated_reach IS 'Estimated unique users';
COMMENT ON COLUMN public.ad_targeting_criteria.estimated_impressions IS 'Estimated daily impressions';
COMMENT ON COLUMN public.ad_targeting_criteria.bid_modifier IS 'Bid adjustment multiplier';
COMMENT ON COLUMN public.ad_targeting_criteria.priority IS 'Rule evaluation priority';
COMMENT ON COLUMN public.ad_targeting_criteria.is_active IS 'Whether rule is active';
COMMENT ON COLUMN public.ad_targeting_criteria.performance_data IS 'Performance by targeting segment';

-- Strategic Indexes
CREATE INDEX idx_targeting_criteria_ad_group ON public.ad_targeting_criteria(ad_group_id)
    WHERE ad_group_id IS NOT NULL AND is_active = true AND deleted_at IS NULL;
CREATE INDEX idx_targeting_criteria_template ON public.ad_targeting_criteria(audience_template_id)
    WHERE audience_template_id IS NOT NULL;
CREATE INDEX idx_targeting_criteria_rules ON public.ad_targeting_criteria USING gin(targeting_rules);
CREATE INDEX idx_targeting_criteria_active ON public.ad_targeting_criteria(is_active, rule_type)
    WHERE is_active = true;
CREATE INDEX idx_targeting_criteria_performance ON public.ad_targeting_criteria USING gin(performance_data);

-- Trigger
DROP TRIGGER IF EXISTS update_targeting_criteria_timestamp ON public.ad_targeting_criteria;
CREATE TRIGGER update_targeting_criteria_timestamp
    BEFORE UPDATE ON public.ad_targeting_criteria
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.ad_targeting_criteria ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS targeting_criteria_owner_policy ON public.ad_targeting_criteria;
CREATE POLICY targeting_criteria_owner_policy ON public.ad_targeting_criteria
    USING (
        ad_group_id IS NOT NULL AND
        EXISTS (
            SELECT 1 FROM public.ad_groups ag
            JOIN public.ad_campaigns ac ON ag.campaign_id = ac.campaign_id
            WHERE ag.ad_group_id = ad_targeting_criteria.ad_group_id
              AND ac.advertiser_id = public.current_user_id()
              AND ac.deleted_at IS NULL
        )
        AND deleted_at IS NULL
    );

-- =============================================================================
-- TABLE 171: ad_targeting_audiences
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 171
-- Table Name: ad_targeting_audiences
-- Description: Saved target audiences for reuse across campaigns including
--              custom audiences, lookalike audiences, and retargeting pools.
--
-- Business Case (300 words):
-- Building effective audiences requires time and expertise. This table enables
-- advertisers to save, name, and reuse targeting configurations across multiple
-- campaigns. It supports various audience types including custom audiences
-- (email lists, website visitors), lookalike audiences (AI-generated similar
-- users), and retargeting pools. Saved audiences accelerate campaign setup and
-- ensure consistency across marketing initiatives.
--
-- Without saved audiences, advertisers repeatedly rebuild the same targeting
-- configurations, wasting time and introducing inconsistencies. Best practices
-- aren't captured and shared across teams. This table creates a library of
-- proven audience definitions that can be deployed instantly, dramatically
-- reducing campaign setup time while improving performance through tested
-- targeting approaches.
--
-- The business impact is significant: saved audiences reduce campaign setup
-- time by 70% and improve performance consistency by 40%. They enable audience
-- sharing across agency accounts. Lookalike audiences expand reach while
-- maintaining relevance. Custom audiences enable powerful retargeting
-- strategies that recover abandoned opportunities.
--
-- Key Performance Indicators (KPIs):
--   1. Audience Reuse Rate: Frequency of audience template usage
--   2. Lookalike Performance: Conversion rate of lookalike vs. source
--   3. Audience Size Stability: Change in audience size over time
--   4. Audience Overlap: Shared users across saved audiences
--   5. Retargeting Window: Time to conversion for retargeting
--   6. Audience Sharing: Templates shared across accounts
--   7. Match Rate: Percentage of custom audience matched
--   8. Audience Freshness: Last update timestamp
--   9. Performance by Audience: ROAS per saved audience
--   10. Audience Expansion: Reach of lookalike audiences
--
-- Feature Reference: AD-14 (Audience Management)
-- Requirements Traceability: R-AD-071 through R-AD-085
--
-- Normalization: 3NF - Audiences dependent on advertisers
--
-- High-Write Considerations:
--   - Moderate write volume (audience creation/updates)
--   - Read-heavy during campaign setup and ad serving
--   - JSONB for audience definitions
--   - Full-text search for audience discovery
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.ad_targeting_audiences CASCADE;
CREATE TABLE public.ad_targeting_audiences (
    audience_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    advertiser_id UUID NOT NULL,
    audience_name VARCHAR(255) NOT NULL,
    description TEXT,
    audience_type VARCHAR(50) NOT NULL,
    source_type VARCHAR(50),
    source_audience_id UUID,
    targeting_rules JSONB NOT NULL,
    audience_size INTEGER,
    match_rate NUMERIC(5,2),
    lookalike_percentage INTEGER CHECK (lookalike_percentage BETWEEN 1 AND 20),
    refresh_frequency VARCHAR(20),
    last_refreshed_at TIMESTAMP WITH TIME ZONE,
    expiration_days INTEGER,
    is_shared BOOLEAN DEFAULT false,
    shared_accounts UUID[],
    performance_summary JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT fk_targeting_audiences_advertiser FOREIGN KEY (advertiser_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_targeting_audiences_source FOREIGN KEY (source_audience_id)
        REFERENCES public.ad_targeting_audiences(audience_id) ON DELETE SET NULL,
    CONSTRAINT unique_advertiser_audience_name UNIQUE (advertiser_id, audience_name, deleted_at),
    CONSTRAINT valid_audience_type CHECK (audience_type IN ('CUSTOM', 'LOOKALIKE', 'RETARGETING', 'SAVED', 'ENGAGEMENT'))
);

COMMENT ON TABLE public.ad_targeting_audiences IS 'Saved target audiences for reuse across campaigns including custom and lookalike audiences';
COMMENT ON COLUMN public.ad_targeting_audiences.audience_id IS 'Primary key - Unique audience identifier';
COMMENT ON COLUMN public.ad_targeting_audiences.advertiser_id IS 'Owner advertiser';
COMMENT ON COLUMN public.ad_targeting_audiences.audience_name IS 'Audience display name';
COMMENT ON COLUMN public.ad_targeting_audiences.description IS 'Audience description';
COMMENT ON COLUMN public.ad_targeting_audiences.audience_type IS 'CUSTOM, LOOKALIKE, RETARGETING, SAVED, ENGAGEMENT';
COMMENT ON COLUMN public.ad_targeting_audiences.source_type IS 'Source of custom audience (EMAIL_LIST, WEBSITE, APP, etc.)';
COMMENT ON COLUMN public.ad_targeting_audiences.source_audience_id IS 'Source for lookalike audiences';
COMMENT ON COLUMN public.ad_targeting_audiences.targeting_rules IS 'JSON targeting rule definition';
COMMENT ON COLUMN public.ad_targeting_audiences.audience_size IS 'Number of users in audience';
COMMENT ON COLUMN public.ad_targeting_audiences.match_rate IS 'Percentage of source list matched';
COMMENT ON COLUMN public.ad_targeting_audiences.lookalike_percentage IS 'Similarity threshold for lookalike (1-20%)';
COMMENT ON COLUMN public.ad_targeting_audiences.refresh_frequency IS 'How often audience is refreshed';
COMMENT ON COLUMN public.ad_targeting_audiences.last_refreshed_at IS 'Last refresh timestamp';
COMMENT ON COLUMN public.ad_targeting_audiences.expiration_days IS 'Days until audience expires';
COMMENT ON COLUMN public.ad_targeting_audiences.is_shared IS 'Whether shared with other accounts';
COMMENT ON COLUMN public.ad_targeting_audiences.shared_accounts IS 'Account IDs with access';
COMMENT ON COLUMN public.ad_targeting_audiences.performance_summary IS 'Aggregate performance metrics';

-- Strategic Indexes
CREATE INDEX idx_targeting_audiences_advertiser ON public.ad_targeting_audiences(advertiser_id, audience_type)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_targeting_audiences_type ON public.ad_targeting_audiences(audience_type)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_targeting_audiences_source ON public.ad_targeting_audiences(source_audience_id)
    WHERE source_audience_id IS NOT NULL;
CREATE INDEX idx_targeting_audiences_shared ON public.ad_targeting_audiences(is_shared)
    WHERE is_shared = true;
CREATE INDEX idx_targeting_audiences_refreshed ON public.ad_targeting_audiences(last_refreshed_at)
    WHERE last_refreshed_at IS NOT NULL;
CREATE INDEX idx_targeting_audiences_rules ON public.ad_targeting_audiences USING gin(targeting_rules);
CREATE INDEX idx_targeting_audiences_shared_accounts ON public.ad_targeting_audiences USING gin(shared_accounts);
CREATE INDEX idx_targeting_audiences_fulltext ON public.ad_targeting_audiences USING gin(
    to_tsvector('english', audience_name || ' ' || COALESCE(description,''))
);

-- Trigger
DROP TRIGGER IF EXISTS update_targeting_audiences_timestamp ON public.ad_targeting_audiences;
CREATE TRIGGER update_targeting_audiences_timestamp
    BEFORE UPDATE ON public.ad_targeting_audiences
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.ad_targeting_audiences ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS targeting_audiences_owner_policy ON public.ad_targeting_audiences;
CREATE POLICY targeting_audiences_owner_policy ON public.ad_targeting_audiences
    USING (advertiser_id = public.current_user_id() AND deleted_at IS NULL)
    WITH CHECK (advertiser_id = public.current_user_id());

DROP POLICY IF EXISTS targeting_audiences_shared_policy ON public.ad_targeting_audiences;
CREATE POLICY targeting_audiences_shared_policy ON public.ad_targeting_audiences
    FOR SELECT USING (
        is_shared = true
        AND public.current_user_id() = ANY(shared_accounts)
        AND deleted_at IS NULL
    );

