-- FUNCTIONS FOR ADVERTISING MODULE
-- =============================================================================

-------------------------------------------------------------------------------
-- Function: calculate_bid_amount
-- Description: Calculate real-time bid amount based on strategy and performance
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.calculate_bid_amount(
    p_ad_group_id UUID,
    p_user_context JSONB DEFAULT '{}'::JSONB
)
RETURNS NUMERIC AS $$
DECLARE
    v_ad_group RECORD;
    v_bid_amount NUMERIC := 0;
    v_adjustment NUMERIC := 1.0;
BEGIN
    -- Get ad group configuration
    SELECT * INTO v_ad_group
    FROM public.ad_groups
    WHERE ad_group_id = p_ad_group_id
      AND status = 'ACTIVE'
      AND deleted_at IS NULL;

    IF v_ad_group.ad_group_id IS NULL THEN
        RETURN 0;
    END IF;

    -- Base bid calculation
    CASE v_ad_group.bid_strategy_type
        WHEN 'MANUAL_CPC', 'MANUAL_CPM' THEN
            v_bid_amount := COALESCE(v_ad_group.default_bid_amount, 0);
        WHEN 'AUTOMATED_MAX_CLICKS', 'AUTOMATED_MAX_CONVERSIONS' THEN
            -- AI-calculated bid based on historical performance
            SELECT AVG(cpc) * 1.2 INTO v_bid_amount
            FROM public.ad_performance_daily
            WHERE ad_group_id = p_ad_group_id
              AND date >= CURRENT_DATE - INTERVAL '7 days';
            v_bid_amount := COALESCE(v_bid_amount, v_ad_group.default_bid_amount);
        WHEN 'AUTOMATED_TARGET_CPA' THEN
            v_bid_amount := COALESCE(v_ad_group.target_cpa, 0) * 0.1;
        WHEN 'AUTOMATED_TARGET_ROAS' THEN
            -- Calculate based on predicted conversion value
            v_bid_amount := COALESCE(v_ad_group.default_bid_amount, 1.0);
        ELSE
            v_bid_amount := COALESCE(v_ad_group.default_bid_amount, 0);
    END CASE;

    -- Apply targeting bid adjustments from user context
    IF p_user_context ? 'industry' THEN
        SELECT COALESCE(bid_modifier, 1.0) INTO v_adjustment
        FROM public.ad_targeting_criteria
        WHERE ad_group_id = p_ad_group_id
          AND targeting_rules->>'industry' = p_user_context->>'industry'
          AND is_active = true
        LIMIT 1;
    END IF;

    v_bid_amount := v_bid_amount * v_adjustment;

    -- Apply time-based adjustments (dayparting)
    IF v_ad_group.day_parting IS NOT NULL THEN
        -- Apply hourly multiplier from dayparting JSON
        v_bid_amount := v_bid_amount * COALESCE(
            (v_ad_group.day_parting->>EXTRACT(HOUR FROM NOW())::TEXT)::NUMERIC,
            1.0
        );
    END IF;

    RETURN ROUND(v_bid_amount, 4);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.calculate_bid_amount(UUID, JSONB) IS 'Calculate real-time bid amount based on strategy and performance context';

-------------------------------------------------------------------------------
-- Function: track_impression
-- Description: Track ad impression with deduplication and viewability data
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.track_impression(
    p_creative_id UUID,
    p_user_id UUID,
    p_impression_id UUID DEFAULT gen_random_uuid(),
    p_viewability public.impression_viewability DEFAULT 'UNMEASURED',
    p_placement VARCHAR(100) DEFAULT NULL,
    p_auction_price NUMERIC(12,6) DEFAULT NULL,
    p_metadata JSONB DEFAULT '{}'::JSONB
)
RETURNS UUID AS $$
DECLARE
    v_campaign_id UUID;
    v_ad_group_id UUID;
    v_impression_id UUID;
BEGIN
    -- Get campaign and ad group
    SELECT ag.ad_group_id, ag.campaign_id
    INTO v_ad_group_id, v_campaign_id
    FROM public.ad_creatives ac
    JOIN public.ad_groups ag ON ac.ad_group_id = ag.ad_group_id
    WHERE ac.creative_id = p_creative_id
      AND ac.status = 'ACTIVE'
      AND ag.status = 'ACTIVE';

    IF v_campaign_id IS NULL THEN
        RAISE EXCEPTION 'Invalid or inactive creative';
    END IF;

    -- Check for duplicate impression
    IF EXISTS (
        SELECT 1 FROM public.ad_impressions
        WHERE impression_id = p_impression_id
    ) THEN
        RETURN p_impression_id;
    END IF;

    -- Insert impression
    INSERT INTO public.ad_impressions (
        impression_id,
        creative_id,
        campaign_id,
        ad_group_id,
        user_id,
        impression_time,
        viewability,
        placement,
        auction_price,
        metadata
    ) VALUES (
        p_impression_id,
        p_creative_id,
        v_campaign_id,
        v_ad_group_id,
        p_user_id,
        NOW(),
        p_viewability,
        p_placement,
        p_auction_price,
        p_metadata
    ) RETURNING impression_id INTO v_impression_id;

    -- Update campaign spend if auction price provided
    IF p_auction_price IS NOT NULL THEN
        UPDATE public.ad_campaigns
        SET total_spent = total_spent + p_auction_price,
            updated_at = NOW()
        WHERE campaign_id = v_campaign_id;
    END IF;

    RETURN v_impression_id;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Failed to track impression: %', SQLERRM;
        RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.track_impression(UUID, UUID, UUID, public.impression_viewability, VARCHAR, NUMERIC, JSONB) IS 'Track ad impression with deduplication and viewability data';


