-- =============================================================================
-- TABLE 197: events
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 197
-- Table Name: events
-- Description: Event definitions with comprehensive metadata for professional
--              gatherings, conferences, webinars, and networking opportunities.
--
-- Business Case (300 words):
-- Professional events are a cornerstone of career development, networking,
-- and industry education. This table serves as the central definition for all
-- events hosted on or integrated with the platform, from intimate meetups to
-- global virtual conferences. It manages event identity, scheduling, format
-- (in-person, virtual, hybrid), branding, and core configuration that drives
-- the entire event ecosystem.
--
-- Without structured event management, professional gatherings become
-- fragmented across multiple platforms, reducing discoverability and limiting
-- the network effects that make events valuable. Organizers struggle with
-- logistics, attendees miss relevant opportunities, and the platform cannot
-- leverage events for engagement and monetization. This table provides the
-- authoritative event record that powers discovery, registration, and all
-- event-related features.
--
-- The business impact is transformative: a unified event platform increases
-- event discovery by 300% and attendance by 150%. It enables premium event
-- features (ticketing, sponsorships, networking) that create new revenue
-- streams. Events drive platform engagement, with event attendees showing
-- 80% higher 30-day retention. The event data provides rich signals about
-- professional interests and relationships that improve all platform
-- recommendations.
--
-- Key Performance Indicators (KPIs):
--   1. Registration Rate: Registrations per event
--   2. Attendance Rate: Check-ins / registrations
--   3. Revenue per Event: Total ticket + sponsorship revenue
--   4. Attendee Satisfaction: Average feedback rating
--   5. Networking Connections: Connections made per attendee
--   6. Session Engagement: Average session attendance
--   7. Event ROI: Revenue / cost ratio
--   8. Repeat Attendance: Attendees returning to organizer events
--   9. Geographic Reach: Attendee location diversity
--   10. Content Engagement: Session views and interactions
--
-- Feature Reference: EVENT-11 (Event Management)
-- Requirements Traceability: R-EVENT-001 through R-EVENT-025
--
-- Normalization: 3NF - Events independent with organizer relationships
--
-- High-Write Considerations:
--   - Moderate write volume (event updates)
--   - Read-heavy during discovery and registration
--   - JSONB for flexible configuration
--   - Geospatial indexes for location-based discovery
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.events CASCADE;
CREATE TABLE public.events (
    event_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    organizer_id UUID NOT NULL,
    company_id UUID,
    group_id UUID,
    event_name VARCHAR(255) NOT NULL,
    slug VARCHAR(255) UNIQUE NOT NULL,
    description TEXT,
    short_description VARCHAR(500),
    event_type public.event_type NOT NULL,
    status public.event_status DEFAULT 'DRAFT' NOT NULL,
    category_id UUID,
    start_datetime TIMESTAMP WITH TIME ZONE NOT NULL,
    end_datetime TIMESTAMP WITH TIME ZONE NOT NULL,
    timezone VARCHAR(50) DEFAULT 'UTC',
    registration_start TIMESTAMP WITH TIME ZONE,
    registration_deadline TIMESTAMP WITH TIME ZONE,
    max_attendees INTEGER CHECK (max_attendees > 0),
    current_registrations INTEGER DEFAULT 0,
    current_attendees INTEGER DEFAULT 0,
    is_private BOOLEAN DEFAULT false,
    requires_approval BOOLEAN DEFAULT false,
    age_restriction INTEGER,
    language VARCHAR(50) DEFAULT 'en',
    accessibility_info TEXT,
    health_safety_info TEXT,
    header_image_url VARCHAR(1000),
    logo_url VARCHAR(1000),
    website_url VARCHAR(500),
    social_links JSONB,
    contact_email VARCHAR(255),
    contact_phone VARCHAR(50),
    hashtag VARCHAR(100),
    tags TEXT[],
    custom_fields JSONB,
    metadata JSONB,
    published_at TIMESTAMP WITH TIME ZONE,
    cancelled_at TIMESTAMP WITH TIME ZONE,
    cancellation_reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    CONSTRAINT fk_events_organizer FOREIGN KEY (organizer_id)
        REFERENCES public.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_events_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT fk_events_group FOREIGN KEY (group_id)
        REFERENCES public.community_groups(group_id) ON DELETE SET NULL,
    CONSTRAINT valid_slug CHECK (slug ~ '^[a-z0-9-]+$'),
    CONSTRAINT valid_dates CHECK (end_datetime > start_datetime),
    CONSTRAINT valid_registration_dates CHECK (
        registration_start IS NULL OR
        registration_deadline IS NULL OR
        registration_deadline > registration_start
    ),
    CONSTRAINT valid_email_format CHECK (contact_email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')
);

COMMENT ON TABLE public.events IS 'Event definitions with comprehensive metadata for professional gatherings';
COMMENT ON COLUMN public.events.event_id IS 'Primary key - Unique event identifier';
COMMENT ON COLUMN public.events.organizer_id IS 'Primary event organizer';
COMMENT ON COLUMN public.events.company_id IS 'Company hosting the event';
COMMENT ON COLUMN public.events.group_id IS 'Associated community group';
COMMENT ON COLUMN public.events.event_name IS 'Event display name';
COMMENT ON COLUMN public.events.slug IS 'URL-friendly unique identifier';
COMMENT ON COLUMN public.events.description IS 'Full event description';
COMMENT ON COLUMN public.events.short_description IS 'Brief description for cards';
COMMENT ON COLUMN public.events.event_type IS 'Event format (IN_PERSON, VIRTUAL, HYBRID)';
COMMENT ON COLUMN public.events.status IS 'Current event status';
COMMENT ON COLUMN public.events.category_id IS 'Event category reference';
COMMENT ON COLUMN public.events.start_datetime IS 'Event start date/time';
COMMENT ON COLUMN public.events.end_datetime IS 'Event end date/time';
COMMENT ON COLUMN public.events.timezone IS 'Event timezone';
COMMENT ON COLUMN public.events.registration_start IS 'When registration opens';
COMMENT ON COLUMN public.events.registration_deadline IS 'Registration cutoff';
COMMENT ON COLUMN public.events.max_attendees IS 'Maximum capacity';
COMMENT ON COLUMN public.events.current_registrations IS 'Cached registration count';
COMMENT ON COLUMN public.events.current_attendees IS 'Cached check-in count';
COMMENT ON COLUMN public.events.is_private IS 'Whether event is private/invite-only';
COMMENT ON COLUMN public.events.requires_approval IS 'Whether registration needs approval';
COMMENT ON COLUMN public.events.age_restriction IS 'Minimum age requirement';
COMMENT ON COLUMN public.events.language IS 'Primary event language';
COMMENT ON COLUMN public.events.accessibility_info IS 'Accessibility accommodations';
COMMENT ON COLUMN public.events.health_safety_info IS 'Health and safety protocols';
COMMENT ON COLUMN public.events.header_image_url IS 'Event header/banner image';
COMMENT ON COLUMN public.events.logo_url IS 'Event logo image';
COMMENT ON COLUMN public.events.website_url IS 'External event website';
COMMENT ON COLUMN public.events.social_links IS 'JSON of social media links';
COMMENT ON COLUMN public.events.contact_email IS 'Event contact email';
COMMENT ON COLUMN public.events.contact_phone IS 'Event contact phone';
COMMENT ON COLUMN public.events.hashtag IS 'Official event hashtag';
COMMENT ON COLUMN public.events.tags IS 'Array of search tags';
COMMENT ON COLUMN public.events.custom_fields IS 'Custom event fields';
COMMENT ON COLUMN public.events.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.events.published_at IS 'When event was published';
COMMENT ON COLUMN public.events.cancelled_at IS 'When event was cancelled';
COMMENT ON COLUMN public.events.cancellation_reason IS 'Reason for cancellation';

-- Strategic Indexes
CREATE INDEX idx_events_status ON public.events(status, start_datetime)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_events_organizer ON public.events(organizer_id, start_datetime DESC);
CREATE INDEX idx_events_company ON public.events(company_id) WHERE company_id IS NOT NULL;
CREATE INDEX idx_events_group ON public.events(group_id) WHERE group_id IS NOT NULL;
CREATE INDEX idx_events_type ON public.events(event_type, status);
CREATE INDEX idx_events_dates ON public.events(start_datetime, end_datetime)
    WHERE status IN ('PUBLISHED', 'REGISTRATION_OPEN', 'IN_PROGRESS');
CREATE INDEX idx_events_category ON public.events(category_id) WHERE category_id IS NOT NULL;
CREATE INDEX idx_events_private ON public.events(is_private) WHERE is_private = true;
CREATE INDEX idx_events_tags ON public.events USING gin(tags);
CREATE INDEX idx_events_social ON public.events USING gin(social_links);
CREATE INDEX idx_events_fulltext ON public.events USING gin(
    to_tsvector('english',
        event_name || ' ' ||
        COALESCE(description,'') || ' ' ||
        COALESCE(short_description,'')
    )
);

-- Trigger
DROP TRIGGER IF EXISTS update_events_timestamp ON public.events;
CREATE TRIGGER update_events_timestamp
    BEFORE UPDATE ON public.events
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS events_view_policy ON public.events;
CREATE POLICY events_view_policy ON public.events
    FOR SELECT USING (
        deleted_at IS NULL AND (
            status IN ('PUBLISHED', 'REGISTRATION_OPEN', 'REGISTRATION_CLOSED', 'IN_PROGRESS', 'COMPLETED') OR
            organizer_id = public.current_user_id() OR
            EXISTS (
                SELECT 1 FROM public.event_registrations er
                WHERE er.event_id = events.event_id
                  AND er.user_id = public.current_user_id()
            ) OR
            EXISTS (
                SELECT 1 FROM public.user_roles ur
                JOIN public.roles r ON ur.role_id = r.role_id
                WHERE ur.user_id = public.current_user_id()
                AND r.name IN ('admin', 'event_manager')
            )
        )
    );

DROP POLICY IF EXISTS events_organizer_policy ON public.events;
CREATE POLICY events_organizer_policy ON public.events
    USING (organizer_id = public.current_user_id())
    WITH CHECK (organizer_id = public.current_user_id());

-- =============================================================================
-- TABLE 198: event_categories
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 198
-- Table Name: event_categories
-- Description: Event type categorization with hierarchical structure for
--              improved discovery and recommendations.
--
-- Business Case (300 words):
-- Effective event discovery requires meaningful categorization that helps
-- attendees find relevant professional development opportunities. This table
-- defines a hierarchical taxonomy of event categories (e.g., Technology >
-- Software Development > Web Development) that powers faceted search, browse
-- experiences, and personalized recommendations. It enables consistent
-- categorization across all events on the platform.
--
-- Without standardized categories, event discovery becomes a frustrating
-- keyword search exercise. Related events are scattered, and users miss
-- valuable opportunities. This table provides the organizational framework
-- that makes event discovery intuitive and effective. Categories can be
-- used for trending analysis, content strategy, and targeted promotions.
--
-- The business impact is significant: categorized events see 45% higher
-- discovery and 30% higher registration rates. Categories enable category-
-- based email digests and recommendations that drive ongoing engagement.
-- For organizers, categories provide market intelligence about popular
-- topics and underserved niches.
--
-- Key Performance Indicators (KPIs):
--   1. Category Popularity: Events per category
--   2. Discovery Impact: Views from category browsing
--   3. Conversion by Category: Registration rate by category
--   4. Category Growth: New categories created
--   5. Search Refinement: Use of category filters
--   6. Cross-Category Attendance: Attendees across categories
--   7. Trending Categories: Fastest growing categories
--   8. Category Depth: Events at each hierarchy level
--   9. Niche Opportunity: Underserved categories
--   10. Recommendation Accuracy: Category-based recommendations
--
-- Feature Reference: EVENT-12 (Categorization)
-- Requirements Traceability: R-EVENT-026 through R-EVENT-035
--
-- Normalization: 3NF - Categories with hierarchical parent relationships
--
-- High-Write Considerations:
--   - Write-light (categories change infrequently)
--   - Read-heavy during discovery and filtering
--   - LTREE for efficient hierarchical queries
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.event_categories CASCADE;
CREATE TABLE public.event_categories (
    category_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    parent_id UUID,
    category_name VARCHAR(100) NOT NULL,
    slug VARCHAR(100) UNIQUE NOT NULL,
    description TEXT,
    icon_url VARCHAR(500),
    display_order INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    path LTREE,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_event_categories_parent FOREIGN KEY (parent_id)
        REFERENCES public.event_categories(category_id) ON DELETE CASCADE,
    CONSTRAINT unique_category_name_parent UNIQUE (parent_id, category_name),
    CONSTRAINT valid_slug CHECK (slug ~ '^[a-z0-9-]+$')
);

COMMENT ON TABLE public.event_categories IS 'Event type categorization with hierarchical structure';
COMMENT ON COLUMN public.event_categories.category_id IS 'Primary key - Unique category identifier';
COMMENT ON COLUMN public.event_categories.parent_id IS 'Parent category for hierarchy';
COMMENT ON COLUMN public.event_categories.category_name IS 'Category display name';
COMMENT ON COLUMN public.event_categories.slug IS 'URL-friendly identifier';
COMMENT ON COLUMN public.event_categories.description IS 'Category description';
COMMENT ON COLUMN public.event_categories.icon_url IS 'Category icon URL';
COMMENT ON COLUMN public.event_categories.display_order IS 'Sort order in lists';
COMMENT ON COLUMN public.event_categories.is_active IS 'Whether category is active';
COMMENT ON COLUMN public.event_categories.path IS 'LTREE path for hierarchical queries';
COMMENT ON COLUMN public.event_categories.metadata IS 'Additional category metadata';

-- Strategic Indexes
CREATE INDEX idx_event_categories_parent ON public.event_categories(parent_id)
    WHERE parent_id IS NOT NULL AND is_active = true;
CREATE INDEX idx_event_categories_active ON public.event_categories(is_active, display_order);
CREATE INDEX idx_event_categories_slug ON public.event_categories(slug);
CREATE INDEX idx_event_categories_path ON public.event_categories USING gist(path);
CREATE INDEX idx_event_categories_metadata ON public.event_categories USING gin(metadata);

-- Function to update LTREE path
CREATE OR REPLACE FUNCTION public.update_category_path()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.path := NEW.category_id::TEXT::LTREE;
    ELSE
        SELECT path || NEW.category_id::TEXT INTO NEW.path
        FROM public.event_categories
        WHERE category_id = NEW.parent_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_category_path ON public.event_categories;
CREATE TRIGGER trigger_update_category_path
    BEFORE INSERT OR UPDATE OF parent_id ON public.event_categories
    FOR EACH ROW EXECUTE FUNCTION public.update_category_path();

-- Trigger
DROP TRIGGER IF EXISTS update_event_categories_timestamp ON public.event_categories;
CREATE TRIGGER update_event_categories_timestamp
    BEFORE UPDATE ON public.event_categories
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.event_categories ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS event_categories_read_policy ON public.event_categories;
CREATE POLICY event_categories_read_policy ON public.event_categories
    FOR SELECT USING (is_active = true);

DROP POLICY IF EXISTS event_categories_admin_policy ON public.event_categories;
CREATE POLICY event_categories_admin_policy ON public.event_categories
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'event_manager')
    ));

