-- =============================================================================
-- TABLE 212: mobile_device_tokens
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 212
-- Table Name: mobile_device_tokens
-- Description: Push notification device tokens with platform-specific details,
--              user association, and token lifecycle management.
--
-- Business Case (300 words):
-- Push notifications are the primary re-engagement channel for mobile users,
-- driving daily active usage and time-sensitive professional interactions.
-- This table manages device tokens for push notification delivery across
-- iOS (APNS) and Android (FCM) platforms. It associates tokens with user
-- accounts, tracks token validity, and manages token lifecycle including
-- registration, updates, and expiration.
--
-- Without proper token management, push notifications fail silently, users
-- miss important updates, and engagement plummets. Invalid tokens accumulate
-- causing delivery failures and increased costs. This table provides the
-- authoritative source for device-to-user mapping, enabling reliable push
-- delivery, token refresh handling, and multi-device support (phone, tablet,
-- watch). It supports targeted notifications, quiet hours, and user
-- notification preferences.
--
-- The business impact is substantial: reliable push notifications increase
-- 30-day retention by 40% and daily active users by 25%. They drive timely
-- responses to messages, job applications, and connection requests. Proper
-- token management reduces push delivery costs by 30% through invalid token
-- cleanup. Multi-device support improves user experience across the device
-- ecosystem.
--
-- Key Performance Indicators (KPIs):
--   1. Token Validity Rate: Active vs. invalid tokens
--   2. Device Diversity: Users per device/platform
--   3. Notification Opt-in Rate: Tokens with notifications enabled
--   4. Token Churn: New registrations vs. invalidations
--   5. Multi-device Users: Average devices per user
--   6. Push Reliability: Successful / attempted deliveries
--   7. Platform Distribution: iOS vs. Android usage
--   8. OS Version Distribution: Users by OS version
--   9. Token Refresh Rate: Frequency of token updates
--   10. Notification Engagement: Click-through rate by device
--
-- Feature Reference: MOBILE-09 (Device Management)
-- Requirements Traceability: R-MOBILE-001 through R-MOBILE-015
--
-- Normalization: 3NF - Tokens dependent on users
--
-- High-Write Considerations:
--   - Moderate write volume (token registration/updates)
--   - Read-heavy during push notification sending
--   - Partial indexes for active tokens
--   - Regular cleanup of invalid tokens
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.mobile_device_tokens CASCADE;
CREATE TABLE public.mobile_device_tokens (
    token_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID NOT NULL,
    device_token VARCHAR(512) NOT NULL,
    platform public.device_platform NOT NULL,
    push_provider public.push_provider NOT NULL,
    device_id VARCHAR(255),
    device_name VARCHAR(255),
    device_model VARCHAR(100),
    os_version VARCHAR(50),
    app_version VARCHAR(20),
    app_build VARCHAR(20),
    bundle_id VARCHAR(255),
    timezone VARCHAR(50),
    locale VARCHAR(10),
    notifications_enabled BOOLEAN DEFAULT true,
    quiet_hours_start TIME,
    quiet_hours_end TIME,
    notification_preferences JSONB DEFAULT '{
        "messages": true,
        "connections": true,
        "job_alerts": true,
        "content": true,
        "events": true,
        "marketing": false
    }'::JSONB,
    last_active_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    last_notification_sent_at TIMESTAMP WITH TIME ZONE,
    registered_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    invalidated_at TIMESTAMP WITH TIME ZONE,
    invalidation_reason VARCHAR(100),
    is_primary_device BOOLEAN DEFAULT false,
    push_token_hash VARCHAR(64) GENERATED ALWAYS AS (encode(sha256(device_token::bytea), 'hex')) STORED,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_device_tokens_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT unique_user_device UNIQUE (user_id, device_id),
    CONSTRAINT valid_quiet_hours CHECK (
        quiet_hours_start IS NULL OR
        quiet_hours_end IS NULL OR
        quiet_hours_start != quiet_hours_end
    )
);

COMMENT ON TABLE public.mobile_device_tokens IS 'Push notification device tokens with platform details and user association';
COMMENT ON COLUMN public.mobile_device_tokens.token_id IS 'Primary key - Unique token record identifier';
COMMENT ON COLUMN public.mobile_device_tokens.user_id IS 'User account associated with device';
COMMENT ON COLUMN public.mobile_device_tokens.device_token IS 'Platform-specific push token';
COMMENT ON COLUMN public.mobile_device_tokens.platform IS 'Device platform (iOS, Android, etc.)';
COMMENT ON COLUMN public.mobile_device_tokens.push_provider IS 'Push service provider (APNS, FCM, etc.)';
COMMENT ON COLUMN public.mobile_device_tokens.device_id IS 'Vendor/advertising identifier';
COMMENT ON COLUMN public.mobile_device_tokens.device_name IS 'User-assigned device name';
COMMENT ON COLUMN public.mobile_device_tokens.device_model IS 'Device model identifier';
COMMENT ON COLUMN public.mobile_device_tokens.os_version IS 'Operating system version';
COMMENT ON COLUMN public.mobile_device_tokens.app_version IS 'App version installed';
COMMENT ON COLUMN public.mobile_device_tokens.app_build IS 'App build number';
COMMENT ON COLUMN public.mobile_device_tokens.bundle_id IS 'App bundle identifier';
COMMENT ON COLUMN public.mobile_device_tokens.timezone IS 'Device timezone';
COMMENT ON COLUMN public.mobile_device_tokens.locale IS 'Device locale';
COMMENT ON COLUMN public.mobile_device_tokens.notifications_enabled IS 'Whether notifications allowed';
COMMENT ON COLUMN public.mobile_device_tokens.quiet_hours_start IS 'Do not disturb start time';
COMMENT ON COLUMN public.mobile_device_tokens.quiet_hours_end IS 'Do not disturb end time';
COMMENT ON COLUMN public.mobile_device_tokens.notification_preferences IS 'JSON channel preferences';
COMMENT ON COLUMN public.mobile_device_tokens.last_active_at IS 'Last app activity timestamp';
COMMENT ON COLUMN public.mobile_device_tokens.last_notification_sent_at IS 'Last push sent to device';
COMMENT ON COLUMN public.mobile_device_tokens.registered_at IS 'When token was registered';
COMMENT ON COLUMN public.mobile_device_tokens.invalidated_at IS 'When token became invalid';
COMMENT ON COLUMN public.mobile_device_tokens.invalidation_reason IS 'Reason for invalidation';
COMMENT ON COLUMN public.mobile_device_tokens.is_primary_device IS 'Whether this is primary device';
COMMENT ON COLUMN public.mobile_device_tokens.push_token_hash IS 'Hashed token for lookups';

-- Strategic Indexes
CREATE INDEX idx_device_tokens_user ON public.mobile_device_tokens(user_id, platform)
    WHERE invalidated_at IS NULL AND notifications_enabled = true;
CREATE INDEX idx_device_tokens_hash ON public.mobile_device_tokens(push_token_hash);
CREATE INDEX idx_device_tokens_platform ON public.mobile_device_tokens(platform, os_version)
    WHERE invalidated_at IS NULL;
CREATE INDEX idx_device_tokens_app_version ON public.mobile_device_tokens(app_version)
    WHERE app_version IS NOT NULL;
CREATE INDEX idx_device_tokens_active ON public.mobile_device_tokens(last_active_at)
    WHERE invalidated_at IS NULL;
CREATE INDEX idx_device_tokens_invalidated ON public.mobile_device_tokens(invalidated_at)
    WHERE invalidated_at IS NOT NULL;
CREATE INDEX idx_device_tokens_preferences ON public.mobile_device_tokens USING gin(notification_preferences);
CREATE INDEX idx_device_tokens_metadata ON public.mobile_device_tokens USING gin(metadata);

-- Trigger
DROP TRIGGER IF EXISTS update_device_tokens_timestamp ON public.mobile_device_tokens;
CREATE TRIGGER update_device_tokens_timestamp
    BEFORE UPDATE ON public.mobile_device_tokens
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.mobile_device_tokens ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS device_tokens_self_policy ON public.mobile_device_tokens;
CREATE POLICY device_tokens_self_policy ON public.mobile_device_tokens
    USING (user_id = public.current_user_id())
    WITH CHECK (user_id = public.current_user_id());

DROP POLICY IF EXISTS device_tokens_system_policy ON public.mobile_device_tokens;
CREATE POLICY device_tokens_system_policy ON public.mobile_device_tokens
    USING (current_user IN ('notification_service', 'mobile_backend', 'postgres'));

-- =============================================================================
-- TABLE 213: mobile_push_logs (PARTITIONED)
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 213
-- Table Name: mobile_push_logs
-- Description: Push notification delivery logs with comprehensive tracking
--              of send attempts, delivery status, and user engagement.
--
-- Business Case (300 words):
-- Understanding push notification effectiveness requires detailed delivery
-- and engagement tracking. This table logs every push notification sent,
-- tracking its journey from send attempt through platform delivery to user
-- interaction (click, dismiss). It provides the data foundation for
-- notification analytics, A/B testing, and delivery optimization.
--
-- Without push logging, notification effectiveness is a black box. Teams
-- cannot measure which notifications drive engagement, optimize send times,
-- or identify delivery issues. This table enables data-driven notification
-- strategies that maximize engagement while minimizing user annoyance.
-- It supports personalization by tracking individual notification preferences
-- and response patterns.
--
-- The business impact is significant: notification analytics increase click-
-- through rates by 35% through optimization of content, timing, and frequency.
-- Delivery failure tracking reduces silent failures by 50%. Engagement data
-- informs user-level notification frequency caps that reduce opt-outs by 25%.
-- For product teams, it provides crucial insights into feature engagement
-- and user behavior patterns.
--
-- Key Performance Indicators (KPIs):
--   1. Delivery Success Rate: Delivered / sent notifications
--   2. Click-Through Rate (CTR): Clicks / delivered
--   3. Time-to-Click: Latency from delivery to interaction
--   4. Notification Volume: Notifications per user per day
--   5. Opt-out Rate: Disabled / total tokens
--   6. Channel Effectiveness: CTR by notification type
--   7. Platform Differences: Delivery rates by platform
--   8. Bounce Rate: Failed / sent notifications
--   9. Engagement by Time: CTR by hour/day
--   10. Notification Fatigue: CTR decline over frequency
--
-- Feature Reference: MOBILE-10 (Push Analytics)
-- Requirements Traceability: R-MOBILE-016 through R-MOBILE-030
--
-- Normalization: 3NF - Logs dependent on tokens and users
--
-- High-Write Considerations:
--   - Very high write volume (every notification logged)
--   - Partitioned by created_at for scalability and retention
--   - BRIN indexes for time-series efficiency
--   - Async processing for analytics aggregation
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.mobile_push_logs CASCADE;
CREATE TABLE public.mobile_push_logs (
    log_id UUID DEFAULT gen_random_uuid(),
    notification_id UUID NOT NULL,
    user_id UUID NOT NULL,
    token_id UUID,
    push_provider public.push_provider NOT NULL,
    notification_type VARCHAR(50) NOT NULL,
    title VARCHAR(255),
    body TEXT,
    data_payload JSONB,
    status public.notification_status NOT NULL,
    sent_at TIMESTAMP WITH TIME ZONE NOT NULL,
    delivered_at TIMESTAMP WITH TIME ZONE,
    clicked_at TIMESTAMP WITH TIME ZONE,
    dismissed_at TIMESTAMP WITH TIME ZONE,
    provider_message_id VARCHAR(255),
    provider_response JSONB,
    error_code VARCHAR(50),
    error_message TEXT,
    retry_count INTEGER DEFAULT 0,
    campaign_id UUID,
    experiment_id UUID,
    experiment_variant VARCHAR(50),
    source_screen VARCHAR(100),
    deeplink_url VARCHAR(2000),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY (log_id, created_at),
    CONSTRAINT fk_push_logs_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_push_logs_token FOREIGN KEY (token_id)
        REFERENCES public.mobile_device_tokens(token_id) ON DELETE SET NULL
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.mobile_push_logs IS 'Push notification delivery logs with engagement tracking';
COMMENT ON COLUMN public.mobile_push_logs.log_id IS 'Primary key part 1 - Unique log identifier';
COMMENT ON COLUMN public.mobile_push_logs.created_at IS 'Primary key part 2 - Partition key';
COMMENT ON COLUMN public.mobile_push_logs.notification_id IS 'Unique notification identifier';
COMMENT ON COLUMN public.mobile_push_logs.user_id IS 'Target user';
COMMENT ON COLUMN public.mobile_push_logs.token_id IS 'Device token used';
COMMENT ON COLUMN public.mobile_push_logs.push_provider IS 'Provider used for delivery';
COMMENT ON COLUMN public.mobile_push_logs.notification_type IS 'Type of notification';
COMMENT ON COLUMN public.mobile_push_logs.title IS 'Notification title';
COMMENT ON COLUMN public.mobile_push_logs.body IS 'Notification body';
COMMENT ON COLUMN public.mobile_push_logs.data_payload IS 'JSON data payload';
COMMENT ON COLUMN public.mobile_push_logs.status IS 'Current notification status';
COMMENT ON COLUMN public.mobile_push_logs.sent_at IS 'When notification was sent';
COMMENT ON COLUMN public.mobile_push_logs.delivered_at IS 'When platform confirmed delivery';
COMMENT ON COLUMN public.mobile_push_logs.clicked_at IS 'When user clicked notification';
COMMENT ON COLUMN public.mobile_push_logs.dismissed_at IS 'When user dismissed notification';
COMMENT ON COLUMN public.mobile_push_logs.provider_message_id IS 'Provider-assigned message ID';
COMMENT ON COLUMN public.mobile_push_logs.provider_response IS 'Provider API response';
COMMENT ON COLUMN public.mobile_push_logs.error_code IS 'Provider error code if failed';
COMMENT ON COLUMN public.mobile_push_logs.error_message IS 'Human-readable error';
COMMENT ON COLUMN public.mobile_push_logs.retry_count IS 'Number of retry attempts';
COMMENT ON COLUMN public.mobile_push_logs.campaign_id IS 'Associated campaign';
COMMENT ON COLUMN public.mobile_push_logs.experiment_id IS 'A/B test experiment';
COMMENT ON COLUMN public.mobile_push_logs.experiment_variant IS 'A/B test variant';
COMMENT ON COLUMN public.mobile_push_logs.source_screen IS 'Screen that triggered notification';
COMMENT ON COLUMN public.mobile_push_logs.deeplink_url IS 'Destination deep link';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_push_logs_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'mobile_push_logs_' || TO_CHAR(partition_date, 'YYYY_MM_DD');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-DD');
    end_date := TO_CHAR(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    EXECUTE FORMAT('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.mobile_push_logs
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create partition indexes
    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(user_id, sent_at DESC)',
        'idx_' || partition_name || '_user', partition_name);

    EXECUTE FORMAT('
        CREATE INDEX IF NOT EXISTS %I ON public.%I(status, sent_at) WHERE status IN (''SENT'', ''DELIVERED'')',
        'idx_' || partition_name || '_status', partition_name);

    RAISE NOTICE 'Created push logs partition: %', partition_name;
END;
$$ LANGUAGE plpgsql;

-- Create initial partitions for next 7 days
DO $$
DECLARE
    i INTEGER;
BEGIN
    FOR i IN 0..6 LOOP
        PERFORM public.create_push_logs_partition(CURRENT_DATE + i);
    END LOOP;
END $$;

-- Global indexes (apply to all partitions)
CREATE INDEX idx_push_logs_user ON public.mobile_push_logs(user_id, sent_at DESC);
CREATE INDEX idx_push_logs_notification ON public.mobile_push_logs(notification_id);
CREATE INDEX idx_push_logs_token ON public.mobile_push_logs(token_id) WHERE token_id IS NOT NULL;
CREATE INDEX idx_push_logs_campaign ON public.mobile_push_logs(campaign_id) WHERE campaign_id IS NOT NULL;
CREATE INDEX idx_push_logs_experiment ON public.mobile_push_logs(experiment_id, experiment_variant)
    WHERE experiment_id IS NOT NULL;
CREATE INDEX idx_push_logs_clicked ON public.mobile_push_logs(clicked_at) WHERE clicked_at IS NOT NULL;
CREATE INDEX idx_push_logs_payload ON public.mobile_push_logs USING gin(data_payload);

-- RLS
ALTER TABLE public.mobile_push_logs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS push_logs_user_policy ON public.mobile_push_logs;
CREATE POLICY push_logs_user_policy ON public.mobile_push_logs
    FOR SELECT USING (user_id = public.current_user_id());

DROP POLICY IF EXISTS push_logs_system_policy ON public.mobile_push_logs;
CREATE POLICY push_logs_system_policy ON public.mobile_push_logs
    USING (current_user IN ('notification_service', 'analytics_service', 'postgres'));

-- =============================================================================
-- TABLE 214: mobile_app_versions
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 214
-- Table Name: mobile_app_versions
-- Description: Mobile app version tracking with release notes, platform
--              compatibility, and rollout configuration.
--
-- Business Case (300 words):
-- Mobile app releases require careful version management across multiple
-- platforms (iOS, Android) and release tracks (production, beta, alpha).
-- This table tracks all app versions, their compatibility requirements,
-- release status, and rollout percentages. It powers version-specific
-- features, update prompts, and forced update enforcement.
--
-- Without version tracking, supporting older app versions becomes chaotic.
-- Critical updates cannot be targeted, deprecated APIs cannot be safely
-- removed, and users experience inconsistent features. This table provides
-- the version inventory that enables gradual rollouts, A/B testing of new
-- features, and targeted deprecation of outdated versions.
--
-- The business impact is substantial: structured version management reduces
-- support burden by 40% through clear compatibility boundaries. Gradual
-- rollouts catch issues before affecting all users. Version analytics inform
-- adoption rates and help prioritize bug fixes for widely-used versions.
-- Forced update capability ensures security patches reach users promptly.
--
-- Key Performance Indicators (KPIs):
--   1. Version Adoption Rate: Users per version over time
--   2. Update Velocity: Days to reach 50% adoption
--   3. Rollback Frequency: Versions requiring rollback
--   4. Minimum Version Retention: Users on oldest supported version
--   5. Beta Participation: Users in beta program
--   6. Platform Parity: Version adoption by platform
--   7. Release Success Rate: Versions without critical issues
--   8. Time-to-Update: Average user update latency
--   9. Store Review Rating: Ratings by version
--   10. Crash Rate by Version: Crashes per version
--
-- Feature Reference: MOBILE-11 (Version Management)
-- Requirements Traceability: R-MOBILE-031 through R-MOBILE-045
--
-- Normalization: 3NF - Versions independent entity
--
-- High-Write Considerations:
--   - Write-light (new versions added occasionally)
--   - Read-heavy during app startup checks
--   - Partial indexes for active versions
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.mobile_app_versions CASCADE;
CREATE TABLE public.mobile_app_versions (
    version_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    platform public.device_platform NOT NULL,
    app_version VARCHAR(20) NOT NULL,
    build_number INTEGER NOT NULL,
    semantic_version VARCHAR(20) GENERATED ALWAYS AS (
        regexp_replace(app_version, '^v', '')
    ) STORED,
    release_track VARCHAR(20) DEFAULT 'PRODUCTION',
    status VARCHAR(20) DEFAULT 'ACTIVE',
    release_date DATE NOT NULL,
    rollout_percentage INTEGER DEFAULT 100 CHECK (rollout_percentage BETWEEN 0 AND 100),
    minimum_os_version VARCHAR(20),
    release_notes TEXT,
    whats_new JSONB,
    deprecated_features TEXT[],
    required_android_permissions TEXT[],
    required_ios_permissions TEXT[],
    download_url_android VARCHAR(500),
    download_url_ios VARCHAR(500),
    store_url_android VARCHAR(500),
    store_url_ios VARCHAR(500),
    is_forced_update_eligible BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT unique_platform_version_build UNIQUE (platform, app_version, build_number),
    CONSTRAINT valid_release_track CHECK (release_track IN ('ALPHA', 'BETA', 'PRODUCTION', 'ENTERPRISE')),
    CONSTRAINT valid_status CHECK (status IN ('DRAFT', 'ACTIVE', 'DEPRECATED', 'RETIRED', 'ROLLED_BACK'))
);

COMMENT ON TABLE public.mobile_app_versions IS 'Mobile app version tracking with release notes and rollout configuration';
COMMENT ON COLUMN public.mobile_app_versions.version_id IS 'Primary key - Unique version identifier';
COMMENT ON COLUMN public.mobile_app_versions.platform IS 'Target platform';
COMMENT ON COLUMN public.mobile_app_versions.app_version IS 'Marketing version string';
COMMENT ON COLUMN public.mobile_app_versions.build_number IS 'Build number';
COMMENT ON COLUMN public.mobile_app_versions.semantic_version IS 'Normalized semantic version';
COMMENT ON COLUMN public.mobile_app_versions.release_track IS 'Release track (ALPHA, BETA, PRODUCTION)';
COMMENT ON COLUMN public.mobile_app_versions.status IS 'Version status';
COMMENT ON COLUMN public.mobile_app_versions.release_date IS 'Official release date';
COMMENT ON COLUMN public.mobile_app_versions.rollout_percentage IS 'Phased rollout percentage';
COMMENT ON COLUMN public.mobile_app_versions.minimum_os_version IS 'Minimum required OS version';
COMMENT ON COLUMN public.mobile_app_versions.release_notes IS 'Public release notes';
COMMENT ON COLUMN public.mobile_app_versions.whats_new IS 'JSON of new features';
COMMENT ON COLUMN public.mobile_app_versions.deprecated_features IS 'Array of deprecated features';
COMMENT ON COLUMN public.mobile_app_versions.required_android_permissions IS 'Android permissions required';
COMMENT ON COLUMN public.mobile_app_versions.required_ios_permissions IS 'iOS permissions required';
COMMENT ON COLUMN public.mobile_app_versions.download_url_android IS 'Direct download URL (Android)';
COMMENT ON COLUMN public.mobile_app_versions.download_url_ios IS 'Direct download URL (iOS)';
COMMENT ON COLUMN public.mobile_app_versions.store_url_android IS 'Play Store URL';
COMMENT ON COLUMN public.mobile_app_versions.store_url_ios IS 'App Store URL';
