-- =============================================================================
-- TABLE 215: mobile_forced_updates
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 215
-- Table Name: mobile_forced_updates
-- Description: Forced update configurations with urgency levels, version
--              targeting, and messaging customization.
--
-- Business Case (300 words):
-- Critical security patches, breaking API changes, and severe bugs require
-- forced updates to ensure users are on safe, functional app versions.
-- This table manages forced update campaigns, defining which versions are
-- affected, the urgency level, custom messaging, and any grace periods.
-- It enables gradual forced update rollouts to manage support load.
--
-- Without forced update capability, users remain on vulnerable or broken
-- versions indefinitely. Support teams handle issues already fixed in newer
-- versions. API changes break for users on old clients. This table provides
-- the configuration layer for update enforcement, enabling product teams to
-- set clear upgrade requirements with appropriate user communication.
--
-- The business impact is significant: forced updates reduce support ticket
-- volume by 30% for version-related issues. They ensure security patches
-- reach 95% of users within 7 days. Gradual enforcement prevents support
-- overload while maintaining service quality. Custom messaging improves user
-- understanding and compliance with update requirements.
--
-- Key Performance Indicators (KPIs):
--   1. Update Compliance Rate: Users updated within deadline
--   2. Time-to-Compliance: Days to reach target update percentage
--   3. Force Update Bypass Rate: Users bypassing or delaying
--   4. Support Impact: Ticket reduction after forced update
--   5. Message Effectiveness: Update rate by message variant
--   6. Urgency Accuracy: Correlation with actual issue severity
--   7. Grace Period Utilization: Users updating during grace period
--   8. Rollout Smoothness: Update rate over time
--   9. Version Sunset Speed: Deprecated version retirement time
--   10. User Complaints: Negative feedback during forced update
--
-- Feature Reference: MOBILE-12 (Update Enforcement)
-- Requirements Traceability: R-MOBILE-046 through R-MOBILE-060
--
-- Normalization: 3NF - Updates dependent on versions
--
-- High-Write Considerations:
--   - Write-light (update campaigns created occasionally)
--   - Read-heavy during app startup version checks
--   - Partial indexes for active campaigns
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.mobile_forced_updates CASCADE;
CREATE TABLE public.mobile_forced_updates (
    update_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    platform public.device_platform NOT NULL,
    affected_versions_below UUID NOT NULL,
    target_version_id UUID NOT NULL,
    urgency public.update_urgency NOT NULL,
    title VARCHAR(255) NOT NULL,
    message TEXT NOT NULL,
    confirm_button_text VARCHAR(50) DEFAULT 'Update Now',
    defer_button_text VARCHAR(50),
    max_deferrals INTEGER DEFAULT 0,
    grace_period_hours INTEGER DEFAULT 0,
    effective_from TIMESTAMP WITH TIME ZONE NOT NULL,
    effective_until TIMESTAMP WITH TIME ZONE,
    rollout_percentage INTEGER DEFAULT 100 CHECK (rollout_percentage BETWEEN 0 AND 100),
    is_active BOOLEAN DEFAULT true,
    affected_countries TEXT[],
    affected_locales TEXT[],
    min_app_usage_days INTEGER,
    exclude_beta_users BOOLEAN DEFAULT true,
    internal_reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_forced_updates_affected FOREIGN KEY (affected_versions_below)
        REFERENCES public.mobile_app_versions(version_id) ON DELETE RESTRICT,
    CONSTRAINT fk_forced_updates_target FOREIGN KEY (target_version_id)
        REFERENCES public.mobile_app_versions(version_id) ON DELETE RESTRICT,
    CONSTRAINT valid_dates CHECK (effective_until IS NULL OR effective_until > effective_from),
    CONSTRAINT valid_deferral CHECK (defer_button_text IS NULL OR max_deferrals > 0)
);

COMMENT ON TABLE public.mobile_forced_updates IS 'Forced update configurations with urgency levels and version targeting';
COMMENT ON COLUMN public.mobile_forced_updates.update_id IS 'Primary key - Unique update campaign identifier';
COMMENT ON COLUMN public.mobile_forced_updates.platform IS 'Target platform';
COMMENT ON COLUMN public.mobile_forced_updates.affected_versions_below IS 'Versions below this require update';
COMMENT ON COLUMN public.mobile_forced_updates.target_version_id IS 'Minimum required version';
COMMENT ON COLUMN public.mobile_forced_updates.urgency IS 'Update urgency level';
COMMENT ON COLUMN public.mobile_forced_updates.title IS 'Update prompt title';
COMMENT ON COLUMN public.mobile_forced_updates.message IS 'Update prompt message';
COMMENT ON COLUMN public.mobile_forced_updates.confirm_button_text IS 'Confirm button label';
COMMENT ON COLUMN public.mobile_forced_updates.defer_button_text IS 'Defer button label (if allowed)';
COMMENT ON COLUMN public.mobile_forced_updates.max_deferrals IS 'Maximum times user can defer';
COMMENT ON COLUMN public.mobile_forced_updates.grace_period_hours IS 'Hours before enforcement';
COMMENT ON COLUMN public.mobile_forced_updates.effective_from IS 'When update requirement starts';
COMMENT ON COLUMN public.mobile_forced_updates.effective_until IS 'When requirement expires';
COMMENT ON COLUMN public.mobile_forced_updates.rollout_percentage IS 'Percentage of users affected';
COMMENT ON COLUMN public.mobile_forced_updates.is_active IS 'Whether campaign is active';
COMMENT ON COLUMN public.mobile_forced_updates.affected_countries IS 'Array of country codes affected';
COMMENT ON COLUMN public.mobile_forced_updates.affected_locales IS 'Array of locales affected';
COMMENT ON COLUMN public.mobile_forced_updates.min_app_usage_days IS 'Minimum days before enforcing';
COMMENT ON COLUMN public.mobile_forced_updates.exclude_beta_users IS 'Whether to exclude beta users';
COMMENT ON COLUMN public.mobile_forced_updates.internal_reason IS 'Internal reason for update';

-- Strategic Indexes
CREATE INDEX idx_forced_updates_platform ON public.mobile_forced_updates(platform, is_active, effective_from)
    WHERE is_active = true;
CREATE INDEX idx_forced_updates_versions ON public.mobile_forced_updates(affected_versions_below, target_version_id);
CREATE INDEX idx_forced_updates_urgency ON public.mobile_forced_updates(urgency) WHERE is_active = true;
CREATE INDEX idx_forced_updates_countries ON public.mobile_forced_updates USING gin(affected_countries);
CREATE INDEX idx_forced_updates_locales ON public.mobile_forced_updates USING gin(affected_locales);

-- Trigger
DROP TRIGGER IF EXISTS update_forced_updates_timestamp ON public.mobile_forced_updates;
CREATE TRIGGER update_forced_updates_timestamp
    BEFORE UPDATE ON public.mobile_forced_updates
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.mobile_forced_updates ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS forced_updates_read_policy ON public.mobile_forced_updates;
