    FOR SELECT USING (true);

DROP POLICY IF EXISTS forced_updates_admin_policy ON public.mobile_forced_updates;
CREATE POLICY forced_updates_admin_policy ON public.mobile_forced_updates
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'mobile_engineer', 'release_manager')
    ));

-- =============================================================================
-- TABLE 216: mobile_deep_links
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 216
-- Table Name: mobile_deep_links
-- Description: Deep link routing configurations with pattern matching,
--              platform-specific behavior, and analytics tracking.
--
-- Business Case (300 words):
-- Deep links are the connective tissue between web content, push notifications,
-- emails, and the mobile app experience. This table defines routing rules that
-- map URL patterns to specific app screens, handling platform differences
-- (iOS universal links vs. Android app links) and fallback behaviors. It
-- powers seamless transitions from external content to in-app experiences.
--
-- Without structured deep link management, routing logic becomes hardcoded
-- and difficult to maintain. Broken links lead to poor user experiences.
-- Marketing campaigns cannot reliably drive users to specific app content.
-- This table centralizes deep link configuration, enabling dynamic routing
-- updates without app releases, A/B testing of landing experiences, and
-- comprehensive click attribution across channels.
--
-- The business impact is substantial: properly routed deep links increase
-- conversion rates by 40% by reducing friction. They enable sophisticated
-- marketing attribution and retargeting. Dynamic configuration allows rapid
-- response to content changes without app updates. Deep link analytics provide
-- insights into cross-channel user journeys and campaign effectiveness.
--
-- Key Performance Indicators (KPIs):
--   1. Deep Link Success Rate: Successful opens / clicks
--   2. Fallback Rate: Percentage falling back to web
--   3. App Install Conversion: Installs from deep links
--   4. Time-to-Content: Latency to content display
--   5. Link Rot: Broken or outdated deep links
--   6. Platform Parity: Success rate by platform
--   7. Campaign Attribution: Conversions by link source
--   8. User Retention: Retention of deep link users
--   9. Screen Load Time: Deep link to screen render
--   10. Error Rate: Failed deep link resolutions
--
-- Feature Reference: MOBILE-13 (Deep Linking)
-- Requirements Traceability: R-MOBILE-061 through R-MOBILE-075
--
-- Normalization: 3NF - Links independent configuration
--
-- High-Write Considerations:
--   - Write-light (routes configured occasionally)
--   - Read-heavy during deep link resolution
--   - Pattern matching indexes for URL routing
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.mobile_deep_links CASCADE;
CREATE TABLE public.mobile_deep_links (
    link_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    route_name VARCHAR(100) UNIQUE NOT NULL,
    url_pattern VARCHAR(500) NOT NULL,
    pattern_type VARCHAR(20) DEFAULT 'EXACT',
    platform public.device_platform NOT NULL,
    app_screen VARCHAR(255) NOT NULL,
    screen_params JSONB,
    universal_link_domain VARCHAR(255),
    app_link_host VARCHAR(255),
    requires_auth BOOLEAN DEFAULT true,
    fallback_url VARCHAR(2000),
    ios_universal_link BOOLEAN DEFAULT true,
    android_app_link BOOLEAN DEFAULT true,
    priority INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    track_clicks BOOLEAN DEFAULT true,
    expires_at TIMESTAMP WITH TIME ZONE,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT valid_pattern_type CHECK (pattern_type IN ('EXACT', 'PREFIX', 'REGEX', 'WILDCARD'))
);

COMMENT ON TABLE public.mobile_deep_links IS 'Deep link routing configurations with pattern matching and platform behavior';
COMMENT ON COLUMN public.mobile_deep_links.link_id IS 'Primary key - Unique deep link configuration';
COMMENT ON COLUMN public.mobile_deep_links.route_name IS 'Named route identifier';
COMMENT ON COLUMN public.mobile_deep_links.url_pattern IS 'URL pattern to match';
COMMENT ON COLUMN public.mobile_deep_links.pattern_type IS 'Matching strategy (EXACT, PREFIX, REGEX, WILDCARD)';
COMMENT ON COLUMN public.mobile_deep_links.platform IS 'Target platform';
COMMENT ON COLUMN public.mobile_deep_links.app_screen IS 'Target app screen identifier';
COMMENT ON COLUMN public.mobile_deep_links.screen_params IS 'JSON parameters for screen';
COMMENT ON COLUMN public.mobile_deep_links.universal_link_domain IS 'iOS universal link domain';
COMMENT ON COLUMN public.mobile_deep_links.app_link_host IS 'Android app link host';
COMMENT ON COLUMN public.mobile_deep_links.requires_auth IS 'Whether authentication required';
COMMENT ON COLUMN public.mobile_deep_links.fallback_url IS 'Fallback web URL';
COMMENT ON COLUMN public.mobile_deep_links.ios_universal_link IS 'Whether iOS universal link';
COMMENT ON COLUMN public.mobile_deep_links.android_app_link IS 'Whether Android app link';
COMMENT ON COLUMN public.mobile_deep_links.priority IS 'Match priority (higher wins)';
COMMENT ON COLUMN public.mobile_deep_links.is_active IS 'Whether route is active';
