-- =============================================================================
-- VIEWS FOR MOBILE FEATURES MODULE
-- =============================================================================

-------------------------------------------------------------------------------
-- View: vw_active_device_tokens
-- Description: Active device tokens eligible for push notifications
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_active_device_tokens AS
SELECT
    mdt.token_id,
    mdt.user_id,
    mdt.device_token,
    mdt.platform,
    mdt.push_provider,
    mdt.device_name,
    mdt.device_model,
    mdt.os_version,
    mdt.app_version,
    mdt.timezone,
    mdt.locale,
    mdt.notifications_enabled,
    mdt.quiet_hours_start,
    mdt.quiet_hours_end,
    mdt.notification_preferences,
    mdt.last_active_at,
    u.email,
    u.full_name,
    CASE
        WHEN mdt.quiet_hours_start IS NOT NULL
            AND mdt.quiet_hours_end IS NOT NULL THEN
            (CURRENT_TIME AT TIME ZONE mdt.timezone)::TIME NOT BETWEEN
                mdt.quiet_hours_start AND mdt.quiet_hours_end
        ELSE true
    END AS in_notification_window
FROM public.mobile_device_tokens mdt
JOIN public.users u ON mdt.user_id = u.user_id
WHERE mdt.invalidated_at IS NULL
  AND mdt.notifications_enabled = true
  AND u.is_active = true
  AND u.deleted_at IS NULL;

COMMENT ON VIEW public.vw_active_device_tokens IS 'Active device tokens eligible for push notifications with window calculation';

-------------------------------------------------------------------------------
-- View: vw_push_notification_analytics
-- Description: Push notification performance analytics by type and platform
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_push_notification_analytics AS
WITH daily_stats AS (
    SELECT
        DATE_TRUNC('day', sent_at) AS send_date,
        notification_type,
        push_provider,
        COUNT(*) AS total_sent,
        COUNT(CASE WHEN status IN ('DELIVERED', 'CLICKED', 'DISMISSED') THEN 1 END) AS total_delivered,
        COUNT(CASE WHEN status = 'CLICKED' THEN 1 END) AS total_clicked,
        COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS total_failed,
        AVG(EXTRACT(EPOCH FROM (delivered_at - sent_at))) AS avg_delivery_latency_seconds,
        AVG(EXTRACT(EPOCH FROM (clicked_at - delivered_at))) AS avg_time_to_click_seconds
    FROM public.mobile_push_logs
    WHERE sent_at > NOW() - INTERVAL '30 days'
    GROUP BY 1,2,3
)
SELECT
    send_date,
    notification_type,
    push_provider,
    total_sent,
    total_delivered,
    total_clicked,
    total_failed,
    ROUND(100.0 * total_delivered / NULLIF(total_sent, 0), 2) AS delivery_rate_pct,
    ROUND(100.0 * total_clicked / NULLIF(total_delivered, 0), 2) AS ctr_pct,
    ROUND(avg_delivery_latency_seconds, 2) AS avg_delivery_latency_seconds,
    ROUND(avg_time_to_click_seconds, 2) AS avg_time_to_click_seconds
FROM daily_stats
ORDER BY send_date DESC, notification_type;

COMMENT ON VIEW public.vw_push_notification_analytics IS 'Push notification performance analytics with delivery and engagement metrics';

-------------------------------------------------------------------------------
-- View: vw_app_version_distribution
-- Description: Distribution of active users across app versions
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_app_version_distribution AS
WITH active_devices AS (
    SELECT
        platform,
        app_version,
        os_version,
        COUNT(DISTINCT user_id) AS user_count,
        COUNT(*) AS device_count,
        MAX(last_active_at) AS last_active
    FROM public.mobile_device_tokens
    WHERE invalidated_at IS NULL
      AND last_active_at > NOW() - INTERVAL '30 days'
    GROUP BY 1,2,3
),
version_totals AS (
    SELECT
        platform,
        SUM(user_count) AS platform_total_users
    FROM active_devices
    GROUP BY platform
)
SELECT
    ad.platform,
    ad.app_version,
    ad.os_version,
    ad.user_count,
    ad.device_count,
    ROUND(100.0 * ad.user_count / vt.platform_total_users, 2) AS user_percentage,
    ad.last_active,
    mav.release_date,
    mav.status AS version_status
FROM active_devices ad
JOIN version_totals vt ON ad.platform = vt.platform
LEFT JOIN public.mobile_app_versions mav ON ad.platform = mav.platform
    AND ad.app_version = mav.app_version
ORDER BY ad.platform, ad.user_count DESC;

COMMENT ON VIEW public.vw_app_version_distribution IS 'Distribution of active users across app versions with percentages';

-- =============================================================================
-- FUNCTIONS FOR MOBILE FEATURES MODULE
-- =============================================================================

-------------------------------------------------------------------------------
-- Function: send_push_notification
-- Description: Send push notification to user with provider selection and logging
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.send_push_notification(
    p_user_id UUID,
    p_notification_type VARCHAR(50),
    p_title VARCHAR(255),
    p_body TEXT,
    p_data JSONB DEFAULT '{}'::JSONB,
    p_deeplink_url VARCHAR(2000) DEFAULT NULL,
    p_campaign_id UUID DEFAULT NULL,
    p_experiment_id UUID DEFAULT NULL,
    p_experiment_variant VARCHAR(50) DEFAULT NULL
)
RETURNS TABLE (
    notification_id UUID,
    tokens_sent INTEGER,
    tokens_failed INTEGER
) AS $$
DECLARE
    v_notification_id UUID := gen_random_uuid();
    v_sent_count INTEGER := 0;
    v_failed_count INTEGER := 0;
    v_token RECORD;
BEGIN
    -- Get active tokens for user within notification window
    FOR v_token IN (
        SELECT * FROM public.vw_active_device_tokens
        WHERE user_id = p_user_id
          AND in_notification_window = true
        ORDER BY is_primary_device DESC, last_active_at DESC
    ) LOOP
        BEGIN
            -- Insert log entry as pending
            INSERT INTO public.mobile_push_logs (
                notification_id,
                user_id,
                token_id,
                push_provider,
                notification_type,
                title,
                body,
                data_payload,
                status,
                sent_at,
                campaign_id,
                experiment_id,
                experiment_variant,
                deeplink_url
            ) VALUES (
                v_notification_id,
                p_user_id,
                v_token.token_id,
                v_token.push_provider,
                p_notification_type,
                p_title,
                p_body,
                p_data,
                'PENDING',
                NOW(),
                p_campaign_id,
                p_experiment_id,
                p_experiment_variant,
                p_deeplink_url
            );

            v_sent_count := v_sent_count + 1;

            -- Update token last notification timestamp
            UPDATE public.mobile_device_tokens
            SET last_notification_sent_at = NOW(),
                updated_at = NOW()
            WHERE token_id = v_token.token_id;

        EXCEPTION
            WHEN OTHERS THEN
                v_failed_count := v_failed_count + 1;
                RAISE WARNING 'Failed to queue notification for token %: %', v_token.token_id, SQLERRM;
        END;
    END LOOP;

    -- Return results
    RETURN QUERY SELECT v_notification_id, v_sent_count, v_failed_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.send_push_notification(UUID, VARCHAR, VARCHAR, TEXT, JSONB, VARCHAR, UUID, UUID, VARCHAR) IS 'Send push notification to user with provider selection and comprehensive logging';

-------------------------------------------------------------------------------
-- Function: check_forced_update
-- Description: Check if user's app version requires forced update
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.check_forced_update(
    p_user_id UUID,
    p_platform public.device_platform,
    p_current_version VARCHAR(20),
    p_country_code VARCHAR(2) DEFAULT NULL,
    p_locale VARCHAR(10) DEFAULT NULL
)
RETURNS TABLE (
    update_required BOOLEAN,
    update_id UUID,
    urgency public.update_urgency,
    title VARCHAR(255),
    message TEXT,
    confirm_button_text VARCHAR(50),
    defer_button_text VARCHAR(50),
    target_version VARCHAR(20),
    store_url VARCHAR(500)
) AS $$
DECLARE
    v_current_version_id UUID;
    v_forced_update RECORD;
BEGIN
    -- Get current version ID
    SELECT version_id INTO v_current_version_id
    FROM public.mobile_app_versions
    WHERE platform = p_platform
      AND app_version = p_current_version
      AND status = 'ACTIVE'
    LIMIT 1;

    -- Find applicable forced update
    SELECT
        fu.update_id,
        fu.urgency,
        fu.title,
        fu.message,
        fu.confirm_button_text,
        fu.defer_button_text,
        target.app_version AS target_version,
        CASE
            WHEN p_platform = 'IOS' THEN target.store_url_ios
            ELSE target.store_url_android
        END AS store_url
    INTO v_forced_update
    FROM public.mobile_forced_updates fu
    JOIN public.mobile_app_versions affected ON fu.affected_versions_below = affected.version_id
    JOIN public.mobile_app_versions target ON fu.target_version_id = target.version_id
    WHERE fu.platform = p_platform
      AND fu.is_active = true
      AND fu.effective_from <= NOW()
      AND (fu.effective_until IS NULL OR fu.effective_until > NOW())
      AND (v_current_version_id IS NULL OR affected.semantic_version > p_current_version)
      AND (fu.affected_countries IS NULL OR p_country_code = ANY(fu.affected_countries))
      AND (fu.affected_locales IS NULL OR p_locale = ANY(fu.affected_locales))
      AND (fu.exclude_beta_users = false OR NOT EXISTS (
          SELECT 1 FROM public.mobile_device_tokens
          WHERE user_id = p_user_id AND app_version ~ 'beta'
      ))
    ORDER BY fu.urgency DESC, fu.effective_from DESC
    LIMIT 1;

    IF v_forced_update.update_id IS NOT NULL THEN
        RETURN QUERY SELECT
            true,
            v_forced_update.update_id,
            v_forced_update.urgency,
            v_forced_update.title,
            v_forced_update.message,
            v_forced_update.confirm_button_text,
            v_forced_update.defer_button_text,
            v_forced_update.target_version,
            v_forced_update.store_url;
    ELSE
        RETURN QUERY SELECT false, NULL::UUID, NULL::public.update_urgency,
            NULL::VARCHAR, NULL::TEXT, NULL::VARCHAR, NULL::VARCHAR,
            NULL::VARCHAR, NULL::VARCHAR;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.check_forced_update(UUID, public.device_platform, VARCHAR, VARCHAR, VARCHAR) IS 'Check if user app version requires forced update with country and locale targeting';


