-- This module implements the following database objects:
--
-- ENUMS (10):
--   1. organization_status - Organization lifecycle states
--   2. organization_type - Organization classification
--   3. domain_verification_status - Email domain verification states
--   4. sso_protocol - SSO protocol types
--   5. sso_nameid_format - SAML NameID format types
--   6. verification_status - Employee verification states
--   7. verification_document_type - Types of verification documents
--   8. learning_compliance_status - Learning compliance states
--   9. report_schedule_frequency - Report scheduling frequencies
--   10. permission_scope - Permission scope levels
--
-- TABLES (18):
--   227. enterprise_organizations
--   228. enterprise_domains
--   229. enterprise_seats
--   230. sso_providers
--   231. sso_sessions
--   232. sso_attributes
--   233. org_chart_hierarchy
--   234. org_departments
--   235. org_teams
--   236. org_cost_centers
--   237. employee_verification
--   238. employee_verification_documents
--   239. enterprise_learning_paths
--   240. enterprise_learning_enrollments
--   241. enterprise_learning_compliance
--   242. enterprise_reports
--   243. enterprise_admin_roles
--   244. enterprise_admin_permissions
--
-- FUNCTIONS (14):
--   - verify_employee_domain() - Domain-based employee verification
--   - generate_saml_metadata() - SAML SP metadata generation
--   - validate_saml_response() - SAML response validation
--   - sync_org_chart_from_hr() - HRIS org chart sync
--   - calculate_learning_compliance() - Compliance status calculation
--   - assign_enterprise_seats() - Bulk seat assignment
--   - generate_enterprise_report() - Report generation engine
--   - check_enterprise_permission() - Permission validation
--   - provision_sso_user() - SSO user provisioning
--   - manage_org_hierarchy() - Hierarchy management
--   - verify_document_authenticity() - Document verification
--   - calculate_license_utilization() - Seat utilization analytics
--   - sync_department_structure() - Department sync from HRIS
--   - refresh_enterprise_metrics_mv() - Materialized view refresh
--
-- VIEWS (8):
--   - vw_enterprise_directory
--   - vw_org_chart_view
--   - vw_license_utilization
--   - vw_learning_compliance_dashboard
--   - vw_sso_activity_log
--   - vw_employee_verification_status
--   - vw_department_hierarchy
--   - vw_enterprise_audit_trail
--
-- MATERIALIZED VIEWS (4):
--   - mv_enterprise_usage_rollup
--   - mv_learning_compliance_summary
--   - mv_org_structure_analytics
--   - mv_sso_adoption_metrics
--
-- TRIGGERS (20):
--   - update_timestamp triggers for all tables
--   - domain_verification_triggers
--   - seat_assignment_triggers
--   - compliance_deadline_triggers
--   - audit_logging_triggers
--
-- INDEXES (80+):
--   - Strategic composite, partial, GIN, and LTREE indexes
--
-- POLICIES (45+):
--   - Row Level Security policies with organization and role-based access

-- =============================================================================
-- ENUMS FOR ENTERPRISE FEATURES MODULE
-- =============================================================================

-------------------------------------------------------------------------------
-- Enum: organization_status
-- Description: Enterprise organization lifecycle states
-- Business Case: Manages organization progression from trial through active,
--                suspended, or terminated status
-- Feature Reference: ENT-01 (Organization Lifecycle)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.organization_status CASCADE;
CREATE TYPE public.organization_status AS ENUM (
    'TRIAL',
    'ACTIVE',
    'SUSPENDED',
    'GRACE_PERIOD',
    'EXPIRED',
    'CANCELLED',
    'TERMINATED',
    'MERGED'
);
COMMENT ON TYPE public.organization_status IS 'Enterprise organization lifecycle states';

-------------------------------------------------------------------------------
-- Enum: organization_type
-- Description: Enterprise organization classification
-- Business Case: Enables differentiated features and pricing for various
--                organization types
-- Feature Reference: ENT-02 (Organization Types)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.organization_type CASCADE;
CREATE TYPE public.organization_type AS ENUM (
    'CORPORATE',
    'SMALL_BUSINESS',
    'EDUCATIONAL',
    'GOVERNMENT',
    'NONPROFIT',
    'AGENCY',
    'FRANCHISE',
    'ENTERPRISE'
);
COMMENT ON TYPE public.organization_type IS 'Enterprise organization classification';

-------------------------------------------------------------------------------
-- Enum: domain_verification_status
-- Description: Email domain verification states
-- Business Case: Tracks domain ownership verification for enterprise
--                authentication and employee identification
-- Feature Reference: ENT-03 (Domain Verification)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.domain_verification_status CASCADE;
CREATE TYPE public.domain_verification_status AS ENUM (
    'PENDING',
    'DNS_VERIFIED',
    'EMAIL_VERIFIED',
    'FILE_VERIFIED',
    'MANUALLY_VERIFIED',
    'FAILED',
    'EXPIRED',
    'REVOKED'
);
COMMENT ON TYPE public.domain_verification_status IS 'Email domain verification states';

-------------------------------------------------------------------------------
-- Enum: sso_protocol
-- Description: Single Sign-On protocol types
-- Business Case: Supports multiple enterprise SSO standards for broad
--                compatibility with identity providers
-- Feature Reference: ENT-04 (SSO Integration)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.sso_protocol CASCADE;
CREATE TYPE public.sso_protocol AS ENUM (
    'SAML_2_0',
    'OIDC',
    'OAUTH_2_0',
    'WS_FED',
    'LDAP',
    'CUSTOM'
);
COMMENT ON TYPE public.sso_protocol IS 'Single Sign-On protocol types';

-------------------------------------------------------------------------------
-- Enum: sso_nameid_format
-- Description: SAML NameID format specifications
-- Business Case: Configures proper NameID format matching for SAML identity
--                provider compatibility
-- Feature Reference: ENT-05 (SAML Configuration)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.sso_nameid_format CASCADE;
CREATE TYPE public.sso_nameid_format AS ENUM (
    'UNSPECIFIED',
    'EMAIL_ADDRESS',
    'PERSISTENT',
    'TRANSIENT',
    'X509_SUBJECT_NAME',
    'WINDOWS_DOMAIN_QUALIFIED_NAME',
    'KERBEROS_PRINCIPAL_NAME',
    'ENTITY_ID'
);
COMMENT ON TYPE public.sso_nameid_format IS 'SAML NameID format specifications';

-------------------------------------------------------------------------------
-- Enum: verification_status
-- Description: Employee verification states
-- Business Case: Tracks employee identity verification workflow for
--                enterprise trust and compliance
-- Feature Reference: ENT-06 (Employee Verification)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.verification_status CASCADE;
CREATE TYPE public.verification_status AS ENUM (
    'UNVERIFIED',
    'DOMAIN_VERIFIED',
    'PENDING_DOCUMENT',
    'DOCUMENT_SUBMITTED',
    'UNDER_REVIEW',
    'VERIFIED',
    'REJECTED',
    'EXPIRED',
    'REVERIFICATION_REQUIRED'
);
COMMENT ON TYPE public.verification_status IS 'Employee verification states';

-------------------------------------------------------------------------------
-- Enum: verification_document_type
-- Description: Types of verification documents accepted
-- Business Case: Supports various document types for employee identity
