-- Feature Reference: ENT-07 (Document Verification)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.verification_document_type CASCADE;
CREATE TYPE public.verification_document_type AS ENUM (
    'GOVERNMENT_ID',
    'PASSPORT',
    'DRIVERS_LICENSE',
    'WORK_BADGE',
    'PAY_STUB',
    'EMPLOYMENT_LETTER',
    'TAX_DOCUMENT',
    'PROFESSIONAL_LICENSE',
    'EDUCATION_CERTIFICATE',
    'UTILITY_BILL'
);
COMMENT ON TYPE public.verification_document_type IS 'Types of verification documents accepted';

-------------------------------------------------------------------------------
-- Enum: learning_compliance_status
-- Description: Learning compliance tracking states
-- Business Case: Manages mandatory training compliance for enterprise
