-- Feature Reference: ENT-08 (Learning Compliance)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.learning_compliance_status CASCADE;
CREATE TYPE public.learning_compliance_status AS ENUM (
    'NOT_STARTED',
    'IN_PROGRESS',
    'COMPLETED',
    'OVERDUE',
    'WAIVED',
    'EXEMPT',
