-- Feature Reference: ENT-09 (Reporting)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.report_schedule_frequency CASCADE;
CREATE TYPE public.report_schedule_frequency AS ENUM (
    'DAILY',
    'WEEKLY',
    'BIWEEKLY',
    'MONTHLY',
    'QUARTERLY',
