-- Feature Reference: ENT-10 (Admin Permissions)
-------------------------------------------------------------------------------
DROP TYPE IF EXISTS public.permission_scope CASCADE;
CREATE TYPE public.permission_scope AS ENUM (
    'GLOBAL',
