-- =============================================================================
-- TABLE 227: enterprise_organizations
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 227
-- Table Name: enterprise_organizations
-- Description: Enterprise customer organizations with contract details,
--              configuration settings, and lifecycle management.
--
-- Business Case (300 words):
-- Enterprise customers represent the highest-value segment requiring
-- sophisticated account management, contract tracking, and organizational
-- administration. This table serves as the master record for enterprise
-- organizations, managing their identity, contract terms, feature entitlements,
-- and overall lifecycle from trial through renewal or termination. It
-- provides the foundation for multi-tenant enterprise administration.
--
-- Without structured enterprise organization management, sales, customer
-- success, and support teams operate with fragmented information. Contract
-- details are scattered, renewal opportunities are missed, and enterprise
-- features cannot be properly provisioned. This table centralizes enterprise
-- account data, enabling professional account management, automated provisioning,
-- and comprehensive reporting across the enterprise customer base.
--
-- The business impact is substantial: proper enterprise account management
-- increases renewal rates by 35% and expansion revenue by 50%. It enables
-- self-service administration for enterprise admins, reducing support costs.
-- Contract and usage data inform customer health scores and proactive
-- engagement. For finance, it provides accurate revenue recognition and
-- forecasting based on contract terms.
--
-- Key Performance Indicators (KPIs):
--   1. Enterprise ARR: Annual recurring revenue per organization
--   2. Seat Utilization: Used / purchased seats
--   3. Renewal Rate: Percentage of contracts renewed
--   4. Time-to-Value: Days from contract to full deployment
--   5. Feature Adoption: Enterprise feature usage rate
--   6. Health Score: Composite customer health metric
--   7. Expansion Revenue: Upsell/cross-sell revenue
--   8. Support Ticket Volume: Tickets per seat
--   9. Admin Activity: Enterprise admin actions
--   10. Contract Compliance: Terms adherence
--
-- Feature Reference: ENT-11 (Organization Management)
-- Requirements Traceability: R-ENT-001 through R-ENT-020
--
-- Normalization: 3NF - Organizations independent entity
--
-- High-Write Considerations:
--   - Moderate write volume (organization updates)
--   - Read-heavy during authentication and authorization
--   - JSONB for flexible configuration
--   - Partial indexes for active organizations
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.enterprise_organizations CASCADE;
CREATE TABLE public.enterprise_organizations (
    organization_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    organization_name VARCHAR(255) NOT NULL,
    legal_name VARCHAR(255),
    tax_id VARCHAR(50),
    registration_number VARCHAR(50),
    organization_type public.organization_type NOT NULL,
    status public.organization_status DEFAULT 'TRIAL' NOT NULL,
    website_url VARCHAR(500),
    logo_url VARCHAR(1000),
    primary_contact_name VARCHAR(255),
    primary_contact_email VARCHAR(255),
    primary_contact_phone VARCHAR(50),
    billing_email VARCHAR(255),
    billing_address JSONB,
    shipping_address JSONB,
    contract_start_date DATE,
    contract_end_date DATE,
    renewal_date DATE,
    contract_value NUMERIC(15,2),
    currency CHAR(3) DEFAULT 'USD',
    payment_terms VARCHAR(50),
    purchased_seats INTEGER DEFAULT 0 CHECK (purchased_seats >= 0),
    used_seats INTEGER DEFAULT 0,
    feature_entitlements JSONB DEFAULT '{
        "sso": true,
        "advanced_analytics": true,
        "api_access": true,
        "custom_branding": false,
        "dedicated_support": false,
        "learning_management": true,
        "talent_pool": true,
        "recruiter_seats": 0,
        "sales_navigator_seats": 0,
        "premium_seats": 0
    }'::JSONB,
    security_settings JSONB DEFAULT '{
        "mfa_required": true,
        "password_policy": "STRONG",
        "session_timeout_minutes": 480,
        "ip_restrictions": [],
        "allowed_domains": []
    }'::JSONB,
    branding_settings JSONB,
    integration_settings JSONB,
    parent_organization_id UUID,
    timezone VARCHAR(50) DEFAULT 'UTC',
    locale VARCHAR(10) DEFAULT 'en-US',
    data_retention_days INTEGER DEFAULT 365,
    is_self_managed BOOLEAN DEFAULT false,
    trial_start_date DATE,
    trial_end_date DATE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    version INTEGER DEFAULT 1,
    CONSTRAINT fk_enterprise_orgs_parent FOREIGN KEY (parent_organization_id)
        REFERENCES public.enterprise_organizations(organization_id) ON DELETE SET NULL,
    CONSTRAINT valid_contract_dates CHECK (
        contract_end_date IS NULL OR
        contract_start_date IS NULL OR
        contract_end_date >= contract_start_date
    ),
    CONSTRAINT valid_trial_dates CHECK (
        trial_end_date IS NULL OR
        trial_start_date IS NULL OR
        trial_end_date >= trial_start_date
    ),
    CONSTRAINT valid_email_format CHECK (
        primary_contact_email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' AND
        (billing_email IS NULL OR billing_email ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')
    )
);

COMMENT ON TABLE public.enterprise_organizations IS 'Enterprise customer organizations with contract details and configuration';
COMMENT ON COLUMN public.enterprise_organizations.organization_id IS 'Primary key - Unique organization identifier';
COMMENT ON COLUMN public.enterprise_organizations.organization_name IS 'Display name of organization';
COMMENT ON COLUMN public.enterprise_organizations.legal_name IS 'Legal entity name';
COMMENT ON COLUMN public.enterprise_organizations.tax_id IS 'Tax identification number';
COMMENT ON COLUMN public.enterprise_organizations.registration_number IS 'Business registration number';
COMMENT ON COLUMN public.enterprise_organizations.organization_type IS 'Type of organization';
COMMENT ON COLUMN public.enterprise_organizations.status IS 'Current organization status';
COMMENT ON COLUMN public.enterprise_organizations.website_url IS 'Organization website';
COMMENT ON COLUMN public.enterprise_organizations.logo_url IS 'Organization logo';
COMMENT ON COLUMN public.enterprise_organizations.primary_contact_name IS 'Primary contact person';
COMMENT ON COLUMN public.enterprise_organizations.primary_contact_email IS 'Primary contact email';
COMMENT ON COLUMN public.enterprise_organizations.primary_contact_phone IS 'Primary contact phone';
COMMENT ON COLUMN public.enterprise_organizations.billing_email IS 'Billing contact email';
COMMENT ON COLUMN public.enterprise_organizations.billing_address IS 'JSON billing address';
COMMENT ON COLUMN public.enterprise_organizations.shipping_address IS 'JSON shipping address';
COMMENT ON COLUMN public.enterprise_organizations.contract_start_date IS 'Contract start date';
COMMENT ON COLUMN public.enterprise_organizations.contract_end_date IS 'Contract end date';
COMMENT ON COLUMN public.enterprise_organizations.renewal_date IS 'Contract renewal date';
COMMENT ON COLUMN public.enterprise_organizations.contract_value IS 'Total contract value';
COMMENT ON COLUMN public.enterprise_organizations.currency IS 'Billing currency';
COMMENT ON COLUMN public.enterprise_organizations.payment_terms IS 'Payment terms (NET30, etc.)';
COMMENT ON COLUMN public.enterprise_organizations.purchased_seats IS 'Total seats purchased';
COMMENT ON COLUMN public.enterprise_organizations.used_seats IS 'Currently assigned seats';
COMMENT ON COLUMN public.enterprise_organizations.feature_entitlements IS 'JSON of enabled features';
COMMENT ON COLUMN public.enterprise_organizations.security_settings IS 'JSON security configuration';
COMMENT ON COLUMN public.enterprise_organizations.branding_settings IS 'JSON branding customization';
COMMENT ON COLUMN public.enterprise_organizations.integration_settings IS 'JSON integration configuration';
COMMENT ON COLUMN public.enterprise_organizations.parent_organization_id IS 'Parent organization for hierarchy';
COMMENT ON COLUMN public.enterprise_organizations.timezone IS 'Primary timezone';
COMMENT ON COLUMN public.enterprise_organizations.locale IS 'Primary locale';
COMMENT ON COLUMN public.enterprise_organizations.data_retention_days IS 'Data retention period in days';
COMMENT ON COLUMN public.enterprise_organizations.is_self_managed IS 'Whether self-managed by customer';
COMMENT ON COLUMN public.enterprise_organizations.trial_start_date IS 'Trial period start';
COMMENT ON COLUMN public.enterprise_organizations.trial_end_date IS 'Trial period end';

-- Strategic Indexes
CREATE INDEX idx_enterprise_orgs_status ON public.enterprise_organizations(status, organization_type)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_enterprise_orgs_parent ON public.enterprise_organizations(parent_organization_id)
    WHERE parent_organization_id IS NOT NULL;
CREATE INDEX idx_enterprise_orgs_contract ON public.enterprise_organizations(contract_end_date, renewal_date)
    WHERE status IN ('ACTIVE', 'GRACE_PERIOD');
CREATE INDEX idx_enterprise_orgs_trial ON public.enterprise_organizations(trial_end_date)
    WHERE status = 'TRIAL';
CREATE INDEX idx_enterprise_orgs_website ON public.enterprise_organizations(website_url)
    WHERE website_url IS NOT NULL;
CREATE INDEX idx_enterprise_orgs_features ON public.enterprise_organizations USING gin(feature_entitlements);
CREATE INDEX idx_enterprise_orgs_security ON public.enterprise_organizations USING gin(security_settings);
CREATE INDEX idx_enterprise_orgs_branding ON public.enterprise_organizations USING gin(branding_settings);
CREATE INDEX idx_enterprise_orgs_integration ON public.enterprise_organizations USING gin(integration_settings);
CREATE INDEX idx_enterprise_orgs_fulltext ON public.enterprise_organizations USING gin(
    to_tsvector('english',
        organization_name || ' ' ||
        COALESCE(legal_name,'')
    )
);

-- Trigger
DROP TRIGGER IF EXISTS update_enterprise_orgs_timestamp ON public.enterprise_organizations;
CREATE TRIGGER update_enterprise_orgs_timestamp
    BEFORE UPDATE ON public.enterprise_organizations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.enterprise_organizations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS enterprise_orgs_view_policy ON public.enterprise_organizations;
CREATE POLICY enterprise_orgs_view_policy ON public.enterprise_organizations
    FOR SELECT USING (
        deleted_at IS NULL AND (
            EXISTS (
                SELECT 1 FROM public.enterprise_seats es
                WHERE es.organization_id = enterprise_organizations.organization_id
                  AND es.user_id = public.current_user_id()
                  AND es.status = 'ACTIVE'
            ) OR
            EXISTS (
                SELECT 1 FROM public.enterprise_admin_roles ear
                WHERE ear.organization_id = enterprise_organizations.organization_id
                  AND ear.user_id = public.current_user_id()
            )
        )
    );

DROP POLICY IF EXISTS enterprise_orgs_admin_policy ON public.enterprise_organizations;
CREATE POLICY enterprise_orgs_admin_policy ON public.enterprise_organizations
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'enterprise_admin', 'customer_success_manager')
    ));

-- =============================================================================
-- TABLE 228: enterprise_domains
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 228
-- Table Name: enterprise_domains
-- Description: Verified company email domains with ownership verification
--              status and automatic employee identification.
--
-- Business Case (300 words):
-- Email domain verification is the primary method for identifying and
-- provisioning enterprise employees. This table manages the association
-- between organizations and their email domains, tracking verification
-- status through DNS records, email verification, or file upload methods.
-- It enables automatic employee recognition, SSO routing, and domain-based
-- security policies.
--
-- Without domain verification, enterprises must manually provision each
-- employee, creating significant administrative overhead. Employees from
-- the same company cannot be automatically grouped for collaboration and
-- compliance features. This table provides the foundation for zero-touch
-- employee onboarding, automatic organization affiliation, and domain-based
-- access controls.
--
-- The business impact is substantial: domain verification reduces enterprise
-- onboarding time by 80% and administrative costs by 60%. It enables automatic
-- employee verification and SSO configuration. Domain-based policies ensure
-- consistent security across all employees. For the platform, verified domains
-- provide high-quality signals about professional affiliations.
--
-- Key Performance Indicators (KPIs):
--   1. Domain Coverage: Percentage of employees with verified domains
--   2. Verification Success Rate: Verified / attempted domains
--   3. Time-to-Verify: Hours from submission to verification
--   4. Auto-Provisioning Rate: Employees auto-provisioned via domain
--   5. Domain Disputes: Competing claims per domain
--   6. Verification Method Distribution: DNS vs. email vs. file
--   7. Domain Health: Domains with proper MX/SPF/DKIM
--   8. Employee Match Rate: Domain-matched employees
--   9. Subdomain Coverage: Subdomains per primary domain
--   10. Domain Churn: Domains removed or changed
--
-- Feature Reference: ENT-12 (Domain Management)
-- Requirements Traceability: R-ENT-021 through R-ENT-035
--
-- Normalization: 3NF - Domains dependent on organizations
--
-- High-Write Considerations:
--   - Moderate write volume (domain additions)
--   - Read-heavy during email verification
--   - Unique constraints for domain ownership
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.enterprise_domains CASCADE;
CREATE TABLE public.enterprise_domains (
    domain_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    organization_id UUID NOT NULL,
    domain_name VARCHAR(255) NOT NULL,
    verification_status public.domain_verification_status DEFAULT 'PENDING' NOT NULL,
    verification_method VARCHAR(20),
    verification_token VARCHAR(255),
    verification_record_type VARCHAR(10),
    verified_at TIMESTAMP WITH TIME ZONE,
    verified_by UUID,
    verification_expires_at TIMESTAMP WITH TIME ZONE,
    is_primary BOOLEAN DEFAULT false,
    is_verified BOOLEAN GENERATED ALWAYS AS (
        verification_status IN ('DNS_VERIFIED', 'EMAIL_VERIFIED', 'FILE_VERIFIED', 'MANUALLY_VERIFIED')
    ) STORED,
    auto_provision_users BOOLEAN DEFAULT true,
    auto_join_groups UUID[],
    default_role VARCHAR(50) DEFAULT 'MEMBER',
    saml_enforced BOOLEAN DEFAULT false,
    dns_records JSONB,
    verification_attempts INTEGER DEFAULT 0,
    last_verification_attempt TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_enterprise_domains_org FOREIGN KEY (organization_id)
        REFERENCES public.enterprise_organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_enterprise_domains_verified_by FOREIGN KEY (verified_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT unique_domain_per_org UNIQUE (organization_id, domain_name),
    CONSTRAINT unique_domain_globally UNIQUE (domain_name) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT valid_domain_name CHECK (domain_name ~ '^[a-zA-Z0-9][a-zA-Z0-9.-]*\.[a-zA-Z]{2,}$'),
    CONSTRAINT valid_verification_method CHECK (verification_method IN ('DNS', 'EMAIL', 'FILE', 'MANUAL'))
);

COMMENT ON TABLE public.enterprise_domains IS 'Verified company email domains with ownership verification';
COMMENT ON COLUMN public.enterprise_domains.domain_id IS 'Primary key - Unique domain identifier';
COMMENT ON COLUMN public.enterprise_domains.organization_id IS 'Owning organization';
COMMENT ON COLUMN public.enterprise_domains.domain_name IS 'Email domain (e.g., company.com)';
COMMENT ON COLUMN public.enterprise_domains.verification_status IS 'Current verification status';
COMMENT ON COLUMN public.enterprise_domains.verification_method IS 'Method used for verification';
COMMENT ON COLUMN public.enterprise_domains.verification_token IS 'Unique verification token';
COMMENT ON COLUMN public.enterprise_domains.verification_record_type IS 'DNS record type (TXT, CNAME)';
COMMENT ON COLUMN public.enterprise_domains.verified_at IS 'When domain was verified';
COMMENT ON COLUMN public.enterprise_domains.verified_by IS 'User who verified domain';
COMMENT ON COLUMN public.enterprise_domains.verification_expires_at IS 'When verification expires';
COMMENT ON COLUMN public.enterprise_domains.is_primary IS 'Whether this is primary domain';
COMMENT ON COLUMN public.enterprise_domains.auto_provision_users IS 'Auto-provision users with this domain';
COMMENT ON COLUMN public.enterprise_domains.auto_join_groups IS 'Groups to auto-join';
COMMENT ON COLUMN public.enterprise_domains.default_role IS 'Default role for auto-provisioned users';
COMMENT ON COLUMN public.enterprise_domains.saml_enforced IS 'Whether SAML required for this domain';
COMMENT ON COLUMN public.enterprise_domains.dns_records IS 'JSON of DNS verification records';
COMMENT ON COLUMN public.enterprise_domains.verification_attempts IS 'Number of verification attempts';
COMMENT ON COLUMN public.enterprise_domains.last_verification_attempt IS 'Last attempt timestamp';

-- Strategic Indexes
CREATE INDEX idx_enterprise_domains_org ON public.enterprise_domains(organization_id, is_primary);
CREATE INDEX idx_enterprise_domains_name ON public.enterprise_domains(domain_name);
CREATE INDEX idx_enterprise_domains_status ON public.enterprise_domains(verification_status)
    WHERE verification_status = 'PENDING';
CREATE INDEX idx_enterprise_domains_verified ON public.enterprise_domains(is_verified)
    WHERE is_verified = true;
CREATE INDEX idx_enterprise_domains_saml ON public.enterprise_domains(saml_enforced)
    WHERE saml_enforced = true;
CREATE INDEX idx_enterprise_domains_groups ON public.enterprise_domains USING gin(auto_join_groups);
CREATE INDEX idx_enterprise_domains_dns ON public.enterprise_domains USING gin(dns_records);

-- Function to generate verification token
CREATE OR REPLACE FUNCTION public.generate_domain_verification_token()
RETURNS TRIGGER AS $$
BEGIN
    NEW.verification_token := encode(gen_random_bytes(32), 'hex');
    NEW.verification_expires_at := NOW() + INTERVAL '30 days';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_generate_verification_token ON public.enterprise_domains;
CREATE TRIGGER trigger_generate_verification_token
    BEFORE INSERT ON public.enterprise_domains
    FOR EACH ROW EXECUTE FUNCTION public.generate_domain_verification_token();

-- Trigger
DROP TRIGGER IF EXISTS update_enterprise_domains_timestamp ON public.enterprise_domains;
CREATE TRIGGER update_enterprise_domains_timestamp
    BEFORE UPDATE ON public.enterprise_domains
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.enterprise_domains ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS enterprise_domains_view_policy ON public.enterprise_domains;
CREATE POLICY enterprise_domains_view_policy ON public.enterprise_domains
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.enterprise_seats es
            WHERE es.organization_id = enterprise_domains.organization_id
              AND es.user_id = public.current_user_id()
              AND es.status = 'ACTIVE'
        ) OR
        EXISTS (
            SELECT 1 FROM public.enterprise_admin_roles ear
            WHERE ear.organization_id = enterprise_domains.organization_id
              AND ear.user_id = public.current_user_id()
        )
    );

-- =============================================================================
-- TABLE 229: enterprise_seats
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 229
-- Table Name: enterprise_seats
-- Description: Enterprise license seat assignments with role mapping,
--              provisioning status, and usage tracking.
--
-- Business Case (300 words):
-- Enterprise customers purchase seat licenses that must be assigned to
-- individual employees. This table manages the seat assignment lifecycle,
-- tracking which users consume which license types, their provisioning
-- status, and seat utilization. It serves as the authoritative source for
-- license compliance and provides the foundation for usage-based billing
-- and analytics.
--
-- Without structured seat management, enterprises cannot effectively manage
-- their license investment. Seats may be assigned to departed employees,
-- utilization is invisible, and procurement cannot justify renewals. This
-- table enables self-service seat management for enterprise admins, automated
-- provisioning/deprovisioning workflows, and accurate license utilization
-- reporting that drives renewal and expansion decisions.
--
-- The business impact is direct: proper seat management increases license
-- utilization by 25% and reduces administrative overhead by 50%. It enables
-- just-in-time provisioning and automated deprovisioning that maintains
-- security compliance. Usage data identifies power users and training
-- opportunities. For finance, it provides accurate seat count for billing.
--
-- Key Performance Indicators (KPIs):
--   1. Seat Utilization Rate: Assigned / purchased seats
--   2. Provisioning Time: Time from assignment to active
--   3. Seat Churn: Assignments and unassignments
--   4. License Type Distribution: Seats by license tier
--   5. Inactive Seats: Seats with no activity > 30 days
--   6. Department Coverage: Seats by department
--   7. Cost per Active Seat: Total cost / active users
--   8. Seat Reclamation: Reclaimed seats per month
--   9. User Satisfaction: Seat feature usage
--   10. Renewal Readiness: Utilization trend before renewal
--
-- Feature Reference: ENT-13 (Seat Management)
-- Requirements Traceability: R-ENT-036 through R-ENT-050
--
-- Normalization: 3NF - Seats dependent on organizations and users
--
-- High-Write Considerations:
--   - Moderate write volume (seat assignments)
--   - Read-heavy during authentication and authorization
--   - Composite indexes for user lookups
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.enterprise_seats CASCADE;
CREATE TABLE public.enterprise_seats (
    seat_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    organization_id UUID NOT NULL,
    user_id UUID NOT NULL,
    license_type VARCHAR(50) NOT NULL,
    status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (status IN ('PENDING', 'ACTIVE', 'SUSPENDED', 'REVOKED', 'EXPIRED')),
    role VARCHAR(50),
    assigned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    assigned_by UUID,
    activated_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,
    last_activity_at TIMESTAMP WITH TIME ZONE,
    department_id UUID,
    cost_center_id UUID,
    custom_attributes JSONB,
    provisioning_source VARCHAR(50),
    external_id VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_enterprise_seats_org FOREIGN KEY (organization_id)
        REFERENCES public.enterprise_organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT fk_enterprise_seats_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_enterprise_seats_assigned_by FOREIGN KEY (assigned_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT unique_user_org_seat UNIQUE (organization_id, user_id),
    CONSTRAINT valid_dates CHECK (expires_at IS NULL OR expires_at > assigned_at)
);

COMMENT ON TABLE public.enterprise_seats IS 'Enterprise license seat assignments with role mapping and usage tracking';
COMMENT ON COLUMN public.enterprise_seats.seat_id IS 'Primary key - Unique seat assignment identifier';
COMMENT ON COLUMN public.enterprise_seats.organization_id IS 'Owning organization';
COMMENT ON COLUMN public.enterprise_seats.user_id IS 'Assigned user';
COMMENT ON COLUMN public.enterprise_seats.license_type IS 'Type of license (PREMIUM, RECRUITER, SALES_NAVIGATOR)';
COMMENT ON COLUMN public.enterprise_seats.status IS 'Seat assignment status';
COMMENT ON COLUMN public.enterprise_seats.role IS 'User role within organization';
COMMENT ON COLUMN public.enterprise_seats.assigned_at IS 'When seat was assigned';
COMMENT ON COLUMN public.enterprise_seats.assigned_by IS 'Admin who assigned seat';
COMMENT ON COLUMN public.enterprise_seats.activated_at IS 'When user activated seat';
COMMENT ON COLUMN public.enterprise_seats.expires_at IS 'When seat assignment expires';
COMMENT ON COLUMN public.enterprise_seats.last_activity_at IS 'Last user activity';
COMMENT ON COLUMN public.enterprise_seats.department_id IS 'Department reference';
COMMENT ON COLUMN public.enterprise_seats.cost_center_id IS 'Cost center reference';
COMMENT ON COLUMN public.enterprise_seats.custom_attributes IS 'Custom seat attributes';
COMMENT ON COLUMN public.enterprise_seats.provisioning_source IS 'Source of provisioning (MANUAL, SCIM, API)';
COMMENT ON COLUMN public.enterprise_seats.external_id IS 'External system identifier';

-- Strategic Indexes
CREATE INDEX idx_enterprise_seats_org ON public.enterprise_seats(organization_id, status, license_type);
CREATE INDEX idx_enterprise_seats_user ON public.enterprise_seats(user_id, status);
CREATE INDEX idx_enterprise_seats_department ON public.enterprise_seats(department_id)
    WHERE department_id IS NOT NULL;
CREATE INDEX idx_enterprise_seats_license ON public.enterprise_seats(license_type, status);
CREATE INDEX idx_enterprise_seats_expires ON public.enterprise_seats(expires_at)
    WHERE expires_at IS NOT NULL;
CREATE INDEX idx_enterprise_seats_activity ON public.enterprise_seats(last_activity_at)
    WHERE status = 'ACTIVE';
CREATE INDEX idx_enterprise_seats_custom ON public.enterprise_seats USING gin(custom_attributes);

-- Trigger to update organization used seats count
CREATE OR REPLACE FUNCTION public.update_org_seat_count()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'ACTIVE' THEN
        UPDATE public.enterprise_organizations
        SET used_seats = used_seats + 1,
            updated_at = NOW()
        WHERE organization_id = NEW.organization_id;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.status != 'ACTIVE' AND NEW.status = 'ACTIVE' THEN
            UPDATE public.enterprise_organizations
            SET used_seats = used_seats + 1,
                updated_at = NOW()
            WHERE organization_id = NEW.organization_id;
        ELSIF OLD.status = 'ACTIVE' AND NEW.status != 'ACTIVE' THEN
            UPDATE public.enterprise_organizations
            SET used_seats = used_seats - 1,
                updated_at = NOW()
            WHERE organization_id = NEW.organization_id;
        END IF;
    ELSIF TG_OP = 'DELETE' AND OLD.status = 'ACTIVE' THEN
        UPDATE public.enterprise_organizations
        SET used_seats = used_seats - 1,
            updated_at = NOW()
        WHERE organization_id = OLD.organization_id;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_org_seat_count ON public.enterprise_seats;
CREATE TRIGGER trigger_update_org_seat_count
    AFTER INSERT OR UPDATE OR DELETE ON public.enterprise_seats
    FOR EACH ROW EXECUTE FUNCTION public.update_org_seat_count();

-- Trigger
DROP TRIGGER IF EXISTS update_enterprise_seats_timestamp ON public.enterprise_seats;
CREATE TRIGGER update_enterprise_seats_timestamp
    BEFORE UPDATE ON public.enterprise_seats
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.enterprise_seats ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS enterprise_seats_self_policy ON public.enterprise_seats;
CREATE POLICY enterprise_seats_self_policy ON public.enterprise_seats
    FOR SELECT USING (user_id = public.current_user_id());

DROP POLICY IF EXISTS enterprise_seats_admin_policy ON public.enterprise_seats;
CREATE POLICY enterprise_seats_admin_policy ON public.enterprise_seats
    USING (EXISTS (
        SELECT 1 FROM public.enterprise_admin_roles ear
        WHERE ear.organization_id = enterprise_seats.organization_id
          AND ear.user_id = public.current_user_id()
          AND ear.role_name IN ('ORG_ADMIN', 'LICENSE_MANAGER')
    ))
    WITH CHECK (EXISTS (
        SELECT 1 FROM public.enterprise_admin_roles ear
        WHERE ear.organization_id = enterprise_seats.organization_id
          AND ear.user_id = public.current_user_id()
          AND ear.role_name IN ('ORG_ADMIN', 'LICENSE_MANAGER')
    ));

-- =============================================================================
-- TABLE 230: sso_providers
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 230
-- Table Name: sso_providers
-- Description: SSO/SAML provider configurations with certificate management,
--              attribute mapping, and authentication settings.
--
-- Business Case (300 words):
-- Enterprise customers require seamless integration with their identity
-- providers (IdP) for secure, centralized authentication. This table manages
-- SSO provider configurations including SAML metadata, certificates, endpoint
-- URLs, and authentication policies. It enables enterprise single sign-on
-- that meets security and compliance requirements while simplifying user
-- access management.
--
-- Without structured SSO configuration, enterprise IT teams struggle to
-- integrate the platform with their identity infrastructure. Security
-- policies cannot be consistently enforced, and user provisioning becomes
-- manual and error-prone. This table provides the configuration layer for
-- enterprise-grade authentication, supporting multiple IdPs, certificate
-- rotation, and just-in-time provisioning.
--
-- The business impact is critical: SSO is a mandatory requirement for 80%
-- of enterprise deals. Proper SSO configuration reduces security incidents
-- by 60% through centralized access control. It eliminates password-related
-- support tickets. For users, SSO provides seamless access that increases
-- platform adoption and satisfaction.
--
-- Key Performance Indicators (KPIs):
--   1. SSO Adoption Rate: SSO-enabled / total enterprise users
--   2. Authentication Success Rate: Successful / attempted logins
--   3. Certificate Expiry Compliance: Certificates renewed before expiry
--   4. IdP Response Time: Authentication latency
--   5. Provisioning Accuracy: Correct attribute mapping
--   6. SSO-Only Enforcement: Users authenticating via SSO
--   7. Multi-IdP Usage: Organizations with multiple IdPs
--   8. Failed Auth Reasons: Common authentication failures
--   9. Session Duration: Average SSO session length
--   10. JIT Provisioning Rate: Users created via JIT
--
-- Feature Reference: ENT-14 (SSO Configuration)
-- Requirements Traceability: R-ENT-051 through R-ENT-065
--
-- Normalization: 3NF - Providers dependent on organizations
--
-- High-Write Considerations:
--   - Write-light (SSO configuration changes infrequent)
--   - Read-heavy during authentication
--   - Secure storage for certificates and secrets
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.sso_providers CASCADE;
CREATE TABLE public.sso_providers (
    provider_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    organization_id UUID NOT NULL,
    provider_name VARCHAR(255) NOT NULL,
    protocol public.sso_protocol NOT NULL,
    is_active BOOLEAN DEFAULT true,
    is_primary BOOLEAN DEFAULT false,
    idp_entity_id VARCHAR(500),
    idp_sso_url VARCHAR(2000),
    idp_slo_url VARCHAR(2000),
    sp_entity_id VARCHAR(500),
    sp_acs_url VARCHAR(2000),
    sp_slo_url VARCHAR(2000),
    nameid_format public.sso_nameid_format DEFAULT 'EMAIL_ADDRESS',
    idp_certificate TEXT,
    idp_certificate_fingerprint VARCHAR(128),
    certificate_expires_at TIMESTAMP WITH TIME ZONE,
    signing_algorithm VARCHAR(50) DEFAULT 'RSA-SHA256',
    authn_context_class VARCHAR(255),
    force_authn BOOLEAN DEFAULT false,
    allow_unencrypted_assertion BOOLEAN DEFAULT false,
    sign_authn_requests BOOLEAN DEFAULT true,
    sign_logout_requests BOOLEAN DEFAULT true,
    want_assertions_signed BOOLEAN DEFAULT true,
    want_response_signed BOOLEAN DEFAULT true,
    metadata_url VARCHAR(500),
    metadata_xml TEXT,
    last_metadata_refresh TIMESTAMP WITH TIME ZONE,
    attribute_mapping JSONB,
    jit_provisioning BOOLEAN DEFAULT false,
    jit_default_role VARCHAR(50),
    jit_auto_join_groups UUID[],
    domain_restrictions TEXT[],
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_sso_providers_org FOREIGN KEY (organization_id)
        REFERENCES public.enterprise_organizations(organization_id) ON DELETE CASCADE,
    CONSTRAINT unique_org_provider_name UNIQUE (organization_id, provider_name),
    CONSTRAINT unique_org_entity_id UNIQUE (organization_id, idp_entity_id)
);

COMMENT ON TABLE public.sso_providers IS 'SSO/SAML provider configurations with certificate management';
COMMENT ON COLUMN public.sso_providers.provider_id IS 'Primary key - Unique provider identifier';
COMMENT ON COLUMN public.sso_providers.organization_id IS 'Owning organization';
COMMENT ON COLUMN public.sso_providers.provider_name IS 'Display name for provider';
COMMENT ON COLUMN public.sso_providers.protocol IS 'SSO protocol (SAML, OIDC, etc.)';
COMMENT ON COLUMN public.sso_providers.is_active IS 'Whether provider is active';
COMMENT ON COLUMN public.sso_providers.is_primary IS 'Whether this is primary provider';
COMMENT ON COLUMN public.sso_providers.idp_entity_id IS 'Identity Provider Entity ID';
COMMENT ON COLUMN public.sso_providers.idp_sso_url IS 'IdP Single Sign-On URL';
COMMENT ON COLUMN public.sso_providers.idp_slo_url IS 'IdP Single Logout URL';
COMMENT ON COLUMN public.sso_providers.sp_entity_id IS 'Service Provider Entity ID';
COMMENT ON COLUMN public.sso_providers.sp_acs_url IS 'SP Assertion Consumer Service URL';
COMMENT ON COLUMN public.sso_providers.sp_slo_url IS 'SP Single Logout URL';
COMMENT ON COLUMN public.sso_providers.nameid_format IS 'SAML NameID format';
COMMENT ON COLUMN public.sso_providers.idp_certificate IS 'IdP X.509 certificate (PEM)';
COMMENT ON COLUMN public.sso_providers.idp_certificate_fingerprint IS 'Certificate fingerprint';
COMMENT ON COLUMN public.sso_providers.certificate_expires_at IS 'Certificate expiration date';
COMMENT ON COLUMN public.sso_providers.signing_algorithm IS 'Signature algorithm';
COMMENT ON COLUMN public.sso_providers.authn_context_class IS 'Authentication context class';
COMMENT ON COLUMN public.sso_providers.force_authn IS 'Force re-authentication';
COMMENT ON COLUMN public.sso_providers.allow_unencrypted_assertion IS 'Allow unencrypted assertions';
COMMENT ON COLUMN public.sso_providers.sign_authn_requests IS 'Sign authentication requests';
COMMENT ON COLUMN public.sso_providers.sign_logout_requests IS 'Sign logout requests';
COMMENT ON COLUMN public.sso_providers.want_assertions_signed IS 'Require signed assertions';
COMMENT ON COLUMN public.sso_providers.want_response_signed IS 'Require signed responses';
COMMENT ON COLUMN public.sso_providers.metadata_url IS 'IdP metadata URL';
COMMENT ON COLUMN public.sso_providers.metadata_xml IS 'Cached metadata XML';
COMMENT ON COLUMN public.sso_providers.last_metadata_refresh IS 'Last metadata refresh';
COMMENT ON COLUMN public.sso_providers.attribute_mapping IS 'JSON attribute mapping';
COMMENT ON COLUMN public.sso_providers.jit_provisioning IS 'Enable just-in-time provisioning';
COMMENT ON COLUMN public.sso_providers.jit_default_role IS 'Default role for JIT users';
COMMENT ON COLUMN public.sso_providers.jit_auto_join_groups IS 'Groups for JIT users';
COMMENT ON COLUMN public.sso_providers.domain_restrictions IS 'Allowed email domains';

-- Strategic Indexes
CREATE INDEX idx_sso_providers_org ON public.sso_providers(organization_id, is_active, is_primary);
CREATE INDEX idx_sso_providers_entity ON public.sso_providers(idp_entity_id)
    WHERE idp_entity_id IS NOT NULL;
CREATE INDEX idx_sso_providers_cert_expiry ON public.sso_providers(certificate_expires_at)
    WHERE certificate_expires_at IS NOT NULL;
CREATE INDEX idx_sso_providers_jit ON public.sso_providers(jit_provisioning)
    WHERE jit_provisioning = true;
CREATE INDEX idx_sso_providers_mapping ON public.sso_providers USING gin(attribute_mapping);
CREATE INDEX idx_sso_providers_domains ON public.sso_providers USING gin(domain_restrictions);

-- Trigger
DROP TRIGGER IF EXISTS update_sso_providers_timestamp ON public.sso_providers;
CREATE TRIGGER update_sso_providers_timestamp
    BEFORE UPDATE ON public.sso_providers
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.sso_providers ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS sso_providers_admin_policy ON public.sso_providers;
CREATE POLICY sso_providers_admin_policy ON public.sso_providers
    USING (EXISTS (
        SELECT 1 FROM public.enterprise_admin_roles ear
        WHERE ear.organization_id = sso_providers.organization_id
          AND ear.user_id = public.current_user_id()
          AND ear.role_name IN ('ORG_ADMIN', 'SECURITY_ADMIN')
    ));

-- =============================================================================
-- TABLE 231: sso_sessions
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 231
-- Table Name: sso_sessions
-- Description: SSO session tracking with authentication context, session
--              duration, and logout coordination.
--
-- Business Case (300 words):
-- SSO session management is critical for security, compliance, and user
-- experience. This table tracks active SSO sessions, maintaining the link
-- between platform sessions and identity provider assertions. It enables
-- single logout (SLO), session termination across devices, and audit trails
-- for security investigations.
--
-- Without session tracking, enterprises cannot enforce session policies or
-- respond to security incidents by terminating compromised sessions. Single
-- logout cannot be coordinated with the IdP. Compliance audits lack required
-- session records. This table provides comprehensive session lifecycle
-- management that meets enterprise security and compliance requirements.
--
-- The business impact is significant: proper session management enables SOC2
-- and ISO 27001 compliance. It reduces session hijacking risk by enabling
-- rapid session termination. Single logout improves user experience and
-- security. Session analytics inform timeout policies and detect anomalies.
--
-- Key Performance Indicators (KPIs):
--   1. Active Sessions: Concurrent sessions per user
--   2. Session Duration: Average session length
--   3. Logout Coordination: Successful SLO rate
--   4. Session Termination: Admin-forced logouts
--   5. Session Timeouts: Natural vs. forced expiry
--   6. Auth Method Distribution: SSO vs. other methods
--   7. Session Anomalies: Unusual session patterns
--   8. IdP Response Time: Authentication latency
--   9. Session Re-authentication: MFA challenges
--   10. Cross-device Sessions: Users on multiple devices
--
-- Feature Reference: ENT-15 (Session Management)
-- Requirements Traceability: R-ENT-066 through R-ENT-075
--
-- Normalization: 3NF - Sessions dependent on users and providers
--
-- High-Write Considerations:
--   - High write volume (session creation/termination)
--   - Read-heavy during authentication validation
--   - Partitioned for efficient cleanup
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.sso_sessions CASCADE;
CREATE TABLE public.sso_sessions (
    session_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID NOT NULL,
    provider_id UUID NOT NULL,
    session_token VARCHAR(255) UNIQUE NOT NULL,
    saml_session_index VARCHAR(255),
    name_id VARCHAR(500),
    name_id_format public.sso_nameid_format,
    session_index VARCHAR(255),
    authn_instant TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    last_accessed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    logged_out_at TIMESTAMP WITH TIME ZONE,
    logout_type VARCHAR(20),
    ip_address INET,
    user_agent TEXT,
    device_id VARCHAR(255),
    authn_context_class VARCHAR(255),
    attributes_received JSONB,
    is_active BOOLEAN GENERATED ALWAYS AS (
        logged_out_at IS NULL AND expires_at > NOW()
    ) STORED,
    CONSTRAINT fk_sso_sessions_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_sso_sessions_provider FOREIGN KEY (provider_id)
        REFERENCES public.sso_providers(provider_id) ON DELETE CASCADE,
    CONSTRAINT valid_expiry CHECK (expires_at > created_at)
);

COMMENT ON TABLE public.sso_sessions IS 'SSO session tracking with authentication context and logout coordination';
COMMENT ON COLUMN public.sso_sessions.session_id IS 'Primary key - Unique session identifier';
COMMENT ON COLUMN public.sso_sessions.user_id IS 'Authenticated user';
COMMENT ON COLUMN public.sso_sessions.provider_id IS 'SSO provider used';
COMMENT ON COLUMN public.sso_sessions.session_token IS 'Unique session token';
COMMENT ON COLUMN public.sso_sessions.saml_session_index IS 'SAML session index from IdP';
COMMENT ON COLUMN public.sso_sessions.name_id IS 'SAML NameID value';
COMMENT ON COLUMN public.sso_sessions.name_id_format IS 'SAML NameID format';
COMMENT ON COLUMN public.sso_sessions.session_index IS 'SAML session index';
COMMENT ON COLUMN public.sso_sessions.authn_instant IS 'IdP authentication timestamp';
COMMENT ON COLUMN public.sso_sessions.expires_at IS 'Session expiration time';
COMMENT ON COLUMN public.sso_sessions.last_accessed_at IS 'Last activity timestamp';
COMMENT ON COLUMN public.sso_sessions.logged_out_at IS 'When session was terminated';
COMMENT ON COLUMN public.sso_sessions.logout_type IS 'USER, ADMIN, TIMEOUT, SLO, FORCED';
COMMENT ON COLUMN public.sso_sessions.ip_address IS 'Client IP address';
COMMENT ON COLUMN public.sso_sessions.user_agent IS 'Client user agent';
COMMENT ON COLUMN public.sso_sessions.device_id IS 'Device identifier';
COMMENT ON COLUMN public.sso_sessions.authn_context_class IS 'Authentication context';
COMMENT ON COLUMN public.sso_sessions.attributes_received IS 'JSON of received attributes';

-- Strategic Indexes
CREATE INDEX idx_sso_sessions_user ON public.sso_sessions(user_id, is_active)
    WHERE is_active = true;
CREATE INDEX idx_sso_sessions_token ON public.sso_sessions(session_token);
CREATE INDEX idx_sso_sessions_provider ON public.sso_sessions(provider_id, created_at DESC);
CREATE INDEX idx_sso_sessions_active ON public.sso_sessions(expires_at)
    WHERE is_active = true;
CREATE INDEX idx_sso_sessions_saml ON public.sso_sessions(saml_session_index)
    WHERE saml_session_index IS NOT NULL;
CREATE INDEX idx_sso_sessions_attributes ON public.sso_sessions USING gin(attributes_received);

-- Trigger
DROP TRIGGER IF EXISTS update_sso_sessions_timestamp ON public.sso_sessions;
CREATE TRIGGER update_sso_sessions_timestamp
    BEFORE UPDATE ON public.sso_sessions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.sso_sessions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS sso_sessions_self_policy ON public.sso_sessions;
CREATE POLICY sso_sessions_self_policy ON public.sso_sessions
    FOR SELECT USING (user_id = public.current_user_id());

DROP POLICY IF EXISTS sso_sessions_admin_policy ON public.sso_sessions;
CREATE POLICY sso_sessions_admin_policy ON public.sso_sessions
    USING (EXISTS (
        SELECT 1 FROM public.enterprise_admin_roles ear
        JOIN public.sso_providers sp ON ear.organization_id = sp.organization_id
        WHERE sp.provider_id = sso_sessions.provider_id
          AND ear.user_id = public.current_user_id()
          AND ear.role_name IN ('ORG_ADMIN', 'SECURITY_ADMIN')
    ));

-- =============================================================================
-- TABLE 232: sso_attributes
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 232
-- Table Name: sso_attributes
-- Description: SAML attribute mapping configurations with transformation
--              rules and default values for user provisioning.
--
-- Business Case (300 words):
-- Identity providers send user attributes in various formats and naming
-- conventions. This table defines how SAML attributes map to platform user
-- fields, enabling flexible integration with any IdP. It supports attribute
-- transformations (e.g., email to lowercase), default values, and conditional
-- mappings based on attribute presence.
--
-- Without attribute mapping, each SSO integration requires custom code to
-- handle IdP-specific attribute formats. User provisioning fails when
-- expected attributes are missing or malformed. This table provides a
-- declarative mapping layer that enterprise admins can configure without
-- engineering support, dramatically reducing integration time and complexity.
--
-- The business impact is substantial: declarative attribute mapping reduces
-- SSO integration time from weeks to hours. It eliminates custom development
-- costs for each integration. Proper attribute mapping ensures accurate user
-- profiles and group assignments, improving the user experience and reducing
-- support tickets.
--
-- Key Performance Indicators (KPIs):
--   1. Mapping Success Rate: Successful / attempted mappings
--   2. Missing Attribute Rate: Required attributes not provided
--   3. Transformation Accuracy: Correctly transformed values
--   4. Default Value Usage: Fallback to defaults
--   5. Custom Mapping Usage: Non-standard mappings per IdP
--   6. Group Sync Accuracy: Correct group assignments
--   7. Provisioning Errors: Failed user creations
--   8. Attribute Coverage: Percentage of fields mapped
--   9. Mapping Complexity: Average transformations per attribute
--   10. Admin Configuration Time: Time to complete mapping
--
-- Feature Reference: ENT-16 (Attribute Mapping)
-- Requirements Traceability: R-ENT-076 through R-ENT-085
--
-- Normalization: 3NF - Attributes dependent on providers
--
-- High-Write Considerations:
--   - Write-light (mappings configured infrequently)
--   - Read-heavy during authentication and provisioning
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.sso_attributes CASCADE;
CREATE TABLE public.sso_attributes (
    attribute_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    provider_id UUID NOT NULL,
    saml_attribute_name VARCHAR(255) NOT NULL,
    platform_field VARCHAR(100) NOT NULL,
    is_required BOOLEAN DEFAULT false,
    default_value VARCHAR(500),
    transformation VARCHAR(50),
    transformation_params JSONB,
    priority INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    condition JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_sso_attributes_provider FOREIGN KEY (provider_id)
        REFERENCES public.sso_providers(provider_id) ON DELETE CASCADE,
    CONSTRAINT unique_provider_field UNIQUE (provider_id, platform_field),
    CONSTRAINT valid_platform_field CHECK (platform_field IN (
        'email', 'first_name', 'last_name', 'full_name', 'title',
        'department', 'company', 'phone', 'mobile', 'location',
        'timezone', 'locale', 'employee_id', 'manager_email', 'groups'
    )),
    CONSTRAINT valid_transformation CHECK (transformation IN (
        'NONE', 'LOWERCASE', 'UPPERCASE', 'TRIM', 'SUBSTRING',
        'REGEX_REPLACE', 'CONCAT', 'SPLIT', 'MAP', 'CUSTOM'
    ))
);

COMMENT ON TABLE public.sso_attributes IS 'SAML attribute mapping configurations with transformation rules';
COMMENT ON COLUMN public.sso_attributes.attribute_id IS 'Primary key - Unique attribute mapping';
COMMENT ON COLUMN public.sso_attributes.provider_id IS 'Associated SSO provider';
COMMENT ON COLUMN public.sso_attributes.saml_attribute_name IS 'SAML attribute name from IdP';
COMMENT ON COLUMN public.sso_attributes.platform_field IS 'Target platform user field';
COMMENT ON COLUMN public.sso_attributes.is_required IS 'Whether attribute is required';
COMMENT ON COLUMN public.sso_attributes.default_value IS 'Default value if missing';
COMMENT ON COLUMN public.sso_attributes.transformation IS 'Transformation to apply';
COMMENT ON COLUMN public.sso_attributes.transformation_params IS 'Parameters for transformation';
COMMENT ON COLUMN public.sso_attributes.priority IS 'Priority for multiple sources';
COMMENT ON COLUMN public.sso_attributes.is_active IS 'Whether mapping is active';
COMMENT ON COLUMN public.sso_attributes.condition IS 'JSON condition for conditional mapping';

-- Strategic Indexes
CREATE INDEX idx_sso_attributes_provider ON public.sso_attributes(provider_id, is_active, priority);
CREATE INDEX idx_sso_attributes_field ON public.sso_attributes(platform_field) WHERE is_active = true;
CREATE INDEX idx_sso_attributes_required ON public.sso_attributes(provider_id) WHERE is_required = true;
CREATE INDEX idx_sso_attributes_params ON public.sso_attributes USING gin(transformation_params);
CREATE INDEX idx_sso_attributes_condition ON public.sso_attributes USING gin(condition);

-- Trigger
DROP TRIGGER IF EXISTS update_sso_attributes_timestamp ON public.sso_attributes;
CREATE TRIGGER update_sso_attributes_timestamp
    BEFORE UPDATE ON public.sso_attributes
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.sso_attributes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS sso_attributes_admin_policy ON public.sso_attributes;
CREATE POLICY sso_attributes_admin_policy ON public.sso_attributes
    USING (EXISTS (
        SELECT 1 FROM public.sso_providers sp
        JOIN public.enterprise_admin_roles ear ON sp.organization_id = ear.organization_id
        WHERE sp.provider_id = sso_attributes.provider_id
          AND ear.user_id = public.current_user_id()
          AND ear.role_name IN ('ORG_ADMIN', 'SECURITY_ADMIN')
    ));

