-------------------------------------------------------------------------------
-- View: vw_enterprise_directory
-- Description: Enterprise employee directory with organizational context
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_enterprise_directory AS
SELECT
    eo.organization_id,
    eo.organization_name,
    eo.logo_url AS org_logo,
    es.user_id,
    u.email,
    u.full_name,
    u.title,
    u.department,
    es.license_type,
    es.status AS seat_status,
    es.assigned_at,
    od.department_name,
    ot.team_name,
    occ.cost_center_code,
    occ.cost_center_name,
    och.manager_id,
    mu.full_name AS manager_name,
    ev.verification_status,
    CASE
        WHEN ev.verification_status = 'VERIFIED' THEN true
        ELSE false
    END AS is_verified_employee
FROM public.enterprise_organizations eo
JOIN public.enterprise_seats es ON eo.organization_id = es.organization_id
JOIN public.users u ON es.user_id = u.user_id
LEFT JOIN public.org_departments od ON es.department_id = od.department_id
LEFT JOIN public.org_teams ot ON u.user_id = ANY(ot.member_ids)
LEFT JOIN public.org_cost_centers occ ON es.cost_center_id = occ.cost_center_id
LEFT JOIN public.org_chart_hierarchy och ON u.user_id = och.user_id
LEFT JOIN public.users mu ON och.manager_id = mu.user_id
LEFT JOIN public.employee_verification ev ON u.user_id = ev.user_id
    AND ev.organization_id = eo.organization_id
WHERE eo.deleted_at IS NULL
  AND es.status = 'ACTIVE'
  AND u.deleted_at IS NULL
  AND u.is_active = true;

COMMENT ON VIEW public.vw_enterprise_directory IS 'Enterprise employee directory with organizational context and reporting structure';

-------------------------------------------------------------------------------
-- View: vw_org_chart_view
-- Description: Hierarchical organizational chart view with reporting relationships
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_org_chart_view AS
WITH RECURSIVE org_hierarchy AS (
    -- Anchor: Top-level employees (no manager or manager outside org)
    SELECT
        och.hierarchy_id,
        och.organization_id,
        och.user_id,
        och.manager_id,
        u.full_name,
        u.title,
        u.department,
        0 AS level,
        ARRAY[och.user_id] AS path,
        u.full_name AS path_names
    FROM public.org_chart_hierarchy och
    JOIN public.users u ON och.user_id = u.user_id
    WHERE och.manager_id IS NULL
       OR NOT EXISTS (
           SELECT 1 FROM public.org_chart_hierarchy och2
           WHERE och2.user_id = och.manager_id
       )

    UNION ALL

    -- Recursive: Direct reports
    SELECT
        och.hierarchy_id,
        och.organization_id,
        och.user_id,
        och.manager_id,
        u.full_name,
        u.title,
        u.department,
        oh.level + 1,
        oh.path || och.user_id,
        oh.path_names || ' > ' || u.full_name
    FROM public.org_chart_hierarchy och
    JOIN public.users u ON och.user_id = u.user_id
    JOIN org_hierarchy oh ON och.manager_id = oh.user_id
    WHERE NOT (och.user_id = ANY(oh.path))
      AND oh.level < 15
)
SELECT
    oh.hierarchy_id,
    oh.organization_id,
    eo.organization_name,
    oh.user_id,
    oh.full_name,
    oh.title,
    oh.department,
    oh.manager_id,
    mu.full_name AS manager_name,
    oh.level,
    oh.path,
    oh.path_names,
    (SELECT COUNT(*) FROM public.org_chart_hierarchy och2
     WHERE och2.manager_id = oh.user_id) AS direct_report_count,
    (SELECT COUNT(*) FROM public.enterprise_seats es
     WHERE es.user_id = oh.user_id AND es.status = 'ACTIVE') AS seat_count
FROM org_hierarchy oh
JOIN public.enterprise_organizations eo ON oh.organization_id = eo.organization_id
LEFT JOIN public.users mu ON oh.manager_id = mu.user_id
WHERE eo.deleted_at IS NULL
ORDER BY oh.organization_id, oh.level, oh.full_name;

COMMENT ON VIEW public.vw_org_chart_view IS 'Hierarchical organizational chart with recursive reporting relationships';

-------------------------------------------------------------------------------
-- View: vw_license_utilization
-- Description: Enterprise license utilization analytics dashboard
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_license_utilization AS
WITH license_summary AS (
    SELECT
        eo.organization_id,
        eo.organization_name,
        eo.status AS org_status,
        eo.purchased_seats,
        eo.used_seats,
        eo.contract_end_date,
        eo.renewal_date,
        jsonb_each_text(eo.feature_entitlements) AS feature_entitlement,
        COUNT(DISTINCT CASE WHEN es.status = 'ACTIVE' THEN es.user_id END) AS active_users,
        COUNT(DISTINCT CASE WHEN es.last_activity_at > NOW() - INTERVAL '30 days'
            THEN es.user_id END) AS active_users_30d,
        COUNT(DISTINCT CASE WHEN es.license_type = 'PREMIUM' AND es.status = 'ACTIVE'
            THEN es.user_id END) AS premium_seats_used,
        COUNT(DISTINCT CASE WHEN es.license_type = 'RECRUITER' AND es.status = 'ACTIVE'
            THEN es.user_id END) AS recruiter_seats_used,
        COUNT(DISTINCT CASE WHEN es.license_type = 'SALES_NAVIGATOR' AND es.status = 'ACTIVE'
            THEN es.user_id END) AS sales_nav_seats_used
    FROM public.enterprise_organizations eo
    LEFT JOIN public.enterprise_seats es ON eo.organization_id = es.organization_id
    WHERE eo.deleted_at IS NULL
    GROUP BY 1,2,3,4,5,6,7,8
)
SELECT
    organization_id,
    organization_name,
    org_status,
    purchased_seats,
    used_seats,
    ROUND(100.0 * used_seats / NULLIF(purchased_seats, 0), 2) AS utilization_pct,
    active_users,
    active_users_30d,
    ROUND(100.0 * active_users_30d / NULLIF(used_seats, 0), 2) AS engagement_pct,
    premium_seats_used,
    recruiter_seats_used,
    sales_nav_seats_used,
    contract_end_date,
    renewal_date,
    CASE
        WHEN contract_end_date IS NOT NULL
        THEN EXTRACT(DAY FROM contract_end_date - NOW())
        ELSE NULL
    END AS days_to_renewal,
    CASE
        WHEN used_seats > purchased_seats THEN 'OVER_LICENSED'
        WHEN used_seats = purchased_seats THEN 'FULLY_UTILIZED'
        WHEN ROUND(100.0 * used_seats / NULLIF(purchased_seats, 0), 2) >= 80 THEN 'HEALTHY'
        WHEN ROUND(100.0 * used_seats / NULLIF(purchased_seats, 0), 2) >= 50 THEN 'MODERATE'
        ELSE 'UNDER_UTILIZED'
    END AS utilization_status
FROM license_summary
ORDER BY purchased_seats DESC;

COMMENT ON VIEW public.vw_license_utilization IS 'Enterprise license utilization analytics with renewal tracking';

