-------------------------------------------------------------------------------
-- Function: verify_employee_domain
-- Description: Automatically verify employee based on email domain
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.verify_employee_domain(
    p_user_id UUID,
    p_email VARCHAR(255)
)
RETURNS TABLE (
    verified BOOLEAN,
    organization_id UUID,
    organization_name VARCHAR,
    domain_name VARCHAR
) AS $$
DECLARE
    v_domain TEXT;
    v_org RECORD;
BEGIN
    -- Extract domain from email
    v_domain := split_part(p_email, '@', 2);

    -- Find verified domain and organization
    SELECT
        ed.organization_id,
        eo.organization_name,
        ed.domain_name
    INTO v_org
    FROM public.enterprise_domains ed
    JOIN public.enterprise_organizations eo ON ed.organization_id = eo.organization_id
    WHERE ed.domain_name = v_domain
      AND ed.is_verified = true
      AND ed.auto_provision_users = true
      AND eo.status = 'ACTIVE'
      AND eo.deleted_at IS NULL
    LIMIT 1;

    IF v_org.organization_id IS NOT NULL THEN
        -- Update or create employee verification
        INSERT INTO public.employee_verification (
            user_id,
            organization_id,
            verification_status,
            verified_at,
            verification_method,
            email_verified
        ) VALUES (
            p_user_id,
            v_org.organization_id,
            'DOMAIN_VERIFIED',
            NOW(),
            'EMAIL_DOMAIN',
            true
        ) ON CONFLICT (user_id, organization_id) DO UPDATE
        SET verification_status = 'DOMAIN_VERIFIED',
            verified_at = NOW(),
            updated_at = NOW()
        WHERE employee_verification.verification_status != 'VERIFIED';

        -- Auto-assign seat if not already assigned
        INSERT INTO public.enterprise_seats (
            organization_id,
            user_id,
            license_type,
            status,
            assigned_at,
            activated_at,
            provisioning_source
        ) VALUES (
            v_org.organization_id,
            p_user_id,
            'PREMIUM',
            'ACTIVE',
            NOW(),
            NOW(),
            'DOMAIN_AUTO'
        ) ON CONFLICT (organization_id, user_id) DO NOTHING;

        RETURN QUERY SELECT
            true,
            v_org.organization_id,
            v_org.organization_name,
            v_org.domain_name;
    ELSE
        RETURN QUERY SELECT false, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.verify_employee_domain(UUID, VARCHAR) IS 'Automatically verify employee based on email domain and provision seat';

-------------------------------------------------------------------------------
-- Function: generate_saml_metadata
-- Description: Generate SAML Service Provider metadata XML
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.generate_saml_metadata(
    p_provider_id UUID
)
RETURNS TEXT AS $$
DECLARE
    v_provider RECORD;
    v_metadata TEXT;
BEGIN
    SELECT * INTO v_provider
    FROM public.sso_providers
    WHERE provider_id = p_provider_id;

    IF v_provider.provider_id IS NULL THEN
        RAISE EXCEPTION 'SSO provider not found';
    END IF;

    -- Generate SAML metadata XML
    v_metadata := FORMAT('
        <?xml version="1.0" encoding="UTF-8"?>
        <md:EntityDescriptor
            xmlns:md="urn:oasis:names:tc:SAML:2.0:metadata"
            entityID="%s">
            <md:SPSSODescriptor
                AuthnRequestsSigned="%s"
                WantAssertionsSigned="%s"
                protocolSupportEnumeration="urn:oasis:names:tc:SAML:2.0:protocol">
                <md:NameIDFormat>%s</md:NameIDFormat>
                <md:AssertionConsumerService
                    Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-POST"
                    Location="%s"
                    index="0" isDefault="true"/>
                <md:SingleLogoutService
                    Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-POST"
                    Location="%s"/>
                <md:SingleLogoutService
                    Binding="urn:oasis:names:tc:SAML:2.0:bindings:HTTP-Redirect"
                    Location="%s"/>
            </md:SPSSODescriptor>
        </md:EntityDescriptor>',
        COALESCE(v_provider.sp_entity_id, 'https://platform.com/saml/metadata/' || p_provider_id),
        CASE WHEN v_provider.sign_authn_requests THEN 'true' ELSE 'false' END,
        CASE WHEN v_provider.want_assertions_signed THEN 'true' ELSE 'false' END,
        CASE v_provider.nameid_format
            WHEN 'EMAIL_ADDRESS' THEN 'urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress'
            WHEN 'PERSISTENT' THEN 'urn:oasis:names:tc:SAML:2.0:nameid-format:persistent'
            WHEN 'TRANSIENT' THEN 'urn:oasis:names:tc:SAML:2.0:nameid-format:transient'
            ELSE 'urn:oasis:names:tc:SAML:1.1:nameid-format:unspecified'
        END,
        v_provider.sp_acs_url,
        v_provider.sp_slo_url,
        v_provider.sp_slo_url
    );

    RETURN v_metadata;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.generate_saml_metadata(UUID) IS 'Generate SAML Service Provider metadata XML for IdP configuration';


