-- =============================================================================
-- TABLE 245: supported_languages
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 245
-- Table Name: supported_languages
-- Description: Languages supported by the platform with locale information,
--              script details, and enablement status.
--
-- Business Case (300 words):
-- A global professional network must support multiple languages to serve
-- diverse user populations effectively. This table defines all languages
-- supported by the platform, including locale codes, writing scripts,
-- fallback languages, and enablement status. It serves as the foundation
-- for all internationalization features including UI translation, content
-- localization, and region-specific experiences.
--
-- Without structured language support, the platform cannot scale globally.
-- Users in non-English markets receive poor experiences, limiting growth
-- and engagement. This table enables systematic language rollout, tracking
-- which languages are available for UI, content, and support. It supports
-- language fallback chains for partial translations and provides the locale
-- information needed for proper date, number, and currency formatting.
--
-- The business impact is transformative: proper language support increases
-- international user acquisition by 300% and engagement by 150%. It enables
-- market entry strategies with phased language rollout. Language analytics
-- inform content localization priorities and market investment decisions.
-- For enterprise customers, language support is often a requirement for
-- global deployment.
--
-- Key Performance Indicators (KPIs):
--   1. Language Coverage: Languages supported vs. user demand
--   2. User Language Distribution: Active users by language
--   3. Translation Completeness: Translated strings / total strings
--   4. Language Growth: New users by language
--   5. Fallback Usage: Users relying on fallback languages
--   6. RTL Support: Right-to-left language adoption
--   7. Market Penetration: Users in target language markets
--   8. Localization ROI: Revenue per language investment
--   9. Support Ticket Language: Tickets by user language
--   10. Language Retention: Retention rates by language
--
-- Feature Reference: LOC-09 (Language Management)
-- Requirements Traceability: R-LOC-001 through R-LOC-015
--
-- Normalization: 3NF - Languages independent entity
--
-- High-Write Considerations:
--   - Write-light (languages added infrequently)
--   - Read-heavy during every page load for locale detection
--   - Cached in application layer
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.supported_languages CASCADE;
CREATE TABLE public.supported_languages (
    language_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    language_code VARCHAR(10) NOT NULL UNIQUE,
    language_name VARCHAR(100) NOT NULL,
    native_name VARCHAR(100),
    locale_code VARCHAR(20) NOT NULL UNIQUE,
    script public.language_script NOT NULL,
    text_direction VARCHAR(3) DEFAULT 'LTR' CHECK (text_direction IN ('LTR', 'RTL')),
    fallback_language_id UUID,
    is_active BOOLEAN DEFAULT true,
    is_default BOOLEAN DEFAULT false,
    is_ui_supported BOOLEAN DEFAULT true,
    is_content_supported BOOLEAN DEFAULT true,
    translation_completeness INTEGER DEFAULT 0 CHECK (translation_completeness BETWEEN 0 AND 100),
    priority INTEGER DEFAULT 0,
    decimal_separator VARCHAR(1) DEFAULT '.',
    thousand_separator VARCHAR(1) DEFAULT ',',
    date_format VARCHAR(20) DEFAULT 'YYYY-MM-DD',
    time_format VARCHAR(10) DEFAULT '24',
    first_day_of_week INTEGER DEFAULT 1 CHECK (first_day_of_week BETWEEN 0 AND 6),
    currency_symbol_position VARCHAR(10) DEFAULT 'BEFORE',
    flag_icon_url VARCHAR(500),
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_supported_languages_fallback FOREIGN KEY (fallback_language_id)
        REFERENCES public.supported_languages(language_id) ON DELETE SET NULL,
    CONSTRAINT valid_language_code CHECK (language_code ~ '^[a-z]{2,3}(-[A-Z][a-z]{3})?(-[A-Z]{2})?$'),
    CONSTRAINT valid_locale_code CHECK (locale_code ~ '^[a-z]{2,3}_[A-Z]{2}(@[a-z]+)?$')
);

COMMENT ON TABLE public.supported_languages IS 'Languages supported by the platform with locale and script information';
COMMENT ON COLUMN public.supported_languages.language_id IS 'Primary key - Unique language identifier';
COMMENT ON COLUMN public.supported_languages.language_code IS 'ISO 639 language code (e.g., en, es, zh)';
COMMENT ON COLUMN public.supported_languages.language_name IS 'English name of language';
COMMENT ON COLUMN public.supported_languages.native_name IS 'Native name of language';
COMMENT ON COLUMN public.supported_languages.locale_code IS 'Full locale code (e.g., en_US, es_ES, zh_CN)';
COMMENT ON COLUMN public.supported_languages.script IS 'Writing script type';
COMMENT ON COLUMN public.supported_languages.text_direction IS 'LTR (left-to-right) or RTL (right-to-left)';
COMMENT ON COLUMN public.supported_languages.fallback_language_id IS 'Fallback language for missing translations';
COMMENT ON COLUMN public.supported_languages.is_active IS 'Whether language is available';
COMMENT ON COLUMN public.supported_languages.is_default IS 'Whether this is default language';
COMMENT ON COLUMN public.supported_languages.is_ui_supported IS 'Whether UI is translated';
COMMENT ON COLUMN public.supported_languages.is_content_supported IS 'Whether content translation available';
COMMENT ON COLUMN public.supported_languages.translation_completeness IS 'Estimated translation coverage (0-100)';
COMMENT ON COLUMN public.supported_languages.priority IS 'Display priority in language selectors';
COMMENT ON COLUMN public.supported_languages.decimal_separator IS 'Decimal separator character';
COMMENT ON COLUMN public.supported_languages.thousand_separator IS 'Thousands separator character';
COMMENT ON COLUMN public.supported_languages.date_format IS 'Preferred date format pattern';
COMMENT ON COLUMN public.supported_languages.time_format IS '12 or 24 hour time format';
COMMENT ON COLUMN public.supported_languages.first_day_of_week IS 'First day of week (0=Sunday, 1=Monday)';
COMMENT ON COLUMN public.supported_languages.currency_symbol_position IS 'BEFORE or AFTER amount';
COMMENT ON COLUMN public.supported_languages.flag_icon_url IS 'URL to flag icon';

-- Strategic Indexes
CREATE INDEX idx_supported_languages_active ON public.supported_languages(is_active, priority)
    WHERE is_active = true;
CREATE INDEX idx_supported_languages_code ON public.supported_languages(language_code);
CREATE INDEX idx_supported_languages_locale ON public.supported_languages(locale_code);
CREATE INDEX idx_supported_languages_default ON public.supported_languages(is_default)
    WHERE is_default = true;
CREATE INDEX idx_supported_languages_script ON public.supported_languages(script);
CREATE INDEX idx_supported_languages_rtl ON public.supported_languages(text_direction)
    WHERE text_direction = 'RTL';
CREATE INDEX idx_supported_languages_metadata ON public.supported_languages USING gin(metadata);

