-- =============================================================================
-- TABLE 246: content_translations
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 246
-- Table Name: content_translations
-- Description: Translated content items with versioning, quality scoring,
--              and machine/human translation tracking.
--
-- Business Case (300 words):
-- Content must be accessible in users' preferred languages to maximize
-- engagement and value. This table stores translations for all platform
-- content including posts, articles, and descriptions. It supports both
-- machine translation for speed and human translation for quality, with
-- versioning to track when original content changes and translations need
-- updating.
--
-- Without translation management, content is siloed by language, creating
-- fragmented user experiences and limiting cross-cultural professional
-- networking. Users miss valuable content, and content creators cannot
-- reach global audiences. This table enables seamless multilingual content
-- delivery, connecting professionals across language barriers.
--
-- The business impact is substantial: translated content increases engagement
-- by 200% for non-English users and expands content creator reach by 400%.
-- It enables global knowledge sharing and professional development. Machine
-- translation provides immediate accessibility while human translation
-- ensures quality for high-value content. Translation analytics inform
-- language investment decisions.
--
-- Key Performance Indicators (KPIs):
--   1. Translation Coverage: Translated content / total content
--   2. Translation Quality Score: Human-rated quality
--   3. Machine Translation Usage: MT vs. human translations
--   4. Translation Freshness: Outdated translations percentage
--   5. Language Engagement: Views by language version
--   6. Translation Cost: Cost per translated word
--   7. Translator Productivity: Words per translator
--   8. Content Reach: Audience size by language
--   9. Translation ROI: Engagement lift from translation
--   10. Outdated Content: Translations needing update
--
-- Feature Reference: LOC-10 (Content Translation)
-- Requirements Traceability: R-LOC-016 through R-LOC-030
--
-- Normalization: 3NF - Translations dependent on content and languages
--
-- High-Write Considerations:
--   - Moderate write volume (translations added/updated)
--   - Read-heavy during content display
--   - Full-text search for translated content
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.content_translations CASCADE;
CREATE TABLE public.content_translations (
    translation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    content_id UUID NOT NULL,
    language_id UUID NOT NULL,
    title VARCHAR(500),
    body TEXT,
    summary TEXT,
    translated_title VARCHAR(500),
    translated_body TEXT,
    translated_summary TEXT,
    status public.translation_status DEFAULT 'PENDING' NOT NULL,
    translation_method VARCHAR(20) DEFAULT 'MACHINE',
    quality_score INTEGER CHECK (quality_score BETWEEN 0 AND 100),
    translated_by UUID,
    reviewed_by UUID,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    published_at TIMESTAMP WITH TIME ZONE,
    source_content_hash VARCHAR(64),
    word_count INTEGER,
    character_count INTEGER,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_content_translations_content FOREIGN KEY (content_id)
        REFERENCES public.contents(content_id) ON DELETE CASCADE,
    CONSTRAINT fk_content_translations_language FOREIGN KEY (language_id)
        REFERENCES public.supported_languages(language_id) ON DELETE CASCADE,
    CONSTRAINT fk_content_translations_translator FOREIGN KEY (translated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_content_translations_reviewer FOREIGN KEY (reviewed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT unique_content_language UNIQUE (content_id, language_id),
    CONSTRAINT valid_translation_method CHECK (translation_method IN ('MACHINE', 'HUMAN', 'HYBRID', 'IMPORTED'))
);

COMMENT ON TABLE public.content_translations IS 'Translated content items with versioning and quality tracking';
COMMENT ON COLUMN public.content_translations.translation_id IS 'Primary key - Unique translation identifier';
COMMENT ON COLUMN public.content_translations.content_id IS 'Original content reference';
COMMENT ON COLUMN public.content_translations.language_id IS 'Target language';
COMMENT ON COLUMN public.content_translations.title IS 'Original title (for reference)';
COMMENT ON COLUMN public.content_translations.body IS 'Original body (for reference)';
COMMENT ON COLUMN public.content_translations.summary IS 'Original summary (for reference)';
COMMENT ON COLUMN public.content_translations.translated_title IS 'Translated title';
COMMENT ON COLUMN public.content_translations.translated_body IS 'Translated body';
COMMENT ON COLUMN public.content_translations.translated_summary IS 'Translated summary';
COMMENT ON COLUMN public.content_translations.status IS 'Translation workflow status';
COMMENT ON COLUMN public.content_translations.translation_method IS 'MACHINE, HUMAN, HYBRID, IMPORTED';
COMMENT ON COLUMN public.content_translations.quality_score IS 'Quality rating (0-100)';
COMMENT ON COLUMN public.content_translations.translated_by IS 'Translator user reference';
COMMENT ON COLUMN public.content_translations.reviewed_by IS 'Reviewer user reference';
COMMENT ON COLUMN public.content_translations.reviewed_at IS 'When translation was reviewed';
COMMENT ON COLUMN public.content_translations.published_at IS 'When translation was published';
COMMENT ON COLUMN public.content_translations.source_content_hash IS 'Hash to detect source changes';
COMMENT ON COLUMN public.content_translations.word_count IS 'Word count of translation';
COMMENT ON COLUMN public.content_translations.character_count IS 'Character count of translation';

-- Strategic Indexes
CREATE INDEX idx_content_translations_content ON public.content_translations(content_id, language_id);
CREATE INDEX idx_content_translations_language ON public.content_translations(language_id, status);
CREATE INDEX idx_content_translations_status ON public.content_translations(status)
    WHERE status IN ('PENDING', 'NEEDS_REVIEW');
CREATE INDEX idx_content_translations_quality ON public.content_translations(quality_score)
    WHERE quality_score IS NOT NULL;
CREATE INDEX idx_content_translations_published ON public.content_translations(published_at)
    WHERE published_at IS NOT NULL;
CREATE INDEX idx_content_translations_fulltext ON public.content_translations USING gin(
    to_tsvector('simple', COALESCE(translated_title,'') || ' ' || COALESCE(translated_body,''))
);

-- Trigger to detect source content changes
CREATE OR REPLACE FUNCTION public.detect_content_changes()
RETURNS TRIGGER AS $$
DECLARE
    v_source_hash TEXT;
BEGIN
    -- Calculate hash of source content
    SELECT encode(sha256((COALESCE(c.title,'') || COALESCE(c.body,'') || COALESCE(c.summary,''))::bytea), 'hex')
    INTO v_source_hash
    FROM public.contents c
    WHERE c.content_id = NEW.content_id;

    IF v_source_hash != NEW.source_content_hash THEN
        NEW.status := 'OUTDATED';
        NEW.source_content_hash := v_source_hash;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_detect_content_changes ON public.content_translations;
CREATE TRIGGER trigger_detect_content_changes
    BEFORE UPDATE ON public.content_translations
    FOR EACH ROW EXECUTE FUNCTION public.detect_content_changes();

-- Trigger
DROP TRIGGER IF EXISTS update_content_translations_timestamp ON public.content_translations;
CREATE TRIGGER update_content_translations_timestamp
    BEFORE UPDATE ON public.content_translations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.content_translations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS content_translations_read_policy ON public.content_translations;
CREATE POLICY content_translations_read_policy ON public.content_translations
    FOR SELECT USING (status IN ('PUBLISHED', 'REVIEWED'));

DROP POLICY IF EXISTS content_translations_admin_policy ON public.content_translations;
CREATE POLICY content_translations_admin_policy ON public.content_translations
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'content_manager', 'translator')
    ));

