    translated_responsibilities TEXT,
    translated_qualifications TEXT,
    translated_benefits TEXT,
    translated_company_description TEXT,
    status public.translation_status DEFAULT 'PUBLISHED' NOT NULL,
    translation_method VARCHAR(20) DEFAULT 'MACHINE',
    quality_score INTEGER CHECK (quality_score BETWEEN 0 AND 100),
    published_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_job_translations_job FOREIGN KEY (job_id)
        REFERENCES public.job_listings(job_id) ON DELETE CASCADE,
    CONSTRAINT fk_job_translations_language FOREIGN KEY (language_id)
        REFERENCES public.supported_languages(language_id) ON DELETE CASCADE,
    CONSTRAINT unique_job_language UNIQUE (job_id, language_id)
);

COMMENT ON TABLE public.job_translations IS 'Translated job listings with localized descriptions and requirements';
COMMENT ON COLUMN public.job_translations.translation_id IS 'Primary key - Unique translation identifier';
COMMENT ON COLUMN public.job_translations.job_id IS 'Job listing reference';
COMMENT ON COLUMN public.job_translations.language_id IS 'Target language';
COMMENT ON COLUMN public.job_translations.translated_title IS 'Translated job title';
COMMENT ON COLUMN public.job_translations.translated_description IS 'Translated job description';
COMMENT ON COLUMN public.job_translations.translated_requirements IS 'Translated requirements';
COMMENT ON COLUMN public.job_translations.translated_responsibilities IS 'Translated responsibilities';
COMMENT ON COLUMN public.job_translations.translated_qualifications IS 'Translated qualifications';
COMMENT ON COLUMN public.job_translations.translated_benefits IS 'Translated benefits';
COMMENT ON COLUMN public.job_translations.translated_company_description IS 'Translated company description';
COMMENT ON COLUMN public.job_translations.status IS 'Translation status';
COMMENT ON COLUMN public.job_translations.translation_method IS 'How translation was created';
COMMENT ON COLUMN public.job_translations.quality_score IS 'Translation quality score';
COMMENT ON COLUMN public.job_translations.published_at IS 'When translation was published';

-- Strategic Indexes
CREATE INDEX idx_job_translations_job ON public.job_translations(job_id, language_id);
CREATE INDEX idx_job_translations_language ON public.job_translations(language_id, status);
CREATE INDEX idx_job_translations_quality ON public.job_translations(quality_score)
    WHERE quality_score IS NOT NULL;
CREATE INDEX idx_job_translations_fulltext ON public.job_translations USING gin(
    to_tsvector('simple',
        COALESCE(translated_title,'') || ' ' ||
        COALESCE(translated_description,'') || ' ' ||
        COALESCE(translated_requirements,'')
    )
);

-- Trigger
DROP TRIGGER IF EXISTS update_job_translations_timestamp ON public.job_translations;
CREATE TRIGGER update_job_translations_timestamp
    BEFORE UPDATE ON public.job_translations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.job_translations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS job_translations_read_policy ON public.job_translations;
CREATE POLICY job_translations_read_policy ON public.job_translations
    FOR SELECT USING (status = 'PUBLISHED');

DROP POLICY IF EXISTS job_translations_employer_policy ON public.job_translations;
CREATE POLICY job_translations_employer_policy ON public.job_translations
    USING (
        EXISTS (
            SELECT 1 FROM public.job_listings jl
            WHERE jl.job_id = job_translations.job_id
              AND jl.employer_id = public.current_user_id()
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1 FROM public.job_listings jl
            WHERE jl.job_id = job_translations.job_id
              AND jl.employer_id = public.current_user_id()
        )
    );

-- =============================================================================
-- TABLE 249: company_translations
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 249
-- Table Name: company_translations
-- Description: Translated company profiles with localized descriptions,
--              culture information, and brand messaging.
--
-- Business Case (300 words):
-- Global companies need to present their brand consistently across languages
-- and cultures. This table stores translations for company profiles including
-- descriptions, culture statements, and brand messaging. It enables companies
-- to maintain authentic, culturally-appropriate presence in each market
-- while managing a unified company identity.
--
-- Without company translations, global brands appear disconnected from
-- local markets. Important cultural nuances are lost, and employer branding
-- suffers internationally. This table enables companies to localize their
-- presence appropriately, demonstrating respect for local cultures and
-- improving talent attraction in diverse markets.
--
-- The business impact is significant: localized company profiles increase
-- job applications by 200% in target markets and improve employer brand
-- perception by 150%. They support global recruitment marketing and
-- diversity initiatives. For the platform, company translations increase
-- international company engagement and premium feature adoption.
--
-- Key Performance Indicators (KPIs):
--   1. Multilingual Company Rate: Companies with multiple languages
--   2. Profile Views by Language: Views per language version
--   3. Follower Growth: Followers by language market
--   4. Job Application Lift: Applications after translation
--   5. Brand Perception: Survey scores by market
--   6. Translation Completeness: Fields translated percentage
--   7. Market-Specific Engagement: Interactions by language
--   8. Localization ROI: Recruitment cost reduction
--   9. Cultural Adaptation: Customizations per market
--   10. Global Brand Consistency: Cross-market message alignment
--
-- Feature Reference: LOC-13 (Company Translation)
-- Requirements Traceability: R-LOC-061 through R-LOC-075
--
-- Normalization: 3NF - Translations dependent on companies and languages
--
-- High-Write Considerations:
--   - Light write volume (company profile updates)
--   - Read-heavy during company page views
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.company_translations CASCADE;
CREATE TABLE public.company_translations (
    translation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    company_id UUID NOT NULL,
    language_id UUID NOT NULL,
    translated_name VARCHAR(255),
    translated_tagline VARCHAR(500),
    translated_description TEXT,
    translated_culture TEXT,
    translated_mission TEXT,
    translated_vision TEXT,
    translated_values TEXT,
    localized_website VARCHAR(500),
    status public.translation_status DEFAULT 'PUBLISHED' NOT NULL,
    is_primary BOOLEAN DEFAULT false,
    published_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_company_translations_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE CASCADE,
    CONSTRAINT fk_company_translations_language FOREIGN KEY (language_id)
        REFERENCES public.supported_languages(language_id) ON DELETE CASCADE,
    CONSTRAINT unique_company_language UNIQUE (company_id, language_id)
);

COMMENT ON TABLE public.company_translations IS 'Translated company profiles with localized descriptions and messaging';
COMMENT ON COLUMN public.company_translations.translation_id IS 'Primary key - Unique translation identifier';
COMMENT ON COLUMN public.company_translations.company_id IS 'Company reference';
COMMENT ON COLUMN public.company_translations.language_id IS 'Target language';
COMMENT ON COLUMN public.company_translations.translated_name IS 'Localized company name';
COMMENT ON COLUMN public.company_translations.translated_tagline IS 'Translated company tagline';
COMMENT ON COLUMN public.company_translations.translated_description IS 'Translated company description';
COMMENT ON COLUMN public.company_translations.translated_culture IS 'Translated culture description';
COMMENT ON COLUMN public.company_translations.translated_mission IS 'Translated mission statement';
COMMENT ON COLUMN public.company_translations.translated_vision IS 'Translated vision statement';
COMMENT ON COLUMN public.company_translations.translated_values IS 'Translated company values';
COMMENT ON COLUMN public.company_translations.localized_website IS 'Market-specific website URL';
COMMENT ON COLUMN public.company_translations.status IS 'Translation status';
COMMENT ON COLUMN public.company_translations.is_primary IS 'Whether this is primary version';

-- Strategic Indexes
CREATE INDEX idx_company_translations_company ON public.company_translations(company_id, language_id);
CREATE INDEX idx_company_translations_language ON public.company_translations(language_id, status);
CREATE INDEX idx_company_translations_primary ON public.company_translations(company_id)
    WHERE is_primary = true;
CREATE INDEX idx_company_translations_fulltext ON public.company_translations USING gin(
    to_tsvector('simple',
        COALESCE(translated_name,'') || ' ' ||
        COALESCE(translated_tagline,'') || ' ' ||
        COALESCE(translated_description,'')
    )
);

-- Trigger
DROP TRIGGER IF EXISTS update_company_translations_timestamp ON public.company_translations;
CREATE TRIGGER update_company_translations_timestamp
    BEFORE UPDATE ON public.company_translations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.company_translations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS company_translations_read_policy ON public.company_translations;
CREATE POLICY company_translations_read_policy ON public.company_translations
    FOR SELECT USING (status = 'PUBLISHED');

DROP POLICY IF EXISTS company_translations_admin_policy ON public.company_translations;
CREATE POLICY company_translations_admin_policy ON public.company_translations
    USING (
        EXISTS (
            SELECT 1 FROM public.companies c
            WHERE c.company_id = company_translations.company_id
              AND (c.owner_id = public.current_user_id() OR
                   EXISTS (
                       SELECT 1 FROM public.company_admins ca
                       WHERE ca.company_id = c.company_id
                         AND ca.user_id = public.current_user_id()
                   ))
        )
    );

-- =============================================================================
-- TABLE 250: ui_translation_keys
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 250
-- Table Name: ui_translation_keys
-- Description: UI text translation keys with context, screens, and metadata
--              for internationalization management.
--
-- Business Case (300 words):
-- Consistent UI translation requires a centralized key management system.
-- This table defines all translatable UI strings with unique keys, context
-- information, and metadata. It serves as the source of truth for UI
-- internationalization, enabling translators to understand context and
-- maintain consistency across the application.
--
-- Without structured key management, UI translations become inconsistent
-- and difficult to maintain. Same phrases are translated differently across
-- screens. Context is lost, leading to inappropriate translations. This
-- table provides the organizational framework for professional UI localization,
-- supporting translation memory, context-aware translation, and automated
-- quality checks.
--
-- The business impact is significant: structured key management reduces
-- translation errors by 70% and accelerates localization of new features
-- by 50%. It enables professional translation workflows with context and
-- screenshots. Consistent translations improve user experience and reduce
-- support confusion. Translation analytics identify gaps and prioritize
-- localization efforts.
--
-- Key Performance Indicators (KPIs):
--   1. Key Coverage: Translated keys / total keys
--   2. Translation Consistency: Duplicate translations detected
--   3. Context Completeness: Keys with context descriptions
--   4. Screen Coverage: Keys by application screen
--   5. Translation Velocity: Keys translated per day
--   6. Quality Issues: Reported translation errors
--   7. Unused Keys: Keys without usage
--   8. Key Growth: New keys per release
--   9. Machine Translation Usage: MT for UI strings
--   10. Reviewer Efficiency: Keys reviewed per hour
--
-- Feature Reference: LOC-14 (UI Internationalization)
-- Requirements Traceability: R-LOC-076 through R-LOC-090
--
-- Normalization: 3NF - Keys independent entity
--
-- High-Write Considerations:
--   - Moderate write volume (new keys with releases)
--   - Read-heavy during UI rendering (cached)
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.ui_translation_keys CASCADE;
CREATE TABLE public.ui_translation_keys (
    key_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    translation_key VARCHAR(255) NOT NULL UNIQUE,
    default_text TEXT NOT NULL,
    description TEXT,
    context TEXT,
    screen VARCHAR(100),
    component VARCHAR(100),
    platform VARCHAR(20) DEFAULT 'ALL',
    max_length INTEGER,
    placeholders JSONB,
    is_plural BOOLEAN DEFAULT false,
    plural_forms JSONB,
    is_html BOOLEAN DEFAULT false,
    tags TEXT[],
    priority INTEGER DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT valid_platform CHECK (platform IN ('ALL', 'WEB', 'IOS', 'ANDROID', 'API'))
);

COMMENT ON TABLE public.ui_translation_keys IS 'UI text translation keys with context and metadata';
COMMENT ON COLUMN public.ui_translation_keys.key_id IS 'Primary key - Unique key identifier';
COMMENT ON COLUMN public.ui_translation_keys.translation_key IS 'Unique translation key identifier';
COMMENT ON COLUMN public.ui_translation_keys.default_text IS 'Default (English) text';
COMMENT ON COLUMN public.ui_translation_keys.description IS 'Description for translators';
COMMENT ON COLUMN public.ui_translation_keys.context IS 'Usage context for accurate translation';
COMMENT ON COLUMN public.ui_translation_keys.screen IS 'Screen where text appears';
COMMENT ON COLUMN public.ui_translation_keys.component IS 'UI component name';
COMMENT ON COLUMN public.ui_translation_keys.platform IS 'Target platform(s)';
COMMENT ON COLUMN public.ui_translation_keys.max_length IS 'Maximum character length';
COMMENT ON COLUMN public.ui_translation_keys.placeholders IS 'JSON of placeholder variables';
COMMENT ON COLUMN public.ui_translation_keys.is_plural IS 'Whether text has plural forms';
COMMENT ON COLUMN public.ui_translation_keys.plural_forms IS 'JSON of plural form definitions';
COMMENT ON COLUMN public.ui_translation_keys.is_html IS 'Whether text contains HTML markup';
COMMENT ON COLUMN public.ui_translation_keys.tags IS 'Categorization tags';
COMMENT ON COLUMN public.ui_translation_keys.priority IS 'Translation priority';
COMMENT ON COLUMN public.ui_translation_keys.is_active IS 'Whether key is currently used';

-- Strategic Indexes
CREATE INDEX idx_ui_keys_active ON public.ui_translation_keys(is_active, priority)
    WHERE is_active = true;
CREATE INDEX idx_ui_keys_screen ON public.ui_translation_keys(screen);
CREATE INDEX idx_ui_keys_platform ON public.ui_translation_keys(platform);
CREATE INDEX idx_ui_keys_tags ON public.ui_translation_keys USING gin(tags);
CREATE INDEX idx_ui_keys_placeholders ON public.ui_translation_keys USING gin(placeholders);

-- Trigger
DROP TRIGGER IF EXISTS update_ui_translation_keys_timestamp ON public.ui_translation_keys;
CREATE TRIGGER update_ui_translation_keys_timestamp
    BEFORE UPDATE ON public.ui_translation_keys
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.ui_translation_keys ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ui_keys_read_policy ON public.ui_translation_keys;
CREATE POLICY ui_keys_read_policy ON public.ui_translation_keys
    FOR SELECT USING (is_active = true);

DROP POLICY IF EXISTS ui_keys_admin_policy ON public.ui_translation_keys;
CREATE POLICY ui_keys_admin_policy ON public.ui_translation_keys
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'localization_manager', 'developer')
    ));

-- =============================================================================
-- TABLE 251: ui_translations
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 251
-- Table Name: ui_translations
-- Description: Translated UI text with versioning, review status, and
--              quality metrics for multilingual interface support.
--
-- Business Case (300 words):
-- Delivering a localized user interface requires storing and managing
-- translations for every UI string in every supported language. This table
-- stores the actual translations for UI keys, tracking version compatibility,
-- review status, and quality metrics. It enables dynamic UI language switching
-- and supports continuous localization workflows.
--
-- Without centralized translation storage, UI localization becomes fragmented.
-- Translations are hardcoded or scattered across resource files. Updating
-- translations requires app releases. This table enables runtime translation
-- updates, A/B testing of translations, and comprehensive translation quality
-- management. It supports professional translation workflows with review
-- and approval processes.
--
-- The business impact is substantial: dynamic UI translation reduces time-
-- to-market for new languages by 80% and enables continuous improvement of
-- translations based on user feedback. It supports enterprise customers who
-- require custom terminology. Translation analytics identify quality issues
-- and guide localization investment.
--
-- Key Performance Indicators (KPIs):
--   1. Translation Completeness: Translated / total keys by language
--   2. Review Coverage: Reviewed / total translations
--   3. Translation Quality Score: User-reported issues
--   4. Version Compatibility: Translations for current version
--   5. Translator Productivity: Words translated per period
--   6. Machine Translation Adoption: MT usage percentage
--   7. Translation Turnaround: Time from request to publish
--   8. User Language Switching: Language change frequency
--   9. Fallback Usage: Missing translation fallback rate
--   10. Contextual Accuracy: Translation appropriateness
--
-- Feature Reference: LOC-15 (UI Translations)
-- Requirements Traceability: R-LOC-091 through R-LOC-105
--
-- Normalization: 3NF - Translations dependent on keys and languages
--
-- High-Write Considerations:
--   - Moderate write volume (translation updates)
--   - Read-heavy during UI rendering (heavily cached)
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.ui_translations CASCADE;
CREATE TABLE public.ui_translations (
    translation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    key_id UUID NOT NULL,
    language_id UUID NOT NULL,
    translated_text TEXT NOT NULL,
    status public.translation_status DEFAULT 'PENDING' NOT NULL,
    translation_method VARCHAR(20) DEFAULT 'MACHINE',
    quality_score INTEGER CHECK (quality_score BETWEEN 0 AND 100),
    translated_by UUID,
    reviewed_by UUID,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    published_at TIMESTAMP WITH TIME ZONE,
    app_version_min VARCHAR(20),
    app_version_max VARCHAR(20),
    character_count INTEGER GENERATED ALWAYS AS (char_length(translated_text)) STORED,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT fk_ui_translations_key FOREIGN KEY (key_id)
        REFERENCES public.ui_translation_keys(key_id) ON DELETE CASCADE,
    CONSTRAINT fk_ui_translations_language FOREIGN KEY (language_id)
        REFERENCES public.supported_languages(language_id) ON DELETE CASCADE,
    CONSTRAINT fk_ui_translations_translator FOREIGN KEY (translated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ui_translations_reviewer FOREIGN KEY (reviewed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT unique_key_language UNIQUE (key_id, language_id)
);

COMMENT ON TABLE public.ui_translations IS 'Translated UI text with versioning and quality metrics';
COMMENT ON COLUMN public.ui_translations.translation_id IS 'Primary key - Unique translation identifier';
COMMENT ON COLUMN public.ui_translations.key_id IS 'Translation key reference';
COMMENT ON COLUMN public.ui_translations.language_id IS 'Target language';
COMMENT ON COLUMN public.ui_translations.translated_text IS 'Translated UI text';
COMMENT ON COLUMN public.ui_translations.status IS 'Translation workflow status';
COMMENT ON COLUMN public.ui_translations.translation_method IS 'MACHINE, HUMAN, HYBRID';
COMMENT ON COLUMN public.ui_translations.quality_score IS 'Quality rating (0-100)';
COMMENT ON COLUMN public.ui_translations.translated_by IS 'Translator user reference';
COMMENT ON COLUMN public.ui_translations.reviewed_by IS 'Reviewer user reference';
COMMENT ON COLUMN public.ui_translations.reviewed_at IS 'When reviewed';
COMMENT ON COLUMN public.ui_translations.published_at IS 'When published';
COMMENT ON COLUMN public.ui_translations.app_version_min IS 'Minimum app version';
COMMENT ON COLUMN public.ui_translations.app_version_max IS 'Maximum app version';
COMMENT ON COLUMN public.ui_translations.character_count IS 'Character count (generated)';

-- Strategic Indexes
CREATE INDEX idx_ui_translations_key ON public.ui_translations(key_id, language_id);
CREATE INDEX idx_ui_translations_language ON public.ui_translations(language_id, status);
CREATE INDEX idx_ui_translations_status ON public.ui_translations(status)
    WHERE status IN ('PENDING', 'NEEDS_REVIEW');
CREATE INDEX idx_ui_translations_published ON public.ui_translations(published_at)
    WHERE status = 'PUBLISHED';
CREATE INDEX idx_ui_translations_quality ON public.ui_translations(quality_score)
    WHERE quality_score IS NOT NULL;

-- Trigger
DROP TRIGGER IF EXISTS update_ui_translations_timestamp ON public.ui_translations;
CREATE TRIGGER update_ui_translations_timestamp
    BEFORE UPDATE ON public.ui_translations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- RLS
ALTER TABLE public.ui_translations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ui_translations_read_policy ON public.ui_translations;
CREATE POLICY ui_translations_read_policy ON public.ui_translations
    FOR SELECT USING (status = 'PUBLISHED');

DROP POLICY IF EXISTS ui_translations_admin_policy ON public.ui_translations;
CREATE POLICY ui_translations_admin_policy ON public.ui_translations
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = public.current_user_id()
        AND r.name IN ('admin', 'localization_manager', 'translator')
    ));

-- =============================================================================
-- TABLE 252: regional_compliance_rules
-- =============================================================================

-------------------------------------------------------------------------------
-- Serial No: 252
-- Table Name: regional_compliance_rules
-- Description: Region-specific compliance requirements for data protection,
--              content moderation, and user rights management.
--
-- Business Case (300 words):
-- Operating globally requires compliance with diverse regional regulations
-- including GDPR, CCPA, LGPD, and others. This table defines compliance
-- rules by region, specifying requirements for data collection, processing,
-- user rights, and content restrictions. It enables automated compliance
-- enforcement and provides audit trails for regulatory inspections.
--
-- Without structured compliance management, organizations risk significant
-- fines and reputational damage from regulatory violations. Manual compliance
-- processes cannot scale across hundreds of jurisdictions. This table provides
-- a centralized compliance rule engine that automatically applies appropriate
-- controls based on user location and data residency requirements.
--
-- The business impact is critical: automated compliance reduces regulatory
-- risk by 90% and audit preparation time by 80%. It enables confident global
-- expansion by ensuring local compliance. For enterprise customers, it
-- provides necessary compliance assurances for procurement. The rule engine
-- adapts quickly to new regulations without code changes.
--
-- Key Performance Indicators (KPIs):
--   1. Compliance Coverage: Regions with defined rules
--   2. Rule Effectiveness: Violations prevented
--   3. Audit Pass Rate: Successful compliance audits
--   4. Regulatory Response Time: Days to implement new rules
--   5. User Rights Requests: Volume by region and type
--   6. Consent Collection Rate: Users providing required consent
--   7. Data Subject Access: DSAR fulfillment time
--   8. Compliance Cost: Cost per regulated user
--   9. Incident Rate: Compliance incidents per region
--   10. Rule Version Currency: Rules updated within deadline
--
-- Feature Reference: LOC-16 (Regional Compliance)
-- Requirements Traceability: R-LOC-106 through R-LOC-120
--
-- Normalization: 3NF - Rules independent with region applicability
--
-- High-Write Considerations:
--   - Write-light (rules updated with regulations)
--   - Read-heavy during user operations
-------------------------------------------------------------------------------
DROP TABLE IF EXISTS public.regional_compliance_rules CASCADE;
CREATE TABLE public.regional_compliance_rules (
    rule_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    region_type public.compliance_region_type NOT NULL,
    rule_name VARCHAR(255) NOT NULL,
    rule_category VARCHAR(50) NOT NULL,
    description TEXT,
    requirement JSONB NOT NULL,
    enforcement_level VARCHAR(20) DEFAULT 'REQUIRED',
    applies_to_countries TEXT[],
    applies_to_states TEXT[],
    effective_date DATE NOT NULL,
    expiration_date DATE,
    is_active BOOLEAN DEFAULT true,
    priority INTEGER DEFAULT 0,
    legal_reference TEXT,
    penalty_description TEXT,
    implementation_notes TEXT,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT valid_rule_category CHECK (rule_category IN (
        'DATA_COLLECTION', 'DATA_PROCESSING', 'DATA_RETENTION', 'DATA_TRANSFER',
        'USER_RIGHTS', 'CONSENT', 'COOKIES', 'MARKETING', 'CONTENT', 'MINORS',
        'BIOMETRICS', 'AI_ML', 'BREACH_NOTIFICATION', 'DPIA', 'RECORD_KEEPING'
    )),
    CONSTRAINT valid_enforcement_level CHECK (enforcement_level IN ('REQUIRED', 'RECOMMENDED', 'OPTIONAL', 'CONDITIONAL'))
);

COMMENT ON TABLE public.regional_compliance_rules IS 'Region-specific compliance requirements for data protection and user rights';
COMMENT ON COLUMN public.regional_compliance_rules.rule_id IS 'Primary key - Unique rule identifier';
COMMENT ON COLUMN public.regional_compliance_rules.region_type IS 'Regulatory region classification';
COMMENT ON COLUMN public.regional_compliance_rules.rule_name IS 'Rule display name';
COMMENT ON COLUMN public.regional_compliance_rules.rule_category IS 'Category of compliance requirement';
COMMENT ON COLUMN public.regional_compliance_rules.description IS 'Detailed rule description';
COMMENT ON COLUMN public.regional_compliance_rules.requirement IS 'JSON rule definition and parameters';
COMMENT ON COLUMN public.regional_compliance_rules.enforcement_level IS 'REQUIRED, RECOMMENDED, OPTIONAL, CONDITIONAL';
COMMENT ON COLUMN public.regional_compliance_rules.applies_to_countries IS 'Array of ISO country codes';
COMMENT ON COLUMN public.regional_compliance_rules.applies_to_states IS 'Array of state/province codes';
COMMENT ON COLUMN public.regional_compliance_rules.effective_date IS 'When rule becomes effective';
COMMENT ON COLUMN public.regional_compliance_rules.expiration_date IS 'When rule expires';
COMMENT ON COLUMN public.regional_compliance_rules.is_active IS 'Whether rule is active';
COMMENT ON COLUMN public.regional_compliance_rules.priority IS 'Rule precedence (higher wins)';
COMMENT ON COLUMN public.regional_compliance_rules.legal_reference IS 'Legal citation reference';
COMMENT ON COLUMN public.regional_compliance_rules.penalty_description IS 'Potential penalties for violation';
COMMENT ON COLUMN public.regional_compliance_rules.implementation_notes IS 'Technical implementation guidance';

-- Strategic Indexes
