-------------------------------------------------------------------------------
-- View: vw_available_languages
-- Description: Available languages with translation completeness metrics
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_available_languages AS
SELECT
    sl.language_id,
    sl.language_code,
    sl.language_name,
    sl.native_name,
    sl.locale_code,
    sl.script,
    sl.text_direction,
    sl.is_active,
    sl.is_default,
    sl.is_ui_supported,
    sl.is_content_supported,
    sl.translation_completeness,
    sl.priority,
    COUNT(DISTINCT uit.translation_id) AS ui_translations_count,
    COUNT(DISTINCT CASE WHEN uit.status = 'PUBLISHED' THEN uit.translation_id END) AS published_ui_translations,
    COUNT(DISTINCT ct.translation_id) AS content_translations_count,
    COUNT(DISTINCT jt.translation_id) AS job_translations_count,
    COUNT(DISTINCT compt.translation_id) AS company_translations_count,
    CASE
        WHEN sl.fallback_language_id IS NOT NULL
        THEN (SELECT language_code FROM public.supported_languages WHERE language_id = sl.fallback_language_id)
        ELSE NULL
    END AS fallback_language_code
FROM public.supported_languages sl
LEFT JOIN public.ui_translations uit ON sl.language_id = uit.language_id
LEFT JOIN public.content_translations ct ON sl.language_id = ct.language_id AND ct.status = 'PUBLISHED'
LEFT JOIN public.job_translations jt ON sl.language_id = jt.language_id AND jt.status = 'PUBLISHED'
LEFT JOIN public.company_translations compt ON sl.language_id = compt.language_id AND compt.status = 'PUBLISHED'
GROUP BY sl.language_id
ORDER BY sl.priority DESC, sl.language_name;

COMMENT ON VIEW public.vw_available_languages IS 'Available languages with translation completeness metrics across all content types';

-------------------------------------------------------------------------------
-- View: vw_regional_compliance_matrix
-- Description: Regional compliance requirements matrix by country
-------------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.vw_regional_compliance_matrix AS
WITH country_rules AS (
    SELECT
        rcr.rule_id,
        rcr.region_type,
        rcr.rule_name,
        rcr.rule_category,
        rcr.enforcement_level,
        rcr.priority,
        UNNEST(rcr.applies_to_countries) AS country_code
    FROM public.regional_compliance_rules rcr
    WHERE rcr.is_active = true
      AND rcr.applies_to_countries IS NOT NULL
)
SELECT
    cr.country_code,
    cr.region_type,
    cr.rule_category,
    COUNT(*) AS rule_count,
    COUNT(CASE WHEN cr.enforcement_level = 'REQUIRED' THEN 1 END) AS required_rules,
    COUNT(CASE WHEN cr.enforcement_level = 'RECOMMENDED' THEN 1 END) AS recommended_rules,
    MAX(cr.priority) AS highest_priority,
    ARRAY_AGG(DISTINCT cr.rule_name ORDER BY cr.rule_name) AS applicable_rules
FROM country_rules cr
GROUP BY 1,2,3
ORDER BY cr.country_code, cr.rule_category;

COMMENT ON VIEW public.vw_regional_compliance_matrix IS 'Regional compliance requirements matrix by country for quick reference';

