-- =============================================================================

-------------------------------------------------------------------------------
-- Function: detect_user_language
-- Description: Detect appropriate language for user based on preferences and location
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.detect_user_language(
    p_user_id UUID DEFAULT NULL,
    p_accept_language VARCHAR(255) DEFAULT NULL,
    p_country_code VARCHAR(2) DEFAULT NULL
)
RETURNS TABLE (
    language_id UUID,
    language_code VARCHAR,
    locale_code VARCHAR,
    confidence INTEGER
) AS $$
DECLARE
    v_user_preferred_language UUID;
    v_browser_language VARCHAR(10);
    v_region_language UUID;
BEGIN
    -- Check user's saved preference
    IF p_user_id IS NOT NULL THEN
        SELECT language_id INTO v_user_preferred_language
        FROM public.user_preferences
        WHERE user_id = p_user_id;

        IF v_user_preferred_language IS NOT NULL THEN
            RETURN QUERY SELECT
                sl.language_id, sl.language_code, sl.locale_code, 100
            FROM public.supported_languages sl
            WHERE sl.language_id = v_user_preferred_language
              AND sl.is_active = true;
            RETURN;
        END IF;
    END IF;

    -- Parse Accept-Language header
    IF p_accept_language IS NOT NULL THEN
        v_browser_language := split_part(split_part(p_accept_language, ',', 1), ';', 1);

        RETURN QUERY SELECT
            sl.language_id, sl.language_code, sl.locale_code, 80
        FROM public.supported_languages sl
        WHERE sl.language_code = split_part(v_browser_language, '-', 1)
          AND sl.is_active = true
        LIMIT 1;

        IF FOUND THEN
            RETURN;
        END IF;
    END IF;

    -- Fallback to region-based language
    IF p_country_code IS NOT NULL THEN
        -- Map country to primary language (simplified)
        v_region_language := CASE
            WHEN p_country_code IN ('US', 'GB', 'AU', 'CA', 'NZ', 'IE') THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'en' LIMIT 1)
            WHEN p_country_code IN ('ES', 'MX', 'AR', 'CO', 'CL', 'PE') THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'es' LIMIT 1)
            WHEN p_country_code IN ('FR', 'BE', 'CH', 'LU', 'MC') THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'fr' LIMIT 1)
            WHEN p_country_code IN ('DE', 'AT', 'CH', 'LI') THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'de' LIMIT 1)
            WHEN p_country_code IN ('CN', 'TW', 'HK', 'SG') THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'zh' LIMIT 1)
            WHEN p_country_code = 'JP' THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'ja' LIMIT 1)
            WHEN p_country_code IN ('SA', 'AE', 'EG', 'QA', 'KW', 'BH', 'OM') THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'ar' LIMIT 1)
            WHEN p_country_code IN ('BR', 'PT') THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'pt' LIMIT 1)
            WHEN p_country_code = 'IN' THEN
                (SELECT language_id FROM public.supported_languages WHERE language_code = 'hi' LIMIT 1)
            ELSE NULL
        END;

        IF v_region_language IS NOT NULL THEN
            RETURN QUERY SELECT
                sl.language_id, sl.language_code, sl.locale_code, 60
            FROM public.supported_languages sl
            WHERE sl.language_id = v_region_language
              AND sl.is_active = true;
            RETURN;
        END IF;
    END IF;

    -- Ultimate fallback to default language
    RETURN QUERY SELECT
        sl.language_id, sl.language_code, sl.locale_code, 0
    FROM public.supported_languages sl
    WHERE sl.is_default = true
      AND sl.is_active = true
    LIMIT 1;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION public.detect_user_language(UUID, VARCHAR, VARCHAR) IS 'Detect appropriate language for user based on preferences, browser, and location';

-------------------------------------------------------------------------------
-- Function: convert_currency
-- Description: Convert amount between currencies using latest exchange rates
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.convert_currency(
    p_amount NUMERIC,
    p_from_currency CHAR(3),
    p_to_currency CHAR(3),
    p_exchange_date DATE DEFAULT CURRENT_DATE
)
RETURNS NUMERIC AS $$
DECLARE
    v_rate NUMERIC;
    v_result NUMERIC;
BEGIN
    -- Same currency, no conversion needed
    IF p_from_currency = p_to_currency THEN
        RETURN p_amount;
    END IF;

    -- Get exchange rate
    SELECT rate INTO v_rate
    FROM public.currency_exchange_rates
    WHERE from_currency = p_from_currency
      AND to_currency = p_to_currency
      AND effective_date <= p_exchange_date
      AND (expiration_date IS NULL OR expiration_date >= p_exchange_date)
    ORDER BY effective_date DESC
    LIMIT 1;

    IF v_rate IS NULL THEN
        -- Try reverse rate
        SELECT (1.0 / rate) INTO v_rate
        FROM public.currency_exchange_rates
        WHERE from_currency = p_to_currency
          AND to_currency = p_from_currency
          AND effective_date <= p_exchange_date
          AND (expiration_date IS NULL OR expiration_date >= p_exchange_date)
        ORDER BY effective_date DESC
        LIMIT 1;
    END IF;

    IF v_rate IS NULL THEN
        RAISE EXCEPTION 'No exchange rate found for % to % on %',
            p_from_currency, p_to_currency, p_exchange_date;
    END IF;

    v_result := ROUND(p_amount * v_rate, 2);
    RETURN v_result;
END;
$$ LANGUAGE plpgsql STABLE;

COMMENT ON FUNCTION public.convert_currency(NUMERIC, CHAR, CHAR, DATE) IS 'Convert amount between currencies using latest exchange rates';



