-- Enable required extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "btree_gin";
CREATE EXTENSION IF NOT EXISTS "btree_gist";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- =============================================================================
-- CUSTOM DOMAINS FOR DATA INTEGRITY
-- =============================================================================

-- Domain: positive_money
-- Description: Monetary values that cannot be negative
-- Business Case: Prevents invalid financial transactions and accounting errors
-- KPIs: Data quality score, transaction error rate
-- Feature Reference: FIN01-FIN50 (Financial Integrity)
DROP DOMAIN IF EXISTS public.positive_money CASCADE;
CREATE DOMAIN public.positive_money AS NUMERIC(15,4) CHECK (VALUE >= 0);
COMMENT ON DOMAIN public.positive_money IS 'Non-negative monetary values for financial transactions';

-- Domain: percentage
-- Description: Percentage values between 0 and 100
-- Business Case: Standardizes rate calculations across the platform
-- KPIs: Data validation pass rate
-- Feature Reference: CORE01-CORE20 (Core Data Types)
DROP DOMAIN IF EXISTS public.percentage CASCADE;
CREATE DOMAIN public.percentage AS NUMERIC(5,2) CHECK (VALUE BETWEEN 0 AND 100);
COMMENT ON DOMAIN public.percentage IS 'Percentage values constrained between 0 and 100 percent';

-- Domain: iso_currency
-- Description: ISO 4217 three-letter currency codes
-- Business Case: Ensures consistent currency handling across international transactions
-- KPIs: Currency conversion accuracy, international transaction success rate
-- Feature Reference: FIN51-FIN80 (Multi-Currency Support)
DROP DOMAIN IF EXISTS public.iso_currency CASCADE;
CREATE DOMAIN public.iso_currency AS CHAR(3)
CHECK (VALUE ~ '^[A-Z]{3}$' AND VALUE IN ('USD', 'EUR', 'GBP', 'JPY', 'CAD', 'AUD', 'CHF', 'CNY', 'INR'));
COMMENT ON DOMAIN public.iso_currency IS 'ISO 4217 three-letter currency codes for international transactions';

-- Domain: email_address
-- Description: Validated email address format
-- Business Case: Ensures communication channel validity for notifications and compliance
-- KPIs: Email delivery success rate, contact data quality
-- Feature Reference: CORE21-CORE40 (Contact Management)
DROP DOMAIN IF EXISTS public.email_address CASCADE;
CREATE DOMAIN public.email_address AS VARCHAR(255)
CHECK (VALUE ~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$');
COMMENT ON DOMAIN public.email_address IS 'RFC 5322 compliant email address format';

-- =============================================================================
-- TABLE: audit_log
-- Description: Comprehensive audit trail with before/after snapshots for compliance
-- Business Case: Provides complete historical record for SOX, GDPR, and HIPAA audits
-- KPIs: Audit trail completeness (100%), query response time (<100ms), storage efficiency
-- Feature Reference: COMP01-COMP30 (Comprehensive Audit)
-- =============================================================================
DROP TABLE IF EXISTS public.audit_log CASCADE;
CREATE TABLE public.audit_log (
    audit_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    table_name VARCHAR(100) NOT NULL,
    record_id UUID NOT NULL,
    operation CHAR(1) NOT NULL CHECK (operation IN ('I', 'U', 'D', 'S')),
    old_data JSONB,
    new_data JSONB,
    changed_by UUID REFERENCES public.users(user_id),
    changed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    client_ip INET,
    user_agent TEXT,
    correlation_id UUID,
    CONSTRAINT valid_audit_data CHECK (
        (operation = 'I' AND old_data IS NULL AND new_data IS NOT NULL) OR
        (operation = 'D' AND old_data IS NOT NULL AND new_data IS NULL) OR
        (operation = 'U' AND old_data IS NOT NULL AND new_data IS NOT NULL) OR
        (operation = 'S' AND old_data IS NULL AND new_data IS NULL)
    )
) PARTITION BY RANGE (changed_at);
COMMENT ON TABLE public.audit_log IS 'Complete audit trail with before/after snapshots for regulatory compliance';
COMMENT ON COLUMN public.audit_log.audit_id IS 'Unique identifier for audit record';
COMMENT ON COLUMN public.audit_log.table_name IS 'Database table where change occurred';
COMMENT ON COLUMN public.audit_log.record_id IS 'Primary key of changed record';
COMMENT ON COLUMN public.audit_log.operation IS 'Type of operation: I(Insert), U(Update), D(Delete), S(Select read)';
COMMENT ON COLUMN public.audit_log.old_data IS 'JSON snapshot of record before change';
COMMENT ON COLUMN public.audit_log.new_data IS 'JSON snapshot of record after change';
COMMENT ON COLUMN public.audit_log.changed_by IS 'User ID who performed the operation';
COMMENT ON COLUMN public.audit_log.changed_at IS 'Timestamp of the operation';
COMMENT ON COLUMN public.audit_log.client_ip IS 'IP address of the client making the change';
COMMENT ON COLUMN public.audit_log.user_agent IS 'Client application identifier';
COMMENT ON COLUMN public.audit_log.correlation_id IS 'Distributed tracing identifier for request chains';

-- Index: idx_audit_record
-- Description: Optimizes queries for record history retrieval
-- Business Case: Enables fast audit trail queries for compliance reviews
-- Feature Reference: COMP01-COMP30
CREATE INDEX idx_audit_record ON public.audit_log(table_name, record_id, changed_at DESC);

-- Index: idx_audit_correlation
-- Description: Supports distributed tracing across microservices
-- Business Case: Enables end-to-end transaction auditing
-- Feature Reference: COMP15-COMP20
CREATE INDEX idx_audit_correlation ON public.audit_log(correlation_id);

-- Index: idx_audit_changed_at
-- Description: Optimizes time-based audit queries for compliance reporting
-- Business Case: Speeds up audit report generation for regulatory submissions
-- Feature Reference: COMP21-COMP25
CREATE INDEX idx_audit_changed_at ON public.audit_log(changed_at DESC) WHERE changed_at > NOW() - INTERVAL '90 days';

-- =============================================================================
-- TABLE: access_review_sessions
-- Description: Periodic access certification campaigns for SOX/GDPR compliance
-- Business Case: Enables automated access reviews with escalation workflows
-- KPIs: Review completion rate, compliance score, time-to-completion, risk reduction
-- Feature Reference: SEC01-SEC30 (Access Governance)
-- =============================================================================
DROP TABLE IF EXISTS public.access_review_sessions CASCADE;
CREATE TABLE public.access_review_sessions (
    review_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    campaign_name VARCHAR(255) NOT NULL,
    review_type VARCHAR(50) CHECK (review_type IN ('PERIODIC', 'EVENT_DRIVEN', 'CONTINUOUS', 'ROLE_BASED')),
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'COMPLETED', 'EXPIRED', 'CANCELLED')),
    scope_filter JSONB,
    due_date TIMESTAMP WITH TIME ZONE,
    completion_date TIMESTAMP WITH TIME ZONE,
    reviewer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    findings_summary JSONB,
    total_items_reviewed INTEGER DEFAULT 0,
    compliance_score NUMERIC(5,2),
    auto_approve_threshold NUMERIC(5,2),
    escalation_chain JSONB,
    reminder_sent_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT valid_dates CHECK (completion_date IS NULL OR due_date IS NULL OR completion_date >= due_date),
    CONSTRAINT valid_compliance_score CHECK (compliance_score BETWEEN 0 AND 100)
);
COMMENT ON TABLE public.access_review_sessions IS 'Periodic access certification campaigns for SOX/GDPR compliance';
COMMENT ON COLUMN public.access_review_sessions.review_id IS 'Unique identifier for access review session';
COMMENT ON COLUMN public.access_review_sessions.campaign_name IS 'Human-readable campaign name for tracking';
COMMENT ON COLUMN public.access_review_sessions.review_type IS 'Type of review: periodic scheduled, event-driven, continuous monitoring, or role-based';
COMMENT ON COLUMN public.access_review_sessions.status IS 'Current campaign status workflow state';
COMMENT ON COLUMN public.access_review_sessions.scope_filter IS 'JSON defining which users/roles are in scope';
COMMENT ON COLUMN public.access_review_sessions.due_date IS 'Deadline for review completion';
COMMENT ON COLUMN public.access_review_sessions.completion_date IS 'Actual completion timestamp';
COMMENT ON COLUMN public.access_review_sessions.reviewer_id IS 'Primary reviewer responsible for certification';
COMMENT ON COLUMN public.access_review_sessions.findings_summary IS 'Aggregated findings and remediation actions';
COMMENT ON COLUMN public.access_review_sessions.total_items_reviewed IS 'Count of access items reviewed';
COMMENT ON COLUMN public.access_review_sessions.compliance_score IS 'Percentage score of compliant access rights';
COMMENT ON COLUMN public.access_review_sessions.auto_approve_threshold IS 'Score threshold for automatic approval';
COMMENT ON COLUMN public.access_review_sessions.escalation_chain IS 'Escalation path for overdue reviews';
COMMENT ON COLUMN public.access_review_sessions.reminder_sent_at IS 'Last reminder notification timestamp';
COMMENT ON COLUMN public.access_review_sessions.deleted_at IS 'Soft deletion timestamp for data retention';

-- Index: idx_access_review_status
-- Description: Supports active review queries and overdue monitoring
-- Business Case: Enables dashboard for pending reviews requiring attention
-- Feature Reference: SEC12-SEC15
CREATE INDEX idx_access_review_status ON public.access_review_sessions(status, due_date) WHERE status IN ('ACTIVE', 'DRAFT');

-- Index: idx_access_review_reviewer
-- Description: Optimizes reviewer workload queries
-- Business Case: Enables reviewer assignment and workload balancing
-- Feature Reference: SEC16-SEC18
CREATE INDEX idx_access_review_reviewer ON public.access_review_sessions(reviewer_id);

-- Index: idx_access_review_scope
-- Description: Supports JSONB scope filter queries
-- Business Case: Enables dynamic scope filtering for large organizations
-- Feature Reference: SEC19-SEC22
CREATE INDEX idx_access_review_scope ON public.access_review_sessions USING gin(scope_filter);

-- Index: idx_access_review_due
-- Description: Identifies overdue reviews for escalation
-- Business Case: Automates compliance deadline enforcement
-- Feature Reference: SEC23-SEC25
CREATE INDEX idx_access_review_due ON public.access_review_sessions(due_date) WHERE status = 'ACTIVE' AND due_date < NOW();

-- =============================================================================
-- TABLE: scim_sync_logs
-- Description: Audit trail for IdP directory synchronization via SCIM 2.0
-- Business Case: Enables identity provider integration with error tracking
-- KPIs: Sync success rate, sync duration, retry count, error resolution time
-- Feature Reference: IDM01-IDM40 (Identity Management)
-- =============================================================================
DROP TABLE IF EXISTS public.scim_sync_logs CASCADE;
CREATE TABLE public.scim_sync_logs (
    log_id BIGSERIAL NOT NULL,
    provider_id UUID NOT NULL,
    operation VARCHAR(20) NOT NULL CHECK (operation IN ('CREATE', 'UPDATE', 'DELETE', 'PATCH', 'BULK')),
    entity_type VARCHAR(50) NOT NULL CHECK (entity_type IN ('USER', 'GROUP', 'ROLE')),
    entity_id VARCHAR(255),
    request_payload JSONB,
    response_payload JSONB,
    status VARCHAR(20) DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED', 'RETRYING', 'SKIPPED')),
    error_message TEXT,
    error_category VARCHAR(50) CHECK (error_category IN ('NETWORK', 'AUTH', 'VALIDATION', 'RATE_LIMIT', 'SERVER_ERROR', 'UNKNOWN')),
    sync_duration_ms INTEGER,
    synced_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    retry_count INTEGER DEFAULT 0,
    PRIMARY KEY (log_id, synced_at)
) PARTITION BY RANGE (synced_at);
COMMENT ON TABLE public.scim_sync_logs IS 'Audit trail for IdP directory synchronization with error categorization';
COMMENT ON COLUMN public.scim_sync_logs.log_id IS 'Sequential identifier for sync operations';
COMMENT ON COLUMN public.scim_sync_logs.provider_id IS 'Identity provider reference';
COMMENT ON COLUMN public.scim_sync_logs.operation IS 'SCIM operation type performed';
COMMENT ON COLUMN public.scim_sync_logs.entity_type IS 'Type of directory object being synced';
COMMENT ON COLUMN public.scim_sync_logs.entity_id IS 'External ID from identity provider';
COMMENT ON COLUMN public.scim_sync_logs.request_payload IS 'SCIM request payload sent to provider';
COMMENT ON COLUMN public.scim_sync_logs.response_payload IS 'SCIM response payload received';
COMMENT ON COLUMN public.scim_sync_logs.status IS 'Sync operation status';
COMMENT ON COLUMN public.scim_sync_logs.error_category IS 'Categorized error type for monitoring';
COMMENT ON COLUMN public.scim_sync_logs.sync_duration_ms IS 'Time taken for sync operation';
COMMENT ON COLUMN public.scim_sync_logs.synced_at IS 'Timestamp of sync attempt';
COMMENT ON COLUMN public.scim_sync_logs.retry_count IS 'Number of retry attempts';

-- Index: idx_scim_sync_provider
-- Description: Supports provider-specific sync history queries
-- Business Case: Enables per-IdP performance monitoring
-- Feature Reference: IDM21-IDM25
CREATE INDEX idx_scim_sync_provider ON public.scim_sync_logs(provider_id, synced_at DESC);

-- Index: idx_scim_sync_status
-- Description: Identifies failed syncs for remediation
-- Business Case: Enables automated alerting on sync failures
-- Feature Reference: IDM26-IDM30
CREATE INDEX idx_scim_sync_status ON public.scim_sync_logs(status, synced_at DESC) WHERE status = 'FAILED';

-- Index: idx_scim_error_category
-- Description: Supports error pattern analysis
-- Business Case: Identifies systemic sync issues by error type
-- Feature Reference: IDM31-IDM35
CREATE INDEX idx_scim_error_category ON public.scim_sync_logs(error_category, synced_at) WHERE error_category IS NOT NULL;

-- =============================================================================
-- TABLE: webhook_retry_queues
-- Description: Circuit breaker-enabled queue for failed webhook deliveries
-- Business Case: Ensures reliable event delivery with automatic retry logic
-- KPIs: Delivery success rate, retry success rate, circuit breaker events, MTTR
-- Feature Reference: INT01-INT35 (Integration Resilience)
-- =============================================================================
DROP TABLE IF EXISTS public.webhook_retry_queues CASCADE;
CREATE TABLE public.webhook_retry_queues (
    queue_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    webhook_subscription_id UUID NOT NULL,
    event_type VARCHAR(100) NOT NULL,
    payload JSONB NOT NULL,
    attempt_number INTEGER DEFAULT 1 CHECK (attempt_number > 0),
    max_attempts INTEGER DEFAULT 5,
    next_retry_at TIMESTAMP WITH TIME ZONE NOT NULL,
    status VARCHAR(20) DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'PROCESSING', 'EXHAUSTED', 'CANCELLED', 'CIRCUIT_OPEN')),
    last_error_code VARCHAR(50),
    last_error_message TEXT,
    backoff_strategy VARCHAR(20) DEFAULT 'EXPONENTIAL' CHECK (backoff_strategy IN ('EXPONENTIAL', 'LINEAR', 'FIXED')),
    circuit_breaker_state VARCHAR(20) DEFAULT 'CLOSED' CHECK (circuit_breaker_state IN ('CLOSED', 'OPEN', 'HALF_OPEN')),
    circuit_breaker_failures INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT valid_retry_dates CHECK (next_retry_at >= created_at)
);
COMMENT ON TABLE public.webhook_retry_queues IS 'Circuit breaker-enabled queue for failed webhook deliveries';
COMMENT ON COLUMN public.webhook_retry_queues.queue_id IS 'Unique queue entry identifier';
COMMENT ON COLUMN public.webhook_retry_queues.webhook_subscription_id IS 'Subscribed webhook configuration';
COMMENT ON COLUMN public.webhook_retry_queues.event_type IS 'Type of event being delivered';
COMMENT ON COLUMN public.webhook_retry_queues.payload IS 'Event payload for delivery';
COMMENT ON COLUMN public.webhook_retry_queues.attempt_number IS 'Current retry attempt count';
COMMENT ON COLUMN public.webhook_retry_queues.max_attempts IS 'Maximum retry attempts before exhaustion';
COMMENT ON COLUMN public.webhook_retry_queues.next_retry_at IS 'Scheduled next retry timestamp';
COMMENT ON COLUMN public.webhook_retry_queues.status IS 'Queue entry processing status';
COMMENT ON COLUMN public.webhook_retry_queues.last_error_code IS 'HTTP status code or error code from last attempt';
COMMENT ON COLUMN public.webhook_retry_queues.last_error_message IS 'Detailed error message from last attempt';
COMMENT ON COLUMN public.webhook_retry_queues.backoff_strategy IS 'Retry backoff algorithm';
COMMENT ON COLUMN public.webhook_retry_queues.circuit_breaker_state IS 'Circuit breaker protection state';
COMMENT ON COLUMN public.webhook_retry_queues.circuit_breaker_failures IS 'Consecutive failure count for circuit breaker';

-- Index: idx_webhook_retry_status
-- Description: Identifies pending deliveries for processing
-- Business Case: Enables efficient queue processing
-- Feature Reference: INT21-INT25
CREATE INDEX idx_webhook_retry_status ON public.webhook_retry_queues(status, next_retry_at) WHERE status = 'PENDING';

-- Index: idx_webhook_retry_subscription
-- Description: Supports per-subscription failure analysis
-- Business Case: Enables webhook health monitoring per subscriber
-- Feature Reference: INT26-INT30
CREATE INDEX idx_webhook_retry_subscription ON public.webhook_retry_queues(webhook_subscription_id);

-- Index: idx_webhook_circuit
-- Description: Identifies open circuit breakers for intervention
-- Business Case: Enables proactive monitoring of failing endpoints
-- Feature Reference: INT31-INT35
CREATE INDEX idx_webhook_circuit ON public.webhook_retry_queues(circuit_breaker_state) WHERE circuit_breaker_state = 'OPEN';

-- =============================================================================
-- TABLE: data_dictionary_entries
-- Description: Standardized metadata registry for master data management
-- Business Case: Enables data governance and lineage tracking
-- KPIs: Metadata coverage, data quality score, impact analysis time
-- Feature Reference: DG01-DG40 (Data Governance)
-- =============================================================================
DROP TABLE IF EXISTS public.data_dictionary_entries CASCADE;
CREATE TABLE public.data_dictionary_entries (
    entry_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    table_name VARCHAR(100) NOT NULL,
    column_name VARCHAR(100) NOT NULL,
    data_type VARCHAR(50) NOT NULL,
    business_definition TEXT NOT NULL,
    technical_definition TEXT,
    business_owner_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    technical_owner_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    sensitivity_level VARCHAR(20) CHECK (sensitivity_level IN ('PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED')),
    retention_policy_id UUID,
    is_pii BOOLEAN DEFAULT false,
    is_key BOOLEAN DEFAULT false,
    tags TEXT[],
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT unique_table_column UNIQUE (table_name, column_name, deleted_at)
);
COMMENT ON TABLE public.data_dictionary_entries IS 'Standardized metadata registry for master data management';
COMMENT ON COLUMN public.data_dictionary_entries.entry_id IS 'Unique metadata entry identifier';
COMMENT ON COLUMN public.data_dictionary_entries.table_name IS 'Database table containing the column';
COMMENT ON COLUMN public.data_dictionary_entries.column_name IS 'Column name in the database';
COMMENT ON COLUMN public.data_dictionary_entries.data_type IS 'Technical data type of column';
COMMENT ON COLUMN public.data_dictionary_entries.business_definition IS 'Business meaning and usage of data element';
COMMENT ON COLUMN public.data_dictionary_entries.technical_definition IS 'Technical implementation details';
COMMENT ON COLUMN public.data_dictionary_entries.business_owner_id IS 'Business stakeholder responsible for data quality';
COMMENT ON COLUMN public.data_dictionary_entries.technical_owner_id IS 'Technical stakeholder responsible for implementation';
COMMENT ON COLUMN public.data_dictionary_entries.sensitivity_level IS 'Data classification for security controls';
COMMENT ON COLUMN public.data_dictionary_entries.retention_policy_id IS 'Reference to retention policy configuration';
COMMENT ON COLUMN public.data_dictionary_entries.is_pii IS 'Flag indicating personally identifiable information';
COMMENT ON COLUMN public.data_dictionary_entries.is_key IS 'Flag indicating key business identifier';
COMMENT ON COLUMN public.data_dictionary_entries.tags IS 'Searchable tags for data discovery';

-- Index: idx_data_dict_table
-- Description: Supports table metadata queries
-- Business Case: Enables rapid data lineage discovery
-- Feature Reference: DG21-DG25
CREATE INDEX idx_data_dict_table ON public.data_dictionary_entries(table_name, column_name) WHERE deleted_at IS NULL;

-- Index: idx_data_dict_owner
-- Description: Supports data stewardship assignment queries
-- Business Case: Enables data governance responsibility tracking
-- Feature Reference: DG26-DG30
CREATE INDEX idx_data_dict_owner ON public.data_dictionary_entries(business_owner_id);

-- Index: idx_data_dict_tags
-- Description: Supports tag-based data discovery
-- Business Case: Enables business glossary and data catalog search
-- Feature Reference: DG31-DG35
CREATE INDEX idx_data_dict_tags ON public.data_dictionary_entries USING gin(tags);

-- =============================================================================
-- TABLE: data_quality_checks
-- Description: Rule engine for automated data completeness and accuracy validation
-- Business Case: Enables proactive data quality monitoring and alerting
-- KPIs: Data quality score, rule coverage, detection time, false positive rate
-- Feature Reference: DG41-DG70 (Data Quality Management)
-- =============================================================================
DROP TABLE IF EXISTS public.data_quality_checks CASCADE;
CREATE TABLE public.data_quality_checks (
    check_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    table_name VARCHAR(100) NOT NULL,
    column_name VARCHAR(100),
    check_type VARCHAR(50) NOT NULL CHECK (check_type IN ('COMPLETENESS', 'ACCURACY', 'CONSISTENCY', 'UNIQUENESS', 'TIMELINESS', 'VALIDITY')),
    rule_definition JSONB NOT NULL,
    status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE', 'FAILED', 'DEPRECATED')),
    threshold NUMERIC(5,2) DEFAULT 100.0,
    last_run_at TIMESTAMP WITH TIME ZONE,
    last_pass_rate NUMERIC(5,2),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT valid_threshold CHECK (threshold BETWEEN 0 AND 100)
);
COMMENT ON TABLE public.data_quality_checks IS 'Rule engine for automated data completeness and accuracy validation';
COMMENT ON COLUMN public.data_quality_checks.check_id IS 'Unique quality check identifier';
COMMENT ON COLUMN public.data_quality_checks.table_name IS 'Target table for quality validation';
COMMENT ON COLUMN public.data_quality_checks.column_name IS 'Target column for validation (null for table-level)';
COMMENT ON COLUMN public.data_quality_checks.check_type IS 'Category of quality validation';
COMMENT ON COLUMN public.data_quality_checks.rule_definition IS 'JSON containing validation rule logic';
COMMENT ON COLUMN public.data_quality_checks.status IS 'Current rule operational status';
COMMENT ON COLUMN public.data_quality_checks.threshold IS 'Minimum acceptable pass rate percentage';
COMMENT ON COLUMN public.data_quality_checks.last_run_at IS 'Timestamp of most recent execution';
COMMENT ON COLUMN public.data_quality_checks.last_pass_rate IS 'Pass rate from most recent execution';

-- Index: idx_data_quality_table
-- Description: Supports active quality rule queries
-- Business Case: Enables efficient rule processing for data validation jobs
-- Feature Reference: DG51-DG55
CREATE INDEX idx_data_quality_table ON public.data_quality_checks(table_name, status) WHERE status = 'ACTIVE';

-- Index: idx_data_quality_rule
-- Description: Supports JSONB rule definition queries
-- Business Case: Enables dynamic rule discovery and execution
-- Feature Reference: DG56-DG60
CREATE INDEX idx_data_quality_rule ON public.data_quality_checks USING gin(rule_definition);

-- =============================================================================
-- TABLE: data_lineage_edges
-- Description: Provenance tracking for regulatory compliance and impact analysis
-- Business Case: Enables complete data flow visibility for GDPR/CCPA compliance
-- KPIs: Lineage coverage, impact analysis time, data flow accuracy
-- Feature Reference: DG71-DG99 (Data Lineage)
-- =============================================================================
DROP TABLE IF EXISTS public.data_lineage_edges CASCADE;
CREATE TABLE public.data_lineage_edges (
    edge_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    source_entity VARCHAR(100) NOT NULL,
    source_field VARCHAR(100),
    target_entity VARCHAR(100) NOT NULL,
    target_field VARCHAR(100),
    transformation_type VARCHAR(50) CHECK (transformation_type IN ('DIRECT', 'MAPPED', 'AGGREGATED', 'FILTERED', 'ENRICHED')),
    pipeline_id UUID,
    transformation_logic JSONB,
    verified_at TIMESTAMP WITH TIME ZONE,
    verified_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID
);
COMMENT ON TABLE public.data_lineage_edges IS 'Provenance tracking for regulatory compliance and impact analysis';
COMMENT ON COLUMN public.data_lineage_edges.edge_id IS 'Unique lineage relationship identifier';
COMMENT ON COLUMN public.data_lineage_edges.source_entity IS 'Source table or view name';
COMMENT ON COLUMN public.data_lineage_edges.source_field IS 'Source column name (null for whole entity)';
COMMENT ON COLUMN public.data_lineage_edges.target_entity IS 'Target table or view name';
COMMENT ON COLUMN public.data_lineage_edges.target_field IS 'Target column name (null for whole entity)';
COMMENT ON COLUMN public.data_lineage_edges.transformation_type IS 'Type of data transformation applied';
COMMENT ON COLUMN public.data_lineage_edges.pipeline_id IS 'ETL pipeline responsible for transformation';
COMMENT ON COLUMN public.data_lineage_edges.transformation_logic IS 'Detailed transformation logic in JSON';
COMMENT ON COLUMN public.data_lineage_edges.verified_at IS 'Timestamp of lineage verification';
COMMENT ON COLUMN public.data_lineage_edges.verified_by IS 'User who verified lineage accuracy';

-- Index: idx_data_lineage_source
-- Description: Supports upstream dependency analysis
-- Business Case: Enables impact analysis for source changes
-- Feature Reference: DG81-DG85
CREATE INDEX idx_data_lineage_source ON public.data_lineage_edges(source_entity, source_field);

-- Index: idx_data_lineage_target
-- Description: Supports downstream impact analysis
-- Business Case: Enables change impact assessment on target systems
-- Feature Reference: DG86-DG90
CREATE INDEX idx_data_lineage_target ON public.data_lineage_edges(target_entity, target_field);

-- =============================================================================
-- TABLE: workflow_definitions
-- Description: Configurable multi-step approval and routing templates
-- Business Case: Enables no-code workflow automation for business processes
-- KPIs: Workflow creation time, execution success rate, modification frequency
-- Feature Reference: BPM01-BPM35 (Business Process Management)
-- =============================================================================
DROP TABLE IF EXISTS public.workflow_definitions CASCADE;
CREATE TABLE public.workflow_definitions (
    definition_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    workflow_key VARCHAR(100) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    version INTEGER DEFAULT 1 NOT NULL,
    description TEXT,
    trigger_type VARCHAR(50) CHECK (trigger_type IN ('MANUAL', 'SCHEDULED', 'EVENT', 'API')),
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'PAUSED', 'ARCHIVED')),
    definition_json JSONB NOT NULL,
    timeout_hours INTEGER,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE
);
COMMENT ON TABLE public.workflow_definitions IS 'Configurable multi-step approval and routing templates';
COMMENT ON COLUMN public.workflow_definitions.definition_id IS 'Unique workflow template identifier';
COMMENT ON COLUMN public.workflow_definitions.workflow_key IS 'Unique business key for workflow identification';
COMMENT ON COLUMN public.workflow_definitions.name IS 'Human-readable workflow name';
COMMENT ON COLUMN public.workflow_definitions.version IS 'Semantic version of workflow definition';
COMMENT ON COLUMN public.workflow_definitions.description IS 'Workflow purpose and usage documentation';
COMMENT ON COLUMN public.workflow_definitions.trigger_type IS 'How workflow execution is initiated';
COMMENT ON COLUMN public.workflow_definitions.status IS 'Workflow definition lifecycle state';
COMMENT ON COLUMN public.workflow_definitions.definition_json IS 'Complete workflow definition in BPMN-like JSON';
COMMENT ON COLUMN public.workflow_definitions.timeout_hours IS 'Maximum execution time before automatic termination';

-- Index: idx_workflow_def_status
-- Description: Supports active workflow template queries
-- Business Case: Enables efficient workflow deployment and execution
-- Feature Reference: BPM21-BPM25
CREATE INDEX idx_workflow_def_status ON public.workflow_definitions(status) WHERE status = 'ACTIVE';

-- Index: idx_workflow_def_json
-- Description: Supports JSON workflow definition queries
-- Business Case: Enables dynamic workflow discovery and validation
-- Feature Reference: BPM26-BPM30
CREATE INDEX idx_workflow_def_json ON public.workflow_definitions USING gin(definition_json);

-- =============================================================================
-- TABLE: workflow_instances
-- Description: Runtime state and execution history of active workflows
-- Business Case: Enables workflow monitoring, debugging, and SLA tracking
-- KPIs: Execution time, success rate, bottleneck identification, SLA compliance
-- Feature Reference: BPM36-BPM65 (Workflow Execution)
-- =============================================================================
DROP TABLE IF EXISTS public.workflow_instances CASCADE;
CREATE TABLE public.workflow_instances (
    instance_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    definition_id UUID NOT NULL REFERENCES public.workflow_definitions(definition_id) ON DELETE RESTRICT,
    trigger_type VARCHAR(50),
    triggered_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    status VARCHAR(20) DEFAULT 'RUNNING' CHECK (status IN ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED', 'TERMINATED', 'ARCHIVED')),
    current_step VARCHAR(100),
    input_payload JSONB,
    output_payload JSONB,
    error_log TEXT[],
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT valid_dates CHECK (completed_at IS NULL OR completed_at >= started_at)
);
COMMENT ON TABLE public.workflow_instances IS 'Runtime state and execution history of active workflows';
COMMENT ON COLUMN public.workflow_instances.instance_id IS 'Unique workflow execution identifier';
COMMENT ON COLUMN public.workflow_instances.definition_id IS 'Reference to workflow definition';
COMMENT ON COLUMN public.workflow_instances.trigger_type IS 'How this instance was triggered';
COMMENT ON COLUMN public.workflow_instances.triggered_by IS 'User or system that initiated workflow';
COMMENT ON COLUMN public.workflow_instances.status IS 'Current execution state';
COMMENT ON COLUMN public.workflow_instances.current_step IS 'Currently executing step identifier';
COMMENT ON COLUMN public.workflow_instances.input_payload IS 'Input data for workflow execution';
COMMENT ON COLUMN public.workflow_instances.output_payload IS 'Output data from workflow execution';
COMMENT ON COLUMN public.workflow_instances.error_log IS 'Array of error messages during execution';
COMMENT ON COLUMN public.workflow_instances.started_at IS 'Timestamp when execution began';
COMMENT ON COLUMN public.workflow_instances.completed_at IS 'Timestamp when execution finished';

-- Index: idx_workflow_instance_status
-- Description: Supports active workflow monitoring queries
-- Business Case: Enables real-time workflow dashboard and alerts
-- Feature Reference: BPM51-BPM55
CREATE INDEX idx_workflow_instance_status ON public.workflow_instances(definition_id, status) WHERE status = 'RUNNING';

-- Index: idx_workflow_instance_trigger
-- Description: Supports user workflow history queries
-- Business Case: Enables personal workflow audit trail
-- Feature Reference: BPM56-BPM60
CREATE INDEX idx_workflow_instance_trigger ON public.workflow_instances(triggered_by);

-- Index: idx_workflow_timing
-- Description: Supports performance analytics on workflow execution
-- Business Case: Enables bottleneck identification and optimization
-- Feature Reference: BPM61-BPM65
CREATE INDEX idx_workflow_timing ON public.workflow_instances(definition_id, started_at DESC) WHERE status = 'COMPLETED';

-- =============================================================================
-- TABLE: task_assignments
-- Description: SLA-bound task routing and escalation tracking
-- Business Case: Enables accountable task management with automated escalation
-- KPIs: Task completion rate, SLA breach rate, average handling time, escalation rate
-- Feature Reference: BPM66-BPM99 (Task Management)
-- =============================================================================
DROP TABLE IF EXISTS public.task_assignments CASCADE;
CREATE TABLE public.task_assignments (
    task_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    instance_id UUID NOT NULL REFERENCES public.workflow_instances(instance_id) ON DELETE CASCADE,
    assignee_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    role_required VARCHAR(100),
    due_date TIMESTAMP WITH TIME ZONE,
    sla_breach_at TIMESTAMP WITH TIME ZONE,
    status VARCHAR(20) DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'ASSIGNED', 'IN_PROGRESS', 'COMPLETED', 'ESCALATED', 'OVERRIDDEN')),
    priority VARCHAR(20) DEFAULT 'MEDIUM' CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    comments TEXT,
    outcome_json JSONB,
    assigned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT valid_dates CHECK (completed_at IS NULL OR completed_at >= assigned_at)
);
COMMENT ON TABLE public.task_assignments IS 'SLA-bound task routing and escalation tracking';
COMMENT ON COLUMN public.task_assignments.task_id IS 'Unique task identifier';
COMMENT ON COLUMN public.task_assignments.instance_id IS 'Parent workflow instance';
COMMENT ON COLUMN public.task_assignments.assignee_id IS 'User assigned to complete task';
COMMENT ON COLUMN public.task_assignments.role_required IS 'Required role qualification for assignment';
COMMENT ON COLUMN public.task_assignments.due_date IS 'Deadline for task completion';
COMMENT ON COLUMN public.task_assignments.sla_breach_at IS 'Timestamp when SLA was violated';
COMMENT ON COLUMN public.task_assignments.status IS 'Current task lifecycle state';
COMMENT ON COLUMN public.task_assignments.priority IS 'Task urgency level';
COMMENT ON COLUMN public.task_assignments.comments IS 'Task-specific notes and instructions';
COMMENT ON COLUMN public.task_assignments.outcome_json IS 'Structured outcome data from task completion';
COMMENT ON COLUMN public.task_assignments.assigned_at IS 'Timestamp when task was assigned';
COMMENT ON COLUMN public.task_assignments.completed_at IS 'Timestamp when task was completed';

-- Index: idx_task_assignee_status
-- Description: Supports personal task list queries
-- Business Case: Enables efficient user task dashboard
-- Feature Reference: BPM81-BPM85
CREATE INDEX idx_task_assignee_status ON public.task_assignments(assignee_id, status) WHERE status IN ('PENDING', 'IN_PROGRESS');

-- Index: idx_task_due_date
-- Description: Supports SLA monitoring and breach detection
-- Business Case: Enables automated escalation and alerting
-- Feature Reference: BPM86-BPM90
CREATE INDEX idx_task_due_date ON public.task_assignments(due_date) WHERE due_date IS NOT NULL AND status != 'COMPLETED';

-- Index: idx_task_sla
-- Description: Identifies SLA breaches for remediation
-- Business Case: Enables proactive SLA management
-- Feature Reference: BPM91-BPM95
CREATE INDEX idx_task_sla ON public.task_assignments(sla_breach_at) WHERE sla_breach_at > NOW() AND status != 'COMPLETED';

-- =============================================================================
-- TABLE: tax_jurisdictions
-- Description: Geo/time-bound tax rule storage for multi-region compliance
-- Business Case: Enables accurate tax calculation across 200+ jurisdictions
-- KPIs: Tax accuracy rate, calculation speed, jurisdiction coverage
-- Feature Reference: TAX01-TAX40 (Tax Management)
-- =============================================================================
DROP TABLE IF EXISTS public.tax_jurisdictions CASCADE;
CREATE TABLE public.tax_jurisdictions (
    jurisdiction_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    code VARCHAR(20) UNIQUE NOT NULL,
    name VARCHAR(255) NOT NULL,
    country_code CHAR(2) NOT NULL,
    region_code VARCHAR(50),
    tax_type VARCHAR(50) CHECK (tax_type IN ('VAT', 'GST', 'SALES_TAX', 'USE_TAX', 'EXCISE', 'CUSTOMS')),
    effective_from DATE NOT NULL,
    effective_to DATE,
    is_active BOOLEAN DEFAULT true,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    CONSTRAINT valid_dates CHECK (effective_to IS NULL OR effective_to >= effective_from)
);
COMMENT ON TABLE public.tax_jurisdictions IS 'Geo/time-bound tax rule storage for multi-region compliance';
COMMENT ON COLUMN public.tax_jurisdictions.jurisdiction_id IS 'Unique tax jurisdiction identifier';
COMMENT ON COLUMN public.tax_jurisdictions.code IS 'Short jurisdiction code for reference';
COMMENT ON COLUMN public.tax_jurisdictions.name IS 'Full jurisdiction name';
COMMENT ON COLUMN public.tax_jurisdictions.country_code IS 'ISO 3166-1 alpha-2 country code';
COMMENT ON COLUMN public.tax_jurisdictions.region_code IS 'State, province, or region identifier';
COMMENT ON COLUMN public.tax_jurisdictions.tax_type IS 'Type of tax applied in jurisdiction';
COMMENT ON COLUMN public.tax_jurisdictions.effective_from IS 'Date when tax rules become effective';
COMMENT ON COLUMN public.tax_jurisdictions.effective_to IS 'Date when tax rules expire (null for current)';
COMMENT ON COLUMN public.tax_jurisdictions.is_active IS 'Whether jurisdiction is currently applicable';
COMMENT ON COLUMN public.tax_jurisdictions.metadata IS 'Additional jurisdiction-specific tax data';

-- Index: idx_tax_jurisdiction_active
-- Description: Supports active tax rule lookups by country
-- Business Case: Enables fast tax calculation for international transactions
-- Feature Reference: TAX21-TAX25
CREATE INDEX idx_tax_jurisdiction_active ON public.tax_jurisdictions(country_code, tax_type, is_active) WHERE is_active = true;

-- Index: idx_tax_effective_dates
-- Description: Supports historical tax rate queries
-- Business Case: Enables tax calculation for back-dated transactions
-- Feature Reference: TAX26-TAX30
CREATE INDEX idx_tax_effective_dates ON public.tax_jurisdictions(effective_from, effective_to) WHERE is_active = true;

-- =============================================================================
-- TABLE: tax_calculations
-- Description: Pre-computed tax breakdowns for invoices and financial auditing
-- Business Case: Enables tax audit trail with line-level detail
-- KPIs: Calculation accuracy, audit completeness, reconciliation speed
-- Feature Reference: TAX41-TAX70 (Tax Calculation)
-- =============================================================================
DROP TABLE IF EXISTS public.tax_calculations CASCADE;
CREATE TABLE public.tax_calculations (
    calculation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    invoice_id UUID REFERENCES public.invoices(invoice_id) ON DELETE SET NULL,
    line_item_id UUID,
    jurisdiction_id UUID NOT NULL REFERENCES public.tax_jurisdictions(jurisdiction_id) ON DELETE RESTRICT,
    taxable_amount NUMERIC(15,4) NOT NULL,
    tax_rate NUMERIC(5,4) NOT NULL,
    tax_amount NUMERIC(15,4) NOT NULL,
    calculated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID
);
COMMENT ON TABLE public.tax_calculations IS 'Pre-computed tax breakdowns for invoices and financial auditing';
COMMENT ON COLUMN public.tax_calculations.calculation_id IS 'Unique tax calculation identifier';
COMMENT ON COLUMN public.tax_calculations.invoice_id IS 'Associated invoice for header-level tax';
COMMENT ON COLUMN public.tax_calculations.line_item_id IS 'Associated line item for detail-level tax';
COMMENT ON COLUMN public.tax_calculations.jurisdiction_id IS 'Jurisdiction where tax was calculated';
COMMENT ON COLUMN public.tax_calculations.taxable_amount IS 'Base amount subject to tax';
COMMENT ON COLUMN public.tax_calculations.tax_rate IS 'Applied tax rate as decimal (e.g., 0.08 for 8%)';
COMMENT ON COLUMN public.tax_calculations.tax_amount IS 'Calculated tax amount';
COMMENT ON COLUMN public.tax_calculations.calculated_at IS 'Timestamp when calculation was performed';
COMMENT ON COLUMN public.tax_calculations.created_by IS 'User or system that performed calculation';

-- Index: idx_tax_calc_invoice
-- Description: Supports invoice-level tax audit queries
-- Business Case: Enables rapid tax audit for invoices
-- Feature Reference: TAX56-TAX60
CREATE INDEX idx_tax_calc_invoice ON public.tax_calculations(invoice_id);

-- Index: idx_tax_calc_jurisdiction
-- Description: Supports jurisdictional tax analysis
-- Business Case: Enables tax liability reporting by jurisdiction
-- Feature Reference: TAX61-TAX65
CREATE INDEX idx_tax_calc_jurisdiction ON public.tax_calculations(jurisdiction_id);

-- =============================================================================
-- TABLE: journal_entries
-- Description: Double-entry audit trail header for GAAP/IFRS accounting
-- Business Case: Enables complete financial audit trail with reconciliation
-- KPIs: Audit trail completeness, reconciliation speed, posting accuracy
-- Feature Reference: FIN81-FIN120 (General Ledger)
-- =============================================================================
DROP TABLE IF EXISTS public.journal_entries CASCADE;
CREATE TABLE public.journal_entries (
    entry_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    entry_number VARCHAR(50) UNIQUE NOT NULL,
    transaction_date DATE NOT NULL,
    description TEXT,
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'POSTED', 'REVERSED', 'CANCELLED')),
    posted_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    posted_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID
);
COMMENT ON TABLE public.journal_entries IS 'Double-entry audit trail header for GAAP/IFRS accounting';
COMMENT ON COLUMN public.journal_entries.entry_id IS 'Unique journal entry identifier';
COMMENT ON COLUMN public.journal_entries.entry_number IS 'Sequential journal entry number for accounting';
COMMENT ON COLUMN public.journal_entries.transaction_date IS 'Date of the underlying transaction';
COMMENT ON COLUMN public.journal_entries.description IS 'Narrative description of the entry';
COMMENT ON COLUMN public.journal_entries.status IS 'Journal entry lifecycle state';
COMMENT ON COLUMN public.journal_entries.posted_by IS 'User who posted the entry to general ledger';
COMMENT ON COLUMN public.journal_entries.posted_at IS 'Timestamp when entry was posted';

-- Index: idx_journal_entry_status
-- Description: Supports draft and posted entry queries
-- Business Case: Enables efficient period-end closing process
-- Feature Reference: FIN101-FIN105
CREATE INDEX idx_journal_entry_status ON public.journal_entries(status, transaction_date) WHERE status IN ('POSTED', 'DRAFT');

-- Index: idx_journal_entry_number
-- Description: Supports sequential number validation
-- Business Case: Ensures no gaps in audit trail
-- Feature Reference: FIN106-FIN110
CREATE INDEX idx_journal_entry_number ON public.journal_entries(entry_number);

-- =============================================================================
-- TABLE: documents
-- Description: Centralized document repository with metadata and version control
-- Business Case: Enables secure document management with full audit trail
-- KPIs: Storage efficiency, retrieval speed, access compliance, version accuracy
-- Feature Reference: DOC01-DOC40 (Document Management)
-- =============================================================================
DROP TABLE IF EXISTS public.documents CASCADE;
CREATE TABLE public.documents (
    document_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    title VARCHAR(500) NOT NULL,
    description TEXT,
    document_type VARCHAR(50) NOT NULL,
    storage_path VARCHAR(1000) NOT NULL,
    mime_type VARCHAR(100),
    size_bytes BIGINT,
    owner_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'ARCHIVED', 'DELETED')),
    tags TEXT[],
    metadata JSONB,
    search_vector tsvector GENERATED ALWAYS AS (
        setweight(to_tsvector('english', COALESCE(title, '')), 'A') ||
        setweight(to_tsvector('english', COALESCE(description, '')), 'B')
    ) STORED,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE
);
COMMENT ON TABLE public.documents IS 'Centralized document repository with metadata and version control';
COMMENT ON COLUMN public.documents.document_id IS 'Unique document identifier';
COMMENT ON COLUMN public.documents.title IS 'Document title or name';
COMMENT ON COLUMN public.documents.description IS 'Document description and purpose';
COMMENT ON COLUMN public.documents.document_type IS 'Classification of document (e.g., CONTRACT, INVOICE, POLICY)';
COMMENT ON COLUMN public.documents.storage_path IS 'Path to document in object storage';
COMMENT ON COLUMN public.documents.mime_type IS 'Document MIME type for rendering';
COMMENT ON COLUMN public.documents.size_bytes IS 'Document size in bytes for storage planning';
COMMENT ON COLUMN public.documents.owner_id IS 'User who owns the document';
COMMENT ON COLUMN public.documents.status IS 'Document lifecycle state';
COMMENT ON COLUMN public.documents.tags IS 'Searchable tags for categorization';
COMMENT ON COLUMN public.documents.metadata IS 'Extended document metadata';
COMMENT ON COLUMN public.documents.search_vector IS 'Full-text search vector for document discovery';

-- Index: idx_doc_status
-- Description: Supports active document queries
-- Business Case: Enables efficient document retrieval
-- Feature Reference: DOC21-DOC25
CREATE INDEX idx_doc_status ON public.documents(status, created_at DESC) WHERE status IN ('ACTIVE', 'DRAFT');

-- Index: idx_doc_owner
-- Description: Supports user document queries
-- Business Case: Enables personal document workspace
-- Feature Reference: DOC26-DOC30
CREATE INDEX idx_doc_owner ON public.documents(owner_id);

-- Index: idx_doc_tags
-- Description: Supports tag-based document discovery
-- Business Case: Enables faceted document search
-- Feature Reference: DOC31-DOC35
CREATE INDEX idx_doc_tags ON public.documents USING gin(tags);

-- Index: idx_document_search
-- Description: Supports full-text search on documents
-- Business Case: Enables content-based document discovery
-- Feature Reference: DOC36-DOC40
CREATE INDEX idx_document_search ON public.documents USING GIN(search_vector);

-- =============================================================================
-- TABLE: document_versions
-- Description: Immutable historical versions of documents for audit and rollback
-- Business Case: Enables complete version history with compliance retention
-- KPIs: Version integrity, retrieval speed, storage efficiency
-- Feature Reference: DOC41-DOC60 (Version Control)
-- =============================================================================
DROP TABLE IF EXISTS public.document_versions CASCADE;
CREATE TABLE public.document_versions (
    version_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    document_id UUID NOT NULL REFERENCES public.documents(document_id) ON DELETE CASCADE,
    version_number INTEGER NOT NULL CHECK (version_number > 0),
    storage_path VARCHAR(1000) NOT NULL,
    content_hash VARCHAR(64) NOT NULL,
    change_summary TEXT,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT unique_doc_version UNIQUE (document_id, version_number)
);
COMMENT ON TABLE public.document_versions IS 'Immutable historical versions of documents for audit and rollback';
COMMENT ON COLUMN public.document_versions.version_id IS 'Unique version identifier';
COMMENT ON COLUMN public.document_versions.document_id IS 'Parent document reference';
COMMENT ON COLUMN public.document_versions.version_number IS 'Sequential version number';
COMMENT ON COLUMN public.document_versions.storage_path IS 'Path to version in object storage';
COMMENT ON COLUMN public.document_versions.content_hash IS 'SHA-256 hash for integrity verification';
COMMENT ON COLUMN public.document_versions.change_summary IS 'Description of changes in this version';
COMMENT ON COLUMN public.document_versions.created_by IS 'User who created this version';
COMMENT ON COLUMN public.document_versions.created_at IS 'Timestamp when version was created';

-- Index: idx_doc_version_doc
-- Description: Supports document version history queries
-- Business Case: Enables version browsing and rollback
-- Feature Reference: DOC51-DOC55
CREATE INDEX idx_doc_version_doc ON public.document_versions(document_id, version_number DESC);

-- Index: idx_doc_version_hash
-- Description: Supports content integrity verification
-- Business Case: Enables duplicate detection and integrity checks
-- Feature Reference: DOC56-DOC60
CREATE INDEX idx_doc_version_hash ON public.document_versions(content_hash);

-- =============================================================================
-- TABLE: digital_signatures
-- Description: Cryptographic signatures with certificate chains for legal enforceability
-- Business Case: Enables legally binding electronic signatures with non-repudiation
-- KPIs: Signature verification time, certificate validity, legal acceptance rate
-- Feature Reference: SIG01-SIG35 (Digital Signatures)
-- =============================================================================
DROP TABLE IF EXISTS public.digital_signatures CASCADE;
CREATE TABLE public.digital_signatures (
    signature_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    document_id UUID NOT NULL REFERENCES public.documents(document_id) ON DELETE CASCADE,
    signature_algorithm VARCHAR(50) NOT NULL CHECK (signature_algorithm IN ('RSA-SHA256', 'ECDSA-SHA256', 'ED25519')),
    certificate_chain JSONB,
    signed_data_hash VARCHAR(64) NOT NULL,
    signature_value TEXT NOT NULL,
    signed_at TIMESTAMP WITH TIME ZONE NOT NULL,
    signer_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    status VARCHAR(20) DEFAULT 'VALID' CHECK (status IN ('VALID', 'REVOKED', 'EXPIRED')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);
COMMENT ON TABLE public.digital_signatures IS 'Cryptographic signatures with certificate chains for legal enforceability';
COMMENT ON COLUMN public.digital_signatures.signature_id IS 'Unique signature identifier';
COMMENT ON COLUMN public.digital_signatures.document_id IS 'Signed document reference';
COMMENT ON COLUMN public.digital_signatures.signature_algorithm IS 'Cryptographic algorithm used';
COMMENT ON COLUMN public.digital_signatures.certificate_chain IS 'X.509 certificate chain in JSON format';
COMMENT ON COLUMN public.digital_signatures.signed_data_hash IS 'Hash of signed content';
COMMENT ON COLUMN public.digital_signatures.signature_value IS 'Base64-encoded cryptographic signature';
COMMENT ON COLUMN public.digital_signatures.signed_at IS 'Timestamp when signature was applied';
COMMENT ON COLUMN public.digital_signatures.signer_id IS 'User who applied the signature';
COMMENT ON COLUMN public.digital_signatures.status IS 'Signature validity state';

-- Index: idx_digital_sig_doc
-- Description: Supports document signature queries
-- Business Case: Enables signature verification for documents
-- Feature Reference: SIG21-SIG25
CREATE INDEX idx_digital_sig_doc ON public.digital_signatures(document_id);

-- Index: idx_digital_sig_signer
-- Description: Supports signer signature history queries
-- Business Case: Enables audit of user signing activity
-- Feature Reference: SIG26-SIG30
CREATE INDEX idx_digital_sig_signer ON public.digital_signatures(signer_id);

-- Index: idx_digital_sig_status
-- Description: Supports signature validity monitoring
-- Business Case: Enables certificate expiration alerts
-- Feature Reference: SIG31-SIG35
CREATE INDEX idx_digital_sig_status ON public.digital_signatures(status, signed_at) WHERE status = 'EXPIRED';

-- =============================================================================
-- TABLE: contracts
-- Description: Master contract registry with lifecycle and financial tracking
-- Business Case: Enables complete contract lifecycle management from negotiation to termination
-- KPIs: Contract value, renewal rate, compliance score, time-to-execution
-- Feature Reference: CON01-CON50 (Contract Management)
-- =============================================================================
DROP TABLE IF EXISTS public.contracts CASCADE;
CREATE TABLE public.contracts (
    contract_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    title VARCHAR(500) NOT NULL,
    contract_number VARCHAR(50) UNIQUE,
    counterparty_id UUID,
    contract_type VARCHAR(50) NOT NULL,
    status VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'NEGOTIATION', 'ACTIVE', 'EXPIRED', 'TERMINATED')),
    effective_date DATE,
    expiration_date DATE,
    total_value NUMERIC(15,4),
    currency CHAR(3) DEFAULT 'USD',
    owner_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    metadata JSONB,
    search_vector tsvector GENERATED ALWAYS AS (
        setweight(to_tsvector('english', COALESCE(title, '')), 'A') ||
        setweight(to_tsvector('english', COALESCE(contract_number, '')), 'B')
    ) STORED,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT valid_dates CHECK (expiration_date IS NULL OR effective_date IS NULL OR expiration_date >= effective_date)
);
COMMENT ON TABLE public.contracts IS 'Master contract registry with lifecycle and financial tracking';
COMMENT ON COLUMN public.contracts.contract_id IS 'Unique contract identifier';
COMMENT ON COLUMN public.contracts.title IS 'Contract title or name';
COMMENT ON COLUMN public.contracts.contract_number IS 'Legal contract number for reference';
COMMENT ON COLUMN public.contracts.counterparty_id IS 'Other party to the contract';
COMMENT ON COLUMN public.contracts.contract_type IS 'Type of contract (SaaS, Service, License, etc.)';
COMMENT ON COLUMN public.contracts.status IS 'Contract lifecycle state';
COMMENT ON COLUMN public.contracts.effective_date IS 'Date when contract becomes binding';
COMMENT ON COLUMN public.contracts.expiration_date IS 'Date when contract expires';
COMMENT ON COLUMN public.contracts.total_value IS 'Total contract value over lifetime';
COMMENT ON COLUMN public.contracts.currency IS 'Currency of financial values';
COMMENT ON COLUMN public.contracts.owner_id IS 'Contract owner responsible for management';
COMMENT ON COLUMN public.contracts.metadata IS 'Contract-specific metadata and attributes';
COMMENT ON COLUMN public.contracts.search_vector IS 'Full-text search vector for contract discovery';

-- Index: idx_contract_status
-- Description: Supports active contract monitoring
-- Business Case: Enables expiration alerts and renewal tracking
-- Feature Reference: CON31-CON35
CREATE INDEX idx_contract_status ON public.contracts(status, expiration_date) WHERE status = 'ACTIVE';

-- Index: idx_contract_owner
-- Description: Supports contract portfolio queries
-- Business Case: Enables contract manager workload tracking
-- Feature Reference: CON36-CON40
CREATE INDEX idx_contract_owner ON public.contracts(owner_id);

-- Index: idx_contract_search
-- Description: Supports full-text search on contracts
-- Business Case: Enables contract discovery and legal research
-- Feature Reference: CON41-CON45
CREATE INDEX idx_contract_search ON public.contracts USING GIN(search_vector);

-- Index: idx_contracts_covering
-- Description: Covering index for common contract queries
-- Business Case: Optimizes contract dashboard performance
-- Feature Reference: CON46-CON50
CREATE INDEX idx_contracts_covering ON public.contracts(contract_type, status) INCLUDE (title, total_value, effective_date, expiration_date) WHERE deleted_at IS NULL;

-- =============================================================================
-- TABLE: contract_clauses
-- Description: Legal clause extraction and obligation tracking for compliance
-- Business Case: Enables automated obligation monitoring and risk assessment
-- KPIs: Clause extraction accuracy, compliance rate, risk identification speed
-- Feature Reference: CON51-CON80 (Contract Compliance)
-- =============================================================================
DROP TABLE IF EXISTS public.contract_clauses CASCADE;
CREATE TABLE public.contract_clauses (
    clause_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    contract_id UUID NOT NULL REFERENCES public.contracts(contract_id) ON DELETE CASCADE,
    clause_type VARCHAR(100) NOT NULL,
    clause_text TEXT NOT NULL,
    risk_rating VARCHAR(20) CHECK (risk_rating IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    compliance_status VARCHAR(20) DEFAULT 'COMPLIANT',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID
);
COMMENT ON TABLE public.contract_clauses IS 'Legal clause extraction and obligation tracking for compliance';
COMMENT ON COLUMN public.contract_clauses.clause_id IS 'Unique clause identifier';
COMMENT ON COLUMN public.contract_clauses.contract_id IS 'Parent contract reference';
COMMENT ON COLUMN public.contract_clauses.clause_type IS 'Classification of clause (Indemnification, Termination, etc.)';
COMMENT ON COLUMN public.contract_clauses.clause_text IS 'Full text of the legal clause';
COMMENT ON COLUMN public.contract_clauses.risk_rating IS 'Risk level associated with clause';
COMMENT ON COLUMN public.contract_clauses.compliance_status IS 'Current compliance state of clause obligations';

-- Index: idx_clause_contract
-- Description: Supports contract clause extraction queries
-- Business Case: Enables clause-level contract analysis
-- Feature Reference: CON66-CON70
CREATE INDEX idx_clause_contract ON public.contract_clauses(contract_id);

-- Index: idx_clause_type
-- Description: Supports clause type analysis across contracts
-- Business Case: Enables contract pattern analysis
-- Feature Reference: CON71-CON75
CREATE INDEX idx_clause_type ON public.contract_clauses(clause_type);

-- Index: idx_clause_compliance
-- Description: Supports compliance monitoring queries
-- Business Case: Enables automated obligation tracking
-- Feature Reference: CON76-CON80
CREATE INDEX idx_clause_compliance ON public.contract_clauses(compliance_status, risk_rating) WHERE compliance_status != 'COMPLIANT';

-- =============================================================================
-- TABLE: health_check_results
-- Description: Synthetic and endpoint monitoring logs for system health tracking
-- Business Case: Enables proactive system health monitoring with historical analysis
-- KPIs: System uptime, response time percentiles, error rate, MTTR
-- Feature Reference: SRE01-SRE30 (System Monitoring)
-- =============================================================================
DROP TABLE IF EXISTS public.health_check_results CASCADE;
CREATE TABLE public.health_check_results (
    check_id BIGSERIAL,
    check_type VARCHAR(50) NOT NULL,
    endpoint VARCHAR(500) NOT NULL,
    status VARCHAR(20) NOT NULL CHECK (status IN ('HEALTHY', 'DEGRADED', 'UNHEALTHY', 'UNKNOWN')),
    response_time_ms INTEGER,
    status_code INTEGER,
    details JSONB,
    checked_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY (check_id, checked_at)
) PARTITION BY RANGE (checked_at);
COMMENT ON TABLE public.health_check_results IS 'Synthetic and endpoint monitoring logs for system health tracking';
COMMENT ON COLUMN public.health_check_results.check_id IS 'Sequential health check identifier';
COMMENT ON COLUMN public.health_check_results.check_type IS 'Type of health check (HTTP, TCP, DNS, etc.)';
COMMENT ON COLUMN public.health_check_results.endpoint IS 'Monitored endpoint identifier';
COMMENT ON COLUMN public.health_check_results.status IS 'Health status of the endpoint';
COMMENT ON COLUMN public.health_check_results.response_time_ms IS 'Response time in milliseconds';
COMMENT ON COLUMN public.health_check_results.status_code IS 'HTTP status code or protocol-specific code';
COMMENT ON COLUMN public.health_check_results.details IS 'Detailed health check metadata and diagnostics';
COMMENT ON COLUMN public.health_check_results.checked_at IS 'Timestamp when health check was performed';

-- Index: idx_health_endpoint_status
-- Description: Supports endpoint health trend analysis
-- Business Case: Enables SLA monitoring and alerting
-- Feature Reference: SRE21-SRE25
CREATE INDEX idx_health_endpoint_status ON public.health_check_results(endpoint, status, checked_at DESC);

-- Index: idx_health_timing
-- Description: Supports response time percentile calculations
-- Business Case: Enables performance SLO monitoring
-- Feature Reference: SRE26-SRE30
CREATE INDEX idx_health_timing ON public.health_check_results(endpoint, checked_at DESC, response_time_ms);

-- =============================================================================
-- TABLE: alert_policies
-- Description: Threshold-based alerting rules for monitoring systems
-- Business Case: Enables automated alerting with customizable thresholds
-- KPIs: Alert accuracy, false positive rate, detection time, resolution time
-- Feature Reference: SRE31-SRE55 (Alerting)
-- =============================================================================
DROP TABLE IF EXISTS public.alert_policies CASCADE;
CREATE TABLE public.alert_policies (
    policy_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    metric_name VARCHAR(100) NOT NULL,
    comparison_operator VARCHAR(10) CHECK (comparison_operator IN ('>', '>=', '<', '<=', '=', '!=', 'CHANGES')),
    threshold NUMERIC(20,6) NOT NULL,
    evaluation_window_seconds INTEGER DEFAULT 60,
    notification_channel VARCHAR(50),
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE
);
COMMENT ON TABLE public.alert_policies IS 'Threshold-based alerting rules for monitoring systems';
COMMENT ON COLUMN public.alert_policies.policy_id IS 'Unique alert policy identifier';
COMMENT ON COLUMN public.alert_policies.name IS 'Human-readable policy name';
COMMENT ON COLUMN public.alert_policies.metric_name IS 'Metric being monitored';
COMMENT ON COLUMN public.alert_policies.comparison_operator IS 'Operator for threshold comparison';
COMMENT ON COLUMN public.alert_policies.threshold IS 'Threshold value for alerting';
COMMENT ON COLUMN public.alert_policies.evaluation_window_seconds IS 'Time window for metric evaluation';
COMMENT ON COLUMN public.alert_policies.notification_channel IS 'Channel for alert notifications';
COMMENT ON COLUMN public.alert_policies.is_active IS 'Whether policy is currently enforced';

-- Index: idx_alert_active
-- Description: Supports active policy evaluation
-- Business Case: Enables efficient alert processing
-- Feature Reference: SRE46-SRE50
CREATE INDEX idx_alert_active ON public.alert_policies(is_active, metric_name) WHERE is_active = true;

-- =============================================================================
-- TABLE: escalation_policies
-- Description: Tiered escalation rules for incident response automation
-- Business Case: Enables automated incident escalation based on severity and duration
-- KPIs: Escalation accuracy, response time, resolution SLA compliance
-- Feature Reference: SRE56-SRE80 (Incident Response)
