    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE
);
COMMENT ON TABLE public.escalation_policies IS 'Tiered escalation rules for incident response automation';
COMMENT ON COLUMN public.escalation_policies.policy_id IS 'Unique escalation policy identifier';
COMMENT ON COLUMN public.escalation_policies.name IS 'Policy name for reference';
COMMENT ON COLUMN public.escalation_policies.severity IS 'Incident severity level';
COMMENT ON COLUMN public.escalation_policies.levels IS 'JSON array of escalation levels with targets and timing';
COMMENT ON COLUMN public.escalation_policies.timeout_minutes IS 'Time before escalation to next level';
COMMENT ON COLUMN public.escalation_policies.is_active IS 'Whether policy is currently enforced';

-- Index: idx_escalation_severity
-- Description: Supports severity-based escalation queries
-- Business Case: Enables rapid escalation rule lookup
-- Feature Reference: SRE71-SRE75
CREATE INDEX idx_escalation_severity ON public.escalation_policies(severity, is_active) WHERE is_active = true;

-- Index: idx_escalation_levels
-- Description: Supports JSON escalation level queries
-- Business Case: Enables dynamic escalation configuration
-- Feature Reference: SRE76-SRE80
CREATE INDEX idx_escalation_levels ON public.escalation_policies USING gin(levels);

-- =============================================================================
-- TABLE: on_call_schedules
-- Description: Rotation rosters and override management for incident response
-- Business Case: Enables 24/7 coverage with automated scheduling
-- KPIs: Coverage completeness, schedule adherence, response time
-- Feature Reference: SRE81-SRE99 (On-Call Management)
-- =============================================================================
DROP TABLE IF EXISTS public.on_call_schedules CASCADE;
CREATE TABLE public.on_call_schedules (
    schedule_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    timezone VARCHAR(50) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    rotation_type VARCHAR(50) CHECK (rotation_type IN ('WEEKLY', 'DAILY', 'CUSTOM')),
    participants JSONB NOT NULL,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE,
    CONSTRAINT valid_dates CHECK (end_date IS NULL OR end_date >= start_date)
);
COMMENT ON TABLE public.on_call_schedules IS 'Rotation rosters and override management for incident response';
COMMENT ON COLUMN public.on_call_schedules.schedule_id IS 'Unique schedule identifier';
COMMENT ON COLUMN public.on_call_schedules.name IS 'Schedule name for reference';
COMMENT ON COLUMN public.on_call_schedules.timezone IS 'IANA timezone for schedule';
COMMENT ON COLUMN public.on_call_schedules.start_date IS 'Schedule effective start date';
COMMENT ON COLUMN public.on_call_schedules.end_date IS 'Schedule effective end date';
COMMENT ON COLUMN public.on_call_schedules.rotation_type IS 'Type of rotation pattern';
COMMENT ON COLUMN public.on_call_schedules.participants IS 'JSON array of on-call participants with roles';
COMMENT ON COLUMN public.on_call_schedules.is_active IS 'Whether schedule is currently active';

-- Index: idx_oncall_active
-- Description: Supports active schedule queries
-- Business Case: Enables current on-call determination
-- Feature Reference: SRE91-SRE95
CREATE INDEX idx_oncall_active ON public.on_call_schedules(is_active, start_date) WHERE is_active = true;

-- =============================================================================
-- TABLE: api_gateway_routes
-- Description: Routing, rate limiting, and transformation rules for API management
-- Business Case: Enables centralized API governance with security policies
-- KPIs: Route performance, rate limit compliance, error rate, auth success rate
-- Feature Reference: API01-API35 (API Management)
-- =============================================================================
DROP TABLE IF EXISTS public.api_gateway_routes CASCADE;
CREATE TABLE public.api_gateway_routes (
    route_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    path VARCHAR(500) NOT NULL,
    method VARCHAR(10) DEFAULT 'ANY' CHECK (method IN ('GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'ANY')),
    backend_service VARCHAR(100) NOT NULL,
    rate_limit INTEGER,
    timeout_ms INTEGER DEFAULT 5000,
    auth_required BOOLEAN DEFAULT true,
    is_active BOOLEAN DEFAULT true,
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID,
    updated_by UUID,
    deleted_at TIMESTAMP WITH TIME ZONE
);
COMMENT ON TABLE public.api_gateway_routes IS 'Routing, rate limiting, and transformation rules for API management';
COMMENT ON COLUMN public.api_gateway_routes.route_id IS 'Unique route identifier';
COMMENT ON COLUMN public.api_gateway_routes.path IS 'API path pattern with wildcard support';
COMMENT ON COLUMN public.api_gateway_routes.method IS 'HTTP method or ANY for all methods';
COMMENT ON COLUMN public.api_gateway_routes.backend_service IS 'Target backend service identifier';
COMMENT ON COLUMN public.api_gateway_routes.rate_limit IS 'Requests per minute limit (null for unlimited)';
COMMENT ON COLUMN public.api_gateway_routes.timeout_ms IS 'Request timeout in milliseconds';
COMMENT ON COLUMN public.api_gateway_routes.auth_required IS 'Whether authentication is required';
COMMENT ON COLUMN public.api_gateway_routes.is_active IS 'Whether route is currently enabled';
COMMENT ON COLUMN public.api_gateway_routes.metadata IS 'Additional route configuration and transformations';

