-- =============================================================================
-- MATERIALIZED VIEW: user_activity_dashboard
-- Description: Daily user activity metrics for executive dashboards
-- Business Case: Provides pre-aggregated user engagement metrics
-- KPIs: DAU, WAU, MAU, adoption rate, engagement score
-- Feature Reference: ANA01-ANA20 (User Analytics)
-- =============================================================================
DROP MATERIALIZED VIEW IF EXISTS public.user_activity_dashboard CASCADE;
CREATE MATERIALIZED VIEW public.user_activity_dashboard AS
SELECT
    DATE(u.last_login) as date,
    COUNT(DISTINCT u.user_id) as active_users,
    COUNT(DISTINCT CASE WHEN EXTRACT(HOUR FROM u.last_login) BETWEEN 9 AND 17 THEN u.user_id END) as business_hours_users,
    COUNT(DISTINCT CASE WHEN EXTRACT(HOUR FROM u.last_login) NOT BETWEEN 9 AND 17 THEN u.user_id END) as after_hours_users,
    COUNT(DISTINCT CASE WHEN u.last_login > NOW() - INTERVAL '7 days' THEN u.user_id END) as weekly_active_users,
    COUNT(DISTINCT CASE WHEN u.last_login > NOW() - INTERVAL '30 days' THEN u.user_id END) as monthly_active_users,
    ROUND(100.0 * COUNT(DISTINCT CASE WHEN u.last_login > NOW() - INTERVAL '30 days' THEN u.user_id END) / NULLIF(COUNT(DISTINCT u.user_id), 0), 2) as retention_rate
FROM public.users u
WHERE u.deleted_at IS NULL
GROUP BY DATE(u.last_login)
WITH DATA;
COMMENT ON MATERIALIZED VIEW public.user_activity_dashboard IS 'Daily user activity metrics for executive dashboards';
COMMENT ON COLUMN public.user_activity_dashboard.date IS 'Date of activity measurement';
COMMENT ON COLUMN public.user_activity_dashboard.active_users IS 'Daily Active Users (DAU)';
COMMENT ON COLUMN public.user_activity_dashboard.business_hours_users IS 'Users active during 9 AM - 5 PM';
COMMENT ON COLUMN public.user_activity_dashboard.after_hours_users IS 'Users active outside business hours';
COMMENT ON COLUMN public.user_activity_dashboard.weekly_active_users IS 'Weekly Active Users (WAU)';
COMMENT ON COLUMN public.user_activity_dashboard.monthly_active_users IS 'Monthly Active Users (MAU)';
COMMENT ON COLUMN public.user_activity_dashboard.retention_rate IS 'Percentage of users retained month-over-month';

CREATE UNIQUE INDEX idx_user_activity_dashboard_date ON public.user_activity_dashboard(date);
CREATE INDEX idx_user_activity_dashboard_retention ON public.user_activity_dashboard(retention_rate DESC);

-- =============================================================================
-- MATERIALIZED VIEW: contract_compliance_dashboard
-- Description: Contract lifecycle and compliance metrics
-- Business Case: Enables executive visibility into contract portfolio health
-- KPIs: Contract value, compliance rate, renewal rate, risk exposure
-- Feature Reference: ANA21-ANA40 (Contract Analytics)
-- =============================================================================
DROP MATERIALIZED VIEW IF EXISTS public.contract_compliance_dashboard CASCADE;
CREATE MATERIALIZED VIEW public.contract_compliance_dashboard AS
SELECT
    c.contract_type,
    c.status,
    COUNT(*) as contract_count,
    SUM(c.total_value) as total_value,
    AVG(EXTRACT(DAY FROM (c.expiration_date - c.effective_date))) as avg_duration_days,
    COUNT(CASE WHEN cc.compliance_status != 'COMPLIANT' THEN 1 END) as non_compliant_clauses,
    COUNT(CASE WHEN c.expiration_date < NOW() AND c.status = 'ACTIVE' THEN 1 END) as expired_active_contracts,
    ROUND(100.0 * COUNT(CASE WHEN cc.compliance_status = 'COMPLIANT' THEN 1 END) / NULLIF(COUNT(cc.clause_id), 0), 2) as compliance_rate
FROM public.contracts c
LEFT JOIN public.contract_clauses cc ON c.contract_id = cc.contract_id
WHERE c.deleted_at IS NULL
GROUP BY c.contract_type, c.status
WITH DATA;
COMMENT ON MATERIALIZED VIEW public.contract_compliance_dashboard IS 'Contract lifecycle and compliance metrics';
COMMENT ON COLUMN public.contract_compliance_dashboard.contract_type IS 'Type of contract classification';
COMMENT ON COLUMN public.contract_compliance_dashboard.status IS 'Contract lifecycle status';
COMMENT ON COLUMN public.contract_compliance_dashboard.contract_count IS 'Number of contracts in category';
COMMENT ON COLUMN public.contract_compliance_dashboard.total_value IS 'Total contract value in USD';
COMMENT ON COLUMN public.contract_compliance_dashboard.avg_duration_days IS 'Average contract duration in days';
COMMENT ON COLUMN public.contract_compliance_dashboard.non_compliant_clauses IS 'Count of non-compliant clauses';
COMMENT ON COLUMN public.contract_compliance_dashboard.expired_active_contracts IS 'Active contracts past expiration date';
COMMENT ON COLUMN public.contract_compliance_dashboard.compliance_rate IS 'Percentage of compliant clauses';

CREATE UNIQUE INDEX idx_contract_compliance_type_status ON public.contract_compliance_dashboard(contract_type, status);

-- =============================================================================
-- VIEW: database_performance_diagnostics
-- Description: Performance metrics for identifying missing indexes and vacuum needs
-- Business Case: Enables proactive database performance optimization
-- KPIs: Index usage percentage, dead tuple percentage, cache hit ratio
-- Feature Reference: PERF01-PERF20 (Performance Optimization)
-- =============================================================================
DROP VIEW IF EXISTS public.database_performance_diagnostics CASCADE;
CREATE VIEW public.database_performance_diagnostics AS
SELECT
    schemaname,
    tablename,
    seq_scan,
    seq_tup_read,
    idx_scan,
    idx_tup_fetch,
    n_tup_ins,
    n_tup_upd,
    n_tup_del,
    n_live_tup,
    n_dead_tup,
    ROUND(100.0 * idx_scan / NULLIF(seq_scan + idx_scan, 0), 2) as index_usage_percent,
    ROUND(100.0 * n_dead_tup / NULLIF(n_live_tup, 0), 2) as dead_tuple_percent,
    CASE
        WHEN ROUND(100.0 * idx_scan / NULLIF(seq_scan + idx_scan, 0), 2) < 70 THEN 'Missing Index Candidate'
        WHEN ROUND(100.0 * n_dead_tup / NULLIF(n_live_tup, 0), 2) > 10 THEN 'Vacuum Recommended'
        ELSE 'Healthy'
    END as recommendation
FROM pg_stat_user_tables
WHERE schemaname = 'public'
ORDER BY seq_scan DESC;
COMMENT ON VIEW public.database_performance_diagnostics IS 'Performance metrics for identifying missing indexes and vacuum needs';
COMMENT ON COLUMN public.database_performance_diagnostics.schemaname IS 'Schema name of the table';
COMMENT ON COLUMN public.database_performance_diagnostics.tablename IS 'Name of the table';
COMMENT ON COLUMN public.database_performance_diagnostics.seq_scan IS 'Number of sequential scans performed';
COMMENT ON COLUMN public.database_performance_diagnostics.idx_scan IS 'Number of index scans performed';
COMMENT ON COLUMN public.database_performance_diagnostics.index_usage_percent IS 'Percentage of queries using indexes';
COMMENT ON COLUMN public.database_performance_diagnostics.dead_tuple_percent IS 'Percentage of dead tuples requiring vacuum';
COMMENT ON COLUMN public.database_performance_diagnostics.recommendation IS 'Automated performance recommendation';

