-- =============================================================================
-- FUNCTIONS AND TRIGGERS
-- =============================================================================

-- Function: update_timestamp
-- Description: Automatically updates updated_at timestamp on row changes
-- Business Case: Enables audit trail of record modifications
-- Feature Reference: CORE41-CORE45
-- =============================================================================
CREATE OR REPLACE FUNCTION public.update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.update_timestamp() IS 'Trigger function to automatically update updated_at timestamp';

-- Apply update_timestamp triggers to all tables with audit columns
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT tablename FROM pg_tables
        WHERE schemaname = 'public'
        AND EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_name = tablename AND column_name = 'updated_at'
        )
    ) LOOP
        EXECUTE format('
            DROP TRIGGER IF EXISTS update_%I_timestamp ON public.%I;
            CREATE TRIGGER update_%I_timestamp
            BEFORE UPDATE ON public.%I
            FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();
        ', r.tablename, r.tablename, r.tablename, r.tablename);
    END LOOP;
END $$;

