COMMENT ON FUNCTION public.refresh_user_activity_dashboard() IS 'Refreshes the user activity dashboard materialized view';

-- =============================================================================
-- Function: create_monthly_partition
-- Description: Creates monthly partitions for time-series tables
-- Business Case: Enables efficient data management and retention
-- Feature Reference: PERF21-PERF30
-- =============================================================================
CREATE OR REPLACE FUNCTION public.create_monthly_partition()
RETURNS void AS $$
DECLARE
    start_date DATE;
    end_date DATE;
    partition_name TEXT;
    table_names TEXT[] := ARRAY['scim_sync_logs', 'health_check_results', 'audit_log'];
    table_name TEXT;
BEGIN
    FOREACH table_name IN ARRAY table_names LOOP
        start_date := DATE_TRUNC('month', NOW() + INTERVAL '1 month');
        end_date := DATE_TRUNC('month', NOW() + INTERVAL '2 months');
        partition_name := table_name || '_' || TO_CHAR(start_date, 'YYYY_MM');

        EXECUTE format('
            CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.%I
            FOR VALUES FROM (%L) TO (%L)
        ', partition_name, table_name, start_date, end_date);
    END LOOP;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.create_monthly_partition() IS 'Creates monthly partitions for time-series tables';

-- =============================================================================
-- Function: enforce_retention_policies
-- Description: Enforces data retention policies across all tables
-- Business Case: Ensures compliance with data retention regulations
-- Feature Reference: COMP31-COMP40
-- =============================================================================
CREATE OR REPLACE FUNCTION public.enforce_retention_policies()
RETURNS void AS $$
BEGIN
    -- Delete audit logs older than 7 years (for compliance)
    DELETE FROM public.audit_log WHERE changed_at < NOW() - INTERVAL '7 years';

    -- Delete health check results older than 90 days
    DELETE FROM public.health_check_results WHERE checked_at < NOW() - INTERVAL '90 days';

    -- Delete SCIM logs older than 1 year
    DELETE FROM public.scim_sync_logs WHERE synced_at < NOW() - INTERVAL '1 year';

    -- Archive completed workflow instances older than 2 years
    UPDATE public.workflow_instances
    SET status = 'ARCHIVED',
        updated_at = NOW()
    WHERE status = 'COMPLETED'
    AND completed_at < NOW() - INTERVAL '2 years';
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.enforce_retention_policies() IS 'Enforces data retention policies across all tables';

-- =============================================================================
-- Function: search_documents
-- Description: Full-text search function for documents
-- Business Case: Enables content-based document discovery
-- Feature Reference: DOC36-DOC40
-- =============================================================================
CREATE OR REPLACE FUNCTION public.search_documents(search_query TEXT, user_id UUID)
RETURNS TABLE(
    document_id UUID,
    title VARCHAR(500),
    relevance REAL,
    snippet TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        d.document_id,
        d.title,
        ts_rank(d.search_vector, plainto_tsquery('english', search_query)) as relevance,
        ts_headline('english', COALESCE(d.description, ''), plainto_tsquery('english', search_query)) as snippet
    FROM public.documents d
    WHERE d.search_vector @@ plainto_tsquery('english', search_query)
    AND (d.owner_id = user_id OR d.status = 'ACTIVE')
    AND d.deleted_at IS NULL
    ORDER BY relevance DESC
    LIMIT 100;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.search_documents(VARCHAR, UUID) IS 'Full-text search for documents with relevance ranking';

-- =============================================================================
-- Function: predict_contract_renewal
-- Description: Predicts contract renewal probability based on multiple factors
-- Business Case: Enables proactive contract renewal management
-- Feature Reference: ANA30-ANA35
-- =============================================================================
CREATE OR REPLACE FUNCTION public.predict_contract_renewal(contract_id UUID)
RETURNS NUMERIC AS $$
DECLARE
    renewal_probability NUMERIC;
BEGIN
    SELECT
        CASE
            WHEN EXTRACT(DAY FROM (expiration_date - NOW())) < 30 THEN 0.1
            WHEN EXTRACT(DAY FROM (expiration_date - NOW())) < 90 THEN 0.3
            ELSE 0.7
        END *
        CASE
            WHEN total_value > 100000 THEN 0.9
            WHEN total_value > 50000 THEN 0.7
            ELSE 0.5
        END *
        CASE
            WHEN status = 'ACTIVE' THEN 1.0
            ELSE 0.5
        END INTO renewal_probability
    FROM public.contracts
    WHERE contract_id = predict_contract_renewal.contract_id
    AND deleted_at IS NULL;

    RETURN LEAST(renewal_probability, 1.0);
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.predict_contract_renewal(UUID) IS 'Predicts contract renewal probability (0-1)';

-- =============================================================================
-- Function: workflow_sla_compliance_rate
-- Description: Calculates SLA compliance rate for workflow definitions
-- Business Case: Enables workflow performance monitoring and optimization
-- Feature Reference: BPM61-BPM65
-- =============================================================================
CREATE OR REPLACE FUNCTION public.workflow_sla_compliance_rate(definition_id UUID, days_back INTEGER DEFAULT 30)
RETURNS TABLE(
    total_instances BIGINT,
    sla_compliant BIGINT,
    compliance_rate NUMERIC
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*) as total_instances,
        COUNT(CASE WHEN completed_at <= started_at + (timeout_hours || ' hours')::INTERVAL THEN 1 END) as sla_compliant,
        ROUND(100.0 * COUNT(CASE WHEN completed_at <= started_at + (timeout_hours || ' hours')::INTERVAL THEN 1 END) / COUNT(*), 2) as compliance_rate
    FROM public.workflow_instances wi
    JOIN public.workflow_definitions wd ON wi.definition_id = wd.definition_id
    WHERE wi.definition_id = workflow_sla_compliance_rate.definition_id
    AND wi.completed_at > NOW() - (days_back || ' days')::INTERVAL
    AND wi.status = 'COMPLETED';
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.workflow_sla_compliance_rate(UUID, INTEGER) IS 'Calculates SLA compliance rate for workflow definitions';

-- =============================================================================
-- Function: validate_contract_dates
-- Description: Validates contract date overlaps for counterparties
-- Business Case: Prevents conflicting contract obligations
-- Feature Reference: CON35-CON40
-- =============================================================================
CREATE OR REPLACE FUNCTION public.validate_contract_dates()
RETURNS TRIGGER AS $$
BEGIN
    -- Ensure contract doesn't overlap with existing active contracts for same counterparty
    IF EXISTS (
        SELECT 1 FROM public.contracts c
        WHERE c.counterparty_id = NEW.counterparty_id
        AND c.status = 'ACTIVE'
        AND c.deleted_at IS NULL
        AND c.contract_id != COALESCE(NEW.contract_id, '00000000-0000-0000-0000-000000000000')
        AND daterange(c.effective_date, c.expiration_date, '[]') && daterange(NEW.effective_date, NEW.expiration_date, '[]')
    ) THEN
        RAISE EXCEPTION 'Contract overlaps with existing active contract for counterparty %', NEW.counterparty_id;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.validate_contract_dates() IS 'Prevents overlapping active contracts for the same counterparty';

DROP TRIGGER IF EXISTS validate_contract_dates_trigger ON public.contracts;
CREATE TRIGGER validate_contract_dates_trigger
    BEFORE INSERT OR UPDATE ON public.contracts
    FOR EACH ROW
    EXECUTE FUNCTION public.validate_contract_dates();

-- =============================================================================
-- Function: prevent_deleted_updates
-- Description: Prevents updates to soft-deleted records
-- Business Case: Ensures data integrity and audit compliance
-- Feature Reference: COMP25-COMP28
-- =============================================================================
CREATE OR REPLACE FUNCTION public.prevent_deleted_updates()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD.deleted_at IS NOT NULL THEN
        RAISE EXCEPTION 'Cannot update a soft-deleted record in table %.%', TG_TABLE_SCHEMA, TG_TABLE_NAME;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.prevent_deleted_updates() IS 'Prevents updates to soft-deleted records';

-- Apply prevent_deleted_updates trigger to all tables with deleted_at column
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT tablename FROM pg_tables
        WHERE schemaname = 'public'
        AND EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_name = tablename
            AND column_name = 'deleted_at'
        )
    ) LOOP
        EXECUTE format('
            DROP TRIGGER IF EXISTS prevent_deleted_updates_trigger ON public.%I;
            CREATE TRIGGER prevent_deleted_updates_trigger
            BEFORE UPDATE ON public.%I
            FOR EACH ROW
            EXECUTE FUNCTION public.prevent_deleted_updates();
        ', r.tablename, r.tablename);
    END LOOP;
END $$;

-- =============================================================================
-- Function: update_health_summary
-- Description: Updates daily system health summary
-- Business Case: Enables system health trending and reporting
-- Feature Reference: SRE25-SRE28
-- =============================================================================
CREATE OR REPLACE FUNCTION public.update_health_summary()
RETURNS void AS $$
BEGIN
    INSERT INTO public.system_health_summary (check_date, overall_status, total_checks, healthy_count, degraded_count, unhealthy_count, avg_response_time_ms, details)
    SELECT
        DATE(checked_at) as check_date,
        CASE
            WHEN COUNT(CASE WHEN status = 'UNHEALTHY' THEN 1 END) > COUNT(*) * 0.1 THEN 'UNHEALTHY'
            WHEN COUNT(CASE WHEN status = 'DEGRADED' THEN 1 END) > COUNT(*) * 0.2 THEN 'DEGRADED'
            ELSE 'HEALTHY'
        END as overall_status,
        COUNT(*) as total_checks,
        COUNT(CASE WHEN status = 'HEALTHY' THEN 1 END) as healthy_count,
        COUNT(CASE WHEN status = 'DEGRADED' THEN 1 END) as degraded_count,
        COUNT(CASE WHEN status = 'UNHEALTHY' THEN 1 END) as unhealthy_count,
        AVG(response_time_ms) as avg_response_time_ms,
        jsonb_build_object(
            'endpoints', jsonb_agg(DISTINCT endpoint),
            'worst_response_time', MAX(response_time_ms),
            'most_common_error', MODE() WITHIN GROUP (ORDER BY status_code)
        ) as details
    FROM public.health_check_results
    WHERE checked_at > NOW() - INTERVAL '1 day'
    GROUP BY DATE(checked_at)
    ON CONFLICT (check_date) DO UPDATE SET
        overall_status = EXCLUDED.overall_status,
        total_checks = EXCLUDED.total_checks,
        healthy_count = EXCLUDED.healthy_count,
        degraded_count = EXCLUDED.degraded_count,
        unhealthy_count = EXCLUDED.unhealthy_count,
        avg_response_time_ms = EXCLUDED.avg_response_time_ms,
        details = EXCLUDED.details,
        created_at = CURRENT_TIMESTAMP;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.update_health_summary() IS 'Updates daily system health summary from health check results';

-- =============================================================================
-- TABLE: system_health_summary
-- Description: Daily aggregated system health metrics
-- Business Case: Provides historical health trends for capacity planning
-- Feature Reference: SRE29-SRE32
-- =============================================================================
DROP TABLE IF EXISTS public.system_health_summary CASCADE;
CREATE TABLE public.system_health_summary (
    summary_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    check_date DATE NOT NULL,
    overall_status VARCHAR(20) CHECK (overall_status IN ('HEALTHY', 'DEGRADED', 'UNHEALTHY')),
    total_checks INTEGER,
    healthy_count INTEGER,
    degraded_count INTEGER,
    unhealthy_count INTEGER,
    avg_response_time_ms NUMERIC,
    details JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(check_date)
);
COMMENT ON TABLE public.system_health_summary IS 'Daily aggregated system health metrics';
COMMENT ON COLUMN public.system_health_summary.summary_id IS 'Unique summary identifier';
COMMENT ON COLUMN public.system_health_summary.check_date IS 'Date of health summary';
COMMENT ON COLUMN public.system_health_summary.overall_status IS 'Overall system health for the day';
COMMENT ON COLUMN public.system_health_summary.total_checks IS 'Total number of health checks performed';
COMMENT ON COLUMN public.system_health_summary.healthy_count IS 'Number of healthy endpoints';
COMMENT ON COLUMN public.system_health_summary.degraded_count IS 'Number of degraded endpoints';
COMMENT ON COLUMN public.system_health_summary.unhealthy_count IS 'Number of unhealthy endpoints';
COMMENT ON COLUMN public.system_health_summary.avg_response_time_ms IS 'Average response time across all endpoints';
COMMENT ON COLUMN public.system_health_summary.details IS 'Detailed health metrics as JSON';

-- =============================================================================
-- Function: generate_schema_documentation
-- Description: Generates complete schema documentation
-- Business Case: Enables automated documentation generation
-- Feature Reference: DEV15-DEV18
-- =============================================================================
CREATE OR REPLACE FUNCTION public.generate_schema_documentation()
RETURNS TABLE(
    table_name TEXT,
    column_name TEXT,
    data_type TEXT,
    description TEXT,
    constraints TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        c.table_name::TEXT,
        c.column_name::TEXT,
        c.data_type::TEXT,
        pgd.description::TEXT,
        (
            SELECT string_agg(contype::TEXT, ', ')
            FROM pg_constraint
            WHERE conrelid = (quote_ident(c.table_schema) || '.' || quote_ident(c.table_name))::regclass
            AND pg_get_constraintdef(oid) LIKE '%' || c.column_name || '%'
        ) as constraints
    FROM information_schema.columns c
    LEFT JOIN pg_description pgd ON pgd.objoid = (quote_ident(c.table_schema) || '.' || quote_ident(c.table_name))::regclass
        AND pgd.objsubid = c.ordinal_position
    WHERE c.table_schema = 'public'
    ORDER BY c.table_name, c.ordinal_position;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION public.generate_schema_documentation() IS 'Generates complete schema documentation with descriptions and constraints';

-- =============================================================================
-- ROW LEVEL SECURITY POLICIES
-- =============================================================================

-- Enable Row Level Security on all tables
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT tablename FROM pg_tables
        WHERE schemaname = 'public'
        AND tablename NOT IN ('schema_version', 'system_health_summary')
    ) LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', r.tablename);
    END LOOP;
END $$;

-- Create standardized RLS Policies
DO $$
DECLARE
    r RECORD;
    admin_policies TEXT[] := ARRAY['access_review_sessions', 'scim_sync_logs', 'webhook_retry_queues',
                                   'data_dictionary_entries', 'data_quality_checks', 'data_lineage_edges',
                                   'workflow_definitions', 'workflow_instances', 'task_assignments',
                                   'tax_jurisdictions', 'tax_calculations', 'journal_entries',
                                   'documents', 'document_versions', 'digital_signatures', 'contracts', 'contract_clauses',
                                   'health_check_results', 'alert_policies', 'escalation_policies', 'on_call_schedules',
                                   'api_gateway_routes', 'integration_mappings', 'tenant_configurations'];
BEGIN
    FOREACH r IN ARRAY admin_policies LOOP
        EXECUTE format('
            DROP POLICY IF EXISTS %I_admin_policy ON public.%I;
            CREATE POLICY %I_admin_policy ON public.%I
            USING (EXISTS (
                SELECT 1 FROM public.user_roles ur
                JOIN public.roles r ON ur.role_id = r.role_id
                WHERE ur.user_id = public.current_user_id()
                AND r.name IN (''admin'', ''platform_admin'', ''security_admin'', ''data_steward'')
            ));
        ', r, r, r, r);
    END LOOP;
END $$;

-- =============================================================================
-- SCHEMA COMPLETION
-- =============================================================================

COMMENT ON SCHEMA public IS 'Professional Network Schema v3.0 - Enterprise Enhanced Edition with comprehensive documentation, audit trails, search, retention policies, analytics, and full compliance features';

-- Final validation
DO $$
DECLARE
    object_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO object_count
    FROM pg_tables
    WHERE schemaname = 'public';

    RAISE NOTICE 'Schema deployment complete. Total tables created: %', object_count;
    RAISE NOTICE 'Additional objects: domains (4), materialized views (2), views (1), functions (11)';
END $$;

--------------------------------------------------------------------------------
-- ENUM: api_rate_limit_action
-- Description: Defines actions taken when API rate limits are exceeded
-- Business Case: Enables different rate limit handling strategies based on severity
-- Feature Reference: RATE-05 (Rate Limit Response Strategies)
--------------------------------------------------------------------------------
CREATE TYPE api_rate_limit_action AS ENUM (
    'BLOCK',           -- Completely block the request
    'THROTTLE',        -- Slow down request processing
    'QUEUE',          -- Queue for later processing
    'DEGRADE',        -- Return degraded response
    'CIRCUIT_BREAKER' -- Open circuit breaker pattern
);

--------------------------------------------------------------------------------
-- ENUM: feature_flag_status
-- Description: Status of feature flags throughout their lifecycle
-- Business Case: Manages feature rollout states from development to retirement
-- Feature Reference: FF-08 (Feature Flag Lifecycle Management)
--------------------------------------------------------------------------------
CREATE TYPE feature_flag_status AS ENUM (
    'DEVELOPMENT',     -- In active development
    'TESTING',        -- Quality assurance testing
    'STAGING',        -- Pre-production validation
    'PRODUCTION',     -- Live in production
    'DEPRECATED',     -- Scheduled for removal
    'ARCHIVED'        -- Removed from codebase
);

--------------------------------------------------------------------------------
-- ENUM: outbox_status
-- Description: Status of messages in the outbox pattern
-- Business Case: Tracks message delivery lifecycle for reliable event publishing
-- Feature Reference: OUT-10 (Outbox Message State Management)
--------------------------------------------------------------------------------
CREATE TYPE outbox_status AS ENUM (
    'PENDING',        -- Ready for publishing
    'PUBLISHING',     -- Being published
    'PUBLISHED',      -- Successfully delivered
    'FAILED',         -- Delivery failed
    'RETRY',          -- Scheduled for retry
    'EXPIRED',        -- Max retries exceeded
    'SKIPPED'         -- Intentionally skipped
);

--------------------------------------------------------------------------------
-- ENUM: security_event_severity
-- Description: Severity levels for security events
-- Business Case: Enables prioritized security incident response
-- Feature Reference: SEC-15 (Security Event Classification)
--------------------------------------------------------------------------------
CREATE TYPE security_event_severity AS ENUM (
    'LOW',            -- Informational events
    'MEDIUM',         -- Potential security concerns
    'HIGH',           -- Suspicious activities requiring attention
    'CRITICAL',       -- Confirmed security incidents
    'EMERGENCY'       -- Active breach requiring immediate action
);

--------------------------------------------------------------------------------
-- ENUM: dlq_status
-- Description: Status codes for dead letter queue entries
-- Business Case: Manages failed job resolution lifecycle
-- Feature Reference: DLQ-07 (Dead Letter Resolution Tracking)
--------------------------------------------------------------------------------
CREATE TYPE dlq_status AS ENUM (
    'NEW',            -- Recently failed, pending review
    'INVESTIGATING',  -- Under analysis
    'RETRY_SCHEDULED',-- Scheduled for retry
    'RESOLVED',       -- Successfully fixed
    'SKIPPED',        -- Intentionally ignored
    'ESCALATED'       -- Escalated to engineering
);

--------------------------------------------------------------------------------
-- Table: API_RATE_LIMITS
-- Serial No: TBL-001
-- Description: Comprehensive API rate limiting system with multi-dimensional tracking
--
-- Business Case:
-- The api_rate_limits table serves as the foundation for protecting enterprise API infrastructure
-- from abuse, ensuring fair resource allocation across tenants, and maintaining service quality
-- for all users. In a professional network with thousands of API consumers (internal services,
-- partner integrations, third-party developers), unconstrained API usage can lead to
-- infrastructure overload, degraded performance, and denial-of-service scenarios.
--
-- This table enables granular rate limiting policies based on multiple dimensions: user identity,
-- API client/application, endpoint specificity, organizational tenant, and geographic region.
-- By tracking request volumes, timestamps, and consumption patterns, the system can dynamically
-- enforce limits (e.g., 1000 requests/minute for standard users, 10000/minute for premium clients).
--
-- The implementation supports tiered pricing models where higher API quotas become premium features.
-- It also enables burst handling (allowing short-term spikes with longer-term averages),
-- rate limit notifications via headers (X-RateLimit-*), and automatic throttling when approaching limits.
--
-- For compliance and auditing, the table records when limits were breached, enabling retrospective
-- analysis of API usage patterns and identifying potential abuse vectors. Integration with
-- monitoring systems provides real-time alerts when unusual traffic patterns emerge.
--
-- Feature References:
-- RATE-01: Multi-dimensional rate limiting (user, client, endpoint)
-- RATE-02: Tiered quota management
-- RATE-03: Burst handling and smoothing
-- RATE-04: Rate limit headers support
-- RATE-06: Real-time monitoring and alerts
-- RATE-07: Historical usage analytics
-- RATE-08: Distributed rate limiting across regions
--
-- Key Performance Indicators (KPIs):
-- 1. API Error Rate (429) - Percentage of requests rejected due to rate limiting (<1%)
-- 2. Peak Throughput - Maximum requests/second handled without degradation
-- 3. Rate Limit Hit Frequency - Number of times users hit limits per day
-- 4. Average Time to Reset - Mean duration until rate limit windows reset
-- 5. Concurrent Usage Pattern - Peak vs average request distribution across time
-- 6. Quota Utilization % - Percentage of allocated quotas actually used
-- 7. Burst Tolerance Score - Success rate during traffic spikes
-- 8. Abuse Prevention Rate - Number of potential abuse attempts blocked
-------------------------------------------------------------------------------
CREATE TABLE api_rate_limits (
    -- Primary identifier
    limit_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Multi-dimensional rate limiting keys
    user_id UUID,                                        -- Specific user (NULL for global)
    client_id VARCHAR(255) NOT NULL,                     -- API client identifier
    endpoint_pattern VARCHAR(500) NOT NULL,              -- Endpoint pattern (/api/v1/users/*)
    tenant_id VARCHAR(100),                              -- Multi-tenant isolation
    region VARCHAR(50),                                  -- Geographic region

    -- Rate limit configuration
    limit_type VARCHAR(50) NOT NULL CHECK (limit_type IN ('REQUEST_COUNT', 'BANDWIDTH_MB', 'CONCURRENT', 'BURST')),
    window_duration_seconds INTEGER NOT NULL CHECK (window_duration_seconds >= 1 AND window_duration_seconds <= 86400),
    max_requests INTEGER NOT NULL CHECK (max_requests > 0),
    burst_capacity INTEGER CHECK (burst_capacity >= max_requests),

    -- Current tracking
    current_count INTEGER DEFAULT 0 NOT NULL,
    window_start_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    window_end_time TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (window_start_time + (window_duration_seconds * INTERVAL '1 second')) STORED,

    -- Throttling behavior
    action_on_limit api_rate_limit_action NOT NULL DEFAULT 'BLOCK',
    throttle_delay_ms INTEGER DEFAULT 0 CHECK (throttle_delay_ms >= 0),
    queue_capacity INTEGER DEFAULT 0,

    -- Usage analytics
    last_request_time TIMESTAMP WITH TIME ZONE,
    total_requests_this_window INTEGER DEFAULT 0,
    blocked_requests_this_window INTEGER DEFAULT 0,

    -- Rate limit headers support
    include_headers BOOLEAN DEFAULT true,
    headers_retry_after INTEGER,                         -- Seconds to wait before retry

    -- Dynamic adjustment
    is_dynamic BOOLEAN DEFAULT false,
    adjustment_factor NUMERIC(3,2) DEFAULT 1.00 CHECK (adjustment_factor BETWEEN 0.1 AND 10.0),
    last_adjustment_time TIMESTAMP WITH TIME ZONE,

    -- Status and lifecycle
    is_active BOOLEAN DEFAULT true NOT NULL,
    priority_level INTEGER DEFAULT 5 CHECK (priority_level BETWEEN 1 AND 10),

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints for data integrity
    CONSTRAINT rate_limit_unique_composite UNIQUE (user_id, client_id, endpoint_pattern, tenant_id, region, limit_type, window_duration_seconds),
    CONSTRAINT rate_limit_window_check CHECK (window_end_time > window_start_time),
    CONSTRAINT rate_limit_burst_check CHECK (burst_capacity IS NULL OR burst_capacity >= max_requests)
);

-- Indexes for optimal query performance
CREATE INDEX idx_rate_limits_lookup ON api_rate_limits (client_id, endpoint_pattern, user_id, tenant_id);
CREATE INDEX idx_rate_limits_window ON api_rate_limits (window_start_time, window_end_time);
CREATE INDEX idx_rate_limits_current ON api_rate_limits (current_count, max_requests) WHERE is_active = true;
CREATE INDEX idx_rate_limits_tenant ON api_rate_limits (tenant_id) WHERE tenant_id IS NOT NULL;
CREATE INDEX idx_rate_limits_region ON api_rate_limits (region) WHERE region IS NOT NULL;
CREATE INDEX idx_rate_limits_priority ON api_rate_limits (priority_level, is_active);

-- Partial index for active high-priority limits
CREATE INDEX CONCURRENTLY idx_rate_limits_active_priority ON api_rate_limits (priority_level) WHERE is_active = true AND priority_level <= 3;

-- Composite index for time-series analysis
CREATE INDEX idx_rate_limits_analytics ON api_rate_limits (client_id, window_start_time, current_count, blocked_requests_this_window);

-- Comments for documentation
COMMENT ON TABLE api_rate_limits IS 'Comprehensive API rate limiting system with multi-dimensional tracking and dynamic adjustment';
COMMENT ON COLUMN api_rate_limits.user_id IS 'NULL indicates global limit applicable to all users';
COMMENT ON COLUMN api_rate_limits.burst_capacity IS 'Maximum requests allowed during burst periods, must be >= max_requests';
COMMENT ON COLUMN api_rate_limits.adjustment_factor IS 'Dynamic adjustment factor based on system load (0.1 = reduce to 10%, 10.0 = increase to 1000%)';

-- Row Level Security for multi-tenant isolation
ALTER TABLE api_rate_limits ENABLE ROW LEVEL SECURITY;

CREATE POLICY rate_limits_tenant_policy ON api_rate_limits
    USING (tenant_id = current_setting('app.current_tenant_id', true)::VARCHAR OR
           current_setting('app.is_super_user', true)::BOOLEAN = true);

-------------------------------------------------------------------------------
-- Table: FEATURE_FLAGS
-- Serial No: TBL-002
-- Description: Enterprise feature flag management system with advanced rollout controls
--
-- Business Case:
-- Feature flags represent a paradigm shift in software delivery, enabling continuous
-- deployment, A/B testing, and risk-free feature rollbacks. In a professional network
-- serving millions of users across different tiers (free, premium, enterprise),
-- feature flags allow granular control over which users see which features, when,
-- and under what conditions.
--
-- This table enables canary releases where new features roll out to 1% of users,
-- then 10%, then 50%, before full deployment—automatically rolling back if error
-- rates spike. It supports kill switches for emergency feature disablement without
-- code deployment, reducing MTTR (Mean Time To Resolution) from hours to seconds.
--
-- For compliance and regulations (GDPR, CCPA), feature flags can region-lock features
-- that aren't compliant in certain jurisdictions. A/B testing infrastructure uses these
-- flags to split traffic between control and experiment groups, measuring business
-- metrics before full rollout.
--
-- The system maintains audit trails of who changed which flag, when, and why—critical
-- for change management and incident post-mortems. Integration with monitoring systems
-- automatically triggers rollbacks when error budgets are exceeded.
--
-- Feature References:
-- FF-01: Gradual feature rollout (percentage-based)
-- FF-02: User segment targeting (tier, region, role)
-- FF-03: A/B testing infrastructure
-- FF-04: Emergency kill switches
-- FF-05: Automated rollback on errors
-- FF-06: Audit trail for compliance
-- FF-07: Dependency management between flags
-- FF-09: Time-based activation schedules
--
-- Key Performance Indicators (KPIs):
-- 1. Feature Adoption Rate - % of target users using new feature within 7 days
-- 2. Rollback Frequency - Number of automatic rollbacks per 100 deployments
-- 3. Flag Cleanup Rate - % of flags removed within 30 days of deprecation
-- 4. A/B Test Confidence - Statistical significance achieved in experiments
-- 5. Deployment Risk Score - Estimated risk based on flag configuration
-- 6. Time to Disable - Seconds from kill switch activation to feature blocked
-- 7. Flag Evaluation Latency - P99 latency of flag evaluation (target <5ms)
-- 8. User Impact During Rollback - % of users unaffected by problematic releases
-------------------------------------------------------------------------------
CREATE TABLE feature_flags (
    -- Primary identifier
    flag_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Flag identification
    flag_key VARCHAR(255) NOT NULL UNIQUE,
    flag_name VARCHAR(500) NOT NULL,
    description TEXT,
    owner_team VARCHAR(100) NOT NULL,
    owner_email VARCHAR(255),

    -- Flag status and lifecycle
    status feature_flag_status NOT NULL DEFAULT 'DEVELOPMENT',
    is_enabled BOOLEAN DEFAULT false NOT NULL,

    -- Rollout configuration
    rollout_percentage INTEGER DEFAULT 0 CHECK (rollout_percentage BETWEEN 0 AND 100),
    rollout_strategy VARCHAR(50) DEFAULT 'RANDOM' CHECK (rollout_strategy IN ('RANDOM', 'USER_ID_HASH', 'EMAIL_HASH', 'SEQUENTIAL')),

    -- Targeting rules (JSON for complex conditions)
    targeting_rules JSONB DEFAULT '{}'::JSONB,
    -- Example: {"tiers": ["premium", "enterprise"], "regions": ["US", "EU"], "min_user_tenure_days": 30}

    -- A/B testing support
    experiment_id VARCHAR(255),
    variant_name VARCHAR(100),
    control_percentage INTEGER CHECK (control_percentage BETWEEN 0 AND 100),

    -- Time-based activation
    activation_time TIMESTAMP WITH TIME ZONE,
    deactivation_time TIMESTAMP WITH TIME ZONE,
    timezone VARCHAR(100) DEFAULT 'UTC',

    -- Dependency management
    depends_on_flag_id UUID REFERENCES feature_flags(flag_id) ON DELETE SET NULL,
    dependency_operator VARCHAR(20) DEFAULT 'AND' CHECK (dependency_operator IN ('AND', 'OR')),

    -- Automated behavior
    auto_rollback_enabled BOOLEAN DEFAULT false,
    error_rate_threshold NUMERIC(5,2) CHECK (error_rate_threshold BETWEEN 0 AND 100),
    latency_threshold_ms INTEGER,
    rollback_duration_minutes INTEGER DEFAULT 5,

    -- Kill switch configuration
    kill_switch_enabled BOOLEAN DEFAULT false,
    kill_switch_activated_at TIMESTAMP WITH TIME ZONE,
    kill_switch_reason TEXT,

    -- Analytics and metrics
    evaluation_count BIGINT DEFAULT 0,
    true_evaluation_count BIGINT DEFAULT 0,
    last_evaluated_at TIMESTAMP WITH TIME ZONE,

    -- Cache configuration
    cache_ttl_seconds INTEGER DEFAULT 60 CHECK (cache_ttl_seconds >= 0),

    -- Version control
    version INTEGER DEFAULT 1 NOT NULL,
    change_notes TEXT,

    -- Audit trail
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT feature_flag_percentage_check CHECK (rollout_percentage IS NULL OR rollout_percentage <= 100),
    CONSTRAINT feature_flag_activation_check CHECK (activation_time IS NULL OR deactivation_time IS NULL OR activation_time < deactivation_time),
    CONSTRAINT feature_flag_experiment_check CHECK (experiment_id IS NULL OR (control_percentage IS NOT NULL AND variant_name IS NOT NULL))
);

-- Indexes for performance
CREATE INDEX idx_feature_flags_lookup ON feature_flags (flag_key, is_enabled, status);
CREATE INDEX idx_feature_flags_owner ON feature_flags (owner_team);
CREATE INDEX idx_feature_flags_rollout ON feature_flags (rollout_percentage, rollout_strategy) WHERE is_enabled = true;
CREATE INDEX idx_feature_flags_time ON feature_flags (activation_time, deactivation_time);
CREATE INDEX idx_feature_flags_dependency ON feature_flags (depends_on_flag_id);
CREATE INDEX idx_feature_flags_kill ON feature_flags (kill_switch_enabled, kill_switch_activated_at);
CREATE INDEX idx_feature_flags_experiment ON feature_flags (experiment_id, variant_name);

-- GIN index for JSON targeting rules
CREATE INDEX idx_feature_flags_targeting ON feature_flags USING gin(targeting_rules);

-- Partial index for active production flags
CREATE INDEX CONCURRENTLY idx_feature_flags_production ON feature_flags (flag_key) WHERE status = 'PRODUCTION' AND is_enabled = true;

-- Comments for documentation
COMMENT ON TABLE feature_flags IS 'Enterprise feature flag management system with advanced rollout controls and A/B testing';
COMMENT ON COLUMN feature_flags.rollout_percentage IS 'Percentage of eligible users who see the feature (0-100)';
COMMENT ON COLUMN feature_flags.targeting_rules IS 'JSONB containing complex targeting conditions like user tiers, regions, and custom attributes';
COMMENT ON COLUMN feature_flags.kill_switch_enabled IS 'When true, allows emergency disable without code deployment';

-- Row Level Security
ALTER TABLE feature_flags ENABLE ROW LEVEL SECURITY;

CREATE POLICY feature_flags_admin_policy ON feature_flags
    USING (current_setting('app.is_admin', true)::BOOLEAN = true);

-------------------------------------------------------------------------------
-- Table: EVENT_OUTBOX
-- Serial No: TBL-003
-- Description: Reliable event publishing pattern ensuring exactly-once delivery semantics
--
-- Business Case:
-- In microservices architectures, maintaining data consistency across service
-- boundaries is one of the toughest challenges. The outbox pattern solves the
-- dual-write problem: when a transaction writes to both local database and message
-- queue, if one fails, data becomes inconsistent. This table implements the
-- transactional outbox pattern where events are written atomically with business
-- transactions, then published reliably to message brokers.
--
-- For a professional network, this ensures that when a user updates their profile,
-- all downstream services (search indexing, notification service, analytics,
-- recommendation engine) receive consistent updates. Without this, users might
-- update their job title but search still shows old title, or notifications fail
-- to trigger.
--
-- The table manages retry logic with exponential backoff, dead letter handling,
-- and exactly-once delivery guarantees. It maintains ordering constraints when
-- needed (e.g., "user created" must come before "user updated") and supports
-- partition keys for parallel processing.
--
-- Integration with change data capture (CDC) tools provides real-time streaming
-- without polling overhead. The system automatically purges successfully published
-- events after retention period, managing storage growth.
--
-- Feature References:
-- OUT-01: Transactional outbox pattern
-- OUT-02: Exactly-once delivery semantics
-- OUT-03: Exponential backoff retry logic
-- OUT-04: Event ordering preservation
-- OUT-05: Partition-based parallel processing
-- OUT-06: Dead letter queue integration
-- OUT-07: Idempotent event processing
-- OUT-08: CDC tool integration
-- OUT-09: Automatic retention and purging
--
-- Key Performance Indicators (KPIs):
-- 1. Event Publishing Latency - Time from commit to broker acknowledgment (p99)
-- 2. Delivery Success Rate - % of events successfully delivered (target >99.9%)
-- 3. Retry Efficiency - % of events delivered on first retry attempt
-- 4. Outbox Table Size - Growth rate (should be <10GB/day for typical load)
-- 5. Dead Letter Rate - % of events moving to DLQ (target <0.1%)
-- 6. Event Processing Throughput - Events/second processed by publisher
-- 7. Lag Time - Max delay between creation and publishing
-- 8. Duplicate Detection Rate - % of duplicate events correctly identified
-------------------------------------------------------------------------------
CREATE TABLE event_outbox (
    -- Primary identifier
    event_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Event identification
    event_type VARCHAR(255) NOT NULL,
    event_version VARCHAR(20) NOT NULL,                   -- Semantic version (1.0.0)
    aggregate_id VARCHAR(255) NOT NULL,                   -- Business entity ID (user_123)
    aggregate_type VARCHAR(100) NOT NULL,                 -- Entity type (user, post, comment)

    -- Event payload
    payload JSONB NOT NULL,
    metadata JSONB DEFAULT '{}'::JSONB,

    -- Delivery configuration
    destination_topic VARCHAR(255) NOT NULL,
    partition_key VARCHAR(255),                            -- For ordered processing
    message_key VARCHAR(255),                             -- Kafka message key

    -- Status tracking
    status outbox_status NOT NULL DEFAULT 'PENDING',
    retry_count INTEGER DEFAULT 0 NOT NULL,
    max_retries INTEGER DEFAULT 3 NOT NULL,

    -- Timing information
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    next_retry_time TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    published_at TIMESTAMP WITH TIME ZONE,
    last_error_time TIMESTAMP WITH TIME ZONE,

    -- Error handling
    last_error_message TEXT,
    error_details JSONB,

    -- Ordering and deduplication
    sequence_number BIGSERIAL,
    correlation_id VARCHAR(255),                          -- Trace across services
    causation_id VARCHAR(255),                            -- Parent event ID

    -- Idempotency
    idempotency_key VARCHAR(255) UNIQUE,                  -- Prevent duplicate processing

    -- Retry strategy
    backoff_strategy VARCHAR(50) DEFAULT 'EXPONENTIAL' CHECK (backoff_strategy IN ('FIXED', 'LINEAR', 'EXPONENTIAL', 'CUSTOM')),
    backoff_base_ms INTEGER DEFAULT 1000 CHECK (backoff_base_ms >= 100),
    backoff_multiplier NUMERIC(3,1) DEFAULT 2.0,

    -- Processing constraints
    processing_timeout_ms INTEGER DEFAULT 30000,          -- 30 seconds default
    delivery_deadline TIMESTAMP WITH TIME ZONE,

    -- Retention
    retention_days INTEGER DEFAULT 7,

    -- Constraints
    CONSTRAINT event_outbox_retry_check CHECK (retry_count <= max_retries),
    CONSTRAINT event_outbox_timing_check CHECK (next_retry_time >= created_at),
    CONSTRAINT event_outbox_payload_not_empty CHECK (payload IS NOT NULL AND jsonb_typeof(payload) = 'object')
);

-- Indexes for publisher polling
CREATE INDEX idx_outbox_pending_events ON event_outbox (status, next_retry_time) WHERE status IN ('PENDING', 'RETRY');
CREATE INDEX idx_outbox_published_cleanup ON event_outbox (published_at, retention_days) WHERE status = 'PUBLISHED';
CREATE INDEX idx_outbox_aggregate ON event_outbox (aggregate_type, aggregate_id, created_at);
CREATE INDEX idx_outbox_correlation ON event_outbox (correlation_id) WHERE correlation_id IS NOT NULL;
CREATE INDEX idx_outbox_delivery_deadline ON event_outbox (delivery_deadline) WHERE delivery_deadline IS NOT NULL AND status != 'PUBLISHED';

-- Composite index for ordered processing
CREATE INDEX idx_outbox_ordered_processing ON event_outbox (partition_key, sequence_number) WHERE partition_key IS NOT NULL;

-- Partial index for failed events needing attention
CREATE INDEX CONCURRENTLY idx_outbox_failed_events ON event_outbox (retry_count, last_error_time) WHERE status = 'FAILED' AND retry_count >= max_retries;

-- Comments for documentation
COMMENT ON TABLE event_outbox IS 'Transactional outbox pattern for reliable cross-service event publishing';
COMMENT ON COLUMN event_outbox.payload IS 'Event data as JSONB (e.g., {"user_id": "123", "old_title": "Engineer", "new_title": "Senior Engineer"})';
COMMENT ON COLUMN event_outbox.idempotency_key IS 'Unique key to prevent duplicate event processing';
COMMENT ON COLUMN event_outbox.backoff_strategy IS 'Controls retry timing: EXPONENTIAL provides 1s, 2s, 4s intervals';

-- Row Level Security (service accounts only, not user-level)
ALTER TABLE event_outbox ENABLE ROW LEVEL SECURITY;

CREATE POLICY outbox_service_access_policy ON event_outbox
    USING (current_setting('app.service_name', true) IS NOT NULL);

-- Trigger to automatically set delivery_deadline
CREATE OR REPLACE FUNCTION set_outbox_delivery_deadline()
RETURNS TRIGGER AS $$
BEGIN
    NEW.delivery_deadline = NEW.created_at + (NEW.processing_timeout_ms * INTERVAL '1 millisecond');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_outbox_delivery_deadline
    BEFORE INSERT ON event_outbox
    FOR EACH ROW
    EXECUTE FUNCTION set_outbox_delivery_deadline();

-------------------------------------------------------------------------------
-- Table: SECURITY_EVENTS
-- Serial No: TBL-004
-- Description: Comprehensive security event logging for SOC2 and threat detection
--
-- Business Case:
-- Security event logging is non-negotiable for SOC2, GDPR, and other compliance
-- frameworks. This table captures every authentication attempt, authorization
-- decision, privilege change, and suspicious activity across the professional
-- network. It enables real-time threat detection, forensic analysis during
-- incidents, and compliance reporting for audits.
--
-- The table supports zero-trust security models by tracking every access request,
-- regardless of success or failure. For failed MFA attempts, it records which
-- factor failed (something you know, have, are). For privilege escalations, it
-- captures before/after states for rollback capabilities.
--
-- Integration with SIEM (Security Information and Event Management) systems
-- provides real-time alerting when threat signatures match (e.g., 10 failed
-- logins followed by successful login from new location). Machine learning
-- models can query this table to establish baseline behavior and detect anomalies
-- like credential stuffing attacks or impossible travel (login from NY then
-- Tokyo within 1 hour).
--
-- The table implements data retention policies aligned with compliance requirements
-- (e.g., 1 year for standard logs, 7 years for privileged access events) and
-- supports cryptographic hashing of sensitive fields (like IP addresses) for
-- privacy while maintaining security analytics capabilities.
--
-- Feature References:
-- SEC-01: Authentication event tracking (success/failure/MFA)
-- SEC-02: Authorization audit trail
-- SEC-03: Privilege escalation monitoring
-- SEC-04: SIEM integration
-- SEC-05: Threat detection patterns
-- SEC-06: Behavioral analytics support
-- SEC-07: Compliance retention policies
-- SEC-08: Privacy-preserving logging
-- SEC-09: Real-time alerting
-- SEC-10: Forensic investigation support
--
-- Key Performance Indicators (KPIs):
-- 1. Authentication Success Rate - % of successful vs failed attempts
-- 2. Mean Time to Detect (MTTD) - Time from event to alert (target <5 minutes)
-- 3. Suspicious Activity Rate - % of events flagged as suspicious
-- 4. Compliance Coverage - % of required events captured (target 100%)
-- 5. Log Processing Lag - Time from event to database write (target <100ms)
-- 6. Security Incident Correlation Rate - % of events linked to incidents
-- 7. False Positive Rate - % of alerts incorrectly flagged as suspicious
-- 8. Audit Query Response Time - P95 query performance for compliance reports
-------------------------------------------------------------------------------
CREATE TABLE security_events (
    -- Primary identifier
    event_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Event classification
    event_category VARCHAR(100) NOT NULL CHECK (event_category IN (
        'AUTHENTICATION', 'AUTHORIZATION', 'ACCOUNT_MANAGEMENT', 'DATA_ACCESS',
        'CONFIGURATION_CHANGE', 'PRIVILEGE_ESCALATION', 'API_ACCESS', 'DATA_EXPORT',
        'SYSTEM_ADMIN', 'COMPLIANCE_VIOLATION', 'THREAT_DETECTED'
    )),
    event_action VARCHAR(100) NOT NULL,
    severity security_event_severity NOT NULL,

    -- Who
    user_id UUID,                                        -- NULL for system events
    username VARCHAR(255),
    email_hash VARCHAR(255),                             -- Privacy-preserving hash
    service_account VARCHAR(100),

    -- Where
    source_ip INET,
    source_ip_hash VARCHAR(255),                         -- For GDPR right-to-be-forgotten
    user_agent TEXT,
    device_id VARCHAR(255),
    session_id UUID,

    -- What
    resource_type VARCHAR(100),
    resource_id VARCHAR(255),
    http_method VARCHAR(10),
    endpoint VARCHAR(500),
    query_parameters JSONB,
    request_body_hash VARCHAR(255),                      -- Hash, not raw body

    -- Outcome
    success BOOLEAN NOT NULL,
    failure_reason VARCHAR(500),
    failure_detail JSONB,

    -- Context
    correlation_id VARCHAR(255),
    parent_event_id UUID REFERENCES security_events(event_id),

    -- Authentication details (when applicable)
    auth_method VARCHAR(50) CHECK (auth_method IN ('PASSWORD', 'MFA_TOTP', 'MFA_SMS', 'MFA_EMAIL', 'OAUTH', 'SAML', 'SSO', 'BIOMETRIC')),
    mfa_used BOOLEAN DEFAULT false,
    mfa_success BOOLEAN,
    auth_factors_used TEXT[],
    auth_time_taken_ms INTEGER,

    -- Authorization details
    required_permission VARCHAR(255),
    granted_permissions TEXT[],
    denied_permissions TEXT[],

    -- Risk scoring
    risk_score INTEGER CHECK (risk_score BETWEEN 0 AND 100),
    risk_factors JSONB,
    anomaly_detected BOOLEAN DEFAULT false,
    anomaly_type VARCHAR(255),

    -- Geolocation
    geolocation_country VARCHAR(100),
    geolocation_city VARCHAR(100),
    geolocation_latitude DECIMAL(10, 6),
    geolocation_longitude DECIMAL(10, 6),

    -- Compliance tagging
    compliance_frameworks TEXT[] DEFAULT ARRAY[]::TEXT[],  -- ['SOC2', 'GDPR', 'PCI']
    retention_period_days INTEGER NOT NULL DEFAULT 365,

    -- Forensic data
    forensic_tags TEXT[],
    incident_id VARCHAR(255),                             -- Link to incident management
    evidence_hash VARCHAR(255),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    logged_by_ip INET,
    log_source VARCHAR(255) NOT NULL,                     -- Service that generated event

    -- Constraints
    CONSTRAINT security_event_retention_check CHECK (retention_period_days IN (30, 90, 365, 730, 2555)),
    CONSTRAINT security_event_auth_check CHECK (auth_method IS NULL OR mfa_success IS NOT NULL OR mfa_used = false)
);

-- Indexes for security analytics
CREATE INDEX idx_security_events_time ON security_events (created_at DESC);
CREATE INDEX idx_security_events_user ON security_events (user_id, created_at DESC);
CREATE INDEX idx_security_events_severity ON security_events (severity, created_at DESC) WHERE success = false;
CREATE INDEX idx_security_events_source_ip ON security_events (source_ip, created_at DESC);
CREATE INDEX idx_security_events_correlation ON security_events (correlation_id);
CREATE INDEX idx_security_events_incident ON security_events (incident_id) WHERE incident_id IS NOT NULL;
CREATE INDEX idx_security_events_anomaly ON security_events (anomaly_detected, created_at DESC) WHERE anomaly_detected = true;

-- Composite indexes for common threat detection queries
CREATE INDEX idx_security_events_failed_auth ON security_events (user_id, source_ip, created_at DESC) WHERE event_category = 'AUTHENTICATION' AND success = false;
CREATE INDEX idx_security_events_privilege_escalation ON security_events (user_id, resource_id, created_at DESC) WHERE event_category = 'PRIVILEGE_ESCALATION';

-- Partial index for high-risk events in last 24 hours
CREATE INDEX CONCURRENTLY idx_security_events_high_risk_recent ON security_events (created_at, risk_score) WHERE severity IN ('HIGH', 'CRITICAL', 'EMERGENCY') AND created_at > NOW() - INTERVAL '24 hours';

-- GIN indexes for JSON columns
CREATE INDEX idx_security_events_risk_factors ON security_events USING gin(risk_factors);
CREATE INDEX idx_security_events_failure_detail ON security_events USING gin(failure_detail);

-- Comments for documentation
COMMENT ON TABLE security_events IS 'Comprehensive security event logging for threat detection and compliance';
COMMENT ON COLUMN security_events.email_hash IS 'SHA-256 hash of email for privacy while maintaining query capability';
COMMENT ON COLUMN security_events.retention_period_days IS 'Compliance-driven retention: 30d for routine, 365d+ for security events';
COMMENT ON COLUMN security_events.anomaly_type IS 'Type of detected anomaly: impossible_travel, credential_stuffing, etc.';

-- Row Level Security - extremely restrictive (audit/admin only)
ALTER TABLE security_events ENABLE ROW LEVEL SECURITY;

CREATE POLICY security_events_audit_only_policy ON security_events
    USING (current_setting('app.security_auditor', true)::BOOLEAN = true);

-------------------------------------------------------------------------------
-- Table: DEAD_LETTER_QUEUE
-- Serial No: TBL-005
-- Description: Resilient failure handling for background job processing
--
-- Business Case:
-- In distributed systems, failures are inevitable—networks partition, services
-- crash, databases become unavailable. The dead letter queue (DLQ) is a
-- fundamental resilience pattern that prevents data loss and enables operational
-- visibility when things go wrong.
--
-- This table captures every failed background job (email sending, report generation,
-- data synchronization, notification delivery) with full context about the failure.
-- Instead of losing the job or retrying indefinitely, the system moves it to DLQ
-- for human or automated intervention.
--
-- For a professional network processing millions of daily background tasks, this
-- becomes critical when a vendor API is temporarily down. Rather than dropping
-- invoice sync jobs, they route to DLQ. When the API recovers, operations can
-- replay failed jobs without data loss.
--
-- The table supports automated retry strategies with exponential backoff,
-- circuit breaker patterns to prevent cascading failures, and intelligent
-- filtering that distinguishes transient failures (retry) from permanent ones (DLQ).
-- Integration with alerting systems notifies on-call engineers when failure rates
-- exceed thresholds.
--
-- Operational dashboards use this table to display system health, identify
-- problematic services, and drive reliability improvements. Data from the DLQ
-- feeds into engineering OKRs around system stability (e.g., 99.99% job success rate).
--
-- Feature References:
-- DLQ-01: Job failure capture and isolation
-- DLQ-02: Transient vs permanent failure detection
-- DLQ-03: Exponential backoff retry scheduling
-- DLQ-04: Circuit breaker integration
-- DLQ-05: Manual replay capability
-- DLQ-06: Alerting and notification integration
-- DLQ-08: Failure analytics dashboard
-- DLQ-09: Retention and purging policies
-- DLQ-10: Idempotent replay semantics
--
-- Key Performance Indicators (KPIs):
-- 1. DLQ Entry Rate - Number of jobs failed per minute (trend analysis)
-- 2. Mean Time to Resolve (MTTR) - Time from DLQ entry to resolution
-- 3. Retry Success Ratio - % of failed jobs that succeed on retry
-- 4. Permanent Failure Rate - % of jobs requiring manual intervention
-- 5. DLQ Queue Depth - Current pending investigations count
-- 6. Service Reliability Score - 1 - (DLQ entries / total jobs)
-- 7. Recovery Time After Incident - Time to clear backlog post-outage
-- 8. Auto-resolution Rate - % of DLQ entries resolved without human action
-------------------------------------------------------------------------------
CREATE TABLE dead_letter_queue (
    -- Primary identifier
    dlq_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Original job identification
    original_job_id UUID NOT NULL,
    job_type VARCHAR(255) NOT NULL,
    job_queue VARCHAR(100) NOT NULL,                     -- email, sync, report, notification

    -- Job payload
    payload JSONB NOT NULL,
    metadata JSONB DEFAULT '{}'::JSONB,

    -- Failure information    failure_time TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    failure_stage VARCHAR(100) NOT NULL CHECK (failure_stage IN ('RECEIVED', 'PROCESSING', 'PUBLISHING', 'CONSUMER', 'CALLBACK')),
    failure_reason TEXT,
    exception_type VARCHAR(255),
    exception_stack TEXT,

    -- Failure classification
    failure_category VARCHAR(100) CHECK (failure_category IN (
        'NETWORK', 'DATABASE', 'TIMEOUT', 'RATE_LIMIT', 'AUTHENTICATION', 'AUTHORIZATION',
        'DATA_VALIDATION', 'BUSINESS_RULE', 'DEPENDENCY_UNAVAILABLE', 'RESOURCE_EXHAUSTED',
        'THROTTLED', 'CIRCUIT_OPEN', 'UNKNOWN'
    )),
    is_transient BOOLEAN,                                -- True if should retry

    -- Retry tracking
    retry_count INTEGER DEFAULT 0,
    max_retries_attempted INTEGER,
    last_retry_time TIMESTAMP WITH TIME ZONE,
    next_retry_time TIMESTAMP WITH TIME ZONE,

    -- Resolution tracking
    status dlq_status NOT NULL DEFAULT 'NEW',
    resolution_time TIMESTAMP WITH TIME ZONE,
    resolution_action VARCHAR(255),
    resolution_notes TEXT,
    resolved_by UUID,

    -- Circuit breaker context
    circuit_breaker_name VARCHAR(255),
    circuit_breaker_state VARCHAR(50) CHECK (circuit_breaker_state IN ('CLOSED', 'OPEN', 'HALF_OPEN')),

    -- Dependencies context
    failed_dependency VARCHAR(255),
    dependency_response_time_ms INTEGER,
    dependency_http_status INTEGER,
    dependency_error_code VARCHAR(100),

    -- Operational context
    service_name VARCHAR(255) NOT NULL,
    hostname VARCHAR(255),
    pod_name VARCHAR(255),
    trace_id VARCHAR(255),                               -- Distributed tracing
    span_id VARCHAR(255),

    -- Priority and escalation
    priority_level INTEGER DEFAULT 3 CHECK (priority_level BETWEEN 1 AND 5),
    escalation_required BOOLEAN DEFAULT false,
    escalation_time TIMESTAMP WITH TIME ZONE,
    escalation_notes TEXT,

    -- Replay configuration
    replay_scheduled BOOLEAN DEFAULT false,
    replay_time TIMESTAMP WITH TIME ZONE,
    replay_attempts INTEGER DEFAULT 0,

    -- Analytics
    business_impact VARCHAR(255),                        -- e.g., "delayed_invoice", "missed_notification"
    affected_entity_type VARCHAR(255),
    affected_entity_id VARCHAR(255),

    -- Retention
    retention_days INTEGER DEFAULT 30,
    auto_purge_after TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (failure_time + (retention_days * INTERVAL '1 day')) STORED,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by VARCHAR(255) DEFAULT 'SYSTEM',
    updated_by VARCHAR(255) DEFAULT 'SYSTEM',

    -- Constraints
    CONSTRAINT dlq_retry_check CHECK (retry_count <= max_retries_attempted OR max_retries_attempted IS NULL),
    CONSTRAINT dlq_resolution_check CHECK (resolution_time IS NOT NULL OR status = 'NEW' OR status = 'INVESTIGATING'),
    CONSTRAINT dlq_replay_check CHECK (replay_time IS NULL OR replay_time > failure_time)
);

-- Indexes for operational queries
CREATE INDEX idx_dlq_status ON dead_letter_queue (status, priority_level, failure_time);
CREATE INDEX idx_dlq_failure_time ON dead_letter_queue (failure_time DESC);
CREATE INDEX idx_dlq_job_type ON dead_letter_queue (job_type, failure_category);
CREATE INDEX idx_dlq_escalation ON dead_letter_queue (escalation_required, escalation_time) WHERE escalation_required = true;
CREATE INDEX idx_dlq_circuit_breaker ON dead_letter_queue (circuit_breaker_name, circuit_breaker_state);
CREATE INDEX idx_dlq_dependency ON dead_letter_queue (failed_dependency, dependency_http_status);
CREATE INDEX idx_dlq_trace ON dead_letter_queue (trace_id) WHERE trace_id IS NOT NULL;
CREATE INDEX idx_dlq_entity ON dead_letter_queue (affected_entity_type, affected_entity_id);

-- Composite indexes for dashboard queries
CREATE INDEX idx_dlq_dashboard_overview ON dead_letter_queue (failure_date) WHERE failure_date >= CURRENT_DATE - 30;
CREATE INDEX idx_dlq_service_health ON dead_letter_queue (service_name, failure_time DESC) WHERE failure_time > NOW() - INTERVAL '24 hours';

-- Partial index for unresolved high-priority issues
CREATE INDEX CONCURRENTLY idx_dlq_unresolved_high_priority ON dead_letter_queue (priority_level, failure_time) WHERE status NOT IN ('RESOLVED', 'SKIPPED') AND priority_level <= 2;

-- GIN index for JSON search
CREATE INDEX idx_dlq_payload ON dead_letter_queue USING gin(payload);
CREATE INDEX idx_dlq_metadata ON dead_letter_queue USING gin(metadata);

-- Comments for documentation
COMMENT ON TABLE dead_letter_queue IS 'Resilient failure handling system capturing failed jobs with full context for resolution';
COMMENT ON COLUMN dead_letter_queue.is_transient IS 'True for temporary failures that may succeed on retry (network blip, timeout)';
COMMENT ON COLUMN dead_letter_queue.business_impact IS 'Business consequence of failure to prioritize resolution (e.g., invoice_delay, revenue_impact)';
COMMENT ON COLUMN dead_letter_queue.auto_purge_after IS 'Automatically calculated retention expiration for compliance and storage management';

-- Row Level Security
ALTER TABLE dead_letter_queue ENABLE ROW LEVEL SECURITY;

CREATE POLICY dlq_operator_policy ON dead_letter_queue
    USING (current_setting('app.dlq_operator', true)::BOOLEAN = true);

