-- Updated_at triggers for all tables
-------------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Apply triggers to tables with updated_at columns
CREATE TRIGGER trg_api_rate_limits_updated_at
    BEFORE UPDATE ON api_rate_limits
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trg_feature_flags_updated_at
    BEFORE UPDATE ON feature_flags
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER trg_dead_letter_queue_updated_at
    BEFORE UPDATE ON dead_letter_queue
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-------------------------------------------------------------------------------
-- Materialized View: mv_api_usage_analytics
-- Description: Pre-aggregated API usage metrics for performance-critical dashboards
-- Refresh Strategy: Concurrent refresh every 5 minutes
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW mv_api_usage_analytics AS
SELECT
    DATE_TRUNC('hour', window_start_time) as hour_bucket,
    client_id,
    endpoint_pattern,
    tenant_id,
    COUNT(*) as total_requests,
    SUM(blocked_requests_this_window) as total_blocked,
    AVG(current_count::NUMERIC / max_requests) as avg_utilization_rate,
    MAX(current_count) as peak_usage,
    MIN(adjustment_factor) as min_throttle_factor
FROM api_rate_limits
WHERE window_start_time > NOW() - INTERVAL '30 days'
GROUP BY hour_bucket, client_id, endpoint_pattern, tenant_id;

CREATE UNIQUE INDEX idx_mv_api_usage_hourly ON mv_api_usage_analytics (hour_bucket, client_id, endpoint_pattern, tenant_id);

COMMENT ON MATERIALIZED VIEW mv_api_usage_analytics IS 'Pre-aggregated API usage for performance-optimized dashboards and alerting';

-------------------------------------------------------------------------------
-- Stored Procedure: retry_failed_outbox_events
-- Description: Intelligent retry handler for failed outbox events with exponential backoff
-------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE retry_failed_outbox_events(
    p_max_retries INTEGER DEFAULT 3,
    p_batch_size INTEGER DEFAULT 100
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_event RECORD;
    v_retry_delay INTEGER;
    v_updated_count INTEGER := 0;
BEGIN
    -- Input validation
    IF p_max_retries < 1 OR p_max_retries > 10 THEN
        RAISE EXCEPTION 'p_max_retries must be between 1 and 10, got %', p_max_retries;
    END IF;

    IF p_batch_size < 1 OR p_batch_size > 1000 THEN
        RAISE EXCEPTION 'p_batch_size must be between 1 and 1000, got %', p_batch_size;
    END IF;

    -- Process retryable events
    FOR v_event IN
        SELECT event_id, retry_count, backoff_base_ms, backoff_multiplier
        FROM event_outbox
        WHERE status = 'FAILED'
          AND retry_count < p_max_retries
          AND next_retry_time <= NOW()
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            -- Calculate exponential backoff
            v_retry_delay := v_event.backoff_base_ms * (v_event.backoff_multiplier ^ v_event.retry_count);

            -- Update for retry
            UPDATE event_outbox
            SET
                status = 'RETRY',
                retry_count = retry_count + 1,
                next_retry_time = NOW() + (v_retry_delay * INTERVAL '1 millisecond'),
                updated_at = NOW(),
                updated_by = 'SYSTEM_RETRY_HANDLER'
            WHERE event_id = v_event.event_id;

            v_updated_count := v_updated_count + 1;

            -- Log retry action (optional: insert to audit log)
            RAISE NOTICE 'Event % scheduled for retry % at %',
                v_event.event_id, v_event.retry_count + 1, v_retry_delay;

        EXCEPTION WHEN OTHERS THEN
            -- Log error but continue processing other events
            RAISE WARNING 'Failed to retry event %: %', v_event.event_id, SQLERRM;
        END;
    END LOOP;

    RAISE NOTICE 'Scheduled % events for retry', v_updated_count;

EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Error in retry_failed_outbox_events: %', SQLERRM;
END;
$$;

COMMENT ON PROCEDURE retry_failed_outbox_events IS 'Intelligent retry handler implementing exponential backoff for failed outbox events';

-------------------------------------------------------------------------------
-- Function: check_rate_limit
-- Description: Evaluate rate limit status for an API request with burst handling
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION check_rate_limit(
    p_client_id VARCHAR(255),
    p_endpoint_pattern VARCHAR(500),
    p_user_id UUID DEFAULT NULL,
    p_tenant_id VARCHAR(100) DEFAULT NULL,
    p_request_count INTEGER DEFAULT 1
)
RETURNS TABLE (
    is_allowed BOOLEAN,
    remaining_quota INTEGER,
    retry_after_seconds INTEGER,
    current_usage INTEGER
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_limit RECORD;
    v_window_end TIMESTAMP;
    v_usage INTEGER;
BEGIN
    -- Find applicable rate limit
    SELECT * INTO v_limit
    FROM api_rate_limits
    WHERE client_id = p_client_id
      AND endpoint_pattern = p_endpoint_pattern
      AND (user_id = p_user_id OR user_id IS NULL)
      AND (tenant_id = p_tenant_id OR tenant_id IS NULL)
      AND is_active = true
      AND window_end_time > NOW()
    ORDER BY priority_level, user_id NULLS LAST
    LIMIT 1;

    -- If no limit defined, allow request
    IF v_limit IS NULL THEN
        RETURN QUERY SELECT true, 999999, 0, 0;
        RETURN;
    END IF;

    -- Get current usage
    SELECT current_count INTO v_usage
    FROM api_rate_limits
    WHERE limit_id = v_limit.limit_id
    FOR UPDATE;

    -- Check if within limits
    IF v_usage + p_request_count <= v_limit.max_requests THEN
        -- Allow and increment
        UPDATE api_rate_limits
        SET current_count = current_count + p_request_count,
            total_requests_this_window = total_requests_this_window + p_request_count,
            last_request_time = NOW(),
            updated_at = NOW()
        WHERE limit_id = v_limit.limit_id;

        RETURN QUERY SELECT
            true,
            v_limit.max_requests - (v_usage + p_request_count),
            0,
            v_usage + p_request_count;
    ELSE
        -- Block request
        UPDATE api_rate_limits
        SET blocked_requests_this_window = blocked_requests_this_window + p_request_count
        WHERE limit_id = v_limit.limit_id;

        RETURN QUERY SELECT
            false,
            0,
            EXTRACT(EPOCH FROM (v_limit.window_end_time - NOW()))::INTEGER,
            v_usage;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        -- On error, allow request but log (circuit breaker pattern)
        RAISE WARNING 'Rate limit check failed for client % endpoint %: %',
            p_client_id, p_endpoint_pattern, SQLERRM;
        RETURN QUERY SELECT true, 0, 0, 0;
END;
$$;

COMMENT ON FUNCTION check_rate_limit IS 'Atomic rate limit check with burst handling and automatic increment';

-- Grant appropriate permissions (adjust based on security requirements)
GRANT SELECT, INSERT, UPDATE ON api_rate_limits TO ap_application;
GRANT SELECT, INSERT, UPDATE ON feature_flags TO ap_application;
GRANT SELECT, INSERT, UPDATE ON event_outbox TO ap_application;
GRANT SELECT, INSERT ON security_events TO ap_application;
GRANT SELECT, INSERT, UPDATE ON dead_letter_queue TO ap_application;

GRANT EXECUTE ON PROCEDURE retry_failed_outbox_events TO ap_application;
GRANT EXECUTE ON FUNCTION check_rate_limit TO ap_application;


--------------------------------------------------------------------------------
-- ENUM: notification_channel
-- Description: Defines available delivery channels for notifications
-- Business Case: Enables multi-channel notification delivery strategy
-- Feature Reference: NOTIF-03 (Multi-channel Delivery)
--------------------------------------------------------------------------------
CREATE TYPE notification_channel AS ENUM (
    'EMAIL',           -- Email delivery
    'PUSH',            -- Mobile/Web push notifications
    'SMS',             -- Text message delivery
    'IN_APP',          -- In-application notification center
    'SLACK',           -- Slack integration
    'TEAMS',           -- Microsoft Teams integration
    'WEBHOOK'          -- HTTP webhook callback
);

--------------------------------------------------------------------------------
-- ENUM: notification_priority
-- Description: Priority levels for notification sending and queuing
-- Business Case: Enables critical notifications to bypass queues
-- Feature Reference: NOTIF-07 (Priority-based Routing)
--------------------------------------------------------------------------------
CREATE TYPE notification_priority AS ENUM (
    'LOW',             -- Batch processed, no user disruption
    'NORMAL',          -- Standard delivery within SLA
    'HIGH',            -- Time-sensitive (password resets)
    'CRITICAL'         -- Imminent security/privacy issues
);

--------------------------------------------------------------------------------
-- ENUM: behavior_event_type
-- Description: Categories of user behavior tracking events
-- Business Case: Structured event taxonomy for analytics
-- Feature Reference: ANALYTICS-02 (Event Taxonomy)
--------------------------------------------------------------------------------
CREATE TYPE behavior_event_type AS ENUM (
    'PAGE_VIEW',       -- Page/screen viewed
    'CLICK',           -- UI element interaction
    'FORM_SUBMIT',     -- Form completion
    'SEARCH',          -- Search execution
    'SHARE',           -- Content sharing action
    'DOWNLOAD',        -- File download
    'LOGIN',           -- Authentication event
    'LOGOUT',          -- Session termination
    'REGISTRATION',    -- New user signup
    'UPGRADE',         -- Plan/ tier upgrade
    'FEATURE_USE',     -- Specific feature usage
    'ERROR',           -- Application error encounter
    'ENGAGEMENT'       -- Content interaction (like, comment)
);

--------------------------------------------------------------------------------
-- ENUM: moderation_status
-- Description: Content moderation workflow states
-- Business Case: Tracks content through review lifecycle
-- Feature Reference: MOD-04 (Workflow State Management)
--------------------------------------------------------------------------------
CREATE TYPE moderation_status AS ENUM (
    'PENDING',         -- Awaiting review
    'IN_REVIEW',       -- Currently being reviewed
    'APPROVED',        -- Passed moderation
    'REJECTED',        -- Failed moderation
    'FLAGGED',         -- Needs additional review
    'APPEALED',        -- User disputed decision
    'ESCALATED',       -- Sent to senior moderator
    'AUTO_APPROVED',   -- Passed automated checks
    'AUTO_REJECTED'    -- Failed automated checks
);

--------------------------------------------------------------------------------
-- ENUM: moderation_action
-- Description: Actions taken on moderated content
-- Business Case: Enables consistent enforcement actions
-- Feature Reference: MOD-08 (Enforcement Actions)
--------------------------------------------------------------------------------
CREATE TYPE moderation_action AS ENUM (
    'ALLOW',           -- Content published
    'BLOCK',           -- Content prevented from publishing
    'REMOVE',          -- Remove existing content
    'HIDE',            -- Hide from public view
    'FLAG_REVIEW',     -- Mark for human review
    'DEMOTE',          -- Reduce visibility/ranking
    'WARN_USER',       -- Send warning to user
    'SUSPEND_USER',    -- Temporary account restriction
    'BAN_USER'         -- Permanent account ban
);

--------------------------------------------------------------------------------
-- ENUM: notification_frequency
-- Description: User preferences for notification aggregation
-- Business Case: Reduces notification fatigue
-- Feature Reference: NOTIF-12 (Digest Preferences)
--------------------------------------------------------------------------------
CREATE TYPE notification_frequency AS ENUM (
    'REAL_TIME',       -- Immediate delivery
    'HOURLY',          -- Batched hourly
    'DAILY',           -- Daily digest
    'WEEKLY',          -- Weekly summary
    'NEVER'            -- Opted out
);

--------------------------------------------------------------------------------
-- Table: NOTIFICATION_TEMPLATES
-- Serial No: TBL-006
-- Description: Reusable, localized notification content management system
--
-- Business Case:
-- In a professional network sending millions of notifications daily (connection requests,
-- job alerts, message notifications, system announcements), maintaining consistent,
-- personalized, and localized messaging is critical for user experience and brand voice.
-- Hard-coded notification strings lead to inconsistent messaging, difficult updates,
-- and inability to A/B test content variations.
--
-- This table serves as a centralized template repository supporting multiple languages,
-- dynamic variable substitution (e.g., {{user_name}}, {{company_name}}), and conditional
-- logic for personalized content. Marketing teams can update promotional messaging without
-- engineering deployments, while legal can ensure compliance language (GDPR consent,
-- terms updates) appears consistently across all communications.
--
-- The system supports A/B testing of notification content to optimize engagement metrics
-- (open rates, click-through rates). Templates can be versioned, allowing rollback if
-- new messaging underperforms. The template engine includes safety features to prevent
-- variable injection attacks and validates that all required variables are provided.
--
-- For multi-national platforms, templates support i18n with region-specific formatting
-- (dates, currencies, number formats) and cultural adaptations. Fallback chains ensure
-- users always receive content in their preferred language or a reasonable default.
--
-- Feature References:
-- NOTIF-01: Centralized template management
-- NOTIF-02: Multi-language support (i18n)
-- NOTIF-04: Dynamic variable substitution (mustache/jinja)
-- NOTIF-05: A/B testing content variations
-- NOTIF-06: Template versioning and rollback
-- NOTIF-08: Conditional content logic
-- NOTIF-09: Preview and testing interface
-- NOTIF-10: Regulatory compliance embedding
-- NOTIF-11: Template analytics (open/click rates)
--
-- Key Performance Indicators (KPIs):
-- 1. Template Utilization Rate - % of active templates used in last 30 days
-- 2. Localization Coverage - % of templates translated for top 5 languages
-- 3. A/B Test Win Rate - % of tests where variant beats control
-- 4. Time to Update Messaging - Hours from edit to production deployment
-- 5. Template Rendering Latency - P99 milliseconds to render (target <10ms)
-- 6. Variable Error Rate - % of sends with missing variables
-- 7. Engagement by Template - Open/click rates segmented by template
-- 8. Compliance Coverage - % of regulatory communications using approved templates
--------------------------------------------------------------------------------
CREATE TABLE notification_templates (
    -- Primary identifier
    template_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Template identification
    template_key VARCHAR(255) NOT NULL UNIQUE,
    template_name VARCHAR(500) NOT NULL,
    description TEXT,
    category VARCHAR(100) NOT NULL CHECK (category IN (
        'TRANSACTIONAL', 'MARKETING', 'SYSTEM', 'SECURITY',
        'SOCIAL', 'REMINDER', 'BILLING', 'COMPLIANCE'
    )),

    -- Content
    subject_template TEXT,                                -- For email/SMS subjects
    body_template TEXT NOT NULL,                          -- Main content template
    html_body_template TEXT,                              -- HTML version (for email)
    push_title_template TEXT,                             -- Push notification title
    push_body_template TEXT,                              -- Push notification body

    -- Supported channels (which channels this template works with)
    supported_channels notification_channel[] DEFAULT ARRAY['EMAIL', 'IN_APP']::notification_channel[],

    -- Localization
    language_code VARCHAR(10) NOT NULL DEFAULT 'en',      -- ISO 639-1 + region
    fallback_language VARCHAR(10),                        -- Language to use if this missing
    region_overrides JSONB,                               -- Region-specific variations

    -- Variable schema documentation
    required_variables JSONB,                             -- {"user_name": "string", "action_url": "url"}
    optional_variables JSONB,
    variable_validators JSONB,                            -- Regex patterns for safety

    -- Conditional logic
    conditional_rules JSONB,                              -- If/else logic for dynamic content

    -- Priority and routing
    default_priority notification_priority DEFAULT 'NORMAL',
    throttle_rate_per_minute INTEGER,                     -- Send rate limiting

    -- A/B testing
    is_ab_test_variant BOOLEAN DEFAULT false,
    parent_template_id UUID REFERENCES notification_templates(template_id),
    ab_test_weight INTEGER CHECK (ab_test_weight BETWEEN 0 AND 100),
    ab_test_metrics JSONB,                                -- Performance tracking

    -- Version control
    version INTEGER DEFAULT 1 NOT NULL,
    is_active BOOLEAN DEFAULT true NOT NULL,
    is_deprecated BOOLEAN DEFAULT false,
    deprecated_at TIMESTAMP WITH TIME ZONE,
    deprecation_reason TEXT,

    -- Analytics metadata
    use_count BIGINT DEFAULT 0,
    success_count BIGINT DEFAULT 0,
    failure_count BIGINT DEFAULT 0,
    avg_open_rate NUMERIC(5,2),
    avg_click_rate NUMERIC(5,2),
    last_used_at TIMESTAMP WITH TIME ZONE,

    -- Rendering configuration
    renderer_type VARCHAR(50) DEFAULT 'JINJA' CHECK (renderer_type IN ('JINJA', 'MUSTACHE', 'CUSTOM')),
    escape_html BOOLEAN DEFAULT true,
    max_rendered_size INTEGER DEFAULT 100000,             -- Max rendered bytes

    -- Approval workflow
    requires_approval BOOLEAN DEFAULT false,
    approved_by UUID,
    approved_at TIMESTAMP WITH TIME ZONE,
    approval_notes TEXT,

    -- Styling
    brand_color VARCHAR(7),                               -- Hex code
    brand_logo_url TEXT,
    footer_html TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT template_version_consistency CHECK (
        (is_ab_test_variant = false OR parent_template_id IS NOT NULL)
    ),
    CONSTRAINT template_localization_check CHECK (
        (language_code = 'en' AND fallback_language IS NULL) OR
        fallback_language IS NOT NULL
    )
);

-- Indexes for template lookup
CREATE INDEX idx_notification_templates_lookup ON notification_templates (template_key, language_code, is_active);
CREATE INDEX idx_notification_templates_category ON notification_templates (category, is_active);
CREATE INDEX idx_notification_templates_ab_test ON notification_templates (parent_template_id, is_ab_test_variant);
CREATE INDEX idx_notification_templates_usage ON notification_templates (use_count DESC, last_used_at DESC);

-- Partial index for active templates
CREATE INDEX CONCURRENTLY idx_templates_active ON notification_templates (category, language_code) WHERE is_active = true AND is_deprecated = false;

-- GIN indexes for JSON columns
CREATE INDEX idx_templates_required_vars ON notification_templates USING gin(required_variables);
CREATE INDEX idx_templates_conditional_rules ON notification_templates USING gin(conditional_rules);

-- Comments for documentation
COMMENT ON TABLE notification_templates IS 'Centralized, localized, versioned notification template system with A/B testing support';
COMMENT ON COLUMN notification_templates.template_key IS 'Unique identifier used in code (e.g., "welcome_email", "password_reset_sms")';
COMMENT ON COLUMN notification_templates.required_variables IS 'JSON schema defining required template variables for validation';
COMMENT ON COLUMN notification_templates.conditional_rules IS 'Jinja/Mustache conditional logic for dynamic content personalization';

-- Row Level Security
ALTER TABLE notification_templates ENABLE ROW LEVEL SECURITY;

CREATE POLICY templates_admin_policy ON notification_templates
    USING (current_setting('app.is_notification_admin', true)::BOOLEAN = true);

CREATE POLICY templates_readonly_policy ON notification_templates
    FOR SELECT USING (is_active = true);

--------------------------------------------------------------------------------
-- Table: NOTIFICATION_PREFERENCES
-- Serial No: TBL-007
-- Description: User-controlled notification channel and frequency management
--
-- Business Case:
-- Notification fatigue is a leading cause of user churn. In professional networks,
-- users receive notifications for connection requests, job recommendations, messages,
-- system updates, and marketing communications. Without granular controls, users
-- either receive too many (leading to frustration and unsubscribes) or too few
-- (missing critical updates). GDPR and CAN-SPAM regulations require explicit user
-- consent for marketing communications and easy opt-out mechanisms.
--
-- This table enables users to customize their notification experience per channel
-- (email, push, SMS, in-app) and per notification type (job alerts, connection
-- requests, messages). Users can set quiet hours (e.g., "no notifications 10PM-8AM"),
-- choose digest frequencies (real-time, daily, weekly), and temporarily pause all
-- notifications during vacations.
--
-- The system respects user preferences with multi-channel orchestration: if a user
-- disables email but enables push, notifications route appropriately. Critical
-- security notifications (password changes, suspicious login) can override user
-- preferences for safety. The table supports team/workspace-level defaults with
-- individual overrides, essential for enterprise customers.
--
-- Analytics from this table informs product decisions about notification defaults,
-- identifies channels users prefer, and drives A/B tests of new notification types.
-- Compliance reports demonstrate opt-in rates and consent timestamps for regulatory audits.
--
-- Feature References:
-- PREF-01: Channel-level opt-in/opt-out
-- PREF-02: Notification-type granular preferences
-- PREF-03: Quiet hours and time-based rules
-- PREF-04: Digest frequency configuration
-- PREF-05: Global pause (vacation mode)
-- PREF-06: Critical notification override
-- PREF-07: Team/workspace defaults
-- PREF-08: Preference change audit trail
-- PREF-09: Consent tracking (GDPR)
-- PREF-10: Preference inheritance hierarchy
--
-- Key Performance Indicators (KPIs):
-- 1. Preference Configuration Rate - % of users who customize defaults (target >30%)
-- 2. Opt-out Rate by Notification Type - % disabling specific notification types
-- 3. Channel Preference Distribution - % using email vs push vs SMS vs in-app
-- 4. Quiet Hour Adoption - % setting time-based restrictions
-- 5. Digest Preference Rate - % choosing digests vs real-time
-- 6. Preference Change Frequency - Average number of preference updates per user
-- 7. Notification Receipt Satisfaction - Survey-based satisfaction correlation
-- 8. GDPR Consent Coverage - % with explicit consent for marketing
--------------------------------------------------------------------------------
CREATE TABLE notification_preferences (
    -- Primary identifier
    preference_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User identification
    user_id UUID NOT NULL,
    workspace_id UUID,                                    -- Team-level defaults

    -- Channel preferences
    channel notification_channel NOT NULL,
    is_enabled BOOLEAN DEFAULT true NOT NULL,

    -- Granular type preferences (JSON for flexibility)
    enabled_notification_types TEXT[] DEFAULT ARRAY[]::TEXT[],  -- Empty = all enabled
    disabled_notification_types TEXT[] DEFAULT ARRAY[]::TEXT[], -- Explicit disables

    -- Frequency control
    frequency notification_frequency DEFAULT 'REAL_TIME' NOT NULL,
    digest_hour INTEGER CHECK (digest_hour BETWEEN 0 AND 23),    -- Hour for daily digest
    digest_day_of_week INTEGER CHECK (digest_day_of_week BETWEEN 0 AND 6), -- 0=Monday

    -- Quiet hours
    quiet_hours_enabled BOOLEAN DEFAULT false,
    quiet_hours_start TIME,                               -- Local time
    quiet_hours_end TIME,
    quiet_hours_timezone VARCHAR(100) DEFAULT 'UTC',

    -- Time-based rules (more complex schedules)
    time_rules JSONB,                                     -- Cron-like expressions

    -- Throttling
    max_per_day INTEGER,                                  -- Max notifications per day
    max_per_hour INTEGER,

    -- Global pause
    global_pause_enabled BOOLEAN DEFAULT false,
    global_pause_start TIMESTAMP WITH TIME ZONE,
    global_pause_end TIMESTAMP WITH TIME ZONE,
    global_pause_reason TEXT,

    -- Override hierarchy
    preference_source VARCHAR(50) DEFAULT 'USER' CHECK (preference_source IN ('USER', 'WORKSPACE', 'DEFAULT', 'COMPLIANCE')),
    parent_preference_id UUID REFERENCES notification_preferences(preference_id),
    override_reason TEXT,

    -- Critical notification overrides
    allow_critical_overrides BOOLEAN DEFAULT true,       -- Security notifications override
    critical_override_channels notification_channel[],

    -- Marketing consent (GDPR specific)
    marketing_consent_given BOOLEAN DEFAULT false,
    marketing_consent_given_at TIMESTAMP WITH TIME ZONE,
    marketing_consent_source_ip INET,
    marketing_consent_method VARCHAR(50) CHECK (marketing_consent_method IN ('CHECKBOX', 'EMAIL_CLICK', 'SUPPORT_REQUEST', 'DEFAULT')),

    -- Withdrawal tracking
    withdrawn_at TIMESTAMP WITH TIME ZONE,
    withdrawn_reason TEXT,

    -- Analytics
    last_notification_sent_at TIMESTAMP WITH TIME ZONE,
    notifications_sent_24h INTEGER DEFAULT 0,
    notifications_sent_7d INTEGER DEFAULT 0,

    -- Experiment tracking
    ab_test_bucket VARCHAR(100),                          -- Which default preference variant

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT preferences_type_conflict CHECK (
        NOT (enabled_notification_types IS NOT NULL AND disabled_notification_types IS NOT NULL AND
             array_length(enabled_notification_types, 1) > 0 AND
             array_length(disabled_notification_types, 1) > 0)
    ),
    CONSTRAINT quiet_hours_valid CHECK (
        NOT (quiet_hours_enabled = true AND (quiet_hours_start IS NULL OR quiet_hours_end IS NULL))
    ),
    CONSTRAINT global_pause_valid CHECK (
        NOT (global_pause_enabled = true AND (global_pause_start IS NULL OR global_pause_end IS NULL))
    ),
    CONSTRAINT marketing_consent_check CHECK (
        NOT (marketing_consent_given = true AND marketing_consent_given_at IS NULL)
    ),
    UNIQUE(user_id, workspace_id, channel)
);

-- Indexes for preference lookups
CREATE INDEX idx_preferences_user ON notification_preferences (user_id, channel);
CREATE INDEX idx_preferences_workspace ON notification_preferences (workspace_id) WHERE workspace_id IS NOT NULL;
CREATE INDEX idx_preferences_global_pause ON notification_preferences (global_pause_enabled, global_pause_end) WHERE global_pause_enabled = true;
CREATE INDEX idx_preferences_marketing_consent ON notification_preferences (marketing_consent_given, marketing_consent_given_at);

-- Partial index for active users with custom preferences
CREATE INDEX CONCURRENTLY idx_preferences_active_custom ON notification_preferences (user_id, channel)
    WHERE preference_source = 'USER' AND is_enabled = true;

-- Comments for documentation
COMMENT ON TABLE notification_preferences IS 'Granular user notification preferences with GDPR-compliant consent tracking';
COMMENT ON COLUMN notification_preferences.enabled_notification_types IS 'Whitelist of notification types (e.g., ["job_alert", "connection_request"])';
COMMENT ON COLUMN notification_preferences.disabled_notification_types IS 'Blacklist of notification types - overrides enabled list';
COMMENT ON COLUMN notification_preferences.marketing_consent_given IS 'GDPR-required explicit consent timestamp for marketing communications';

-- Row Level Security
ALTER TABLE notification_preferences ENABLE ROW LEVEL SECURITY;

CREATE POLICY preferences_user_policy ON notification_preferences
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

CREATE POLICY preferences_workspace_admin_policy ON notification_preferences
    USING (EXISTS (
        SELECT 1 FROM workspace_admins
        WHERE workspace_id = notification_preferences.workspace_id
        AND user_id = current_setting('app.current_user_id', true)::UUID
    ));

--------------------------------------------------------------------------------
-- Table: SEARCH_QUERY_LOGS
-- Serial No: TBL-008
-- Description: Comprehensive search analytics for relevance optimization
--
-- Business Case:
-- Search is the primary discovery mechanism in professional networks—users find
-- jobs, talent, content, and connections through search. Poor search relevance
-- directly correlates with user frustration, platform abandonment, and lost
-- revenue from job posts and premium features. Without analytics, teams cannot
-- identify what users are searching for, what results are missing, or how to
-- improve ranking algorithms.
--
-- This table captures every search query with rich contextual data: search terms,
-- filters applied (location, industry, experience level), results returned, user
-- interactions (clicks, zero-result queries), and conversion events (applications,
-- messages, follows). This data feeds machine learning models that continuously
-- improve search relevance through learning-to-rank algorithms.
--
-- Zero-result queries are particularly valuable—they represent failed searches
-- and content gaps. If many users search for "machine learning engineer" with no
-- results, content teams can prioritize creating relevant content or recruiting
-- in that area. Time-to-click metrics indicate ranking effectiveness: if users
-- consistently click the 5th result, rank 5 should move higher.
--
-- The table powers analytics dashboards showing popular search terms (trend analysis),
-- search success rates (results + clicks), and user segments with poor search
-- experiences. A/B tests for ranking algorithms compare performance metrics
-- against historical baselines from this table.
--
-- Feature References:
-- SEARCH-01: Query log capture with full context
-- SEARCH-02: Zero-result query tracking
-- SEARCH-03: Click analytics and position tracking
-- SEARCH-04: Search usage trends dashboard
-- SEARCH-05: Content gap identification
-- SEARCH-06: Training data for ML ranking
-- SEARCH-07: A/B test metrics
-- SEARCH-08: Search abandonment analysis
-- SEARCH-09: Filter usage analytics
-- SEARCH-10: Personalization tuning data
--
-- Key Performance Indicators (KPIs):
-- 1. Search Success Rate - % of queries with >=1 click (target >60%)
-- 2. Zero-Result Rate - % of queries returning 0 results (target <10%)
-- 3. Average Click Position - Mean rank of clicked result (target <3.0)
-- 4. Search Abandonment Rate - % of searches with no clicks
-- 5. Filter Usage % - % of searches using advanced filters
-- 6. Query Reformulation Rate - % of users modifying search terms
-- 7. Time to First Click - Average seconds from search to click
-- 8. Search Session Length - Average queries per search session
-- 9. Long-tail Coverage - % of unique queries with good results
-- 10. Search-to-Conversion Rate - % of searches leading to desired action
--------------------------------------------------------------------------------
CREATE TABLE search_query_logs (
    -- Primary identifier
    search_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User context
    user_id UUID,
    session_id UUID NOT NULL,
    ip_address INET,
    user_agent TEXT,

    -- Query details
    query_raw TEXT NOT NULL,                              -- Original user input
    query_normalized VARCHAR(500),                        -- Lowercase, normal form
    query_tokens TEXT[],                                  -- Tokenized query
    query_length INTEGER,                                 -- Character count
    word_count INTEGER,                                   -- Number of terms

    -- Search type and scope
    search_type VARCHAR(50) NOT NULL CHECK (search_type IN (
        'PEOPLE', 'JOBS', 'CONTENT', 'COMPANIES', 'GROUPS', 'ALL', 'ADVANCED'
    )),
    search_scope VARCHAR(100),                            -- "network_only", "public", "workspace"

    -- Filters applied
    filters_applied JSONB DEFAULT '{}'::JSONB,
    -- Example: {"location": "San Francisco", "industry": "Tech", "experience": "5+ years"}

    -- Temporal filters
    date_range_start DATE,
    date_range_end DATE,

    -- Results metadata
    total_results INTEGER DEFAULT 0 NOT NULL,
    results_returned INTEGER DEFAULT 0,
    is_zero_result BOOLEAN GENERATED ALWAYS AS (total_results = 0) STORED,

    -- Pagination
    page_number INTEGER DEFAULT 1,
    results_per_page INTEGER DEFAULT 20,

    -- Performance
    search_latency_ms INTEGER,                           -- Time to fetch results
    ranking_latency_ms INTEGER,                          -- Time to rank results

    -- User interaction (post-search)
    clicked_result BOOLEAN DEFAULT false,
    click_position INTEGER,                               -- 1-indexed position in results
    clicked_result_id VARCHAR(255),                       -- ID of clicked entity
    clicked_result_type VARCHAR(50),                     -- "profile", "job", "post"
    time_to_click_seconds INTEGER,                       -- Seconds after search

    -- Follow-up actions
    applied_filters_after BOOLEAN DEFAULT false,          -- Refined search
    reformulated_query BOOLEAN DEFAULT false,             -- New search
    reformulated_query_text TEXT,
    abandoned_session BOOLEAN DEFAULT false,              -- No further action

    -- Conversion tracking (what user did after search)
    conversion_type VARCHAR(50),                          -- "applied", "messaged", "saved", "followed"
    conversion_id UUID,
    conversion_time TIMESTAMP WITH TIME ZONE,

    -- Ranking algorithm context
    ranking_version VARCHAR(50),                          -- Which ranking model
    ab_bucket VARCHAR(100),                               -- A/B test group
    relevance_scores JSONB,                               -- Per-result scores (anonymized)

    -- Search quality (labeling)
    was_satisfied BOOLEAN,                                -- Implicit satisfaction
    explicit_feedback INTEGER CHECK (explicit_feedback BETWEEN 1 AND 5), -- 1-5 rating
    explicit_feedback_text TEXT,

    -- Contextual signals
    query_time TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    day_of_week INTEGER GENERATED ALWAYS AS (EXTRACT(DOW FROM query_time)) STORED,
    hour_of_day INTEGER GENERATED ALWAYS AS (EXTRACT(HOUR FROM query_time)) STORED,
    is_business_hours BOOLEAN GENERATED ALWAYS AS (
        EXTRACT(HOUR FROM query_time) BETWEEN 9 AND 17
    ) STORED,

    -- Device context
    device_type VARCHAR(50) CHECK (device_type IN ('DESKTOP', 'MOBILE', 'TABLET', 'UNKNOWN')),
    browser VARCHAR(100),
    os VARCHAR(100),

    -- Geo context
    geo_country VARCHAR(100),
    geo_city VARCHAR(100),
    geo_region VARCHAR(100),

    -- Retention policy
    retention_period_days INTEGER DEFAULT 90,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,

    -- Constraints
    CONSTRAINT search_click_position_check CHECK (
        clicked_result = false OR (click_position IS NOT NULL AND click_position > 0)
    ),
    CONSTRAINT search_relevance_check CHECK (
        explicit_feedback IS NULL OR (explicit_feedback BETWEEN 1 AND 5 AND explicit_feedback_text IS NOT NULL)
    )
);

-- Critical indexes for search analytics
CREATE INDEX idx_search_query_time ON search_query_logs (query_time DESC);
CREATE INDEX idx_search_user_session ON search_query_logs (user_id, session_id, query_time);
CREATE INDEX idx_search_zero_result ON search_query_logs (is_zero_result, query_time DESC) WHERE is_zero_result = true;
CREATE INDEX idx_search_query_normalized ON search_query_logs (query_normalized, query_time DESC);
CREATE INDEX idx_search_type ON search_query_logs (search_type, query_time DESC);

-- Composite indexes for trend analysis
CREATE INDEX idx_search_analytics_daily ON search_query_logs (DATE(query_time), search_type, is_zero_result);
CREATE INDEX idx_search_click_analysis ON search_query_logs (clicked_result, click_position, query_time) WHERE clicked_result = true;

-- Partial index for high-value queries (with conversions)
CREATE INDEX CONCURRENTLY idx_search_conversions ON search_query_logs (conversion_type, conversion_time) WHERE conversion_type IS NOT NULL;

-- GIN indexes for JSON filters
CREATE INDEX idx_search_filters ON search_query_logs USING gin(filters_applied);
CREATE INDEX idx_search_relevance_scores ON search_query_logs USING gin(relevance_scores);

-- Time-based partitioning (for retention management)
-- Using table inheritance for production (simplified example)
CREATE INDEX idx_search_retention ON search_query_logs (query_time) WHERE query_time < NOW() - INTERVAL '90 days';

-- Comments for documentation
COMMENT ON TABLE search_query_logs IS 'Comprehensive search analytics capturing queries, interactions, and relevance metrics';
COMMENT ON COLUMN search_query_logs.query_raw IS 'Original user input before normalization (PII consideration)';
COMMENT ON COLUMN search_query_logs.is_zero_result IS 'Critical metric for identifying content gaps';
COMMENT ON COLUMN search_query_logs.was_satisfied IS 'Implicit satisfaction measured by post-search engagement';
COMMENT ON COLUMN search_query_logs.ranking_version IS 'Tracks which ranking algorithm version produced these results';

-- Row Level Security (anonymized access only)
ALTER TABLE search_query_logs ENABLE ROW LEVEL SECURITY;

CREATE POLICY search_logs_analytics_policy ON search_query_logs
    USING (current_setting('app.is_search_analyst', true)::BOOLEAN = true);

-- PII masking for non-analyst users
CREATE POLICY search_logs_masked_policy ON search_query_logs
    FOR SELECT USING (current_setting('app.is_authenticated', true)::BOOLEAN = true);

--------------------------------------------------------------------------------
-- Table: USER_BEHAVIOR_EVENTS
-- Serial No: TBL-009
-- Description: Raw event tracking for analytics, personalization, and product insights
--
-- Business Case:
-- In modern product development, decisions must be data-driven rather than opinion-driven.
-- User behavior events capture every meaningful interaction users have with the platform:
-- page views, clicks, form submissions, feature usage, errors, and engagement actions.
-- This raw event stream powers product analytics (funnel analysis, retention cohorts),
-- personalization algorithms (recommendation systems, content ranking), and machine
-- learning models (churn prediction, lifetime value estimation).
--
-- Unlike aggregated tables, raw events maintain full granularity for ad-hoc analysis.
-- When product managers ask "how many users clicked the new job alert button but didn't
-- complete setup?", analysts can query this table directly. For A/B tests comparing
-- onboarding flows, event data provides statistical significance calculations.
--
-- The table is optimized for high-throughput writes (millions of events per day) with
-- appropriate indexing for analytical queries (time-range scans, user-centric queries).
-- Event schemas are validated against JSON schemas to ensure data quality. For GDPR
-- compliance, user IDs can be pseudonymized after retention periods, and users can
-- request deletion of their event history.
--
-- Integration with data warehouses (Snowflake, BigQuery) via streaming pipelines ensures
-- events are available for offline analytics within minutes. Real-time events also feed
-- personalization engines that adjust content ranking based on recent interactions.
--
-- Feature References:
-- EVENT-01: Raw event capture with schemas
-- EVENT-02: Funnel and cohort analysis
-- EVENT-03: Personalization signal generation
-- EVENT-04: A/B test data collection
-- EVENT-05: ML feature engineering
-- EVENT-06: GDPR-compliant pseudonymization
-- EVENT-07: Real-time event streaming
-- EVENT-08: Event validation and enrichment
-- EVENT-09: Session reconstruction
-- EVENT-10: User journey mapping
--
-- Key Performance Indicators (KPIs):
-- 1. Event Volume - Events per day (capacity planning)
-- 2. Event Latency - Time from occurrence to database write (p99)
-- 3. Data Quality Score - % events passing validation
-- 4. Event Coverage - % user actions captured vs missed
-- 5. Analysis Query Performance - P95 query time for common analytics
-- 6. Real-time Signal Latency - Time to personalization engine
-- 7. Session Reconstruction Rate - % events successfully attributed to sessions
-- 8. Data Freshness for Reporting - Time until events available in warehouse
-- 9. PII Compliance Rate - % events properly pseudonymized
-- 10. Event Schema Evolution - % breaking changes vs additive changes
--------------------------------------------------------------------------------
CREATE TABLE user_behavior_events (
    -- Primary identifier (using bigserial for high-volume ingestion)
    event_id BIGSERIAL PRIMARY KEY,

    -- Event classification
    event_type behavior_event_type NOT NULL,
    event_category VARCHAR(100) GENERATED ALWAYS AS (
        CASE
            WHEN event_type IN ('PAGE_VIEW', 'CLICK', 'FORM_SUBMIT') THEN 'INTERACTION'
            WHEN event_type IN ('LOGIN', 'LOGOUT', 'REGISTRATION') THEN 'AUTHENTICATION'
            WHEN event_type IN ('SEARCH') THEN 'DISCOVERY'
            WHEN event_type IN ('UPGRADE', 'FEATURE_USE') THEN 'MONETIZATION'
            WHEN event_type = 'ERROR' THEN 'PERFORMANCE'
            ELSE 'ENGAGEMENT'
        END
    ) STORED,

    -- User identity (pseudonymized for GDPR)
    user_id UUID,
    user_pseudonym VARCHAR(255),                          -- Hash for GDPR compliance
    session_id UUID NOT NULL,
    anonymous_id UUID,                                     -- Before login

    -- Event timing
    event_time TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    client_time TIMESTAMP WITH TIME ZONE,                 -- Client-reported time
    timezone_offset INTEGER,                              -- Minutes from UTC

    -- Event properties (flexible schema)
    event_properties JSONB NOT NULL,
    -- Example for CLICK: {"element_id": "job_apply_button", "position": 3, "job_id": "123"}
    -- Example for PAGE_VIEW: {"page": "/jobs", "referrer": "/dashboard", "load_time_ms": 450}

    -- User properties (snapshot at event time)
    user_properties JSONB,
    -- Example: {"tier": "premium", "tenure_days": 45, "industry": "tech"}

    -- Page/context properties
    page_url TEXT,
    page_title VARCHAR(500),
    referrer_url TEXT,
    landing_page BOOLEAN DEFAULT false,
    exit_page BOOLEAN DEFAULT false,

    -- Technical context
    user_agent TEXT,
    screen_resolution VARCHAR(20),
    viewport_size VARCHAR(20),
    language VARCHAR(10),
    timezone VARCHAR(100),

    -- Device identifiers
    device_id VARCHAR(255),
    device_model VARCHAR(100),
    device_brand VARCHAR(50),
    os_name VARCHAR(50),
    os_version VARCHAR(20),
    browser_name VARCHAR(50),
    browser_version VARCHAR(20),
    is_mobile BOOLEAN,
    is_tablet BOOLEAN,
    is_desktop BOOLEAN,

    -- Network context
    ip_address INET,
    geo_country VARCHAR(100),
    geo_region VARCHAR(100),
    geo_city VARCHAR(100),
    carrier_name VARCHAR(100),
    connection_type VARCHAR(50),                          -- wifi, cellular, ethernet

    -- Engagement metrics
    time_on_page_seconds INTEGER,                         -- For page_view events
    scroll_depth_percent INTEGER CHECK (scroll_depth_percent BETWEEN 0 AND 100),
    num_interactions INTEGER,                             -- Events on this page

    -- A/B testing context
    ab_tests JSONB,                                       -- Active test assignments
    feature_flags JSONB,                                  -- Enabled features

    -- Funnel tracking
    funnel_id VARCHAR(255),
    funnel_step INTEGER,
    funnel_name VARCHAR(255),

    -- Attribution
    utm_source VARCHAR(255),
    utm_medium VARCHAR(255),
    utm_campaign VARCHAR(255),
    utm_term VARCHAR(255),
    utm_content VARCHAR(255),
    gclid VARCHAR(255),                                   -- Google click ID
    fbclid VARCHAR(255),                                  -- Facebook click ID

    -- Session context
    session_number INTEGER,                               -- User's nth session
    event_number_in_session INTEGER,                      -- Sequential event index
    time_since_last_event_seconds INTEGER,

    -- Validation
    is_validated BOOLEAN DEFAULT false,
    validation_errors TEXT[],
    schema_version VARCHAR(20) DEFAULT '1.0',

    -- Enrichment (post-ingestion)
    enriched_at TIMESTAMP WITH TIME ZONE,
    enrichment_data JSONB,

    -- ML predictions (real-time)
    predicted_churn_risk NUMERIC(4,3),                    -- 0-1 probability
    predicted_lifetime_value NUMERIC(10,2),
    predicted_intent VARCHAR(100),

    -- Compliance
    is_pseudonymized BOOLEAN DEFAULT false,
    pseudonymized_at TIMESTAMP WITH TIME ZONE,
    gdpr_consent_given BOOLEAN,                          -- At event time
    data_retention_end TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    ingested_by VARCHAR(255) DEFAULT 'event_collector',

    -- Constraints
    CONSTRAINT event_time_valid CHECK (event_time <= NOW() + INTERVAL '5 minutes'),
    CONSTRAINT event_properties_not_null CHECK (event_properties IS NOT NULL AND jsonb_typeof(event_properties) = 'object')
);

-- Critical indexes for high-volume analytics
CREATE INDEX idx_behavior_events_time ON user_behavior_events (event_time DESC, event_type);
CREATE INDEX idx_behavior_events_user ON user_behavior_events (user_id, event_time DESC) WHERE user_id IS NOT NULL;
CREATE INDEX idx_behavior_events_session ON user_behavior_events (session_id, event_number_in_session);
CREATE INDEX idx_behavior_events_funnel ON user_behavior_events (funnel_id, funnel_step, event_time);

-- Time-based partitioning (monthly)
-- For production, use declarative partitioning: PARTITION BY RANGE (event_time)
CREATE INDEX idx_behavior_events_time_range ON user_behavior_events (event_time)
    WHERE event_time > NOW() - INTERVAL '7 days';

-- Partial indexes for common queries
