CREATE INDEX CONCURRENTLY idx_behavior_events_conversion ON user_behavior_events (event_time, event_type)
    WHERE event_type IN ('UPGRADE', 'REGISTRATION');

-- GIN indexes for JSON queries
CREATE INDEX idx_behavior_events_properties ON user_behavior_events USING gin(event_properties);
CREATE INDEX idx_behavior_events_user_props ON user_behavior_events USING gin(user_properties);

-- BRIN index for time-series (space-efficient)
