-- Comments for documentation
COMMENT ON TABLE user_behavior_events IS 'Raw event stream for product analytics, personalization, and ML feature engineering';
COMMENT ON COLUMN user_behavior_events.event_properties IS 'Flexible JSON schema for event-specific properties (validated against schema registry)';
COMMENT ON COLUMN user_behavior_events.user_pseudonym IS 'GDPR-compliant pseudonymized user identifier after retention period';
COMMENT ON COLUMN user_behavior_events.predicted_churn_risk IS 'Real-time ML prediction for downstream personalization';

-- Row Level Security (pseudonymized access only)
ALTER TABLE user_behavior_events ENABLE ROW LEVEL SECURITY;

