sl_compliance_rate NUMERIC(5,2),
last_instance_completed_at TIMESTAMP WITH TIME ZONE,

-- Audit trail
created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
created_by UUID NOT NULL,
updated_by UUID NOT NULL,

-- Constraints
CONSTRAINT workflow_steps_not_empty CHECK (jsonb_array_length(steps) > 0),
CONSTRAINT workflow_transitions_valid CHECK (jsonb_array_length(transitions) >= jsonb_array_length(steps) - 1),
CONSTRAINT workflow_timeout_check CHECK (default_step_timeout_hours >= 1 AND default_step_timeout_hours <= 720)
);

