-- ENUM: worker_status for job queue workers
CREATE TYPE worker_status AS ENUM ('RUNNING', 'STOPPED', 'DEGRADED', 'UNHEALTHY');

-- ENUM: pipeline_status for ETL job tracking
CREATE TYPE pipeline_status AS ENUM ('PENDING', 'RUNNING', 'SUCCESS', 'FAILED', 'CANCELLED');

-- Table: JOB_QUEUE_WORKERS
CREATE TABLE job_queue_workers (
    worker_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    worker_name VARCHAR(255) NOT NULL UNIQUE,
    queue_name VARCHAR(255) NOT NULL,
    worker_host VARCHAR(255) NOT NULL,
    worker_pid INTEGER,
    worker_status worker_status DEFAULT 'RUNNING',
    current_job_id UUID,
    current_job_type VARCHAR(100),
    started_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    last_heartbeat TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    stopped_at TIMESTAMP WITH TIME ZONE,
    total_jobs_processed BIGINT DEFAULT 0,
    total_jobs_failed BIGINT DEFAULT 0,
    avg_processing_time_ms INTEGER,
    last_error TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_worker_heartbeat (last_heartbeat, worker_status),
    INDEX idx_worker_queue (queue_name, worker_status)
);

-- Table: PIPELINE_EXECUTION_LOGS
CREATE TABLE pipeline_execution_logs (
    execution_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    pipeline_name VARCHAR(255) NOT NULL,
    pipeline_type VARCHAR(50) CHECK (pipeline_type IN ('ETL', 'ELT', 'STREAMING', 'CDC')),
    execution_status pipeline_status DEFAULT 'PENDING',
    triggered_by VARCHAR(255),
    triggered_by_user UUID,
    started_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    completed_at TIMESTAMP WITH TIME ZONE,
    rows_read BIGINT,
    rows_written BIGINT,
    rows_rejected BIGINT,
    data_size_bytes BIGINT,
    error_message TEXT,
    error_details JSONB,
    execution_duration_ms INTEGER,
    retry_count INTEGER DEFAULT 0,
    checkpoint_location VARCHAR(500),
    metadata JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_pipeline_name (pipeline_name, started_at DESC),
    INDEX idx_pipeline_status (execution_status, started_at),
    INDEX idx_pipeline_time (started_at)
);

-- Table: SLA_BREACH_LOGS
CREATE TABLE sla_breach_logs (
    breach_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    sla_name VARCHAR(255) NOT NULL,
    sla_tier VARCHAR(50),
    tenant_id UUID,
    metric_name VARCHAR(255) NOT NULL,
    expected_value NUMERIC(10,2),
    actual_value NUMERIC(10,2),
    breach_threshold NUMERIC(10,2),
    breach_severity alert_severity DEFAULT 'WARNING',
    breach_started_at TIMESTAMP WITH TIME ZONE NOT NULL,
    breach_resolved_at TIMESTAMP WITH TIME ZONE,
    resolution_duration_seconds INTEGER,
    auto_credit_issued BOOLEAN DEFAULT false,
    auto_credit_amount NUMERIC(10,2),
    customer_notified_at TIMESTAMP WITH TIME ZONE,
    incident_ticket_id VARCHAR(255),
    root_cause TEXT,
    remediation_plan TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_sla_breach_tenant (tenant_id, breach_started_at),
    INDEX idx_sla_breach_unresolved (breach_resolved_at) WHERE breach_resolved_at IS NULL
);

-- Table: FEATURE_FLAG_EVALUATION_LOGS (sampled for analytics)
CREATE TABLE feature_flag_evaluation_logs (
    evaluation_id BIGSERIAL PRIMARY KEY,
    flag_key VARCHAR(255) NOT NULL,
    flag_variant VARCHAR(100),
    user_id UUID,
    tenant_id UUID,
    evaluation_result BOOLEAN NOT NULL,
    evaluation_context JSONB,
    evaluation_latency_ms INTEGER,
    sampling_weight INTEGER DEFAULT 1,
    evaluated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_flag_evaluations (flag_key, evaluated_at DESC),
    INDEX idx_flag_user (user_id, flag_key, evaluated_at)
);

-- Table: CACHE_WARMING_JOBS
CREATE TABLE cache_warming_jobs (
    job_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    cache_name VARCHAR(255) NOT NULL,
    warming_schedule VARCHAR(100),  -- cron expression
    query_pattern TEXT NOT NULL,
    parameters JSONB,
    priority INTEGER DEFAULT 5,
    status VARCHAR(50) DEFAULT 'PENDING',
    triggered_by VARCHAR(100),
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    keys_loaded INTEGER DEFAULT 0,
    keys_failed INTEGER DEFAULT 0,
    job_duration_ms INTEGER,
    last_error TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_warming_status (status, priority),
    INDEX idx_warming_cache (cache_name)
);

