-- ENUM: dsar_status for Data Subject Access Requests
CREATE TYPE dsar_status AS ENUM ('PENDING', 'IN_PROGRESS', 'AWAITING_USER', 'COMPLETED', 'REJECTED', 'EXPIRED');

-- Table: DATA_SUBJECT_REQUESTS (GDPR/CCPA DSAR workflow)
CREATE TABLE data_subject_requests (
    request_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    request_type VARCHAR(50) CHECK (request_type IN ('ACCESS', 'DELETION', 'PORTABILITY', 'RECTIFICATION', 'RESTRICTION')),
    request_status dsar_status DEFAULT 'PENDING',
    request_details JSONB,
    verification_method VARCHAR(50) CHECK (verification_method IN ('EMAIL', 'ID_DOCUMENT', 'SIGNED_STATEMENT')),
    verification_proof TEXT,
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    deadline_at TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (submitted_at + INTERVAL '30 days') STORED,
    completed_at TIMESTAMP WITH TIME ZONE,
    data_discovered JSONB,                               -- Summary of found data
    data_export_url TEXT,                                -- For portability requests
    deletion_performed BOOLEAN DEFAULT false,
    anonymization_performed BOOLEAN DEFAULT false,
    legal_hold_exceptions JSONB,                         -- Data preserved for legal reasons
    rejection_reason TEXT,
    fulfillment_notes TEXT,
    privacy_officer_notes TEXT,
    audit_trail JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_dsar_user (user_id, request_status),
    INDEX idx_dsar_deadline (deadline_at) WHERE request_status = 'PENDING'
);

-- Table: EXPERIMENT_METRIC_FACTS (aggregated daily for statistical engines)
CREATE TABLE experiment_metric_facts (
    fact_id BIGSERIAL PRIMARY KEY,
    experiment_id UUID NOT NULL REFERENCES experiment_definitions(experiment_id),
    variant_name VARCHAR(100) NOT NULL,
    metric_date DATE NOT NULL,
    user_count INTEGER NOT NULL,
    metric_name VARCHAR(255) NOT NULL,
    metric_value NUMERIC(20,4),
    metric_sum NUMERIC(20,4),
    metric_min NUMERIC(20,4),
    metric_max NUMERIC(20,4),
    metric_count INTEGER,
    confidence_interval_lower NUMERIC(10,4),
    confidence_interval_upper NUMERIC(10,4),
    p_value NUMERIC(10,6),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    UNIQUE(experiment_id, variant_name, metric_date, metric_name),
    INDEX idx_experiment_facts (experiment_id, metric_date, metric_name)
);

-- Table: WORKFLOW_EXECUTION_INSTANCES (runtime state for workflow_definitions)
CREATE TABLE workflow_execution_instances (
    instance_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    workflow_definition_id UUID NOT NULL REFERENCES workflow_definitions(workflow_id),
    workflow_version INTEGER NOT NULL,
    workflow_key VARCHAR(255) NOT NULL,

    -- Current state
    current_step_id VARCHAR(255),
    step_state JSONB,
    workflow_context JSONB,                               -- Business data
    workflow_status VARCHAR(50) DEFAULT 'RUNNING' CHECK (workflow_status IN
        ('RUNNING', 'COMPLETED', 'FAILED', 'CANCELLED', 'ESCALATED')),

    -- Assignments
    assignees JSONB,                                      -- Current step assignees
    completed_assignees JSONB,                            -- Historical assignments

    -- Timing
    started_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    completed_at TIMESTAMP WITH TIME ZONE,
    last_activity_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    sla_deadline TIMESTAMP WITH TIME ZONE,
    sla_breached BOOLEAN DEFAULT false,

    -- Escalation tracking
    escalation_count INTEGER DEFAULT 0,
    last_escalation_at TIMESTAMP WITH TIME ZONE,

    -- Audit
    execution_trace JSONB,                                -- Complete step history
    error_message TEXT,
    created_by UUID NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_workflow_instances (workflow_key, workflow_status),
    INDEX idx_workflow_assignees USING gin(assignees),
    INDEX idx_workflow_sla (sla_deadline) WHERE workflow_status = 'RUNNING'
);

-- Table: RECOMMENDATION_TRAINING_DATASETS (snapshots for ML retraining)
CREATE TABLE recommendation_training_datasets (
    dataset_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    dataset_name VARCHAR(255) NOT NULL,
    dataset_version INTEGER NOT NULL,
    model_type VARCHAR(100) NOT NULL,                    -- collaboration, content-based, hybrid
    training_data_url TEXT NOT NULL,
    validation_data_url TEXT,
    test_data_url TEXT,
    data_schema JSONB,
    data_start_date DATE NOT NULL,
    data_end_date DATE NOT NULL,
    row_count BIGINT,
    feature_count INTEGER,
    data_quality_score NUMERIC(5,2),
    sampling_method VARCHAR(100),
    sampling_rate NUMERIC(5,4),
    created_by VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    expires_at TIMESTAMP WITH TIME ZONE,

    INDEX idx_training_datasets (model_type, data_end_date DESC)
);

-- Table: BACKUP_RESTORE_JOBS (PITR tracking, WAL archive, verification)
CREATE TABLE backup_restore_jobs (
    job_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    job_type VARCHAR(50) CHECK (job_type IN ('BACKUP', 'RESTORE', 'VERIFY', 'PITR_RECOVER')),
    backup_type VARCHAR(50) CHECK (backup_type IN ('FULL', 'INCREMENTAL', 'WAL', 'SNAPSHOT')),

    -- Source/target
    source_database VARCHAR(255),
    target_location VARCHAR(500),
    wal_archive_location VARCHAR(500),

    -- Point-in-time recovery
    pitr_target_time TIMESTAMP WITH TIME ZONE,
    pitr_actual_time TIMESTAMP WITH TIME ZONE,

    -- Status
    status VARCHAR(50) DEFAULT 'PENDING',
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    backup_size_bytes BIGINT,
    wal_segments_archived INTEGER,
    recovery_wal_lsn VARCHAR(255),

    -- Verification
    verification_result BOOLEAN,
    verification_checksum VARCHAR(255),
    restore_test_completed BOOLEAN DEFAULT false,
    restore_test_duration_ms INTEGER,

    -- Errors
    error_message TEXT,
    retry_count INTEGER DEFAULT 0,

    -- Metadata
    triggered_by VARCHAR(255),
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_backup_jobs (status, started_at DESC),
    INDEX idx_backup_time (pitr_target_time) WHERE pitr_target_time IS NOT NULL
);

