-- =============================================================================
-- SUBSCRIPTION & BILLING CORE TABLES
-- Phase: Revenue & Subscription Management
-- =============================================================================

--------------------------------------------------------------------------------
-- ENUM: subscription_status
-- Description: Subscription lifecycle states for recurring billing
-- Business Case: Enables dunning management and revenue recognition
-- Feature Reference: SUB-05 (Subscription State Management)
--------------------------------------------------------------------------------
CREATE TYPE subscription_status AS ENUM (
    'TRIALING',         -- In trial period, not yet billed
    'ACTIVE',           -- Active subscription, billing normally
    'PAST_DUE',         -- Payment failed, grace period active
    'CANCELED',         -- Canceled by user or admin
    'UNPAID',           -- Payment failed beyond grace period
    'INCOMPLETE',       -- Initial payment pending/failed
    'INCOMPLETE_EXPIRED',-- Incomplete checkout expired
    'PAUSED'            -- Temporarily paused by user
);

--------------------------------------------------------------------------------
-- ENUM: billing_cycle
-- Description: Billing frequency for subscription plans
-- Business Case: Supports diverse pricing models (monthly, annual, custom)
-- Feature Reference: SUB-03 (Flexible Billing Cycles)
--------------------------------------------------------------------------------
CREATE TYPE billing_cycle AS ENUM (
    'MONTHLY',          -- Billed every month
    'QUARTERLY',        -- Billed every 3 months
    'SEMI_ANNUAL',      -- Billed every 6 months
    'ANNUAL',           -- Billed once per year
    'BIENNIAL',         -- Billed every 2 years
    'CUSTOM'            -- Custom interval (for enterprise)
);

--------------------------------------------------------------------------------
-- ENUM: invoice_status
-- Description: Invoice lifecycle states
-- Business Case: Enables automated collections and accounting reconciliation
-- Feature Reference: INV-08 (Invoice Status Tracking)
--------------------------------------------------------------------------------
CREATE TYPE invoice_status AS ENUM (
    'DRAFT',            -- Being prepared, not final
    'OPEN',             -- Issued, awaiting payment
    'PAID',             -- Payment received
    'UNCOLLECTIBLE',    -- Written off as bad debt
    'VOID',             -- Invalid/canceled invoice
    'REFUNDED',         -- Full refund issued
    'PARTIALLY_REFUNDED',-- Partial refund issued
    'MARKED_UNCOLLECTIBLE' -- Accounting write-off
);

--------------------------------------------------------------------------------
-- ENUM: payment_status
-- Description: Payment transaction states
-- Business Case: Tracks payment processing and reconciliation
-- Feature Reference: PAY-04 (Payment State Machine)
--------------------------------------------------------------------------------
CREATE TYPE payment_status AS ENUM (
    'REQUIRES_PAYMENT_METHOD',  -- Needs payment method added
    'REQUIRES_CONFIRMATION',    -- Awaiting confirmation (3D Secure)
    'REQUIRES_ACTION',          -- Additional action needed
    'PROCESSING',               -- Being processed
    'SUCCEEDED',                -- Payment successful
    'FAILED',                   -- Payment failed
    'REFUNDED',                 -- Fully refunded
    'PARTIALLY_REFUNDED',       -- Partially refunded
    'DISPUTED',                 -- In chargeback/dispute
    'CANCELED'                  -- Canceled before completion
);

--------------------------------------------------------------------------------
-- ENUM: payment_method_type
-- Description: Payment method categories for token routing
-- Business Case: Enables processor-specific handling and fraud scoring
-- Feature Reference: PAY-09 (Payment Method Routing)
--------------------------------------------------------------------------------
CREATE TYPE payment_method_type AS ENUM (
    'CREDIT_CARD',      -- Visa, Mastercard, Amex, etc.
    'DEBIT_CARD',       -- Debit card
    'BANK_ACCOUNT',     -- ACH/SEPA direct debit
    'DIGITAL_WALLET',   -- PayPal, Apple Pay, Google Pay
    'CRYPTO',           -- Cryptocurrency
    'INVOICE'           -- Net terms billing
);

--------------------------------------------------------------------------------
-- ENUM: metering_unit
-- Description: Units for usage-based billing measurement
-- Business Case: Supports various pricing models (API calls, storage, users)
-- Feature Reference: USAGE-04 (Unit Standardization)
--------------------------------------------------------------------------------
CREATE TYPE metering_unit AS ENUM (
    'API_CALL',         -- Per API request
    'GB_STORAGE',       -- Gigabyte of storage
    'USER_SEAT',        -- Per user per month
    'JOB_POSTING',      -- Per job posting
    'CONNECTION',       -- Per network connection
    'MESSAGE',          -- Per message sent
    'SEARCH_QUERY',     -- Per search operation
    'CUSTOM'            -- Custom unit for enterprise
);

--------------------------------------------------------------------------------
-- Table: SUBSCRIPTION_PLANS
-- Serial No: TBL-025
-- Description: Defines pricing tiers, features, and trial rules for subscription products
--
-- Business Case (300 words):
-- For a professional network with multiple user segments (job seekers, recruiters,
-- enterprises), subscription plans are the primary revenue driver. Without a
-- centralized plan definition system, pricing changes require code deployment,
-- feature entitlement logic is scattered across services, and A/B testing new
-- pricing models becomes impossible. This results in billing errors, customer
-- confusion, and lost revenue opportunities.
--
-- This table serves as the source of truth for all subscription products. Each
-- plan defines its billing cycle (monthly, annual), base price in multiple
-- currencies, trial eligibility (e.g., 14-day free trial for new users), and
-- feature entitlements via JSONB. Feature entitlements control product access:
-- "premium_job_search: true", "max_connections: 500", "export_limit: 1000/month".
--
-- The system supports plan hierarchy for upgrades/downgrades: a Professional plan
-- might upgrade to Business plan, with prorated billing differences. Plan
-- visibility can be restricted by region (e.g., GDPR-compliant plans for EU) or
-- user segment (internal vs public plans). The `sort_order` column controls
-- pricing page display order.
--
-- For enterprise sales, custom plans allow negotiated pricing and custom feature
-- bundles. The table supports multiple pricing models: flat rate, per-seat,
-- usage-based, and hybrid (base + overage). Integration with billing systems
-- (Stripe, Chargebee, Recurly) maps plan IDs to external provider plan IDs.
--
-- Compliance requirements include tax support (VAT, GST, sales tax) with different
-- rates per jurisdiction. The `is_active` flag enables plan deprecation without
-- affecting existing subscribers on grandfathered plans. A/B testing support
-- allows testing different price points by assigning users to different plan
-- configurations.
--
-- Feature References:
-- PLAN-01: Multi-tier subscription definition
-- PLAN-02: Feature entitlement JSONB (flexible schema)
-- PLAN-03: Multiple billing cycles
-- PLAN-04: Multi-currency pricing
-- PLAN-05: Trial period configuration
-- PLAN-06: Plan upgrade/downgrade paths
-- PLAN-07: Custom enterprise plans
-- PLAN-08: Regional pricing variations
-- PLAN-09: A/B testing support
-- PLAN-10: Tax rate configuration
-- PLAN-11: Grandfathered plan support
-- PLAN-12: Usage-based pricing models
--
-- Key Performance Indicators (KPIs):
-- 1. Plan Conversion Rate - % free to paid within trial period
-- 2. Average Revenue Per User (ARPU) - By plan tier
-- 3. Plan Churn Rate - % subscribers canceling per plan
-- 4. Upgrade Velocity - Time from signup to upgrade
-- 5. Pricing Elasticity - Conversion rate by price point
-- 6. Feature Adoption Rate - % using premium features
-- 7. Trial Conversion by Plan - % converting after trial
-- 8. Enterprise Sales Cycle - Days from quote to subscription
-- 9. Plan Profitability - Margin by tier
-- 10. Grandfathered User Count - Users on deprecated plans
--------------------------------------------------------------------------------
CREATE TABLE subscription_plans (
    -- Primary identifier
    plan_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Plan identification
    plan_code VARCHAR(100) NOT NULL UNIQUE,          -- e.g., "pro_monthly", "business_annual"
    plan_name VARCHAR(255) NOT NULL,
    plan_description TEXT,
    plan_display_name VARCHAR(255),                  -- Customer-facing name

    -- Categorization
    plan_category VARCHAR(50) CHECK (plan_category IN ('FREE', 'PERSONAL', 'PROFESSIONAL', 'BUSINESS', 'ENTERPRISE', 'CUSTOM')),
    visibility VARCHAR(50) DEFAULT 'PUBLIC' CHECK (visibility IN ('PUBLIC', 'INTERNAL', 'ENTERPRISE_ONLY', 'BETA')),

    -- Feature entitlements (flexible JSONB schema)
    feature_entitlements JSONB NOT NULL DEFAULT '{}'::JSONB,
    -- Example: {"job_search_limit": "unlimited", "contacts_limit": 500, "analytics": true, "api_access": "basic"}

    -- Billing configuration
    billing_cycle billing_cycle NOT NULL,
    billing_interval_count INTEGER DEFAULT 1,        -- e.g., every 2 months
    billing_anchor_day INTEGER CHECK (billing_anchor_day BETWEEN 1 AND 28), -- Day of month for billing

    -- Pricing (multiple currencies)
    base_price NUMERIC(10,2) NOT NULL,
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    setup_fee NUMERIC(10,2) DEFAULT 0,
    per_seat_price NUMERIC(10,2),                   -- For per-seat pricing

    -- Regional pricing overrides
    regional_pricing JSONB DEFAULT '{}'::JSONB,      -- {"EUR": {"price": 12.99, "currency": "EUR"}}

    -- Trial configuration
    trial_days INTEGER DEFAULT 0,
    trial_requires_payment_method BOOLEAN DEFAULT true,

    -- Usage-based overage
    overage_config JSONB,                            -- {"type": "flat_fee", "rate": 0.10, "unit": "api_call"}

    -- Quota configuration
    included_usage JSONB,                            -- {"api_calls": 10000, "storage_gb": 10, "users": 5}

    -- Upgrade/downgrade paths
    upgrade_target_plan_ids UUID[],                  -- Allowed upgrade destinations
    downgrade_target_plan_ids UUID[],                -- Allowed downgrade destinations
    proration_mode VARCHAR(50) DEFAULT 'PRORATE' CHECK (proration_mode IN ('PRORATE', 'FULL_REFUND', 'NONE')),

    -- Tax configuration
    tax_category VARCHAR(100),                       -- Physical goods, digital service, etc.
    tax_rates JSONB,                                 -- Per jurisdiction tax rates

    -- External system mapping
    external_provider_id VARCHAR(255),               -- Stripe price ID, etc.
    external_provider_name VARCHAR(50),              -- stripe, chargebee, recurly
    external_product_id VARCHAR(255),

    -- Status and ordering
    is_active BOOLEAN DEFAULT true,
    is_addon BOOLEAN DEFAULT false,                  -- Additional feature add-on
    sort_order INTEGER DEFAULT 999,
    featured BOOLEAN DEFAULT false,

    -- Metadata
    metadata JSONB DEFAULT '{}'::JSONB,
    tags TEXT[],

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT plan_price_check CHECK (base_price >= 0),
    CONSTRAINT plan_trial_check CHECK (trial_days >= 0),
    CONSTRAINT plan_interval_check CHECK (billing_interval_count >= 1),

    INDEX idx_subscription_plans_code (plan_code, is_active),
    INDEX idx_subscription_plans_category (plan_category, billing_cycle, is_active),
    INDEX idx_subscription_plans_price (base_price, currency),
    INDEX idx_subscription_plans_sort (sort_order, featured, is_active),
    INDEX idx_subscription_plans_external (external_provider_id, external_provider_name)
);

-- Partial index for active plans only
CREATE INDEX CONCURRENTLY idx_plans_active ON subscription_plans (plan_code, plan_category, billing_cycle, base_price)
    WHERE is_active = true;

-- GIN indexes for JSON fields
CREATE INDEX idx_plans_entitlements ON subscription_plans USING gin(feature_entitlements);
CREATE INDEX idx_plans_regional_pricing ON subscription_plans USING gin(regional_pricing);
CREATE INDEX idx_plans_upgrade_targets ON subscription_plans USING gin(upgrade_target_plan_ids);

COMMENT ON TABLE subscription_plans IS 'Multi-tier subscription product catalog with feature entitlements and pricing strategies';
COMMENT ON COLUMN subscription_plans.feature_entitlements IS 'JSONB schema defining feature access for this plan';
COMMENT ON COLUMN subscription_plans.regional_pricing IS 'Country/region-specific pricing overrides';
COMMENT ON COLUMN subscription_plans.overage_config IS 'Configuration for usage-based overage billing';

-- Row Level Security
ALTER TABLE subscription_plans ENABLE ROW LEVEL SECURITY;

CREATE POLICY plans_readonly_policy ON subscription_plans
    FOR SELECT USING (visibility IN ('PUBLIC', 'BETA') OR current_setting('app.is_billing_admin', true)::BOOLEAN = true);

--------------------------------------------------------------------------------
-- Table: SUBSCRIPTIONS
-- Serial No: TBL-026
-- Description: Tracks user subscriptions with billing cycles and status
-- Business Case: Core to recurring revenue management
--
-- Business Case (300 words):
-- Subscriptions are the lifeblood of SaaS revenue. Without systematic subscription
-- tracking, organizations cannot bill customers correctly, handle failed payments,
-- process prorated upgrades/downgrades, or comply with revenue recognition
-- standards (ASC 606). For a professional network with millions of subscribers,
-- manual subscription management is impossible.
--
-- This table implements comprehensive subscription lifecycle management. Each
-- subscription record links a user/tenant to a plan with billing period tracking
-- (current_period_start, current_period_end), trial information, and cancelation
-- handling (cancel_at_period_end). The status field implements dunning logic:
-- when payments fail, status transitions from ACTIVE → PAST_DUE → UNPAID,
-- with automated retry schedules and customer notifications.
--
-- The system supports multi-currency subscriptions with exchange rate tracking
-- for international customers. Proration calculations for mid-period changes
-- use the subscription's anchor dates and remaining period value. For enterprise
-- customers with multiple seats, the subscription tracks seat count changes
-- and per-seat pricing.
--
-- Integration with payment gateways maintains external subscription IDs to
-- synchronize status between systems (e.g., Stripe webhooks update local
-- subscription when payment succeeds). The system handles payment method updates,
-- trial extensions for goodwill, and subscription pausing for seasonal businesses.
--
-- For compliance (ASC 606), the subscription tracks revenue recognition milestones.
-- For churn analysis, the `canceled_at` and `cancellation_reason` columns power
-- retention analytics. The table supports retroactive subscription changes for
-- customer support (e.g., backdating a plan change after billing error).
--
-- Feature References:
-- SUB-01: Subscription lifecycle tracking
-- SUB-02: Billing period management
-- SUB-04: Trial management and conversion
-- SUB-06: Dunning workflow integration
-- SUB-07: Proration calculations
-- SUB-08: Multi-currency support
-- SUB-09: Seat management
-- SUB-10: Payment gateway synchronization
-- SUB-11: Subscription pausing
-- SUB-12: Retroactive changes
--------------------------------------------------------------------------------
CREATE TABLE subscriptions (
    -- Primary identifier
    subscription_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Customer links
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    plan_id UUID NOT NULL REFERENCES subscription_plans(plan_id),

    -- Subscription details
    subscription_number VARCHAR(100) GENERATED ALWAYS AS (
        'SUB-' || LPAD(EXTRACT(YEAR FROM created_at)::TEXT, 4, '0') || '-' ||
        LPAD(subscription_id::TEXT, 10, '0')
    ) STORED UNIQUE,

    -- Status lifecycle
    status subscription_status NOT NULL DEFAULT 'TRIALING',
    status_reason TEXT,                                   -- Payment failure reason, cancellation reason

    -- Seats/quantity
    quantity INTEGER DEFAULT 1 CHECK (quantity > 0),
    seat_assignments JSONB,                               -- Which users/teams have seats

    -- Billing periods
    current_period_start TIMESTAMP WITH TIME ZONE NOT NULL,
    current_period_end TIMESTAMP WITH TIME ZONE NOT NULL,
    trial_start TIMESTAMP WITH TIME ZONE,
    trial_end TIMESTAMP WITH TIME ZONE,

    -- Cancelation handling
    cancel_at_period_end BOOLEAN DEFAULT false,
    canceled_at TIMESTAMP WITH TIME ZONE,
    cancellation_reason TEXT,
    cancellation_reason_code VARCHAR(100),

    -- Pause handling
    paused_at TIMESTAMP WITH TIME ZONE,
    paused_resume_at TIMESTAMP WITH TIME ZONE,
    pause_reason TEXT,

    -- Pricing at subscription time (immutable snapshot)
    subscribed_price NUMERIC(10,2) NOT NULL,
    subscribed_currency CHAR(3) NOT NULL,
    subscribed_billing_cycle billing_cycle NOT NULL,

    -- Multi-currency exchange rates at billing time
    exchange_rate NUMERIC(10,6),
    base_amount_usd NUMERIC(10,2) GENERATED ALWAYS AS (
        subscribed_price / NULLIF(exchange_rate, 1.0)
    ) STORED,                                              -- For revenue reporting

    -- Metering and overage
    current_usage_cycle_start TIMESTAMP WITH TIME ZONE,
    current_usage_cycle_end TIMESTAMP WITH TIME ZONE,
    overage_billed_to_date NUMERIC(10,2) DEFAULT 0,

    -- Payment method
    payment_method_id UUID,
    default_payment_method_token VARCHAR(255),

    -- Trial handling
    trial_used BOOLEAN DEFAULT false,
    trial_converted_at TIMESTAMP WITH TIME ZONE,

    -- External system sync
    external_subscription_id VARCHAR(255),
    external_provider VARCHAR(50),                        -- stripe, chargebee, recurly
    last_sync_at TIMESTAMP WITH TIME ZONE,
    last_sync_status VARCHAR(50),

    -- Dunning (failed payment handling)
    dunning_attempts INTEGER DEFAULT 0,
    dunning_last_attempt_at TIMESTAMP WITH TIME ZONE,
    dunning_next_attempt_at TIMESTAMP WITH TIME ZONE,
    dunning_grace_days_remaining INTEGER,

    -- Revenue recognition (ASC 606)
    revenue_recognition_start TIMESTAMP WITH TIME ZONE,
    revenue_recognition_end TIMESTAMP WITH TIME ZONE,
    recognized_revenue_to_date NUMERIC(10,2) DEFAULT 0,

    -- Metadata
    metadata JSONB DEFAULT '{}'::JSONB,
    tags TEXT[],
    notes TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT subscription_period_check CHECK (current_period_end > current_period_start),
    CONSTRAINT subscription_trial_check CHECK (trial_end IS NULL OR trial_end > trial_start),
    CONSTRAINT subscription_price_check CHECK (subscribed_price >= 0),
    CONSTRAINT subscription_status_valid CHECK (
        (status = 'TRIALING' AND trial_end IS NOT NULL AND trial_end > NOW()) OR
        (status != 'TRIALING')
    ),

    FOREIGN KEY (user_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

-- Critical indexes for subscription queries
CREATE INDEX idx_subscriptions_user ON subscriptions (user_id, tenant_id, status);
CREATE INDEX idx_subscriptions_status ON subscriptions (status, current_period_end) WHERE status IN ('ACTIVE', 'PAST_DUE');
CREATE INDEX idx_subscriptions_period ON subscriptions (current_period_start, current_period_end);
CREATE INDEX idx_subscriptions_plan ON subscriptions (plan_id, status);
CREATE INDEX idx_subscriptions_external ON subscriptions (external_subscription_id) WHERE external_subscription_id IS NOT NULL;

-- Partial index for active subscriptions (most common query)
CREATE INDEX CONCURRENTLY idx_subscriptions_active ON subscriptions (user_id, tenant_id, current_period_end)
    WHERE status IN ('ACTIVE', 'TRIALING');

-- Partial index for dunning management
CREATE INDEX CONCURRENTLY idx_subscriptions_dunning ON subscriptions (dunning_next_attempt_at, dunning_attempts)
    WHERE status = 'PAST_DUE' AND dunning_attempts < 5;

-- Comments for documentation
COMMENT ON TABLE subscriptions IS 'Complete subscription lifecycle tracking with billing periods, dunning, and revenue recognition';
COMMENT ON COLUMN subscriptions.subscribed_price IS 'Snapshot of plan price at subscription time for historical accuracy';
COMMENT ON COLUMN subscriptions.cancel_at_period_end IS 'True if cancellation is scheduled for end of billing period';
COMMENT ON COLUMN subscriptions.dunning_grace_days_remaining IS 'Days left before subscription moves to UNPAID status';

-- Row Level Security
ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;

CREATE POLICY subscriptions_self_policy ON subscriptions
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

CREATE POLICY subscriptions_tenant_admin_policy ON subscriptions
    USING (tenant_id = current_setting('app.current_tenant_id', true)::UUID);

--------------------------------------------------------------------------------
-- Table: INVOICES
-- Description: Legal billing documents with line-item breakdowns
--------------------------------------------------------------------------------
CREATE TABLE invoices (
    -- Primary identifier
    invoice_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Invoice identification
    invoice_number VARCHAR(100) NOT NULL UNIQUE,
    invoice_display_number VARCHAR(100) GENERATED ALWAYS AS (
        'INV-' || LPAD(EXTRACT(YEAR FROM created_at)::TEXT, 4, '0') || '-' ||
        LPAD(EXTRACT(MONTH FROM created_at)::TEXT, 2, '0') || '-' ||
        LPAD(CAST(EXTRACT(EPOCH FROM created_at) AS TEXT), 8, '0')
    ) STORED,

    -- Customer links
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    subscription_id UUID REFERENCES subscriptions(subscription_id),

    -- Denormalized customer info for delivery (snapshot at invoice time)
    customer_email VARCHAR(255) NOT NULL,
    customer_name VARCHAR(255),
    customer_tax_id VARCHAR(100),
    customer_address JSONB,

    -- Invoice details
    status invoice_status NOT NULL DEFAULT 'DRAFT',
    invoice_type VARCHAR(50) CHECK (invoice_type IN ('RECURRING', 'ONE_TIME', 'REFUND', 'CREDIT_NOTE', 'OVERAGE')),

    -- Dates
    invoice_date DATE NOT NULL DEFAULT CURRENT_DATE,
    due_date DATE NOT NULL,
    paid_at TIMESTAMP WITH TIME ZONE,
    voided_at TIMESTAMP WITH TIME ZONE,
    void_reason TEXT,

    -- Amounts
    subtotal NUMERIC(10,2) NOT NULL,
    tax_amount NUMERIC(10,2) DEFAULT 0,
    discount_amount NUMERIC(10,2) DEFAULT 0,
    total_amount NUMERIC(10,2) NOT NULL,
    amount_paid NUMERIC(10,2) DEFAULT 0,
    amount_due NUMERIC(10,2) GENERATED ALWAYS AS (total_amount - amount_paid) STORED,

    -- Currency
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    exchange_rate NUMERIC(10,6),

    -- Tax breakdown (jurisdiction-specific)
    tax_breakdown JSONB,                                 -- {"VAT": {"rate": 0.20, "amount": 20.00}, "GST": ...}

    -- Line items summary (redundant for quick access)
    line_items_summary JSONB,                            -- {"subscription": {"amount": 99.00}, "overage": {"amount": 5.50}}

    -- Billing period (for recurring invoices)
    period_start DATE,
    period_end DATE,

    -- Payment details
    payment_instructions TEXT,
    payment_terms VARCHAR(50) DEFAULT 'NET_15',

    -- PDF generation
    pdf_url TEXT,
    pdf_generated_at TIMESTAMP WITH TIME ZONE,

    -- Email delivery
    email_sent_at TIMESTAMP WITH TIME ZONE,
    email_delivery_status VARCHAR(50),
    email_error_message TEXT,

    -- Late fee tracking
    late_fee_amount NUMERIC(10,2) DEFAULT 0,
    late_fee_applied_at TIMESTAMP WITH TIME ZONE,

    -- Collection (dunning) tracking
    collection_attempts INTEGER DEFAULT 0,
    last_collection_attempt_at TIMESTAMP WITH TIME ZONE,

    -- External system
    external_invoice_id VARCHAR(255),
    external_provider VARCHAR(50),

    -- Metadata
    metadata JSONB DEFAULT '{}'::JSONB,
    notes TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT invoice_amounts_check CHECK (subtotal >= 0 AND tax_amount >= 0 AND discount_amount >= 0 AND total_amount >= 0),
    CONSTRAINT invoice_dates_check CHECK (due_date >= invoice_date),
    CONSTRAINT invoice_status_date_check CHECK (
        (status != 'PAID' OR paid_at IS NOT NULL) AND
        (status != 'VOID' OR voided_at IS NOT NULL)
    ),

    INDEX idx_invoices_user (user_id, tenant_id, invoice_date DESC),
    INDEX idx_invoices_status (status, due_date) WHERE status = 'OPEN',
    INDEX idx_invoices_subscription (subscription_id),
    INDEX idx_invoices_external (external_invoice_id),
    INDEX idx_invoices_number (invoice_number)
);

-- Partial index for open invoices (collections)
CREATE INDEX CONCURRENTLY idx_invoices_collections ON invoices (due_date, total_amount, amount_paid, collection_attempts)
    WHERE status = 'OPEN' AND amount_due > 0 AND due_date < NOW();

COMMENT ON TABLE invoices IS 'Legal billing documents with comprehensive tax handling and collections tracking';
COMMENT ON COLUMN invoices.tax_breakdown IS 'Per-jurisdiction tax breakdown for compliance reporting';
COMMENT ON COLUMN invoices.line_items_summary IS 'Denormalized line item summary for quick invoice rendering';

--------------------------------------------------------------------------------
-- Table: INVOICE_LINE_ITEMS
-- Description: Line-by-line breakdown of invoice charges
--------------------------------------------------------------------------------
CREATE TABLE invoice_line_items (
    line_item_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    invoice_id UUID NOT NULL REFERENCES invoices(invoice_id) ON DELETE CASCADE,

    -- Line item identification
    line_item_type VARCHAR(50) CHECK (line_item_type IN
        ('SUBSCRIPTION', 'PRORATION', 'OVERAGE', 'TAX', 'DISCOUNT', 'CREDIT', 'LATE_FEE', 'SETUP_FEE')),

    -- Description
    description TEXT NOT NULL,
    period_start DATE,
    period_end DATE,

    -- Quantity and unit
    quantity NUMERIC(10,4) DEFAULT 1,
    unit_price NUMERIC(10,4) NOT NULL,
    unit_price_currency CHAR(3) DEFAULT 'USD',
    unit_name VARCHAR(50),                               -- "month", "api_call", "gb_storage"

    -- Amounts
    amount NUMERIC(10,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
    tax_amount NUMERIC(10,2) DEFAULT 0,
    discount_amount NUMERIC(10,2) DEFAULT 0,
    total_amount NUMERIC(10,2) GENERATED ALWAYS AS (amount + tax_amount - discount_amount) STORED,

    -- Tax details (per line item)
    tax_rate NUMERIC(5,4),
    tax_jurisdiction VARCHAR(100),
    tax_exempt_reason TEXT,

    -- Reference to source (for audit)
    source_type VARCHAR(50),                             -- subscription, invoice, payment
    source_id UUID,

    -- Sorting
    line_sort_order INTEGER DEFAULT 0,

    -- Metadata
    metadata JSONB,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_line_items_invoice (invoice_id, line_sort_order),
    INDEX idx_line_items_source (source_type, source_id)
);

COMMENT ON TABLE invoice_line_items IS 'Granular line items for invoice auditing and breakdown';

--------------------------------------------------------------------------------
-- Table: PAYMENT_METHODS
-- Description: PCI-compliant payment method token storage
--------------------------------------------------------------------------------
CREATE TABLE payment_methods (
    payment_method_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Customer links
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,

    -- Payment method type
    payment_method_type payment_method_type NOT NULL,

    -- Tokenized payment info (never store raw PAN)
    gateway_token VARCHAR(255) NOT NULL,                 -- Provider token (Stripe PaymentMethod ID)
    gateway_customer_id VARCHAR(255),                    -- Provider customer ID

    -- Display-friendly card info (last4 only)
    last4 VARCHAR(4),                                    -- Only for cards
    card_brand VARCHAR(20),                              -- visa, mastercard, amex
    exp_month INTEGER CHECK (exp_month BETWEEN 1 AND 12),
    exp_year INTEGER CHECK (exp_year >= 2000),

    -- Bank account info (partial)
    bank_name VARCHAR(255),
    bank_account_last4 VARCHAR(4),
    bank_account_type VARCHAR(20),                       -- checking, savings

    -- Billing address
    billing_address JSONB,

    -- Status
    is_default BOOLEAN DEFAULT false,
    is_verified BOOLEAN DEFAULT false,                   -- For ACH/micro-deposits
    is_expired BOOLEAN DEFAULT false,

    -- Metadata
    metadata JSONB,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID NOT NULL,

    CONSTRAINT payment_method_unique_default UNIQUE (user_id, tenant_id, is_default) WHERE is_default = true,

    INDEX idx_payment_methods_user (user_id, tenant_id, is_default),
    INDEX idx_payment_methods_gateway (gateway_token, gateway_customer_id),
    INDEX idx_payment_methods_expiry (exp_year, exp_month)
);

COMMENT ON TABLE payment_methods IS 'PCI-compliant payment method storage with tokenized provider references';
COMMENT ON COLUMN payment_methods.gateway_token IS 'Provider token (Stripe PaymentMethod ID) - never store raw PAN';

--------------------------------------------------------------------------------
-- Table: PAYMENTS
-- Description: Payment transaction tracking with reconciliation support
--------------------------------------------------------------------------------
CREATE TABLE payments (
    -- Primary identifier
    payment_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Payment identification
    payment_number VARCHAR(100) UNIQUE,
    idempotency_key UUID UNIQUE,                         -- Prevent duplicate processing

    -- Customer links
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    invoice_id UUID REFERENCES invoices(invoice_id),
    subscription_id UUID REFERENCES subscriptions(subscription_id),
    payment_method_id UUID REFERENCES payment_methods(payment_method_id),

    -- Payment details
    amount NUMERIC(10,2) NOT NULL,
    currency CHAR(3) NOT NULL DEFAULT 'USD',
    payment_status payment_status NOT NULL,

    -- Payment type
    payment_type VARCHAR(50) CHECK (payment_type IN
        ('RECURRING', 'ONE_TIME', 'REFUND', 'CREDIT_BALANCE', 'LATE_FEE', 'OVERAGE')),

    -- Gateway response
    gateway_transaction_id VARCHAR(255) NOT NULL,
    gateway_response_code VARCHAR(50),
    gateway_response_message TEXT,
    gateway_response_full JSONB,                         -- Full provider response (audit)

    -- Timing
    payment_date TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    settled_at TIMESTAMP WITH TIME ZONE,
    failed_at TIMESTAMP WITH TIME ZONE,
    failure_reason TEXT,
    failure_code VARCHAR(50),

    -- Fee tracking (for reconciliation)
    gateway_fee_amount NUMERIC(10,2),
    gateway_fee_currency CHAR(3),
    net_amount NUMERIC(10,2),

    -- Refund tracking
    refunded_amount NUMERIC(10,2) DEFAULT 0,
    refunded_at TIMESTAMP WITH TIME ZONE,
    refund_reason TEXT,
    refund_idempotency_key UUID,

    -- Dispute tracking
    disputed_at TIMESTAMP WITH TIME ZONE,
    dispute_reason VARCHAR(100),
    dispute_amount NUMERIC(10,2),
    dispute_outcome VARCHAR(50),                         -- won, lost, pending
    dispute_resolution_date DATE,

    -- Metadata
    metadata JSONB,
    billing_agreement_id VARCHAR(255),                   -- For recurring payments

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID NOT NULL,

    -- Partition key
    payment_year INTEGER GENERATED ALWAYS AS (EXTRACT(YEAR FROM payment_date)) STORED,
    payment_month INTEGER GENERATED ALWAYS AS (EXTRACT(MONTH FROM payment_date)) STORED,

    INDEX idx_payments_user (user_id, payment_date DESC),
    INDEX idx_payments_invoice (invoice_id),
    INDEX idx_payments_status (payment_status, payment_date),
    INDEX idx_payments_gateway (gateway_transaction_id),
    INDEX idx_payments_idempotency (idempotency_key),
    INDEX idx_payments_refund (refund_idempotency_key)
) PARTITION BY RANGE (payment_year, payment_month);

-- Create monthly partitions (example)
CREATE TABLE payments_2024_01 PARTITION OF payments FOR VALUES FROM (2024, 1) TO (2024, 2);

COMMENT ON TABLE payments IS 'Monthly partitioned payment transactions with refund and dispute tracking';
COMMENT ON COLUMN payments.idempotency_key IS 'UUID to prevent duplicate payment processing';

--------------------------------------------------------------------------------
-- Table: USAGE_METERING
-- Description: Tracks API calls, storage, and feature usage for overage billing
--------------------------------------------------------------------------------
CREATE TABLE usage_metering (
    -- Primary identifier
    usage_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Customer links
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    subscription_id UUID REFERENCES subscriptions(subscription_id),

    -- Usage type
    meter_type VARCHAR(100) NOT NULL,                    -- api_calls, storage_gb, search_queries
    meter_unit metering_unit NOT NULL,

    -- Usage values
    counter_value NUMERIC(20,4) NOT NULL,
    delta_value NUMERIC(20,4) NOT NULL,                  -- Change since last report

    -- Time window
    usage_start TIMESTAMP WITH TIME ZONE NOT NULL,
    usage_end TIMESTAMP WITH TIME ZONE NOT NULL,
    reset_at TIMESTAMP WITH TIME ZONE,                   -- When this counter resets

    -- Alerting
    alert_threshold_pct INTEGER,                         -- 0-100, trigger at % of quota
    alert_sent_at TIMESTAMP WITH TIME ZONE,

    -- Quota context (snapshot at usage time)
    plan_quota NUMERIC(20,4),                            -- Included in plan
    overage_rate NUMERIC(10,6),                          -- Per-unit overage cost

    -- Reconciliation
    reconciled BOOLEAN DEFAULT false,                    -- Billed yet?
    reconciled_at TIMESTAMP WITH TIME ZONE,
    invoice_line_item_id UUID,                           -- Link to invoice line item

    -- Metadata
    metadata JSONB,
    source_ip INET,
    correlation_id UUID,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_usage_metering_user (user_id, meter_type, usage_end DESC),
    INDEX idx_usage_metering_period (usage_start, usage_end),
    INDEX idx_usage_metering_reconciliation (reconciled, created_at),
    INDEX idx_usage_metering_reset (reset_at) WHERE reset_at IS NOT NULL
);

-- BRIN index for time-range queries (space-efficient for high-volume)
CREATE INDEX idx_usage_metering_brin ON usage_metering USING brin(usage_start, usage_end, created_at);

-- Partial index for unreconciled usage
CREATE INDEX CONCURRENTLY idx_usage_unreconciled ON usage_metering (user_id, meter_type, usage_end)
    WHERE reconciled = false;

COMMENT ON TABLE usage_metering IS 'Usage tracking for consumption-based billing with alerting thresholds';
COMMENT ON COLUMN usage_metering.counter_value IS 'Absolute counter value (e.g., total API calls this period)';
COMMENT ON COLUMN usage_metering.delta_value IS 'Change since last recording (atomic increment)';

-- Atomic increment function for usage metering
CREATE OR REPLACE FUNCTION increment_usage_counter(
    p_user_id UUID,
    p_tenant_id UUID,
    p_meter_type VARCHAR(100),
    p_delta_value NUMERIC,
    p_metadata JSONB DEFAULT '{}'
)
RETURNS NUMERIC
LANGUAGE plpgsql
AS $$
DECLARE
    v_subscription_id UUID;
    v_current_value NUMERIC;
    v_plan_quota NUMERIC;
    v_usage_period_start TIMESTAMP;
    v_usage_period_end TIMESTAMP;
BEGIN
    -- Get active subscription
    SELECT subscription_id, current_period_start, current_period_end
    INTO v_subscription_id, v_usage_period_start, v_usage_period_end
    FROM subscriptions
    WHERE user_id = p_user_id
      AND tenant_id = p_tenant_id
      AND status IN ('ACTIVE', 'TRIALING')
    ORDER BY current_period_start DESC
    LIMIT 1;

    IF v_subscription_id IS NULL THEN
        RETURN -1; -- No active subscription
    END IF;

    -- Atomic upsert and increment
    INSERT INTO usage_metering (
        user_id, tenant_id, subscription_id, meter_type, meter_unit,
        usage_start, usage_end, counter_value, delta_value, metadata
    )
    VALUES (
        p_user_id, p_tenant_id, v_subscription_id, p_meter_type,
        'API_CALL'::metering_unit,  -- Example default, adjust as needed
        v_usage_period_start, v_usage_period_end,
        p_delta_value, p_delta_value, p_metadata
    )
    ON CONFLICT ON CONSTRAINT (no constraint - handles via update)
    DO UPDATE SET
        counter_value = usage_metering.counter_value + EXCLUDED.delta_value,
        delta_value = EXCLUDED.delta_value,
        usage_end = EXCLUDED.usage_end
    WHERE usage_metering.user_id = EXCLUDED.user_id
      AND usage_metering.meter_type = EXCLUDED.meter_type
      AND usage_metering.usage_start = EXCLUDED.usage_start
    RETURNING counter_value INTO v_current_value;

    -- Check alert thresholds
    IF v_current_value > v_plan_quota * 0.90 THEN
        PERFORM pg_notify('usage_alert',
            jsonb_build_object('user_id', p_user_id, 'meter_type', p_meter_type,
                              'current_value', v_current_value, 'quota', v_plan_quota)::TEXT);
    END IF;

    RETURN v_current_value;
END;
$$;

-- Grant permissions
GRANT SELECT, INSERT, UPDATE ON subscription_plans, subscriptions, invoices, invoice_line_items,
    payment_methods, payments, usage_metering TO ap_application;
GRANT EXECUTE ON FUNCTION increment_usage_counter TO ap_application;



-- =============================================================================
-- DATA GOVERNANCE & COMPLIANCE TABLES (GDPR/CCPA)
-- Phase: Legal Compliance & Data Privacy
-- =============================================================================

--------------------------------------------------------------------------------
-- ENUM: retention_action
-- Description: Actions to take when data retention period expires
-- Business Case: Enables automated compliance with data minimization principles
-- Feature Reference: RET-04 (Expiration Action Types)
--------------------------------------------------------------------------------
CREATE TYPE retention_action AS ENUM (
    'DELETE',           -- Permanently delete data
    'ARCHIVE',          -- Move to cold storage
    'ANONYMIZE',        -- Remove PII but keep aggregates
    'REVIEW',           -- Flag for manual review
    'NOTIFY'            -- Send notification before action
);

--------------------------------------------------------------------------------
-- ENUM: dsar_request_type
-- Description: Types of Data Subject Access Requests under GDPR/CCPA
-- Business Case: Routes requests to appropriate fulfillment workflows
-- Feature Reference: DSAR-03 (Request Type Categorization)
--------------------------------------------------------------------------------
CREATE TYPE dsar_request_type AS ENUM (
    'ACCESS',           -- User requests copy of their data
    'DELETION',         -- Right to be forgotten
    'PORTABILITY',      -- Data export in machine-readable format
    'RECTIFICATION',    -- Correct inaccurate data
    'RESTRICTION',      -- Restrict processing
    'OBJECTION'         -- Object to processing
);

--------------------------------------------------------------------------------
-- ENUM: dsar_status
-- Description: Lifecycle states for DSAR fulfillment
-- Business Case: Tracks compliance with 30-day response deadline
-- Feature Reference: DSAR-06 (Status Tracking)
--------------------------------------------------------------------------------
CREATE TYPE dsar_status AS ENUM (
    'PENDING',          -- Request received, not yet processed
    'VERIFYING',        -- Verifying user identity
    'IN_PROGRESS',      -- Actively gathering data
    'AWAITING_USER',    -- Need additional info from user
    'COMPLETED',        -- Request fulfilled
    'PARTIAL',          -- Partially fulfilled (some data exempt)
    'REJECTED',         -- Legally rejected (with reason)
    'EXPIRED'           -- Deadline passed without completion
);

--------------------------------------------------------------------------------
-- ENUM: consent_purpose
-- Description: Specific purposes for which user consent is collected
-- Business Case: Granular consent management per processing activity
-- Feature Reference: CONSENT-04 (Purpose Granularity)
--------------------------------------------------------------------------------
CREATE TYPE consent_purpose AS ENUM (
    'MARKETING_EMAILS',     -- Promotional emails
    'PERSONALIZED_ADS',     -- Targeted advertising
    'ANALYTICS',            -- Product usage analytics
    'PROFILING',            -- User behavior profiling
    'THIRD_PARTY_SHARING',  -- Sharing with partners
    'CROSS_BORDER_TRANSFER' -- International data transfer
);

--------------------------------------------------------------------------------
-- Table: DATA_RETENTION_POLICIES
-- Serial No: TBL-027
-- Description: Defines TTL, archival, and deletion rules per table/column
--
-- Business Case (300 words):
-- Data minimization is a core GDPR principle: organizations must not retain
-- personal data longer than necessary. Without automated retention policies,
-- companies accumulate PII indefinitely, increasing breach risk, storage costs,
-- and non-compliance fines (up to €20 million). Manual deletion is error-prone
-- and unscalable for databases with billions of rows.
--
-- This table implements declarative retention policies per table, schema, or
-- column. Each policy defines retention duration (e.g., "delete inactive sessions
-- after 90 days", "anonymize logs after 30 days"), action on expiry (DELETE,
-- ARCHIVE, ANONYMIZE), and optional override reasons for legal holds. The system
-- automatically executes these policies via scheduled jobs, ensuring compliance
-- without developer intervention.
--
-- For multi-tenant systems, policies can apply globally or per tenant (e.g.,
-- EU tenants require stricter retention). The table supports conditional policies
-- based on row attributes (e.g., "retain financial records for 7 years, but only
-- if account_status != 'closed'"). The `override_reasons` column tracks legal
-- holds: when a retention policy is suspended for litigation, the reason and
-- author are recorded for audit purposes.
--
-- The system integrates with the legal hold framework: active legal holds
-- automatically override retention policies. Pre-deletion hooks enable data
-- classification reviews (e.g., ensure no PII remains before deletion). The
-- `action_on_expiry` supports ARCHIVE to cold storage (S3 Glacier) before
-- deletion, balancing compliance with cost optimization.
--
-- For operational visibility, the table tracks last execution time and rows
-- affected. Failed deletions are logged for manual intervention (e.g., foreign
-- key constraints blocking deletion). The policy engine supports dry-run mode
-- for impact analysis before production deployment.
--
-- Feature References:
-- RET-01: Table/column-level retention rules
-- RET-02: Conditional retention based on row attributes
-- RET-03: Legal hold override support
-- RET-05: Automated deletion jobs
-- RET-06: Archive to cold storage
-- RET-07: Pre-deletion validation hooks
-- RET-08: Multi-tenant policy isolation
-- RET-09: Dry-run impact analysis
-- RET-10: Retention audit trail
--
-- Key Performance Indicators (KPIs):
-- 1. Policy Coverage - % tables with retention rules (target 100%)
-- 2. Compliance Rate - % data deleted within required timeframe
-- 3. Storage Cost Reduction - % reduction from automated deletion
-- 4. Legal Hold Conflicts - # policies overridden by holds
-- 5. Deletion Job Success Rate - % successful vs failed deletions
-- 6. Policy Execution Time - Hours for full retention sweep
-- 7. Override Frequency - % policies overridden manually
-- 8. Archive-to-Delete Ratio - Archived vs directly deleted data
-- 9. Policy Staleness - Months since policy last reviewed
-- 10. Breach Risk Reduction - PII volume reduction
--------------------------------------------------------------------------------
CREATE TABLE data_retention_policies (
    -- Primary identifier
    policy_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Target definition
    target_schema VARCHAR(255) NOT NULL,
    target_table VARCHAR(255) NOT NULL,
    target_column VARCHAR(255),                           -- NULL = entire row
    condition_expression TEXT,                            -- WHERE clause for conditional retention

    -- Policy configuration
    retention_days INTEGER NOT NULL CHECK (retention_days > 0),
    action_on_expiry retention_action NOT NULL DEFAULT 'DELETE',

    -- Archive configuration (if action = ARCHIVE)
    archive_target VARCHAR(500),                          -- S3 path, cold storage
    archive_format VARCHAR(50) DEFAULT 'PARQUET',        -- PARQUET, CSV, JSONL
    archive_compression VARCHAR(20) DEFAULT 'GZIP',

    -- Anonymization rules (if action = ANONYMIZE)
    anonymization_rules JSONB,                           -- Column mapping to null/hash/mask

    -- Execution schedule
    cron_schedule VARCHAR(100) DEFAULT '0 2 * * *',      -- Daily at 2 AM
    batch_size INTEGER DEFAULT 10000,
    max_execution_time_seconds INTEGER DEFAULT 3600,

    -- Status
    is_active BOOLEAN DEFAULT true,
    is_enforced BOOLEAN DEFAULT true,                    -- False = monitoring only

    -- Legal hold override
    allow_legal_hold_override BOOLEAN DEFAULT true,
    active_override_reason TEXT,
    active_override_by UUID,
    active_override_at TIMESTAMP WITH TIME ZONE,

    -- Multi-tenant
    tenant_id UUID,                                       -- NULL = global policy

    -- Metadata
    priority INTEGER DEFAULT 5 CHECK (priority BETWEEN 1 AND 10),
    description TEXT,
    created_by UUID NOT NULL,

    -- Execution tracking
    last_executed_at TIMESTAMP WITH TIME ZONE,
    last_rows_deleted BIGINT,
    last_rows_archived BIGINT,
    last_error_message TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT retention_policy_unique UNIQUE (target_schema, target_table, target_column, tenant_id),
    CONSTRAINT retention_condition_check CHECK (
        condition_expression IS NULL OR
        condition_expression ~ '^[a-zA-Z0-9_<>=\s()''AND OR NOT]+$'
    ),

    INDEX idx_retention_policies_table (target_schema, target_table, is_active),
    INDEX idx_retention_policies_execution (is_active, is_enforced, last_executed_at),
    INDEX idx_retention_policies_tenant (tenant_id) WHERE tenant_id IS NOT NULL
);

COMMENT ON TABLE data_retention_policies IS 'Declarative retention policies for automated data lifecycle management';
COMMENT ON COLUMN data_retention_policies.condition_expression IS 'SQL WHERE clause for conditional retention (e.g., "status != ''closed''")';
COMMENT ON COLUMN data_retention_policies.action_on_expiry IS 'DELETE, ARCHIVE, or ANONYMIZE when retention period expires';

-- Row Level Security
ALTER TABLE data_retention_policies ENABLE ROW LEVEL SECURITY;

CREATE POLICY retention_policies_admin_policy ON data_retention_policies
    USING (current_setting('app.is_compliance_officer', true)::BOOLEAN = true);

--------------------------------------------------------------------------------
-- Table: DATA_SUBJECT_REQUESTS (Enhanced GDPR/CCPA DSAR)
-- Serial No: TBL-028
-- Description: Complete DSAR workflow with SLA tracking
--------------------------------------------------------------------------------
CREATE TABLE data_subject_requests (
    -- Primary identifier
    request_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    request_number VARCHAR(50) GENERATED ALWAYS AS (
        'DSAR-' || LPAD(EXTRACT(YEAR FROM created_at)::TEXT, 4, '0') || '-' ||
        LPAD(request_id::TEXT, 8, '0')
    ) STORED UNIQUE,

    -- User identification
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    requester_email VARCHAR(255) NOT NULL,

    -- Request details
    request_type dsar_request_type NOT NULL,
    request_status dsar_status DEFAULT 'PENDING',
    request_details JSONB,                               -- Specific data requested

    -- Verification
    verification_method VARCHAR(50) CHECK (verification_method IN ('EMAIL', 'ID_DOCUMENT', 'SIGNED_STATEMENT', 'KNOWN_DATA')),
    verification_proof TEXT,                             -- Uploaded doc reference
    verified_at TIMESTAMP WITH TIME ZONE,
    verified_by UUID,
    verification_notes TEXT,

    -- Timeline (GDPR requires response within 30 days)
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    deadline_at TIMESTAMP WITH TIME ZONE GENERATED ALWAYS AS (submitted_at + INTERVAL '30 days') STORED,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,

    -- SLA tracking
    sla_breach_alert_sent BOOLEAN DEFAULT false,
    sla_breach_notified_at TIMESTAMP WITH TIME ZONE,

    -- Data discovery results
    data_discovered JSONB,                               -- Summary by system/table
    data_volume_gb NUMERIC(10,2),
    record_count BIGINT,

    -- For ACCESS requests
    data_package_url TEXT,                               -- Secure download link
    data_package_expires_at TIMESTAMP WITH TIME ZONE,
    data_format VARCHAR(50) DEFAULT 'JSON',              -- JSON, CSV, XML

    -- For DELETION requests (right to be forgotten)
    deletion_performed BOOLEAN DEFAULT false,
    deletion_completed_at TIMESTAMP WITH TIME ZONE,
    deletion_method VARCHAR(50),                         -- HARD_DELETE, ANONYMIZE, SOFT_DELETE
    deletion_exceptions JSONB,                           -- Data kept for legal reasons

    -- For PORTABILITY requests
    portability_format VARCHAR(50) DEFAULT 'JSON',       -- JSON, CSV, XML
    portability_target TEXT,                             -- Direct transfer to third party

    -- For RECTIFICATION requests
    rectification_changes JSONB,                         -- Before/after data mapping

    -- Legal exceptions
    legal_exemptions JSONB,                              -- Data not provided due to legal exemption
    rejection_reason TEXT,                               -- If request rejected

    -- Processing metadata
    processing_notes TEXT,
    internal_ticket_id VARCHAR(255),                     -- Internal tracking
    assigned_to UUID,                                    -- Privacy team member

    -- Notifications
    acknowledgment_sent_at TIMESTAMP WITH TIME ZONE,
    reminder_sent_at TIMESTAMP WITH TIME ZONE,
    completion_notification_sent_at TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Indexes
    INDEX idx_dsar_user (user_id, request_status, submitted_at DESC),
    INDEX idx_dsar_deadline (deadline_at, request_status) WHERE request_status NOT IN ('COMPLETED', 'REJECTED', 'EXPIRED'),
    INDEX idx_dsar_type (request_type, request_status),

    FOREIGN KEY (user_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

-- Trigger for SLA breach alerts
CREATE OR REPLACE FUNCTION check_dsar_sla_breach()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.request_status NOT IN ('COMPLETED', 'REJECTED') AND
       NEW.deadline_at < NOW() AND
       NEW.sla_breach_alert_sent = false THEN
        -- Send alert (example using NOTIFY)
        PERFORM pg_notify('dsar_sla_breach',
            jsonb_build_object('request_id', NEW.request_id, 'user_id', NEW.user_id,
                              'deadline', NEW.deadline_at)::TEXT);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_dsar_sla_breach
    AFTER INSERT OR UPDATE OF request_status ON data_subject_requests
    FOR EACH ROW
    EXECUTE FUNCTION check_dsar_sla_breach();

COMMENT ON TABLE data_subject_requests IS 'GDPR/CCPA DSAR workflow with 30-day SLA tracking and legal exemptions';

--------------------------------------------------------------------------------
-- Table: CONSENT_RECORDS
-- Serial No: TBL-029
-- Description: Immutable user consent logs with version tracking
--------------------------------------------------------------------------------
CREATE TABLE consent_records (
    -- Primary identifier
    consent_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User identification
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,

    -- Consent purpose
    purpose_id consent_purpose NOT NULL,
    purpose_version VARCHAR(20) NOT NULL,                -- Version of consent text

    -- Consent state
    is_granted BOOLEAN NOT NULL,                         -- true = granted, false = withdrawn
    is_verified BOOLEAN DEFAULT false,                   -- Double opt-in verified

    -- Collection context
    collection_method VARCHAR(50) CHECK (collection_method IN
        ('CHECKBOX', 'EMAIL_CONFIRM', 'SIGNATURE', 'VERBAL', 'API', 'IMPLICIT')),
    collection_point VARCHAR(255),                       -- Where consent was collected (page/flow)
    consent_text_hash VARCHAR(255),                      -- Hash of consent text presented

    -- Technical metadata
    ip_address INET NOT NULL,
    user_agent TEXT,
    device_fingerprint VARCHAR(255),

    -- Geographic context
    geo_country VARCHAR(100),
    geo_region VARCHAR(100),

    -- Withdrawal metadata (if applicable)
    withdrawn_at TIMESTAMP WITH TIME ZONE,
    withdrawn_by UUID,
    withdrawal_method VARCHAR(50),
    withdrawal_reason TEXT,

    -- Refresh tracking
    refresh_token VARCHAR(255),                          -- For consent refresh workflows
    refresh_reminder_sent BOOLEAN DEFAULT false,
    refreshed_at TIMESTAMP WITH TIME ZONE,

    -- Legal basis
    legal_basis VARCHAR(100) DEFAULT 'CONSENT',
    legal_basis_details TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT consent_unique_active UNIQUE (user_id, tenant_id, purpose_id, purpose_version)
        WHERE is_granted = true,

    INDEX idx_consent_user (user_id, purpose_id, is_granted, created_at),
    INDEX idx_consent_purpose (purpose_id, is_granted),
    INDEX idx_consent_refresh (refresh_token) WHERE refresh_token IS NOT NULL
);

COMMENT ON TABLE consent_records IS 'Immutable user consent audit trail for GDPR/CCPA compliance';
COMMENT ON COLUMN consent_records.purpose_version IS 'Version of consent text presented to user';

-- Immutable trigger (prevent updates/deletes)
CREATE TRIGGER trg_consent_immutable
    BEFORE UPDATE OR DELETE ON consent_records
    FOR EACH ROW
    EXECUTE FUNCTION prevent_consent_modification();

--------------------------------------------------------------------------------
-- Table: DATA_PROCESSING_ACTIVITIES (GDPR Article 30 Register)
-- Serial No: TBL-030
-- Description: Register of processing activities for compliance audits
--------------------------------------------------------------------------------
CREATE TABLE data_processing_activities (
    -- Primary identifier
    activity_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    activity_number VARCHAR(50) UNIQUE,

    -- Activity identification
    activity_name VARCHAR(255) NOT NULL,
    activity_description TEXT NOT NULL,
    data_controller VARCHAR(255) NOT NULL,               -- Legal entity
    data_protection_officer UUID,                        -- DPO contact

    -- Data flow mapping
    data_sources JSONB NOT NULL,                         -- Where data originates
    data_transformations JSONB,                          -- ETL/processing steps
    data_destinations JSONB NOT NULL,                    -- Where data goes

    -- Data categories processed
    data_categories data_category[] NOT NULL,            -- PII, PCI, etc.
    special_categories JSONB,                            -- Health, biometric, etc.

    -- Legal basis
    legal_basis VARCHAR(100) NOT NULL CHECK (legal_basis IN
        ('CONSENT', 'CONTRACT', 'LEGAL_OBLIGATION', 'VITAL_INTERESTS',
         'PUBLIC_INTEREST', 'LEGITIMATE_INTERESTS')),
    legitimate_interests_assessment TEXT,                -- Required for legitimate interests
    consent_purpose_ids UUID[],                          -- Link to consent_records

    -- Processing details
    processing_purpose TEXT NOT NULL,
    processing_location VARCHAR(255),                    -- Geographic location of processing
    data_retention_period VARCHAR(100),                  -- Retention schedule reference
    automated_decision_making BOOLEAN DEFAULT false,
    profiling BOOLEAN DEFAULT false,
    profiling_logic TEXT,                                -- Explain profiling algorithms

    -- Data transfers
    international_transfers JSONB,                       -- Cross-border transfer details
    adequacy_decision VARCHAR(255),                      -- EU adequacy decision
    standard_contractual_clauses TEXT,

    -- Security measures
    technical_measures TEXT[],
    organizational_measures TEXT[],
    encryption_standard VARCHAR(100),

    -- Risk assessment (DPIA)
    dpia_required BOOLEAN DEFAULT false,
    dpia_completed BOOLEAN DEFAULT false,
    dpia_document_url TEXT,
    dpia_completed_date DATE,
    risk_level VARCHAR(50) CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),

    -- Third-party processors
    third_party_processors JSONB,                        -- List of sub-processors

    -- Compliance status
    is_active BOOLEAN DEFAULT true,
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    next_review_at TIMESTAMP WITH TIME ZONE,
    reviewed_by UUID,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    INDEX idx_processing_activities_controller (data_controller, is_active),
    INDEX idx_processing_activities_categories USING gin(data_categories)
);

COMMENT ON TABLE data_processing_activities IS 'GDPR Article 30 Register of Processing Activities for compliance audits';
COMMENT ON COLUMN data_processing_activities.data_sources IS 'Mapping of source systems and tables';
COMMENT ON COLUMN data_processing_activities.third_party_processors IS 'List of sub-processors and their processing purposes';

-- =============================================================================
-- WEBHOOK & EVENT DELIVERY TABLES
-- Phase: Integration Infrastructure
-- =============================================================================

--------------------------------------------------------------------------------
-- ENUM: webhook_status
-- Description: Webhook subscription and delivery states
-- Business Case: Enables circuit breaker patterns for failing webhooks
-- Feature Reference: WEB-07 (Circuit Breaker Integration)
--------------------------------------------------------------------------------
CREATE TYPE webhook_status AS ENUM (
    'ACTIVE',           -- Normal operation
    'PAUSED',           -- Temporarily paused (user action)
    'DISABLED',         -- Permanently disabled
    'RATE_LIMITED',     -- Exceeded rate limits
    'CIRCUIT_OPEN'      -- Too many failures, circuit breaker open
);

--------------------------------------------------------------------------------
-- Table: WEBHOOK_SUBSCRIPTIONS
-- Description: External event push infrastructure
--------------------------------------------------------------------------------
CREATE TABLE webhook_subscriptions (
    subscription_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Subscriber identification
    tenant_id UUID NOT NULL,
    created_by UUID NOT NULL,
    subscriber_name VARCHAR(255) NOT NULL,
    subscriber_email VARCHAR(255),                       -- For delivery failure notifications

    -- Webhook configuration
    webhook_url TEXT NOT NULL,
    webhook_secret VARCHAR(255) NOT NULL,                -- HMAC signing secret
    webhook_version VARCHAR(20) DEFAULT '1.0',

    -- Event filtering
    event_types TEXT[] NOT NULL,                         -- Which events to receive
    filter_conditions JSONB,                             -- JSONPath filters

    -- Retry configuration
    retry_count INTEGER DEFAULT 3,
    retry_backoff_seconds INTEGER[] DEFAULT ARRAY[60, 300, 900], -- 1min, 5min, 15min
    timeout_seconds INTEGER DEFAULT 10,

    -- Rate limiting
    rate_limit_per_minute INTEGER DEFAULT 100,
    rate_limit_per_hour INTEGER DEFAULT 1000,

    -- Circuit breaker
    circuit_failure_threshold INTEGER DEFAULT 5,         -- Failures before opening circuit
    circuit_timeout_seconds INTEGER DEFAULT 60,          -- Time before retry
    circuit_health_check_interval INTEGER DEFAULT 30,    -- Seconds between health checks

    -- Status
    status webhook_status DEFAULT 'ACTIVE',
    paused_at TIMESTAMP WITH TIME ZONE,
    paused_reason TEXT,

    -- Statistics
    total_deliveries BIGINT DEFAULT 0,
    total_successful BIGINT DEFAULT 0,
    total_failed BIGINT DEFAULT 0,
    total_latency_ms BIGINT DEFAULT 0,
    last_delivery_at TIMESTAMP WITH TIME ZONE,
    last_failure_at TIMESTAMP WITH TIME ZONE,
    last_failure_reason TEXT,
    current_failure_count INTEGER DEFAULT 0,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_webhook_subscriptions_tenant (tenant_id, status),
    INDEX idx_webhook_subscriptions_events USING gin(event_types),
    INDEX idx_webhook_subscriptions_circuit (status, current_failure_count, last_failure_at)
);

--------------------------------------------------------------------------------
-- Table: WEBHOOK_DELIVERY_LOGS (Partitioned by day)
-- Description: Complete webhook delivery history for debugging
--------------------------------------------------------------------------------
CREATE TABLE webhook_delivery_logs (
    delivery_id BIGSERIAL NOT NULL,
    subscription_id UUID NOT NULL REFERENCES webhook_subscriptions(subscription_id),

    -- Event details
    event_id UUID NOT NULL,
    event_type VARCHAR(255) NOT NULL,
    event_payload JSONB NOT NULL,

    -- Delivery attempt
    attempt_number INTEGER NOT NULL,
    request_headers JSONB,
    response_status_code INTEGER,
    response_body TEXT,

    -- Timing
    queued_at TIMESTAMP WITH TIME ZONE NOT NULL,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    delivery_duration_ms INTEGER,

    -- Outcome
    was_successful BOOLEAN NOT NULL,
    error_type VARCHAR(100),                             -- TIMEOUT, HTTP_ERROR, NETWORK
    error_message TEXT,

    -- Retry tracking
    will_retry BOOLEAN DEFAULT false,
    next_retry_at TIMESTAMP WITH TIME ZONE,

    -- Partition key
    delivery_date DATE GENERATED ALWAYS AS (DATE(queued_at)) STORED,

    PRIMARY KEY (delivery_id, delivery_date)
) PARTITION BY RANGE (delivery_date);

-- Create daily partitions (example)
CREATE TABLE webhook_delivery_logs_2024_01_01 PARTITION OF webhook_delivery_logs
    FOR VALUES FROM ('2024-01-01') TO ('2024-01-02');

-- Indexes
CREATE INDEX idx_webhook_delivery_subscription ON webhook_delivery_logs (subscription_id, queued_at DESC);
CREATE INDEX idx_webhook_delivery_event ON webhook_delivery_logs (event_id);
CREATE INDEX idx_webhook_delivery_failed ON webhook_delivery_logs (was_successful, queued_at) WHERE was_successful = false;

COMMENT ON TABLE webhook_delivery_logs IS 'Daily partitioned webhook delivery logs for audit and debugging';

-- =============================================================================
-- EXPERIMENT & WORKFLOW TRACKING TABLES
-- Phase: Analytics & Process Automation
-- =============================================================================

--------------------------------------------------------------------------------
-- Table: EXPERIMENT_METRICS
-- Description: Business metrics per variant for A/B test analysis
--------------------------------------------------------------------------------
CREATE TABLE experiment_metrics (
    metric_id BIGSERIAL PRIMARY KEY,

    -- Experiment context
    experiment_id UUID NOT NULL REFERENCES experiment_definitions(experiment_id),
    variant_name VARCHAR(100) NOT NULL,
    user_id UUID,
    session_id UUID,

    -- Metric details
    metric_name VARCHAR(255) NOT NULL,
    metric_value NUMERIC(20,4) NOT NULL,
    metric_type VARCHAR(50) CHECK (metric_type IN ('COUNT', 'SUM', 'AVG', 'CONVERSION', 'DURATION')),

    -- Weight (for conversion metrics)
    weight NUMERIC(10,4) DEFAULT 1.0,

    -- Timestamp
    occurred_at TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Partition by week
    metric_week DATE GENERATED ALWAYS AS (DATE_TRUNC('week', occurred_at)) STORED,

    INDEX idx_experiment_metrics_lookup (experiment_id, variant_name, metric_name, occurred_at),
    INDEX idx_experiment_metrics_user (user_id, experiment_id)
) PARTITION BY RANGE (metric_week);

COMMENT ON TABLE experiment_metrics IS 'Business metric values for A/B test statistical analysis';

--------------------------------------------------------------------------------
-- ENUM: workflow_instance_status
-- Description: Runtime status for workflow execution instances
-- Business Case: Enables escalation and SLA monitoring
-- Feature Reference: WF-INS-05 (Status Management)
--------------------------------------------------------------------------------
CREATE TYPE workflow_instance_status AS ENUM (
    'PENDING',          -- Created but not started
    'RUNNING',          -- Actively executing
    'WAITING',          -- Awaiting user action
    'COMPLETED',        -- Successfully finished
    'FAILED',           -- Terminal failure
    'CANCELLED',        -- User/Admin cancelled
    'ESCALATED'         -- Escalated due to timeout
);

--------------------------------------------------------------------------------
-- Table: WORKFLOW_INSTANCES
-- Description: Runtime execution of workflow_definitions
--------------------------------------------------------------------------------
CREATE TABLE workflow_instances (
    instance_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    workflow_definition_id UUID NOT NULL REFERENCES workflow_definitions(workflow_id),
    workflow_version INTEGER NOT NULL,

    -- Business context
    correlation_id UUID,                                 -- Business entity ID
    payload JSONB NOT NULL,                              -- Workflow input data
    context JSONB DEFAULT '{}',                          -- Runtime context

    -- Status tracking
    status workflow_instance_status DEFAULT 'PENDING',
    current_step_id VARCHAR(255),
    completed_steps TEXT[] DEFAULT '{}',

    -- Assignment
    assignee_id UUID,                                    -- Current assignee
    assignee_group VARCHAR(255),

    -- SLA and deadlines
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    sla_deadline TIMESTAMP WITH TIME ZONE,
    sla_breached BOOLEAN DEFAULT false,

    -- Escalation
    escalation_count INTEGER DEFAULT 0,
    last_escalation_at TIMESTAMP WITH TIME ZONE,
    escalation_reason TEXT,

    -- Audit
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_workflow_instances_status (status, sla_deadline) WHERE status IN ('RUNNING', 'WAITING', 'PENDING'),
    INDEX idx_workflow_instances_assignee (assignee_id, status)
);

--------------------------------------------------------------------------------
-- Table: WORKFLOW_STEPS
-- Description: Individual step execution within workflow instances
--------------------------------------------------------------------------------
CREATE TABLE workflow_steps (
    step_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    instance_id UUID NOT NULL REFERENCES workflow_instances(instance_id) ON DELETE CASCADE,

    -- Step identification
    step_definition_id VARCHAR(255) NOT NULL,
    step_name VARCHAR(255) NOT NULL,
    step_type workflow_step_type NOT NULL,

    -- Execution details
    step_input JSONB,
    step_output JSONB,
    step_status workflow_instance_status DEFAULT 'PENDING',

    -- Assignment (for user tasks)
    assignee_id UUID,
    assignee_email VARCHAR(255),
    assignment_expires_at TIMESTAMP WITH TIME ZONE,

    -- Timing
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    step_duration_ms INTEGER,

    -- SLA per step
    step_sla_deadline TIMESTAMP WITH TIME ZONE,
    step_sla_breached BOOLEAN DEFAULT false,

    -- Retry count (for failed automated steps)
    retry_count INTEGER DEFAULT 0,
    max_retries INTEGER DEFAULT 3,
    last_error TEXT,

    INDEX idx_workflow_steps_instance (instance_id, step_number),
    INDEX idx_workflow_steps_assignee (assignee_id, step_status)
);

ALTER TABLE workflow_steps ADD COLUMN step_number INTEGER NOT NULL;

-- =============================================================================
-- SERVICE HEALTH & MODERATION TABLES
-- Phase: Operations & Content Governance
-- =====================================================================================================================================================
-- Table: SERVICE_HEALTH_STATUS
-- Description: Internal service endpoint monitoring
--------------------------------------------------------------------------------
CREATE TABLE service_health_status (
    check_id BIGSERIAL PRIMARY KEY,

    -- Service identification
    service_name VARCHAR(255) NOT NULL,
    service_environment VARCHAR(50) NOT NULL,            -- prod, staging, dev
    endpoint_url TEXT NOT NULL,
    endpoint_type VARCHAR(50) CHECK (endpoint_type IN ('HTTP', 'GRPC', 'KAFKA', 'RABBITMQ')),

    -- Health metrics
    status health_status NOT NULL,
    response_time_ms INTEGER,
    status_code INTEGER,

    -- Performance
    latency_p50_ms INTEGER,
    latency_p95_ms INTEGER,
    latency_p99_ms INTEGER,
    error_rate_1min NUMERIC(5,4),
    throughput_rps NUMERIC(10,2),

    -- Error details
    error_message TEXT,
    error_type VARCHAR(100),

    -- Dependency health (cascading failures)
    dependent_services TEXT[],

    -- Check context
    checked_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    check_duration_ms INTEGER,
    monitoring_region VARCHAR(50),                       -- Which region performed check

    INDEX idx_service_health (service_name, service_environment, checked_at DESC),
    INDEX idx_service_health_status (status, checked_at),
    INDEX idx_service_health_time (checked_at DESC)
);

COMMENT ON TABLE service_health_status IS 'Internal service health monitoring for proactive incident detection';

--------------------------------------------------------------------------------
-- Table: MODERATION_ACTIONS
-- Description: Audit trail of moderator decisions
--------------------------------------------------------------------------------
CREATE TABLE moderation_actions (
    action_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Content identification
    content_id VARCHAR(255) NOT NULL,
    content_type VARCHAR(50) NOT NULL,
    queue_id UUID REFERENCES content_moderation_queues(moderation_id),

    -- Action details
    action_type moderation_action NOT NULL,
    action_reason TEXT NOT NULL,
    action_reason_code VARCHAR(100),                     -- Policy violation code

    -- Moderator
    moderator_id UUID NOT NULL,
    moderator_notes TEXT,
    moderator_confidence INTEGER CHECK (moderator_confidence BETWEEN 1 AND 5),

    -- Automated vs manual
    was_automated BOOLEAN DEFAULT false,
    automation_rule VARCHAR(255),
    automation_confidence NUMERIC(5,2),

    -- Timing
    actioned_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    -- Notification
    user_notified BOOLEAN DEFAULT false,
    user_notification_sent_at TIMESTAMP WITH TIME ZONE,

    -- Reversal (if action was overturned)
    reversed_at TIMESTAMP WITH TIME ZONE,
    reversed_by UUID,
    reversal_reason TEXT,

    INDEX idx_moderation_actions_content (content_id, content_type, actioned_at),
    INDEX idx_moderation_actions_moderator (moderator_id, actioned_at)
);

--------------------------------------------------------------------------------
-- Table: MODERATION_APPEALS
-- Description: User appeals against moderation decisions
--------------------------------------------------------------------------------
CREATE TABLE moderation_appeals (
    appeal_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    action_id UUID NOT NULL REFERENCES moderation_actions(action_id),

    -- Appellant
    user_id UUID NOT NULL,
    appeal_reason TEXT NOT NULL,
    appeal_evidence TEXT,                                -- User-provided evidence URL

    -- Status
    appeal_status VARCHAR(50) DEFAULT 'PENDING' CHECK (appeal_status IN ('PENDING', 'APPROVED', 'REJECTED', 'ESCALATED')),

    -- Review
    reviewed_by UUID,
    reviewed_at TIMESTAMP WITH TIME ZONE,
    review_decision TEXT,
    review_notes TEXT,

    -- Timelines
    submitted_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    sla_deadline TIMESTAMP WITH TIME ZONE,               -- Response by (e.g., 7 days)

    -- Auto-escalation
    escalated_at TIMESTAMP WITH TIME ZONE,
    escalated_to UUID,

    INDEX idx_moderation_appeals_user (user_id, appeal_status),
    INDEX idx_moderation_appeals_action (action_id),
    INDEX idx_moderation_appeals_sla (sla_deadline, appeal_status) WHERE appeal_status = 'PENDING'
);

-- =============================================================================
-- FEATURE FLAG & SEARCH SYNC TABLES
-- Phase: Feature Management & Search Infrastructure
-- =============================================================================

--------------------------------------------------------------------------------
-- Table: FEATURE_FLAG_EVALUATIONS (Partitioned by day)
-- Description: Logs flag checks for analytics and debugging
--------------------------------------------------------------------------------
CREATE TABLE feature_flag_evaluations (
    evaluation_id BIGSERIAL NOT NULL,

    -- Flag context
    flag_key VARCHAR(255) NOT NULL,
    flag_variant VARCHAR(100),

    -- User context
    user_id UUID,
    tenant_id UUID,
    session_id UUID,

    -- Evaluation result
    evaluation_result BOOLEAN NOT NULL,
    evaluation_context JSONB,                            -- User attributes at evaluation time

    -- Performance
    evaluation_latency_ms INTEGER,

    -- Sampling (1% sampling for high-volume flags)
    sampling_weight INTEGER DEFAULT 1,

    -- Timing
    evaluated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    evaluation_day DATE GENERATED ALWAYS AS (DATE(evaluated_at)) STORED,

    PRIMARY KEY (evaluation_id, evaluation_day)
) PARTITION BY RANGE (evaluation_day);

COMMENT ON TABLE feature_flag_evaluations IS 'Sampled feature flag evaluation logs for analytics and performance monitoring';

--------------------------------------------------------------------------------
-- ENUM: sync_operation
-- Description: Search index synchronization operations
-- Feature Reference: SEARCH-SYNC-03 (Operation Types)
--------------------------------------------------------------------------------
CREATE TYPE sync_operation AS ENUM (
    'INDEX',            -- Add/update document
    'DELETE',           -- Remove document
    'REINDEX'           -- Full reindex required
);

--------------------------------------------------------------------------------
-- Table: SEARCH_SYNC_QUEUE
-- Description: Tracks content changes needing search index updates
--------------------------------------------------------------------------------
CREATE TABLE search_sync_queue (
    queue_id BIGSERIAL PRIMARY KEY,

    -- Entity identification
    entity_type VARCHAR(100) NOT NULL,                   -- user, job, company, post
    entity_id VARCHAR(255) NOT NULL,
    entity_version INTEGER,                              -- Optimistic locking

    -- Sync operation
    operation sync_operation NOT NULL,
    payload JSONB,                                       -- Full document snapshot

    -- Status tracking
    status VARCHAR(50) DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'SKIPPED')),

    -- Retry handling
    retry_count INTEGER DEFAULT 0,
    max_retries INTEGER DEFAULT 3,
    last_error TEXT,

    -- Timing
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    processing_started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,

    -- Worker assignment (SKIP LOCKED for concurrent processing)
    locked_by VARCHAR(255),
    locked_at TIMESTAMP WITH TIME ZONE,
    lock_expires_at TIMESTAMP WITH TIME ZONE,

    -- Partition key
    created_date DATE GENERATED ALWAYS AS (DATE(created_at)) STORED,

    INDEX idx_search_sync_pending (status, created_at, retry_count) WHERE status = 'PENDING',
    INDEX idx_search_sync_entity (entity_type, entity_id),
    INDEX idx_search_sync_locks (locked_by, lock_expires_at) WHERE locked_by IS NOT NULL
) PARTITION BY RANGE (created_date);

COMMENT ON TABLE search_sync_queue IS 'Queue for async search index updates with retry and dead-letter handling';

-- =============================================================================
-- BACKUP & DISASTER RECOVERY TABLES
-- Phase: DR Compliance & RPO/RTO Tracking
-- =============================================================================

--------------------------------------------------------------------------------
-- ENUM: backup_type
-- Description: Database backup methodologies
-- Feature Reference: DR-02 (Backup Strategy Types)
--------------------------------------------------------------------------------
CREATE TYPE backup_type AS ENUM (
    'FULL',             -- Full database backup
    'INCREMENTAL',      -- Incremental since last full
    'DIFFERENTIAL',     -- Changes since last full
    'WAL_ARCHIVE',      -- Write-ahead log segments
    'SNAPSHOT'          -- Cloud provider snapshot
);

--------------------------------------------------------------------------------
-- Table: BACKUP_METADATA
-- Description: Tracks database backups for DR compliance
--------------------------------------------------------------------------------
CREATE TABLE backup_metadata (
    backup_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    backup_name VARCHAR(255) NOT NULL,
    backup_type backup_type NOT NULL,

    -- Backup location
    backup_url TEXT NOT NULL,                             -- S3/GCS/Azure path
    backup_region VARCHAR(100),
    storage_class VARCHAR(50) DEFAULT 'STANDARD',         -- STANDARD, GLACIER, DEEP_ARCHIVE

    -- Size and content
    size_bytes BIGINT,
    compressed_size_bytes BIGINT,
    tables_included TEXT[],

    -- Timing
    started_at TIMESTAMP WITH TIME ZONE NOT NULL,
    completed_at TIMESTAMP WITH TIME ZONE,
    backup_duration_seconds INTEGER,

    -- Point-in-time recovery
    wal_lsn_start VARCHAR(255),
    wal_lsn_end VARCHAR(255),
    pitr_timestamp TIMESTAMP WITH TIME ZONE,              -- Recoverable to this time

    -- Status
    status VARCHAR(50) NOT NULL CHECK (status IN ('RUNNING', 'SUCCESS', 'FAILED', 'VERIFYING', 'VERIFIED')),
    error_message TEXT,

    -- Retention
    retention_until TIMESTAMP WITH TIME ZONE NOT NULL,
    is_deleted BOOLEAN DEFAULT false,
    deleted_at TIMESTAMP WITH TIME ZONE,

    -- Verification (for DR readiness)
    last_verified_at TIMESTAMP WITH TIME ZONE,
    verification_restore_time_ms INTEGER,
    verification_checksum VARCHAR(255),

    -- Metadata
    database_version VARCHAR(50),
    postgres_version VARCHAR(50),
    created_by VARCHAR(255),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_backup_metadata_status (status, retention_until),
    INDEX idx_backup_metadata_time (started_at DESC),
    INDEX idx_backup_metadata_pitr (pitr_timestamp)
);

COMMENT ON TABLE backup_metadata IS 'Database backup tracking for DR compliance and PITR recovery';

--------------------------------------------------------------------------------
-- Table: RESTORE_LOGS
-- Description: Records restore operations for audit and DR testing
--------------------------------------------------------------------------------
CREATE TABLE restore_logs (
    restore_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    backup_id UUID REFERENCES backup_metadata(backup_id),

    -- Restore details
    restore_type VARCHAR(50) CHECK (restore_type IN ('DR_TEST', 'PRODUCTION_RECOVERY', 'POINT_IN_TIME', 'STAGING_REFRESH')),
    target_environment VARCHAR(50),                      -- staging, production, dr

    -- Point-in-time target (for PITR)
    pitr_target_time TIMESTAMP WITH TIME ZONE,
    pitr_actual_time TIMESTAMP WITH TIME ZONE,

    -- Timing
    started_at TIMESTAMP WITH TIME ZONE NOT NULL,
    completed_at TIMESTAMP WITH TIME ZONE,
    restore_duration_seconds INTEGER,

    -- Outcome
    was_successful BOOLEAN NOT NULL,
    error_message TEXT,
    data_verified BOOLEAN DEFAULT false,

    -- Data consistency
    row_count_before BIGINT,
    row_count_after BIGINT,
    consistency_checksum VARCHAR(255),

    -- Auditor
    restored_by UUID NOT NULL,
    restore_reason TEXT,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_restore_logs_backup (backup_id),
    INDEX idx_restore_logs_time (started_at DESC)
);

COMMENT ON TABLE restore_logs IS 'Audit trail of restore operations for DR compliance testing';

-- Grant all permissions
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO ap_application;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO ap_application;



--------------------------------------------------------------------------------
-- AI identified gaps and recommended tables list below
--------------------------------------------------------------------------------
-- =============================================================================
-- AI CAREER INTELLIGENCE TABLES
-- Phase: Advanced Analytics & Personalization
-- =============================================================================

--------------------------------------------------------------------------------
-- ENUM: career_path_confidence
-- Description: Confidence levels for career path predictions
-- Business Case: Enables users to assess prediction reliability for decision-making
-- Feature Reference: CPS-06 (Confidence Scoring)
--------------------------------------------------------------------------------
CREATE TYPE career_path_confidence AS ENUM (
    'EXPERIMENTAL',     -- Low confidence, emerging role
    'EMERGING',         -- Growing trend but limited data
    'ESTABLISHED',      -- Well-understood path with ample data
    'HIGHLY_RELIABLE'   -- High confidence based on market patterns
);

--------------------------------------------------------------------------------
-- ENUM: skill_gap_priority
-- Description: Priority levels for skill gap recommendations
-- Business Case: Guides users on which skills to acquire first
-- Feature Reference: SGA-04 (Priority Scoring)
--------------------------------------------------------------------------------
CREATE TYPE skill_gap_priority AS ENUM (
    'CRITICAL',         -- Required for target role, immediate need
    'HIGH',             -- Important, should acquire soon
    'MEDIUM',           -- Beneficial but not urgent
    'LOW'               -- Nice to have, low impact
);

--------------------------------------------------------------------------------
-- ENUM: learning_resource_type
-- Description: Types of learning resources for skill acquisition
-- Business Case: Matches user learning preferences with available content
-- Feature Reference: SGA-07 (Resource Recommendations)
--------------------------------------------------------------------------------
CREATE TYPE learning_resource_type AS ENUM (
    'COURSE',           -- Structured online course
    'MICRO_LEARNING',   -- Bite-sized (<15 min) modules
    'PROJECT',          -- Hands-on project
    'ARTICLE',          -- Technical blog post
    'VIDEO_TUTORIAL',   -- Video-based instruction
    'CERTIFICATION',    -- Formal certification program
    'INTERNSHIP',       -- Practical work experience
    'MENTORSHIP'        -- One-on-one guidance
);

--------------------------------------------------------------------------------
-- ENUM: recommendation_explainability_type
-- Description: Types of AI recommendation explanations
-- Business Case: Provides transparent AI decision-making for user trust
-- Feature Reference: AIR-09 (Explanation Taxonomy)
--------------------------------------------------------------------------------
CREATE TYPE recommendation_explainability_type AS ENUM (
    'FEATURE_IMPACT',   -- Which skills/attributes influenced score
    'COUNTERFACTUAL',   -- "If you had skill X, score would increase by Y%"
    'SIMILAR_USERS',    -- Users with similar profiles succeeded
    'MARKET_DEMAND',    -- High demand in current market
    'TRAJECTORY',       -- Users with this path advanced within Z months
    'MULTI_FACTOR'      -- Combined explanation with weighted factors
);

--------------------------------------------------------------------------------
-- ENUM: market_trend_direction
-- Description: Direction of market demand trends
-- Business Case: Indicates growth or decline for career guidance
-- Feature Reference: CPS-09 (Trend Analysis)
--------------------------------------------------------------------------------
CREATE TYPE market_trend_direction AS ENUM (
    'SURGING',          -- Demand growing rapidly (>20% YoY)
    'GROWING',          -- Steady growth (5-20% YoY)
    'STABLE',           -- Flat demand (-5% to 5% YoY)
    'DECLINING',        -- Decreasing demand (5-20% YoY)
    'SHRINKING'         -- Rapid decline (>20% YoY)
);

--------------------------------------------------------------------------------
-- Table: CAREER_PATH_SIMULATIONS
-- Serial No: TBL-031
-- Description: Predicts optimal next roles based on skills, market demand, and user trajectory
--
-- Business Case (300 words):
-- Traditional job platforms show static listings, leaving users to guess which roles
-- match their skills and which career moves lead to success. This creates information
-- asymmetry—job seekers waste months applying to unsuitable roles, while employers
-- struggle to find qualified candidates. For a professional network with millions
-- of users, probabilistic career path simulation represents a paradigm shift from
-- reactive job search to proactive career planning.
--
-- This table implements a career path simulation engine that combines multiple data
-- sources: user's current skills (extracted from profiles, endorsements, projects),
-- historical career trajectories of similar users, real-time labor market demand,
-- and emerging industry trends. For each user, the system generates probabilistic
-- career paths with confidence intervals: "You have a 73% probability of transitioning
-- from Junior Developer to Tech Lead within 18-24 months, with higher success if
-- you acquire cloud architecture skills."
--
-- The simulation accounts for multiple factors: geographic market variations (cloud
-- architects in Seattle vs. Boise), industry verticals (healthcare vs. finance),
-- company size preferences, and remote work availability. Time-to-transition
-- predictions use survival analysis models trained on historical user data.
--
-- Users can explore "what-if" scenarios: "If I complete the AWS certification,
-- how does my career path change?" The system responds with updated probabilities
-- and alternative paths. For employers, aggregated (anonymized) path data reveals
-- skill gaps in their workforce and informs L&D investments.
--
-- Feature References:
-- CPS-01: Probabilistic career path modeling
-- CPS-02: Skill-to-role transition probability
-- CPS-03: Time-to-transition prediction
-- CPS-04: Geographic and industry variance
-- CPS-05: What-if scenario simulation
-- CPS-07: Multi-path exploration
-- CPS-08: Survival analysis integration
-- CPS-10: Employer aggregate insights
-- CPS-11: Real-time market data integration
-- CPS-12: Personalized confidence scoring
--
-- Key Performance Indicators (KPIs):
-- 1. Prediction Accuracy - % actual career moves correctly predicted (target >70%)
-- 2. User Engagement - % viewing career paths vs. job search
-- 3. Path Completion Rate - % users following recommended paths
-- 4. Time-to-Transition Accuracy - Predicted vs actual months
-- 5. Salary Lift - Average increase when following recommendations
-- 6. User Satisfaction - NPS for career simulation feature
-- 7. Skill Acquisition Rate - % acquiring recommended skills
-- 8. Market Responsiveness - Days to detect new role emergence
-- 9. Career Changer Success - % successfully pivoting industries
-- 10. Model Retraining Cadence - Frequency of probability updates
--------------------------------------------------------------------------------
CREATE TABLE career_path_simulations (
    -- Primary identifier
    simulation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User context
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    simulation_date TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    -- Current state snapshot
    current_role VARCHAR(255) NOT NULL,
    current_industry VARCHAR(255),
    current_skills TEXT[] NOT NULL,                      -- Extracted from profile
    years_of_experience INTEGER,
    education_level VARCHAR(100),

    -- Target role prediction
    target_role VARCHAR(255) NOT NULL,
    target_industry VARCHAR(255),
    confidence_score NUMERIC(5,2) NOT NULL CHECK (confidence_score >= 0 AND confidence_score <= 100),
    confidence_level career_path_confidence DEFAULT 'ESTABLISHED',

    -- Probability metrics
    transition_probability_6m NUMERIC(5,2) CHECK (transition_probability_6m BETWEEN 0 AND 100),
    transition_probability_12m NUMERIC(5,2) CHECK (transition_probability_12m BETWEEN 0 AND 100),
    transition_probability_24m NUMERIC(5,2) CHECK (transition_probability_24m BETWEEN 0 AND 100),
    transition_probability_36m NUMERIC(5,2) CHECK (transition_probability_36m BETWEEN 0 AND 100),
    median_time_to_transition_months INTEGER,
    confidence_interval_lower INTEGER,                    -- 10th percentile
    confidence_interval_upper INTEGER,                    -- 90th percentile

    -- Success factors (what drives success)
    success_drivers JSONB NOT NULL,
    -- Example: {"critical_skills": ["cloud_architecture", "kubernetes"],
    --           "recommended_certifications": ["AWS_SAA"],
    --           "key_experience": "team_lead",
    --           "weighted_impact": {"cloud_architecture": 0.35, "kubernetes": 0.28}}

    -- Market context
    market_demand_score NUMERIC(5,2) CHECK (market_demand_score BETWEEN 0 AND 100),
    market_trend market_trend_direction,
    salary_range_min INTEGER,
    salary_range_max INTEGER,
    salary_currency CHAR(3) DEFAULT 'USD',
    remote_work_availability NUMERIC(5,2) CHECK (remote_work_availability BETWEEN 0 AND 100),

    -- Geographic variance
    geographic_variance JSONB,                           -- Regional probability differences

    -- Similar user trajectories (anonymized)
    similar_users_count INTEGER,                         -- Sample size for this path
    similar_users_success_rate NUMERIC(5,2),            -- % who successfully transitioned

    -- Alternative paths (multiple potential routes)
    alternative_paths JSONB,                             -- Other possible roles with probabilities
    -- Example: [{"role": "Solutions Architect", "probability": 0.45, "time_months": 14}, ...]

    -- What-if scenario generation
    scenario_improvements JSONB,                         -- "If you add skill X, probability increases by Y%"
    -- Example: [{"skill": "Kubernetes", "current_have": false, "probability_increase": 12.5,
    --            "learning_time_estimate_weeks": 8}]

    -- Model metadata
    model_version VARCHAR(50) NOT NULL,
    training_data_date DATE,
    simulation_duration_ms INTEGER,                      -- Processing time

    -- Feedback loop (user interactions)
    user_feedback_score INTEGER CHECK (user_feedback_score BETWEEN 1 AND 5),
    user_feedback_text TEXT,
    user_clicked_path BOOLEAN DEFAULT false,             -- User explored this path
    user_saved_path BOOLEAN DEFAULT false,

    -- Expiration (simulations become stale as market changes)
    valid_until TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + INTERVAL '90 days'),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID NOT NULL,

    -- Indexes
    INDEX idx_career_path_user (user_id, simulation_date DESC),
    INDEX idx_career_path_role (current_role, target_role, confidence_score),
    INDEX idx_career_path_market (market_trend, market_demand_score),
    INDEX idx_career_path_valid (valid_until, user_id) WHERE valid_until > NOW(),
    INDEX idx_career_path_skills USING gin(current_skills),

    FOREIGN KEY (user_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

COMMENT ON TABLE career_path_simulations IS 'Probabilistic career path predictions combining skills, market demand, and user trajectory';
COMMENT ON COLUMN career_path_simulations.transition_probability_12m IS 'Probability user transitions to target role within 12 months';
COMMENT ON COLUMN career_path_simulations.success_drivers IS 'Weighted factors contributing to successful role transition';
COMMENT ON COLUMN career_path_simulations.scenario_improvements IS '"What-if" improvements showing impact of acquiring new skills';

-- Row Level Security
ALTER TABLE career_path_simulations ENABLE ROW LEVEL SECURITY;

CREATE POLICY career_path_user_policy ON career_path_simulations
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

-- Function to refresh stale simulations
CREATE OR REPLACE FUNCTION refresh_stale_career_paths()
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_refreshed_count INTEGER;
BEGIN
    UPDATE career_path_simulations
    SET valid_until = NOW() + INTERVAL '90 days',
        updated_at = NOW()
    WHERE valid_until < NOW()
      AND user_feedback_score >= 4
    RETURNING COUNT(*) INTO v_refreshed_count;

    RETURN v_refreshed_count;
END;
$$;

--------------------------------------------------------------------------------
-- Table: SKILL_GAP_ANALYSIS
-- Serial No: TBL-032
-- Description: Maps current skills vs. target roles, recommends micro-learning
--
-- Business Case (300 words):
-- Users know they need new skills but don't know which skills to learn, in what
-- order, or which learning resources deliver the best ROI. Generic "recommended
-- courses" ignore individual starting points, learning styles, and career goals.
-- For a professional network, this results in low course completion rates and
-- frustrated users who invest time in irrelevant skills.
--
-- This table transforms passive profiles into actionable skill roadmaps. For each
-- user and target role, the system performs granular skill gap analysis: compares
-- user's existing skills (from profile, endorsements, completed courses, projects)
-- against role requirements. The output is a prioritized skill acquisition plan
-- with specific learning resources, time estimates, and impact projections.
--
-- The analysis uses a skill ontology mapping dependencies between skills. For
-- example, to learn "Machine Learning," user needs prerequisite "Python Programming"
-- and "Statistics." The system builds a learning DAG (directed acyclic graph)
-- showing the optimal skill acquisition sequence to minimize time-to-competency.
--
-- Micro-learning recommendations align with user behavior patterns: users who
-- prefer 10-minute videos receive bite-sized content; users who complete longer
-- courses receive structured programs. The system tracks learning progress,
-- updating gap analysis as skills are acquired and suggesting next steps.
--
-- For employers, aggregated skill gap data identifies workforce training needs
-- at department/company level. HR teams see "67% of our engineering team lacks
-- cloud security skills" and can procure targeted training. The system integrates
-- with LMS platforms (Coursera, Udemy, LinkedIn Learning) for one-click enrollment.
--
-- Feature References:
-- SGA-01: Current vs. target skill mapping
-- SGA-02: Skill ontology and prerequisite detection
-- SGA-03: Prioritized skill acquisition roadmap
-- SGA-05: Learning resource matching (style, format, duration)
-- SGA-06: Progress tracking and dynamic re-prioritization
-- SGA-08: Employer aggregate skill insights
-- SGA-09: LMS integration for enrollment
-- SGA-10: Time-to-competency prediction
-- SGA-11: Skill adjacency (related skills to learn together)
-- SGA-12: Learning ROI calculation
--------------------------------------------------------------------------------
CREATE TABLE skill_gap_analysis (
    -- Primary identifier
    analysis_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User context
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    analysis_date TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    -- Target role (from career path or user-selected)
    target_role VARCHAR(255) NOT NULL,
    target_role_category VARCHAR(100),

    -- Current skills snapshot
    current_skills TEXT[] NOT NULL,
    skill_proficiency JSONB,                             -- Per-skill proficiency levels (1-10)
    -- Example: {"python": 8, "sql": 7, "aws": 3, "kubernetes": 0}

    -- Required skills for target role
    required_skills TEXT[] NOT NULL,
    required_skill_proficiency INTEGER DEFAULT 7 CHECK (required_skill_proficiency BETWEEN 1 AND 10),

    -- Gap analysis results
    missing_skills TEXT[] GENERATED ALWAYS AS (
        ARRAY(SELECT unnest(required_skills) EXCEPT SELECT unnest(current_skills))
    ) STORED,

    skill_gap_summary JSONB NOT NULL,                    -- Detailed per-skill gaps
    -- Example: {"python": {"current": 8, "required": 7, "gap": 0, "status": "met"},
    --           "kubernetes": {"current": 0, "required": 7, "gap": 7, "status": "critical"}}

    -- Prioritized learning roadmap
    learning_roadmap JSONB NOT NULL,                     -- Ordered steps with estimates
    -- Example: [{"skill": "Docker", "priority": "critical", "estimated_hours": 15,
    --            "prerequisites": [], "learning_resources": [...]},
    --           {"skill": "Kubernetes", "priority": "high", "estimated_hours": 40,
    --            "prerequisites": ["Docker"], "learning_resources": [...]}]

    -- Skill dependencies (prerequisite graph)
    skill_dependencies JSONB,                            -- DAG of required learning sequence

    -- Learning recommendations
    recommended_resources JSONB,                         -- Curated by skill
    -- Example per skill: [{"type": "MICRO_LEARNING", "title": "K8s in 10 mins",
    --                      "url": "...", "duration_minutes": 10, "provider": "YouTube"},
    --                     {"type": "COURSE", "title": "CKAD Certification",
    --                      "duration_hours": 40, "provider": "Udemy", "cost_usd": 29}]

    -- Time and cost estimates
    total_estimated_hours INTEGER,
    total_estimated_cost_usd NUMERIC(10,2),
    optimal_completion_weeks INTEGER,                    -- Based on 5 hours/week
    accelerated_completion_weeks INTEGER,                -- Based on 15 hours/week

    -- Learning ROI (return on investment)
    expected_salary_increase INTEGER,
    salary_increase_percentage INTEGER,
    roi_percentage INTEGER GENERATED ALWAYS AS (
        CASE
            WHEN total_estimated_cost_usd > 0
            THEN (expected_salary_increase / total_estimated_cost_usd) * 100
            ELSE NULL
        END
    ) STORED,

    -- Progress tracking (for ongoing analysis)
    skills_acquired_since_analysis TEXT[] DEFAULT '{}',
    progress_percentage NUMERIC(5,2) GENERATED ALWAYS AS (
        (array_length(skills_acquired_since_analysis, 1)::NUMERIC /
         NULLIF(array_length(missing_skills, 1), 0)) * 100
    ) STORED,

    -- Learning preferences (user-configured)
    preferred_learning_style learning_resource_type[],
    weekly_learning_hours INTEGER DEFAULT 5,
    budget_usd NUMERIC(10,2),

    -- User engagement
    learner_enrolled_count INTEGER DEFAULT 0,
    learner_completed_count INTEGER DEFAULT 0,
    last_accessed_at TIMESTAMP WITH TIME ZONE,

    -- Model metadata
    model_version VARCHAR(50) NOT NULL,
    skill_ontology_version VARCHAR(50),

    -- Expiration (as user acquires skills)
    valid_until TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + INTERVAL '180 days'),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID NOT NULL,

    -- Indexes
    INDEX idx_skill_gap_user (user_id, analysis_date DESC),
    INDEX idx_skill_gap_role (target_role, analysis_date),
    INDEX idx_skill_gap_missing USING gin(missing_skills),
    INDEX idx_skill_gap_current USING gin(current_skills),
    INDEX idx_skill_gap_progress (progress_percentage, user_id) WHERE progress_percentage < 100,

    FOREIGN KEY (user_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

COMMENT ON TABLE skill_gap_analysis IS 'Actionable skill gap analysis with prioritized learning roadmaps and ROI calculations';
COMMENT ON COLUMN skill_gap_analysis.skill_gap_summary IS 'Per-skill comparison of current vs. required proficiency';
COMMENT ON COLUMN skill_gap_analysis.learning_roadmap IS 'Sequential learning plan with dependencies and resource recommendations';
COMMENT ON COLUMN skill_gap_analysis.skills_acquired_since_analysis IS 'Skills user has completed post-analysis for dynamic updates';

-- Row Level Security
ALTER TABLE skill_gap_analysis ENABLE ROW LEVEL SECURITY;

CREATE POLICY skill_gap_user_policy ON skill_gap_analysis
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

-- Function to update skill acquisition progress
CREATE OR REPLACE FUNCTION update_skill_acquisition(
    p_user_id UUID,
    p_skill TEXT,
    p_analysis_id UUID DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
AS $$
DECLARE
    v_analysis_id UUID;
BEGIN
    -- Get most recent analysis if not specified
    IF p_analysis_id IS NULL THEN
        SELECT analysis_id INTO v_analysis_id
        FROM skill_gap_analysis
        WHERE user_id = p_user_id
        ORDER BY analysis_date DESC
        LIMIT 1;
    ELSE
        v_analysis_id := p_analysis_id;
    END IF;

    -- Update acquired skills array
    UPDATE skill_gap_analysis
    SET skills_acquired_since_analysis =
        ARRAY(SELECT DISTINCT unnest(skills_acquired_since_analysis || ARRAY[p_skill]))
    WHERE analysis_id = v_analysis_id;

    RETURN FOUND;
END;
$$;

--------------------------------------------------------------------------------
-- ENUM: recommendation_status
-- Description: Lifecycle of AI career recommendations
-- Feature Reference: AIR-08 (Recommendation State)
--------------------------------------------------------------------------------
CREATE TYPE recommendation_status AS ENUM (
    'ACTIVE',           -- Currently valid
    'DISMISSED',        -- User dismissed
    'COMPLETED',        -- User acted on (applied, saved)
    'EXPIRED',          -- No longer relevant
    'ARCHIVED'          -- Historical record
);

--------------------------------------------------------------------------------
-- Table: AI_CAREER_RECOMMENDATIONS
-- Serial No: TBL-033
-- Description: ML-driven role/project recommendations with explainability
--
-- Business Case (300 words):
-- "Black box" AI recommendations erode user trust. When a system suggests a role
-- or project without explanation, users are skeptical ("Why is it showing me this?"),
-- less likely to act, and more likely to dismiss the feature. For career decisions
-- with significant life impact (job changes, skill investments), explainability
-- is not optional—it's essential for adoption and trust.
--
-- This table delivers transparent AI recommendations with human-readable explanations.
-- Each recommendation includes a match score (0-100) and a multi-factor explanation
-- showing exactly which skills, experiences, or market factors drove the score.
-- The system uses multiple explainability types: feature impact ("You're 78% match
-- because your Python skill (35%) and cloud experience (28%) closely match this role"),
-- counterfactual ("If you had Kubernetes certification, your match would be 89%"),
-- and similar users ("Professionals like you transitioned to this role in 6 months").
--
-- Recommendations span multiple types: job opportunities (personalized to user's
-- career path), learning projects (skill-building with career impact), mentorship
-- connections (with users who made similar transitions), and side projects (to
-- fill skill gaps). Each recommendation includes actionable next steps and
-- estimated career impact (salary increase, promotion probability, time saved).
--
-- The system continuously learns from user feedback: when users accept or dismiss
-- recommendations, the model refines its predictions. Real-time integration with
-- job market data ensures recommendations respond to emerging opportunities.
-- For ethical AI, the system tracks demographic parity to detect and mitigate bias
-- (e.g., recommending different roles based on gender or location).
--
-- Feature References:
-- AIR-01: ML-driven job/role recommendations
-- AIR-02: Transparent match scoring with breakdown
-- AIR-03: Counterfactual explanations ("what if")
-- AIR-04: Similar user success stories
-- AIR-05: Actionable next steps
-- AIR-06: Career impact estimation
-- AIR-07: Feedback loop for model improvement
-- AIR-10: Bias detection and mitigation
-- AIR-11: Real-time market signal integration
-- AIR-12: Multi-type recommendations (jobs, projects, mentors)
--------------------------------------------------------------------------------
CREATE TABLE ai_career_recommendations (
    -- Primary identifier
    recommendation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User context
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    recommendation_date TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    -- Recommendation type
    recommendation_type VARCHAR(50) NOT NULL CHECK (recommendation_type IN
        ('JOB', 'PROJECT', 'COURSE', 'MENTOR', 'CERTIFICATION', 'INTERNSHIP', 'NETWORKING_EVENT')),

    -- Recommendation content
    target_id VARCHAR(255) NOT NULL,                     -- Job ID, course ID, mentor UUID
    target_title VARCHAR(500) NOT NULL,
    target_description TEXT,
    target_url TEXT,

    -- Match scoring
    match_score NUMERIC(5,2) NOT NULL CHECK (match_score >= 0 AND match_score <= 100),
    confidence_interval JSONB,                           -- P10, P50, P90 scores

    -- Explainability (transparent AI)
    explainability_type recommendation_explainability_type[] NOT NULL,
    explanation_json JSONB NOT NULL,                     -- Human-readable with breakdown
    -- Example: {"summary": "Strong match based on Python and cloud skills.",
    --           "factors": [
    --             {"factor": "Python expertise", "weight": 0.35, "contribution": 28},
    --             {"factor": "Cloud experience", "weight": 0.28, "contribution": 22},
    --             {"factor": "Years of experience", "weight": 0.15, "contribution": 12}
    --           ],
    --           "counterfactual": "Kubernetes certification would increase score by 11 points",
    --           "similar_users": "1,247 similar users succeeded in this role"}

    -- Feature importance (for ML transparency)
    feature_importance JSONB,                            -- Full feature weight breakdown
    model_shap_values JSONB,                             -- SHAP values for interpretability

    -- Similar users (anonymized)
    similar_users_example JSONB,                         -- Example user with similar path
    successful_transition_count INTEGER,
    successful_transition_rate NUMERIC(5,2),

    -- Career impact projection
    estimated_salary_increase INTEGER,
    estimated_promotion_probability NUMERIC(5,2),
    estimated_time_to_impact_months INTEGER,
    career_trajectory_impact VARCHAR(50) CHECK (career_trajectory_impact IN
        ('ACCELERATOR', 'PIVOT', 'UPGRADE', 'ALTERNATIVE')),

    -- Actionable steps
    next_steps JSONB NOT NULL,
    -- Example: ["Review full job description", "Connect with hiring manager",
    --           "Complete skill assessment", "Apply by deadline"]

    -- Status tracking
    status recommendation_status DEFAULT 'ACTIVE',
    user_viewed_at TIMESTAMP WITH TIME ZONE,
    user_saved BOOLEAN DEFAULT false,
    user_saved_at TIMESTAMP WITH TIME ZONE,
    user_dismissed_at TIMESTAMP WITH TIME ZONE,
    user_applied_at TIMESTAMP WITH TIME ZONE,            -- For job applications
    user_completed_at TIMESTAMP WITH TIME ZONE,          -- For courses/certifications

    -- User feedback (model training)
    user_feedback_score INTEGER CHECK (user_feedback_score BETWEEN 1 AND 5),
    user_feedback_text TEXT,
    user_feedback_relevance VARCHAR(50) CHECK (user_feedback_relevance IN ('HIGH', 'MEDIUM', 'LOW', 'IRRELEVANT')),

    -- A/B testing metadata
    ab_test_bucket VARCHAR(100),
    ranking_algorithm_version VARCHAR(50),

    -- Bias detection
    demographic_parity_score NUMERIC(5,4),               -- Measure of recommendation bias
    fairness_constraint_applied BOOLEAN DEFAULT false,

    -- Expiration (market-driven)
    expires_at TIMESTAMP WITH TIME ZONE DEFAULT (NOW() + INTERVAL '30 days'),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_by UUID NOT NULL,

    -- Indexes
    INDEX idx_ai_recommendations_user (user_id, recommendation_date DESC, status),
    INDEX idx_ai_recommendations_score (match_score DESC, status),
    INDEX idx_ai_recommendations_type (recommendation_type, status),
    INDEX idx_ai_recommendations_expiry (expires_at) WHERE status = 'ACTIVE',
    INDEX idx_ai_recommendations_feedback (user_feedback_score, user_feedback_relevance),

    FOREIGN KEY (user_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

COMMENT ON TABLE ai_career_recommendations IS 'Transparent ML career recommendations with explainable AI and bias mitigation';
COMMENT ON COLUMN ai_career_recommendations.explanation_json IS 'Human-readable multi-factor explanation of recommendation score';
COMMENT ON COLUMN ai_career_recommendations.feature_importance IS 'Full ML model feature weights for transparency';
COMMENT ON COLUMN ai_career_recommendations.demographic_parity_score IS 'Measure of fairness to detect demographic bias in recommendations';

-- Row Level Security
ALTER TABLE ai_career_recommendations ENABLE ROW LEVEL SECURITY;

CREATE POLICY ai_recommendations_user_policy ON ai_career_recommendations
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

-- Function to refresh recommendations based on user feedback
CREATE OR REPLACE FUNCTION refresh_recommendation_weights()
RETURNS TRIGGER AS $$
BEGIN
    -- Update recommendation relevance based on user feedback
    IF NEW.user_feedback_score IS NOT NULL THEN
        -- Log feedback for offline model retraining
        INSERT INTO recommendation_feedback_log (
            recommendation_id, user_id, feedback_score,
            recommendation_type, match_score, created_at
        ) VALUES (
            NEW.recommendation_id, NEW.user_id, NEW.user_feedback_score,
            NEW.recommendation_type, NEW.match_score, NOW()
        );
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE recommendation_feedback_log (
    log_id BIGSERIAL PRIMARY KEY,
    recommendation_id UUID NOT NULL,
    user_id UUID NOT NULL,
    feedback_score INTEGER NOT NULL,
    recommendation_type VARCHAR(50),
    match_score NUMERIC(5,2),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_feedback_training (recommendation_type, feedback_score, created_at)
);

CREATE TRIGGER trg_recommendation_feedback
    AFTER UPDATE OF user_feedback_score ON ai_career_recommendations
    FOR EACH ROW
    EXECUTE FUNCTION refresh_recommendation_weights();

-- =============================================================================
-- AGGREGATED VIEWS FOR ANALYTICS
-- =============================================================================

-------------------------------------------------------------------------------
-- Materialized View: mv_market_skill_demand
-- Description: Aggregated view of in-demand skills by role and market trend
-- Refresh: Daily via cron
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW mv_market_skill_demand AS
SELECT
    target_role,
    skill,
    COUNT(DISTINCT sga.user_id) as users_needing_skill,
    AVG(priority_score) as avg_priority,
    COUNT(DISTINCT cps.user_id) as career_path_mentions,
    market_trend_direction as trend
FROM skill_gap_analysis sga,
     LATERAL unnest(missing_skills) AS skill,
     career_path_simulations cps
WHERE sga.target_role = cps.target_role
  AND sga.analysis_date > NOW() - INTERVAL '90 days'
GROUP BY target_role, skill, market_trend_direction;

CREATE UNIQUE INDEX idx_mv_market_demand ON mv_market_skill_demand (target_role, skill);

COMMENT ON MATERIALIZED VIEW mv_market_skill_demand IS 'Aggregated skill demand analytics for career path optimization';

-------------------------------------------------------------------------------
-- Materialized View: mv_recommendation_performance
-- Description: Tracks AI recommendation performance metrics
-- Refresh: Hourly
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW mv_recommendation_performance AS
SELECT
    recommendation_type,
    DATE(created_at) as recommendation_date,
    COUNT(*) as total_recommendations,
    AVG(match_score) as avg_match_score,
    SUM(CASE WHEN user_saved THEN 1 ELSE 0 END) as saved_count,
    SUM(CASE WHEN user_applied_at IS NOT NULL THEN 1 ELSE 0 END) as applied_count,
    SUM(CASE WHEN user_completed_at IS NOT NULL THEN 1 ELSE 0 END) as completed_count,
    AVG(CASE WHEN user_feedback_score IS NOT NULL THEN user_feedback_score END) as avg_feedback_score,
    SUM(CASE WHEN user_dismissed_at IS NOT NULL THEN 1 ELSE 0 END) as dismissed_count
FROM ai_career_recommendations
WHERE created_at > NOW() - INTERVAL '30 days'
GROUP BY recommendation_type, DATE(created_at);

CREATE UNIQUE INDEX idx_mv_rec_perf ON mv_recommendation_performance (recommendation_type, recommendation_date);

COMMENT ON MATERIALIZED VIEW mv_recommendation_performance IS 'AI recommendation performance metrics for model evaluation';

-- Grant permissions
GRANT SELECT, INSERT, UPDATE ON career_path_simulations, skill_gap_analysis,
    ai_career_recommendations, recommendation_feedback_log TO ap_application;
GRANT EXECUTE ON FUNCTION refresh_stale_career_paths, update_skill_acquisition TO ap_application;
GRANT SELECT ON mv_market_skill_demand, mv_recommendation_performance TO ap_application;



-- =============================================================================
-- CREDENTIAL VERIFICATION & TRUST REPUTATION SYSTEM
-- Phase: Trust & Safety - Anti-Fraud Infrastructure
-- =============================================================================

--------------------------------------------------------------------------------
-- ENUM: credential_type
-- Description: Types of verifiable credentials supported by the system
-- Business Case: Enables specialized verification workflows per credential type
-- Feature Reference: CV-02 (Credential Categorization)
--------------------------------------------------------------------------------
CREATE TYPE credential_type AS ENUM (
    'DEGREE',           -- Academic degree (Bachelor's, Master's, PhD, etc.)
    'CERTIFICATION',    -- Professional certification (PMP, AWS, CFA, etc.)
    'EMPLOYMENT',       -- Work history, role, tenure
    'SKILL',            -- Technical or soft skill with proficiency level
    'ACHIEVEMENT',      -- Awards, publications, patents
    'LANGUAGE',         -- Language proficiency (CEFR, ILR)
    'SECURITY_CLEARANCE' -- Government/compliance clearances
);

--------------------------------------------------------------------------------
-- ENUM: verification_status
-- Description: Lifecycle states for credential verification
-- Business Case: Tracks verification progress and enables appeals
-- Feature Reference: CV-05 (Verification State Management)
--------------------------------------------------------------------------------
CREATE TYPE verification_status AS ENUM (
    'PENDING',          -- Submitted, waiting for verification
    'VERIFYING',        -- In active verification process
    'VERIFIED',         -- Successfully verified
    'FAILED',           -- Verification failed (fraudulent/suspicious)
    'EXPIRED',          -- Time-limited credential expired
    'DISPUTED',         -- User contesting verification result
    'REVOKED'           -- Issuing authority revoked credential
);

--------------------------------------------------------------------------------
-- ENUM: verification_method
-- Description: Methods used to verify credential authenticity
-- Business Case: Supports multi-factor verification for high-stakes credentials
-- Feature Reference: CV-08 (Verification Method Flexibility)
--------------------------------------------------------------------------------
CREATE TYPE verification_method AS ENUM (
    'INSTITUTION_API',      -- Direct API to issuing institution
    'THIRD_PARTY_API',      -- Clearbit, Truework, etc.
    'DOCUMENT_UPLOAD',      -- Diploma, certificate images
    'EMPLOYER_CONFIRM',     -- HR direct confirmation
    'PEER_ENDORSEMENT',     -- Colleague verification
    'BLOCKCHAIN',           -- On-chain credential
    'W3C_VERIFIABLE_CREDENTIAL', -- Decentralized identity standard
    'MANUAL_REVIEW'         -- Human verification team
);

--------------------------------------------------------------------------------
-- ENUM: reputation_tier
-- Description: Trust tiers for user reputation scores
-- Business Case: Enables graduated trust for different platform features
-- Feature Reference: TRS-06 (Reputation Tiers)
--------------------------------------------------------------------------------
CREATE TYPE reputation_tier AS ENUM (
    'UNVERIFIED',       -- New user, minimal trust
    'BASIC',            -- Email/phone verified
    'VERIFIED',         -- Single credential verified
    'TRUSTED',          -- Multiple credentials, positive platform history
    'HIGHLY_TRUSTED',   -- Extensive verification, long-term positive history
    'INSTITUTIONAL'     -- Verified organization/institution
);

--------------------------------------------------------------------------------
-- ENUM: blockchain_network
-- Description: Supported blockchain networks for credential anchoring
-- Business Case: Enables cross-chain credential portability
-- Feature Reference: BCL-03 (Multi-Chain Support)
--------------------------------------------------------------------------------
CREATE TYPE blockchain_network AS ENUM (
    'ETHEREUM_MAINNET',
    'POLYGON',
    'SOLANA',
    'HYPERLEDGER_FABRIC',
    'CELO',
    'OPTIMISM',
    'ARBITRUM',
    'BASE'
);

--------------------------------------------------------------------------------
-- Table: CREDENTIAL_VERIFICATIONS
-- Serial No: TBL-034
-- Description: Stores degree, employment, and skill verification proofs with cryptographic integrity
--
-- Business Case (300 words):
-- Resume fraud costs employers billions annually—studies show 30-50% of candidates
-- exaggerate or falsify credentials. Traditional platforms rely on self-reporting,
-- creating an "honesty tax" where truthful users are disadvantaged. For a professional
-- network, undetected fraud destroys trust: employers waste recruiting resources,
-- qualified candidates lose opportunities to fraudsters, and platform credibility
-- erodes.
--
-- This table implements a comprehensive credential verification system that moves
-- beyond self-reporting to cryptographic proof. Users submit credentials with
-- supporting evidence (diploma images, employer emails, skill assessments).
-- Verification happens through multiple methods: direct API integration with
-- universities (verify degrees in seconds), third-party verification services,
-- or platform-based employer confirmation workflows.
--
-- Each verification creates an immutable audit trail: who verified what, when,
-- and by which method. Verified credentials display trust badges (e.g., "Degree
-- Verified - University of Stanford"). The system supports credential portability:
-- once verified, users can share credentials with other platforms without re-verification.
--
-- For high-stakes roles (executives, financial positions), the system supports
-- multi-factor verification: requiring both document upload AND institutional API
-- confirmation. Failed verifications trigger fraud detection workflows, potentially
-- flagging the user account for review. Expiring credentials (certifications with
-- renewal dates) trigger re-verification reminders.
--
-- The table integrates with the trust reputation system: verified credentials
-- significantly boost user trust scores, while failed verifications reduce trust
-- and may restrict platform features. For compliance (FCRA, GDPR), users can
-- dispute verification results and provide additional evidence.
--
-- Feature References:
-- CV-01: Academic degree verification (diploma, transcripts)
-- CV-03: Employment history verification (dates, titles)
-- CV-04: Skill assessment verification (tests, portfolios)
-- CV-06: Multi-method verification support
-- CV-07: Credential portability across platforms
-- CV-09: Expiration and renewal tracking
-- CV-10: Fraud detection integration
-- CV-11: User dispute workflow
-- CV-12: Trust score integration
-- CV-13: API-based institutional verification
--
-- Key Performance Indicators (KPIs):
-- 1. Verification Completion Rate - % submitted credentials successfully verified
-- 2. Average Verification Time - Hours from submission to completion
-- 3. Fraud Detection Rate - % fraudulent credentials caught
-- 4. False Positive Rate - % legitimate credentials incorrectly flagged
-- 5. Institution API Coverage - % top universities/employers with direct API
-- 6. Credential Portability Usage - % users sharing credentials externally
-- 7. Verification Dispute Rate - % users contesting results
-- 8. Expired Credential Rate - % requiring renewal
-- 9. Trust Score Impact - Avg score increase per verified credential
-- 10. Employer Confidence - % employers trusting verified credentials
--------------------------------------------------------------------------------
CREATE TABLE credential_verifications (
    -- Primary identifier
    credential_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    credential_number VARCHAR(50) GENERATED ALWAYS AS (
        'CRED-' || LPAD(EXTRACT(YEAR FROM created_at)::TEXT, 4, '0') || '-' ||
        LPAD(credential_id::TEXT, 10, '0')
    ) STORED UNIQUE,

    -- User identification
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,

    -- Credential details
    credential_type credential_type NOT NULL,
    credential_title VARCHAR(500) NOT NULL,              -- "Bachelor of Science in Computer Science"
    issuing_authority VARCHAR(500) NOT NULL,             -- "Stanford University", "Google"
    issuing_authority_identifier VARCHAR(255),           -- ORCID, DUNS, ROR ID (disambiguate)

    -- Credential metadata
    issue_date DATE,
    expiration_date DATE,                                 -- For time-limited credentials
    credential_identifier VARCHAR(255),                   -- Diploma ID, certificate number
    credential_level VARCHAR(100),                        -- "Bachelor's", "Master's", "Level 3"

    -- Evidence and proof
    evidence_attachments TEXT[],                          -- S3/GCS paths for documents
    evidence_hashes VARCHAR(255)[],                       -- SHA-256 of evidence files
    external_verification_url TEXT,                       -- Link to public verification

    -- Verification state
    verification_status verification_status DEFAULT 'PENDING',
    verification_status_reason TEXT,
    verification_methods verification_method[],

    -- Verification details (multi-method)
    verification_results JSONB,                           -- Per-method results
    -- Example: [{"method": "INSTITUTION_API", "status": "success", "timestamp": "2024-01-01T00:00:00Z",
    --            "response": {"verified": true, "graduation_date": "2020-05-15"}}]

    -- Verification provenance
    verified_by UUID,                                     -- System, admin, or institution rep
    verified_at TIMESTAMP WITH TIME ZONE,
    verification_notes TEXT,

    -- Automated checks
    fraud_risk_score NUMERIC(5,2) CHECK (fraud_risk_score >= 0 AND fraud_risk_score <= 100),
    anomaly_detection_flags TEXT[],                       -- "mismatched_dates", "unrecognized_institution"

    -- Cryptographic integrity
    content_hash VARCHAR(255),                            -- Hash of credential data
    digital_signature TEXT,                               -- Optional user/authority signature

    -- Dispute workflow
    disputed_at TIMESTAMP WITH TIME ZONE,
    dispute_reason TEXT,
    dispute_evidence TEXT,
    dispute_resolved_by UUID,
    dispute_resolved_at TIMESTAMP WITH TIME ZONE,
    dispute_resolution TEXT,

    -- Revocation
    revoked_at TIMESTAMP WITH TIME ZONE,
    revoked_by UUID,
    revocation_reason TEXT,

    -- Portability (sharing with external platforms)
    external_shares JSONB,                                -- Which platforms this credential shared with
    -- Example: [{"platform": "linkedin", "shared_at": "...", "verified_export": true}]

    -- Trust impact
    trust_score_contribution INTEGER,                     -- Points added to user's trust score

    -- Metadata
    metadata JSONB DEFAULT '{}',
    tags TEXT[],

    -- Expiration handling
    renewal_reminder_sent BOOLEAN DEFAULT false,
    last_renewal_reminder_at TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT credential_dates_check CHECK (expiration_date IS NULL OR expiration_date > issue_date),
    CONSTRAINT credential_evidence_check CHECK (array_length(evidence_attachments, 1) > 0),

    -- Indexes
    INDEX idx_credential_user (user_id, verification_status, credential_type),
    INDEX idx_credential_authority (issuing_authority, credential_type, verification_status),
    INDEX idx_credential_verification (verification_status, verified_at DESC) WHERE verification_status = 'PENDING',
    INDEX idx_credential_fraud (fraud_risk_score, verification_status) WHERE fraud_risk_score > 70,
    INDEX idx_credential_expiration (expiration_date) WHERE expiration_date IS NOT NULL,

    FOREIGN KEY (user_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

COMMENT ON TABLE credential_verifications IS 'Cryptographically verifiable credential storage with multi-method verification support';
COMMENT ON COLUMN credential_verifications.verification_results IS 'Per-method verification outcomes and raw response data';
COMMENT ON COLUMN credential_verifications.content_hash IS 'SHA-256 hash of credential data for tamper detection';
COMMENT ON COLUMN credential_verifications.external_shares IS 'Audit trail of credential sharing with external platforms for portability';

-- Row Level Security
ALTER TABLE credential_verifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY credential_user_policy ON credential_verifications
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

CREATE POLICY credential_verifier_policy ON credential_verifications
    USING (current_setting('app.is_verification_agent', true)::BOOLEAN = true);

-- Function to auto-calculate trust score contribution
CREATE OR REPLACE FUNCTION calculate_credential_trust_value()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.verification_status = 'VERIFIED' THEN
        -- Base points by credential type
        NEW.trust_score_contribution := CASE NEW.credential_type
            WHEN 'DEGREE' THEN 50
            WHEN 'CERTIFICATION' THEN 30
            WHEN 'EMPLOYMENT' THEN 25
            WHEN 'SKILL' THEN 10
            WHEN 'ACHIEVEMENT' THEN 20
            ELSE 15
        END;

        -- Bonus for institutional verification
        IF 'INSTITUTION_API' = ANY(NEW.verification_methods) THEN
            NEW.trust_score_contribution := NEW.trust_score_contribution + 20;
        END IF;

        -- Bonus for multiple methods
        IF array_length(NEW.verification_methods, 1) >= 2 THEN
            NEW.trust_score_contribution := NEW.trust_score_contribution + 15;
        END IF;
    ELSE
        NEW.trust_score_contribution := 0;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_credential_trust_value
    BEFORE INSERT OR UPDATE OF verification_status, verification_methods ON credential_verifications
    FOR EACH ROW
    EXECUTE FUNCTION calculate_credential_trust_value();

--------------------------------------------------------------------------------
-- Table: BLOCKCHAIN_CREDENTIAL_LEDGER
-- Serial No: TBL-035
-- Description: Immutable proof-of-credential hashes with Web3 integration
--
-- Business Case (300 words):
-- Resume fraud persists because credentials are not portable and cannot be
-- cryptographically verified across platforms. A verified credential on Platform A
-- requires complete re-verification on Platform B, wasting time and money.
-- Blockchain technology solves this: credentials anchored to a tamper-proof ledger
-- can be verified by any platform without re-contacting the issuing institution.
--
-- This table implements an optional Web3 layer for credential anchoring. When a
-- credential is verified, its cryptographic hash is written to a blockchain
-- (Ethereum, Polygon, Hyperledger). The hash serves as an immutable timestamp
-- and proof-of-existence. Anyone with the credential data can recompute the hash
-- and verify it matches the blockchain record, confirming the credential is
-- authentic and unaltered.
--
-- The system supports multiple blockchain networks, allowing institutions to
-- choose their preferred chain (public for transparency, private for compliance).
-- Credentials can be anchored to multiple networks for redundancy. Smart contract
-- interactions record additional metadata: issuing authority signature, revocation
-- status, and expiration dates.
--
-- For users, blockchain-anchored credentials become portable "verifiable credentials"
-- they control. A user verified at University A can share that credential with
-- Employer B without University A re-verifying—Employer B simply checks the
-- blockchain. This eliminates credential verification as a bottleneck in hiring.
--
-- The table does NOT store personal data on-chain (privacy risk). Only salted
-- hashes and metadata pointers reside on-chain; the actual credential data remains
-- off-chain with user consent controls. For GDPR compliance, users can request
-- hash removal (cryptographic deletion), though blockchain immutability means
-- the hash may still exist but becomes unlinkable to the user.
--
-- Feature References:
-- BCL-01: Cryptographic hash anchoring to blockchain
-- BCL-02: Smart contract integration for verification
-- BCL-04: Cross-chain credential portability
-- BCL-05: Revocation registry (revoked credentials)
-- BCL-06: Issuer signing and verification
-- BCL-07: Privacy-preserving selective disclosure
-- BCL-08: W3C Verifiable Credentials standard compliance
-- BCL-09: Gas fee optimization for anchor transactions
-- BCL-10: Decentralized identifier (DID) integration
--------------------------------------------------------------------------------
CREATE TABLE blockchain_credential_ledger (
    -- Primary identifier
    anchor_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Linked credential
    credential_id UUID NOT NULL REFERENCES credential_verifications(credential_id),
    user_id UUID NOT NULL,

    -- Blockchain anchor
    blockchain_network blockchain_network NOT NULL,
    transaction_hash VARCHAR(255) NOT NULL,              -- Blockchain tx hash
    block_number BIGINT,
    block_timestamp TIMESTAMP WITH TIME ZONE,
    smart_contract_address VARCHAR(255),

    -- Cryptographic proofs
    credential_hash VARCHAR(255) NOT NULL,               -- Hash of credential + salt
    salted_hash VARCHAR(255),                            -- Hash with user-specific salt
    merkle_proof TEXT,                                   -- For batch anchoring

    -- Decentralized identity
    issuer_did VARCHAR(255),                             -- DID of issuing authority
    user_did VARCHAR(255),                               -- User's DID
    verifiable_credential_uri TEXT,                      -- W3C VC JSON-LD URI

    -- On-chain metadata
    on_chain_metadata JSONB,                             -- Minimal metadata stored on chain
    revocation_status BOOLEAN DEFAULT false,             -- Also stored in chain registry

    -- Verification status
    anchor_status VARCHAR(50) CHECK (anchor_status IN ('PENDING', 'CONFIRMED', 'FAILED', 'EXPIRED')),
    confirmations INTEGER DEFAULT 0,
    gas_used NUMERIC(20,0),                              -- Gas cost in wei
    gas_price_gwei NUMERIC(10,2),                        -- Gas price used

    -- Off-chain storage
    credential_salt TEXT,                                -- User-specific salt (never shared)
    off_chain_storage_url TEXT,                          -- Encrypted credential storage

    -- Expiration
    expires_at TIMESTAMP WITH TIME ZONE,                 -- When on-chain proof expires
    renewed_at TIMESTAMP WITH TIME ZONE,
    renewal_transaction_hash VARCHAR(255),

    -- Revocation (on-chain and off-chain)
    revoked_on_chain BOOLEAN DEFAULT false,
    revocation_transaction_hash VARCHAR(255),
    revoked_at TIMESTAMP WITH TIME ZONE,
    revocation_reason TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,

    -- Indexes
    INDEX idx_blockchain_credential (credential_id, blockchain_network),
    INDEX idx_blockchain_transaction (transaction_hash),
    INDEX idx_blockchain_did (issuer_did, user_did),
    INDEX idx_blockchain_status (anchor_status, confirmations),
    INDEX idx_blockchain_revocation (revocation_status, revoked_at),

    UNIQUE(credential_id, blockchain_network)
);

COMMENT ON TABLE blockchain_credential_ledger IS 'Blockchain-anchored credential proofs for tamper-evident, portable verification';
COMMENT ON COLUMN blockchain_credential_ledger.credential_hash IS 'SHA-256 hash of credential data + salt - stored on blockchain as proof';
COMMENT ON COLUMN blockchain_credential_ledger.salted_hash IS 'Hash with user-specific salt for privacy (prevents rainbow table attacks)';
COMMENT ON COLUMN blockchain_credential_ledger.verifiable_credential_uri IS 'W3C Verifiable Credential standard JSON-LD URI';

-- Row Level Security (limited access - audit only)
ALTER TABLE blockchain_credential_ledger ENABLE ROW LEVEL SECURITY;

CREATE POLICY blockchain_audit_policy ON blockchain_credential_ledger
    USING (current_setting('app.is_compliance_auditor', true)::BOOLEAN = true);

-- Function to anchor credential to blockchain (simplified - actual implementation would call web3)
CREATE OR REPLACE FUNCTION anchor_credential_to_blockchain(
    p_credential_id UUID,
    p_blockchain_network blockchain_network
)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    v_credential_data JSONB;
    v_credential_hash VARCHAR(255);
    v_transaction_hash VARCHAR(255);
BEGIN
    -- Get credential data (excluding PII, just structure)
    SELECT jsonb_build_object(
        'credential_id', credential_id,
        'type', credential_type,
        'title', credential_title,
        'issuer', issuing_authority,
        'issue_date', issue_date
    ) INTO v_credential_data
    FROM credential_verifications
    WHERE credential_id = p_credential_id;

    -- Generate cryptographic hash (simulated)
    v_credential_hash := encode(sha256(v_credential_data::TEXT::BYTEA), 'hex');

    -- Simulate blockchain transaction (production would call web3 API)
    v_transaction_hash := encode(gen_random_bytes(32), 'hex');

    -- Insert anchor record
    INSERT INTO blockchain_credential_ledger (
        credential_id, user_id, blockchain_network,
        transaction_hash, credential_hash, anchor_status,
        created_by
    )
    SELECT
        p_credential_id, user_id, p_blockchain_network,
        v_transaction_hash, v_credential_hash, 'PENDING',
        current_setting('app.current_user_id', true)::UUID
    FROM credential_verifications
    WHERE credential_id = p_credential_id;

    RETURN jsonb_build_object(
        'transaction_hash', v_transaction_hash,
        'credential_hash', v_credential_hash
    );
END;
$$;

--------------------------------------------------------------------------------
-- Table: TRUST_REPUTATION_SCORES
-- Serial No: TBL-036
-- Description: Dynamic trust score based on verification, endorsements, and platform behavior
--
-- Business Case (300 words):
-- Static endorsements ("Jane endorsed John for Python") create perverse incentives:
-- users endorse back without genuine knowledge, creating artificially inflated
-- reputations. Employers cannot distinguish between an expert and someone who
-- merely collected endorsements. For a professional network, this degrades trust—
-- high endorsement counts become meaningless noise.
--
-- This table implements a dynamic, behavior-validated reputation system that
-- evolves with user actions. The trust score combines multiple weighted factors:
-- verified credentials (highest weight, cryptographically proven), peer endorsements
-- (weighted by the endorser's own trust score), platform behavior (completion rates,
-- response times, professionalism flags), and longevity (account age, consistent
-- activity).
--
-- The system uses a PageRank-like algorithm: endorsements from highly trusted
-- users contribute more weight. If User A (trust score 95) endorses User B for
-- Python, that endorsement is 8x more valuable than endorsements from unverified
-- users. This creates natural incentive: users build trust through verifiable
-- actions, then their endorsements carry genuine weight.
--
-- Behavioral signals include: profile completeness, message response rate, reported
-- content violations (inverse weight), successful collaborations, meeting attendance,
-- and contribution quality (in-depth comments vs. spam). The score decays over
-- time without recent positive activity, preventing "set and forget" reputation.
--
-- For anti-gaming, the system detects endorsement rings (groups inflating each
-- other's scores) and applies decay. Suspicious behavior (rapid trust increases,
-- patterns of false endorsements) triggers manual review. The reputation tier
-- determines platform access: features like "verified badge" only unlock at
-- TRUSTED tier.
--
-- Feature References:
-- TRS-01: Weighted trust scoring algorithm
-- TRS-02: Behavioral signal integration (completion, response, contributions)
-- TRS-03: Endorsement weighting by endorser trust
-- TRS-04: Time-based decay mechanism
-- TRS-05: Anti-gaming detection (endorsement rings)
-- TRS-07: Tier-based feature access
-- TRS-08: Historical score tracking
-- TRS-09: Transparency reports (score factors)
-- TRS-10: Manual override for appeals
-- TRS-11: Integration with verification system
-- TRS-12: Multi-dimensional reputation (by skill/category)
--------------------------------------------------------------------------------
CREATE TABLE trust_reputation_scores (
    -- Primary identifier
    reputation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User identification
    user_id UUID NOT NULL,
    tenant_id UUID NOT NULL,

    -- Current scores (0-100 scale)
    overall_score INTEGER NOT NULL CHECK (overall_score >= 0 AND overall_score <= 100),
    verification_score INTEGER CHECK (overall_score >= 0 AND overall_score <= 100),
    endorsement_score INTEGER CHECK (overall_score >= 0 AND overall_score <= 100),
    behavior_score INTEGER CHECK (overall_score >= 0 AND overall_score <= 100),
    longevity_score INTEGER CHECK (overall_score >= 0 AND overall_score <= 100),

    -- Reputation tier
    reputation_tier reputation_tier GENERATED ALWAYS AS (
        CASE
            WHEN overall_score >= 90 THEN 'HIGHLY_TRUSTED'::reputation_tier
            WHEN overall_score >= 75 THEN 'TRUSTED'::reputation_tier
            WHEN overall_score >= 60 THEN 'VERIFIED'::reputation_tier
            WHEN overall_score >= 40 THEN 'BASIC'::reputation_tier
            ELSE 'UNVERIFIED'::reputation_tier
        END
    ) STORED,

    -- Weighted factor configuration
    factor_weights JSONB NOT NULL DEFAULT '{
        "verification_weight": 0.40,
        "endorsement_weight": 0.25,
        "behavior_weight": 0.20,
        "longevity_weight": 0.15
    }'::JSONB,

    -- Multi-dimensional scores (per skill, per industry)
    skill_specific_scores JSONB,                         -- Trust per skill area
    industry_specific_scores JSONB,                      -- Trust per industry

    -- Verification component details
    verified_credential_count INTEGER DEFAULT 0,
    total_credential_weight INTEGER DEFAULT 0,           -- Sum of credential trust values

    -- Endorsement component details
    incoming_endorsement_count INTEGER DEFAULT 0,
    weighted_endorsement_value NUMERIC(10,2) DEFAULT 0,  -- Sum (endorser_trust * weight)
    unique_endorsers INTEGER DEFAULT 0,
    endorsement_decay_factor NUMERIC(5,4) DEFAULT 1.0,

    -- Behavior component details
    profile_completeness_percent INTEGER DEFAULT 0,
    message_response_rate NUMERIC(5,2),
    avg_response_time_hours NUMERIC(10,2),
    collaboration_count INTEGER DEFAULT 0,
    content_contribution_score INTEGER DEFAULT 0,
    professionalism_flags INTEGER DEFAULT 0,             -- Reports, violations
    flag_decay_factor NUMERIC(5,4) DEFAULT 1.0,

    -- Longevity component details
    account_age_days INTEGER DEFAULT 0,
    active_days_last_90 INTEGER DEFAULT 0,
    consistent_activity_score INTEGER DEFAULT 0,
    last_activity_date DATE,

    -- Time-based decay
    last_score_update TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    score_decay_rate NUMERIC(5,4) DEFAULT 0.01,          -- 1% decay per week without activity
    last_activity_bonus INTEGER DEFAULT 0,               -- Bonus for recent positive activity

    -- Anti-gaming detection
    endorsement_ring_detected BOOLEAN DEFAULT false,
    suspicious_activity_score INTEGER DEFAULT 0 CHECK (suspicious_activity_score BETWEEN 0 AND 100),
    manual_review_required BOOLEAN DEFAULT false,
    manual_override_score INTEGER,
    manual_override_reason TEXT,
    manual_overridden_by UUID,
    manual_override_at TIMESTAMP WITH TIME ZONE,

    -- Historical tracking (for trend analysis)
    previous_score INTEGER,
    score_trend VARCHAR(20) GENERATED ALWAYS AS (
        CASE
            WHEN overall_score > previous_score THEN 'IMPROVING'
            WHEN overall_score < previous_score THEN 'DECLINING'
            ELSE 'STABLE'
        END
    ) STORED,
    thirty_day_change INTEGER,

    -- Score components for transparency (user-visible)
    score_breakdown JSONB,                               -- Human-readable explanation
    -- Example: {"verification": "45/100 (3 verified credentials)",
    --           "endorsements": "28/100 (12 endorsements from trusted users)",
    --           "behavior": "15/20 (95% response rate)"}

    -- Audit trail for score changes
    score_history JSONB,                                 -- Snapshot of last 30 days

    -- Metadata
    metadata JSONB,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Indexes
    INDEX idx_trust_score_user (user_id, overall_score, reputation_tier),
    INDEX idx_trust_score_tier (reputation_tier, overall_score DESC),
    INDEX idx_trust_score_verification (verification_score, verified_credential_count),
    INDEX idx_trust_score_endorsement (weighted_endorsement_value DESC),
    INDEX idx_trust_score_suspicious (suspicious_activity_score, manual_review_required)
        WHERE suspicious_activity_score > 50 OR manual_review_required = true,

    FOREIGN KEY (user_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

COMMENT ON TABLE trust_reputation_scores IS 'Dynamic, behavior-validated reputation system with weighted scoring and anti-gaming';
COMMENT ON COLUMN trust_reputation_scores.overall_score IS 'Composite trust score (0-100) combining verification, endorsements, behavior, and longevity';
COMMENT ON COLUMN trust_reputation_scores.endorsement_ring_detected IS 'Algorithm flagged potential coordinated endorsement manipulation';
COMMENT ON COLUMN trust_reputation_scores.score_breakdown IS 'User-visible explanation of score components for transparency';

-- Row Level Security
ALTER TABLE trust_reputation_scores ENABLE ROW LEVEL SECURITY;

CREATE POLICY trust_score_user_policy ON trust_reputation_scores
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

-- Function to calculate trust score (called after verification or endorsement)
CREATE OR REPLACE FUNCTION calculate_trust_score(
    p_user_id UUID
)
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_verification_score INTEGER;
    v_endorsement_score INTEGER;
    v_behavior_score INTEGER;
    v_longevity_score INTEGER;
    v_weights JSONB;
    v_overall_score INTEGER;
BEGIN
    -- Calculate verification component (0-100)
    SELECT LEAST(100, COALESCE(SUM(trust_score_contribution), 0))
    INTO v_verification_score
    FROM credential_verifications
    WHERE user_id = p_user_id
      AND verification_status = 'VERIFIED';

    -- Calculate endorsement component (weighted by endorser trust)
    SELECT LEAST(100, COALESCE(SUM(weighted_value), 0) / GREATEST(unique_endorsers, 1))
    INTO v_endorsement_score
    FROM (
        SELECT
            e.target_user_id,
            SUM(trs.overall_score * e.weight) as weighted_value,
            COUNT(DISTINCT e.source_user_id) as unique_endorsers
        FROM endorsements e
        JOIN trust_reputation_scores trs ON trs.user_id = e.source_user_id
        WHERE e.target_user_id = p_user_id
          AND e.is_active = true
        GROUP BY e.target_user_id
    ) endorsement_stats;

    -- Calculate behavior component
    SELECT LEAST(100,
        (profile_completeness_percent * 0.3) +
        (COALESCE(message_response_rate, 0) * 0.3) +
        (LEAST(50, collaboration_count) * 0.2) +
        (content_contribution_score * 0.2) -
        (professionalism_flags * 5)
    )
    INTO v_behavior_score
    FROM user_behavior_metrics
    WHERE user_id = p_user_id;

    -- Calculate longevity component
    SELECT LEAST(100,
        (account_age_days / 365.0 * 40) +
        (active_days_last_90 * 0.6)
    )
    INTO v_longevity_score
    FROM user_longevity_metrics
    WHERE user_id = p_user_id;

    -- Get weight configuration
    SELECT factor_weights INTO v_weights
    FROM trust_reputation_scores
    WHERE user_id = p_user_id;

    IF v_weights IS NULL THEN
        v_weights := '{"verification_weight": 0.40, "endorsement_weight": 0.25,
                       "behavior_weight": 0.20, "longevity_weight": 0.15}'::JSONB;
    END IF;

    -- Calculate overall score
    v_overall_score :=
        (v_verification_score * (v_weights->>'verification_weight')::NUMERIC) +
        (v_endorsement_score * (v_weights->>'endorsement_weight')::NUMERIC) +
        (v_behavior_score * (v_weights->>'behavior_weight')::NUMERIC) +
        (v_longevity_score * (v_weights->>'longevity_weight')::NUMERIC);

    -- Apply decay and update
    UPDATE trust_reputation_scores
    SET
        overall_score = v_overall_score,
        verification_score = v_verification_score,
        endorsement_score = v_endorsement_score,
        behavior_score = v_behavior_score,
        longevity_score = v_longevity_score,
        previous_score = COALESCE(overall_score, 0),
        thirty_day_change = v_overall_score - COALESCE(overall_score, 0),
        score_breakdown = jsonb_build_object(
            'verification', jsonb_build_object('score', v_verification_score, 'out_of', 100),
            'endorsement', jsonb_build_object('score', v_endorsement_score, 'out_of', 100),
            'behavior', jsonb_build_object('score', v_behavior_score, 'out_of', 100),
            'longevity', jsonb_build_object('score', v_longevity_score, 'out_of', 100)
        ),
        updated_at = NOW()
    WHERE user_id = p_user_id;

    RETURN v_overall_score;
END;
$$;

-- Trigger to update trust score on credential verification
CREATE OR REPLACE FUNCTION trust_score_on_verification()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.verification_status = 'VERIFIED' AND OLD.verification_status != 'VERIFIED' THEN
        PERFORM calculate_trust_score(NEW.user_id);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_trust_score_verification
    AFTER UPDATE OF verification_status ON credential_verifications
    FOR EACH ROW
    EXECUTE FUNCTION trust_score_on_verification();

-- =============================================================================
-- SUPPORTING TABLES FOR ENDORSEMENT SYSTEM
-- =============================================================================

--------------------------------------------------------------------------------
-- Table: ENDORSEMENTS
-- Description: Peer endorsements with weight based on endorser trust
--------------------------------------------------------------------------------
CREATE TABLE endorsements (
    endorsement_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    source_user_id UUID NOT NULL,                         -- Endorser
    target_user_id UUID NOT NULL,                         -- Recipient
    skill_name VARCHAR(255) NOT NULL,

    weight NUMERIC(5,4) DEFAULT 1.0 CHECK (weight >= 0 AND weight <= 1), -- 1.0 = full weight
    is_active BOOLEAN DEFAULT true,

    endorsed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    -- Anti-fraud
    source_ip INET,
    user_agent TEXT,

    -- Indexes
    INDEX idx_endorsements_target (target_user_id, skill_name, weight DESC),
    INDEX idx_endorsements_source (source_user_id),
    CONSTRAINT endorsements_unique UNIQUE (source_user_id, target_user_id, skill_name)
);

--------------------------------------------------------------------------------
-- Table: USER_BEHAVIOR_METRICS (aggregated for trust scoring)
--------------------------------------------------------------------------------
CREATE TABLE user_behavior_metrics (
    user_id UUID PRIMARY KEY,

    profile_completeness_percent INTEGER DEFAULT 0,
    message_response_rate NUMERIC(5,2),
    avg_response_time_hours NUMERIC(10,2),
    collaboration_count INTEGER DEFAULT 0,
    content_contribution_score INTEGER DEFAULT 0,
    professionalism_flags INTEGER DEFAULT 0,

    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

--------------------------------------------------------------------------------
-- Table: USER_LONGEVITY_METRICS
--------------------------------------------------------------------------------
CREATE TABLE user_longevity_metrics (
    user_id UUID PRIMARY KEY,

    account_age_days INTEGER DEFAULT 0,
    active_days_last_90 INTEGER DEFAULT 0,
    consistent_activity_score INTEGER DEFAULT 0,
    last_activity_date DATE,
    join_date DATE,

    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Grant permissions
GRANT SELECT, INSERT, UPDATE ON credential_verifications, blockchain_credential_ledger,
    trust_reputation_scores, endorsements, user_behavior_metrics, user_longevity_metrics TO ap_application;
GRANT EXECUTE ON FUNCTION calculate_trust_score, anchor_credential_to_blockchain TO ap_application;


-- =============================================================================
-- COLLABORATION & PROJECT ECONOMY TABLES
-- Phase: Project Collaboration & Creator Monetization
-- =============================================================================

--------------------------------------------------------------------------------
-- ENUM: project_type
-- Description: Types of collaborative projects supported by the platform
-- Business Case: Enables specialized workflows and tooling per project category
-- Feature Reference: CP-02 (Project Categorization)
--------------------------------------------------------------------------------
CREATE TYPE project_type AS ENUM (
    'OPEN_SOURCE',      -- Open source software contribution
    'HACKATHON',        -- Time-bound competitive event
    'CONSULTING',       -- Paid professional services
    'VOLUNTEER',        -- Non-profit / pro-bono work
    'RESEARCH',         -- Academic or industry research
    'CREATIVE',         -- Design, writing, media projects
    'MENTORING'         -- Structured mentoring program
);

--------------------------------------------------------------------------------
-- ENUM: contribution_type
-- Description: Types of contributions to collaborative projects
-- Business Case: Provides granular recognition for different work types
-- Feature Reference: PC-03 (Contribution Granularity)
--------------------------------------------------------------------------------
CREATE TYPE contribution_type AS ENUM (
    'CODE_COMMIT',      -- Source code contribution
    'DOCUMENTATION',    -- Writing, guides, README
    'DESIGN',           -- UI/UX, graphics, assets
    'REVIEW',           -- Code review, feedback
    'TESTING',          -- QA, bug reports
    'PROJECT_MGMT',     -- Coordination, planning
    'CONTENT',          -- Articles, tutorials
    'MENTORING',        -- Guiding other contributors
    'FUNDING',          -- Financial contribution
    'INFRASTRUCTURE'    -- DevOps, hosting, tooling
);

--------------------------------------------------------------------------------
-- ENUM: subscription_tier
-- Description: Creator subscription access levels
-- Business Case: Enables graduated monetization for creator content
-- Feature Reference: CS-03 (Tiered Access)
--------------------------------------------------------------------------------
CREATE TYPE subscription_tier AS ENUM (
    'FREE',             -- Basic access, public content
    'PREMIUM',          -- Exclusive content, community access
    'VIP',              -- All premium + 1:1 AMAs, early access
    'CORPORATE'         -- Team/company subscriptions
);

--------------------------------------------------------------------------------
-- ENUM: tip_type
-- Description: Types of content tipping mechanisms
-- Business Case: Supports diverse micro-payment scenarios
-- Feature Reference: CT-04 (Tip Categorization)
--------------------------------------------------------------------------------
CREATE TYPE tip_type AS ENUM (
    'CONTENT_TIP',      -- Tip for specific post/article
    'HELPFUL_REVIEW',   -- Tip for product/service review
    'ADVICE',           -- Tip for consulting advice
    'COLLABORATION',    -- Tip for project contribution
    'SUPPORTER'         -- General creator support
);

--------------------------------------------------------------------------------
-- ENUM: affiliate_status
-- Description: Affiliate opportunity lifecycle states
-- Business Case: Tracks referral from click to commission
-- Feature Reference: AF-05 (Conversion Tracking)
--------------------------------------------------------------------------------
CREATE TYPE affiliate_status AS ENUM (
    'PENDING',          -- Created, not yet active
    'ACTIVE',           -- Available for promotion
    'EXPIRED',          -- Time window ended
    'PAUSED',           -- Temporarily unavailable
    'COMPLETED'         -- Fully fulfilled/paid
);

--------------------------------------------------------------------------------
-- Table: COLLABORATION_PROJECTS
-- Serial No: TBL-037
-- Description: Open professional projects (open-source, hackathons, consulting) with co-created work
--
-- Business Case (300 words):
-- Professional networks excel at showcasing "what you've done" but fail at supporting
-- "what you're doing together." Users post static portfolios of past work but lack
-- infrastructure for live collaboration. GitHub demonstrates open-source collaboration
-- value, but no professional network offers similar tools for non-developers—
-- designers, writers, researchers, and consultants lack platforms to co-create visibly.
--
-- This table transforms the platform from passive resume repository to active
-- collaboration hub. Users create or join projects with defined goals, milestones,
-- and visible contribution tracking. Unlike isolated "posts," projects show
-- ongoing work with commit histories, deliverables, and peer recognition. A
-- designer can showcase a Figma file evolution; a writer shows draft iterations
-- with co-author attribution; an open-source maintainer demonstrates community
-- contributions.
--
-- Each project has configurable visibility: public (portfolio-worthy), team-only
-- (internal collaboration), or private. Projects can be commercial (paid consulting)
-- or volunteer (open source, non-profit). The system integrates with external
-- tools: GitHub API syncs commits, Figma exports designs, Google Docs tracks
-- collaborative writing. API webhooks automatically log contributions.
--
-- For organizations, team projects demonstrate internal collaboration to external
-- talent—a "culture of documentation" becomes visible through wiki contributions.
-- For job seekers, project contributions provide verifiable work history independent
-- of employment gaps or NDAs (with redaction tools). The platform becomes a
-- legitimate alternative to resumes: "Here are 47 commits to TensorFlow, 12 design
-- reviews, and 3 published papers" proves competency more convincingly than
-- "5 years Python experience."
--
-- Feature References:
-- CP-01: Project lifecycle management (create, join, leave, archive)
-- CP-03: Role-based access controls (owner, maintainer, contributor, viewer)
-- CP-04: External tool integration (GitHub, GitLab, Figma, Google Docs)
-- CP-05: Milestone and deliverable tracking
-- CP-06: Contribution attribution and weighting
-- CP-07: Portfolio embedding (showcase projects on profile)
-- CP-08: Team collaboration spaces
-- CP-09: Commercial project support (payments, contracts)
-- CP-10: NDA/confidentiality tools for private projects
-- CP-11: Project discovery and matching
-- CP-12: Skill development tracking
--
-- Key Performance Indicators (KPIs):
-- 1. Active Collaboration Rate - % users in at least one active project
-- 2. Project Completion Rate - % reaching milestone completion
-- 3. Cross-Organization Collaboration - % projects with >1 company/org
-- 4. Tool Integration Adoption - % projects using external sync
-- 5. Contribution Velocity - Avg commits/deliverables per project per week
-- 6. Project-to-Job Conversion - % projects leading to employment
-- 7. Skill Demonstration Efficacy - % recruiters viewing project contributions
-- 8. Retention Lift - User churn reduction among active collaborators
-- 9. Open Source Contribution Growth - % YoY increase in OSS projects
-- 10. Commercial Project Revenue - $ volume through platform
--------------------------------------------------------------------------------
CREATE TABLE collaboration_projects (
    -- Primary identifier
    project_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    project_number VARCHAR(50) GENERATED ALWAYS AS (
        'PROJ-' || LPAD(EXTRACT(YEAR FROM created_at)::TEXT, 4, '0') || '-' ||
        LPAD(project_id::TEXT, 10, '0')
    ) STORED UNIQUE,

    -- Project identification
    project_name VARCHAR(500) NOT NULL,
    project_description TEXT NOT NULL,
    project_type project_type NOT NULL,

    -- Ownership and roles
    owner_id UUID NOT NULL,
    tenant_id UUID NOT NULL,
    owner_team_id UUID,

    -- Team composition
    team_members JSONB DEFAULT '[]'::JSONB,              -- Array of {user_id, role, joined_at}
    -- Example: [{"user_id": "uuid1", "role": "maintainer", "joined_at": "2024-01-01"}]

    max_members INTEGER,
    is_open_for_joining BOOLEAN DEFAULT true,
    join_approval_required BOOLEAN DEFAULT false,

    -- Project scope and goals
    project_goals TEXT,
    milestones JSONB,                                     -- Key deliverables with dates
    -- Example: [{"title": "MVP Launch", "due_date": "2024-03-01", "completed": false}]

    -- Commercial configuration (for consulting/paid projects)
    is_commercial BOOLEAN DEFAULT false,
    budget_amount NUMERIC(10,2),
    budget_currency CHAR(3) DEFAULT 'USD',
    payment_terms TEXT,

    -- Visibility and access
    visibility VARCHAR(50) DEFAULT 'PUBLIC' CHECK (visibility IN ('PUBLIC', 'TEAM', 'PRIVATE', 'ENTERPRISE')),
    requires_nda BOOLEAN DEFAULT false,
    nda_content TEXT,

    -- External integrations
    external_repositories JSONB DEFAULT '{}'::JSONB,     -- GitHub, GitLab, etc.
    -- Example: {"github": {"repo": "org/repo", "webhook_id": "123"}, "figma": {"file_id": "abc"}}

    -- Contribution settings
    contribution_types_enabled contribution_type[] DEFAULT ARRAY['CODE_COMMIT']::contribution_type[],
    auto_verify_contributions BOOLEAN DEFAULT true,      -- Trust API/webhook data

    -- Status tracking
    status VARCHAR(50) DEFAULT 'PLANNING' CHECK (status IN
        ('PLANNING', 'ACTIVE', 'PAUSED', 'COMPLETED', 'ARCHIVED', 'CANCELLED')),
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,

    -- Media and branding
    project_logo_url TEXT,
    project_banner_url TEXT,
    project_tags TEXT[],

    -- Analytics
    total_contributions INTEGER DEFAULT 0,
    total_contributors INTEGER DEFAULT 0,
    total_views INTEGER DEFAULT 0,
    total_forks INTEGER DEFAULT 0,                        -- Project copies/splits

    -- Discovery and matching
    required_skills TEXT[],
    looking_for_roles TEXT[],
    project_difficulty VARCHAR(50) CHECK (project_difficulty IN ('BEGINNER', 'INTERMEDIATE', 'ADVANCED', 'EXPERT')),

    -- Communication
    chat_channel_url TEXT,
    meeting_schedule VARCHAR(255),

    -- Metadata
    metadata JSONB DEFAULT '{}',

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Indexes
    INDEX idx_projects_owner (owner_id, status),
    INDEX idx_projects_type (project_type, status, is_open_for_joining),
    INDEX idx_projects_visibility (visibility, status),
    INDEX idx_projects_tags USING gin(project_tags),
    INDEX idx_projects_skills USING gin(required_skills),
    INDEX idx_projects_members USING gin(team_members),
    INDEX idx_projects_search (project_name, project_description)  -- Gin trigram would be added

    -- FK constraints
    -- FOREIGN KEY (owner_id, tenant_id) REFERENCES tenant_configurations(tenant_id)
);

COMMENT ON TABLE collaboration_projects IS 'Platform for co-created professional work with visible contribution tracking';
COMMENT ON COLUMN collaboration_projects.external_repositories IS 'Integration config for GitHub, GitLab, Figma, Google Docs auto-sync';
COMMENT ON COLUMN collaboration_projects.milestones IS 'Time-bound deliverables with completion tracking';

-- Row Level Security
ALTER TABLE collaboration_projects ENABLE ROW LEVEL SECURITY;

CREATE POLICY projects_owner_policy ON collaboration_projects
    USING (owner_id = current_setting('app.current_user_id', true)::UUID);

CREATE POLICY projects_member_policy ON collaboration_projects
    USING (EXISTS (
        SELECT 1 FROM jsonb_array_elements(team_members) AS member
        WHERE member->>'user_id' = current_setting('app.current_user_id', true)
    ));

CREATE POLICY projects_public_read_policy ON collaboration_projects
    FOR SELECT USING (visibility = 'PUBLIC' AND status != 'ARCHIVED');

--------------------------------------------------------------------------------
-- Table: PROJECT_CONTRIBUTIONS
-- Serial No: TBL-038
-- Description: Tracks commits, deliverables, peer reviews, and skill gains
--
-- Business Case (300 words):
-- Employment history creates gaps: freelancers lack "official" employment records,
-- career-changers' previous industries seem irrelevant, and NDA-protected work
-- can't be discussed. Traditional resumes fail to capture granular, verifiable
-- work history. Project contributions solve this: every commit, design review,
-- or documentation edit becomes a permanent, verifiable artifact.
--
-- This table captures every contribution to collaborative projects with cryptographic
-- integrity. Each contribution includes type (code, design, review), quantitative
-- metrics (lines of code, hours worked, files changed), peer reviews (endorsements
-- from project maintainers), and skill gains (new skills demonstrated).
--
-- The system auto-verifies contributions via API integrations: GitHub webhooks log
-- commits, Figma API captures design versions, Google Docs revision history tracks
-- edits. For manual contributions (meetings, consulting hours), verification
-- requires peer sign-off. This creates tamper-evident work history that employers
-- trust more than self-reported resumes.
--
-- Contribution weight accounts for significance: a critical bug fix might weight
-- higher than typo correction; lead architect contributions weight higher than
-- documentation. Peer endorsements multiply weight: 3 maintainers approving a
-- contribution signals high quality. The trust reputation system uses contribution
-- history as a primary signal for expertise scoring.
--
-- For skill portfolio, contributions automatically add to user's skill graph
-- with proficiency levels inferred from contribution complexity and volume.
-- A user with 50 TypeScript commits and 5 peer reviews for TypeScript work
-- receives higher skill verification than self-reported "TypeScript: 5 years."
--
-- Feature References:
-- PC-01: Granular contribution capture (code, design, content, review)
-- PC-02: Auto-verification via API/webhook integrations
-- PC-04: Contribution weighting and significance scoring
-- PC-05: Peer review and endorsement integration
-- PC-06: Skill inference from contribution patterns
-- PC-07: Verifiable work history for employment gaps
-- PC-08: NDA-safe contribution redaction
-- PC-09: Export to resume/CV formats
-- PC-10: Time tracking and effort estimation
-- PC-11: Contribution feed for recruiters
-- PC-12: Badge and achievement generation
--------------------------------------------------------------------------------
CREATE TABLE project_contributions (
    -- Primary identifier
    contribution_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Project context
    project_id UUID NOT NULL REFERENCES collaboration_projects(project_id) ON DELETE CASCADE,
    user_id UUID NOT NULL,

    -- Contribution details
    contribution_type contribution_type NOT NULL,
    contribution_title VARCHAR(500) NOT NULL,
    contribution_description TEXT,

    -- Quantitative metrics
    quantity_value NUMERIC(10,2),                         -- Lines of code, hours, files
    quantity_unit VARCHAR(50),                            -- "lines", "hours", "files", "commits"
    complexity_score INTEGER CHECK (complexity_score BETWEEN 1 AND 10),

    -- Artifact links
    artifact_url TEXT,                                    -- Link to commit, PR, design file
    artifact_hash VARCHAR(255),                           -- Git commit hash, file hash
    artifact_version VARCHAR(100),

    -- Verification
    auto_verified BOOLEAN DEFAULT false,
    verification_source VARCHAR(100),                     -- github_webhook, figma_api, manual
    verification_timestamp TIMESTAMP WITH TIME ZONE,
    verification_data JSONB,                              -- Raw API/webhook payload

    -- Peer review
    peer_reviews JSONB DEFAULT '[]'::JSONB,
    -- Example: [{"reviewer_id": "uuid", "rating": 5, "comment": "Excellent work", "reviewed_at": "..."}]
    average_peer_rating NUMERIC(3,2),
    peer_endorsement_count INTEGER DEFAULT 0,

    -- Significance weighting
    base_weight NUMERIC(5,4) DEFAULT 1.0,
    significance_multiplier NUMERIC(5,4) DEFAULT 1.0,     -- Based on peer reviews, complexity
    total_weight NUMERIC(5,4) GENERATED ALWAYS AS (base_weight * significance_multiplier) STORED,

    -- Skill gain inference
    skills_demonstrated TEXT[],
    skill_proficiency_inferred INTEGER,                   -- 1-10 inferred from contribution
    skill_verified_by_project BOOLEAN DEFAULT false,

    -- Time tracking
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    duration_minutes INTEGER,

    -- Status
    status VARCHAR(50) DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'VERIFIED', 'REJECTED', 'ARCHIVED')),

    -- Stakeholder attribution
    attributed_by UUID,                                   -- Who added this contribution
    attributed_method VARCHAR(50) CHECK (attributed_method IN ('AUTO', 'SELF', 'PEER', 'MAINTAINER')),

    -- NDA redaction
    is_redacted BOOLEAN DEFAULT false,
    redacted_version TEXT,
    redaction_reason TEXT,
    redacted_by UUID,
    redacted_at TIMESTAMP WITH TIME ZONE,

    -- Badges earned from this contribution
    badges_earned TEXT[],

    -- Metadata
    metadata JSONB DEFAULT '{}',

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,

    -- Indexes
    INDEX idx_contributions_user (user_id, contributed_at DESC),
    INDEX idx_contributions_project (project_id, contribution_type),
    INDEX idx_contributions_skills USING gin(skills_demonstrated),
    INDEX idx_contributions_verification (auto_verified, verification_source),
    INDEX idx_contributions_weight (total_weight DESC),
    INDEX idx_contributions_time (contributed_at)
);

ALTER TABLE project_contributions ADD COLUMN contributed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW();

COMMENT ON TABLE project_contributions IS 'Granular, verifiable work contributions with peer validation and skill inference';
COMMENT ON COLUMN project_contributions.total_weight IS 'Composite weight = base_weight × significance_multiplier for reputation scoring';

-- Row Level Security
ALTER TABLE project_contributions ENABLE ROW LEVEL SECURITY;

CREATE POLICY contributions_user_policy ON project_contributions
    USING (user_id = current_setting('app.current_user_id', true)::UUID);

-- Trigger to auto-update project contribution counts
CREATE OR REPLACE FUNCTION update_project_contribution_stats()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'VERIFIED' THEN
        UPDATE collaboration_projects
        SET total_contributions = total_contributions + 1,
            total_contributors = (SELECT COUNT(DISTINCT user_id) FROM project_contributions
                                  WHERE project_id = NEW.project_id AND status = 'VERIFIED')
        WHERE project_id = NEW.project_id;
    ELSIF TG_OP = 'UPDATE' AND OLD.status != 'VERIFIED' AND NEW.status = 'VERIFIED' THEN
        UPDATE collaboration_projects
        SET total_contributions = total_contributions + 1
        WHERE project_id = NEW.project_id;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_project_contribution_stats
    AFTER INSERT OR UPDATE OF status ON project_contributions
    FOR EACH ROW
    EXECUTE FUNCTION update_project_contribution_stats();

--------------------------------------------------------------------------------
-- Table: MENTORSHIP_MATCHES
-- Serial No: TBL-039
-- Description: AI-matched mentorship with goal tracking and session logging
--
-- Business Case (300 words):
-- LinkedIn connections are static, unstructured, and rarely lead to meaningful
-- mentorship. Users collect thousands of "connections" but lack mechanisms for
-- structured learning relationships. Aspiring mentors want to give back but
-- struggle to find mentees; mentees seek guidance but don't know how to request it.
--
-- This table implements an AI-powered mentorship matching system that goes beyond
-- random pairing. The algorithm considers multiple dimensions: career stage
-- (mentor has 5+ years more experience), skill alignment (mentee wants Python,
-- mentor specializes in Python), industry relevance, communication preferences,
-- time availability, and learning goals.
--
-- Once matched, the system structures the relationship: mentee sets learning goals
-- (e.g., "transition to management within 6 months"), mentor proposes meeting
-- cadence (bi-weekly, 1 hour), and the platform schedules sessions with calendar
-- integration. Each session is logged with topics covered, action items, and
-- feedback. Progress toward goals is tracked, triggering re-matching if stagnant.
--
-- Quality metrics ensure effectiveness: mentee satisfaction surveys, goal completion
-- rates, and promotion/transition outcomes. Low-rated mentors are removed from
-- matching pool; under-attending mentees receive reminders. The system integrates
-- with the trust reputation score: successful mentorship boosts both parties' scores.
--
-- For enterprises, the platform supports internal mentorship programs (senior
-- engineers mentoring juniors) with reporting dashboards for HR. For career
-- accelerators, group mentorship cohorts enable 1:many relationships (one mentor,
-- 5 mentees).
--
-- Feature References:
-- MS-01: Multi-factor AI mentorship matching
-- MS-02: Structured goal setting and tracking
-- MS-03: Session logging with outcomes
-- MS-04: Satisfaction and effectiveness ratings
-- MS-05: Calendar integration (Google, Outlook)
-- MS-06: Communication channel integration
-- MS-07: Group mentorship support
-- MS-08: Enterprise program management
-- MS-09: Mentor/mentee skill development tracking
-- MS-10: Re-matching and progression algorithms
-- MS-11: Reporting and analytics suite
-- MS-12: Escalation for low engagement
--------------------------------------------------------------------------------
CREATE TABLE mentorship_matches (
    -- Primary identifier
    match_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    match_number VARCHAR(50) GENERATED ALWAYS AS (
        'MENTOR-' || LPAD(EXTRACT(YEAR FROM created_at)::TEXT, 4, '0') || '-' ||
        LPAD(match_id::TEXT, 10, '0')
    ) STORED UNIQUE,

    -- Participants
    mentee_id UUID NOT NULL,
    mentor_id UUID NOT NULL,
    tenant_id UUID NOT NULL,

    -- Matching metadata
    match_score NUMERIC(5,2) CHECK (match_score BETWEEN 0 AND 100),
    match_factors JSONB,                                 -- Why they were matched
    -- Example: {"skill_alignment": 95, "industry_match": 85, "availability_overlap": "weekly"}

    -- Goals and expectations
    mentee_goals TEXT NOT NULL,
    mentor_offering TEXT NOT NULL,
    success_criteria JSONB,
    -- Example: {"promotion_target": "Senior Engineer", "skills_to_learn": ["System Design"], "timeframe_months": 6}

    -- Schedule configuration
    meeting_cadence VARCHAR(50) DEFAULT 'BI_WEEKLY' CHECK (meeting_cadence IN ('WEEKLY', 'BI_WEEKLY', 'MONTHLY', 'FLEXIBLE')),
    meeting_duration_minutes INTEGER DEFAULT 60,
    preferred_day VARCHAR(20),
    preferred_time TIME,
    timezone VARCHAR(100),

    -- Calendar integration
    calendar_integration JSONB DEFAULT '{}'::JSONB,
    -- Example: {"provider": "google", "calendar_id": "primary", "meeting_link": "meet.google.com/abc"}

    -- Communication preferences
    preferred_channel VARCHAR(50) DEFAULT 'VIDEO_CALL' CHECK (preferred_channel IN
        ('VIDEO_CALL', 'CHAT', 'EMAIL', 'IN_PERSON', 'FLEXIBLE')),

    -- Progress tracking
    current_status VARCHAR(50) DEFAULT 'ACTIVE' CHECK (current_status IN
        ('PENDING_ACCEPTANCE', 'ACTIVE', 'PAUSED', 'COMPLETED', 'REJECTED', 'EXPIRED')),

    mentee_progress_score INTEGER DEFAULT 0 CHECK (mentee_progress_score BETWEEN 0 AND 100),
    mentor_engagement_score INTEGER DEFAULT 0 CHECK (mentor_engagement_score BETWEEN 0 AND 100),

    -- Session metrics
    total_sessions INTEGER DEFAULT 0,
    total_sessions_attended INTEGER DEFAULT 0,
    total_sessions_missed INTEGER DEFAULT 0,
    last_session_at TIMESTAMP WITH TIME ZONE,
    next_session_scheduled_at TIMESTAMP WITH TIME ZONE,

    -- Goal completion
    goals_achieved_count INTEGER DEFAULT 0,
    goals_total_count INTEGER,
    goal_completion_rate NUMERIC(5,2),

    -- Satisfaction ratings
    mentee_satisfaction_avg NUMERIC(3,2) CHECK (mentee_satisfaction_avg BETWEEN 1 AND 5),
    mentor_satisfaction_avg NUMERIC(3,2) CHECK (mentor_satisfaction_avg BETWEEN 1 AND 5),

    -- Expiration and renewal
    expected_end_date DATE,
    actual_end_date DATE,
    renewal_offered BOOLEAN DEFAULT false,
    renewal_accepted BOOLEAN,

    -- Escalation
    is_escalated BOOLEAN DEFAULT false,
    escalation_reason TEXT,
    escalated_to UUID,
    escalated_at TIMESTAMP WITH TIME ZONE,

    -- Trust impact
    trust_score_impact_mentee INTEGER,
    trust_score_impact_mentor INTEGER,

    -- Metadata
    metadata JSONB DEFAULT '{}',

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() NOT NULL,
    created_by UUID NOT NULL,

    -- Indexes
    INDEX idx_mentorship_mentee (mentee_id, current_status),
    INDEX idx_mentorship_mentor (mentor_id, current_status),
    INDEX idx_mentorship_status (current_status, match_score DESC),
    INDEX idx_mentorship_expiry (expected_end_date) WHERE current_status = 'ACTIVE',
    INDEX idx_mentorship_sessions (total_sessions, last_session_at),

    FOREIGN KEY (mentee_id, tenant_id) REFERENCES tenant_configurations(tenant_id),
    FOREIGN KEY (mentor_id, tenant_id) REFERENCES tenant_configurations(tenant_id),
    CONSTRAINT mentorship_different_users CHECK (mentee_id != mentor_id)
);

COMMENT ON TABLE mentorship_matches IS 'AI-matched structured mentorship relationships with goal tracking and session logging';
COMMENT ON COLUMN mentorship_matches.match_factors IS 'Transparent matching criteria for explainability';
COMMENT ON COLUMN mentorship_matches.mentee_progress_score IS 'Algorithmic assessment of goal progression';

-- Row Level Security
ALTER TABLE mentorship_matches ENABLE ROW LEVEL SECURITY;

CREATE POLICY mentorship_participant_policy ON mentorship_matches
    USING (mentee_id = current_setting('app.current_user_id', true)::UUID OR
           mentor_id = current_setting('app.current_user_id', true)::UUID);

--------------------------------------------------------------------------------
-- Table: MENTORSHIP_SESSIONS
-- Description: Individual mentorship meeting logs with outcomes
--------------------------------------------------------------------------------
CREATE TABLE mentorship_sessions (
    session_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    match_id UUID NOT NULL REFERENCES mentorship_matches(match_id) ON DELETE CASCADE,

    -- Session details
    session_date TIMESTAMP WITH TIME ZONE NOT NULL,
    duration_minutes INTEGER,
    topics_covered TEXT[],

    -- Artifacts
    meeting_notes TEXT,
    recording_url TEXT,
    action_items TEXT[],
    resources_shared TEXT[],

    -- Attendance
    mentee_attended BOOLEAN DEFAULT true,
    mentor_attended BOOLEAN DEFAULT true,
    missed_reason TEXT,

    -- Feedback
    mentee_rating INTEGER CHECK (mentee_rating BETWEEN 1 AND 5),
    mentee_feedback TEXT,
    mentor_rating INTEGER CHECK (mentor_rating BETWEEN 1 AND 5),
    mentor_feedback TEXT,

    -- Learning outcomes
    skills_practiced TEXT[],
    next_session_goals TEXT,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_mentorship_sessions_match (match_id, session_date DESC)
);

--------------------------------------------------------------------------------
-- Table: CREATOR_SUBSCRIPTIONS
-- Description: Tiered access to premium creator content and community
--------------------------------------------------------------------------------
CREATE TABLE creator_subscriptions (
    subscription_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Creator and subscriber
    creator_id UUID NOT NULL,
    subscriber_id UUID NOT NULL,
    tenant_id UUID NOT NULL,

    -- Subscription tier
    tier subscription_tier NOT NULL,
    price_amount NUMERIC(10,2) NOT NULL,
    price_currency CHAR(3) DEFAULT 'USD',
    billing_cycle VARCHAR(20) DEFAULT 'MONTHLY' CHECK (billing_cycle IN ('MONTHLY', 'ANNUAL')),

    -- Access permissions (JSON representation of tier benefits)
    access_permissions JSONB,
    -- Example: {"exclusive_posts": true, "community_access": true, "ama_slots_per_month": 2}

    -- Status
    status VARCHAR(50) DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'CANCELED', 'EXPIRED', 'PAST_DUE')),

    -- Dates
    started_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    current_period_start TIMESTAMP WITH TIME ZONE,
    current_period_end TIMESTAMP WITH TIME ZONE,
    canceled_at TIMESTAMP WITH TIME ZONE,

    -- Renewal
    auto_renew BOOLEAN DEFAULT true,
    cancel_at_period_end BOOLEAN DEFAULT false,

    -- Payment
    payment_method_id UUID,
    external_subscription_id VARCHAR(255),

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_creator_subscriptions_creator (creator_id, status),
    INDEX idx_creator_subscriptions_subscriber (subscriber_id, status),
    UNIQUE(creator_id, subscriber_id, tier, status) WHERE status = 'ACTIVE'
);

--------------------------------------------------------------------------------
-- Table: CONTENT_TIPS
-- Description: Micro-payments for high-value content with tipping
--------------------------------------------------------------------------------
CREATE TABLE content_tips (
    tip_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Content and parties
    content_id UUID NOT NULL,                              -- Post, comment, review
    content_type VARCHAR(50) CHECK (content_type IN ('POST', 'COMMENT', 'REVIEW', 'ARTICLE', 'PROJECT')),
    tipper_id UUID NOT NULL,
    recipient_id UUID NOT NULL,

    -- Tip details
    tip_type tip_type NOT NULL,
    amount NUMERIC(10,2) NOT NULL,
    currency CHAR(3) DEFAULT 'USD',

    -- Message
    message TEXT,
    is_anonymous BOOLEAN DEFAULT false,

    -- Status
    status VARCHAR(50) DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'COMPLETED', 'REFUNDED', 'FAILED')),

    -- Payment
    payment_id UUID,
    gateway_transaction_id VARCHAR(255),
    platform_fee_amount NUMERIC(10,2),
    creator_amount NUMERIC(10,2) GENERATED ALWAYS AS (amount - platform_fee_amount) STORED,

    -- Display
    is_publicly_shown BOOLEAN DEFAULT true,               -- Show in "Top Tips" leaderboard

    tipped_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_content_tips_recipient (recipient_id, tipped_at DESC),
    INDEX idx_content_tips_content (content_id, content_type),
    INDEX idx_content_tips_tipper (tipper_id)
);

--------------------------------------------------------------------------------
-- Table: AFFILIATE_OPPORTUNITIES
-- Description: B2B referral tracking with commission attribution
--------------------------------------------------------------------------------
CREATE TABLE affiliate_opportunities (
    opportunity_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Program details
    program_name VARCHAR(255) NOT NULL,
    program_description TEXT,
    advertiser_id UUID NOT NULL,                           -- Company offering commission
    advertiser_tenant_id UUID NOT NULL,

    -- Commission structure
    commission_model VARCHAR(50) CHECK (commission_model IN ('FIXED', 'PERCENTAGE', 'TIERED', 'RECURRING')),
    commission_value NUMERIC(10,2),                        -- Fixed amount or percentage
    commission_currency CHAR(3) DEFAULT 'USD',

    tiered_commissions JSONB,                             -- For TIERED model
    -- Example: [{"min_amount": 0, "commission": 10}, {"min_amount": 10000, "commission": 15}]

    recurring_duration_months INTEGER,                     -- For recurring commission

    -- Conversion tracking
    attribution_window_days INTEGER DEFAULT 30,            -- Cookie/click window
    conversion_required VARCHAR(100),                     -- "SIGNUP", "PAID_SUBSCRIPTION", "PURCHASE"

    -- Promotional content
    affiliate_links TEXT[],
    promo_codes TEXT[],
    marketing_materials TEXT[],

    -- Targeting
    allowed_affiliate_tiers subscription_tier[],
    minimum_follower_count INTEGER,
    required_skills TEXT[],

    -- Status and dates
    status affiliate_status DEFAULT 'PENDING',
    starts_at TIMESTAMP WITH TIME ZONE,
    ends_at TIMESTAMP WITH TIME ZONE,

    -- Payout schedule
    payout_schedule VARCHAR(50) DEFAULT 'MONTHLY' CHECK (payout_schedule IN ('WEEKLY', 'MONTHLY', 'NET_30', 'NET_60')),
    minimum_payout_amount NUMERIC(10,2) DEFAULT 50,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_affiliate_opportunities_advertiser (advertiser_id, status),
    INDEX idx_affiliate_opportunities_date (starts_at, ends_at),
    INDEX idx_affiliate_opportunities_active (status, starts_at) WHERE status = 'ACTIVE'
);

--------------------------------------------------------------------------------
-- Table: AFFILIATE_CONVERSIONS
-- Description: Tracked conversions from affiliate referrals
--------------------------------------------------------------------------------
CREATE TABLE affiliate_conversions (
    conversion_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    opportunity_id UUID NOT NULL REFERENCES affiliate_opportunities(opportunity_id),

    affiliate_id UUID NOT NULL,                           -- User promoting
    customer_id UUID NOT NULL,                            -- Converted user

    -- Conversion details
    conversion_type VARCHAR(50),                          -- signup, purchase, subscription
    conversion_value NUMERIC(10,2),                       -- Purchase amount
    commission_earned NUMERIC(10,2),
    commission_currency CHAR(3) DEFAULT 'USD',

    -- Attribution
    click_id VARCHAR(255),                                -- Unique click identifier
    attribution_source VARCHAR(50),                       -- link, promo_code, direct
    conversion_timestamp TIMESTAMP WITH TIME ZONE,

    -- Status
    is_validated BOOLEAN DEFAULT false,                   -- Fraud check passed
    is_paid BOOLEAN DEFAULT false,
    paid_at TIMESTAMP WITH TIME ZONE,

    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),

    INDEX idx_affiliate_conversions_affiliate (affiliate_id, conversion_timestamp),
    INDEX idx_affiliate_conversions_customer (customer_id),
    INDEX idx_affiliate_conversions_unpaid (is_paid, commission_earned) WHERE is_paid = false
);

-- Grant permissions
GRANT SELECT, INSERT, UPDATE ON collaboration_projects, project_contributions, mentorship_matches,
    mentorship_sessions, creator_subscriptions, content_tips, affiliate_opportunities, affiliate_conversions TO ap_application;
