                                -- ----------------------------------------------------------------------
                                -- Enum: rate_limit_granularity
                                -- Description: Defines the time window granularity for rate limiting rules.
                                -- Business Case: Allows flexible rate limiting per second, minute, hour, or day.
                                -- Feature Reference: RL01 (API Rate Limiting)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.rate_limit_granularity AS ENUM (
                                    'SECOND',
                                    'MINUTE',
                                    'HOUR',
                                    'DAY'
                                );
                                COMMENT ON TYPE public.rate_limit_granularity IS 'Time granularity for rate limit windows';

                                -- ----------------------------------------------------------------------
                                -- Enum: session_status
                                -- Description: Status of a user session.
                                -- Business Case: Enables session lifecycle management and security enforcement.
                                -- Feature Reference: SS01 (Session Management)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.session_status AS ENUM (
                                    'ACTIVE',
                                    'EXPIRED',
                                    'REVOKED',
                                    'TERMINATED'
                                );
                                COMMENT ON TYPE public.session_status IS 'Possible states of a user session';

                                -- ----------------------------------------------------------------------
                                -- Enum: payment_method_type
                                -- Description: Types of payment methods supported.
                                -- Business Case: Supports diverse payment instruments.
                                -- Feature Reference: PM01 (Payment Methods)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.payment_method_type AS ENUM (
                                    'CREDIT_CARD',
                                    'DEBIT_CARD',
                                    'BANK_ACCOUNT',
                                    'PAYPAL',
                                    'APPLE_PAY',
                                    'GOOGLE_PAY',
                                    'CRYPTO'
                                );
                                COMMENT ON TYPE public.payment_method_type IS 'Supported payment method types';

                                -- ----------------------------------------------------------------------
                                -- Enum: payment_method_status
                                -- Description: Status of a user's stored payment method.
                                -- Business Case: Tracks validity and usability of payment instruments.
                                -- Feature Reference: PM02 (Payment Method Lifecycle)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.payment_method_status AS ENUM (
                                    'ACTIVE',
                                    'EXPIRED',
                                    'INVALID',
                                    'REMOVED',
                                    'VERIFICATION_PENDING'
                                );
                                COMMENT ON TYPE public.payment_method_status IS 'Lifecycle status of a payment method';

                                -- ----------------------------------------------------------------------
                                -- Enum: tax_rate_type
                                -- Description: Types of taxes applicable.
                                -- Business Case: Differentiates VAT, GST, sales tax, etc., for correct calculation.
                                -- Feature Reference: TX01 (Tax Management)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.tax_rate_type AS ENUM (
                                    'VAT',
                                    'GST',
                                    'SALES_TAX',
                                    'USE_TAX',
                                    'EXCISE',
                                    'CUSTOMS'
                                );
                                COMMENT ON TYPE public.tax_rate_type IS 'Tax type classification';

                                -- ----------------------------------------------------------------------
                                -- Enum: tax_jurisdiction_level
                                -- Description: Geographic level of a tax jurisdiction.
                                -- Business Case: Enables hierarchical tax rate application (country → state → city).
                                -- Feature Reference: TX02 (Tax Jurisdiction)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.tax_jurisdiction_level AS ENUM (
                                    'COUNTRY',
                                    'STATE',
                                    'COUNTY',
                                    'CITY',
                                    'SPECIAL_DISTRICT'
                                );
                                COMMENT ON TYPE public.tax_jurisdiction_level IS 'Hierarchical level of tax jurisdiction';

                                -- ----------------------------------------------------------------------
                                -- Enum: dead_letter_status
                                -- Description: Status of a failed background job entry.
                                -- Business Case: Tracks retry attempts and final resolution.
                                -- Feature Reference: DLQ01 (Dead Letter Queue)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.dead_letter_status AS ENUM (
                                    'PENDING_RETRY',
                                    'RETRYING',
                                    'FAILED_PERMANENT',
                                    'ARCHIVED'
                                );
                                COMMENT ON TYPE public.dead_letter_status IS 'Status of a dead letter queue entry';

                                -- ----------------------------------------------------------------------
                                -- Enum: abuse_report_severity
                                -- Description: Severity level of an abuse report.
                                -- Business Case: Prioritizes moderation actions based on severity.
                                -- Feature Reference: AB01 (Abuse Reporting)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.abuse_report_severity AS ENUM (
                                    'LOW',
                                    'MEDIUM',
                                    'HIGH',
                                    'CRITICAL'
                                );
                                COMMENT ON TYPE public.abuse_report_severity IS 'Severity levels for abuse reports';

                                -- ----------------------------------------------------------------------
                                -- Enum: service_dependency_type
                                -- Description: Type of dependency between services.
                                -- Business Case: Defines criticality of dependencies for health checks.
                                -- Feature Reference: SD01 (Service Dependency Mapping)
                                -- ----------------------------------------------------------------------
                                CREATE TYPE public.service_dependency_type AS ENUM (
                                    'HARD',
                                    'SOFT',
                                    'OPTIONAL'
                                );
                                COMMENT ON TYPE public.service_dependency_type IS 'Nature of service dependency';

                                -- ======================================================================
                                -- TABLE: schema_migrations (Priority 1)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 1
                                -- Table Name: schema_migrations
                                -- Description: Tracks version history of database schema changes applied
                                --              via CI/CD or migration tools.
                                -- Business Case: In an enterprise environment, multiple developers and
                                --                automated deployment pipelines must apply database changes
                                --                consistently. Without a migration tracking table,
                                --                environments can drift, leading to deployment failures or
                                --                data corruption. This table stores each migration’s
                                --                identifier, checksum, and application timestamp, enabling
                                --                idempotent runs and rollback support. It is the cornerstone
                                --                of Database as Code practices, ensuring that all
                                --                environments (dev, test, staging, production) remain
                                --                synchronized. It also supports auditability by recording
                                --                who applied the migration and when.
                                -- KPIs:
                                --   1. Migration success rate (percentage of successful migrations)
                                --   2. Time to apply migrations (average duration)
                                --   3. Number of failed migrations per release
                                --   4. Environment drift count (mismatches between environments)
                                --   5. Rollback frequency (number of reverts)
                                -- Feature Reference: MIG01 (Database Migration Management)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.schema_migrations (
                                    migration_id      UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    version           VARCHAR(50) NOT NULL,
                                    name              VARCHAR(255) NOT NULL,
                                    checksum          TEXT NOT NULL,
                                    applied_by        UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
                                    applied_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    execution_time_ms INTEGER,                     -- duration of migration
                                    success           BOOLEAN NOT NULL,
                                    rollback_of       UUID REFERENCES public.schema_migrations(migration_id) ON DELETE SET NULL, -- if this is a rollback
                                    script_content    TEXT,                         -- for audit, store the actual DDL
                                    environment       VARCHAR(50) NOT NULL,         -- e.g., 'production', 'staging'
                                    CONSTRAINT uq_schema_migrations_version UNIQUE (version, environment)
                                );

                                COMMENT ON TABLE public.schema_migrations IS 'Tracks version history of database schema changes';
                                COMMENT ON COLUMN public.schema_migrations.migration_id IS 'Primary key';
                                COMMENT ON COLUMN public.schema_migrations.version IS 'Migration version number (e.g., 20250217001)';
                                COMMENT ON COLUMN public.schema_migrations.name IS 'Descriptive name of the migration';
                                COMMENT ON COLUMN public.schema_migrations.checksum IS 'Checksum of migration script to detect tampering';
                                COMMENT ON COLUMN public.schema_migrations.applied_by IS 'User who applied the migration';
                                COMMENT ON COLUMN public.schema_migrations.applied_at IS 'Timestamp when migration was applied';
                                COMMENT ON COLUMN public.schema_migrations.execution_time_ms IS 'Time taken to execute the migration in milliseconds';
                                COMMENT ON COLUMN public.schema_migrations.success IS 'Whether migration succeeded';
                                COMMENT ON COLUMN public.schema_migrations.rollback_of IS 'If this migration is a rollback, references original migration';
                                COMMENT ON COLUMN public.schema_migrations.script_content IS 'Full migration script (for audit)';
                                COMMENT ON COLUMN public.schema_migrations.environment IS 'Environment where migration was applied';

                                -- Indexes
                                CREATE INDEX idx_schema_migrations_version ON public.schema_migrations(version, environment);
                                CREATE INDEX idx_schema_migrations_applied_at ON public.schema_migrations(applied_at DESC);
                                CREATE INDEX idx_schema_migrations_applied_by ON public.schema_migrations(applied_by);

                                -- Trigger to automatically update execution_time_ms if needed? Not needed as it's set at insert.

                                -- No RLS needed as this is administrative data.

                                -- ======================================================================
                                -- TABLE: rate_limits (Priority 1)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 2
                                -- Table Name: rate_limits
                                -- Description: Defines rate limiting rules for API endpoints or actions,
                                --              including thresholds, time windows, and applicable user tiers.
                                -- Business Case: To protect the platform from abuse, denial-of-service
                                --                attacks, and unintentional overuse, rate limiting is
                                --                essential. This table stores configurable rules that can
                                --                be applied per endpoint, per user role, or per API key.
                                --                By centralizing rate limit definitions, the system can
                                --                dynamically adjust limits without code changes. The table
                                --                supports multiple granularities (per second, minute, hour)
                                --                and can enforce both request counts and concurrent request
                                --                limits. Integration with API gateways or middleware ensures
                                --                fair usage and maintains service quality for all users.
                                -- KPIs:
                                --   1. Number of rate limit violations per endpoint per day
                                --   2. Percentage of requests throttled
                                --   3. Average response time under vs. over limit
                                --   4. Time to detect abuse (anomaly detection latency)
                                --   5. Rule coverage (percentage of endpoints with rate limits)
                                -- Feature Reference: RL01 (Rate Limiting Rules)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.rate_limits (
                                    rate_limit_id     UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    name              VARCHAR(100) NOT NULL,
                                    description       TEXT,
                                    resource_pattern  VARCHAR(255) NOT NULL,       -- e.g., '/api/v1/jobs/*' or action name
                                    method            VARCHAR(10),                  -- HTTP method if applicable (GET, POST, etc.)
                                    user_tier         VARCHAR(50) DEFAULT 'ALL',    -- 'FREE', 'PREMIUM', 'ALL', or NULL for all
                                    api_key_pattern   VARCHAR(255),                  -- restrict to specific API key pattern
                                    limit_count       INTEGER NOT NULL CHECK (limit_count > 0),
                                    window_size       INTEGER NOT NULL CHECK (window_size > 0), -- numeric value
                                    window_granularity public.rate_limit_granularity NOT NULL,
                                    concurrent_limit  INTEGER,                       -- max concurrent requests (if applicable)
                                    is_active         BOOLEAN DEFAULT true NOT NULL,
                                    priority          INTEGER DEFAULT 100,           -- lower number evaluated first
                                    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    created_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    updated_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    CONSTRAINT uq_rate_limit_resource UNIQUE (resource_pattern, method, user_tier, api_key_pattern)
                                );

                                COMMENT ON TABLE public.rate_limits IS 'Rate limiting rules for API endpoints and actions';
                                COMMENT ON COLUMN public.rate_limits.rate_limit_id IS 'Primary key';
                                COMMENT ON COLUMN public.rate_limits.name IS 'Short name for the rule';
                                COMMENT ON COLUMN public.rate_limits.description IS 'Detailed description';
                                COMMENT ON COLUMN public.rate_limits.resource_pattern IS 'Pattern matching the resource (supports wildcards)';
                                COMMENT ON COLUMN public.rate_limits.method IS 'HTTP method or action type';
                                COMMENT ON COLUMN public.rate_limits.user_tier IS 'User tier to which rule applies (e.g., FREE, PREMIUM)';
                                COMMENT ON COLUMN public.rate_limits.api_key_pattern IS 'Pattern matching API keys (for key-specific limits)';
                                COMMENT ON COLUMN public.rate_limits.limit_count IS 'Maximum number of requests allowed';
                                COMMENT ON COLUMN public.rate_limits.window_size IS 'Size of the time window';
                                COMMENT ON COLUMN public.rate_limits.window_granularity IS 'Unit of window size (SECOND, MINUTE, HOUR, DAY)';
                                COMMENT ON COLUMN public.rate_limits.concurrent_limit IS 'Maximum concurrent requests (if applicable)';
                                COMMENT ON COLUMN public.rate_limits.is_active IS 'Whether rule is currently enforced';
                                COMMENT ON COLUMN public.rate_limits.priority IS 'Evaluation order (lower numbers first)';
                                COMMENT ON COLUMN public.rate_limits.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.rate_limits.updated_at IS 'Timestamp of last update';
                                COMMENT ON COLUMN public.rate_limits.created_by IS 'User who created the rule';
                                COMMENT ON COLUMN public.rate_limits.updated_by IS 'User who last updated the rule';

                                -- Indexes
                                CREATE INDEX idx_rate_limits_resource ON public.rate_limits(resource_pattern, method);
                                CREATE INDEX idx_rate_limits_user_tier ON public.rate_limits(user_tier);
                                CREATE INDEX idx_rate_limits_active ON public.rate_limits(is_active) WHERE is_active = true;

                                -- Trigger for updated_at
                                CREATE TRIGGER update_rate_limits_timestamp
                                    BEFORE UPDATE ON public.rate_limits
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- RLS not needed (configuration data), but could be enabled if multi-tenant.

                                -- ======================================================================
                                -- TABLE: sessions (Priority 1)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 3
                                -- Table Name: sessions
                                -- Description: Stores active user sessions with tokens, expiry, and metadata
                                --              for authentication and authorization.
                                -- Business Case: Modern applications require robust session management to
                                --                maintain user state securely across requests. This table
                                --                holds session tokens (JWT or opaque), refresh tokens,
                                --                device information, and expiry times. It enables features
                                --                like "logout everywhere", session revocation, and concurrent
                                --                session limits. By storing sessions, the system can
                                --                invalidate compromised tokens and enforce security policies
                                --                (e.g., MFA required after a certain time). This table is
                                --                critical for user experience and security compliance.
                                -- KPIs:
                                --   1. Active sessions per user (average, max)
                                --   2. Session duration (average, distribution)
                                --   3. Session revocation rate (due to logout, expiry, security)
                                --   4. Concurrent session limit violations
                                --   5. Refresh token success rate
                                -- Feature Reference: SS01 (Session Management)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.sessions (
                                    session_id        UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    user_id           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
                                    access_token      TEXT NOT NULL,                -- hashed or encrypted
                                    refresh_token     TEXT,                          -- hashed or encrypted
                                    token_type        VARCHAR(20) DEFAULT 'Bearer' NOT NULL,
                                    issued_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    expires_at        TIMESTAMP WITH TIME ZONE NOT NULL,
                                    refresh_expires_at TIMESTAMP WITH TIME ZONE,
                                    last_activity_at  TIMESTAMP WITH TIME ZONE,
                                    ip_address        INET,
                                    user_agent        TEXT,
                                    device_id         VARCHAR(255),                  -- for device tracking
                                    device_name       VARCHAR(255),
                                    location          GEOGRAPHY(POINT),               -- optional, if GDPR allows
                                    status            public.session_status DEFAULT 'ACTIVE' NOT NULL,
                                    revoked_at        TIMESTAMP WITH TIME ZONE,
                                    revoked_reason    TEXT,
                                    CONSTRAINT uq_access_token UNIQUE (access_token),   -- ensure no duplicates
                                    CONSTRAINT uq_refresh_token UNIQUE (refresh_token)
                                );

                                COMMENT ON TABLE public.sessions IS 'Active user sessions and tokens';
                                COMMENT ON COLUMN public.sessions.session_id IS 'Primary key';
                                COMMENT ON COLUMN public.sessions.user_id IS 'User owning the session';
                                COMMENT ON COLUMN public.sessions.access_token IS 'Hashed access token (opaque or JWT)';
                                COMMENT ON COLUMN public.sessions.refresh_token IS 'Hashed refresh token for obtaining new access tokens';
                                COMMENT ON COLUMN public.sessions.token_type IS 'Type of token (e.g., Bearer)';
                                COMMENT ON COLUMN public.sessions.issued_at IS 'Timestamp when session was created';
                                COMMENT ON COLUMN public.sessions.expires_at IS 'Expiration time of access token';
                                COMMENT ON COLUMN public.sessions.refresh_expires_at IS 'Expiration time of refresh token';
                                COMMENT ON COLUMN public.sessions.last_activity_at IS 'Last request time using this session';
                                COMMENT ON COLUMN public.sessions.ip_address IS 'IP address from which session originated';
                                COMMENT ON COLUMN public.sessions.user_agent IS 'User agent string of client';
                                COMMENT ON COLUMN public.sessions.device_id IS 'Unique device identifier (if available)';
                                COMMENT ON COLUMN public.sessions.device_name IS 'Human-readable device name';
                                COMMENT ON COLUMN public.sessions.location IS 'Geolocation point (if consented)';
                                COMMENT ON COLUMN public.sessions.status IS 'Current session status';
                                COMMENT ON COLUMN public.sessions.revoked_at IS 'When session was revoked (if any)';
                                COMMENT ON COLUMN public.sessions.revoked_reason IS 'Reason for revocation';

                                -- Indexes for fast lookups and cleanup
                                CREATE INDEX idx_sessions_user_id ON public.sessions(user_id, status);
                                CREATE INDEX idx_sessions_access_token ON public.sessions(access_token);
                                CREATE INDEX idx_sessions_refresh_token ON public.sessions(refresh_token);
                                CREATE INDEX idx_sessions_expires_at ON public.sessions(expires_at) WHERE status = 'ACTIVE';
                                CREATE INDEX idx_sessions_refresh_expires_at ON public.sessions(refresh_expires_at) WHERE status = 'ACTIVE';
                                CREATE INDEX idx_sessions_last_activity ON public.sessions(last_activity_at) WHERE status = 'ACTIVE';

                                -- No update trigger needed; we'll update last_activity manually

                                -- Enable RLS
                                ALTER TABLE public.sessions ENABLE ROW LEVEL SECURITY;

                                -- Policy: users can only see/update their own sessions (admins have separate policy)
                                CREATE POLICY sessions_user_policy ON public.sessions
                                    USING (user_id = current_user_id());

                                -- (Admin policy can be added separately via roles)

                                -- ======================================================================
                                -- TABLE: payment_methods (Priority 2)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 4
                                -- Table Name: payment_methods
                                -- Description: Stores tokenized payment methods (credit cards, bank accounts,
                                --              etc.) linked to users, with PCI‑compliant handling.
                                -- Business Case: To enable recurring billing and one‑click purchases,
                                --                the platform must securely store payment method references.
                                --                This table holds only tokenized representations (provided
                                --                by a payment gateway like Stripe or Braintree) and never
                                --                raw PANs. It tracks the method type, billing address,
                                --                expiration, and status. By centralizing payment methods,
                                --                users can manage their payment options, and the system can
                                --                automatically handle retries on failed payments. Compliance
                                --                with PCI DSS is achieved by offloading sensitive data to
                                --                the gateway and storing only tokens.
                                -- KPIs:
                                --   1. Number of active payment methods per user
                                --   2. Payment method failure rate (declined transactions)
                                --   3. Time from expiration to update (average)
                                --   4. Percentage of users with at least one valid payment method
                                --   5. Tokenization success rate
                                -- Feature Reference: PM01 (Payment Method Management)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.payment_methods (
                                    payment_method_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    user_id           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
                                    method_type       public.payment_method_type NOT NULL,
                                    provider          VARCHAR(50) NOT NULL,               -- e.g., 'stripe', 'braintree'
                                    provider_token    TEXT NOT NULL,                       -- token from gateway (encrypted at rest)
                                    last_four         VARCHAR(4),                          -- last 4 digits for display
                                    expiry_month      INTEGER CHECK (expiry_month BETWEEN 1 AND 12),
                                    expiry_year       INTEGER CHECK (expiry_year >= 2024),
                                    card_holder_name  VARCHAR(255),
                                    billing_address   TEXT,
                                    billing_city      VARCHAR(100),
                                    billing_state     VARCHAR(100),
                                    billing_postal_code VARCHAR(20),
                                    billing_country   CHAR(2),
                                    is_default        BOOLEAN DEFAULT false NOT NULL,
                                    status            public.payment_method_status DEFAULT 'ACTIVE' NOT NULL,
                                    last_used_at      TIMESTAMP WITH TIME ZONE,
                                    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    created_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    updated_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    CONSTRAINT uq_user_provider_token UNIQUE (user_id, provider, provider_token)
                                );

                                COMMENT ON TABLE public.payment_methods IS 'Tokenized payment methods linked to users';
                                COMMENT ON COLUMN public.payment_methods.payment_method_id IS 'Primary key';
                                COMMENT ON COLUMN public.payment_methods.user_id IS 'User owning the payment method';
                                COMMENT ON COLUMN public.payment_methods.method_type IS 'Type of payment instrument';
                                COMMENT ON COLUMN public.payment_methods.provider IS 'Payment gateway name';
                                COMMENT ON COLUMN public.payment_methods.provider_token IS 'Gateway token (encrypted)';
                                COMMENT ON COLUMN public.payment_methods.last_four IS 'Last 4 digits of card/account for display';
                                COMMENT ON COLUMN public.payment_methods.expiry_month IS 'Expiration month (if applicable)';
                                COMMENT ON COLUMN public.payment_methods.expiry_year IS 'Expiration year';
                                COMMENT ON COLUMN public.payment_methods.card_holder_name IS 'Name on card';
                                COMMENT ON COLUMN public.payment_methods.billing_address IS 'Billing address line';
                                COMMENT ON COLUMN public.payment_methods.billing_city IS 'Billing city';
                                COMMENT ON COLUMN public.payment_methods.billing_state IS 'Billing state/province';
                                COMMENT ON COLUMN public.payment_methods.billing_postal_code IS 'Billing postal code';
                                COMMENT ON COLUMN public.payment_methods.billing_country IS 'Billing country (ISO 3166-1 alpha-2)';
                                COMMENT ON COLUMN public.payment_methods.is_default IS 'Whether this is the default payment method';
                                COMMENT ON COLUMN public.payment_methods.status IS 'Current status of payment method';
                                COMMENT ON COLUMN public.payment_methods.last_used_at IS 'Last time this method was used successfully';
                                COMMENT ON COLUMN public.payment_methods.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.payment_methods.updated_at IS 'Timestamp of last update';
                                COMMENT ON COLUMN public.payment_methods.created_by IS 'User who added the method';
                                COMMENT ON COLUMN public.payment_methods.updated_by IS 'User who last updated the method';

                                -- Indexes
                                CREATE INDEX idx_payment_methods_user_id ON public.payment_methods(user_id, status);
                                CREATE INDEX idx_payment_methods_provider_token ON public.payment_methods(provider_token);
                                CREATE INDEX idx_payment_methods_expiry ON public.payment_methods(expiry_year, expiry_month) WHERE status = 'ACTIVE';

                                -- Trigger for updated_at
                                CREATE TRIGGER update_payment_methods_timestamp
                                    BEFORE UPDATE ON public.payment_methods
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- Enable RLS
                                ALTER TABLE public.payment_methods ENABLE ROW LEVEL SECURITY;

                                -- Policy: users can CRUD their own payment methods
                                CREATE POLICY payment_methods_user_policy ON public.payment_methods
                                    USING (user_id = current_user_id());

                                -- ======================================================================
                                -- TABLE: tax_rates (Priority 2)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 5
                                -- Table Name: tax_rates
                                -- Description: Defines tax rates applicable to products/services based on
                                --              geographic jurisdiction, product type, and customer type.
                                -- Business Case: In a global platform, tax compliance requires accurate
                                --                calculation of VAT, GST, sales tax, etc., based on the
                                --                buyer’s location and the nature of the product. This table
                                --                stores tax rates by jurisdiction (country, state, city),
                                --                effective dates, and tax type. It supports complex rules
                                --                like reduced rates for certain goods or exemptions for
                                --                business customers. By maintaining this data, invoicing
                                --                and payment systems can automatically apply correct taxes,
                                --                reducing manual errors and audit risks.
                                -- KPIs:
                                --   1. Tax rate update frequency (number of changes per month)
                                --   2. Number of jurisdictions covered
                                --   3. Tax calculation accuracy (percentage of invoices with correct tax)
                                --   4. Time to update tax rates after legislative changes
                                --   5. Number of tax exemption certificates stored
                                -- Feature Reference: TX01 (Tax Rate Management)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.tax_rates (
                                    tax_rate_id       UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    tax_type          public.tax_rate_type NOT NULL,
                                    jurisdiction_level public.tax_jurisdiction_level NOT NULL,
                                    country_code      CHAR(2) NOT NULL,                -- ISO 3166-1 alpha-2
                                    state_code        VARCHAR(10),                      -- e.g., 'CA', 'NSW'
                                    county            VARCHAR(100),
                                    city              VARCHAR(100),
                                    district          VARCHAR(100),
                                    postal_code       VARCHAR(20),                       -- can be specific or range
                                    product_category  VARCHAR(100),                      -- product/service category, NULL for all
                                    customer_type     VARCHAR(50) DEFAULT 'ALL',        -- 'INDIVIDUAL', 'BUSINESS', 'ALL'
                                    rate_percentage   NUMERIC(7,4) NOT NULL CHECK (rate_percentage >= 0 AND rate_percentage <= 100),
                                    effective_from    DATE NOT NULL,
                                    effective_to      DATE,                               -- NULL means indefinitely
                                    is_compound       BOOLEAN DEFAULT false,             -- whether tax is applied on top of other taxes
                                    exemption_threshold NUMERIC(12,2),                    -- if applicable
                                    description       TEXT,
                                    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    created_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    updated_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    CONSTRAINT uq_tax_rate UNIQUE (tax_type, jurisdiction_level, country_code, state_code, county, city, district, postal_code, product_category, customer_type, effective_from)
                                );

                                COMMENT ON TABLE public.tax_rates IS 'Tax rates by jurisdiction, product, and customer type';
                                COMMENT ON COLUMN public.tax_rates.tax_rate_id IS 'Primary key';
                                COMMENT ON COLUMN public.tax_rates.tax_type IS 'Type of tax (VAT, GST, etc.)';
                                COMMENT ON COLUMN public.tax_rates.jurisdiction_level IS 'Geographic level of jurisdiction';
                                COMMENT ON COLUMN public.tax_rates.country_code IS 'ISO 3166-1 alpha-2 country code';
                                COMMENT ON COLUMN public.tax_rates.state_code IS 'State/province code (if applicable)';
                                COMMENT ON COLUMN public.tax_rates.county IS 'County name';
                                COMMENT ON COLUMN public.tax_rates.city IS 'City name';
                                COMMENT ON COLUMN public.tax_rates.district IS 'Special tax district';
                                COMMENT ON COLUMN public.tax_rates.postal_code IS 'Postal code or range';
                                COMMENT ON COLUMN public.tax_rates.product_category IS 'Product/service category to which rate applies';
                                COMMENT ON COLUMN public.tax_rates.customer_type IS 'Customer segment to which rate applies';
                                COMMENT ON COLUMN public.tax_rates.rate_percentage IS 'Tax rate as percentage';
                                COMMENT ON COLUMN public.tax_rates.effective_from IS 'Start date of rate validity';
                                COMMENT ON COLUMN public.tax_rates.effective_to IS 'End date of rate validity (NULL = ongoing)';
                                COMMENT ON COLUMN public.tax_rates.is_compound IS 'Whether this tax is applied on top of other taxes';
                                COMMENT ON COLUMN public.tax_rates.exemption_threshold IS 'Revenue threshold for exemption';
                                COMMENT ON COLUMN public.tax_rates.description IS 'Notes about the tax rate';
                                COMMENT ON COLUMN public.tax_rates.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.tax_rates.updated_at IS 'Timestamp of last update';
                                COMMENT ON COLUMN public.tax_rates.created_by IS 'User who created the record';
                                COMMENT ON COLUMN public.tax_rates.updated_by IS 'User who last updated the record';

                                -- Indexes for fast lookup
                                CREATE INDEX idx_tax_rates_jurisdiction ON public.tax_rates(country_code, state_code, city, postal_code);
                                CREATE INDEX idx_tax_rates_effective ON public.tax_rates(effective_from, effective_to) WHERE effective_to IS NOT NULL;
                                CREATE INDEX idx_tax_rates_product_customer ON public.tax_rates(product_category, customer_type);

                                -- Trigger for updated_at
                                CREATE TRIGGER update_tax_rates_timestamp
                                    BEFORE UPDATE ON public.tax_rates
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- RLS not needed (configuration data)

                                -- ======================================================================
                                -- TABLE: search_sync_queue (Priority 2)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 6
                                -- Table Name: search_sync_queue
                                -- Description: Queue of entities that need to be synchronized with an
                                --              external search engine (e.g., Elasticsearch, OpenSearch).
                                -- Business Case: Full‑text search on a large dataset is best handled by
                                --                dedicated search engines. Changes to indexed entities
                                --                (users, jobs, companies, content) must be propagated
                                --                asynchronously to keep search results fresh. This table
                                --                acts as a reliable queue, recording each change event
                                --                and its processing status. It supports retries, dead‑letter
                                --                handling, and batch processing. By decoupling index updates
                                --                from transactional writes, the main database avoids
                                --                performance degradation, and search indexing can be scaled
                                --                independently.
                                -- KPIs:
                                --   1. Queue depth (number of pending sync items)
                                --   2. Processing latency (time from enqueue to successful sync)
                                --   3. Failure rate (percentage of items that fail permanently)
                                --   4. Throughput (items processed per minute)
                                --   5. Age of oldest pending item
                                -- Feature Reference: SS01 (Search Synchronization)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.search_sync_queue (
                                    sync_id           UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    entity_type       VARCHAR(50) NOT NULL,           -- e.g., 'user', 'job', 'company'
                                    entity_id         UUID NOT NULL,
                                    operation         VARCHAR(10) NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')),
                                    changed_at        TIMESTAMP WITH TIME ZONE NOT NULL,  -- time of original change
                                    priority          INTEGER DEFAULT 100,                 -- lower = higher priority
                                    status            VARCHAR(20) DEFAULT 'PENDING' NOT NULL CHECK (status IN ('PENDING', 'PROCESSING', 'SUCCEEDED', 'FAILED', 'SKIPPED')),
                                    retry_count       INTEGER DEFAULT 0 NOT NULL,
                                    last_error        TEXT,
                                    locked_until      TIMESTAMP WITH TIME ZONE,            -- for distributed workers
                                    locked_by         VARCHAR(100),                         -- worker identifier
                                    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
                                );

                                COMMENT ON TABLE public.search_sync_queue IS 'Queue for synchronizing data changes with external search engine';
                                COMMENT ON COLUMN public.search_sync_queue.sync_id IS 'Primary key';
                                COMMENT ON COLUMN public.search_sync_queue.entity_type IS 'Type of entity that changed';
                                COMMENT ON COLUMN public.search_sync_queue.entity_id IS 'UUID of the entity';
                                COMMENT ON COLUMN public.search_sync_queue.operation IS 'Type of change operation';
                                COMMENT ON COLUMN public.search_sync_queue.changed_at IS 'Timestamp of original change';
                                COMMENT ON COLUMN public.search_sync_queue.priority IS 'Priority for processing (lower first)';
                                COMMENT ON COLUMN public.search_sync_queue.status IS 'Current processing status';
                                COMMENT ON COLUMN public.search_sync_queue.retry_count IS 'Number of retry attempts';
                                COMMENT ON COLUMN public.search_sync_queue.last_error IS 'Last error message';
                                COMMENT ON COLUMN public.search_sync_queue.locked_until IS 'Time until which item is locked by a worker';
                                COMMENT ON COLUMN public.search_sync_queue.locked_by IS 'Identifier of worker that locked the item';
                                COMMENT ON COLUMN public.search_sync_queue.created_at IS 'Timestamp when queue item was created';
                                COMMENT ON COLUMN public.search_sync_queue.updated_at IS 'Timestamp of last update';

                                -- Indexes for efficient dequeuing
                                CREATE INDEX idx_search_sync_queue_status_priority ON public.search_sync_queue(status, priority, created_at) WHERE status = 'PENDING';
                                CREATE INDEX idx_search_sync_queue_locked ON public.search_sync_queue(locked_until) WHERE locked_until IS NOT NULL;
                                CREATE INDEX idx_search_sync_queue_entity ON public.search_sync_queue(entity_type, entity_id);

                                -- Trigger for updated_at
                                CREATE TRIGGER update_search_sync_queue_timestamp
                                    BEFORE UPDATE ON public.search_sync_queue
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- RLS not needed (internal queue)

                                -- ======================================================================
                                -- TABLE: referral_codes (Priority 3)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 7
                                -- Table Name: referral_codes
                                -- Description: Tracks user referral codes, their usage, and rewards.
                                -- Business Case: To drive user growth through word‑of‑mouth, the platform
                                --                needs a robust referral program. This table stores unique
                                --                referral codes generated by users, along with associated
                                --                rewards (e.g., discounts, credits). It records when a code
                                --                is used by a new user, linking the referrer and referee.
                                --                This enables accurate attribution of new sign‑ups and
                                --                automated reward fulfillment. By analyzing referral
                                --                performance, the business can optimize incentives and
                                --                identify top advocates. The table also supports campaign
                                --                tracking (e.g., seasonal promotions).
                                -- KPIs:
                                --   1. Referral conversion rate (percentage of codes used)
                                --   2. Average number of referrals per user
                                --   3. Time from code generation to first use
                                --   4. Revenue attributed to referrals
                                --   5. Referrer lifetime value (LTV) vs. non‑referrers
                                -- Feature Reference: RC01 (Referral Program)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.referral_codes (
                                    referral_code_id  UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    user_id           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
                                    code              VARCHAR(50) NOT NULL UNIQUE,
                                    campaign          VARCHAR(100),                      -- e.g., 'SUMMER2025'
                                    reward_type       VARCHAR(50) NOT NULL CHECK (reward_type IN ('DISCOUNT', 'CREDIT', 'PREMIUM_EXTENSION')),
                                    reward_value      NUMERIC(10,2) NOT NULL,
                                    currency          CHAR(3) DEFAULT 'USD',
                                    max_uses          INTEGER DEFAULT 1,
                                    current_uses      INTEGER DEFAULT 0 NOT NULL,
                                    expires_at        TIMESTAMP WITH TIME ZONE,
                                    is_active         BOOLEAN DEFAULT true NOT NULL,
                                    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    created_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    updated_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL
                                );

                                COMMENT ON TABLE public.referral_codes IS 'User referral codes and their usage';
                                COMMENT ON COLUMN public.referral_codes.referral_code_id IS 'Primary key';
                                COMMENT ON COLUMN public.referral_codes.user_id IS 'User who generated the code';
                                COMMENT ON COLUMN public.referral_codes.code IS 'Unique referral code string';
                                COMMENT ON COLUMN public.referral_codes.campaign IS 'Optional campaign identifier';
                                COMMENT ON COLUMN public.referral_codes.reward_type IS 'Type of reward given to referrer';
                                COMMENT ON COLUMN public.referral_codes.reward_value IS 'Amount of reward (discount percent or credit amount)';
                                COMMENT ON COLUMN public.referral_codes.currency IS 'Currency for credit rewards';
                                COMMENT ON COLUMN public.referral_codes.max_uses IS 'Maximum number of times code can be used';
                                COMMENT ON COLUMN public.referral_codes.current_uses IS 'Current usage count';
                                COMMENT ON COLUMN public.referral_codes.expires_at IS 'Expiration timestamp';
                                COMMENT ON COLUMN public.referral_codes.is_active IS 'Whether code can still be used';
                                COMMENT ON COLUMN public.referral_codes.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.referral_codes.updated_at IS 'Timestamp of last update';
                                COMMENT ON COLUMN public.referral_codes.created_by IS 'User who created the code (usually same as user_id)';
                                COMMENT ON COLUMN public.referral_codes.updated_by IS 'User who last updated the code';

                                -- Indexes
                                CREATE INDEX idx_referral_codes_user_id ON public.referral_codes(user_id);
                                CREATE INDEX idx_referral_codes_code ON public.referral_codes(code) WHERE is_active = true;
                                CREATE INDEX idx_referral_codes_campaign ON public.referral_codes(campaign);

                                -- Trigger for updated_at
                                CREATE TRIGGER update_referral_codes_timestamp
                                    BEFORE UPDATE ON public.referral_codes
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- Enable RLS
                                ALTER TABLE public.referral_codes ENABLE ROW LEVEL SECURITY;

                                -- Policy: users can view their own codes; admins can view all
                                CREATE POLICY referral_codes_user_policy ON public.referral_codes
                                    USING (user_id = current_user_id());

                                -- ======================================================================
                                -- TABLE: dead_letter_queue (Priority 3)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 8
                                -- Table Name: dead_letter_queue
                                -- Description: Stores failed background job messages that could not be
                                --              processed after retries, for later inspection and replay.
                                -- Business Case: In a distributed system, background jobs (e.g., sending
                                --                emails, processing payments, syncing search) may fail due
                                --                to transient errors or bugs. Rather than losing these
                                --                messages, they are moved to a dead‑letter queue (DLQ) for
                                --                manual or automated intervention. This table stores the
                                --                original payload, error details, and metadata. It enables
                                --                operators to diagnose failures, replay messages after fixes,
                                --                and ensure no data loss. It also feeds into monitoring
                                --                systems to alert on high failure rates.
                                -- KPIs:
                                --   1. DLQ size (number of unresolved messages)
                                --   2. Age of oldest message in DLQ
                                --   3. Replay success rate
                                --   4. Top failing job types
                                --   5. Mean time to resolution (MTTR) for DLQ messages
                                -- Feature Reference: DLQ01 (Dead Letter Queue)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.dead_letter_queue (
                                    dlq_id            UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    queue_name        VARCHAR(100) NOT NULL,           -- e.g., 'email', 'payment', 'search_sync'
                                    job_type          VARCHAR(100) NOT NULL,
                                    payload           JSONB NOT NULL,
                                    error_message     TEXT NOT NULL,
                                    error_stack       TEXT,
                                    retry_count       INTEGER NOT NULL,
                                    first_failure_at  TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    last_failure_at   TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    status            public.dead_letter_status DEFAULT 'PENDING_RETRY' NOT NULL,
                                    locked_until      TIMESTAMP WITH TIME ZONE,
                                    locked_by         VARCHAR(100),
                                    resolved_at       TIMESTAMP WITH TIME ZONE,
                                    resolved_by       UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    resolution_notes  TEXT,
                                    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
                                );

                                COMMENT ON TABLE public.dead_letter_queue IS 'Failed background job messages awaiting handling';
                                COMMENT ON COLUMN public.dead_letter_queue.dlq_id IS 'Primary key';
                                COMMENT ON COLUMN public.dead_letter_queue.queue_name IS 'Name of the source queue';
                                COMMENT ON COLUMN public.dead_letter_queue.job_type IS 'Type of job that failed';
                                COMMENT ON COLUMN public.dead_letter_queue.payload IS 'Original job payload (JSON)';
                                COMMENT ON COLUMN public.dead_letter_queue.error_message IS 'Error message from last failure';
                                COMMENT ON COLUMN public.dead_letter_queue.error_stack IS 'Stack trace (if available)';
                                COMMENT ON COLUMN public.dead_letter_queue.retry_count IS 'Number of retry attempts made';
                                COMMENT ON COLUMN public.dead_letter_queue.first_failure_at IS 'Timestamp of first failure';
                                COMMENT ON COLUMN public.dead_letter_queue.last_failure_at IS 'Timestamp of most recent failure';
                                COMMENT ON COLUMN public.dead_letter_queue.status IS 'Current status in DLQ';
                                COMMENT ON COLUMN public.dead_letter_queue.locked_until IS 'Lock expiration for processing';
                                COMMENT ON COLUMN public.dead_letter_queue.locked_by IS 'Worker identifier';
                                COMMENT ON COLUMN public.dead_letter_queue.resolved_at IS 'When the issue was resolved';
                                COMMENT ON COLUMN public.dead_letter_queue.resolved_by IS 'User who resolved';
                                COMMENT ON COLUMN public.dead_letter_queue.resolution_notes IS 'Notes on resolution';
                                COMMENT ON COLUMN public.dead_letter_queue.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.dead_letter_queue.updated_at IS 'Timestamp of last update';

                                -- Indexes
                                CREATE INDEX idx_dead_letter_queue_status ON public.dead_letter_queue(status, last_failure_at);
                                CREATE INDEX idx_dead_letter_queue_locked ON public.dead_letter_queue(locked_until) WHERE locked_until IS NOT NULL;
                                CREATE INDEX idx_dead_letter_queue_queue ON public.dead_letter_queue(queue_name);

                                -- Trigger for updated_at
                                CREATE TRIGGER update_dead_letter_queue_timestamp
                                    BEFORE UPDATE ON public.dead_letter_queue
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- RLS not needed (internal)

                                -- ======================================================================
                                -- TABLE: feature_flag_evaluations (Priority 3)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 9
                                -- Table Name: feature_flag_evaluations
                                -- Description: Logs each evaluation of a feature flag for a user/session,
                                --              storing the flag name, evaluated value, and context.
                                -- Business Case: Feature flags allow gradual rollouts and A/B testing.
                                --                To analyze the impact of a flag, it’s essential to know
                                --                which users saw which variant and when. This table records
                                --                every evaluation, capturing the user, session, flag,
                                --                evaluated value, and metadata (e.g., experiment cohort).
                                --                The data feeds into analytics dashboards to measure
                                --                feature adoption, conversion rates, and detect anomalies.
                                --                It also supports debugging by showing who got what variant.
                                -- KPIs:
                                --   1. Flag evaluation count per day
                                --   2. Variant distribution for each flag
                                --   3. User exposure percentage (coverage)
                                --   4. Time from flag creation to first evaluation
                                --   5. Correlation between flag variant and user actions
                                -- Feature Reference: FF01 (Feature Flag Telemetry)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.feature_flag_evaluations (
                                    evaluation_id     UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    flag_name         VARCHAR(100) NOT NULL,
                                    user_id           UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    session_id        UUID REFERENCES public.sessions(session_id) ON DELETE SET NULL,
                                    evaluated_value   BOOLEAN NOT NULL,
                                    variant           VARCHAR(50),                     -- if A/B test, which variant
                                    reason            TEXT,                              -- why that value was returned (e.g., rule matched)
                                    context           JSONB,                             -- additional context (e.g., country, device)
                                    evaluated_at      TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    ip_address        INET
                                );

                                COMMENT ON TABLE public.feature_flag_evaluations IS 'Logs of feature flag evaluations for analysis';
                                COMMENT ON COLUMN public.feature_flag_evaluations.evaluation_id IS 'Primary key';
                                COMMENT ON COLUMN public.feature_flag_evaluations.flag_name IS 'Name of the feature flag';
                                COMMENT ON COLUMN public.feature_flag_evaluations.user_id IS 'User for whom flag was evaluated (if authenticated)';
                                COMMENT ON COLUMN public.feature_flag_evaluations.session_id IS 'Session during evaluation';
                                COMMENT ON COLUMN public.feature_flag_evaluations.evaluated_value IS 'Boolean result of evaluation';
                                COMMENT ON COLUMN public.feature_flag_evaluations.variant IS 'Variant identifier for A/B tests';
                                COMMENT ON COLUMN public.feature_flag_evaluations.reason IS 'Explanation of why value was chosen';
                                COMMENT ON COLUMN public.feature_flag_evaluations.context IS 'Contextual data used in evaluation';
                                COMMENT ON COLUMN public.feature_flag_evaluations.evaluated_at IS 'Timestamp of evaluation';
                                COMMENT ON COLUMN public.feature_flag_evaluations.ip_address IS 'IP address of client';

                                -- Indexes for analytics queries
                                CREATE INDEX idx_feature_flag_evaluations_flag_time ON public.feature_flag_evaluations(flag_name, evaluated_at);
                                CREATE INDEX idx_feature_flag_evaluations_user_id ON public.feature_flag_evaluations(user_id, evaluated_at);
                                CREATE INDEX idx_feature_flag_evaluations_session_id ON public.feature_flag_evaluations(session_id);

                                -- No update trigger (immutable log)

                                -- Enable RLS
                                ALTER TABLE public.feature_flag_evaluations ENABLE ROW LEVEL SECURITY;

                                -- Policy: users can see only their own evaluations; admins can see all
                                CREATE POLICY feature_flag_evaluations_user_policy ON public.feature_flag_evaluations
                                    USING (user_id = current_user_id());

                                -- ======================================================================
                                -- TABLE: data_retention_queue (Priority 3)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 10
                                -- Table Name: data_retention_queue
                                -- Description: Queue of records that need to be anonymized or deleted
                                --              according to data retention policies, with execution status.
                                -- Business Case: GDPR and other privacy regulations require timely deletion
                                --                or anonymization of personal data after a defined retention
                                --                period. Manually tracking and executing these operations
                                --                is error‑prone and non‑scalable. This table automates the
                                --                process: retention policies define when data expires, and
                                --                a scheduled job inserts entries into this queue for each
                                --                record that needs action. Workers then process the queue,
                                --                applying the configured anonymization strategy (deletion,
                                --                pseudonymization, aggregation). The queue also logs results
                                --                for audit purposes.
                                -- KPIs:
                                --   1. Queue backlog (records pending processing)
                                --   2. Processing time (average per record)
                                --   3. Compliance rate (percentage of expired records processed on time)
                                --   4. Error rate during processing
                                --   5. Number of records anonymized per day
                                -- Feature Reference: DR01 (Data Retention Automation)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.data_retention_queue (
                                    retention_queue_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    table_name         VARCHAR(100) NOT NULL,
                                    record_id          UUID NOT NULL,
                                    policy_id          INTEGER NOT NULL REFERENCES public.data_retention_policies(policy_id) ON DELETE RESTRICT,
                                    action_required    VARCHAR(20) NOT NULL CHECK (action_required IN ('ANONYMIZE', 'DELETE', 'ARCHIVE')),
                                    scheduled_date     DATE NOT NULL,
                                    status             VARCHAR(20) DEFAULT 'PENDING' NOT NULL CHECK (status IN ('PENDING', 'PROCESSING', 'COMPLETED', 'FAILED', 'SKIPPED')),
                                    retry_count        INTEGER DEFAULT 0,
                                    last_error         TEXT,
                                    processed_at       TIMESTAMP WITH TIME ZONE,
                                    processed_by       UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    created_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
                                );

                                COMMENT ON TABLE public.data_retention_queue IS 'Queue for executing data retention actions';
                                COMMENT ON COLUMN public.data_retention_queue.retention_queue_id IS 'Primary key';
                                COMMENT ON COLUMN public.data_retention_queue.table_name IS 'Name of the table containing the record';
                                COMMENT ON COLUMN public.data_retention_queue.record_id IS 'Primary key of the record';
                                COMMENT ON COLUMN public.data_retention_queue.policy_id IS 'Reference to the retention policy that triggered this';
                                COMMENT ON COLUMN public.data_retention_queue.action_required IS 'Type of action to perform';
                                COMMENT ON COLUMN public.data_retention_queue.scheduled_date IS 'Date when action should be performed';
                                COMMENT ON COLUMN public.data_retention_queue.status IS 'Current processing status';
                                COMMENT ON COLUMN public.data_retention_queue.retry_count IS 'Number of retry attempts';
                                COMMENT ON COLUMN public.data_retention_queue.last_error IS 'Last error message';
                                COMMENT ON COLUMN public.data_retention_queue.processed_at IS 'When action was completed';
                                COMMENT ON COLUMN public.data_retention_queue.processed_by IS 'User who processed (if manual)';
                                COMMENT ON COLUMN public.data_retention_queue.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.data_retention_queue.updated_at IS 'Timestamp of last update';

                                -- Indexes
                                CREATE INDEX idx_data_retention_queue_status ON public.data_retention_queue(status, scheduled_date);
                                CREATE INDEX idx_data_retention_queue_table_record ON public.data_retention_queue(table_name, record_id);

                                -- Trigger for updated_at
                                CREATE TRIGGER update_data_retention_queue_timestamp
                                    BEFORE UPDATE ON public.data_retention_queue
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- RLS not needed (internal)

                                -- ======================================================================
                                -- TABLE: abuse_reports_aggregate (Priority 4)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 11
                                -- Table Name: abuse_reports_aggregate
                                -- Description: Pre‑aggregated statistics on abuse reports per user/content,
                                --              used for automated spam detection and moderator prioritization.
                                -- Business Case: Real‑time detection of abusive behavior requires fast
                                --                access to aggregated report counts. Instead of counting
                                --                reports on the fly (which can be expensive), this table
                                --                maintains rolling counts per reporter, per target, per
                                --                reason, and over various time windows. It is updated via
                                --                triggers when new reports are filed. Moderators can quickly
                                --                see users with high report counts, and automated systems
                                --                can temporarily restrict accounts that exceed thresholds.
                                -- KPIs:
                                --   1. Number of users with report count above threshold
                                --   2. Average time to moderation after report count spike
                                --   3. False positive rate (reports that were dismissed)
                                --   4. Top reported content types
                                --   5. Recidivism rate among previously moderated users
                                -- Feature Reference: AB02 (Abuse Detection Aggregates)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.abuse_reports_aggregate (
                                    aggregate_id      UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    target_user_id    UUID REFERENCES public.users(user_id) ON DELETE CASCADE,
                                    target_content_id UUID,                              -- if content-specific, else NULL
                                    content_type      VARCHAR(50),                        -- e.g., 'comment', 'message', 'profile'
                                    report_reason     TEXT,                               -- simplified reason category
                                    report_count_last_1h   INTEGER DEFAULT 0 NOT NULL,
                                    report_count_last_24h  INTEGER DEFAULT 0 NOT NULL,
                                    report_count_last_7d   INTEGER DEFAULT 0 NOT NULL,
                                    report_count_total     INTEGER DEFAULT 0 NOT NULL,
                                    distinct_reporter_count INTEGER DEFAULT 0 NOT NULL,
                                    last_report_at     TIMESTAMP WITH TIME ZONE,
                                    created_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    CONSTRAINT uq_abuse_aggregate_target UNIQUE (target_user_id, target_content_id, content_type, report_reason)
                                );

                                COMMENT ON TABLE public.abuse_reports_aggregate IS 'Pre‑aggregated counts of abuse reports for rapid detection';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.aggregate_id IS 'Primary key';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.target_user_id IS 'User being reported (if applicable)';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.target_content_id IS 'Specific content item being reported';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.content_type IS 'Type of content (if applicable)';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.report_reason IS 'Category of report reason';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.report_count_last_1h IS 'Number of reports in last hour';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.report_count_last_24h IS 'Number of reports in last 24 hours';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.report_count_last_7d IS 'Number of reports in last 7 days';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.report_count_total IS 'Total reports ever';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.distinct_reporter_count IS 'Number of distinct users who reported';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.last_report_at IS 'Timestamp of most recent report';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.abuse_reports_aggregate.updated_at IS 'Timestamp of last update';

                                -- Indexes for fast queries
                                CREATE INDEX idx_abuse_aggregate_user ON public.abuse_reports_aggregate(target_user_id);
                                CREATE INDEX idx_abuse_aggregate_content ON public.abuse_reports_aggregate(target_content_id) WHERE target_content_id IS NOT NULL;
                                CREATE INDEX idx_abuse_aggregate_last_report ON public.abuse_reports_aggregate(last_report_at DESC);

                                -- Trigger for updated_at
                                CREATE TRIGGER update_abuse_reports_aggregate_timestamp
                                    BEFORE UPDATE ON public.abuse_reports_aggregate
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

                                -- Enable RLS (moderators/admins only)
                                ALTER TABLE public.abuse_reports_aggregate ENABLE ROW LEVEL SECURITY;

                                -- Policy: only moderators and admins can view (assume role 'moderator' or 'admin')
                                CREATE POLICY abuse_reports_aggregate_moderator_policy ON public.abuse_reports_aggregate
                                    USING (EXISTS (
                                        SELECT 1 FROM public.user_roles ur
                                        JOIN public.roles r ON ur.role_id = r.role_id
                                        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'moderator')
                                    ));

                                -- ======================================================================
                                -- TABLE: service_dependencies (Priority 4)
                                -- ======================================================================
                                -- ----------------------------------------------------------------------
                                -- Serial No: 12
                                -- Table Name: service_dependencies
                                -- Description: Maps dependencies between microservices or internal components,
                                --              used for health checks and circuit breaking.
                                -- Business Case: In a microservices architecture, understanding which
                                --                services depend on which others is critical for incident
                                --                response and capacity planning. This table stores dependency
                                --                relationships, including the type (hard, soft) and optional
                                --                version constraints. It can be used by orchestration tools
                                --                to determine restart order, by monitoring to prioritize
                                --                alerts, and by developers to assess impact of changes.
                                --                When a service fails, the system can quickly identify
                                --                all downstream dependencies and potentially trigger circuit
                                --                breakers.
                                -- KPIs:
                                --   1. Number of hard dependencies per service
                                --   2. Dependency coverage (percentage of services with documented deps)
                                --   3. Time to identify impacted services during outage
                                --   4. Number of circular dependencies detected
                                --   5. Dependency freshness (last verified timestamp)
                                -- Feature Reference: SD01 (Service Dependency Mapping)
                                -- ----------------------------------------------------------------------
                                CREATE TABLE public.service_dependencies (
                                    dependency_id     UUID DEFAULT gen_random_uuid() PRIMARY KEY,
                                    service_name      VARCHAR(100) NOT NULL,
                                    depends_on        VARCHAR(100) NOT NULL,
                                    dependency_type   public.service_dependency_type NOT NULL,
                                    version_constraint VARCHAR(50),                      -- e.g., '>=2.0.0'
                                    description       TEXT,
                                    is_active         BOOLEAN DEFAULT true NOT NULL,
                                    last_verified_at  TIMESTAMP WITH TIME ZONE,
                                    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
                                    created_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    updated_by        UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
                                    CONSTRAINT uq_service_dependency UNIQUE (service_name, depends_on)
                                );

                                COMMENT ON TABLE public.service_dependencies IS 'Dependencies between microservices or components';
                                COMMENT ON COLUMN public.service_dependencies.dependency_id IS 'Primary key';
                                COMMENT ON COLUMN public.service_dependencies.service_name IS 'Name of the dependent service';
                                COMMENT ON COLUMN public.service_dependencies.depends_on IS 'Name of the service being depended upon';
                                COMMENT ON COLUMN public.service_dependencies.dependency_type IS 'Hard, soft, or optional dependency';
                                COMMENT ON COLUMN public.service_dependencies.version_constraint IS 'Version constraint for dependency';
                                COMMENT ON COLUMN public.service_dependencies.description IS 'Additional details';
                                COMMENT ON COLUMN public.service_dependencies.is_active IS 'Whether this dependency is currently valid';
                                COMMENT ON COLUMN public.service_dependencies.last_verified_at IS 'When this dependency was last verified';
                                COMMENT ON COLUMN public.service_dependencies.created_at IS 'Timestamp of creation';
                                COMMENT ON COLUMN public.service_dependencies.updated_at IS 'Timestamp of last update';
                                COMMENT ON COLUMN public.service_dependencies.created_by IS 'User who created the record';
                                COMMENT ON COLUMN public.service_dependencies.updated_by IS 'User who last updated the record';

                                -- Indexes
                                CREATE INDEX idx_service_dependencies_service ON public.service_dependencies(service_name);
                                CREATE INDEX idx_service_dependencies_depends ON public.service_dependencies(depends_on);

                                -- Trigger for updated_at
                                CREATE TRIGGER update_service_dependencies_timestamp
                                    BEFORE UPDATE ON public.service_dependencies
                                    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();





-- =============================================================================
-- ENUMS FOR CORE INFRASTRUCTURE & SECURITY
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Enum: migration_status
-- Description: Defines the possible states of a database migration execution
-- Business Case: Tracks the success/failure of migrations for rollback decisions
-- Feature Reference: MIG-01 (Migration Management)
-- -----------------------------------------------------------------------------
CREATE TYPE public.migration_status AS ENUM (
    'PENDING',      -- Migration script exists but not yet applied
    'SUCCESS',      -- Migration applied successfully
    'FAILED',       -- Migration failed during execution
    'ROLLED_BACK',  -- Migration was rolled back
    'SKIPPED',      -- Migration skipped (e.g., for specific environments)
    'PARTIAL'       -- Partial success (some statements failed)
);
COMMENT ON TYPE public.migration_status IS 'States of database migration execution for tracking deployment history';

-- -----------------------------------------------------------------------------
-- Enum: rate_limit_granularity
-- Description: Defines the time window granularity for rate limiting rules
-- Business Case: Allows flexible rate limiting per second, minute, hour, or day
-- Feature Reference: RL-01 (Rate Limiting)
-- -----------------------------------------------------------------------------
CREATE TYPE public.rate_limit_granularity AS ENUM (
    'SECOND',       -- Per second limits (e.g., 10 requests/second)
    'MINUTE',       -- Per minute limits (e.g., 100 requests/minute)
    'HOUR',         -- Per hour limits (e.g., 1000 requests/hour)
    'DAY',          -- Per day limits (e.g., 10000 requests/day)
    'MONTH'         -- Per month limits (e.g., for subscription tiers)
);
COMMENT ON TYPE public.rate_limit_granularity IS 'Time window granularities for rate limiting rules';

-- -----------------------------------------------------------------------------
-- Enum: rate_limit_action
-- Description: Defines actions to take when rate limit is exceeded
-- Business Case: Enables graduated response to abuse (throttle, block, alert)
-- Feature Reference: RL-02 (Rate Limit Enforcement)
-- -----------------------------------------------------------------------------
CREATE TYPE public.rate_limit_action AS ENUM (
    'THROTTLE',     -- Slow down requests (queue/delay)
    'BLOCK',        -- Reject requests with 429
    'ALERT_ONLY',   -- Log but don't block
    'CAPTCHA',      -- Challenge with CAPTCHA
    'MFA_REQUIRED'  -- Require multi-factor authentication
);
COMMENT ON TYPE public.rate_limit_action IS 'Actions taken when rate limit thresholds are exceeded';

-- -----------------------------------------------------------------------------
-- Enum: session_status
-- Description: Defines the lifecycle states of a user session
-- Business Case: Enables session management, revocation, and cleanup
-- Feature Reference: SESS-01 (Session Management)
-- -----------------------------------------------------------------------------
CREATE TYPE public.session_status AS ENUM (
    'ACTIVE',           -- Session is valid and usable
    'EXPIRED',          -- Session expired naturally (TTL reached)
    'REVOKED',          -- Explicitly revoked (logout everywhere)
    'TERMINATED',       -- Forcefully terminated by admin
    'SUSPENDED',        -- Temporarily suspended (security hold)
    'COMPROMISED'       -- Marked as potentially compromised
);
COMMENT ON TYPE public.session_status IS 'Lifecycle states of user authentication sessions';

-- -----------------------------------------------------------------------------
-- Enum: token_type
-- Description: Types of tokens used in authentication
-- Business Case: Distinguishes between different token purposes
-- Feature Reference: AUTH-02 (Token Management)
-- -----------------------------------------------------------------------------
CREATE TYPE public.token_type AS ENUM (
    'ACCESS_TOKEN',     -- Short-lived API access token
    'REFRESH_TOKEN',    -- Long-lived token to refresh access
    'ID_TOKEN',         -- OpenID Connect identity token
    'RESET_TOKEN',      -- Password reset token
    'VERIFICATION_TOKEN' -- Email/phone verification token
);
COMMENT ON TYPE public.token_type IS 'Types of authentication and authorization tokens';

-- -----------------------------------------------------------------------------
-- Enum: api_client_status
-- Description: Status of registered API client applications
-- Business Case: Manages client lifecycle from registration to revocation
-- Feature Reference: API-01 (API Client Management)
-- -----------------------------------------------------------------------------
CREATE TYPE public.api_client_status AS ENUM (
    'ACTIVE',           -- Client can authenticate and access APIs
    'PENDING_REVIEW',   -- Awaiting approval
    'SUSPENDED',        -- Temporarily disabled
    'REVOKED',          -- Permanently revoked
    'EXPIRED',          -- Client credentials expired
    'RATE_LIMITED'      -- Exceeded quota, temporarily blocked
);
COMMENT ON TYPE public.api_client_status IS 'Status states for registered API client applications';

-- -----------------------------------------------------------------------------
-- Enum: oauth_grant_type
-- Description: OAuth 2.0 grant types supported by the platform
-- Business Case: Enables different OAuth flows for different client types
-- Feature Reference: OAUTH-01 (OAuth2 Support)
-- -----------------------------------------------------------------------------
CREATE TYPE public.oauth_grant_type AS ENUM (
    'AUTHORIZATION_CODE',   -- Web server applications
    'CLIENT_CREDENTIALS',   -- Machine-to-machine
    'PASSWORD',            -- Legacy/trusted applications (deprecated)
    'REFRESH_TOKEN',       -- Token refresh
    'IMPLICIT'             -- Legacy SPAs (deprecated)
);
COMMENT ON TYPE public.oauth_grant_type IS 'OAuth 2.0 grant types for different authentication flows';

-- -----------------------------------------------------------------------------
-- Enum: secret_status
-- Description: Status of secrets in the secrets manager
-- Business Case: Tracks secret lifecycle from creation to destruction
-- Feature Reference: SEC-01 (Secrets Management)
-- -----------------------------------------------------------------------------
CREATE TYPE public.secret_status AS ENUM (
    'ACTIVE',           -- Secret is in use
    'ROTATING',         -- In process of rotation
    'RETIRED',          -- No longer in use but kept for history
    'COMPROMISED',      -- Marked as potentially leaked
    'DESTROYED',        -- Permanently deleted
    'EXPIRED'           -- Past its expiration date
);
COMMENT ON TYPE public.secret_status IS 'Lifecycle status of secrets in the management system';

-- -----------------------------------------------------------------------------
-- Enum: secret_rotation_policy
-- Description: Defines automatic rotation policies for secrets
-- Business Case: Automates credential rotation for security compliance
-- Feature Reference: SEC-02 (Secret Rotation)
-- -----------------------------------------------------------------------------
CREATE TYPE public.secret_rotation_policy AS ENUM (
    'MANUAL',           -- Rotate manually only
    'DAILY',            -- Rotate every 24 hours
    'WEEKLY',           -- Rotate every 7 days
    'MONTHLY',          -- Rotate every 30 days
    'QUARTERLY',        -- Rotate every 90 days
    'ON_COMPROMISE'     -- Rotate only if compromise detected
);
COMMENT ON TYPE public.secret_rotation_policy IS 'Policies for automatic secret rotation';

-- -----------------------------------------------------------------------------
-- Enum: encryption_key_status
-- Description: Status of encryption keys in the key hierarchy
-- Business Case: Manages key lifecycle for encryption compliance
-- Feature Reference: ENC-01 (Encryption Key Management)
-- -----------------------------------------------------------------------------
CREATE TYPE public.encryption_key_status AS ENUM (
    'ACTIVE',           -- Key is currently used for encryption
    'ACTIVE_READONLY',  -- Can decrypt but not encrypt new data
    'RETIRED',          -- No longer used, kept for decryption
    'DESTROYED',        -- Permanently destroyed
    'COMPROMISED',      -- Marked as potentially compromised
    'PENDING_ACTIVATION' -- Created but not yet active
);
COMMENT ON TYPE public.encryption_key_status IS 'Status of encryption keys in the key management hierarchy';

-- -----------------------------------------------------------------------------
-- Enum: encryption_key_usage
-- Description: Allowed usage purposes for encryption keys
-- Business Case: Implements principle of least privilege for keys
-- Feature Reference: ENC-02 (Key Usage Restrictions)
-- -----------------------------------------------------------------------------
CREATE TYPE public.encryption_key_usage AS ENUM (
    'DATA_ENCRYPTION',      -- Encrypt/decrypt application data
    'KEY_ENCRYPTION',       -- Encrypt other keys (KEK)
    'SIGNING',             -- Digital signatures
    'TOKENIZATION',        -- Tokenization of sensitive data
    'DATABASE_TDE'         -- Transparent data encryption
);
COMMENT ON TYPE public.encryption_key_usage IS 'Allowed purposes for encryption key usage';

-- -----------------------------------------------------------------------------
-- Enum: encryption_algorithm
-- Description: Supported encryption algorithms
-- Business Case: Enables algorithm agility and compliance with standards
-- Feature Reference: ENC-03 (Encryption Algorithms)
-- -----------------------------------------------------------------------------
CREATE TYPE public.encryption_algorithm AS ENUM (
    'AES256_GCM',       -- AES-256 in GCM mode (authenticated encryption)
    'AES256_CBC',       -- AES-256 in CBC mode (legacy)
    'CHACHA20_POLY1305', -- Modern stream cipher
    'RSA_OAEP_2048',    -- RSA with OAEP padding (2048-bit)
    'RSA_OAEP_4096',    -- RSA with OAEP padding (4096-bit)
    'ECIES_P256'        -- Elliptic curve integrated encryption
);
COMMENT ON TYPE public.encryption_algorithm IS 'Supported encryption algorithms for data protection';

-- -----------------------------------------------------------------------------
-- Enum: audit_severity
-- Description: Severity levels for audit log entries
-- Business Case: Prioritizes audit events for monitoring and alerting
-- Feature Reference: AUD-01 (Audit Logging)
-- -----------------------------------------------------------------------------
CREATE TYPE public.audit_severity AS ENUM (
    'DEBUG',            -- Detailed debugging information
    'INFO',             -- Normal operational information
    'WARNING',          -- Warning conditions
    'ERROR',            -- Error conditions
    'CRITICAL',         -- Critical conditions requiring immediate attention
    'SECURITY'          -- Security-related events (always logged)
);
COMMENT ON TYPE public.audit_severity IS 'Severity levels for audit log entries to prioritize monitoring';

-- -----------------------------------------------------------------------------
-- Enum: audit_category
-- Description: Categories for audit log entries
-- Business Case: Enables filtering and analysis of audit trails
-- Feature Reference: AUD-02 (Audit Categories)
-- -----------------------------------------------------------------------------
CREATE TYPE public.audit_category AS ENUM (
    'AUTHENTICATION',   -- Login/logout events
    'AUTHORIZATION',    -- Permission checks
    'DATA_ACCESS',      -- Data read/write operations
    'DATA_MODIFICATION', -- Create/update/delete operations
    'CONFIGURATION',    -- System configuration changes
    'SECURITY',         -- Security-related events
    'COMPLIANCE',       -- Compliance-relevant events
    'ADMIN_ACTION',     -- Administrative actions
    'API_ACCESS',       -- API calls
    'EXPORT'            -- Data exports (GDPR relevant)
);
COMMENT ON TYPE public.audit_category IS 'Categories for classifying audit log entries';

-- -----------------------------------------------------------------------------
-- Enum: data_sensitivity_level
-- Description: Sensitivity classification for data elements
-- Business Case: Implements data-centric security based on classification
-- Feature Reference: CLASS-01 (Data Classification)
-- -----------------------------------------------------------------------------
CREATE TYPE public.data_sensitivity_level AS ENUM (
    'PUBLIC',           -- Can be freely shared
    'INTERNAL',         -- Internal use only
    'CONFIDENTIAL',     -- Confidential business information
    'RESTRICTED',       -- Restricted access
    'PII',              -- Personally Identifiable Information
    'PCI',              -- Payment Card Industry data
    'PHI',              -- Protected Health Information
    'REGULATED'         -- Other regulated data
);
COMMENT ON TYPE public.data_sensitivity_level IS 'Data sensitivity classifications for access control and protection';

-- -----------------------------------------------------------------------------
-- Enum: data_category
-- Description: Categories of data for classification and processing
-- Business Case: Enables targeted protection based on data type
-- Feature Reference: CLASS-02 (Data Categories)
-- -----------------------------------------------------------------------------
CREATE TYPE public.data_category AS ENUM (
    'USER_PROFILE',     -- User profile information
    'AUTHENTICATION',   -- Authentication credentials
    'FINANCIAL',        -- Financial data
    'HEALTH',           -- Health information
    'DEMOGRAPHIC',      -- Demographic data
    'BEHAVIORAL',       -- User behavior data
    'PREFERENCES',      -- User preferences
    'CONTENT',          -- User-generated content
    'SYSTEM',           -- System-generated data
    'ANALYTICS'         -- Analytics data
);
COMMENT ON TYPE public.data_category IS 'Categories of data for classification and processing purposes';

-- =============================================================================
-- TABLE: 1 - schema_migrations
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 1
-- Table Name: schema_migrations
-- Description: Tracks version history of database schema changes applied
--              via CI/CD or migration tools with full audit trail.
--
-- Business Case: In an enterprise environment with multiple developers and
--                automated deployment pipelines, database schema changes must
--                be applied consistently across all environments (dev, test,
--                staging, production). Without a migration tracking table,
--                environments can drift, leading to deployment failures,
--                data corruption, and hours of debugging. This table stores
--                each migration's identifier, checksum, application timestamp,
--                and execution metadata, enabling idempotent runs and rollback
--                support. It is the cornerstone of Database as Code practices,
--                ensuring that all environments remain synchronized. The table
--                also supports auditability by recording who applied the
--                migration and when, which is essential for compliance
--                (SOC2, ISO27001) and incident investigation. The checksum
--                validation prevents tampering with already-applied migrations,
--                ensuring the integrity of the deployment history. With
--                support for rollbacks and partial success states, the team
--                can confidently deploy changes with minimal downtime risk.
--
-- KPIs:
--   1. Migration success rate > 99.5% (percentage of successful migrations)
--   2. Average migration execution time < 30 seconds
--   3. Number of failed migrations per release < 2
--   4. Environment drift count (mismatches between environments) = 0
--   5. Rollback frequency < 1 per quarter
--   6. Time to detect failed migration < 5 minutes
--   7. Migration test coverage (staging vs production) = 100%
--
-- Feature Reference: MIG-01 (Database Migration Management)
--                  : MIG-02 (Migration Audit Trail)
--                  : MIG-03 (Rollback Support)
-- -----------------------------------------------------------------------------
CREATE TABLE public.schema_migrations (
    -- Primary key
    migration_id      UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Migration identification (semantic versioning)
    version           VARCHAR(50) NOT NULL,
    name              VARCHAR(255) NOT NULL,
    description       TEXT,

    -- Content integrity
    checksum          TEXT NOT NULL,
    script_content    TEXT,                         -- Full migration script (for audit)
    rollback_script   TEXT,                          -- Optional rollback script

    -- Execution metadata
    applied_by        UUID NOT NULL,
    applied_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    execution_time_ms INTEGER,                       -- Duration of migration execution

    -- Status and tracking
    status            public.migration_status NOT NULL DEFAULT 'PENDING',
    rollback_of       UUID,                           -- If this migration is a rollback
    rollback_reason   TEXT,

    -- Environment and context
    environment       VARCHAR(50) NOT NULL,          -- e.g., 'production', 'staging'
    database_name     VARCHAR(100) NOT NULL,
    server_host       VARCHAR(255),

    -- Performance metrics
    rows_affected     BIGINT,
    locks_acquired    JSONB,                          -- Track locks for analysis

    -- Dependencies
    dependencies      UUID[],                          -- Migrations that must run before
    conflicts_with    UUID[],                          -- Migrations that conflict

    -- Deployment metadata
    deployment_id     VARCHAR(100),                    -- CI/CD pipeline ID
    git_commit        VARCHAR(40),                      -- Git commit hash
    git_branch        VARCHAR(255),
    pull_request_id   VARCHAR(50),

    -- Validation
    validated_at      TIMESTAMP WITH TIME ZONE,
    validated_by      UUID,
    validation_status VARCHAR(20) CHECK (validation_status IN ('PASSED', 'FAILED', 'PENDING')),

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_schema_migrations_version UNIQUE (version, environment),
    CONSTRAINT uq_schema_migrations_name UNIQUE (name, environment),
    CONSTRAINT fk_schema_migrations_rollback FOREIGN KEY (rollback_of)
        REFERENCES public.schema_migrations(migration_id) ON DELETE SET NULL,
    CONSTRAINT chk_migration_execution_time CHECK (execution_time_ms >= 0),
    CONSTRAINT chk_migration_version CHECK (version ~ '^\d+\.\d+\.\d+$')
);

-- Comments for schema_migrations table
COMMENT ON TABLE public.schema_migrations IS 'Tracks version history of database schema changes with full audit trail';
COMMENT ON COLUMN public.schema_migrations.migration_id IS 'Primary key using UUID for distributed systems';
COMMENT ON COLUMN public.schema_migrations.version IS 'Semantic version number (e.g., 1.2.3)';
COMMENT ON COLUMN public.schema_migrations.name IS 'Descriptive name of the migration (e.g., add_users_table)';
COMMENT ON COLUMN public.schema_migrations.description IS 'Detailed description of changes in this migration';
COMMENT ON COLUMN public.schema_migrations.checksum IS 'SHA-256 checksum of migration script to detect tampering';
COMMENT ON COLUMN public.schema_migrations.script_content IS 'Full migration script for audit and reconstruction';
COMMENT ON COLUMN public.schema_migrations.rollback_script IS 'Script to revert this migration if applicable';
COMMENT ON COLUMN public.schema_migrations.applied_by IS 'User ID who applied the migration';
COMMENT ON COLUMN public.schema_migrations.applied_at IS 'Timestamp when migration was applied';
COMMENT ON COLUMN public.schema_migrations.execution_time_ms IS 'Time taken to execute migration in milliseconds';
COMMENT ON COLUMN public.schema_migrations.status IS 'Current status of migration (PENDING, SUCCESS, FAILED, etc.)';
COMMENT ON COLUMN public.schema_migrations.rollback_of IS 'If this is a rollback, references original migration';
COMMENT ON COLUMN public.schema_migrations.rollback_reason IS 'Reason for rollback (for audit)';
COMMENT ON COLUMN public.schema_migrations.environment IS 'Environment where migration was applied';
COMMENT ON COLUMN public.schema_migrations.database_name IS 'Name of the database';
COMMENT ON COLUMN public.schema_migrations.server_host IS 'Database server hostname';
COMMENT ON COLUMN public.schema_migrations.rows_affected IS 'Number of rows affected by migration';
COMMENT ON COLUMN public.schema_migrations.locks_acquired IS 'JSON record of locks held during migration';
COMMENT ON COLUMN public.schema_migrations.dependencies IS 'Array of migration IDs that must run before this one';
COMMENT ON COLUMN public.schema_migrations.conflicts_with IS 'Array of migration IDs that conflict with this one';
COMMENT ON COLUMN public.schema_migrations.deployment_id IS 'CI/CD pipeline deployment identifier';
COMMENT ON COLUMN public.schema_migrations.git_commit IS 'Git commit hash of the migration script';
COMMENT ON COLUMN public.schema_migrations.git_branch IS 'Git branch name';
COMMENT ON COLUMN public.schema_migrations.pull_request_id IS 'Pull request identifier';
COMMENT ON COLUMN public.schema_migrations.validated_at IS 'When migration was validated in lower environment';
COMMENT ON COLUMN public.schema_migrations.validated_by IS 'Who validated the migration';
COMMENT ON COLUMN public.schema_migrations.validation_status IS 'Validation status in lower environments';
COMMENT ON COLUMN public.schema_migrations.created_at IS 'Timestamp of record creation';
COMMENT ON COLUMN public.schema_migrations.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.schema_migrations.created_by IS 'User who created the record';
COMMENT ON COLUMN public.schema_migrations.updated_by IS 'User who last updated the record';

-- Indexes for schema_migrations table
CREATE INDEX idx_schema_migrations_version ON public.schema_migrations(version, environment);
CREATE INDEX idx_schema_migrations_applied_at ON public.schema_migrations(applied_at DESC);
CREATE INDEX idx_schema_migrations_applied_by ON public.schema_migrations(applied_by);
CREATE INDEX idx_schema_migrations_status ON public.schema_migrations(status, environment);
CREATE INDEX idx_schema_migrations_validation ON public.schema_migrations(validation_status) WHERE validation_status = 'FAILED';
CREATE INDEX idx_schema_migrations_dependencies ON public.schema_migrations USING gin(dependencies);
CREATE INDEX idx_schema_migrations_git_commit ON public.schema_migrations(git_commit) WHERE git_commit IS NOT NULL;

-- Partial indexes for common queries
CREATE INDEX idx_schema_migrations_pending ON public.schema_migrations(version)
    WHERE status = 'PENDING' AND environment = 'production';
CREATE INDEX idx_schema_migrations_recent_failures ON public.schema_migrations(applied_at DESC)
    WHERE status = 'FAILED';

-- Trigger for updated_at
CREATE TRIGGER update_schema_migrations_timestamp
    BEFORE UPDATE ON public.schema_migrations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- No RLS needed as this is administrative data, but we add audit
COMMENT ON TABLE public.schema_migrations IS 'Tracks version history of database schema changes with full audit trail';

-- =============================================================================
-- TABLE: 2 - rate_limits
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 2
-- Table Name: rate_limits
-- Description: Defines rate limiting rules for API endpoints or actions,
--              including thresholds, time windows, and applicable user tiers.
--
-- Business Case: To protect the platform from abuse, denial-of-service attacks,
--                and unintentional overuse, rate limiting is essential. This
--                table stores configurable rules that can be applied per endpoint,
--                per user role, or per API client. By centralizing rate limit
--                definitions, the system can dynamically adjust limits without
--                code changes. The table supports multiple granularities
--                (per second, minute, hour, day) and can enforce both request
--                counts and concurrent request limits. Integration with API
--                gateways or middleware ensures fair usage and maintains service
--                quality for all users. The priority system allows complex rule
--                evaluation (e.g., stricter limits for free tier, more permissive
--                for premium). The table also supports graduated responses:
--                throttle first, then block, then challenge with CAPTCHA for
--                persistent offenders. With burst handling capabilities, the
--                system can accommodate legitimate traffic spikes while still
--                preventing abuse. This centralized approach enables:
--                1) Rapid response to new attack patterns by updating rules,
--                2) Granular control per API endpoint or action,
--                3) Tiered service levels for different user segments,
--                4) Analytics on API usage patterns,
--                5) Compliance with partner SLAs.
--
-- KPIs:
--   1. Number of rate limit violations per endpoint per day < 100
--   2. Percentage of requests throttled < 5% (healthy traffic)
--   3. Average response time under limit vs. over limit (degradation < 20%)
--   4. Time to detect new abuse patterns < 1 hour
--   5. Rule coverage (percentage of endpoints with rate limits) > 95%
--   6. False positive rate (legitimate users blocked) < 0.01%
--   7. Peak request handling capacity (requests/second) > 10,000
--
-- Feature Reference: RL-01 (Rate Limiting Rules)
--                  : RL-02 (Rate Limit Enforcement)
--                  : RL-03 (Burst Handling)
--                  : RL-04 (Tiered Rate Limits)
-- -----------------------------------------------------------------------------
CREATE TABLE public.rate_limits (
    -- Primary key
    rate_limit_id     UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Rule identification
    name              VARCHAR(100) NOT NULL,
    description       TEXT,

    -- Resource targeting (supports wildcards)
    resource_pattern  VARCHAR(255) NOT NULL,    -- e.g., '/api/v1/jobs/*' or 'jobs:search'
    method            VARCHAR(10),               -- HTTP method if applicable (GET, POST, etc.)

    -- Target audience
    user_tier         VARCHAR(50) DEFAULT 'ALL', -- 'FREE', 'PREMIUM', 'ENTERPRISE', 'ALL'
    user_role         VARCHAR(50),                -- Specific role if applicable
    api_client_id     UUID,                        -- Specific API client if applicable
    ip_range          CIDR,                        -- IP range for geo-based limits

    -- Limit configuration
    limit_count       INTEGER NOT NULL CHECK (limit_count > 0),
    window_size       INTEGER NOT NULL CHECK (window_size > 0), -- Numeric value
    window_granularity public.rate_limit_granularity NOT NULL,

    -- Advanced controls
    concurrent_limit  INTEGER,                     -- Max concurrent requests
    burst_multiplier  NUMERIC(3,1) DEFAULT 1.0 CHECK (burst_multiplier >= 1.0), -- Allow bursts
    burst_duration_seconds INTEGER,                 -- How long burst allowed

    -- Response configuration
    exceeded_action   public.rate_limit_action NOT NULL DEFAULT 'BLOCK',
    response_message  TEXT,                          -- Custom error message
    retry_after_seconds INTEGER,                      -- Suggested retry time

    -- Priority and evaluation
    priority          INTEGER DEFAULT 100 CHECK (priority >= 1), -- Lower = evaluated first
    is_active         BOOLEAN DEFAULT true NOT NULL,

    -- Time-based restrictions
    time_restriction_start TIME WITHOUT TIME ZONE,   -- e.g., business hours only
    time_restriction_end   TIME WITHOUT TIME ZONE,
    day_of_week_restriction INTEGER[],                 -- 0=Sunday, 6=Saturday

    -- Alerting
    alert_threshold   INTEGER,                        -- Alert when approaching limit
    alert_webhook     TEXT,                            -- Webhook for alerts

    -- Audit and metadata
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_rate_limit_resource UNIQUE (resource_pattern, method, user_tier, user_role, api_client_id),
    CONSTRAINT chk_rate_limit_window CHECK (window_size > 0),
    CONSTRAINT chk_rate_limit_burst CHECK (burst_multiplier >= 1.0),
    CONSTRAINT chk_rate_limit_time_range CHECK (
        (time_restriction_start IS NULL AND time_restriction_end IS NULL) OR
        (time_restriction_start IS NOT NULL AND time_restriction_end IS NOT NULL AND
         time_restriction_start < time_restriction_end)
    )
);

-- Comments for rate_limits table
COMMENT ON TABLE public.rate_limits IS 'Configurable rate limiting rules for API endpoints and actions';
COMMENT ON COLUMN public.rate_limits.rate_limit_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.rate_limits.name IS 'Short, descriptive name for the rule (e.g., jobs_api_free_tier)';
COMMENT ON COLUMN public.rate_limits.description IS 'Detailed description of the rule and its purpose';
COMMENT ON COLUMN public.rate_limits.resource_pattern IS 'Pattern matching the resource (supports wildcards like * for any)';
COMMENT ON COLUMN public.rate_limits.method IS 'HTTP method (GET, POST, PUT, DELETE) or action type';
COMMENT ON COLUMN public.rate_limits.user_tier IS 'User tier to which rule applies (FREE, PREMIUM, ENTERPRISE, ALL)';
COMMENT ON COLUMN public.rate_limits.user_role IS 'Specific role (admin, user, etc.) if rule is role-specific';
COMMENT ON COLUMN public.rate_limits.api_client_id IS 'Specific API client ID for client-specific limits';
COMMENT ON COLUMN public.rate_limits.ip_range IS 'IP range for geo-based or network-based limits';
COMMENT ON COLUMN public.rate_limits.limit_count IS 'Maximum number of requests allowed in the time window';
COMMENT ON COLUMN public.rate_limits.window_size IS 'Size of the time window (numeric value)';
COMMENT ON COLUMN public.rate_limits.window_granularity IS 'Unit of window size (SECOND, MINUTE, HOUR, DAY, MONTH)';
COMMENT ON COLUMN public.rate_limits.concurrent_limit IS 'Maximum number of concurrent requests allowed';
COMMENT ON COLUMN public.rate_limits.burst_multiplier IS 'Allows temporary bursts (e.g., 2.0 = double the limit for short periods)';
COMMENT ON COLUMN public.rate_limits.burst_duration_seconds IS 'How long the burst multiplier applies (in seconds)';
COMMENT ON COLUMN public.rate_limits.exceeded_action IS 'Action to take when limit is exceeded';
COMMENT ON COLUMN public.rate_limits.response_message IS 'Custom error message to return when limit exceeded';
COMMENT ON COLUMN public.rate_limits.retry_after_seconds IS 'Suggested time to wait before retrying';
COMMENT ON COLUMN public.rate_limits.priority IS 'Evaluation order (lower numbers evaluated first)';
COMMENT ON COLUMN public.rate_limits.is_active IS 'Whether rule is currently enforced';
COMMENT ON COLUMN public.rate_limits.time_restriction_start IS 'Start time for when rule applies (e.g., 09:00 for business hours)';
COMMENT ON COLUMN public.rate_limits.time_restriction_end IS 'End time for when rule applies';
COMMENT ON COLUMN public.rate_limits.day_of_week_restriction IS 'Days of week rule applies (0=Sunday, 6=Saturday)';
COMMENT ON COLUMN public.rate_limits.alert_threshold IS 'Alert when usage reaches this percentage of limit';
COMMENT ON COLUMN public.rate_limits.alert_webhook IS 'Webhook URL for sending alerts';
COMMENT ON COLUMN public.rate_limits.created_at IS 'Timestamp of rule creation';
COMMENT ON COLUMN public.rate_limits.updated_at IS 'Timestamp of last rule update';
COMMENT ON COLUMN public.rate_limits.created_by IS 'User who created the rule';
COMMENT ON COLUMN public.rate_limits.updated_by IS 'User who last updated the rule';

-- Indexes for rate_limits table
CREATE INDEX idx_rate_limits_resource ON public.rate_limits(resource_pattern, method);
CREATE INDEX idx_rate_limits_user_tier ON public.rate_limits(user_tier, user_role);
CREATE INDEX idx_rate_limits_api_client ON public.rate_limits(api_client_id) WHERE api_client_id IS NOT NULL;
CREATE INDEX idx_rate_limits_active ON public.rate_limits(is_active, priority) WHERE is_active = true;
CREATE INDEX idx_rate_limits_ip_range ON public.rate_limits USING gist(ip_range) WHERE ip_range IS NOT NULL;
CREATE INDEX idx_rate_limits_time_restriction ON public.rate_limits(time_restriction_start, time_restriction_end)
    WHERE time_restriction_start IS NOT NULL;

-- GiST index for IP range searches
CREATE INDEX idx_rate_limits_ip_range_gist ON public.rate_limits USING gist(ip_range);

-- Trigger for updated_at
CREATE TRIGGER update_rate_limits_timestamp
    BEFORE UPDATE ON public.rate_limits
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS for multi-tenant support (if needed)
ALTER TABLE public.rate_limits ENABLE ROW LEVEL SECURITY;

-- Policy: Admins can manage all rules
CREATE POLICY rate_limits_admin_policy ON public.rate_limits
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'security_admin')
    ));

-- Policy: Read-only for API gateway service account
CREATE POLICY rate_limits_readonly_policy ON public.rate_limits
    FOR SELECT USING (current_user = 'api_gateway');

-- =============================================================================
-- TABLE: 3 - sessions
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 3
-- Table Name: sessions
-- Description: Stores active user sessions with tokens, expiry, and metadata
--              for authentication and authorization with comprehensive security.
--
-- Business Case: Modern applications require robust session management to
--                maintain user state securely across requests. This table holds
--                session tokens (JWT or opaque), refresh tokens, device
--                information, and expiry times. It enables features like
--                "logout everywhere", session revocation, and concurrent session
--                limits. By storing sessions, the system can invalidate
--                compromised tokens and enforce security policies (e.g., MFA
--                required after a certain time, re-authentication for sensitive
--                operations). The table supports risk-based authentication by
--                tracking login patterns, device fingerprints, and geographic
--                locations. For compliance with regulations like GDPR, it
--                records consent timestamps and allows users to view active
--                sessions. The session management system also enables:
--                1) Single sign-on across multiple applications,
--                2) Remember me functionality with secure token rotation,
--                3) Detection of suspicious activities (multiple geographic
--                   locations, impossible travel times),
--                4) Automatic cleanup of expired sessions for performance,
--                5) Audit trails for security investigations.
--                With support for refresh token rotation, the system can detect
--                token theft and automatically revoke compromised sessions.
--                The device fingerprinting helps in recognizing trusted devices
--                and reducing friction for returning users.
--
-- KPIs:
--   1. Active sessions per user (average < 3, max < 10 for security)
--   2. Session duration (average, distribution) - 80% < 24 hours
--   3. Session revocation rate due to security events < 1% of total sessions
--   4. Concurrent session limit violations (users exceeding limits) < 0.1%
--   5. Refresh token success rate > 99%
--   6. Time to detect compromised sessions < 5 minutes
--   7. Session cleanup efficiency (expired sessions removed within 1 hour)
--   8. Geographic anomaly detection rate > 95%
--
-- Feature Reference: SESS-01 (Session Management)
--                  : SESS-02 (Token Rotation)
--                  : SESS-03 (Device Fingerprinting)
--                  : SESS-04 (Concurrent Session Control)
--                  : SESS-05 (Session Audit)
-- -----------------------------------------------------------------------------
CREATE TABLE public.sessions (
    -- Primary key
    session_id        UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User association
    user_id           UUID NOT NULL,

    -- Authentication tokens (all hashed/encrypted)
    access_token      TEXT NOT NULL,                -- Hashed access token
    refresh_token     TEXT,                          -- Hashed refresh token
    id_token          TEXT,                          -- OpenID Connect ID token
    token_type        VARCHAR(20) DEFAULT 'Bearer' NOT NULL,

    -- Token metadata
    token_family      UUID,                          -- Group related tokens (rotation chain)
    token_version     INTEGER DEFAULT 1,              -- For token format migration

    -- Time-based controls
    issued_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    refresh_expires_at TIMESTAMP WITH TIME ZONE,
    last_activity_at  TIMESTAMP WITH TIME ZONE,

    -- Client information
    client_id         UUID,                            -- OAuth client if applicable
    client_version    VARCHAR(50),
    user_agent        TEXT,
    user_agent_parsed JSONB,                           -- Parsed browser/OS info

    -- Device fingerprinting
    device_id         VARCHAR(255),                     -- Unique device identifier
    device_name       VARCHAR(255),
    device_type       VARCHAR(50) CHECK (device_type IN ('desktop', 'mobile', 'tablet', 'tv', 'watch', 'bot')),
    device_os         VARCHAR(100),
    device_os_version VARCHAR(50),
    browser_name      VARCHAR(100),
    browser_version   VARCHAR(50),
    screen_resolution VARCHAR(20),
    timezone_offset   INTEGER,                           -- Minutes from UTC
    language          VARCHAR(10),

    -- Network information
    ip_address        INET,
    ip_location       GEOGRAPHY(POINT),                  -- Geolocation (if consented)
    ip_country        CHAR(2),                            -- Country code
    ip_city           VARCHAR(100),
    ip_asn            INTEGER,                            -- Autonomous System Number
    ip_isp            VARCHAR(100),
    proxy_detected    BOOLEAN DEFAULT false,
    vpn_detected      BOOLEAN DEFAULT false,
    tor_detected      BOOLEAN DEFAULT false,

    -- Security context
    auth_method       VARCHAR(50) CHECK (auth_method IN ('password', 'oauth', 'saml', 'mfa', 'magic_link', 'api_key')),
    mfa_used          BOOLEAN DEFAULT false,
    mfa_method        VARCHAR(50),
    auth_provider     VARCHAR(50),                        -- 'google', 'linkedin', etc. for OAuth
    auth_provider_id  VARCHAR(255),                       -- User ID from provider

    -- Risk assessment
    risk_score        NUMERIC(5,2) CHECK (risk_score >= 0 AND risk_score <= 100),
    risk_factors      TEXT[],                              -- ['new_device', 'new_location', 'unusual_time']
    risk_assessment_at TIMESTAMP WITH TIME ZONE,

    -- Session controls
    status            public.session_status NOT NULL DEFAULT 'ACTIVE',
    requires_reauthentication BOOLEAN DEFAULT false,
    reauthentication_reason VARCHAR(100),
    reauthentication_at TIMESTAMP WITH TIME ZONE,

    -- Concurrent session management
    session_sequence  INTEGER,                            -- Order among user's sessions
    parent_session_id UUID,                                -- For session hierarchies

    -- Consent tracking
    consent_granted_at TIMESTAMP WITH TIME ZONE,
    consent_version   VARCHAR(50),

    -- Termination details
    terminated_at     TIMESTAMP WITH TIME ZONE,
    terminated_by     UUID,                                -- User or admin who terminated
    termination_reason TEXT,
    termination_ip    INET,

    -- Audit
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,                       -- Usually the user themselves
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_access_token UNIQUE (access_token),
    CONSTRAINT uq_refresh_token UNIQUE (refresh_token),
    CONSTRAINT uq_id_token UNIQUE (id_token),
    CONSTRAINT chk_session_expiry CHECK (expires_at > issued_at),
    CONSTRAINT chk_refresh_expiry CHECK (refresh_expires_at IS NULL OR refresh_expires_at > issued_at),
    CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_sessions_client FOREIGN KEY (client_id) REFERENCES public.api_clients(client_id) ON DELETE SET NULL,
    CONSTRAINT fk_sessions_parent FOREIGN KEY (parent_session_id) REFERENCES public.sessions(session_id) ON DELETE SET NULL,
    CONSTRAINT fk_sessions_terminated_by FOREIGN KEY (terminated_by) REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for sessions table
COMMENT ON TABLE public.sessions IS 'Active user sessions with comprehensive security and device tracking';
COMMENT ON COLUMN public.sessions.session_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.sessions.user_id IS 'User owning the session (references users table)';
COMMENT ON COLUMN public.sessions.access_token IS 'Hashed access token for API authentication';
COMMENT ON COLUMN public.sessions.refresh_token IS 'Hashed refresh token for obtaining new access tokens';
COMMENT ON COLUMN public.sessions.id_token IS 'OpenID Connect ID token (if applicable)';
COMMENT ON COLUMN public.sessions.token_type IS 'Type of token (Bearer, MAC, etc.)';
COMMENT ON COLUMN public.sessions.token_family IS 'Group identifier for token rotation chains';
COMMENT ON COLUMN public.sessions.token_version IS 'Version number for token format migration';
COMMENT ON COLUMN public.sessions.issued_at IS 'Timestamp when session was created';
