COMMENT ON COLUMN public.sessions.updated_by IS 'User who last updated the session';

-- Indexes for sessions table
CREATE INDEX idx_sessions_user_id ON public.sessions(user_id, status);
CREATE INDEX idx_sessions_access_token ON public.sessions(access_token);
CREATE INDEX idx_sessions_refresh_token ON public.sessions(refresh_token) WHERE refresh_token IS NOT NULL;
CREATE INDEX idx_sessions_token_family ON public.sessions(token_family);
CREATE INDEX idx_sessions_expires_at ON public.sessions(expires_at) WHERE status = 'ACTIVE';
CREATE INDEX idx_sessions_refresh_expires ON public.sessions(refresh_expires_at) WHERE refresh_token IS NOT NULL;
CREATE INDEX idx_sessions_last_activity ON public.sessions(last_activity_at) WHERE status = 'ACTIVE';
CREATE INDEX idx_sessions_device_id ON public.sessions(device_id) WHERE device_id IS NOT NULL;
CREATE INDEX idx_sessions_ip_address ON public.sessions(ip_address);
CREATE INDEX idx_sessions_risk_score ON public.sessions(risk_score DESC) WHERE risk_score > 70;
CREATE INDEX idx_sessions_terminated ON public.sessions(terminated_at) WHERE terminated_at IS NOT NULL;

-- GiST index for IP location searches
CREATE INDEX idx_sessions_ip_location ON public.sessions USING gist(ip_location) WHERE ip_location IS NOT NULL;

-- BRIN index for time-based queries on large session table
CREATE INDEX idx_sessions_created_brin ON public.sessions USING brin(created_at);

-- Partial indexes for common queries
CREATE INDEX idx_sessions_active ON public.sessions(user_id, last_activity_at)
    WHERE status = 'ACTIVE';
CREATE INDEX idx_sessions_stale ON public.sessions(last_activity_at)
    WHERE status = 'ACTIVE' AND last_activity_at < NOW() - INTERVAL '30 days';

-- Trigger for updated_at
CREATE TRIGGER update_sessions_timestamp
    BEFORE UPDATE ON public.sessions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.sessions ENABLE ROW LEVEL SECURITY;

-- Policy: Users can see and manage their own sessions
CREATE POLICY sessions_user_policy ON public.sessions
    USING (user_id = current_user_id());

-- Policy: Security team can view all sessions for investigation
CREATE POLICY sessions_security_policy ON public.sessions
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('security_admin', 'admin')
    ));

-- Policy: Session cleanup service can update expired sessions
CREATE POLICY sessions_cleanup_policy ON public.sessions
    FOR UPDATE USING (current_user = 'session_cleanup')
    WITH CHECK (status IN ('EXPIRED', 'TERMINATED'));

-- =============================================================================
-- TABLE: 4 - api_clients
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 4
-- Table Name: api_clients
-- Description: Registers and manages third-party applications that can access
--              the platform's API with OAuth2 client credentials.
--
-- Business Case: As the platform grows, third-party developers and partners
--                will want to build integrations and applications that consume
--                our APIs. Without a proper client registration system, there
--                is no way to control access, track usage, or revoke permissions
--                when needed. This table serves as the authoritative source for
--                all applications that can authenticate via OAuth2. It stores
--                client credentials (hashed secrets), allowed redirect URIs,
--                granted scopes, and application metadata. The registration
--                process ensures that every application is vetted and approved
--                before accessing user data. This table enables:
--                1) Secure OAuth2 flows with proper client authentication,
--                2) Per-client rate limiting and usage quotas,
--                3) Granular permission scopes (read-only, write, etc.),
--                4) Developer portal with self-service registration,
--                5) Audit of which applications access user data,
--                6) Revocation of compromised or abandoned applications,
--                7) Analytics on API usage by application.
--                For enterprise customers, it supports:
--                - Custom applications with dedicated rate limits,
--                - IP whitelisting for additional security,
--                - Service accounts for machine-to-machine integration.
--                The table also tracks compliance with terms of service and
--                enables automated suspension for policy violations.
--
-- KPIs:
--   1. Number of active API clients (target: 100+ in first year)
--   2. Average time to approve new client registration < 24 hours
--   3. Percentage of API calls from registered clients > 95%
--   4. Client revocation rate (security incidents) < 1% per quarter
--   5. Developer satisfaction score with API portal > 4.5/5
--   6. OAuth2 flow success rate > 99.5%
--   7. Time to rotate compromised client secrets < 1 hour
--   8. Compliance with API terms (violations detected) < 1% of clients
--
-- Feature Reference: API-01 (API Client Management)
--                  : API-02 (OAuth2 Server)
--                  : API-03 (Client Authentication)
--                  : API-04 (Scope Management)
--                  : API-05 (Developer Portal)
-- -----------------------------------------------------------------------------
CREATE TABLE public.api_clients (
    -- Primary key
    client_id         UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Client identification
    client_name       VARCHAR(255) NOT NULL,
    client_description TEXT,
    client_website    VARCHAR(255),
    client_logo_url   VARCHAR(255),

    -- Client credentials (OAuth2)
    client_secret_hash TEXT NOT NULL,                  -- Hashed client secret
    client_secret_rotated_at TIMESTAMP WITH TIME ZONE,
    client_secret_expires_at TIMESTAMP WITH TIME ZONE,

    -- Authentication
    allowed_grant_types public.oauth_grant_type[] NOT NULL DEFAULT '{AUTHORIZATION_CODE,REFRESH_TOKEN}',
    auth_method        VARCHAR(50) CHECK (auth_method IN ('client_secret_basic', 'client_secret_post', 'private_key_jwt', 'none')),

    -- OAuth2 endpoints
    redirect_uris      TEXT[] NOT NULL,                 -- Allowed callback URLs
    post_logout_redirect_uris TEXT[],                   -- Post-logout redirects
    logo_uri           VARCHAR(255),
    policy_uri         VARCHAR(255),                     -- Privacy policy URL
    tos_uri            VARCHAR(255),                     -- Terms of service URL

    -- Permissions
    scopes             TEXT[] NOT NULL DEFAULT '{}',     -- Granted scopes (e.g., 'read:profile', 'write:messages')
    default_scopes     TEXT[] DEFAULT '{read:profile}',  -- Scopes granted by default

    -- Owner information
    owner_user_id      UUID NOT NULL,                     -- Developer who registered
    owner_company_id   UUID,                               -- Company if applicable
    technical_contact  VARCHAR(255),                       -- Email for technical issues
    business_contact   VARCHAR(255),                       -- Email for business matters

    -- Rate limiting and quotas
    rate_limit_tier    VARCHAR(50) DEFAULT 'STANDARD',    -- 'STANDARD', 'PREMIUM', 'ENTERPRISE'
    quota_daily        INTEGER,                            -- Daily request quota
    quota_monthly      INTEGER,                            -- Monthly request quota
    concurrent_limit   INTEGER DEFAULT 100,                 -- Max concurrent connections

    -- Security controls
    ip_whitelist       CIDR[],                              -- Allowed IP ranges
    require_pkce       BOOLEAN DEFAULT true,                -- Require Proof Key for Code Exchange
    require_consent    BOOLEAN DEFAULT true,                -- Require user consent
    allow_offline_access BOOLEAN DEFAULT false,             -- Can request refresh tokens

    -- Status and compliance
    status             public.api_client_status NOT NULL DEFAULT 'PENDING_REVIEW',
    status_reason      TEXT,
    approved_at        TIMESTAMP WITH TIME ZONE,
    approved_by        UUID,
    last_activity_at   TIMESTAMP WITH TIME ZONE,

    -- Terms acceptance
    terms_accepted_at  TIMESTAMP WITH TIME ZONE,
    terms_version      VARCHAR(50),
    privacy_policy_accepted_at TIMESTAMP WITH TIME ZONE,

    -- Application metadata
    app_type           VARCHAR(50) CHECK (app_type IN ('web', 'native', 'spa', 'machine', 'backend')),
    platform           VARCHAR(50),                         -- 'ios', 'android', 'web', etc.
    version            VARCHAR(50),

    -- Compliance
    data_retention_days INTEGER DEFAULT 30,                  -- How long to retain user data
    complies_with_gdpr BOOLEAN DEFAULT false,
    gdpr_contact      VARCHAR(255),
    dpia_completed_at TIMESTAMP WITH TIME ZONE,

    -- Audit and metadata
    created_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by         UUID NOT NULL,
    updated_by         UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_client_name UNIQUE (client_name),
    CONSTRAINT chk_client_redirect_uris CHECK (array_length(redirect_uris, 1) > 0),
    CONSTRAINT chk_client_secret_expiry CHECK (client_secret_expires_at IS NULL OR client_secret_expires_at > CURRENT_TIMESTAMP),
    CONSTRAINT fk_api_clients_owner_user FOREIGN KEY (owner_user_id) REFERENCES public.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_api_clients_owner_company FOREIGN KEY (owner_company_id) REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT fk_api_clients_approved_by FOREIGN KEY (approved_by) REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for api_clients table
COMMENT ON TABLE public.api_clients IS 'Registered OAuth2 client applications with comprehensive security controls';
COMMENT ON COLUMN public.api_clients.client_id IS 'Primary key - the OAuth2 client_id';
COMMENT ON COLUMN public.api_clients.client_name IS 'Display name of the application';
COMMENT ON COLUMN public.api_clients.client_description IS 'Detailed description of the application';
COMMENT ON COLUMN public.api_clients.client_website IS 'Application website URL';
COMMENT ON COLUMN public.api_clients.client_logo_url IS 'URL to application logo';
COMMENT ON COLUMN public.api_clients.client_secret_hash IS 'Hashed client secret (never store plaintext)';
COMMENT ON COLUMN public.api_clients.client_secret_rotated_at IS 'When the client secret was last rotated';
COMMENT ON COLUMN public.api_clients.client_secret_expires_at IS 'When the current client secret expires';
COMMENT ON COLUMN public.api_clients.allowed_grant_types IS 'OAuth2 grant types this client can use';
COMMENT ON COLUMN public.api_clients.auth_method IS 'Authentication method for token endpoint';
COMMENT ON COLUMN public.api_clients.redirect_uris IS 'Allowed OAuth2 redirect URIs (for authorization code flow)';
COMMENT ON COLUMN public.api_clients.post_logout_redirect_uris IS 'Allowed redirect URIs after logout';
COMMENT ON COLUMN public.api_clients.logo_uri IS 'URI to client logo for consent screen';
COMMENT ON COLUMN public.api_clients.policy_uri IS 'URI to privacy policy';
COMMENT ON COLUMN public.api_clients.tos_uri IS 'URI to terms of service';
COMMENT ON COLUMN public.api_clients.scopes IS 'All scopes this client is allowed to request';
COMMENT ON COLUMN public.api_clients.default_scopes IS 'Scopes automatically granted without user selection';
COMMENT ON COLUMN public.api_clients.owner_user_id IS 'Developer user who owns this client';
COMMENT ON COLUMN public.api_clients.owner_company_id IS 'Company that owns this client (if applicable)';
COMMENT ON COLUMN public.api_clients.technical_contact IS 'Email for technical support issues';
COMMENT ON COLUMN public.api_clients.business_contact IS 'Email for business/commercial matters';
COMMENT ON COLUMN public.api_clients.rate_limit_tier IS 'Rate limiting tier for this client';
COMMENT ON COLUMN public.api_clients.quota_daily IS 'Maximum API requests per day';
COMMENT ON COLUMN public.api_clients.quota_monthly IS 'Maximum API requests per month';
COMMENT ON COLUMN public.api_clients.concurrent_limit IS 'Maximum concurrent connections';
COMMENT ON COLUMN public.api_clients.ip_whitelist IS 'Allowed IP ranges (empty = all IPs allowed)';
COMMENT ON COLUMN public.api_clients.require_pkce IS 'Whether PKCE is required for authorization code flow';
COMMENT ON COLUMN public.api_clients.require_consent IS 'Whether user consent is required';
COMMENT ON COLUMN public.api_clients.allow_offline_access IS 'Whether client can request offline access (refresh tokens)';
COMMENT ON COLUMN public.api_clients.status IS 'Current client status';
COMMENT ON COLUMN public.api_clients.status_reason IS 'Reason for current status (if suspended/rejected)';
COMMENT ON COLUMN public.api_clients.approved_at IS 'When client was approved';
COMMENT ON COLUMN public.api_clients.approved_by IS 'Who approved the client';
COMMENT ON COLUMN public.api_clients.last_activity_at IS 'Last API activity from this client';
COMMENT ON COLUMN public.api_clients.terms_accepted_at IS 'When developer accepted terms of service';
COMMENT ON COLUMN public.api_clients.terms_version IS 'Version of terms accepted';
COMMENT ON COLUMN public.api_clients.privacy_policy_accepted_at IS 'When privacy policy was accepted';
COMMENT ON COLUMN public.api_clients.app_type IS 'Type of application';
COMMENT ON COLUMN public.api_clients.platform IS 'Target platform (iOS, Android, Web)';
COMMENT ON COLUMN public.api_clients.version IS 'Application version';
COMMENT ON COLUMN public.api_clients.data_retention_days IS 'Days to retain user data (for compliance)';
COMMENT ON COLUMN public.api_clients.complies_with_gdpr IS 'Whether client claims GDPR compliance';
COMMENT ON COLUMN public.api_clients.gdpr_contact IS 'GDPR contact email';
COMMENT ON COLUMN public.api_clients.dpia_completed_at IS 'When Data Protection Impact Assessment was completed';
COMMENT ON COLUMN public.api_clients.created_at IS 'Timestamp of client registration';
COMMENT ON COLUMN public.api_clients.updated_at IS 'Timestamp of last client update';
COMMENT ON COLUMN public.api_clients.created_by IS 'User who created the client record';
COMMENT ON COLUMN public.api_clients.updated_by IS 'User who last updated the client';

-- Indexes for api_clients table
CREATE INDEX idx_api_clients_owner_user ON public.api_clients(owner_user_id);
CREATE INDEX idx_api_clients_owner_company ON public.api_clients(owner_company_id) WHERE owner_company_id IS NOT NULL;
CREATE INDEX idx_api_clients_status ON public.api_clients(status, last_activity_at);
CREATE INDEX idx_api_clients_rate_limit_tier ON public.api_clients(rate_limit_tier) WHERE status = 'ACTIVE';
CREATE INDEX idx_api_clients_name_search ON public.api_clients USING gin(client_name gin_trgm_ops);

-- Partial index for active clients
CREATE INDEX idx_api_clients_active ON public.api_clients(client_id) WHERE status = 'ACTIVE';

-- GiST index for IP whitelist
CREATE INDEX idx_api_clients_ip_whitelist ON public.api_clients USING gin(ip_whitelist);

-- Trigger for updated_at
CREATE TRIGGER update_api_clients_timestamp
    BEFORE UPDATE ON public.api_clients
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.api_clients ENABLE ROW LEVEL SECURITY;

-- Policy: Developers can see and manage their own clients
CREATE POLICY api_clients_owner_policy ON public.api_clients
    USING (owner_user_id = current_user_id());

-- Policy: Admins can manage all clients
CREATE POLICY api_clients_admin_policy ON public.api_clients
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'api_admin')
    ));

-- Policy: OAuth2 server can read client details
CREATE POLICY api_clients_oauth_policy ON public.api_clients
    FOR SELECT USING (current_user = 'oauth_server');

-- =============================================================================
-- TABLE: 5 - secrets_manager
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 5
-- Table Name: secrets_manager
-- Description: Centralized, encrypted storage for all application secrets
--              including API keys, database passwords, and encryption keys
--              with full audit trail and rotation policies.
--
-- Business Case: In a microservices architecture, dozens of services need
--                credentials to access databases, external APIs, and other
--                services. Hardcoding these secrets in configuration files or
--                environment variables creates security risks and operational
--                overhead. This table serves as a centralized vault for all
--                secrets, with encryption at rest and in transit. It provides:
--                1) Single source of truth for all credentials,
--                2) Automatic rotation of secrets based on policies,
--                3) Versioning to support zero-downtime rotation,
--                4) Granular access controls (who can read which secrets),
--                5) Full audit trail of all secret access,
--                6) Emergency access procedures for break-glass scenarios,
--                7) Integration with Kubernetes/container orchestration,
--                8) Compliance with standards like PCI DSS and SOC2.
--                The table supports hierarchical secret organization (by
--                environment, service, region) and can store different types
--                of secrets (opaque strings, key pairs, certificates). With
--                built-in rotation policies, secrets can be automatically
--                rotated on schedule or on-demand, with old versions kept for
--                rollback. The system also detects potential compromises
--                (e.g., secrets exposed in logs) and triggers immediate
--                rotation. For disaster recovery, the table supports backup
--                and restore with master key escrow.
--
-- KPIs:
--   1. Number of secrets under management (target: all production secrets)
--   2. Average secret rotation compliance > 95% (rotated within policy)
--   3. Time to rotate compromised secret < 5 minutes
--   4. Secret access audit coverage (all accesses logged) = 100%
--   5. Zero secrets in plaintext in configuration files
--   6. Time to onboard new service with secrets < 1 hour
--   7. Secret retrieval latency < 100ms (cached)
--   8. Number of unauthorized access attempts detected
--
-- Feature Reference: SEC-01 (Secrets Management)
--                  : SEC-02 (Secret Rotation)
--                  : SEC-03 (Access Audit)
--                  : SEC-04 (Emergency Access)
--                  : SEC-05 (Compromise Detection)
-- -----------------------------------------------------------------------------
CREATE TABLE public.secrets_manager (
    -- Primary key
    secret_id         UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Secret identification
    secret_key        VARCHAR(255) NOT NULL,           -- e.g., 'database/main/password'
    secret_name       VARCHAR(255) NOT NULL,            -- Human-readable name
    description       TEXT,

    -- Secret value (encrypted)
    secret_value      BYTEA NOT NULL,                    -- Encrypted secret
    secret_hash       TEXT,                               -- Hash for integrity
    encryption_key_id UUID,                               -- Which key encrypted it

    -- Secret metadata
    secret_type       VARCHAR(50) CHECK (secret_type IN ('password', 'api_key', 'certificate', 'ssh_key', 'token', 'connection_string')),
    version           INTEGER NOT NULL DEFAULT 1,
    previous_version_id UUID,                             -- Link to previous version

    -- Environment and context
    environment       VARCHAR(50) NOT NULL CHECK (environment IN ('development', 'staging', 'production', 'dr')),
    service_name      VARCHAR(100) NOT NULL,              -- Which service uses this
    region            VARCHAR(50),                         -- Geographic region
    component         VARCHAR(100),                        -- Sub-component

    -- Rotation policy
    rotation_policy   public.secret_rotation_policy NOT NULL DEFAULT 'MANUAL',
    rotation_schedule VARCHAR(50),                          -- Cron expression for auto-rotation
    last_rotated_at   TIMESTAMP WITH TIME ZONE,
    next_rotation_at  TIMESTAMP WITH TIME ZONE,
    rotated_by        UUID,                                 -- Who last rotated

    -- Expiration
    expires_at        TIMESTAMP WITH TIME ZONE,
    expiry_warning_sent BOOLEAN DEFAULT false,

    -- Access control
    allowed_services  TEXT[],                               -- Services that can access
    allowed_roles     TEXT[],                               -- Roles that can access
    requires_approval BOOLEAN DEFAULT false,                -- Need approval for access

    -- Usage tracking
    last_accessed_at  TIMESTAMP WITH TIME ZONE,
    last_accessed_by  UUID,
    access_count      BIGINT DEFAULT 0,

    -- Compromise detection
    compromise_detected BOOLEAN DEFAULT false,
    compromise_detected_at TIMESTAMP WITH TIME ZONE,
    compromise_reason  TEXT,
    auto_rotate_on_compromise BOOLEAN DEFAULT true,

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_secret_key UNIQUE (secret_key, environment, region),
    CONSTRAINT uq_secret_name UNIQUE (secret_name, environment),
    CONSTRAINT chk_secret_expiry CHECK (expires_at IS NULL OR expires_at > created_at),
    CONSTRAINT fk_secrets_prev_version FOREIGN KEY (previous_version_id)
        REFERENCES public.secrets_manager(secret_id) ON DELETE SET NULL,
    CONSTRAINT fk_secrets_encryption_key FOREIGN KEY (encryption_key_id)
        REFERENCES public.encryption_keys(key_id) ON DELETE RESTRICT,
    CONSTRAINT fk_secrets_rotated_by FOREIGN KEY (rotated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_secrets_last_accessed_by FOREIGN KEY (last_accessed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for secrets_manager table
COMMENT ON TABLE public.secrets_manager IS 'Centralized encrypted storage for all application secrets with full audit';
COMMENT ON COLUMN public.secrets_manager.secret_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.secrets_manager.secret_key IS 'Unique key for the secret (hierarchical format)';
COMMENT ON COLUMN public.secrets_manager.secret_name IS 'Human-readable name for the secret';
COMMENT ON COLUMN public.secrets_manager.description IS 'Detailed description of secret purpose';
COMMENT ON COLUMN public.secrets_manager.secret_value IS 'Encrypted secret value (binary)';
COMMENT ON COLUMN public.secrets_manager.secret_hash IS 'Hash of secret for integrity verification';
COMMENT ON COLUMN public.secrets_manager.encryption_key_id IS 'ID of key used to encrypt this secret';
COMMENT ON COLUMN public.secrets_manager.secret_type IS 'Type of secret for validation';
COMMENT ON COLUMN public.secrets_manager.version IS 'Version number for rotation';
COMMENT ON COLUMN public.secrets_manager.previous_version_id IS 'Previous version (for rollback)';
COMMENT ON COLUMN public.secrets_manager.environment IS 'Environment where secret is used';
COMMENT ON COLUMN public.secrets_manager.service_name IS 'Service that uses this secret';
COMMENT ON COLUMN public.secrets_manager.region IS 'Geographic region (for multi-region)';
COMMENT ON COLUMN public.secrets_manager.component IS 'Specific component within service';
COMMENT ON COLUMN public.secrets_manager.rotation_policy IS 'How often secret should be rotated';
COMMENT ON COLUMN public.secrets_manager.rotation_schedule IS 'Cron expression for auto-rotation';
COMMENT ON COLUMN public.secrets_manager.last_rotated_at IS 'When secret was last rotated';
COMMENT ON COLUMN public.secrets_manager.next_rotation_at IS 'When secret should next be rotated';
COMMENT ON COLUMN public.secrets_manager.rotated_by IS 'Who performed last rotation';
COMMENT ON COLUMN public.secrets_manager.expires_at IS 'When secret expires (if applicable)';
COMMENT ON COLUMN public.secrets_manager.expiry_warning_sent IS 'Whether expiry warning was sent';
COMMENT ON COLUMN public.secrets_manager.allowed_services IS 'Services permitted to access';
COMMENT ON COLUMN public.secrets_manager.allowed_roles IS 'Roles permitted to access';
COMMENT ON COLUMN public.secrets_manager.requires_approval IS 'Whether access requires approval';
COMMENT ON COLUMN public.secrets_manager.last_accessed_at IS 'When secret was last accessed';
COMMENT ON COLUMN public.secrets_manager.last_accessed_by IS 'Who last accessed the secret';
COMMENT ON COLUMN public.secrets_manager.access_count IS 'Number of times secret was accessed';
COMMENT ON COLUMN public.secrets_manager.compromise_detected IS 'Whether compromise was detected';
COMMENT ON COLUMN public.secrets_manager.compromise_detected_at IS 'When compromise was detected';
