    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'security_admin')
    ));

-- =============================================================================
-- TABLE: 6 - encryption_keys
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 6
-- Table Name: encryption_keys
-- Description: Manages the encryption key hierarchy including master keys,
--              data encryption keys, and key encryption keys with full
--              lifecycle management and rotation policies.
--
-- Business Case: Enterprise-grade encryption requires a robust key management
--                system that follows industry best practices and compliance
--                requirements (PCI DSS, HIPAA, GDPR). This table implements a
--                hierarchical key management system where:
--                1) Master keys protect lower-level keys,
--                2) Data encryption keys (DEKs) protect actual data,
--                3) Key encryption keys (KEKs) protect DEKs,
--                4) Keys can be rotated without re-encrypting all data,
--                5) Compromised keys can be quickly revoked.
--                The system supports multiple encryption algorithms and key
--                strengths to maintain algorithm agility. Each key has a
--                defined purpose and usage restrictions to implement the
--                principle of least privilege. Keys can be marked as
--                "ACTIVE_READONLY" during rotation so existing data can be
--                decrypted while new data uses the new key. The table also
--                tracks key usage metadata for compliance reporting and
--                supports key escrow for disaster recovery. Integration with
--                Hardware Security Modules (HSMs) can be achieved by storing
--                only key references rather than the actual key material.
--
-- KPIs:
--   1. Number of active encryption keys (by type)
--   2. Key rotation compliance (percentage rotated within policy)
--   3. Time to revoke compromised key < 1 minute
--   4. Zero plaintext keys in logs or backups
--   5. Key usage audit coverage = 100%
--   6. Key generation latency < 100ms
--   7. Decryption success rate > 99.99%
--   8. Number of keys approaching expiry
--
-- Feature Reference: ENC-01 (Key Management)
--                  : ENC-02 (Key Hierarchy)
--                  : ENC-03 (Key Rotation)
--                  : ENC-04 (Key Usage Audit)
--                  : ENC-05 (HSM Integration)
-- -----------------------------------------------------------------------------
CREATE TABLE public.encryption_keys (
    -- Primary key
    key_id            UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Key identification
    key_name          VARCHAR(255) NOT NULL,
    key_description   TEXT,
    key_purpose       public.encryption_key_usage NOT NULL,

    -- Key hierarchy
    parent_key_id     UUID,                               -- Key that encrypts this key (KEK)
    root_key          BOOLEAN DEFAULT false,              -- Whether this is a root/master key

    -- Key material (encrypted by parent key)
    key_material      BYTEA NOT NULL,                      -- Encrypted key material
    key_algorithm     public.encryption_algorithm NOT NULL,
    key_size          INTEGER NOT NULL,                    -- Key size in bits
    key_format        VARCHAR(50) DEFAULT 'RAW' CHECK (key_format IN ('RAW', 'PKCS8', 'JWK')),

    -- Key identifiers (for cloud KMS integration)
    kms_provider      VARCHAR(50),                         -- 'aws_kms', 'azure_keyvault', 'gcp_kms', 'hsm'
    kms_key_id        VARCHAR(255),                        -- ID in external KMS
    external_key      BOOLEAN DEFAULT false,               -- Whether key is stored externally

    -- Key lifecycle
    key_version       INTEGER NOT NULL DEFAULT 1,
    status            public.encryption_key_status NOT NULL DEFAULT 'ACTIVE',
    activated_at      TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deactivated_at    TIMESTAMP WITH TIME ZONE,
    expires_at        TIMESTAMP WITH TIME ZONE,

    -- Rotation
    rotation_due_at   TIMESTAMP WITH TIME ZONE,
    rotated_from_key_id UUID,                              -- Previous version

    -- Usage restrictions
    allowed_operations TEXT[] NOT NULL DEFAULT '{ENCRYPT,DECRYPT}', -- Allowed crypto operations
    max_uses_per_period INTEGER,                            -- Rate limiting
    usage_period_seconds INTEGER,                           -- Period for max_uses

    -- Usage tracking
    times_used        BIGINT DEFAULT 0,
    last_used_at      TIMESTAMP WITH TIME ZONE,
    last_used_for     VARCHAR(100),                         -- Last operation type

    -- Compliance
    compliance_tags   TEXT[],                               -- e.g., {'PCI', 'HIPAA', 'GDPR'}
    fips_compliant    BOOLEAN DEFAULT false,                 -- FIPS 140-2 compliance

    -- Audit
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_key_name UNIQUE (key_name, key_version),
    CONSTRAINT chk_key_expiry CHECK (expires_at IS NULL OR expires_at > activated_at),
    CONSTRAINT chk_key_deactivation CHECK (deactivated_at IS NULL OR deactivated_at >= activated_at),
    CONSTRAINT chk_key_size CHECK (key_size >= 128 AND key_size <= 4096),
    CONSTRAINT fk_keys_parent FOREIGN KEY (parent_key_id)
        REFERENCES public.encryption_keys(key_id) ON DELETE RESTRICT,
    CONSTRAINT fk_keys_rotated_from FOREIGN KEY (rotated_from_key_id)
        REFERENCES public.encryption_keys(key_id) ON DELETE SET NULL
);

-- Comments for encryption_keys table
COMMENT ON TABLE public.encryption_keys IS 'Hierarchical encryption key management with full lifecycle tracking';
COMMENT ON COLUMN public.encryption_keys.key_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.encryption_keys.key_name IS 'Unique name for the key (e.g., master-key-2024)';
COMMENT ON COLUMN public.encryption_keys.key_description IS 'Description of key purpose';
COMMENT ON COLUMN public.encryption_keys.key_purpose IS 'Allowed usage for this key';
COMMENT ON COLUMN public.encryption_keys.parent_key_id IS 'Parent key that encrypts this key (KEK)';
COMMENT ON COLUMN public.encryption_keys.root_key IS 'Whether this is a root/master key (no parent)';
COMMENT ON COLUMN public.encryption_keys.key_material IS 'Encrypted key material';
COMMENT ON COLUMN public.encryption_keys.key_algorithm IS 'Encryption algorithm for this key';
COMMENT ON COLUMN public.encryption_keys.key_size IS 'Key size in bits';
COMMENT ON COLUMN public.encryption_keys.key_format IS 'Format of the key material';
COMMENT ON COLUMN public.encryption_keys.kms_provider IS 'External KMS provider (if applicable)';
COMMENT ON COLUMN public.encryption_keys.kms_key_id IS 'Key ID in external KMS';
COMMENT ON COLUMN public.encryption_keys.external_key IS 'Whether key is stored externally';
COMMENT ON COLUMN public.encryption_keys.key_version IS 'Version number for this key';
COMMENT ON COLUMN public.encryption_keys.status IS 'Current key status';
COMMENT ON COLUMN public.encryption_keys.activated_at IS 'When key became active';
COMMENT ON COLUMN public.encryption_keys.deactivated_at IS 'When key was deactivated';
COMMENT ON COLUMN public.encryption_keys.expires_at IS 'When key expires';
COMMENT ON COLUMN public.encryption_keys.rotation_due_at IS 'When key should be rotated';
COMMENT ON COLUMN public.encryption_keys.rotated_from_key_id IS 'Previous version of this key';
COMMENT ON COLUMN public.encryption_keys.allowed_operations IS 'Allowed cryptographic operations';
COMMENT ON COLUMN public.encryption_keys.max_uses_per_period IS 'Maximum uses in time period';
COMMENT ON COLUMN public.encryption_keys.usage_period_seconds IS 'Time period for max_uses';
COMMENT ON COLUMN public.encryption_keys.times_used IS 'Number of times key has been used';
COMMENT ON COLUMN public.encryption_keys.last_used_at IS 'When key was last used';
COMMENT ON COLUMN public.encryption_keys.last_used_for IS 'Last operation performed';
COMMENT ON COLUMN public.encryption_keys.compliance_tags IS 'Compliance classifications';
COMMENT ON COLUMN public.encryption_keys.fips_compliant IS 'Whether key is FIPS 140-2 compliant';
COMMENT ON COLUMN public.encryption_keys.created_at IS 'Timestamp of key creation';
COMMENT ON COLUMN public.encryption_keys.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.encryption_keys.created_by IS 'User who created the key';
COMMENT ON COLUMN public.encryption_keys.updated_by IS 'User who last updated the key';

-- Indexes for encryption_keys table
CREATE INDEX idx_keys_name ON public.encryption_keys(key_name, key_version);
CREATE INDEX idx_keys_parent ON public.encryption_keys(parent_key_id) WHERE parent_key_id IS NOT NULL;
CREATE INDEX idx_keys_status ON public.encryption_keys(status, key_purpose);
CREATE INDEX idx_keys_expiry ON public.encryption_keys(expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX idx_keys_rotation ON public.encryption_keys(rotation_due_at) WHERE rotation_due_at IS NOT NULL;
CREATE INDEX idx_keys_usage ON public.encryption_keys(last_used_at) WHERE times_used > 0;

-- Partial index for active keys
CREATE INDEX idx_keys_active ON public.encryption_keys(key_id) WHERE status IN ('ACTIVE', 'ACTIVE_READONLY');

-- Trigger for updated_at
CREATE TRIGGER update_encryption_keys_timestamp
    BEFORE UPDATE ON public.encryption_keys
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.encryption_keys ENABLE ROW LEVEL SECURITY;

-- Policy: Key management service can access
CREATE POLICY encryption_keys_service_policy ON public.encryption_keys
    USING (current_user = 'key_management_service');

-- Policy: Security admins can manage keys
CREATE POLICY encryption_keys_admin_policy ON public.encryption_keys
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('security_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 7 - audit_log_archive
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 7
-- Table Name: audit_log_archive
-- Description: Long-term, immutable storage for audit logs with compression,
--              partitioning, and compliance-grade retention policies.
--
-- Business Case: Compliance regulations (SOC2, ISO27001, GDPR, HIPAA, PCI DSS)
--                require retention of audit logs for 1-7 years. The main
--                audit_logs table is optimized for recent data access and
--                would become unmanageably large if all historical data were
--                kept there. This archive table serves as the long-term storage
--                for audit data with the following features:
--                1) Immutable records (no updates or deletes),
--                2) Partitioning by year/month for efficient management,
--                3) Compression to reduce storage costs,
--                4) Encryption at rest for sensitive audit data,
--                5) Tamper-evident checksums to detect unauthorized changes,
--                6) Retention policies with automated purging,
--                7) Export capabilities for legal discovery,
--                8) Integration with SIEM systems for security monitoring.
--                The table supports different retention periods based on
--                audit category (e.g., authentication logs kept longer,
--                debug logs purged sooner). For legal holds, specific records
--                can be preserved beyond normal retention. The archive also
--                includes chain of custody information to prove integrity in
--                legal proceedings. With proper indexing, forensic investigators
--                can efficiently search years of audit data when needed.
--
-- KPIs:
--   1. Audit log retention compliance = 100% (no premature deletion)
--   2. Time to search 1 year of audit data < 1 minute
--   3. Storage cost per GB/month (optimized with compression)
--   4. Number of legal holds active (records preserved)
--   5. Tamper detection alerts (zero false positives)
--   6. Data integrity verification success rate = 100%
--   7. Export time for legal discovery < 24 hours for 5 years of data
--
-- Feature Reference: AUD-01 (Long-term Audit Storage)
--                  : AUD-02 (Audit Retention)
--                  : AUD-03 (Legal Hold)
--                  : AUD-04 (Tamper Detection)
--                  : AUD-05 (SIEM Integration)
-- -----------------------------------------------------------------------------
CREATE TABLE public.audit_log_archive (
    -- Primary key (using composite for partitioning)
    log_id            UUID NOT NULL,
    archive_date      DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Core audit data (mirroring main audit_logs)
    event_time        TIMESTAMP WITH TIME ZONE NOT NULL,
    event_type        VARCHAR(100) NOT NULL,
    event_category    public.audit_category NOT NULL,
    severity          public.audit_severity NOT NULL DEFAULT 'INFO',

    -- Who and what
    user_id           UUID,
    session_id        UUID,
    api_client_id     UUID,

    -- Action details
    action            VARCHAR(255) NOT NULL,
    resource_type     VARCHAR(100),
    resource_id       UUID,
    old_values        JSONB,                            -- For changes
    new_values        JSONB,

    -- Context
    ip_address        INET,
    user_agent        TEXT,
    request_id        UUID,
    trace_id          VARCHAR(100),                       -- Distributed tracing

    -- Security metadata
    authentication_method VARCHAR(50),
    authorization_result VARCHAR(20),
    reason            TEXT,                                -- Why action was taken

    -- Integrity
    checksum          TEXT NOT NULL,                       -- SHA-256 of all fields
    previous_log_hash TEXT,                                 -- Blockchain-style chaining
    digital_signature BYTEA,                                -- Cryptographic signature

    -- Retention
    retention_until   DATE NOT NULL,                        -- When to purge
    legal_hold        BOOLEAN DEFAULT false,
    legal_hold_reason TEXT,
    legal_hold_applied_at TIMESTAMP WITH TIME ZONE,
    legal_hold_applied_by UUID,

    -- Compression metadata
    compressed_size   BIGINT,                               -- Size after compression
    compression_algorithm VARCHAR(20) DEFAULT 'zstd',

    -- Archive metadata
    archived_at       TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    archived_by       UUID,
    archive_batch_id  UUID,                                 -- For batch operations

    -- Storage location
    storage_tier      VARCHAR(50) DEFAULT 'HOT' CHECK (storage_tier IN ('HOT', 'WARM', 'COLD', 'GLACIER')),
    storage_path      TEXT,                                  -- If moved to object storage

    -- Partition key
    PRIMARY KEY (log_id, archive_date)
) PARTITION BY RANGE (archive_date);

-- Comments for audit_log_archive table
COMMENT ON TABLE public.audit_log_archive IS 'Long-term immutable archive for audit logs with compliance-grade retention';
COMMENT ON COLUMN public.audit_log_archive.log_id IS 'Original log ID from source system';
COMMENT ON COLUMN public.audit_log_archive.archive_date IS 'Date when log was archived (partition key)';
COMMENT ON COLUMN public.audit_log_archive.event_time IS 'When the audited event occurred';
COMMENT ON COLUMN public.audit_log_archive.event_type IS 'Type of audited event';
COMMENT ON COLUMN public.audit_log_archive.event_category IS 'Category of audit event';
COMMENT ON COLUMN public.audit_log_archive.severity IS 'Severity level of event';
COMMENT ON COLUMN public.audit_log_archive.user_id IS 'User who performed the action';
COMMENT ON COLUMN public.audit_log_archive.session_id IS 'Session during which action occurred';
COMMENT ON COLUMN public.audit_log_archive.api_client_id IS 'API client used (if applicable)';
COMMENT ON COLUMN public.audit_log_archive.action IS 'Action performed';
COMMENT ON COLUMN public.audit_log_archive.resource_type IS 'Type of resource affected';
COMMENT ON COLUMN public.audit_log_archive.resource_id IS 'ID of resource affected';
COMMENT ON COLUMN public.audit_log_archive.old_values IS 'Previous state (for modifications)';
COMMENT ON COLUMN public.audit_log_archive.new_values IS 'New state (for modifications)';
COMMENT ON COLUMN public.audit_log_archive.ip_address IS 'IP address of client';
COMMENT ON COLUMN public.audit_log_archive.user_agent IS 'User agent of client';
COMMENT ON COLUMN public.audit_log_archive.request_id IS 'Request identifier for correlation';
COMMENT ON COLUMN public.audit_log_archive.trace_id IS 'Distributed tracing ID';
COMMENT ON COLUMN public.audit_log_archive.authentication_method IS 'How user was authenticated';
COMMENT ON COLUMN public.audit_log_archive.authorization_result IS 'Result of authorization check';
COMMENT ON COLUMN public.audit_log_archive.reason IS 'Reason for action/decision';
COMMENT ON COLUMN public.audit_log_archive.checksum IS 'SHA-256 checksum for integrity';
COMMENT ON COLUMN public.audit_log_archive.previous_log_hash IS 'Hash of previous log (for chain)';
COMMENT ON COLUMN public.audit_log_archive.digital_signature IS 'Cryptographic signature';
COMMENT ON COLUMN public.audit_log_archive.retention_until IS 'When log can be purged';
COMMENT ON COLUMN public.audit_log_archive.legal_hold IS 'Whether on legal hold';
COMMENT ON COLUMN public.audit_log_archive.legal_hold_reason IS 'Why legal hold applied';
COMMENT ON COLUMN public.audit_log_archive.legal_hold_applied_at IS 'When legal hold was applied';
COMMENT ON COLUMN public.audit_log_archive.legal_hold_applied_by IS 'Who applied legal hold';
COMMENT ON COLUMN public.audit_log_archive.compressed_size IS 'Size after compression';
COMMENT ON COLUMN public.audit_log_archive.compression_algorithm IS 'Algorithm used for compression';
COMMENT ON COLUMN public.audit_log_archive.archived_at IS 'When log was archived';
COMMENT ON COLUMN public.audit_log_archive.archived_by IS 'Who archived the log';
COMMENT ON COLUMN public.audit_log_archive.archive_batch_id IS 'Batch identifier for bulk archiving';
COMMENT ON COLUMN public.audit_log_archive.storage_tier IS 'Storage tier for cost optimization';
COMMENT ON COLUMN public.audit_log_archive.storage_path IS 'Path if moved to external storage';

-- Create partitions for audit_log_archive
-- Function to create monthly partitions
CREATE OR REPLACE FUNCTION public.create_audit_archive_partition(
    p_year INTEGER,
    p_month INTEGER
) RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date DATE;
    end_date DATE;
BEGIN
    partition_name := 'audit_log_archive_' || p_year || '_' || LPAD(p_month::TEXT, 2, '0');
    start_date := MAKE_DATE(p_year, p_month, 1);

    IF p_month = 12 THEN
        end_date := MAKE_DATE(p_year + 1, 1, 1);
    ELSE
        end_date := MAKE_DATE(p_year, p_month + 1, 1);
    END IF;

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.audit_log_archive
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create indexes on the partition
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_event_time ON public.%I(event_time)',
        partition_name, partition_name
    );

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_user_id ON public.%I(user_id)',
        partition_name, partition_name
    );

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_resource ON public.%I(resource_type, resource_id)',
        partition_name, partition_name
    );
END;
$$ LANGUAGE plpgsql;

