CREATE INDEX idx_audit_archive_new_values ON public.audit_log_archive USING gin(new_values);

-- Trigger to automatically set checksum on insert
CREATE OR REPLACE FUNCTION public.calculate_audit_archive_checksum()
RETURNS TRIGGER AS $$
DECLARE
    hash_input TEXT;
BEGIN
    -- Build input string for hash
    hash_input := COALESCE(NEW.log_id::TEXT, '') ||
                  COALESCE(NEW.event_time::TEXT, '') ||
                  COALESCE(NEW.event_type, '') ||
                  COALESCE(NEW.user_id::TEXT, '') ||
                  COALESCE(NEW.action, '') ||
                  COALESCE(NEW.resource_type, '') ||
                  COALESCE(NEW.resource_id::TEXT, '') ||
                  COALESCE(NEW.old_values::TEXT, '') ||
                  COALESCE(NEW.new_values::TEXT, '') ||
                  COALESCE(NEW.ip_address::TEXT, '') ||
                  COALESCE(NEW.request_id::TEXT, '');

    -- Set checksum
    NEW.checksum := encode(sha256(hash_input::BYTEA), 'hex');

    -- Set previous_log_hash from last record (simplified - would need last record lookup)
    -- In production, you'd look up the last log's hash

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER set_audit_archive_checksum
    BEFORE INSERT ON public.audit_log_archive
    FOR EACH ROW EXECUTE FUNCTION public.calculate_audit_archive_checksum();

-- Enable RLS
ALTER TABLE public.audit_log_archive ENABLE ROW LEVEL SECURITY;

-- Policy: Security team can view all logs
CREATE POLICY audit_archive_security_policy ON public.audit_log_archive
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('security_admin', 'auditor', 'admin')
    ));

-- Policy: Legal team can view logs on legal hold
CREATE POLICY audit_archive_legal_policy ON public.audit_log_archive
    FOR SELECT USING (
        legal_hold = true AND
        EXISTS (
            SELECT 1 FROM public.user_roles ur
            JOIN public.roles r ON ur.role_id = r.role_id
            WHERE ur.user_id = current_user_id() AND r.name IN ('legal', 'admin')
        )
    );

-- =============================================================================
-- TABLE: 8 - data_classification
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 8
-- Table Name: data_classification
-- Description: Catalog of all sensitive data elements with classification
--              levels, protection requirements, and compliance mappings.
--
-- Business Case: With increasing regulatory requirements (GDPR, CCPA, HIPAA,
--                PCI DSS), organizations must know exactly what sensitive data
--                they hold and how to protect it. This table serves as the
--                authoritative inventory of all data elements that require
--                special handling. It maps database columns, API fields, and
--                file types to sensitivity classifications, enabling:
--                1) Automated data protection (encryption, masking, redaction),
--                2) Data Loss Prevention (DLP) policy enforcement,
--                3) Privacy impact assessments,
--                4) Breach notification scope determination,
--                5) Data minimization and retention decisions,
--                6) Consent management integration,
--                7) Third-party data sharing compliance.
--                The classification system supports multiple frameworks
--                simultaneously (e.g., a field can be both PII and PCI).
--                It also tracks data lineage - where data originates, how it
--                transforms, and where it's stored. For each classified
--                element, the table specifies protection requirements:
--                encryption algorithms, access controls, audit logging levels,
--                and retention periods. This enables automated policy
--                enforcement throughout the data lifecycle. The table also
--                supports impact assessments by linking to business processes
--                and legal bases for processing.
--
-- KPIs:
--   1. Classification coverage (percentage of data elements classified) > 95%
--   2. Time to classify new data elements < 24 hours
--   3. Protection policy compliance rate > 99.9%
--   4. Number of data elements with incomplete protection requirements
--   5. Audit findings related to misclassification = 0
--   6. Time to identify all PII for a user < 1 minute
--   7. Classification accuracy (verified by audits) > 99%
--
-- Feature Reference: CLASS-01 (Data Classification)
--                  : CLASS-02 (Sensitive Data Inventory)
--                  : CLASS-03 (Protection Requirements)
--                  : CLASS-04 (Compliance Mapping)
--                  : CLASS-05 (Data Lineage)
-- -----------------------------------------------------------------------------
CREATE TABLE public.data_classification (
    -- Primary key
    classification_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Data element identification
    data_domain       VARCHAR(100) NOT NULL,            -- e.g., 'user', 'payment', 'health'
    data_category     public.data_category NOT NULL,
    data_element      VARCHAR(255) NOT NULL,             -- e.g., 'email', 'credit_card'
    data_description  TEXT,

    -- Location information (where this data lives)
    database_name     VARCHAR(100),
    schema_name       VARCHAR(100),
    table_name        VARCHAR(100),
    column_name       VARCHAR(100),
    api_endpoint      VARCHAR(255),                       -- If exposed via API
    api_field         VARCHAR(255),                        -- Field name in API
    file_type         VARCHAR(50),                         -- For file-based data

    -- Sensitivity classification
    sensitivity_level public.data_sensitivity_level NOT NULL,
    sensitivity_score INTEGER CHECK (sensitivity_score BETWEEN 1 AND 10), -- 10 = most sensitive

    -- Compliance frameworks
    gdpr_relevant     BOOLEAN DEFAULT false,
    gdpr_category     VARCHAR(50) CHECK (gdpr_category IN ('IDENTIFICATION', 'FINANCIAL', 'HEALTH', 'BIOMETRIC', 'GENETIC', 'POLITICAL', 'RELIGIOUS', 'TRADE_UNION')),
    ccpa_relevant      BOOLEAN DEFAULT false,
    pci_relevant       BOOLEAN DEFAULT false,
    pci_category       VARCHAR(20) CHECK (pci_category IN ('CHD', 'SAD', 'PAN')),
    hipaa_relevant     BOOLEAN DEFAULT false,
    hipaa_category     VARCHAR(20) CHECK (hipaa_category IN ('PHI', 'CE', 'BA')),
    sox_relevant       BOOLEAN DEFAULT false,

    -- Protection requirements
    requires_encryption_at_rest BOOLEAN DEFAULT true,
    encryption_algorithm VARCHAR(50),                      -- Which algorithm to use
    requires_encryption_in_transit BOOLEAN DEFAULT true,
    requires_masking    BOOLEAN DEFAULT false,
    masking_pattern     VARCHAR(100),                       -- e.g., '***-***-1234'
    requires_redaction  BOOLEAN DEFAULT false,              -- For logs
    requires_anonymization BOOLEAN DEFAULT false,           -- For analytics
    anonymization_method VARCHAR(50),                        -- e.g., 'hash', 'tokenize', 'generalize'

    -- Access controls
    minimum_access_role VARCHAR(100),                        -- Minimum role required
    requires_justification BOOLEAN DEFAULT false,            -- Need business reason
    requires_approval   BOOLEAN DEFAULT false,               -- Need manager approval
    access_audit_level  VARCHAR(20) DEFAULT 'STANDARD' CHECK (access_audit_level IN ('NONE', 'STANDARD', 'DETAILED', 'ALWAYS')),

    -- Retention
    retention_period_days INTEGER,                           -- How long to keep
    retention_policy_id UUID,                                 -- Reference to retention policy
    requires_purging    BOOLEAN DEFAULT true,                 -- Must be deleted after retention

    -- Data lineage
    data_source         VARCHAR(255),                          -- Where data comes from
    data_sink           VARCHAR(255),                          -- Where data goes to
    transformation_log  JSONB,                                 -- How data is transformed

    -- Business context
    business_process    VARCHAR(255),                          -- Which process uses this
    legal_basis         VARCHAR(50),                            -- For GDPR: consent, contract, etc.
    data_controller     VARCHAR(255),                           -- Who controls this data
    data_processor      VARCHAR(255),                           -- Who processes this data

    -- Third-party sharing
    shared_with_third_parties BOOLEAN DEFAULT false,
    third_parties       TEXT[],                                 -- List of third parties
    sharing_countries   TEXT[],                                 -- Countries shared to

    -- Data quality
    data_quality_requirement VARCHAR(50),                       -- e.g., 'HIGH', 'MEDIUM', 'LOW'
    validation_rules    JSONB,                                  -- Validation requirements

    -- Audit and metadata
    created_at          TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at          TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by          UUID NOT NULL,
    updated_by          UUID NOT NULL,
    deprecated_at       TIMESTAMP WITH TIME ZONE,
    deprecated_by       UUID,
    deprecation_reason  TEXT,

    -- Constraints
    CONSTRAINT uq_data_classification UNIQUE (data_domain, data_category, data_element, table_name, column_name),
    CONSTRAINT chk_classification_location CHECK (
        (database_name IS NOT NULL AND schema_name IS NOT NULL AND table_name IS NOT NULL AND column_name IS NOT NULL) OR
        (api_endpoint IS NOT NULL AND api_field IS NOT NULL) OR
        (file_type IS NOT NULL)
    )
);

-- Comments for data_classification table
COMMENT ON TABLE public.data_classification IS 'Inventory and classification of all sensitive data elements';
COMMENT ON COLUMN public.data_classification.classification_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.data_classification.data_domain IS 'Business domain of the data (e.g., user, payment)';
COMMENT ON COLUMN public.data_classification.data_category IS 'Category of data';
COMMENT ON COLUMN public.data_classification.data_element IS 'Specific data element name';
COMMENT ON COLUMN public.data_classification.data_description IS 'Description of what this data represents';
COMMENT ON COLUMN public.data_classification.database_name IS 'Database where data resides';
COMMENT ON COLUMN public.data_classification.schema_name IS 'Schema name';
COMMENT ON COLUMN public.data_classification.table_name IS 'Table name';
COMMENT ON COLUMN public.data_classification.column_name IS 'Column name';
COMMENT ON COLUMN public.data_classification.api_endpoint IS 'API endpoint exposing this data';
COMMENT ON COLUMN public.data_classification.api_field IS 'API field name';
COMMENT ON COLUMN public.data_classification.file_type IS 'File type for file-based data';
COMMENT ON COLUMN public.data_classification.sensitivity_level IS 'Sensitivity classification level';
COMMENT ON COLUMN public.data_classification.sensitivity_score IS 'Numerical sensitivity score (1-10)';
COMMENT ON COLUMN public.data_classification.gdpr_relevant IS 'Whether data is relevant to GDPR';
COMMENT ON COLUMN public.data_classification.gdpr_category IS 'GDPR special category if applicable';
COMMENT ON COLUMN public.data_classification.ccpa_relevant IS 'Whether data is relevant to CCPA';
COMMENT ON COLUMN public.data_classification.pci_relevant IS 'Whether data is PCI DSS relevant';
COMMENT ON COLUMN public.data_classification.pci_category IS 'PCI data category';
COMMENT ON COLUMN public.data_classification.hipaa_relevant IS 'Whether data is HIPAA relevant';
COMMENT ON COLUMN public.data_classification.hipaa_category IS 'HIPAA data category';
COMMENT ON COLUMN public.data_classification.sox_relevant IS 'Whether data is SOX relevant';
COMMENT ON COLUMN public.data_classification.requires_encryption_at_rest IS 'Whether data must be encrypted at rest';
COMMENT ON COLUMN public.data_classification.encryption_algorithm IS 'Encryption algorithm to use';
COMMENT ON COLUMN public.data_classification.requires_encryption_in_transit IS 'Whether data must be encrypted in transit';
COMMENT ON COLUMN public.data_classification.requires_masking IS 'Whether data should be masked';
COMMENT ON COLUMN public.data_classification.masking_pattern IS 'Pattern for masking (e.g., ***-***-1234)';
COMMENT ON COLUMN public.data_classification.requires_redaction IS 'Whether data should be redacted from logs';
COMMENT ON COLUMN public.data_classification.requires_anonymization IS 'Whether data needs anonymization for analytics';
COMMENT ON COLUMN public.data_classification.anonymization_method IS 'Method for anonymization';
COMMENT ON COLUMN public.data_classification.minimum_access_role IS 'Minimum role required to access';
COMMENT ON COLUMN public.data_classification.requires_justification IS 'Whether access requires business justification';
COMMENT ON COLUMN public.data_classification.requires_approval IS 'Whether access requires approval';
COMMENT ON COLUMN public.data_classification.access_audit_level IS 'Level of audit logging for access';
COMMENT ON COLUMN public.data_classification.retention_period_days IS 'Retention period in days';
COMMENT ON COLUMN public.data_classification.retention_policy_id IS 'Reference to retention policy';
COMMENT ON COLUMN public.data_classification.requires_purging IS 'Whether data must be purged after retention';
COMMENT ON COLUMN public.data_classification.data_source IS 'Source system of data';
COMMENT ON COLUMN public.data_classification.data_sink IS 'Destination system of data';
COMMENT ON COLUMN public.data_classification.transformation_log IS 'Log of data transformations';
COMMENT ON COLUMN public.data_classification.business_process IS 'Business process using this data';
COMMENT ON COLUMN public.data_classification.legal_basis IS 'Legal basis for processing';
COMMENT ON COLUMN public.data_classification.data_controller IS 'Data controller entity';
COMMENT ON COLUMN public.data_classification.data_processor IS 'Data processor entity';
COMMENT ON COLUMN public.data_classification.shared_with_third_parties IS 'Whether shared with third parties';
COMMENT ON COLUMN public.data_classification.third_parties IS 'List of third parties';
COMMENT ON COLUMN public.data_classification.sharing_countries IS 'Countries data is shared with';
COMMENT ON COLUMN public.data_classification.data_quality_requirement IS 'Required data quality level';
COMMENT ON COLUMN public.data_classification.validation_rules IS 'Validation rules for this data';
COMMENT ON COLUMN public.data_classification.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.data_classification.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.data_classification.created_by IS 'User who created the record';
COMMENT ON COLUMN public.data_classification.updated_by IS 'User who last updated the record';
COMMENT ON COLUMN public.data_classification.deprecated_at IS 'When this classification was deprecated';
COMMENT ON COLUMN public.data_classification.deprecated_by IS 'Who deprecated this classification';
COMMENT ON COLUMN public.data_classification.deprecation_reason IS 'Why classification was deprecated';

-- Indexes for data_classification table
CREATE INDEX idx_classification_location ON public.data_classification(database_name, schema_name, table_name, column_name)
    WHERE database_name IS NOT NULL;
CREATE INDEX idx_classification_api ON public.data_classification(api_endpoint, api_field)
    WHERE api_endpoint IS NOT NULL;
CREATE INDEX idx_classification_sensitivity ON public.data_classification(sensitivity_level, sensitivity_score);
CREATE INDEX idx_classification_compliance ON public.data_classification(gdpr_relevant, ccpa_relevant, pci_relevant, hipaa_relevant);
CREATE INDEX idx_classification_domain ON public.data_classification(data_domain, data_category);

-- Partial index for active classifications
CREATE INDEX idx_classification_active ON public.data_classification(classification_id)
    WHERE deprecated_at IS NULL;

-- GIN index for JSONB transformation log
CREATE INDEX idx_classification_transformations ON public.data_classification USING gin(transformation_log);

-- Trigger for updated_at
CREATE TRIGGER update_data_classification_timestamp
    BEFORE UPDATE ON public.data_classification
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.data_classification ENABLE ROW LEVEL SECURITY;

-- Policy: Data stewards and compliance team can manage classifications
CREATE POLICY data_classification_steward_policy ON public.data_classification
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('data_steward', 'compliance_officer', 'admin')
    ));

-- Policy: Read-only for other roles (for integration)
CREATE POLICY data_classification_readonly_policy ON public.data_classification
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
    ));

-- =============================================================================
-- FUNCTION: update_timestamp()
-- =============================================================================
CREATE OR REPLACE FUNCTION public.update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.update_timestamp() IS 'Automatically updates the updated_at timestamp column on any table';

-- =============================================================================
-- FUNCTION: current_user_id()
-- =============================================================================
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS UUID AS $$
DECLARE
    user_id UUID;
BEGIN
    -- Get user_id from session variable
    BEGIN
        user_id := current_setting('app.current_user_id')::UUID;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN NULL;
    END;
    RETURN user_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.current_user_id() IS 'Returns the UUID of the currently authenticated user from session settings';

