-- Indexes for invoices table
CREATE INDEX idx_invoices_user_id ON public.invoices(user_id, invoice_status);
CREATE INDEX idx_invoices_company_id ON public.invoices(company_id) WHERE company_id IS NOT NULL;
CREATE INDEX idx_invoices_subscription_id ON public.invoices(subscription_id) WHERE subscription_id IS NOT NULL;
CREATE INDEX idx_invoices_status ON public.invoices(invoice_status, due_date);
CREATE INDEX idx_invoices_issue_date ON public.invoices(issue_date DESC);
CREATE INDEX idx_invoices_due_date ON public.invoices(due_date) WHERE invoice_status NOT IN ('PAID', 'VOID', 'ARCHIVED');
CREATE INDEX idx_invoices_number ON public.invoices(invoice_number);
CREATE INDEX idx_invoices_po_number ON public.invoices(po_number) WHERE po_number IS NOT NULL;
CREATE INDEX idx_invoices_reconciliation ON public.invoices(reconciliation_status) WHERE reconciliation_status != 'RECONCILED';

-- Partial index for overdue invoices
CREATE INDEX idx_invoices_overdue ON public.invoices(invoice_id)
    WHERE invoice_status IN ('SENT', 'PARTIALLY_PAID') AND due_date < CURRENT_DATE;

-- GiST index for JSONB tax_breakdown
CREATE INDEX idx_invoices_tax_breakdown ON public.invoices USING gin(tax_breakdown);

-- Trigger for updated_at
CREATE TRIGGER update_invoices_timestamp
    BEFORE UPDATE ON public.invoices
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update paid_date when fully paid
CREATE OR REPLACE FUNCTION public.update_invoice_paid_date()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.amount_paid >= NEW.grand_total AND OLD.amount_paid < NEW.grand_total THEN
        NEW.paid_date := CURRENT_DATE;
        NEW.invoice_status := 'PAID';
    ELSIF NEW.amount_paid < NEW.grand_total AND OLD.amount_paid >= NEW.grand_total THEN
        NEW.paid_date := NULL;
        NEW.invoice_status := 'PARTIALLY_PAID';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER set_invoice_paid_date
    BEFORE UPDATE OF amount_paid ON public.invoices
    FOR EACH ROW EXECUTE FUNCTION public.update_invoice_paid_date();

-- Enable RLS
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view their own invoices
CREATE POLICY invoices_user_policy ON public.invoices
    USING (user_id = current_user_id());

-- Policy: Finance team can manage all invoices
CREATE POLICY invoices_finance_policy ON public.invoices
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 12 - invoice_line_items
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 12 (Subsidiary to invoices)
-- Table Name: invoice_line_items
-- Description: Individual line items on invoices with detailed breakdown of
--              products, services, quantities, and pricing.
--
-- Business Case: For transparency and dispute resolution, invoices must show
--                detailed line items. This table stores each line item with
--                product/service description, quantity, unit price, discounts,
--                and tax amounts. It supports:
--                1) Multiple line items per invoice,
--                2) Detailed product/service descriptions,
--                3) Quantity-based pricing,
--                4) Per-item discounts,
--                5) Tax breakdown by line item,
--                6) Revenue allocation by product,
--                7) COGS tracking,
--                8) Inventory management integration.
--
-- KPIs:
--   1. Average line items per invoice
--   2. Most frequently purchased items
--   3. Discount percentage by product category
--   4. Revenue by product/service
--   5. Tax collected by product type
--
-- Feature Reference: INV-07 (Line Items)
-- -----------------------------------------------------------------------------
CREATE TABLE public.invoice_line_items (
    -- Primary key
    line_item_id      UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Invoice reference
    invoice_id        UUID NOT NULL,

    -- Line item details
    line_number       INTEGER NOT NULL,
    item_type         VARCHAR(50) NOT NULL CHECK (item_type IN ('PRODUCT', 'SERVICE', 'SUBSCRIPTION', 'FEE', 'TAX', 'SHIPPING', 'DISCOUNT', 'ADJUSTMENT')),

    -- Product reference
    product_id        UUID,                                   -- Product/service ID
    sku               VARCHAR(100),                           -- Stock keeping unit
    description       TEXT NOT NULL,

    -- Quantity and pricing
    quantity          NUMERIC(12,3) NOT NULL CHECK (quantity > 0),
    unit_price        NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0),
    discount_percentage NUMERIC(5,2) DEFAULT 0 CHECK (discount_percentage BETWEEN 0 AND 100),
    discount_amount   NUMERIC(12,2) GENERATED ALWAYS AS (
        ROUND((quantity * unit_price * discount_percentage / 100)::NUMERIC, 2)
    ) STORED,

    -- Amounts
    subtotal          NUMERIC(12,2) GENERATED ALWAYS AS (
        ROUND((quantity * unit_price)::NUMERIC, 2)
    ) STORED,
    line_total        NUMERIC(12,2) GENERATED ALWAYS AS (
        ROUND((quantity * unit_price * (1 - discount_percentage / 100))::NUMERIC, 2)
    ) STORED,

    -- Tax
    taxable           BOOLEAN DEFAULT true,
    tax_rate_id       UUID,                                   -- Tax rate applied
    tax_amount        NUMERIC(12,2) DEFAULT 0,
    tax_details       JSONB,                                   -- Detailed tax breakdown

    -- Cost and margin
    cost_price        NUMERIC(12,2),                          -- For margin calculation
    margin_amount     NUMERIC(12,2) GENERATED ALWAYS AS (
        CASE WHEN cost_price IS NOT NULL
        THEN line_total - (quantity * cost_price)
        ELSE NULL END
    ) STORED,

    -- Period (for subscriptions)
    period_start      DATE,                                    -- Service period start
    period_end        DATE,                                    -- Service period end

    -- Metadata
    metadata          JSONB,

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_invoice_line UNIQUE (invoice_id, line_number),
    CONSTRAINT chk_line_period CHECK (period_end IS NULL OR period_end >= period_start),
    CONSTRAINT fk_line_items_invoice FOREIGN KEY (invoice_id)
        REFERENCES public.invoices(invoice_id) ON DELETE CASCADE,
    CONSTRAINT fk_line_items_tax_rate FOREIGN KEY (tax_rate_id)
        REFERENCES public.tax_rates(tax_rate_id) ON DELETE SET NULL
);

-- Comments for invoice_line_items table
COMMENT ON TABLE public.invoice_line_items IS 'Detailed line items for invoices';
COMMENT ON COLUMN public.invoice_line_items.line_item_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.invoice_line_items.invoice_id IS 'Parent invoice';
COMMENT ON COLUMN public.invoice_line_items.line_number IS 'Line number for ordering';
COMMENT ON COLUMN public.invoice_line_items.item_type IS 'Type of line item';
COMMENT ON COLUMN public.invoice_line_items.product_id IS 'Reference to product';
COMMENT ON COLUMN public.invoice_line_items.sku IS 'Stock keeping unit';
COMMENT ON COLUMN public.invoice_line_items.description IS 'Item description';
COMMENT ON COLUMN public.invoice_line_items.quantity IS 'Quantity';
COMMENT ON COLUMN public.invoice_line_items.unit_price IS 'Price per unit';
COMMENT ON COLUMN public.invoice_line_items.discount_percentage IS 'Discount percentage';
COMMENT ON COLUMN public.invoice_line_items.discount_amount IS 'Calculated discount amount';
COMMENT ON COLUMN public.invoice_line_items.subtotal IS 'Subtotal before discount';
COMMENT ON COLUMN public.invoice_line_items.line_total IS 'Line total after discount';
COMMENT ON COLUMN public.invoice_line_items.taxable IS 'Whether item is taxable';
COMMENT ON COLUMN public.invoice_line_items.tax_rate_id IS 'Tax rate applied';
COMMENT ON COLUMN public.invoice_line_items.tax_amount IS 'Tax amount for this line';
COMMENT ON COLUMN public.invoice_line_items.tax_details IS 'Detailed tax breakdown';
COMMENT ON COLUMN public.invoice_line_items.cost_price IS 'Cost price for margin calculation';
COMMENT ON COLUMN public.invoice_line_items.margin_amount IS 'Calculated margin';
COMMENT ON COLUMN public.invoice_line_items.period_start IS 'Service period start';
COMMENT ON COLUMN public.invoice_line_items.period_end IS 'Service period end';
COMMENT ON COLUMN public.invoice_line_items.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.invoice_line_items.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.invoice_line_items.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.invoice_line_items.created_by IS 'User who created the record';
COMMENT ON COLUMN public.invoice_line_items.updated_by IS 'User who last updated the record';

-- Indexes for invoice_line_items table
CREATE INDEX idx_invoice_line_items_invoice_id ON public.invoice_line_items(invoice_id);
CREATE INDEX idx_invoice_line_items_product_id ON public.invoice_line_items(product_id) WHERE product_id IS NOT NULL;
CREATE INDEX idx_invoice_line_items_period ON public.invoice_line_items(period_start, period_end)
    WHERE period_start IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_invoice_line_items_timestamp
    BEFORE UPDATE ON public.invoice_line_items
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS (inherits from invoice through foreign key)
ALTER TABLE public.invoice_line_items ENABLE ROW LEVEL SECURITY;

-- Policy: Users can see their own invoice line items
CREATE POLICY invoice_line_items_user_policy ON public.invoice_line_items
    USING (EXISTS (
        SELECT 1 FROM public.invoices i
        WHERE i.invoice_id = invoice_line_items.invoice_id
        AND i.user_id = current_user_id()
    ));

-- Policy: Finance team can see all
CREATE POLICY invoice_line_items_finance_policy ON public.invoice_line_items
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 13 - subscription_plans
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 13
-- Table Name: subscription_plans
-- Description: Product catalog of subscription plans with features, pricing,
--              and billing rules. Supports multiple tiers, intervals, and
--              grandfathering of legacy plans.
--
-- Business Case: Monetization requires flexible plan definitions that can
--                evolve over time. This table stores the complete product
--                catalog for subscriptions, enabling:
--                1) Multiple pricing tiers (Basic, Pro, Enterprise),
--                2) Various billing intervals (monthly, yearly),
--                3) Feature sets and limitations,
--                4) Free trial periods,
--                5) Setup fees and minimum commitments,
--                6) Plan grandfathering (legacy plans for existing customers),
--                7) Regional pricing variations,
--                8) Promotional pricing periods,
--                9) Usage-based add-ons,
--                10) Plan dependencies (required add-ons).
--                For enterprise sales, it supports:
--                - Custom plans with negotiated pricing,
--                - Volume discounts,
--                - Contract-based pricing,
--                - Multi-year commitments.
--                The table also enables:
--                - A/B testing of pricing,
--                - Plan comparison tools,
--                - Upgrade/downgrade paths,
--                - Revenue forecasting,
--                - Churn analysis by plan.
--
-- KPIs:
--   1. Plan adoption rate (percentage of users per plan)
--   2. Average revenue per user (ARPU) by plan
--   3. Plan churn rate by plan tier
--   4. Upgrade/downgrade conversion rates
--   5. Trial-to-paid conversion rate by plan
--   6. Plan profitability (revenue vs. cost to serve)
--   7. Feature usage by plan tier
--   8. Plan satisfaction score (NPS by plan)
--
-- Feature Reference: PL-01 (Subscription Plans)
--                  : PL-02 (Feature Management)
--                  : PL-03 (Plan Grandfathering)
--                  : PL-04 (Regional Pricing)
--                  : PL-05 (Promotional Pricing)
-- -----------------------------------------------------------------------------
CREATE TABLE public.subscription_plans (
    -- Primary key
    plan_id           UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Plan identification
    plan_name         VARCHAR(255) NOT NULL,
    plan_description  TEXT,
    plan_tagline      VARCHAR(255),                          -- Short marketing tagline
    plan_tier         VARCHAR(50) CHECK (plan_tier IN ('FREE', 'BASIC', 'PRO', 'BUSINESS', 'ENTERPRISE', 'CUSTOM')),

    -- Display and ordering
    display_order     INTEGER DEFAULT 0,
    is_featured       BOOLEAN DEFAULT false,                 -- Featured in marketing
    badge_text        VARCHAR(100),                           -- "Most Popular", "Best Value"

    -- Pricing
    currency          CHAR(3) NOT NULL DEFAULT 'USD',
    price             NUMERIC(12,2) NOT NULL CHECK (price >= 0),
    interval          public.subscription_interval NOT NULL,
    interval_count    INTEGER DEFAULT 1 CHECK (interval_count > 0), -- e.g., 3 for quarterly

    -- Billing configuration
    trial_days        INTEGER DEFAULT 0 CHECK (trial_days >= 0),
    setup_fee         NUMERIC(12,2) DEFAULT 0 CHECK (setup_fee >= 0),
    minimum_quantity  INTEGER DEFAULT 1 CHECK (minimum_quantity >= 1),
    maximum_quantity  INTEGER,                                 -- For per-seat plans
    proration_enabled BOOLEAN DEFAULT true,
    proration_behavior VARCHAR(20) CHECK (proration_behavior IN ('PRORATE', 'CREDIT', 'NONE')),

    -- Feature limits (JSON for flexibility)
    feature_limits    JSONB NOT NULL DEFAULT '{}',            -- e.g., {"users": 5, "storage": 10}
    feature_access    TEXT[],                                  -- List of features included

    -- Usage-based components
    has_metered_billing BOOLEAN DEFAULT false,
    metered_components JSONB,                                  -- Usage-based add-ons

    -- Contract terms
    contract_required BOOLEAN DEFAULT false,
    minimum_term_months INTEGER,                               -- Minimum commitment
    cancellation_fee  NUMERIC(12,2),                          -- Early termination fee

    -- Plan relationships
    parent_plan_id    UUID,                                    -- For plan variations
    upgrade_plan_id   UUID,                                    -- Recommended upgrade path
    downgrade_plan_id UUID,                                    -- Recommended downgrade path

    -- Grandfathering
    deprecated_at     TIMESTAMP WITH TIME ZONE,                -- When plan was deprecated
    deprecation_notice_period INTEGER,                         -- Days notice before deprecation
    grandfathered_plan_id UUID,                                -- Plan for existing customers

    -- Regional availability
    available_countries CHAR(3)[],                             -- NULL = all countries
    excluded_countries   CHAR(3)[],                            -- Countries where not available

    -- Marketing
    marketing_headline VARCHAR(255),
    marketing_bullets TEXT[],                                  -- Bullet points for sales page
    documentation_url  TEXT,                                   -- Link to documentation

    -- Status
    is_active         BOOLEAN DEFAULT true NOT NULL,
    is_public         BOOLEAN DEFAULT true,                    -- Visible in public listing
    is_addon          BOOLEAN DEFAULT false,                   -- Whether this is an add-on

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_plan_name UNIQUE (plan_name),
    CONSTRAINT chk_plan_pricing CHECK (price >= 0),
    CONSTRAINT chk_plan_trial CHECK (trial_days >= 0),
    CONSTRAINT chk_plan_deprecation CHECK (deprecated_at IS NULL OR deprecated_at > created_at),
    CONSTRAINT fk_plans_parent FOREIGN KEY (parent_plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE SET NULL,
    CONSTRAINT fk_plans_upgrade FOREIGN KEY (upgrade_plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE SET NULL,
    CONSTRAINT fk_plans_downgrade FOREIGN KEY (downgrade_plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE SET NULL,
    CONSTRAINT fk_plans_grandfathered FOREIGN KEY (grandfathered_plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE SET NULL
);

-- Comments for subscription_plans table
COMMENT ON TABLE public.subscription_plans IS 'Product catalog of subscription plans with features and pricing';
COMMENT ON COLUMN public.subscription_plans.plan_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.subscription_plans.plan_name IS 'Name of the plan (e.g., "Professional Monthly")';
COMMENT ON COLUMN public.subscription_plans.plan_description IS 'Detailed description of plan';
COMMENT ON COLUMN public.subscription_plans.plan_tagline IS 'Short marketing tagline';
COMMENT ON COLUMN public.subscription_plans.plan_tier IS 'Tier classification';
COMMENT ON COLUMN public.subscription_plans.display_order IS 'Order for display';
COMMENT ON COLUMN public.subscription_plans.is_featured IS 'Whether plan is featured';
COMMENT ON COLUMN public.subscription_plans.badge_text IS 'Badge text (e.g., "Most Popular")';
COMMENT ON COLUMN public.subscription_plans.currency IS 'Currency code';
COMMENT ON COLUMN public.subscription_plans.price IS 'Price per interval';
COMMENT ON COLUMN public.subscription_plans.interval IS 'Billing interval';
COMMENT ON COLUMN public.subscription_plans.interval_count IS 'Number of intervals';
COMMENT ON COLUMN public.subscription_plans.trial_days IS 'Number of trial days';
COMMENT ON COLUMN public.subscription_plans.setup_fee IS 'One-time setup fee';
COMMENT ON COLUMN public.subscription_plans.minimum_quantity IS 'Minimum quantity (for per-seat)';
COMMENT ON COLUMN public.subscription_plans.maximum_quantity IS 'Maximum quantity (for per-seat)';
COMMENT ON COLUMN public.subscription_plans.proration_enabled IS 'Whether proration is enabled';
COMMENT ON COLUMN public.subscription_plans.proration_behavior IS 'Proration behavior';
COMMENT ON COLUMN public.subscription_plans.feature_limits IS 'Feature limits as JSON';
COMMENT ON COLUMN public.subscription_plans.feature_access IS 'List of features included';
COMMENT ON COLUMN public.subscription_plans.has_metered_billing IS 'Whether plan has metered billing';
COMMENT ON COLUMN public.subscription_plans.metered_components IS 'Usage-based components';
COMMENT ON COLUMN public.subscription_plans.contract_required IS 'Whether contract is required';
COMMENT ON COLUMN public.subscription_plans.minimum_term_months IS 'Minimum commitment in months';
COMMENT ON COLUMN public.subscription_plans.cancellation_fee IS 'Early termination fee';
COMMENT ON COLUMN public.subscription_plans.parent_plan_id IS 'Parent plan for variations';
COMMENT ON COLUMN public.subscription_plans.upgrade_plan_id IS 'Recommended upgrade path';
COMMENT ON COLUMN public.subscription_plans.downgrade_plan_id IS 'Recommended downgrade path';
COMMENT ON COLUMN public.subscription_plans.deprecated_at IS 'When plan was deprecated';
COMMENT ON COLUMN public.subscription_plans.deprecation_notice_period IS 'Days notice before deprecation';
COMMENT ON COLUMN public.subscription_plans.grandfathered_plan_id IS 'Plan for existing customers';
COMMENT ON COLUMN public.subscription_plans.available_countries IS 'Countries where plan is available';
COMMENT ON COLUMN public.subscription_plans.excluded_countries IS 'Countries where plan is not available';
COMMENT ON COLUMN public.subscription_plans.marketing_headline IS 'Marketing headline';
COMMENT ON COLUMN public.subscription_plans.marketing_bullets IS 'Marketing bullet points';
COMMENT ON COLUMN public.subscription_plans.documentation_url IS 'URL to documentation';
COMMENT ON COLUMN public.subscription_plans.is_active IS 'Whether plan is active';
COMMENT ON COLUMN public.subscription_plans.is_public IS 'Whether plan is publicly visible';
COMMENT ON COLUMN public.subscription_plans.is_addon IS 'Whether this is an add-on plan';
COMMENT ON COLUMN public.subscription_plans.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.subscription_plans.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.subscription_plans.created_by IS 'User who created the record';
COMMENT ON COLUMN public.subscription_plans.updated_by IS 'User who last updated the record';

-- Indexes for subscription_plans table
CREATE INDEX idx_plans_active ON public.subscription_plans(is_active, display_order) WHERE is_active = true;
CREATE INDEX idx_plans_tier ON public.subscription_plans(plan_tier) WHERE plan_tier IS NOT NULL;
CREATE INDEX idx_plans_currency ON public.subscription_plans(currency);
CREATE INDEX idx_plans_deprecated ON public.subscription_plans(deprecated_at) WHERE deprecated_at IS NOT NULL;
CREATE INDEX idx_plans_grandfathered ON public.subscription_plans(grandfathered_plan_id) WHERE grandfathered_plan_id IS NOT NULL;

-- GiST index for JSONB feature_limits
CREATE INDEX idx_plans_feature_limits ON public.subscription_plans USING gin(feature_limits);

-- Trigger for updated_at
CREATE TRIGGER update_subscription_plans_timestamp
    BEFORE UPDATE ON public.subscription_plans
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.subscription_plans ENABLE ROW LEVEL SECURITY;

-- Policy: Product team can manage plans
CREATE POLICY subscription_plans_product_policy ON public.subscription_plans
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('product_manager', 'admin')
    ));

-- Policy: All authenticated users can view active plans
CREATE POLICY subscription_plans_read_policy ON public.subscription_plans
    FOR SELECT USING (is_active = true AND is_public = true);

-- =============================================================================
-- TABLE: 14 - subscriptions
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 14
-- Table Name: subscriptions
-- Description: Tracks user subscriptions to plans, including start/end dates,
--              status, payment history, and metadata. Enhanced version with
--              comprehensive lifecycle management.
--
-- Business Case: Core to recurring revenue. This table manages the lifecycle
--                of each user's subscription, enabling billing, access control,
--                and churn analysis. Enhanced features include:
--                1) Multiple subscription states (trial, active, past_due),
--                2) Scheduled plan changes (upgrades/downgrades),
--                3) Proration calculations,
--                4) Usage tracking integration,
--                5) Add-on subscriptions,
--                6) Multi-entity subscriptions (team/organization),
--                7) Cancellation surveys and reasons,
--                8) Grace periods for failed payments,
--                9) Reactivation handling,
--                10) Subscription analytics.
--                For enterprise, it supports:
--                - Annual commitments with monthly billing,
--                - Multi-year contracts,
--                - Custom billing cycles,
--                - Usage-based overage billing,
--                - Seat management.
--                The table enables critical business metrics:
--                - Monthly Recurring Revenue (MRR),
--                - Annual Recurring Revenue (ARR),
--                - Customer Lifetime Value (LTV),
--                - Churn rate analysis,
--                - Expansion revenue,
--                - Contraction revenue.
--
-- KPIs:
--   1. Monthly Recurring Revenue (MRR) and growth rate
--   2. Customer churn rate < 2% monthly
--   3. Revenue churn rate < 1% monthly
--   4. Average Revenue Per User (ARPU)
--   5. Customer Lifetime Value (LTV) > 3x Customer Acquisition Cost
--   6. Trial-to-paid conversion rate > 20%
--   7. Upgrade rate (percentage upgrading per quarter)
--   8. Payment recovery rate (failed payment success) > 70%
--
-- Feature Reference: SUB-01 (Subscription Management)
--                  : SUB-02 (MRR Tracking)
--                  : SUB-03 (Churn Analysis)
--                  : SUB-04 (Proration)
--                  : SUB-05 (Usage-based Billing)
--                  : SUB-06 (Team/Org Subscriptions)
-- -----------------------------------------------------------------------------
CREATE TABLE public.subscriptions (
    -- Primary key
    subscription_id   UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Customer
    user_id           UUID NOT NULL,
    company_id        UUID,                                   -- For team/business subscriptions
    subscriber_type   VARCHAR(20) NOT NULL CHECK (subscriber_type IN ('INDIVIDUAL', 'TEAM', 'ENTERPRISE')),

    -- Plan details
    plan_id           UUID NOT NULL,
    plan_snapshot     JSONB,                                   -- Snapshot of plan at subscription time
    quantity          INTEGER DEFAULT 1 CHECK (quantity >= 1), -- For per-seat plans

    -- Status
    status            public.subscription_status NOT NULL DEFAULT 'TRIALING',
    status_reason     TEXT,                                    -- Why status changed
    status_changed_at TIMESTAMP WITH TIME ZONE,

    -- Time boundaries
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    trial_start       TIMESTAMP WITH TIME ZONE,
    trial_end         TIMESTAMP WITH TIME ZONE,
    current_period_start TIMESTAMP WITH TIME ZONE NOT NULL,
    current_period_end   TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Billing
    billing_anchor    DATE,                                    -- Anchor date for billing
    billing_cycle_anchor TIMESTAMP WITH TIME ZONE,             -- When billing cycle starts
    billing_interval  public.subscription_interval NOT NULL,
    billing_interval_count INTEGER DEFAULT 1,

    -- Payment
    payment_method_id UUID,
    payment_provider  public.payment_provider,
    provider_subscription_id VARCHAR(255),                     -- ID from payment provider

    -- Pricing (at subscription time)
    currency          CHAR(3) NOT NULL DEFAULT 'USD',
    unit_price        NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0),
    subtotal          NUMERIC(12,2) GENERATED ALWAYS AS (unit_price * quantity) STORED,
    discount_percentage NUMERIC(5,2) DEFAULT 0,
    discount_amount   NUMERIC(12,2) GENERATED ALWAYS AS (
        ROUND((unit_price * quantity * discount_percentage / 100)::NUMERIC, 2)
    ) STORED,
    total_price       NUMERIC(12,2) GENERATED ALWAYS AS (
        (unit_price * quantity) -
        ROUND((unit_price * quantity * discount_percentage / 100)::NUMERIC, 2)
    ) STORED,

    -- Coupon/Promotion
    coupon_id         UUID,
    coupon_code       VARCHAR(50),

    -- Cancellation
    cancel_at_period_end BOOLEAN DEFAULT false,
    canceled_at       TIMESTAMP WITH TIME ZONE,
    cancellation_reason VARCHAR(100),
    cancellation_feedback TEXT,
    cancellation_survey_id UUID,

    -- Pending changes (scheduled upgrades/downgrades)
    pending_plan_id   UUID,
    pending_quantity  INTEGER,
    pending_effective_date TIMESTAMP WITH TIME ZONE,
    pending_metadata  JSONB,

    -- Usage-based billing
    metered_usage     BOOLEAN DEFAULT false,
    usage_last_reset  TIMESTAMP WITH TIME ZONE,
    usage_alert_threshold INTEGER,                             -- Alert at X% of included usage

    -- Add-ons
    addon_subscriptions UUID[],                                -- Linked add-on subscriptions

    -- Metadata
    metadata          JSONB,
    tags              TEXT[],

    -- Audit
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_subscription_dates CHECK (
        trial_end IS NULL OR trial_end > trial_start AND
        current_period_end > current_period_start
    ),
    CONSTRAINT chk_subscription_cancel CHECK (
        (canceled_at IS NOT NULL AND cancel_at_period_end = true) OR
        (canceled_at IS NULL)
    ),
    CONSTRAINT fk_subscriptions_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscriptions_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT fk_subscriptions_plan FOREIGN KEY (plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscriptions_payment_method FOREIGN KEY (payment_method_id)
        REFERENCES public.payment_methods(payment_method_id) ON DELETE SET NULL,
    CONSTRAINT fk_subscriptions_coupon FOREIGN KEY (coupon_id)
        REFERENCES public.coupons(coupon_id) ON DELETE SET NULL,
    CONSTRAINT fk_subscriptions_pending_plan FOREIGN KEY (pending_plan_id)
        REFERENCES public.subscription_plans(plan_id) ON DELETE SET NULL
);

-- Comments for subscriptions table
COMMENT ON TABLE public.subscriptions IS 'User subscriptions to plans with comprehensive lifecycle management';
COMMENT ON COLUMN public.subscriptions.subscription_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.subscriptions.user_id IS 'Subscribing user';
COMMENT ON COLUMN public.subscriptions.company_id IS 'Subscribing company (if team/business)';
COMMENT ON COLUMN public.subscriptions.subscriber_type IS 'Type of subscriber';
COMMENT ON COLUMN public.subscriptions.plan_id IS 'Current plan';
COMMENT ON COLUMN public.subscriptions.plan_snapshot IS 'Snapshot of plan details at subscription time';
COMMENT ON COLUMN public.subscriptions.quantity IS 'Quantity (for per-seat plans)';
COMMENT ON COLUMN public.subscriptions.status IS 'Current subscription status';
COMMENT ON COLUMN public.subscriptions.status_reason IS 'Reason for current status';
COMMENT ON COLUMN public.subscriptions.status_changed_at IS 'When status last changed';
COMMENT ON COLUMN public.subscriptions.created_at IS 'When subscription was created';
COMMENT ON COLUMN public.subscriptions.updated_at IS 'When subscription was last updated';
COMMENT ON COLUMN public.subscriptions.trial_start IS 'Trial period start';
COMMENT ON COLUMN public.subscriptions.trial_end IS 'Trial period end';
COMMENT ON COLUMN public.subscriptions.current_period_start IS 'Current billing period start';
COMMENT ON COLUMN public.subscriptions.current_period_end IS 'Current billing period end';
COMMENT ON COLUMN public.subscriptions.billing_anchor IS 'Anchor date for billing cycles';
COMMENT ON COLUMN public.subscriptions.billing_cycle_anchor IS 'When billing cycle starts';
COMMENT ON COLUMN public.subscriptions.billing_interval IS 'Billing interval';
COMMENT ON COLUMN public.subscriptions.billing_interval_count IS 'Number of intervals';
COMMENT ON COLUMN public.subscriptions.payment_method_id IS 'Payment method used';
COMMENT ON COLUMN public.subscriptions.payment_provider IS 'Payment provider';
COMMENT ON COLUMN public.subscriptions.provider_subscription_id IS 'Provider subscription ID';
COMMENT ON COLUMN public.subscriptions.currency IS 'Currency code';
COMMENT ON COLUMN public.subscriptions.unit_price IS 'Price per unit';
COMMENT ON COLUMN public.subscriptions.subtotal IS 'Subtotal (price * quantity)';
COMMENT ON COLUMN public.subscriptions.discount_percentage IS 'Discount percentage';
COMMENT ON COLUMN public.subscriptions.discount_amount IS 'Discount amount';
COMMENT ON COLUMN public.subscriptions.total_price IS 'Total price after discount';
COMMENT ON COLUMN public.subscriptions.coupon_id IS 'Applied coupon';
COMMENT ON COLUMN public.subscriptions.coupon_code IS 'Coupon code used';
COMMENT ON COLUMN public.subscriptions.cancel_at_period_end IS 'Whether to cancel at period end';
COMMENT ON COLUMN public.subscriptions.canceled_at IS 'When subscription was canceled';
COMMENT ON COLUMN public.subscriptions.cancellation_reason IS 'Reason for cancellation';
COMMENT ON COLUMN public.subscriptions.cancellation_feedback IS 'Cancellation feedback';
COMMENT ON COLUMN public.subscriptions.cancellation_survey_id IS 'Cancellation survey response';
COMMENT ON COLUMN public.subscriptions.pending_plan_id IS 'Plan to switch to';
COMMENT ON COLUMN public.subscriptions.pending_quantity IS 'Quantity after change';
COMMENT ON COLUMN public.subscriptions.pending_effective_date IS 'When change takes effect';
COMMENT ON COLUMN public.subscriptions.pending_metadata IS 'Metadata for pending change';
COMMENT ON COLUMN public.subscriptions.metered_usage IS 'Whether subscription has metered usage';
COMMENT ON COLUMN public.subscriptions.usage_last_reset IS 'When usage was last reset';
COMMENT ON COLUMN public.subscriptions.usage_alert_threshold IS 'Alert at usage percentage';
COMMENT ON COLUMN public.subscriptions.addon_subscriptions IS 'Linked add-on subscriptions';
COMMENT ON COLUMN public.subscriptions.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.subscriptions.tags IS 'Tags for categorization';
COMMENT ON COLUMN public.subscriptions.created_by IS 'User who created the record';
COMMENT ON COLUMN public.subscriptions.updated_by IS 'User who last updated the record';

-- Indexes for subscriptions table
CREATE INDEX idx_subscriptions_user_id ON public.subscriptions(user_id, status);
CREATE INDEX idx_subscriptions_company_id ON public.subscriptions(company_id) WHERE company_id IS NOT NULL;
CREATE INDEX idx_subscriptions_plan_id ON public.subscriptions(plan_id, status);
CREATE INDEX idx_subscriptions_status ON public.subscriptions(status, current_period_end);
CREATE INDEX idx_subscriptions_provider ON public.subscriptions(payment_provider, provider_subscription_id)
    WHERE provider_subscription_id IS NOT NULL;
CREATE INDEX idx_subscriptions_cancel_at_period ON public.subscriptions(cancel_at_period_end)
    WHERE cancel_at_period_end = true;
CREATE INDEX idx_subscriptions_trial_end ON public.subscriptions(trial_end)
    WHERE status = 'TRIALING';
CREATE INDEX idx_subscriptions_pending ON public.subscriptions(pending_effective_date)
    WHERE pending_plan_id IS NOT NULL;

-- Partial index for active subscriptions
CREATE INDEX idx_subscriptions_active ON public.subscriptions(subscription_id)
    WHERE status IN ('ACTIVE', 'TRIALING', 'PAST_DUE');

-- GiST index for JSONB metadata
CREATE INDEX idx_subscriptions_metadata ON public.subscriptions USING gin(metadata);

-- Trigger for updated_at
CREATE TRIGGER update_subscriptions_timestamp
    BEFORE UPDATE ON public.subscriptions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update status_changed_at
CREATE OR REPLACE FUNCTION public.update_subscription_status_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.status != OLD.status THEN
        NEW.status_changed_at := CURRENT_TIMESTAMP;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER set_subscription_status_changed
    BEFORE UPDATE OF status ON public.subscriptions
    FOR EACH ROW EXECUTE FUNCTION public.update_subscription_status_timestamp();

-- Enable RLS
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view their own subscriptions
CREATE POLICY subscriptions_user_policy ON public.subscriptions
    USING (user_id = current_user_id());

-- Policy: Company admins can view company subscriptions
CREATE POLICY subscriptions_company_policy ON public.subscriptions
    FOR SELECT USING (
        company_id IS NOT NULL AND
        EXISTS (
            SELECT 1 FROM public.company_admins ca
            WHERE ca.company_id = subscriptions.company_id
            AND ca.user_id = current_user_id()
        )
    );

-- Policy: Finance team can manage all subscriptions
CREATE POLICY subscriptions_finance_policy ON public.subscriptions
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 15 - subscription_events
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 15 (Subsidiary to subscriptions)
-- Table Name: subscription_events
-- Description: Audit trail of all subscription state changes for analysis
--              and debugging.
--
-- Business Case: Subscriptions change state frequently (trial → active → canceled).
--                This table records every state change with reasons, enabling:
--                1) Churn analysis,
--                2) Subscription lifecycle tracking,
--                3) Debugging billing issues,
--                4) Compliance and audit,
--                5) Trend analysis of cancellation reasons.
--
-- Feature Reference: SUB-07 (Subscription Audit)
-- -----------------------------------------------------------------------------
CREATE TABLE public.subscription_events (
    event_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    subscription_id   UUID NOT NULL,
    event_type        VARCHAR(50) NOT NULL CHECK (event_type IN (
        'CREATED', 'TRIAL_STARTED', 'TRIAL_ENDED', 'ACTIVATED', 'RENEWED',
        'UPGRADED', 'DOWNGRADED', 'PAYMENT_SUCCEEDED', 'PAYMENT_FAILED',
        'PAST_DUE', 'SUSPENDED', 'CANCELED', 'EXPIRED', 'REACTIVATED'
    )),
    previous_status   public.subscription_status,
    new_status        public.subscription_status NOT NULL,
    event_reason      TEXT,
    event_data        JSONB,                                   -- Additional event data
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID,                                    -- System or user who triggered

    CONSTRAINT fk_subscription_events_subscription FOREIGN KEY (subscription_id)
        REFERENCES public.subscriptions(subscription_id) ON DELETE CASCADE
);

COMMENT ON TABLE public.subscription_events IS 'Audit trail of subscription state changes';
COMMENT ON COLUMN public.subscription_events.event_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.subscription_events.subscription_id IS 'Subscription reference';
COMMENT ON COLUMN public.subscription_events.event_type IS 'Type of event';
COMMENT ON COLUMN public.subscription_events.previous_status IS 'Previous status';
COMMENT ON COLUMN public.subscription_events.new_status IS 'New status';
COMMENT ON COLUMN public.subscription_events.event_reason IS 'Reason for event';
COMMENT ON COLUMN public.subscription_events.event_data IS 'Additional event data';
COMMENT ON COLUMN public.subscription_events.created_at IS 'When event occurred';
COMMENT ON COLUMN public.subscription_events.created_by IS 'Who triggered the event';

CREATE INDEX idx_subscription_events_subscription_id ON public.subscription_events(subscription_id, created_at DESC);
CREATE INDEX idx_subscription_events_type ON public.subscription_events(event_type, created_at DESC);

-- =============================================================================
-- TABLE: 16 - usage_meters
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 16
-- Table Name: usage_meters
-- Description: Tracks consumption of metered resources for usage-based billing,
--              with real-time aggregation and alerting.
--
-- Business Case: Modern SaaS products increasingly use usage-based pricing
--                (API calls, storage, active users). This table records usage
--                events in near real-time and aggregates them for billing. It
--                supports:
--                1) Multiple meter types (incremental, absolute, gauge),
--                2) Real-time aggregation,
--                3) Usage alerts and throttling,
--                4) Integration with subscription billing,
--                5) Historical trending,
--                6) Forecast and capacity planning,
--                7) Anomaly detection.
--                The meter can track various usage patterns:
--                - Cumulative (total API calls),
--                - Peak (max concurrent users),
--                - Rate (requests per second),
--                - Duration (total minutes streamed).
--                For enterprise, it enables:
--                - Custom usage metrics,
--                - Multi-dimensional tracking,
--                - Usage-based discounts,
--                - Commitment tracking.
--
-- KPIs:
--   1. Usage per user/customer (average, distribution)
--   2. Peak usage times and patterns
--   3. Overage revenue percentage
--   4. Usage forecast accuracy
--   5. Metering data latency < 1 second
--   6. Billing accuracy (usage vs. invoiced) = 100%
--
-- Feature Reference: USG-01 (Usage Metering)
--                  : USG-02 (Real-time Aggregation)
--                  : USG-03 (Usage Alerting)
--                  : USG-04 (Usage Forecasting)
-- -----------------------------------------------------------------------------
CREATE TABLE public.usage_meters (
    -- Primary key
    meter_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Customer
    user_id           UUID NOT NULL,
    subscription_id   UUID,                                   -- Linked subscription
    company_id        UUID,                                   -- For team/organization

    -- Meter configuration
    meter_name        VARCHAR(100) NOT NULL,
    meter_type        public.usage_meter_type NOT NULL,
    meter_unit        VARCHAR(50),                             -- e.g., 'calls', 'GB', 'hours'

    -- Meter mode
    aggregation_method VARCHAR(20) NOT NULL CHECK (aggregation_method IN (
        'SUM', 'MAX', 'AVG', 'COUNT', 'LAST', 'RATE'
    )),
    reset_frequency   VARCHAR(20) CHECK (reset_frequency IN (
        'NEVER', 'DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY', 'BILLING_CYCLE'
    )),

    -- Current billing period
    current_period_start TIMESTAMP WITH TIME ZONE NOT NULL,
    current_period_end   TIMESTAMP WITH TIME ZONE NOT NULL,
    current_usage      NUMERIC(15,3) DEFAULT 0 NOT NULL,

    -- Plan limits
    included_quantity  NUMERIC(15,3),                         -- Included in plan
    overage_rate       NUMERIC(12,4),                          -- Price per unit over limit
    overage_currency   CHAR(3),

    -- Alert thresholds
    alert_thresholds   INTEGER[],                               -- Percentages [50,80,90,100]
    alert_sent_at      TIMESTAMP WITH TIME ZONE[],              -- When alerts were sent
    last_alert_level   INTEGER,

    -- Usage tracking
    last_usage_at      TIMESTAMP WITH TIME ZONE,
    peak_usage         NUMERIC(15,3),                           -- Peak recorded
    peak_usage_at      TIMESTAMP WITH TIME ZONE,
    average_usage_rate NUMERIC(15,3),                           -- Rolling average

    -- Metadata
    metadata           JSONB,

    -- Audit columns
    created_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by         UUID NOT NULL,
    updated_by         UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_usage_meter UNIQUE (user_id, meter_name, current_period_start),
    CONSTRAINT chk_usage_period CHECK (current_period_end > current_period_start),
    CONSTRAINT fk_usage_meters_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_usage_meters_subscription FOREIGN KEY (subscription_id)
        REFERENCES public.subscriptions(subscription_id) ON DELETE SET NULL,
    CONSTRAINT fk_usage_meters_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL
);

-- Comments for usage_meters table
COMMENT ON TABLE public.usage_meters IS 'Tracks consumption of metered resources for usage-based billing';
COMMENT ON COLUMN public.usage_meters.meter_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.usage_meters.user_id IS 'User whose usage is tracked';
COMMENT ON COLUMN public.usage_meters.subscription_id IS 'Linked subscription';
COMMENT ON COLUMN public.usage_meters.company_id IS 'Company (if team/organization)';
COMMENT ON COLUMN public.usage_meters.meter_name IS 'Name of the meter';
COMMENT ON COLUMN public.usage_meters.meter_type IS 'Type of usage being metered';
COMMENT ON COLUMN public.usage_meters.meter_unit IS 'Unit of measurement';
COMMENT ON COLUMN public.usage_meters.aggregation_method IS 'How usage is aggregated';
COMMENT ON COLUMN public.usage_meters.reset_frequency IS 'How often usage resets';
COMMENT ON COLUMN public.usage_meters.current_period_start IS 'Current period start';
COMMENT ON COLUMN public.usage_meters.current_period_end IS 'Current period end';
COMMENT ON COLUMN public.usage_meters.current_usage IS 'Usage in current period';
COMMENT ON COLUMN public.usage_meters.included_quantity IS 'Quantity included in plan';
COMMENT ON COLUMN public.usage_meters.overage_rate IS 'Price per unit over limit';
COMMENT ON COLUMN public.usage_meters.overage_currency IS 'Currency for overage';
COMMENT ON COLUMN public.usage_meters.alert_thresholds IS 'Alert at percentages';
COMMENT ON COLUMN public.usage_meters.alert_sent_at IS 'When alerts were sent';
COMMENT ON COLUMN public.usage_meters.last_alert_level IS 'Last alert level sent';
COMMENT ON COLUMN public.usage_meters.last_usage_at IS 'Last usage recorded';
COMMENT ON COLUMN public.usage_meters.peak_usage IS 'Peak usage recorded';
COMMENT ON COLUMN public.usage_meters.peak_usage_at IS 'When peak occurred';
COMMENT ON COLUMN public.usage_meters.average_usage_rate IS 'Rolling average usage';
COMMENT ON COLUMN public.usage_meters.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.usage_meters.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.usage_meters.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.usage_meters.created_by IS 'User who created the record';
COMMENT ON COLUMN public.usage_meters.updated_by IS 'User who last updated the record';

-- Indexes for usage_meters table
CREATE INDEX idx_usage_meters_user_id ON public.usage_meters(user_id, meter_name);
CREATE INDEX idx_usage_meters_subscription_id ON public.usage_meters(subscription_id) WHERE subscription_id IS NOT NULL;
CREATE INDEX idx_usage_meters_period ON public.usage_meters(current_period_end) WHERE current_usage > 0;
CREATE INDEX idx_usage_meters_alert ON public.usage_meters(user_id) WHERE alert_thresholds IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_usage_meters_timestamp
    BEFORE UPDATE ON public.usage_meters
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.usage_meters ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view their own usage
CREATE POLICY usage_meters_user_policy ON public.usage_meters
    USING (user_id = current_user_id());

-- Policy: Finance team can view all
CREATE POLICY usage_meters_finance_policy ON public.usage_meters
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 17 - usage_events
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 17 (Subsidiary to usage_meters)
-- Table Name: usage_events
-- Description: Raw usage events recorded in real-time for metering and analytics.
--
-- Business Case: For accurate usage-based billing, every usage event must be
--                recorded. This table stores raw events as they occur, which
--                are then aggregated into usage_meters. It supports:
--                1) High-volume event ingestion,
--                2) Event deduplication,
--                3) Timestamp accuracy,
--                4) Replay capabilities,
--                5) Debugging and audit.
--
-- Feature Reference: USG-05 (Usage Events)
-- -----------------------------------------------------------------------------
CREATE TABLE public.usage_events (
    event_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id           UUID NOT NULL,
    subscription_id   UUID,
    meter_id          UUID,

    event_type        public.usage_meter_type NOT NULL,
    event_value       NUMERIC(15,3) NOT NULL,
    event_unit        VARCHAR(50),

    event_timestamp   TIMESTAMP WITH TIME ZONE NOT NULL,
    recorded_at       TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Source
    source_ip         INET,
    source_endpoint   VARCHAR(255),
    user_agent        TEXT,

    -- Context
    session_id        UUID,
    request_id        UUID,
    metadata          JSONB,

    -- Deduplication
    idempotency_key   VARCHAR(255) UNIQUE,

    -- Constraints
    CONSTRAINT fk_usage_events_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_usage_events_subscription FOREIGN KEY (subscription_id)
        REFERENCES public.subscriptions(subscription_id) ON DELETE SET NULL,
    CONSTRAINT fk_usage_events_meter FOREIGN KEY (meter_id)
        REFERENCES public.usage_meters(meter_id) ON DELETE SET NULL
) PARTITION BY RANGE (event_timestamp);

COMMENT ON TABLE public.usage_events IS 'Raw usage events for metering and analytics';

-- Comments for usage_events table
COMMENT ON COLUMN public.usage_events.event_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.usage_events.user_id IS 'User generating usage';
COMMENT ON COLUMN public.usage_events.subscription_id IS 'Linked subscription';
COMMENT ON COLUMN public.usage_events.meter_id IS 'Linked meter (after aggregation)';
COMMENT ON COLUMN public.usage_events.event_type IS 'Type of usage event';
COMMENT ON COLUMN public.usage_events.event_value IS 'Usage value';
COMMENT ON COLUMN public.usage_events.event_unit IS 'Unit of measurement';
COMMENT ON COLUMN public.usage_events.event_timestamp IS 'When usage occurred';
COMMENT ON COLUMN public.usage_events.recorded_at IS 'When event was recorded';
COMMENT ON COLUMN public.usage_events.source_ip IS 'Source IP address';
COMMENT ON COLUMN public.usage_events.source_endpoint IS 'API endpoint that generated usage';
COMMENT ON COLUMN public.usage_events.user_agent IS 'Client user agent';
COMMENT ON COLUMN public.usage_events.session_id IS 'Session identifier';
COMMENT ON COLUMN public.usage_events.request_id IS 'Request identifier';
COMMENT ON COLUMN public.usage_events.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.usage_events.idempotency_key IS 'Key for deduplication';

-- Create partitions for usage_events (by month)
CREATE OR REPLACE FUNCTION public.create_usage_events_partition(
    p_year INTEGER,
    p_month INTEGER
) RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'usage_events_' || p_year || '_' || LPAD(p_month::TEXT, 2, '0');
    start_date := MAKE_DATE(p_year, p_month, 1)::TEXT;

    IF p_month = 12 THEN
        end_date := MAKE_DATE(p_year + 1, 1, 1)::TEXT;
    ELSE
        end_date := MAKE_DATE(p_year, p_month + 1, 1)::TEXT;
    END IF;

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.usage_events
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create indexes on the partition
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_user_id ON public.%I(user_id)',
        partition_name, partition_name
    );

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_timestamp ON public.%I(event_timestamp DESC)',
        partition_name, partition_name
    );
END;
$$ LANGUAGE plpgsql;

-- Create current month and next month partitions
SELECT public.create_usage_events_partition(
    EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER,
    EXTRACT(MONTH FROM CURRENT_DATE)::INTEGER
);
SELECT public.create_usage_events_partition(
    EXTRACT(YEAR FROM CURRENT_DATE + INTERVAL '1 month')::INTEGER,
    EXTRACT(MONTH FROM CURRENT_DATE + INTERVAL '1 month')::INTEGER
);

-- Global indexes
CREATE INDEX idx_usage_events_user_id ON public.usage_events(user_id, event_timestamp DESC);
CREATE INDEX idx_usage_events_subscription_id ON public.usage_events(subscription_id, event_timestamp DESC);
CREATE INDEX idx_usage_events_meter_id ON public.usage_events(meter_id, event_timestamp DESC);
CREATE INDEX idx_usage_events_idempotency ON public.usage_events(idempotency_key) WHERE idempotency_key IS NOT NULL;

-- =============================================================================
-- TABLE: 18 - credits_wallet
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 18
-- Table Name: credits_wallet
-- Description: Manages user credit/points balance with full transaction history,
--              supporting virtual currency, refunds, and promotional credits.
--
-- Business Case: Modern platforms use virtual credits for multiple purposes:
--                - Referral program rewards,
--                - Refunds (to avoid payment reversals),
--                - Promotional giveaways,
--                - Loyalty points,
--                - Cashback programs,
--                - Gift cards,
--                - Microtransactions.
--                This table maintains the current balance with complete audit
--                trail of every credit movement. It supports:
--                1) Multiple credit types (promotional, purchased, loyalty),
--                2) Expiration dates for promotional credits,
--                3) Transaction reversal capability,
--                4) Concurrent transaction safety,
--                5) Balance verification (ledger-style),
--                6) Currency conversion,
--                7) Spending rules (what credits can buy),
--                8) Anti-fraud controls.
--                For compliance, it tracks:
--                - Source of credits (why they were granted),
--                - Expiration and forfeiture,
--                - Regulatory reporting (if credits are monetary),
--                - Audit trail for financial reconciliation.
--
-- KPIs:
--   1. Average credits per user
--   2. Credit redemption rate (percentage used)
--   3. Credit expiration rate (percentage expired)
--   4. Credits issued via promotions vs. purchases
--   5. Fraud rate (unauthorized credit usage) < 0.01%
--   6. Customer satisfaction with credit programs
--   7. Revenue impact of credit programs
--
-- Feature Reference: WAL-01 (Credit Wallet)
--                  : WAL-02 (Transaction Audit)
--                  : WAL-03 (Expiration Management)
--                  : WAL-04 (Fraud Prevention)
-- -----------------------------------------------------------------------------
CREATE TABLE public.credits_wallet (
    -- Primary key
    wallet_id         UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Owner
    user_id           UUID NOT NULL UNIQUE,                   -- One wallet per user
    company_id        UUID,                                    -- For business accounts

    -- Current balance
    current_balance   NUMERIC(15,4) DEFAULT 0 NOT NULL CHECK (current_balance >= 0),
    pending_balance   NUMERIC(15,4) DEFAULT 0 CHECK (pending_balance >= 0),
    lifetime_credits  NUMERIC(15,4) DEFAULT 0,                 -- Total credits ever received
    lifetime_usage    NUMERIC(15,4) DEFAULT 0,                 -- Total credits ever used

    -- Balance breakdown by type
    promotional_balance NUMERIC(15,4) DEFAULT 0 CHECK (promotional_balance >= 0),
    purchased_balance   NUMERIC(15,4) DEFAULT 0 CHECK (purchased_balance >= 0),
    loyalty_balance     NUMERIC(15,4) DEFAULT 0 CHECK (loyalty_balance >= 0),
    refund_balance      NUMERIC(15,4) DEFAULT 0 CHECK (refund_balance >= 0),

    -- Currency
    currency          CHAR(3) NOT NULL DEFAULT 'USD',
    credit_value      NUMERIC(10,4) DEFAULT 1.0,               -- Value per credit in currency

    -- Controls
    is_active         BOOLEAN DEFAULT true,
    locked_until      TIMESTAMP WITH TIME ZONE,                 -- For fraud holds
    lock_reason       TEXT,

    -- Spending rules
    allowed_products  TEXT[],                                   -- Products credits can buy
    excluded_products TEXT[],                                   -- Products credits cannot buy
    minimum_spend     NUMERIC(15,4),                            -- Minimum spend to use credits
    maximum_per_transaction NUMERIC(15,4),                      -- Max credits per transaction

    -- Auto-recharge (for negative balances prevention)
    auto_recharge_threshold NUMERIC(15,4),                      -- Auto-recharge when below
    auto_recharge_amount NUMERIC(15,4),
    auto_recharge_payment_method_id UUID,

    -- Audit
    last_transaction_at TIMESTAMP WITH TIME ZONE,
    last_activity_at    TIMESTAMP WITH TIME ZONE,

    -- Metadata
    metadata          JSONB,

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_wallet_balances CHECK (
        current_balance = promotional_balance + purchased_balance + loyalty_balance + refund_balance
    ),
    CONSTRAINT fk_credits_wallet_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_credits_wallet_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT fk_credits_wallet_payment_method FOREIGN KEY (auto_recharge_payment_method_id)
        REFERENCES public.payment_methods(payment_method_id) ON DELETE SET NULL
);

-- Comments for credits_wallet table
COMMENT ON TABLE public.credits_wallet IS 'User credit/points wallet with balance tracking';
COMMENT ON COLUMN public.credits_wallet.wallet_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.credits_wallet.user_id IS 'Wallet owner';
COMMENT ON COLUMN public.credits_wallet.company_id IS 'Company (if business account)';
COMMENT ON COLUMN public.credits_wallet.current_balance IS 'Current available balance';
COMMENT ON COLUMN public.credits_wallet.pending_balance IS 'Pending (unconfirmed) balance';
COMMENT ON COLUMN public.credits_wallet.lifetime_credits IS 'Total credits ever received';
COMMENT ON COLUMN public.credits_wallet.lifetime_usage IS 'Total credits ever used';
COMMENT ON COLUMN public.credits_wallet.promotional_balance IS 'Promotional credits balance';
COMMENT ON COLUMN public.credits_wallet.purchased_balance IS 'Purchased credits balance';
COMMENT ON COLUMN public.credits_wallet.loyalty_balance IS 'Loyalty credits balance';
COMMENT ON COLUMN public.credits_wallet.refund_balance IS 'Refund credits balance';
COMMENT ON COLUMN public.credits_wallet.currency IS 'Currency of credits';
COMMENT ON COLUMN public.credits_wallet.credit_value IS 'Value per credit in currency';
COMMENT ON COLUMN public.credits_wallet.is_active IS 'Whether wallet is active';
COMMENT ON COLUMN public.credits_wallet.locked_until IS 'Lock for fraud holds';
COMMENT ON COLUMN public.credits_wallet.lock_reason IS 'Reason for lock';
COMMENT ON COLUMN public.credits_wallet.allowed_products IS 'Products credits can buy';
COMMENT ON COLUMN public.credits_wallet.excluded_products IS 'Products credits cannot buy';
COMMENT ON COLUMN public.credits_wallet.minimum_spend IS 'Minimum spend to use credits';
COMMENT ON COLUMN public.credits_wallet.maximum_per_transaction IS 'Max credits per transaction';
COMMENT ON COLUMN public.credits_wallet.auto_recharge_threshold IS 'Auto-recharge when below';
COMMENT ON COLUMN public.credits_wallet.auto_recharge_amount IS 'Amount to auto-recharge';
COMMENT ON COLUMN public.credits_wallet.auto_recharge_payment_method_id IS 'Payment method for auto-recharge';
COMMENT ON COLUMN public.credits_wallet.last_transaction_at IS 'Last transaction timestamp';
COMMENT ON COLUMN public.credits_wallet.last_activity_at IS 'Last activity timestamp';
COMMENT ON COLUMN public.credits_wallet.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.credits_wallet.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.credits_wallet.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.credits_wallet.created_by IS 'User who created the record';
COMMENT ON COLUMN public.credits_wallet.updated_by IS 'User who last updated the record';

-- Indexes for credits_wallet table
CREATE INDEX idx_credits_wallet_user_id ON public.credits_wallet(user_id);
CREATE INDEX idx_credits_wallet_company_id ON public.credits_wallet(company_id) WHERE company_id IS NOT NULL;
CREATE INDEX idx_credits_wallet_balance ON public.credits_wallet(current_balance) WHERE current_balance > 0;
CREATE INDEX idx_credits_wallet_locked ON public.credits_wallet(locked_until) WHERE locked_until IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_credits_wallet_timestamp
    BEFORE UPDATE ON public.credits_wallet
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.credits_wallet ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view their own wallet
CREATE POLICY credits_wallet_user_policy ON public.credits_wallet
    USING (user_id = current_user_id());

-- Policy: Finance team can manage wallets
CREATE POLICY credits_wallet_finance_policy ON public.credits_wallet
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 19 - credit_transactions
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 19 (Subsidiary to credits_wallet)
-- Table Name: credit_transactions
-- Description: Complete audit trail of all credit movements in the wallet,
--              supporting balance verification and dispute resolution.
--
-- Business Case: Every credit movement must be tracked for audit and
--                reconciliation. This table records each transaction with:
--                1) Before/after balances for verification,
--                2) Transaction type and reason,
--                3) Reference to related entities (orders, invoices),
--                4) Expiration tracking,
--                5) Reversal links.
--                It enables:
--                - Balance verification queries,
--                - Dispute investigation,
--                - Fraud detection,
--                - Accounting reconciliation,
--                - Tax reporting (if credits are taxable),
--                - Loyalty program analytics.
--
-- Feature Reference: WAL-05 (Credit Transactions)
--                  : WAL-06 (Audit Trail)
-- -----------------------------------------------------------------------------
CREATE TABLE public.credit_transactions (
    transaction_id    UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    wallet_id         UUID NOT NULL,
    user_id           UUID NOT NULL,                           -- Denormalized for performance

    -- Transaction identification
    transaction_type  public.credit_transaction_type NOT NULL,
    transaction_reason TEXT,
    transaction_ref   VARCHAR(255),                             -- External reference

    -- Amounts
    amount            NUMERIC(15,4) NOT NULL,
    credit_type       VARCHAR(20) NOT NULL CHECK (credit_type IN ('PROMOTIONAL', 'PURCHASED', 'LOYALTY', 'REFUND')),

    -- Balance tracking
    balance_before    NUMERIC(15,4) NOT NULL,
    balance_after     NUMERIC(15,4) NOT NULL,

    -- Related entities
    order_id          UUID,                                     -- Related order
    invoice_id        UUID,                                     -- Related invoice
    subscription_id   UUID,                                     -- Related subscription
    referral_id       UUID,                                     -- Related referral
    reversal_of       UUID,                                     -- If this is a reversal

    -- Expiration
    expires_at        TIMESTAMP WITH TIME ZONE,                  -- When credits expire
    expired_at        TIMESTAMP WITH TIME ZONE,                  -- When actually expired

    -- Status
    status            VARCHAR(20) DEFAULT 'COMPLETED' CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED', 'REVERSED')),

    -- Metadata
    metadata          JSONB,

    -- Timestamps
    transaction_date  TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID,                                     -- System or user who initiated

    -- Constraints
    CONSTRAINT chk_credit_balance CHECK (balance_after = balance_before +
        CASE WHEN transaction_type IN ('PURCHASE', 'REFERRAL_BONUS', 'SIGNUP_BONUS', 'LOYALTY_BONUS', 'PROMOTION', 'CASHBACK', 'TRANSFER_IN', 'REFUND')
            THEN amount
            ELSE -amount
        END),
    CONSTRAINT fk_credit_transactions_wallet FOREIGN KEY (wallet_id)
        REFERENCES public.credits_wallet(wallet_id) ON DELETE CASCADE,
    CONSTRAINT fk_credit_transactions_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_credit_transactions_reversal FOREIGN KEY (reversal_of)
        REFERENCES public.credit_transactions(transaction_id) ON DELETE SET NULL
);

-- Comments for credit_transactions table
COMMENT ON TABLE public.credit_transactions IS 'Audit trail of all credit wallet transactions';
COMMENT ON COLUMN public.credit_transactions.transaction_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.credit_transactions.wallet_id IS 'Wallet reference';
COMMENT ON COLUMN public.credit_transactions.user_id IS 'User (denormalized)';
COMMENT ON COLUMN public.credit_transactions.transaction_type IS 'Type of transaction';
COMMENT ON COLUMN public.credit_transactions.transaction_reason IS 'Reason for transaction';
COMMENT ON COLUMN public.credit_transactions.transaction_ref IS 'External reference';
COMMENT ON COLUMN public.credit_transactions.amount IS 'Transaction amount';
COMMENT ON COLUMN public.credit_transactions.credit_type IS 'Type of credits';
COMMENT ON COLUMN public.credit_transactions.balance_before IS 'Balance before transaction';
COMMENT ON COLUMN public.credit_transactions.balance_after IS 'Balance after transaction';
COMMENT ON COLUMN public.credit_transactions.order_id IS 'Related order';
COMMENT ON COLUMN public.credit_transactions.invoice_id IS 'Related invoice';
COMMENT ON COLUMN public.credit_transactions.subscription_id IS 'Related subscription';
COMMENT ON COLUMN public.credit_transactions.referral_id IS 'Related referral';
COMMENT ON COLUMN public.credit_transactions.reversal_of IS 'Reversed transaction';
COMMENT ON COLUMN public.credit_transactions.expires_at IS 'When credits expire';
COMMENT ON COLUMN public.credit_transactions.expired_at IS 'When credits expired';
COMMENT ON COLUMN public.credit_transactions.status IS 'Transaction status';
COMMENT ON COLUMN public.credit_transactions.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.credit_transactions.transaction_date IS 'When transaction occurred';
COMMENT ON COLUMN public.credit_transactions.created_at IS 'Record creation time';
COMMENT ON COLUMN public.credit_transactions.created_by IS 'Who initiated';

-- Indexes for credit_transactions table
CREATE INDEX idx_credit_transactions_wallet_id ON public.credit_transactions(wallet_id, transaction_date DESC);
CREATE INDEX idx_credit_transactions_user_id ON public.credit_transactions(user_id, transaction_date DESC);
CREATE INDEX idx_credit_transactions_type ON public.credit_transactions(transaction_type, transaction_date);
CREATE INDEX idx_credit_transactions_reference ON public.credit_transactions(order_id) WHERE order_id IS NOT NULL;
CREATE INDEX idx_credit_transactions_invoice ON public.credit_transactions(invoice_id) WHERE invoice_id IS NOT NULL;
CREATE INDEX idx_credit_transactions_expiry ON public.credit_transactions(expires_at) WHERE expires_at IS NOT NULL;

-- Trigger to update wallet last_transaction_at
CREATE OR REPLACE FUNCTION public.update_wallet_activity()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE public.credits_wallet
    SET last_transaction_at = NEW.transaction_date,
        last_activity_at = CURRENT_TIMESTAMP
    WHERE wallet_id = NEW.wallet_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_wallet_on_transaction
    AFTER INSERT ON public.credit_transactions
    FOR EACH ROW EXECUTE FUNCTION public.update_wallet_activity();

-- Enable RLS
ALTER TABLE public.credit_transactions ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view their own transactions
CREATE POLICY credit_transactions_user_policy ON public.credit_transactions
    USING (user_id = current_user_id());

-- Policy: Finance team can view all
CREATE POLICY credit_transactions_finance_policy ON public.credit_transactions
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 20 - coupons
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 20
-- Table Name: coupons
-- Description: Manages discount coupons and promotional codes with flexible
--              rules for marketing campaigns.
--
-- Business Case: Marketing campaigns require flexible discount mechanisms to
--                acquire and retain customers. This table stores coupon
--                configurations with support for:
--                1) Multiple discount types (percentage, fixed amount),
--                2) Single-use or multi-use codes,
--                3) First-time customer restrictions,
--                4) Minimum purchase requirements,
--                5) Product/category restrictions,
--                6) Time-limited campaigns,
--                7) Stacking rules (can combine with other offers),
--                8) Referral-specific coupons,
--                9) Geographic restrictions,
--                10) Usage limits per customer.
--                For analytics, it tracks:
--                - Redemption rates,
--                - Campaign ROI,
--                - Customer acquisition cost,
--                - Promotion effectiveness.
--
-- KPIs:
--   1. Coupon redemption rate by campaign
--   2. Average order value with coupon vs. without
--   3. Customer retention rate from coupon users
--   4. Coupon fraud rate (unauthorized use) < 0.1%
--   5. Time to first redemption after campaign launch
--
-- Feature Reference: CUP-01 (Coupon Management)
--                  : CUP-02 (Campaign Tracking)
--                  : CUP-03 (Fraud Prevention)
-- -----------------------------------------------------------------------------
CREATE TABLE public.coupons (
    -- Primary key
    coupon_id         UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Coupon identification
    coupon_code       VARCHAR(100) NOT NULL UNIQUE,
    coupon_name       VARCHAR(255) NOT NULL,
    coupon_description TEXT,

    -- Campaign
    campaign_id       UUID,                                   -- Marketing campaign
    campaign_name     VARCHAR(255),

    -- Discount configuration
    coupon_type       public.coupon_type NOT NULL,
    discount_value    NUMERIC(12,4) NOT NULL,                  -- Percentage or fixed amount
    discount_currency CHAR(3),                                 -- For fixed amount
    minimum_order_amount NUMERIC(12,2),                        -- Minimum purchase
    maximum_discount  NUMERIC(12,2),                           -- Max discount amount

    -- Duration and usage
    duration          public.coupon_duration NOT NULL DEFAULT 'ONCE',
    duration_in_months INTEGER,                                -- For REPEATING duration
    max_uses          INTEGER,                                 -- Total uses across all customers
    max_uses_per_customer INTEGER,                             -- Uses per customer
    max_uses_per_order INTEGER DEFAULT 1,

    -- Eligibility
    first_time_customers_only BOOLEAN DEFAULT false,
    existing_customers_only BOOLEAN DEFAULT false,
    minimum_account_age_days INTEGER,                          -- Min days since signup
    maximum_account_age_days INTEGER,                          -- Max days since signup

    -- Product restrictions
    applicable_products TEXT[],                                -- Product IDs or categories
    applicable_categories TEXT[],
    excluded_products TEXT[],
    excluded_categories TEXT[],

    -- Customer restrictions
    applicable_customer_segments TEXT[],                       -- Customer segments
    applicable_customer_tags TEXT[],                           -- Customer tags
    excluded_customers UUID[],                                 -- Specific customers excluded

    -- Geographic restrictions
    applicable_countries CHAR(3)[],
    -- Geographic restrictions (continued)
    applicable_countries CHAR(3)[],                            -- Countries where coupon is valid
    excluded_countries CHAR(3)[],                              -- Countries where coupon is invalid
    applicable_postal_codes TEXT[],                            -- Specific postal codes

    -- Time restrictions
    valid_from        TIMESTAMP WITH TIME ZONE NOT NULL,
    valid_until       TIMESTAMP WITH TIME ZONE,
    active_days_of_week INTEGER[],                             -- 0=Sunday, 6=Saturday
    active_hours_start TIME WITHOUT TIME ZONE,                  -- Start time each day
    active_hours_end   TIME WITHOUT TIME ZONE,                  -- End time each day

    -- Stacking rules
    stackable_with_other_coupons BOOLEAN DEFAULT false,
    stackable_with_sales BOOLEAN DEFAULT true,
    stackable_with_referrals BOOLEAN DEFAULT true,
    stack_priority    INTEGER DEFAULT 0,                        -- Higher = applied first

    -- Referral tracking
    is_referral_coupon BOOLEAN DEFAULT false,
    referring_user_id UUID,                                     -- User who generated (for referral)

    -- Status
    is_active         BOOLEAN DEFAULT true NOT NULL,
    is_public         BOOLEAN DEFAULT true,                     -- Visible to all users
    status_reason     TEXT,                                      -- Why deactivated if not active

    -- Usage tracking
    times_used        INTEGER DEFAULT 0 NOT NULL,
    first_used_at     TIMESTAMP WITH TIME ZONE,
    last_used_at      TIMESTAMP WITH TIME ZONE,
    total_discount_given NUMERIC(15,2) DEFAULT 0,

    -- Metadata
    metadata          JSONB,
    tags              TEXT[],

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_coupon_dates CHECK (valid_until IS NULL OR valid_until > valid_from),
    CONSTRAINT chk_coupon_duration CHECK (
        (duration = 'REPEATING' AND duration_in_months IS NOT NULL) OR
        (duration != 'REPEATING' OR duration_in_months IS NULL)
    ),
    CONSTRAINT chk_coupon_hours CHECK (
        (active_hours_start IS NULL AND active_hours_end IS NULL) OR
        (active_hours_start IS NOT NULL AND active_hours_end IS NOT NULL AND active_hours_start < active_hours_end)
    ),
    CONSTRAINT fk_coupons_campaign FOREIGN KEY (campaign_id)
        REFERENCES public.campaigns(campaign_id) ON DELETE SET NULL,
    CONSTRAINT fk_coupons_referring_user FOREIGN KEY (referring_user_id)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for coupons table
COMMENT ON TABLE public.coupons IS 'Discount coupons and promotional codes with flexible eligibility rules';
COMMENT ON COLUMN public.coupons.coupon_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.coupons.coupon_code IS 'Unique coupon code for redemption';
COMMENT ON COLUMN public.coupons.coupon_name IS 'Display name for the coupon';
COMMENT ON COLUMN public.coupons.coupon_description IS 'Detailed description of coupon terms';
COMMENT ON COLUMN public.coupons.campaign_id IS 'Associated marketing campaign';
COMMENT ON COLUMN public.coupons.campaign_name IS 'Campaign name (denormalized)';
COMMENT ON COLUMN public.coupons.coupon_type IS 'Type of discount';
COMMENT ON COLUMN public.coupons.discount_value IS 'Discount amount or percentage';
COMMENT ON COLUMN public.coupons.discount_currency IS 'Currency for fixed amount discounts';
COMMENT ON COLUMN public.coupons.minimum_order_amount IS 'Minimum purchase required';
COMMENT ON COLUMN public.coupons.maximum_discount IS 'Maximum discount amount';
COMMENT ON COLUMN public.coupons.duration IS 'How long coupon applies after first use';
COMMENT ON COLUMN public.coupons.duration_in_months IS 'Months for REPEATING duration';
COMMENT ON COLUMN public.coupons.max_uses IS 'Total uses allowed';
COMMENT ON COLUMN public.coupons.max_uses_per_customer IS 'Uses per customer';
COMMENT ON COLUMN public.coupons.max_uses_per_order IS 'Uses per order';
COMMENT ON COLUMN public.coupons.first_time_customers_only IS 'Only for new customers';
COMMENT ON COLUMN public.coupons.existing_customers_only IS 'Only for existing customers';
COMMENT ON COLUMN public.coupons.minimum_account_age_days IS 'Minimum days since signup';
COMMENT ON COLUMN public.coupons.maximum_account_age_days IS 'Maximum days since signup';
COMMENT ON COLUMN public.coupons.applicable_products IS 'Products coupon applies to';
COMMENT ON COLUMN public.coupons.applicable_categories IS 'Categories coupon applies to';
COMMENT ON COLUMN public.coupons.excluded_products IS 'Products excluded';
COMMENT ON COLUMN public.coupons.excluded_categories IS 'Categories excluded';
COMMENT ON COLUMN public.coupons.applicable_customer_segments IS 'Customer segments eligible';
COMMENT ON COLUMN public.coupons.applicable_customer_tags IS 'Customer tags eligible';
COMMENT ON COLUMN public.coupons.excluded_customers IS 'Specific customers excluded';
COMMENT ON COLUMN public.coupons.applicable_countries IS 'Countries where valid';
COMMENT ON COLUMN public.coupons.excluded_countries IS 'Countries where invalid';
COMMENT ON COLUMN public.coupons.applicable_postal_codes IS 'Specific postal codes';
COMMENT ON COLUMN public.coupons.valid_from IS 'When coupon becomes valid';
COMMENT ON COLUMN public.coupons.valid_until IS 'When coupon expires';
COMMENT ON COLUMN public.coupons.active_days_of_week IS 'Days of week active';
COMMENT ON COLUMN public.coupons.active_hours_start IS 'Start time each day';
COMMENT ON COLUMN public.coupons.active_hours_end IS 'End time each day';
COMMENT ON COLUMN public.coupons.stackable_with_other_coupons IS 'Can combine with other coupons';
COMMENT ON COLUMN public.coupons.stackable_with_sales IS 'Can combine with sales';
COMMENT ON COLUMN public.coupons.stackable_with_referrals IS 'Can combine with referrals';
COMMENT ON COLUMN public.coupons.stack_priority IS 'Priority when stacking';
COMMENT ON COLUMN public.coupons.is_referral_coupon IS 'Whether this is a referral coupon';
COMMENT ON COLUMN public.coupons.referring_user_id IS 'User who generated (for referral)';
COMMENT ON COLUMN public.coupons.is_active IS 'Whether coupon is active';
COMMENT ON COLUMN public.coupons.is_public IS 'Whether publicly visible';
COMMENT ON COLUMN public.coupons.status_reason IS 'Reason if inactive';
COMMENT ON COLUMN public.coupons.times_used IS 'Number of times used';
COMMENT ON COLUMN public.coupons.first_used_at IS 'First use timestamp';
COMMENT ON COLUMN public.coupons.last_used_at IS 'Most recent use';
COMMENT ON COLUMN public.coupons.total_discount_given IS 'Total discount amount provided';
COMMENT ON COLUMN public.coupons.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.coupons.tags IS 'Tags for categorization';
COMMENT ON COLUMN public.coupons.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.coupons.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.coupons.created_by IS 'User who created the record';
COMMENT ON COLUMN public.coupons.updated_by IS 'User who last updated the record';

-- Indexes for coupons table
CREATE INDEX idx_coupons_code ON public.coupons(coupon_code) WHERE is_active = true;
CREATE INDEX idx_coupons_campaign_id ON public.coupons(campaign_id) WHERE campaign_id IS NOT NULL;
CREATE INDEX idx_coupons_valid_period ON public.coupons(valid_from, valid_until) WHERE is_active = true;
CREATE INDEX idx_coupons_type ON public.coupons(coupon_type);
CREATE INDEX idx_coupons_referring_user ON public.coupons(referring_user_id) WHERE is_referral_coupon = true;
CREATE INDEX idx_coupons_usage ON public.coupons(times_used) WHERE times_used > 0;

-- Partial index for active coupons
CREATE INDEX idx_coupons_active ON public.coupons(coupon_id)
    WHERE is_active = true AND valid_from <= CURRENT_TIMESTAMP AND (valid_until IS NULL OR valid_until >= CURRENT_TIMESTAMP);

-- GiST index for array columns
CREATE INDEX idx_coupons_applicable_products ON public.coupons USING gin(applicable_products);
CREATE INDEX idx_coupons_excluded_products ON public.coupons USING gin(excluded_products);
CREATE INDEX idx_coupons_applicable_countries ON public.coupons USING gin(applicable_countries);

-- Trigger for updated_at
CREATE TRIGGER update_coupons_timestamp
    BEFORE UPDATE ON public.coupons
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;

-- Policy: Marketing team can manage coupons
CREATE POLICY coupons_marketing_policy ON public.coupons
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('marketing_admin', 'admin')
    ));

-- Policy: All authenticated users can view active public coupons
CREATE POLICY coupons_read_policy ON public.coupons
    FOR SELECT USING (is_active = true AND is_public = true);

-- =============================================================================
-- TABLE: 21 - coupon_redemptions
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 21 (Subsidiary to coupons)
-- Table Name: coupon_redemptions
-- Description: Tracks each instance of coupon usage by customers for audit
--              and analytics.
--
-- Business Case: Understanding coupon effectiveness requires tracking every
--                redemption. This table records who used which coupon when,
--                and on what order. It enables:
--                1) Campaign ROI analysis,
--                2) Fraud detection (unusual redemption patterns),
--                3) Customer behavior analysis,
--                4) Coupon effectiveness by segment,
--                5) Expiration tracking.
--                The data feeds into marketing analytics and helps optimize
--                future campaigns.
--
-- Feature Reference: CUP-04 (Redemption Tracking)
-- -----------------------------------------------------------------------------
CREATE TABLE public.coupon_redemptions (
    redemption_id     UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    coupon_id         UUID NOT NULL,
    user_id           UUID NOT NULL,
    order_id          UUID,                                    -- Order where applied
    invoice_id        UUID,                                    -- Generated invoice

    discount_amount   NUMERIC(12,2) NOT NULL,
    currency          CHAR(3) NOT NULL,

    order_amount      NUMERIC(12,2) NOT NULL,                  -- Original order amount
    final_amount      NUMERIC(12,2) NOT NULL,                  -- Amount after discount

    redemption_date   TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    ip_address        INET,
    user_agent        TEXT,

    metadata          JSONB,

    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT fk_coupon_redemptions_coupon FOREIGN KEY (coupon_id)
        REFERENCES public.coupons(coupon_id) ON DELETE CASCADE,
    CONSTRAINT fk_coupon_redemptions_user FOREIGN KEY (user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_coupon_redemptions_order FOREIGN KEY (order_id)
        REFERENCES public.orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_coupon_redemptions_invoice FOREIGN KEY (invoice_id)
        REFERENCES public.invoices(invoice_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.coupon_redemptions IS 'Tracks each coupon usage by customers';

-- Indexes for coupon_redemptions
CREATE INDEX idx_coupon_redemptions_coupon_id ON public.coupon_redemptions(coupon_id, redemption_date DESC);
CREATE INDEX idx_coupon_redemptions_user_id ON public.coupon_redemptions(user_id, redemption_date DESC);
CREATE INDEX idx_coupon_redemptions_order_id ON public.coupon_redemptions(order_id) WHERE order_id IS NOT NULL;
CREATE INDEX idx_coupon_redemptions_date ON public.coupon_redemptions(redemption_date DESC);

-- Trigger to update coupon usage stats
CREATE OR REPLACE FUNCTION public.update_coupon_usage_stats()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE public.coupons
    SET times_used = times_used + 1,
        last_used_at = NEW.redemption_date,
        total_discount_given = total_discount_given + NEW.discount_amount,
        first_used_at = COALESCE(first_used_at, NEW.redemption_date)
    WHERE coupon_id = NEW.coupon_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_coupon_on_redemption
    AFTER INSERT ON public.coupon_redemptions
    FOR EACH ROW EXECUTE FUNCTION public.update_coupon_usage_stats();

-- Enable RLS
ALTER TABLE public.coupon_redemptions ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view their own redemptions
CREATE POLICY coupon_redemptions_user_policy ON public.coupon_redemptions
    FOR SELECT USING (user_id = current_user_id());

-- Policy: Marketing team can view all
CREATE POLICY coupon_redemptions_marketing_policy ON public.coupon_redemptions
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('marketing_admin', 'admin')
    ));

-- =============================================================================
-- TABLE: 22 - affiliate_partners
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 22
-- Table Name: affiliate_partners
-- Description: Manages affiliate marketing partners who promote the platform
--              in exchange for commissions on referred sales.
--
-- Business Case: Affiliate marketing is a powerful customer acquisition channel.
--                This table manages the partner program with:
--                1) Partner registration and approval workflow,
--                2) Commission structures (percentage, fixed, tiered),
--                3) Cookie tracking for attribution,
--                4) Payout schedules and thresholds,
--                5) Marketing materials access,
--                6) Performance tracking,
--                7) Fraud detection,
--                8) Tax information collection (W-9, W-8BEN),
--                9) Payment method preferences,
--                10) Multi-tier programs.
--                For compliance, it tracks:
--                - Partner agreements and signatures,
--                - Tax documentation,
--                - Payout history,
--                - FTC disclosure compliance.
--                The program can support:
--                - Influencers and content creators,
--                - Review sites and blogs,
--                - Strategic partners,
--                - Resellers and agencies.
--
-- KPIs:
--   1. Number of active partners
--   2. Revenue generated through affiliates
--   3. Average commission rate by partner tier
--   4. Partner acquisition cost
--   5. Partner retention rate
--   6. Top-performing partners (80/20 rule)
--   7. Fraud rate (invalid referrals) < 1%
--   8. Average time to first payout
--
-- Feature Reference: AFF-01 (Affiliate Program)
--                  : AFF-02 (Partner Management)
--                  : AFF-03 (Commission Tracking)
--                  : AFF-04 (Fraud Prevention)
-- -----------------------------------------------------------------------------
CREATE TABLE public.affiliate_partners (
    -- Primary key
    partner_id        UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Partner identification
    partner_user_id   UUID NOT NULL UNIQUE,                    -- User account of partner
    company_id        UUID,                                    -- If partner is a company
    partner_type      VARCHAR(50) NOT NULL CHECK (partner_type IN (
        'INDIVIDUAL', 'BLOG', 'INFLUENCER', 'REVIEW_SITE', 'STRATEGIC_PARTNER', 'RESELLER', 'AGENCY'
    )),

    -- Contact information
    business_name     VARCHAR(255),
    contact_name      VARCHAR(255) NOT NULL,
    contact_email     VARCHAR(255) NOT NULL,
    contact_phone     VARCHAR(50),
    website_url       VARCHAR(255),
    social_media_handles JSONB,                                 -- Social media accounts

    -- Tax information
    tax_id            VARCHAR(50),                               -- EIN or SSN
    tax_id_type       VARCHAR(20) CHECK (tax_id_type IN ('EIN', 'SSN', 'VAT', 'OTHER')),
    tax_country       CHAR(2),
    w9_received       BOOLEAN DEFAULT false,
    w9_verified_at    TIMESTAMP WITH TIME ZONE,
    w9_url            TEXT,                                      -- Stored W-9 document

    -- Payment information
    payment_method    public.payment_method_type,
    payment_details   JSONB,                                     -- Bank account/PayPal details
    payment_currency  CHAR(3) DEFAULT 'USD',
    payment_threshold NUMERIC(12,2) DEFAULT 50.00,               -- Minimum for payout
    payment_frequency VARCHAR(20) DEFAULT 'MONTHLY' CHECK (payment_frequency IN ('WEEKLY', 'BIWEEKLY', 'MONTHLY', 'QUARTERLY')),

    -- Commission structure
    commission_type   public.commission_type NOT NULL,
    commission_rate   NUMERIC(5,2) NOT NULL,                    -- Percentage or fixed amount
    commission_tiers  JSONB,                                     -- Tiered commission structure

    -- Cookie tracking
    cookie_days       INTEGER DEFAULT 30,                        -- Attribution window
    default_tracking_code TEXT,                                  -- Default tracking code

    -- Marketing materials
    marketing_materials_access BOOLEAN DEFAULT false,
    custom_landing_page VARCHAR(255),                            -- Custom landing page URL

    -- Performance metrics
    referral_count    INTEGER DEFAULT 0,
    conversion_count  INTEGER DEFAULT 0,
    conversion_rate   NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN referral_count > 0
        THEN (conversion_count::NUMERIC / referral_count::NUMERIC) * 100
        ELSE 0 END
    ) STORED,
    total_sales       NUMERIC(15,2) DEFAULT 0,
    total_commission  NUMERIC(15,2) DEFAULT 0,
    paid_commission   NUMERIC(15,2) DEFAULT 0,
    pending_commission NUMERIC(15,2) DEFAULT 0,

    -- Status
    status            public.affiliate_status NOT NULL DEFAULT 'PENDING_APPROVAL',
    status_reason     TEXT,
    approved_at       TIMESTAMP WITH TIME ZONE,
    approved_by       UUID,

    -- Dates
    joined_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_activity_at  TIMESTAMP WITH TIME ZONE,

    -- Agreement
    agreement_accepted_at TIMESTAMP WITH TIME ZONE,
    agreement_version VARCHAR(50),
    agreement_ip      INET,

    -- Fraud detection
    fraud_score       INTEGER CHECK (fraud_score BETWEEN 0 AND 100),
    fraud_flags       TEXT[],                                   -- Suspicious activities
    last_fraud_check  TIMESTAMP WITH TIME ZONE,

    -- Metadata
    metadata          JSONB,
    tags              TEXT[],

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_affiliate_commission CHECK (commission_rate >= 0),
    CONSTRAINT fk_affiliate_partners_user FOREIGN KEY (partner_user_id)
        REFERENCES public.users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_affiliate_partners_company FOREIGN KEY (company_id)
        REFERENCES public.companies(company_id) ON DELETE SET NULL,
    CONSTRAINT fk_affiliate_partners_approved_by FOREIGN KEY (approved_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for affiliate_partners table
COMMENT ON TABLE public.affiliate_partners IS 'Manages affiliate marketing partners and their commission structures';
COMMENT ON COLUMN public.affiliate_partners.partner_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.affiliate_partners.partner_user_id IS 'User account of partner';
COMMENT ON COLUMN public.affiliate_partners.company_id IS 'Company (if partner is a business)';
COMMENT ON COLUMN public.affiliate_partners.partner_type IS 'Type of partner';
COMMENT ON COLUMN public.affiliate_partners.business_name IS 'Business name if applicable';
COMMENT ON COLUMN public.affiliate_partners.contact_name IS 'Primary contact name';
COMMENT ON COLUMN public.affiliate_partners.contact_email IS 'Contact email';
COMMENT ON COLUMN public.affiliate_partners.contact_phone IS 'Contact phone';
COMMENT ON COLUMN public.affiliate_partners.website_url IS 'Partner website';
COMMENT ON COLUMN public.affiliate_partners.social_media_handles IS 'Social media accounts';
COMMENT ON COLUMN public.affiliate_partners.tax_id IS 'Tax ID for reporting';
COMMENT ON COLUMN public.affiliate_partners.tax_id_type IS 'Type of tax ID';
