-- =============================================================================
-- TABLE: 23 - affiliate_referrals
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 23 (Subsidiary to affiliate_partners)
-- Table Name: affiliate_referrals
-- Description: Tracks individual referrals from affiliate partners, including
--              attribution, conversion status, and commission calculations.
--
-- Business Case: Accurate tracking of each referral is essential for paying
--                commissions correctly and analyzing program performance.
--                This table records:
--                1) Referral source (link, cookie, promo code),
--                2) Referred customer and their actions,
--                3) Conversion status (click, signup, purchase),
--                4) Commission amounts,
--                5) Cookie and IP data for fraud detection,
--                6) Attribution window tracking,
--                7) Multi-touch attribution if applicable.
--                The data enables:
--                - Accurate commission payments,
--                - Fraud detection (same IP, multiple clicks),
--                - Channel performance analysis,
--                - Customer acquisition cost by source,
--                - Lifetime value by referral source.
--
-- Feature Reference: AFF-05 (Referral Tracking)
--                  : AFF-06 (Commission Calculation)
-- -----------------------------------------------------------------------------
CREATE TABLE public.affiliate_referrals (
    -- Primary key
    referral_id       UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Partner
    partner_id        UUID NOT NULL,
    tracking_code     VARCHAR(100),                              -- Specific tracking code used

    -- Referred user
    referred_user_id  UUID,                                      -- User who was referred
    referred_email    VARCHAR(255),                              -- Email before signup
    referred_ip       INET,                                      -- IP at time of referral

    -- Referral source
    referrer_url      TEXT,                                      -- URL where click occurred
    landing_url       TEXT,                                      -- Landing page URL
    utm_source        VARCHAR(255),                              -- UTM parameters
    utm_medium        VARCHAR(255),
    utm_campaign      VARCHAR(255),
    utm_term          VARCHAR(255),
    utm_content       VARCHAR(255),

    -- Attribution
    cookie_id         VARCHAR(255),                              -- Browser cookie ID
    click_id          VARCHAR(255),                              -- Click ID from network
    clicked_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    attributed_at     TIMESTAMP WITH TIME ZONE,                  -- When attributed to partner

    -- Conversion tracking
    conversion_type   VARCHAR(50) CHECK (conversion_type IN ('CLICK', 'SIGNUP', 'PURCHASE', 'SUBSCRIBE')),
    converted_at      TIMESTAMP WITH TIME ZONE,
    order_id          UUID,                                      -- Order if purchase
    subscription_id   UUID,                                      -- Subscription if applicable
    conversion_value  NUMERIC(12,2),                              -- Value of conversion

    -- Commission
    commission_rate   NUMERIC(5,2),                               -- Rate at time of conversion
    commission_amount NUMERIC(12,2),                              -- Calculated commission
    commission_currency CHAR(3),
    commission_paid   BOOLEAN DEFAULT false,
    commission_paid_at TIMESTAMP WITH TIME ZONE,
    commission_payout_id UUID,                                   -- Link to payout

    -- Fraud detection
    fraud_score       INTEGER CHECK (fraud_score BETWEEN 0 AND 100),
    fraud_reason      TEXT,
    is_valid          BOOLEAN DEFAULT true,                       -- Whether referral is valid
    validation_notes  TEXT,

    -- Metadata
    metadata          JSONB,

    -- Timestamps
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT fk_affiliate_referrals_partner FOREIGN KEY (partner_id)
        REFERENCES public.affiliate_partners(partner_id) ON DELETE CASCADE,
    CONSTRAINT fk_affiliate_referrals_user FOREIGN KEY (referred_user_id)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_affiliate_referrals_order FOREIGN KEY (order_id)
        REFERENCES public.orders(order_id) ON DELETE SET NULL,
    CONSTRAINT fk_affiliate_referrals_subscription FOREIGN KEY (subscription_id)
        REFERENCES public.subscriptions(subscription_id) ON DELETE SET NULL
);

-- Comments for affiliate_referrals table
COMMENT ON TABLE public.affiliate_referrals IS 'Tracks individual referrals from affiliate partners';
COMMENT ON COLUMN public.affiliate_referrals.referral_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.affiliate_referrals.partner_id IS 'Referring affiliate partner';
COMMENT ON COLUMN public.affiliate_referrals.tracking_code IS 'Specific tracking code used';
