-- Trigger to update partner metrics
CREATE OR REPLACE FUNCTION public.update_partner_metrics()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.affiliate_partners
        SET referral_count = referral_count + 1,
            last_activity_at = CURRENT_TIMESTAMP
        WHERE partner_id = NEW.partner_id;
    ELSIF TG_OP = 'UPDATE' AND NEW.converted_at IS NOT NULL AND OLD.converted_at IS NULL THEN
        UPDATE public.affiliate_partners
        SET conversion_count = conversion_count + 1,
            total_sales = total_sales + COALESCE(NEW.conversion_value, 0),
            total_commission = total_commission + COALESCE(NEW.commission_amount, 0),
            pending_commission = pending_commission + COALESCE(NEW.commission_amount, 0)
        WHERE partner_id = NEW.partner_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_partner_on_referral
    AFTER INSERT OR UPDATE ON public.affiliate_referrals
    FOR EACH ROW EXECUTE FUNCTION public.update_partner_metrics();

