COMMENT ON COLUMN public.ledger_accounts.report_order IS 'Order in financial statements';
COMMENT ON COLUMN public.ledger_accounts.tax_relevant IS 'Whether relevant for tax';
COMMENT ON COLUMN public.ledger_accounts.tax_code IS 'Tax reporting code';
