COMMENT ON COLUMN public.ledger_accounts.created_by IS 'User who created the record';
COMMENT ON COLUMN public.ledger_accounts.updated_by IS 'User who last updated the record';

-- Enable ltree extension for hierarchical queries
CREATE EXTENSION IF NOT EXISTS ltree;

-- Indexes for ledger_accounts
CREATE INDEX idx_ledger_accounts_code ON public.ledger_accounts(account_code);
CREATE INDEX idx_ledger_accounts_type ON public.ledger_accounts(account_type);
CREATE INDEX idx_ledger_accounts_parent ON public.ledger_accounts(parent_account_id);
CREATE INDEX idx_ledger_accounts_path ON public.ledger_accounts USING gist(path);
CREATE INDEX idx_ledger_accounts_active ON public.ledger_accounts(is_active) WHERE is_active = true;

-- Trigger for updated_at
CREATE TRIGGER update_ledger_accounts_timestamp
    BEFORE UPDATE ON public.ledger_accounts
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Trigger to update path and level
CREATE OR REPLACE FUNCTION public.update_account_path()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.parent_account_id IS NULL THEN
        NEW.level := 1;
        NEW.path := text2ltree(NEW.account_code);
    ELSE
        SELECT level + 1, path || text2ltree(NEW.account_code)
        INTO NEW.level, NEW.path
        FROM public.ledger_accounts
        WHERE account_id = NEW.parent_account_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER set_account_path
    BEFORE INSERT OR UPDATE OF parent_account_id ON public.ledger_accounts
    FOR EACH ROW EXECUTE FUNCTION public.update_account_path();

