        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'accountant', 'admin')
    ));

-- =============================================================================
-- TABLE: 27 - ledger_entries
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 27
-- Table Name: ledger_entries
-- Description: Core double-entry accounting table recording all financial
--              transactions with debits and credits ensuring balance.
--
-- Business Case: For financial integrity and audit compliance, every monetary
--                transaction must be recorded using double-entry bookkeeping.
--                This table is the heart of the accounting system, ensuring:
--                1) Every transaction balances (debits = credits),
--                2) Complete audit trail of all financial activity,
--                3) Integration with sub-ledgers (invoices, payments),
--                4) Support for multiple currencies,
--                5) Period closing and reversals,
--                6) Financial statement generation,
--                7) Tax reporting,
--                8) Reconciliation with bank statements.
--                Each transaction creates at least two entries (debit and credit)
--                that must sum to zero. The table supports:
--                - Complex transactions with multiple lines,
--                - Recurring journal entries,
--                - Adjusting entries,
--                - Reversing entries,
--                - Intercompany transactions.
--                For audit purposes, every entry is immutable once posted and
--                includes references to source documents (invoices, payments).
--
-- KPIs:
--   1. Number of transactions per day/month
--   2. Percentage of automatically generated entries
--   3. Outstanding reconciliation items
--   4. Time to close books (month-end)
--   5. Audit adjustments per period
--
-- Feature Reference: LED-03 (General Ledger)
--                  : LED-04 (Journal Entries)
--                  : LED-05 (Audit Trail)
-- -----------------------------------------------------------------------------
CREATE TABLE public.ledger_entries (
    -- Primary key
    entry_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Journal identification
    journal_id        UUID NOT NULL,                            -- Group entries for same transaction
    entry_number      VARCHAR(50),                               -- Human-readable entry number
    entry_type        VARCHAR(50) NOT NULL CHECK (entry_type IN (
        'SALE', 'PURCHASE', 'PAYMENT', 'RECEIPT', 'REFUND', 'ADJUSTMENT',
        'DEPRECIATION', 'ACCRUAL', 'DEFERRAL', 'REVERSAL', 'CLOSING'
    )),

    -- Account
    account_id        UUID NOT NULL,
    account_code      VARCHAR(20) NOT NULL,                     -- Denormalized for performance

    -- Entry details
    entry_date        DATE NOT NULL,
    entry_description TEXT NOT NULL,

    -- Amounts (debit/credit - only one will be non-zero)
    debit_amount      NUMERIC(15,2) DEFAULT 0 CHECK (debit_amount >= 0),
    credit_amount     NUMERIC(15,2) DEFAULT 0 CHECK (credit_amount >= 0),
    currency          CHAR(3) NOT NULL,
    exchange_rate     NUMERIC(12,6) DEFAULT 1.0,
    base_currency_amount NUMERIC(15,2) GENERATED ALWAYS AS (
        CASE
            WHEN debit_amount > 0 THEN debit_amount * exchange_rate
            ELSE credit_amount * exchange_rate
        END
    ) STORED,

    -- Reference to source
    source_type       VARCHAR(50) NOT NULL CHECK (source_type IN (
        'INVOICE', 'PAYMENT', 'REFUND', 'CREDIT_NOTE', 'JOURNAL', 'SYSTEM'
    )),
    source_id         UUID NOT NULL,
    source_reference  VARCHAR(255),                              -- Human-readable reference

    -- Period
    fiscal_year       INTEGER NOT NULL,
    fiscal_period     INTEGER NOT NULL CHECK (fiscal_period BETWEEN 1 AND 12),
    is_period_closing BOOLEAN DEFAULT false,

    -- Reconciliation
    reconciliation_status public.reconciliation_status DEFAULT 'UNRECONCILED',
    reconciled_at     TIMESTAMP WITH TIME ZONE,
    reconciled_by     UUID,

    -- Reversal
    reverses_entry_id UUID,                                     -- If this entry reverses another
    reversed_by_entry_id UUID,                                  -- If this entry was reversed

    -- Approval
    requires_approval BOOLEAN DEFAULT false,
    approved_at       TIMESTAMP WITH TIME ZONE,
    approved_by       UUID,

    -- Metadata
    metadata          JSONB,

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT chk_ledger_entry_amount CHECK (
        (debit_amount > 0 AND credit_amount = 0) OR
        (debit_amount = 0 AND credit_amount > 0)
    ),
    CONSTRAINT fk_ledger_entries_account FOREIGN KEY (account_id)
        REFERENCES public.ledger_accounts(account_id) ON DELETE RESTRICT,
    CONSTRAINT fk_ledger_entries_reverses FOREIGN KEY (reverses_entry_id)
        REFERENCES public.ledger_entries(entry_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_entries_reversed_by FOREIGN KEY (reversed_by_entry_id)
        REFERENCES public.ledger_entries(entry_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_entries_approved_by FOREIGN KEY (approved_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_entries_reconciled_by FOREIGN KEY (reconciled_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for ledger_entries table
COMMENT ON TABLE public.ledger_entries IS 'Double-entry accounting records for all financial transactions';
COMMENT ON COLUMN public.ledger_entries.entry_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.ledger_entries.journal_id IS 'Group ID for related entries in same transaction';
COMMENT ON COLUMN public.ledger_entries.entry_number IS 'Human-readable entry number';
COMMENT ON COLUMN public.ledger_entries.entry_type IS 'Type of journal entry';
COMMENT ON COLUMN public.ledger_entries.account_id IS 'Account being debited/credited';
COMMENT ON COLUMN public.ledger_entries.account_code IS 'Account code (denormalized)';
COMMENT ON COLUMN public.ledger_entries.entry_date IS 'Date of the entry';
COMMENT ON COLUMN public.ledger_entries.entry_description IS 'Description of the transaction';
COMMENT ON COLUMN public.ledger_entries.debit_amount IS 'Debit amount (if applicable)';
COMMENT ON COLUMN public.ledger_entries.credit_amount IS 'Credit amount (if applicable)';
COMMENT ON COLUMN public.ledger_entries.currency IS 'Transaction currency';
COMMENT ON COLUMN public.ledger_entries.exchange_rate IS 'Exchange rate to base currency';
COMMENT ON COLUMN public.ledger_entries.base_currency_amount IS 'Amount in base currency';
COMMENT ON COLUMN public.ledger_entries.source_type IS 'Source document type';
COMMENT ON COLUMN public.ledger_entries.source_id IS 'Source document ID';
COMMENT ON COLUMN public.ledger_entries.source_reference IS 'Human-readable source reference';
COMMENT ON COLUMN public.ledger_entries.fiscal_year IS 'Fiscal year';
COMMENT ON COLUMN public.ledger_entries.fiscal_period IS 'Fiscal period (1-12)';
COMMENT ON COLUMN public.ledger_entries.is_period_closing IS 'Whether this is a closing entry';
COMMENT ON COLUMN public.ledger_entries.reconciliation_status IS 'Reconciliation status';
COMMENT ON COLUMN public.ledger_entries.reconciled_at IS 'When entry was reconciled';
COMMENT ON COLUMN public.ledger_entries.reconciled_by IS 'Who reconciled the entry';
COMMENT ON COLUMN public.ledger_entries.reverses_entry_id IS 'Entry that this reverses';
COMMENT ON COLUMN public.ledger_entries.reversed_by_entry_id IS 'Entry that reversed this';
COMMENT ON COLUMN public.ledger_entries.requires_approval IS 'Whether entry needs approval';
COMMENT ON COLUMN public.ledger_entries.approved_at IS 'When entry was approved';
COMMENT ON COLUMN public.ledger_entries.approved_by IS 'Who approved the entry';
COMMENT ON COLUMN public.ledger_entries.metadata IS 'Additional metadata';
COMMENT ON COLUMN public.ledger_entries.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.ledger_entries.created_by IS 'User who created the entry';

-- Indexes for ledger_entries table
CREATE INDEX idx_ledger_entries_journal_id ON public.ledger_entries(journal_id);
CREATE INDEX idx_ledger_entries_account_id ON public.ledger_entries(account_id, entry_date DESC);
CREATE INDEX idx_ledger_entries_date ON public.ledger_entries(entry_date DESC);
CREATE INDEX idx_ledger_entries_period ON public.ledger_entries(fiscal_year, fiscal_period);
CREATE INDEX idx_ledger_entries_source ON public.ledger_entries(source_type, source_id);
CREATE INDEX idx_ledger_entries_reconciliation ON public.ledger_entries(reconciliation_status)
    WHERE reconciliation_status != 'RECONCILED';

-- Partial index for entries needing approval
CREATE INDEX idx_ledger_entries_pending_approval ON public.ledger_entries(entry_date)
    WHERE requires_approval = true AND approved_at IS NULL;

-- Trigger to validate that journal balances
CREATE OR REPLACE FUNCTION public.validate_journal_balance()
RETURNS TRIGGER AS $$
DECLARE
    v_sum_debit NUMERIC;
    v_sum_credit NUMERIC;
BEGIN
    -- For new entries, check that the journal balances
    SELECT COALESCE(SUM(debit_amount), 0), COALESCE(SUM(credit_amount), 0)
    INTO v_sum_debit, v_sum_credit
    FROM public.ledger_entries
    WHERE journal_id = NEW.journal_id;

    -- Include the new entry if this is an insert
    IF TG_OP = 'INSERT' THEN
        IF NEW.debit_amount > 0 THEN
            v_sum_debit := v_sum_debit + NEW.debit_amount;
        ELSE
            v_sum_credit := v_sum_credit + NEW.credit_amount;
        END IF;
    END IF;

    -- Debits must equal credits (within rounding tolerance)
    IF ROUND(v_sum_debit, 2) != ROUND(v_sum_credit, 2) THEN
        RAISE EXCEPTION 'Journal % does not balance: Debits = %, Credits = %',
            NEW.journal_id, v_sum_debit, v_sum_credit;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER validate_journal_balance
    AFTER INSERT OR UPDATE ON public.ledger_entries
    FOR EACH ROW EXECUTE FUNCTION public.validate_journal_balance();

-- Enable RLS
ALTER TABLE public.ledger_entries ENABLE ROW LEVEL SECURITY;

