        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('finance_admin', 'accountant', 'auditor', 'admin')
    ));

-- =============================================================================
-- TABLE: 28 - ledger_periods
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 28
-- Table Name: ledger_periods
-- Description: Defines accounting periods (months, quarters, years) and their
--              open/closed status for financial reporting and controls.
--
-- Business Case: Accounting follows fiscal periods. Once a period is closed,
--                no new entries should be added to ensure financial statement
--                integrity. This table manages:
--                1) Fiscal year definitions,
--                2) Period open/close status,
--                3) Period adjustment windows,
--                4) Audit trail of period changes.
--                It enforces that entries cannot be posted to closed periods
--                and tracks who closed each period for audit purposes.
--
-- Feature Reference: LED-06 (Period Management)
-- -----------------------------------------------------------------------------
CREATE TABLE public.ledger_periods (
    period_id         UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Period identification
    fiscal_year       INTEGER NOT NULL,
    fiscal_period     INTEGER NOT NULL CHECK (fiscal_period BETWEEN 1 AND 12),
    period_name       VARCHAR(50) NOT NULL,                    -- e.g., 'January 2025'

    -- Dates
    start_date        DATE NOT NULL,
    end_date          DATE NOT NULL,
    closing_date      DATE,                                     -- Actual closing date

    -- Status
    is_open           BOOLEAN DEFAULT true NOT NULL,
    is_adjustment_period BOOLEAN DEFAULT false,                 -- For post-close adjustments
    closed_at         TIMESTAMP WITH TIME ZONE,
    closed_by         UUID,
    reopened_at       TIMESTAMP WITH TIME ZONE,
    reopened_by       UUID,
    reopen_reason     TEXT,

    -- Next period
    next_period_id    UUID,                                     -- For chaining

    -- Notes
    closing_notes     TEXT,

    -- Audit columns
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT uq_ledger_period UNIQUE (fiscal_year, fiscal_period),
    CONSTRAINT chk_period_dates CHECK (end_date >= start_date),
    CONSTRAINT fk_ledger_periods_closed_by FOREIGN KEY (closed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_periods_reopened_by FOREIGN KEY (reopened_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_ledger_periods_next FOREIGN KEY (next_period_id)
        REFERENCES public.ledger_periods(period_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.ledger_periods IS 'Accounting periods with open/close status';

-- Indexes
CREATE INDEX idx_ledger_periods_year ON public.ledger_periods(fiscal_year, fiscal_period);
CREATE INDEX idx_ledger_periods_open ON public.ledger_periods(is_open) WHERE is_open = true;

-- Trigger for updated_at
CREATE TRIGGER update_ledger_periods_timestamp
    BEFORE UPDATE ON public.ledger_periods
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.ledger_periods ENABLE ROW LEVEL SECURITY;

