-- -----------------------------------------------------------------------------
-- Enum: feature_flag_status
-- Description: Defines the lifecycle status of a feature flag
-- Business Case: Manages feature flags from creation through deprecation
-- Feature Reference: FF-01 (Feature Flag Lifecycle)
-- -----------------------------------------------------------------------------
CREATE TYPE public.feature_flag_status AS ENUM (
    'DRAFT',           -- Flag created but not yet active
    'ACTIVE',          -- Flag is actively being evaluated
    'PAUSED',          -- Temporarily disabled for investigation
    'ROLLING_OUT',     -- Gradually increasing rollout percentage
    'ROLLED_BACK',     -- Feature was rolled back, flag remains for cleanup
    'PERMANENT',       -- Feature is permanent (flag always true)
    'DEPRECATED',      -- Flag no longer used, pending removal
    'ARCHIVED'         -- Flag removed from system
);
COMMENT ON TYPE public.feature_flag_status IS 'Lifecycle states of feature flags from creation to removal';

-- -----------------------------------------------------------------------------
-- Enum: flag_evaluation_reason
-- Description: Reasons for feature flag evaluation results
-- Business Case: Understand why a particular variant was returned
-- Feature Reference: FF-02 (Flag Evaluation)
-- -----------------------------------------------------------------------------
CREATE TYPE public.flag_evaluation_reason AS ENUM (
    'TARGETING_MATCH',      -- User matched targeting rules
    'ROLLOUT_PERCENTAGE',   -- Assigned via percentage rollout
    'DEFAULT',               -- Default value used
    'DISABLED',              -- Flag is disabled
    'ERROR',                 -- Error during evaluation
    'PREREQUISITE_FAILED',   -- Prerequisite flag not satisfied
    'EXPERIMENT_BUCKET'      -- Assigned as part of A/B test
);
COMMENT ON TYPE public.flag_evaluation_reason IS 'Reasons for feature flag evaluation results';

-- -----------------------------------------------------------------------------
-- Enum: service_status
-- Description: Operational status of a microservice
-- Business Case: Track service health for monitoring and incident response
-- Feature Reference: SD-01 (Service Health)
-- -----------------------------------------------------------------------------
CREATE TYPE public.service_status AS ENUM (
    'HEALTHY',           -- Service operating normally
    'DEGRADED',          -- Service operating with reduced capacity
    'UNHEALTHY',         -- Service experiencing issues
    'DOWN',              -- Service completely unavailable
    'MAINTENANCE',       -- Under scheduled maintenance
    'STARTING',          -- Service is starting up
    'STOPPING'           -- Service is shutting down
);
COMMENT ON TYPE public.service_status IS 'Operational status of microservices';

-- -----------------------------------------------------------------------------
-- Enum: circuit_breaker_state
-- Description: States of a circuit breaker for fault tolerance
-- Business Case: Prevent cascading failures by tracking service dependency health
-- Feature Reference: CB-01 (Circuit Breaker)
-- -----------------------------------------------------------------------------
CREATE TYPE public.circuit_breaker_state AS ENUM (
    'CLOSED',            -- Normal operation, requests allowed
    'OPEN',              -- Circuit is open, requests fail fast
    'HALF_OPEN',         -- Testing if service recovered
    'DISABLED',          -- Circuit breaker disabled
    'FORCED_OPEN'        -- Manually forced open (maintenance)
);
COMMENT ON TYPE public.circuit_breaker_state IS 'States of circuit breakers for fault tolerance';

-- -----------------------------------------------------------------------------
-- Enum: dead_letter_status
-- Description: Status of failed messages in dead letter queue
-- Business Case: Track resolution of failed background jobs
-- Feature Reference: DLQ-01 (Dead Letter Queue)
-- -----------------------------------------------------------------------------
CREATE TYPE public.dead_letter_status AS ENUM (
    'PENDING_RETRY',     -- Awaiting next retry attempt
    'RETRYING',          -- Currently being retried
    'FAILED_PERMANENT',  -- Permanently failed, requires manual intervention
    'RESOLVED',          -- Successfully processed after retry
    'IGNORED',           -- Manually marked as ignored
    'ARCHIVED'           -- Moved to long-term storage
);
COMMENT ON TYPE public.dead_letter_status IS 'Status of failed messages in dead letter queue';

-- -----------------------------------------------------------------------------
-- Enum: sync_queue_status
-- Description: Status of items in synchronization queues
-- Business Case: Track processing of async sync jobs
-- Feature Reference: SYNC-01 (Sync Queue)
-- -----------------------------------------------------------------------------
CREATE TYPE public.sync_queue_status AS ENUM (
    'PENDING',           -- Awaiting processing
    'PROCESSING',        -- Currently being processed
    'COMPLETED',         -- Successfully processed
    'FAILED',            -- Failed processing
    'RETRY',             -- Will be retried
    'SKIPPED',           -- Skipped (e.g., obsolete)
    'CANCELLED'          -- Cancelled before processing
);
COMMENT ON TYPE public.sync_queue_status IS 'Status of items in synchronization queues';

-- -----------------------------------------------------------------------------
-- Enum: webhook_delivery_status
-- Description: Status of webhook delivery attempts
-- Business Case: Track reliability of outgoing webhooks
-- Feature Reference: WH-01 (Webhook Delivery)
-- -----------------------------------------------------------------------------
CREATE TYPE public.webhook_delivery_status AS ENUM (
    'PENDING',           -- Awaiting delivery
    'DELIVERING',        -- Currently being delivered
    'DELIVERED',         -- Successfully delivered (2xx response)
    'FAILED',            -- Failed delivery (non-2xx response)
    'RETRYING',          -- Will be retried
    'EXPIRED',           -- Expired after max retries
    'CANCELLED'          -- Cancelled before delivery
);
COMMENT ON TYPE public.webhook_delivery_status IS 'Status of webhook delivery attempts';

-- -----------------------------------------------------------------------------
-- Enum: cache_invalidation_reason
-- Description: Reasons for cache invalidation
-- Business Case: Track why cache entries are being invalidated
-- Feature Reference: CACHE-01 (Cache Invalidation)
-- -----------------------------------------------------------------------------
CREATE TYPE public.cache_invalidation_reason AS ENUM (
    'DATA_UPDATE',       -- Underlying data changed
    'DATA_DELETE',       -- Underlying data deleted
    'TTL_EXPIRED',       -- Time-to-live expired
    'MANUAL',            -- Manual invalidation
    'CACHE_FULL',        -- Cache full, LRU eviction
    'VERSION_CHANGE',    -- Data version changed
    'SCHEMA_CHANGE'      -- Data schema changed
);
COMMENT ON TYPE public.cache_invalidation_reason IS 'Reasons for cache invalidation events';

-- -----------------------------------------------------------------------------
-- Enum: migration_environment
-- Description: Environments for database migrations
-- Business Case: Track migrations across different environments
-- Feature Reference: MIG-01 (Migration Environments)
-- -----------------------------------------------------------------------------
CREATE TYPE public.migration_environment AS ENUM (
    'LOCAL',             -- Developer local environment
    'DEVELOPMENT',       -- Shared development
    'TEST',              -- Automated testing
    'STAGING',           -- Pre-production staging
    'PRODUCTION',        -- Production
    'DR'                 -- Disaster recovery
);
COMMENT ON TYPE public.migration_environment IS 'Environments where database migrations run';

-- =============================================================================
-- TABLE: 19 - feature_flags (enhanced)
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 19
-- Table Name: feature_flags
-- Description: Enhanced feature flag system with gradual rollout, targeting rules,
--              A/B testing capabilities, and full lifecycle management.
--
-- Business Case: Feature flags are essential for modern DevOps practices,
--                enabling safe deployments, canary releases, and kill switches.
--                This enhanced table provides enterprise-grade feature flag
--                management with:
--                1) Gradual rollouts with percentage-based targeting,
--                2) User/group/attribute-based targeting rules,
--                3) A/B testing variant support,
--                4) Prerequisite flag dependencies,
--                5) Scheduled activation/deactivation,
--                6) Environment-specific configurations,
--                7) Audit trail of all changes,
--                8) Integration with experiment management.
--                The system allows product managers to release features to
--                specific user segments (e.g., beta users, enterprise customers)
--                and gradually increase rollout while monitoring metrics.
--                Kill switches provide immediate rollback capability without
--                code deployment. The targeting engine supports complex rules
--                using JSON conditions (e.g., country = 'US' AND subscription
--                tier IN ('premium', 'enterprise')). For A/B tests, flags can
--                return multiple variants with weighted distribution.
--                Prerequisite flags enable feature dependencies (e.g., new
--                checkout depends on payment service flag). This table is the
--                source of truth for the feature flag evaluation service.
--
-- KPIs:
--   1. Number of active feature flags (target: < 100 to avoid complexity)
--   2. Time to rollback a feature using kill switch < 1 minute
--   3. Flag evaluation latency (p99 < 10ms with caching)
--   4. Percentage of flags with >90% rollout (successful releases)
--   5. Number of rollbacks per quarter (decreasing trend)
--   6. Flag coverage (percentage of features behind flags) > 80%
--   7. Time to remove deprecated flags < 30 days after full rollout
--
-- Feature Reference: FF-01 (Feature Flag Management)
--                  : FF-02 (Gradual Rollout)
--                  : FF-03 (Targeting Rules)
--                  : FF-04 (A/B Testing)
--                  : FF-05 (Kill Switch)
-- -----------------------------------------------------------------------------
CREATE TABLE public.feature_flags (
    -- Primary key
    flag_id           UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Core identification
    flag_key          VARCHAR(255) NOT NULL,           -- e.g., 'new-checkout-experience'
    flag_name         VARCHAR(255) NOT NULL,
    description       TEXT,

    -- Ownership
    owner_team        VARCHAR(100) NOT NULL,           -- Team responsible
    owner_user_id     UUID,                             -- Individual owner
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Status and lifecycle
    status            public.feature_flag_status NOT NULL DEFAULT 'DRAFT',
    version           INTEGER NOT NULL DEFAULT 1,
    deprecated_at     TIMESTAMP WITH TIME ZONE,
    deprecated_by     UUID,
    deprecation_reason TEXT,

    -- Environments
    environment       VARCHAR(50) NOT NULL CHECK (environment IN ('development', 'staging', 'production')),
    is_enabled        BOOLEAN DEFAULT false,            -- Master switch

    -- Rollout configuration
    rollout_strategy  VARCHAR(50) CHECK (rollout_strategy IN ('percentage', 'targeted', 'experiment', 'manual')),
    rollout_percentage INTEGER CHECK (rollout_percentage BETWEEN 0 AND 100),
    rollout_started_at TIMESTAMP WITH TIME ZONE,
    rollout_completed_at TIMESTAMP WITH TIME ZONE,

    -- Targeting rules (JSON for flexibility)
    targeting_rules   JSONB,                             -- Complex targeting conditions
    target_users      UUID[],                             -- Specific user IDs
    target_groups     UUID[],                             -- Group IDs
    target_attributes JSONB,                              -- e.g., {"country": "US", "tier": "premium"}

    -- A/B testing
    experiment_id     UUID,                                -- Link to experiments table
    variants          JSONB,                               -- e.g., [{"name": "control", "weight": 50}, {"name": "treatment", "weight": 50}]
    default_variant   VARCHAR(100),                        -- Default if no match

    -- Dependencies
    prerequisite_flags UUID[],                             -- Flags that must be true
    conflict_flags    UUID[],                               -- Flags that cannot be true simultaneously

    -- Scheduling
    scheduled_activation_at TIMESTAMP WITH TIME ZONE,
    scheduled_deactivation_at TIMESTAMP WITH TIME ZONE,
    time_restrictions  JSONB,                              -- Time-based availability

    -- Kill switch configuration
    kill_switch_enabled BOOLEAN DEFAULT true,
    kill_switch_activated_at TIMESTAMP WITH TIME ZONE,
    kill_switch_activated_by UUID,
    kill_switch_reason TEXT,

    -- Monitoring and alerting
    alert_on_evaluation_failure BOOLEAN DEFAULT true,
    alert_threshold_errors INTEGER DEFAULT 100,            -- Errors per minute
    metrics_endpoint  VARCHAR(255),                         -- Where to send metrics

    -- Performance
    cache_ttl_seconds INTEGER DEFAULT 60,                   -- How long to cache evaluation
    stale_while_revalidate BOOLEAN DEFAULT true,            -- Serve stale while refreshing

    -- Audit
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_evaluated_at TIMESTAMP WITH TIME ZONE,
    evaluation_count  BIGINT DEFAULT 0,

    -- Constraints
    CONSTRAINT uq_feature_flag_key UNIQUE (flag_key, environment),
    CONSTRAINT chk_rollout_percentage CHECK (
        (rollout_strategy = 'percentage' AND rollout_percentage IS NOT NULL) OR
        (rollout_strategy != 'percentage' AND rollout_percentage IS NULL)
    ),
    CONSTRAINT chk_experiment_variants CHECK (
        (experiment_id IS NOT NULL AND variants IS NOT NULL) OR
        (experiment_id IS NULL)
    ),
    CONSTRAINT fk_feature_flags_owner FOREIGN KEY (owner_user_id)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flags_experiment FOREIGN KEY (experiment_id)
        REFERENCES public.experiments(experiment_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flags_deprecated_by FOREIGN KEY (deprecated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_feature_flags_kill_switch_by FOREIGN KEY (kill_switch_activated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for feature_flags table
COMMENT ON TABLE public.feature_flags IS 'Enhanced feature flag system with gradual rollout, targeting, and A/B testing';
COMMENT ON COLUMN public.feature_flags.flag_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.feature_flags.flag_key IS 'Unique key for the flag (used in code)';
COMMENT ON COLUMN public.feature_flags.flag_name IS 'Human-readable name';
COMMENT ON COLUMN public.feature_flags.description IS 'Detailed description of the feature';
COMMENT ON COLUMN public.feature_flags.owner_team IS 'Team responsible for this flag';
COMMENT ON COLUMN public.feature_flags.owner_user_id IS 'Individual owner (if applicable)';
COMMENT ON COLUMN public.feature_flags.status IS 'Current lifecycle status';
COMMENT ON COLUMN public.feature_flags.version IS 'Version number for tracking changes';
COMMENT ON COLUMN public.feature_flags.deprecated_at IS 'When flag was deprecated';
COMMENT ON COLUMN public.feature_flags.deprecated_by IS 'Who deprecated the flag';
COMMENT ON COLUMN public.feature_flags.deprecation_reason IS 'Why flag was deprecated';
COMMENT ON COLUMN public.feature_flags.environment IS 'Environment where flag applies';
COMMENT ON COLUMN public.feature_flags.is_enabled IS 'Master enable/disable switch';
COMMENT ON COLUMN public.feature_flags.rollout_strategy IS 'Strategy for gradual rollout';
COMMENT ON COLUMN public.feature_flags.rollout_percentage IS 'Percentage of users to enable for';
COMMENT ON COLUMN public.feature_flags.rollout_started_at IS 'When rollout began';
COMMENT ON COLUMN public.feature_flags.rollout_completed_at IS 'When rollout completed (100%)';
COMMENT ON COLUMN public.feature_flags.targeting_rules IS 'JSON conditions for targeting';
COMMENT ON COLUMN public.feature_flags.target_users IS 'Specific users to enable for';
COMMENT ON COLUMN public.feature_flags.target_groups IS 'Specific groups to enable for';
COMMENT ON COLUMN public.feature_flags.target_attributes IS 'Attribute-based targeting';
COMMENT ON COLUMN public.feature_flags.experiment_id IS 'Linked A/B test experiment';
COMMENT ON COLUMN public.feature_flags.variants IS 'Variant definitions for A/B tests';
COMMENT ON COLUMN public.feature_flags.default_variant IS 'Default variant when no match';
COMMENT ON COLUMN public.feature_flags.prerequisite_flags IS 'Flags that must be true';
COMMENT ON COLUMN public.feature_flags.conflict_flags IS 'Flags that cannot be true';
COMMENT ON COLUMN public.feature_flags.scheduled_activation_at IS 'When flag auto-activates';
COMMENT ON COLUMN public.feature_flags.scheduled_deactivation_at IS 'When flag auto-deactivates';
COMMENT ON COLUMN public.feature_flags.time_restrictions IS 'Time-based availability rules';
COMMENT ON COLUMN public.feature_flags.kill_switch_enabled IS 'Whether kill switch is available';
COMMENT ON COLUMN public.feature_flags.kill_switch_activated_at IS 'When kill switch was activated';
COMMENT ON COLUMN public.feature_flags.kill_switch_activated_by IS 'Who activated kill switch';
COMMENT ON COLUMN public.feature_flags.kill_switch_reason IS 'Why kill switch was activated';
COMMENT ON COLUMN public.feature_flags.alert_on_evaluation_failure IS 'Whether to alert on errors';
COMMENT ON COLUMN public.feature_flags.alert_threshold_errors IS 'Error threshold for alerts';
COMMENT ON COLUMN public.feature_flags.metrics_endpoint IS 'Endpoint for sending metrics';
COMMENT ON COLUMN public.feature_flags.cache_ttl_seconds IS 'Cache duration for evaluations';
COMMENT ON COLUMN public.feature_flags.stale_while_revalidate IS 'Serve stale while refreshing';
COMMENT ON COLUMN public.feature_flags.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.feature_flags.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.feature_flags.last_evaluated_at IS 'Last time flag was evaluated';
COMMENT ON COLUMN public.feature_flags.evaluation_count IS 'Number of evaluations';

-- Indexes for feature_flags table
CREATE INDEX idx_feature_flags_key ON public.feature_flags(flag_key, environment);
CREATE INDEX idx_feature_flags_status ON public.feature_flags(status, environment);
CREATE INDEX idx_feature_flags_owner ON public.feature_flags(owner_team, owner_user_id);
CREATE INDEX idx_feature_flags_experiment ON public.feature_flags(experiment_id) WHERE experiment_id IS NOT NULL;
CREATE INDEX idx_feature_flags_scheduled ON public.feature_flags(scheduled_activation_at, scheduled_deactivation_at)
    WHERE scheduled_activation_at IS NOT NULL OR scheduled_deactivation_at IS NOT NULL;

-- GIN indexes for JSON and array searches
CREATE INDEX idx_feature_flags_targeting ON public.feature_flags USING gin(targeting_rules);
CREATE INDEX idx_feature_flags_target_users ON public.feature_flags USING gin(target_users);
CREATE INDEX idx_feature_flags_target_groups ON public.feature_flags USING gin(target_groups);
CREATE INDEX idx_feature_flags_prereq ON public.feature_flags USING gin(prerequisite_flags);

-- Partial index for active flags
CREATE INDEX idx_feature_flags_active ON public.feature_flags(flag_key, environment)
    WHERE status IN ('ACTIVE', 'ROLLING_OUT');

-- Trigger for updated_at
CREATE TRIGGER update_feature_flags_timestamp
    BEFORE UPDATE ON public.feature_flags
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.feature_flags ENABLE ROW LEVEL SECURITY;

-- Policy: Team members can manage their flags
CREATE POLICY feature_flags_team_policy ON public.feature_flags
    USING (owner_team IN (SELECT team FROM public.user_teams WHERE user_id = current_user_id()));

-- Policy: Admins can manage all flags
CREATE POLICY feature_flags_admin_policy ON public.feature_flags
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'product_manager')
    ));

-- Policy: Read-only for everyone else (for evaluation service)
CREATE POLICY feature_flags_readonly_policy ON public.feature_flags
    FOR SELECT USING (true);

-- =============================================================================
-- TABLE: 20 - feature_flag_evaluations
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 20
-- Table Name: feature_flag_evaluations
-- Description: Logs all feature flag evaluations for analysis, debugging,
--              and understanding feature adoption patterns.
--
-- Business Case: To make data-driven decisions about feature rollouts and
--                A/B tests, we need to know which users saw which variants
--                and when. This table captures every feature flag evaluation,
--                providing:
--                1) Adoption metrics (percentage of users seeing feature),
--                2) A/B test exposure tracking,
--                3) Debugging capability (why a user got a particular variant),
--                4) Performance monitoring (evaluation latency),
--                5) Anomaly detection (unusual evaluation patterns),
--                6) Compliance evidence (who saw what, when),
--                7) Rollout verification (ensuring correct percentages).
--                The data feeds into analytics dashboards to measure feature
--                success, detect issues (e.g., low adoption indicating problems),
--                and optimize targeting rules. For A/B tests, it's the source
--                of truth for experiment exposure, enabling accurate analysis
--                of treatment effects. The table is write-heavy but queried
--                primarily for analytics, so it's partitioned by time and
--                uses columnar compression for long-term storage.
--
-- KPIs:
--   1. Evaluation volume (flags evaluated per second)
--   2. Evaluation latency (p99 < 10ms with caching)
--   3. Percentage of evaluations that hit cache > 90%
--   4. Data completeness for A/B tests (exposure logged for 100% of participants)
--   5. Time to detect anomalous evaluation patterns < 5 minutes
--   6. Query performance for analytics (1 month of data < 10 seconds)
--   7. Storage growth rate (GB per month)
--
-- Feature Reference: FF-06 (Flag Analytics)
--                  : FF-07 (Adoption Tracking)
--                  : FF-08 (A/B Test Exposure)
--                  : FF-09 (Debug Logging)
-- -----------------------------------------------------------------------------
CREATE TABLE public.feature_flag_evaluations (
    -- Primary key (using composite for partitioning)
    evaluation_id     UUID NOT NULL,
    evaluation_date   DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Flag information
    flag_id           UUID NOT NULL,
    flag_key          VARCHAR(255) NOT NULL,
    flag_version      INTEGER NOT NULL,

    -- User context
    user_id           UUID,
    session_id        UUID,
    anonymous_id      VARCHAR(255),                        -- For unauthenticated users

    -- Evaluation result
    result_value      BOOLEAN NOT NULL,
    variant           VARCHAR(100),                          -- For A/B tests
    reason            public.flag_evaluation_reason NOT NULL,

    -- Evaluation context
    context           JSONB,                                 -- What data was used
    targeting_rules_applied JSONB,                            -- Which rules matched

    -- Performance
    evaluation_time_ms INTEGER NOT NULL,                     -- How long evaluation took
    cache_hit         BOOLEAN DEFAULT false,

    -- Request information
    evaluated_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    ip_address        INET,
    user_agent        TEXT,

    -- Environment
    environment       VARCHAR(50) NOT NULL,

    -- Error tracking
    error_message     TEXT,
    error_stack       TEXT,

    -- Metadata
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Partition key
    PRIMARY KEY (evaluation_id, evaluation_date)
) PARTITION BY RANGE (evaluation_date);

-- Comments for feature_flag_evaluations table
COMMENT ON TABLE public.feature_flag_evaluations IS 'Logs all feature flag evaluations for analytics and debugging';
COMMENT ON COLUMN public.feature_flag_evaluations.evaluation_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.feature_flag_evaluations.evaluation_date IS 'Date of evaluation (partition key)';
COMMENT ON COLUMN public.feature_flag_evaluations.flag_id IS 'ID of evaluated flag';
COMMENT ON COLUMN public.feature_flag_evaluations.flag_key IS 'Key of evaluated flag (denormalized)';
COMMENT ON COLUMN public.feature_flag_evaluations.flag_version IS 'Version of flag at evaluation time';
COMMENT ON COLUMN public.feature_flag_evaluations.user_id IS 'User who was evaluated';
COMMENT ON COLUMN public.feature_flag_evaluations.session_id IS 'Session during evaluation';
COMMENT ON COLUMN public.feature_flag_evaluations.anonymous_id IS 'Anonymous identifier';
COMMENT ON COLUMN public.feature_flag_evaluations.result_value IS 'Boolean result of evaluation';
COMMENT ON COLUMN public.feature_flag_evaluations.variant IS 'Variant returned (for A/B tests)';
COMMENT ON COLUMN public.feature_flag_evaluations.reason IS 'Why this result was returned';
COMMENT ON COLUMN public.feature_flag_evaluations.context IS 'Context data used in evaluation';
COMMENT ON COLUMN public.feature_flag_evaluations.targeting_rules_applied IS 'Which rules matched';
COMMENT ON COLUMN public.feature_flag_evaluations.evaluation_time_ms IS 'Time taken to evaluate';
COMMENT ON COLUMN public.feature_flag_evaluations.cache_hit IS 'Whether result came from cache';
COMMENT ON COLUMN public.feature_flag_evaluations.evaluated_at IS 'When evaluation occurred';
COMMENT ON COLUMN public.feature_flag_evaluations.ip_address IS 'Client IP address';
COMMENT ON COLUMN public.feature_flag_evaluations.user_agent IS 'Client user agent';
COMMENT ON COLUMN public.feature_flag_evaluations.environment IS 'Environment of evaluation';
COMMENT ON COLUMN public.feature_flag_evaluations.error_message IS 'Error if evaluation failed';
COMMENT ON COLUMN public.feature_flag_evaluations.error_stack IS 'Stack trace if error';
COMMENT ON COLUMN public.feature_flag_evaluations.created_at IS 'Timestamp of log creation';

-- Function to create monthly partitions
CREATE OR REPLACE FUNCTION public.create_flag_eval_partition(p_year INTEGER, p_month INTEGER)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date DATE;
    end_date DATE;
BEGIN
    partition_name := 'feature_flag_evaluations_' || p_year || '_' || LPAD(p_month::TEXT, 2, '0');
    start_date := MAKE_DATE(p_year, p_month, 1);

    IF p_month = 12 THEN
        end_date := MAKE_DATE(p_year + 1, 1, 1);
    ELSE
        end_date := MAKE_DATE(p_year, p_month + 1, 1);
    END IF;

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.feature_flag_evaluations
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create indexes on the partition
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_flag_user ON public.%I(flag_id, user_id)',
        partition_name, partition_name
    );

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_evaluated_at ON public.%I(evaluated_at)',
        partition_name, partition_name
    );
END;
$$ LANGUAGE plpgsql;

