SELECT public.create_flag_eval_partition(EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER + 1, 11);
SELECT public.create_flag_eval_partition(EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER + 1, 12);

-- Create default partition
CREATE TABLE public.feature_flag_evaluations_default PARTITION OF public.feature_flag_evaluations DEFAULT;

-- Global indexes
CREATE INDEX idx_flag_eval_flag_user ON public.feature_flag_evaluations(flag_id, user_id);
CREATE INDEX idx_flag_eval_evaluated_at ON public.feature_flag_evaluations(evaluated_at);
CREATE INDEX idx_flag_eval_reason ON public.feature_flag_evaluations(reason);
CREATE INDEX idx_flag_eval_context ON public.feature_flag_evaluations USING gin(context);

-- Enable RLS
ALTER TABLE public.feature_flag_evaluations ENABLE ROW LEVEL SECURITY;

