CREATE POLICY flag_eval_user_policy ON public.feature_flag_evaluations
    FOR SELECT USING (user_id = current_user_id());

-- Policy: Analytics team can see all
CREATE POLICY flag_eval_analytics_policy ON public.feature_flag_evaluations
    FOR SELECT USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('analyst', 'product_manager', 'admin')
    ));

-- =============================================================================
-- TABLE: 21 - service_dependencies
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 21
-- Table Name: service_dependencies
-- Description: Maps dependencies between microservices for impact analysis,
--              circuit breaking, and incident response.
--
-- Business Case: In a microservices architecture, understanding service
--                dependencies is critical for:
--                1) Incident response - knowing which services are affected,
--                2) Change management - assessing impact of updates,
--                3) Capacity planning - understanding traffic flows,
--                4) Circuit breaking - configuring failure thresholds,
--                5) Chaos engineering - identifying critical paths,
--                6) SLA management - calculating composite SLAs,
--                7) Migration planning - understanding coupling.
--                This table provides the authoritative dependency graph,
--                including dependency types (hard vs soft), version constraints,
--                and traffic patterns. It enables automated impact analysis:
--                when Service A fails, we can immediately identify all
--                downstream dependencies. For circuit breakers, it defines
--                thresholds (e.g., 50% failure rate for 30 seconds). The table
--                also tracks dependency health metrics and last verified status
--                to detect drift between documented and actual dependencies.
--                Integration with service mesh and monitoring tools ensures
--                the dependency graph stays accurate. For compliance, it
--                supports data flow mapping for GDPR and security audits.
--
-- KPIs:
--   1. Dependency coverage (percentage of services with documented deps) > 95%
--   2. Time to identify impacted services during outage < 1 minute
--   3. Number of circular dependencies detected (should be zero)
--   4. Dependency drift (documented vs actual) < 5%
--   5. Time to update dependencies after service changes < 24 hours
--   6. Critical path length (max dependencies in chain) - monitor for complexity
--   7. Dependency freshness (last verified timestamp) < 7 days
--
-- Feature Reference: SD-01 (Service Discovery)
--                  : SD-02 (Dependency Mapping)
--                  : SD-03 (Impact Analysis)
--                  : SD-04 (Circuit Breaker Configuration)
--                  : SD-05 (Data Flow Mapping)
-- -----------------------------------------------------------------------------
CREATE TABLE public.service_dependencies (
    -- Primary key
    dependency_id     UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Service identification
    service_name      VARCHAR(255) NOT NULL,
    service_version   VARCHAR(50),
    service_namespace VARCHAR(100),                        -- e.g., 'production', 'staging'

    -- Dependency target
    depends_on_service VARCHAR(255) NOT NULL,
    depends_on_version VARCHAR(50),
    depends_on_namespace VARCHAR(100),

    -- Dependency metadata
    dependency_type   public.service_dependency_type NOT NULL,
    criticality       VARCHAR(20) CHECK (criticality IN ('critical', 'high', 'medium', 'low')),
    description       TEXT,

    -- Traffic patterns
    average_rps       INTEGER,                             -- Requests per second
    peak_rps          INTEGER,
    data_volume_mb_per_sec NUMERIC(10,2),

    -- Circuit breaker configuration
    circuit_breaker_name VARCHAR(255),                     -- Reference to circuit_breakers table
    failure_threshold_percentage NUMERIC(5,2) CHECK (failure_threshold_percentage BETWEEN 0 AND 100),
    failure_threshold_count INTEGER,
    window_size_seconds INTEGER,
    minimum_requests   INTEGER,
    slow_call_threshold_ms INTEGER,

    -- Timeout configuration
    timeout_ms        INTEGER,
    connect_timeout_ms INTEGER,
    read_timeout_ms   INTEGER,
    write_timeout_ms  INTEGER,

    -- Retry configuration
    retry_enabled     BOOLEAN DEFAULT false,
    max_retries       INTEGER,
    retry_backoff_ms  INTEGER,
    retry_on_timeout  BOOLEAN DEFAULT false,

    -- Load balancing
    load_balancer_strategy VARCHAR(50) CHECK (load_balancer_strategy IN ('round_robin', 'least_conn', 'random', 'consistent_hash')),
    healthy_endpoints INTEGER,
    total_endpoints   INTEGER,

    -- Version compatibility
    min_compatible_version VARCHAR(50),
    max_compatible_version VARCHAR(50),
    breaking_changes   TEXT[],                              -- Known breaking changes

    -- Health checks
    health_check_path VARCHAR(255),
    health_check_interval INTEGER,                           -- Seconds
    health_check_timeout INTEGER,                            -- Seconds
    health_check_status VARCHAR(20) CHECK (health_check_status IN ('healthy', 'degraded', 'unhealthy', 'unknown')),
    last_health_check_at TIMESTAMP WITH TIME ZONE,

    -- Validation
    last_verified_at  TIMESTAMP WITH TIME ZONE,
    verified_by       UUID,
    verification_method VARCHAR(50) CHECK (verification_method IN ('manual', 'traffic_analysis', 'service_mesh', 'testing')),

    -- Metadata
    tags              TEXT[],
    documentation_url VARCHAR(255),
    owner_team        VARCHAR(100),

    -- Audit
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,
    deprecated_at     TIMESTAMP WITH TIME ZONE,
    deprecated_by     UUID,

    -- Constraints
    CONSTRAINT uq_service_dependency UNIQUE (service_name, service_namespace, depends_on_service, depends_on_namespace),
    CONSTRAINT chk_circuit_breaker CHECK (
        (failure_threshold_percentage IS NOT NULL AND window_size_seconds IS NOT NULL) OR
        circuit_breaker_name IS NOT NULL OR
        (failure_threshold_percentage IS NULL AND circuit_breaker_name IS NULL)
    ),
    CONSTRAINT fk_service_deps_verified_by FOREIGN KEY (verified_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_service_deps_deprecated_by FOREIGN KEY (deprecated_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for service_dependencies table
COMMENT ON TABLE public.service_dependencies IS 'Maps dependencies between microservices for impact analysis and circuit breaking';
COMMENT ON COLUMN public.service_dependencies.dependency_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.service_dependencies.service_name IS 'Name of the dependent service';
COMMENT ON COLUMN public.service_dependencies.service_version IS 'Version of dependent service';
COMMENT ON COLUMN public.service_dependencies.service_namespace IS 'Namespace/environment of service';
COMMENT ON COLUMN public.service_dependencies.depends_on_service IS 'Name of the service being depended upon';
COMMENT ON COLUMN public.service_dependencies.depends_on_version IS 'Version requirement of dependency';
COMMENT ON COLUMN public.service_dependencies.depends_on_namespace IS 'Namespace of dependency';
COMMENT ON COLUMN public.service_dependencies.dependency_type IS 'Hard, soft, or optional dependency';
COMMENT ON COLUMN public.service_dependencies.criticality IS 'Business criticality of dependency';
COMMENT ON COLUMN public.service_dependencies.description IS 'Description of dependency purpose';
COMMENT ON COLUMN public.service_dependencies.average_rps IS 'Average requests per second';
COMMENT ON COLUMN public.service_dependencies.peak_rps IS 'Peak requests per second';
COMMENT ON COLUMN public.service_dependencies.data_volume_mb_per_sec IS 'Data transfer volume';
COMMENT ON COLUMN public.service_dependencies.circuit_breaker_name IS 'Name of circuit breaker configuration';
COMMENT ON COLUMN public.service_dependencies.failure_threshold_percentage IS 'Failure percentage to open circuit';
COMMENT ON COLUMN public.service_dependencies.failure_threshold_count IS 'Failure count to open circuit';
COMMENT ON COLUMN public.service_dependencies.window_size_seconds IS 'Time window for failure counting';
COMMENT ON COLUMN public.service_dependencies.minimum_requests IS 'Minimum requests before evaluating';
COMMENT ON COLUMN public.service_dependencies.slow_call_threshold_ms IS 'Threshold for slow calls';
COMMENT ON COLUMN public.service_dependencies.timeout_ms IS 'Total request timeout';
COMMENT ON COLUMN public.service_dependencies.connect_timeout_ms IS 'Connection timeout';
COMMENT ON COLUMN public.service_dependencies.read_timeout_ms IS 'Read timeout';
COMMENT ON COLUMN public.service_dependencies.write_timeout_ms IS 'Write timeout';
COMMENT ON COLUMN public.service_dependencies.retry_enabled IS 'Whether retries are enabled';
COMMENT ON COLUMN public.service_dependencies.max_retries IS 'Maximum number of retries';
COMMENT ON COLUMN public.service_dependencies.retry_backoff_ms IS 'Backoff between retries (ms)';
COMMENT ON COLUMN public.service_dependencies.retry_on_timeout IS 'Whether to retry on timeout';
COMMENT ON COLUMN public.service_dependencies.load_balancer_strategy IS 'Load balancing algorithm';
COMMENT ON COLUMN public.service_dependencies.healthy_endpoints IS 'Number of healthy endpoints';
COMMENT ON COLUMN public.service_dependencies.total_endpoints IS 'Total endpoints available';
COMMENT ON COLUMN public.service_dependencies.min_compatible_version IS 'Minimum compatible version';
COMMENT ON COLUMN public.service_dependencies.max_compatible_version IS 'Maximum compatible version';
COMMENT ON COLUMN public.service_dependencies.breaking_changes IS 'Known breaking changes between versions';
COMMENT ON COLUMN public.service_dependencies.health_check_path IS 'Path for health checks';
COMMENT ON COLUMN public.service_dependencies.health_check_interval IS 'Seconds between health checks';
COMMENT ON COLUMN public.service_dependencies.health_check_timeout IS 'Timeout for health checks';
COMMENT ON COLUMN public.service_dependencies.health_check_status IS 'Current health status';
COMMENT ON COLUMN public.service_dependencies.last_health_check_at IS 'Last health check time';
COMMENT ON COLUMN public.service_dependencies.last_verified_at IS 'When dependency was last verified';
COMMENT ON COLUMN public.service_dependencies.verified_by IS 'Who verified the dependency';
COMMENT ON COLUMN public.service_dependencies.verification_method IS 'How dependency was verified';
COMMENT ON COLUMN public.service_dependencies.tags IS 'Tags for categorization';
COMMENT ON COLUMN public.service_dependencies.documentation_url IS 'URL to documentation';
COMMENT ON COLUMN public.service_dependencies.owner_team IS 'Team owning this dependency';
COMMENT ON COLUMN public.service_dependencies.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.service_dependencies.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.service_dependencies.created_by IS 'User who created the record';
COMMENT ON COLUMN public.service_dependencies.updated_by IS 'User who last updated the record';
COMMENT ON COLUMN public.service_dependencies.deprecated_at IS 'When this dependency was deprecated';
COMMENT ON COLUMN public.service_dependencies.deprecated_by IS 'Who deprecated this dependency';

-- Indexes for service_dependencies table
CREATE INDEX idx_service_deps_service ON public.service_dependencies(service_name, service_namespace);
