CREATE POLICY service_deps_platform_policy ON public.service_dependencies
    USING (owner_team IN (SELECT team FROM public.user_teams WHERE user_id = current_user_id()) OR
           EXISTS (SELECT 1 FROM public.user_roles ur
                   JOIN public.roles r ON ur.role_id = r.role_id
                   WHERE ur.user_id = current_user_id() AND r.name IN ('platform_admin', 'admin')));

-- Policy: Read-only for everyone else
CREATE POLICY service_deps_readonly_policy ON public.service_dependencies
    FOR SELECT USING (true);

-- =============================================================================
-- TABLE: 22 - circuit_breakers
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 22
-- Table Name: circuit_breakers
-- Description: Tracks circuit breaker states for service dependencies to
--              prevent cascading failures in distributed systems.
--
-- Business Case: In a microservices architecture, failures can cascade
--                rapidly. Circuit breakers prevent this by failing fast
--                when a dependency is unhealthy. This table maintains the
--                state of all circuit breakers, enabling:
--                1) Real-time visibility into system health,
--                2) Automated failure prevention,
--                3) Manual override for emergency situations,
--                4) Historical analysis of failure patterns,
--                5) Capacity planning for degraded operations,
--                6) Incident response with immediate context,
--                7) Performance optimization during partial outages.
--                The table stores current state (closed, open, half-open),
--                failure counts, and success rates. It integrates with
--                monitoring systems to alert when circuits open. The half-open
--                state allows testing recovery by letting a few requests
--                through. Configuration parameters (failure threshold, window
--                size) can be tuned per dependency based on business criticality.
--                Historical data helps identify problematic dependencies and
--                plan improvements. During incidents, operators can manually
--                open circuits to protect systems or force them closed for
--                emergency access.
--
-- KPIs:
--   1. Circuit open events per day (monitor for trends)
--   2. Average time to recovery (from open to closed)
--   3. Number of cascading failures prevented
--   4. False positive rate (circuits opening unnecessarily) < 1%
--   5. Manual override frequency (should be rare)
--   6. Circuit breaker coverage (percentage of dependencies protected) > 90%
--   7. Alert response time for open circuits < 5 minutes
--
-- Feature Reference: CB-01 (Circuit Breaker)
--                  : CB-02 (Failure Prevention)
--                  : CB-03 (Manual Override)
--                  : CB-04 (Recovery Testing)
--                  : CB-05 (Health Monitoring)
-- -----------------------------------------------------------------------------
CREATE TABLE public.circuit_breakers (
    -- Primary key
    circuit_id        UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Identification
    circuit_name      VARCHAR(255) NOT NULL UNIQUE,
    circuit_type      VARCHAR(50) CHECK (circuit_type IN ('service', 'database', 'cache', 'queue', 'external_api')),
    description       TEXT,

    -- Service reference (if applicable)
    service_name      VARCHAR(255),
    service_namespace VARCHAR(100),
    dependency_id     UUID,                                 -- Link to service_dependencies

    -- Current state
    current_state     public.circuit_breaker_state NOT NULL DEFAULT 'CLOSED',
    state_changed_at  TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    state_changed_by  UUID,                                  -- Who manually changed state
    state_change_reason TEXT,

    -- Failure tracking
    failure_count     INTEGER DEFAULT 0,
    success_count     INTEGER DEFAULT 0,
    total_requests    INTEGER DEFAULT 0,
    failure_rate      NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN total_requests > 0
        THEN (failure_count::NUMERIC / total_requests * 100)
        ELSE 0 END
    ) STORED,

    -- Configuration
    failure_threshold_percentage NUMERIC(5,2) NOT NULL CHECK (failure_threshold_percentage BETWEEN 0 AND 100),
    failure_threshold_count INTEGER NOT NULL,
    window_size_seconds INTEGER NOT NULL CHECK (window_size_seconds > 0),
    minimum_requests   INTEGER NOT NULL DEFAULT 10,

    -- Half-open state configuration
    half_open_max_requests INTEGER NOT NULL DEFAULT 5,
    half_open_success_threshold INTEGER NOT NULL DEFAULT 3,
    half_open_timeout_seconds INTEGER,                       -- How long to stay half-open

    -- Open state configuration
    open_timeout_seconds INTEGER NOT NULL DEFAULT 60,        -- Time before moving to half-open

    -- Metrics
    last_failure_at   TIMESTAMP WITH TIME ZONE,
    last_success_at   TIMESTAMP WITH TIME ZONE,
    last_open_at      TIMESTAMP WITH TIME ZONE,
    last_half_open_at TIMESTAMP WITH TIME ZONE,
    last_closed_at    TIMESTAMP WITH TIME ZONE,

    -- Historical
    total_open_count  INTEGER DEFAULT 0,
    total_open_duration_seconds INTEGER DEFAULT 0,
    average_recovery_time_seconds INTEGER,

    -- Alerting
    alert_on_open     BOOLEAN DEFAULT true,
    alert_webhook     VARCHAR(255),
    alert_cooldown_seconds INTEGER DEFAULT 300,               -- Don't alert too frequently

    -- Metadata
    tags              TEXT[],
    owner_team        VARCHAR(100),

    -- Audit
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by        UUID NOT NULL,
    updated_by        UUID NOT NULL,

    -- Constraints
    CONSTRAINT fk_circuit_breakers_dependency FOREIGN KEY (dependency_id)
        REFERENCES public.service_dependencies(dependency_id) ON DELETE SET NULL,
    CONSTRAINT fk_circuit_breakers_changed_by FOREIGN KEY (state_changed_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for circuit_breakers table
COMMENT ON TABLE public.circuit_breakers IS 'Tracks circuit breaker states for preventing cascading failures';
COMMENT ON COLUMN public.circuit_breakers.circuit_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.circuit_breakers.circuit_name IS 'Unique name for the circuit breaker';
COMMENT ON COLUMN public.circuit_breakers.circuit_type IS 'Type of resource being protected';
COMMENT ON COLUMN public.circuit_breakers.description IS 'Description of what this circuit protects';
COMMENT ON COLUMN public.circuit_breakers.service_name IS 'Service being protected';
COMMENT ON COLUMN public.circuit_breakers.service_namespace IS 'Namespace of service';
COMMENT ON COLUMN public.circuit_breakers.dependency_id IS 'Reference to service dependency';
COMMENT ON COLUMN public.circuit_breakers.current_state IS 'Current circuit breaker state';
COMMENT ON COLUMN public.circuit_breakers.state_changed_at IS 'When state last changed';
COMMENT ON COLUMN public.circuit_breakers.state_changed_by IS 'Who changed state (manual)';
COMMENT ON COLUMN public.circuit_breakers.state_change_reason IS 'Reason for manual state change';
COMMENT ON COLUMN public.circuit_breakers.failure_count IS 'Failures in current window';
COMMENT ON COLUMN public.circuit_breakers.success_count IS 'Successes in current window';
COMMENT ON COLUMN public.circuit_breakers.total_requests IS 'Total requests in current window';
COMMENT ON COLUMN public.circuit_breakers.failure_rate IS 'Calculated failure rate';
COMMENT ON COLUMN public.circuit_breakers.failure_threshold_percentage IS 'Failure % to open circuit';
COMMENT ON COLUMN public.circuit_breakers.failure_threshold_count IS 'Failure count to open circuit';
COMMENT ON COLUMN public.circuit_breakers.window_size_seconds IS 'Time window for counting';
COMMENT ON COLUMN public.circuit_breakers.minimum_requests IS 'Minimum requests before evaluating';
COMMENT ON COLUMN public.circuit_breakers.half_open_max_requests IS 'Requests allowed in half-open';
COMMENT ON COLUMN public.circuit_breakers.half_open_success_threshold IS 'Successes needed to close';
COMMENT ON COLUMN public.circuit_breakers.half_open_timeout_seconds IS 'Max time in half-open';
COMMENT ON COLUMN public.circuit_breakers.open_timeout_seconds IS 'Time before trying half-open';
COMMENT ON COLUMN public.circuit_breakers.last_failure_at IS 'Last failure timestamp';
COMMENT ON COLUMN public.circuit_breakers.last_success_at IS 'Last success timestamp';
COMMENT ON COLUMN public.circuit_breakers.last_open_at IS 'Last time circuit opened';
COMMENT ON COLUMN public.circuit_breakers.last_half_open_at IS 'Last time circuit was half-open';
COMMENT ON COLUMN public.circuit_breakers.last_closed_at IS 'Last time circuit closed';
COMMENT ON COLUMN public.circuit_breakers.total_open_count IS 'Total times circuit opened';
COMMENT ON COLUMN public.circuit_breakers.total_open_duration_seconds IS 'Total time spent open';
COMMENT ON COLUMN public.circuit_breakers.average_recovery_time_seconds IS 'Average recovery time';
COMMENT ON COLUMN public.circuit_breakers.alert_on_open IS 'Whether to alert when circuit opens';
COMMENT ON COLUMN public.circuit_breakers.alert_webhook IS 'Webhook for alerts';
COMMENT ON COLUMN public.circuit_breakers.alert_cooldown_seconds IS 'Minimum time between alerts';
COMMENT ON COLUMN public.circuit_breakers.tags IS 'Tags for categorization';
COMMENT ON COLUMN public.circuit_breakers.owner_team IS 'Team owning this circuit';
COMMENT ON COLUMN public.circuit_breakers.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.circuit_breakers.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.circuit_breakers.created_by IS 'User who created the record';
COMMENT ON COLUMN public.circuit_breakers.updated_by IS 'User who last updated the record';

-- Indexes for circuit_breakers table
CREATE INDEX idx_circuit_breakers_name ON public.circuit_breakers(circuit_name);
CREATE INDEX idx_circuit_breakers_service ON public.circuit_breakers(service_name, service_namespace);
CREATE INDEX idx_circuit_breakers_state ON public.circuit_breakers(current_state, state_changed_at);
CREATE INDEX idx_circuit_breakers_failure_rate ON public.circuit_breakers(failure_rate DESC) WHERE current_state = 'CLOSED';

-- Partial index for open circuits needing attention
CREATE INDEX idx_circuit_breakers_open ON public.circuit_breakers(state_changed_at)
    WHERE current_state IN ('OPEN', 'HALF_OPEN');

-- Trigger for updated_at
CREATE TRIGGER update_circuit_breakers_timestamp
    BEFORE UPDATE ON public.circuit_breakers
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.circuit_breakers ENABLE ROW LEVEL SECURITY;

-- Policy: Platform team can manage circuits
CREATE POLICY circuit_breakers_platform_policy ON public.circuit_breakers
    USING (owner_team IN (SELECT team FROM public.user_teams WHERE user_id = current_user_id()) OR
           EXISTS (SELECT 1 FROM public.user_roles ur
                   JOIN public.roles r ON ur.role_id = r.role_id
                   WHERE ur.user_id = current_user_id() AND r.name IN ('platform_admin', 'admin')));

-- Policy: Read-only for monitoring systems
CREATE POLICY circuit_breakers_monitoring_policy ON public.circuit_breakers
    FOR SELECT USING (current_user = 'monitoring_service');

-- =============================================================================
-- TABLE: 23 - dead_letter_queue
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 23
-- Table Name: dead_letter_queue
-- Description: Stores failed background job messages that could not be processed
--              after retries, enabling manual intervention and replay.
--
-- Business Case: In distributed systems, background jobs (emails, notifications,
--                data processing) may fail due to transient errors or bugs.
--                Losing these messages can have serious business impact:
--                - Failed payment processing leads to revenue loss,
--                - Undelivered emails break customer communication,
--                - Missed notifications damage user experience.
--                This dead letter queue (DLQ) captures all failed messages,
--                providing:
--                1) Zero data loss guarantee for critical jobs,
--                2) Automatic retry with exponential backoff,
--                3) Visibility into failure patterns,
--                4) Manual replay capability after fixes,
--                5) Alerting on high failure rates,
--                6) Audit trail for compliance,
--                7) Capacity planning for job processing.
--                The table stores the full message payload, error details,
--                and retry history. Operators can replay messages after
--                fixing underlying issues, or archive them for compliance.
--                Integration with monitoring tools alerts on DLQ growth,
--                indicating systemic problems. The system supports different
--                handling strategies per job type (e.g., payment failures
--                alert immediately, email retries can wait). With proper
--                indexing, the DLQ can be queried to analyze failure trends
--                and prioritize fixes.
--
-- KPIs:
--   1. DLQ size (number of unresolved messages) - target < 100
--   2. Age of oldest message in DLQ - target < 24 hours
--   3. Replay success rate > 80%
--   4. Top failing job types (for prioritization)
--   5. Mean time to resolution (MTTR) for DLQ messages < 4 hours
--   6. Percentage of messages that never leave DLQ < 1%
--   7. Alert response time for DLQ growth < 30 minutes
--
-- Feature Reference: DLQ-01 (Dead Letter Queue)
--                  : DLQ-02 (Message Replay)
--                  : DLQ-03 (Failure Analysis)
--                  : DLQ-04 (Retry Management)
--                  : DLQ-05 (Alerting)
-- -----------------------------------------------------------------------------
CREATE TABLE public.dead_letter_queue (
    -- Primary key
    dlq_id            UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Queue identification
    queue_name        VARCHAR(100) NOT NULL,                -- e.g., 'email', 'payment', 'notification'
    job_type          VARCHAR(100) NOT NULL,
    job_id            VARCHAR(255),                          -- Original job ID if available

    -- Message payload
    payload           JSONB NOT NULL,
    headers           JSONB,                                 -- Message headers/metadata

    -- Error details
    error_message     TEXT NOT NULL,
    error_stack       TEXT,
    error_code        VARCHAR(50),
    error_category    VARCHAR(50) CHECK (error_category IN ('transient', 'permanent', 'timeout', 'validation', 'dependency', 'unknown')),

    -- Retry tracking
    retry_count       INTEGER NOT NULL DEFAULT 0,
    max_retries       INTEGER NOT NULL DEFAULT 3,
    next_retry_at     TIMESTAMP WITH TIME ZONE,
    last_retry_at     TIMESTAMP WITH TIME ZONE,

    -- Timing
    first_failure_at  TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_failure_at   TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Status
    status            public.dead_letter_status NOT NULL DEFAULT 'PENDING_RETRY',

    -- Locking (for distributed processing)
    locked_until      TIMESTAMP WITH TIME ZONE,
    locked_by         VARCHAR(100),                          -- Worker identifier

    -- Resolution
    resolved_at       TIMESTAMP WITH TIME ZONE,
    resolved_by       UUID,
    resolution_notes  TEXT,

    -- Context
    environment       VARCHAR(50) NOT NULL,
    source_service    VARCHAR(100),
    request_id        UUID,                                   -- For tracing
    trace_id          VARCHAR(100),

    -- Metadata
    tags              TEXT[],

    -- Audit
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT chk_retry_count CHECK (retry_count <= max_retries),
    CONSTRAINT fk_dlq_resolved_by FOREIGN KEY (resolved_by)
        REFERENCES public.users(user_id) ON DELETE SET NULL
);

-- Comments for dead_letter_queue table
COMMENT ON TABLE public.dead_letter_queue IS 'Stores failed background job messages for manual intervention and replay';
