-- =============================================================================
-- TABLE: 24 - search_sync_queue
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 24
-- Table Name: search_sync_queue
-- Description: Queue for synchronizing data changes with external search engines
--              (Elasticsearch, OpenSearch) to maintain search index freshness.
--
-- Business Case: Full-text search on large datasets is best handled by
--                dedicated search engines. Changes to indexed entities
--                (users, jobs, companies, content) must be propagated
--                asynchronously to keep search results fresh. This table
--                acts as a reliable queue, recording each change event and
--                its processing status. It supports:
--                1) Decoupling search indexing from transactional writes,
--                2) Retry logic with exponential backoff,
--                3) Batch processing for efficiency,
--                4) Dead-letter handling for failed syncs,
--                5) Priority queuing for critical updates,
--                6) Idempotent processing to handle duplicates,
--                7) Monitoring of indexing lag.
--                By using a database-backed queue, we gain ACID properties
--                and can coordinate with the transaction that modified the
--                data (using transactional outbox pattern). This ensures
--                that search updates are guaranteed to happen eventually,
--                even if the search engine is temporarily unavailable. The
--                table supports different entity types with different sync
--                priorities (e.g., job postings higher priority than profile
--                updates). With proper indexing, workers can efficiently
--                claim and process batches of items. The system also tracks
--                sync latency to detect and alert on indexing delays.
--
-- KPIs:
--   1. Queue depth (number of pending sync items) - target < 1000
--   2. Processing latency (time from enqueue to successful sync) p99 < 5 seconds
--   3. Failure rate (percentage of items that fail permanently) < 1%
--   4. Throughput (items processed per minute) - monitor for capacity
--   5. Age of oldest pending item - target < 1 hour
--   6. Index freshness lag (time between data change and search visibility) < 30 seconds
--   7. Worker utilization (percentage of time workers busy) < 80%
--
-- Feature Reference: SYNC-01 (Search Sync)
--                  : SYNC-02 (Index Management)
--                  : SYNC-03 (Transactional Outbox)
--                  : SYNC-04 (Sync Monitoring)
-- -----------------------------------------------------------------------------
CREATE TABLE public.search_sync_queue (
    -- Primary key
    sync_id           UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Entity identification
    entity_type       VARCHAR(50) NOT NULL,                 -- e.g., 'user', 'job', 'company'
    entity_id         UUID NOT NULL,
    operation         VARCHAR(10) NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE', 'INDEX', 'REINDEX')),

    -- Change tracking
    changed_at        TIMESTAMP WITH TIME ZONE NOT NULL,    -- Time of original change
    version           BIGINT,                                -- Entity version for optimistic locking

    -- Payload (denormalized data for indexing)
    payload           JSONB,                                 -- Full document to index
    partial_payload   BOOLEAN DEFAULT false,                 -- Whether this is partial update

    -- Priority and routing
    priority          INTEGER DEFAULT 100 CHECK (priority >= 1), -- Lower = higher priority
    routing_key       VARCHAR(100),                          -- For sharding/routing

    -- Processing status
    status            public.sync_queue_status NOT NULL DEFAULT 'PENDING',
    retry_count       INTEGER DEFAULT 0 NOT NULL,
    max_retries       INTEGER DEFAULT 5 NOT NULL,

    -- Timing
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    scheduled_at      TIMESTAMP WITH TIME ZONE,               -- When to process (for delayed)
    started_at        TIMESTAMP WITH TIME ZONE,
    completed_at      TIMESTAMP WITH TIME ZONE,

    -- Error tracking
    last_error        TEXT,
    error_count       INTEGER DEFAULT 0,

    -- Locking (for distributed workers)
    locked_until      TIMESTAMP WITH TIME ZONE,
    locked_by         VARCHAR(100),                            -- Worker identifier

    -- Metrics
    processing_time_ms INTEGER,                                 -- Time taken to process

    -- Context
    source_service    VARCHAR(100),
    environment       VARCHAR(50) NOT NULL,

    -- Constraints
    CONSTRAINT chk_retry_limit CHECK (retry_count <= max_retries),
    CONSTRAINT chk_processing_time CHECK (processing_time_ms >= 0),
    CONSTRAINT uq_sync_entity_version UNIQUE (entity_type, entity_id, version)
        WHERE version IS NOT NULL
);

-- Comments for search_sync_queue table
COMMENT ON TABLE public.search_sync_queue IS 'Queue for synchronizing data changes with external search engine';
COMMENT ON COLUMN public.search_sync_queue.sync_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.search_sync_queue.entity_type IS 'Type of entity that changed';
COMMENT ON COLUMN public.search_sync_queue.entity_id IS 'UUID of the entity';
COMMENT ON COLUMN public.search_sync_queue.operation IS 'Type of change operation';
COMMENT ON COLUMN public.search_sync_queue.changed_at IS 'Timestamp of original change';
COMMENT ON COLUMN public.search_sync_queue.version IS 'Entity version for optimistic locking';
COMMENT ON COLUMN public.search_sync_queue.payload IS 'Full document to index (denormalized)';
COMMENT ON COLUMN public.search_sync_queue.partial_payload IS 'Whether this is a partial update';
COMMENT ON COLUMN public.search_sync_queue.priority IS 'Priority for processing (lower first)';
COMMENT ON COLUMN public.search_sync_queue.routing_key IS 'Routing key for sharding';
COMMENT ON COLUMN public.search_sync_queue.status IS 'Current processing status';
COMMENT ON COLUMN public.search_sync_queue.retry_count IS 'Number of retry attempts';
COMMENT ON COLUMN public.search_sync_queue.max_retries IS 'Maximum retry attempts';
COMMENT ON COLUMN public.search_sync_queue.created_at IS 'Timestamp when queue item was created';
COMMENT ON COLUMN public.search_sync_queue.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.search_sync_queue.scheduled_at IS 'When to process (for delayed)';
COMMENT ON COLUMN public.search_sync_queue.started_at IS 'When processing started';
COMMENT ON COLUMN public.search_sync_queue.completed_at IS 'When processing completed';
COMMENT ON COLUMN public.search_sync_queue.last_error IS 'Last error message';
COMMENT ON COLUMN public.search_sync_queue.error_count IS 'Number of errors encountered';
COMMENT ON COLUMN public.search_sync_queue.locked_until IS 'Time until which item is locked';
COMMENT ON COLUMN public.search_sync_queue.locked_by IS 'Worker that locked the item';
COMMENT ON COLUMN public.search_sync_queue.processing_time_ms IS 'Time taken to process';
COMMENT ON COLUMN public.search_sync_queue.source_service IS 'Service that created the sync item';
COMMENT ON COLUMN public.search_sync_queue.environment IS 'Environment';

-- Indexes for search_sync_queue table
CREATE INDEX idx_sync_queue_status ON public.search_sync_queue(status, priority, created_at)
    WHERE status = 'PENDING';
CREATE INDEX idx_sync_queue_scheduled ON public.search_sync_queue(scheduled_at)
    WHERE status = 'PENDING' AND scheduled_at IS NOT NULL;
CREATE INDEX idx_sync_queue_locked ON public.search_sync_queue(locked_until)
    WHERE locked_until IS NOT NULL;
CREATE INDEX idx_sync_queue_entity ON public.search_sync_queue(entity_type, entity_id, version);
CREATE INDEX idx_sync_queue_created ON public.search_sync_queue(created_at) WHERE status != 'COMPLETED';

-- GIN index for payload searches (for debugging)
CREATE INDEX idx_sync_queue_payload ON public.search_sync_queue USING gin(payload);

-- Partial index for failed items
CREATE INDEX idx_sync_queue_failed ON public.search_sync_queue(updated_at)
    WHERE status = 'FAILED';

-- Trigger for updated_at
CREATE TRIGGER update_search_sync_queue_timestamp
    BEFORE UPDATE ON public.search_sync_queue
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.search_sync_queue ENABLE ROW LEVEL SECURITY;

-- Policy: Platform team can manage sync queue
CREATE POLICY sync_queue_platform_policy ON public.search_sync_queue
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('platform_admin', 'admin')
    ));

-- Policy: Search workers can read/update
CREATE POLICY sync_queue_worker_policy ON public.search_sync_queue
    USING (current_user IN ('search_worker', 'sync_service'));

-- =============================================================================
-- TABLE: 25 - cache_invalidation_queue
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 25
-- Table Name: cache_invalidation_queue
-- Description: Tracks cache keys that need to be invalidated across distributed
--              cache nodes to maintain consistency.
--
-- Business Case: In a distributed system with multiple cache layers (Redis,
--                Memcached, CDN), keeping caches consistent with data changes
--                is challenging. This queue ensures that when data is modified,
--                all cached copies are properly invalidated:
--                1) Write-through cache invalidation,
--                2) Cross-region cache synchronization,
--                3) CDN purge coordination,
--                4) Dependency-based invalidation (e.g., user profile changes
--                   invalidate multiple cache keys),
--                5) Batch invalidation for efficiency,
--                6) Retry mechanism for failed invalidations,
--                7) Audit trail of cache operations.
--                The queue follows the transactional outbox pattern: when a
--                database transaction commits, invalidation events are written
--                to this queue, ensuring they're not lost. Workers then process
--                these events asynchronously, invalidating cache entries across
--                all nodes. The system supports different cache types (Redis,
--                CDN, application cache) with different invalidation methods
--                (delete, set with TTL, purge). Dependency tracking ensures
--                that related cache keys (e.g., user profile and user's posts)
--                are invalidated together. For high-traffic systems, this
--                prevents stale data from being served while maintaining
--                performance.
--
-- KPIs:
--   1. Queue depth (pending invalidations) - target < 100
--   2. Invalidation latency (time from enqueue to completion) p99 < 1 second
--   3. Invalidation coverage (keys invalidated vs. keys changed) = 100%
--   4. Cache hit rate after invalidation (should recover quickly)
--   5. Failed invalidation rate < 0.1%
--   6. Time to detect stale cache (monitoring) < 1 minute
--   7. Worker efficiency (invalidations per second)
--
-- Feature Reference: CACHE-01 (Cache Invalidation)
--                  : CACHE-02 (Distributed Cache)
--                  : CACHE-03 (CDN Purge)
--                  : CACHE-04 (Consistency)
-- -----------------------------------------------------------------------------
CREATE TABLE public.cache_invalidation_queue (
    -- Primary key
    invalidation_id   UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Cache identification
    cache_region      VARCHAR(50) NOT NULL,                 -- e.g., 'redis_users', 'cdn_assets', 'memcached_session'
    cache_key         VARCHAR(500) NOT NULL,
    key_pattern       VARCHAR(500),                          -- For pattern-based invalidation

    -- Invalidation details
    reason            public.cache_invalidation_reason NOT NULL,
    entity_type       VARCHAR(50),                            -- Related entity type
    entity_id         UUID,                                   -- Related entity ID

    -- Dependencies
    dependent_keys    TEXT[],                                 -- Related keys to also invalidate
    parent_invalidation_id UUID,                               -- For batch operations

    -- Timing
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    scheduled_at      TIMESTAMP WITH TIME ZONE,               -- When to invalidate (for delayed)
    expires_at        TIMESTAMP WITH TIME ZONE,                -- When invalidation expires

    -- Processing status
    status            public.sync_queue_status NOT NULL DEFAULT 'PENDING',
    retry_count       INTEGER DEFAULT 0,
    max_retries       INTEGER DEFAULT 3,

    -- Processing tracking
    started_at        TIMESTAMP WITH TIME ZONE,
    completed_at      TIMESTAMP WITH TIME ZONE,
    processing_time_ms INTEGER,

    -- Worker coordination
    locked_until      TIMESTAMP WITH TIME ZONE,
    locked_by         VARCHAR(100),

    -- Result
    success           BOOLEAN,
    error_message     TEXT,
    response_data     JSONB,                                  -- Cache provider response

    -- Context
    source_service    VARCHAR(100),
    request_id        UUID,
    environment       VARCHAR(50) NOT NULL,

    -- Audit
    updated_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT chk_cache_key CHECK (cache_key IS NOT NULL OR key_pattern IS NOT NULL),
    CONSTRAINT fk_cache_invalidation_parent FOREIGN KEY (parent_invalidation_id)
        REFERENCES public.cache_invalidation_queue(invalidation_id) ON DELETE CASCADE
);

-- Comments for cache_invalidation_queue table
COMMENT ON TABLE public.cache_invalidation_queue IS 'Queue for tracking cache invalidation across distributed systems';
COMMENT ON COLUMN public.cache_invalidation_queue.invalidation_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.cache_invalidation_queue.cache_region IS 'Cache region or type';
COMMENT ON COLUMN public.cache_invalidation_queue.cache_key IS 'Specific cache key to invalidate';
COMMENT ON COLUMN public.cache_invalidation_queue.key_pattern IS 'Pattern for bulk invalidation';
COMMENT ON COLUMN public.cache_invalidation_queue.reason IS 'Why invalidation is needed';
COMMENT ON COLUMN public.cache_invalidation_queue.entity_type IS 'Related entity type';
COMMENT ON COLUMN public.cache_invalidation_queue.entity_id IS 'Related entity ID';
COMMENT ON COLUMN public.cache_invalidation_queue.dependent_keys IS 'Related keys to invalidate';
COMMENT ON COLUMN public.cache_invalidation_queue.parent_invalidation_id IS 'Parent for batch operations';
COMMENT ON COLUMN public.cache_invalidation_queue.created_at IS 'When invalidation was requested';
COMMENT ON COLUMN public.cache_invalidation_queue.scheduled_at IS 'When to perform invalidation';
COMMENT ON COLUMN public.cache_invalidation_queue.expires_at IS 'When invalidation expires';
COMMENT ON COLUMN public.cache_invalidation_queue.status IS 'Current processing status';
COMMENT ON COLUMN public.cache_invalidation_queue.retry_count IS 'Number of retry attempts';
COMMENT ON COLUMN public.cache_invalidation_queue.max_retries IS 'Maximum retry attempts';
COMMENT ON COLUMN public.cache_invalidation_queue.started_at IS 'When processing started';
COMMENT ON COLUMN public.cache_invalidation_queue.completed_at IS 'When processing completed';
COMMENT ON COLUMN public.cache_invalidation_queue.processing_time_ms IS 'Time taken to process';
COMMENT ON COLUMN public.cache_invalidation_queue.locked_until IS 'Lock expiration';
COMMENT ON COLUMN public.cache_invalidation_queue.locked_by IS 'Worker identifier';
COMMENT ON COLUMN public.cache_invalidation_queue.success IS 'Whether invalidation succeeded';
COMMENT ON COLUMN public.cache_invalidation_queue.error_message IS 'Error if failed';
COMMENT ON COLUMN public.cache_invalidation_queue.response_data IS 'Response from cache provider';
COMMENT ON COLUMN public.cache_invalidation_queue.source_service IS 'Service requesting invalidation';
COMMENT ON COLUMN public.cache_invalidation_queue.request_id IS 'Request identifier';
COMMENT ON COLUMN public.cache_invalidation_queue.environment IS 'Environment';
COMMENT ON COLUMN public.cache_invalidation_queue.updated_at IS 'Timestamp of last update';

-- Indexes for cache_invalidation_queue table
CREATE INDEX idx_cache_inv_status ON public.cache_invalidation_queue(status, scheduled_at)
    WHERE status = 'PENDING';
CREATE INDEX idx_cache_inv_region ON public.cache_invalidation_queue(cache_region, status);
CREATE INDEX idx_cache_inv_entity ON public.cache_invalidation_queue(entity_type, entity_id)
    WHERE entity_id IS NOT NULL;
CREATE INDEX idx_cache_inv_key ON public.cache_invalidation_queue(cache_key) WHERE cache_key IS NOT NULL;
CREATE INDEX idx_cache_inv_locked ON public.cache_invalidation_queue(locked_until) WHERE locked_until IS NOT NULL;
CREATE INDEX idx_cache_inv_parent ON public.cache_invalidation_queue(parent_invalidation_id)
    WHERE parent_invalidation_id IS NOT NULL;

-- Partial index for failed invalidations
CREATE INDEX idx_cache_inv_failed ON public.cache_invalidation_queue(updated_at)
    WHERE status = 'FAILED';

-- Trigger for updated_at
CREATE TRIGGER update_cache_invalidation_queue_timestamp
    BEFORE UPDATE ON public.cache_invalidation_queue
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.cache_invalidation_queue ENABLE ROW LEVEL SECURITY;

-- Policy: Platform team can manage
CREATE POLICY cache_inv_platform_policy ON public.cache_invalidation_queue
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('platform_admin', 'admin')
    ));

-- Policy: Cache workers can read/update
CREATE POLICY cache_inv_worker_policy ON public.cache_invalidation_queue
    USING (current_user IN ('cache_worker', 'invalidation_service'));

-- =============================================================================
-- TABLE: 26 - webhook_delivery_logs
-- =============================================================================
-- -----------------------------------------------------------------------------
-- Serial No: 26
-- Table Name: webhook_delivery_logs
-- Description: Comprehensive logs of outgoing webhook delivery attempts to
--              external systems with retry tracking and response capture.
--
-- Business Case: Integrating with external systems via webhooks is critical
--                for real-time notifications (e.g., notify CRM when user
--                upgrades, send Slack alerts on incidents). However, external
--                systems may be unavailable or slow. This table provides:
--                1) Delivery guarantee with retry mechanism,
--                2) Full audit trail of all webhook attempts,
--                3) Response capture for debugging,
--                4) Performance monitoring of external endpoints,
--                5) Alerting on persistent failures,
--                6) Compliance evidence of data sharing,
--                7) Capacity planning for webhook traffic.
--                The table records every attempt, including request/response
--                headers, payload, and timing. It supports multiple retry
--                strategies (exponential backoff, fixed interval) and dead-letter
--                handling for permanent failures. Integration with monitoring
--                alerts on high failure rates or slow responses. For compliance
--                (GDPR, SOC2), it logs what data was shared and when. The table
--                is partitioned by time to manage growth and query performance.
--
-- KPIs:
--   1. Webhook delivery success rate > 99.5%
--   2. Average delivery latency p99 < 5 seconds
--   3. Retry rate (percentage requiring retry) < 5%
--   4. Permanent failure rate (dead letter) < 0.1%
--   5. Time to detect webhook outage < 5 minutes
--   6. Webhook volume (requests per day) - monitor for growth
--   7. External system response time trends
--
-- Feature Reference: WH-01 (Webhook Delivery)
--                  : WH-02 (Retry Management)
--                  : WH-03 (Audit Trail)
--                  : WH-04 (Monitoring)
-- -----------------------------------------------------------------------------
CREATE TABLE public.webhook_delivery_logs (
    -- Primary key (using composite for partitioning)
    log_id            UUID NOT NULL,
    delivery_date     DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Webhook identification
    webhook_id        UUID NOT NULL,                          -- Reference to webhook_subscriptions
    event_type        VARCHAR(100) NOT NULL,

    -- Target information
    destination_url   VARCHAR(500) NOT NULL,
    method            VARCHAR(10) DEFAULT 'POST' NOT NULL,

    -- Attempt tracking
    attempt_number    INTEGER NOT NULL DEFAULT 1,
    status            public.webhook_delivery_status NOT NULL DEFAULT 'PENDING',

    -- Request details
    request_headers   JSONB,
    request_body      TEXT,
    request_size_bytes INTEGER,

    -- Response details
    response_status_code INTEGER,
    response_headers  JSONB,
    response_body     TEXT,
    response_size_bytes INTEGER,
    response_time_ms  INTEGER,

    -- Timing
    queued_at         TIMESTAMP WITH TIME ZONE NOT NULL,
    sent_at           TIMESTAMP WITH TIME ZONE,
    completed_at      TIMESTAMP WITH TIME ZONE,

    -- Retry information
    next_retry_at     TIMESTAMP WITH TIME ZONE,
    retry_count       INTEGER DEFAULT 0,
    max_retries       INTEGER NOT NULL,

    -- Error information
    error_message     TEXT,
    error_type        VARCHAR(100),

    -- Context
    source_service    VARCHAR(100),
    trigger_event_id  UUID,                                   -- ID of triggering event
    environment       VARCHAR(50) NOT NULL,

    -- Metadata
    tags              TEXT[],

    -- Audit
    created_at        TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Partition key
    PRIMARY KEY (log_id, delivery_date)
) PARTITION BY RANGE (delivery_date);

-- Comments for webhook_delivery_logs table
COMMENT ON TABLE public.webhook_delivery_logs IS 'Comprehensive logs of webhook delivery attempts to external systems';
COMMENT ON COLUMN public.webhook_delivery_logs.log_id IS 'Primary key using UUID';
COMMENT ON COLUMN public.webhook_delivery_logs.delivery_date IS 'Date of delivery (partition key)';
COMMENT ON COLUMN public.webhook_delivery_logs.webhook_id IS 'Reference to webhook subscription';
COMMENT ON COLUMN public.webhook_delivery_logs.event_type IS 'Type of event triggering webhook';
COMMENT ON COLUMN public.webhook_delivery_logs.destination_url IS 'Target URL for webhook';
COMMENT ON COLUMN public.webhook_delivery_logs.method IS 'HTTP method (usually POST)';
COMMENT ON COLUMN public.webhook_delivery_logs.attempt_number IS 'Which attempt this is';
COMMENT ON COLUMN public.webhook_delivery_logs.status IS 'Delivery status';
COMMENT ON COLUMN public.webhook_delivery_logs.request_headers IS 'HTTP headers sent';
COMMENT ON COLUMN public.webhook_delivery_logs.request_body IS 'Request payload';
COMMENT ON COLUMN public.webhook_delivery_logs.request_size_bytes IS 'Size of request';
COMMENT ON COLUMN public.webhook_delivery_logs.response_status_code IS 'HTTP status code received';
COMMENT ON COLUMN public.webhook_delivery_logs.response_headers IS 'Response headers';
COMMENT ON COLUMN public.webhook_delivery_logs.response_body IS 'Response body';
COMMENT ON COLUMN public.webhook_delivery_logs.response_size_bytes IS 'Size of response';
COMMENT ON COLUMN public.webhook_delivery_logs.response_time_ms IS 'Time to receive response';
COMMENT ON COLUMN public.webhook_delivery_logs.queued_at IS 'When webhook was queued';
COMMENT ON COLUMN public.webhook_delivery_logs.sent_at IS 'When request was sent';
COMMENT ON COLUMN public.webhook_delivery_logs.completed_at IS 'When delivery completed';
