COMMENT ON COLUMN public.webhook_delivery_logs.created_at IS 'Timestamp of log creation';

-- Function to create monthly partitions for webhook logs
CREATE OR REPLACE FUNCTION public.create_webhook_log_partition(p_year INTEGER, p_month INTEGER)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date DATE;
    end_date DATE;
BEGIN
    partition_name := 'webhook_delivery_logs_' || p_year || '_' || LPAD(p_month::TEXT, 2, '0');
    start_date := MAKE_DATE(p_year, p_month, 1);

    IF p_month = 12 THEN
        end_date := MAKE_DATE(p_year + 1, 1, 1);
    ELSE
        end_date := MAKE_DATE(p_year, p_month + 1, 1);
    END IF;

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.webhook_delivery_logs
        FOR VALUES FROM (%L) TO (%L)',
        partition_name, start_date, end_date
    );

    -- Create indexes on the partition
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_webhook_id ON public.%I(webhook_id)',
        partition_name, partition_name
    );

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I_status ON public.%I(status, next_retry_at)',
        partition_name, partition_name
    );
END;
$$ LANGUAGE plpgsql;

-- Create partitions (similar to previous tables)
SELECT public.create_webhook_log_partition(EXTRACT(YEAR FROM CURRENT_DATE)::INTEGER, 1);
-- ... create all months

-- Create default partition
CREATE TABLE public.webhook_delivery_logs_default PARTITION OF public.webhook_delivery_logs DEFAULT;

-- Global indexes
CREATE INDEX idx_webhook_log_webhook_id ON public.webhook_delivery_logs(webhook_id);
CREATE INDEX idx_webhook_log_status ON public.webhook_delivery_logs(status, next_retry_at)
    WHERE status IN ('PENDING', 'RETRYING');
CREATE INDEX idx_webhook_log_destination ON public.webhook_delivery_logs(destination_url);
CREATE INDEX idx_webhook_log_queued ON public.webhook_delivery_logs(queued_at);

-- GIN indexes
CREATE INDEX idx_webhook_log_tags ON public.webhook_delivery_logs USING gin(tags);

-- Enable RLS
ALTER TABLE public.webhook_delivery_logs ENABLE ROW LEVEL SECURITY;

-- Policy: Platform team can view all
CREATE POLICY webhook_log_platform_policy ON public.webhook_delivery_logs
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('platform_admin', 'admin', 'support_engineer')
    ));

-- Policy: Webhook service can read/update
CREATE POLICY webhook_log_worker_policy ON public.webhook_delivery_logs
    USING (current_user = 'webhook_service');

    -- Archive old dead letter queue entries
    CREATE OR REPLACE FUNCTION public.archive_dead_letter_queue()
    RETURNS INTEGER AS $$
    DECLARE
        archived_count INTEGER;
    BEGIN
        WITH archived AS (
            DELETE FROM public.dead_letter_queue
            WHERE status = 'RESOLVED'
              AND updated_at < NOW() - INTERVAL '90 days'
            RETURNING *
        )
        SELECT * FROM archived;

        GET DIAGNOSTICS archived_count = ROW_COUNT;
        RETURN archived_count;
    END;
    $$ LANGUAGE plpgsql;

    -- Rebuild cache from source
    CREATE OR REPLACE FUNCTION public.rebuild_cache_namespace(
        p_namespace VARCHAR,
        p_environment VARCHAR DEFAULT 'production'
    )
    RETURNS INTEGER AS $$
    DECLARE
        rebuilt_count INTEGER = 0;
    BEGIN
        -- Mark existing entries as stale
        UPDATE public.api_response_cache
        SET stale_at = CURRENT_TIMESTAMP
        WHERE cache_namespace = p_namespace
          AND environment = p_environment;

        -- Trigger cache warming jobs (application-specific)
        -- This would call external processes

        RETURN rebuilt_count;
    END;
    $$ LANGUAGE plpgsql;



