-- ====================================================================
-- ENUM: system_health_status
-- Description: Defines the possible health states of system components
-- Business Case: Enables standardized health reporting across all monitored components
-- Feature Reference: OPS-01 (System Monitoring)
-- ====================================================================
CREATE TYPE public.system_health_status AS ENUM (
    'HEALTHY',           -- Component operating normally
    'DEGRADED',          -- Performance below threshold but operational
    'UNHEALTHY',         -- Component failing or impaired
    'MAINTENANCE',       -- Under scheduled maintenance
    'UNKNOWN',           -- Status cannot be determined
    'CRITICAL',          -- Severe impact on functionality
    'RECOVERING'         -- Recovering from failure state
);
COMMENT ON TYPE public.system_health_status IS 'Health states for system components and services';

-- ====================================================================
-- ENUM: alert_severity
-- Description: Severity levels for system alerts and notifications
-- Business Case: Enables proper prioritization and escalation of incidents
-- Feature Reference: OPS-02 (Alert Management)
-- ====================================================================
CREATE TYPE public.alert_severity AS ENUM (
    'INFO',              -- Informational, no action required
    'WARNING',           -- Potential issue, monitor closely
    'MINOR',             -- Minor impact, address during business hours
    'MAJOR',             -- Significant impact, immediate attention required
    'CRITICAL',          -- Severe impact, emergency response
    'SEV1',              -- Complete service outage
    'SEV2',              -- Partial service degradation
    'SEV3'               -- Minor service degradation
);
COMMENT ON TYPE public.alert_severity IS 'Severity classification for system alerts';

-- ====================================================================
-- ENUM: alert_status
-- Description: Lifecycle states of an alert
-- Business Case: Tracks alert from detection through resolution
-- Feature Reference: OPS-02 (Alert Management)
-- ====================================================================
CREATE TYPE public.alert_status AS ENUM (
    'TRIGGERED',         -- Alert condition detected
    'ACKNOWLEDGED',      -- Being investigated
    'RESOLVED',          -- Condition cleared
    'CLOSED',            -- Investigation complete
    'FALSE_POSITIVE',    -- Alert triggered in error
    'ESCALATED',         -- Escalated to higher support tier
    'SUPPRESSED'         -- Temporarily muted
);
COMMENT ON TYPE public.alert_status IS 'Lifecycle states for alert management';

-- ====================================================================
-- ENUM: incident_severity
-- Description: Severity levels for incident reports
-- Business Case: Standardizes incident classification for reporting and SLA tracking
-- Feature Reference: OPS-03 (Incident Management)
-- ====================================================================
CREATE TYPE public.incident_severity AS ENUM (
    'SEV1',              -- Critical outage, business impacting
    'SEV2',              -- Major feature degradation
    'SEV3',              -- Minor feature issue
    'SEV4',              -- Cosmetic issue, workaround exists
    'SEV5'               -- Internal only, no customer impact
);
COMMENT ON TYPE public.incident_severity IS 'Severity classification for incidents';

-- ====================================================================
-- ENUM: incident_status
-- Description: Lifecycle states of an incident
-- Business Case: Tracks incident from detection through post-mortem
-- Feature Reference: OPS-03 (Incident Management)
-- ====================================================================
CREATE TYPE public.incident_status AS ENUM (
    'DETECTED',          -- Incident identified
    'INVESTIGATING',     -- Root cause analysis in progress
    'MITIGATING',        -- Actions being taken to reduce impact
    'RESOLVED',          -- Service restored
    'MONITORING',        -- Monitoring for stability
    'CLOSED',            -- Incident complete, post-mortem pending
    'POST_MORTEM',       -- Post-incident analysis
    'ARCHIVED'           -- Fully documented and archived
);
COMMENT ON TYPE public.incident_status IS 'Lifecycle states for incident management';

-- ====================================================================
-- ENUM: backup_type
-- Description: Types of database backups
-- Business Case: Distinguishes between different backup strategies for retention policies
-- Feature Reference: OPS-04 (Backup Management)
-- ====================================================================
CREATE TYPE public.backup_type AS ENUM (
    'FULL',              -- Complete database backup
    'INCREMENTAL',       -- Changes since last backup
    'DIFFERENTIAL',      -- Changes since last full backup
    'WAL_ARCHIVE',       -- Write-ahead log archive
    'LOGICAL',           -- Logical dump (pg_dump)
    'SNAPSHOT',          -- Storage snapshot
    'CONTINUOUS'         -- Continuous archiving
);
COMMENT ON TYPE public.backup_type IS 'Types of database backup strategies';

-- ====================================================================
-- ENUM: backup_status
