    'APPROVED',          -- Ready for implementation
    'REJECTED',          -- Not approved
    'SCHEDULED',         -- Planned for future execution
    'IN_PROGRESS',       -- Being applied
    'COMPLETED',         -- Successfully applied
    'FAILED',            -- Execution failed
    'ROLLED_BACK',       -- Changes reverted
    'CANCELLED'          -- Withdrawn by requester
);
COMMENT ON TYPE public.change_request_status IS 'Status workflow for database change requests';

-- ====================================================================
-- ENUM: change_risk_level
-- Description: Risk classification for database changes
-- Business Case: Determines approval requirements and implementation windows
-- Feature Reference: OPS-06 (Change Management)
-- ====================================================================
CREATE TYPE public.change_risk_level AS ENUM (
    'LOW',               -- No expected impact, routine changes
    'MEDIUM',            -- Potential minor impact, require peer review
    'HIGH',              -- Significant impact, require management approval
    'CRITICAL'           -- Business-critical, require change advisory board
);
COMMENT ON TYPE public.change_risk_level IS 'Risk classification for database changes';

-- ====================================================================
-- ENUM: sla_status
-- Description: Status of service level agreement compliance
-- Business Case: Tracks SLA compliance against contractual obligations
-- Feature Reference: OPS-07 (SLA Management)
-- ====================================================================
CREATE TYPE public.sla_status AS ENUM (
    'COMPLIANT',         -- Meeting SLA targets
    'AT_RISK',           -- Approaching violation threshold
    'VIOLATED',          -- SLA target missed
    'EXEMPT',            -- Excluded from SLA (maintenance window)
    'PENDING'            -- Awaiting data for calculation
);
COMMENT ON TYPE public.sla_status IS 'Service level agreement compliance status';

-- ====================================================================
-- ENUM: maintenance_status
-- Description: Status of scheduled maintenance windows
-- Business Case: Tracks maintenance lifecycle and communicates status to users
-- Feature Reference: OPS-08 (Maintenance Management)
-- ====================================================================
CREATE TYPE public.maintenance_status AS ENUM (
    'SCHEDULED',         -- Planned for future
    'APPROVED',          -- Change approved
    'IN_PROGRESS',       -- Currently executing
    'COMPLETED',         -- Successfully finished
    'EXTENDED',          -- Duration extended beyond plan
    'CANCELLED',         -- Called off
    'FAILED',            -- Unsuccessful execution
    'ROLLED_BACK'        -- Changes reverted
);
COMMENT ON TYPE public.maintenance_status IS 'Status tracking for maintenance windows';

-- ====================================================================
-- FUNCTION: update_timestamp()
-- Description: Automatically updates updated_at timestamp on row modification
-- Business Case: Ensures consistent timestamp tracking across all tables
-- Feature Reference: AUD-01 (Audit Trail)
-- ====================================================================
CREATE OR REPLACE FUNCTION public.update_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.update_timestamp() IS 'Trigger function to automatically update updated_at timestamp';

-- ====================================================================
-- FUNCTION: current_user_id()
-- Description: Returns the current authenticated user ID from session setting
-- Business Case: Enables audit trail and row-level security based on authenticated user
-- Feature Reference: SEC-01 (Authentication)
-- ====================================================================
CREATE OR REPLACE FUNCTION public.current_user_id()
RETURNS UUID AS $$
DECLARE
    user_id UUID;
BEGIN
    -- Get user_id from session variable
    BEGIN
        user_id := current_setting('app.current_user_id')::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
    END;
    RETURN user_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.current_user_id() IS 'Returns UUID of currently authenticated user from session';

-- ====================================================================
-- TABLE: 49 - system_health_metrics
-- Description: Time-series storage of system performance and health metrics
-- Business Case: Proactive monitoring and capacity planning are essential for maintaining
--                service reliability at enterprise scale. This table stores granular metrics
--                about database performance, resource utilization, query execution, and system
--                health. By analyzing trends, the operations team can predict capacity needs
--                before they become critical, identify performance degradation early, and
--                make data-driven decisions about infrastructure investments. The time-series
--                nature enables historical analysis for root cause investigation and
--                performance tuning. Integration with alerting systems ensures rapid response
--                to anomalies.
-- KPIs:
--   1. Average query response time by hour/day
--   2. Peak connection utilization vs. capacity
--   3. Cache hit ratio trends
--   4. Replication lag (if applicable)
--   5. Disk I/O wait times
--   6. CPU utilization patterns
--   7. Memory usage trends
--   8. Longest-running queries per day
-- Feature Reference: OPS-01 (System Monitoring)
-- ====================================================================
CREATE TABLE public.system_health_metrics (
    metric_id BIGSERIAL PRIMARY KEY,
    -- Metric identification
    metric_name VARCHAR(100) NOT NULL,
    metric_type VARCHAR(50) NOT NULL CHECK (metric_type IN (
        'CPU', 'MEMORY', 'DISK', 'NETWORK', 'DATABASE',
        'CONNECTION', 'QUERY', 'CACHE', 'REPLICATION', 'APPLICATION'
    )),
    -- Metric value and context
    metric_value NUMERIC(20,6) NOT NULL,
    metric_unit VARCHAR(20) NOT NULL, -- 'percent', 'ms', 'bytes', 'count', etc.
    -- Source identification
    host_name VARCHAR(255) NOT NULL,
    host_role VARCHAR(50) CHECK (host_role IN ('PRIMARY', 'STANDBY', 'READ_REPLICA', 'APPLICATION')),
    component_name VARCHAR(100),
    -- Additional dimensions
    database_name VARCHAR(100),
    schema_name VARCHAR(100),
    table_name VARCHAR(100),
    query_id BIGINT,
    -- Time dimensions (partitioning key)
    collected_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    -- For aggregation windows
    collection_interval INTERVAL NOT NULL DEFAULT '1 minute',
    -- Additional metadata
    tags JSONB,
    details JSONB,
    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL
) PARTITION BY RANGE (collected_at);

COMMENT ON TABLE public.system_health_metrics IS 'Time-series system health and performance metrics';
COMMENT ON COLUMN public.system_health_metrics.metric_name IS 'Name of the metric (e.g., cpu_usage, query_duration)';
COMMENT ON COLUMN public.system_health_metrics.metric_type IS 'Category of metric for filtering';
COMMENT ON COLUMN public.system_health_metrics.metric_value IS 'Numeric value of the metric';
COMMENT ON COLUMN public.system_health_metrics.metric_unit IS 'Unit of measurement';
COMMENT ON COLUMN public.system_health_metrics.host_name IS 'Server hostname or identifier';
COMMENT ON COLUMN public.system_health_metrics.host_role IS 'Role of the host in the architecture';
COMMENT ON COLUMN public.system_health_metrics.collected_at IS 'Timestamp when metric was collected';
COMMENT ON COLUMN public.system_health_metrics.collection_interval IS 'Interval over which metric was aggregated';

