-- RLS Policy: Only admins and monitoring systems can access
CREATE POLICY system_health_metrics_admin_policy ON public.system_health_metrics
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'system_monitor')
    ));

-- ====================================================================
-- TABLE: 50 - alert_configurations
-- Description: Defines alert thresholds, conditions, and notification rules
-- Business Case: Automated incident detection requires configurable alert rules that
--                can be tuned without code changes. This table stores threshold-based
--                and anomaly-based alert conditions for various metrics, along with
--                severity levels, notification channels, and escalation policies.
--                It enables the operations team to define what constitutes normal
--                behavior versus incidents, set appropriate response expectations,
--                and ensure the right people are notified at the right time. The
--                configuration-driven approach allows for rapid iteration on alert
--                strategies as the system evolves.
-- KPIs:
--   1. Alert accuracy (true positive rate)
--   2. Mean time to detect (MTTD) per alert type
--   3. Alert noise reduction (suppressed alerts count)
--   4. Configuration coverage (metrics with alerts vs. total metrics)
--   5. Escalation effectiveness
--   6. False positive rate by alert type
--   7. Alert response time by severity
-- Feature Reference: OPS-02 (Alert Management)
-- ====================================================================
CREATE TABLE public.alert_configurations (
    alert_config_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Basic identification
    alert_name VARCHAR(255) NOT NULL UNIQUE,
    alert_description TEXT,
    -- Alert source
    metric_name VARCHAR(100) NOT NULL,
    metric_type VARCHAR(50) NOT NULL,
    -- Threshold configuration
    threshold_type VARCHAR(50) NOT NULL CHECK (threshold_type IN (
        'STATIC',           -- Fixed threshold
        'ANOMALY',          -- Deviation from baseline
        'RATE_OF_CHANGE',   -- Sudden change detection
        'COMPOSITE',        -- Combination of conditions
        'PREDICTIVE'        -- Forecast-based alerting
    )),
    -- Threshold values (for static thresholds)
    warning_threshold NUMERIC(20,6),
    critical_threshold NUMERIC(20,6),
    comparison_operator VARCHAR(10) CHECK (comparison_operator IN ('>', '<', '>=', '<=', '=', '!=', 'BETWEEN')),
    -- For BETWEEN operator
    min_threshold NUMERIC(20,6),
    max_threshold NUMERIC(20,6),
    -- Duration conditions (alert only if condition persists)
    duration_threshold INTERVAL,
    -- Anomaly detection parameters
    baseline_period INTERVAL,
    deviation_factor NUMERIC(5,2) CHECK (deviation_factor > 0),
    -- Rate of change parameters
    rate_window INTERVAL,
    rate_threshold NUMERIC(20,6),
    -- Alert behavior
    severity public.alert_severity NOT NULL,
    status public.alert_status DEFAULT 'TRIGGERED',
    priority INTEGER DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), -- 1 highest
    -- Suppression rules
    suppress_during_maintenance BOOLEAN DEFAULT true,
    suppress_if_resolved BOOLEAN DEFAULT true,
    max_alerts_per_hour INTEGER DEFAULT 10,
    -- Notification configuration
    notification_channels TEXT[] CHECK (
        notification_channels <@ ARRAY['EMAIL', 'SLACK', 'PAGER_DUTY', 'SMS', 'WEBHOOK']
    ),
    notification_template TEXT,
    escalation_delay INTERVAL,
    escalation_channels TEXT[],
    escalation_recipients TEXT[],
    -- Recipients
    recipients TEXT[], -- Email addresses, Slack channels, etc.
    on_call_schedule_id UUID,
    -- Evaluation schedule
    evaluation_interval INTERVAL NOT NULL DEFAULT '1 minute',
    is_active BOOLEAN DEFAULT true,
    -- Filtering criteria
    filter_tags JSONB, -- Only alert if tags match
    filter_hosts TEXT[], -- Limit to specific hosts
    filter_components TEXT[],
    -- Custom logic (for advanced conditions)
    custom_condition TEXT, -- SQL expression or script reference
    -- Audit columns
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Version tracking
    version INTEGER DEFAULT 1,
    -- Last evaluation
    last_evaluated_at TIMESTAMP WITH TIME ZONE,
    last_triggered_at TIMESTAMP WITH TIME ZONE,
    -- Metadata
    tags TEXT[],
    notes TEXT
);

COMMENT ON TABLE public.alert_configurations IS 'Configurable alert rules and notification policies';
COMMENT ON COLUMN public.alert_configurations.alert_name IS 'Unique name for the alert configuration';
COMMENT ON COLUMN public.alert_configurations.threshold_type IS 'Type of threshold detection algorithm';
COMMENT ON COLUMN public.alert_configurations.severity IS 'Severity level when alert triggers';
COMMENT ON COLUMN public.alert_configurations.duration_threshold IS 'How long condition must persist before alerting';
COMMENT ON COLUMN public.alert_configurations.notification_channels IS 'List of channels for alert notifications';
COMMENT ON COLUMN public.alert_configurations.escalation_delay IS 'Time before escalating to next level';

-- Indexes for alert_configurations
CREATE INDEX idx_alert_configurations_metric ON public.alert_configurations(metric_name, metric_type) WHERE is_active = true;
CREATE INDEX idx_alert_configurations_severity ON public.alert_configurations(severity, priority);
CREATE INDEX idx_alert_configurations_active ON public.alert_configurations(is_active, last_evaluated_at);

-- Trigger for updated_at
CREATE TRIGGER update_alert_configurations_timestamp
    BEFORE UPDATE ON public.alert_configurations
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.alert_configurations ENABLE ROW LEVEL SECURITY;

-- RLS Policy: Only admins and system operators
CREATE POLICY alert_configurations_admin_policy ON public.alert_configurations
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'system_operator')
    ));

-- ====================================================================
-- TABLE: 51 - incident_reports
-- Description: Structured documentation of system incidents and outages
-- Business Case: Learning from failures is essential for building reliable systems.
--                This table provides a structured format for documenting incidents,
--                including timeline, impact assessment, root cause analysis, and
--                corrective actions. It serves as the foundation for post-mortem
--                culture, enabling teams to identify patterns, prevent recurrence,
--                and demonstrate continuous improvement to auditors and customers.
--                The structured data also feeds into reliability metrics and helps
--                identify areas requiring investment in resilience.
-- KPIs:
--   1. Mean time to resolve (MTTR) by severity
--   2. Number of incidents per week/month
--   3. Incident recurrence rate
--   4. Root cause category distribution
--   5. Customer impact (users affected, revenue impact)
--   6. Post-mortem completion rate within SLA
--   7. Action item closure rate
-- Feature Reference: OPS-03 (Incident Management)
-- ====================================================================
CREATE TABLE public.incident_reports (
    incident_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Incident identification
    incident_number VARCHAR(50) GENERATED ALWAYS AS (
        'INC-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('incident_seq')::TEXT, 4, '0')
    ) STORED,
    incident_title VARCHAR(500) NOT NULL,
    incident_description TEXT NOT NULL,
    -- Classification
    severity public.incident_severity NOT NULL,
    status public.incident_status DEFAULT 'DETECTED',
    incident_type VARCHAR(50) CHECK (incident_type IN (
        'OUTAGE', 'DEGRADATION', 'SECURITY', 'DATA_CORRUPTION',
        'PERFORMANCE', 'DEPLOYMENT', 'INFRASTRUCTURE', 'THIRD_PARTY'
    )),
    -- Timeline
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    acknowledged_at TIMESTAMP WITH TIME ZONE,
    mitigation_started_at TIMESTAMP WITH TIME ZONE,
    resolved_at TIMESTAMP WITH TIME ZONE,
    closed_at TIMESTAMP WITH TIME ZONE,
    -- Impact assessment
    impacted_services TEXT[],
    impacted_users INTEGER,
    impacted_customers TEXT[], -- Customer names/IDs if known
    revenue_impact NUMERIC(15,2),
    data_loss_occurred BOOLEAN DEFAULT false,
    data_loss_description TEXT,
    -- Root cause
    root_cause_category VARCHAR(50) CHECK (root_cause_category IN (
        'CODE_BUG', 'CONFIGURATION', 'INFRASTRUCTURE', 'THIRD_PARTY',
        'HUMAN_ERROR', 'CAPACITY', 'SECURITY', 'UNKNOWN'
    )),
    root_cause_description TEXT,
    root_cause_evidence JSONB,
    -- Resolution
    resolution_description TEXT,
    workaround_description TEXT,
    permanent_fix_description TEXT,
    -- Team assignment
    incident_commander_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    responding_team VARCHAR(100),
    responding_team_members UUID[],
    -- Post-mortem
    post_mortem_completed BOOLEAN DEFAULT false,
    post_mortem_document_url TEXT,
    post_mortem_summary TEXT,
    post_mortem_completed_at TIMESTAMP WITH TIME ZONE,
    -- Action items (stored as JSON for flexibility, could be separate table)
    action_items JSONB, -- Array of {description, owner, due_date, status}
    -- Communication
    internal_communication_log JSONB,
    customer_communication_sent BOOLEAN DEFAULT false,
    customer_communication_url TEXT,
    -- SLA impact
    sla_violated BOOLEAN DEFAULT false,
    sla_credit_due NUMERIC(15,2),
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    related_incidents UUID[],
    CONSTRAINT incident_timeline_check CHECK (
        acknowledged_at >= detected_at AND
        (mitigation_started_at IS NULL OR mitigation_started_at >= acknowledged_at) AND
        (resolved_at IS NULL OR resolved_at >= mitigation_started_at) AND
        (closed_at IS NULL OR closed_at >= resolved_at)
    )
);

COMMENT ON TABLE public.incident_reports IS 'Structured documentation of system incidents and outages';
COMMENT ON COLUMN public.incident_reports.incident_number IS 'Human-readable incident identifier';
COMMENT ON COLUMN public.incident_reports.severity IS 'Impact severity classification';
COMMENT ON COLUMN public.incident_reports.incident_commander_id IS 'User leading the incident response';
COMMENT ON COLUMN public.incident_reports.action_items IS 'Follow-up tasks from post-mortem';
COMMENT ON COLUMN public.incident_reports.sla_violated IS 'Whether incident violated service level agreements';

-- Create sequence for incident numbering
CREATE SEQUENCE public.incident_seq START 1;

-- Indexes for incident_reports
CREATE INDEX idx_incident_reports_detected_at ON public.incident_reports(detected_at DESC);
CREATE INDEX idx_incident_reports_severity ON public.incident_reports(severity, status);
CREATE INDEX idx_incident_reports_root_cause ON public.incident_reports(root_cause_category);
CREATE INDEX idx_incident_reports_commander ON public.incident_reports(incident_commander_id) WHERE incident_commander_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_incident_reports_timestamp
    BEFORE UPDATE ON public.incident_reports
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.incident_reports ENABLE ROW LEVEL SECURITY;

-- RLS Policy: Incident responders and admins
CREATE POLICY incident_reports_responder_policy ON public.incident_reports
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'incident_responder')
    ));

-- ====================================================================
-- TABLE: 52 - backup_verification_logs
-- Description: Tracks backup execution, integrity verification, and restoration tests
-- Business Case: Backups are only valuable if they can be successfully restored.
--                This table provides comprehensive tracking of backup operations,
--                including verification of backup integrity, periodic restoration
--                tests, and compliance with Recovery Point Objectives (RPO) and
--                Recovery Time Objectives (RTO). It serves as audit evidence for
--                compliance requirements (SOC2, ISO27001) and ensures that data
--                loss incidents can be properly investigated. The verification
--                history enables trend analysis of backup reliability and helps
--                identify systemic issues before they cause data loss.
-- KPIs:
--   1. Backup success rate by type
--   2. Time to complete backup vs. backup window
--   3. Restoration test success rate
--   4. Data volume growth vs. backup time trend
--   5. Recovery Point Objective (RPO) compliance percentage
--   6. Recovery Time Objective (RTO) compliance percentage
--   7. Number of backup failures by type
--   8. Time since last successful restoration test
-- Feature Reference: OPS-04 (Backup Management)
-- ====================================================================
CREATE TABLE public.backup_verification_logs (
    backup_log_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Backup identification
    backup_id VARCHAR(255) NOT NULL,
    backup_name VARCHAR(500),
    backup_type public.backup_type NOT NULL,
    -- Database information
    database_name VARCHAR(100) NOT NULL,
    schema_name VARCHAR(100),
    table_name VARCHAR(100),
    -- Backup details
    backup_size_bytes BIGINT,
    compressed_size_bytes BIGINT,
    backup_location TEXT NOT NULL,
    backup_provider VARCHAR(50) CHECK (backup_provider IN ('AWS_S3', 'AZURE_BLOB', 'GCP_STORAGE', 'LOCAL', 'CUSTOM')),
    encryption_algorithm VARCHAR(50),
    encryption_key_id VARCHAR(255),
    -- Schedule information
    scheduled_start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    actual_start_time TIMESTAMP WITH TIME ZONE,
    actual_end_time TIMESTAMP WITH TIME ZONE,
    duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (actual_end_time - actual_start_time))
    ) STORED,
    -- Status
    status public.backup_status NOT NULL,
    error_message TEXT,
    error_details JSONB,
    -- Verification
    verified_at TIMESTAMP WITH TIME ZONE,
    verified_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    verification_method VARCHAR(50) CHECK (verification_method IN (
        'CHECKSUM', 'RESTORE_TEST', 'MOUNT_TEST', 'VALIDATION', 'MANUAL'
    )),
    verification_result BOOLEAN,
    verification_details TEXT,
    -- Restoration test (if performed)
    restoration_test_id UUID,
    restoration_test_started_at TIMESTAMP WITH TIME ZONE,
    restoration_test_completed_at TIMESTAMP WITH TIME ZONE,
    restoration_test_success BOOLEAN,
    restoration_test_duration INTEGER,
    -- Retention
    retention_days INTEGER NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE,
    deletion_confirmed_at TIMESTAMP WITH TIME ZONE,
    deletion_confirmed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    notes TEXT,
    CONSTRAINT backup_timeline_check CHECK (
        actual_start_time >= scheduled_start_time AND
        (actual_end_time IS NULL OR actual_end_time >= actual_start_time)
    )
);

COMMENT ON TABLE public.backup_verification_logs IS 'Comprehensive tracking of backup operations and verification tests';
COMMENT ON COLUMN public.backup_verification_logs.backup_id IS 'Unique identifier from backup system';
COMMENT ON COLUMN public.backup_verification_logs.verification_method IS 'Method used to verify backup integrity';
COMMENT ON COLUMN public.backup_verification_logs.restoration_test_id IS 'ID of associated restoration test';
COMMENT ON COLUMN public.backup_verification_logs.expires_at IS 'When backup can be deleted based on retention policy';

-- Indexes for backup_verification_logs
CREATE INDEX idx_backup_logs_status ON public.backup_verification_logs(status, backup_type);
CREATE INDEX idx_backup_logs_scheduled_time ON public.backup_verification_logs(scheduled_start_time DESC);
CREATE INDEX idx_backup_logs_expires_at ON public.backup_verification_logs(expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX idx_backup_logs_database ON public.backup_verification_logs(database_name, scheduled_start_time DESC);
CREATE INDEX idx_backup_logs_verification ON public.backup_verification_logs(verified_at) WHERE verified_at IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_backup_verification_logs_timestamp
    BEFORE UPDATE ON public.backup_verification_logs
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.backup_verification_logs ENABLE ROW LEVEL SECURITY;

-- RLS Policy: Backup operators and admins
CREATE POLICY backup_verification_logs_admin_policy ON public.backup_verification_logs
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'backup_operator')
    ));

-- ====================================================================
-- TABLE: 53 - disaster_recovery_tests
-- Description: Documents disaster recovery drill results and procedures
-- Business Case: Regular disaster recovery testing is a compliance requirement for
--                enterprise systems (SOC2, ISO27001, financial regulations). This table
--                provides a structured format for planning, executing, and documenting
--                DR drills. It tracks test objectives, success criteria, actual results,
--                and lessons learned. The historical data demonstrates due diligence to
--                auditors and helps improve recovery procedures over time. It also
--                enables measurement of recovery capabilities against business
--                requirements and identifies gaps requiring investment.
-- KPIs:
--   1. DR test success rate
--   2. Time to achieve recovery (RTO compliance)
--   3. Data loss during recovery (RPO compliance)
--   4. Number of DR tests per year by type
--   5. Improvement in recovery time over successive tests
--   6. Number of identified gaps/improvements per test
--   7. Test coverage of critical systems
-- Feature Reference: OPS-05 (Disaster Recovery)
-- ====================================================================
CREATE TABLE public.disaster_recovery_tests (
    dr_test_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Test identification
    test_number VARCHAR(50) GENERATED ALWAYS AS (
        'DR-' || TO_CHAR(scheduled_date, 'YYYYMMDD') || '-' || LPAD(nextval('dr_test_seq')::TEXT, 3, '0')
    ) STORED,
    test_name VARCHAR(500) NOT NULL,
    test_description TEXT,
    -- Test type and scope
    test_type VARCHAR(50) NOT NULL CHECK (test_type IN (
        'TABLE_TOP',           -- Walkthrough without actual failover
        'COMPONENT_FAILOVER',  -- Test single component
        'PARTIAL_FAILOVER',    -- Test subset of systems
        'FULL_FAILOVER',       -- Complete site failover
        'CHAOS_ENGINEERING'    -- Deliberate failure injection
    )),
    scope VARCHAR(50) CHECK (scope IN ('DATABASE', 'APPLICATION', 'INFRASTRUCTURE', 'FULL_STACK')),
    systems_tested TEXT[], -- List of systems/components tested
    -- Schedule
    scheduled_date DATE NOT NULL,
    actual_start_date TIMESTAMP WITH TIME ZONE,
    actual_end_date TIMESTAMP WITH TIME ZONE,
    duration_hours NUMERIC(8,2) GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (actual_end_date - actual_start_date)) / 3600
    ) STORED,
    -- Objectives and success criteria
    objectives TEXT NOT NULL,
    success_criteria JSONB NOT NULL, -- Array of criteria with targets
    -- Results
    status public.dr_test_status NOT NULL,
    results_summary TEXT,
    results_details JSONB, -- Actual results against success criteria
    -- Recovery metrics
    rto_achieved_minutes INTEGER,
    rpo_achieved_minutes INTEGER,
    data_loss_detected BOOLEAN DEFAULT false,
    data_loss_description TEXT,
    -- Failover details
    primary_site VARCHAR(255),
    failover_site VARCHAR(255),
    failover_duration_minutes INTEGER,
    failback_duration_minutes INTEGER,
    failback_completed BOOLEAN,
    -- Issues encountered
    issues_detected TEXT[],
    issue_details JSONB,
    -- Lessons learned
    lessons_learned TEXT,
    improvements_identified TEXT[],
    action_items JSONB, -- Array of {description, owner, due_date}
    -- Team
    test_lead_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    participants UUID[],
    observers UUID[],
    -- Documentation
    test_plan_url TEXT,
    test_report_url TEXT,
    test_logs_url TEXT,
    -- Compliance
    compliance_requirement VARCHAR(100),
    auditor_witnessed BOOLEAN DEFAULT false,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    notes TEXT,
    next_test_date DATE -- Recommended next test date
);

COMMENT ON TABLE public.disaster_recovery_tests IS 'Documentation of disaster recovery drill execution and results';
COMMENT ON COLUMN public.disaster_recovery_tests.test_number IS 'Human-readable test identifier';
COMMENT ON COLUMN public.disaster_recovery_tests.test_type IS 'Type of DR test being conducted';
COMMENT ON COLUMN public.disaster_recovery_tests.rto_achieved_minutes IS 'Actual time to recover (Recovery Time Objective)';
COMMENT ON COLUMN public.disaster_recovery_tests.rpo_achieved_minutes IS 'Actual data loss in minutes (Recovery Point Objective)';
COMMENT ON COLUMN public.disaster_recovery_tests.action_items IS 'Follow-up tasks from test findings';

-- Create sequence for DR test numbering
CREATE SEQUENCE public.dr_test_seq START 1;

-- Indexes for disaster_recovery_tests
CREATE INDEX idx_dr_tests_scheduled_date ON public.disaster_recovery_tests(scheduled_date DESC);
CREATE INDEX idx_dr_tests_status ON public.disaster_recovery_tests(status);
CREATE INDEX idx_dr_tests_type ON public.disaster_recovery_tests(test_type);
CREATE INDEX idx_dr_tests_lead ON public.disaster_recovery_tests(test_lead_id) WHERE test_lead_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_disaster_recovery_tests_timestamp
    BEFORE UPDATE ON public.disaster_recovery_tests
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.disaster_recovery_tests ENABLE ROW LEVEL SECURITY;

-- RLS Policy: DR team and admins
CREATE POLICY disaster_recovery_tests_admin_policy ON public.disaster_recovery_tests
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'dr_coordinator')
    ));

-- ====================================================================
-- TABLE: 54 - capacity_plans
-- Description: Forecasts resource requirements based on growth trends and business plans
-- Business Case: Proactive capacity planning prevents performance degradation and
--                outages caused by resource exhaustion. This table stores capacity
--                forecasts for various resources (storage, memory, connections, etc.)
--                based on historical trends, business growth projections, and planned
--                feature launches. It enables data-driven infrastructure investment
--                decisions and provides early warning of approaching limits. The
--                comparison between forecasts and actual usage helps refine prediction
--                models and improves planning accuracy over time.
-- KPIs:
--   1. Forecast accuracy (actual vs. predicted)
--   2. Time from capacity warning to exhaustion
--   3. Number of capacity-related incidents
--   4. Resource utilization trends by type
--   5. Provisioning lead time vs. growth rate
--   6. Capacity buffer percentage by resource
--   7. Cost efficiency (utilization vs. provisioned)
-- Feature Reference: OPS-06 (Capacity Management)
-- ====================================================================
CREATE TABLE public.capacity_plans (
    capacity_plan_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Plan identification
    plan_name VARCHAR(255) NOT NULL,
    plan_version VARCHAR(20) NOT NULL,
    plan_description TEXT,
    -- Planning horizon
    planning_year INTEGER NOT NULL CHECK (planning_year >= EXTRACT(YEAR FROM CURRENT_DATE)),
    planning_quarter INTEGER CHECK (planning_quarter BETWEEN 1 AND 4),
    planning_month INTEGER CHECK (planning_month BETWEEN 1 AND 12),
    -- Resource type
    resource_type VARCHAR(50) NOT NULL CHECK (resource_type IN (
        'STORAGE', 'MEMORY', 'CPU', 'CONNECTIONS', 'NETWORK_BANDWIDTH',
        'IOPS', 'THROUGHPUT', 'API_CALLS', 'ACTIVE_USERS', 'CONCURRENT_SESSIONS'
    )),
    resource_unit VARCHAR(50) NOT NULL,
    -- Current state
    current_capacity NUMERIC(20,6) NOT NULL,
    current_utilization NUMERIC(20,6) NOT NULL,
    current_utilization_percent NUMERIC(5,2) GENERATED ALWAYS AS (
        (current_utilization / NULLIF(current_capacity, 0)) * 100
    ) STORED,
    -- Forecasts
    forecast_3_months NUMERIC(20,6),
    forecast_6_months NUMERIC(20,6),
    forecast_12_months NUMERIC(20,6),
    forecast_24_months NUMERIC(20,6),
    -- Growth assumptions
    growth_rate_percent NUMERIC(5,2),
    growth_drivers JSONB, -- Factors driving growth
    -- Thresholds
    warning_threshold_percent NUMERIC(5,2) DEFAULT 70,
    critical_threshold_percent NUMERIC(5,2) DEFAULT 85,
    -- Action plans
    action_required BOOLEAN DEFAULT false,
    action_description TEXT,
    action_owner UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    action_due_date DATE,
    action_status VARCHAR(50) CHECK (action_status IN ('PENDING', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED')),
    -- Procurement details
    procurement_plan TEXT,
    estimated_cost NUMERIC(15,2),
    cost_currency CHAR(3) DEFAULT 'USD',
    procurement_lead_time_days INTEGER,
    -- Validation
    last_reviewed_at TIMESTAMP WITH TIME ZONE,
    last_reviewed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    next_review_date DATE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    notes TEXT,
    CONSTRAINT unique_capacity_plan UNIQUE (resource_type, planning_year, planning_quarter, planning_month)
);

COMMENT ON TABLE public.capacity_plans IS 'Resource capacity forecasts and planning';
COMMENT ON COLUMN public.capacity_plans.plan_name IS 'Name of the capacity plan';
COMMENT ON COLUMN public.capacity_plans.plan_version IS 'Version tracking for iterative planning';
COMMENT ON COLUMN public.capacity_plans.forecast_12_months IS 'Projected resource needs in 12 months';
COMMENT ON COLUMN public.capacity_plans.action_required IS 'Flag indicating if action is needed to address capacity gap';
COMMENT ON COLUMN public.capacity_plans.procurement_plan IS 'Description of planned capacity additions';

-- Indexes for capacity_plans
CREATE INDEX idx_capacity_plans_resource ON public.capacity_plans(resource_type, planning_year, planning_quarter);
CREATE INDEX idx_capacity_plans_action ON public.capacity_plans(action_required, action_due_date) WHERE action_required = true;
CREATE INDEX idx_capacity_plans_next_review ON public.capacity_plans(next_review_date) WHERE next_review_date IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_capacity_plans_timestamp
    BEFORE UPDATE ON public.capacity_plans
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.capacity_plans ENABLE ROW LEVEL SECURITY;

-- RLS Policy: Capacity planners and admins
CREATE POLICY capacity_plans_admin_policy ON public.capacity_plans
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'capacity_planner')
    ));

-- ====================================================================
-- TABLE: 55 - sla_tracking
-- Description: Measures and records compliance with service level agreements
-- Business Case: Customer contracts often include service level agreements (SLAs)
--                with financial penalties for non-compliance. This table tracks actual
--                performance against SLA targets for various metrics (uptime, response
--                time, resolution time, etc.). It provides the data needed for
--                compliance reporting, penalty calculation, and continuous improvement.
--                The historical data also helps identify patterns that might lead to
--                SLA violations and enables proactive intervention.
-- KPIs:
--   1. SLA compliance percentage by service
--   2. Number of SLA violations per period
--   3. Mean time between SLA violations
--   4. Financial impact of SLA penalties
--   5. Customer-specific compliance rates
--   6. Trending of compliance over time
--   7. Root cause distribution of violations
-- Feature Reference: OPS-07 (SLA Management)
-- ====================================================================
CREATE TABLE public.sla_tracking (
    sla_tracking_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- SLA identification
    sla_contract_id VARCHAR(100) NOT NULL,
    sla_name VARCHAR(255) NOT NULL,
    customer_id UUID REFERENCES public.companies(company_id) ON DELETE CASCADE,
    customer_tier VARCHAR(50) CHECK (customer_tier IN ('PREMIUM', 'STANDARD', 'BASIC')),
    -- Service definition
    service_name VARCHAR(255) NOT NULL,
    service_component VARCHAR(255),
    -- Metric definition
    metric_name VARCHAR(100) NOT NULL,
    metric_unit VARCHAR(50),
    -- SLA targets
    target_value NUMERIC(20,6) NOT NULL,
    target_operator VARCHAR(10) CHECK (target_operator IN ('<', '<=', '=', '>=', '>')),
    target_period INTERVAL, -- e.g., '1 month' for monthly targets
    measurement_window INTERVAL, -- e.g., '5 minutes' for availability measurement
    -- Performance measurement
    measurement_start TIMESTAMP WITH TIME ZONE NOT NULL,
    measurement_end TIMESTAMP WITH TIME ZONE NOT NULL,
    actual_value NUMERIC(20,6),
    -- Compliance calculation
    status public.sla_status NOT NULL,
    violation_reason TEXT,
    violation_severity VARCHAR(50) CHECK (violation_severity IN ('MINOR', 'MAJOR', 'CRITICAL')),
    -- Business impact
    customer_impacted_users INTEGER,
    customer_impact_description TEXT,
    -- Financial implications
    penalty_applicable BOOLEAN DEFAULT false,
    penalty_amount NUMERIC(15,2),
    penalty_currency CHAR(3) DEFAULT 'USD',
    penalty_invoiced BOOLEAN DEFAULT false,
    -- Exclusions
    excluded_due_to_maintenance BOOLEAN DEFAULT false,
    excluded_maintenance_id UUID REFERENCES public.maintenance_windows(maintenance_id) ON DELETE SET NULL,
    -- Reporting
    report_generated BOOLEAN DEFAULT false,
    report_url TEXT,
    customer_notified BOOLEAN DEFAULT false,
    notification_sent_at TIMESTAMP WITH TIME ZONE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    notes TEXT,
    CONSTRAINT sla_measurement_period CHECK (measurement_end > measurement_start)
);

COMMENT ON TABLE public.sla_tracking IS 'Tracking and measurement of service level agreement compliance';
COMMENT ON COLUMN public.sla_tracking.sla_contract_id IS 'Reference to the SLA contract document';
COMMENT ON COLUMN public.sla_tracking.target_value IS 'SLA target value for the metric';
COMMENT ON COLUMN public.sla_tracking.actual_value IS 'Actual measured performance';
COMMENT ON COLUMN public.sla_tracking.status IS 'Compliance status against target';
COMMENT ON COLUMN public.sla_tracking.penalty_amount IS 'Financial penalty for violation (if applicable)';

-- Indexes for sla_tracking
CREATE INDEX idx_sla_tracking_customer ON public.sla_tracking(customer_id, measurement_start DESC);
CREATE INDEX idx_sla_tracking_status ON public.sla_tracking(status, measurement_end DESC);
CREATE INDEX idx_sla_tracking_service ON public.sla_tracking(service_name, measurement_start DESC);
CREATE INDEX idx_sla_tracking_violations ON public.sla_tracking(measurement_start, measurement_end) WHERE status = 'VIOLATED';

-- Trigger for updated_at
CREATE TRIGGER update_sla_tracking_timestamp
    BEFORE UPDATE ON public.sla_tracking
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.sla_tracking ENABLE ROW LEVEL SECURITY;

-- RLS Policy: Account managers and admins
CREATE POLICY sla_tracking_admin_policy ON public.sla_tracking
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'account_manager')
    ));

-- ====================================================================
-- TABLE: 56 - cost_allocation
-- Description: Tracks infrastructure costs attributed to specific features, teams, or customers
-- Business Case: In cloud environments, understanding cost drivers is essential for
--                optimization and showback/chargeback models. This table captures
--                detailed cost data from cloud providers (AWS, Azure, GCP) and maps
--                it to internal dimensions like feature, team, or customer. It enables
--                data-driven decisions about infrastructure investment, identifies
--                opportunities for cost optimization, and supports business models
--                where customers are billed based on usage. The attribution data
--                also helps product managers understand the cost impact of feature
--                decisions.
-- KPIs:
--   1. Cost per transaction/API call by feature
--   2. Cost trend by service/resource type
--   3. Cost attribution coverage percentage
--   4. Cost savings from optimization initiatives
--   5. Forecast accuracy (budget vs. actual)
--   6. Cost per customer/tenant
--   7. Resource efficiency (cost per unit of work)
-- Feature Reference: OPS-08 (Cost Management)
-- ====================================================================
CREATE TABLE public.cost_allocation (
    cost_allocation_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Cost period
    cost_date DATE NOT NULL,
    cost_month DATE GENERATED ALWAYS AS (DATE_TRUNC('month', cost_date)) STORED,
    cost_quarter DATE GENERATED ALWAYS AS (DATE_TRUNC('quarter', cost_date)) STORED,
    cost_year INTEGER GENERATED ALWAYS AS (EXTRACT(YEAR FROM cost_date)) STORED,
    -- Source data
    provider VARCHAR(50) NOT NULL CHECK (provider IN ('AWS', 'AZURE', 'GCP', 'ON_PREMISE', 'OTHER')),
    provider_account_id VARCHAR(255),
    service_name VARCHAR(255) NOT NULL,
    resource_type VARCHAR(255),
    resource_id VARCHAR(255),
    region VARCHAR(100),
    -- Cost amounts
    cost_amount NUMERIC(15,4) NOT NULL,
    currency CHAR(3) NOT NULL,
    amount_usd NUMERIC(15,4) GENERATED ALWAYS AS (
        cost_amount * COALESCE(exchange_rate_to_usd, 1)
    ) STORED,
    exchange_rate_to_usd NUMERIC(10,6),
    -- Usage metrics
    usage_quantity NUMERIC(20,6),
    usage_unit VARCHAR(50),
    pricing_model VARCHAR(50) CHECK (pricing_model IN ('ON_DEMAND', 'RESERVED', 'SPOT', 'SAVINGS_PLAN', 'FREE_TIER')),
    -- Allocation dimensions
    feature_name VARCHAR(255),
    team_name VARCHAR(255),
    project_name VARCHAR(255),
    environment VARCHAR(50) CHECK (environment IN ('PRODUCTION', 'STAGING', 'DEVELOPMENT', 'TESTING')),
    customer_id UUID REFERENCES public.companies(company_id) ON DELETE SET NULL,
    user_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    -- Allocation method
    allocation_method VARCHAR(50) CHECK (allocation_method IN (
        'DIRECT', 'PRO_RATA', 'FIXED_PERCENTAGE', 'USAGE_BASED', 'MANUAL'
    )),
    allocation_percentage NUMERIC(5,2) CHECK (allocation_percentage BETWEEN 0 AND 100),
    -- Budget tracking
    budget_id VARCHAR(255),
    budget_category VARCHAR(255),
    -- Tags from cloud provider
    provider_tags JSONB,
    -- Internal annotations
    internal_notes TEXT,
    is_estimated BOOLEAN DEFAULT false,
    estimated_at TIMESTAMP WITH TIME ZONE,
    actual_cost_reconciled BOOLEAN DEFAULT false,
    reconciled_at TIMESTAMP WITH TIME ZONE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    CONSTRAINT unique_cost_allocation UNIQUE (provider, provider_account_id, resource_id, cost_date, feature_name)
);

COMMENT ON TABLE public.cost_allocation IS 'Infrastructure cost tracking and attribution to features/teams/customers';
COMMENT ON COLUMN public.cost_allocation.cost_date IS 'Date when cost was incurred';
COMMENT ON COLUMN public.cost_allocation.amount_usd IS 'Cost normalized to USD for comparison';
COMMENT ON COLUMN public.cost_allocation.feature_name IS 'Feature or product to which cost is attributed';
COMMENT ON COLUMN public.cost_allocation.team_name IS 'Team responsible for the resource';
COMMENT ON COLUMN public.cost_allocation.environment IS 'Deployment environment for the resource';
COMMENT ON COLUMN public.cost_allocation.is_estimated IS 'Whether cost is estimated (vs. actual billing data)';

-- Indexes for cost_allocation
CREATE INDEX idx_cost_allocation_date ON public.cost_allocation(cost_date DESC);
CREATE INDEX idx_cost_allocation_feature ON public.cost_allocation(feature_name, cost_date DESC) WHERE feature_name IS NOT NULL;
CREATE INDEX idx_cost_allocation_customer ON public.cost_allocation(customer_id, cost_date DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX idx_cost_allocation_team ON public.cost_allocation(team_name, cost_date DESC) WHERE team_name IS NOT NULL;
CREATE INDEX idx_cost_allocation_provider ON public.cost_allocation(provider, cost_date DESC);

-- Trigger for updated_at
CREATE TRIGGER update_cost_allocation_timestamp
    BEFORE UPDATE ON public.cost_allocation
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.cost_allocation ENABLE ROW LEVEL SECURITY;

-- RLS Policy: Finance team and admins
CREATE POLICY cost_allocation_admin_policy ON public.cost_allocation
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'finance')
    ));

-- ====================================================================
-- TABLE: 57 - maintenance_windows
-- Description: Schedules and tracks planned maintenance activities
-- Business Case: Communicating planned downtime to users is essential for maintaining
--                trust and meeting SLA requirements. This table provides a centralized
--                schedule of all planned maintenance activities, including scope,
--                expected impact, and notification status. It enables coordination
--                across teams, ensures proper approvals are obtained, and documents
--                that maintenance was performed according to policy. The history of
--                maintenance windows also helps analyze the effectiveness of maintenance
--                practices and their impact on system stability.
-- KPIs:
--   1. Maintenance frequency by system
--   2. Actual vs. planned duration variance
--   3. Number of emergency vs. planned maintenances
--   4. Customer notification lead time
--   5. Maintenance success rate (no post-maintenance incidents)
--   6. Compliance with maintenance windows (staying within schedule)
--   7. User complaints per maintenance
-- Feature Reference: OPS-09 (Maintenance Management)
-- ====================================================================
CREATE TABLE public.maintenance_windows (
    maintenance_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Identification
    maintenance_number VARCHAR(50) GENERATED ALWAYS AS (
        'MNT-' || TO_CHAR(scheduled_start_time, 'YYYYMMDD') || '-' || LPAD(nextval('maintenance_seq')::TEXT, 4, '0')
    ) STORED,
    maintenance_title VARCHAR(500) NOT NULL,
    maintenance_description TEXT NOT NULL,
    -- Type and scope
    maintenance_type VARCHAR(50) NOT NULL CHECK (maintenance_type IN (
        'SCHEDULED', 'EMERGENCY', 'ROLLING_UPGRADE', 'PATCHING', 'SCALING',
        'DATABASE_MIGRATION', 'HARDWARE_REPLACEMENT', 'SECURITY_UPDATE'
    )),
    risk_level public.change_risk_level NOT NULL,
    scope VARCHAR(50) CHECK (scope IN ('DATABASE', 'APPLICATION', 'INFRASTRUCTURE', 'NETWORK', 'FULL_STACK')),
    -- Schedule
    scheduled_start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    scheduled_end_time TIMESTAMP WITH TIME ZONE NOT NULL,
    actual_start_time TIMESTAMP WITH TIME ZONE,
    actual_end_time TIMESTAMP WITH TIME ZONE,
    duration_minutes INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (actual_end_time - actual_start_time)) / 60
    ) STORED,
    -- Status
    status public.maintenance_status NOT NULL DEFAULT 'SCHEDULED',
    -- Impact
    expected_impact TEXT,
    actual_impact TEXT,
    impacted_services TEXT[],
    impacted_users_estimate INTEGER,
    -- Approvals
    requires_approval BOOLEAN DEFAULT true,
    approved_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    approved_at TIMESTAMP WITH TIME ZONE,
    approval_notes TEXT,
    -- Team
    responsible_team VARCHAR(100) NOT NULL,
    responsible_individuals UUID[],
    on_call_contact VARCHAR(255),
    -- Change management integration
    change_request_id UUID REFERENCES public.change_requests(change_request_id) ON DELETE SET NULL,
    -- Notifications
    notification_sent BOOLEAN DEFAULT false,
    notification_sent_at TIMESTAMP WITH TIME ZONE,
    notification_method VARCHAR(50) CHECK (notification_method IN ('EMAIL', 'PORTAL', 'BOTH')),
    notification_audience TEXT[], -- List of customer emails, teams, etc.
    -- Execution details
    pre_checks_passed BOOLEAN,
    pre_checks_notes TEXT,
    post_checks_passed BOOLEAN,
    post_checks_notes TEXT,
    rollback_executed BOOLEAN DEFAULT false,
    rollback_reason TEXT,
    -- Post-maintenance
    issues_encountered TEXT,
    lessons_learned TEXT,
    follow_up_actions TEXT[],
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    notes TEXT,
    CONSTRAINT maintenance_schedule_check CHECK (
        scheduled_end_time > scheduled_start_time AND
        (actual_end_time IS NULL OR actual_end_time >= actual_start_time)
    )
);

COMMENT ON TABLE public.maintenance_windows IS 'Scheduled maintenance activities with approval and notification tracking';
COMMENT ON COLUMN public.maintenance_windows.maintenance_number IS 'Human-readable maintenance identifier';
COMMENT ON COLUMN public.maintenance_windows.risk_level IS 'Risk assessment of maintenance activity';
COMMENT ON COLUMN public.maintenance_windows.expected_impact IS 'Description of expected service impact';
COMMENT ON COLUMN public.maintenance_windows.rollback_executed IS 'Whether rollback was needed';
COMMENT ON COLUMN public.maintenance_windows.follow_up_actions IS 'Post-maintenance action items';

-- Create sequence for maintenance numbering
CREATE SEQUENCE public.maintenance_seq START 1;

-- Indexes for maintenance_windows
CREATE INDEX idx_maintenance_scheduled ON public.maintenance_windows(scheduled_start_time, scheduled_end_time);
CREATE INDEX idx_maintenance_status ON public.maintenance_windows(status, scheduled_start_time);
CREATE INDEX idx_maintenance_type ON public.maintenance_windows(maintenance_type, scheduled_start_time DESC);
CREATE INDEX idx_maintenance_team ON public.maintenance_windows(responsible_team, scheduled_start_time);
CREATE INDEX idx_maintenance_approval ON public.maintenance_windows(requires_approval, approved_at) WHERE requires_approval = true AND approved_at IS NULL;

-- Trigger for updated_at
CREATE TRIGGER update_maintenance_windows_timestamp
    BEFORE UPDATE ON public.maintenance_windows
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.maintenance_windows ENABLE ROW LEVEL SECURITY;

-- RLS Policy: Operations team and admins
CREATE POLICY maintenance_windows_admin_policy ON public.maintenance_windows
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id()
        AND r.name IN ('admin', 'operations')
    ));

-- ====================================================================
-- TABLE: 58 - change_requests
-- Description: Tracks database schema change requests with approval workflow
-- Business Case: In enterprise environments, database changes must be controlled,
--                reviewed, and approved to prevent incidents and maintain data
--                integrity. This table implements a complete change management
--                workflow, from request submission through peer review, approval,
--                and execution. It captures the full context of each change,
--                including the SQL to be executed, rollback plan, risk assessment,
--                and testing evidence. The approval workflow ensures that changes
--                are reviewed by appropriate stakeholders based on risk level.
--                The execution log provides audit trail for compliance requirements
--                and enables post-change analysis.
-- KPIs:
--   1. Change success rate
--   2. Average time from submission to approval
--   3. Number of changes by type/risk level
--   4. Change failure rate by day of week/time
--   5. Rollback frequency
--   6. Peer review coverage percentage
--   7. Change-related incident rate
-- Feature Reference: OPS-10 (Change Management)
-- ====================================================================
CREATE TABLE public.change_requests (
    change_request_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    -- Identification
    change_number VARCHAR(50) GENERATED ALWAYS AS (
        'CHG-' || TO_CHAR(created_at, 'YYYYMMDD') || '-' || LPAD(nextval('change_request_seq')::TEXT, 5, '0')
    ) STORED,
    change_title VARCHAR(500) NOT NULL,
    change_description TEXT NOT NULL,
    -- Change details
    change_type VARCHAR(50) NOT NULL CHECK (change_type IN (
        'SCHEMA_CHANGE', 'INDEX_CREATION', 'INDEX_DROP', 'TABLE_CREATION',
        'TABLE_ALTER', 'DATA_MIGRATION', 'CONFIGURATION', 'PERMISSION_CHANGE',
        'PROCEDURE_CHANGE', 'TRIGGER_CHANGE', 'VIEW_CHANGE', 'FUNCTION_CHANGE'
    )),
    risk_level public.change_risk_level NOT NULL,
    impact_assessment TEXT,
    -- Technical details
    database_name VARCHAR(100) NOT NULL,
    schema_name VARCHAR(100),
    affected_objects TEXT[], -- List of tables, indexes, etc.
    sql_to_execute TEXT NOT NULL,
    sql_rollback TEXT, -- Rollback script
    estimated_execution_time INTERVAL,
    -- Testing
    testing_performed TEXT,
    testing_evidence_url TEXT,
    performance_impact_assessment TEXT,
    -- Dependencies
    dependencies JSONB, -- Other change requests or external dependencies
    -- Schedule
    requested_execution_time TIMESTAMP WITH TIME ZONE,
    actual_execution_time TIMESTAMP WITH TIME ZONE,
    execution_duration INTERVAL,
    -- Status workflow
    status public.change_request_status NOT NULL DEFAULT 'DRAFT',
    rejection_reason TEXT,
    -- Requestor
    requested_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    -- Peer review
    peer_reviewer_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    peer_reviewed_at TIMESTAMP WITH TIME ZONE,
    peer_review_comments TEXT,
    peer_review_status VARCHAR(50) CHECK (peer_review_status IN ('PENDING', 'APPROVED', 'CHANGES_REQUESTED', 'REJECTED')),
    -- Approvals (hierarchical based on risk)
    technical_approver_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    technical_approved_at TIMESTAMP WITH TIME ZONE,
    technical_approval_comments TEXT,
    business_approver_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    business_approved_at TIMESTAMP WITH TIME ZONE,
    business_approval_comments TEXT,
    cab_approval_id UUID, -- Change advisory board meeting reference
    -- Execution
    executed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    executed_at TIMESTAMP WITH TIME ZONE,
    execution_status VARCHAR(50) CHECK (execution_status IN ('PENDING', 'IN_PROGRESS', 'SUCCESS', 'FAILED', 'ROLLED_BACK')),
    execution_log TEXT,
    execution_error TEXT,
    -- Post-execution
    post_execution_validation TEXT,
    rollback_executed BOOLEAN DEFAULT false,
    rollback_reason TEXT,
    rollback_executed_by UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    rollback_executed_at TIMESTAMP WITH TIME ZONE,
    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    -- Metadata
    tags TEXT[],
    notes TEXT,
    related_change_requests UUID[],
    CONSTRAINT change_timeline_check CHECK (
        (peer_reviewed_at IS NULL OR peer_reviewed_at >= requested_at) AND
        (technical_approved_at IS NULL OR technical_approved_at >= peer_reviewed_at) AND
        (business_approved_at IS NULL OR business_approved_at >= technical_approved_at) AND
        (executed_at IS NULL OR executed_at >= business_approved_at)
    )
);

COMMENT ON TABLE public.change_requests IS 'Database change requests with approval workflow tracking';
COMMENT ON COLUMN public.change_requests.change_number IS 'Human-readable change request identifier';
COMMENT ON COLUMN public.change_requests.change_type IS 'Type of database change being requested';
COMMENT ON COLUMN public.change_requests.risk_level IS 'Risk classification determining approval requirements';
COMMENT ON COLUMN public.change_requests.sql_to_execute IS 'SQL script to be executed';
COMMENT ON COLUMN public.change_requests.sql_rollback IS 'Rollback script in case of issues';
COMMENT ON COLUMN public.change_requests.peer_reviewer_id IS 'Team member who reviewed technical aspects';
COMMENT ON COLUMN public.change_requests.technical_approver_id IS 'Technical approver (e.g., DBA lead)';
COMMENT ON COLUMN public.change_requests.business_approver_id IS 'Business approver for high-risk changes';
COMMENT ON COLUMN public.change_requests.cab_approval_id IS 'Change Advisory Board approval reference';

-- Create sequence for change request numbering
CREATE SEQUENCE public.change_request_seq START 1;

-- Indexes for change_requests
CREATE INDEX idx_change_requests_status ON public.change_requests(status, risk_level);
CREATE INDEX idx_change_requests_requested_by ON public.change_requests(requested_by, created_at DESC);
CREATE INDEX idx_change_requests_scheduled ON public.change_requests(requested_execution_time) WHERE requested_execution_time IS NOT NULL;
CREATE INDEX idx_change_requests_peer_review ON public.change_requests(peer_reviewer_id, peer_review_status) WHERE peer_reviewer_id IS NOT NULL;
CREATE INDEX idx_change_requests_approvers ON public.change_requests(technical_approver_id, business_approver_id);

-- Trigger for updated_at
CREATE TRIGGER update_change_requests_timestamp
    BEFORE UPDATE ON public.change_requests
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.change_requests ENABLE ROW LEVEL SECURITY;

-- RLS Policy: All authenticated users can view, but only appropriate roles can approve
CREATE POLICY change_requests_view_policy ON public.change_requests
    FOR SELECT USING (true); -- All authenticated users can view

CREATE POLICY change_requests_create_policy ON public.change_requests
    FOR INSERT WITH CHECK (
        current_user_id() = requested_by
    );

CREATE POLICY change_requests_update_policy ON public.change_requests
    FOR UPDATE USING (
        current_user_id() = requested_by OR
        current_user_id() = peer_reviewer_id OR
        current_user_id() = technical_approver_id OR
        current_user_id() = business_approver_id OR
        EXISTS (
            SELECT 1 FROM public.user_roles ur
            JOIN public.roles r ON ur.role_id = r.role_id
            WHERE ur.user_id = current_user_id()
            AND r.name IN ('admin', 'dba')
        )
    );

-- ====================================================================
-- MATERIALIZED VIEW: mv_weekly_sla_compliance
-- Description: Pre-aggregated weekly SLA compliance metrics by service and customer
-- Business Case: SLA reporting requires efficient aggregation of large volumes of
--                measurement data. This materialized view pre-computes weekly compliance
--                statistics, enabling fast dashboard loading and customer reporting
--                without impacting operational performance. It can be refreshed on a
--                schedule that matches reporting requirements.
-- Feature Reference: OPS-07 (SLA Management)
-- ====================================================================
CREATE MATERIALIZED VIEW public.mv_weekly_sla_compliance AS
SELECT
    DATE_TRUNC('week', measurement_end) AS week_start,
    service_name,
    customer_id,
    COUNT(*) AS total_measurements,
    COUNT(*) FILTER (WHERE status = 'COMPLIANT') AS compliant_count,
    COUNT(*) FILTER (WHERE status = 'VIOLATED') AS violation_count,
    ROUND(
        (COUNT(*) FILTER (WHERE status = 'COMPLIANT') * 100.0 / NULLIF(COUNT(*), 0)),
        2
    ) AS compliance_percentage,
    MAX(actual_value) FILTER (WHERE status = 'VIOLATED') AS max_violation_value,
    MIN(actual_value) FILTER (WHERE status = 'COMPLIANT') AS min_compliant_value,
    COUNT(DISTINCT violation_reason) AS distinct_violation_types
FROM public.sla_tracking
GROUP BY DATE_TRUNC('week', measurement_end), service_name, customer_id;

COMMENT ON MATERIALIZED VIEW public.mv_weekly_sla_compliance IS 'Pre-aggregated weekly SLA compliance metrics';

-- Index for materialized view
CREATE UNIQUE INDEX idx_mv_weekly_sla_compliance_unique
    ON public.mv_weekly_sla_compliance(week_start, service_name, customer_id);
CREATE INDEX idx_mv_weekly_sla_compliance_customer
    ON public.mv_weekly_sla_compliance(customer_id, week_start DESC);

-- ====================================================================
-- FUNCTION: calculate_capacity_forecast
-- Description: Calculates capacity forecasts based on historical trends
-- Business Case: Automates the capacity planning process by generating forecasts
--                from historical usage data, reducing manual effort and improving
--                consistency.
-- Feature Reference: OPS-06 (Capacity Management)
-- ====================================================================
CREATE OR REPLACE FUNCTION public.calculate_capacity_forecast(
    p_resource_type VARCHAR,
    p_months_ahead INTEGER DEFAULT 12
)
RETURNS TABLE (
    forecast_month DATE,
    projected_usage NUMERIC,
    lower_bound NUMERIC,
    upper_bound NUMERIC,
    confidence_level NUMERIC
) AS $$
DECLARE
    v_current_usage NUMERIC;
    v_growth_rate NUMERIC;
    v_seasonality_factor NUMERIC;
BEGIN
    -- Get current usage
    SELECT current_utilization INTO v_current_usage
    FROM public.capacity_plans
    WHERE resource_type = p_resource_type
    ORDER BY planning_year DESC, planning_month DESC
    LIMIT 1;

    -- Calculate growth rate from historical data
    SELECT AVG(growth_rate_percent) / 100 INTO v_growth_rate
    FROM public.capacity_plans
    WHERE resource_type = p_resource_type
    AND planning_year >= EXTRACT(YEAR FROM CURRENT_DATE) - 1;

    -- Generate forecast months
    FOR i IN 0..p_months_ahead-1 LOOP
        forecast_month := DATE_TRUNC('month', CURRENT_DATE) + (i || ' months')::INTERVAL;

        -- Simple linear forecast with confidence intervals
        projected_usage := v_current_usage * POWER(1 + COALESCE(v_growth_rate, 0.05), i/12.0);

        -- Apply seasonality factor (simplified - would be more sophisticated in production)
        v_seasonality_factor := 1 + 0.1 * SIN(EXTRACT(MONTH FROM forecast_month) * 3.14159 / 6);
        projected_usage := projected_usage * v_seasonality_factor;

        -- Confidence intervals (simplified)
        lower_bound := projected_usage * 0.9;
        upper_bound := projected_usage * 1.1;
        confidence_level := 0.85 - (i * 0.02); -- Decreasing confidence over time

        RETURN NEXT;
    END LOOP;

    RETURN;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.calculate_capacity_forecast IS 'Generates capacity forecasts based on historical trends';

-- ====================================================================
-- FUNCTION: execute_change_request
-- Description: Safely executes a change request with error handling and rollback capability
-- Business Case: Automates change execution with built-in safety measures, reducing
--                human error and ensuring consistent change application.
-- Feature Reference: OPS-10 (Change Management)
-- ====================================================================
CREATE OR REPLACE FUNCTION public.execute_change_request(
    p_change_request_id UUID,
    p_executing_user_id UUID
)
RETURNS JSONB AS $$
DECLARE
    v_change_record public.change_requests%ROWTYPE;
    v_result JSONB;
    v_success BOOLEAN := false;
    v_error_message TEXT;
    v_start_time TIMESTAMP WITH TIME ZONE;
    v_end_time TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Get change request and validate
    SELECT * INTO v_change_record
    FROM public.change_requests
    WHERE change_request_id = p_change_request_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Change request not found'
        );
    END IF;

    -- Validate status
    IF v_change_record.status != 'APPROVED' THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', format('Change request must be APPROVED, current status: %s', v_change_record.status)
        );
    END IF;

    -- Start execution
    UPDATE public.change_requests
    SET
        status = 'IN_PROGRESS',
        executed_by = p_executing_user_id,
        actual_execution_time = CURRENT_TIMESTAMP,
        execution_status = 'IN_PROGRESS'
    WHERE change_request_id = p_change_request_id;

    v_start_time := clock_timestamp();

    -- Execute change in transaction with exception handling
    BEGIN
        -- Execute the SQL
        EXECUTE v_change_record.sql_to_execute;

        v_success := true;
        v_end_time := clock_timestamp();

        -- Update success status
        UPDATE public.change_requests
        SET
            status = 'COMPLETED',
            execution_status = 'SUCCESS',
            actual_execution_time = v_start_time,
            execution_duration = v_end_time - v_start_time,
            post_execution_validation = 'Change executed successfully'
        WHERE change_request_id = p_change_request_id;

    EXCEPTION WHEN OTHERS THEN
        v_success := false;
        v_error_message := SQLERRM;
        v_end_time := clock_timestamp();

        -- Log error
        UPDATE public.change_requests
        SET
            status = 'FAILED',
            execution_status = 'FAILED',
            execution_error = v_error_message,
            actual_execution_time = v_start_time,
            execution_duration = v_end_time - v_start_time
        WHERE change_request_id = p_change_request_id;

        -- Attempt rollback if available
        IF v_change_record.sql_rollback IS NOT NULL THEN
            BEGIN
                EXECUTE v_change_record.sql_rollback;

                UPDATE public.change_requests
                SET
                    rollback_executed = true,
                    rollback_reason = v_error_message,
                    rollback_executed_by = p_executing_user_id,
                    rollback_executed_at = CURRENT_TIMESTAMP
                WHERE change_request_id = p_change_request_id;

            EXCEPTION WHEN OTHERS THEN
                -- Log rollback failure
                UPDATE public.change_requests
                SET
                    notes = COALESCE(notes, '') || ' Rollback also failed: ' || SQLERRM
                WHERE change_request_id = p_change_request_id;
            END;
        END IF;
    END;

    -- Return result
    v_result := jsonb_build_object(
        'success', v_success,
        'execution_duration_ms', EXTRACT(EPOCH FROM (v_end_time - v_start_time)) * 1000,
        'change_number', v_change_record.change_number,
        'change_title', v_change_record.change_title
    );

    IF v_error_message IS NOT NULL THEN
        v_result := v_result || jsonb_build_object('error', v_error_message);
    END IF;

    RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.execute_change_request IS 'Safely executes approved change requests with rollback capability';

-- Grant execute permission to appropriate roles
GRANT EXECUTE ON FUNCTION public.execute_change_request TO dba_role;

-- ====================================================================
-- Normalization Analysis
-- ====================================================================
-- All tables in Priority 6 are normalized to 3NF with the following considerations:
--
-- 1. No transitive dependencies: All non-key attributes depend solely on the primary key
-- 2. No partial dependencies: Composite keys are avoided where possible
-- 3. Atomic values: Arrays are used sparingly and only for non-relational data
-- 4. Separate tables for distinct entities (e.g., maintenance_windows separate from change_requests)
--
-- Potential denormalization justified for performance:
-- - Generated columns (e.g., change_number) for readability
-- - JSONB columns for flexible metadata where relational structure would be overkill
-- - Materialized view for SLA reporting to avoid complex runtime aggregations

-- ====================================================================
-- High-Write Workload Analysis
-- ====================================================================
-- Potential bottlenecks and mitigations:
--
-- 1. system_health_metrics: Extremely high write volume
--    - Partitioning by month reduces index size and improves write performance
--    - Consider TimescaleDB hypertable for automatic partitioning and compression
--    - Batch inserts with COPY for better throughput
--
-- 2. cost_allocation: Periodic bulk loads from cloud providers
--    - Use staging table for imports, then merge with upserts
--    - Consider table partitioning by month
--
-- 3. backup_verification_logs: Moderate write volume during backup windows
--    - Index only critical columns for lookups
--    - Archive old records to separate table
--
-- 4. sla_tracking: Continuous writes during measurement periods
--    - Partition by month similar to system_health_metrics
--    - Consider using BRIN indexes for time-series queries
--
-- 5. change_requests: Low write volume (primarily updates to status)
--    - No significant bottlenecks expected

-- ====================================================================
-- RLS Policies Summary
-- ====================================================================
-- All tables have appropriate RLS policies restricting access based on:
-- - User roles (admin, system_monitor, operations, etc.)
-- - User ID ownership where applicable
-- - Functional responsibilities (DR coordinator, capacity planner, etc.)
--
-- This ensures compliance with data governance requirements and provides
-- audit evidence for access control.

-- ======================================================================
-- ENUMS FOR USER EXPERIENCE & ENGAGEMENT
-- ======================================================================

------------------------------------------------------------------------------------------------
-- Enum: UX01 - onboarding_step_status
-- Description: Defines the possible states of each step in the user onboarding process
-- Business Case: Enables granular tracking of user progress through onboarding funnel
-- Feature Reference: UX-ONB-01 (Onboarding Flow Management)
------------------------------------------------------------------------------------------------
CREATE TYPE public.onboarding_step_status AS ENUM (
    'NOT_STARTED',      -- Step not yet initiated
    'IN_PROGRESS',      -- User currently working on this step
    'COMPLETED',        -- Step successfully finished
    'SKIPPED',          -- User opted to skip this step
    'BLOCKED',          -- Step cannot be completed due to dependencies
    'ERROR',            -- System error during step processing
    'TIMEOUT'           -- User abandoned during this step
);
COMMENT ON TYPE public.onboarding_step_status IS 'Lifecycle states for each onboarding step';

------------------------------------------------------------------------------------------------
-- Enum: UX02 - engagement_segment
-- Description: Categorizes users based on their engagement level with the platform
-- Business Case: Enables targeted re-engagement campaigns and personalized experiences
-- Feature Reference: UX-ENG-01 (User Engagement Scoring)
------------------------------------------------------------------------------------------------
CREATE TYPE public.engagement_segment AS ENUM (
    'SUPER_ACTIVE',     -- Daily active users, high feature usage
    'ACTIVE',           -- Weekly active users
    'AT_RISK',          -- Declining engagement, needs intervention
    'DORMANT',          -- No activity in 30+ days
    'CHURNED',          -- No activity in 90+ days
    'NEW',              -- First 14 days after signup
    'POWER_USER',       -- Top 10% by engagement metrics
    'CASUAL'            -- Infrequent but consistent usage
);
COMMENT ON TYPE public.engagement_segment IS 'User engagement level classifications for targeting';

------------------------------------------------------------------------------------------------
-- Enum: UX03 - notification_channel
-- Description: Available channels for delivering notifications to users
-- Business Case: Supports omnichannel communication strategy
-- Feature Reference: UX-NOT-01 (Multi-channel Notifications)
------------------------------------------------------------------------------------------------
CREATE TYPE public.notification_channel AS ENUM (
    'IN_APP',           -- Within platform notifications
    'EMAIL',            -- Email delivery
    'PUSH',             -- Mobile push notifications
    'SMS',              -- Text messages
    'WEB_PUSH',         -- Browser push notifications
    'SLACK',            -- Slack integration (for enterprise)
    'DIGEST'            -- Daily/weekly digest emails
);
COMMENT ON TYPE public.notification_channel IS 'Supported notification delivery channels';

------------------------------------------------------------------------------------------------
-- Enum: UX04 - notification_priority
-- Description: Priority levels for notifications affecting delivery timing and urgency
-- Business Case: Ensures critical notifications are delivered promptly
-- Feature Reference: UX-NOT-02 (Notification Prioritization)
------------------------------------------------------------------------------------------------
CREATE TYPE public.notification_priority AS ENUM (
    'CRITICAL',         -- Immediate delivery required (security alerts)
    'HIGH',             -- Deliver within minutes
    'MEDIUM',           -- Deliver within hours
    'LOW',              -- Batch with digest
    'BACKGROUND'        -- No user action required (analytics)
);
COMMENT ON TYPE public.notification_priority IS 'Priority levels affecting notification delivery timing';

------------------------------------------------------------------------------------------------
-- Enum: UX05 - feedback_category
-- Description: Categories for user feedback submissions
-- Business Case: Enables systematic analysis of feedback for product roadmap
-- Feature Reference: UX-FB-01 (Feedback Collection)
------------------------------------------------------------------------------------------------
CREATE TYPE public.feedback_category AS ENUM (
    'FEATURE_REQUEST',   -- New feature suggestions
    'BUG_REPORT',        -- Issue reporting
    'USABILITY_ISSUE',   -- Difficulty using feature
    'PERFORMANCE',       -- Slow or unresponsive
    'CONTENT_QUALITY',   -- Poor quality content
    'PRICING',           -- Cost-related feedback
    'SUPPORT_QUALITY',   -- Customer service feedback
    'GENERAL'            -- Uncategorized feedback
);
COMMENT ON TYPE public.feedback_category IS 'Categories for organizing user feedback';

------------------------------------------------------------------------------------------------
-- Enum: UX06 - survey_status
-- Description: Status of user surveys throughout their lifecycle
-- Business Case: Tracks survey distribution and completion rates
-- Feature Reference: UX-SRV-01 (Survey Management)
------------------------------------------------------------------------------------------------
CREATE TYPE public.survey_status AS ENUM (
    'DRAFT',            -- Being created, not yet sent
    'SCHEDULED',        -- Planned for future delivery
    'ACTIVE',           -- Currently accepting responses
    'PAUSED',           -- Temporarily stopped
    'CLOSED',           -- No longer accepting responses
    'ARCHIVED'          -- Moved to long-term storage
);
COMMENT ON TYPE public.survey_status IS 'Lifecycle states for user surveys';

------------------------------------------------------------------------------------------------
-- Enum: UX07 - ticket_priority
-- Description: Priority levels for support tickets
-- Business Case: Ensures critical issues receive immediate attention
-- Feature Reference: UX-SUP-01 (Support Ticket Management)
------------------------------------------------------------------------------------------------
CREATE TYPE public.ticket_priority AS ENUM (
    'CRITICAL',         -- System down, data loss, security issue
    'HIGH',             -- Major feature broken for many users
    'MEDIUM',           -- Feature partially working, workaround exists
    'LOW',              -- Cosmetic issue, minor inconvenience
    'PLANNING'          -- Future enhancement, no immediate action
);
COMMENT ON TYPE public.ticket_priority IS 'Priority levels for support tickets based on impact';

------------------------------------------------------------------------------------------------
-- Enum: UX08 - ticket_status
-- Description: Status progression for support tickets
-- Business Case: Tracks ticket lifecycle from creation to resolution
-- Feature Reference: UX-SUP-02 (Ticket Lifecycle)
------------------------------------------------------------------------------------------------
CREATE TYPE public.ticket_status AS ENUM (
    'NEW',              -- Just created, not yet triaged
    'ASSIGNED',         -- Assigned to support agent
    'IN_PROGRESS',      -- Agent actively working
    'PENDING_CUSTOMER', -- Waiting for customer response
    'PENDING_INTERNAL', -- Waiting for internal team
    'RESOLVED',         -- Solution provided, awaiting confirmation
    'CLOSED',           -- Confirmed resolved by customer
    'REOPENED',         -- Issue recurred after resolution
    'ESCALATED'         -- Moved to senior support
);
COMMENT ON TYPE public.ticket_status IS 'Progression states for support tickets';

------------------------------------------------------------------------------------------------
-- Enum: UX09 - article_type
-- Description: Types of knowledge base articles
-- Business Case: Organizes content for different user needs
-- Feature Reference: UX-KB-01 (Knowledge Base Management)
------------------------------------------------------------------------------------------------
CREATE TYPE public.article_type AS ENUM (
    'GETTING_STARTED',   -- Onboarding and basics
    'TUTORIAL',          -- Step-by-step guides
    'FAQ',               -- Frequently asked questions
    'TROUBLESHOOTING',   -- Problem resolution guides
    'BEST_PRACTICE',     -- Tips and recommendations
    'API_DOCUMENTATION', -- Technical API docs
    'RELEASE_NOTES',     -- Product updates
    'POLICY'             -- Terms, privacy, legal
);
COMMENT ON TYPE public.article_type IS 'Categories for knowledge base content';

------------------------------------------------------------------------------------------------
-- Enum: UX10 - achievement_type
-- Description: Types of achievements/badges users can earn
-- Business Case: Enables diverse gamification mechanics
-- Feature Reference: UX-GAM-01 (Gamification System)
------------------------------------------------------------------------------------------------
CREATE TYPE public.achievement_type AS ENUM (
    'ONBOARDING',        -- Completed onboarding steps
    'ENGAGEMENT',        -- Activity-based achievements
    'SOCIAL',            -- Networking achievements
    'CONTRIBUTION',      -- Content creation achievements
    'EXPERTISE',         -- Skill-based achievements
    'MILESTONE',         -- Long-term usage milestones
    'SPECIAL_EVENT',     -- Limited-time achievements
    'COMMUNITY'          -- Community recognition
);
COMMENT ON TYPE public.achievement_type IS 'Categories of achievements in gamification system';

-- ======================================================================
-- TABLE: 59 - user_onboarding_progress
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 59
-- Table Name: user_onboarding_progress
-- Description: Tracks granular progress of users through the onboarding flow, including step
--              completion, time spent, and abandonment points.
--
-- Business Case (300 words):
-- User onboarding is the critical first impression and determinant of long-term retention.
-- Without detailed tracking, product teams operate blindly, unable to identify where users
-- drop off or struggle. This table provides pixel-level visibility into the onboarding funnel,
-- capturing not just completion status but also timing, interactions, and abandonment reasons.
--
-- The business impact is substantial: a 5% improvement in onboarding completion typically
-- translates to 15-25% increase in 30-day retention. By analyzing step-by-step conversion,
-- teams can identify bottlenecks (e.g., 70% drop at profile photo upload), run A/B tests
-- on improvements, and measure impact quantitatively. The table also enables personalization
-- - returning users can resume where they left off, and struggling users can receive
-- targeted help.
--
-- For enterprise reporting, this data feeds into cohort analysis, showing how onboarding
-- changes affect retention cohorts. It also supports predictive models - users who spend
-- >5 minutes on a step are 3x more likely to churn in first week. Real-time dashboards
-- alert product managers to sudden funnel changes (e.g., after app update).
--
-- KPIs:
--   1. Onboarding completion rate (users completing all steps / total signups)
--   2. Average time to complete onboarding (total minutes across steps)
--   3. Step abandonment rate by step (users dropping at each step)
--   4. Reattempt rate (users restarting after abandonment)
--   5. Correlation between onboarding completion and 30-day retention
--   6. Mobile vs. desktop onboarding completion rates
--   7. A/B test variant performance on specific steps
--
-- Feature Reference: UX-ONB-01 to UX-ONB-10 (Onboarding Optimization)
--
-- Normalization: 3NF compliant - onboarding steps are independent of user data,
--                time tracking is separate from user profile.
--
-- High-Write Considerations:
--   - Partitioned by created_date for efficient time-series queries
--   - UNLOGGED option considered but rejected due to business criticality
--   - Uses SKIP LOCKED for concurrent update scenarios
--   - Index on (user_id, step_name) for fast progress lookups
------------------------------------------------------------------------------------------------
CREATE TABLE public.user_onboarding_progress (
    -- Primary identifiers
    progress_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id              UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Onboarding context
    onboarding_version   VARCHAR(20) NOT NULL,           -- A/B test variant
    step_name            VARCHAR(100) NOT NULL,          -- e.g., 'profile_setup', 'photo_upload'
    step_sequence        SMALLINT NOT NULL CHECK (step_sequence > 0),

    -- Status and timing
    status               public.onboarding_step_status NOT NULL DEFAULT 'NOT_STARTED',
    started_at           TIMESTAMP WITH TIME ZONE,
    completed_at         TIMESTAMP WITH TIME ZONE,
    time_spent_seconds   INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (completed_at - started_at))::INTEGER
    ) STORED,

    -- Engagement metrics
    attempts_count       SMALLINT DEFAULT 1 CHECK (attempts_count > 0),
    interactions_count   INTEGER DEFAULT 0,               -- clicks, keystrokes
    help_viewed          BOOLEAN DEFAULT false,           -- user viewed help content

    -- Abandonment tracking
    abandonment_reason   VARCHAR(255),                     -- free text or enum
    last_known_url       TEXT,                             -- where user left
    browser_info         JSONB,                             -- client context

    -- Device context
    device_type          VARCHAR(20) CHECK (device_type IN ('mobile', 'tablet', 'desktop')),
    platform             VARCHAR(50),                       -- iOS, Android, Web
    app_version          VARCHAR(20),

    -- A/B testing
    experiment_id        UUID REFERENCES public.experiments(experiment_id) ON DELETE SET NULL,
    variant_name         VARCHAR(50),

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by           UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by           UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Constraints
    CONSTRAINT valid_onboarding_timing CHECK (
        (status = 'COMPLETED' AND completed_at IS NOT NULL AND started_at IS NOT NULL) OR
        (status != 'COMPLETED' AND completed_at IS NULL)
    ),
    CONSTRAINT valid_onboarding_sequence UNIQUE (user_id, step_name)
);

COMMENT ON TABLE public.user_onboarding_progress IS 'Tracks granular user progress through onboarding funnel';
COMMENT ON COLUMN public.user_onboarding_progress.progress_id IS 'Primary key';
COMMENT ON COLUMN public.user_onboarding_progress.user_id IS 'User reference';
COMMENT ON COLUMN public.user_onboarding_progress.onboarding_version IS 'Version of onboarding flow (A/B test)';
COMMENT ON COLUMN public.user_onboarding_progress.step_name IS 'Name of onboarding step';
COMMENT ON COLUMN public.user_onboarding_progress.step_sequence IS 'Order of step in flow';
COMMENT ON COLUMN public.user_onboarding_progress.status IS 'Current step status';
COMMENT ON COLUMN public.user_onboarding_progress.started_at IS 'When user started this step';
COMMENT ON COLUMN public.user_onboarding_progress.completed_at IS 'When user completed this step';
COMMENT ON COLUMN public.user_onboarding_progress.time_spent_seconds IS 'Calculated time spent on step';
COMMENT ON COLUMN public.user_onboarding_progress.attempts_count IS 'Number of times user attempted step';
COMMENT ON COLUMN public.user_onboarding_progress.interactions_count IS 'Number of interactions during step';
COMMENT ON COLUMN public.user_onboarding_progress.help_viewed IS 'Whether user viewed help';
COMMENT ON COLUMN public.user_onboarding_progress.abandonment_reason IS 'Why user abandoned (if applicable)';
COMMENT ON COLUMN public.user_onboarding_progress.last_known_url IS 'URL where abandonment occurred';
COMMENT ON COLUMN public.user_onboarding_progress.browser_info IS 'Browser/client context at abandonment';
COMMENT ON COLUMN public.user_onboarding_progress.device_type IS 'Device category';
COMMENT ON COLUMN public.user_onboarding_progress.platform IS 'Platform identifier';
COMMENT ON COLUMN public.user_onboarding_progress.app_version IS 'App version during onboarding';
COMMENT ON COLUMN public.user_onboarding_progress.experiment_id IS 'A/B experiment reference';
COMMENT ON COLUMN public.user_onboarding_progress.variant_name IS 'Experiment variant assigned';
COMMENT ON COLUMN public.user_onboarding_progress.created_at IS 'Record creation timestamp';
COMMENT ON COLUMN public.user_onboarding_progress.updated_at IS 'Last update timestamp';
COMMENT ON COLUMN public.user_onboarding_progress.created_by IS 'User who created record';
COMMENT ON COLUMN public.user_onboarding_progress.updated_by IS 'User who last updated record';

-- Indexes for performance
CREATE INDEX idx_onboarding_user_status ON public.user_onboarding_progress(user_id, status);
CREATE INDEX idx_onboarding_step_completion ON public.user_onboarding_progress(step_name, completed_at)
    WHERE completed_at IS NOT NULL;
CREATE INDEX idx_onboarding_abandonment ON public.user_onboarding_progress(abandonment_reason)
    WHERE abandonment_reason IS NOT NULL;
CREATE INDEX idx_onboarding_created_date ON public.user_onboarding_progress(created_at);
CREATE INDEX idx_onboarding_experiment ON public.user_onboarding_progress(experiment_id, variant_name)
    WHERE experiment_id IS NOT NULL;

-- Trigger for updated_at
CREATE TRIGGER update_user_onboarding_progress_timestamp
    BEFORE UPDATE ON public.user_onboarding_progress
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.user_onboarding_progress ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY onboarding_progress_user_policy ON public.user_onboarding_progress
    USING (user_id = current_user_id());

CREATE POLICY onboarding_progress_admin_policy ON public.user_onboarding_progress
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'analyst')
    ));

-- ======================================================================
-- TABLE: 60 - user_engagement_scores
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 60
-- Table Name: user_engagement_scores
-- Description: Computed engagement metrics and scores for each user, updated periodically
--              via background jobs. Includes multiple engagement dimensions and segment classification.
--
-- Business Case (300 words):
-- In a professional network, user engagement directly correlates with retention, network effects,
-- and lifetime value. However, engagement is multi-dimensional - a user might view content daily
-- but never connect with others, representing different engagement patterns. This table provides
-- a holistic view of user engagement through composite scoring across key dimensions: frequency,
-- recency, depth, and breadth of platform usage.
--
-- The business value is multi-faceted. First, it enables proactive retention - by identifying
-- users whose engagement scores decline (e.g., from 85 to 60), the system can trigger automated
-- interventions like personalized emails, feature recommendations, or in-app messages. Second,
-- it powers segmentation for marketing campaigns - "power users" receive different messaging than
-- "at-risk" users. Third, it feeds into predictive models for churn, allowing preemptive action.
--
-- For product teams, aggregated engagement scores by cohort reveal feature adoption trends.
-- A drop in engagement after a release signals problems. For sales, engagement scores help
-- identify expansion opportunities - highly engaged users at free tier are prime upgrade candidates.
-- For community management, scores identify potential community leaders and influencers.
--
-- The table is designed for efficient updates via batch processing (hourly/daily) rather than
-- real-time computation, balancing freshness with computational cost. Scores are stored with
-- historical snapshots to analyze trends over time.
--
-- KPIs:
--   1. Average engagement score by user segment
--   2. Score decline rate (users with >20% drop in 30 days)
--   3. Correlation between engagement score and retention rate
--   4. Engagement score distribution by acquisition channel
--   5. Time from signup to "active" threshold (score > 60)
--   6. Power user ratio (score > 80) by cohort
--   7. Engagement score uplift after feature releases
--
-- Feature Reference: UX-ENG-01 to UX-ENG-15 (Engagement Analytics)
--
-- Normalization: 3NF - scores are separate from user profile to allow historical tracking
--
-- High-Write Considerations:
--   - Updated in batches, not per-user transaction
--   - Partitioned by calculation_date for time-series queries
--   - Uses UPSERT pattern for efficient updates
--   - Separate table for historical snapshots (user_engagement_history)
------------------------------------------------------------------------------------------------
CREATE TABLE public.user_engagement_scores (
    -- Primary identifiers
    score_id             UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id              UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    calculation_date     DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Core engagement dimensions (0-100 scale)
    frequency_score      NUMERIC(5,2) NOT NULL CHECK (frequency_score BETWEEN 0 AND 100),
    recency_score        NUMERIC(5,2) NOT NULL CHECK (recency_score BETWEEN 0 AND 100),
    depth_score          NUMERIC(5,2) NOT NULL CHECK (depth_score BETWEEN 0 AND 100),
    breadth_score        NUMERIC(5,2) NOT NULL CHECK (breadth_score BETWEEN 0 AND 100),

    -- Composite scores (weighted combinations)
    overall_score        NUMERIC(5,2) GENERATED ALWAYS AS (
        (frequency_score * 0.25 + recency_score * 0.25 + depth_score * 0.25 + breadth_score * 0.25)
    ) STORED,

    -- Engagement segment
    engagement_segment   public.engagement_segment NOT NULL,

    -- Component metrics (raw values)
    days_active_last_30   SMALLINT NOT NULL CHECK (days_active_last_30 BETWEEN 0 AND 30),
    sessions_last_30      INTEGER DEFAULT 0 CHECK (sessions_last_30 >= 0),
    features_used_last_30 INTEGER DEFAULT 0 CHECK (features_used_last_30 >= 0),
    connections_last_30   INTEGER DEFAULT 0 CHECK (connections_last_30 >= 0),
    content_created_last_30 INTEGER DEFAULT 0 CHECK (content_created_last_30 >= 0),
    interactions_last_30  INTEGER DEFAULT 0 CHECK (interactions_last_30 >= 0),

    -- Time-based metrics
    last_active_at       TIMESTAMP WITH TIME ZONE,
    first_active_at      TIMESTAMP WITH TIME ZONE,
    account_age_days     INTEGER GENERATED ALWAYS AS (
        EXTRACT(DAY FROM (CURRENT_DATE - first_active_at::DATE))::INTEGER
    ) STORED,

    -- Trend analysis
    score_trend_7d       NUMERIC(5,2),                    -- Change over 7 days
    score_trend_30d      NUMERIC(5,2),                     -- Change over 30 days
    volatility_index     NUMERIC(5,2),                      -- Standard deviation of daily scores

    -- Risk indicators
    risk_level           VARCHAR(20) CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    churn_probability    NUMERIC(5,4) CHECK (churn_probability BETWEEN 0 AND 1),

    -- Calculation metadata
    calculation_version  VARCHAR(20) NOT NULL,
    calculation_time     TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    data_freshness       INTERVAL,                          -- How stale the source data is

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT unique_user_daily_score UNIQUE (user_id, calculation_date)
);

COMMENT ON TABLE public.user_engagement_scores IS 'Computed user engagement metrics and segment classification';
COMMENT ON COLUMN public.user_engagement_scores.score_id IS 'Primary key';
COMMENT ON COLUMN public.user_engagement_scores.user_id IS 'User reference';
COMMENT ON COLUMN public.user_engagement_scores.calculation_date IS 'Date of score calculation';
COMMENT ON COLUMN public.user_engagement_scores.frequency_score IS 'How often user visits (0-100)';
