CREATE INDEX idx_notification_templates_experiment ON public.notification_templates(experiment_id, variant_name);

-- Partial index for active templates only
CREATE INDEX idx_notification_templates_active ON public.notification_templates(template_name) WHERE is_active = true;

-- Trigger for updated_at
CREATE TRIGGER update_notification_templates_timestamp
    BEFORE UPDATE ON public.notification_templates
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.notification_templates ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY notification_templates_admin_policy ON public.notification_templates
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'content_manager')
    ));

CREATE POLICY notification_templates_read_policy ON public.notification_templates
    FOR SELECT USING (true);  -- Anyone can read templates (for rendering)

-- ======================================================================
-- TABLE: 63 - notification_delivery_logs
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 63
-- Table Name: notification_delivery_logs
-- Description: Comprehensive audit trail of all notification delivery attempts, including
--              status, timing, errors, and engagement metrics (opens/clicks).
--
-- Business Case (300 words):
-- In a platform sending millions of notifications daily, visibility into delivery success,
-- timing, and user engagement is critical. This table provides the operational and analytical
-- backbone for the notification system, enabling real-time monitoring, debugging, and
-- optimization of all outbound communications.
--
-- From an operational perspective, the logs enable immediate detection of delivery failures
-- (e.g., email provider down, push certificate expired) and automated retry logic. Support
-- teams can investigate user-reported "I didn't receive the email" issues by checking exact
-- delivery status and error messages. The table also supports SLA monitoring for critical
-- notifications (e.g., password reset emails must deliver within 5 minutes).
--
-- For analytics, the data feeds into engagement reporting - open rates by notification type,
-- click-through rates by template, and optimal send times by user timezone. Product managers
-- use this data to refine notification strategies, reducing fatigue while maximizing impact.
-- Marketing teams measure campaign performance with precise delivery and conversion tracking.
--
-- The table is designed for high-volume writes (every notification attempt) but relatively
-- low-frequency reads for analytics (aggregated reporting). Partitioning by date is essential
-- to manage data growth, with older partitions compressed or moved to cold storage. The
-- table also supports webhook tracking for integrations where delivery confirmation matters.
--
-- KPIs:
--   1. Delivery success rate by channel (email vs. push vs. SMS)
--   2. Average delivery latency (time from creation to sent)
--   3. Open rate by notification type and template
--   4. Click-through rate by notification type
--   5. Bounce rate (permanent failures) by email provider
--   6. Opt-out rate after specific notification types
--   7. Peak notification hours (system capacity planning)
--   8. Retry success rate (recoveries after initial failure)
--
-- Feature Reference: UX-NOT-36 to UX-NOT-50 (Notification Analytics)
--
-- Normalization: 3NF - logs reference notifications and templates but are independent
--
-- High-Write Considerations:
--   - Partitioned by created_at (monthly or daily)
--   - Unlogged table considered but rejected for critical data
--   - Batch inserts for bulk notifications
--   - Automatic archival policy (move to cold storage after 90 days)
--   - Use of BRIN indexes on timestamp columns for efficient scanning
------------------------------------------------------------------------------------------------
CREATE TABLE public.notification_delivery_logs (
    -- Primary identifiers
    log_id               BIGSERIAL,                          -- Using BIGSERIAL for high volume
    notification_id      UUID NOT NULL REFERENCES public.user_notifications(notification_id) ON DELETE CASCADE,

    -- Delivery context
    channel              public.notification_channel NOT NULL,
    template_id          UUID REFERENCES public.notification_templates(template_id) ON DELETE SET NULL,
    template_version     INTEGER,

    -- Recipient
    recipient_address    VARCHAR(255),                       -- email, phone, device token
    user_id              UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Timing
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    queued_at            TIMESTAMP WITH TIME ZONE,
    sent_at              TIMESTAMP WITH TIME ZONE,
    delivered_at         TIMESTAMP WITH TIME ZONE,
    opened_at            TIMESTAMP WITH TIME ZONE,
    clicked_at           TIMESTAMP WITH TIME ZONE,
    bounced_at           TIMESTAMP WITH TIME ZONE,

    -- Delivery status
    status               public.notification_delivery_status NOT NULL DEFAULT 'PENDING',
    attempt_count        SMALLINT DEFAULT 1 CHECK (attempt_count > 0),
    last_attempt_at      TIMESTAMP WITH TIME ZONE,

    -- Provider details
    provider             VARCHAR(50),                         -- e.g., 'aws_ses', 'twilio', 'firebase'
    provider_message_id  VARCHAR(255),                        -- External ID
    provider_response    JSONB,                                -- Raw provider response
    provider_error       TEXT,                                 -- Error message from provider

    -- Engagement
    open_count           SMALLINT DEFAULT 0,                   -- For emails opened multiple times
    click_count          SMALLINT DEFAULT 0,
    last_open_at         TIMESTAMP WITH TIME ZONE,
    last_click_at        TIMESTAMP WITH TIME ZONE,

    -- Links tracking
    clicked_links        TEXT[],                                -- URLs that were clicked
    utm_parameters       JSONB,                                 -- Campaign tracking

    -- Device/client info
    user_agent           TEXT,
    ip_address           INET,
    device_type          VARCHAR(20),
    app_version          VARCHAR(20),

    -- Error handling
    error_category       VARCHAR(50),                          -- 'invalid_address', 'provider_timeout'
    error_code           VARCHAR(50),
    error_message        TEXT,
    will_retry           BOOLEAN DEFAULT false,
    retry_count          SMALLINT DEFAULT 0,

    -- Metadata
    batch_id             UUID,                                  -- For grouped sends
    priority             public.notification_priority,

    -- Audit
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    PRIMARY KEY (log_id, created_at)
) PARTITION BY RANGE (created_at);

COMMENT ON TABLE public.notification_delivery_logs IS 'Comprehensive audit trail of notification delivery attempts';
COMMENT ON COLUMN public.notification_delivery_logs.log_id IS 'Primary key (bigserial for high volume)';
COMMENT ON COLUMN public.notification_delivery_logs.notification_id IS 'Reference to user notification';
COMMENT ON COLUMN public.notification_delivery_logs.channel IS 'Delivery channel';
COMMENT ON COLUMN public.notification_delivery_logs.template_id IS 'Template used';
COMMENT ON COLUMN public.notification_delivery_logs.template_version IS 'Template version at send time';
COMMENT ON COLUMN public.notification_delivery_logs.recipient_address IS 'Actual delivery address';
COMMENT ON COLUMN public.notification_delivery_logs.user_id IS 'User reference (denormalized)';
COMMENT ON COLUMN public.notification_delivery_logs.created_at IS 'When log entry created';
COMMENT ON COLUMN public.notification_delivery_logs.queued_at IS 'When queued for delivery';
COMMENT ON COLUMN public.notification_delivery_logs.sent_at IS 'When handed to provider';
COMMENT ON COLUMN public.notification_delivery_logs.delivered_at IS 'When confirmed delivered';
COMMENT ON COLUMN public.notification_delivery_logs.opened_at IS 'First open time';
COMMENT ON COLUMN public.notification_delivery_logs.clicked_at IS 'First click time';
COMMENT ON COLUMN public.notification_delivery_logs.bounced_at IS 'When bounce occurred';
COMMENT ON COLUMN public.notification_delivery_logs.status IS 'Current delivery status';
COMMENT ON COLUMN public.notification_delivery_logs.attempt_count IS 'Number of delivery attempts';
COMMENT ON COLUMN public.notification_delivery_logs.last_attempt_at IS 'Most recent attempt time';
COMMENT ON COLUMN public.notification_delivery_logs.provider IS 'Delivery service provider';
COMMENT ON COLUMN public.notification_delivery_logs.provider_message_id IS 'Provider’s message ID';
COMMENT ON COLUMN public.notification_delivery_logs.provider_response IS 'Raw provider response';
COMMENT ON COLUMN public.notification_delivery_logs.provider_error IS 'Error from provider';
COMMENT ON COLUMN public.notification_delivery_logs.open_count IS 'Number of opens';
COMMENT ON COLUMN public.notification_delivery_logs.click_count IS 'Number of clicks';
COMMENT ON COLUMN public.notification_delivery_logs.last_open_at IS 'Most recent open';
COMMENT ON COLUMN public.notification_delivery_logs.last_click_at IS 'Most recent click';
COMMENT ON COLUMN public.notification_delivery_logs.clicked_links IS 'URLs clicked';
COMMENT ON COLUMN public.notification_delivery_logs.utm_parameters IS 'Campaign tracking params';
COMMENT ON COLUMN public.notification_delivery_logs.user_agent IS 'Client user agent';
COMMENT ON COLUMN public.notification_delivery_logs.ip_address IS 'IP address at open/click';
COMMENT ON COLUMN public.notification_delivery_logs.device_type IS 'Device category';
COMMENT ON COLUMN public.notification_delivery_logs.app_version IS 'App version';
COMMENT ON COLUMN public.notification_delivery_logs.error_category IS 'Category of error';
COMMENT ON COLUMN public.notification_delivery_logs.error_code IS 'Error code';
COMMENT ON COLUMN public.notification_delivery_logs.error_message IS 'Error description';
COMMENT ON COLUMN public.notification_delivery_logs.will_retry IS 'Whether system will retry';
COMMENT ON COLUMN public.notification_delivery_logs.retry_count IS 'Number of retries so far';
COMMENT ON COLUMN public.notification_delivery_logs.batch_id IS 'Batch identifier';
COMMENT ON COLUMN public.notification_delivery_logs.priority IS 'Notification priority';
COMMENT ON COLUMN public.notification_delivery_logs.updated_at IS 'Last update timestamp';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_notification_logs_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'notification_delivery_logs_' || TO_CHAR(partition_date, 'YYYY_MM');
    start_date := TO_CHAR(partition_date, 'YYYY-MM-01');
    end_date := TO_CHAR(partition_date + INTERVAL '1 month', 'YYYY-MM-01');

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.notification_delivery_logs
        FOR VALUES FROM (%L) TO (%L)
    ', partition_name, start_date, end_date);

    -- Create indexes on the partition
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS idx_%I_notification_id ON public.%I(notification_id);
        CREATE INDEX IF NOT EXISTS idx_%I_user_id ON public.%I(user_id);
        CREATE INDEX IF NOT EXISTS idx_%I_status ON public.%I(status);
        CREATE INDEX IF NOT EXISTS idx_%I_created_at ON public.%I(created_at);
    ', partition_name, partition_name, partition_name, partition_name, partition_name, partition_name, partition_name, partition_name);
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.create_notification_logs_partition(DATE) IS 'Creates monthly partitions for notification_delivery_logs';

-- Create initial partitions (current and next 3 months)
DO $$
DECLARE
    current_date_val DATE := CURRENT_DATE;
    i INTEGER;
BEGIN
    FOR i IN 0..3 LOOP
        PERFORM public.create_notification_logs_partition(current_date_val + (i || ' months')::INTERVAL);
    END LOOP;
END $$;

-- Create default partition
CREATE TABLE public.notification_delivery_logs_default PARTITION OF public.notification_delivery_logs DEFAULT;

-- Global indexes (on parent table - will be inherited by partitions)
CREATE INDEX idx_notification_logs_notification_id ON public.notification_delivery_logs(notification_id);
CREATE INDEX idx_notification_logs_user_id ON public.notification_delivery_logs(user_id);
CREATE INDEX idx_notification_logs_status ON public.notification_delivery_logs(status);
CREATE INDEX idx_notification_logs_created_at ON public.notification_delivery_logs(created_at);
CREATE INDEX idx_notification_logs_provider ON public.notification_delivery_logs(provider, provider_message_id);

-- Trigger for updated_at
CREATE TRIGGER update_notification_delivery_logs_timestamp
    BEFORE UPDATE ON public.notification_delivery_logs
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.notification_delivery_logs ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY notification_logs_user_policy ON public.notification_delivery_logs
    USING (user_id = current_user_id());

CREATE POLICY notification_logs_admin_policy ON public.notification_delivery_logs
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'support_agent')
    ));

-- ======================================================================
-- TABLE: 64 - user_feedback
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 64
-- Table Name: user_feedback
-- Description: Structured collection of user feedback including feature requests, bug reports,
--              and general comments, with categorization, prioritization, and tracking.
--
-- Business Case (300 words):
-- User feedback is the lifeblood of product development, but without a structured system,
-- valuable insights are lost in support tickets, emails, and social media. This table provides
-- a centralized, structured repository for all user feedback, enabling product teams to
-- systematically analyze, prioritize, and track user suggestions and complaints.
--
-- The business impact is transformative: product decisions become data-driven rather than
-- anecdotal. Teams can identify the most requested features (e.g., "50 users asking for X"),
-- segment feedback by user tier (enterprise vs. free), and track sentiment trends over time.
-- For customer success, the table helps identify at-risk accounts based on negative feedback
-- patterns, enabling proactive outreach.
--
-- The table supports integration with development workflows - feedback can be linked to Jira
-- tickets or GitHub issues, providing traceability from user request to shipped feature.
-- For compliance, it maintains an audit trail of how feedback was handled (acknowledged,
-- escalated, resolved). For analytics, it feeds into sentiment analysis models that track
-- overall user satisfaction by feature area.
--
-- The structured approach also enables automated responses - users can receive acknowledgment
-- emails with ticket numbers, and when features ship, they can be notified that their requested
-- feature is now available.
--
-- KPIs:
--   1. Feedback volume by category (feature request vs. bug)
--   2. Average time to acknowledge feedback
--   3. Feature request-to-implementation conversion rate
--   4. Sentiment score trend (positive/negative ratio)
--   5. Top requested features (by user count)
--   6. User tier distribution of feedback submitters
--   7. Feedback resolution rate (percentage closed with response)
--   8. NPS correlation with feedback sentiment
--
-- Feature Reference: UX-FB-01 to UX-FB-15 (Feedback Management)
--
-- Normalization: 3NF - feedback is separate from users, with categorization tables
--
-- High-Write Considerations:
--   - Moderate write volume (users submit feedback daily)
--   - Indexes optimized for analytics queries
--   - JSONB for flexible metadata without schema changes
------------------------------------------------------------------------------------------------
CREATE TABLE public.user_feedback (
    -- Primary identifiers
    feedback_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id              UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Core content
    category             public.feedback_category NOT NULL,
    subject              VARCHAR(255) NOT NULL,
    description          TEXT NOT NULL,

    -- Context
    page_url             TEXT,
    feature_area         VARCHAR(100),                       -- e.g., 'search', 'messaging'
    user_goal            VARCHAR(255),                        -- What user was trying to do

    -- Severity and priority
    severity             VARCHAR(20) CHECK (severity IN ('BLOCKER', 'HIGH', 'MEDIUM', 'LOW', 'SUGGESTION')),
    business_impact      TEXT,                                 -- User description of impact

    -- Attachments
    attachments          TEXT[],                               -- URLs to screenshots/files
    browser_info         JSONB,                                -- Browser/device context

    -- Status tracking
    status               VARCHAR(20) DEFAULT 'NEW' CHECK (status IN (
        'NEW', 'ACKNOWLEDGED', 'IN_REVIEW', 'PLANNED', 'IN_PROGRESS', 'COMPLETED', 'CLOSED', 'REJECTED'
    )),
    acknowledged_at      TIMESTAMP WITH TIME ZONE,
    acknowledged_by      UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Integration
    jira_ticket          VARCHAR(50),                          -- External ticket reference
    github_issue         VARCHAR(50),                          -- GitHub issue number
    internal_notes       TEXT,                                  -- Private team notes

    -- User communication
    user_notified        BOOLEAN DEFAULT false,
    user_notified_at     TIMESTAMP WITH TIME ZONE,
    user_response        TEXT,                                  -- User reply to our response

    -- Voting/upvoting
    upvote_count         INTEGER DEFAULT 0,
    duplicates           UUID[],                                -- Other feedback IDs that are duplicates

    -- Sentiment analysis
    sentiment_score      NUMERIC(3,2) CHECK (sentiment_score BETWEEN -1 AND 1),
    sentiment_confidence NUMERIC(3,2) CHECK (sentiment_confidence BETWEEN 0 AND 1),

    -- Metadata
    tags                 TEXT[],
    feedback_version     VARCHAR(20),                           -- App version when submitted

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by           UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by           UUID REFERENCES public.users(user_id) ON DELETE SET NULL
);

COMMENT ON TABLE public.user_feedback IS 'Structured collection of user feedback and feature requests';
COMMENT ON COLUMN public.user_feedback.feedback_id IS 'Primary key';
COMMENT ON COLUMN public.user_feedback.user_id IS 'User submitting feedback';
COMMENT ON COLUMN public.user_feedback.category IS 'Type of feedback';
COMMENT ON COLUMN public.user_feedback.subject IS 'Short summary';
COMMENT ON COLUMN public.user_feedback.description IS 'Detailed feedback';
COMMENT ON COLUMN public.user_feedback.page_url IS 'URL where feedback was submitted';
COMMENT ON COLUMN public.user_feedback.feature_area IS 'Related feature area';
COMMENT ON COLUMN public.user_feedback.user_goal IS 'What user was trying to accomplish';
COMMENT ON COLUMN public.user_feedback.severity IS 'User-reported severity';
COMMENT ON COLUMN public.user_feedback.business_impact IS 'User description of impact';
COMMENT ON COLUMN public.user_feedback.attachments IS 'URLs to screenshots/files';
COMMENT ON COLUMN public.user_feedback.browser_info IS 'Client context at submission';
COMMENT ON COLUMN public.user_feedback.status IS 'Processing status';
COMMENT ON COLUMN public.user_feedback.acknowledged_at IS 'When feedback was acknowledged';
COMMENT ON COLUMN public.user_feedback.acknowledged_by IS 'Team member who acknowledged';
COMMENT ON COLUMN public.user_feedback.jira_ticket IS 'Jira ticket reference';
COMMENT ON COLUMN public.user_feedback.github_issue IS 'GitHub issue number';
COMMENT ON COLUMN public.user_feedback.internal_notes IS 'Private team notes';
COMMENT ON COLUMN public.user_feedback.user_notified IS 'Whether user was notified of status';
COMMENT ON COLUMN public.user_feedback.user_notified_at IS 'When user was notified';
COMMENT ON COLUMN public.user_feedback.user_response IS 'User reply to notification';
COMMENT ON COLUMN public.user_feedback.upvote_count IS 'Number of users upvoting this';
COMMENT ON COLUMN public.user_feedback.duplicates IS 'Related feedback IDs';
COMMENT ON COLUMN public.user_feedback.sentiment_score IS 'AI-derived sentiment (-1 to 1)';
COMMENT ON COLUMN public.user_feedback.sentiment_confidence IS 'Confidence in sentiment score';
COMMENT ON COLUMN public.user_feedback.tags IS 'Searchable tags';
COMMENT ON COLUMN public.user_feedback.feedback_version IS 'App version at submission';
COMMENT ON COLUMN public.user_feedback.created_at IS 'Record creation timestamp';
COMMENT ON COLUMN public.user_feedback.updated_at IS 'Last update timestamp';
COMMENT ON COLUMN public.user_feedback.created_by IS 'User who created record';
COMMENT ON COLUMN public.user_feedback.updated_by IS 'User who last updated record';

-- Indexes for feedback analysis
CREATE INDEX idx_user_feedback_user_id ON public.user_feedback(user_id);
CREATE INDEX idx_user_feedback_category ON public.user_feedback(category);
CREATE INDEX idx_user_feedback_status ON public.user_feedback(status);
CREATE INDEX idx_user_feedback_created_at ON public.user_feedback(created_at);
CREATE INDEX idx_user_feedback_sentiment ON public.user_feedback(sentiment_score) WHERE sentiment_score IS NOT NULL;

-- GIN index for tags array
CREATE INDEX idx_user_feedback_tags ON public.user_feedback USING gin(tags);

-- Partial index for active feedback
CREATE INDEX idx_user_feedback_active ON public.user_feedback(status)
    WHERE status NOT IN ('CLOSED', 'REJECTED');

-- Trigger for updated_at
CREATE TRIGGER update_user_feedback_timestamp
    BEFORE UPDATE ON public.user_feedback
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.user_feedback ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY user_feedback_user_policy ON public.user_feedback
    USING (user_id = current_user_id());

CREATE POLICY user_feedback_product_policy ON public.user_feedback
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'product_manager', 'support_agent')
    ));

-- ======================================================================
-- TABLE: 65 - user_surveys
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 65
-- Table Name: user_surveys
-- Description: Manages survey campaigns including NPS, CSAT, and custom surveys with
--              targeting rules, response tracking, and analytics.
--
-- Business Case (300 words):
-- Understanding user sentiment through surveys (NPS, CSAT, CES) is essential for measuring
-- product-market fit and customer satisfaction. However, ad-hoc surveys sent via different
-- tools lead to fragmented data and inconsistent methodologies. This table provides a
-- centralized survey management system, enabling product teams to design, target, and
-- analyze surveys with statistical rigor.
--
-- The business value is multi-faceted. First, NPS tracking becomes systematic - the same
-- question asked consistently allows trend analysis over time and comparison across segments.
-- Second, targeted surveys (e.g., to users who just used a feature) provide actionable
-- feedback at the moment of experience. Third, response data integrates with user profiles,
-- enabling correlation between satisfaction and engagement metrics.
--
-- For enterprise customers, the system supports custom surveys for account health checks
-- and renewal risk assessment. For product teams, it enables rapid iteration - if a feature
-- launch receives low satisfaction scores, the team can immediately investigate and improve.
--
-- The table is designed to support various survey methodologies: single-question (NPS),
-- multi-question (CSAT), and custom forms with multiple question types. Response data is
-- stored in a structured format for easy analysis, with scores automatically calculated
-- for standard survey types.
--
-- KPIs:
--   1. NPS score trend (monthly/quarterly)
--   2. Survey response rate by channel (in-app vs. email)
--   3. CSAT score by feature area
--   4. Survey completion rate (percentage finishing)
--   5. Time to response (how quickly users respond)
--   6. Detractor follow-up rate (contacting unhappy users)
--   7. Correlation between NPS and retention/churn
--   8. Survey fatigue (users unsubscribing from surveys)
--
-- Feature Reference: UX-SRV-01 to UX-SRV-20 (Survey Management)
--
-- Normalization: 3NF - surveys, questions, responses are separate tables
--
-- High-Write Considerations:
--   - Response table will have high write volume during campaigns
--   - Partition responses by survey_id or created_at
--   - Batch inserts for bulk responses
------------------------------------------------------------------------------------------------
CREATE TABLE public.user_surveys (
    -- Primary identifiers
    survey_id            UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    survey_name          VARCHAR(255) NOT NULL,
    survey_type          VARCHAR(50) NOT NULL CHECK (survey_type IN ('NPS', 'CSAT', 'CES', 'CUSTOM')),

    -- Configuration
    description          TEXT,
    status               public.survey_status NOT NULL DEFAULT 'DRAFT',

    -- Targeting
    target_audience      JSONB,                                -- User segment criteria
    target_sample_size   INTEGER,                               -- For statistically significant samples
    target_roles         VARCHAR(50)[],                         -- User roles to include

    -- Schedule
    scheduled_start_at   TIMESTAMP WITH TIME ZONE,
    scheduled_end_at     TIMESTAMP WITH TIME ZONE,
    timezone             VARCHAR(50) DEFAULT 'UTC',

    -- Delivery
    channels             public.notification_channel[],        -- How to deliver
    reminder_days        INTEGER[],                             -- Days after to remind

    -- Content (for NPS/CSAT, simplified)
    question_text        TEXT NOT NULL,
    scale_min            SMALLINT DEFAULT 0,
    scale_max            SMALLINT DEFAULT 10,
    scale_labels         JSONB,                                 -- e.g., {"0": "Not likely", "10": "Very likely"}

    -- Follow-up logic
    follow_up_question   TEXT,                                  -- e.g., "Why did you give this score?"
    follow_up_threshold  SMALLINT,                              -- e.g., ask follow-up if score < 7

    -- Incentives
    incentive_type       VARCHAR(50) CHECK (incentive_type IN ('none', 'discount', 'credit', 'gift_card')),
    incentive_value      VARCHAR(255),

    -- Analytics
    target_responses     INTEGER,
    actual_responses     INTEGER DEFAULT 0,
    response_rate        NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN target_responses > 0
        THEN (actual_responses::NUMERIC / target_responses) * 100
        ELSE NULL END
    ) STORED,

    -- Results (aggregated)
    average_score        NUMERIC(5,2),
    score_distribution   JSONB,                                 -- Histogram of scores
    nps_segments         JSONB,                                 -- Promoters/Passives/Detractors

    -- Ownership
    owner_id             UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT
);

COMMENT ON TABLE public.user_surveys IS 'Manages survey campaigns and configuration';
COMMENT ON COLUMN public.user_surveys.survey_id IS 'Primary key';
COMMENT ON COLUMN public.user_surveys.survey_name IS 'Survey identifier';
COMMENT ON COLUMN public.user_surveys.survey_type IS 'Type of survey';
COMMENT ON COLUMN public.user_surveys.description IS 'Survey description';
COMMENT ON COLUMN public.user_surveys.status IS 'Survey lifecycle status';
COMMENT ON COLUMN public.user_surveys.target_audience IS 'JSON criteria for targeting';
COMMENT ON COLUMN public.user_surveys.target_sample_size IS 'Desired sample size';
COMMENT ON COLUMN public.user_surveys.target_roles IS 'User roles to include';
COMMENT ON COLUMN public.user_surveys.scheduled_start_at IS 'When survey becomes active';
COMMENT ON COLUMN public.user_surveys.scheduled_end_at IS 'When survey closes';
COMMENT ON COLUMN public.user_surveys.timezone IS 'Timezone for scheduling';
COMMENT ON COLUMN public.user_surveys.channels IS 'Delivery channels';
COMMENT ON COLUMN public.user_surveys.reminder_days IS 'Days after to send reminders';
COMMENT ON COLUMN public.user_surveys.question_text IS 'Main survey question';
COMMENT ON COLUMN public.user_surveys.scale_min IS 'Minimum scale value';
COMMENT ON COLUMN public.user_surveys.scale_max IS 'Maximum scale value';
COMMENT ON COLUMN public.user_surveys.scale_labels IS 'Labels for scale points';
COMMENT ON COLUMN public.user_surveys.follow_up_question IS 'Conditional follow-up question';
COMMENT ON COLUMN public.user_surveys.follow_up_threshold IS 'Score threshold for follow-up';
COMMENT ON COLUMN public.user_surveys.incentive_type IS 'Type of incentive offered';
COMMENT ON COLUMN public.user_surveys.incentive_value IS 'Value of incentive';
COMMENT ON COLUMN public.user_surveys.target_responses IS 'Desired response count';
COMMENT ON COLUMN public.user_surveys.actual_responses IS 'Actual response count';
COMMENT ON COLUMN public.user_surveys.response_rate IS 'Calculated response rate';
COMMENT ON COLUMN public.user_surveys.average_score IS 'Average score from responses';
COMMENT ON COLUMN public.user_surveys.score_distribution IS 'Histogram of scores';
COMMENT ON COLUMN public.user_surveys.nps_segments IS 'NPS segment breakdown';
COMMENT ON COLUMN public.user_surveys.owner_id IS 'Survey owner';
COMMENT ON COLUMN public.user_surveys.created_at IS 'Record creation timestamp';
COMMENT ON COLUMN public.user_surveys.updated_at IS 'Last update timestamp';
COMMENT ON COLUMN public.user_surveys.created_by IS 'User who created record';
COMMENT ON COLUMN public.user_surveys.updated_by IS 'User who last updated record';

-- Indexes
CREATE INDEX idx_user_surveys_status ON public.user_surveys(status, scheduled_start_at);
CREATE INDEX idx_user_surveys_type ON public.user_surveys(survey_type);
CREATE INDEX idx_user_surveys_owner ON public.user_surveys(owner_id);

-- Trigger for updated_at
CREATE TRIGGER update_user_surveys_timestamp
    BEFORE UPDATE ON public.user_surveys
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.user_surveys ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY user_surveys_owner_policy ON public.user_surveys
    USING (owner_id = current_user_id() OR
           EXISTS (SELECT 1 FROM public.user_roles ur
                  JOIN public.roles r ON ur.role_id = r.role_id
                  WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'product_manager')));

-- Survey responses table (child of surveys)
CREATE TABLE public.survey_responses (
    response_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    survey_id            UUID NOT NULL REFERENCES public.user_surveys(survey_id) ON DELETE CASCADE,
    user_id              UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Response data
    score                SMALLINT CHECK (score >= 0 AND score <= 10),
    answer_text          TEXT,
    follow_up_answer     TEXT,

    -- Metadata
    responded_at         TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    response_channel     public.notification_channel,
    time_to_respond      INTERVAL GENERATED ALWAYS AS (responded_at - survey_sent_at) STORED,
    survey_sent_at       TIMESTAMP WITH TIME ZONE,

    -- Context
    page_url             TEXT,
    user_agent           TEXT,

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    CONSTRAINT unique_user_survey_response UNIQUE (survey_id, user_id)
) PARTITION BY HASH (user_id);  -- Partition by user for even distribution

COMMENT ON TABLE public.survey_responses IS 'Individual survey responses from users';

-- Create 10 hash partitions for responses
CREATE TABLE public.survey_responses_0 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 0);
CREATE TABLE public.survey_responses_1 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 1);
CREATE TABLE public.survey_responses_2 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 2);
CREATE TABLE public.survey_responses_3 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 3);
CREATE TABLE public.survey_responses_4 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 4);
CREATE TABLE public.survey_responses_5 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 5);
CREATE TABLE public.survey_responses_6 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 6);
CREATE TABLE public.survey_responses_7 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 7);
CREATE TABLE public.survey_responses_8 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 8);
CREATE TABLE public.survey_responses_9 PARTITION OF public.survey_responses FOR VALUES WITH (MODULUS 10, REMAINDER 9);

-- Indexes on responses
CREATE INDEX idx_survey_responses_survey_id ON public.survey_responses(survey_id);
CREATE INDEX idx_survey_responses_user_id ON public.survey_responses(user_id);
CREATE INDEX idx_survey_responses_score ON public.survey_responses(score) WHERE score IS NOT NULL;

-- Enable RLS on responses
ALTER TABLE public.survey_responses ENABLE ROW LEVEL SECURITY;

-- RLS for responses
CREATE POLICY survey_responses_user_policy ON public.survey_responses
    USING (user_id = current_user_id());

CREATE POLICY survey_responses_analyst_policy ON public.survey_responses
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'analyst', 'product_manager')
    ));

-- ======================================================================
-- TABLE: 66 - support_tickets
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 66
-- Table Name: support_tickets
-- Description: Central customer support ticket management system tracking all user issues,
--              assignments, priorities, and resolution workflows.
--
-- Business Case (300 words):
-- Customer support is the frontline of user experience and retention. Without a robust
-- ticketing system, issues fall through cracks, response times increase, and user frustration
-- grows. This table provides a comprehensive support ticket management system that integrates
-- with user profiles, notifications, and analytics to deliver exceptional customer service.
--
-- The business impact is direct: faster resolution times lead to higher CSAT scores and
-- improved retention. For every hour reduction in first response time, customer satisfaction
-- increases by 5-10%. The table enables support teams to prioritize effectively - critical
-- issues for enterprise customers are flagged and escalated automatically. It also provides
-- visibility into team performance and common issue patterns.
--
-- For product teams, ticket data is a goldmine of usability issues and feature requests.
-- Analyzing ticket categories helps identify areas needing product improvements. For sales,
-- ticket volume per account can indicate renewal risk. For compliance, the table maintains
-- an audit trail of all support interactions, essential for regulated industries.
--
-- The design supports modern support workflows: SLA tracking, automated assignments,
-- escalation paths, and customer satisfaction surveys after resolution. Integration with
-- knowledge base allows agents to quickly link relevant articles, and with notifications
-- to keep users updated on ticket status.
--
-- KPIs:
--   1. First response time (average, median, 90th percentile)
--   2. Resolution time by priority and category
--   3. CSAT score after ticket resolution
--   4. Ticket volume by category (top issues)
--   5. Backlog size and age (unresolved tickets)
--   6. Agent productivity (tickets resolved per day)
--   7. Escalation rate (percentage requiring senior support)
--   8. Reopen rate (tickets reopened after closure)
--   9. SLA compliance percentage by priority
--
-- Feature Reference: UX-SUP-01 to UX-SUP-30 (Support System)
--
-- Normalization: 3NF - tickets are separate from users, with dedicated tables for comments
--
-- High-Write Considerations:
--   - Moderate write volume (new tickets and updates daily)
--   - Partition by created_at for historical data management
--   - Indexes optimized for agent workflows (status, priority, assigned_to)
------------------------------------------------------------------------------------------------
CREATE TABLE public.support_tickets (
    -- Primary identifiers
    ticket_id            UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    ticket_number        VARCHAR(50) UNIQUE,                   -- Human-readable number

    -- Core
    user_id              UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    subject              VARCHAR(255) NOT NULL,
    description          TEXT NOT NULL,

    -- Categorization
    category             public.ticket_category NOT NULL,
    priority             public.ticket_priority NOT NULL DEFAULT 'MEDIUM',

    -- Status
    status               public.ticket_status NOT NULL DEFAULT 'NEW',

    -- Assignment
    assigned_to          UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    assigned_at          TIMESTAMP WITH TIME ZONE,
    assigned_by          UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Escalation
    escalated_at         TIMESTAMP WITH TIME ZONE,
    escalated_to         UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    escalation_reason    TEXT,

    -- Timing
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    first_response_at    TIMESTAMP WITH TIME ZONE,
    resolved_at          TIMESTAMP WITH TIME ZONE,
    closed_at            TIMESTAMP WITH TIME ZONE,

    -- SLA tracking
    sla_target           INTERVAL,                              -- e.g., '4 hours' for first response
    sla_breached         BOOLEAN DEFAULT false,
    sla_breached_at      TIMESTAMP WITH TIME ZONE,
    time_to_first_response INTERVAL GENERATED ALWAYS AS
        (first_response_at - created_at) STORED,
    time_to_resolution   INTERVAL GENERATED ALWAYS AS
        (resolved_at - created_at) STORED,

    -- Customer satisfaction
    csat_score           SMALLINT CHECK (csat_score BETWEEN 1 AND 5),
    csat_survey_sent_at  TIMESTAMP WITH TIME ZONE,
    csat_response_at     TIMESTAMP WITH TIME ZONE,
    csat_comment         TEXT,

    -- Related items
    related_tickets      UUID[],                                -- Linked tickets
    related_content_id   UUID,                                  -- Content item causing issue
    related_job_id       UUID REFERENCES public.job_listings(job_listing_id) ON DELETE SET NULL,

    -- Internal
    internal_notes       TEXT,
    tags                 TEXT[],

    -- Attachments
    attachments          TEXT[],                                -- URLs to uploaded files

    -- Audit
    created_by           UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    updated_by           UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Metadata
    browser_info         JSONB,                                 -- Context at creation
    source               VARCHAR(50) DEFAULT 'web' CHECK (source IN ('web', 'mobile', 'email', 'api', 'phone'))
);

COMMENT ON TABLE public.support_tickets IS 'Central customer support ticket management';
COMMENT ON COLUMN public.support_tickets.ticket_id IS 'Primary key';
COMMENT ON COLUMN public.support_tickets.ticket_number IS 'Human-readable ticket number';
COMMENT ON COLUMN public.support_tickets.user_id IS 'User reporting issue';
COMMENT ON COLUMN public.support_tickets.subject IS 'Ticket subject line';
COMMENT ON COLUMN public.support_tickets.description IS 'Detailed issue description';
COMMENT ON COLUMN public.support_tickets.category IS 'Issue category';
COMMENT ON COLUMN public.support_tickets.priority IS 'Issue priority';
COMMENT ON COLUMN public.support_tickets.status IS 'Current status';
COMMENT ON COLUMN public.support_tickets.assigned_to IS 'Support agent assigned';
COMMENT ON COLUMN public.support_tickets.assigned_at IS 'When assigned';
COMMENT ON COLUMN public.support_tickets.assigned_by IS 'Who assigned';
COMMENT ON COLUMN public.support_tickets.escalated_at IS 'When escalated';
COMMENT ON COLUMN public.support_tickets.escalated_to IS 'Senior agent';
COMMENT ON COLUMN public.support_tickets.escalation_reason IS 'Why escalated';
COMMENT ON COLUMN public.support_tickets.created_at IS 'Ticket creation time';
COMMENT ON COLUMN public.support_tickets.updated_at IS 'Last update time';
COMMENT ON COLUMN public.support_tickets.first_response_at IS 'Time of first agent response';
COMMENT ON COLUMN public.support_tickets.resolved_at IS 'Time of resolution';
COMMENT ON COLUMN public.support_tickets.closed_at IS 'Time of closure';
COMMENT ON COLUMN public.support_tickets.sla_target IS 'SLA target duration';
COMMENT ON COLUMN public.support_tickets.sla_breached IS 'Whether SLA was missed';
COMMENT ON COLUMN public.support_tickets.sla_breached_at IS 'When SLA was breached';
COMMENT ON COLUMN public.support_tickets.time_to_first_response IS 'Time to first response';
COMMENT ON COLUMN public.support_tickets.time_to_resolution IS 'Time to resolution';
COMMENT ON COLUMN public.support_tickets.csat_score IS 'Customer satisfaction score';
COMMENT ON COLUMN public.support_tickets.csat_survey_sent_at IS 'When CSAT survey sent';
COMMENT ON COLUMN public.support_tickets.csat_response_at IS 'When CSAT response received';
COMMENT ON COLUMN public.support_tickets.csat_comment IS 'CSAT feedback comment';
COMMENT ON COLUMN public.support_tickets.related_tickets IS 'Related ticket IDs';
COMMENT ON COLUMN public.support_tickets.related_content_id IS 'Related content (if any)';
COMMENT ON COLUMN public.support_tickets.related_job_id IS 'Related job (if any)';
COMMENT ON COLUMN public.support_tickets.internal_notes IS 'Private agent notes';
COMMENT ON COLUMN public.support_tickets.tags IS 'Searchable tags';
COMMENT ON COLUMN public.support_tickets.attachments IS 'File attachments';
COMMENT ON COLUMN public.support_tickets.created_by IS 'User who created';
COMMENT ON COLUMN public.support_tickets.updated_by IS 'User who last updated';
COMMENT ON COLUMN public.support_tickets.browser_info IS 'Client context';
COMMENT ON COLUMN public.support_tickets.source IS 'Ticket origin';

-- Generate ticket number sequence
CREATE SEQUENCE public.ticket_number_seq START 10000;

-- Create function to auto-generate ticket number
CREATE OR REPLACE FUNCTION public.generate_ticket_number()
RETURNS TRIGGER AS $$
BEGIN
    NEW.ticket_number := 'TKT-' || TO_CHAR(NEW.created_at, 'YYYYMM') || '-' ||
                         LPAD(nextval('public.ticket_number_seq')::TEXT, 6, '0');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_generate_ticket_number
    BEFORE INSERT ON public.support_tickets
    FOR EACH ROW EXECUTE FUNCTION public.generate_ticket_number();

-- Indexes
CREATE INDEX idx_support_tickets_user_id ON public.support_tickets(user_id, created_at DESC);
CREATE INDEX idx_support_tickets_assigned_to ON public.support_tickets(assigned_to, status) WHERE assigned_to IS NOT NULL;
CREATE INDEX idx_support_tickets_status ON public.support_tickets(status, priority, created_at);
CREATE INDEX idx_support_tickets_category ON public.support_tickets(category);
CREATE INDEX idx_support_tickets_created_at ON public.support_tickets(created_at);
CREATE INDEX idx_support_tickets_sla_breached ON public.support_tickets(sla_breached) WHERE sla_breached = true;

-- GIN index for tags
CREATE INDEX idx_support_tickets_tags ON public.support_tickets USING gin(tags);

-- Trigger for updated_at
CREATE TRIGGER update_support_tickets_timestamp
    BEFORE UPDATE ON public.support_tickets
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY support_tickets_user_policy ON public.support_tickets
    USING (user_id = current_user_id());

CREATE POLICY support_tickets_agent_policy ON public.support_tickets
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'support_agent', 'support_manager')
    ));

-- ======================================================================
-- TABLE: 67 - ticket_comments
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 67
-- Table Name: ticket_comments
-- Description: Complete conversation history for support tickets, including public replies
--              and internal notes between agents.
--
-- Business Case (300 words):
-- Support conversations are the core of ticket resolution, containing valuable context,
-- troubleshooting steps, and user feedback. Without structured storage, this information
-- is lost, leading to repetitive questions and inconsistent support. This table provides
-- a complete audit trail of all ticket communications, enabling seamless handoffs between
-- agents and preserving context for future reference.
--
-- The business value includes improved efficiency - agents can quickly review previous
-- interactions without asking users to repeat themselves. For quality assurance, managers
-- can review conversations to ensure appropriate responses and identify training needs.
-- For analytics, comment patterns can reveal common confusion points and areas where
-- documentation is needed.
--
-- The table distinguishes between public replies (visible to users) and internal notes
-- (visible only to agents), supporting both transparent communication and private team
-- collaboration. Attachments allow screenshots and files to be shared, while system
-- messages automatically record status changes (e.g., "Ticket escalated to Level 2").
--
-- For compliance, the table maintains an immutable record of all communications, essential
-- for regulated industries and dispute resolution. For product feedback, comments can be
-- tagged and analyzed to identify feature requests and bug patterns.
--
-- KPIs:
--   1. Comments per ticket (average, distribution)
--   2. Agent vs. user comment ratio
--   3. Average response time between comments
--   4. Internal note percentage (private vs. public)
--   5. Attachment usage rate
--   6. First response quality (CSAT correlation with comment content)
--   7. Knowledge base article suggestions from comments
--
-- Feature Reference: UX-SUP-31 to UX-SUP-40 (Ticket Communication)
--
-- Normalization: 3NF - comments belong to tickets, separate from other ticket metadata
--
-- High-Write Considerations:
--   - High write volume (multiple comments per ticket)
--   - Partition by ticket_id or created_at
--   - Index on ticket_id for fast conversation loading
------------------------------------------------------------------------------------------------
CREATE TABLE public.ticket_comments (
    -- Primary identifiers
    comment_id           UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    ticket_id            UUID NOT NULL REFERENCES public.support_tickets(ticket_id) ON DELETE CASCADE,

    -- Author
    author_id            UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    author_type          VARCHAR(20) NOT NULL CHECK (author_type IN ('user', 'agent', 'system')),

    -- Content
    comment_text         TEXT NOT NULL,
    is_public            BOOLEAN NOT NULL DEFAULT true,        -- False for internal notes

    -- Formatting
    formatted_text       TEXT,                                  -- HTML/Markdown version
    mentions             UUID[],                                -- Users mentioned (@mentions)

    -- Attachments
    attachments          TEXT[],                                -- URLs to uploaded files

    -- System metadata
    is_status_change     BOOLEAN DEFAULT false,                 -- Comment is auto-generated from status change
    previous_status      public.ticket_status,
    new_status           public.ticket_status,

    -- Time tracking
    time_spent_minutes   INTEGER,                                -- Time spent on this comment (for billing)

    -- Moderation
    is_edited            BOOLEAN DEFAULT false,
    edited_at            TIMESTAMP WITH TIME ZONE,
    edited_by            UUID REFERENCES public.users(user_id) ON DELETE SET NULL,

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);

COMMENT ON TABLE public.ticket_comments IS 'Conversation history for support tickets';
COMMENT ON COLUMN public.ticket_comments.comment_id IS 'Primary key';
COMMENT ON COLUMN public.ticket_comments.ticket_id IS 'Parent ticket';
COMMENT ON COLUMN public.ticket_comments.author_id IS 'User who wrote comment';
COMMENT ON COLUMN public.ticket_comments.author_type IS 'Type of author';
COMMENT ON COLUMN public.ticket_comments.comment_text IS 'Comment content';
COMMENT ON COLUMN public.ticket_comments.is_public IS 'Whether visible to user';
COMMENT ON COLUMN public.ticket_comments.formatted_text IS 'Formatted version';
COMMENT ON COLUMN public.ticket_comments.mentions IS 'Users mentioned';
COMMENT ON COLUMN public.ticket_comments.attachments IS 'File attachments';
COMMENT ON COLUMN public.ticket_comments.is_status_change IS 'Auto-generated from status change';
COMMENT ON COLUMN public.ticket_comments.previous_status IS 'Status before change';
COMMENT ON COLUMN public.ticket_comments.new_status IS 'Status after change';
COMMENT ON COLUMN public.ticket_comments.time_spent_minutes IS 'Time spent on this comment';
COMMENT ON COLUMN public.ticket_comments.is_edited IS 'Whether comment was edited';
COMMENT ON COLUMN public.ticket_comments.edited_at IS 'When edited';
COMMENT ON COLUMN public.ticket_comments.edited_by IS 'Who edited';
COMMENT ON COLUMN public.ticket_comments.created_at IS 'Creation timestamp';
COMMENT ON COLUMN public.ticket_comments.updated_at IS 'Last update timestamp';

-- Indexes
CREATE INDEX idx_ticket_comments_ticket_id ON public.ticket_comments(ticket_id, created_at);
CREATE INDEX idx_ticket_comments_author_id ON public.ticket_comments(author_id);
CREATE INDEX idx_ticket_comments_created_at ON public.ticket_comments(created_at);

-- Trigger for updated_at
CREATE TRIGGER update_ticket_comments_timestamp
    BEFORE UPDATE ON public.ticket_comments
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.ticket_comments ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY ticket_comments_user_policy ON public.ticket_comments
    USING (is_public = true AND EXISTS (
        SELECT 1 FROM public.support_tickets st
        WHERE st.ticket_id = ticket_comments.ticket_id
        AND st.user_id = current_user_id()
    ));

CREATE POLICY ticket_comments_agent_policy ON public.ticket_comments
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'support_agent', 'support_manager')
    ));

-- ======================================================================
-- TABLE: 68 - knowledge_base_articles
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 68
-- Table Name: knowledge_base_articles
-- Description: Self-service knowledge base with articles, FAQs, and documentation to help
--              users resolve issues independently.
--
-- Business Case (300 words):
-- A robust knowledge base is the foundation of scalable customer support. Every article that
-- helps a user self-solve reduces support ticket volume by one, saving agent time and
-- improving user satisfaction (users prefer self-service when possible). This table provides
-- a comprehensive knowledge management system for creating, organizing, and serving help
-- content to users.
--
-- The business impact is significant: effective knowledge bases can deflect 30-50% of
-- support tickets, resulting in millions in cost savings. For users, instant answers improve
-- satisfaction and reduce frustration. For SEO, public articles drive organic traffic to
-- the site. For product teams, article view metrics indicate which features need better
-- documentation or UX improvements.
--
-- The table supports modern documentation needs: versioning (articles updated over time),
-- multilingual content, related articles, and feedback collection (helpful/not helpful).
-- Integration with the support system allows agents to quickly link tickets to relevant
-- articles, and search functionality helps users find answers instantly.
--
-- For enterprise customers, private articles can be restricted to specific user tiers.
-- For compliance, articles can be locked after legal review. Analytics track which articles
-- are most viewed, which have high "not helpful" rates, and which correlate with reduced
-- ticket volume.
--
-- KPIs:
--   1. Article views per day/week/month
--   2. Helpful rate (percentage finding article useful)
--   3. Search-to-article conversion (searches leading to article views)
--   4. Ticket deflection rate (articles viewed before ticket creation)
--   5. Article coverage (percentage of common issues with articles)
--   6. Time to publish (from draft to live)
--   7. Article freshness (time since last update)
--   8. Top search terms without articles (content gaps)
--
-- Feature Reference: UX-KB-01 to UX-KB-25 (Knowledge Base)
--
-- Normalization: 3NF - articles, categories, and feedback are separate
--
-- High-Write Considerations:
--   - Read-heavy (article views dominate)
--   - Writes for updates and feedback moderate
--   - Caching essential (Redis for article content)
------------------------------------------------------------------------------------------------
CREATE TABLE public.knowledge_base_articles (
    -- Primary identifiers
    article_id           UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    article_slug         VARCHAR(255) NOT NULL UNIQUE,        -- URL-friendly identifier
    article_number       VARCHAR(50) UNIQUE,                   -- Internal reference

    -- Core content
    title                VARCHAR(255) NOT NULL,
    content              TEXT NOT NULL,
    excerpt              VARCHAR(500),                          -- Summary for listings
    article_type         public.article_type NOT NULL,

    -- Categorization
    category_id          UUID REFERENCES public.content_categories(category_id) ON DELETE SET NULL,
    tags                 TEXT[],

    -- SEO
    meta_title           VARCHAR(255),
    meta_description     VARCHAR(500),
    meta_keywords        TEXT[],
    canonical_url        TEXT,

    -- Versioning
    version              INTEGER NOT NULL DEFAULT 1,
    previous_version_id  UUID REFERENCES public.knowledge_base_articles(article_id) ON DELETE SET NULL,
    change_log           TEXT,

    -- Status
    status               VARCHAR(20) DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'REVIEW', 'PUBLISHED', 'ARCHIVED')),
    published_at         TIMESTAMP WITH TIME ZONE,
    archived_at          TIMESTAMP WITH TIME ZONE,

    -- Visibility
    visibility           VARCHAR(20) DEFAULT 'PUBLIC' CHECK (visibility IN ('PUBLIC', 'AUTHENTICATED', 'PREMIUM', 'INTERNAL')),
    required_user_tier   VARCHAR(50),                           -- For premium content

    -- Authorship
    author_id            UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    editor_id            UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    reviewer_id          UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    review_completed_at  TIMESTAMP WITH TIME ZONE,

    -- Related content
    related_articles     UUID[],                                -- Manually related
    automatically_related UUID[],                               -- System-suggested

    -- Attachments
    featured_image       TEXT,
    attachments          TEXT[],                                -- Downloads/resources

    -- Feedback
    helpful_count        INTEGER DEFAULT 0,
    not_helpful_count    INTEGER DEFAULT 0,
    helpful_score        NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN (helpful_count + not_helpful_count) > 0
        THEN (helpful_count::NUMERIC / (helpful_count + not_helpful_count)) * 100
        ELSE NULL END
    ) STORED,

    -- Analytics
    view_count           INTEGER DEFAULT 0,
    unique_view_count    INTEGER DEFAULT 0,
    last_viewed_at       TIMESTAMP WITH TIME ZONE,

    -- Search
    search_vector        TSVECTOR,

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT
);

COMMENT ON TABLE public.knowledge_base_articles IS 'Self-service knowledge base articles and documentation';
COMMENT ON COLUMN public.knowledge_base_articles.article_id IS 'Primary key';
COMMENT ON COLUMN public.knowledge_base_articles.article_slug IS 'URL-friendly identifier';
COMMENT ON COLUMN public.knowledge_base_articles.article_number IS 'Internal reference number';
COMMENT ON COLUMN public.knowledge_base_articles.title IS 'Article title';
COMMENT ON COLUMN public.knowledge_base_articles.content IS 'Full article content';
COMMENT ON COLUMN public.knowledge_base_articles.excerpt IS 'Short summary';
COMMENT ON COLUMN public.knowledge_base_articles.article_type IS 'Type of article';
COMMENT ON COLUMN public.knowledge_base_articles.category_id IS 'Content category';
COMMENT ON COLUMN public.knowledge_base_articles.tags IS 'Searchable tags';
COMMENT ON COLUMN public.knowledge_base_articles.meta_title IS 'SEO title';
COMMENT ON COLUMN public.knowledge_base_articles.meta_description IS 'SEO description';
COMMENT ON COLUMN public.knowledge_base_articles.meta_keywords IS 'SEO keywords';
COMMENT ON COLUMN public.knowledge_base_articles.canonical_url IS 'Canonical URL for SEO';
COMMENT ON COLUMN public.knowledge_base_articles.version IS 'Article version';
COMMENT ON COLUMN public.knowledge_base_articles.previous_version_id IS 'Previous version reference';
COMMENT ON COLUMN public.knowledge_base_articles.change_log IS 'Description of changes';
COMMENT ON COLUMN public.knowledge_base_articles.status IS 'Publication status';
COMMENT ON COLUMN public.knowledge_base_articles.published_at IS 'When published';
COMMENT ON COLUMN public.knowledge_base_articles.archived_at IS 'When archived';
