COMMENT ON COLUMN public.knowledge_base_articles.author_id IS 'Original author';
COMMENT ON COLUMN public.knowledge_base_articles.editor_id IS 'Last editor';
COMMENT ON COLUMN public.knowledge_base_articles.reviewer_id IS 'Content reviewer';
COMMENT ON COLUMN public.knowledge_base_articles.review_completed_at IS 'When review completed';
COMMENT ON COLUMN public.knowledge_base_articles.related_articles IS 'Manually related articles';
COMMENT ON COLUMN public.knowledge_base_articles.automatically_related IS 'System-suggested related';
