COMMENT ON COLUMN public.knowledge_base_articles.created_at IS 'Creation timestamp';
COMMENT ON COLUMN public.knowledge_base_articles.updated_at IS 'Last update timestamp';
COMMENT ON COLUMN public.knowledge_base_articles.created_by IS 'User who created';
COMMENT ON COLUMN public.knowledge_base_articles.updated_by IS 'User who last updated';

-- Generate article number
CREATE SEQUENCE public.article_number_seq START 1000;

CREATE OR REPLACE FUNCTION public.generate_article_number()
RETURNS TRIGGER AS $$
BEGIN
    NEW.article_number := 'KB-' || TO_CHAR(NEW.created_at, 'YYYY') || '-' ||
                          LPAD(nextval('public.article_number_seq')::TEXT, 6, '0');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_generate_article_number
    BEFORE INSERT ON public.knowledge_base_articles
    FOR EACH ROW EXECUTE FUNCTION public.generate_article_number();

-- Search vector update function
CREATE OR REPLACE FUNCTION public.update_article_search_vector()
RETURNS TRIGGER AS $$
BEGIN
    NEW.search_vector :=
        setweight(to_tsvector('english', COALESCE(NEW.title, '')), 'A') ||
        setweight(to_tsvector('english', COALESCE(NEW.excerpt, '')), 'B') ||
        setweight(to_tsvector('english', COALESCE(NEW.content, '')), 'C');
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_article_search_vector_update
    BEFORE INSERT OR UPDATE ON public.knowledge_base_articles
    FOR EACH ROW EXECUTE FUNCTION public.update_article_search_vector();

-- Indexes
CREATE INDEX idx_kb_articles_slug ON public.knowledge_base_articles(article_slug) WHERE status = 'PUBLISHED';
CREATE INDEX idx_kb_articles_type ON public.knowledge_base_articles(article_type, status);
CREATE INDEX idx_kb_articles_category ON public.knowledge_base_articles(category_id) WHERE status = 'PUBLISHED';
CREATE INDEX idx_kb_articles_search ON public.knowledge_base_articles USING gin(search_vector);
CREATE INDEX idx_kb_articles_tags ON public.knowledge_base_articles USING gin(tags);
CREATE INDEX idx_kb_articles_published_at ON public.knowledge_base_articles(published_at DESC) WHERE status = 'PUBLISHED';

-- Trigger for updated_at
CREATE TRIGGER update_kb_articles_timestamp
    BEFORE UPDATE ON public.knowledge_base_articles
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.knowledge_base_articles ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY kb_articles_public_policy ON public.knowledge_base_articles
    FOR SELECT USING (
        (visibility = 'PUBLIC' AND status = 'PUBLISHED') OR
        (visibility = 'AUTHENTICATED' AND status = 'PUBLISHED' AND
         EXISTS (SELECT 1 FROM public.users WHERE user_id = current_user_id())) OR
        (visibility = 'PREMIUM' AND status = 'PUBLISHED' AND
         EXISTS (SELECT 1 FROM public.subscriptions s
                 WHERE s.user_id = current_user_id() AND s.status = 'ACTIVE'))
    );

CREATE POLICY kb_articles_author_policy ON public.knowledge_base_articles
    USING (author_id = current_user_id() OR
           EXISTS (SELECT 1 FROM public.user_roles ur
                  JOIN public.roles r ON ur.role_id = r.role_id
                  WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'content_manager')));

-- Article feedback table
CREATE TABLE public.article_feedback (
    feedback_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    article_id           UUID NOT NULL REFERENCES public.knowledge_base_articles(article_id) ON DELETE CASCADE,
    user_id              UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    was_helpful          BOOLEAN NOT NULL,
    comment              TEXT,
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);

COMMENT ON TABLE public.article_feedback IS 'User feedback on knowledge base articles';

CREATE INDEX idx_article_feedback_article ON public.article_feedback(article_id, was_helpful);

-- ======================================================================
-- TABLE: 69 - user_achievements
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 69
-- Table Name: user_achievements
-- Description: Gamification system tracking badges, milestones, and accomplishments earned
--              by users through platform engagement and contributions.
--
-- Business Case (300 words):
-- Gamification drives user engagement by tapping into intrinsic motivation (mastery,
-- recognition) and extrinsic rewards. Professional networks particularly benefit from
-- achievement systems that recognize expertise, contributions, and community involvement.
-- This table powers a comprehensive achievement system that rewards desired behaviors and
-- creates positive feedback loops.
--
-- The business impact is measurable: users with achievements have 40% higher retention,
-- 3x more content contributions, and are more likely to refer others. Achievements serve
-- as social proof - a "Top Contributor" badge signals credibility to other users.
-- For community building, achievements recognize helpful members, encouraging continued
-- participation. For product adoption, "Power User" achievements incentivize feature usage.
--
-- The design supports various achievement types: onboarding (completed profile), engagement
-- (logged in 30 days straight), contribution (10 helpful answers), expertise (skill endorsed
-- by 5 people), and special events (early adopter). Achievements can be tiered (Bronze,
-- Silver, Gold) to provide progression. The table tracks when each achievement was earned,
-- allowing celebration moments (confetti animation, congratulatory email).
--
-- For enterprise, achievements can be tied to professional development - completing courses,
-- earning certifications. For recruitment, achievements on profiles serve as verifiable
-- credentials. For analytics, achievement data reveals which behaviors are being incentivized
-- effectively and where users get stuck.
--
-- KPIs:
--   1. Users with at least one achievement (percentage)
--   2. Average achievements per user
--   3. Achievement completion rate by type
--   4. Time from signup to first achievement
--   5. Retention lift for users with achievements vs. without
--   6. Most commonly earned achievements
--   7. Rare achievements (percentage of users earning)
--   8. Achievement sharing rate (social sharing)
--
-- Feature Reference: UX-GAM-01 to UX-GAM-30 (Gamification)
--
-- Normalization: 3NF - achievements definition separate from user progress
--
-- High-Write Considerations:
--   - Moderate writes as users earn achievements
--   - Achievements earned in batches possible
--   - Read-heavy for profile display
------------------------------------------------------------------------------------------------
CREATE TABLE public.achievement_definitions (
    achievement_id       UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    achievement_code     VARCHAR(50) NOT NULL UNIQUE,          -- e.g., 'PROFILE_COMPLETE'
    name                 VARCHAR(255) NOT NULL,
    description          TEXT NOT NULL,

    -- Categorization
    achievement_type     public.achievement_type NOT NULL,
    category             VARCHAR(50),                           -- e.g., 'onboarding', 'engagement'

    -- Tiers (if applicable)
    has_tiers            BOOLEAN DEFAULT false,
    tier_levels          SMALLINT DEFAULT 1 CHECK (tier_levels BETWEEN 1 AND 5),
    tier_names           TEXT[],                                 -- e.g., ['Bronze', 'Silver', 'Gold']

    -- Criteria (JSON defining how to earn)
    criteria_type        VARCHAR(50) CHECK (criteria_type IN ('count', 'threshold', 'streak', 'completion', 'custom')),
    criteria_definition  JSONB NOT NULL,                         -- e.g., {"action": "login", "count": 30}

    -- Rewards
    points_value         INTEGER DEFAULT 0,
    badge_image_url      TEXT,
    badge_image_svg      TEXT,

    -- Display
    icon                 VARCHAR(50),
    color                VARCHAR(20),
    is_visible           BOOLEAN DEFAULT true,
    display_order        INTEGER,

    -- Achievement limits
    max_awards_per_user  INTEGER DEFAULT 1,                      -- 1 for one-time, >1 for repeatable
    global_limit         INTEGER,                                 -- Max total awards platform-wide

    -- Time constraints
    available_from       TIMESTAMP WITH TIME ZONE,
    available_to         TIMESTAMP WITH TIME ZONE,
    is_limited_time      BOOLEAN DEFAULT false,

    -- Dependencies
    prerequisites        UUID[],                                 -- Required achievements first

    -- Metadata
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT,
    updated_by           UUID NOT NULL REFERENCES public.users(user_id) ON DELETE RESTRICT
);

COMMENT ON TABLE public.achievement_definitions IS 'Master list of all possible achievements';

-- User achievements (earned)
CREATE TABLE public.user_achievements (
    user_achievement_id  UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id              UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    achievement_id       UUID NOT NULL REFERENCES public.achievement_definitions(achievement_id) ON DELETE CASCADE,

    -- Tier tracking
    tier_level           SMALLINT DEFAULT 1 CHECK (tier_level >= 1),

    -- Progress tracking
    progress_value       INTEGER,                                 -- e.g., current count toward achievement
    target_value         INTEGER,                                 -- e.g., required count
    percent_complete     NUMERIC(5,2) GENERATED ALWAYS AS (
        CASE WHEN target_value > 0
        THEN (progress_value::NUMERIC / target_value) * 100
        ELSE NULL END
    ) STORED,

    -- Earning
    earned_at            TIMESTAMP WITH TIME ZONE,
    is_earned             BOOLEAN DEFAULT false,

    -- Context
    earned_metadata      JSONB,                                   -- e.g., which content triggered

    -- Sharing
    shared_on_social     BOOLEAN DEFAULT false,
    shared_at            TIMESTAMP WITH TIME ZONE,

    -- Notification
    notified_at          TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    CONSTRAINT unique_user_achievement UNIQUE (user_id, achievement_id, tier_level)
);

COMMENT ON TABLE public.user_achievements IS 'Achievements earned by users';

-- Achievement progress tracking (for multi-stage achievements)
CREATE TABLE public.achievement_progress (
    progress_id          UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id              UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    achievement_id       UUID NOT NULL REFERENCES public.achievement_definitions(achievement_id) ON DELETE CASCADE,

    -- Current state
    current_value        INTEGER NOT NULL DEFAULT 0,
    target_value         INTEGER NOT NULL,
    last_updated_at      TIMESTAMP WITH TIME ZONE,

    -- Streak tracking
    current_streak       INTEGER DEFAULT 0,
    longest_streak       INTEGER DEFAULT 0,
    streak_reset_at      TIMESTAMP WITH TIME ZONE,

    -- History
    progress_history     JSONB,                                   -- Timeline of progress

    -- Audit
    created_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    CONSTRAINT unique_user_achievement_progress UNIQUE (user_id, achievement_id)
);

COMMENT ON TABLE public.achievement_progress IS 'Real-time progress tracking toward achievements';

-- Indexes
CREATE INDEX idx_user_achievements_user ON public.user_achievements(user_id, is_earned);
CREATE INDEX idx_user_achievements_achievement ON public.user_achievements(achievement_id);
CREATE INDEX idx_user_achievements_earned_at ON public.user_achievements(earned_at) WHERE is_earned = true;

CREATE INDEX idx_achievement_progress_user ON public.achievement_progress(user_id);
CREATE INDEX idx_achievement_progress_achievement ON public.achievement_progress(achievement_id);

-- Triggers
CREATE TRIGGER update_achievement_definitions_timestamp
    BEFORE UPDATE ON public.achievement_definitions
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

CREATE TRIGGER update_user_achievements_timestamp
    BEFORE UPDATE ON public.user_achievements
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

CREATE TRIGGER update_achievement_progress_timestamp
    BEFORE UPDATE ON public.achievement_progress
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.achievement_definitions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_achievements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.achievement_progress ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY achievement_definitions_read_policy ON public.achievement_definitions
    FOR SELECT USING (true);

CREATE POLICY achievement_definitions_admin_policy ON public.achievement_definitions
    USING (EXISTS (
        SELECT 1 FROM public.user_roles ur
        JOIN public.roles r ON ur.role_id = r.role_id
        WHERE ur.user_id = current_user_id() AND r.name = 'admin'
    ));

CREATE POLICY user_achievements_user_policy ON public.user_achievements
    USING (user_id = current_user_id());

CREATE POLICY user_achievements_public_policy ON public.user_achievements
    FOR SELECT USING (is_earned = true);  -- Anyone can see earned achievements

CREATE POLICY achievement_progress_user_policy ON public.achievement_progress
    USING (user_id = current_user_id());

-- ======================================================================
-- TABLE: 70 - user_streaks
-- ======================================================================
------------------------------------------------------------------------------------------------
-- Serial No: 70
-- Table Name: user_streaks
-- Description: Tracks consecutive day activity streaks for users, a powerful retention
--              mechanism that encourages daily platform engagement.
--
-- Business Case (300 words):
-- Streaks are one of the most effective gamification mechanics for driving daily active users
-- (DAU). The psychological principle is simple: users don't want to break their streak, so
-- they return daily. This table powers a streak system that tracks consecutive days of
-- platform activity, celebrating milestones and warning users when streaks are at risk.
--
-- The business impact is significant: streak systems have been shown to increase DAU by
-- 20-30% and 30-day retention by 15-25%. For professional networks, daily engagement is
-- critical for network effects - active users generate content, connections, and interactions
-- that benefit all users. Streaks also create habit formation, making platform usage
-- automatic rather than intentional.
--
-- The table tracks multiple streak types: login streaks (simplest), action streaks (e.g.,
-- applying to jobs daily), and contribution streaks (posting content). It also tracks
-- longest streaks as a point of pride and for milestone achievements. Freeze capabilities
-- (users can protect streaks with points) add monetization potential.
--
-- For user experience, the system sends "streak at risk" notifications when users miss a day,
-- and celebrates milestones with confetti and achievements. For analytics, streak data
-- correlates strongly with lifetime value - users with 30-day streaks have 5x higher LTV.
--
-- KPIs:
--   1. Users with active streaks (percentage of DAU)
--   2. Average streak length
--   3. Streak break rate (percentage ending daily)
--   4. Streak recovery rate (users restarting after break)
--   5. Correlation between streak length and retention
--   6. Milestone achievement rate (7, 30, 100 days)
--   7. Freeze usage (if implemented)
--   8. Streak-related notification engagement
--
-- Feature Reference: UX-GAM-31 to UX-GAM-45 (Streak System)
--
-- Normalization: 3NF - streaks per user, separate from other engagement data
--
-- High-Write Considerations:
--   - Updated daily for all active users (high write volume)
--   - Can be updated in batch at end of day
--   - Partition by user_id hash for distribution
------------------------------------------------------------------------------------------------
CREATE TABLE public.user_streaks (
    -- Primary identifiers
    streak_id             UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id               UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE UNIQUE,

    -- Streak types
    login_streak          INTEGER NOT NULL DEFAULT 0,
    longest_login_streak  INTEGER NOT NULL DEFAULT 0,
    last_login_date       DATE NOT NULL DEFAULT CURRENT_DATE,

    action_streak         INTEGER DEFAULT 0,                     -- e.g., job applications
    longest_action_streak INTEGER DEFAULT 0,
    last_action_date      DATE,

    contribution_streak   INTEGER DEFAULT 0,                     -- e.g., posts/comments
    longest_contribution_streak INTEGER DEFAULT 0,
    last_contribution_date DATE,

    -- Combined streak (any activity)
    current_streak        INTEGER NOT NULL DEFAULT 0,
    longest_streak        INTEGER NOT NULL DEFAULT 0,
    last_activity_date    DATE NOT NULL DEFAULT CURRENT_DATE,

    -- Streak milestones
    next_milestone        INTEGER,                                -- e.g., 7, 30, 100 days
    milestones_achieved   INTEGER[],                              -- Which milestones reached

    -- Streak protection/freezes
    freezes_available     INTEGER DEFAULT 0,
    freezes_used          INTEGER DEFAULT 0,
    next_freeze_available_date DATE,                             -- When next freeze becomes available

-- Streak history (rolling 90-day window)
activity_calendar     JSONB,                                 -- e.g., {"2025-03-01": true, "2025-03-02": true}

-- Streak risk indicators
days_since_last_activity INTEGER GENERATED ALWAYS AS (
    (CURRENT_DATE - last_activity_date)
) STORED,
streak_at_risk        BOOLEAN GENERATED ALWAYS AS (
    (CURRENT_DATE - last_activity_date) = 1
) STORED,
streak_broken         BOOLEAN GENERATED ALWAYS AS (
    (CURRENT_DATE - last_activity_date) > 1 AND current_streak = 0
) STORED,

-- Streak milestones tracking
milestone_7_achieved  BOOLEAN DEFAULT false,
milestone_30_achieved BOOLEAN DEFAULT false,
milestone_100_achieved BOOLEAN DEFAULT false,
milestone_365_achieved BOOLEAN DEFAULT false,

-- Gamification
streak_level          VARCHAR(20) GENERATED ALWAYS AS (
    CASE
        WHEN current_streak >= 365 THEN 'LEGENDARY'
        WHEN current_streak >= 100 THEN 'ELITE'
        WHEN current_streak >= 30 THEN 'DEDICATED'
        WHEN current_streak >= 7 THEN 'REGULAR'
        WHEN current_streak >= 3 THEN 'RISING'
        ELSE 'NEW'
    END
) STORED,

-- Notification tracking
last_reminder_sent_at TIMESTAMP WITH TIME ZONE,
reminder_sent_count   INTEGER DEFAULT 0,
last_milestone_celebrated_at TIMESTAMP WITH TIME ZONE,

-- Audit
created_at            TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
updated_at            TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);

COMMENT ON TABLE public.user_streaks IS 'Tracks consecutive day activity streaks for user retention gamification';
COMMENT ON COLUMN public.user_streaks.streak_id IS 'Primary key';
COMMENT ON COLUMN public.user_streaks.user_id IS 'User reference';
COMMENT ON COLUMN public.user_streaks.login_streak IS 'Consecutive days logged in';
COMMENT ON COLUMN public.user_streaks.longest_login_streak IS 'All-time longest login streak';
COMMENT ON COLUMN public.user_streaks.last_login_date IS 'Most recent login date';
COMMENT ON COLUMN public.user_streaks.action_streak IS 'Consecutive days with key actions';
COMMENT ON COLUMN public.user_streaks.longest_action_streak IS 'Longest action streak';
COMMENT ON COLUMN public.user_streaks.last_action_date IS 'Most recent action date';
COMMENT ON COLUMN public.user_streaks.contribution_streak IS 'Consecutive days with contributions';
COMMENT ON COLUMN public.user_streaks.longest_contribution_streak IS 'Longest contribution streak';
COMMENT ON COLUMN public.user_streaks.last_contribution_date IS 'Most recent contribution date';
COMMENT ON COLUMN public.user_streaks.current_streak IS 'Current combined activity streak';
COMMENT ON COLUMN public.user_streaks.longest_streak IS 'All-time longest combined streak';
COMMENT ON COLUMN public.user_streaks.last_activity_date IS 'Most recent any activity date';
COMMENT ON COLUMN public.user_streaks.next_milestone IS 'Next streak milestone target';
COMMENT ON COLUMN public.user_streaks.milestones_achieved IS 'Array of achieved milestones';
COMMENT ON COLUMN public.user_streaks.freezes_available IS 'Number of streak freezes available';
COMMENT ON COLUMN public.user_streaks.freezes_used IS 'Number of streak freezes used';
COMMENT ON COLUMN public.user_streaks.next_freeze_available_date IS 'When next freeze becomes available';
COMMENT ON COLUMN public.user_streaks.activity_calendar IS 'Rolling 90-day activity record';
COMMENT ON COLUMN public.user_streaks.days_since_last_activity IS 'Days since any activity';
COMMENT ON COLUMN public.user_streaks.streak_at_risk IS 'Flag if streak at risk (1 day missed)';
COMMENT ON COLUMN public.user_streaks.streak_broken IS 'Flag if streak broken (>1 day missed)';
COMMENT ON COLUMN public.user_streaks.milestone_7_achieved IS 'Whether 7-day milestone achieved';
COMMENT ON COLUMN public.user_streaks.milestone_30_achieved IS 'Whether 30-day milestone achieved';
COMMENT ON COLUMN public.user_streaks.milestone_100_achieved IS 'Whether 100-day milestone achieved';
COMMENT ON COLUMN public.user_streaks.milestone_365_achieved IS 'Whether 365-day milestone achieved';
COMMENT ON COLUMN public.user_streaks.streak_level IS 'Gamification level based on streak length';
COMMENT ON COLUMN public.user_streaks.last_reminder_sent_at IS 'When last streak reminder was sent';
COMMENT ON COLUMN public.user_streaks.reminder_sent_count IS 'Number of reminders sent';
COMMENT ON COLUMN public.user_streaks.last_milestone_celebrated_at IS 'When last milestone was celebrated';
COMMENT ON COLUMN public.user_streaks.created_at IS 'Record creation timestamp';
COMMENT ON COLUMN public.user_streaks.updated_at IS 'Last update timestamp';

-- Indexes for streak queries
CREATE INDEX idx_user_streaks_user_id ON public.user_streaks(user_id);
CREATE INDEX idx_user_streaks_current_streak ON public.user_streaks(current_streak DESC) WHERE current_streak > 0;
CREATE INDEX idx_user_streaks_at_risk ON public.user_streaks(user_id) WHERE streak_at_risk = true;
CREATE INDEX idx_user_streaks_last_activity ON public.user_streaks(last_activity_date) WHERE current_streak > 0;
CREATE INDEX idx_user_streaks_milestones ON public.user_streaks(milestone_100_achieved) WHERE milestone_100_achieved = true;

-- Trigger for updated_at
CREATE TRIGGER update_user_streaks_timestamp
BEFORE UPDATE ON public.user_streaks
FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Function to update streak daily
CREATE OR REPLACE FUNCTION public.update_user_streaks()
RETURNS VOID AS $$
DECLARE
v_user_record RECORD;
BEGIN
-- Update streaks for all active users
FOR v_user_record IN
    SELECT DISTINCT user_id
    FROM public.user_activities
    WHERE DATE(activity_timestamp) = CURRENT_DATE - INTERVAL '1 day'
LOOP
    VALUES (v_user_record.user_id)
    ON CONFLICT (user_id) DO UPDATE
    SET
        current_streak = CASE
            WHEN user_streaks.last_activity_date = CURRENT_DATE - INTERVAL '1 day'
            THEN user_streaks.current_streak + 1
            WHEN user_streaks.last_activity_date = CURRENT_DATE
            THEN user_streaks.current_streak
            ELSE 1
        END,
        longest_streak = GREATEST(
            user_streaks.longest_streak,
            CASE
                WHEN user_streaks.last_activity_date = CURRENT_DATE - INTERVAL '1 day'
                THEN user_streaks.current_streak + 1
                ELSE 1
            END
        ),
        last_activity_date = CURRENT_DATE,
        updated_at = CURRENT_TIMESTAMP;
END LOOP;
END;
$$ LANGUAGE plpgsql;

COMMENT ON FUNCTION public.update_user_streaks() IS 'Daily batch job to update user streaks';

-- Enable RLS
ALTER TABLE public.user_streaks ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY user_streaks_user_policy ON public.user_streaks
USING (user_id = current_user_id());

CREATE POLICY user_streaks_public_policy ON public.user_streaks
FOR SELECT USING (true);  -- Streak length can be public (gamification)

-- ======================================================================
-- MATERIALIZED VIEWS FOR ANALYTICS
-- ======================================================================

-- Materialized view for onboarding funnel analytics
CREATE MATERIALIZED VIEW public.mv_onboarding_funnel AS
WITH funnel_steps AS (
SELECT
    DATE_TRUNC('day', created_at) AS day,
    step_name,
    COUNT(*) AS started_count,
    COUNT(CASE WHEN status = 'COMPLETED' THEN 1 END) AS completed_count,
    AVG(time_spent_seconds) FILTER (WHERE status = 'COMPLETED') AS avg_time_seconds
FROM public.user_onboarding_progress
WHERE created_at > CURRENT_DATE - INTERVAL '90 days'
GROUP BY DATE_TRUNC('day', created_at), step_name
)
SELECT
day,
step_name,
started_count,
completed_count,
ROUND((completed_count::NUMERIC / NULLIF(started_count, 0)) * 100, 2) AS completion_rate,
avg_time_seconds,
LAG(completed_count) OVER (PARTITION BY step_name ORDER BY day) AS prev_day_completed,
ROUND(
    ((completed_count - LAG(completed_count) OVER (PARTITION BY step_name ORDER BY day))::NUMERIC /
    NULLIF(LAG(completed_count) OVER (PARTITION BY step_name ORDER BY day), 0)) * 100, 2
) AS day_over_day_change
FROM funnel_steps;

COMMENT ON MATERIALIZED VIEW public.mv_onboarding_funnel IS 'Daily onboarding funnel metrics for product analytics';

CREATE UNIQUE INDEX idx_mv_onboarding_funnel ON public.mv_onboarding_funnel(day, step_name);

-- Materialized view for engagement segmentation
CREATE MATERIALIZED VIEW public.mv_engagement_segments AS
SELECT
DATE_TRUNC('day', calculation_date) AS day,
engagement_segment,
COUNT(*) AS user_count,
AVG(overall_score) AS avg_score,
AVG(frequency_score) AS avg_frequency,
AVG(recency_score) AS avg_recency,
AVG(depth_score) AS avg_depth,
AVG(breadth_score) AS avg_breadth,
AVG(churn_probability) AS avg_churn_risk,
SUM(CASE WHEN risk_level IN ('HIGH', 'CRITICAL') THEN 1 ELSE 0 END) AS high_risk_count
FROM public.user_engagement_scores
WHERE calculation_date > CURRENT_DATE - INTERVAL '90 days'
GROUP BY DATE_TRUNC('day', calculation_date), engagement_segment;

COMMENT ON MATERIALIZED VIEW public.mv_engagement_segments IS 'Daily engagement segment analytics';

CREATE UNIQUE INDEX idx_mv_engagement_segments ON public.mv_engagement_segments(day, engagement_segment);

-- Materialized view for support performance
CREATE MATERIALIZED VIEW public.mv_support_performance AS
WITH ticket_metrics AS (
SELECT
    DATE_TRUNC('day', created_at) AS day,
    COUNT(*) AS tickets_created,
    COUNT(CASE WHEN first_response_at IS NOT NULL THEN 1 END) AS tickets_with_response,
    COUNT(CASE WHEN resolved_at IS NOT NULL THEN 1 END) AS tickets_resolved,
    AVG(EXTRACT(EPOCH FROM (first_response_at - created_at))/3600)::NUMERIC(10,2) AS avg_first_response_hours,
    AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/3600)::NUMERIC(10,2) AS avg_resolution_hours,
    COUNT(CASE WHEN sla_breached THEN 1 END) AS sla_breaches,
    AVG(csat_score) AS avg_csat
FROM public.support_tickets
WHERE created_at > CURRENT_DATE - INTERVAL '90 days'
GROUP BY DATE_TRUNC('day', created_at)
)
SELECT
day,
tickets_created,
tickets_resolved,
ROUND((tickets_with_response::NUMERIC / NULLIF(tickets_created, 0)) * 100, 2) AS response_rate,
ROUND((tickets_resolved::NUMERIC / NULLIF(tickets_created, 0)) * 100, 2) AS resolution_rate,
avg_first_response_hours,
avg_resolution_hours,
sla_breaches,
ROUND((sla_breaches::NUMERIC / NULLIF(tickets_created, 0)) * 100, 2) AS sla_breach_rate,
avg_csat,
SUM(tickets_created) OVER (ORDER BY day ROWS 6 PRECEDING) AS tickets_7day_avg
FROM ticket_metrics;

COMMENT ON MATERIALIZED VIEW public.mv_support_performance IS 'Daily support team performance metrics';

CREATE UNIQUE INDEX idx_mv_support_performance ON public.mv_support_performance(day);

-- Materialized view for knowledge base effectiveness
CREATE MATERIALIZED VIEW public.mv_kb_effectiveness AS
SELECT
DATE_TRUNC('day', a.published_at) AS day,
a.category_id,
COUNT(DISTINCT a.article_id) AS articles_published,
SUM(a.view_count) AS total_views,
AVG(a.helpful_score) FILTER (WHERE a.helpful_score IS NOT NULL) AS avg_helpful_score,
COUNT(DISTINCT f.feedback_id) AS feedback_count,
COUNT(DISTINCT t.ticket_id) FILTER (
    WHERE t.created_at > a.published_at
    AND t.category = 'TECHNICAL'
) AS related_tickets
FROM public.knowledge_base_articles a
LEFT JOIN public.article_feedback f ON a.article_id = f.article_id
LEFT JOIN public.support_tickets t ON t.category = 'TECHNICAL'
AND t.created_at BETWEEN a.published_at AND a.published_at + INTERVAL '7 days'
WHERE a.status = 'PUBLISHED'
GROUP BY DATE_TRUNC('day', a.published_at), a.category_id;

COMMENT ON MATERIALIZED VIEW public.mv_kb_effectiveness IS 'Knowledge base effectiveness metrics';

CREATE INDEX idx_mv_kb_effectiveness_day ON public.mv_kb_effectiveness(day);

