------------------------------------------------------------------------------------------------
-- Procedure: record_user_activity_and_update_streak
-- Description: Records user activity and atomically updates streak counters
-- Business Case: Ensures streak updates are consistent with activity logging
-- Feature Reference: UX-GAM-40
------------------------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE public.record_user_activity_and_update_streak(
p_user_id UUID,
p_activity_type VARCHAR(50),
p_activity_metadata JSONB DEFAULT '{}'::JSONB
)
LANGUAGE plpgsql
AS $$
DECLARE
v_today DATE := CURRENT_DATE;
v_yesterday DATE := CURRENT_DATE - 1;
v_last_activity DATE;
v_streak_exists BOOLEAN;
v_freeze_used BOOLEAN := false;
BEGIN
-- Input validation
IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id cannot be null';
END IF;

IF p_activity_type IS NULL OR p_activity_type = '' THEN
    RAISE EXCEPTION 'activity_type cannot be null or empty';
END IF;

-- Start transaction
BEGIN
    -- Insert activity log
        user_id,
        activity_type,
        activity_timestamp,
        metadata,
        session_id
    ) VALUES (
        p_user_id,
        p_activity_type,
        CURRENT_TIMESTAMP,
        p_activity_metadata,
        (p_activity_metadata->>'session_id')::UUID
    );

    -- Check if streak record exists
    SELECT EXISTS(
        SELECT 1 FROM public.user_streaks WHERE user_id = p_user_id
    ) INTO v_streak_exists;

    IF v_streak_exists THEN
        -- Get last activity date
        SELECT last_activity_date INTO v_last_activity
        FROM public.user_streaks
        WHERE user_id = p_user_id
        FOR UPDATE;  -- Lock row to prevent concurrent updates

        -- Update streak based on last activity
        IF v_last_activity = v_today THEN
            -- Already active today, no streak increment
            UPDATE public.user_streaks
            SET
                updated_at = CURRENT_TIMESTAMP
            WHERE user_id = p_user_id;

        ELSIF v_last_activity = v_yesterday THEN
            -- Consecutive day, increment streak
            UPDATE public.user_streaks
            SET
                current_streak = current_streak + 1,
                longest_streak = GREATEST(longest_streak, current_streak + 1),
                last_activity_date = v_today,
                updated_at = CURRENT_TIMESTAMP,
                -- Check milestones
                milestone_7_achieved = CASE WHEN current_streak + 1 >= 7 THEN true ELSE milestone_7_achieved END,
                milestone_30_achieved = CASE WHEN current_streak + 1 >= 30 THEN true ELSE milestone_30_achieved END,
                milestone_100_achieved = CASE WHEN current_streak + 1 >= 100 THEN true ELSE milestone_100_achieved END,
                milestone_365_achieved = CASE WHEN current_streak + 1 >= 365 THEN true ELSE milestone_365_achieved END
            WHERE user_id = p_user_id;

            -- Update activity calendar
            UPDATE public.user_streaks
            SET activity_calendar =
                COALESCE(activity_calendar, '{}'::JSONB) ||
                jsonb_build_object(v_today::TEXT, true)
            WHERE user_id = p_user_id;

        ELSIF v_last_activity < v_yesterday THEN
            -- Streak broken, check for freeze
            IF EXISTS (
                SELECT 1 FROM public.user_streaks
                WHERE user_id = p_user_id AND freezes_available > 0
            ) THEN
                -- Use a freeze
                UPDATE public.user_streaks
                SET
                    freezes_available = freezes_available - 1,
                    freezes_used = freezes_used + 1,
                    last_activity_date = v_today,
                    updated_at = CURRENT_TIMESTAMP
                WHERE user_id = p_user_id;

                v_freeze_used := true;
            ELSE
                -- Reset streak
                UPDATE public.user_streaks
                SET
                    current_streak = 1,
                    last_activity_date = v_today,
                    updated_at = CURRENT_TIMESTAMP,
                    activity_calendar = jsonb_build_object(v_today::TEXT, true)
                WHERE user_id = p_user_id;
            END IF;
        END IF;
    ELSE
        -- First activity, create streak record
            user_id,
            current_streak,
            longest_streak,
            last_activity_date,
            login_streak,
            longest_login_streak,
            last_login_date,
            activity_calendar
        ) VALUES (
            p_user_id,
            1,
            1,
            v_today,
            CASE WHEN p_activity_type = 'login' THEN 1 ELSE 0 END,
            CASE WHEN p_activity_type = 'login' THEN 1 ELSE 0 END,
            CASE WHEN p_activity_type = 'login' THEN v_today ELSE NULL END,
            jsonb_build_object(v_today::TEXT, true)
        );
    END IF;

    -- Log streak event for analytics
        user_id,
        activity_type,
        activity_timestamp,
        metadata
    ) VALUES (
        p_user_id,
        'streak_update',
        CURRENT_TIMESTAMP,
        jsonb_build_object(
            'previous_streak', v_last_activity,
            'freeze_used', v_freeze_used,
            'current_streak', (SELECT current_streak FROM public.user_streaks WHERE user_id = p_user_id)
        )
    );

    -- Commit transaction
    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        -- Rollback transaction
        ROLLBACK;
        RAISE;
END;
END;
$$;

COMMENT ON PROCEDURE public.record_user_activity_and_update_streak IS 'Atomically records user activity and updates streak counters';

------------------------------------------------------------------------------------------------
-- Procedure: process_survey_responses
-- Description: Processes survey responses and updates aggregate statistics
-- Business Case: Ensures survey analytics are updated in real-time
-- Feature Reference: UX-SRV-15
------------------------------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE public.process_survey_responses(
p_survey_id UUID,
p_user_id UUID,
p_score SMALLINT,
p_answer_text TEXT DEFAULT NULL,
p_follow_up_answer TEXT DEFAULT NULL,
p_channel public.notification_channel DEFAULT 'IN_APP'
)
LANGUAGE plpgsql
AS $$
DECLARE
v_survey_record RECORD;
v_follow_up_threshold SMALLINT;
BEGIN
-- Input validation
IF p_survey_id IS NULL THEN
    RAISE EXCEPTION 'survey_id cannot be null';
END IF;

IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'user_id cannot be null';
END IF;

IF p_score IS NULL OR p_score < 0 OR p_score > 10 THEN
    RAISE EXCEPTION 'score must be between 0 and 10';
END IF;

-- Get survey details
SELECT * INTO v_survey_record
FROM public.user_surveys
WHERE survey_id = p_survey_id
FOR UPDATE;

IF NOT FOUND THEN
    RAISE EXCEPTION 'Survey with ID % not found', p_survey_id;
END IF;

-- Check if user already responded
IF EXISTS (
    SELECT 1 FROM public.survey_responses
    WHERE survey_id = p_survey_id AND user_id = p_user_id
) THEN
    RAISE EXCEPTION 'User has already responded to this survey';
END IF;

-- Insert response
    survey_id,
    user_id,
    score,
    answer_text,
    follow_up_answer,
    response_channel,
    survey_sent_at,
    responded_at
) VALUES (
    p_survey_id,
    p_user_id,
    p_score,
    p_answer_text,
    p_follow_up_answer,
    p_channel,
    v_survey_record.scheduled_start_at,
    CURRENT_TIMESTAMP
);

-- Update survey aggregates
UPDATE public.user_surveys
SET
    actual_responses = actual_responses + 1,
    average_score = (
        (COALESCE(average_score, 0) * actual_responses + p_score) /
        (actual_responses + 1)
    ),
    score_distribution = jsonb_set(
        COALESCE(score_distribution, '{}'::JSONB),
        ARRAY[p_score::TEXT],
        to_jsonb(COALESCE((score_distribution->>p_score::TEXT)::INTEGER, 0) + 1)
    ),
    nps_segments = CASE
        WHEN v_survey_record.survey_type = 'NPS' THEN
            jsonb_build_object(
                'promoters', (
                    SELECT COUNT(*) FROM public.survey_responses
                    WHERE survey_id = p_survey_id AND score >= 9
                ),
                'passives', (
                    SELECT COUNT(*) FROM public.survey_responses
                    WHERE survey_id = p_survey_id AND score BETWEEN 7 AND 8
                ),
                'detractors', (
                    SELECT COUNT(*) FROM public.survey_responses
                    WHERE survey_id = p_survey_id AND score <= 6
                )
            )
        ELSE nps_segments
    END,
    updated_at = CURRENT_TIMESTAMP
WHERE survey_id = p_survey_id;

-- Check if follow-up needed
IF v_survey_record.follow_up_question IS NOT NULL
   AND v_survey_record.follow_up_threshold IS NOT NULL
   AND p_score <= v_survey_record.follow_up_threshold THEN

    -- Create follow-up task for support team
        user_id,
        subject,
        description,
        category,
        priority,
        source,
        internal_notes
    ) VALUES (
        p_user_id,
        'Follow-up on survey response',
        format('User responded with score %s to survey "%s". Follow-up question: %s. Answer: %s',
               p_score, v_survey_record.survey_name,
               v_survey_record.follow_up_question, p_follow_up_answer),
        'FEEDBACK',
        'MEDIUM',
        'web',
        'Auto-generated from survey response'
    );
END IF;

-- Log the response for analytics
    user_id,
    activity_type,
    activity_timestamp,
    metadata
) VALUES (
    p_user_id,
    'survey_response',
    CURRENT_TIMESTAMP,
    jsonb_build_object(
        'survey_id', p_survey_id,
        'survey_type', v_survey_record.survey_type,
        'score', p_score
    )
);

EXCEPTION
WHEN OTHERS THEN
    RAISE;
END;
$$;

COMMENT ON PROCEDURE public.process_survey_responses IS 'Processes survey responses and updates aggregate statistics';

