-- FUNCTIONS FOR BUSINESS LOGIC
-- ======================================================================

------------------------------------------------------------------------------------------------
-- Function: get_user_engagement_summary
-- Description: Returns comprehensive engagement summary for a user
-- Business Case: Powers user profile dashboards and analytics
-- Feature Reference: UX-ENG-20
------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_user_engagement_summary(
p_user_id UUID
)
RETURNS TABLE (
overall_score NUMERIC(5,2),
engagement_segment public.engagement_segment,
current_streak INTEGER,
longest_streak INTEGER,
achievements_count INTEGER,
recent_achievements JSONB,
notifications_pending INTEGER,
unread_notifications INTEGER,
days_active_last_30 INTEGER,
percentile_rank INTEGER
) AS $$
DECLARE
v_user_exists BOOLEAN;
BEGIN
-- Check if user exists
SELECT EXISTS(SELECT 1 FROM public.users WHERE user_id = p_user_id) INTO v_user_exists;

IF NOT v_user_exists THEN
    RAISE EXCEPTION 'User with ID % does not exist', p_user_id;
END IF;

RETURN QUERY
WITH user_stats AS (
    SELECT
        es.overall_score,
        es.engagement_segment,
        es.days_active_last_30,
        PERCENT_RANK() OVER (ORDER BY es.overall_score) AS percentile
    FROM public.user_engagement_scores es
    WHERE es.user_id = p_user_id
    ORDER BY es.calculation_date DESC
    LIMIT 1
),
streak_stats AS (
    SELECT
        current_streak,
        longest_streak
    FROM public.user_streaks
    WHERE user_id = p_user_id
),
achievement_stats AS (
    SELECT
        COUNT(*) AS total_achievements,
        JSONB_AGG(
            jsonb_build_object(
                'name', ad.name,
                'description', ad.description,
                'earned_at', ua.earned_at,
                'badge_url', ad.badge_image_url
            )
            ORDER BY ua.earned_at DESC
            LIMIT 5
        ) AS recent
    FROM public.user_achievements ua
    JOIN public.achievement_definitions ad ON ua.achievement_id = ad.achievement_id
    WHERE ua.user_id = p_user_id AND ua.is_earned = true
),
notification_stats AS (
    SELECT
        COUNT(*) FILTER (WHERE status = 'PENDING') AS pending_count,
        COUNT(*) FILTER (WHERE is_read = false) AS unread_count
    FROM public.user_notifications
    WHERE user_id = p_user_id
)
SELECT
    COALESCE(us.overall_score, 0),
    COALESCE(us.engagement_segment, 'NEW'::public.engagement_segment),
    COALESCE(ss.current_streak, 0),
    COALESCE(ss.longest_streak, 0),
    COALESCE(astats.total_achievements, 0),
    COALESCE(astats.recent, '[]'::JSONB),
    COALESCE(nstats.pending_count, 0),
    COALESCE(nstats.unread_count, 0),
    COALESCE(us.days_active_last_30, 0),
    COALESCE((us.percentile * 100)::INTEGER, 0)
FROM (VALUES (1)) t
LEFT JOIN user_stats us ON true
LEFT JOIN streak_stats ss ON true
LEFT JOIN achievement_stats astats ON true
LEFT JOIN notification_stats nstats ON true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.get_user_engagement_summary(UUID) IS 'Returns comprehensive engagement summary for a user';

------------------------------------------------------------------------------------------------
-- Function: suggest_knowledge_base_articles
-- Description: Suggests relevant knowledge base articles based on user context
-- Business Case: Powers contextual help and self-service recommendations
-- Feature Reference: UX-KB-20
------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.suggest_knowledge_base_articles(
p_user_id UUID,
p_context VARCHAR(50) DEFAULT NULL,  -- e.g., 'dashboard', 'job_search'
p_limit INTEGER DEFAULT 5
)
RETURNS TABLE (
article_id UUID,
title VARCHAR(255),
excerpt VARCHAR(500),
article_type public.article_type,
relevance_score NUMERIC,
helpful_score NUMERIC(5,2),
view_count INTEGER
) AS $$
DECLARE
v_user_tier VARCHAR(50);
v_recent_issues TEXT[];
BEGIN
-- Get user's subscription tier
SELECT plan_id::TEXT INTO v_user_tier
FROM public.subscriptions
WHERE user_id = p_user_id AND status = 'ACTIVE'
LIMIT 1;

-- Get user's recent support issues (last 30 days)
SELECT ARRAY_AGG(DISTINCT category::TEXT)
INTO v_recent_issues
FROM public.support_tickets
WHERE user_id = p_user_id
  AND created_at > CURRENT_DATE - INTERVAL '30 days'
  AND category IS NOT NULL;

RETURN QUERY
WITH article_scores AS (
    SELECT
        a.article_id,
        a.title,
        a.excerpt,
        a.article_type,
        a.view_count,
        a.helpful_score,
        -- Calculate relevance score
        (
            CASE
                WHEN a.article_type::TEXT = ANY(COALESCE(v_recent_issues, ARRAY[]::TEXT[]))
                THEN 10
                ELSE 0
            END +
            CASE
                WHEN p_context IS NOT NULL AND a.tags && ARRAY[p_context]
                THEN 5
                ELSE 0
            END +
            (COALESCE(a.helpful_score, 50) / 10) +
            LEAST(LOG(COALESCE(a.view_count, 1) + 1) * 2, 10)
        ) AS score
    FROM public.knowledge_base_articles a
    WHERE a.status = 'PUBLISHED'
      AND (
          a.visibility = 'PUBLIC' OR
          (a.visibility = 'AUTHENTICATED' AND p_user_id IS NOT NULL) OR
          (a.visibility = 'PREMIUM' AND v_user_tier IS NOT NULL)
      )
)
SELECT
    ascores.article_id,
    ascores.title,
    ascores.excerpt,
    ascores.article_type,
    ROUND(ascores.score, 2) AS relevance_score,
    ascores.helpful_score,
    ascores.view_count
FROM article_scores ascores
ORDER BY ascores.score DESC
LIMIT p_limit;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION public.suggest_knowledge_base_articles(UUID, VARCHAR, INTEGER) IS 'Suggests relevant knowledge base articles based on user context';

-- ======================================================================
-- TRIGGERS FOR AUTOMATED WORKFLOWS
-- ======================================================================

------------------------------------------------------------------------------------------------
-- Trigger: notify_on_ticket_assignment
-- Description: Sends notification when a support ticket is assigned to an agent
-- Business Case: Ensures agents know about new assignments immediately
-- Feature Reference: UX-SUP-25
------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.notify_on_ticket_assignment()
RETURNS TRIGGER AS $$
BEGIN
IF NEW.assigned_to IS NOT NULL AND (OLD.assigned_to IS NULL OR OLD.assigned_to != NEW.assigned_to) THEN
    -- Create notification for assigned agent
        user_id,
        notification_type,
        content,
        related_object_type,
        related_object_id
    ) VALUES (
        NEW.assigned_to,
        'ticket_assigned',
        format('Ticket #%s has been assigned to you', NEW.ticket_number),
        'support_ticket',
        NEW.ticket_id
    );

    -- Log assignment in ticket comments
        ticket_id,
        author_id,
        author_type,
        comment_text,
        is_public,
        is_status_change,
        previous_status,
        new_status
    ) VALUES (
        NEW.ticket_id,
        NEW.assigned_by,
        'system',
        format('Ticket assigned to agent', NEW.ticket_number),
        false,
        true,
        OLD.status,
        NEW.status
    );
END IF;

RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_notify_on_ticket_assignment
AFTER UPDATE OF assigned_to ON public.support_tickets
FOR EACH ROW
WHEN (NEW.assigned_to IS NOT NULL)
EXECUTE FUNCTION public.notify_on_ticket_assignment();

------------------------------------------------------------------------------------------------
-- Trigger: update_streak_on_milestone
-- Description: Creates achievement when user reaches streak milestone
-- Business Case: Automatically rewards users for engagement milestones
-- Feature Reference: UX-GAM-35
------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.update_streak_on_milestone()
RETURNS TRIGGER AS $$
DECLARE
v_achievement_id UUID;
BEGIN
-- Check for milestone achievements
IF NEW.current_streak >= 7 AND (OLD.current_streak < 7 OR OLD IS NULL) THEN
    -- Get 7-day achievement ID
    SELECT achievement_id INTO v_achievement_id
    FROM public.achievement_definitions
    WHERE achievement_code = 'STREAK_7_DAYS';

    IF v_achievement_id IS NOT NULL THEN
            user_id,
            achievement_id,
            earned_at,
            is_earned,
            earned_metadata
        ) VALUES (
            NEW.user_id,
            v_achievement_id,
            CURRENT_TIMESTAMP,
            true,
            jsonb_build_object('streak_length', NEW.current_streak)
        ) ON CONFLICT (user_id, achievement_id, tier_level) DO NOTHING;
    END IF;
END IF;

IF NEW.current_streak >= 30 AND (OLD.current_streak < 30 OR OLD IS NULL) THEN
    -- Get 30-day achievement ID
    SELECT achievement_id INTO v_achievement_id
    FROM public.achievement_definitions
    WHERE achievement_code = 'STREAK_30_DAYS';

    IF v_achievement_id IS NOT NULL THEN
            user_id,
            achievement_id,
            earned_at,
            is_earned,
            earned_metadata
        ) VALUES (
            NEW.user_id,
            v_achievement_id,
            CURRENT_TIMESTAMP,
            true,
            jsonb_build_object('streak_length', NEW.current_streak)
        ) ON CONFLICT (user_id, achievement_id, tier_level) DO NOTHING;
    END IF;
END IF;

IF NEW.current_streak >= 100 AND (OLD.current_streak < 100 OR OLD IS NULL) THEN
    -- Get 100-day achievement ID
    SELECT achievement_id INTO v_achievement_id
    FROM public.achievement_definitions
    WHERE achievement_code = 'STREAK_100_DAYS';

    IF v_achievement_id IS NOT NULL THEN
            user_id,
            achievement_id,
            earned_at,
            is_earned,
            earned_metadata
        ) VALUES (
            NEW.user_id,
            v_achievement_id,
            CURRENT_TIMESTAMP,
            true,
            jsonb_build_object('streak_length', NEW.current_streak)
        ) ON CONFLICT (user_id, achievement_id, tier_level) DO NOTHING;
    END IF;
END IF;

RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_update_streak_on_milestone
AFTER UPDATE OF current_streak ON public.user_streaks
FOR EACH ROW
WHEN (NEW.current_streak > COALESCE(OLD.current_streak, 0))
EXECUTE FUNCTION public.update_streak_on_milestone();

