-- Insert default notification templates
template_name,
notification_type,
channel,
subject,
body_template,
language_code,
is_active,
created_by,
updated_by
) VALUES
(
    'welcome_email',
    'welcome',
    'EMAIL',
    'Welcome to Professional Network, {{user_name}}!',
    'Hi {{user_name}},\n\nWelcome to Professional Network! We''re excited to have you join our community of professionals.\n\nGet started by completing your profile: {{profile_link}}\n\nBest regards,\nThe Professional Network Team',
    'en',
    true,
    (SELECT user_id FROM public.users LIMIT 1),
    (SELECT user_id FROM public.users LIMIT 1)
),
(
    'streak_at_risk',
    'streak_reminder',
    'EMAIL',
    'Don''t break your {{streak_length}}-day streak!',
    'Hi {{user_name}},\n\nYou''re just one day away from breaking your {{streak_length}}-day streak! Log in today to keep it alive.\n\nKeep up the great work!\nThe Professional Network Team',
    'en',
