-- ======================================================================
-- SCHEDULED JOBS (using pg_cron if available)
-- ======================================================================

-- Refresh materialized views daily
DO $$
BEGIN
IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    -- Refresh onboarding funnel at 1 AM
    PERFORM cron.schedule(
        'refresh-onboarding-funnel',
        '0 1 * * *',
        $$REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_onboarding_funnel$$
    );

    -- Refresh engagement segments at 2 AM
    PERFORM cron.schedule(
        'refresh-engagement-segments',
        '0 2 * * *',
        $$REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_engagement_segments$$
    );

    -- Refresh support performance at 3 AM
    PERFORM cron.schedule(
        'refresh-support-performance',
        '0 3 * * *',
        $$REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_support_performance$$
    );

    -- Refresh KB effectiveness at 4 AM
    PERFORM cron.schedule(
        'refresh-kb-effectiveness',
        '0 4 * * *',
        $$REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_kb_effectiveness$$
    );

    -- Update user streaks daily at 11:59 PM
    PERFORM cron.schedule(
        'update-user-streaks',
        '59 23 * * *',
        $$SELECT public.update_user_streaks()$$
    );
END IF;
EXCEPTION
WHEN OTHERS THEN
    RAISE NOTICE 'pg_cron extension not available. Scheduled jobs will not be created.';
END $$;

