-------------------------------------------------------------------------------
CREATE TYPE public.api_key_status AS ENUM (
    'ACTIVE',                    -- Can be used for authentication
    'EXPIRED',                   -- Past expiration date
    'REVOKED',                   -- Manually revoked
    'DISABLED',                  -- Temporarily disabled
    'ROTATED',                   -- Replaced by new key
    'COMPROMISED',               -- Marked as compromised
    'PENDING_ACTIVATION'         -- Created but not yet usable
);
COMMENT ON TYPE public.api_key_status IS 'Complete lifecycle states for API credentials';

