-- RLS Policies
CREATE POLICY webhook_subscriptions_owner_policy ON public.webhook_subscriptions
    USING (owner_id = current_user_id() OR
           EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.role_id
                   WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'integration_manager')));

CREATE POLICY webhook_subscriptions_company_policy ON public.webhook_subscriptions
    FOR ALL USING (owner_type = 'COMPANY' AND
                   EXISTS (SELECT 1 FROM public.company_admins ca
                           WHERE ca.company_id = organization_id AND ca.user_id = current_user_id()));

-- =============================================================================
-- TABLE 72: webhook_attempts
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 72
-- Table Name: webhook_attempts
-- Description: Detailed log of every webhook delivery attempt, including request/
--              response data, timing, and error information. Enables debugging,
--              monitoring, and replay capabilities.
--
-- Business Case: Reliable integration with external systems requires comprehensive
--                visibility into delivery attempts. This table serves as the
--                audit trail for all webhook traffic, capturing every request
--                sent, response received, and any errors encountered. It enables
--                support teams to debug integration issues, partners to verify
--                delivery, and the platform to calculate SLAs. The design supports
--                high-volume ingestion (partitioned by date) while retaining
--                detailed payload information for forensic analysis. Features
--                include: payload compression for storage efficiency, request/
--                response headers for debugging, timing metrics for performance
--                analysis, and correlation IDs for distributed tracing. This
--                data feeds into monitoring dashboards, alerting systems, and
--                capacity planning. With proper indexing, it supports both
--                operational queries (recent attempts) and analytical queries
--                (trend analysis, partner reliability scoring). The table also
--                enables replay capabilities by storing the original event payload
--                that failed, allowing manual or automated retry mechanisms.
--
-- Key Performance Indicators (KPIs):
--   1. Delivery Success Rate by Endpoint: Success percentage per target URL
--   2. Response Time Percentiles: p50/p95/p99 latency per endpoint
--   3. Error Distribution: Breakdown of error types (timeout, 4xx, 5xx)
--   4. Retry Effectiveness: Success rate of retry attempts vs. first attempts
--   5. Payload Size Impact: Correlation between payload size and success rate
--   6. Peak Delivery Volume: Maximum deliveries per second/minute/hour
--   7. Storage Growth Rate: Daily/Weekly/Monthly storage consumption
--   8. Correlation Success Rate: Percentage of attempts with valid correlation IDs
--
-- Feature Reference: INT-WH-05 (Webhook Delivery Logging)
-- Requirements Traceability: R-WEBHOOK-016 through R-WEBHOOK-025
-------------------------------------------------------------------------------
CREATE TABLE public.webhook_attempts (
    -- Primary identifier
    attempt_id UUID DEFAULT gen_random_uuid() NOT NULL,
    subscription_id UUID NOT NULL REFERENCES public.webhook_subscriptions(subscription_id) ON DELETE CASCADE,

    -- Event identification
    event_id UUID NOT NULL, -- Unique event identifier for deduplication
    event_type public.webhook_event_type NOT NULL,
    event_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Attempt tracking
    attempt_number INTEGER NOT NULL CHECK (attempt_number > 0),
    is_retry BOOLEAN DEFAULT false,
    triggered_by VARCHAR(50) NOT NULL CHECK (triggered_by IN ('SYSTEM', 'MANUAL', 'SCHEDULED')),

    -- Request data
    request_url TEXT NOT NULL,
    request_method VARCHAR(10) NOT NULL,
    request_headers JSONB,
    request_payload TEXT, -- Compressed if large
    request_payload_size_bytes INTEGER,
    request_payload_compressed BOOLEAN DEFAULT false,
    request_payload_hash VARCHAR(64), -- SHA-256 for integrity

    -- Response data
    response_status_code INTEGER,
    response_headers JSONB,
    response_body TEXT, -- Truncated if large
    response_body_size_bytes INTEGER,
    response_time_ms INTEGER,

    -- Timing
    queued_at TIMESTAMP WITH TIME ZONE NOT NULL,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    duration_ms INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (completed_at - started_at)) * 1000
    ) STORED,

    -- Result
    status public.webhook_delivery_status NOT NULL,
    status_reason TEXT,
    error_code VARCHAR(100),
    error_details JSONB,

    -- Network information
    source_ip INET,
    destination_ip INET,
    tls_version VARCHAR(20),
    tls_cipher VARCHAR(100),

    -- Correlation
    correlation_id UUID,
    trace_id VARCHAR(100), -- For distributed tracing
    span_id VARCHAR(100),

    -- Retry information
    retry_count INTEGER DEFAULT 0,
    next_retry_at TIMESTAMP WITH TIME ZONE,
    retry_decision_reason TEXT,

    -- Metrics
    bytes_sent INTEGER,
    bytes_received INTEGER,
    connection_time_ms INTEGER,
    ttfb_ms INTEGER, -- Time to first byte
    dns_lookup_time_ms INTEGER,
    ssl_handshake_time_ms INTEGER,

    -- Client information
    user_agent TEXT,
    referer TEXT,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_timing CHECK (
        (started_at IS NULL) OR (started_at >= queued_at)
    ),
    CONSTRAINT valid_completion CHECK (
        (completed_at IS NULL) OR
        (started_at IS NOT NULL AND completed_at >= started_at)
    ),
    CONSTRAINT valid_response CHECK (
        (response_status_code IS NOT NULL) OR
        (status IN ('FAILED', 'TIMED_OUT', 'CANCELLED'))
    ),

    PRIMARY KEY (attempt_id, queued_at)
) PARTITION BY RANGE (queued_at);

COMMENT ON TABLE public.webhook_attempts IS 'Detailed log of every webhook delivery attempt with full request/response data';
COMMENT ON COLUMN public.webhook_attempts.attempt_id IS 'Primary key for attempt';
COMMENT ON COLUMN public.webhook_attempts.subscription_id IS 'Reference to webhook subscription';
COMMENT ON COLUMN public.webhook_attempts.event_id IS 'Unique event identifier for deduplication';
COMMENT ON COLUMN public.webhook_attempts.event_type IS 'Type of event being delivered';
COMMENT ON COLUMN public.webhook_attempts.event_timestamp IS 'When the event originally occurred';
COMMENT ON COLUMN public.webhook_attempts.attempt_number IS 'Attempt number (1 = first)';
COMMENT ON COLUMN public.webhook_attempts.is_retry IS 'Whether this is a retry attempt';
COMMENT ON COLUMN public.webhook_attempts.triggered_by IS 'What triggered this attempt';
COMMENT ON COLUMN public.webhook_attempts.request_url IS 'Full URL requested';
COMMENT ON COLUMN public.webhook_attempts.request_method IS 'HTTP method used';
COMMENT ON COLUMN public.webhook_attempts.request_headers IS 'HTTP headers sent';
COMMENT ON COLUMN public.webhook_attempts.request_payload IS 'Request body (compressed if needed)';
COMMENT ON COLUMN public.webhook_attempts.request_payload_size_bytes IS 'Size of payload in bytes';
COMMENT ON COLUMN public.webhook_attempts.request_payload_compressed IS 'Whether payload is compressed';
COMMENT ON COLUMN public.webhook_attempts.request_payload_hash IS 'SHA-256 hash of payload for integrity';
COMMENT ON COLUMN public.webhook_attempts.response_status_code IS 'HTTP status code received';
COMMENT ON COLUMN public.webhook_attempts.response_headers IS 'Response headers received';
COMMENT ON COLUMN public.webhook_attempts.response_body IS 'Response body (truncated if large)';
COMMENT ON COLUMN public.webhook_attempts.response_body_size_bytes IS 'Size of response body';
COMMENT ON COLUMN public.webhook_attempts.response_time_ms IS 'Total response time';
COMMENT ON COLUMN public.webhook_attempts.queued_at IS 'When attempt was queued';
COMMENT ON COLUMN public.webhook_attempts.started_at IS 'When attempt started';
COMMENT ON COLUMN public.webhook_attempts.completed_at IS 'When attempt completed';
COMMENT ON COLUMN public.webhook_attempts.duration_ms IS 'Generated duration in milliseconds';
COMMENT ON COLUMN public.webhook_attempts.status IS 'Delivery status';
COMMENT ON COLUMN public.webhook_attempts.status_reason IS 'Human-readable status reason';
COMMENT ON COLUMN public.webhook_attempts.error_code IS 'Categorized error code';
COMMENT ON COLUMN public.webhook_attempts.error_details IS 'Detailed error information';
COMMENT ON COLUMN public.webhook_attempts.source_ip IS 'Source IP address of request';
COMMENT ON COLUMN public.webhook_attempts.destination_ip IS 'Destination IP resolved';
COMMENT ON COLUMN public.webhook_attempts.tls_version IS 'TLS version used';
COMMENT ON COLUMN public.webhook_attempts.tls_cipher IS 'TLS cipher suite used';
COMMENT ON COLUMN public.webhook_attempts.correlation_id IS 'Correlation ID for request chains';
COMMENT ON COLUMN public.webhook_attempts.trace_id IS 'Distributed tracing trace ID';
COMMENT ON COLUMN public.webhook_attempts.span_id IS 'Distributed tracing span ID';
COMMENT ON COLUMN public.webhook_attempts.retry_count IS 'Number of retries so far';
COMMENT ON COLUMN public.webhook_attempts.next_retry_at IS 'When next retry is scheduled';
COMMENT ON COLUMN public.webhook_attempts.retry_decision_reason IS 'Why retry was/wasn''t attempted';
COMMENT ON COLUMN public.webhook_attempts.bytes_sent IS 'Bytes sent in request';
COMMENT ON COLUMN public.webhook_attempts.bytes_received IS 'Bytes received in response';
COMMENT ON COLUMN public.webhook_attempts.connection_time_ms IS 'Time to establish connection';
COMMENT ON COLUMN public.webhook_attempts.ttfb_ms IS 'Time to first byte';
COMMENT ON COLUMN public.webhook_attempts.dns_lookup_time_ms IS 'DNS lookup time';
COMMENT ON COLUMN public.webhook_attempts.ssl_handshake_time_ms IS 'SSL/TLS handshake time';
COMMENT ON COLUMN public.webhook_attempts.user_agent IS 'User agent of client';
COMMENT ON COLUMN public.webhook_attempts.referer IS 'Referer header';
COMMENT ON COLUMN public.webhook_attempts.created_at IS 'Timestamp of record creation';

-- Create partition management function
CREATE OR REPLACE FUNCTION public.create_webhook_attempts_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'webhook_attempts_' || to_char(partition_date, 'YYYY_MM');
    start_date := to_char(partition_date, 'YYYY-MM-DD');
    end_date := to_char(partition_date + INTERVAL '1 month', 'YYYY-MM-DD');

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.webhook_attempts
        FOR VALUES FROM (%L) TO (%L)
    ', partition_name, start_date, end_date);

    -- Create indexes on the partition
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I ON public.%I (subscription_id, status, started_at)
    ', 'idx_' || partition_name || '_sub_status', partition_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I ON public.%I (event_id)
    ', 'idx_' || partition_name || '_event', partition_name);
END;
$$ LANGUAGE plpgsql;

-- Create initial partitions
SELECT public.create_webhook_attempts_partition(DATE_TRUNC('month', CURRENT_DATE)::DATE);
SELECT public.create_webhook_attempts_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month')::DATE);
SELECT public.create_webhook_attempts_partition((DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '2 months')::DATE);

-- Global indexes (applied to all partitions via parent table)
CREATE INDEX idx_webhook_attempts_subscription ON public.webhook_attempts(subscription_id, queued_at DESC);
CREATE INDEX idx_webhook_attempts_status ON public.webhook_attempts(status, queued_at DESC) WHERE status IN ('PENDING', 'RETRYING');
CREATE INDEX idx_webhook_attempts_event ON public.webhook_attempts(event_id, subscription_id);
CREATE INDEX idx_webhook_attempts_correlation ON public.webhook_attempts(correlation_id) WHERE correlation_id IS NOT NULL;

-- Enable RLS
ALTER TABLE public.webhook_attempts ENABLE ROW LEVEL SECURITY;

-- RLS Policies (inherit from subscription)
CREATE POLICY webhook_attempts_access_policy ON public.webhook_attempts
    USING (EXISTS (
        SELECT 1 FROM public.webhook_subscriptions ws
        WHERE ws.subscription_id = webhook_attempts.subscription_id
        AND (ws.owner_id = current_user_id() OR
             EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.role_id
                     WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'integration_manager')))
    ));

-- =============================================================================
-- TABLE 73: api_keys
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 73
-- Table Name: api_keys
-- Description: Manages API credentials for programmatic access to the platform.
--              Stores hashed keys, permissions, rate limits, and usage quotas
--              for third-party applications and integrations.
--
-- Business Case: Secure, auditable API access is fundamental to platform
--                extensibility. This table implements enterprise-grade API key
--                management with features including: key hashing (never store
--                raw keys), granular permission sets (read/write per resource),
--                rate limiting per key, expiration policies, and automatic
--                rotation workflows. The design supports multiple key types:
--                user-level keys (acting on behalf of a user), application-level
--                keys (server-to-server), and partner keys (aggregate access).
--                Each key has configurable quotas (daily/monthly request limits),
--                IP whitelisting for additional security, and audit logging of
--                all modifications. The table integrates with the rate limiting
--                system to enforce usage caps and with the billing system for
--                usage-based pricing. Key rotation is automated via expiration
--                policies and can be triggered manually for security incidents.
--                The permission system uses a deny-by-default model with
--                explicit grants, supporting the principle of least privilege.
--                This infrastructure enables the platform to safely expose APIs
--                to partners, developers, and internal services while maintaining
--                security and control.
--
-- Key Performance Indicators (KPIs):
--   1. Active Key Count: Number of active API keys (total and by type)
--   2. Key Rotation Compliance: Percentage of keys rotated within policy window
--   3. Permission Usage: Distribution of granted permissions
--   4. Quota Utilization: Average percentage of daily/monthly quotas used
--   5. Key Expiration Rate: Number of keys expiring per week/month
--   6. Security Incidents: Number of compromised/revoked keys per month
--   7. IP Whitelist Coverage: Percentage of keys with IP restrictions
--   8. Key Age Distribution: Age percentiles of active keys
--
-- Feature Reference: INT-API-03 (API Key Management)
-- Requirements Traceability: R-API-001 through R-API-020
-------------------------------------------------------------------------------
CREATE TABLE public.api_keys (
    -- Primary identifier
    api_key_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Ownership
    owner_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    owner_type VARCHAR(20) NOT NULL CHECK (owner_type IN ('USER', 'APPLICATION', 'PARTNER', 'SERVICE')),
    application_name VARCHAR(255),
    application_id UUID, -- Reference to registered application if applicable

    -- Key identification
    key_prefix VARCHAR(20) NOT NULL, -- First few chars for identification
    key_hash TEXT NOT NULL UNIQUE, -- Argon2id hash of the full key
    key_salt TEXT NOT NULL, -- Salt used for hashing
    key_version INTEGER DEFAULT 1 NOT NULL,

    -- Key metadata
    name VARCHAR(255) NOT NULL,
    description TEXT,
    environment VARCHAR(50) CHECK (environment IN ('PRODUCTION', 'STAGING', 'DEVELOPMENT', 'TESTING')),

    -- Permissions
    permissions public.api_key_permission[] NOT NULL DEFAULT '{}',
    resource_restrictions JSONB, -- Restrict to specific resource IDs

    -- Rate limiting
    rate_limit_overrides JSONB, -- Override global rate limits
    quota_daily INTEGER, -- Max requests per day
    quota_monthly INTEGER, -- Max requests per month
    quota_reset_at TIMESTAMP WITH TIME ZONE,
    current_usage_daily INTEGER DEFAULT 0,
    current_usage_monthly INTEGER DEFAULT 0,

    -- Security
    status public.api_key_status NOT NULL DEFAULT 'PENDING_ACTIVATION',
    status_reason TEXT,
    ip_whitelist INET[],
    allowed_referers TEXT[],
    require_https BOOLEAN DEFAULT true,
    allowed_cors_origins TEXT[],

    -- Expiration and rotation
    issued_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE,
    last_rotated_at TIMESTAMP WITH TIME ZONE,
    rotate_after_days INTEGER DEFAULT 90,
    rotation_notification_sent BOOLEAN DEFAULT false,

    -- Usage tracking
    last_used_at TIMESTAMP WITH TIME ZONE,
    last_used_ip INET,
    total_requests INTEGER DEFAULT 0,
    total_bytes_sent BIGINT DEFAULT 0,
    total_bytes_received BIGINT DEFAULT 0,

    -- Alerting
    alert_email VARCHAR(255),
    alert_threshold_percent INTEGER DEFAULT 80, -- Alert at % of quota
    last_alert_sent_at TIMESTAMP WITH TIME ZONE,

    -- Compliance
    data_classification_allowed VARCHAR(50)[] DEFAULT '{}', -- e.g., {'PUBLIC', 'INTERNAL'}
    requires_mfa BOOLEAN DEFAULT false,
    terms_accepted_at TIMESTAMP WITH TIME ZONE,
    terms_version VARCHAR(20),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Constraints
    CONSTRAINT valid_quota CHECK (
        (quota_daily IS NULL OR quota_daily > 0) AND
        (quota_monthly IS NULL OR quota_monthly > 0)
    ),
    CONSTRAINT valid_expiration CHECK (
        expires_at IS NULL OR expires_at > issued_at
    ),
    CONSTRAINT valid_rotation CHECK (
        rotate_after_days IS NULL OR rotate_after_days >= 1
    )
);

COMMENT ON TABLE public.api_keys IS 'API credentials for programmatic platform access with comprehensive security features';
COMMENT ON COLUMN public.api_keys.api_key_id IS 'Primary key, UUID for security';
COMMENT ON COLUMN public.api_keys.owner_id IS 'User/application/service that owns this key';
COMMENT ON COLUMN public.api_keys.owner_type IS 'Type of owner (USER, APPLICATION, PARTNER, SERVICE)';
