COMMENT ON COLUMN public.api_keys.total_bytes_sent IS 'Total bytes sent in requests';
COMMENT ON COLUMN public.api_keys.total_bytes_received IS 'Total bytes received in responses';
COMMENT ON COLUMN public.api_keys.alert_email IS 'Email for quota/security alerts';
COMMENT ON COLUMN public.api_keys.alert_threshold_percent IS 'Quota percentage to alert at';
COMMENT ON COLUMN public.api_keys.last_alert_sent_at IS 'When last alert was sent';
COMMENT ON COLUMN public.api_keys.data_classification_allowed IS 'Data classifications this key can access';
COMMENT ON COLUMN public.api_keys.requires_mfa IS 'Whether MFA is required to use this key';
COMMENT ON COLUMN public.api_keys.terms_accepted_at IS 'When terms were accepted';
COMMENT ON COLUMN public.api_keys.terms_version IS 'Version of terms accepted';
COMMENT ON COLUMN public.api_keys.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.api_keys.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.api_keys.created_by IS 'User who created the key';
COMMENT ON COLUMN public.api_keys.updated_by IS 'User who last updated the key';

-- Indexes for api_keys
