CREATE INDEX idx_api_keys_key_hash ON public.api_keys(key_hash);
CREATE INDEX idx_api_keys_status ON public.api_keys(status, expires_at);
CREATE INDEX idx_api_keys_usage ON public.api_keys(current_usage_daily, quota_daily) WHERE status = 'ACTIVE';
CREATE INDEX idx_api_keys_expiration ON public.api_keys(expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX idx_api_keys_rotation ON public.api_keys(last_rotated_at, rotate_after_days) WHERE status = 'ACTIVE';

-- Trigger for updated_at
CREATE TRIGGER update_api_keys_timestamp
    BEFORE UPDATE ON public.api_keys
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
