-- RLS Policies
CREATE POLICY api_keys_owner_policy ON public.api_keys
    USING (owner_id = current_user_id() OR
           EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.role_id
                   WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'api_manager')));

-- =============================================================================
-- TABLE 74: api_usage_logs
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 74
-- Table Name: api_usage_logs
-- Description: Comprehensive logging of all API requests for analytics,
--              billing, security monitoring, and capacity planning.
--
-- Business Case: API usage data is essential for multiple business functions:
--                billing (usage-based pricing), security (anomaly detection),
--                capacity planning (traffic patterns), and developer experience
--                (documentation of common patterns). This table captures every
--                API request with sufficient detail to support these use cases
--                while managing the massive volume through partitioning and
--                efficient storage strategies. The design includes: request/
--                response metadata for debugging, performance metrics for SLA
--                monitoring, user/application identification for attribution,
--                and security context for audit. Data is partitioned by date
--                for efficient retention management and query performance.
--                Older partitions can be compressed or moved to cheaper storage.
--                The table feeds real-time dashboards (current traffic), batch
--                analytics (trend analysis), and billing systems (usage
--                aggregation). With proper indexing, it supports both operational
--                queries (recent activity by user) and analytical queries
--                (endpoint popularity over time). The design also includes
--                sampling capabilities for high-volume endpoints to control
--                storage costs while maintaining statistical accuracy.
--
-- Key Performance Indicators (KPIs):
--   1. API Request Volume: Requests per second/minute/hour by endpoint
--   2. Error Rate: Percentage of requests returning 4xx/5xx status codes
--   3. Response Time Percentiles: p50/p95/p99 latency per endpoint
--   4. Active Users/Keys: Distinct API keys/users making requests
--   5. Data Transfer Volume: Bytes sent/received over time
--   6. Peak Traffic Patterns: Busiest hours/days of the week
--   7. Endpoint Popularity: Most and least used API endpoints
--   8. Client Distribution: Breakdown by client library, version, platform
--   9. Throttling Events: Number of rate-limited requests
--   10. Cost Per Request: Infrastructure cost attribution per endpoint
--
-- Feature Reference: INT-API-04 (API Usage Analytics)
-- Requirements Traceability: R-API-021 through R-API-035
-------------------------------------------------------------------------------
CREATE TABLE public.api_usage_logs (
    -- Primary identifier
    log_id BIGSERIAL NOT NULL,
    api_key_id UUID REFERENCES public.api_keys(api_key_id) ON DELETE SET NULL,

    -- Request identification
    request_id UUID NOT NULL, -- Unique request identifier
    correlation_id UUID, -- For distributed tracing
    trace_id VARCHAR(100),

    -- Timing
    request_timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    request_date DATE GENERATED ALWAYS AS (request_timestamp::DATE) STORED,
    response_timestamp TIMESTAMP WITH TIME ZONE,
    duration_ms INTEGER,

    -- Authentication
    user_id UUID REFERENCES public.users(user_id) ON DELETE SET NULL,
    application_id UUID,
    session_id UUID REFERENCES public.sessions(session_id) ON DELETE SET NULL,
    authentication_method VARCHAR(50) CHECK (authentication_method IN ('API_KEY', 'OAUTH', 'SESSION', 'JWT', 'NONE')),

    -- Request details
    http_method VARCHAR(10) NOT NULL,
    endpoint VARCHAR(255) NOT NULL,
    endpoint_group VARCHAR(100), -- Grouped endpoint for analytics
    api_version VARCHAR(20),
    query_string TEXT,
    request_headers JSONB, -- Selected headers only
    request_body_size_bytes INTEGER,
    request_body_sample TEXT, -- Truncated for debugging

    -- Response details
    response_status_code INTEGER NOT NULL,
    response_headers JSONB, -- Selected headers only
    response_body_size_bytes INTEGER,
    response_body_sample TEXT, -- Truncated for debugging
    error_code VARCHAR(100),
    error_message TEXT,

    -- Performance metrics
    db_query_time_ms INTEGER,
    db_query_count INTEGER,
    external_api_time_ms INTEGER,
    external_api_count INTEGER,
    cache_hits INTEGER,
    cache_misses INTEGER,
    cpu_time_ms INTEGER,
    memory_used_mb INTEGER,

    -- Rate limiting
    rate_limit_rule_applied VARCHAR(100),
    rate_limit_remaining INTEGER,
    rate_limit_reset_at TIMESTAMP WITH TIME ZONE,
    was_throttled BOOLEAN DEFAULT false,
    throttle_reason TEXT,

    -- Client information
    client_ip INET,
    user_agent TEXT,
    client_library VARCHAR(100),
    client_version VARCHAR(50),
    device_type VARCHAR(50) CHECK (device_type IN ('DESKTOP', 'MOBILE', 'TABLET', 'BOT', 'OTHER')),
    operating_system VARCHAR(100),
    browser VARCHAR(100),

    -- Geographic information
    country_code CHAR(2),
    region VARCHAR(100),
    city VARCHAR(100),
    latitude DECIMAL(10,8),
    longitude DECIMAL(11,8),
    timezone VARCHAR(50),

    -- Business context
    organization_id UUID,
    project_id UUID,
    cost_center VARCHAR(100),
    billing_category VARCHAR(50),
    is_billable BOOLEAN DEFAULT true,

    -- Security context
    tls_version VARCHAR(20),
    tls_cipher VARCHAR(100),
    is_authenticated BOOLEAN DEFAULT false,
    is_authorized BOOLEAN DEFAULT true,
    auth_failure_reason TEXT,

    -- Sampling
    is_sampled BOOLEAN DEFAULT false,
    sample_rate DECIMAL(3,2), -- 1.0 = 100%, 0.01 = 1%

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Constraints
    CONSTRAINT valid_timing CHECK (
        (response_timestamp IS NULL) OR
        (response_timestamp >= request_timestamp)
    ),
    CONSTRAINT valid_duration CHECK (
        (duration_ms IS NULL) OR
        (duration_ms >= 0)
    ),

    PRIMARY KEY (log_id, request_timestamp)
) PARTITION BY RANGE (request_timestamp);

COMMENT ON TABLE public.api_usage_logs IS 'Comprehensive logging of all API requests for analytics, billing, and security';
COMMENT ON COLUMN public.api_usage_logs.log_id IS 'Sequential ID for the log entry';
COMMENT ON COLUMN public.api_usage_logs.api_key_id IS 'API key used (if any)';
COMMENT ON COLUMN public.api_usage_logs.request_id IS 'Unique request identifier for deduplication';
