COMMENT ON COLUMN public.api_usage_logs.request_body_size_bytes IS 'Size of request body';
COMMENT ON COLUMN public.api_usage_logs.request_body_sample IS 'Truncated request body sample';
COMMENT ON COLUMN public.api_usage_logs.response_status_code IS 'HTTP status code returned';
COMMENT ON COLUMN public.api_usage_logs.response_headers IS 'Selected response headers';
COMMENT ON COLUMN public.api_usage_logs.response_body_size_bytes IS 'Size of response body';
COMMENT ON COLUMN public.api_usage_logs.response_body_sample IS 'Truncated response body sample';
COMMENT ON COLUMN public.api_usage_logs.error_code IS 'Categorized error code';
