-- Create partition function for api_usage_logs
CREATE OR REPLACE FUNCTION public.create_api_usage_partition(partition_date DATE)
RETURNS VOID AS $$
DECLARE
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    partition_name := 'api_usage_logs_' || to_char(partition_date, 'YYYY_MM_DD');
    start_date := to_char(partition_date, 'YYYY-MM-DD');
    end_date := to_char(partition_date + INTERVAL '1 day', 'YYYY-MM-DD');

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS public.%I
        PARTITION OF public.api_usage_logs
        FOR VALUES FROM (%L) TO (%L)
    ', partition_name, start_date, end_date);

    -- Create indexes on daily partition
    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I ON public.%I (api_key_id, endpoint)
    ', 'idx_' || partition_name || '_key_endpoint', partition_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I ON public.%I (user_id)
    ', 'idx_' || partition_name || '_user', partition_name);

    EXECUTE format('
        CREATE INDEX IF NOT EXISTS %I ON public.%I (endpoint, response_status_code)
    ', 'idx_' || partition_name || '_endpoint_status', partition_name);
END;
$$ LANGUAGE plpgsql;

-- Create daily partitions for current week
DO $$
DECLARE
    day_counter DATE;
BEGIN
    FOR day_counter IN
        SELECT generate_series(
            CURRENT_DATE,
            CURRENT_DATE + INTERVAL '7 days',
            '1 day'::interval
        )::DATE
    LOOP
        PERFORM public.create_api_usage_partition(day_counter);
    END LOOP;
END $$;

-- Global indexes
CREATE INDEX idx_api_usage_logs_timestamp ON public.api_usage_logs(request_timestamp DESC);
CREATE INDEX idx_api_usage_logs_key ON public.api_usage_logs(api_key_id, request_timestamp DESC);
CREATE INDEX idx_api_usage_logs_user ON public.api_usage_logs(user_id, request_timestamp DESC);
CREATE INDEX idx_api_usage_logs_endpoint ON public.api_usage_logs(endpoint, request_timestamp DESC);
CREATE INDEX idx_api_usage_logs_status ON public.api_usage_logs(response_status_code, request_timestamp DESC);
CREATE INDEX idx_api_usage_logs_correlation ON public.api_usage_logs(correlation_id) WHERE correlation_id IS NOT NULL;

-- Enable RLS
ALTER TABLE public.api_usage_logs ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY api_usage_logs_owner_policy ON public.api_usage_logs
    USING (user_id = current_user_id() OR
           EXISTS (SELECT 1 FROM public.api_keys ak
                   WHERE ak.api_key_id = api_usage_logs.api_key_id
                   AND ak.owner_id = current_user_id()) OR
           EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.role_id
                   WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'analytics_viewer')));

-- =============================================================================
-- TABLE 75: oauth_connections
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 75
-- Table Name: oauth_connections
-- Description: Links user accounts to external identity providers (Google,
--              LinkedIn, GitHub, etc.) for authentication and profile import.
--
-- Business Case: Modern users expect seamless login experiences with their
--                existing social/professional accounts. This table manages the
--                association between platform user accounts and external
--                identities, enabling features like: one-click login, automatic
--                profile population (photo, name, headline), and gradual
--                engagement (no need to create a new password). The design
--                supports multiple connections per user (e.g., both Google and
--                LinkedIn), enabling account merging and flexible authentication
--                options. Security is paramount: tokens are encrypted at rest,
--                refresh tokens are stored for long-term access, and expiration
--                is tracked to prompt re-authentication. The table also stores
--                the scopes granted by the user, enabling incremental
--                authorization (requesting additional permissions only when
--                needed). For enterprise customers, it supports SAML connections
--                for SSO. The audit trail ensures compliance with identity
--                management regulations. This infrastructure reduces password
--                fatigue, improves security (leveraging provider's MFA), and
--                increases conversion rates during signup. It also enables
--                social features like "find friends from Google" and professional
--                network building by importing connections from LinkedIn.
--
-- Key Performance Indicators (KPIs):
--   1. OAuth Login Percentage: Percentage of logins using OAuth vs. password
--   2. Provider Distribution: Share of logins by provider (Google, LinkedIn, etc.)
--   3. Connection Success Rate: Percentage of OAuth attempts that succeed
--   4. Account Linking Rate: Percentage of users who link multiple providers
--   5. Token Refresh Success: Percentage of successful token refresh operations
--   6. Scope Acceptance: Percentage of users who grant requested scopes
--   7. Unlink Events: Number of users disconnecting providers per month
--   8. Profile Import Coverage: Percentage of profiles enriched via OAuth data
--
-- Feature Reference: INT-OAUTH-02 (External Authentication)
-- Requirements Traceability: R-OAUTH-001 through R-OAUTH-018
-------------------------------------------------------------------------------
CREATE TABLE public.oauth_connections (
    -- Primary identifier
    connection_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- User association
    user_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,

    -- Provider identification
    provider public.oauth_provider NOT NULL,
    provider_user_id VARCHAR(255) NOT NULL,
    provider_email VARCHAR(255),

    -- Connection metadata
    connected_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    last_authenticated_at TIMESTAMP WITH TIME ZONE,

    -- Tokens (encrypted at rest)
    access_token TEXT, -- Encrypted
    refresh_token TEXT, -- Encrypted
    id_token TEXT, -- Encrypted (for OpenID Connect)
    token_type VARCHAR(50) DEFAULT 'Bearer',

    -- Token metadata
    expires_at TIMESTAMP WITH TIME ZONE,
    refresh_expires_at TIMESTAMP WITH TIME ZONE,
    scopes TEXT[] NOT NULL DEFAULT '{}',

    -- Profile data imported from provider
    profile_data JSONB, -- Snapshot of profile at last sync
    profile_synced_at TIMESTAMP WITH TIME ZONE,
    profile_sync_version VARCHAR(20),

    -- Provider-specific identifiers
    provider_username VARCHAR(255),
    provider_display_name VARCHAR(255),
    provider_avatar_url TEXT,
    provider_profile_url TEXT,
    provider_locale VARCHAR(10),

    -- Account linking
    is_primary BOOLEAN DEFAULT false,
    is_email_verified BOOLEAN DEFAULT false,
    email_verified_at TIMESTAMP WITH TIME ZONE,

    -- Permissions
    granted_permissions TEXT[], -- Permissions user has granted
    requested_permissions TEXT[], -- Permissions we requested

    -- Security
    id_token_claims JSONB, -- Validated claims from ID token
    auth_time TIMESTAMP WITH TIME ZONE, -- Time of original auth
    nonce VARCHAR(255), -- Anti-replay nonce
    session_id UUID, -- Associated session

    -- Error tracking
    last_error_code VARCHAR(100),
    last_error_message TEXT,
    error_count INTEGER DEFAULT 0,

    -- Status
    is_active BOOLEAN DEFAULT true,
    deactivated_at TIMESTAMP WITH TIME ZONE,
    deactivation_reason VARCHAR(50) CHECK (deactivation_reason IN ('USER_REVOKED', 'TOKEN_EXPIRED', 'PROVIDER_REVOKED', 'ADMIN_ACTION')),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Constraints
    CONSTRAINT unique_provider_account UNIQUE (provider, provider_user_id),
    CONSTRAINT valid_token_dates CHECK (
        (expires_at IS NULL) OR
        (expires_at > connected_at)
    ),
    CONSTRAINT valid_refresh_dates CHECK (
        (refresh_expires_at IS NULL) OR
        (refresh_expires_at > connected_at)
    )
);

COMMENT ON TABLE public.oauth_connections IS 'Links user accounts to external identity providers for authentication and profile import';
COMMENT ON COLUMN public.oauth_connections.connection_id IS 'Primary key, UUID for security';
COMMENT ON COLUMN public.oauth_connections.user_id IS 'Platform user ID';
COMMENT ON COLUMN public.oauth_connections.provider IS 'OAuth provider (Google, LinkedIn, etc.)';
COMMENT ON COLUMN public.oauth_connections.provider_user_id IS 'User ID from the provider';
COMMENT ON COLUMN public.oauth_connections.provider_email IS 'Email from provider';
COMMENT ON COLUMN public.oauth_connections.connected_at IS 'When connection was established';
COMMENT ON COLUMN public.oauth_connections.last_authenticated_at IS 'Last successful authentication';
COMMENT ON COLUMN public.oauth_connections.access_token IS 'Encrypted access token';
COMMENT ON COLUMN public.oauth_connections.refresh_token IS 'Encrypted refresh token';
COMMENT ON COLUMN public.oauth_connections.id_token IS 'Encrypted OpenID Connect ID token';
COMMENT ON COLUMN public.oauth_connections.token_type IS 'Type of token (Bearer, etc.)';
COMMENT ON COLUMN public.oauth_connections.expires_at IS 'When access token expires';
COMMENT ON COLUMN public.oauth_connections.refresh_expires_at IS 'When refresh token expires';
COMMENT ON COLUMN public.oauth_connections.scopes IS 'OAuth scopes granted';
COMMENT ON COLUMN public.oauth_connections.profile_data IS 'Snapshot of profile from provider';
COMMENT ON COLUMN public.oauth_connections.profile_synced_at IS 'Last profile sync time';
COMMENT ON COLUMN public.oauth_connections.profile_sync_version IS 'Version of sync format';
COMMENT ON COLUMN public.oauth_connections.provider_username IS 'Username from provider';
COMMENT ON COLUMN public.oauth_connections.provider_display_name IS 'Display name from provider';
COMMENT ON COLUMN public.oauth_connections.provider_avatar_url IS 'Avatar URL from provider';
COMMENT ON COLUMN public.oauth_connections.provider_profile_url IS 'Profile URL from provider';
COMMENT ON COLUMN public.oauth_connections.provider_locale IS 'Locale from provider';
COMMENT ON COLUMN public.oauth_connections.is_primary IS 'Whether this is the primary login method';
COMMENT ON COLUMN public.oauth_connections.is_email_verified IS 'Whether provider verified email';
COMMENT ON COLUMN public.oauth_connections.email_verified_at IS 'When email was verified';
COMMENT ON COLUMN public.oauth_connections.granted_permissions IS 'Permissions user granted';
COMMENT ON COLUMN public.oauth_connections.requested_permissions IS 'Permissions we requested';
COMMENT ON COLUMN public.oauth_connections.id_token_claims IS 'Validated claims from ID token';
COMMENT ON COLUMN public.oauth_connections.auth_time IS 'Time of original authentication';
COMMENT ON COLUMN public.oauth_connections.nonce IS 'Anti-replay nonce';
COMMENT ON COLUMN public.oauth_connections.session_id IS 'Associated session ID';
COMMENT ON COLUMN public.oauth_connections.last_error_code IS 'Last error code from provider';
COMMENT ON COLUMN public.oauth_connections.last_error_message IS 'Last error message';
COMMENT ON COLUMN public.oauth_connections.error_count IS 'Count of errors encountered';
COMMENT ON COLUMN public.oauth_connections.is_active IS 'Whether connection is active';
COMMENT ON COLUMN public.oauth_connections.deactivated_at IS 'When connection was deactivated';
COMMENT ON COLUMN public.oauth_connections.deactivation_reason IS 'Why connection was deactivated';
COMMENT ON COLUMN public.oauth_connections.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.oauth_connections.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.oauth_connections.created_by IS 'User who created the connection';
COMMENT ON COLUMN public.oauth_connections.updated_by IS 'User who last updated the connection';

-- Indexes for oauth_connections
CREATE INDEX idx_oauth_connections_user ON public.oauth_connections(user_id, provider, is_active);
CREATE INDEX idx_oauth_connections_provider ON public.oauth_connections(provider, provider_user_id);
CREATE INDEX idx_oauth_connections_email ON public.oauth_connections(provider_email) WHERE provider_email IS NOT NULL;
CREATE INDEX idx_oauth_connections_expiry ON public.oauth_connections(expires_at) WHERE expires_at IS NOT NULL;
CREATE INDEX idx_oauth_connections_primary ON public.oauth_connections(user_id) WHERE is_primary = true;

-- Trigger for updated_at
CREATE TRIGGER update_oauth_connections_timestamp
    BEFORE UPDATE ON public.oauth_connections
    FOR EACH ROW EXECUTE FUNCTION public.update_timestamp();

-- Enable RLS
ALTER TABLE public.oauth_connections ENABLE ROW LEVEL SECURITY;

-- RLS Policies
CREATE POLICY oauth_connections_user_policy ON public.oauth_connections
    USING (user_id = current_user_id());

CREATE POLICY oauth_connections_admin_policy ON public.oauth_connections
    USING (EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.role_id
                   WHERE ur.user_id = current_user_id() AND r.name = 'admin'));

-- =============================================================================
-- TABLE 76: data_import_jobs
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 76
-- Table Name: data_import_jobs
-- Description: Tracks bulk data import operations from external sources,
--              including source configuration, mapping rules, validation
--              results, and processing status.
--
-- Business Case: Customer onboarding often requires migrating existing data
--                into the platform (user lists, job postings, company profiles).
--                This table manages the entire import lifecycle, from source
--                validation to completion, with features for error handling,
--                rollback, and audit. It supports multiple source types (CSV,
--                JSON, Excel, API) and flexible field mapping to accommodate
--                different data formats. The design includes: comprehensive
--                validation at each stage (format, required fields, business
--                rules), progress tracking for long-running jobs, and detailed
--                error reporting for troubleshooting. For large imports, it
--                supports chunking and parallel processing. The table also
--                tracks data quality metrics (invalid records, duplicate count)
--                and provides rollback capability via change logging. This
--                infrastructure enables self-service data import for customers,
--                reduces support load, and ensures data integrity during
--                migrations. The audit trail supports compliance requirements
--                for data provenance.
--
-- Key Performance Indicators (KPIs):
--   1. Import Success Rate: Percentage of imports completing successfully
--   2. Average Import Time: Time to import data by size/type
--   3. Data Quality Score: Percentage of valid records in imports
--   4. Error Rate by Source: Distribution of errors by source type
--   5. Rollback Frequency: Number of imports requiring rollback
--   6. User Retry Rate: Percentage of failed imports retried by users
--   7. Processing Throughput: Records processed per second/minute
--   8. Mapping Complexity: Average number of field mappings per import
--
-- Feature Reference: INT-IMP-02 (Data Import Management)
-- Requirements Traceability: R-IMP-001 through R-IMP-020
-------------------------------------------------------------------------------
CREATE TABLE public.data_import_jobs (
    -- Primary identifier
    import_job_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Ownership
    owner_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    organization_id UUID,

    -- Job identification
    job_name VARCHAR(255) NOT NULL,
    job_description TEXT,
    external_reference VARCHAR(255), -- Reference in external system

    -- Source configuration
    source_type VARCHAR(50) NOT NULL CHECK (source_type IN ('CSV', 'JSON', 'EXCEL', 'API', 'DATABASE', 'SFTP')),
    source_location TEXT NOT NULL, -- URL, file path, etc.
    source_format JSONB, -- Format specification (delimiter, encoding, etc.)
    source_schema_version VARCHAR(20),

    -- Target configuration
    target_entity VARCHAR(100) NOT NULL CHECK (target_entity IN ('USER', 'JOB', 'COMPANY', 'CONTENT', 'CONNECTION', 'APPLICATION')),
    target_mappings JSONB NOT NULL, -- Field mapping rules

    -- Import options
    import_mode VARCHAR(20) NOT NULL CHECK (import_mode IN ('INSERT', 'UPSERT', 'UPDATE', 'REPLACE')),
    deduplication_rules JSONB,
    validation_rules JSONB,
    transformation_rules JSONB,

    -- Chunking
    chunk_size INTEGER DEFAULT 1000,
    total_chunks INTEGER,
    processed_chunks INTEGER DEFAULT 0,

    -- Status tracking
    status public.import_job_status NOT NULL DEFAULT 'PENDING',
    status_reason TEXT,

    -- Timing
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    started_at TIMESTAMP WITH TIME ZONE,
    completed_at TIMESTAMP WITH TIME ZONE,
    estimated_completion_at TIMESTAMP WITH TIME ZONE,
    duration_seconds INTEGER GENERATED ALWAYS AS (
        EXTRACT(EPOCH FROM (completed_at - started_at))
    ) STORED,

    -- Statistics
    total_records INTEGER NOT NULL,
    valid_records INTEGER DEFAULT 0,
    invalid_records INTEGER DEFAULT 0,
    processed_records INTEGER DEFAULT 0,
    failed_records INTEGER DEFAULT 0,
    skipped_records INTEGER DEFAULT 0,
    duplicate_records INTEGER DEFAULT 0,

    -- Data quality
    validation_errors JSONB, -- Summary of validation errors
    quality_score DECIMAL(5,2) GENERATED ALWAYS AS (
        CASE
            WHEN total_records > 0
            THEN (valid_records::DECIMAL / total_records) * 100
            ELSE 0
        END
    ) STORED,

    -- Performance metrics
    processing_rate DECIMAL(10,2), -- Records per second
    peak_memory_mb INTEGER,
    cpu_time_seconds INTEGER,

    -- Error handling
    error_summary TEXT,
    error_details JSONB,
    failed_records_sample JSONB, -- Sample of failed records for debugging

    -- Rollback information
    can_rollback BOOLEAN DEFAULT true,
    rollback_job_id UUID, -- Reference to rollback job
    rollback_completed_at TIMESTAMP WITH TIME ZONE,
    change_log_table VARCHAR(100), -- Table storing changes for rollback

    -- Notifications
    notify_email VARCHAR(255),
    notification_sent_at TIMESTAMP WITH TIME ZONE,

    -- Metadata
    tags TEXT[],
    notes TEXT,

    -- Audit
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Constraints
    CONSTRAINT valid_record_counts CHECK (
        processed_records <= total_records AND
        valid_records + invalid_records <= total_records
    ),
    CONSTRAINT valid_timing CHECK (
        (started_at IS NULL) OR (started_at >= created_at)
    ),
    CONSTRAINT valid_completion CHECK (
        (completed_at IS NULL) OR
        (started_at IS NOT NULL AND completed_at >= started_at)
    )
);

