COMMENT ON COLUMN public.data_export_jobs.created_at IS 'Timestamp of creation';
COMMENT ON COLUMN public.data_export_jobs.updated_at IS 'Timestamp of last update';
COMMENT ON COLUMN public.data_export_jobs.created_by IS 'User who created the job';
