-- =============================================================================
-- TABLE 78: sftp_credentials
-- =============================================================================
-------------------------------------------------------------------------------
-- Serial No: 78
-- Table Name: sftp_credentials
-- Description: Manages SFTP accounts and credentials for secure file transfer
--              with partners and automated data exchange.
--
-- Business Case: Many enterprise integrations still rely on SFTP for batch
--                data exchange due to security requirements and legacy systems.
--                This table provides a complete SFTP user management system
--                integrated with the platform. It supports creating virtual
--                SFTP users (not system users) with chrooted directories,
--                public key authentication, and IP restrictions. Features
--                include: automated key rotation, access logging, quota
--                management (storage and bandwidth), and expiration policies.
--                The table integrates with the data import/export systems for
--                automated file pickup and drop-off. For compliance, it tracks
--                all file transfers with timestamps and hashes. The design
--                supports multiple partners with isolated directories and
--                different permission levels (read-only, write-only, read-write).
--                This infrastructure enables secure, auditable file exchange
--                without managing system-level SFTP users, reducing security
--                risks and operational overhead.
--
-- Key Performance Indicators (KPIs):
--   1. Active SFTP Accounts: Number of active SFTP users
--   2. Transfer Volume: Daily/weekly/monthly data transferred
--   3. Authentication Success Rate: Percentage of successful logins
--   4. Key Rotation Compliance: Percentage of keys rotated within policy
--   5. Quota Utilization: Average storage usage vs. allocated
--   6. File Count: Number of files uploaded/downloaded per period
--   7. Partner Activity: Most active partners by transfer volume
--   8. Security Events: Failed login attempts, unauthorized access attempts
--
-- Feature Reference: INT-SFTP-01 (SFTP Integration)
-- Requirements Traceability: R-SFTP-001 through R-SFTP-015
-------------------------------------------------------------------------------
CREATE TABLE public.sftp_credentials (
    -- Primary identifier
    credential_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,

    -- Ownership
    owner_id UUID NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
    owner_type VARCHAR(20) NOT NULL CHECK (owner_type IN ('USER', 'PARTNER', 'SYSTEM')),
    organization_id UUID,

    -- Account identification
    username VARCHAR(100) NOT NULL UNIQUE,
    display_name VARCHAR(255),
    description TEXT,

    -- Authentication
    public_key TEXT NOT NULL, -- SSH public key
    public_key_fingerprint VARCHAR(64) GENERATED ALWAYS AS (
        encode(sha256(public_key::bytea), 'hex')
    ) STORED,
    public_key_type VARCHAR(50) CHECK (public_key_type IN ('RSA', 'ECDSA', 'ED25519')),

    -- Alternative auth methods
    password_hash TEXT, -- For password auth (encrypted)
    otp_enabled BOOLEAN DEFAULT false,
    otp_secret TEXT, -- For 2FA

    -- Access control
    home_directory VARCHAR(255) NOT NULL, -- Chroot directory
    permissions VARCHAR(20) NOT NULL CHECK (permissions IN ('READ_ONLY', 'WRITE_ONLY', 'READ_WRITE', 'ADMIN')),
    allowed_ips INET[],
    allowed_commands TEXT[], -- Restricted command set

    -- Quotas
    storage_quota_bytes BIGINT, -- Max storage allowed
    bandwidth_quota_bytes BIGINT, -- Max bandwidth per month
    file_count_quota INTEGER, -- Max number of files
    current_storage_bytes BIGINT DEFAULT 0,
    current_bandwidth_bytes BIGINT DEFAULT 0,
    current_file_count INTEGER DEFAULT 0,
    quota_reset_at TIMESTAMP WITH TIME ZONE,

    -- Activity
    last_login_at TIMESTAMP WITH TIME ZONE,
    last_login_ip INET,
    last_activity_at TIMESTAMP WITH TIME ZONE,
    total_logins INTEGER DEFAULT 0,
    total_files_uploaded INTEGER DEFAULT 0,
    total_files_downloaded INTEGER DEFAULT 0,
    total_bytes_transferred BIGINT DEFAULT 0,

    -- Expiration
    valid_from TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    valid_until TIMESTAMP WITH TIME ZONE,
    deactivated_at TIMESTAMP WITH TIME ZONE,
    deactivation_reason VARCHAR(50) CHECK (deactivation_reason IN ('EXPIRED', 'REVOKED', 'COMPROMISED', 'USER_REQUEST')),

    -- Status
    status VARCHAR(20) DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DISABLED', 'EXPIRED', 'LOCKED')),
    status_reason TEXT,

    -- Key rotation
    key_rotated_at TIMESTAMP WITH TIME ZONE,
    key_expires_at TIMESTAMP WITH TIME ZONE,
    rotation_reminder_sent BOOLEAN DEFAULT false,

    -- Notifications
    notify_email VARCHAR(255),
    notify_on_login BOOLEAN DEFAULT false,
    notify_on_quota BOOLEAN DEFAULT true,

    -- Integration
    integration_id UUID, -- Reference to integration
    external_reference VARCHAR(255), -- ID in external system

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by UUID NOT NULL REFERENCES public.users(user_id),
    updated_by UUID NOT NULL REFERENCES public.users(user_id),

    -- Constraints
    CONSTRAINT valid_public_key CHECK (length(public_key) > 100), -- Basic validation
    CONSTRAINT valid_dates CHECK (
        (valid_until IS NULL) OR (valid_until > valid_from)
    ),
    CONSTRAINT valid_key_expiry CHECK (
        (key_expires_at IS NULL) OR (key_expires_at > key_rotated_at)
    )
);

COMMENT ON TABLE public.sftp_credentials IS 'Manages SFTP accounts for secure file transfer with partners';
COMMENT ON COLUMN public.sftp_credentials.credential_id IS 'Primary key, UUID for security';
COMMENT ON COLUMN public.sftp_credentials.owner_id IS 'User/partner who owns this account';
COMMENT ON COLUMN public.sftp_credentials.owner_type IS 'Type of owner';
COMMENT ON COLUMN public.sftp_credentials.organization_id IS 'Organization context';
COMMENT ON COLUMN public.sftp_credentials.username IS 'SFTP username (unique)';
COMMENT ON COLUMN public.sftp_credentials.display_name IS 'Display name for the account';
COMMENT ON COLUMN public.sftp_credentials.description IS 'Description of account purpose';
COMMENT ON COLUMN public.sftp_credentials.public_key IS 'SSH public key for authentication';
COMMENT ON COLUMN public.sftp_credentials.public_key_fingerprint IS 'Generated fingerprint of public key';
COMMENT ON COLUMN public.sftp_credentials.public_key_type IS 'Type of public key algorithm';
COMMENT ON COLUMN public.sftp_credentials.password_hash IS 'Encrypted password for fallback auth';
COMMENT ON COLUMN public.sftp_credentials.otp_enabled IS 'Whether OTP is required';
COMMENT ON COLUMN public.sftp_credentials.otp_secret IS 'Secret for OTP generation';
