-- RLS Policies
CREATE POLICY integration_health_checks_access_policy ON public.integration_health_checks
    USING (EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.roles r ON ur.role_id = r.role_id
                   WHERE ur.user_id = current_user_id() AND r.name IN ('admin', 'integration_manager', 'support_engineer')));

-- =============================================================================
-- MATERIALIZED VIEW: mv_partner_integration_health
-- =============================================================================
-------------------------------------------------------------------------------
-- Materialized View: mv_partner_integration_health
-- Description: Pre-aggregated health metrics per partner for dashboard display
-- Business Case: Partners need real-time visibility into their integration health
-- Refresh Strategy: Every 5 minutes
-------------------------------------------------------------------------------
CREATE MATERIALIZED VIEW public.mv_partner_integration_health AS
SELECT
    pc.partner_id,
    pc.partner_name,
    pc.partner_tier,
    COUNT(DISTINCT ihc.integration_id) as total_integrations,
    COUNT(DISTINCT CASE WHEN ihc.current_status = 'HEALTHY' THEN ihc.integration_id END) as healthy_integrations,
    COUNT(DISTINCT CASE WHEN ihc.current_status = 'DEGRADED' THEN ihc.integration_id END) as degraded_integrations,
    COUNT(DISTINCT CASE WHEN ihc.current_status = 'UNHEALTHY' THEN ihc.integration_id END) as unhealthy_integrations,
    AVG(ihc.rolling_availability) as avg_availability,
    AVG(ihc.rolling_avg_latency_ms) as avg_latency_ms,
    SUM(ihc.slo_violations) as total_slo_violations,
    MAX(ihc.last_failure_at) as last_any_failure,
    NOW() as refreshed_at
FROM public.partner_contracts pc
LEFT JOIN public.integration_health_checks ihc ON pc.partner_id = ihc.integration_id::TEXT -- Simplified join
GROUP BY pc.partner_id, pc.partner_name, pc.partner_tier;

COMMENT ON MATERIALIZED VIEW public.mv_partner_integration_health IS 'Partner-level integration health summary for dashboards';

CREATE UNIQUE INDEX idx_mv_partner_health_partner ON public.mv_partner_integration_health(partner_id);

-- =============================================================================
-- FUNCTIONS AND TRIGGERS
-- =============================================================================

-------------------------------------------------------------------------------
-- Function: check_webhook_subscription_health
-- Description: Updates webhook subscription status based on recent failures
-- Called by: Scheduled job
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.check_webhook_subscription_health()
RETURNS VOID AS $$
DECLARE
    sub RECORD;
BEGIN
    FOR sub IN
        SELECT subscription_id, consecutive_failures, failure_count, status
        FROM public.webhook_subscriptions
        WHERE status IN ('ACTIVE', 'FAILING')
    LOOP
        -- Auto-suspend after 10 consecutive failures
        IF sub.consecutive_failures >= 10 AND sub.status = 'ACTIVE' THEN
            UPDATE public.webhook_subscriptions
            SET status = 'SUSPENDED',
                status_reason = 'Auto-suspended after ' || sub.consecutive_failures || ' consecutive failures',
                updated_at = CURRENT_TIMESTAMP,
                updated_by = (SELECT user_id FROM public.users WHERE email = 'system@platform.com' LIMIT 1)
            WHERE subscription_id = sub.subscription_id;

        -- Mark as failing after 3 consecutive failures
        ELSIF sub.consecutive_failures >= 3 AND sub.consecutive_failures < 10 AND sub.status = 'ACTIVE' THEN
            UPDATE public.webhook_subscriptions
            SET status = 'FAILING',
                status_reason = 'Experiencing failures (' || sub.consecutive_failures || ' consecutive)',
                updated_at = CURRENT_TIMESTAMP,
                updated_by = (SELECT user_id FROM public.users WHERE email = 'system@platform.com' LIMIT 1)
            WHERE subscription_id = sub.subscription_id;
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-------------------------------------------------------------------------------
-- Function: rotate_api_keys
-- Description: Identifies API keys needing rotation and sends notifications
-- Called by: Daily scheduled job
-------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.rotate_api_keys()
RETURNS TABLE(
    api_key_id UUID,
    owner_email VARCHAR(255),
    days_until_expiry INTEGER
) AS $$
BEGIN
    RETURN QUERY
    UPDATE public.api_keys
    SET rotation_notification_sent = true,
        updated_at = CURRENT_TIMESTAMP,
        updated_by = (SELECT user_id FROM public.users WHERE email = 'system@platform.com' LIMIT 1)
    WHERE status = 'ACTIVE'
        AND rotate_after_days IS NOT NULL
        AND (EXTRACT(DAY FROM (CURRENT_TIMESTAMP - last_rotated_at)) >= rotate_after_days - 7)
        AND rotation_notification_sent = false
    RETURNING
        api_key_id,
        (SELECT email FROM public.users WHERE user_id = api_keys.owner_id) as owner_email,
        (rotate_after_days - EXTRACT(DAY FROM (CURRENT_TIMESTAMP - last_rotated_at)))::INTEGER as days_until_expiry;
END;
$$ LANGUAGE plpgsql;

