-- Covering index for login (includes status for active check)
CREATE INDEX CONCURRENTLY idx_users_email_active ON users(email) INCLUDE (is_active, account_locked)
WHERE is_active = true;

-- Partial index for active users only
CREATE INDEX CONCURRENTLY idx_users_active ON users(user_id) WHERE is_active = true;

-- GIN index for search (already exists but consider partial)
CREATE INDEX CONCURRENTLY idx_user_profiles_search_active ON user_profiles USING gin(search_vector)
WHERE profile_visibility = 'public';


-- Frequent: Network graph queries
SELECT * FROM user_connections WHERE user_id = ? AND connection_status = 'accepted';
SELECT * FROM user_connections WHERE connected_user_id = ? AND connection_status = 'accepted';
SELECT * FROM user_connections WHERE user_id = ? AND connected_user_id = ?;

-- Composite covering index for bidirectional lookups
CREATE INDEX CONCURRENTLY idx_user_connections_bidirectional ON user_connections(user_id, connected_user_id)
INCLUDE (connection_status, connection_date, connection_strength)
WHERE connection_status = 'accepted';

-- Reverse lookup index
CREATE INDEX CONCURRENTLY idx_user_connections_reverse ON user_connections(connected_user_id, user_id)
WHERE connection_status = 'accepted';

-- Partition-local indexes (apply to each partition)
-- For efficient connection counting
CREATE INDEX CONCURRENTLY idx_connections_user_status ON user_connections_y2025(user_id, connection_status);

-- Frequent: Job seekers
SELECT * FROM job_listings
WHERE is_active = true
  AND (location_country = ? OR is_remote = true)
  AND job_type_id IN (?)
  AND salary_min >= ?
ORDER BY posted_at DESC;


-- Composite covering index for common search pattern
CREATE INDEX CONCURRENTLY idx_job_listings_search ON job_listings(is_active, posted_at DESC)
INCLUDE (company_id, title, location_country, location_city, is_remote, salary_min, job_type_id)
WHERE is_active = true;

-- Partial index for remote jobs
CREATE INDEX CONCURRENTLY idx_job_listings_remote ON job_listings(posted_at DESC)
WHERE is_active = true AND is_remote = true;

-- GiST index for location-based search (if using PostGIS)
CREATE INDEX CONCURRENTLY idx_job_listings_location_gist ON job_listings USING gist(location_point)
WHERE is_active = true;

-- BRIN index for time-based range queries (if table is large)
CREATE INDEX CONCURRENTLY idx_job_listings_posted_brin ON job_listings USING brin(posted_at)
WHERE is_active = true;


-- Frequent: Social feed
SELECT * FROM contents
WHERE visibility = 'public'
  AND status = 'published'
  AND created_at > NOW() - INTERVAL '30 days'
ORDER BY created_at DESC;


-- Composite index for feed queries
CREATE INDEX CONCURRENTLY idx_contents_feed ON contents(created_at DESC)
INCLUDE (title, summary, user_id, content_type_id)
WHERE visibility = 'public' AND status = 'published';

-- BRIN index for time-series data
CREATE INDEX CONCURRENTLY idx_contents_created_brin ON contents USING brin(created_at)
WHERE visibility = 'public' AND status = 'published';

-- Frequent: Company pages
SELECT company_id, AVG(overall_rating), COUNT(*)
FROM company_reviews
WHERE approval_status = 'approved'
GROUP BY company_id;

-- Covering index for aggregation
CREATE INDEX CONCURRENTLY idx_company_reviews_agg ON company_reviews(company_id, overall_rating)
INCLUDE (approval_status)
WHERE approval_status = 'approved';

-- Partial index on each partition
CREATE INDEX CONCURRENTLY idx_company_reviews_approved ON company_reviews_y2025(company_id)
WHERE approval_status = 'approved';

-- Optimized: Use covering indexes and reduce joins
SELECT cr.review_id, cr.overall_rating, cr.pros, cr.cons,
       cr.created_at, u.email
FROM company_reviews cr
INNER JOIN users u ON cr.user_id = u.user_id
WHERE cr.company_id = '123'
  AND cr.approval_status = 'approved'
ORDER BY cr.created_at DESC
LIMIT 20;

-- 1. Extract location into separate table
CREATE TABLE public.locations (
    location_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    country VARCHAR(100),
    state VARCHAR(100),
    city VARCHAR(100),
    postal_code VARCHAR(20),
    coordinates GEOGRAPHY(POINT),
    timezone VARCHAR(50),
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Add location_id to relevant tables
ALTER TABLE user_profiles ADD COLUMN location_id UUID REFERENCES locations(location_id);
ALTER TABLE companies ADD COLUMN headquarters_location_id UUID REFERENCES locations(location_id);
ALTER TABLE job_listings ADD COLUMN location_id UUID REFERENCES locations(location_id);

-- 2. Extract contact methods
CREATE TABLE public.user_contacts (
    contact_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    contact_type VARCHAR(20) NOT NULL, -- 'email', 'phone', 'social'
    contact_value TEXT NOT NULL,
    is_verified BOOLEAN DEFAULT false,
    is_primary BOOLEAN DEFAULT false,
    verified_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Partition by day instead of month
